INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Yaşamak', 'sensiz-yasamak-bahri-sohtorik-mx0aj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Senden sonra, sensiz yaşamakta zor

Ölmek, en iyisi düşlerin

İşe sarılsam tümüyle, versem çabamı

İnsanlar sözbirliği etmişçesine

Seni sorarlar, 

Avare olsam, gezsem dolaşsam

Heryer seni haykırır bana, 

Tabiata dalsam, soyutlansam dünyadan

Dağ, deniz ve orman

Sen kokarsın buram buram, 

Çılgınca yaşasam, gecenin adamı olsam

Bütün çalgılar seni çalar, 

Kadınlar...

Hepsi bana seni hatırlatırlar, 

Ölmek en iyisi senden sonra

Sensiz yaşamak öylesine zor.', 'Senden sonra, sensiz yaşamakta zor Ölmek, en iyisi düşlerin İşe sarılsam tümüyle, versem çabamı İnsanlar sözbirliği etmişçesine Seni sorarla...', ARRAY['Türk Edebiyatı','Şiir','Bahri Sohtorik']::text[], 8.5, '{"poet":"Bahri Sohtorik","poet_slug":"bahri-sohtorik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sensiz-yasamak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umarım', 'umarim-karhan-germiyanoglu-0t3b9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Umarım! 

Umarum diyorum

Umar mıyım bilmiyorum.

Ben şimdi gidiyorum, 

Dönermiyim bilmiyorum.', 'Umarım!  Umarum diyorum Umar mıyım bilmiyorum. Ben şimdi gidiyorum,  Dönermiyim bilmiyorum....', ARRAY['Türk Edebiyatı','Şiir','Karhan Germiyanoğlu']::text[], 8.5, '{"poet":"Karhan Germiyanoğlu","poet_slug":"karhan-germiyanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/umarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aslında', 'aslinda-vedat-karatas-68kvl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zamandır akıp giden habersiz.

Ve gönüllerde, 

Geçmişe dönüş özlemi

Unutulmayan bir hatıra 

Bir hayatın, 

Bir sevdanın 

Başlangıcıdır aslında...', 'Zamandır akıp giden habersiz. Ve gönüllerde,  Geçmişe dönüş özlemi Unutulmayan bir hatıra  Bir hayatın,  Bir sevdanın  Başlangıcıdır aslında...', ARRAY['Türk Edebiyatı','Şiir','Vedat Karatas']::text[], 8.5, '{"poet":"Vedat Karatas","poet_slug":"vedat-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/aslinda-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-onder-durmus-0k2kz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kelimeler anlamını mı yitiriyor yavaşça, 

Yoksa ben yaşamanın anlamını mı yitiriyorum, 

Anlamış değilim hala, 

Yine de nedendir bilinmez, 

Usul usul dökülüyorlar, 

Önce içime, sonrada önüme, 

Daha çok derinleşiyor anlamlar, 

Ama yazamıyorum artık, 

Sadece hissediyorum, içimdeki seni, 

Gözlerin seriliyor önüme, 

Baktıkça daha çok ölüyorum, 

Kırıldıkça kırılıyor yüreğim, 

İki damla yaş süzülüyor gözlerimden, 

Sonra birden kendime geliyorum, 

Nefretle doluyor içim, 

Herşeyi kırmak parçalamak istiyorum, 

Tane tane dökülüyor sözcükler dudaklarımdan, 

Seni Seviyorum, 

Kelimeler mi anlamını yitiriyor, 

Yoksa ben mi kendimi, 

Daralıyor içim, 

Bir sıkıntı bir kasvet düşüyor derinliklerime, 

Haykırmak, bağırmak istiyorum, 

Çabuk kırılıyorum olaylara, 

Ve çabuk darılıyorum insanlara, 

Rüzgar şiddetini azaltıyor iyice, 

Ama gel bir de bana sor, 

Güneş son haddinde her şeyi kavururken, 

Sen yavaş yavaş ısınmaya başlıyorsun, 

Ben hala kışı yaşıyorum, 

Ben üşüyorum, sen yanıyorsun, 

Konuşurken titriyor dudaklarım, 

Korkuyorum da senden iyice, 

Ne kadar üzsende beni, 

Tane tane dökülüyor sözcükler dudaklarımdan, 

Seni Seviyoum.

06.11.2002', 'Kelimeler anlamını mı yitiriyor yavaşça,  Yoksa ben yaşamanın anlamını mı yitiriyorum,  Anlamış değilim hala,  Yine de nedendir bilinmez,  U...', ARRAY['Türk Edebiyatı','Şiir','Önder Durmuş']::text[], 8.5, '{"poet":"Önder Durmuş","poet_slug":"onder-durmus","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/seni-seviyorum-94-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Tanımadan Önce', 'seni-tanimadan-once-hasan-mahir-57swq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'seni tanımadan önce

sevgi nedir bilmezdim

seni tanımadan önce

sevmemiştim ki hiç böylesi



seni tanımadan önce 

anlamsız gelirdi her şey

boşluğa bakar gibi

bakardım denizin yüzüne

yokuş gelirdi bana aşk

sevmek yaban



seni tanımadan önce

içtiğim suların tadı yoktu

geçtiğim yoldaki söğüt dallarının

güzellini bile fark edemezdim', 'seni tanımadan önce sevgi nedir bilmezdim seni tanımadan önce sevmemiştim ki hiç böylesi seni tanımadan önce  anlamsız gelirdi her şey boşlu...', ARRAY['Türk Edebiyatı','Şiir','Hasan Mahir']::text[], 8.5, '{"poet":"Hasan Mahir","poet_slug":"hasan-mahir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/seni-tanimadan-once-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Necip Fazıla Mektup', 'necip-fazila-mektup-hasan-mahir-ln0pn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aydın iki hece üstadım lafta

Sağcı ile solcu aynı safta

Bir de Müslüman gerici, boynunda yafta

Halimizi düşünüp yanma üstadım

Kavuşmak mı? kim bilir daha uyanmadım

Hayat... bir uzun yol.. mayın döşeli

Dost dediklerimiz dört köşeli

Bir elleri Kur''an bir elleri rakı şişeli

Gel ve git on perdeli bin yıllık devlet

Buna ne vatan dayanır ne millet

Bir ülke ki, düşünce boru içinde

Akıl, almazların zoru içinde

Üst üste sorular soru içinde

Düşünme, konuşma unut

Ne altın olduk ne yakut

Bir idamlık Apo vardı, asılmadı

Söz verdiler erkekçe tutulmadı

Binlerce şehit verdik unutulmadı

Onlardan kalan boynu bükük ve sefil

Ana, çocuk ve sevdiği karanfil

Bakan bey bizi dinler bu gün maruzat

Çatık kaş hükümet dedikleri zat

Beni insan tutmuş, Allah eder azat

Anlamaz yazısız pulsuz dilekçem

Anlamaz! ruhumu aldı bilekçem

Saat beş dedi mi, bir garip ezan

Saf tutar camide üç beş yaşlı müslüman

Ne iman kaldı ne Kur''an

İnsanlar toplumda birer kemiyet

Urbalar mini podyumlar et

Konuşma ki suç, düşünme ki yasak

İnsan ki makama mevkiye tutsak

Hani bir senin bıraktıklarını hatırlasak...

Affet bizi üstadım', 'Aydın iki hece üstadım lafta Sağcı ile solcu aynı safta Bir de Müslüman gerici, boynunda yafta Halimizi düşünüp yanma üstadım Kavuşmak mı? k...', ARRAY['Türk Edebiyatı','Şiir','Hasan Mahir']::text[], 8.5, '{"poet":"Hasan Mahir","poet_slug":"hasan-mahir","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/necip-fazila-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kilim', 'kilim-hasan-mahir-6c621', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir kilim doku bana ley

İlmek ilmek yüreğin olsun

Motif motif gözlerin

Desen desen tutkuların

Buram buram İstanbul

Elvan elvan Anadolu koksun

Bir kilim doku bana ley

Hatıralar içinde saklansın

Tutuşsun korkular

İhanet yansın

Vurgunu koy derinliğine

Hasreti sıkıştır köşeye

Vuslatı imzasını at

Bakanlar beni sansın

Bir kilim doku bana ley

Güneş tutulsun renklerinde

Deniz çırpınsın eteklerinde

Alın yazımı taşıyan bir trende

Hayallerimi bir kompartımana koy

Süzülsün raylardan

Bir güvercin selam götürsün

Yas tutan köylere

İçi pas tutmuş saraylardan

Bir kilim doku bana ley

Anamın elleri göğe değsin

Bacım su beklesin çeşmede

Sitilleri umutla dolsun

Yalın ayak bir köy çocuğu

Mektup yazsın köhne okulundan

Ve yorgun bir akşam

Martıyı vursun kanadından

Kısaltmalı itler için

Üç beş yamyam

Bir kilim doku bana ley

Aşkı hürriyet abidesi

Özgürlüğü sevgi

Yağlı bir urgan yada kızıl bir kurşun

Sebep olsun bana

Ay yıldızlığı bayrağım

TÜRKİYEM ebed olsun sana', 'Bir kilim doku bana ley İlmek ilmek yüreğin olsun Motif motif gözlerin Desen desen tutkuların Buram buram İstanbul Elvan elvan Anadolu koksu...', ARRAY['Türk Edebiyatı','Şiir','Hasan Mahir']::text[], 8.5, '{"poet":"Hasan Mahir","poet_slug":"hasan-mahir","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/kilim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehir Meydanları', 'sehir-meydanlari-hasan-mahir-iqx96', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şehir meydanlarına

Kurtuluş günlerinde dikilmiş

Tunç heykeller gibi

Her gün beklemekteyim



Şehir parklarına

Yağan ilk karda yapılmış

Kömür gözlü kardan adamlar gibi

Her gün erimekteyim', 'Şehir meydanlarına Kurtuluş günlerinde dikilmiş Tunç heykeller gibi Her gün beklemekteyim Şehir parklarına Yağan ilk karda yapılmış Kömür gö...', ARRAY['Türk Edebiyatı','Şiir','Hasan Mahir']::text[], 8.5, '{"poet":"Hasan Mahir","poet_slug":"hasan-mahir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sehir-meydanlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'en-sevgiliye', 'en-sevgiliye-hasan-mahir-peqqb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıllar hüzün yüklü, sessiz.

Bahçeler gül görmedi sensiz

Bülbüller suskun asırlardır

Gül rengi diye ateşlere sarıldık çaresiz

Çöle düştük bir gül diye 

Bir gül diye

Kavuşuruz belki bir gün diye

Bir gün diye

Sana gelmeyen yollar bulduk

Sensiz sevdalara tutulduk

Kuruduk ulu bir çınar gibi

Bulanık sularda boğulduk

Çöle düştük bir gül diye 

Bir gül diye

Kavuşuruz belki bir gün diye

Bir gün diye

Hasretin yakmakta beni', 'Yıllar hüzün yüklü, sessiz. Bahçeler gül görmedi sensiz Bülbüller suskun asırlardır Gül rengi diye ateşlere sarıldık çaresiz Çöle düştük bir...', ARRAY['Türk Edebiyatı','Şiir','Hasan Mahir']::text[], 8.5, '{"poet":"Hasan Mahir","poet_slug":"hasan-mahir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/en-sevgiliye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Affetmeyeceğim', 'affetmeyecegim-sevinc-keles-rq242', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Öyle uzak ki artık elin 

bütün özlemlerime rağmen 

gözlerim senden ayrı yaşıyor gör bak

bir kördüğüm sanki içim

yapmazdı sevdiğim buna bana

 şimdi ağlıyorum bekliyorum ve yine ağlıyorum.

soruyorum iyi mi yaptın

beni yalnız bıraktın, güzel hayellerimiz vardı onları yıktın

artık sana nasıl güvenebilirim ki

içimdeki sızıyı nasıl dindirebilirim 

sensiz olamam derken geleceğim

güne başlarken içimdeki nefretim affetmeyeceğim seni 

söz tüm içtenliğimle

affetmeyeceğim seni seni bunca sevmeme rağmen

affetmeyeceğim

geri dönüş yok unuttum seni sevdiceğim...', 'Öyle uzak ki artık elin  bütün özlemlerime rağmen  gözlerim senden ayrı yaşıyor gör bak bir kördüğüm sanki içim yapmazdı sevdiğim buna bana ...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Keleş']::text[], 8.5, '{"poet":"Sevinç Keleş","poet_slug":"sevinc-keles","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/affetmeyecegim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmaz Olur', 'olmaz-olur-i-hsan-uncuoglu-542lx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'OLMAZ OLUR 

ÇARPILMAK

OLMAZ DEME

BAL GİBİ 

OLUR ÖYLE 

Çarpık akıl doğru ölçüyle uyar hesap yapamaz! 

Benden öte gayrısın yok diyenle dost olunmaz 

Heryerde atılan adımı eğrisi doğrusu ederi ayarını 

Bilgisinden ölç karar ver Ölçü şaşmaz, aldatmaz. 

***

Dilin uzandığı bir yerde 

Biri çıkar karşına

yanlışıyla 

Olmaz olur ya 

Kişi İmam olursa

Belki

girilir günaha

Fen`ne arkadaş ol

Fend`e dikkat! 

Fal`a kanma, 

***

Aklı olan İnsan anlar 

tanır arar öğrenir

doğru bilgi bulur uygular

Kendi doğruların varsa 

önder olur tek telin

faydan olur Dünyana! ,', 'OLMAZ OLUR  ÇARPILMAK OLMAZ DEME BAL GİBİ  OLUR ÖYLE  Çarpık akıl doğru ölçüyle uyar hesap yapamaz!  Benden öte gayrısın yok diyenle dost ol...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/olmaz-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklın Yolu Bir', 'aklin-yolu-bir-i-hsan-uncuoglu-3hw5t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'BİRDİRBİR

Herbirimizde Akıl Beceri Yolu Yedi 

Sağduyu, Şuur, Mantık Ola Pervanesi 

Bir Laf söylenir ortada Leylek lak lak

Aklın yolu bir denmiş denir ya bak bak! 

Hak kime kimlere vermis böyle ilgi`yi 

Sorulsa akıl sahib`ine günde bu Han`a 

Gelenle gideni kaç bindi kaç indi bilirmi! ? , 

* **

Nasıl ne anlaşılır tek gözle uzaklardan 

O neler nedir anılır ne kalmışsa atadan 

Ey fani nice açık birdirbirler diyarından 

Kendin acep gören körmü neyin sahibisin 

Bu hazır çatılmış mülke bakan kim ne dersin, 

* **

Hak akıl üretim yoksa her yoldan yalan

Toprağa suya faydan yeniliğin ne yandan 

Aklın yolu bir doğru eski unutulmuş sanki 

Benzer baş beden el ayak kol bacak hepsi 

Karışık aralardan neysin tanırmıydın kendini', 'BİRDİRBİR Herbirimizde Akıl Beceri Yolu Yedi  Sağduyu, Şuur, Mantık Ola Pervanesi  Bir Laf söylenir ortada Leylek lak lak Aklın yolu bir den...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aklin-yolu-bir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zilli Dili Zehirli', 'zilli-dili-zehirli-i-hsan-uncuoglu-2mulv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ZİLLİ DİLİ ZEHİRLİ 

BU ZİLLİ DİLİ ZEHİRLİ 

NİYETİYSE ÇOK GİZLİ

Millet vatan güven içinde deki ayni ev ayni han

Düzenlen aklın canım yiğidim daha bu yol başından, 

**

Taşına toprağına doğrusun duyarlı bakıyorsan heran

Yolundaki yapraklar filizlenir işte sana bir yeşil Orman, 

**

Aah bir olsa! Evin Köy`ünde nerde o fırsat Eğitimden 

Diyarın Yeşil Yolun Bağın Gülistanlık olsun istersen

Çook konuda candan destek dayanışma gerek Bilgelerden, 

**

Dam`ına göz dikenlerin gör yolu hep birdir değişmez uyuma

Zinde Güçlerin birliğin için aldanma pınar berrak ayna olsa, 

**

Su çatlak delik dinlemez evvel tedbir al sonra geç yola

İçten nankör dıştan namerd yaban göstermez kendin arada, 

**

Ova gibi açıktan düz bir yol Eve gider görünür belirli

Dağ ardında buyol olur bin taşlı tuzak geçişli belli mi? 

**

Tane tane ayrı yollar yoz çatallanır hep bir tehlike

Sahip Vatanında aymazlar kalmasın gulyabani besleme, 

**

Önce sağla güveni eğitim yönetim Kutlu Kutsal neyin var

Başı önü ardı bu karanlık niyetliler hep sana karşı olurlar! 

**

Heryoldan her kılıkta perde perde dost görünür pek tatlı

Aslızehir iğnedilli ufak ufak yabanından çok kurnaz hesaplı, 

**

Yarmaya başlar! aah! Baş gitti! gide gide kimi kuşağ kimi Beli

Kuşku yok değerli ne bulursa herşeye uzanır çözer yoz yaban eli! , 

**

Kulağına küpe ola uyan bre iki gözüm Fatihim Yavuzum uyan 

Dünyan nereye gider gör örnekleri tuzak yeme artık kalk uykudan.', 'ZİLLİ DİLİ ZEHİRLİ  BU ZİLLİ DİLİ ZEHİRLİ  NİYETİYSE ÇOK GİZLİ Millet vatan güven içinde deki ayni ev ayni han Düzenlen aklın canım yiğidim ...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/zilli-dili-zehirli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Parayla', 'parayla-i-hsan-uncuoglu-pm7gd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'YOK ÖYLE BİR PARA 

GÖSTERSENE DÜNYADA

Can görevi hepimizin payıdır

hak verilmez alınır kazanılır 

Kutlu Asker Milletin Ocağından

İşte O zaman deki benimdir bu Vatan! 

***

Sana Aş Ekmek Ev Özgürlük veren

Ata`lardan kalan bu Aziztoprak

Kayarsa, elin avuç ayakların altından

Her yönden, yol gösterenin çook 

Bir de yıkılmış, el açarak ağlasanda 

Açıkça saklanıp gülenler olur ardında, 

***

Ağla oğlum ağlaa, hep ağlarsın, 

Anan ağla, baban ağla, sen ağla, 

Kimse aldırmaz bakmaz göz yaşına

Ne demek 

Böyle bir misal Dünyada! , 

***

Çarpık gözle bakanların 

hiç yeri Olmasın 

Aziz toprağında sakın! 

önce Sağduyunla düşün 

Güvenini

Mantığın sağlasın 

hemen bir de çelik davranışın, 

***

Aslanım bak 

ne yapsak dünyada 

kim verir 

Böyle yeşil bir Yurt, 

bir Vatan parayla 

Parayla bir vatan, haa

hangi parayla! ? 

öyle bir Para yok ki Dünyada! .

Be Kızanım varmı can Can''dan başka, 

***

Nasıl olsa herşey düşler bir yaban/ Düşman sonunda

Yabanla kim olur bir Vatan''da ney için acaba, 

***

Ortada hiçmi hiç Hak yokken nasıl olur kiminle

Amma diye diye hep hak istenir kaç renk yüzle.

***

Aymaza bilmeze üstelik yalancıya olmaz

Rüyada bile yok Haktan hakyolu şöyle böyle

Gözün iyi göre layıkmısın yaşadığın Ülke''ye, 

***

Bakarak Sağ`a Sol`a, ekmeden üretmeden, 

Kıra döke olmaaz! bizde zaman zehir olmasın

Vakit nakit''tende kıymetli Can''lar boşuna harcanmasın! .', 'YOK ÖYLE BİR PARA  GÖSTERSENE DÜNYADA Can görevi hepimizin payıdır hak verilmez alınır kazanılır  Kutlu Asker Milletin Ocağından İşte O zama...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/parayla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarif!', 'tarif-abdulkadir-karaman-67q44', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gökyüzüne ahenk benim

Yeryüzüne mihenk benim

Aykırıya tek denk benim

Müjdelerin kesretiyim.

Aşk her âzamda hürüklü

Duygularım var körüklü

Tohumum...sevgiyle yüklü

Ben toprağın hasretiyim! ..

Aşkla itirazsız yanan

Her tür mihnete dayanan

Gurbeti sılası sanan

Sılasızlar gurbetiyim.

Malım, mülküm var diyordum

Her nefesim kâr diyordum

Her gülene yâr diyordum

Güvenmenin mihnetiyim.

Yaralıya ilaç kimse? 

Menzillere kulaç kimse? 

Teselliye muhtaç kimse? 

Ağlayanın servetiyim.

Değer bilirdim kendimi

Yokmuş, aradım dengimi

Yaptım nefsimle cengimi

Yenilginin zahmetiyim.

Şüphe kıraç, iman taçmış

Doğru tahkike muhtaçmış

Bilen şüpheliden kaçmış

Şüphelerin töhmetiyim.

Aramakla bulunmayan

Söze, göze alınmayan

Adı, sanı bilinmeyen

Yiğitlerin şöhretiyim.

Hakim, mahkum vicdanımdır

Varlık, yokluk hep gamımdır

Acı, tatlı ikramımdır

Dünyaların lezzetiyim! ..

Güçlülerin çekindiği

Zayıfların yekindiği

Haksızların sakındığı

Adaletin izzetiyim.

Aşıkların çilesiyim

Duyguların sılasıyım

Özlemlerin cilasıyım

Şansızların kısmetiyim.

Hasretiyim, hasretiyim

Ben toprağın hasretiyim

Sılasızlar sılasıyım

Gurbetsizler gurbetiyim.

02 – 12 – 2001', 'Gökyüzüne ahenk benim Yeryüzüne mihenk benim Aykırıya tek denk benim Müjdelerin kesretiyim. Aşk her âzamda hürüklü Duygularım var körüklü To...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/tarif-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapalı Kapıların Ardından', 'kapali-kapilarin-ardindan-cahit-i-pekoglu-6kl15', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Elde hüzün

ve silik bir fotoğrafta kaldı yüzün.

Gözlerimi tırmalayan

hep yüreğiminde kaldı artık sensiz bir yanı.

Bir suçlu gibi

bakamadım gözlerine.

Oysa en duru pınarıydı yeryüzünün

tek sevilesi yüreğinde.

Bak gülüm bak meleğim

hüznünle bakamadım yüreğine bir suçlu gibi.

Bakabilseydim eğer

yüreğinin kapısını bulacaktım eskisi gibi.

Yüreğinin anahtarı yüreğimde saklı

her kapını açışım, bir, birinden farklı.

Gerçek açabilseydim eğer kapını

aşkı sunacaktım sana, ruhta saklı..

Sensizlik bunca acıtmayacaktı

kanayan çığlığımı.

Böyle çaresiz eşelemeyecektim

sönmüş bir ateşin korlarını.

Bakabilseydim eğer gözlerine korkmadan

bir sevda gibi, girecektim yüreğini sarsmadan.

Bakamadım gözlerine savrulduk

başka yüreklerin kuytularında kaybolduk..', 'Elde hüzün ve silik bir fotoğrafta kaldı yüzün. Gözlerimi tırmalayan hep yüreğiminde kaldı artık sensiz bir yanı. Bir suçlu gibi bakamadım g...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kapali-kapilarin-ardindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer', 'eger-bekir-ayral-hpsvs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni görmeden evel, 

Güne başlarsam eğer, 

Her şey terse dönüyor, 

Nasıl anlatsam bilemem.

Gün akşamdan başlayıp, 

Sabah ile bitiyor.

Kuşlar denizde yüzüp, 

Balıklar uçuşuyor.

Yaz güneşi dondurup, 

Kar sıcaktan yakıyor.

Baharda çiçekler solup, 

Yaşamı yitiriyor.

Seni görmezsem eğer, 

Seni görmezsem eğer.', 'Seni görmeden evel,  Güne başlarsam eğer,  Her şey terse dönüyor,  Nasıl anlatsam bilemem. Gün akşamdan başlayıp,  Sabah ile bitiyor. Kuşlar...', ARRAY['Türk Edebiyatı','Şiir','Bekir Ayral']::text[], 8.5, '{"poet":"Bekir Ayral","poet_slug":"bekir-ayral","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/eger-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep kirve olacağız', 'hep-kirve-olacagiz-sair-suphi-x15td', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hep kirve olacağız

Biz kirveyiz

Biz, 

Özgür yaşamın esen barış rüzgarıyız

Biz, 

Yaşamın sevda özleminde açılan

gül çiçekleriyiz.

Yani biz kirveyiz

Biz, 

Ülkenin güzellikleri için söylenen

özlem türküsüyüz.

Biz, 

Zulmün adeletsizliğine hep inat

İnsanlığın yaşama sevincine ise

hep umut olmuşuz.

Yani biz kirveyiz.

Dostum yoldaşım ve sırdaşım

hep kirve olsun.

Kirvem nice baskı ve zulme

yol olmuştur.

Bu sevdaki hep kirvemin

adı olagelmiştir.

İşte biz kirveyiz.

Adın hep kirve olsun

Biz umuda hep sevda olacağız.

İşte biz kirveyiz

Yani, 

kirve dosttur, umuttur ve yaşamın

onur bekçisidir.

Ve, 

kirve tüm bunların daha da ötesinde

umudun manifestosudur.

Abartmıyorum da

Kızmayın ha

kirve dar günde yetişen kazma ve kürekteki

nasırlı ve umut ellerdir.

Yani, 

kirvem kotülüklerin ve zulmün kalelerini

yıkmadaki varolmanın adıdır.

Işte biz kirveyiz.

Biz ki, 

Hep güzelliklerden ve dosttan yana

var olmanın başkaldırısı olmuşuz.

Biz ki, 

kışta ve zemheride umut yolunda bedenlerimizi

vermiş, kahramanlıkların adı olmuşuz.

İşte biz kirveyiz.

Kirve onurlu yaşamın hep kale bekçisi olmuştur.

Kirve dostu için tek kol ve ayakla can vermiş

pahası biçilmez bir yoldaştır bir onurdur.

İşte, 

Bundan böyle

Hep kirve olacağız.', 'Hep kirve olacağız Biz kirveyiz Biz,  Özgür yaşamın esen barış rüzgarıyız Biz,  Yaşamın sevda özleminde açılan gül çiçekleriyiz. Yani biz ki...', ARRAY['Türk Edebiyatı','Şiir','Şair Suphi']::text[], 8.5, '{"poet":"Şair Suphi","poet_slug":"sair-suphi","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/hep-kirve-olacagiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaderim..!', 'kaderim-bekir-ayral-r0dcl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Değişse tüm dünya, 

Sırça saray olsa.

İçi güzelle dolsa, 

Değişmez şu kaderim.

Gökten; 

Yağmur, kar değil, 

Yakut, zümrütler yağsa.

Herkes sevdiği ile

Mutluluktan coşsa.

Değişse dört mevsim, 

Dördü de nevbahar olsa, 

Her yerde çiçekler açıp, 

Kuşlar cıvıldaşsa.

Değişse, 

Tüm evren, 

Mekan- ı  Cennet olsa.

DEĞİŞMEZ, 

ŞU KADERİM.', 'Değişse tüm dünya,  Sırça saray olsa. İçi güzelle dolsa,  Değişmez şu kaderim. Gökten;  Yağmur, kar değil,  Yakut, zümrütler yağsa. Herkes s...', ARRAY['Türk Edebiyatı','Şiir','Bekir Ayral']::text[], 8.5, '{"poet":"Bekir Ayral","poet_slug":"bekir-ayral","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kaderim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdam', 'sevdam-vedat-koparan-czbrl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevdam

Sen görsem de görmesem de 

Yüreğimin yıldızı gözlerimin ışığısın

Yarımlarımın çeyrek asırlığımın vurgunluğusun

Sen yürek çağrım sevgi selim 

Susadıkça susadığım içtikçe içtiğim pınarımsın 

Duygu kaçaklığım yağmur sağanağım

Sen sevdam sevdamsın! ! 

    Vedat.K 11-Kasım 2002', 'Sevdam Sen görsem de görmesem de  Yüreğimin yıldızı gözlerimin ışığısın Yarımlarımın çeyrek asırlığımın vurgunluğusun Sen yürek çağrım sevgi...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevdam-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melek', 'melek-serhan-karaduman-9renm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir melek duyardı eskiden

o dinlerdi

sevmeyi anlatırdı bazen

ağlatırdı

yüzünde iyiliğe dokunuş wardı bazen

gerçekçi ama yıldırmazdı

sana seni seviyorum dedirten

ve ben dedirten

o vardı sen vardın

gülümseyişler wardı', 'bir melek duyardı eskiden o dinlerdi sevmeyi anlatırdı bazen ağlatırdı yüzünde iyiliğe dokunuş wardı bazen gerçekçi ama yıldırmazdı sana sen...', ARRAY['Türk Edebiyatı','Şiir','Serhan Karaduman']::text[], 8.5, '{"poet":"Serhan Karaduman","poet_slug":"serhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/melek-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vur Boynumu Vur Artık', 'vur-boynumu-vur-artik-bahri-sohtorik-7zk4y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Git gönlünü eyle, beni geç artık

Seviyorum demek sanki suç artık

Sevgi selin benimkine eş değil

Sebil oldu, her gelene saç artık

Ne uzakmış iki kalbin arası

Bana geldi şimdi veda sırası

Ayrılığın beni tutan sarası

Yıkıp geçti çaresi de yok artık

Mutlu olmak hayal senin yanında

Vefasızlık sanki gezer kanında

Aldatmak bir keskin kılıç kınında

Çek kılıcı vur boynumu vur artık

Yaptıkların kar mı kaldı yanına

Yakıştımı bilmem senin şanına

Neden beni kurban seçtin uğruna

Haydi durma, vakit tamam, git artık.', 'Git gönlünü eyle, beni geç artık Seviyorum demek sanki suç artık Sevgi selin benimkine eş değil Sebil oldu, her gelene saç artık Ne uzakmış ...', ARRAY['Türk Edebiyatı','Şiir','Bahri Sohtorik']::text[], 8.5, '{"poet":"Bahri Sohtorik","poet_slug":"bahri-sohtorik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/vur-boynumu-vur-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dil', 'dil-cevat-akgun-41sqe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'DİL

Dil uzunsa baş dertlidir.

Hem el öper hem ayak.

Çaresizlik feryadı, 

Yükselir bayrak bayrak.

Elde taş görse yılan, 

Çıkarmazm dilini? 

Hep görürüz kavgada, 

Kaynanayla gelini.

Uzanır bulduğuna

İyi kötü aramaz

Çok konuşup az dinler, 

Fakat işe yaramaz.

Bırakırsan ipini, 

Kale yıkar kalp kırar, 

Örümcek ağlarında, 

Barınacak dal arar.', 'DİL Dil uzunsa baş dertlidir. Hem el öper hem ayak. Çaresizlik feryadı,  Yükselir bayrak bayrak. Elde taş görse yılan,  Çıkarmazm dilini?  H...', ARRAY['Türk Edebiyatı','Şiir','Cevat Akgün']::text[], 8.5, '{"poet":"Cevat Akgün","poet_slug":"cevat-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dil-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Yasaklı', 'bana-yasakli-bahri-sohtorik-skv8i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevgi gönüllerden akmasın hele

Önünde ne varsa götürür seller

Kapkara saçları bırak ki yele

Kıskansın yasemen, kıskansın güller

Sanki manolyasın, beyaz ve narin

Teninde bir oya sayılmaz benler

Göğsünde açınca goncalar  yarin

Gönül bülbül olur, sevenler dinler

Ateşte kavrulsun, tutuşsun yansın

Böyle mutluluğa son veren diller

Ahımla kurusun, kasılsın kalsın

Benden başkasını okşayan eller

Sevgi gönüllerden akarsa aksın

Ateşi isterse, kalbimi yaksın

Sen bana yasaklı, bana uzaksın

Ne yapsam şu dilin, adımı beller', 'Sevgi gönüllerden akmasın hele Önünde ne varsa götürür seller Kapkara saçları bırak ki yele Kıskansın yasemen, kıskansın güller Sanki manoly...', ARRAY['Türk Edebiyatı','Şiir','Bahri Sohtorik']::text[], 8.5, '{"poet":"Bahri Sohtorik","poet_slug":"bahri-sohtorik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bana-yasakli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneciğim', 'annecigim-cevat-akgun-i6crr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kişi gurbet ele düştüğü zaman, 

Hasretlik içinde kor, anneciğim.

Sıla hayalinde gözleri duman, 

Annesiz yaşamak zor anneciğim.

Uzat elleini öpeyim ana, 

Uzat ki öpeyim ben kana kana.

Hayırlı günlerde dua et bana, 

Senden başka kimim var, anneciğim? 

Hayat bir makine, zaman eriyor.

Rüzgar gazelleri yere seriyor.

Her kuş yavrusuna kanat geriyor.

Sen de bana kanat, ger anneeciğim.

Toprak yarık yarık, rahmete susuz.

Gönüller uyanık, gözler uykusuz.

Ne yapsam olmuyor, gine huzursuz.

Susadım bir tas su, ver anneciğim.', 'Kişi gurbet ele düştüğü zaman,  Hasretlik içinde kor, anneciğim. Sıla hayalinde gözleri duman,  Annesiz yaşamak zor anneciğim. Uzat elleini ...', ARRAY['Türk Edebiyatı','Şiir','Cevat Akgün']::text[], 8.5, '{"poet":"Cevat Akgün","poet_slug":"cevat-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/annecigim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmuşum', 'unutmusum-cevat-akgun-n0n6f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaptığımdan haberim yok

Ben de beni unutmuşum.

Sevabım az günahım çok, 

Bende beni unutmuşum.

Kokusu yok güller gibi, 

Ötmeyen bülbüller gibi, 

Gafletteki kullar gibi, 

Ben de beni unutmuşum.

Boşluktaki taş misali, 

Hissiz akan yaş misali, 

Hayal, hayal düş misali, 

Bende beni unutmuşum.', 'Yaptığımdan haberim yok Ben de beni unutmuşum. Sevabım az günahım çok,  Bende beni unutmuşum. Kokusu yok güller gibi,  Ötmeyen bülbüller gib...', ARRAY['Türk Edebiyatı','Şiir','Cevat Akgün']::text[], 8.5, '{"poet":"Cevat Akgün","poet_slug":"cevat-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/unutmusum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyleyin Dostlar', 'soyleyin-dostlar-sadik-altinkaynak-kc790', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nasihat eder dururdu babam; 

''Oku da oğlum, adam ol adam.''

Okudum ben de oldum Kaymakam

Çalışır dururum ''ha babam, de babam''

Emrimde lojmanım, altımda arabam.

Eh...Fena da değil ilçede havam.

Yalnız bir soruya takılır kafam; 

Nasıl olmalıdır, nedir Kaymakam.

En büyük mülki amirdir Kaymakam

Herkesten iyi olmalı fiyakam.

Ama, malum bordrodaki rakam, 

Zor gelir bir araya iki yakam.

Bence orkestra şefidir Kaymakam.

Ahenk, birlik, düzen ister herşeyde.

Çalmasın herkes ayrı bir makam, 

Tek ses, uyum olsun saz, cümbüş, neyde.

Lakin ne fayda? Yazık, çok yazık...

Sazlar düzensiz, akordlar bozuk.

Her yeni mevzuat atarsa bir kazık, 

Söyleyin dostlar n''etsin Kaymakam.

                                                         1984.', 'Nasihat eder dururdu babam;  ''Oku da oğlum, adam ol adam.'' Okudum ben de oldum Kaymakam Çalışır dururum ''ha babam, de babam'' Emrimde lojmanı...', ARRAY['Türk Edebiyatı','Şiir','Sadık Altınkaynak']::text[], 8.5, '{"poet":"Sadık Altınkaynak","poet_slug":"sadik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/soyleyin-dostlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar Önce', 'yillar-once-ozcan-nevres-dyboi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elim eline değmemiş olsa da

Fukaranın umut aşından beter

Umudumun vazgeçilmeziydin sen

Sen bir başkasına yar olduğunda

Nasıl yıkıldığımı anlatamam

Bir dostuma mutsuzluğunu anlatmışsın

Seven bir kez candan sever

Geçmişi sildim unuttum onu derse eğer

Yalandır söyledikleri aldatmacadır 

Ben de sevdim bir zamanlar delicesine

Aşkıma karşılık göremedim

Unuturum onu diye evlendim ama

Unutamadım onu dostum unutamadım

Öyle derin kazınmış ki aşkı

İçimden söküp atamadım

Beni sormuşsun evlendi mi diye

Yok demiş dostumuz aradığını bulamadı

Buğulanmış gözlerin

Akan göz yaşlarını gizlememişsin

O idi ilk aşkım ilk sevdiğim demişsin

Nasıl da vurdu beni derinden o sözler

Utangaçlığım nelere mal olmuş meğer

Beni sevdiğini öğrendim ya 

İşte bu bana yeter

Bundan böyle bana

Sana mutluluk dilemek düşer

		Özcan Nevres

11 Kasım 2002 Pazartesi', 'Elim eline değmemiş olsa da Fukaranın umut aşından beter Umudumun vazgeçilmeziydin sen Sen bir başkasına yar olduğunda Nasıl yıkıldığımı anl...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yillar-once-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlar', 'dostlar-cevat-akgun-dmtsr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dostlar

Yolcuyum artık, 

Eğerleyin

                 Atımı

Verin

Terhis teskeremi, 

Alın

              Techizatımı.', 'Dostlar Yolcuyum artık,  Eğerleyin                  Atımı Verin Terhis teskeremi,  Alın               Techizatımı....', ARRAY['Türk Edebiyatı','Şiir','Cevat Akgün']::text[], 8.5, '{"poet":"Cevat Akgün","poet_slug":"cevat-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dostlar-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarınlar', 'yarinlar-cevat-akgun-eolaj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yarın, 

Yarın diyorum.

Yine umut yarından.

Bir gün daha eksildi, 

Ömür sayfalarından.

Dün de, 

Yarın, diyordum.

Bugün dünün yarını

Yarınlar bozu zaten, 

Ömrümün ayarını...', 'Yarın,  Yarın diyorum. Yine umut yarından. Bir gün daha eksildi,  Ömür sayfalarından. Dün de,  Yarın, diyordum. Bugün dünün yarını Yarınlar ...', ARRAY['Türk Edebiyatı','Şiir','Cevat Akgün']::text[], 8.5, '{"poet":"Cevat Akgün","poet_slug":"cevat-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yarinlar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşündüm', 'seni-dusundum-sair-pasa-kvzdi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni düşündüm 

Bu gece yine iki nolu da 

Havan kılıfının içinde uyumaya çalışırken 

Gelen devriyeyi takip ederken 

Çünkü seni düşünmek

İçimdeki o soğuk havayı ısıtıyor

Hemde uykusuzluğu paylaşıyordu

Seni düşündüğüm gece 

Tuttuğum en kötü nöbetti

Bak ben seni en kötü zamanlarda bile düşünüyorum

Aslında ben seni hep düşünüyorum', 'Seni düşündüm  Bu gece yine iki nolu da  Havan kılıfının içinde uyumaya çalışırken  Gelen devriyeyi takip ederken  Çünkü seni düşünmek İçimd...', ARRAY['Türk Edebiyatı','Şiir','Şair Paşa']::text[], 8.5, '{"poet":"Şair Paşa","poet_slug":"sair-pasa","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/seni-dusundum-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişmanım', 'pismanim-sadik-altinkaynak-q5pgz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''Eşim ve Çocuklarıma''

Yanlış iş tuttum

Mesken eyledim gurbeti

Evimin yolunu unuttum

Çıra gibi yaktı sıla hasreti

Vuslattır ancak ayrılığın şerbeti

Pişmanım yavrum ayrılığa pişmanım

Sevdiğinden ayrı kalmasın düşmanım

Ayrılıktan burnuma geldi canım

Duydum hastalanmış oğlum Seyitcan''ım

Vuslat yaklaştıkça artar heyecanım

Burnumda tütüyor evim evlatlarım

Pişmanım arkadaş ayrılığa pişmanım

Sevdiğinden ayrı kalmasın düşmanım

Ayrılık benim alın yazım

Kaderim bu Feleğe geçmiyor nazım

Bu gün imtihana girecek Aslı kızım

Baba dediğin evlada böyle günde lazım

Pişmanım çocuğum ayrılığa pişmanım

Sevdiğinden ayrı kalmasın düşmanım

Gurbet çekmeyen bilmez sılayı

Gurbete düşen bulmuştur belayı

Göremedim mezun olurken Esra''yı

Pişmanım yavrum ayrılığa pişmanım

Sevdiğinden ayrı kalmasın düşmanım

Böyle olsun istemezdim Değerli Eşim

Ayrılık benim işim ben Müfettişim

Bu işi seçerken ben hata etmişim

Pişmanım arkadaşım ben bu işe pişmanım

Sevdiğinden ayrı kalmasın düşmanım

1994.', '''Eşim ve Çocuklarıma'' Yanlış iş tuttum Mesken eyledim gurbeti Evimin yolunu unuttum Çıra gibi yaktı sıla hasreti Vuslattır ancak ayrılığın ş...', ARRAY['Türk Edebiyatı','Şiir','Sadık Altınkaynak']::text[], 8.5, '{"poet":"Sadık Altınkaynak","poet_slug":"sadik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/pismanim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-ugur-erbil-tc3ab', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Canım, 

Sen bir yaralı kuş gibisin dalıma konan

Sen benim yaşama sebebim olan canımsın! 

Sen gözleri Yıldız gibi parlayan bir tanemsin

Sen benim tek aşkımsın, tek varlığım, canımsın, 

Sen benim mutluluk yolumu açan, can, canan

Sen ay gibi parlayan gözleri kamaştıran

Sen güzelliğinle içimi yakan sarı saçlarınla Güneş gibi ısıtan

Sen insanın içini ürpertensin cansın canansın canımsın, 

Sen sevginin en temiz en iyisine layıksın

Sen ki benim tek varlığım tek hasretimsin

Sen ruhuma iliklerime kadar işleyen bir insansın

Sen sadece benim, sadece benim biricik aşkımsın', 'Canım,  Sen bir yaralı kuş gibisin dalıma konan Sen benim yaşama sebebim olan canımsın!  Sen gözleri Yıldız gibi parlayan bir tanemsin Sen b...', ARRAY['Türk Edebiyatı','Şiir','Uğur Erbil']::text[], 8.5, '{"poet":"Uğur Erbil","poet_slug":"ugur-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sen-191-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bercesteler', 'bercesteler-sair-hay-l-a3021', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gönül derler bir eğlencem deli var

Başında vâdi-i aşkın yeli var

***

Anı hoş tut garîbindir efendim işte biz gittik

Gönül derler ser-i kûyunda bir dîvânemiz kaldı

***						

Adem behişti dâneye sattı o hâle ben

Benzerse böyle benzeye oğlan atasına', 'Gönül derler bir eğlencem deli var Başında vâdi-i aşkın yeli var *** Anı hoş tut garîbindir efendim işte biz gittik Gönül derler ser-i kûyun...', ARRAY['Türk Edebiyatı','Şiir','Şair Hayâlî']::text[], 8.5, '{"poet":"Şair Hayâlî","poet_slug":"sair-hay-l","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bercesteler-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Para', 'para-semsi-belli-wzpzf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '- Para! ... dedim.

Kınından sıyrıldı paslanmış hançer

İpek oldu.

- Para! ... dedim.

Yelesini yoldu bütün aslanlar

Köpek oldu.

- Para! ... dedim.

Şeklini unuttu yuvarlak dünya

Dört köşe oldu.

- Para! ... dedim.

Yaldızını döktü altın sürahi

Bir şişe oldu.

- Para! ... dedim.

Namusuyla beraber soyundu kadın

Fahişe oldu.

- Para! ... dedim.

Suratlar değişti, fikir değişti.

Öfkeler neş''e oldu.

- Para! ... dedim.

“Geber, Kahrol! ” diyen küflü dudaklar

“Yaşa! ... Çok Yaşa! ...” oldu.

*(D-1929-Ö-10.10.1995)   Mekanın cennet olsun büyük usta..(G.Ş.G)', '- Para! ... dedim. Kınından sıyrıldı paslanmış hançer İpek oldu. - Para! ... dedim. Yelesini yoldu bütün aslanlar Köpek oldu. - Para! ... de...', ARRAY['Türk Edebiyatı','Şiir','Şemsi Belli']::text[], 8.5, '{"poet":"Şemsi Belli","poet_slug":"semsi-belli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/para-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümü Yaşamak', 'olumu-yasamak-akdemir-akmut-m4g41', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tam sınırdan kaçarken vurulmak nedir bilir misin? 

Nöbetçiler ha gördü ha görecek;                 

Parmaklarının ucu dikenli tellere değdi değecek...

Ama... Bir adım daha atamazsın;                 

Uzanıp tutamazsın;                              

Göz pınarlarında donup kalır hayâllerin,        

Plânların, kaçışın, kurtuluşun                  

Ve deler sevgi dolu yüreğini                    

Sevgi nedir bilmeyen bir kurşun...              

Bir okyanusta boğulmak nedir bilir misin? 

Batan bir gemiye el sallayamamak,       

Oturup ağlayamamak,                     

Birkaç kulaç ötedeki                    

Bir tahta parçasını tutamamak           

Nedir bilir misin?                      

Sevmek nedir bilir misin?              

Bir şeyler tutuşur yüreğinde kıpır kıpır, 

Bütün benliğini sarar, ısıtır.         

Her gülüşte yeniden doğarsın           

Ve bin kerre ölürsün her iç çekişte.   

Nasıl anlatsam bilmem ki               

Yani sevmek işte...                    

Duymak nedir bilir misin?             

Duymak, ama anlatamamak.              

Çemberini kıramamak kelimelerin.      

Tam dilinin ucuna gelmişken söyleyememek

“Seviyorum” diyememek.                

Yani ölümü yaşamak nedir bilir misin?', 'Tam sınırdan kaçarken vurulmak nedir bilir misin?  Nöbetçiler ha gördü ha görecek;                  Parmaklarının ucu dikenli tellere değdi ...', ARRAY['Türk Edebiyatı','Şiir','Akdemir Akmut']::text[], 8.5, '{"poet":"Akdemir Akmut","poet_slug":"akdemir-akmut","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/olumu-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mübadil Sonrası', 'mubadil-sonrasi-ali-naili-erdem-48n7l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '-Anneme-

               

Ne sen anladın beni ne başkaları

Yağ kandillerinden uzayan geceler vardı.

Diş diş karlardı getirilen Nif dağlarından

İnce eller örterdi uyuyan pancurları

Anılar bir hüzünlü gelin, bir masal yâr''dı.

Meyvalar vardı, tahta sofralarda bölüştüğümüz

Sırma bohçalarda hıçkıran çaresizliğimizdi

Rengi solmuş albümler, mübadil sonrası

Bakıp ağladığımız, anıp gülüştüğümüz

               

Artık ince şiltelerde uyuyan çocukluğum yok

Kimbilir hangi tesbihinde büyükannem

Yeşile küskünlüğüm, denize burukluğum, 

Zeytin dallarında büyüyen matem, 

Doğup büyüdüğümüz yerlerden ses-seda yok.', '-Anneme-                 Ne sen anladın beni ne başkaları Yağ kandillerinden uzayan geceler vardı. Diş diş karlardı getirilen Nif dağlarında...', ARRAY['Türk Edebiyatı','Şiir','Ali Naili Erdem']::text[], 8.5, '{"poet":"Ali Naili Erdem","poet_slug":"ali-naili-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/mubadil-sonrasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utan Dostum Utan', 'utan-dostum-utan-gursel-colak-xn04f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalan söylemekten

Kendini kandırmaktan

Başkalarını aldatmaktan

Bıkmadınmı? Hergün kaçmaktan

Utan Dostum Utan

Yaptıklarından utan.

Kırmamak için narin kalbini

Söylediklerine inandım

Susmayı tercih ettim, konuşmadım

Genede ben suçlandım.

Yüzünü zaten görmedim

Sesini hiç duymadım

Yalan olduğunu bile bile

Her söylediğine inandım.

Ama sen utanmadın

Utan Dostum Utan

Söylediğin yalanlardan utan.', 'Yalan söylemekten Kendini kandırmaktan Başkalarını aldatmaktan Bıkmadınmı? Hergün kaçmaktan Utan Dostum Utan Yaptıklarından utan. Kırmamak i...', ARRAY['Türk Edebiyatı','Şiir','Gürsel Çolak']::text[], 8.5, '{"poet":"Gürsel Çolak","poet_slug":"gursel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/utan-dostum-utan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Vicdanlım', 'kara-vicdanlim-gursel-colak-snwuf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bastığın yerlere dikkat et! 

Farkında değilsin, amma! 

Her bastığın yerde

Senin tarafından parçalanmış

Kalp parçaları var.

Parçalarken acımadın

Bari parçalara acı.

Sorarlar bir gün hesabını

Parçalarlar seninde kalbini

Belki anlarsın o zaman

Parçalanmış kalbin sancısını.

Ama nasıl olur! 

Sen anlayamazsınki

Unuttum! 

Sen zaten kalpsizsin

Kara Vicdanlım....', 'Bastığın yerlere dikkat et!  Farkında değilsin, amma!  Her bastığın yerde Senin tarafından parçalanmış Kalp parçaları var. Parçalarken acıma...', ARRAY['Türk Edebiyatı','Şiir','Gürsel Çolak']::text[], 8.5, '{"poet":"Gürsel Çolak","poet_slug":"gursel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kara-vicdanlim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beddua!', 'beddua-gursel-colak-dzni9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerimden akan yaşlar

Gökten boşalan yağmur gibi

Dökülen her bir damla

Büyüsün içinde bitmez bir dert gibi.

Azmı çektirdin bana

İçim kanıyor, kana kana

Elbet gelir sıra bir gün sana

Umarım ağlarsın sende, kana kana.

İsterim ALLAH'' tan gülmesin yüzün

Yaşadığın her gün olsun keder ve hüzün

Başkalarınıda yakmasın diye

Kör olsun her iki gözün.

Sözlerin ile vurdun beni

Mum gibi yaktın erittin beni

Çektirdiğin ızdıraplardan ötürü

Cehennem ateşi yaksın seni.', 'Gözlerimden akan yaşlar Gökten boşalan yağmur gibi Dökülen her bir damla Büyüsün içinde bitmez bir dert gibi. Azmı çektirdin bana İçim kanıy...', ARRAY['Türk Edebiyatı','Şiir','Gürsel Çolak']::text[], 8.5, '{"poet":"Gürsel Çolak","poet_slug":"gursel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beddua-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Affet', 'affet-necip-fazil-kisakurek-pk1b2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'göz kaptırdığım renkten, kulak verdiğim sesten, 

affet senden habersiz aldığım her nefesten...', 'göz kaptırdığım renkten, kulak verdiğim sesten,  affet senden habersiz aldığım her nefesten......', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/affet-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günaydın', 'gunaydin-vedat-koparan-pxx98', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Günaydın

günaydın gün çiçeğim 

Gün yüzlüm gün gülüşlüm

Günün ilk ışığı ile uyanmak var ya

İlk anda ilk akla düşmek var ya

İşte o sensin bir tanem can yüreğim..

Vedat.K  12-11-2002', 'Günaydın günaydın gün çiçeğim  Gün yüzlüm gün gülüşlüm Günün ilk ışığı ile uyanmak var ya İlk anda ilk akla düşmek var ya İşte o sensin bir ...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gunaydin-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pandora'' ya Dönüş', 'pandora-ya-donus-mine-ozdemirtas-ilkdf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben sana zarar veriyorum kozadaki kelebek.

Okşamak için uzattığım ellerimde nasır var.

Dokunursam Kanarsın...sarılırsam canın yanar.

Öpersem kıyamet kopar..savrulursun,

Yüreğimdeki fırtınalar kadar.

Dinle beni.... çok güzelsin.

Ve anlamıyorum....

Kaynayan kazanımda ne işin var

Dolayıp durma parmaklarıma narinliğini ipeğinin.

Islanıp üşür kabuksuzluğun..haindir içimdeki yağmurlar.

Benimle uçmayı deneme bile.

Sarılıp sarmalandığın dut yaprağında kal.

Gözlerimde kapkara bulutlar.

Pandoranın kutusuna dönüyorum...hoşçakal.', 'Ben sana zarar veriyorum kozadaki kelebek. Okşamak için uzattığım ellerimde nasır var. Dokunursam Kanarsın...sarılırsam canın yanar. Öpersem...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/pandora-ya-donus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Midas''ın Kulakları', 'midas-in-kulaklari-mine-ozdemirtas-3a280', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Issız bir kumsalda… belki de var olmayan bir adada

Geç kalmış  bir yolcu…yalnız başına.

Demsiz çayını yudumlarken...  hüzünlü kamelyada

Gölgeler…yarından sonrasına…  yansımada.

Korku yok olacak…Korkusuzluklar da.

Geç kalmayacak yolcu… o hazır…çıkacak yola.

Şairler sabahı bekleyecek… karanlıklarda...

Gecenin alacası kaybolana dek…satır aralarında.

Söylenmeyenleri de…anlamak adına… anlatılmayanları da..

Saygıyla dalarak…  eskiyememiş ve eskitilememiş anılara.

Bir dost eli değecekse... Temizlemek için…Tozlu raflara.

Beklenebilir… özel olan… emekle… sabırla.

Yaşam kendini yeniler...eninde  ya da sonunda.

Güneş yeniden doğduğunda … o yeni baharda.

Midas…..  can verecekmiş çakıl taşlarına.

Ne fısıldanacaksa…  fısıldansın hele… Midas''ın kulaklarına', 'Issız bir kumsalda… belki de var olmayan bir adada Geç kalmış  bir yolcu…yalnız başına. Demsiz çayını yudumlarken...  hüzünlü kamelyada Gölg...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/midas-in-kulaklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Ormanları', 'yagmur-ormanlari-mine-ozdemirtas-kogzm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana bu mektubu yağmur ormanlarından yazıyorum.

Tepemde... senin asla göremeyeceğin... bir gök yüzü var.

Sonsuz maviliklerde kaybolmayı düşlemek... çok kolay.

Ayağımın altında çürümüş yapraklar denizi hışırdarken, 

Toprağa bile hasretim buralarda.

Durgunluk etimi acıtıp dururken yılan sokması gibi mosmor.

Bütün kemirgenler ve yırtıcılar pusuda.

Zaman... kıyamet öncesi. Bunu biliyor olmak..... çok zor.

İnsanca bir şeyler kımıldıyor içimde uyur/uyanık.

Pembe/beyaz teniyle kucağımda mis kokan, bir bebek özlüyorum.

Sesi... daha kulağıma vurmadan rüzgara karışıyor.

O henüz doğmamış  / Son Amazon

Tülden kanatları var başında ise hare./ sessizce ağlıyor.

Uzanıp dokunmak istiyorum gözyaşlarına/ İzin vermiyor.

Çaresizlik bağları dal/budak her yanımda.

Tutuşturacağım yağmur ormanını....yanacak az sonra.

Sana yazdığım bu mektup ta  böylece bitmiş olacak, 

Ve... pişmanlık bükülecek sancıya.', 'Sana bu mektubu yağmur ormanlarından yazıyorum. Tepemde... senin asla göremeyeceğin... bir gök yüzü var. Sonsuz maviliklerde kaybolmayı düşl...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yagmur-ormanlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Kuş', 'mavi-kus-charles-bukowski-dkxpp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'mavi kuş

bir mavi kuş var yüreğimde

çıkmaya can atan

ama ben ondan güçlüyüm, kal, 

diyorum ona, kimsenin

seni görmesine izin veremem.

bir mavi kuş var yüreğimde

çıkmaya can atan

ama viski döküyorum üstüne

sigara dumanına 

boğuyorum, 

fahişeler, barmenler ve

bakkal çırakları hiçbir zaman

bilmiyorlar onun orada

olduğunu.

bir mavi kuş var yüreğimde

çıkmaya can atan

ama ben ondan güçlüyüm, 

yat lan aşağı, diyorum ona, 

ocağıma incir dikmek mi

niyetin? Avrupa''daki kitap

satışlarımı sabote etmek mi? 

bir mavi kuş var yüreğimde

çıkmaya can atan

ama zekiyim, sadece

geceleri izin veriyorum çıkmasına, 

herkes yattıktan sonra.

orada olduğunu biliyorum, derim

ona, kederlenme

artık.

sonra yerine koyarım yine

ama hafifçe öter

tamamen ölmesine de izin

vermiyorum

ve birlikte uyuyoruz

gizli antlaşmamızla

ve insanı ağlatacak kadar

güzel, ama ben

ağlamam, ya

siz? 

charles bukowski', 'mavi kuş bir mavi kuş var yüreğimde çıkmaya can atan ama ben ondan güçlüyüm, kal,  diyorum ona, kimsenin seni görmesine izin veremem. bir ma...', ARRAY['Türk Edebiyatı','Şiir','Charles Bukowski']::text[], 8.5, '{"poet":"Charles Bukowski","poet_slug":"charles-bukowski","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/mavi-kus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna''ya Bak', 'ayna-ya-bak-mine-ozdemirtas-wlr68', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aynaya bak / Artık çırılçıplaksın

Bütün yaşanmışlıklarımızı geri aldım.

Sen...  bu  utançla canım, 

Bilemem....bir ömür nasıl yaşayacaksın.

Ben yokum / Buna alışacaksın.

Bütün günlerinin Güneşini çaldım.

Sen.... bu gidişle canım

Sanırım..... gecelerin içine kanayacaksın.', 'Aynaya bak / Artık çırılçıplaksın Bütün yaşanmışlıklarımızı geri aldım. Sen...  bu  utançla canım,  Bilemem....bir ömür nasıl yaşayacaksın. ...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ayna-ya-bak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlükler 1', 'dortlukler-1-tuncer-oral-4skze', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Soran olursa biri beni senden, 

Söylersin ''''Eser kalmamış eski halinden, 

Bensiz yaşamaya alışmış artık 

İsmimi duymuyormuş kimse dilinden.

29 Ekim 1999', 'Soran olursa biri beni senden,  Söylersin ''''Eser kalmamış eski halinden,  Bensiz yaşamaya alışmış artık  İsmimi duymuyormuş kimse dilinden. ...', ARRAY['Türk Edebiyatı','Şiir','Tuncer Oral']::text[], 8.5, '{"poet":"Tuncer Oral","poet_slug":"tuncer-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dortlukler-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlükler 2', 'dortlukler-2-tuncer-oral-w7z9l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Salkım söğüt gibi salınan güzel, 

Derdimi bilmeyen dertsiz gibisin. 

Ne o? Dallarına ayazmı vurdu, 

Hayattan tat almaz keyifsiz gibisin.', 'Salkım söğüt gibi salınan güzel,  Derdimi bilmeyen dertsiz gibisin.  Ne o? Dallarına ayazmı vurdu,  Hayattan tat almaz keyifsiz gibisin....', ARRAY['Türk Edebiyatı','Şiir','Tuncer Oral']::text[], 8.5, '{"poet":"Tuncer Oral","poet_slug":"tuncer-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dortlukler-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlükler 3', 'dortlukler-3-tuncer-oral-ys7hf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gel gör beni, bak ne haldeyim, 

Ateşler üstünde yürür gibiyim. 

O meçhul sonumu yalnızlığımı, 

Ufuk çizgisinde görür gibiyim.', 'Bir gel gör beni, bak ne haldeyim,  Ateşler üstünde yürür gibiyim.  O meçhul sonumu yalnızlığımı,  Ufuk çizgisinde görür gibiyim....', ARRAY['Türk Edebiyatı','Şiir','Tuncer Oral']::text[], 8.5, '{"poet":"Tuncer Oral","poet_slug":"tuncer-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dortlukler-3-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem''e', 'annem-e-tuncer-oral-segcp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beni bırakıpta gitme ne olur, 

Sevgine henüz doymadım anne. 

Kalbimde yer eden sıcaklığının, 

İsmini henüz koymadım anne.', 'Beni bırakıpta gitme ne olur,  Sevgine henüz doymadım anne.  Kalbimde yer eden sıcaklığının,  İsmini henüz koymadım anne....', ARRAY['Türk Edebiyatı','Şiir','Tuncer Oral']::text[], 8.5, '{"poet":"Tuncer Oral","poet_slug":"tuncer-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/annem-e-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasaksın', 'yasaksin-sair-i-smihan-s6owe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yanımdasın

Kucakladığım tenin, tenime yabancı şimdi

Aramızda yürümekle aşılmaz mesafeler

Gözlerime yabancı bakan senin gözlerin

Yasaksın..

Sanki yıllarımı almış gibi tanıdık

Sanki tüm yeminleri bozdurmaya sağdık

Ama yapamadık..', 'Yanımdasın Kucakladığım tenin, tenime yabancı şimdi Aramızda yürümekle aşılmaz mesafeler Gözlerime yabancı bakan senin gözlerin Yasaksın.. S...', ARRAY['Türk Edebiyatı','Şiir','Şair İsmihan']::text[], 8.5, '{"poet":"Şair İsmihan","poet_slug":"sair-i-smihan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yasaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlükler 4', 'dortlukler-4-tuncer-oral-0738d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dört mevsim dallar kuru, 

Yeşermiyor ağaçlar. 

Sensizliğin eseri, 

Ağaran yorgun saçlar', 'Dört mevsim dallar kuru,  Yeşermiyor ağaçlar.  Sensizliğin eseri,  Ağaran yorgun saçlar...', ARRAY['Türk Edebiyatı','Şiir','Tuncer Oral']::text[], 8.5, '{"poet":"Tuncer Oral","poet_slug":"tuncer-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dortlukler-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakın Gelme', 'sakin-gelme-yasemin-aydin-s3682', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sakın gelme...

Hiç gelme.

Yakamozlar yok artık.

Sahiller avutmuyor beni.

Geleceğin varsa da sakın gelme.

Ben gene gidiyorum.

Seni hep beklediğim yere.

Gelme...

Ben sana gelene kadar; sen hiç kimseye gitme...', 'Sakın gelme... Hiç gelme. Yakamozlar yok artık. Sahiller avutmuyor beni. Geleceğin varsa da sakın gelme. Ben gene gidiyorum. Seni hep bekled...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Aydın']::text[], 8.5, '{"poet":"Yasemin Aydın","poet_slug":"yasemin-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sakin-gelme-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet', 'gurbet-yoksul-i-brahim-r1xgm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir umut uğruna düştüm yollara

Eşe dosta hasret ettin oy gurbet 

Ömrümü yoldaş kıldın yıllara

Damarda kanımı çektin oy gurbet

Gözlerimi yaşlar ile doldurdun 

Bağımda güllerimi soldurdun

Sen beni yaşar iken öldürdün

Saçlarımı tel tel döktün oy gurbet

Yoksul ibrahimin halı çok acı 

Bitmek bilmez yüreğindeki sancı 

Genç yaşta dediler adıma hancı 

Canımdan ömrümü söktün oy gurbet', 'Bir umut uğruna düştüm yollara Eşe dosta hasret ettin oy gurbet  Ömrümü yoldaş kıldın yıllara Damarda kanımı çektin oy gurbet Gözlerimi yaşl...', ARRAY['Türk Edebiyatı','Şiir','Yoksul İbrahim']::text[], 8.5, '{"poet":"Yoksul İbrahim","poet_slug":"yoksul-i-brahim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gurbet-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Neye Benzer?', 'ayrilik-neye-benzer-tolga-akgun-1om5m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Büyük geniş kaldırımlı caddelerde, 

daracık bir arka mahalle gibi durmaya benzer ayrılık.

Asmalarından akşamüstleri koparılan bir salkım üzüm kadar

katışıksız ve anlamsız kalmaya benzer..

Yorgun eller arasından kayıp düşen bir sigara izmaritini, 

Kimsenin uğramadığı bir limanda, 

Kucak açmış bekleyen bir gemiyi anımsatır ayrılık.

Hiç çiçek tanımamış bir vazoya benzer..

Aynalarda cevap bulmaya çalışan derin çizgili alınlara, 

Toprağın yağmurla buluştuğu anda açtığı kola benzer.

Ayrılık ardında kalana benzer çoğu zaman gidenin.

Eski bir dostun ölümü nasıl benzerse ayrılığa, 

Ölüm kadar benzer ayrılık da sonsuz boşluğa.', 'Büyük geniş kaldırımlı caddelerde,  daracık bir arka mahalle gibi durmaya benzer ayrılık. Asmalarından akşamüstleri koparılan bir salkım üzü...', ARRAY['Türk Edebiyatı','Şiir','Tolga Akgün']::text[], 8.5, '{"poet":"Tolga Akgün","poet_slug":"tolga-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ayrilik-neye-benzer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam', 'aksam-umit-turan-8rh6c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'akşam; 

sana çağırıyor arzularım, 

tutmak istiyorum hayallerin elinden

sessizce yaklaşıyorsun yanıma

gülen yüzün ayın ondördü sanki

dokunmak ölümlerden ölüm...

tenin, toprağın kokusu buram buram

gözlerinin içinde ışıl ışıl hüzün

bir rüzgar eserken titrek yüreğimden, 

avuçlarım üşüyor sessizce

al götür beni sevdanın kül olduğu şehre

zaten yabancısı değilmiyiz bu şehrin ikimiz

cesaretim yok deme, 

gözlerimdeki istek ateşine bak

sevdanın en durusu bu inan

bu şehrin büyüsü yanıyor

sen olmayınca duman duman.', 'akşam;  sana çağırıyor arzularım,  tutmak istiyorum hayallerin elinden sessizce yaklaşıyorsun yanıma gülen yüzün ayın ondördü sanki dokunmak...', ARRAY['Türk Edebiyatı','Şiir','Ümit Turan']::text[], 8.5, '{"poet":"Ümit Turan","poet_slug":"umit-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aksam-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğru Yanlış', 'dogru-yanlis-serhan-karaduman-ehiye', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'we yapılanlardı son ibadetler

hangimiz deliydik

ki akıllısına rastlanabilirdi

doğruyu aynı kefeye koymadan

yanlışla yatıverseydik

belki ozaman üşümezdik

yakamozlara saklanan geceler

bir daha doğurdu seni

ama doğru değildi gözlerin

yanlıştı...

      Çok sevdiğim kankam Özgeye.... ;)', 'we yapılanlardı son ibadetler hangimiz deliydik ki akıllısına rastlanabilirdi doğruyu aynı kefeye koymadan yanlışla yatıverseydik belki ozam...', ARRAY['Türk Edebiyatı','Şiir','Serhan Karaduman']::text[], 8.5, '{"poet":"Serhan Karaduman","poet_slug":"serhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dogru-yanlis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçuk Mavilerde', 'ucuk-mavilerde-vedat-koparan-s9dyu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uçuk  Mavilerde

Düşüncelerimde bir güneş gibi taşıyıp 

Olmadığın anlarda aydınlandığım 

Ben toprak sen yağmur 

Yağacağın zamanlara kendimi vurduğum 

Her damlandan denizlere vardığım 

Okyanuslarda kaldığım 

Unutmadığım nehirlerin akıntılarını 

Her yakamoz bir ışık aydınlatır 

Anlatır derin karanlıkları 

Her yakamoz 

Bir gülüş bir seviştir 

Çocuk gözlerinde

Sen geldiğinde ben uçuk mavilerde..

Vedat.K 26.06.2002', 'Uçuk  Mavilerde Düşüncelerimde bir güneş gibi taşıyıp  Olmadığın anlarda aydınlandığım  Ben toprak sen yağmur  Yağacağın zamanlara kendimi v...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ucuk-mavilerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sımsıcak Sinesi', 'simsicak-sinesi-cuneyd-beri-abuei', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dünyaya fazilet örecek ellerimi

Işığınla ısıtacaksın öğretmenim

Cehaletin öldüren, amansız pençelerini

Hadsiz bilgilerinle eriteceksin öğretmenim.

Bir kuluçka misali sancılı gecelerinde

Değerin kaynağını yakacaksın öğretmenim

Bilgi köprüsünden geçerken geleceğe

Ellerimi sımsıkı tutacaksın öğretmenim

Vurgun yemiş, virane dimağlar görürken

Yıkılmaz bir kale olacaksın öğretmenim

Pınarları kurumuş kızıl çöllere

Serin bir rahmet olup, (yağacaksın)   öğretmenim 

Sımsıcak sinende ısıtırken ümitleri

Çehrelerdeki endişeyi sen sileceksin öğretmenim

Yurdumda yeşerttiğin bin bir türlü çiçekle

Atamın yüzünü sen güldüreceksin öğretmenim', 'Dünyaya fazilet örecek ellerimi Işığınla ısıtacaksın öğretmenim Cehaletin öldüren, amansız pençelerini Hadsiz bilgilerinle eriteceksin öğret...', ARRAY['Türk Edebiyatı','Şiir','Cüneyd Beri']::text[], 8.5, '{"poet":"Cüneyd Beri","poet_slug":"cuneyd-beri","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/simsicak-sinesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Kaybedersem Aman ALLAH''ım Seni', 'seni-kaybedersem-aman-allah-im-seni-salih-ozalasan-olggj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen beni hep gülerken gördün değilmi

Ya ağladığım geceler kadere isyanlarım

Sen beni hep mutlu sanıyorsun değilmi

Ya umutsuz kalbimdeki özlemlerim

Sen beni yıkılıp yerlerde görmedin değilmi

Dost sandıklarımdan yediğim darbeleri

Sen benim kaldırım taşlarında sabahladığımı

Köşe başlarında seni gözlediğimi

Sen yazdığım isyan mektuplarını okumadın değilmi 

Sayfa sayfa alıcısı olmayan yırttığım

Sokak lambası altında biriken izmaritleri

Ya o mürekkebi bitik vefakar kalemleri

Sen gülen gözlerimle sevecenliğimle

Yalnız senin tanıdığın yüzümle tanıyorsun beni

Oysa ben kahreden gecelerde isyankar

Sevgilere hasret arkasından vurulmuş biri

Hayatı boyunca hep yarım kalmış sevgileri

Bağrını döğmekten ellerinde kan izleri

Sensiz geçen gecelerde bana gelen halleri

Bilmiyorsun değilmi iki büklüm halimi

Saçlarıma düşen karbeyazını

Göz altlarımı kaplıyan mor lekeleri

Herşeyden öte gözyaşımdan oluşan dereleri

Ya hıçkırıklarımla yaptığım besteleri

Bilemessin bebeğim bilemessin

Ben hep yaşadım ömrümce sefilleri

Aradım aradım bulamadım

Bulduğumdada hep kaybettim sevgileri

Unutulup gitti kalmadı artık geçmişin izleri

Seni kaybedersem aman Allah''ım seni

Tam mutluluğum kaderim dediğim seni

Bilmelisin işte ozaman ölüm bile kurtaramaz beni

Toprağın altındada dinmez isyanım

Dokuz şiddetinde deprem olur

Yıkar geçerim yerleri gökleri

Cehennem ateşide olsa yakamaz

Sadece ben yakarım yemin sana heryeri

Yaşatırım tüm canlılara Dünya''da mahşeri

Y.Tar 12-11-2002 Saat 19.30', 'Sen beni hep gülerken gördün değilmi Ya ağladığım geceler kadere isyanlarım Sen beni hep mutlu sanıyorsun değilmi Ya umutsuz kalbimdeki özle...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/seni-kaybedersem-aman-allah-im-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani Benim Ganat Çırpan Guşlarım', 'hani-benim-ganat-cirpan-guslarim-ozan-nebi-dadaloglu-220mz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hazır yiyici değildik 

                                                                            Tan yeri gibi ağarıyorduk! ..

Yaman çavdı yıldızlar, karanlığa yaman

Sakınma otlardan, böceklerden, gurtlardan aman

Ve ganat çırptı ak güvercinler, bölük bölük

Kızılçullu dan, Akçadağ’dan, Akpınar’dan

                                                   Aksu’dan! 

Yollara döküldü ayşeler, Fatmalar, Meyrolar, 

                                                             Memeolar

Omuzlarında gıl heybe, ayaklarında gıllı çarık

Horana kalktılar Gocamüdürle, halka halka

Pazarören’de, Yıldızeli’nde, Beşikdüzü’de, 

                                                          Düziçi’nde

Bentler çekildi, gayalar söküldü yerli yerinden

Yarasalar uçamaz oldu, guzgunlar döndü havada

Bir yıldız çavdı, bir yıldız çavdı yüceden yüce

Hasanoğlan’da, Ortaklar’da, pulur’da, Cılavuz’da! ..

Memedler (tuu!)   deyince gazmalara

Korkunç soludu, engerek yılanı korkunç

Kırmızı güle geçince ovalar, güneş başkalaştı

                                                              Pırıl pırıl

Savaştepe’de, Kepirtepe’de, Arifiye’de, Çifteler’de

Gımıldaddı anadolu gımıl gımıl, hani benim ganat 

                                                                      Çırpan guşlarım

Çiftliklerim, işliklerim, dersliklerim

Hey sisdağı, Sisdağı, gurulacak horanlarım

Gönen’de, Gölköy’de, İvriz’de, Dicle’de, Edirne’de! ..', 'Hazır yiyici değildik                                                                              Tan yeri gibi ağarıyorduk! .. Yaman çavdı...', ARRAY['Türk Edebiyatı','Şiir','Ozan Nebi Dadaloğlu']::text[], 8.5, '{"poet":"Ozan Nebi Dadaloğlu","poet_slug":"ozan-nebi-dadaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hani-benim-ganat-cirpan-guslarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arayış', 'arayis-cevat-akgun-cq5tw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bakıyorum alemde

Bir arayış havası

Koyunlar kuzusunu

       Ben seni arıyorum

Oyuncağı kırılmış

Ağlayan cocuk gibi, 

Analar yavrusunu, 

    Ben seni arıyorum

Tebessüm ediyorum, , 

Her yüzüme gülene

Bilmezler doğrusunu

        Ben seni arıyorum

Ymek için yaşıyor, 

Değilim şu alemde.

Insaniar coğusunu

        Ben seni arıyorum

Bizim aşk dediğimiz, 

Abartılmış yalanmış, 

Mecnunlar leylesını

        Ben seni arıyorum

Çobanın haberi yok

Önümdeki sürüden

Çobanlar sürüsünğ

      Ben seni arıyorum

Maddiyata sevdalı

Hayal perest insanlar

Onlar neyin nesini

       Ben seni arıyorum

Yanlızlığa boğulmuş

Çın çın öten kubbeler

Minareler süsünü

      Ben seni arıyorum

Mazideki gerçeği

Unuttuk birer birer

Tarihler öyküsünü

      Ben seni arıyorum

Arkasını dönmüşte

Aynanın ön yüzüne

Onlar görüntüsünü

    Ben seni arıyorum

Gülleler dökülürdü, 

Surların tepesine, 

Gökler gürültüsünü 

        Ben seni arıyorum

Ilkbahar da sonbahar

Mmevsimini yaşadık

Ağaçlar meyvesini

       Ben seni arıyorum.

Yalanlara karışmış

Gerçeğin filizleri

Güller bülbül sesini

       Ben seni arıyorum

Gece gündüz demeden

Yokuş ve düz demeden.

Bu yollar yolcusunu, 

       Ben seni arıyorum.

Gözümüzü bürümüş

Makam mevki hevesi, 

Gafiller övgüsünü

        Ben seni arıyorum', 'Bakıyorum alemde Bir arayış havası Koyunlar kuzusunu        Ben seni arıyorum Oyuncağı kırılmış Ağlayan cocuk gibi,  Analar yavrusunu,      ...', ARRAY['Türk Edebiyatı','Şiir','Cevat Akgün']::text[], 8.5, '{"poet":"Cevat Akgün","poet_slug":"cevat-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/arayis-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Sesim', 'benim-sesim-cevat-akgun-wi201', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir 

Ses duydum

         Kaba kaba, 

Bu ses benim mi 

         Acaba

Bir ses duydum

Boğuk boğuk

O ses ki sesimden 

         Soğuk

Bir 

Ses duydum

Acı acı.

Bu seste bana

         Yabancı

Bir 

Ses duydum

Son nefesim

İşte bu ses

         Benim sesim', 'Bir  Ses duydum          Kaba kaba,  Bu ses benim mi           Acaba Bir ses duydum Boğuk boğuk O ses ki sesimden           Soğuk Bir  Ses d...', ARRAY['Türk Edebiyatı','Şiir','Cevat Akgün']::text[], 8.5, '{"poet":"Cevat Akgün","poet_slug":"cevat-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/benim-sesim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunmayın', 'dokunmayin-sakir-bozan-na4mx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dokunmayın acılarıma

Onlar benliğimi bana anlatır

Sizler yokken onlardı hep yanıbaşımda

Onlardı yüreğimi yakan

Onlardı canevimden yıkan

Dokunmayın yanlızlığıma

Ben böylesine alışığım

Ben böyle yaşamalıyım

Ben yalnız yaşamalıyım

Ben yalnız ölmeliyim

Dokunmayın çığlıklarıma

Beni onlar anlatır

Canımın yandığını

Yüreğimin kanadığını

Onlar anlatır onlar söyler

Dokunmayın gözyaşlarıma

Ben onları içimde çoğalttım

Onlar ıslatır yanaklarımı

Susuzluğumu onlarla gideririm

Bir yudum su vermediğiniz anlarda

Dokunmayın umutlarıma

Yakarım hepinizi Alimallah

Bir tek umutlarımdan  başka

Kimsem yok beklediğim uzaklardan

Siz siz olun dokunmayın

Ölürsünüz  ÖLÜRSÜNÜZ

Şakir BOZAN

10-11-2002', 'Dokunmayın acılarıma Onlar benliğimi bana anlatır Sizler yokken onlardı hep yanıbaşımda Onlardı yüreğimi yakan Onlardı canevimden yıkan Doku...', ARRAY['Türk Edebiyatı','Şiir','Şakir Bozan']::text[], 8.5, '{"poet":"Şakir Bozan","poet_slug":"sakir-bozan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/dokunmayin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balıkçılar', 'balikcilar-gokcen-duran-ilkp3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Denizi yarıyor balıkçı tekneleri

Uykuları bölünmüş tayfaların gözlerinde

Geçim derdinin bin bir zorlukları

Büyüdükçe büyüyor dalgalarla kardeşçe

Unutuluyor geçen her günün verimsizliği

Daha bir umutla sarılıyorlar işlerine

Çabaları umutla katıklanmış ekmek oluyor

Fakir balıkçı sofralarına

             Geçiyor takalar önümden

             Bir ileri, bir geri

             Denizi yarıyor balıkçı tekneleri

             Uykuları bölünmüş tayfaların gözlerinde', 'Denizi yarıyor balıkçı tekneleri Uykuları bölünmüş tayfaların gözlerinde Geçim derdinin bin bir zorlukları Büyüdükçe büyüyor dalgalarla kard...', ARRAY['Türk Edebiyatı','Şiir','Gökçen Duran']::text[], 8.5, '{"poet":"Gökçen Duran","poet_slug":"gokcen-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/balikcilar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazanımsın', 'hazanimsin-gokcen-duran-sbgzk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hangi rüzgar döktü yapraklarını

Ayaz geceler üşütür şimdi seni

               

                              Üşüme sen benim hazanımsın

 Zaman bir bir acıtır yaralarını

Ayrılıklar sonrası sığındığın limanlarda

                 

                             Acımasın yüreğin sen benim hazanımsın

Nedenler arasın yaşatmak için anılarını

Ilık bir haz duyarsan her anı kırıntısında

                              Yaşat anılarını sen benim hazanımsın

Melekler usulca sokulur düşlerine

Senden çalınan çocukluğun başını okşar

                             

                              Okşat saçlarını sen benim hazanımsın

Işıl ışıl olur gözlerin, kanamaz artık yaran

Nevbahar gelir bakıri hüzünlerine usulca

                              Hüzünlerine bahar gelsin sen benim hazanımsın', 'Hangi rüzgar döktü yapraklarını Ayaz geceler üşütür şimdi seni                                               Üşüme sen benim hazanımsın  Zam...', ARRAY['Türk Edebiyatı','Şiir','Gökçen Duran']::text[], 8.5, '{"poet":"Gökçen Duran","poet_slug":"gokcen-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hazanimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karakavak 1', 'karakavak-1-husrev-hatemi-l6wf4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kıyıda tahammülfersa çay bahçeleri, 

Sıcak ve güneşte parlayan semaverler

Bu olmayacak..böyle gitmeyecek bu

Çoraklaştı bayırlar, çoraklaştı her yer

Ancak hatırlar gibiyim çiçekleri....

Bu uğultudan nasıl ayrılır kederim? 

Savrulurken tipi kent üzerinde kışın, 

Keder de savrulsaydı ya..Hayır bilirim onu, kalır

Savrulmaz bilirim beni kül eder keder

Uzakta çay bahçeleri yerde çerçöp

Gittiğimin farkında olsaydı eğer, 

Yeterdi bana, beklemiyordum özlenmeyi

              Ne kanıt istiyorum şimdi ne bir yorum

              Derin bir keder şimdi sadece duyduğum

              Unutulmuş tren istasyonlarında ağaçlara

              Benzemek degildi hiç dileğim.....

              Mahzun saksağanların konuk olduğu, 

              Bir karakavağım şimdi, 

              Kentte tahammülfersa çay bahçeleri, 

              Oturmuş denize bakan insanlar.....

              Burda Unutulmuş bir Sultan Aziz İstasyonu, 

              Ben, demiryolu yanında bir karakavak

              Nergis ve lale tarlalarına hayli uzak.

                                     Antalya 2001', 'Kıyıda tahammülfersa çay bahçeleri,  Sıcak ve güneşte parlayan semaverler Bu olmayacak..böyle gitmeyecek bu Çoraklaştı bayırlar, çoraklaştı ...', ARRAY['Türk Edebiyatı','Şiir','Hüsrev Hatemi']::text[], 8.5, '{"poet":"Hüsrev Hatemi","poet_slug":"husrev-hatemi","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/karakavak-1-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda', 'veda-sule-subasi-bwnvs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey sokaklarında yıllarca dolaştığım........’im, 

                     Ey en masum arzularımı gizleyen odam! 

                     Ey her sabah kucakladığım öğrencilerim! 

                     Ah biliyorum güç gelecek size! 

                     Ama artık gitmek geliyor içimden, 

                     Bir sabah bembeyaz  bir bulutun peşinden, 

                     Dönüşü olmayan yerlere.', 'Ey sokaklarında yıllarca dolaştığım........’im,                       Ey en masum arzularımı gizleyen odam!                       Ey her sab...', ARRAY['Türk Edebiyatı','Şiir','Şule Subaşı']::text[], 8.5, '{"poet":"Şule Subaşı","poet_slug":"sule-subasi","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/veda-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karakavak 2', 'karakavak-2-husrev-hatemi-bgssp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kimse kimseye doymadı ki, herkesi herkesin

Herkesi herkesin elinden aldılar

Böyle söylemişti o zayıf, 

Avurtları çökük ve parlak gözlü, 

Siyahlar giyinmiş, siyah çoraplı hanım...

Böyle söylemişti gıcırtılı

İçimi üşüten sesiyle

''Burada bir Nevin Hanım vardı degil  miii? 

Sonra iki kızı ve kendisi, 

Zaman geçti ve öldüler degil miii? ''

Boğazım kurumuştu sessiz, 

Bir çığlıkla uyandığımda

Hemen kayboldu zayıf Hanım

O zaman dokuz yaşındaydım

Şimdiyse bir karakavak', 'Kimse kimseye doymadı ki, herkesi herkesin Herkesi herkesin elinden aldılar Böyle söylemişti o zayıf,  Avurtları çökük ve parlak gözlü,  Siy...', ARRAY['Türk Edebiyatı','Şiir','Hüsrev Hatemi']::text[], 8.5, '{"poet":"Hüsrev Hatemi","poet_slug":"husrev-hatemi","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/karakavak-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karakavak 3', 'karakavak-3-husrev-hatemi-rseh9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gece, aranıyordu yine arıyordu sızacağı ruhlara yol...

Ruhlar olmasa Gece nedir ki? 

Geceler nedir ki...hepsi geçicidir...

Vurulmaktan korkar gece...bu sebepten

Vurur İnsanları canevinden evlerinde...

Vurur insanları tarlalarda, ormanlarda

Vurur insanları otoyolda bulvarlarda...

Gece ülkesinde soluk daralabilir, 

Gece yaraları en onulmazı yaraların.', 'Gece, aranıyordu yine arıyordu sızacağı ruhlara yol... Ruhlar olmasa Gece nedir ki?  Geceler nedir ki...hepsi geçicidir... Vurulmaktan korka...', ARRAY['Türk Edebiyatı','Şiir','Hüsrev Hatemi']::text[], 8.5, '{"poet":"Hüsrev Hatemi","poet_slug":"husrev-hatemi","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/karakavak-3-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karakavak 4', 'karakavak-4-husrev-hatemi-bfhs8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir ney sesiyle hıçkırık, 

Karışık...

Edirne yolunda tipi, 

Önce  serpen, giderek yoğunlaşan kar

Ölüm yine salınıyor sekerek

Ah Ölüm, Ah Seeen, boğazına dursun ham çökelek

Sen Edirne, sen neşeli günlerimde bile...

Hüznü kulağıma bağıran diyar...

Uzakta tahammülfersa çay bahçeleri...

Kenara yığılmış ve örtülü

Yaz mevsimini bekleyen masalar

Benim beklediğim gelmiyecek ve ayrıca

Beni de bekleyen yok', 'Bir ney sesiyle hıçkırık,  Karışık... Edirne yolunda tipi,  Önce  serpen, giderek yoğunlaşan kar Ölüm yine salınıyor sekerek Ah Ölüm, Ah See...', ARRAY['Türk Edebiyatı','Şiir','Hüsrev Hatemi']::text[], 8.5, '{"poet":"Hüsrev Hatemi","poet_slug":"husrev-hatemi","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/karakavak-4-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasak Sevdam', 'yasak-sevdam-guney-ozdemir-pbdl7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bu sehrin izdihaminda

yasakli sevdalardan

gizemli siirler besliyorum

en ünlü serüvenleri

hem de en kasvetinden

haritanin adsinda diretiyorum

gönlünü zorla da olsa

dizelerle isgal etmek istiyorum', 'bu sehrin izdihaminda yasakli sevdalardan gizemli siirler besliyorum en ünlü serüvenleri hem de en kasvetinden haritanin adsinda diretiyorum...', ARRAY['Türk Edebiyatı','Şiir','Güney Özdemir']::text[], 8.5, '{"poet":"Güney Özdemir","poet_slug":"guney-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yasak-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar Gülü', 'sonbahar-gulu-bahri-sohtorik-u1h2n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben sana susamış sana hasretim

Kimseye yar olmam sana kısmetim

Sen olmazsan olmaz  benim vuslatım

Gel artık, sonbahar gülüm açıyor

Vuslatın zamanı geldi geçiyor

Ne başka güzelin bendesi oldum

Ne aşklarla doldum, ne de duruldum

Ben sana aşığım, sana vuruldum

Gel artık, sonbahar gülüm açıyor

Vuslatın zamanı geldi geçiyor

Haydi gel yapraklar hazal olmadan

Bahçede çiçekler bir bir solmadan

Akıbet, bir kara toprak olmadan

Gel artık, sonbahar gülüm açıyor

Vuslatın zamanı geldi geçiyor', 'Ben sana susamış sana hasretim Kimseye yar olmam sana kısmetim Sen olmazsan olmaz  benim vuslatım Gel artık, sonbahar gülüm açıyor Vuslatın ...', ARRAY['Türk Edebiyatı','Şiir','Bahri Sohtorik']::text[], 8.5, '{"poet":"Bahri Sohtorik","poet_slug":"bahri-sohtorik","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sonbahar-gulu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bilsen', 'bir-bilsen-bahri-sohtorik-l8qtn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayal gibi geçti bunca seneler

Düşüm sendin, yaşadığım dünyam sen

Suskunluğun bana çok şey söylüyor

İçimdeki şu kavgayı bir bilsen

Şikar idin, şahan oldun sayemde

Aşk odunu yakar oldun sayemde

Ben mamurdum, viran oldum alemde

Sen bendeki yıkıntıyı bir bilsen

Akarsuyum, çağlayanım, akarım

Yaş dökmeden ağlayanım, çekerim

Değersizsem, bu sevdadan geçerim

Pahasızım, değerimi bir bilsen

Ne ben küstüm, ne sen beni anladın

Benim gibi belki aşık olmadın

Bu ateşle bir gün dahi yanmadın

Nasıl yakar, acısını bir bilsen', 'Hayal gibi geçti bunca seneler Düşüm sendin, yaşadığım dünyam sen Suskunluğun bana çok şey söylüyor İçimdeki şu kavgayı bir bilsen Şikar idi...', ARRAY['Türk Edebiyatı','Şiir','Bahri Sohtorik']::text[], 8.5, '{"poet":"Bahri Sohtorik","poet_slug":"bahri-sohtorik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-bilsen-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sis Basar', 'sis-basar-bahri-sohtorik-smbwr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni her düşündüğümde

Mutlu anılar gelir aklıma

Mutlu anlar, mutlu günler

Sanırsın ki mutluluktan uçarım, 

Bir an, 

Sis basar düşüncelerimi

Yas''lanırım

Seni her düşündüğümde

Yaşama sevinci sarar beni

Gül yüzlü gülüşlerle güler

Sevgi denizinde yüzerim, 

Bir an, 

Sis basar düşüncelerimi

Hislenirim

Seni her düşündüğümde

Beni burada yaralı

Bütün günlerimi karalı

Bıraktığın gelir aklıma, 

Bir an, 

Sis basar düşüncelerimi

Puslanırım.', 'Seni her düşündüğümde Mutlu anılar gelir aklıma Mutlu anlar, mutlu günler Sanırsın ki mutluluktan uçarım,  Bir an,  Sis basar düşüncelerimi ...', ARRAY['Türk Edebiyatı','Şiir','Bahri Sohtorik']::text[], 8.5, '{"poet":"Bahri Sohtorik","poet_slug":"bahri-sohtorik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sis-basar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Tutulması', 'ay-tutulmasi-selim-eysioglu-u59wo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen, yüreğimde yaşayan en büyük sevda, 

Sen gündüz hayaldesin, geceleri rüyada, 

Sen, yollarda beklediğim, yolunu gözlediğim, 

Sen, ey güzel! Akşamdan...sabaha özlediğim

Yaşadığın şehirde güneş bir başka doğar.

Gözünün değdiği çiçek, hepsinden güzel kokar.

Ve senin o gözlerin, ateşten beter yakar.

Sen,  ey güzel,  en güzel,  herkesten gizlediğim.

Basit aşıklar der ya; ''Şarkılar sana söyleniyor''

Çok sıradan sözler bunlar, sana hiç yakışmıyor.

''Ay'' Dünyanın değil, senin uydun bir tanem; 

İnan bana;  ''Ay'' yıllardır etrafında dönüyor.

Etrafında dönüp duran bir aşığın daha var.

''Ay''  ve  ''O'' senin için, yanıp tutuşmaktalar.

Ve her ikisi de bazan, sana tutulmaktalar; 

Biri ''Ay tutulması''  -ki bir süre sonra biter, 

Diğeri ''Selim tutulması'' bir ömür boyu sürer...

(11.10.2002   Ankara)', 'Sen, yüreğimde yaşayan en büyük sevda,  Sen gündüz hayaldesin, geceleri rüyada,  Sen, yollarda beklediğim, yolunu gözlediğim,  Sen, ey güzel...', ARRAY['Türk Edebiyatı','Şiir','Selim Eyşioğlu']::text[], 8.5, '{"poet":"Selim Eyşioğlu","poet_slug":"selim-eysioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ay-tutulmasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kutsal tebessüm', 'kutsal-tebessum-begmurat-bayriyev-671nv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir yağmur damlası kadar temiz ve berrak

Gönlüme dokunur bazen karA bazen ak

Ahh! Güzelim ne bu kaldırılır mı hiç, 

Bir yük ki eriyiverir tek tebessümünle 

Bir yük kaybolur gülümsemenle

Masum bakışların kalbimde mühür

Duygularım çıplak, ruhum benim hür 

Rüzgarın esmesi..yağmura yağması...

Fırtına kopmadan güzün gelmesi...

Hepsi. Ama hepsi de sende

Senin o masumca gülen çehrende 

Bahar gelir bana tebessümünle', 'Bir yağmur damlası kadar temiz ve berrak Gönlüme dokunur bazen karA bazen ak Ahh! Güzelim ne bu kaldırılır mı hiç,  Bir yük ki eriyiverir te...', ARRAY['Türk Edebiyatı','Şiir','Begmurat Bayriyev']::text[], 8.5, '{"poet":"Begmurat Bayriyev","poet_slug":"begmurat-bayriyev","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kutsal-tebessum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidene Destan', 'gidene-destan-ergun-yildiz-oofu4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüzündeki hüznü döktün yüzüme

Yağmurları serptin gülen gözüme

Giderken ateşi attın özüme

Sen gittin gideli gülemez oldum.



Al kana boyadın sinemi benim

Yıktın harap ettin hanemi benim

Çaldın gittin, bunca senemi benim

Yitik  yıllarımı bulamaz oldum. 



Artık boyun eğdim alın yazıma

Yandım dedim, inanmadın sözüme 

Dünya zindan görünüyor gözüme

Gecemi, gündüz mü bilemez oldum.



Bir dal idim, kırdın beni sonunda

Eğilmedim ama, düştüm önünde

Ne en güzel, ne de kötü gününde

Ben senin yanına gelemez oldum



Düşüp şu toprağa çürümek için

Hasretinle yanıp erimek için

Dön deyip ardından yürümek için

Bedenimde derman bulamaz oldum.



Kimselere boyun eğmez biriydim 

Yüreğine sevda koymaz biriydim

Gözlerine hüzün değmez biriydim

Şimdi gözyaşımı silemez oldum.



Oysa nasıl ölesiye sevdim ben

Nasıl bağlanmıştım sana bir bilsen

Yüreğimde ümidini beslerken

Düşlerimi gerçek kılamaz oldum



Teli kırık saza çevirdin beni

Susuz, kurak yaza çevirdin beni

Ayrılık yeline savurdun beni

Ben artık yönümü bulamaz oldum.



Gökte yıldız idim, yere indirdin

Narımı aldın da beni söndürdün

Akil idim, divaneye döndürdün

Ben bile kendimi bilemez oldum. 



Bir kara geceden ayrılıp geldin

Eski yaşamından sıyrılıp geldin

Sandım ki benimsin, hep benim oldun

Meğer yalan imiş, gülemez oldum



Gerçek ile düş arası bir şeysin

Bahar ile kış arası bir şeysin

Kahkahayla yaş arası bir şeysin

Seni koyacak yer bulamaz oldum.



Çok uzattım hiç tutmadın elimi

Çok anlattım anlamadın halimi

Bir meçhule yönlendirdin yolumu

Yürüsem de sana gelemez oldum



Hep bir sır olarak kalsa da yüzün

Bil ki  hep ruhumda kalacak izin

Anladım, yarını yok ikimizin

Şu dünyadan bir tad alamaz oldum



Sevdim seni, yine pişman değilim

Çok kırıldım, ama düşman değilim

Artık, o savaşan insan değilim

Direnecek gücü bulamaz oldum.



Ergun YILDIZ.

13.11.2002', 'Yüzündeki hüznü döktün yüzüme Yağmurları serptin gülen gözüme Giderken ateşi attın özüme Sen gittin gideli gülemez oldum. Al kana boyadın si...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/gidene-destan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaşırma Duvar Aşklarına II', 'sasirma-duvar-asklarina-ii-umut-ulbegi-vzp9j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hani bir durak aşkı görmüştüm ya

Ocak ayını Şubat''a bağlıyordu yalnızlığım

bugün bir bebeğe can verecek kadar gün geçmiş aradan

Saydım ilkokul matematiğini aşamamış kayıtsız parmaklarımla

Dudaklarımda kül renkli gecelerden -ki daha çok sigara içiyorum dünden- dökülen o cümle

Işığım sana aşığım

Her ay dönümünde tekrarladığım

Aşığım sana ışığım

Tersyüz edip yeniden bağlandığım

Şimdi Grangé geçiyor yanımdan 

göç uçuşu kazıyorum yüreğimden ışığını

elimde buluttan kümülüs bir neşter 

ve geceye süzülen damlalar

Hani bir durak aşkı görmüştüm ya

İşte o yürüyor artık.

08.11.2002', 'Hani bir durak aşkı görmüştüm ya Ocak ayını Şubat''a bağlıyordu yalnızlığım bugün bir bebeğe can verecek kadar gün geçmiş aradan Saydım ilkok...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sasirma-duvar-asklarina-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve BEN', 'sen-ve-ben-murat-tali-tbt8t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir yürek ezgisidir çalınır çığlık çığlığa, 

bir tutkudur söylenir dize dize, 

bir özlemdir dile gelir hece hece, 

tutunamaz gece, 

tutunamaz gün, 

katılmak ister satır satır güneşe, 

Güneş gülüşünde saklı

Yağmur Gözlüm

Sen gece ve gündüz

sen siyah ve beyaz

sen hüzün ve coşku

sen yitik ve doğru adreslersin benim için

Sen yitikliğimde bulduğumsun. 

sen aslında bensin 

benden içeri 

bensin benden içeri 

BEN', 'bir yürek ezgisidir çalınır çığlık çığlığa,  bir tutkudur söylenir dize dize,  bir özlemdir dile gelir hece hece,  tutunamaz gece,  tutunama...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-ve-ben-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen de Unutma', 'sen-de-unutma-ensar-cevval-l77jx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Onsekizindeydim

Güneşin soldurmadığı amazon yeşili

Bir orman kuytusu gözlerin vardı

Başak rengi örülü bir demetti saçların

Rüzgârın her esişinde savrulan, 

Savruldukça da yüzleri okşayan saçların.

Gül kokardı, karanfil 

En çok ta yasemin; 

Sevinçli iken bir bakışın vardı

Ağustosta, çıplak ayakla kumda yürümek

Güneşi avuçlarında tutmak gibiydi.

Hüzünse, gözlerinde idam sehpasına çıkmak

Son kez, doyasıya bakmaktı yaşama.

Yağmur ormanlarında pusulamdın 

 Kaybettim...

Okyanusta yön veren yıldızımdın sen

Gökyüzünün en parlak, en kaygan yıldızı

Gözlerimde fer, damarlarımda ılık bir süzülüştün.

Bir yaz gecesi gözlerimi kırparken aniden

Sonsuzluğa, ölümün ağzına düşürdüm seni

Kaybettim...

Otuzlardaydım son gördüğümde

Damarlarımdan denizler taştı, 

Yüreğimde volkanlar

Gözlerine baktım, yeşili azdı

Saçlarına baktım, yarısı beyazdı

O yaz gecesi, son kırpmamdı gözlerimi

Bin yaz gecesi geçse de kırpmam artık gözlerimi

Bizimki sevda değil, bir adı her neyse

Dalgaların, gözyaşları ile yıkayıp, 

Sonra koynunda dinlendiği taştı.

Ağlarken, çiçekler boyun bükerdi, 

Gülünce, minik elli bebekler gülerdi 

 Bir adımlık uzaklıktasın şimdi

Gözlerine bakarken utanıyorsam hala

Gözlerim, hala dolabiliyorsa karşında

Ellerim, uyuşuyor, dilim tutuluyorsa

Ve hala ilk günün heyecanını taşıyorsam eğer

Bu, seni unutamadığımdandır

Sen de beni unutma...

Ensar CEVVAL 2002', 'Onsekizindeydim Güneşin soldurmadığı amazon yeşili Bir orman kuytusu gözlerin vardı Başak rengi örülü bir demetti saçların Rüzgârın her esiş...', ARRAY['Türk Edebiyatı','Şiir','Ensar Cevval']::text[], 8.5, '{"poet":"Ensar Cevval","poet_slug":"ensar-cevval","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/sen-de-unutma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Ve Rüzgar', 'deniz-ve-ruzgar-serhat-sumer-ed0td', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir duman kaplardı gözlerimi 

Ve deli dolu bir akşamdı

Titreten ellerimi.

Hüzünlü şarkıların 

Ayrılığa açılan penceresinde 

Mahzun bakışlı çocuk yüzüydüm

Ve sen 

Başka iklimlerin 

Başka yüzlere vurduğu 

Rüzgarda kokardın 

Teninde nisan yağmurları

Ağlardım.

Her zaman acıklı

Gamlı bir mevsimin kanadına 

Yüklerdim rüyalarımı.

Her şey  “sen” olurdu o zaman 

Ve hiçbir şey

“Ben” olmayı beceremezdi senin yanında 

Yaralı bir ilkbahar akşamının 

Sana çırpınan son  bulutuydum 

Şarkı dolu rüzgarlarda bıraktım yıldızımı

Ve çoktan unuttum karanlığı 

Şimdi bana kurban ver

İçine yıldız düşmüş akşamları...', 'Bir duman kaplardı gözlerimi  Ve deli dolu bir akşamdı Titreten ellerimi. Hüzünlü şarkıların  Ayrılığa açılan penceresinde  Mahzun bakışlı ç...', ARRAY['Türk Edebiyatı','Şiir','Serhat Sümer']::text[], 8.5, '{"poet":"Serhat Sümer","poet_slug":"serhat-sumer","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/deniz-ve-ruzgar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret Yanığı', 'hasret-yanigi-sadik-altinkaynak-2iti4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bakmayın rengimin karalığına

Tenim denizde değil hasretten yandı

Bakın ki şu bahtımın karalığına

Herkes beni zevk-u sefada sandı

Rengim bronz ben doğuştan yanığım

Her türlü derde mihnete tanığım

Bakın ki şu işin maskaralığına 

Herkes beni zevk-u sefada sandı

Bakmayın yüzümün güleç olduğuna

Lokman çare olmaz feleğin vurduğuna

Kulak asıp müzevirlerin uydurduğuna

Herkes beni zevk-u sefada sandı

                                   Eylül-2001', 'Bakmayın rengimin karalığına Tenim denizde değil hasretten yandı Bakın ki şu bahtımın karalığına Herkes beni zevk-u sefada sandı Rengim bron...', ARRAY['Türk Edebiyatı','Şiir','Sadık Altınkaynak']::text[], 8.5, '{"poet":"Sadık Altınkaynak","poet_slug":"sadik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hasret-yanigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evlerinin Önü-3+', 'evlerinin-onu-3-bayram-tunca-ijjt6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Evlerimizin önü bayır mı bayır

Yar ne olur elçime deme hayır

Yüreğim yanmakta cayır cayır

Evet de ki sonu da olsun hayır

Evlerinin önü, dik mi dik yokuş

Mest eder âdemi o güzel kokuş

Bakışıyla işler ilmek ilmek nakış 

Mest eder âdemi o gizemli bakış

Evlerinin önü bir dönümlük kesik

Evlerinde var, tahtadan bir beşik

Elime verdiler, tahtadan bir kaşık

O bana ben ona ikimiz olduk âşık

Evlerinin önünden geçer patika yol 

O yâri görmezsem, kalkmaz bu kol

Onun aşkından yüreğim oldu akkor

Leylâ’sız yaşamak, ölümden de zor

09.08.2002-18:45

''Aşk Ateşten GÖmlek''', 'Evlerimizin önü bayır mı bayır Yar ne olur elçime deme hayır Yüreğim yanmakta cayır cayır Evet de ki sonu da olsun hayır Evlerinin önü, dik ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/evlerinin-onu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Ateşi', 'ayrilik-atesi-sadik-altinkaynak-svwvc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ayrılık ateşi yaktı gönlümü

Bu ateş sönmez hasret bitmeden

Zaman zaman aratıyor ölümü

İflah olmam sevda baştan gitmeden

Vuslattır ancak ayrılığın ilacı

Ayrılık sızısı ölümden acı

Üç vakte kadar gelecek dedi falcı

Geleceksen gel ecel yetmeden

Bilirim gurbette ben yanarım sılada sen

Ya ben sana gelsem ya da sen gelsen

Yollara çıksan pencerede beklesen

Gelirim bir sabah şafak sökmeden', 'Ayrılık ateşi yaktı gönlümü Bu ateş sönmez hasret bitmeden Zaman zaman aratıyor ölümü İflah olmam sevda baştan gitmeden Vuslattır ancak ayrı...', ARRAY['Türk Edebiyatı','Şiir','Sadık Altınkaynak']::text[], 8.5, '{"poet":"Sadık Altınkaynak","poet_slug":"sadik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ayrilik-atesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Daha', 'bir-daha-sadik-altinkaynak-3m0hb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Akdeniz kıyısındayım garip tenha

Dalgaları dinliyorum akşamdan sabaha

Kıyıya hışımla vuran her deli dalga

Beynimde yankılanır bir daha bir daha

Ne uyku kaldı bende ne iştaha

Ne tebessüm kaldı ne kahkaha

Sabaha dek dua ettim Allah''a

Gurbette yalnız koyma bir daha

Neyleyim kaderim bu müfettişim

Hep evimden barkımdan uzakta işim

Daim gözümde tüter çocuklarım eşim

Hasretle yanarım bir daha bir daha

Gazipaşa demişler bu gurbet diyarına

Gurbet bu biter mi bu günden yarına

Can mı dayanır şu gurbet efkârına

Her gün yeniden ölürüm bir daha bir daha', 'Akdeniz kıyısındayım garip tenha Dalgaları dinliyorum akşamdan sabaha Kıyıya hışımla vuran her deli dalga Beynimde yankılanır bir daha bir d...', ARRAY['Türk Edebiyatı','Şiir','Sadık Altınkaynak']::text[], 8.5, '{"poet":"Sadık Altınkaynak","poet_slug":"sadik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-daha-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutadair', 'umutadair-karartma-geceleri-x0y7y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Umut...

Yarınların adı olsun

Bizden sonrakilere selam olsun

Ellere takılan kelepçenin

Dağlarımda uçan ak güvercinin

Esaret altında kalmış halkımın 

Adı umut olsun

Bizden sonrakilere selam olsun

Emekçinin alın teri

Yurttaşın sevgisi

Yoldaşın cesareti

Devrimci gençlik ateşinin 

Adı umut olsun

Bizden sonrakilere selam olsun

Umut yarınların adı olsun...

                                         (21 -4-2001)', 'Umut... Yarınların adı olsun Bizden sonrakilere selam olsun Ellere takılan kelepçenin Dağlarımda uçan ak güvercinin Esaret altında kalmış ha...', ARRAY['Türk Edebiyatı','Şiir','Karartma Geceleri']::text[], 8.5, '{"poet":"Karartma Geceleri","poet_slug":"karartma-geceleri","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/umutadair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Benim Herşeyimsin', 'sen-benim-herseyimsin-onder-durmus-if5g1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir samyeli olacağım, 

Saçının tellerini birbirinden ayıran, 

Denizdeki bir dalga olacağım, 

Koşarak gelip sana sarılan, 

Tutup elinden uçacağım semaya, 

Ve yavaş yavaş karışacağız bulutlara, 

Sahildeki kum tanelerini saymaya çalışırken, 

Dudağına bir öpücük kondurup, 

Seni seviyorum diyeceğim, 

Seni daha gitmeden özleyeceğim, 

Ve sonsuza dek bekleyeceğim, 

Sen benim herşeyimsin.

11.11.2002', 'Bir samyeli olacağım,  Saçının tellerini birbirinden ayıran,  Denizdeki bir dalga olacağım,  Koşarak gelip sana sarılan,  Tutup elinden uçac...', ARRAY['Türk Edebiyatı','Şiir','Önder Durmuş']::text[], 8.5, '{"poet":"Önder Durmuş","poet_slug":"onder-durmus","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sen-benim-herseyimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muradım....(?)', 'muradim-bekir-ayral-yem28', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yiğitlerin otağında, 

Bir kulum olsun istedim.

Erenlerin divanında, 

Bir sözüm olsun istedim.

Güzellerin yatağında, 

Bir gülüm olsun istedim.

Boşa geçti bunca zaman, 

Muradıma eremedim.

Eremedim canım, gülüm.

Eremedim bir tanem, 

Boşa geçti bunca zaman, 

Muradıma eremedim.', 'Yiğitlerin otağında,  Bir kulum olsun istedim. Erenlerin divanında,  Bir sözüm olsun istedim. Güzellerin yatağında,  Bir gülüm olsun istedim...', ARRAY['Türk Edebiyatı','Şiir','Bekir Ayral']::text[], 8.5, '{"poet":"Bekir Ayral","poet_slug":"bekir-ayral","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/muradim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Misal...!', 'misal-bekir-ayral-gcwxf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Patlıyor birer, birer

Parçalanıyor beynimde, 

Düşünceler, 

Duygular

Ve tüm ümitler

Bir Atom Bombası

MİSALİ.

Patlayıp, parçalandıkça

Birer, birer

Sarsıyor 

Tüm

Hayatımı, 

Ruhumu, 

Ve bedenimi

Silkelenen bir Dut Ağacı 

MİSALİ.

Sarsıldıkça, 

Birer, birer

Dökülüyor, 

Dağılıyor etrafa

Parçalanmış

Düşünceler, 

Duygular

Ve ümitler

Birer dut tanesi

MİSALİ.

Dökülüp, dağıldıkça

Birer, birer

Kaybolup, yok oluyor

Parlak gün ışığında

Buharlaşıp, uçan

Bir su damlası

MİSALİ.

Kaybolup, yok oldukça

Birer, birer

Sönüyor

İçimdeki aydınlık, 

Koparıyor beni

Hayattan, 

Götürüyor ruhumu

Sonsuz bir karanlığa, 

Mezara konan

Bir ceset

MİSALİ.', 'Patlıyor birer, birer Parçalanıyor beynimde,  Düşünceler,  Duygular Ve tüm ümitler Bir Atom Bombası MİSALİ. Patlayıp, parçalandıkça Birer, b...', ARRAY['Türk Edebiyatı','Şiir','Bekir Ayral']::text[], 8.5, '{"poet":"Bekir Ayral","poet_slug":"bekir-ayral","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/misal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sevgi Büyüttüm', 'bir-sevgi-buyuttum-murat-tali-iz07k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir sevgi büyüttüm susuz ve güneşsiz

bir sevgi büyüttüm saksısız ve topraksız

bir sevgi büyüttüm aysız ve yıldızsız gecelerden

bir sevgi büyüttüm karşılıksız ve çıkarsız

bir sevgi büyüttüm parasız ve çeksiz

bir sevgi büyüttüm sessiz ve derinden

bir sevgi büyüttüm ıraksamalardan

bir sevgi büyüttüm duraksamalardan

bir sevgi büyüttüm özlemlerden türkülere dönerek

bir sevgi büyüttüm büyümeyen yanımla

bir sevgi büyüttüm adressiz ve çoğullaşarak

bir sevgi büyüttüm büyüdükçe çocuklaşarak

bir sevgi büyüttüm kollarımı açtığımda büyüyerek

bir sevgi büyüttüm bitmeyecek bitirilmeyecek

bir sevgi büyüttüm büyüdüğünde sana varacak

bir sevgi büyüttüm büyüdüğünde sana varacak 

büyüdüğünde sana varacak

Büyüde gel 

Büyüde gel', 'bir sevgi büyüttüm susuz ve güneşsiz bir sevgi büyüttüm saksısız ve topraksız bir sevgi büyüttüm aysız ve yıldızsız gecelerden bir sevgi büy...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-sevgi-buyuttum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Ne Bilem', 'ben-ne-bilem-mustafa-demirci-2-ki3qs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben ne bilem senin kırılacağını

Ne bilem göz yaşlarının bu kadar çok olduğunu

Ben ne bilem kalbinin bu kadar yanacağını

Ne bilem güneşin bu kadar çabuk söneceğini

Hatırlarmısın ellerimizin birbirine değdiğini

Nasılda sıçaktı senin ellerin

Dudaklarının dudaklarıma dediğini

Nasılda salıvermiştin kendini...

Hani loş ışığın altında bir ceylan gibiydin

Taze ve berrak yüzündeki tebessüm

Beni yalnız bırakın gidin

Ben ne bilem seni bu kadar sevdiğimi

Şimdi yapayalnız kalmışım dünyada

Ne sen varsın nede gölgen

Hayalin bile bazen gidip gidiyor gözlerimden

Sisli ve dumanlı bir sahne gibi

Pırıltısı kalmadı güneşin

Bak bulutlandı havalar

Ben ne bilem seni bu kadar özlediğimi', 'Ben ne bilem senin kırılacağını Ne bilem göz yaşlarının bu kadar çok olduğunu Ben ne bilem kalbinin bu kadar yanacağını Ne bilem güneşin bu ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Demirci 2']::text[], 8.5, '{"poet":"Mustafa Demirci 2","poet_slug":"mustafa-demirci-2","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ben-ne-bilem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tek Sen Bilmelisin', 'bir-tek-sen-bilmelisin-koray-musicbox-ilqla', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir tek sen bilmelisin ağladığımı

En büyük kederlerime sen ortak olmalısın

Utanırım başkasına anlatmaya, sıkılırım.

En korkulu rüyalarımı sana anlatabilirim sadece

En büyük sıkıntılarımı, en büyük yıkıntılarımı

Bir tek sana söyleyebilirim canımın yandığını

Bir aşk uğruna mahvolup, parçalandığımı...

Bir tek sen bilmelisin ağladığımı

Yangınını yüreğimin siyahında gecenin

Çığlıklarını beynimin çıldırasıya 

Ve hain bir bulut karanlığa terk eden ruhumu

Lime lime ederken, göğsümün sol yarısının

Bir tek sana anlatabilirim ağrılarını

Aslında olanı biteni yok eden varlığımı...

Bir tek sen bilmelisin ağladığımı

Utanır söyleyemem kimselere, sıkılırım

Bir tek sen bilmelisin yalnızlığımı

Sarhoşluğumu, yoksulluğumu, perişanlığımı 

Bir gün anlamalısın, bu dizeleri senin için yazdığımı

Bir tek sen bilmelisin söyleyemediğim her kelimede

Hayallerinle uykusuz kalarak geçirdiğim her gecede

Şiirlerimde geçen ismine ait her hecede kavrulup yandığımı

Sensiz geçen her saniye aç, susuz, halsiz, çaresiz 

Bir mahpus gibi aşka hasret kaldığımı.', 'Bir tek sen bilmelisin ağladığımı En büyük kederlerime sen ortak olmalısın Utanırım başkasına anlatmaya, sıkılırım. En korkulu rüyalarımı sa...', ARRAY['Türk Edebiyatı','Şiir','Koray Musicbox']::text[], 8.5, '{"poet":"Koray Musicbox","poet_slug":"koray-musicbox","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-tek-sen-bilmelisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Feneri', 'deniz-feneri-neslihan-ayakta-a2jyt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sikayetin mi var; 

Susma o zaman! 

Korkma ac yelkenlerini! 

Cesaretin var mi dort mevsime; 

Tadina vara vara 

Birak siir olsun yasadiklarin.

Dumende heyecan, 

Yelkende umut; 

Kamaranda sicakligin olsun.

Rotan yok, sevdanin yolundasin! 

Dalga dost, dalga dusman; 

Ruzgar tenini yaliyor.

Hic durma! 

Kiyilarda bir deniz feneri

Ve capanda kaliciligin; 

Demir attigin yerler seruvenlerin.

Rihtimlar siginagin, rihtimlar senin! 

New Jersey kiyilarinda bir deniz feneri

Haydi ac yelkenlerini! 

(22.03.02)', 'Sikayetin mi var;  Susma o zaman!  Korkma ac yelkenlerini!  Cesaretin var mi dort mevsime;  Tadina vara vara  Birak siir olsun yasadiklarin....', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/deniz-feneri-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Op Beni, Saril Bana', 'op-beni-saril-bana-neslihan-ayakta-0bc0p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Saniyem gecmiyor sensiz

Dusmanim yokluguna

Tenim cekiyor tenini

Hasretim dokunusuna

Op beni, saril bana.

Gulusune, sesine hayran

Gonlune, seyrine kurban

Sevdan yuregime ceryan

Sevkedir davet

Gel benim umut yelkenim

Gel op beni, saril bana.

Gozden sakin; sozu esirgeme

Sevdan benimdir, gerisini dusunme

Haydi gel bana, op beni

Saril bana yelkenim.

(08.04.02)', 'Saniyem gecmiyor sensiz Dusmanim yokluguna Tenim cekiyor tenini Hasretim dokunusuna Op beni, saril bana. Gulusune, sesine hayran Gonlune, se...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/op-beni-saril-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbimde', 'kalbimde-sair-karagozlum-fme2p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ismin dilimde

hayalin gözümde

hatiralar beynimde

sicakligin ellerimde

ama

en güzeli olan

askin

kalbimde.', 'Ismin dilimde hayalin gözümde hatiralar beynimde sicakligin ellerimde ama en güzeli olan askin kalbimde....', ARRAY['Türk Edebiyatı','Şiir','Şair Karagözlüm']::text[], 8.5, '{"poet":"Şair Karagözlüm","poet_slug":"sair-karagozlum","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kalbimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazen..', 'bazen-sair-karagozlum-3g2m9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bazen seni özlüyorum

Bazen senden nefret ediyorum

Bazen varligini ariyorum

Bazen sana kiziyorum

Bazen haline gülüyorum

Bazen yoklugun yüzünden agliyorum

Bazen seninle hayal kuruyorum

Bazende..

bazende......   aslinda kendime aciyorum

cünki

seni seviyorum.', 'Bazen seni özlüyorum Bazen senden nefret ediyorum Bazen varligini ariyorum Bazen sana kiziyorum Bazen haline gülüyorum Bazen yoklugun yüzünd...', ARRAY['Türk Edebiyatı','Şiir','Şair Karagözlüm']::text[], 8.5, '{"poet":"Şair Karagözlüm","poet_slug":"sair-karagozlum","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bazen-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alın Yazım', 'alin-yazim-sair-karagozlum-147hv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geceleri rüyalarima giren

bana gizli haber gönderen

''Seni seviyorum'' diyemeyen

olanlardan habersiz Alin yazim.

Beni görünce konusmayan

uzaktan selam veren

hayalimdeki onu canlandaran

olanlardan habersiz Alin yazim.

Sana olan sevgimden anlamayan

ayni duygulari yasayip anlatmayan

ayni rüyalarda dolasan

olanlardan habersiz Alin yazim.

Ben her kismeti tepen

senin hayalinle yasayan

sen beni görünce gülümseyen

olanlardan habersiz Alin yazim.', 'Geceleri rüyalarima giren bana gizli haber gönderen ''Seni seviyorum'' diyemeyen olanlardan habersiz Alin yazim. Beni görünce konusmayan uzakt...', ARRAY['Türk Edebiyatı','Şiir','Şair Karagözlüm']::text[], 8.5, '{"poet":"Şair Karagözlüm","poet_slug":"sair-karagozlum","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/alin-yazim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşler Yağmuru Bekliyor', 'dusler-yagmuru-bekliyor-ceyhun-kuburlu-9v0le', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bırak git artık beni kendi halime

Ne kadar üzülsem de

Yalnız kalsam da bu şehirde

Bizi bilirsin 

Sevdamızı harmanlamasını biliriz yüreğimizde

Hadi bırak beni kendi halime

Unut demiyorum 

Biliyorum ne kadar kaçsan da

Başka kimliklere 

Unutamayız ikimizde

Ama gitmelisin ve yeni yaşamındaki 

Şehre alışmalısın bensiz ve başkasıyla

Arada bir de olsa bir merhabayı esirgemelisin benden

Bir merhaba umudun filizi oluyor mevsimde

Sormamalısın beni eşe dosta

Başın öne de eyik olmamalı

Gülmelisin gittiğin gün gibi

Gülmelisin ve ağlamalısın gamzelerinin yalanlığına

Hadi git 

Düşlerimiz buğulu camlardan silinir yağmurda

Unut hepsini; unutamasan da

Nasılsa isimsizdi aşkımız

Hiçbir kayda rastlayamazsın hayatta

Hadi git artık

Hayatımız dağınık kalsın

Yarın gece ben uğrarım yine

Toplama yatağımı

Alışmalıyım sensizliğe

Telefonu beklememeliyim gece yarılarına kadar

Sesini duymadan korkamadan 

Uyumaya alışmalıyım tek başıma

Git ama kendini bırak odamın bir köşesine

Özlememeliyim seni 

Özlersem ararım 

Özlersem kölen olurum

Özlersem yenilirim yalnızlığıma...

Artık kimliksiz çıkmalıyım gece vardiyalarına

Yorgunluktan sızmalıyım 

Seni düşünecek hiçbir güzelliğim olmamalı hayatta

Git, git artık 

Ama sen yinede bir merhabayı esirgeme

Bu mevsim o mevsim 

Gitmelisin sevecek hiçbir baharı yaşamadan git

Elveda sevgili...

Bu gece tüm düşler yağmuru bekleyecek unutma; 

Unutma...

Kasım 2002

İstanbul (Cihangir Meydanı)', 'Bırak git artık beni kendi halime Ne kadar üzülsem de Yalnız kalsam da bu şehirde Bizi bilirsin  Sevdamızı harmanlamasını biliriz yüreğimizd...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Kuburlu']::text[], 8.5, '{"poet":"Ceyhun Kuburlu","poet_slug":"ceyhun-kuburlu","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/dusler-yagmuru-bekliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda dedikleri bir pınar', 'sevda-dedikleri-bir-pinar-salih-ozalasan-8k98a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevda dedikleri gönülde bir pınar

Pınardan su içersin yüreğin yanar

Çağlayıp akar dinlemez önünde engel

Bir kapılmaya gör bak sana neler yapar

Kendini bulursun denizler ortasında

Rotasını kaybetmiş kaptansız bir gemi misali

Sevda rüzgarı coşkun dalgalarla

Limandan limana sürükler seni

Beklersin bir yolcu binsin gemine

Oda katılsın istersin sevgi seline

Hele birde yakalanırsan karayeline

Yelkende bulamassın inanki gemine

Kapılıp gidersin rüzgarın estiği yöne

Çağlayan pınarda bir ateş yanarki

Bekleyesinki gözyaşınla söne

Sevda dedikleri gönülde bir pınarya

O pınar bazen dönüşür bir göle

Sevgine bulamassan birde karşılık

Deniz ortasında düşersin bir çöle

Kalbin olur zalim bir bedevi

Sende ona olursun ömür boyu köle

Y.Tar.13-11-2002 Saat 21.38', 'Sevda dedikleri gönülde bir pınar Pınardan su içersin yüreğin yanar Çağlayıp akar dinlemez önünde engel Bir kapılmaya gör bak sana neler yap...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevda-dedikleri-bir-pinar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Aşk', 'ask-mustafa-engin-karatay-jonhg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşk denilen bu illet; ne kânun, kural tanır, 

Ne hüküm fermân dinler; ne arlanır, utanır... 

Dâvetsiz kapı çalar; zannetme ki usanır! .. 

Girdimi bir gönüle, nasıl yakar kavurur 

Perme-perişân eder, küller gibi savurur 

*Önüne geçmek* diye, deyim icâd bulmamış 

Bir tutulan, bir daha aslâ iflâh olmamış 

Göster! Hangi filinta, sâm-u zebûn solmamış? 

Yağız delikanlı mı, yiğit mi, demez vurur 

Şâh''a pençe taktımı, tâc-ı saltanât kurur 

Çökmesin bir yüreğe; inletir, süründürür 

Velî''yi deli eyler, Kırk hâle büründürür 

Tanınmaz mecâl verir, yek-pervâne döndürür 

Ne şeref, izzet kalır; ne de bırakır gurûr 

Deldirir Ferhât gibi, önünde dağ mı durur?', 'Aşk denilen bu illet; ne kânun, kural tanır,  Ne hüküm fermân dinler; ne arlanır, utanır...  Dâvetsiz kapı çalar; zannetme ki usanır! ..  Gi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ask-112-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Güzel', 'en-guzel-bahadir-atay-k2vd3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dünyadaki en güzel şiiri yazmak isterdim, 

Ama biliyorum hiç bir zaman yazılamayacak.

Dünyadaki en güzel şarkıyı söylemek isterdim

Bağıra bağıra, umursamazcasına, 

Ama biliyorum o da bestelenemeyecek.

En güzel günümü yaşayamadan öleceğim belki, 

En kötü günlerimi de, 

Ve en güzel saatlerim sadece bir hayal olarak kalacak.

En sıkıcıları da kötü bir rüya.

Belki de dünyanın en güzel halini,

Ya da en kötüsünü göremeyeceğim, 

Siz, bu diyeceğime ne kızın, ne de gücenin.

Ama ben bu dünyadaki en güzel kızı sevdim.', 'Dünyadaki en güzel şiiri yazmak isterdim,  Ama biliyorum hiç bir zaman yazılamayacak. Dünyadaki en güzel şarkıyı söylemek isterdim Bağıra ba...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Atay']::text[], 8.5, '{"poet":"Bahadır Atay","poet_slug":"bahadir-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/en-guzel-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzsüzler', 'yuzsuzler-bahadir-atay-jhmxw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bazı insanlar vardır, yüzsüz, 

Her sabah aynaya baktığımda 

Kızıyorum kendime, 

Aynı yüzsüzlere benziyorum diye, 

Onların da ağzı var benimde, 

Burnum da onlarınkine benziyor, 

Gözlerimin rengi farklı hiç değilse

Kulaklarım biraz küçük ama aynı şekilde, 

Olmaz yaşayamam ben artık böyle, 

İstemem olmasın benim de bir yüzüm, 

Benzemek istemiyorum ben yüzsüzlere.', 'Bazı insanlar vardır, yüzsüz,  Her sabah aynaya baktığımda  Kızıyorum kendime,  Aynı yüzsüzlere benziyorum diye,  Onların da ağzı var benimd...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Atay']::text[], 8.5, '{"poet":"Bahadır Atay","poet_slug":"bahadir-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yuzsuzler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-ugur-erbil-29r7x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni çok seviyorum

Öylesine bir sevgidir ki bu aşkım

Sensiz olamıyor dayanamıyorum

Sensizlik ölüm sensizlik ızdıraptır

Seni varlığınla seni her şeyinle seviyorum

Ben seni çok seviyorum

Seninle bambaşkayım seninle bir bütünüm

Sensiz kalırsam inan ki gülüm üzülürüm

O kadar yakın hissediyorum ki seni bana 

Sen eşi bulunmayansın çölde aranan su gibi

Bu yüzden seni çok seviyorum

Sen, sen şefkat dolu birisin ki o kadar güzelsin ki

Sana bakmaya kıyamıyorum seni seviyorum

Sen benim kalbimin derinlerinde tahta sahipsin

Sen benim hayatımda tek ve biricik aşkımsın

Seni çok seviyorum

Ben hayatımda bu kadar sevmemiştim kimseyi

Seni sevdiğim sana taptığım kadar sevgilim

Ben hiç kimseye sana yazdığım kadar sevgilim

Adına şarkı, şiir yazdığımı hatırlamıyorum 

Ben seni çok seviyorum

Sen Ay’ın yanına yaklaşmış parlak yıldız

Sen Dünyaya Güneş’in yansıması gibi güzel

Gözlerin yıldızlar gibi ışıldak ve çekici

Saçların Ateş sarısı gibi parlak sen bir meleksin

Ben  seni çok seviyorum

Aklımdasın gece gündüz rüyamdasın uykusuz

Kalbimdeki taht sahibi bir kraliçesin sen

Gözümün daldığı derinliklerde hayalimsin

Ama şimdi çok yakınımda hayat arkadaşımsın 

Ben seni çok seviyorum...', 'Seni çok seviyorum Öylesine bir sevgidir ki bu aşkım Sensiz olamıyor dayanamıyorum Sensizlik ölüm sensizlik ızdıraptır Seni varlığınla seni ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Erbil']::text[], 8.5, '{"poet":"Uğur Erbil","poet_slug":"ugur-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/seni-seviyorum-95-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güller ve eşkıyalar', 'guller-ve-eskiyalar-rabia-can-ulas-a0ar8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'güller ve eşkıyalar

ne güllere inandım nede eşkıyalara

askerlerse zaten hep bir ordunun emrindeydi, 

donanımsızlıklarına inat

kanayan dikenli tellerdi

düşlerimdeki yalazı tandır ateşleri kavruk tenlerinde yansıyan

baskın yemiş evimiz aranan eşkıyalardı

parçalanan uykularımda

kimsenin bilmediği bir şey vardı

kendimden bile sakladığım, yüzümde hep parıldayan

kaçakların saklandığı uykularımı koruyan

çocuktum..

gülleri ve eşkıyaları

böylesine umarsızca kollayan

annemi belinde saklı silahlarla

paylaşan..

yıllar sonra anladım, 

hüzne örttükçe kapılarımı

sesimdeki kuşlarda azalan

ve parıltısını kadınların gözlerinde unutan

çocuktum..

mendilini her ayrılıkta kanatan..

ve dikenlerimi ayırdıkça tenimden 

yerleri bir bir yaralanan

güllere inançsız..

çocuktum..

soylu karanfiller gibi genzimi yakan..

ve dört  kitaba suskun..

yüreğinin aynasındaki aksini

kendi kanıyla boğan

çocuktum..

her akşam kendi ölümünü tasarlayan..

öyle olmayacağını bile bile..', 'güller ve eşkıyalar ne güllere inandım nede eşkıyalara askerlerse zaten hep bir ordunun emrindeydi,  donanımsızlıklarına inat kanayan dikenl...', ARRAY['Türk Edebiyatı','Şiir','Rabia Can Ulaş']::text[], 8.5, '{"poet":"Rabia Can Ulaş","poet_slug":"rabia-can-ulas","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/guller-ve-eskiyalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle Bana Usta', 'soyle-bana-usta-hamdi-topcu-cph8b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Söyle bana usta

Kim bezedi şimdiye dek, 

Bir tek renkle bir tuvali

Kim sever koyu karanlığını gecenin

Ufku kucaklayan gökkuşağı

Ki tacında yedi renk

Yedi sevda iç içe demek değil mi? 

Söyle bana usta

Kim söyledi şimdiye dek, 

Bir tek sesle bir şarkıyı

Kim sever yüreklerimizi ürperten sirenleri

Ki kuşlar muştular getirir

Şarkılarında yedi ses

Yedi sevda iç içe demek değil mi? 

Söyle bana usta 

Kim öğrendi şimdiye dek, 

Bir tek günde dostluğu, kardeşliği

Kim sever güneşsiz bir sabahı

Ki o yeryüzüne hayat verir

Yedi günle anılır zaman

Yedi sevda iç içe demek değil mi? 

Söyle bana usta

Kim yazdı şimdiye dek

Bir tek harfle bir şiiri

Kim sığdırabilir tek kitaba geçmişi, geleceği

Ki şavkır dilim barışın aydınlığında

Ve ağlar karanlıklarına savaşların

Bazen sur üflerim Alp dağlarında

Bazen çöllerde sağnak sağnak yağmur

Köküm Anadolu, dallarım  dünya

Gün gelince yedi kapılı şehirlerden çıkıp

Yedi deryaları yine ben geçmeyecek miyim?', 'Söyle bana usta Kim bezedi şimdiye dek,  Bir tek renkle bir tuvali Kim sever koyu karanlığını gecenin Ufku kucaklayan gökkuşağı Ki tacında y...', ARRAY['Türk Edebiyatı','Şiir','Hamdi Topçu']::text[], 8.5, '{"poet":"Hamdi Topçu","poet_slug":"hamdi-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/soyle-bana-usta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anvers Limanında', 'anvers-limaninda-hamdi-topcu-8rjhg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Orda limanın arka sokaklarında

Tüller gemiciler ve meyhaneler

Dünden çok, yarın da tekil

Ter ve tuz

Ve şarap tadında korsan hikayeleri

Orda limanın arka sokaklarında

Köşe başlarında kandil, 

Nar içi odalarda gül dövmeli çocuklar

Lir çalarken çiçek kayığında Çinli; 

Sütbeyaz kazak örer kendisine zenci

Ve haftalar süren vardiyalardan

Ceplerinde solgun aile resimleri

Ağır ellerinde okyanuslar

Sakal yağmurları sökün eder

Bu liman bir pir-i mugan caanım

Bu denizler sevgilisiz albüm

Merhaba derken rıhtımlara kaptan

Pıır eder

Gotik kilise kulelerinden

Metruk meyhanelerden

Martı bulutu, güvercin yağmuru

Zenci, çekik gözlü, sarışın...

Çanlar çalar, liman uyur, 

Köprüler açılır, masalar kurulur

Orda, kuşlar yuvalarında sessiz

Düşler doklarda çığlık çığlığa vurulur

Orda limanın arka sokaklarında

Beynimde teori zincirleri

Belleğimde pratikler

Hece hece tütsülerken geceyi özlem

Yalnızlıklarla kuşatıyor

Çılgınlıklarımı gerçekler

Orda limanın arka sokaklarında

Akordeon çalan doğuştan âmâ adam, 

Yani ben

Gülü sesinden severken

Gökçe sabahlar bağışlıyor rüzgâr

Demir tarıyor yüreğimde tüm gemiler', 'Orda limanın arka sokaklarında Tüller gemiciler ve meyhaneler Dünden çok, yarın da tekil Ter ve tuz Ve şarap tadında korsan hikayeleri Orda ...', ARRAY['Türk Edebiyatı','Şiir','Hamdi Topçu']::text[], 8.5, '{"poet":"Hamdi Topçu","poet_slug":"hamdi-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/anvers-limaninda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konuş Benimle', 'konus-benimle-hamdi-topcu-77ksi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'O kavşaklarında haylaz ıslıkların

Tarandım ve güllendim

Tenimde mersin kokusu

Ağzımda çağla tadı

Duruldu serpilişim

Konuş benimle

Güneşim ol ilkyaz bahçelerimde

Ay ışığım körfez körfez

Kuzey gecelerimde sonsuz

Kar açıyor ağaçlar

Ve kuşlar selamsız sabahsız

Geçip gidiyor denizaşırı

Yalnız, yorgun, içedönük

Çığlık çığlığa suskunluklarım

Konuş benimle

Konuş benimle

Unutulmuş giz

Suyu çekilmiş ırmaklar gibi

O yalan gülüşlerin çırağı

Ve ustası acıların

Ve kıyıcığında sevmelerin

Ve sevilmelerin ardıl

Ve İzmir aydınlığı

Ve yüreğimi ayartan imbat

Dilimi özledim

Konuş benimle', 'O kavşaklarında haylaz ıslıkların Tarandım ve güllendim Tenimde mersin kokusu Ağzımda çağla tadı Duruldu serpilişim Konuş benimle Güneşim ol...', ARRAY['Türk Edebiyatı','Şiir','Hamdi Topçu']::text[], 8.5, '{"poet":"Hamdi Topçu","poet_slug":"hamdi-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/konus-benimle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim Su Başı Durak', 'kalbim-su-basi-durak-hamdi-topcu-lv1d5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mevrow  Marie Claer-leonard  Roziers’e



Su başında durmuş, 

Yolcular uzaklardan, bakışları kısa

Durak, 

Soluklanmaya ayrılmış, dingin

Sırçasının altında –ip durur  sır.

Durmuşlar ruhlara santur  indirmeye

Çingeneler, yörükler, nomadlar, bedeviler...

Bir  şaman beklerken masallardan, 

Bir ana çıkagelmiş

Ömrü, gökkuşağına adanmış zaman.

Su başına vardım ben de, 

Diz çöktüm, avuçlarımı toprağa yaslayıp

Suda yüzünü aradım

Yüreğini gördüm

Su olup akan...

Kim denizine ulaşır, 

Kim kurur yatağını bulamadan...

Uzun adlar nesidir ömrümüzün

Su başlarına konmadan

Durmuşsam söze

Beklemeli   Limburg

Hasat zamanları  sevgi  sözcükleri  derlemeye

Hem suyum, hem su başı, hem durak

Kavşağıma  insan kokulu  ırmaklar akar  hâlâ.', 'Mevrow  Marie Claer-leonard  Roziers’e Su başında durmuş,  Yolcular uzaklardan, bakışları kısa Durak,  Soluklanmaya ayrılmış, dingin Sırçası...', ARRAY['Türk Edebiyatı','Şiir','Hamdi Topçu']::text[], 8.5, '{"poet":"Hamdi Topçu","poet_slug":"hamdi-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kalbim-su-basi-durak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Narinna Rinna Ninanay Nay', 'narinna-rinna-ninanay-nay-hamdi-topcu-8y8y4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Başka bir gün geliniz

Başkaları  filizlendiğinde  içinizde

Size ada çayı demlerim

Sakız ağaçlarının gölgesinde

Ben fesleğen  kokulu saba söylerim, 

Siz nar renkli hüzzama eşlik edersiniz...

                                 Narinna rinna ninanay nay

Güneş altın tepsiyle dönüyorsa 

Yazdır; haziran ya da temmuz 

Dilim  esriktir, sözcem  mahmur, 

Doğurur adalarını yeniden Ege

Adalarda bekleyiniz

Yalıyarlarda martı  bayramları başlar

Öptükçe kumsalı tuz, hayatı selamlarız...

Hayat  sevgiyle  akran...

                               Narinna rinna ninanay nay

Çekirdeksiz üzüm gözlerinizde 

Yanık  dağlar mavisiyim

Suskunsam, su olup çağıldayınız

Görmemişsem, kuruntularınızdan arınıp 

Yetmiş iki renginizle geliniz

Ölürsem, 

Aşksız kentlere yolum düşer korkumdandır 

Hakkımdır, şahdamarımda uyumak  ey! 

                            Narinna rinna  ninanay  nay', 'Başka bir gün geliniz Başkaları  filizlendiğinde  içinizde Size ada çayı demlerim Sakız ağaçlarının gölgesinde Ben fesleğen  kokulu saba söy...', ARRAY['Türk Edebiyatı','Şiir','Hamdi Topçu']::text[], 8.5, '{"poet":"Hamdi Topçu","poet_slug":"hamdi-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/narinna-rinna-ninanay-nay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek', 'dilek-gursel-colak-a4u7a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sağ elime Güneşi

Sol elime Ay'' ı verebilseler

Ben genede istemem.

Tek dileğim, senin mutluluğun.

Dilerim Güneş hiç batmasın

Gözlerin hiç kapanmasın

O tertemiz olan kalbin

Keder ve hüzün tatmasın.

Dilerim ALLAH'' tan 

Her gün gülsün yüzün

Sevgi ile dolu olan gönlün

Ne dert görsün, nede hüzün.', 'Sağ elime Güneşi Sol elime Ay'' ı verebilseler Ben genede istemem. Tek dileğim, senin mutluluğun. Dilerim Güneş hiç batmasın Gözlerin hiç kap...', ARRAY['Türk Edebiyatı','Şiir','Gürsel Çolak']::text[], 8.5, '{"poet":"Gürsel Çolak","poet_slug":"gursel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dilek-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Bu, Ne Dinmez Fırtına?', 'bu-ne-dinmez-firtina-mustafa-engin-karatay-0uv10', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zamânın akışına, ayak uydurmak zormuş

Hebâ olan ömrümde, zihnimi, kalbim yormuş

Bir vicdân yoksununa, vicdânım neler sormuş? ..

Şimdi her şey nâfile, tahribâtlar onulmaz

Uymayan kalıplara, hür insâfım konulmaz

Zamânlamam mı yanlış, geliş-varış yönümde? 

Efkâr adlı denizi, geçemedim önümde

Sâdece bir tek sabâh, olur muyum günümde? 

Keşmekeş deryâsında, bu ne dinmez fırtına? 

Ne giriftler yüklenmiş, bir çârenin sırtına...

Tuhaflıklar var ama, aceb sâde bende mi? 

Kolsuz entârimizde, İki kol bir yende mi? 

Mahkûmluk rûhumda mı, can taşıyan tende mi? 

Kavîleşmiş, devrilmez; sille ile yıkılmaz! ..

Ecel kapımı çalsa; yok, içinden çıkılmaz! ..

09.04.2001   Dr. Lohscheidt / Landsberg   16: 35', 'Zamânın akışına, ayak uydurmak zormuş Hebâ olan ömrümde, zihnimi, kalbim yormuş Bir vicdân yoksununa, vicdânım neler sormuş? .. Şimdi her şe...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-ne-dinmez-firtina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susuz Ceylan', 'susuz-ceylan-yetik-ozan-as3lw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gül yüzünde gülücükler görende 

Bir sevdalı bülbül uçar bağrımdan, 

Yüreğim çırpınır selam verende; 

Sanki bir ciylan su içer bağrımdan 

Harami, gözünü cana döndürmüş, 

Düz giden yolları yana döndürmüş, 

Beni bir uğursuz hana döndürmüş; 

Bin dert konar, bin dert göçer bağrımdan. 

Koklayıp geçmiş de bir sarı ölüm 

Toz pembe çağında kurumuş gülüm, 

Gayri bir gölgesiz, sınırsız çölüm 

En mecnun emeller geçer bağrımdan', 'Gül yüzünde gülücükler görende  Bir sevdalı bülbül uçar bağrımdan,  Yüreğim çırpınır selam verende;  Sanki bir ciylan su içer bağrımdan  Har...', ARRAY['Türk Edebiyatı','Şiir','Yetik Ozan']::text[], 8.5, '{"poet":"Yetik Ozan","poet_slug":"yetik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/susuz-ceylan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağustos', 'agustos-yetik-ozan-lkd2s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kurşun derelerin sustuğu çağdır; 

Susuzluk çağıldar taşlar katında, 

Yeşilin kendini astığı çağdır

Uzak çamlar, sürgün kuşlar katında.

Gün yürür; dağ, yazı gölgeye girer, 

Öfkeli başaklar dalgaya girer, 

Anılar birer tunç tolgaya girer; 

Zafer bayraklaşır başlar katında.

Gün döner; gündöndü yere serilir, 

Bir saz burgulanır, bir tel gerilir, 

Her akşam bir ölü oğul dirilir

Ana gözündeki yaşlar katında.

Ay doğar; bin yıllık bir denk çözülür, 

Aynı tasta aynı kına ezilir, 

Hala körpe gelin gibi süzülür

Ağustos ölümsüz düşler katında.', 'Kurşun derelerin sustuğu çağdır;  Susuzluk çağıldar taşlar katında,  Yeşilin kendini astığı çağdır Uzak çamlar, sürgün kuşlar katında. Gün y...', ARRAY['Türk Edebiyatı','Şiir','Yetik Ozan']::text[], 8.5, '{"poet":"Yetik Ozan","poet_slug":"yetik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/agustos-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter', 'yeter-said-alpagut-senel-6zd87', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bekledim yıllardır gelirsin diye

Uzaktan uzağa sevdiğin yeter

Birgün gelip benim olursun diye

Halime bakıp ta güldüğün yeter

Sevemedim senden başka birini

Tutamadı kimse senin yerini

Gel artık ne olur ağlatma beni

Seni yokluğunda bulduğum yeter

Aşık Hoyrat ayrı düştü gülünden

Adın düşmez oldu inan dilimden

Gerçekte de bir kez tutsam elinden

Her gece düşümde sardığım yeter', 'Bekledim yıllardır gelirsin diye Uzaktan uzağa sevdiğin yeter Birgün gelip benim olursun diye Halime bakıp ta güldüğün yeter Sevemedim sende...', ARRAY['Türk Edebiyatı','Şiir','Said Alpagut Şenel']::text[], 8.5, '{"poet":"Said Alpagut Şenel","poet_slug":"said-alpagut-senel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yeter-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı Çekme Hürriyeti', 'aci-cekme-hurriyeti-gulcihan-atalay-n1dzc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne gül dalı inceliğim

Ne çocuksu dalgınlığım

İstanbul 

Hovarda oğlum benim

Canımda çığlık gibi duran.

Hüznünü tenimde buram buram

Taşıdığım kızkardeşim

Her gelişinde bir daha vuran

Sevda yollarında kara trenim

Bir koca kazandır ki

İçinde kaynar durur yüreğim…

Düş bozgunu,  serüven yitiği

Kan kınası sevdam benim

İstanbul! 

Tel örgüler saçlarında

Prangalarda hasretim 

Yüreğim avuçlarında 

Hüznümse servetim

Cehennemim

Cennetim…

O şehr-i şahane ki 

Acı çekme hürriyetim!', 'Ne gül dalı inceliğim Ne çocuksu dalgınlığım İstanbul  Hovarda oğlum benim Canımda çığlık gibi duran. Hüznünü tenimde buram buram Taşıdığım ...', ARRAY['Türk Edebiyatı','Şiir','Gülcihan Atalay']::text[], 8.5, '{"poet":"Gülcihan Atalay","poet_slug":"gulcihan-atalay","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/aci-cekme-hurriyeti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Prangalar', 'prangalar-kemal-burkay-q49jn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben ki yalnızca sevmek isterdim 

Sizi, kırları, yaz akşamlarını 

Bir kadın eli gibi geçsin 

İsterdim saçlarımdan rüzgâr 

Bir Hasan var orda dağ köylerinde 

Daha hiç okşanmamış 

Bir Elif var saçları taranmamış 

Trahomsuz büyüsünler isterdim 

Öyleyse nedir bu prangalar 

Ben kimin ağlamasını istedim ki 

Yok ki benim kurşunlarım 

Dikenli tellerim, taş duvarlarım yok ki 

Bir türkü söylerim güneş vardır içinde 

Alınteri, toprak ve hayat 

Beni elleriniz ilgilendirirdi 

Gözleriniz, o hilesiz ve dost 

Öyleyse nedir bu prangalar 

Çocukları kılıçlara büyütmeyelim 

Çocukları ağlamaya büyütmeyelim 

Ağaçları küstürmeyelim kendimizden 

Bombaları çoğaltmasak sevinçler çoğalırdı 

Kinleri bilemesek ne güzel gülümserdik 

İstesek bölüşürdük doğan günü 

Birleşirdi ellerimiz ve türkülerimiz 

İstesek bölüşürdük bir dilim ekmeği 

Ama ne çoğalırdı yaprakların sevinci 

Ne mutlu büyürdü çocuklar 

Ben sizden bir maviyi gizledim mi 

Hangi denizleri kaçırdım sizden 

Hangi yağmuru, çiğ tanelerini 

Size şiirler getirirdim, nisan aylarını 

Yalnızlığımı getirirdim ısınmanız için 

Öyleyse nedir bu prangalar 

Ben kimin ağlamasını istedim ki 

Yok ki benim kurşunlarım 

Dikenli tellerim, taş duvarlarım yok ki', 'Ben ki yalnızca sevmek isterdim  Sizi, kırları, yaz akşamlarını  Bir kadın eli gibi geçsin  İsterdim saçlarımdan rüzgâr  Bir Hasan var orda ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Burkay']::text[], 8.5, '{"poet":"Kemal Burkay","poet_slug":"kemal-burkay","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/prangalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden', 'neden-said-alpagut-senel-887el', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey sevdiğim söyle sana ne diyem? 

Soldurdun bahçemde güllerü neden? 

Başka bakar oldu yeşil gözlerin

İnlettin sazımda telleri neden? 

Sevdim seni güzel sevdim neyleyim? 

Şu sensiz gönlümü nasıl eğleyim? 

Dosta düşmana ben neler söyleyim? 

Estirdin ayrılık yelleri neden? 

Ağlar iken gönlüm hep güler oldu

Yeşil gözlerinde mutluluk buldu

Şimdilerde seni ellerden sordu

Kattın aramıza elleri neden? 

Sensiz geçem günde gülemiyorum

Neden bu ayrılık bilemiyorum

Ölmek istedimde ölemiyorum

Susmaz Hoyrat''ımın dilleri neden?', 'Ey sevdiğim söyle sana ne diyem?  Soldurdun bahçemde güllerü neden?  Başka bakar oldu yeşil gözlerin İnlettin sazımda telleri neden?  Sevdim...', ARRAY['Türk Edebiyatı','Şiir','Said Alpagut Şenel']::text[], 8.5, '{"poet":"Said Alpagut Şenel","poet_slug":"said-alpagut-senel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/neden-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün', 'huzun-mustafa-demirci-2-11trz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine hüzünlendi deli gönlüm

Boşa koysam dolmuyor, dolu almıyor

Yollarım kapandı sanki gözüm görmüyor

Kahretsin kahretsin yine olmuyor

Bir zamanlar aynı ekmeği paylaşıyorduk

Boğazımıza tıkanan ekmek nasılda zor geçiyordu

Birbirimizin sırtına vurarak yutkunduk hep

Kahretsin kahretsin yine gülmüyor....

Geçen vakte bile aldırmadan dertleşirdik 

Sen hüznünü ben sevincimi anlatırdım

Gözyaşlarımızdan kirlenen yüzümüzü

Kahretsin kahretsin kimse görmüyor

Mustafa hani fani idi dünya

Hala ben yaşıyorum sende öyle

Kanayan gönlüme derman yok ki

Kahretsin kahretsin hekim sarmıyor', 'Yine hüzünlendi deli gönlüm Boşa koysam dolmuyor, dolu almıyor Yollarım kapandı sanki gözüm görmüyor Kahretsin kahretsin yine olmuyor Bir za...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Demirci 2']::text[], 8.5, '{"poet":"Mustafa Demirci 2","poet_slug":"mustafa-demirci-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/huzun-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Mevsimi', 'huzun-mevsimi-arkadas-zekai-ozger-wtkpw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gece 

bir tabut gibi çöker omuzlarıma 

bir ölünün iç çekmesi olur rüzgar 

hüzünle düşünürüm uzaktaki bir evi 

yıldızlar sayılmaz: hasret uzakta 

hasreti bir ben bilirim 

bir de gecenin gözlerindeki baykuş 

baykuş kötü kuş baykuş çirkin kuş 

onu hüznümle güzelleştiririm. hüznümle 

süsler. bir damın üstüne oturturum 

süsler. Damımın üstüne oturturum 

-sizi hiç bu kadar yakından görmedimdi 

yıldızlar sayılmaz: hasret uzakta 

abimin acıyla yontulmuş yüzü 

yaşlı bir güvercin gibi düşer avuçlarıma 

dağılır ses olur acısı 

ezberlediğim bir öğüdü yineler bana 

-çocuğum üşütme yüreğini 

şimdi hüzün mevsimidir bütün şiirleri gezen 

ben doğma büyüme evciyim göç benim harcım değil 

hasret bana çabuk dokunur yalnızken karanlıktan 

korkarım 

mesela mevsim kışsa yağmur yağıyorsa 

mesela annem de yoksa yanımda 

mesela, şimşek de çakıyorsa ben çok korkarım ağlarım 

-ana bana kurşun dök. dua oku. üfle ana 

ana ben daha çok küçüğüm. bana ninni söyle ana 

yalnızım. bunu hep söylüyorum 

yalnızım. bunu hep söylüyorum 

geceyi çarmıha geriyorum kimseler tapmıyor 

hüznümü ölçeğe vuruyorum yüreğine sığmıyor 

her şey ne kadar olabilir meraklanıyorum 

yüzüme dokundukça tırnaklarım kanıyor 

yalnızlığımı hüznümle yoğuran gece 

öyle basitsin ki sen bütün şiirlerin içinde 

biliyorum. biliyorum bunu da biliyorum 

gökteki yıldızlar kadar dizeler yazılsa da 

kendime kendimden başka kendim yok 

ne utancımı kuşanan bir sevgi 

ne çirkinliğimi öpen bir kız 

yalnızlığımdan yalnızlığım yalnız 

-ana bana bir hal oldu. hep böyle titriyorum 

ana çok üşüyorum, ıhlamur ısıt bana 

yıldızlar sayılmaz: hasret uzakta 

ben sevgiye hasretim, sevgi uzakta 

ey insanlar 

ey gecede unutulmuşluğumun yargıçları 

iğrenerek öpüyorum parmaklarınızı 

iğrenerek. hepinizi kucaklıyorum ilkin 

ağzınızı dudaklarınızı dişlerinizi öpüyorum 

bilmiyorsunuz. ben kendimi öpüyorum 

cinsel bir çiftleşmedir çarşaflar 

ıslak bir gece en fazla kendini çoğaltır 

bir solucan vücuduna yeni bir halka ekler 

döllenir acı. sevişme daha da erselikleşir 

-hü''yü tanıdım size anlatmalıyım bir gün 

size bir gün mutlaka hü''yü anlatmalıyım 

geceyse 

tükenmişse güneşin güçlülüğü 

gök gözlerinin buğusunu yansıtır 

senin acın acıların ölümüne gebedir 

korkma yavrum 

ne gece ne geceler senin 

suçsuz mızıkçılığını küçültemez 

bir çirkini öpmek için uzattığın yüreğini 

güzelleşip bir sevginin göğsüne yatmak biraz 

biraz yorgun biraz korkak bir insan sevmek biraz 

dayayıp sırtını gecenin duvarına 

bir ölünün ağzını dudağını öpmek biraz 

yıldızlar sayılmaz: hasret uzakta 

ben sevgiye hasretim, sevgi uzakta 

ey kanımda tefler çalan mevsimle gelen 

sesimi çakallarla boğan gece 

hüznüme vur acımı soy 

beni de kuşat 

boris karlof kadar masum yüzümü 

karanlığınla frenkeştaynla 

çünkü artık büyütmeliyim içimde nefreti 

kalbim ki yıllardır iyiliğe abone 

nerde bir insan görse 

bırakır sevgi kuşlarını 

çünkü o bağışlar yargıçlarını 

kendi yasalarını kuramıyan yargıçlarını 

ey gecede unutulmuşluğumun suçluları 

ey yanlışlığımın yanlış yargılayıcıları 

suçum: nefreti öksüz bırakmak 

savunmam: sevgimi yüceltmek içindir 

sakalım yok biliyorum ama kötü değilim 

büyükleri sayarım küçükleri severim 

çocukları incitmeden severim. kadını öpmesini 

bilirim 

sizi de sizi de öpmesini bilirim 

-ana ben çok yalnızım. benim başka sevgim yok 

içimde utanç çiçeği gibi büyüyor hü 

kural tanımayan sevgim benim 

aykırım fizikötem doğaüstüm yanlışlığım 

aşkım. sevgili yanılgım benim başyargıcım 

nefretim nefretim nerdesin 

kalbim 

bir gün elbette sana hükmedeceğim 

elbet geçer bu hüzün mevsimi 

bir baykuş bir serçeyle arkadaş olduğu gün 

o gün size sevinci de anlatıcam 

bir solucan bir leylekle çiftleştiği gün 

o gün bahar mevsimidir size aşkı anlatacağım 

ve bir gün elbette yıldızları sayacağım 

-gelin kucaklayın beni. yıldızları sayamıyorum.', 'Gece  bir tabut gibi çöker omuzlarıma  bir ölünün iç çekmesi olur rüzgar  hüzünle düşünürüm uzaktaki bir evi  yıldızlar sayılmaz: hasret uza...', ARRAY['Türk Edebiyatı','Şiir','Arkadaş Zekai Özger']::text[], 8.5, '{"poet":"Arkadaş Zekai Özger","poet_slug":"arkadas-zekai-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":107,"source_url":"https://www.antoloji.com/huzun-mevsimi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gezgin', 'gezgin-arkadas-zekai-ozger-hgcss', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'dün geldim

geç kalsam da bağışlanır

bir bahar bozumuydu yola çıktığımda

yüzümde suçlu bir merak

kalbim heyecandan telaşlı

gözlerimde ısırgan bir hüzün vardı

hüzün: hep bilinir

bir afyon çiçeğidir önceleri

dalayan bir ısırgan yoncası olur sonra

dalayan ve uyandıran o afyon uykusundan

dün geldim

acı sırtımda tabiy

yolum uzundu

yanımda hiç resim yoktu

dağlara baktım: dağıldım

yollara baktım: yoruldum

gece ayışığı içtim, dudaklarım kurudu

gündüz böğürtlen yedim, dilim buğulandı

siz görmeliydiniz o kanı

bir dağ çiçeği sevdasına bin arı öldü

tam ordan geçiyordum, gördüm diyebilirim

aman nasıl petekti öyle

nasıl baldı

böğürtlen gibi kırmızıydı

kan gibi saydam

bir garip kokuydu, onun kokusuydu

dayanamadım, eli titrekti ama

yedim yedim kalbim çatladı

sevdam o dağ çiçeğinde kaldı

dün geldim, anca geldim

usumda vızıldayan bin arı ölüsü

heybemde onarımı gereken bin iğne

önce kendi etime

dün geldim

hoş mu geldim

hoş olmayan şeylerden geldim

bir kentten geçtim ki canım titredi

sıtma kabusuyla sallanıyordu uzaktan

girişte insanlar gördüm, hiç görmediğim

ama sanki biryerlerden tanıdığım, yemin

edebilirim

iğrenç suratları vardı, insandan çok

cüzzamlı bir köpeğe benziyorlardı

kuru birer ağaç dibine çömelmiş

çürümüş bir dalı kemiriyorlardı

omuzlarında soyulmuş yılan derileri

ellerinde pas tutmuş makaslar

iki ucu da kırık

tam ben yanlarından geçiyorken

elma ağaçlarının çiçeklerini kesmeye başladılar

ben sanki tarihini bilmiyormuşum gibi

bakır çalığı bir kasede

elmanın kanını sundular

geldim ya, nasıl geldim

bir elimde tarih atlası

bir elimde güneş humması

soğutulmaya zorlanmış bir çöl kızgınlığından

bir kum fırtınasının

soylu kumcuklarından geldim

yorgundum, susamıştım, dilim kuruydu ama

gördüğüm serap mıydı, gerçek miydi

bilirim ben

çölün tam ortasında sonsuz bir ışıltıydı

yedibin rengi yansıtan renksiz bir kuyuydu

duruydu, aydınlıktı, yaz gökleri gibiydi suyu

uzanıp avuçlasam benimdi

öyle yakın, öyle kolay, öyle dokunsam

ah o kervancıbaşı

ah o sırmalı soyguncu

ve ellerinde kesik başlar ve zebellah ordusu

birden beliriverdiler tam kuyunun başında

ellerinde kan sızıtan kesik başları

tan kuyunun ağzından sarkıtıyorlardı ki

ne olduysa o anda oldu

kızıl bir bulut ağdı kuyunun ağzından göğe

bulut değil

bir devin alev saçan soluğuydu

ardından muhteşem bir kum fırtınası

kum değil

devin çocuklarıydı saçılan

ah görmeliydiniz o savaşı

ne kanlı kervancıbaşı

ne zebellah ordusu

dayanamadılar kum fırtınasının şiddetine

çöl mü yarıldı

kuyu mu büyüttü ağzını

kızgın çöl kavuşunca dinginliğine

bir ben vardım kuyunun başında diri

ve herşeyi görebilen sağlıklı çöl tanığı

öğrendim çöl kızgınsa öfkesi nice olur

kum fırtınasında neler yapılır

nasıl yok edilir çöllerin sırmalı

soygun kervancıları

gördüğüm serap mıydı, gerçek miydi

bilirim ben

bir elimde güneş humması

bir elimde tarih atlası vardı

vakit dardı

kanarak içtim de kuyunun duru suyundan

uçar gibi aştım çölü o sonsuz ışıltıdan

dün geldim 

dün ben nerden geldim

ezberlenip unutulmuş bir sıkıntıdan geldim

adı konulmamış bir düşten geldim

terlemiş balıklar gördüm, rengi bozulmuş mavilikler

kabaran denizler gibi coşkun sürücüler

kılçığı beynine saplanmış gözsüz balıklar gördüm

trollenmiş deniz tarlası, iyot vurgunu

derya içindeydim de hani deryayı gördüm

küçük balığı gördüm, peşinde büyük balık

bir su ağası gibi kuvvetli ve saldırgan

oh balık, küçük balık, can balık

anasının kuzusu, deniz kokulum

söyle yavrum, söyle gözüm, söyle kılçığım

kim dokundu senin pullanmamış derine

kim kıydı senin o tazecik gövdene

denizde kum gibi dolgun pullarıyla

doymaz mı büyük balık küçük balığa

ama gördüm ya sonunda

derya içindeki deryayı

büyük balık küçük balık peşindeydi ya

birleşince küçük balık yüzlercesiyle

şaşırıp kaldı büyük balık

şaşırıp kalmadım amma

ne de keskinleşmiş dişleri ol mahilerin

unutulmaz bir deniz anası gibi büyüdü gövdeleri

kıymık kıymık oldu gövdesi büyük balığın

anladım

nice olsa da

denizde kum, büyük balıkta pul

birleşince

edemezmiş küçükleri kendine kul

                              14 Mart 1972', 'dün geldim geç kalsam da bağışlanır bir bahar bozumuydu yola çıktığımda yüzümde suçlu bir merak kalbim heyecandan telaşlı gözlerimde ısırgan...', ARRAY['Türk Edebiyatı','Şiir','Arkadaş Zekai Özger']::text[], 8.5, '{"poet":"Arkadaş Zekai Özger","poet_slug":"arkadas-zekai-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":133,"source_url":"https://www.antoloji.com/gezgin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara''lı Dört Dörtlük', 'ankara-li-dort-dortluk-arkadas-zekai-ozger-t99x9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ankara vurulmuş bileklerime

dumanlı hava, kurt kapanı, 

ciğerparem

yaşayanlar unutmadı geçen kışı

dumanlı hava, kurt kapanı, 

ciğerparem

ilkyaz mı bu hani nerde Ankara

cılk yumurta akı, kına yakısı

sürgün hızı sürgün hızı yürektedir

kavuniçi buğday tanesi, yanık 

yarası

koş bire doru at koş bire doru at

sürgün hızı yüreğime tak eder

ben böyle Ankara''yı neyleyim

sürgün hızı yüreğime tak eder

doymadım doymadım adını 

anmağa

oy benim canımın canı canım

doymadan doymadan Ankara''ya

oy benim canımın canı canım', 'Ankara vurulmuş bileklerime dumanlı hava, kurt kapanı,  ciğerparem yaşayanlar unutmadı geçen kışı dumanlı hava, kurt kapanı,  ciğerparem ilk...', ARRAY['Türk Edebiyatı','Şiir','Arkadaş Zekai Özger']::text[], 8.5, '{"poet":"Arkadaş Zekai Özger","poet_slug":"arkadas-zekai-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ankara-li-dort-dortluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakalsız Bir Oğlanın Tragedyası', 'sakalsiz-bir-oglanin-tragedyasi-arkadas-zekai-ozger-1d3nw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'charles chaplin bir savaşta yitirdim sakalımı

çıkmazlığın grev sesi umutlarımı vururken

yendirdim bıyıklarımı papağan kuşkulara

biraz elma şekeriyle kazıdım sakalımı

lohusa şerbetiyle kazıdım sakalımı

yanaklarım paprika lahmacun ister misiniz

al işte sana böyle yüze böyle güz

demeyin deseniz de sakal yok ya ucunda

bu güz vermedi tarla seneye bıyık kerim

ben ettim siz etmeyin sakal veririm size

iğne iplik elimde bıyık dikerim size

yanaklarım taşlıtarla kurabiye yer misiniz

Sayın bayan dursanıza gözünüze kuş kaçmış

bu bıyık hiç gitmemiş sesinizin rengine

sakalınız uzamış inmiş ta belinize

at kuyruğu yapınız ya da örgüleyiniz

kedinizin bıyığını usturayla kesiniz

yanaklarım bileytaşı ispirto sever misiniz

yoksul ve utangaç bir müşteriyim ben

sizde güneş bulunur mu biraz/kaktüs alıcam

saksılarım yeşersin üç beş bulut verin de

çok üşüdü güneşten şizofreni olucak

çabuk olun lütfen dikenleri solucak

yanaklarım gobi çölü soğuk su içer misiniz

yüzüm eski bir artist yaşlandıkça shirley temple

elimde bir baş soğan bir baş sarımsak

ah ne kadar şakacısınız hiç hamlet oynamadınızmı

olmak ya da olmamak bütün sorun bu

yanaklarım yul bryner şimşir tarak istermisiniz', 'charles chaplin bir savaşta yitirdim sakalımı çıkmazlığın grev sesi umutlarımı vururken yendirdim bıyıklarımı papağan kuşkulara biraz elma ş...', ARRAY['Türk Edebiyatı','Şiir','Arkadaş Zekai Özger']::text[], 8.5, '{"poet":"Arkadaş Zekai Özger","poet_slug":"arkadas-zekai-ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sakalsiz-bir-oglanin-tragedyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Olmayan Aşk', 'adi-olmayan-ask-abdullah-taybogan-g8xrc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'söyle, kime sitem edeyim

dertlerimi, yaralarımı kime açayım

feryat figan düşüyor hep bana

bu derin yaraları nasıl kapayayım

isterdim ki benim de bir yarim olsun

güneşe benzer nazlı bir ay olsun

ona benzer biri dünyaya gelmemiş olsun

yaralı yürek onunla şad olsun

kaç yıl sonra bir yarim oldu

güneşe benzer nazlı bir aydı

ne ana, baba ne kardeş bırakmadı

göremediler yürekteki aşkı, eremedim murada

bir dağdım derdim ben asla düşmem

suyuydum Fırat''ın şimdiyse kurağım 

tüm aşkların adı var, Mem u Zin gibi

ben de aşığım neden yoktur adım

dert ve yaradır yazgıma yazılan

tanrıdan tek istediğim, sevdiğim ROJBİN

aşkın koyu karanlık zındanına düştüm

ben de senin kulunum neden ben ağlıyorum

istiyorum ki birbirimize kavuşalım

ateş ve duman oldum, senin için yanıyorum

güneşin ışığı gibi ateşlidir aşkım

kendim için yok önemi, senin için ölürüm', 'söyle, kime sitem edeyim dertlerimi, yaralarımı kime açayım feryat figan düşüyor hep bana bu derin yaraları nasıl kapayayım isterdim ki beni...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Tayboğan']::text[], 8.5, '{"poet":"Abdullah Tayboğan","poet_slug":"abdullah-taybogan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/adi-olmayan-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Manyakmısın Lan', 'manyakmisin-lan-mustafa-demirci-2-fai3i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güya kendini boğaz köprüsünden atacakmış

Sen manyakmısın aslanım

Sevdalı olduğunu herkes biliyor

Bizim manyak kendini yakacakmış

Bırak lan ellerini, düş aşağıya

Erkeksen bakma coşkun suya

Bir sürü polis molis başında

Güya kafasına kurşun sıkacakmış

Ulan senin neyine köprü üstüne çıkmak

Bir manyak karıya sarkıntılık yaparak aşık olmak

Kendine gel aslanım adam ol çalışarak

Hala bağırıyor hadi herif çıldıracakmış

Ulan hergele evde anan aç bacın aç

Sen seni tanımayana kaptırmışın kendini

Uyan bu manyak rüyadan gözlerini aç

İşin doğrusuda bu değilmi

Mustafa kızgın yine bugün

Değermi lan aslanım uğuruna öldüğün

Bırak koçum bu vicdan hesabını

Herkes kendi çiziyor sende çiz yasanı', 'Güya kendini boğaz köprüsünden atacakmış Sen manyakmısın aslanım Sevdalı olduğunu herkes biliyor Bizim manyak kendini yakacakmış Bırak lan e...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Demirci 2']::text[], 8.5, '{"poet":"Mustafa Demirci 2","poet_slug":"mustafa-demirci-2","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/manyakmisin-lan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ezîza min', 'ez-za-min-abdullah-taybogan-pvxtr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ezîza ber dilê min

çiqas min xweş dikir

bi stêrka navê te

dinivîsî li ezmana

bi pêlê bahrê 

min dinivîsi navê te

ser bahra wanê

ezîza min ezîza ber dilê min

bi hêstrê çâvê xwe

min dinivîsî

bi hêstrê câvê xwe', 'ezîza ber dilê min çiqas min xweş dikir bi stêrka navê te dinivîsî li ezmana bi pêlê bahrê  min dinivîsi navê te ser bahra wanê ezîza min ez...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Tayboğan']::text[], 8.5, '{"poet":"Abdullah Tayboğan","poet_slug":"abdullah-taybogan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/eziza-min-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pirozbe', 'pirozbe-abdullah-taybogan-qs6jg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dinyayê sê hebê go 

hes ji te bikin hebin

bizanib yek ji wan ezim

na go du heb hebin

disa yek jê ezim

belê go yek hebê

ew yek jî ezim

lê go tunebin

bizanib ez mrîme, ez mrîme

her tiştên wxeş 

li jî yana te pîroz be', 'dinyayê sê hebê go  hes ji te bikin hebin bizanib yek ji wan ezim na go du heb hebin disa yek jê ezim belê go yek hebê ew yek jî ezim lê go ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Tayboğan']::text[], 8.5, '{"poet":"Abdullah Tayboğan","poet_slug":"abdullah-taybogan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/pirozbe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ez Âlimîm', 'ez-lim-m-abdullah-taybogan-kelzp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ez ketim lê âlimîm rabunê

min dest agir dida

destê min dişewitî

şewat çiya min fahm dikir

âlimîm heskirinê, heskirinê

paşî te tenê dimam benda wê

piştî te ji bîra dibum 

min fahmkir 

her tişt min fahmkir û âlimîm

lê jibîrkirin min fahmnekir

û ne âlimîm Rojbîn...', 'ez ketim lê âlimîm rabunê min dest agir dida destê min dişewitî şewat çiya min fahm dikir âlimîm heskirinê, heskirinê paşî te tenê dimam ben...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Tayboğan']::text[], 8.5, '{"poet":"Abdullah Tayboğan","poet_slug":"abdullah-taybogan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ez-alimim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-i-smail-acarkan-jlspm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen kendi dünyanda hep varlığı yaşadın, 

Benim dünyamda ise ben bile yoktum. 

Sen hayatımın gözbebeğiydin, 

Bense gördüğümde gözlerini kapattığın biriyim.

Ben bir damlacık arzuda boğuldum, 

Sen arzuların okyanusunda  ayaklarını bile ıslatmadın, 

Sen tutunduğum tek daldın, 

Seninse köklerin bile gökteydi.

Sen bana doğru hiç koşmuyordun, 

Durduğun yere beni getiriyordun 

Sen görmediklerine de inanıyordun, 

Ben gördüklerimi bile yalanlıyordum.', 'Sen kendi dünyanda hep varlığı yaşadın,  Benim dünyamda ise ben bile yoktum.  Sen hayatımın gözbebeğiydin,  Bense gördüğümde gözlerini kapat...', ARRAY['Türk Edebiyatı','Şiir','İsmail Acarkan']::text[], 8.5, '{"poet":"İsmail Acarkan","poet_slug":"i-smail-acarkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-192-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlerim', 'ozlerim-mustafa-demirbas-95w0o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karanlık çöktü birden,  ruhum nuru arıyor.....

Aydınlığa muhtacım, görmez oldu gözlerim....

Sana giden tüm yollar, bedenimi sarıyor.....

Seni her an görürüm, ama yine özlerim......:', 'Karanlık çöktü birden,  ruhum nuru arıyor..... Aydınlığa muhtacım, görmez oldu gözlerim.... Sana giden tüm yollar, bedenimi sarıyor..... Sen...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Demirbaş']::text[], 8.5, '{"poet":"Mustafa Demirbaş","poet_slug":"mustafa-demirbas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ozlerim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Benim Yabancı Benimsin', 'sen-benim-yabanci-benimsin-i-smail-acarkan-8o113', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen

Yüreğimin kayıtsız şartsız alıcısı

Sen

İliklerine kadar ıslanmak pahasınaBir günün tutkulu akşamında

Bardaktan boşanırcasına

Sokakları kimsesiz kılan bir yağmur altında

Çıplak bir sokağın

Her bir taşında

Beni aramaktan yorulmuş

Ellerimi tutmaktan utandırdığım bakışlarınla...

Sen

Göz yaşlarıma sarılan ellerimsin,   

Sen benim yabancı perimsin. 

Yalnızlığı hayattan gizli		

Kısmeti yokluğa çıkmış		

Zamanın ötesine uzanmış   		

Tutunamadığım dalımsın. 		

Sen benim yabancı benimsin...		

Alışamadığım tenim        		

Bir zamanlar küsüp terk ettiğim		

Sen benim yabancı benimsin...', 'Sen Yüreğimin kayıtsız şartsız alıcısı Sen İliklerine kadar ıslanmak pahasınaBir günün tutkulu akşamında Bardaktan boşanırcasına Sokakları k...', ARRAY['Türk Edebiyatı','Şiir','İsmail Acarkan']::text[], 8.5, '{"poet":"İsmail Acarkan","poet_slug":"i-smail-acarkan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sen-benim-yabanci-benimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkmaz Bir Sevda', 'cikmaz-bir-sevda-ali-dost-aydin-wsune', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'çıkmaz bir sevdanın içindeyim 

çırpındıkça batıyorum 

daha derin sevdalara dalıyorum 

sığmıyor yüreğime sevdam 

aklıma sığdırmaya çalışıyorum 

zipleyip her anını seninle yaşadıklarımın 

sensiz! ... 

aklıma yazıyorum 

biliyorum bir gün 

aklımda almayacak sevdamı 

ve ben aklımı yitirip bu sevdadan 

bir heykel olacağım 

bakırköyde 

düşünen adam heykelinin yanında 

bir seven adam heykeli olacağım 

bir sevda delisi diyecekler 

bana 

biliyorum 

ve sen bir gün bile 

bir çiçekle 

gelmeyeceksin 

ziyaretime 

biliyorum 

ve belkide hiç 

bilemeyeceksin 

sevdiğimi 

seni bu kadar', 'çıkmaz bir sevdanın içindeyim  çırpındıkça batıyorum  daha derin sevdalara dalıyorum  sığmıyor yüreğime sevdam  aklıma sığdırmaya çalışıyoru...', ARRAY['Türk Edebiyatı','Şiir','Ali Dost Aydın']::text[], 8.5, '{"poet":"Ali Dost Aydın","poet_slug":"ali-dost-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/cikmaz-bir-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda''ma Sevdalı Kalmak', 'sevda-ma-sevdali-kalmak-ali-dost-aydin-78nnz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'o orda karşımda 

ben burda karşısında 

günde bir kez 

yanlıza bir saniye 

sadece ucuyla 

gözümüzün 

birebir örtüşmesi 

belki 

bir ömür yeter bana 

Sevda''ma Sevdalı kalmama', 'o orda karşımda  ben burda karşısında  günde bir kez  yanlıza bir saniye  sadece ucuyla  gözümüzün  birebir örtüşmesi  belki  bir ömür yeter...', ARRAY['Türk Edebiyatı','Şiir','Ali Dost Aydın']::text[], 8.5, '{"poet":"Ali Dost Aydın","poet_slug":"ali-dost-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevda-ma-sevdali-kalmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küllerim', 'kullerim-ali-dost-aydin-2yjwb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Küllerim

hani mitolojide 

eski bir hikaye vardı 

duymuştum 

eminim 

ama adını bilmiyorum 

hani küllerinden mi 

doğardı 

ne 

........ ! 

doğacak külüm 

kalmadı 

gülüm. 

Ama tükenmez yine de 

umudum

kül bulmasam da

o gülen gözlerinde 

nice güller bulurum

sonra kara deliklerinde 

kaybolurum

o kara deliklerden

Girsem de 

Kara bir cennete

Yeniden doğarım yine 

yıkıldığım 

her yerde 

bir tohum ekip 

evrene 

Yine de 

yeniden

doğarım

Gülüm.', 'Küllerim hani mitolojide  eski bir hikaye vardı  duymuştum  eminim  ama adını bilmiyorum  hani küllerinden mi  doğardı  ne  ........ !  doğa...', ARRAY['Türk Edebiyatı','Şiir','Ali Dost Aydın']::text[], 8.5, '{"poet":"Ali Dost Aydın","poet_slug":"ali-dost-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kullerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerini Süzerken', 'gozlerini-suzerken-mustafa-demirbas-tq16h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerinle  süzerken  beni inceden ince, 

Biran kurudu  dilim, çölde hep aradım su, 

Ferahladım bir anda, sen ruhumdan gidince, 

iman  şüphe götürmez, budur işin doğrusu....

Zorla Olmaz din, izan, haktan sual sorulmaz, 

Ruhun hep gelir gider, ,  biran için durulmaz...

Sevdayı ''arar mısın? '' niçin bu isyan niye, 

Nefsin sıkıntı çekmiş,    rabbine nisyan niye? 

Başını kapatmışsın,  zoraki giyiyorsun, 

sevgi mi  korku mu bu? asık simandan belli, 

Tam teslimiyet nedir, sen onu bilmiyorsun, 

İfrit sarmış ruhunu,  hayal imandan belli...

İçinde gizli isyan, Allah''a şirk koşarsın, 

Neden mutsuzum der? musibete şaşarsın...

Oyma bunlar hiç gibi, asıl narın yanında, 

Bir dua eder garip, doğruyu ''bul sonunda''

Nefsin azgınlar gibi, zekan pek ağır basmış, 

Cellat olmuş gelmişler, güzellikleri asmış...

Allah diyerek geldim,    Bir ibret vesikası, 

Görüntüsü müslüman,   ardı ''narın şahkası''

Musibetle, imtihan, yeryüzünde olacak, 

Kimi hakkı görecek, kimi narı bulacak, 

Sabredene cennet var, sonsuza dek nimet var, 

Düşün biraz alemi, ''azgın nefse cinnet var.''

Mecburiyetten değil, sevgiden olur iman, 

Musibetler mü''minin yükselen derecesi, 

Kalbinde şek varsa ki, azap mutlak pek yaman, 

Dağları yıkar gider ''Allah '' diyen hecesi....

Adildir cenab-ı Hak, ne verirse hakettin, 

Kendini beğenerek, nefsine zulüm ettin...

Gerçek kalple şükürü, yapmadın yapamazsın, 

Ateşe girersin hep, nefsinden sapamazsın...

Gözün pek yükseklerde, dilin aksini söyler, 

İnanan kalpler bilir, ürperir böyle tüyler...

Derman az yaram ağır,   öksüz kalp durma bağır, 

İşitmez ya devam et... Çünkü onlar kör sağır...

Kördür öyle bakarlar dal endam balık ete, 

Ak alnıma karadır, lekedir memlekete....

Bırakın kirletmeyin, alemin havasını, 

sahte hüviyetlerle bu islam davasını, 

Yeter istismarınız yapılıan hezeyanlar...

Sahte ''ruhunuzu sizin'' elbette arif anlar....

10.11.2000-Pazar/İstanbul

MUSTAFA DEMİRBAŞ', 'Gözlerinle  süzerken  beni inceden ince,  Biran kurudu  dilim, çölde hep aradım su,  Ferahladım bir anda, sen ruhumdan gidince,  iman  şüphe...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Demirbaş']::text[], 8.5, '{"poet":"Mustafa Demirbaş","poet_slug":"mustafa-demirbas","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/gozlerini-suzerken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Şiiri', 'yalnizlik-siiri-tugba-gurelli-ypgsm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çoğaltılmış 

                 yalnızlıklarda

                                    kırık

                                          cam

                              sevdaları

                        battı

              içime...', 'Çoğaltılmış                   yalnızlıklarda                                     kırık                                           cam        ...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Gürelli']::text[], 8.5, '{"poet":"Tuğba Gürelli","poet_slug":"tugba-gurelli","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yalnizlik-siiri-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklerim', 'beklerim-husnu-bahadir-us5qm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ardından ben koşa koşa yoruldum, 

Bilmiyorum ben neyine vuruldum, 

Her saat her dakka seninle oldum, 

Bir daha seninle olamam gayrı.

Adım adım seni yaşadım bende, 

Ben hiç mutlu olmadım bu diyardan gidende, 

Hep sen vardın gündüzümde gecemde, 

Sensiz artık güneşler doğamaz gayrı.

Sensiz doğan güneşi ben neyleyim, 

Bir bekle de ben bin sene bekleyim.

Bu dünyada olmadıysa neyleyim.

Ahireti beklerim çare kalmadı gayrı.', 'Ardından ben koşa koşa yoruldum,  Bilmiyorum ben neyine vuruldum,  Her saat her dakka seninle oldum,  Bir daha seninle olamam gayrı. Adım ad...', ARRAY['Türk Edebiyatı','Şiir','Hüsnü Bahadır']::text[], 8.5, '{"poet":"Hüsnü Bahadır","poet_slug":"husnu-bahadir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/beklerim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Gül...', 'mavi-gul-serkan-akoglu-4dahc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Serseri geceLer''de doLaştım yine.. 

Bir başıma yine yaLnız.. YapayaLnız.. 

Hırçın yağmurLar''da ıslandım, , 

Bir başıma, bir ben, bir gece  boyunca..... 

AğLayan gönLüm iLe ısLandı kirpikLerim.. 

GözyaşLarım aktı yalnızlığa...sessizLiğe......! ! 

Umut tarLaLarına ekilen binLerce tohum... 

GözyaşLarımLa büyüdü, yeşerdi...

Bir yaşamı simgeLeyen... 

BeLkide bir ömrü anlatan.. 

Bir güLün adı...... 

YaLnızdım...Oysa..

 İsmini yaLnızlık koymadım.. 

Onda acı yok''tu, isyan yok''tu 

AğLasada gönLüm, ısLansada kirpikLerim 

Hiç tükenmeyecek umut var''dı 

Umut dedim  çünkü..

Sabahı vardı o gecenin! ! ! 

Yeniden doğacak oLan güneş var''dı 

Her tarafı masmavi  aLacakaranLığın içiçde...

MAVİ dedim,  sevgi dedi.. 

GönLümde acan güL gibi.. 

Umut, sevgi içinde ben vardım.. 

İşte sana heyy hayat.........

Bir hediyem MAVi GÜL''ÜM.........', 'Serseri geceLer''de doLaştım yine..  Bir başıma yine yaLnız.. YapayaLnız..  Hırçın yağmurLar''da ıslandım, ,  Bir başıma, bir ben, bir gece  b...', ARRAY['Türk Edebiyatı','Şiir','Serkan Akoğlu']::text[], 8.5, '{"poet":"Serkan Akoğlu","poet_slug":"serkan-akoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/mavi-gul-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığa Nikotin Karıştırmak', 'yalnizliga-nikotin-karistirmak-i-smail-cem-cvi1f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Son söz söylenmiştir

Ve bir daha ertelenmemek üzere

ertelenmiştir bu dava...

Yapacak birşey yoktur artık

Giyilmemiş bir hükümdür

sensiz yaşamak.

Param olmadığına göre rakıya

En iyisi yalnızlığa nikotin karıştırmak.', 'Son söz söylenmiştir Ve bir daha ertelenmemek üzere ertelenmiştir bu dava... Yapacak birşey yoktur artık Giyilmemiş bir hükümdür sensiz yaşa...', ARRAY['Türk Edebiyatı','Şiir','İsmail Cem']::text[], 8.5, '{"poet":"İsmail Cem","poet_slug":"i-smail-cem","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yalnizliga-nikotin-karistirmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Monolog', 'monolog-kemal-sarialioglu-0g5cn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bardaktan mı boşanıyor yağmur? 

Gök mü delindi yoksa? 

Benim gözümde yaş mı var? 

Maç seyrediyorum oysa. 

Boş ver şimdi beni. 

Seyret ayağında topla geleni. 

Bak nasıl dizdi herkasi çalıma. 

Gelme Gül; gelme artık aklıma. 

Bak birader topu yine aldı. 

Noluyorki hakeme düdük çaldı. 

Neresi faul ulan bunun. 

Maç seyrediyorum Nur; değil senin konun. 

Çocukta yetenek var ama. 

İyi oynuyor helal ona. 

Yakışır bu oyunu birde golle süslemek. 

Yakışmıyor Melek; sana bunları söylemek. 

Yaptığına bak hakemin; çaldı yine düdüğü. 

Serap mıdır nedir bu herifin gördüğü? 

Bir gözlük verinde şuna sesi kesilsin. 

Serap! Benim gördüğüm serapta sensin. 

Herif nihayet attı golünü. 

Üç beş kişi duyacak ancak ününü. 

Ama hakkıydı iki asist birde gol. 

Yaklaşma Güneş! Benden uzak ol. 

Ne iş kardeş; niye bu düdük sesi? 

Kesilmedi mi hala bu maymunun nefesi? 

Öyle ya; önce bir muayene lazım adama. 

Sen tak Fidan, gözlük yakışıyor sana. 

Adam haklıymış ama ilk yarı bitmiş. 

Zaman ne çabuk uçup gitmiş. 

Hayat dediğin neki abi, sadece bir an. 

Ömür! Anılacaksa adım birtek sen an. 

Baba ben derim ki; gidelim artık eve. 

Baksana saate; çeyrek var üçe. 

Haklısın dostum sahur yaklaşmış iyice. 

Seviyorum seni Sevda; hemde delice. 

İyi ıslandık ama balık olduk sudan çıkmış. 

Şimdi farkettim bende; benim karnım acıkmış. 

İyi ya; eve gidince yemeğini yersin. 

Söylesene Nigar; sen bu aşka ne dersin. 

Düşündümde baba, manyak bu adamlar. 

Bu yağmurun altında top peşinde kim koşar? 

Onlar manyaksa dostum; bizede demeliler ahmak. 

Lakin yakışıyor bize yağmurda ıslanmak. 

                                                                   10 Kasım  2002', 'Bardaktan mı boşanıyor yağmur?  Gök mü delindi yoksa?  Benim gözümde yaş mı var?  Maç seyrediyorum oysa.  Boş ver şimdi beni.  Seyret ayağın...', ARRAY['Türk Edebiyatı','Şiir','Kemal Sarıalioğlu']::text[], 8.5, '{"poet":"Kemal Sarıalioğlu","poet_slug":"kemal-sarialioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/monolog-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ssatranc', 'ssatranc-sair-etzel-fmn1o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yol uzar gönlümden gönlüne

Uzar günler, geçmez hasretlik

Gönlümden geçmez yar haline

Gönlüne hasretlik, haline ayrılık..', 'Yol uzar gönlümden gönlüne Uzar günler, geçmez hasretlik Gönlümden geçmez yar haline Gönlüne hasretlik, haline ayrılık.....', ARRAY['Türk Edebiyatı','Şiir','Şair Etzel']::text[], 8.5, '{"poet":"Şair Etzel","poet_slug":"sair-etzel","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ssatranc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tezat', 'tezat-sair-etzel-tsgx0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aldın beni benden, kaldım ben bensiz

Sen benle, sen senle, ben kaldım sensiz

Ya beni bana ver, bırakma beni sensiz! 

Ya gel bana, tükendim artık sensiz..!', 'Aldın beni benden, kaldım ben bensiz Sen benle, sen senle, ben kaldım sensiz Ya beni bana ver, bırakma beni sensiz!  Ya gel bana, tükendim a...', ARRAY['Türk Edebiyatı','Şiir','Şair Etzel']::text[], 8.5, '{"poet":"Şair Etzel","poet_slug":"sair-etzel","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/tezat-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aleni ve de Gizli', 'aleni-ve-de-gizli-beyhan-oral-bayram-zsax7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bazen budanası bir sevda gibi

Susmayı bilmeyen bir fırtına

Hatta kar sularının şehre inmesi

Bir din gibi tapılası olur bazen de 

Belki kaldırımda çamurlu bir birikinti

Ve hatta 

Nemli bir kuyu gibi

Kimsesizlik gibi bazen 

Kimsesizsizlik! 

Yorgun ve dingin bir uykunun dibi

Ya da uyanırken tatlı bir öpüşün ahengi

Nasıl bir şey bu? 

Yüksek sesle söylenemeyecek kadar gizli

Sessizliğe gömülemeyecek kadar aleni...', 'Bazen budanası bir sevda gibi Susmayı bilmeyen bir fırtına Hatta kar sularının şehre inmesi Bir din gibi tapılası olur bazen de  Belki kaldı...', ARRAY['Türk Edebiyatı','Şiir','Beyhan Oral Bayram']::text[], 8.5, '{"poet":"Beyhan Oral Bayram","poet_slug":"beyhan-oral-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/aleni-ve-de-gizli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçerde büyümek', 'i-cerde-buyumek-ozel-arabul-rh69o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İçerde  büyümek        

Pas kokulu bir çiçektir gökyüzü

Sabahları açmalara utanan

Daracık pencerede

Zaman geceleri içimde

Su yürüyen hüzündür

Salınır saçlarında anamın

Kaskatı bir ağaç taş döşemede

Güneş ne zamandır bir bıçak

Keser duvarı

Gölgemi uzatır karşı dağlara

Uçmasını bilmeyen kuşlara benzer

Ayak izlerim yanar toprakta

Ben burada doğmuşum

İçerde bütün analar benim

“ziyaret günleri” nden kalmış

yoksul bir şeftali gibiyim

ya siz dışardakiler

daha mı geniş soluğunuz

kardeşlerim



Özel ARABUL', 'İçerde  büyümek         Pas kokulu bir çiçektir gökyüzü Sabahları açmalara utanan Daracık pencerede Zaman geceleri içimde Su yürüyen hüzündü...', ARRAY['Türk Edebiyatı','Şiir','Özel Arabul']::text[], 8.5, '{"poet":"Özel Arabul","poet_slug":"ozel-arabul","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/icerde-buyumek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül ü ver', 'gul-u-ver-zubeyir-sasmaz-z2b03', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen bana, gül ‘ü ver

Ben sana, zambağı.

sen, bana gülüver.

Ben sana,  dünyayı  vereyim.', 'Sen bana, gül ‘ü ver Ben sana, zambağı. sen, bana gülüver. Ben sana,  dünyayı  vereyim....', ARRAY['Türk Edebiyatı','Şiir','Zübeyir Şaşmaz']::text[], 8.5, '{"poet":"Zübeyir Şaşmaz","poet_slug":"zubeyir-sasmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gul-u-ver-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Okul Çağı', 'okul-cagi-ozel-arabul-57ypk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'DERS1

Atlaslarda tuzlu tuzsuz gölleri

Belletirler uzun değnekleriyle

Sanki karınca yuvası

Daracık kahverengi çizgiler

Sınırlar çiçek açmaz diken içinde

Gemiler geçmiyormuş izinsiz

Paylaşılmış deniz dipleri

Olgun bir dut gibi sallanır başım

Kürsünün gölgesinde

DERS2

Sultanlar girer birden sınıfa

Altın işlikleri

Ve saf ipekten otağlarıyla

Savaş tortusu gibi

Biçilmiş gövdelerin üstünde

DERS3

Birbirimize bakarız bütün çocuklar

Saçlarımızdan yakalarımızdan

Dökülür aşağıya sayılar

Kırık bir doğru gibi parmaklarımız

ÇOCUK

Hiç sormadım gelmiyor aklımıza

Babam neden kullanmaz ürettiğini 

Niye ürkütür onu çarşılar

Sesi de benzemiyor başkalarına

Eski bir top gibi düşer yüreğim

Koşamam çayır kuşlarıyla

Hepinizden daha yorgunum şimdi', 'DERS1 Atlaslarda tuzlu tuzsuz gölleri Belletirler uzun değnekleriyle Sanki karınca yuvası Daracık kahverengi çizgiler Sınırlar çiçek açmaz d...', ARRAY['Türk Edebiyatı','Şiir','Özel Arabul']::text[], 8.5, '{"poet":"Özel Arabul","poet_slug":"ozel-arabul","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/okul-cagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir gülüşe Bağdat', 'bir-guluse-bagdat-zubeyir-sasmaz-pxbax', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gülüşe Bağdat''ın nasıl verildiğini, 

Sen gülünce anladım.

Bir sevgili için canın nasıl verildiğini, 

Seni görünce anladım.

Saatlerce seni seyretmekten, 

Kendimi   alıkoyamadım.

Gözlerimin içine bak, gülerek.

Ruhumun derinlerine inerek, 

Solan yüzümü güldürerek

Gözlerimin içine bak, gülerek.

Günlerce seyretsem doyamam.

Seni ellere vermeğe kıyamam.

Gezsem de bütün dünyayı

Senden güzelini bulamam

Senden güzel gülenini bulamam.

canım benim', 'Bir gülüşe Bağdat''ın nasıl verildiğini,  Sen gülünce anladım. Bir sevgili için canın nasıl verildiğini,  Seni görünce anladım. Saatlerce sen...', ARRAY['Türk Edebiyatı','Şiir','Zübeyir Şaşmaz']::text[], 8.5, '{"poet":"Zübeyir Şaşmaz","poet_slug":"zubeyir-sasmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-guluse-bagdat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evcil Acı', 'evcil-aci-ozel-arabul-qryno', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Su içiyor bardağımdan

Karşımda tam karşımda duruyor

Açsam ağzımı

Benden önce o söylüyor

Yastığımda onun baş izi

Onun serinliği göğüs boşluğumda

Kullanılmamış bir ev gibi

Beni yenibaştan döşüyor

Diyelim ki küçük, yerleşik bir saat içimde

Kendi kendini durmadan kuruyor

Hiç kimse aslında 

Bir yerlere gitmiyor

Bütün süreçlerinde

Bir yelken bezi gibi

Rüzgara karşı inip kalkarak

Suyunda dinleniyor

İşte bir ağaç yanlış iki dalıyla

Geceyle günü yine de karıştırıyor 

Sonra bütün pencerelerde gökyüzü

Taş baskı gibi hiç değişmiyor

Ben ki bir çocuk kadar yalnızım

Böyle olsa ne çıkar

Bir çocuk bile yalnızlığında

Artık kendini kullanıyor', 'Su içiyor bardağımdan Karşımda tam karşımda duruyor Açsam ağzımı Benden önce o söylüyor Yastığımda onun baş izi Onun serinliği göğüs boşluğu...', ARRAY['Türk Edebiyatı','Şiir','Özel Arabul']::text[], 8.5, '{"poet":"Özel Arabul","poet_slug":"ozel-arabul","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/evcil-aci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzafiyet', 'i-zafiyet-zubeyir-sasmaz-cblxa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Birlikte yürüdüğümüzde  yol hiç bitmesin

         zaman  dursun, artık  geçmesin isterdim

Her gün yarım saatte gidemediğim yol

         SEN inle gidince, iki dakikalıkmış  dedim

O güne kadar, kaldırımların bu kadar

               güzel olduğunun hiç  farkında değildim.

Senden sonra, hep aynı yolu tekrar tekrar

        her gün yeni baştan, seninle gitmek istedim.

canım benim', 'Birlikte yürüdüğümüzde  yol hiç bitmesin          zaman  dursun, artık  geçmesin isterdim Her gün yarım saatte gidemediğim yol          SEN ...', ARRAY['Türk Edebiyatı','Şiir','Zübeyir Şaşmaz']::text[], 8.5, '{"poet":"Zübeyir Şaşmaz","poet_slug":"zubeyir-sasmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/izafiyet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dilim Ay', 'bir-dilim-ay-ozel-arabul-xunl5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir dilim ay, kıpkırmızı bir dilim ay

İstemli bir dilim ay, yanıp sönesi

Vapur olsam varasım gelir

Onca gecenin içinde

Hem de sümbülsü mavi

Bir dilim ay

Oldukça puslu hem de

Bir bardak su gibi

İçip kanasım gelir

Şarkıları asarız da

Yediveren gülleri gibi baharımıza

Nedense hem İsa öncesi hem İsa sonrası

Camgöbeğinden bir dilim ay

Renk değiştirir durmadan akşamımıza

İnce bir bıçak çıkarır

Yorgun bir ses gibi dağılmasından

Okyanusa yağan karın yüzüne

Senin yüzüne, benim yüzüme

Bir dilim ay kılıç gibi

Üstüne kapanasım gelir', 'Bir dilim ay, kıpkırmızı bir dilim ay İstemli bir dilim ay, yanıp sönesi Vapur olsam varasım gelir Onca gecenin içinde Hem de sümbülsü mavi ...', ARRAY['Türk Edebiyatı','Şiir','Özel Arabul']::text[], 8.5, '{"poet":"Özel Arabul","poet_slug":"ozel-arabul","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-dilim-ay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlim *Şematik*', 'i-lim-sematik-mustafa-engin-karatay-z1e3h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zulüm.............Âbâd.............Kılmaz........Aslâ................Zâlimi

Âbâd..............Eyler..............İlim.............Utandırmaz....Âlimi

Kılmaz............İlim.................Rüsvây......Sürdür............Ta''limi

Aslâ...............Utandırmaz...Sürdür........Vasf-ı..............Sâlimi

Zâlimi............Âlimi..............Ta''limi........Sâlimi.............Hâlimi

Tut................Bilgeler.........Buyruğunu...Zarar...............Etmezsin

Bilgeler........Nasihâtını.....Alıp..............Cürme.............Gitmezsin

Buyruğunu...Alıp...............Pîrin.............Od''a.................Tütmezsin

Zarar...........Cürme, .........Od''a............Girme..............Yetmezsin

Etmezsin....Gitmezsin.....Tütmezsin....Yetmezsin.......Bitmezsin

Okumakla....Nûrlanır........Yol, ..............Körelir............Cehil

Nûrlanır, ......Ziyâdan........Eyler............Neş''et............Te''hil

Yol................Eyler.............Yolcusunu...Sırlara.............Ehil

Körelir..........Neş''et..........Sırlara.........Varamaz.........Bahil

Cehil............Te''hil............Ehil..............Bahil...............Vehil

Ârif...............Mutlak...........İlimle.............Görür............Cemâli

Mutlak..........Hazînede.....Gizli...............Esrâr.............Kemâli

İlimle............Gizli..............Keşf-i............Mütebeyyin...Şemâli

Görür...........Esrâr............Mütebeyyin..Cihette...........Şimâli

Cemâli........Kemâli.........Şemâli..........Şimâli.............Îmâli 



08.09.2000   Landsberg   02: 40', 'Zulüm.............Âbâd.............Kılmaz........Aslâ................Zâlimi Âbâd..............Eyler..............İlim.............Utandırmaz...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ilim-sematik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üsküdarda Akşam', 'uskudarda-aksam-abdullah-karaduman-5td1n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir ayrıcalıktır yaşamak Üsküdar da

Batan güneşi ve Sarayburnu nu seyretmek

Doşalmak kıyısında, sahil boyunda

Bir başka olur akşam Üsküdar da

Güneşle birlikte doğar umutlar

Kadıköy''den Beykoz''a gider balıkçılar

Geçerken Kız kulesine bir selam çakar

Bir başkadır Üsküdar da akşamlar

Salacak''tan güneşin batışını seyreder aşıklar

Kıyısından, yamacından olta sallar balıkçılar

Parklarında oyun oynar çocuklar

Bir başkadır Üsküdar da akşamlar

Nice sevdalara şahitlik eder martılar

Nice umutlar taşır gün boyu vapurlar

El ele dolaşır anne baba çocuklar

Bir başkadır Üsküdar da akşamlar

Boranda, karda, fırtınada yağmurda

Sığındım sana, ana kucağına

Gündüzler çok güzel olur ama

Bir başkadır akşamlar Üsküdar da 

Marmara''ya açılan yüzüne

Bir kızıllık düşer yalıların üzerine

İşte ozaman  hüzün dolar içime

Bir başkadır Üsküdar da akşamlar

Yine sana geldim Üsküdar

Kır diyorsun zincirini, kolaysa gel sen kır

Bulutların arkasından görünüyor yıldızlar

Bir başkadır Üsküdar da akşamlar

İşte bak yine akşam oluyor

Gözlerim dalıyor, içim daralıyor

Kalbime bir  hançer saplanıyor

Bir başkadır Üsküdar da akşamlar

Karaköy''den Eminönü''nden Sarayburnu''ndan

Hep sana yansıyor ışıklar

Hüzün ve sevinci bir arada yaşayanlar

Bir başkadır Üsküdar da akşamlar', 'Bir ayrıcalıktır yaşamak Üsküdar da Batan güneşi ve Sarayburnu nu seyretmek Doşalmak kıyısında, sahil boyunda Bir başka olur akşam Üsküdar d...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karaduman']::text[], 8.5, '{"poet":"Abdullah Karaduman","poet_slug":"abdullah-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/uskudarda-aksam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesler ve Küller', 'sesler-ve-kuller-behcet-aysan-zlfeq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sesler ve küller

		

		

orada duruyorsun, fırtınalar tanığımdır

terkedilmiş 

beyaz ve nazlı, 

yorgun bir hallacın

            attığı

                yünler

                    gibi

dokunaklı.

git diyorlar gidiyorsun

kal diyorlar

ne bir ses

ne bir şarkı.

ey saçlarına ak kuşlar üşüştüren

yüzünü peçesine saklamış

ayın altında

çam dalına asılan

gümüş 

gölgesi

göle düşmüş.

kendine bıçaklar bileyen

                 devrilmiş

                 kağnı

                 gibi

yolda kalmış

sevgilim.

altın benekli

fundalıklarda

pusuya düşürülen

geceleyin gözleri bağlı

                           götürülen

karaca.

inilmedik ne bir deniz

çıkılmadık ne bir dağ

uğranmadık han

bırakmayan

yaralı koşma

sevdalı

im

halkım, sevgilim.

saz yok

mızrap yok

hep konmuş

hem göçebe

hem balık hem kuş

hem ingin hem yokuş

yanık otlar gibi

              kavrulmuş

esmer ve yoksul.

iner şafağın alacasında

karıncalar ordusu

şehre

                    kenar

                    mahallelerden

yürüyerek

ve trenlerle.

su satan çocuklarıyla

kapılarında vagonların

çamaşırcı

kadınlarıyla

                  iner

                 şehre

sincan''dan

iner mamak''tan

battal gazi

destanı ve

kan kalesi

ve kılıcıyla alinin

mızraklı ilmihalle.

yok başka bir cehennem

yaşıyorsun işte 

ellerine

bulaşmış

kara incirin sütü

ve kardeşinin

kanı

habil ile kabilin.

yaşıyorsun

sarışın

onurlu ve aşık

karasevdalar

içinde

               aydınlık.

yok senin kayan bir yıldızın

puslu 

ssekendizin

çolpanın

görünmüyor.

bu gökyüzü

sana

bana dar

telliturnam uçamaz

gelinkuşum konamaz.

                 tel örgüyle

                 çevrilmiş

onlara

mavi ve alabildiğine

                               geniş.

hasretin çırağı

gurbetin

kalfası

ve aydınlıkların

ustasısın

             sönünce

             mum

sönünce

çarağı

karanlıklara

çarpan

pervanem.

             halkım

             sevgilim

yanar

güneşte etin kehribar

                        bir üzüm

çıngılı

gibi.

çıkrık iner

çıkar

çıkrık

varılmaz

dibi görülmedik

korkuyum.

süngerdedir

vurgun yemiş

tütün 

düzer

                 inci

                 gibi.

karabükte

duman olur

                 savrulur

gıslavette işçi.

yıllar yılı

bilirim

döne döne

yıllar yılı

aynı 

kitabı okur

adı acılarbilgisi

adı acılarbilgisi

acılarbilgisi. 

Behçet Aysan', 'Sesler ve küller 		 		 orada duruyorsun, fırtınalar tanığımdır terkedilmiş  beyaz ve nazlı,  yorgun bir hallacın             attığı         ...', ARRAY['Türk Edebiyatı','Şiir','Behçet Aysan']::text[], 8.5, '{"poet":"Behçet Aysan","poet_slug":"behcet-aysan","theme":"Türk Şiiri","is_hero":false,"total_lines":143,"source_url":"https://www.antoloji.com/sesler-ve-kuller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Edirne', 'edirne-mehmet-akif-ersoy-9a2bm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Edirne kal''asıdır gördüğün hisar-ı mehib

Şu zirvesinde biten simsiyah ağaç da salib

Murad-ı evveli koynunda gezdiren tepeler

Nasıl rüku ediyor Ferdinand''a bak bu sefer

Bizim midir sanıyorsun şu yükselen bayrak? 

Çeken Savof, Lala Şahin değil kuzum, iyi bak

Edirne! İşte o islamın ahenin suru

Edirne! İşte o şarkın cebin-i mağruru

İkinci aşr-ı tealisi Al-i Osman''ın

Birinci mevki-i feyyazı belki dünyanın

Edirne! İşte o şarkın demir kilidi

Sefil ayakları altında Bulgar''ın şimdi

Muzaffer ordusu hakkıyla(!)   intikam alıyor

Kadın, kız, çoluk, çocuk, erkek ne bulsa parçalıyor

Bu katliama da razıyım ihtiram olsa

Harim-i dini de  geçtik harim-i namusa

Şu dört minareli cami ki yoktu hiçbir eşi

Ki parlıyordu hilalinde sanatın güneşi

Salibi sineye çekmiş de bekliyor.Nevmid', 'Edirne kal''asıdır gördüğün hisar-ı mehib Şu zirvesinde biten simsiyah ağaç da salib Murad-ı evveli koynunda gezdiren tepeler Nasıl rüku ediy...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Ersoy']::text[], 8.5, '{"poet":"Mehmet Akif Ersoy","poet_slug":"mehmet-akif-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/edirne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olurmu İkincisi', 'olurmu-i-kincisi-i-hsan-uncuoglu-yz9aj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İnandığım Allah

Tek Yaratan! 

Peygamberler yanında

Eşsiz Yerin var Anam! 

SENDEN ÇIKMADI 

Derinden hiiç

Aaah! demedin

Hiçbir zaman 

Heyhat kaçırdım 

Meğer Yüce aşkım 

Anladım Sen idin, 

Şimdi ardından 

Eşşiz hatırana 

Bir Aaah! 

Bilirim çeksem 

Olmaz hiç yetmez 

Bu Yol dönülmez 

Ne yapsam ki! 

Anam, 

Varmı eşi Ey! dünya 

Bir araya gelin 

Söyleyin! 

Yok benzer bir bağ böylesine 

Sevende sevilende 

Bu Sevgi bambaşka 

Hayatboyu ayrılma yok 

Ölünceye dek

Görülmemiş bu aşk

Ölüm var nedek

Ölünceye, 

***

Aralıksız gece gündüz

Ana evlat arasında

Süren bu aşkın tadına

Varan kimse desin 

Kim O çıksa ortaya? , 

***

Yaşadıkça 

Çook gezdim aradım 

Arandım

Sızlayan burnumun direği 

Damla damla gözyaşımla 

Geçen Sisli aralarda

Kimi hatıramda dondum

Kaldım, 

***

Enbüyük mezarlıkta 

Kitaplarda bulamadım

Koca koca Selviler 

Çınarlar altında

Hatta öldükten sonra 

Ana evlat aşkından

Bir iki satır

Öyle yüce bir Sevgiyi anlatır, 

***

Yazılı yazısız 

Ya yok yada kalmamış

Mezar taşlarında

Allahtan Allahın adından başka! ,', 'İnandığım Allah Tek Yaratan!  Peygamberler yanında Eşsiz Yerin var Anam!  SENDEN ÇIKMADI  Derinden hiiç Aaah! demedin Hiçbir zaman  Heyhat k...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/olurmu-ikincisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Damla', 'damla-i-hsan-uncuoglu-9ifwy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'KALPTEN KALBE HEYA DEĞER NASIL TAŞINIR 

DERETEPE HER AYDINDAN SELAM ALKIŞLANIR! 

*

Selam ne güzeldir yürekten aktarılır 

Kelamdır yürekten yüreğe yol anlatır 

Değer insanları yürekten selamlamak

Arkadaş özünden doğru yetenekli bak 

Ne mutlu yüreklere sevgi doldurmak 

Anlam dolu güçlü dünyalar yaratarak. 

* 

Selamları yumak sevinçli dostça yaparsak 

El kaşta başta bu Ruh''a gelip selam durak 

Lale dikenli güle sarılmış türküsüne bak 

Aydın sevgi selidir ister dolun aydınlık 

Meydanlar çınlar selamınla harika bu Ustalık. 

*

KALPTEN KALBE HEYA DEĞER NASIL TAŞINIR 

DERETEPE HER AYDINDAN SELAM ALKIŞLANIR! ALKIŞLANIR! ..', 'KALPTEN KALBE HEYA DEĞER NASIL TAŞINIR  DERETEPE HER AYDINDAN SELAM ALKIŞLANIR!  * Selam ne güzeldir yürekten aktarılır  Kelamdır yürekten y...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/damla-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevince Sen', 'sevince-sen-i-smail-acarkan-9gwrw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kimse bilmez... 

Gece nerede başlar

Gündüz nerede biter...

Ve kimse bilmez

Benim bittiğim yeri, 

Senin de başladığın.

Sanırım...

Her şeyin ayrılacağı gün

Ayırmak güç olacak ikimizi.

Belki...

Geceyi de gündüzü de

Biz ayırırız birbirinden

Gözümüzü kapatınca gece

Açınca da gündüz değil midir? 

Ve aşk doğsa kalbimize

Kapatır mıyız bir daha gözlerimizi? 

Sevince sen

Sevilince ben olmuyor muyum? 

Sana bakınca sen

Bana bakınca ben değil miyim?', 'Kimse bilmez...  Gece nerede başlar Gündüz nerede biter... Ve kimse bilmez Benim bittiğim yeri,  Senin de başladığın. Sanırım... Her şeyin a...', ARRAY['Türk Edebiyatı','Şiir','İsmail Acarkan']::text[], 8.5, '{"poet":"İsmail Acarkan","poet_slug":"i-smail-acarkan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevince-sen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Nefeste', 'son-nefeste-ali-dost-aydin-ofzjf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gül doyumu sevdalarımda oldu 

Bülbül hasreti de çektim 

                         altın kafeste 

Ama biliyorum ki bir gün

seni seviyorum diyeceğim 

                        yine birine 

                        son nefeste', 'Gül doyumu sevdalarımda oldu  Bülbül hasreti de çektim                           altın kafeste  Ama biliyorum ki bir gün seni seviyorum diye...', ARRAY['Türk Edebiyatı','Şiir','Ali Dost Aydın']::text[], 8.5, '{"poet":"Ali Dost Aydın","poet_slug":"ali-dost-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/son-nefeste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanki Bilmiyorum', 'sanki-bilmiyorum-i-smail-acarkan-utkwq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir kopukluk var

Ruhumda hissettiğim, 

Anlatılmaz bir şey bu.

''Sanki ben biliyor muyum? ''

O kadar karışık ki

Var mıyım diyorum.

O kadar derin 

ve yoğun

Anlatamıyorum.

Ama...

Eminim; 

Seni Seviyorum.', 'Bir kopukluk var Ruhumda hissettiğim,  Anlatılmaz bir şey bu. ''Sanki ben biliyor muyum? '' O kadar karışık ki Var mıyım diyorum. O kadar deri...', ARRAY['Türk Edebiyatı','Şiir','İsmail Acarkan']::text[], 8.5, '{"poet":"İsmail Acarkan","poet_slug":"i-smail-acarkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sanki-bilmiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlara Heykel Dikmek Gök Yüzü Sevdalı', 'umutlara-heykel-dikmek-gok-yuzu-sevdali-ali-dost-aydin-ugiqr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir beyaz gülüm olsa 

Dikenlerine bansam mutluluğumu

Gülpembemsi peltelerden

Umutlara heykel diksem 

                   gökyüzü sevdalı

Bir adını yazardım kaidesine 

                                 birde 

Sevdiğimi seni 

        Gül benlim', 'Bir beyaz gülüm olsa  Dikenlerine bansam mutluluğumu Gülpembemsi peltelerden Umutlara heykel diksem                     gökyüzü sevdalı Bir ...', ARRAY['Türk Edebiyatı','Şiir','Ali Dost Aydın']::text[], 8.5, '{"poet":"Ali Dost Aydın","poet_slug":"ali-dost-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/umutlara-heykel-dikmek-gok-yuzu-sevdali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasat zamani', 'hasat-zamani-orhan-balta-p9ujh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yagmurlarin yavas yavas sonlanmaya.

gunes isisinin doganin rengini degistirmeye

yesilden sari bir renkle kucaklasmaya basladigi zaman

yakindir artik hasat zamani.

Topragin rengi donusurken yesilden sariya'', 

insanlarin rengide degismeye baslar, 

bembeyaz tenler once sararip sonra kavrululmaya baslar.

Soguk kis gunleri geride kalmis 

bahar sonlanmis ilk yaz sicaklari bugdaylari sarartmaya 

ekinlerin basaklarini olgunlastirmaya baslamistir 

hummali bir hazirlik icindedir koylu. 

Oraklar bileglenir, tirpanlar tasa surulur, 

yabalar, tirmiklar, dirgenler son kontrolden gecirilir 

hasat ortasinda yeni bir ugras cikartmamasi icin tamir edilip hazirlanir.

Harman yerleri temizlenmis anbarlar duzenlenmis

bugdaylarin, arpalarin konacagi kil cuvallar gozden gecirilmistir.

Ilk oragin sallancagi tirpanin vurulacagi zamanin beklemesindedirler.. 

Uzun kis geceleri edilen sohbet zamanlari 

erken kalkilacak gunler icin yerini derin derin dusuncelere birakmistir artik..

eskisi gibi oturulup ankara konusulmaz 

partilerin kavgalari yasanmaz.

Tarlalarindan kaldirdiklari urunlerini nasil nereye

kaca satacaklarinin hesabi icindedirler 

bunu sadece kendi kendilerine konusur 

yine kendilerine verirler cevabini, 

bundan once nasil olduysa yine oyle olur.

Uzun ugraslar sonucunda kan ter icinde kalarak topladiklari urunlerini yine harac mezat satacaklardir 

onlarin sirtindan para kazanan komisyoncular 

kasalarini doldururken yine kendileri kislik yiyecekleri kadarini ayirip 

sattiklariylada bir kac eksiklerini tamamlayip 

yeni seneyi bekleyeceklerdir..

bu hep boyle olmustur bundan sonrada boyle devam edecektir..

varmidir baska caresi  varsada bilmezlerdir..

ne bir yol gosteren  nede bu islerin nasil yapildigini bilen vardir.

Her yil hasat zamani gelen ilcenin ofis memuru bu yilin fiyatlarini, 

hasatlarini teslim edecekleri yeri soyler..

onlarda ona gore teslim ederler urunlerini..

gariptir paralarini alacaklari zamani bile soramazlar

ne zaman cagiririsa devletin memuru gider verilen parayi alir.

gelecek yilin tohum gubre masraflari ayrilir 

geriye kalanlada colugun cocugun ufak tefek eksikleri temin edilip 

yari sevincli yari kaygili koylerine donup, kader boyleymis deyip

teslim olurlar.', 'Yagmurlarin yavas yavas sonlanmaya. gunes isisinin doganin rengini degistirmeye yesilden sari bir renkle kucaklasmaya basladigi zaman yakind...', ARRAY['Türk Edebiyatı','Şiir','Orhan Balta']::text[], 8.5, '{"poet":"Orhan Balta","poet_slug":"orhan-balta","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/hasat-zamani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam Madam', 'adam-madam-i-hsan-uncuoglu-1tp3b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mantar Kafa''lar 

Soyundan Doğan 

Yavru Mantarlar 

Ah! Sülo Sülo, lar

OLSAYDI OLDU

Giscard d''estaing aklı 

saklısı yok adam haklı 

Mösyö''yü coşturdu 

belle temps''ın anısı

Adam madam''ı kıskandı 

İştahları kabardı 

bunların adı 

Avrupalı, 

(belle Temps, , Fransızların Sömürge''lerle dolu Zengin Lale Devirleri)

Geldi vermedin bir hediye 

Gerçek rüyası kalmadı

sömürge üstüne sömürge

Uyutarak dünyayı el ele 

yaşadılar beleşlerle

Monşer ile madam haklı 

adı bunların

Avrupalı, 

ADAM MADAM 2

Mum yanmazdı evlerinde 

Yıkanmağa suları yoktu 

Köln''den Kokmasınlar diye 

Silin temizlen Kolonya ile

Şimdi Unuttular! Pariste, 

(Eau d''cologne/Köln Suyu)

(Cologne/Fransızcada 

Almanyanın Köln şehri/

Köln Suyu yani Türkçe Kolonya)

Akıl ordanmış bekle bir ışık

bizde birlik lafta yok karışık 

içli dışlı bir sürü babalık 

Onlara yakın bizeyse kayıp

Rüyalarda açarlar bazı bazı

İçi paslı parlak taşlı 

Ağır Altın varak yapraklı

Yalan bir tarih sayfası 

En başta süslü Hacılar 

Duyulmamış bin fal açarlar

Gerçekleri anında saptırır çarpıtırlar

Sultan Süleyman koca ordusun kaldırmış

Almanın elinden almak için bir Fransızı

Günümüzde ne sıfat ile Türke karşı 

Bu Mösyö et Madam zıpçıktı

Bunların da adı

Avrupalı? 

Kim sorar, , 

***

Gerçek sevgi yokmuş

Süleymandan

Fransuva''ya 

Adamla madama kadar

ne verdin de almadı

Türkiyede Vatan''cı 

Avrupada Avrupalı 

Meydanı boş bulunca 

sakallı hanzo''lar

Meydanları doldururlar

Havalardan hava atar 

Haberiniz olsun

İçlerinde çoğ başlar 

Günah bilmez yalanlarla 

Bizans özlemile yaşarlar 

bunların da adı 

Avrupalı, 

ADAM MADAM 3

Çanakkale geçilmedi 

O sıra Mehmet vardı

Denizde Karada

Türk Askeri Savaştı 

Kırk Düvele karşı

Günümüzde Avrupada 

Korku dağları aştı

Sevdaları bile 

göreceli içten içe

İşlerine geldiğince

Niyetleri karışık 

Sözde açık seçik 

Alt tarafı kimi yamalı

Donu Pantalonu 

Ceket Gömlek kıravratı 

benzer ayak numaralı 

bunların Adı 

avrupalı, 

***

İnsan hakları ardarda 

Baştan sona palavra

Ardına kadar Madama

Sevdalı olanlara 

kapılar açık aynı 

sana bana kapalı 

özgür Kafa hala Haçlı 

düşünce eşit Fikir farklı

Hepsi köhne değme Akılları

Bizans''tan kalma hafızalı

hesapları Boş marka 

Medeniyet sevdalısı 

makinalar Uzay çağı

21 inci asrı birlikte

görüyoruz yaşıyoruz 

Sınırlar ayrı

onların adı zengin

Sihirli

Avrupalı,', 'Mantar Kafa''lar  Soyundan Doğan  Yavru Mantarlar  Ah! Sülo Sülo, lar OLSAYDI OLDU Giscard d''estaing aklı  saklısı yok adam haklı  Mösyö''yü c...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":107,"source_url":"https://www.antoloji.com/adam-madam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türban Daş', 'turban-das-i-hsan-uncuoglu-x4v9w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Arkadaş Hiç Darılma 

Niyetlii Kısmetlii

Türban Takıp Başına

Geçiversen Karşıma

Seni Anlarım Kolayca 

Kimlerden Ortaklaşa

Aşk Yolları Açılır Sana, 

*

Uzak bir yerden eskimermer taş çıplak on tanrı 

Üstte çıkarır yedi katlı göklere bir ay parçası 

Ona taş baş saç bıyık sakal süsleri az gelmiş

Eksik aklın yapısı yalan yanlış şimşirdenmiş 

Eteğ başın saçına zil çıngıraklar takılsada 

İnançtan çıkarmı bir doğru kaç düzine ölçü varsa 

Anya manya oynarsın ya vız gelir sana o düdük aldırma! .

***

Kaç inanç var dünyada azmı başkanım dense sana

Türbo baş örtülü kahramanlar ne yakışıyor arkanda

Yürü bu rüya İlham birbaşka gel halvet ol en başta

Tasavvur düşünce derken ne fikirler doğar sonunda

Doğrusu bu haktır diye birde umutla karışık şey baba

Kanaatlı bu kumpanya zor olmazmı dönüş yanlış kapıda! 

***

Kimin inancı hakları neye dayanır ayarlanır

Kurallar kim elinde kim okur kimle savsaklanır

Geri herşey doğru olsa bile gün gibi açık ortada

Sormageç işte bu inanç endoğru ayarlı hepal varya

Karanlıkta orta yok doğruya her nutukta palavra

Nedenir arkadan adı güzel olsun ney çıkarsa bahtına, 

***

Bu açıkgözler valla kendilerin bile 

Hele O cepten her zamanda fırsatta 

Peygamberler çıkarta çıkarta uyutur

Cümle alemi meydanlarda oy şarkılarında! .', 'Arkadaş Hiç Darılma  Niyetlii Kısmetlii Türban Takıp Başına Geçiversen Karşıma Seni Anlarım Kolayca  Kimlerden Ortaklaşa Aşk Yolları Açılır ...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/turban-das-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerin', 'ellerin-onur-nazim-bulut-8dwjv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ellerin: incee, nariin.

alsa koynuna, alsa sadece.

Sorma alsa yeter ki, 

bakmazdım ardıma.

Yol açardı inan, 

çin seddi dahil bütün duvar.

Güneş toplardı tüm karanlıklar gözlerimden.

ilham olurdum tüm aşk şarkılarına...', 'Ellerin: incee, nariin. alsa koynuna, alsa sadece. Sorma alsa yeter ki,  bakmazdım ardıma. Yol açardı inan,  çin seddi dahil bütün duvar. Gü...', ARRAY['Türk Edebiyatı','Şiir','Onur Nazım Bulut']::text[], 8.5, '{"poet":"Onur Nazım Bulut","poet_slug":"onur-nazim-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ellerin-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Kaybettin', 'beni-kaybettin-abdullah-ozturk-a4vy3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bırak verme aşkını

ne benim sevilmeye hakkım var

ne senin sevmeye vaktin

melek olsan kar etmez

çünkü aşkı kaybettin

ışıksız kaldın yani, yüreksiz

dipsiz kuyuların karanlığında

ve uykusuz kaldın, gecelerin en tenhasında

yalnızdın benim gibi

derdim gibi dermansız, aşkım gibi fermansız

sevmemeye yeminliydin 

bile bile öldürmeye

ömründe hiç gülmemeye

ve beni güldürmemeye

bırak bitsin bu çile

ne benim dayanacak gücüm kaldı

ne senin çektirecek zulmün

yemin etsen faydasız

çünkü beni kaybettin

apo''suz kaldın yani, sahipsiz

koca bir şehrin limanında

ve tütünsüz kaldın, gecelerin en efkarlısında

yani bensiz kaldın, çırılçıplak gün ortasında.....!', 'bırak verme aşkını ne benim sevilmeye hakkım var ne senin sevmeye vaktin melek olsan kar etmez çünkü aşkı kaybettin ışıksız kaldın yani, yür...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Öztürk']::text[], 8.5, '{"poet":"Abdullah Öztürk","poet_slug":"abdullah-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/beni-kaybettin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahpe Yıllar', 'kahpe-yillar-abdullah-ozturk-yxsrg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ömrümün en orospu yıllarıydı

taş duvarlar ezdiğim, dağlarda gezdiğim 

ve canımdan bezdiğim yıllardı

gönlümün kahpeliğine en tutsak yıllarıydı

uzaktan sevdiğim, rüzgarına değdiğim

ve hiç sevilmediğim yıllardı

kanımın en kırmızı yıllarıydı

kalbimden vurulduğum, kaçmaktan yorulduğum

ve hesap sorulduğum yıllardı

dilimin en yırtık yıllarıydı

aykırı laflar ettiğim, ileriye gittiğim

ve bu yüzden bittiğim yıllardı

fikrimin en suskun yıllarıydı

düşünmekten pustuğum, kendime kin kustuğum

ve mecburen sustuğum yıllardı', 'ömrümün en orospu yıllarıydı taş duvarlar ezdiğim, dağlarda gezdiğim  ve canımdan bezdiğim yıllardı gönlümün kahpeliğine en tutsak yıllarıyd...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Öztürk']::text[], 8.5, '{"poet":"Abdullah Öztürk","poet_slug":"abdullah-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kahpe-yillar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Menfaat Güzeli', 'menfaat-guzeli-abdullah-ozturk-s3akx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir güzel gördüm, kolunda çantası

nere gider belli değil, evli desem evli değil

tutamadım kendimi, koştum hemen peşinden

yakın takibe aldım, yaklaştıkça yaklaştım

adını soracak oldum, cesaret edemedim

kızar mıydı acaba, hoşuna mı giderdi? 

farketti bir an beni, panikledim aniden

kafa önde, gözler bende devam etti yürümeye

sülün gibi eteğini başladı sürümeye

bir kaç adım daha gitti, dayanamadı belli ki

döndü birden geriye, geldi biraz beriye

kan sıçradı gözünden, namus aktı özünden

kıpkırmızı kesildim, sustum bir kaç saniye

toparladım kendimi, döndüm sonra faniye

sizi izlememde ki gaye, benzediğinizdir aya

niyetim çok ciddidir, sanma bende yok haya

birden tavrı değişti, çattı biraz kaşını

bir adım geri çıktı ve kaldırdı başını

olmaz dedi böyle şey, ya bir gören olursa

söylemeye utandı, lakin hoşlandı benden

ağzı, dili tutuldu, birden gözleri doldu

hazan yaprağı gibi hemen sarardı soldu

neyse dedim ben sonra, görüşelim az sonra

tanışır, anlaşırız, sonra nişanlanırız

meğer dünden razıymış, ama biraz nazlıymış

bir araba, bir de ev, dedi beni böyle sev

şaşırdım afalladım, defol dedim yolladım....!', 'bir güzel gördüm, kolunda çantası nere gider belli değil, evli desem evli değil tutamadım kendimi, koştum hemen peşinden yakın takibe aldım,...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Öztürk']::text[], 8.5, '{"poet":"Abdullah Öztürk","poet_slug":"abdullah-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/menfaat-guzeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzelliğin Tanımı', 'guzelligin-tanimi-bekir-ayral-0gv83', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Üç özellik ararım 

Kızlarda, 

Güzelliğin

Simgesi.

Birincisi: 

Serseri ruh, 

İkincisi: 

Hippi kılık, 

Güzel vücuttur

Üçüncüsü.

Vesaire sayılır

Artık

Benim için; 

Bunlardan 

GERİSİ.', 'Üç özellik ararım  Kızlarda,  Güzelliğin Simgesi. Birincisi:  Serseri ruh,  İkincisi:  Hippi kılık,  Güzel vücuttur Üçüncüsü. Vesaire sayılı...', ARRAY['Türk Edebiyatı','Şiir','Bekir Ayral']::text[], 8.5, '{"poet":"Bekir Ayral","poet_slug":"bekir-ayral","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/guzelligin-tanimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cevap', 'cevap-turgay-kaygi-epzjm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'doğum nedir biliyor musun Memedim? 

doğum çektikten sonra bir ton acıyı, eziyeti, 

insana ''hepsine değdi be! '' dedirten bir mucizedir! ..

haa! dersen ki ''lan kaç kere doğurdun ki hayatında sen? ..''

aslında yok be hocam bunun dişisi, erkeği! ..

şunu bil ki, 

ben bugün olduğu gibi yarında gülümserken sana, 

için için

dokuz doğuruyor olacağım! ..

(inegöl,14.09.2002)', 'doğum nedir biliyor musun Memedim?  doğum çektikten sonra bir ton acıyı, eziyeti,  insana ''hepsine değdi be! '' dedirten bir mucizedir! .. ha...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kaygı']::text[], 8.5, '{"poet":"Turgay Kaygı","poet_slug":"turgay-kaygi","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/cevap-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bunun Adını Sahibi Koysun!', 'bunun-adini-sahibi-koysun-turgay-kaygi-bc6sw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'en ümitsiz kaldığım, 

herşeyden büsbütün vazgeçtiğim noktada

bir gülüveriyorsun ya yüzüme! 

savaşta yakılmış, yıkılmış bir kentin, 

herşeyini kaybeden insanlarının

terketmek dururken o kentten geriye kalan ne varsa

yeniden inşaya başlaması gibi

evlerini, okullarını, ibadethanelerini

ben de kendi ellerimle yıkarak, 

kendi ördüğüm kapkara duvarları

yerine, 

alabildiğine müşkülpesent davranıp bir de üstüne üstlük! 

gül bahçeleri yapıyorum

kırmızı kırmızı güllerini bahçelerimin

gözlerimden bile sakınıyorum

sanki hiç sonbahar gelmeyecekmiş gibi! ..

(inegöl,29.10.2002)', 'en ümitsiz kaldığım,  herşeyden büsbütün vazgeçtiğim noktada bir gülüveriyorsun ya yüzüme!  savaşta yakılmış, yıkılmış bir kentin,  herşeyin...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kaygı']::text[], 8.5, '{"poet":"Turgay Kaygı","poet_slug":"turgay-kaygi","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bunun-adini-sahibi-koysun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoooooooook Zor Anlatması', 'coooooooook-zor-anlatmasi-turgay-kaygi-c81u4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''boşver! '' dediler

dinlemedim doğrusu

''unut gitsin! '' diyenlerde çıkmadı değil

sağolsunlar

hele ''bekle! '' diyenlerin haddi hesabı yoktu

asmadım kulağımı

hiç kimseye anlatamadım bir türlü

ne kadar mutlu, 

ne kadar umutlu, 

her zamankinden ne kadar farklı gözlerle

baktığımı dünyaya

yalan yok

seneleri devirirken bir bir

canım bolca sıkılmıştır

olmayacak şeylere ama

ekseri güzel geçti

yirmiyedi yıl

içim içime sığmadı kimi zaman

kimi ise batasım geldi yerin dibine

ama bugün

bugün; 

kabuğunu yırtarken 

bir yavru kuş yumurtasının

ne kadar mutluysa

bende mutluyum

bir o kadar! ..

(inegöl,16.09.2002)', '''boşver! '' dediler dinlemedim doğrusu ''unut gitsin! '' diyenlerde çıkmadı değil sağolsunlar hele ''bekle! '' diyenlerin haddi hesabı yoktu asma...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kaygı']::text[], 8.5, '{"poet":"Turgay Kaygı","poet_slug":"turgay-kaygi","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/coooooooook-zor-anlatmasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Yazma Hastalığı', 'siir-yazma-hastaligi-turgay-kaygi-5bgja', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'her sabah sorarsın ya

''bunları nereden buluyorsun? '' diye

dinle bak anlatayım abla! 

her sabah açar açmaz gözümü

başlar birikmeye içimde bunlar

tıpkı istiridyenin bağrında

yıllar geçtikçe büyüyen inci tanesi gibi

tıpkı hiç istemediğin halde

bahçende biten yaban otlar gibi

geçtikçe saatler ağır-aksak

çoğalır da çoğalır bunlar abla! 

gece olunca

elimi daldırıp ruhuma

çekip çıkartmasam bunları

inan bana deliririm abla! 

(inegöl,31.10.2002)', 'her sabah sorarsın ya ''bunları nereden buluyorsun? '' diye dinle bak anlatayım abla!  her sabah açar açmaz gözümü başlar birikmeye içimde bun...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kaygı']::text[], 8.5, '{"poet":"Turgay Kaygı","poet_slug":"turgay-kaygi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/siir-yazma-hastaligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavak yelleri...', 'kavak-yelleri-sah-ali-yasar-oo82z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gezdim gurbet kaçak gibi

Kavurdu ayaz geceler!..

Kesti ağzım bıçak gibi

Dilime vurdu heceler!..

Başımda kavak yelleri

Savurdu sinmiş külleri

Açmadan sevda gülleri

Kurudu yeşil bahçeler!..

Kimler geldi, kimler geçti

Aklı olan aşkı seçti

Ne ektiyse onu biçti

Sır oldu gitti niceler!..

Şah Ali der, sona erdim

Acılara göğüs gerdim

Yücelere gönül verdim

Alçakta durdu cüceler!..', 'Gezdim gurbet kaçak gibi Kavurdu ayaz geceler!.. Kesti ağzım bıçak gibi Dilime vurdu heceler!.. Başımda kavak yelleri Savurdu sinmiş külleri...', ARRAY['Türk Edebiyatı','Şiir','Şah Ali Yaşar']::text[], 8.5, '{"poet":"Şah Ali Yaşar","poet_slug":"sah-ali-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kavak-yelleri-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bak Aklıma Ne Geldi!', 'bak-aklima-ne-geldi-turgay-kaygi-bgrds', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dinliyor musun? 

dinle bak! 

ölümü anlatacağım sana bu gece

ölüm dediğin nesnenin

bin türlü hali vardır bilesin

bazen en güvendiğin köşesinden

kopar hayat

hiç ummadığın taşın deleceği tutar başını

hiç ummadığın insan sıkabilir boğazını

ansızın

hem sen öldün diye kıyamet de kopmaz ha! , 

geride kalanlar arasında

kemiklerinden çok önce kurur

hatıraların yakınlarının gözünde

hepimiz öleceğiz amenna! 

fakat seni bilemem ama, 

benim ardımdan; 

''pencereden dışarıyı seyrederken

duruvermiş kalbi! ''

dedirtmeye hiç niyetim yok! 

öyle bir ölmem gerek ki benim, 

azrailin bile aklı ermemeli sırrına! 

anlıyor musun? 

(inegöl,29.10.2002)', 'dinliyor musun?  dinle bak!  ölümü anlatacağım sana bu gece ölüm dediğin nesnenin bin türlü hali vardır bilesin bazen en güvendiğin köşesind...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kaygı']::text[], 8.5, '{"poet":"Turgay Kaygı","poet_slug":"turgay-kaygi","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bak-aklima-ne-geldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terapi', 'terapi-turgay-kaygi-5pmv5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'çocukluğuma inmeyelim

boşver doktor

inan orada değil problem

basbayağı şuram ağrıyor işte

ben yıllarca boş sanmıştım

orasını, 

meğer

bende de kalp varmış

Orhan Veli diye birinin

öldüğünü bilirdim de yıllar evvel

böyle canciğer kuzu sarması

dost olacağımızı

billahi tahmin etmezdim

ömür denen şey var ya doktor

geçip gider diye dedilerdi ya

ben işte onun takılıp kaldım kışına

bana illaki bir şey diyeceksen

bahara çok var mı? 

onu söyle doktor! 

söylesene! 

(inegöl,29.10.2002)', 'çocukluğuma inmeyelim boşver doktor inan orada değil problem basbayağı şuram ağrıyor işte ben yıllarca boş sanmıştım orasını,  meğer bende d...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kaygı']::text[], 8.5, '{"poet":"Turgay Kaygı","poet_slug":"turgay-kaygi","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/terapi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı Müptela', 'kirmizi-muptela-alper-bagcivan-lgupo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kırmızı bir müptelaya tutulmuşsun 

güller yanmış senle beraber

bir haber vermeden gözlerime

yalancı çıkmışsın sözlerinle beraber

.

bahar yeni veririken tomurcuklarını

sen kış hülyalarına dalmışsın 

bendeki sevdanı yabana atıp

beyaz bir yatağa kalmışsın.

.

kelimeler yanlızlığa girerken

kan olmuşlar senin üzerinde

kaderden bir ağıtsı dokunuş bedenine

bir de uzağındaki sevdalının titrek yüreğine

.

biliyorum gün gün eriyorsun

ölüm korkusu sinmiş bakışlarına

fakir kalmışsın yaşam sevincinde

hüznün ve karamsarlığınla

yaprakların savrulurken

ben sana yenilmiştim

sense

o hastalığa', 'kırmızı bir müptelaya tutulmuşsun  güller yanmış senle beraber bir haber vermeden gözlerime yalancı çıkmışsın sözlerinle beraber . bahar yen...', ARRAY['Türk Edebiyatı','Şiir','Alper Bağcivan']::text[], 8.5, '{"poet":"Alper Bağcivan","poet_slug":"alper-bagcivan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kirmizi-muptela-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeminettim', 'yeminettim-yakamoz-ali-ozkut-fzl73', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sevene merhaba 

sev meyene elveda', 'sevene merhaba  sev meyene elveda...', ARRAY['Türk Edebiyatı','Şiir','Yakamoz Ali Özkut']::text[], 8.5, '{"poet":"Yakamoz Ali Özkut","poet_slug":"yakamoz-ali-ozkut","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/yeminettim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakkın Bende Yüreğim Sende Kalsın', 'hakkin-bende-yuregim-sende-kalsin-metin-usengec-08efn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dönüp arkana bakmadan

Yüreksiz ve vicdansız gidişin

Binlerce kez ahımı aldı

İçimde boşluk yüreğimde acısı kaldı

Yetmediyse yüreğin sevmeye

Arkana bakma yolun açık olsun

Sevgi emek ister sevgi yürek ister ya

Hakkın bende Yüreğim sende kalsın

Aşk sevgi dostluk dolu dolu yaşanır

Gün gelir hatıralarda saklanır

Gerçek dostluk gerçek sevgi yoksa kalplerde

Ne hatır ne de hatıralar kalır

Sanma ki seni unutacağım

Sanma ki kuruyacak gözlerimdeki yaşlar

Sanma ki dinecek yüreğimdeki acılar 

Sanma ki seni affedeceğim

Sanma ki hakkımı helal edeceğim..

Ekim-2002

Dilerim Sende Bir Ömür Hasret Kalırsın Benim Seni Sevdiğim Gibi Sevdiğin Birine..', 'Dönüp arkana bakmadan Yüreksiz ve vicdansız gidişin Binlerce kez ahımı aldı İçimde boşluk yüreğimde acısı kaldı Yetmediyse yüreğin sevmeye A...', ARRAY['Türk Edebiyatı','Şiir','Metin Üşengeç']::text[], 8.5, '{"poet":"Metin Üşengeç","poet_slug":"metin-usengec","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hakkin-bende-yuregim-sende-kalsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Hatırla', 'beni-hatirla-metin-usengec-r65xy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geceleri değil gündüzleri

Yalnızken değil insanların yüzüne baktığında

Üzülürken değil gülerken mutluyken

Şarkılarda değil geride bıraktıklarında

Hatırla beni sevgilim..

Kasım-2002

Ben Kendimden Geçtim Ama Gülüm Senden Vazgeçemem..', 'Geceleri değil gündüzleri Yalnızken değil insanların yüzüne baktığında Üzülürken değil gülerken mutluyken Şarkılarda değil geride bıraktıkla...', ARRAY['Türk Edebiyatı','Şiir','Metin Üşengeç']::text[], 8.5, '{"poet":"Metin Üşengeç","poet_slug":"metin-usengec","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/beni-hatirla-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün', 'bir-gun-metin-usengec-7rkug', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gün sende düşersen beni düşürdüğün duruma

Bir gün ateş düştüğü yeri yakar ise sende 

Bir gün dayanılmaz acılar düşer ise içine

Bir gün taş basarsan yaşıyorken yüreğine

Bil ki o gün beni anlayacağın gündür

Bil ki o gün beni anlamış olmanın huzuru ile

Huzur ile ölebileceğim gündür..

Kasım-2002

Ahlarım Beddua Değil Anlaşılabilmek İçin..', 'Bir gün sende düşersen beni düşürdüğün duruma Bir gün ateş düştüğü yeri yakar ise sende  Bir gün dayanılmaz acılar düşer ise içine Bir gün t...', ARRAY['Türk Edebiyatı','Şiir','Metin Üşengeç']::text[], 8.5, '{"poet":"Metin Üşengeç","poet_slug":"metin-usengec","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-gun-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senirkent', 'senirkent-i-hsan-uncuoglu-dego5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senirkent Beşkardeş Dağı Heybetlidir! , 

İslamköy/Senirkent arası koyun otlar yayladır     

Beşkardeş''ten aşağı kırık anılarım yuvarlanır

Başım öne eğik düşünerek ağır giderken yoldan

Karıştırdım cebimden çıktı birkaç Çoban Süleyman! ,', 'Senirkent Beşkardeş Dağı Heybetlidir! ,  İslamköy/Senirkent arası koyun otlar yayladır      Beşkardeş''ten aşağı kırık anılarım yuvarlanır Ba...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/senirkent-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belkide mahşerde', 'belkide-mahserde-salih-ozalasan-j27fu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalnızlığımı yazsam sayfalara

Ağlar benimle iki gözü iki çeşme

Yüreğim öyle hasret dolu ki

Yalvarırım ne olur yaramı deşme

Haykırsam feryadıma dağlar yıkılır

Bunu adına diyorlar umutsuz sevme

Bize ne zaman kavuşmak yazılır

Dayanamam bana boşyere ümit verme

Gözlerin hep gülüyor dilinde sevgi

Seninle hayat doluyor yüreğime

Uzakta ta uzakta kavuşmak bir umut belki

Bir teselli buluyorum hep sözlerinde

Seninle sensizim feryadım deler geceleri

Sen bir yerde ben bir yerde

Gönüller birlikte yaşıyorya ateş sevgileri

Kimbilir kavuşuruz belki bir yerde (Belkide mahşerde)  

Y.Tar.15-11-2002 saat 21.48', 'Yalnızlığımı yazsam sayfalara Ağlar benimle iki gözü iki çeşme Yüreğim öyle hasret dolu ki Yalvarırım ne olur yaramı deşme Haykırsam feryadı...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/belkide-mahserde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farazi', 'farazi-zulkar-ozkan-j5mjp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gun isigina cikmamis siirlerden sadece bir baslangicdir bu dortluk siirim.Hic bir dergi gazete ve bilumum mecmualarda yayinlanmadi bu siirim.Yaziklar olsunki yasda gecti.ve benden her sey gecti.Gecmeyen sizlerle paylasacagim siirlerim olacaktir.

Bir buse almadan, esmisse gonlum avare

Yakandi ruhumu bu arzu duyan dudaklar.......

Dalmisim gibi derinden, bir sonsuz hayale, 

Ruhumsa bu gonlumu bir cikmazda kucaklar.', 'Gun isigina cikmamis siirlerden sadece bir baslangicdir bu dortluk siirim.Hic bir dergi gazete ve bilumum mecmualarda yayinlanmadi bu siirim...', ARRAY['Türk Edebiyatı','Şiir','Zülkar Özkan']::text[], 8.5, '{"poet":"Zülkar Özkan","poet_slug":"zulkar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/farazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Ben', 'sen-ve-ben-sair-i-brahim-ckjvr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'şiir benim eserim orjinal deil 1 yıl oluyo bulduğum', 'şiir benim eserim orjinal deil 1 yıl oluyo bulduğum...', ARRAY['Türk Edebiyatı','Şiir','Şair İbrahim']::text[], 8.5, '{"poet":"Şair İbrahim","poet_slug":"sair-i-brahim","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/sen-ve-ben-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzah', 'i-zah-turgay-kaygi-rjzv8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''neden sessizsin bu gece? ''

sorusunun cevabı

çok ama çok basit: 

''mutsuzum da ondan! ''

''neden mutsuzsun böyle? ''

diye sorsaydın

''beni mutsuz kılan şeyler

mutlu kılanlara oranla

daha çok! '' 

derdim ki 

hiç de samimi bir yanıta

benzemezdi, 

iyi ki sormamışsın! 

sorunun güzeli: 

''neler geçiyor içinden? ''

olurdu

ki sana

''kendimi

uçsuz bucaksız

çayırlarda

asi ve hür koşuştururken

amaçsızca, 

birdenbire nasıl olduysa

yakalanmış da, boyunduruğa alınmış, 

gece kadar siyah, 

gece kadar kara

evcilleşmeye de hiç niyeti olmayan

vahşi bir at gibi

hissediyorum! ''

diyebileyim! 

(inegöl,07.11.2002)', '''neden sessizsin bu gece? '' sorusunun cevabı çok ama çok basit:  ''mutsuzum da ondan! '' ''neden mutsuzsun böyle? '' diye sorsaydın ''beni mutsuz...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kaygı']::text[], 8.5, '{"poet":"Turgay Kaygı","poet_slug":"turgay-kaygi","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/izah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben...', 'ben-nilgun-akcay-ij6ng', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her gece..

Kurarım darağacımı..

Ruhumun derinliklerine.

Celladım olur gururum..

Ve..Ben..Her gece ölen..

Yaşam mahkumuyum.

                              Nil..', 'Her gece.. Kurarım darağacımı.. Ruhumun derinliklerine. Celladım olur gururum.. Ve..Ben..Her gece ölen.. Yaşam mahkumuyum.                  ...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Akçay']::text[], 8.5, '{"poet":"Nilgün Akçay","poet_slug":"nilgun-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ben-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlar da Yalnızdı', 'yildizlar-da-yalnizdi-serra-timur-ol2hb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yanlızlığın sancısı sardı yüreğimi.

Bir    yıldızlara  daldı gözlerim, 

Bize ne kadar uzaksınız 

Ey samanın nakışları.

Keşke siz olsaydınız yanımda

Bitmeyen sancının başladığı an

 Siz yüreğimde sıcak bir  yaşam

Derin bir  ukte sardı her yanımı 

Bitmeyen bu kavganın dinginlenmiş  ruhunda.

Sarardı gökyüzü 

Ben  yalnız bakakaldım guruba.

Yarın fecir  yine doğacak,  kararan  gökyüzünde

Yine maviliğini saracak.

Acep  çıkarmı yüreğimden 

Bitmeyen bir özlemin hasret gurubu.

Silsilesi  çiledir  yaşamın; 

bilirim…

Sevdalar en  son işimiz.

Yürek dağdağası oldu 

Gözlerimizde bir  dost parılstısı

Hangi fıtınılarda kaybettik  ruhlarımızı

Ve kalakaldık  yalnızlığımızla.

Yıldızlar  da  çok uzaklara gitti.

Ey  kan kırmızı gökyüzü, 

Hani uzaklara giden  nura 

Söyle 

Beni de al götür; 

Yalnızlık burda kalsın.', 'Yanlızlığın sancısı sardı yüreğimi. Bir    yıldızlara  daldı gözlerim,  Bize ne kadar uzaksınız  Ey samanın nakışları. Keşke siz olsaydınız ...', ARRAY['Türk Edebiyatı','Şiir','Serra Timur']::text[], 8.5, '{"poet":"Serra Timur","poet_slug":"serra-timur","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yildizlar-da-yalnizdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Ne Zaman Açılacağız Denizlere?', 'biz-ne-zaman-acilacagiz-denizlere-turgay-kaygi-u4ojw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''neleri sever, nelerden hoşlanırsın? '' diye sorduğunda

kimi zaman insanlar, 

en emin verdiğim cevap

deniz olmuştur hep...

çocukluğumda tatilleri dayımlarla

fıstıklı''da kampta geçirirken

ve yüksekokulda okurken bandırma''da

nedenini hiç düşünmeden

o koca lacivert düzlüğün ufukla birleştiği

uzun beyaz çizgiye

dalar giderdim...

giderdim diyorum ya! 

hala ne zaman yolum gemlik''e, istanbul''a, 

denize kenar bir şehre düşse

ilk defa gören biri gibi, 

bir sigara yakar

hayran hayran seyrederim denizi...

insan bir şeyi böyle sever de

ondan uzak kalmaya neden katlanır? , 

neden yakınında, kenarında olmayı

denemeye bile cesaret edemez, 

bilemiyorum! 

bildiğim bir şey var ki

evvelden beri

çok istediğim şeylerden

hep uzak durdum, 

ömrüm boyunca yanımda olmasını istediğim insanlarla arama

kilometreler, kırgınlıklar ve hatalar girdi salakça

sınırlarını kendim çizdim dünyamın...

şikayet etmeye

yada af dilemeye ne hakkım var şimdi kimseden, 

ne de niyetim...

doğanın kanunu bu; 

farklı kutuplar birbirini çekerken, 

aynı olanlar itiyor, 

nedense...

yaşamayanların anlayamayacağı şeyleri 

izah etmeye bu kadar çabaladıktan sonra

itiraf etmem gerekiyor ki

hala

kendimle tanışmaya, 

kendimi anlamaya, 

zamanın mağrur ve zalimce geçmekte olduğunu kabullenip, 

çok istediğim halde

hep ertelediğim şeylere

kendimi salıvermeye

pek cesaretim yok! 

ama varsın tek şahidim tanrı olsun ki

bir sabah

o gücü hissettiğimde kendimde, 

daha değil balıkçılar, 

balıklar bile uyanmadan, 

güneşin saçları bile

görünmeden ufukta, 

geriye dönememek için

yaktığı gibi bir savaşçının gemilerini, 

yakıp, yıkıp bende limanımı

açılacağım denizlere! ...

(inegöl,14.09.2002)', '''neleri sever, nelerden hoşlanırsın? '' diye sorduğunda kimi zaman insanlar,  en emin verdiğim cevap deniz olmuştur hep... çocukluğumda tatil...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kaygı']::text[], 8.5, '{"poet":"Turgay Kaygı","poet_slug":"turgay-kaygi","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/biz-ne-zaman-acilacagiz-denizlere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorabilirim', 'sorabilirim-fethi-giray-7hveq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben harp çocuğuyum! 

Yumruğumla bir baş soğanı, 

İkiye ayırabilirim, 

Kara somuna, 

Anam gibi sarılabilirim, 

Seferberlikte doğduğumu

Her hatırlayışta, 

Sızıncaya kadar içerek kaldırım taşlarında

Efkarlanıp efkarlanıp, 

Nara atabilirim! ...

Kınamayın dostlar! 

Kınamayın! ! ..

Ben harp çocuğuyum! 

Gülerken, 

Ağlayabilirim.

Şu küçücük kuşa masmavi göklerin

En genişi, 

İnsanoğluna yer yüzünün

İnişi, yokuşu, 

Bir gün ben; düşünüp düşünüp bu işi

Tanrıdan sorabilirim!', 'Ben harp çocuğuyum!  Yumruğumla bir baş soğanı,  İkiye ayırabilirim,  Kara somuna,  Anam gibi sarılabilirim,  Seferberlikte doğduğumu Her ha...', ARRAY['Türk Edebiyatı','Şiir','Fethi Giray']::text[], 8.5, '{"poet":"Fethi Giray","poet_slug":"fethi-giray","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sorabilirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esirler', 'esirler-fethi-giray-9fzfo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Başları önlerine düşük, 

Sürü sürü insanlar...

Mavi bulutların ötesinde, 

Analar, kardeşler, nişanlılar...

Belki şimdi, 

Bir resmin önünde

Sessiz sessiz ağlıyorlar, 

Analar, kardeşler, nişanlılar...

Sokaklar bomboş, 

Çocuklar gülmüyor, 

Oyuncakları bir tarafta sessiz, 

Çocuklar babalarını düşünüyor.

Belki bir şafak vakti, 

Daha gözleri bağlanmadan evvel, 

Kapkara bir duvarın önünde, 

Güneş onlara bir kerre daha gülümseyecek

Masmavi bulutların üstünde.

Ve sonra uzun kirpiklerinde

Birer damla yaş, 

Tırnaklar ete batıncaya kadar, 

Yumruklar sıkılacak, 

Yavaş yavaş, 

Belki yağmurlu bir günde, 

Gözler çevrilecek göklere.

Birbirinin göğsüne yaslanmış başları, 

Kapkara bir duvarın önünde.', 'Başları önlerine düşük,  Sürü sürü insanlar... Mavi bulutların ötesinde,  Analar, kardeşler, nişanlılar... Belki şimdi,  Bir resmin önünde S...', ARRAY['Türk Edebiyatı','Şiir','Fethi Giray']::text[], 8.5, '{"poet":"Fethi Giray","poet_slug":"fethi-giray","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/esirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onlardan Biri', 'onlardan-biri-fethi-giray-0q9qh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yürüyor o! 

Gecede tahta bacağını sürüyerek, 

Yürüyor o! 

Dalgalar gibi

Alçalarak, 

Yükselerek.

Zaman donmuş, 

Bir avuç kurşun külçesinde; 

O ayaklar yürüyor sanki: 

Kafkas cephesinde.

Baş ileride, 

Göğüs ileride...

Yürürken o! 

Bir bayrak dalgalanıyor

Göğsünün üzerinde.

Yürüyor...

Tahta bacağını sürüyerek, 

Yürüyor o! gecede, 

Dalgalar gibi: 

Alçalarak, 

Yükselerek.', 'Yürüyor o!  Gecede tahta bacağını sürüyerek,  Yürüyor o!  Dalgalar gibi Alçalarak,  Yükselerek. Zaman donmuş,  Bir avuç kurşun külçesinde;  ...', ARRAY['Türk Edebiyatı','Şiir','Fethi Giray']::text[], 8.5, '{"poet":"Fethi Giray","poet_slug":"fethi-giray","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/onlardan-biri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Silah Arkadaşım', 'silah-arkadasim-fethi-giray-pi8cs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Köstebek gibi...

Toprağa sokulu başım, 

Sarıkamışlı Mehmed onbaşı, 

Silah arkadaşım.

Burmuş kaytan bıyıklarını, 

Konuşmuyor, gülmüyor, 

Bir kaya parçasına dayamış alnını, 

Upuzun, sessiz yatıyor.

Yirmi iki aydır onunla

Omuz omuza, yan yanayım, 

Yirmi iki aydır, 

Huduttayım.

Bazan o! 

Başı elleri arasında düşünüyor, 

Bazan o! 

Hemşerim memleketten mektup var mı ki diyor? 

Sarıkamışlı Mehmed onbaşı

Yirmi iki aydır, 

“Akşam oldu yine bastı kareler

Göz göz oldu sinemdeki yareler”

Türküsünü söylüyor.', 'Köstebek gibi... Toprağa sokulu başım,  Sarıkamışlı Mehmed onbaşı,  Silah arkadaşım. Burmuş kaytan bıyıklarını,  Konuşmuyor, gülmüyor,  Bir ...', ARRAY['Türk Edebiyatı','Şiir','Fethi Giray']::text[], 8.5, '{"poet":"Fethi Giray","poet_slug":"fethi-giray","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/silah-arkadasim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı Pabuçlu Hayal Perisi', 'kirmizi-pabuclu-hayal-perisi-reha-basogul-7mzu2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'el fenerlerinin yumuşakça dokunduğu

dişleri olmayan bir yüzdü o gece gözüken

çamurdan ayaklı ve elleri titreyen

dağınık saçlarıyla ve korkulu gözleriyle seçilen

ufacık ellerini kıymıklar süslemiş

bir güzeller güzeli çıktı yıkık evden

acımasız gecenin kurbanlarını

gördüklerimize inandıramamıştık

kayıp kalplerini durdurmuşken

güzeller güzeline gelmemişti onlar tanıdık

içini ısıttıktan sonra 

konuşturabildi yüzü temizlenen

masalsı bir rüyada

hatıraları karıştıran

düğmelerle süslü kutuyu konuşturursa

bir hayal perisi gözükürmüş ona

kırmızı pabuçlarıyla

yıldızlara basa basa

gökyüzünde dansedermiş aklın sıra

yapraklar sararmadan hüzünden ayrılınca

mevsimler beyazlamaya başlayınca

uzun bir rüyada

bir hayal perisi yaklaştı bana

çıkartmış kırmızı pabuçlarını

götürmemi istiyor kendisiyle o gece konuşana

saçlarına ak düşmüş mevsimden

trenler korkup kaçışırmış

yıldızlar koşarken penceremden

canlandırdığı elektrik direklerine 

hayal perisi sarılmış, bana bakar

çok da sabırsızlanırmış

eskimiş kilimle dolu 

içinde ocak olmayan

bezden eve yaklaşınca 

kıpırdanmaya başlamış 

kırmızı pabuçtan yürekler

diller mazide gezinince 

kucağa gelirmiş inci dişler

kıvılcım seslerinin ortasında

mutluluk dansı yapılınca

tutulurmuş ufacık ellerden

çıkılırmış karanlığa.

gözler çiçek açtığında

bir nefes üflenirmiş 

mavi hırkası sökülmüşün kulağına

seslenecekmiş ona masalsı bir rüya 

aklın sıra

o hayal perisi yaklaşıp

uzun uzun konuşacakmış onla

mevsimler yeşillenmeye başlamadan

pabuçlarını takmayacakmış ayağına

o gün gelinceye kadar

dansetmeliymiş onun yerine karlarda

eğer dediğini yapıp

bu sırada bakarsa yıldızlara

hep bir gülümseme belirecekmiş

güzeller güzelinin kırmızı pabuçlarında...', 'el fenerlerinin yumuşakça dokunduğu dişleri olmayan bir yüzdü o gece gözüken çamurdan ayaklı ve elleri titreyen dağınık saçlarıyla ve korkul...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/kirmizi-pabuclu-hayal-perisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Çocuklarım', 'benim-cocuklarim-reha-basogul-er17m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalbimde sayısız oda vardır benim

her odada da hiç büyümeyen ayrı bir çocuk beslerim

hepsi haylaz hepsi yumurcaktır

ama ben hepsini de severim

hepsinin bir hayali bir de aşkı vardır

kimisi de yalnızlık hastasıdır

kimsenin yüzü birbirine benzemez

ama bana göre hepsi de ışıl ışıldır...

yaramazdır benim çocuklarım

biri diğerinin odasını karıştırır

ondan hepsinin odası dağınıktır

ama ben hepsini de sabah olmadan toplarım...

Her odada ayrı bir dünya yaratmıştır benim çocuklarım

her birinin güneşi ayrıdır

ondan her çocuğum farklı saatlerde uyanır

ama ben hepsinin de cıvıl cıvıl kalktığını duyarım.

çalışkandır benim çocuklarım

kimi alimken kimi de sanatçıdır

her gün ödevlerini yaparlar 

ama benim hepsine de dokunur bir yardımım

kıskançtır da benim çocuklarım

kendi ödevi için diğerinden birşey aşırmıştır

hepsi inkar eder hepsi bana bağırıp çağırır

ama ben her alınanı tekrar yerine koyarım

kimi zaman da şefkat bekler benim çocuklarım

yanlarına yatıp 

bütün gece kendisiyle uyumamı isterler

ama hepsi içinde mutlaka vardır bir masalım 

geceleri de çok korkar benim çocuklarım

düşlerinde canavarlar yaratır

bütün gece de onlarla savaşılır

ama ben hepsini de yatıştırırım

Ölüme inanmaz benim çocuklarım

onlara sorarsanız her biri ayrı bir ilahtır

hepsi de odalarında sonsuza kadar yaşayacağını sanır

ama ben her gün birinin cenazesini kaldırırım...', 'Kalbimde sayısız oda vardır benim her odada da hiç büyümeyen ayrı bir çocuk beslerim hepsi haylaz hepsi yumurcaktır ama ben hepsini de sever...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/benim-cocuklarim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Barış', 'baris-bahri-sohtorik-n8h8i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen Rum soyundan

Ben Kayı boyundan

Neslimiz se Adem oğlu

Biz kardeşiz be Yorgi

Soframızda kuru fasulye

Soğan yemişiz, 

Bir kadeh''te rakı, 

Birlikte kederlenip

Birlikte gülmüşüz

Sen Maria''yla gezerken

Ben Ayşe''mle el sallamışım, 

Sırtaki ile coşmuş

Üstünde horon tepmişiz, 

Bu topraklar bizim be Yorgi

Şimdi, bir elinde tüfek

Bir elinde, bomba var

Yapma be Yorgi, 

Ben ölürsem, ağlarsın bilirim

Bir eline zeytin dalı

Bir eline gül al, 

Yine sırtaki ile coşup

Yine horon tepelim

Birliğimizden korkanlara inat

Gel sarılalım, 

Düşmana korku

Dosta sevgi salalım, 

Haydi be Yorgi, 

Gel sarılalım.', 'Sen Rum soyundan Ben Kayı boyundan Neslimiz se Adem oğlu Biz kardeşiz be Yorgi Soframızda kuru fasulye Soğan yemişiz,  Bir kadeh''te rakı,  B...', ARRAY['Türk Edebiyatı','Şiir','Bahri Sohtorik']::text[], 8.5, '{"poet":"Bahri Sohtorik","poet_slug":"bahri-sohtorik","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/baris-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hacı Bektaş Veli Gibi', 'haci-bektas-veli-gibi-bahri-sohtorik-i6pig', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalbimizi dosta açtık

Sevgi dolduk, sevgi taştık

Hacı Bektaş Veli gibi

İşte bu yolda tanıştık

Hep cahillikle savaştık

İlimle, evreni dolaştık

Bir çok zorlukları aşıp

Nihayet çağa ulaştık

Çağdaş insan geri koşmaz

İnsana, hizmette şaşmaz

İlim, onun rehberidir

Yanlış yollarda dolaşmaz

Geriden ders alınmalı

Karanlıktan arınmalı

Atatürk''ün söylediği

Çağdaşlık, hedef olmalı

Gelin, ileri koşalım

Bilgiyle dolup taşalım

Hacı Bektaş Veli gibi

Çağımızı da aşalım', 'Kalbimizi dosta açtık Sevgi dolduk, sevgi taştık Hacı Bektaş Veli gibi İşte bu yolda tanıştık Hep cahillikle savaştık İlimle, evreni dolaştı...', ARRAY['Türk Edebiyatı','Şiir','Bahri Sohtorik']::text[], 8.5, '{"poet":"Bahri Sohtorik","poet_slug":"bahri-sohtorik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/haci-bektas-veli-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-bahri-sohtorik-6hs0b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tan atarken yedi tepede

Yanık bir ezan sesiyle uyanırsın

Serin bir iyot kokusuyla başlar gün

Nereden bakarsan bak, İstanbul''a

Huşu duyarsın.

Yok olanlar duygulandırır seni, üzülürsün

Yinede, bir tutkudur İstanbul

Vazgeçemez, terkedemezsin

Bir nakış gibi işlenmiştir semaları

Allaha uzanan elleri sanırsın, 

Yedi tepeden gökyüzüne doğru

Yalvarırcasına uzanan minareleri.

Şimdiyse serpiştirme gökdelenler

Betonlar, betonlar, betonlar

Yinede, bir tutkudur İstanbul

Vazgeçemez, terkedemezsin.

Akarken, ruha huzur vererek boğaz

Martlardır bağrışan, eşşiz İstanbul diye, 

Avaz avaz.

Bir milyonluk koca şehir, şimdi yirmi milyon, en az.

Mevsimler de karıştı, kışmıdır sonbahar mı

Belki de yaz.

Yok oldular, o tebessümü dudağında

O sımsıcacık insanlar, 

Surat asık, kalpler ayaz.

Yine de bir tutkudur İstanbul

Vazgeçemez, terkedemezsin.

Gençlerin yarıştığı masmavi sular

Üstünde süzülür, dört çifte kayıklar

Altın boynuzda, yeşil  korular.

Hasbahçe de seyrine doyulmaz laleler var

Kimler, neden yok ettiler bu yeri.

Artık düştür

Bilirsin dönmezler geri

Yine de bir tutkudur İstanbul

Vazgeçemez terkedemezsin.

Cumbalı evler, fesleğenli pencereler

Biraz kapı muhabbeti, komşular, dostlar

Agop''la Mehmet Efendi, bir de tornacı Lefter.

Akşam dönmeden eve

Biraz sohbet, bir yorgunluk kahvesi

Yanında, nargile içerler

Yok oldu bu gelenekler

Yine de bir tutkudur İstanbul

Vazgeçemez, terkedemezsin.', 'Tan atarken yedi tepede Yanık bir ezan sesiyle uyanırsın Serin bir iyot kokusuyla başlar gün Nereden bakarsan bak, İstanbul''a Huşu duyarsın....', ARRAY['Türk Edebiyatı','Şiir','Bahri Sohtorik']::text[], 8.5, '{"poet":"Bahri Sohtorik","poet_slug":"bahri-sohtorik","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/istanbul-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstemedim', 'i-stemedim-gursel-colak-7igs2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dünyayı verdiler

Kim var? dedim

Kimse yok dediler

İstemedim.

Cennete gönderelim dediler

Seni sordum

Orada yok dediler

İstemedim.

Ne istersin? dediler

Onunla olan herşeyi dedim

Mutluluk dediler

Onunla beraber dedim

Olmaz dediler

İstemedim.

Neden? onunla dediler

Herşeyim dedim

Canını bağşlıyalım dediler

Sen yoksun diye 

İstemedim.

Ölümsüz bir yaşam dediler

Kim ile? dedim

Onsuz dediler

İstemedim.

Neden? dediler

Ben zaten ölüyüm

Ne demek? dediler

Onsuzum

Onsuz yaşamak ölümdür dedim

Verilenleri o yüzden istemedim.', 'Dünyayı verdiler Kim var? dedim Kimse yok dediler İstemedim. Cennete gönderelim dediler Seni sordum Orada yok dediler İstemedim. Ne istersin...', ARRAY['Türk Edebiyatı','Şiir','Gürsel Çolak']::text[], 8.5, '{"poet":"Gürsel Çolak","poet_slug":"gursel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/istemedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şans', 'sans-ahmet-ozdemir-7kwc5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ŞANS

Bitmez sandığımız yaz, 

Şimdi çok uzaklarda kaldı.

Günlerce süren bir kuru ayaz, 

Yerini bırakırken bu sersem yele

Kar yağdı köye! 

Kaba kaba kar, 

Kar, lâpa lâpa

Diz boyu bembeyaz

Kar...

Çıktılar damlarını kürümeye, 

Toprak damlarını

Konular komşular...

“Bre Hasan” dedi Osman, 

Bir hoş, keyflice; 

“Şeker olsaydı yağan, yağan kar, 

İnceden ince...”

Bir acı gülümsemeydi Hasan’ın dudaklarında yayılan; 

Ağzından püskürürken buhar, 

Karşılık verdi üzgün, manidâr: 

“Hiç buralara yağar mıydı

Şeker olsaydı kar! ...”

Ahmet ÖZDEMİR', 'ŞANS Bitmez sandığımız yaz,  Şimdi çok uzaklarda kaldı. Günlerce süren bir kuru ayaz,  Yerini bırakırken bu sersem yele Kar yağdı köye!  Kab...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özdemir']::text[], 8.5, '{"poet":"Ahmet Özdemir","poet_slug":"ahmet-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sans-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Binbir Düşünce', 'binbir-dusunce-bahadir-atay-ja20t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kafamda binbir düşünce, 

Binbiri de birbirini kovalar, 

Gece olup yalnızlık çökünce, 

Düşünceler beni oyalar.

Binbir tane dediysem, 

Bin tanesi sen 

Bir tanesi de...

Offf, of bir de beni bir sevsen.', 'Kafamda binbir düşünce,  Binbiri de birbirini kovalar,  Gece olup yalnızlık çökünce,  Düşünceler beni oyalar. Binbir tane dediysem,  Bin tan...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Atay']::text[], 8.5, '{"poet":"Bahadır Atay","poet_slug":"bahadir-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/binbir-dusunce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eve Özlem', 'eve-ozlem-bahadir-atay-9ktb7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Evimi özledim, evimi...

Annemi, babamı, kardeşlerimi...

Beni en çok sevenleri, 

Ve de en çok sevdiklerimi...

Onları öpmeyi, kucaklamayı, 

Onlara sarılmayı, 

Onlarla çocuk, 

Onlarla genç, 

Onlarla yetişkin olmayı özledim.

Biraz daha yazmak isterdim, 

Ama bırakayım biraz kağıt kalsın, 

Ve mürekkep biraz da, 

Diğer insanlara.', 'Evimi özledim, evimi... Annemi, babamı, kardeşlerimi... Beni en çok sevenleri,  Ve de en çok sevdiklerimi... Onları öpmeyi, kucaklamayı,  On...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Atay']::text[], 8.5, '{"poet":"Bahadır Atay","poet_slug":"bahadir-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/eve-ozlem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-bahadir-atay-vdk3i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ömür uzun geliyor artık, 

Ne güneş aydınlatıyor hayatımı ne de sen.

Ne de gülümseyebiliyorum karanlıkta

Nerede olduğumdan bile habersizim, 

Bir orada, bir burada.

Yataktan kalkasım gelmiyor bu günlerde, 

Öyle miskin, öyle tembelleştim bir bilsen, 

Niye anlatıyorum ki bunları sana 

Umurunda bile değilim artık belki de. 

Soğuk burası, üşüyorum...

Belki bir gün döneceksin geriye, 

Ama tekrar yaşanamayacak anılar

Çünkü soğuk, hayatım, günlerim, gecelerim, 

Varlığın ısıtmayınca içimi, 

Biliyorum, 

Buz tutacak şu yüreğim.

Şu küçücük dünyamda, 

Kocaman bir yer vermiştim ben sana.

Sense küçücük bir insan olmayı seçtin, 

Şu kocaman dünyada.', 'Ömür uzun geliyor artık,  Ne güneş aydınlatıyor hayatımı ne de sen. Ne de gülümseyebiliyorum karanlıkta Nerede olduğumdan bile habersizim,  ...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Atay']::text[], 8.5, '{"poet":"Bahadır Atay","poet_slug":"bahadir-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ayrilik-82-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskici', 'eskici-bahadir-atay-t5dgk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yeni bir eve taşındım dün, 

Yepyeni herşeyiyle, 

Tek bir iz bile kalsın istemedim, 

Eski hayatımdan.

Nasıl unutabilirim ki başka türlü, 

Ayrılışımı, 

Biricik aşkımdan.

Yanıma tek aldığım

Sadece küçük bir toka

Ayrılırken vermiştin ya

Bir hatıra olsun demiştin.

Ben de sana karşılığında, 

Bir kol düğmesi vermiştim.

Yeni bir eve taşındım dün

Herşeyiyle yepyeni, 

Hatta taşları yeni dizilmiş caddesinden

Geçen eskicisi.

Eskiler alıyormuş kendisi, 

Eski aşkımı vermek istedim almadı, 

Bunun bir değeri yok dedi.

Bilemiyorum, belki de haklıydı.

Masanın üzerindeki toka geldi aklıma, 

Herşeyi unutmalıydım, 

Şu tokadan da kurtulmalıydım.

Tokayı eskiciye verdim, 

Önce iyice inceledi, 

Sonra düşündü bir, 

Belki dedi, 

Belki bulabiliriz bir şeyler bunun için, 

Ve cebine götürdü elini, 

Önce iyice karıştırdı, 

Sonra birşey çıkardı, 

Bir küçük kol düğmesi.

Bunu daha demin aldım dedi, 

Bir hanımdan, 

Yakın hemen şurası, 

Şu karşıki apartman.

O da sizin gibi yeni ayrılmış aşkından.

Daha yeni taşınmış buraya, 

Kurtulmak için derdinden, tasasından.

Tokayı cebine attı.

Ve hızla uzaklaşırken durdu birden, 

Durdu, döndü ve bağırdı, 

Söylemeyi unutmuşum birşeyi, 

Şu düğme karşılığında, 

Söz vermiştim o kıza, 

Ona geri getirmeyi, 

Eski sevgilisini.

O eskiciyi göremedim bir daha, 

Kimbilir hangi yerde

Ya da hangi diyarda, 

Hangi bitmiş aşkları, 

Yeniden yaratmakta.', 'Yeni bir eve taşındım dün,  Yepyeni herşeyiyle,  Tek bir iz bile kalsın istemedim,  Eski hayatımdan. Nasıl unutabilirim ki başka türlü,  Ayr...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Atay']::text[], 8.5, '{"poet":"Bahadır Atay","poet_slug":"bahadir-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/eskici-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden', 'yeniden-bahadir-atay-oe1p7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Toprağın kurumasının nedeni, 

Ayrılık acısı mıdır ölülerin? 

Ya da sırrı, 

Tuzlu gözyaşlarında mıdır sevgililerin

Solmasının çiçeklerin? 

Peki ya yaprak dökümleri...

Terkedilişler olmalı, 

Onların da nedeni.

Eğer yeniden bahar olmasını istiyorsa, 

Güz mevsimindeki, 

Terkedilmiş bir sevgili

Yeniden sevmeli ve sevilmeli.', 'Toprağın kurumasının nedeni,  Ayrılık acısı mıdır ölülerin?  Ya da sırrı,  Tuzlu gözyaşlarında mıdır sevgililerin Solmasının çiçeklerin?  Pe...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Atay']::text[], 8.5, '{"poet":"Bahadır Atay","poet_slug":"bahadir-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yeniden-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Galat-i Meshur Ask', 'galat-i-meshur-ask-funda-kocaoglu-8gx7d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Didaktigi eksik bir lugatsin.

inanmiyorum artik Egzistansiyalizm''a..

Yoksun! ! 

Siirlerimin Epizod_u degilsin artik

Galat- i Meshur tanimissin beni ne yazik! ! 

Itnab a gerek yok, susuyorum....

icaz  geliyor gözyasim! 

