INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nazire 7', 'nazire-7-yavuz-turhan-wo187', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüreğimden boşaldın.

  Gözlerim, sana doldu..', 'Yüreğimden boşaldın.   Gözlerim, sana doldu.....', ARRAY['Türk Edebiyatı','Şiir','Yavuz Turhan']::text[], 8.5, '{"poet":"Yavuz Turhan","poet_slug":"yavuz-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/nazire-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlar', 'dostlar-cahit-i-pekoglu-4qccv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilirmisinizki koklamayi cok severdim

koklarken gülümün yapraklarini döktüm dostlar.

Aski tam yakaladim derken

yüreginden cikip sonsuzluga gömüldüm dostlar.

Aska yenik düstüm

yorgunum cok yorgun dostlar.

Hic bitmez derken askimiz

sevdam beni unuttu gitti dostlar...

Aska yenik düstüm

yorgunum cok yorgun dostlar.

Artik kadinim yok''ki koynumda

Atesi suyu kanima gecsin dostlar.

Sevdami yüregime kiralamadim

Ben onu satin aldim dostlar.

Aska yenik düstüm

yorgunum cok yorgun dostlar...', 'Bilirmisinizki koklamayi cok severdim koklarken gülümün yapraklarini döktüm dostlar. Aski tam yakaladim derken yüreginden cikip sonsuzluga g...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dostlar-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yangın', 'bir-yangin-ahmet-ozturk-21m4y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir yangın sönüyor

bir yangın kopuyordu

Gözyaşların yanaklarında

ne güzel

ellerimde ne sihirliydi

Hele başımızın dönmesi

ne devran dönüşüydü...

(08 Nisan 2000)

(BİGA)', 'Bir yangın sönüyor bir yangın kopuyordu Gözyaşların yanaklarında ne güzel ellerimde ne sihirliydi Hele başımızın dönmesi ne devran dönüşüydü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Öztürk']::text[], 8.5, '{"poet":"Ahmet Öztürk","poet_slug":"ahmet-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-yangin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece Yıldızlar Böyle Olmamalıydı', 'bu-gece-yildizlar-boyle-olmamaliydi-ahmet-ozturk-mszod', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu gece yıldızlar böyle olmamalıydı

Bu gece ay, betim benzim

böyle solmamalıydı

Dudaklarından sonra

sigara dudaklarıma değmemeliydi

Bu gece yıldızlar böyle olmamalıydı

“SEN” diye bir zehir 

içime dolmamalıydı

(03 Nisan 2000)

(BİGA)', 'Bu gece yıldızlar böyle olmamalıydı Bu gece ay, betim benzim böyle solmamalıydı Dudaklarından sonra sigara dudaklarıma değmemeliydi Bu gece ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Öztürk']::text[], 8.5, '{"poet":"Ahmet Öztürk","poet_slug":"ahmet-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bu-gece-yildizlar-boyle-olmamaliydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin', 'gittin-omer-faruk-cakir-0ym0b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Burada kuşlar yok

Gittiğin gecenin sabahı

Uçup gittiler penceremden

Bir daha da hiç gelmediler

Şimdi hangi cama baksam

Hüzün

Hangi rüyaya dalsam bin parça

Yüzün

Caddelerde alımlı yalnızlıklar

Bedensiz gölgeler

Gölgesiz bedenler var

Herkes kendi halinde işte

Öğleden sonra

Belki yağmur yağar biraz

Kaldırımlarda şiir kokusu

Her aşk örselenmiş biraz', 'Burada kuşlar yok Gittiğin gecenin sabahı Uçup gittiler penceremden Bir daha da hiç gelmediler Şimdi hangi cama baksam Hüzün Hangi rüyaya da...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Çakır']::text[], 8.5, '{"poet":"Ömer Faruk Çakır","poet_slug":"omer-faruk-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gittin-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bodur Çingene', 'bodur-cingene-fazil-husnu-cakiroglu-5nhkc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben güzelligimi seyrederken

Derin sularda, 

Sen suyu bulandiran cirkin ördek.

Ben goncayim dalda, 

Ha acti ha acacak.

Sen gecmis bahar.

Ben suda gögü okurum, 

Sen avucta yalani.

Ben koyum, sen rüzgar.

Habire denizi dalgalandiran.

Ben cinarim basi gökte.

Sen dibimde

Tas bakla sayan cingene

Ben hep göge uzayacagim.

Sen kücülürken dibimde

Ve yapraklarim la örtecegim sen 

Bodur cingene...

                                                                   26.09.1998

                                                                     Berlin', 'Ben güzelligimi seyrederken Derin sularda,  Sen suyu bulandiran cirkin ördek. Ben goncayim dalda,  Ha acti ha acacak. Sen gecmis bahar. Ben ...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Çakıroğlu']::text[], 8.5, '{"poet":"Fazıl Hüsnü Çakıroğlu","poet_slug":"fazil-husnu-cakiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bodur-cingene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düseceği Derinlik Gözlerindir', 'dusecegi-derinlik-gozlerindir-ethem-vayvayli-8yyi3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'düşeceğim derinlik gözlerinse

atıyorum kendimi aşağı

kollarında bir demet gül  olup, 

gözlerinde bir damla yaş, 

belirsiz öykülerle, 

belirsiz derinliklere, 

düşüp duruyorum.', 'düşeceğim derinlik gözlerinse atıyorum kendimi aşağı kollarında bir demet gül  olup,  gözlerinde bir damla yaş,  belirsiz öykülerle,  belirs...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dusecegi-derinlik-gozlerindir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen yoksun ya', 'sen-yoksun-ya-fazil-husnu-cakiroglu-0e1xc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ta ortasinda, 

Dokunmadan dokunulmadan.

Üstü örtülü peceli bir suskuya

Gömü verdi herseyi.

Yeri öperken karanliklar, 

Isiklar sönerken bir yerlerde, 

Icine yada disina kapanirken kapilar, 

O coktan kilitlemisti yüregini.

Kendini kendiyle yikarken sular, 

Kendiyle örtünürken karanliklar.

Adi yok iste! 

Biraz hüzün biraz aci.

Nedir ki yok olmak? 

Ölmek.... Nedir ki? 

Bir yigin toprak.

Ha uzak ta olmak

Yada yok.....

Yoka sayiyor günlerimi hersey.

Yoktan sayiliyor bugünlerde hersey.

Sen yosun ya....

Ondan olsa gerek.

sen yoklugumdasin. 

                                                                          07.12.2001

                                                                                 berlin', 'Ta ortasinda,  Dokunmadan dokunulmadan. Üstü örtülü peceli bir suskuya Gömü verdi herseyi. Yeri öperken karanliklar,  Isiklar sönerken bir y...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Çakıroğlu']::text[], 8.5, '{"poet":"Fazıl Hüsnü Çakıroğlu","poet_slug":"fazil-husnu-cakiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-yoksun-ya-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizlikte yalnizlik', 'sessizlikte-yalnizlik-fazil-husnu-cakiroglu-t0dus', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Baslar sessizligin cigligi.

Boslugun icinde yokluk

Yoklugun icinde karanlik.

Alabildigine ürkütücü

alabildigine gizemli.

Kasvetle kapli kara gece, 

Gecenin ortasin da yanliz sen.

Ucsuz bucaksiz enginlerde yolalan

Binlerce ruh.

Alabildigine özgür 

Alabildigine sinirsiz

Alabildigine hür.

Düsen bir yagmurun sesidir dostun

Yada uzaklardaki bir ciglik.

Bilincsiz mesai deyken binlerce ruh, 

Yalnizliklarla bezenmis sessizlige siginmak, 

Kimbilir? 

Belki gizli gizli yakarmak.

O ruhunun derinliklerindeki ilahi güce. 

                                                                        09.05.1994

                                                                          Ankara', 'Baslar sessizligin cigligi. Boslugun icinde yokluk Yoklugun icinde karanlik. Alabildigine ürkütücü alabildigine gizemli. Kasvetle kapli kara...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Çakıroğlu']::text[], 8.5, '{"poet":"Fazıl Hüsnü Çakıroğlu","poet_slug":"fazil-husnu-cakiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sessizlikte-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Aşkı', 'i-nsan-aski-zulkuf-cengiz-21adv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'taş güçlüdür, 

demir daha güçlüdür, 

ama hiç kuşkusuz demiri eriten, 

ona binbir şekil veren ateş daha da güçlüdür.

ama ateşi söndüren su, 

daha kuvvet li degilmidir.

ve suyu denizlerde dalgalandıran rüzgardır, 

rüzgarın esmesini engelleyen, 

önüne set olan karlı yalçın dağlar vardır, 

ve insan bu dağları delmiştir 

şimdi sen engüçlü şeyi düşün 

sen düşünürken ben seni 

o dağları deldirten aşkla seviyorum

Zülküf CENGİZ (ziko)   ısparta 2002', 'taş güçlüdür,  demir daha güçlüdür,  ama hiç kuşkusuz demiri eriten,  ona binbir şekil veren ateş daha da güçlüdür. ama ateşi söndüren su,  ...', ARRAY['Türk Edebiyatı','Şiir','Zülküf Cengiz']::text[], 8.5, '{"poet":"Zülküf Cengiz","poet_slug":"zulkuf-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/insan-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrı Kadını Yarattı', 'tanri-kadini-yaratti-ozge-ucar-kmp7h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Circé''ye...

Ve tanrı kadını yarattı... 

Bir kedi misali sıcaklığı, başkaldırışları

Gecenin karanlığından daha derin bakışları

Bir ceylanın ürkekliği

Bir meleğin saflığı

Bir tanrıçanın kızıla boyalı tutkuları 

Ve tütsü kokan şiirleriyle 

Tanrı kadını yarattı...', 'Circé''ye... Ve tanrı kadını yarattı...  Bir kedi misali sıcaklığı, başkaldırışları Gecenin karanlığından daha derin bakışları Bir ceylanın ü...', ARRAY['Türk Edebiyatı','Şiir','Özge Uçar']::text[], 8.5, '{"poet":"Özge Uçar","poet_slug":"ozge-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tanri-kadini-yaratti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni beklerken', 'seni-beklerken-riza-aslan-l4ofb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'seni beklerken 

korkularım gelir aklıma

ve hep korktuğum gelir başıma

seni beklerken 

dayanamam 

çelişkili duygulara

seni beklerken

uyuyamam sabahlaraca

çitlerin üzerinden 

sensindir atlayan

yüzleri sana benzemeyen 

senler

seni beklerken

içimden kalkan trenlere 

el sallarım, gücenmeden

varılacak o en son istasyona

senden önce varırım.

seni  beklerken 

bekleyen ben değilimdir artık

başkalaşırım 

gitmek isterim

gidemem senden

seni beklerken 

vazgeçmek geçer aklımdan

sen gelirsin aklıma

seni de kaybetmek istemem

daha öncekiler gibi

seni beklerken

hep beklemek isterim

ulaşmak istemem sana

dokunmak istemem sana

kaybetmekten korkarım

seni beklerken

içimden göçmen kuşlar havalanır

başka bir mekanda

başka bir bana

ulaşmanın hevesiyle

seni beklerken

gelmeni istemem aslında 

hep beklemek isterim seni

içimden kalkan 

ve seni bana getiren trenin

gelmesini istemem 

seni beklerken

kayıplarım gelir aklıma

yitirdiklerim

seni de yitirmek istemem 

seni beklerken

korkarım senden

umduğum, beklediğim sen

ya sen değilsen

seni beklerken

fırtınalar kopar

geçtiğin yollarda

kasırgalar döner

virane şehirlerde

seni beklerken

sen değilsindir aslında beklediğim

hayalindir istediğim

o hayalin ki

yeri gelince hoyratça

öpebildiğim

seni beklerken

korkarım senden

umduğum, beklediğim sen

ya sen değilsen

seni beklerken

daha önceki senler

gelir aklıma

bırakıp da beni giden

seni beklerken

gelmeni istemem aslında

benim olmanı istemem

çünkü benim olan her şey

anlamını yitiriyor.

20 – 11 - 2002

Bergama   -  İzmir', 'seni beklerken  korkularım gelir aklıma ve hep korktuğum gelir başıma seni beklerken  dayanamam  çelişkili duygulara seni beklerken uyuyamam...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":77,"source_url":"https://www.antoloji.com/seni-beklerken-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lazım', 'lazim-riza-aslan-w7ryn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir şeyler yazmak lazım

bir şeyler yapmak lazım

anlamı

anlamını veren göre 

değişmeyen

19 – 11 – 2002 

Bergama', 'bir şeyler yazmak lazım bir şeyler yapmak lazım anlamı anlamını veren göre  değişmeyen 19 – 11 – 2002  Bergama...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/lazim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzi kalır', 'i-zi-kalir-riza-aslan-h1ol8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'su akar 

sessiz derinden

yaralar, derinlerde 

her ne kalmışsa

su akar

götürür

geride hiç bir parça bırakmayarak 

su akar 

derinlerde kalan

kalmaz geride

su akar 

sessiz derinden

alıp götürür 

bilinmeyen bir geçmişe

zamanın, mekanın

tanımı yoktur artık

günlük uğraşılar

bir anlam ifade etmez

su akar 

sessiz derinden

su akar

izi kalır

13 – 11 – 2002 

bergama', 'su akar  sessiz derinden yaralar, derinlerde  her ne kalmışsa su akar götürür geride hiç bir parça bırakmayarak  su akar  derinlerde kalan k...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/izi-kalir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sinisi yalnızlık', 'sinisi-yalnizlik-riza-aslan-qwa9e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'karanlıklar

zifiri karanlıklar içinde

göz gözü görmez

halim harap

yalnızlığım sinsidir

ufak bir açığımı gözler

her zaman

ayakta dimdik

sorgusuz, sorunsuz 

kalmak zor

yalnızlığım sinsidir

ufak bir açığımı gözler

04 – 10 – 2002 

bergama', 'karanlıklar zifiri karanlıklar içinde göz gözü görmez halim harap yalnızlığım sinsidir ufak bir açığımı gözler her zaman ayakta dimdik sorgu...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sinisi-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beden Beden Yalnızlık', 'beden-beden-yalnizlik-riza-aslan-p3cex', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'uzaklara 

çok uzaklara gitmek lazım

tek başına yapayalnız

bavulunda  beden beden 

yalnızlıkların olmalı

bavulunda senden geriye kalan

sen - kalmışsa –

öyle bir yer olmalı ki bu

daha önce hiç kimsenin 

yaşamadığı

öyle bir yer olmalı ki bu 

daha önceden olmayan

olmayan bir yerde

olmayan bir kendinle 

yapayalnız baş başa

bavulunda  beden beden 

yalnızlıkların olmalı

bavulunda senden geriye kalan

sen - kalmışsa-

17 – 09 – 2002 

bergama', 'uzaklara  çok uzaklara gitmek lazım tek başına yapayalnız bavulunda  beden beden  yalnızlıkların olmalı bavulunda senden geriye kalan sen - ...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/beden-beden-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'yağmur ve yalnızlık', 'yagmur-ve-yalnizlik-riza-aslan-3o92x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yağmur yağıyor

üzerime

gecenin bir vakti

ortalık zifiri karanlık

ellerim cebimde

sırtım kendime dönük

dudaklarımda çok bilinen

bir türkünün

o çok bilinen 

ezgileri

ağır ağır ilerliyorum

bilmediğim sokaklarda

her adımda kendimden

bir adım daha

uzaklaşıyorum

hava soğuk

ve karanlık

mermi gibi yağıyor

üzerime damlalar

her damla

bir kurşun gibi yaralasa da

akıp gidiyor

benliğime yabancı geçmişim

yağmur yapıyor

ıslanmışım

ellerim cebimde

sırtım kendime dönük

dudaklarımda çok bilinen

bir türkünün 

o çok bilinen ezgileri

20 – 09 – 2002

bergama', 'yağmur yağıyor üzerime gecenin bir vakti ortalık zifiri karanlık ellerim cebimde sırtım kendime dönük dudaklarımda çok bilinen bir türkünün ...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yagmur-ve-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçer olduk', 'vazgecer-olduk-riza-aslan-hglaz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'nelere minnet eder olduk

kötünün içinde

vazgeçer olduk

kendimizden

tükenir olduk göz göre göre

kaçıramadık kendimizi

bu izbe mekandan

kaçıramadık çünkü

korktuk

 30 – 09 – 2002

  bergama', 'nelere minnet eder olduk kötünün içinde vazgeçer olduk kendimizden tükenir olduk göz göre göre kaçıramadık kendimizi bu izbe mekandan kaçıra...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/vazgecer-olduk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ufuk', 'ufuk-riza-aslan-vur85', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sağanaklar içinde

ufkun devam eden hayatı

bir bıçak gibi kestiği

bir ortamdayım

hayatın

yaşamın

beklentilerin

devam ettiği zannedilen 

her şeyin

durduğu bir ortamdayım

21 – 05 – 2002 

polatlı', 'sağanaklar içinde ufkun devam eden hayatı bir bıçak gibi kestiği bir ortamdayım hayatın yaşamın beklentilerin devam ettiği zannedilen  her ş...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ufuk-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zoraki sürgün', 'zoraki-surgun-riza-aslan-7u99p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sürgündeyim

yalnızım 

her yalnızlık 

bir yangın

01 – 10 – 2002

bergama', 'sürgündeyim yalnızım  her yalnızlık  bir yangın 01 – 10 – 2002 bergama...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/zoraki-surgun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz Geliyor', 'guz-geliyor-umut-cetin-3yg2r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'beceriksiz bir tacirin düşlerini satıyorum

naylon ayakkabılardan kamyonlarımı

yol boyu öptüğüm bütün yüzlerin

kımıltısız kalabalık yalnızlığını

seninle gidiyor kentin palyaçoları

gülüşün akıyor peşinden

kimsesiz istasyonlarına ülkemin

güz geliyor üşüyebilirim 

Tavşan Dağı kaçağını arıyor

kasabalı kurnazlığıyla gizlediğim adresi

güz diyerek getirdim sana

bavuluma doldurduğum hapishanemi

evsizin bankamatik sıcaklığını

ne iş olsa yapabilirliğini işsizin

yangınlar üstüne süslenebiliyorsa kadınlar

hayat eski bir alışkanlık mı

atölye önlerinde küfürleşen dolmuşlar

yalan mı askere alınmam yeniden', 'beceriksiz bir tacirin düşlerini satıyorum naylon ayakkabılardan kamyonlarımı yol boyu öptüğüm bütün yüzlerin kımıltısız kalabalık yalnızlığ...', ARRAY['Türk Edebiyatı','Şiir','Umut Çetin']::text[], 8.5, '{"poet":"Umut Çetin","poet_slug":"umut-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/guz-geliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Zaman', 'ne-zaman-serhan-celebi-3bq0n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne zaman görülmüş çöllere kar yağdığı

Memleketin yerini gurbetin aldığı

İstanbul''un adamı padişah yaptığı

Kilyos''ta sensiz güneş açtığı', 'Ne zaman görülmüş çöllere kar yağdığı Memleketin yerini gurbetin aldığı İstanbul''un adamı padişah yaptığı Kilyos''ta sensiz güneş açtığı...', ARRAY['Türk Edebiyatı','Şiir','Serhan Çelebi']::text[], 8.5, '{"poet":"Serhan Çelebi","poet_slug":"serhan-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ne-zaman-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört Mevsim Sonbahar', 'dort-mevsim-sonbahar-fatih-cinar-nzsy6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'şimdi kimlerlesin kimbilir

kimler okşuyor senin saçının tellerini

şimdi kimlerlesin kimbilir

kimler tutuyor senin karbeyaz ellerini

ben çok mutsuzum sensiz buralarda

yanımda bıraktığın hediye dört mevsim sonbahar

ağlıyorum gecenin karanlık ıslak koynunda

peşimi bırakmıyor isyankar senle dolu şarkılar

şimdi kimlerlesin kimbilir

gönlümdesin hala gönlüme açtığın kılıç yarası gibi

şimdi kimlerlesin kimbilir

silemedim hala günlerime gözlerinle bıraktığın izi

müzik: fatih çınar', 'şimdi kimlerlesin kimbilir kimler okşuyor senin saçının tellerini şimdi kimlerlesin kimbilir kimler tutuyor senin karbeyaz ellerini ben çok ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dort-mevsim-sonbahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret Sonu', 'hasret-sonu-memo-alp-7pwib', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sustu kocamillet hiç konuşmayacak

Açtı agzını hasret hiç susmayacak

Ve ynine yüreklere yazık olacak

Ama senin gibiler anlamayacak

Karanlık odamda yalnızım ve sessiz

Yüzüğümdeki zehri içiyorum

Ve sana acıları bırakıyorum

Ama sen acıları sevmeyeceksin

Hasret küheylanına bindim sen yokken

Ölümün balkonuna indim sen yokken

Dön dediler daha senin erken

Ama sen bunları hiç bilmeyeceksin

Beden dayanır sevdanın güçüne

Ya dayanırmı aşkın hasretine

Hasret sonunda güzel ölümler bile

Ama sen ölemeyeceksin hasretle', 'Sustu kocamillet hiç konuşmayacak Açtı agzını hasret hiç susmayacak Ve ynine yüreklere yazık olacak Ama senin gibiler anlamayacak Karanlık o...', ARRAY['Türk Edebiyatı','Şiir','Memo Alp']::text[], 8.5, '{"poet":"Memo Alp","poet_slug":"memo-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hasret-sonu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk''ta Kaybedenlere', 'ask-ta-kaybedenlere-buket-gul-imkf7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Umut herzaman vardı

Açılmayan kapıları açtıran

Girilmeyen yollara girdiren

İmkansızı başarmak isteyen

Hep o umuttu

Ya aşk

O da yaptırmazmı

Aştırmazmı tüm zorlukları

Yıktırmazmı engelleri

Kör etmezmi insanın gözünü

Yakıp kavurmazmı gönlünü

Fark nedir sence

Biri sonsuza dek sürer

Diğeri gözün açıldığında biter

İstemiyorum artık kör olmayı

Acı çekip, kırılmayı

Ve diyorum ki

Yarınlar umut olsun

Aşktan yana kaybedenlere

Tüm sevda çekenlere', 'Umut herzaman vardı Açılmayan kapıları açtıran Girilmeyen yollara girdiren İmkansızı başarmak isteyen Hep o umuttu Ya aşk O da yaptırmazmı A...', ARRAY['Türk Edebiyatı','Şiir','Buket Gül']::text[], 8.5, '{"poet":"Buket Gül","poet_slug":"buket-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ask-ta-kaybedenlere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oksijen Karışımı', 'oksijen-karisimi-ilgin-polat-va0ht', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir yağmur damlasında, 

Seni görürüm. 

Bulutların üzerindedir 

Hâlâ kokun. 

Bahar; 

Dudaklarına işler, 

Ayrı ayrı tatlar verir. 

Oksijen karışımı, 

Dalarsın içime. 

Bazen bir gül, bazen menekşe. 

Bir sandalda oturur, 

Gözlerine dalarım. 

Yağmurlardan kaçarlar 

Balıklar. 

Saçlarına işler kokusu, 

Yağmurun. 

Oksijen karışımı, 

Dalarsın içime. 

Bazen bir gül, bazen menekşe. 

              -2002- 

                               ILGIN POLAT', 'Bir yağmur damlasında,  Seni görürüm.  Bulutların üzerindedir  Hâlâ kokun.  Bahar;  Dudaklarına işler,  Ayrı ayrı tatlar verir.  Oksijen kar...', ARRAY['Türk Edebiyatı','Şiir','Ilgın Polat']::text[], 8.5, '{"poet":"Ilgın Polat","poet_slug":"ilgin-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/oksijen-karisimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Yolculuk', 'son-yolculuk-kursat-emre-demir-vtafn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yazar arabalarinin 

Kontaklarina baglidir 

Emperyalizmin yildizlari; 

Ve son yolculuklarinda 

Ayni cadde üzerinde 

En az bes Mc Donalds''in 

Önünden geçer, 

Bayraklarindan kurtulan 

Tek yildiza 

Ayin eslik ettigi 

Tabutlari... 

Kürşat Emre DEMIR / Ankara / 2002', 'Yazar arabalarinin  Kontaklarina baglidir  Emperyalizmin yildizlari;  Ve son yolculuklarinda  Ayni cadde üzerinde  En az bes Mc Donalds''in  ...', ARRAY['Türk Edebiyatı','Şiir','Kürşat Emre Demir']::text[], 8.5, '{"poet":"Kürşat Emre Demir","poet_slug":"kursat-emre-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/son-yolculuk-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece', 'sadece-kursat-emre-demir-s1djf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aci çekmekse ask, 

Medeniyet adina 

Kendi topraklarinda 

Katledilmek gibi; 

Sen incitmene bak sevdigim, 

Olurum elbet 

Bu sevdanin 

Kizil derilisi...! 

Gözlerin asili 

Damarlarimda ki bütün 

Reklam panolarinda, 

Üstelik 

Ilan Yapistirmak Yasakti 

Büyük kan dolasimi 

Basladiginda 

Aldanma 

Kemiklerine yeni sevda sözleri 

Kaziyan halime, 

Dügün salonlarinda 

Daha çok kola içmek için 

Degisik masalara oturan 

Esmer bir çocuk yüzüyüm 

Sadece... 

Kürşat Emre DEMIR / Ankara / 2002', 'Aci çekmekse ask,  Medeniyet adina  Kendi topraklarinda  Katledilmek gibi;  Sen incitmene bak sevdigim,  Olurum elbet  Bu sevdanin  Kizil de...', ARRAY['Türk Edebiyatı','Şiir','Kürşat Emre Demir']::text[], 8.5, '{"poet":"Kürşat Emre Demir","poet_slug":"kursat-emre-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sadece-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ona Doğru Koşmak İçin', 'ona-dogru-kosmak-i-cin-nihat-behram-bgkyz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana ufku anlatmak istiyorum

Yüreğini

Avuçlarında bir güvercinin

Yüreğiyle yatıştıran çocuğun

Bileklerinde çözüp

Doldurduğu şeyi

Sana anlatmalıyım...

Binlerce insan dökülmüş duraklara

Asfalttan, yapılardan, seslerden; 

Binlerce saattir oradalar

Ve kudurgan bir beyin

Ve kıpırtısız bir yürekle

Düşmanca bir şeyler biriktiriyorlar karşılıklı

Ve herkes birbirine benziyor

Ve herkes yabancı birbirine üstelik.

Sana ufku anlatmak istiyorum...

Yalınayak

Ve aşağılara koşarken çaylarda

Çakıl taşları, çağlayanlar

Ve kayaların oyuklarında köpüren suyun

Düşündürdüğü şeyi

Sana anlatmalıyım...

...

Sana ufku anlatmak istiyorum...

Bir ağacın kökleri ve dallarıyla

Uzanıp uzanıp vardığı şeyi

Sana anlatmalıyım...

İçinde duvarlar uğulduyor ilişkilerin

İlanlar, rutubet, çıkar...

Ve söz namusun simgesi değil,

Duygular öyle lekelenmiş

İçtenlik öyle hesap işi ki...

Kimin öpüşleri bir papatya kadar temiz

Kim kime kıstırıldığı anda omuz verebilir? 

Ya aşk: çarparak başlatan yeni şeyleri

O sevinç

Nerede şimdi? 

Yine de güzel bazı duygular

Aşkla kendini onarıyor

Fakat rüzgârlı, yağmurlu ve sabahları

Bir sinir birikintisi olarak karşılamaktan

Bakışları gizlice köreliyor onun da

Ve hatta sağanağı bir nehir gibi

Yabani bir hayvanmış gibi düşünüp

Ürküyor

Ve giderek aciz,

Sinirli, habis insanlar dolduruyor caddeleri; 

Oysa şehirden Yabani bir hayvan kadar uzakta nehir

Öpüşüyor uçsuz bucaksız bir çalkantıyla

Ve yüzlerce çocuk tanıyorum

Kaçak bir duygu taşıyan sinemalarda

Ona doğru koşmak için...

Sana ufku anlatmak istiyorum.

...

Son mavisi gözlerinde kaldı gökyüzünün

Bu şehirde

Anlatmak istediğim', 'Sana ufku anlatmak istiyorum Yüreğini Avuçlarında bir güvercinin Yüreğiyle yatıştıran çocuğun Bileklerinde çözüp Doldurduğu şeyi Sana anlatm...', ARRAY['Türk Edebiyatı','Şiir','Nihat Behram']::text[], 8.5, '{"poet":"Nihat Behram","poet_slug":"nihat-behram","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/ona-dogru-kosmak-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hafiyyen', 'hafiyyen-fazil-husnu-cakiroglu-pw313', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Birisi birinin dilinde

Birisi birinin dününde

Dün birinin benliginde

Bir hüsni an.

Zaman tugyan

Mekansiz

Hafiyyeten susatir

Susatir gecmise.

Kah hafredir yolumuza, 

Kah haiben bir kosu, 

Yarinimiza.

                                                                           11.07.1996

                                                                             Istanbul', 'Birisi birinin dilinde Birisi birinin dününde Dün birinin benliginde Bir hüsni an. Zaman tugyan Mekansiz Hafiyyeten susatir Susatir gecmise....', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Çakıroğlu']::text[], 8.5, '{"poet":"Fazıl Hüsnü Çakıroğlu","poet_slug":"fazil-husnu-cakiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hafiyyen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O kadar anlamsızsın ki?', 'o-kadar-anlamsizsin-ki-i-brahim-halil-f9p5t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ızdırap...

azap sanki bir darp, 

umutlarmı harap, 

bir hanguman bir ahuzar

anlamını bimediğim bir an, 

anlamını bilmediğim bir hal, 

anlamını bilmediğimokadar çok şey varki.........

beni anlamsızlaştıran o kadar 

GÜNAHIM varki.

Yinede umut

umut der yürğim, 

belki bilmek istemem

O KADAR ANLAMSIZSIN Kİ

ne ben seni anladım 

nede sen anlattın.

Umutsuzluklar içinde umut, 

vahşetine tanıklık eder yüreğim; 

taşıyamaz artık ne seni nede kendini

artık yorğun düşmüştür 

belki yenik

belki mağlup

artık solğun düşmüştür.

Nihayeti olmayan

çaresi yokluk olan bir elemdir

onun derdi 

evet artık ne anlar nede anlatılır olmuştur, 

sine dert

felek dert

anlamaz anlayamaz onu hiç bir fert

günahkar; artık sus, sus ki ALLAH affetsin', 'ızdırap... azap sanki bir darp,  umutlarmı harap,  bir hanguman bir ahuzar anlamını bimediğim bir an,  anlamını bilmediğim bir hal,  anlamın...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Halil']::text[], 8.5, '{"poet":"İbrahim Halil","poet_slug":"i-brahim-halil","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/o-kadar-anlamsizsin-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tersine Yaşıyorum', 'tersine-yasiyorum-fazil-husnu-cakiroglu-1jnnx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tersine yasiyorum yasami

Kimsenin bilmedigi yollari

Dönüs vakitleri erkenden geciyorum.

Ufkum sisli puslu

Yada duvar örülü düslereimde.

Aslinda ben olmayan bir yarayim

Habire kaziyorum.

Ikide birde zamani göstermeyen

Köstekli yüzümü aynada yokluyorum.

Hergün birazim tasinirken

Gecmisin o engin bosluguna.

Cogun neden kisili kalmis

Dersiniz bu dar kaliplara

Cogumu azima katin diyorum.....

Azim nerde idi? 

Cogum nerde! 

Simdi onuda bilmiyorum.

                                                                                11.10.1997

                                                                                 Berlin', 'Tersine yasiyorum yasami Kimsenin bilmedigi yollari Dönüs vakitleri erkenden geciyorum. Ufkum sisli puslu Yada duvar örülü düslereimde. Asli...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Çakıroğlu']::text[], 8.5, '{"poet":"Fazıl Hüsnü Çakıroğlu","poet_slug":"fazil-husnu-cakiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/tersine-yasiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Olan sevgimle Örtündüm', 'sana-olan-sevgimle-ortundum-metin-yalti-ygvi4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aklımdaydın

Gün Geceye Devrildiğinde

Gece Uzundu, Yağmurluydu

Hava   Soğuk

Sen Uzaktın

Oysa

Bir Sen Vardın İçimi Isıtacak

Seni Özlemekten

Seni Düşünmekten

Yorgun Kaldığım Gecelerden

Biriydi Gece

Zalim Ve İnatçıydı.

Tek Şey Kalmıştı Geriye

Donana Kadar Parmaklarım

Seni Yazmak.

Bir, Bir Saydım Niteliklerini

İktidarı Garantilemiş Bir Başkan Gibi

Kah Yedi Tepesinden Baktın İstanbul’un

Kah Varoşlarındaydın Sevgilim

Oysa Seni Ben Seçmiştim

İstanbul Değil

Kızmak Geçmedi Değil İçimden

Ama Yapamadım

Sana Karşı Hep Yenik Kalacağım Galiba

Uyumuşum.

Sana Olan Sevgimle Örtündüm

3/11/02  / İstanbul', 'Aklımdaydın Gün Geceye Devrildiğinde Gece Uzundu, Yağmurluydu Hava   Soğuk Sen Uzaktın Oysa Bir Sen Vardın İçimi Isıtacak Seni Özlemekten Se...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sana-olan-sevgimle-ortundum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdan ve Mestan', 'sevdan-ve-mestan-metin-yalti-mj7n8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Denize  bakan pencereme

Adalar üzerinden doğarken güneş

Deniz   dudaklarının  rengindeydi

Aklımda sen, parkta kediler vardı

Ara sıra verdiğim birkaç lokma için

Nasılda minnettar kalırlar bana

Pamuk sürtünür, Kirli hep uzak durur

Mestan’sa  atlar kucağıma...

Her sokağa çıkışımda

Doluşur onlarcası etrafıma

Hani nankördü kediler? 

Bir parça ekmek için

Nasıl da  teşekkür ediyorlar

Ya insanlar? 

Hele sen.

Su gibi aziz, 

Ekmek gibi mübarek

Benliğimi de katık yaparak

Sevgimi verdim sana

İçtenlikle...

Bir kez gülümsemedin bile

Sahi, sen bilirdin

Hangisi büyük? 

Bir koca ömre sığmaz sevdamı? 

Yoksa bir parça ekmek mi? 

Kedilere  yapılan haksızlık mı yoksa? 

 Yeşilköy / 19/11/02', 'Denize  bakan pencereme Adalar üzerinden doğarken güneş Deniz   dudaklarının  rengindeydi Aklımda sen, parkta kediler vardı Ara sıra verdiği...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sevdan-ve-mestan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaramsın Sen', 'yaramsin-sen-fazil-husnu-cakiroglu-p77cv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Adini andigimda adimin yaninda, 

Ben söyleyemem iste! 

Herkes gibi söylemek istedigimi aninda.

Seni ektim icime

Ve büyütüyorum seni

Gece sessizliginde görülmeden duyulmadan.

Dal saliyosun icimde dayanilmaz acilarla.

Uykuya doymus gözler gibisin, 

Habire aciliyosun.

Habire dayanilmaz büyüklükte

Icimde büyüttügüm yaramsin sen.

Adini söyleyemedigim adimin yaninda

Suskumun icindeki cigligim.

Büyüttügüm gece karanliginda

Gündüze acan aksam sefam.

Sen yakinimdaki uzagim, 

Uzanipta dokunamadigim.

Adini yazamadigim

Kagida cizdigim düsmsün

Düsümdeki gizim

Adini koyamadigim.', 'Adini andigimda adimin yaninda,  Ben söyleyemem iste!  Herkes gibi söylemek istedigimi aninda. Seni ektim icime Ve büyütüyorum seni Gece ses...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Çakıroğlu']::text[], 8.5, '{"poet":"Fazıl Hüsnü Çakıroğlu","poet_slug":"fazil-husnu-cakiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yaramsin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Isırgan Otu Ölüm', 'bir-isirgan-otu-olum-fazil-husnu-cakiroglu-aeddp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne zaman acitacagi belli olmayan

Bir isirgan otu ölüm.

Ölümü ben secmedim, 

Isirgan otlarini ekmedigim gibi.

Kenin acilarla ovuyorsam avuclari mi...

Kestisi gelmeyen bir limanda

Islanan sadece umutlarim degilki.

Ki simdi düsleyin bi kestigah! 

Denizi cekilmis bi yamacta

Kemyap bir usuluk icinde 

Ketum bir gecede susumus.

Sevmediysemde ölümü yekruze dünyada

Ubaya giden yolda

Tek yekru dosttur keza.

                                                                        12.01.1997

                                                                         Istanbul', 'Ne zaman acitacagi belli olmayan Bir isirgan otu ölüm. Ölümü ben secmedim,  Isirgan otlarini ekmedigim gibi. Kenin acilarla ovuyorsam avucla...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Çakıroğlu']::text[], 8.5, '{"poet":"Fazıl Hüsnü Çakıroğlu","poet_slug":"fazil-husnu-cakiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-isirgan-otu-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyi Var Saysam', 'neyi-var-saysam-fazil-husnu-cakiroglu-rbgal', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Neyi var saysam, yoka cikiyor.

Elimi atsam bosa

Yasayanlar coktan gitti.

Icimde ölüler kaldi

Herkes konusurken kendi dilince

Icimde büyüttügüm sesizlik

Ölümdür kendime.

Kendi tülünden coktan düsmüs hayallerim

Ve simdi dar geliyor 

annemin ördügü uzun kazaklar.

Ve sikiyor bedenimi yilan derim.

Gagamla kirmalimiyim yumurtami? 

Yoksa yokolup gitmelimiyim 

kendi ördügüm kozanla? ? 

Ve eger tel tel söküp alacaklarsa 

Kozami sirtimda 

Öreceklerse baska hayata

Ölümun adini ne koymaliyim? 

Derimki cöldür yasamda

Serap görürüz

Bazan cocuklugumzu

Bazen gencligimizi

Bazende ölümü

Sikistirsada karanfili cocuklugu 

Tasisada öteye beriye

Kirilir ufalanir dökülür avuclarimizdan.

Sökmeye kalksan sökemezsin

Cünkü cok sira sökülüdur bazilarindan.

                                                            

                                                                      07.12.1997

                                                                      Istanbul', 'Neyi var saysam, yoka cikiyor. Elimi atsam bosa Yasayanlar coktan gitti. Icimde ölüler kaldi Herkes konusurken kendi dilince Icimde büyüttüg...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Çakıroğlu']::text[], 8.5, '{"poet":"Fazıl Hüsnü Çakıroğlu","poet_slug":"fazil-husnu-cakiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/neyi-var-saysam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum (Diyemiyorum)', 'seni-seviyorum-diyemiyorum-salih-ozalasan-q561d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Öyle bir ateş yaktınki yüreğime

Kor alevlerdeyim, tütemiyorum

Aşk''ımı tutsak ettim yüreğime

Seni seviyorum diyemiyorum

Kalbimde iki sevgi iç içe

Ne yâr''den, ne senden geçemiyorum

Bir Güneş gibi doğmuş sevgin yüreğime

Seni seviyorum diyemiyorum

Senide seviyorum, içim içime sığmıyor

Gönül gözümde hayalin, hiç gitmiyor

Yüreğim küçücük, iki sevda sığmıyor

Seni seviyorum diyemiyorum

Adını andığımda gözlerim parlıyor

Seni başköşeye koysam yüreğim almıyor

Bölsem, elma değil bıçak bölmüyor

Seni seviyorum diyemiyorum

Geceler uzadı artık Güneş doğmuyor

Doğsada gönül gözüm görmüyor

Kalbim vefasız, hiç insaf etmiyor

Seni seviyorum diyemiyorum

Ben ne yapacağım

Çıkar yol bulamıyorum

Gecemde sen günümde sen; AMA

Seni seviyorum diyemiyorum

Y.Tar 21-11-2002 Saat 21.51

(Armağan)', 'Öyle bir ateş yaktınki yüreğime Kor alevlerdeyim, tütemiyorum Aşk''ımı tutsak ettim yüreğime Seni seviyorum diyemiyorum Kalbimde iki sevgi iç...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/seni-seviyorum-diyemiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balıkçı Murat', 'balikci-murat-gokcen-duran-u131d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hasta bir babası, üç de kardeşi

Yeni doğmuş bir çocuk, bir de eşi

Aylarca ayak basamaz karaya

Bakar kardeş, çocuk, eş ve babaya

Deniz uçsuz bucaksız, türkü söyler

Türkünün her sözü içine işler

Hep ufka bakar gözlerinde buğu

Tüter burnunda yari ve çocuğu

Aylar oldu dönmedi memlekete

Bir öpücük konduramadı bebeğe

Denizde karalar gözler, karalar

Ya kısmet deyip çalışır, çabalar

Murat’a bakarlar bir de takaya

Kim bilir, belki döner haftaya...', 'Hasta bir babası, üç de kardeşi Yeni doğmuş bir çocuk, bir de eşi Aylarca ayak basamaz karaya Bakar kardeş, çocuk, eş ve babaya Deniz uçsuz ...', ARRAY['Türk Edebiyatı','Şiir','Gökçen Duran']::text[], 8.5, '{"poet":"Gökçen Duran","poet_slug":"gokcen-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/balikci-murat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
