INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-huseyin-cayikli-7mqo6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'eski fotograflarda buluyorum

solgun yuzunu

sevda senin dezin

zamana 

karsi gelmekteyiz

oysa

sen bilmektesin

seni sevdigim gunden beri 

yer demir gok bakir

keske su iki goz

bir araya gelebilseydi

simdi

hersey yalan

yaninda ki bir baska kisi

olmayacak dua gibi

ne gelirsin nede gidersin

cunku 

hersey zaman

hersey sendin

yer demir gok bakir

sevda zamandir

yarasi sarilir...', 'eski fotograflarda buluyorum solgun yuzunu sevda senin dezin zamana  karsi gelmekteyiz oysa sen bilmektesin seni sevdigim gunden beri  yer d...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/zaman-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tanem', 'bir-tanem-gonul-sen-27erz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Duman duman aşkın yanar içimde

Ateş de sen, kül de sensin bir tanem

Senin gözlerine buldum sevdayı

Gonca da sen, gül de sensin bir tanem

Bir tanem, bir tanem

Kanımdasın, bir tanem

Bir tanem, bir tanem

Canımdasın, bir tanem', 'Duman duman aşkın yanar içimde Ateş de sen, kül de sensin bir tanem Senin gözlerine buldum sevdayı Gonca da sen, gül de sensin bir tanem Bir...', ARRAY['Türk Edebiyatı','Şiir','Gönül Şen']::text[], 8.5, '{"poet":"Gönül Şen","poet_slug":"gonul-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-tanem-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönmeyeceğim', 'donmeyecegim-aysel-gurel-a8mn6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Resmimi buruştursan

Külleri tutuştursan

Ateşle buluştursan

Yine sana dönmeyeceğim

Dilsizi konuştursan

Hasreti unuttursan

Ölsen, yine doğsan

Yine sana dönmeyeceğim

Dalgalandım seninle

İsmim artık isminle

Söylüyorum yeminle

Yine sana dönmeyeceğim', 'Resmimi buruştursan Külleri tutuştursan Ateşle buluştursan Yine sana dönmeyeceğim Dilsizi konuştursan Hasreti unuttursan Ölsen, yine doğsan ...', ARRAY['Türk Edebiyatı','Şiir','Aysel Gürel']::text[], 8.5, '{"poet":"Aysel Gürel","poet_slug":"aysel-gurel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/donmeyecegim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözüm İstanbul', 'gozum-i-stanbul-i-brahim-erkal-ij43h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağlıyorsun için için

Yara almış yüreğinden

Sana bu kin, nefret niçin

Kan damlıyor gözlerinden

Nice aşklar yaşamışsın

Nice sırlar taşımışsın

Nasıl da yalnız kalmışsın

Gözüm İstanbul

Sevdiğinden herkes seni

Bağlamışlar seni

Ağlamışsın görmemişler

O masum gözlerini

Gün gelecek gidecekler

Terkedecekler, bırakıp da gidecekler

Sana yazık edecekler

Gözüm İstanbul

Saçlarını yakmak için kesmişler

Yerlerine beton surlar dikmişler

Ey sevgilim sana yazık etmişler

Gözüm İstanbul

Sen gönüller sultanısın

Sen böyle hep sevdalısın

O hasta yatağında

Yine de çok alımlısın

Sen böyle mi olacaktın

Sararıp da solacaktın

Yaktın ah içimi yaktın

Gözüm İstanbul', 'Ağlıyorsun için için Yara almış yüreğinden Sana bu kin, nefret niçin Kan damlıyor gözlerinden Nice aşklar yaşamışsın Nice sırlar taşımışsın ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Erkal']::text[], 8.5, '{"poet":"İbrahim Erkal","poet_slug":"i-brahim-erkal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gozum-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamaya Bak', 'yasamaya-bak-gonul-sen-5m5z3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İşte gece bitti, güneş doğdo bak

Faydasız, umutla yollara bakmak

Dünü sil, bugünü yaşamaya bak

Unutmak tek çare, gönlüm unutmak

Kim kime bir ömür boyu senetli

Kim var bu dünyada candan kıymetli

Sönsün içinde bir hasret ateşi

Unutmak tek çare, gönlüm unutmak', 'İşte gece bitti, güneş doğdo bak Faydasız, umutla yollara bakmak Dünü sil, bugünü yaşamaya bak Unutmak tek çare, gönlüm unutmak Kim kime bir...', ARRAY['Türk Edebiyatı','Şiir','Gönül Şen']::text[], 8.5, '{"poet":"Gönül Şen","poet_slug":"gonul-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yasamaya-bak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alem Bozulmuş', 'alem-bozulmus-i-brahim-erkal-wra8n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kime inanayım, kime güveneyim

Kime değer verip, kimi seveyim

Kime ağlayayım, kime güleyim

Alem hoş olmuş ben neyleyim

Kimin elleri kimin cebinde

Kimin kaderi kimin elinde

Kimin hayatı kimin dilinde

Alem boş olmuş ben neyleyim

Kimisi büyürken kimisi çöker

Rahatın derdini rahatsız çeker

Kimisi çaresiz boynunu büker

Alem bozulmuş ben neyleyim

Birisi her şeyi tüketip atar

Birisi yoksulluk içinde yatar

Birisi dostluğu ucuza satar

Alem kuş olmuş ben neyleyim', 'Kime inanayım, kime güveneyim Kime değer verip, kimi seveyim Kime ağlayayım, kime güleyim Alem hoş olmuş ben neyleyim Kimin elleri kimin ceb...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Erkal']::text[], 8.5, '{"poet":"İbrahim Erkal","poet_slug":"i-brahim-erkal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/alem-bozulmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Sevmiştim', 'nasil-sevmistim-i-brahim-erkal-7mce7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şarkılar yazdım sana

Milyonlar adını duydu

Reva mıydı bu bana

Yapacağın bu muydu

Işıklarmı aldın

Hasret bıraktın sana

Bu güzelim dünyayı

Dar ettin bana

Ben ne yokuşlar çıktım

Ben ne duvarlar yıktım

Sevgi çölünde acıktım

Sığındım sana

Ben dostluk derysında

Çok sevdim, çok sevildim

Bir mutluluk rüyasında

Sana çok kötü yenildim

Lanet olsun gücüm yetmiyor

Lanet olsun süzüm geçmiyor

Nasıl sevmiştim seni', 'Şarkılar yazdım sana Milyonlar adını duydu Reva mıydı bu bana Yapacağın bu muydu Işıklarmı aldın Hasret bıraktın sana Bu güzelim dünyayı Dar...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Erkal']::text[], 8.5, '{"poet":"İbrahim Erkal","poet_slug":"i-brahim-erkal","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/nasil-sevmistim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Abone', 'abone-aysel-gurel-t3obf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana kaptırmam ben onu

İki yıl kaç bölüm oldu

Daha çok sürer bu dizi

Hiç kaçırmam saatini

Onu ilk gördüğüm zaman

Pat...bayıldım amn aman

Annem bu iş olur dedi

Ruhumuz uydu tastamam

Kızların hepsi peşinde

Güzü yok ki hiç birinde

Hem ona aboneyim

Bütün biletler cebimde

Aboneyim abone

Biletleri cebimde

Ballı lokma tatlısı

Aman haydi hayırlısı

Efervesan vitaminle

Gece süt, çiğ yumurta

Sinirlenince her şeyi

Deviriyor bir yumrukta

Joging onda, kayak onda

Su altı, üstü sporu

Şaştım üç lisan biliyor

Okumuş çocuk, borumu

Daha bir güzelleştim

Bu aşk yaradı bana

Herkes dalga geçse de

Darısı başınıza', 'Sana kaptırmam ben onu İki yıl kaç bölüm oldu Daha çok sürer bu dizi Hiç kaçırmam saatini Onu ilk gördüğüm zaman Pat...bayıldım amn aman Ann...', ARRAY['Türk Edebiyatı','Şiir','Aysel Gürel']::text[], 8.5, '{"poet":"Aysel Gürel","poet_slug":"aysel-gurel","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/abone-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereye..', 'nereye-nilgun-akcay-mp1hy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir avuç dolusu yürekle...

Yapayalnız kaldığımda.

Bilmediğim suçlarımın

Aksi vurdu gözlerime...

Arkamı döndüğüm tüm duygularım...

Şaşkındı..Yenilgime.

İnanmadı umudum...

İnanmadı gururum.

Aynalar bile şaşkındı.

Bomboş bakan gözlerime...

İnkar etmek de yetmiyordu...

Unutmaksa zaten imkansız.

Şimdi....

Benliğimi bırakarak....

Gidiyorum...Koşarak...', 'Bir avuç dolusu yürekle... Yapayalnız kaldığımda. Bilmediğim suçlarımın Aksi vurdu gözlerime... Arkamı döndüğüm tüm duygularım... Şaşkındı.....', ARRAY['Türk Edebiyatı','Şiir','Nilgün Akçay']::text[], 8.5, '{"poet":"Nilgün Akçay","poet_slug":"nilgun-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/nereye-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ara Sıra - Çaya Kaç Şeker?', 'ara-sira-caya-kac-seker-elif-sebnem-akal-35eog', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnızlığa dayanırım da, birbaşınalığa asla..

Yaşlanmak hoş değil duvarlara baka baka..

Bir dost göz arayışıyla.

Saat tıkırtısıyla.....

Korkmam

Geçinip gideriz biz mutluluğumla, 

ama

''Günün aydın, akşamın iyi olsun'' diyen biri olmalı..

Bir telefon sesi çalmalı arasıra kulağımda...

yoksa

Zor değil, hiç zor değil, 

demli çayı bardakta

karıştırıp bir başına

yudumlamak doyasıya....

Ama

''çaya kaç şeker alırsın? ''

Diye soran bir ses

olmalı ya ara sıra......

22.11.2002', 'Yalnızlığa dayanırım da, birbaşınalığa asla.. Yaşlanmak hoş değil duvarlara baka baka.. Bir dost göz arayışıyla. Saat tıkırtısıyla..... Kork...', ARRAY['Türk Edebiyatı','Şiir','Elif Şebnem Akal']::text[], 8.5, '{"poet":"Elif Şebnem Akal","poet_slug":"elif-sebnem-akal","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ara-sira-caya-kac-seker-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölene Kadar...', 'olene-kadar-nilgun-akcay-6bmfu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugün... Ağlayacağım...

Gözyaşlarımı silmek isteyeceğim...

Ellerim yanacak..

Kalbimde...

Tüm geçmişime, dostlarıma isyan olacak.

 O an...Yüreğimin bir yerinde...

Kıyametler kopacak...

Ve ben...

O...Hiç kopamadığım vicdanımla...

Başbaşa kalıp ağlayacağım.

Gözyaşlarımda kırık sevgiler bulacağım.

Yanacak ellerim...Bomboş kalacak.

Çaresiz, yorgun, bitkin olacağım....

Verdiğim savaşta vicdanım kazanacak.

Sonbaharım..Gelmiş diyeceğim.....

Pişmanlığım...Fayda vermeyecek...

Ben..Nasıl yaptım diyerek; 

Ufuksuz anılarıma bakacağım.

Ama... Yine de sonsuzlukta...

Yanlızlığımla başbaşa....

Ağlayacağım..

Kaybettiklerimi gözlerimde...

Yaşayacağım..Ölene kadar...', 'Bugün... Ağlayacağım... Gözyaşlarımı silmek isteyeceğim... Ellerim yanacak.. Kalbimde... Tüm geçmişime, dostlarıma isyan olacak.  O an...Yür...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Akçay']::text[], 8.5, '{"poet":"Nilgün Akçay","poet_slug":"nilgun-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/olene-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm''ü Yaşamak', 'olum-u-yasamak-nilgun-akcay-vf4hd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerimden akan iki damla yaş! ...

Nefretime dair.

Onlarla tüm sevgilerimin üzerini çizdim.

Mutluluklarımı, iyiliklerimi...

Onlarla gömdüm.

Onlarla ölüm fermanımı imzaladım.

Yalnızlığım, çaresizliğim..

Ve umutsuzluğum..

Onlarla büyüdü, yeşerdi.

Gözlerimden akan iki damla yaş.! ..

Yalnızlığıma dair..

Onlarla tüm dostluklarıma karşı geldim.

Aldığım her nefesi onlarla paylaştım.

Sevinçlerimi hep onlara anlattım...

Çaresizliğin kör savaşçısıydım...

Kalkanım hep onlar oldu.

Gözlerimden akan iki damla yaş.! ..

Ölüm''e dair...

Her akşam vasiyetimi yazarım....

Gözyaşlarımla...

Yorganım kağıdım...

Gözyaşlarım kalemim olur.

Duvarlar sessizce beni dinler...

Ve her akşam...

Ölüm kokar odamın her köşesi.

Ecelin soğuk kahkahası, 

Azrailin tatlı gülümsemesi, 

sarar ruhumun ta derinliklerini...

Ben...Her akşam...

İçimdeki nefretle yalnızlığıma ağlarım...

Ne garip şeydir, derim kendi kendime...

Umudu ÖLÜM olup da umutsuzluğu...

Yaşamak.

Ne gariptir Allahım...

ÖLMEDEN ÖLÜM''Ü YAŞAMAK..........', 'Gözlerimden akan iki damla yaş! ... Nefretime dair. Onlarla tüm sevgilerimin üzerini çizdim. Mutluluklarımı, iyiliklerimi... Onlarla gömdüm....', ARRAY['Türk Edebiyatı','Şiir','Nilgün Akçay']::text[], 8.5, '{"poet":"Nilgün Akçay","poet_slug":"nilgun-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/olum-u-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli....', 'deli-nilgun-akcay-4vmr3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bilir misiniz...? 

İnsanların ne kadar acımasız...

Ne kadar vicdansız olduğunu

Ben....Ölüm''ü seviyorum.

Dediğim de...

Gülüp bu kadın DELİ...

Dediler de...

Kimse aynaya bakmadı..

Ve göremedi.. Gerçeği...

İhtirasları uğruna...

Harcadıkları güzellikleri...

Gerçek Deliyi.....

                             2000 Nil...', 'Bilir misiniz...?  İnsanların ne kadar acımasız... Ne kadar vicdansız olduğunu Ben....Ölüm''ü seviyorum. Dediğim de... Gülüp bu kadın DELİ......', ARRAY['Türk Edebiyatı','Şiir','Nilgün Akçay']::text[], 8.5, '{"poet":"Nilgün Akçay","poet_slug":"nilgun-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/deli-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değer miydi..?', 'deger-miydi-nilgun-akcay-xpcez', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kader arkadaşım, kardeşim, dostum.

Hatırlar mısın..? 

Yıllar önce bir Şubat günüydü...

Ben ve sen tanışmıştık.

Dostluk tohumları ekilmişti aramızda.

Gözlerimiz, yüreğimiz, dertlerimiz...

Acılarımız, mutluluklarımız, sırlarımız...

Şimdi çok uzaklarda anılarda...

Hatalar, yalanlar...

İşte dostluğumuzu bozan...

Duygularındı..Savaşı hep kazanan.

İhtirasındı..Bizi bizden koparan.

Ben nefretle..

Sen sevgiyle yaklaşırdın..

Mutsuzluk bana..

Mutluluk sana yakışırdı.

Üzüldüğünde dünyam yıkılırdı...

Mutluluğunla yüreğim aydınlanırdı...

Hiçbirşey saklamamıştık birbirimizden...

Küstük bazen....

Birbirimize hissettirmeden...

Ya şimdi...

Yıllanmış dostluğumuzu bozmaya...

Senin deyiminle SATMAYA...

Değer miydi...? 

                                    Nil.', 'Kader arkadaşım, kardeşim, dostum. Hatırlar mısın..?  Yıllar önce bir Şubat günüydü... Ben ve sen tanışmıştık. Dostluk tohumları ekilmişti a...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Akçay']::text[], 8.5, '{"poet":"Nilgün Akçay","poet_slug":"nilgun-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/deger-miydi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asla..!', 'asla-nilgun-akcay-sv8xw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben.........

Mutlu olmanı isterdim...

Yalana değil, gerçek sevgiye...

İhtirasa değil, dostluğa....

İnanmanı isterdim...

Ve...Gerçek seni...

ASLA...Görmemek...

İsterdim....

               Nil..', 'Ben......... Mutlu olmanı isterdim... Yalana değil, gerçek sevgiye... İhtirasa değil, dostluğa.... İnanmanı isterdim... Ve...Gerçek seni... ...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Akçay']::text[], 8.5, '{"poet":"Nilgün Akçay","poet_slug":"nilgun-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/asla-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selam Olsun', 'selam-olsun-ahmet-selcuk-i-lkan-76tfc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hepsi birer umuttular

Birer birer uyuttular

Bizi burda unuttular

Gidenlere selam olsun

Bu acıyı çekeriz biz

Dağı, taşı deleriz biz

Yanmasını biliriz biz

Yakanlara selam olsun

Selam olsun, selam olsun

Gidenlere selam olsun

Acımadan sırtımızdan

Vuranlara selam olsun

Su boğar, ateş yakar

Zalimlerde bir gün yanar

Dağ gibiydi tüm umutlar

Yıkanlara selam olsun

Ha bir saray, ha bir dağ başı

Sonumuz bir mezar taşı

Gözümüzden kanlı yaşı

Akıtana selam olsun', 'Hepsi birer umuttular Birer birer uyuttular Bizi burda unuttular Gidenlere selam olsun Bu acıyı çekeriz biz Dağı, taşı deleriz biz Yanmasını...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/selam-olsun-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevesim Var', 'sevesim-var-reside-murat-e41eq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Derde deva sular gibi

Seni nasıl içesim var

Yüreğine yerleşip de

Ömür boyu sevesim var

Gideceğin el diyara

Adım adım gelesim var

Kem gözlerden uzak seni 

Gizli gizli sevesim var

Bir gün seni, sevdamızı

Kaybederim korkusu var

Ayırmasın Allah diye

Dualarla sevesim var', 'Derde deva sular gibi Seni nasıl içesim var Yüreğine yerleşip de Ömür boyu sevesim var Gideceğin el diyara Adım adım gelesim var Kem gözlerd...', ARRAY['Türk Edebiyatı','Şiir','Reşide Murat']::text[], 8.5, '{"poet":"Reşide Murat","poet_slug":"reside-murat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevesim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen de Gidersen Eğer', 'sen-de-gidersen-eger-serdem-coskun-ok0hk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Artık günler geçer mi

Sen de gidersen eğer

Yüzüm böyle güler mi

Sen de gidersen eğer

Dert dökecek dostum yok

Sarılacak kimsem yok

Yaşamaya gücüm yok

Sen de gidersen eğer

Söyle ne edeceğim

Kime ne diyeceğim

Ben kimi seveceğim

Sen de gidersen eğer

Bağrıma taşlar düşer

Saçıma aklar düşer

Gözümden yaşlar düşer

Sen de gidersen eğer

Bir zindan, bir karanlık

Bu ümitsiz ayrılık

Sanma yaşarım artık

Sen de gidersen eğer', 'Artık günler geçer mi Sen de gidersen eğer Yüzüm böyle güler mi Sen de gidersen eğer Dert dökecek dostum yok Sarılacak kimsem yok Yaşamaya g...', ARRAY['Türk Edebiyatı','Şiir','Serdem Coşkun']::text[], 8.5, '{"poet":"Serdem Coşkun","poet_slug":"serdem-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-de-gidersen-eger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Durağı', 'sevda-duragi-i-brahim-yoruk-6lgra', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dün bir durakta karşılaştık, 

Görür görmez hemen tanıdım.

İlkten utandı yanıma yaklaşmadı; 

Ya da ben utandı sandım.

O beni düşman gibi seyretti

Ben ona bir düşman gibi baktım.

Karşımda eskimiş bir eşya gibiydi.

Yılların pişmanlığı yine gözlerinde; 

Dili onurluydu, onurluydu fakat, 

Gözleri onursuzdu gözlerimde.

Yağmur yağıyordu, durak kuytuydu.

Lanet şey! otobüs yine dopdoluydu.

Son durakta tüm yolcular indi

O da indi, bende indim, herkes indi.

Yanıma yaklaştı ansızın, dedi ki: 

''''Sen gittin ya herşey gitti! ''''

Yanımdan hızla ayrılırken sevgili

Ben ardından bağırdığımı hissettim: 

''''Sen gitmeseydin ben gidermiydim.''''', 'Dün bir durakta karşılaştık,  Görür görmez hemen tanıdım. İlkten utandı yanıma yaklaşmadı;  Ya da ben utandı sandım. O beni düşman gibi seyr...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yörük']::text[], 8.5, '{"poet":"İbrahim Yörük","poet_slug":"i-brahim-yoruk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sevda-duragi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Öğretmeniz..!', 'biz-ogretmeniz-umut-gul-g2jc1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ahmet’ iz, Mehmet’iz

                                 Esma’yız, Ayşe’yiz

                                 Biz öğretmeniz

                                 Atam endişe etme

                                 İzindeyiz...

                                 Aydınlık Çağdaş Türkiye için

                                 Hepimiz birer neferiz, 

                               

                                 Kah kara tahta önünde, 

                                 Kah ücra bir köyünde, 

                                 Ağrı,  Adana, Erzincan da

                                 Edirne, Mersin, Ardahan da

                                 Hep ilerdeyiz, hep en önde, 

                                 Senin gösterdiğin hedefte, 

                                 Işığımız ilkelerinle... 

                                 Atam Endişe etme, 

                                 Biz öğretmeniz, 

                                 Yılmadık, izindeyiz, 

                                 Hepimiz birer, 

                                 Mustafa Kemaliz...

                                                        24.11.2002', 'Ahmet’ iz, Mehmet’iz                                  Esma’yız, Ayşe’yiz                                  Biz öğretmeniz                    ...', ARRAY['Türk Edebiyatı','Şiir','Umut Gül']::text[], 8.5, '{"poet":"Umut Gül","poet_slug":"umut-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/biz-ogretmeniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Ben', 'ben-mustafa-engin-karatay-5dhni', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben, ana rahminde hayât, biraz kemik, biraz et; 

Ben, başı bilinmeyen zamân içinde, ölümsüz rûhunu özleyen ceset 

Ben, kumsalların billûr tânelerinde; ayak altında duran kaya gibiyim, 

Her şeyi içime atarken bile, kabına sığmayan maya gibiyim 

Ben, zifiri karanlıkta ateş böceği; ben, zıpkınlanmış Yunus 

Ben, en büyük ressamın Milyonluk tablosuna, dönüp de bakmayan gurûrlu Tavus 

Muhteşem barajların kalın duvarlarında; deliği törpüleyen bir sızıntıyım, 

Eşsiz Minâreler''in inci sütûnlarında, Boş Mescid''i seyreden bir üzüntüyüm 

Ben, Şeytan''a meydan okuyan, Besmele''nin bir hecesiyim 

Kâinât''ı ilmek ilmek dokuyan, Yaradan''ın sonsuz bilmecesiyim 

Tarlalarda çıplak bir ayak, topuklarda nasır gibiyim 

Ben, zâlime atılan dayak, mazlûma yetişen Hızır gibiyim 

Ben, damarda pıhtılaşan kan, kış boyunca solmayan çiçek 

Ben dudaklardan düşmeyen nidâ, Mahşer''e dek coşkuyla söylenecek 

Ve ben, aç tavuğun düşünde darı, çuvalda saklanan mızrak gibiyim 

Toprakla yoğrulup toprağa giden, fâni bir bedenin geçici sâhibiyim... 

30.12.1998   Nürnberg   21: 05', 'Ben, ana rahminde hayât, biraz kemik, biraz et;  Ben, başı bilinmeyen zamân içinde, ölümsüz rûhunu özleyen ceset  Ben, kumsalların billûr tâ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kız Kulesi', 'kiz-kulesi-deral-baran-zkgo0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yasaklı sevdiceğim 

Kız Kulesi...

Ay bu gece de koynunda 

Sabahladı.

Mağrur endamın 

Kaç denizci gurbete 

Uğurladı.

Bana türküler söyle 

Kız Kulesi...

Süleymaniye yi uzak etme 

Arındır günahlarımı 

Ellerin ne de sıcak 

Nedir bu telaşın 

Kız kulesi...

Boynumda ağır bir 

Vebal.

Ellerim sularında gömülü 

Her gece.

Kız kulesi

18 kasım 2002 İst.

Deral Baran', 'Yasaklı sevdiceğim  Kız Kulesi... Ay bu gece de koynunda  Sabahladı. Mağrur endamın  Kaç denizci gurbete  Uğurladı. Bana türküler söyle  Kız...', ARRAY['Türk Edebiyatı','Şiir','Deral Baran']::text[], 8.5, '{"poet":"Deral Baran","poet_slug":"deral-baran","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kiz-kulesi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terkedemem', 'terkedemem-gonul-sen-wf4iv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Azap verse bile aşkın

Senden şikayet edemem

Her şeyinle kabulümsün

Sevdim seni, terkedemem

Sen hayatsın, ben yaşayan

Aşkına umut bağlayan

Razıyım hep yanımda kal

Sevdim seni, terkedemem

Kimselere vermem seni

Yokluğun öldürür beni

Bu kalbimin tek dileği

Sevdim seni, terkedemem

Seni sevmek günah olsa

Mahşer günü azap olsa

Tutulmuşum nasıl olsa

Sevdim seni, terkedemem', 'Azap verse bile aşkın Senden şikayet edemem Her şeyinle kabulümsün Sevdim seni, terkedemem Sen hayatsın, ben yaşayan Aşkına umut bağlayan Ra...', ARRAY['Türk Edebiyatı','Şiir','Gönül Şen']::text[], 8.5, '{"poet":"Gönül Şen","poet_slug":"gonul-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/terkedemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanıyor Yüreğim', 'yaniyor-yuregim-serdem-coskun-mmzgm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir suya yüz sürmüş toprağa

Bir ıslanmış çatlak dudağa

Hasretim

Kim derdi ki

Hem de bu çocuk yaşta

Elimde bir tüfek haftalarca

Yanıyor yüreğim, yanıyor aman

Ak sütümdü, helalimdi

Gönderdim onu

Haberin ulaşır tez bizim köye

O zaman vururum başım yerden yere

Kim derdi ki hem de yad ellerde

Yavrumun ciğeri pare pare', 'Bir suya yüz sürmüş toprağa Bir ıslanmış çatlak dudağa Hasretim Kim derdi ki Hem de bu çocuk yaşta Elimde bir tüfek haftalarca Yanıyor yüreğ...', ARRAY['Türk Edebiyatı','Şiir','Serdem Coşkun']::text[], 8.5, '{"poet":"Serdem Coşkun","poet_slug":"serdem-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yaniyor-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Türkü', 'bir-turku-aysel-gurel-7jw34', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gece ilk defa kendi saçımı okşadım

İlk defa dudaklarım bana bir şey söyledi

Aşktan verdiğim cevasılamadın

Hani ya aşk çok güzel, her şeyden güzeldi

Bu gece ilk defa kendime türkü söyledim

Bir yanık türkü annemden kalan

Bu gece ilk defa yatağımda yalnızdım

İlk defa kollarımla kendimi kucakladım

Sessiz kıvrıldım, tenime sarıldım

Hani ya aşk çok güzel, her şeyden güzeldi

Bu gece ilk defa kendime türkü söyledim

Bir yanık türkü annemden kalan', 'Bu gece ilk defa kendi saçımı okşadım İlk defa dudaklarım bana bir şey söyledi Aşktan verdiğim cevasılamadın Hani ya aşk çok güzel, her şeyd...', ARRAY['Türk Edebiyatı','Şiir','Aysel Gürel']::text[], 8.5, '{"poet":"Aysel Gürel","poet_slug":"aysel-gurel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-turku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaktım Çıranı', 'yaktim-cirani-reside-murat-4knpt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senin devrin son buldu

Bende oyun sırası

Üzgünüm vaktin doldu

Şimdi yaktım çıranı

Karnım tok masallara

Paydos tüm acılara

Düştün sen tuzağıma

Şimdi yaktım çıranı

Affedemem yalvarma

Boş sözlerle kandırma

Kimse gelmez yardıma

Şimdi yaktım çıranı', 'Senin devrin son buldu Bende oyun sırası Üzgünüm vaktin doldu Şimdi yaktım çıranı Karnım tok masallara Paydos tüm acılara Düştün sen tuzağım...', ARRAY['Türk Edebiyatı','Şiir','Reşide Murat']::text[], 8.5, '{"poet":"Reşide Murat","poet_slug":"reside-murat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yaktim-cirani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Yazık', 'ne-yazik-adem-tetik-c65qb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sonbahar da dökülen  yapraklar gibi

Sarardı bu sevda bitti ne yazık ki 

Sevgilim ellere gelin olmuş gider

Unutmuş maziyi güzel günleri

Düşsede bu sevda artık dillere 

Yaşandı bir kere bitti ne çare 

Ağlama gözlerim o güzel yare 

Vefasız işte gitti ellere', 'Sonbahar da dökülen  yapraklar gibi Sarardı bu sevda bitti ne yazık ki  Sevgilim ellere gelin olmuş gider Unutmuş maziyi güzel günleri Düşse...', ARRAY['Türk Edebiyatı','Şiir','Adem Tetik']::text[], 8.5, '{"poet":"Adem Tetik","poet_slug":"adem-tetik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ne-yazik-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Saati', 'siir-saati-ozhan-arioglu-rpu3p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kalem elimde titriyor yazı yazarken

Senidile dökmek sevmekten de zormuş.

Göz yaşlarım akıyor artık birer birer

Seni görmek görememekten de zormuş...', 'Kalem elimde titriyor yazı yazarken Senidile dökmek sevmekten de zormuş. Göz yaşlarım akıyor artık birer birer Seni görmek görememekten de z...', ARRAY['Türk Edebiyatı','Şiir','Özhan Arıoğlu']::text[], 8.5, '{"poet":"Özhan Arıoğlu","poet_slug":"ozhan-arioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/siir-saati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Vurdular Anne!', 'beni-vurdular-anne-gokhan-karaduman-9nmxb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni vurdular anne

Sevgi sokağında

Aşk apartmanındaki küçük odamda

Beni kalbimden vurdular anne

Gözyaşıma acımadan

Bir damla kan akıtmadan

Haince, kahpece

Ayrılık kurşunuyla

Failim meçhul değil

Çok güvendiğim

Uğrunda ölümlere gidip geldiğim

Çekilmez acılar çektiğim

Gönlümün kapısını açtığım

Evet, evet o çok sevdiğim

Beni bugün kalbimden vurdu anne

Ayrılığın kahpe kurşunu

Kalbime saplandı anne

Oysa sen! 

Nasıl büyütmüstün beni

Aglatmadan, üzmeden

Bir tek gün bile dövmeden

Beni nasıl da severek büyütmüstün anne.

Peki ya ben

Ya ben onu nasıl sevmiştim

Biliyor musun anne

Affet beni anne

Onu senden çok sevmiştim

Ona gönlümü vermiştim

Adım üzüntü

Soyadım keder oldu anne

Gözyaşıma acimadan

Bir damla kan akıtmadan

Ayrılık kurşunuyla

Haince, kahpece, acımasızca

Beni yüreğimden vurdular anne

27.07.2001 - Gökhan Karaduman

“Sanki büyük bir savaştan yaralı çıkmış gibiyim”', 'Beni vurdular anne Sevgi sokağında Aşk apartmanındaki küçük odamda Beni kalbimden vurdular anne Gözyaşıma acımadan Bir damla kan akıtmadan H...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Karaduman']::text[], 8.5, '{"poet":"Gökhan Karaduman","poet_slug":"gokhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/beni-vurdular-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Bildiklerim', 'dost-bildiklerim-gokhan-karaduman-l1kxz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dost bildigim hainler

Birer birer terkettiler

Hep yüzüme gülenler

Arkamdan laf ettiler

Dost bildigim hainler

Hep sirtimdan vurdular

Melek gibi görünenler

Adam sandigim seytanlar

Dost bildigim hainler

Beni benden ettiler

Hep biz variz diyenler

Kötü günde gittiler

Dost bildigim hainler

Acilarla vurdular

Hepsi beni ezdiler

Dost sandigim serefsizler', 'Dost bildigim hainler Birer birer terkettiler Hep yüzüme gülenler Arkamdan laf ettiler Dost bildigim hainler Hep sirtimdan vurdular Melek gi...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Karaduman']::text[], 8.5, '{"poet":"Gökhan Karaduman","poet_slug":"gokhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dost-bildiklerim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollarda Bulurum Seni', 'yollarda-bulurum-seni-haluk-levent-6mvf5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Olmasan da yanımda

Olmasan da birlikte

Hiç istemezsen bile

Yaşarım ben seni

Yollarda bulurum seni

Takvimlerden çalarım seni

Dansederim hayalinle

Yine de yaşarım seni

Yanlız kalırım sanma

Mutsuz olurum sanma

Yaşarım doya doya

Yaşarım ben seni

Yollarda bulurum seni

Takvimlerden çalarım seni 

Dansederim hayalinle 

Yine de yaşarım seni 

Şiir: 

Yosun denizde saklıdır 

Deniz mavide 

Mavi gözlerinde 

Seni unutmak mümkün mü 

Yağmur bulutta saklıdır 

Bulut beyazda 

Beyaz teninde

Seni unutmak mümkün mü 

Buğday başakta saklıdır 

Başak sarıda 

Sarı saçlarında 

Seni unutmak mümkün mü', 'Olmasan da yanımda Olmasan da birlikte Hiç istemezsen bile Yaşarım ben seni Yollarda bulurum seni Takvimlerden çalarım seni Dansederim hayal...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yollarda-bulurum-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışamadım', 'alisamadim-haluk-levent-dld2v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zaman akar zaman gider 

Bir sıkıntı biner bedenime 

Her dakika ve her saniye 

Çırpınır yüreğim hasretine 

Şu insanlar arasında yapayanlızım 

Yanlızlığım sensin 

Uzaktan da olsa konuş 

Konuş benimle bak gelecek sesin 

Alışamadım ben bu kente 

Alışamadım sensizliğe 

Soluduğum bu şehir 

Artık benim değil 

O gölge veren ağaç 

Artık burada değil 

Bildiğim güzellikler 

Yabancılaştı bana 

Göklerde parıldayan 

Benim yıldızım değil 

Şu insanlar arasında yapayanlızım 

Yanlızlığım sensin 

Uzaktan da olsa konuş 

Konuş benimle bak gelecek sesin 

Alışamadım ben bu kente 

Alışamadım sensizliğe', 'Zaman akar zaman gider  Bir sıkıntı biner bedenime  Her dakika ve her saniye  Çırpınır yüreğim hasretine  Şu insanlar arasında yapayanlızım ...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/alisamadim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökova', 'gokova-haluk-levent-2ue3q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Cennet vatan Türkiye’min kıyısında 

Rüzgar esmez yağmur yağmaz adı Gökova 

Gökyüzü paramparça orada ağaçlar sessiz 

Yeşili öldürdük Gökova’da 

Yeter ki Gökova’lar olmasın 

Ağaçlar bulutlar bize kalsın 

Gelin gelin arkadaşlar birlik olalım 

Zehir saçan santralleri çöpe atalım 

Çevremizi temiz tutalım ülkemizi koruyalım 

Başka Türkiye yok bu dünyada 

Yeter ki Gökova’lar olmasın 

Ağaçlar bulutlar bize kalsın 

Boğaz faciaları çarpışan tankerler 

Güzelim balıkları yunusları yok ettiler 

Bir yanda zehirli atıklar 

Bir yanda kirli variller 

Karadenizden sonra Akdeniz’i yok ettiler 

Yeter artık yeter 

Çıldırtmayın bizleri 

Yürüyelim arkadaşlar Gökova bekler bizi', 'Cennet vatan Türkiye’min kıyısında  Rüzgar esmez yağmur yağmaz adı Gökova  Gökyüzü paramparça orada ağaçlar sessiz  Yeşili öldürdük Gökova’d...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gokova-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Ateş Sönmez', 'bu-ates-sonmez-haluk-levent-vt2yb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Öyle büyük bir ateş düştü içime 

Aylar geçse yıllar geçse bu ateş sönmez 

Meşaleler gibi canım bu ateş sönmez 

Eritipte bulutları sarsam yüreğime 

Kor bir ışık gibi canım bu ateş sönmez 

Umutları sırtlasam 

Çıplak ayak yürüsem kutuplarda 

Dolaşsam buzullarda bu ateş sönmez 

Denizleri içsem canım bu ateş sönmez 

Yağmurları yutsam canım bu ateş sönmez 

Meşaleler gibi canım bu ateş sönmez', 'Öyle büyük bir ateş düştü içime  Aylar geçse yıllar geçse bu ateş sönmez  Meşaleler gibi canım bu ateş sönmez  Eritipte bulutları sarsam yür...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bu-ates-sonmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bosna', 'bosna-haluk-levent-le7li', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gazetelerde bugün bir çocuk resmi gördüm 

Uzanmış kanlar içinde Avrupa’nın göbeğinde 

Uyuyor uyuyor 

Petrol için savaşan Dünya şimdi nerede 

Amerika Avrupa Almanya hamburger kola 

Uyuyor uyuyor 

Toplama kamplarında Nazi vahşeti gibi 

İnsanlık yok ediliyor 

Sokak ortasında analar kucaklarda çocuklar 

Kurşuna diziliyor 

Hani insan hakları hani çağdaş Avrupa 

Hepsi hepsi susuyor 

Bosna’nın ortasında petrollerin yerine 

İnsan kanı fışkırıyor 

Sam amca torunları Hitler’in tohumları 

Hepsi hepsi susuyor 

Uyuyor uyuyor', 'Gazetelerde bugün bir çocuk resmi gördüm  Uzanmış kanlar içinde Avrupa’nın göbeğinde  Uyuyor uyuyor  Petrol için savaşan Dünya şimdi nerede ...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bosna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin', 'nerdesin-haluk-levent-jvc2t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine resmin duvarda

Geceler yine sensiz

Gönlüme üç kurşun sevdalı

Saatler yine sessiz

Eski bir şarkı bu

Tarihin kaleminde

Ne güzel aşk yaşamıştık

Akdeniz''de Ege''de

Ah! ...Nerdesin

Nerdesin

Unutamıyorum', 'Yine resmin duvarda Geceler yine sensiz Gönlüme üç kurşun sevdalı Saatler yine sessiz Eski bir şarkı bu Tarihin kaleminde Ne güzel aşk yaşam...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/nerdesin-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereye Saklarsın', 'nereye-saklarsin-haluk-levent-iqqwe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nereye saklarsın yıkılmış bir aşkı

Nasıl gizlersin yüreğini

Gözlerin seni seni ele verir

Utanır sevişmezsin

Nereye saklarsın yıkılmış bir aşkı

Nasıl gizlersin yüreğini

Ellerini seni seni ele verir

Utanır sevişmezsin

Deli gönlüm aşık oldu

Al kendini durma git

Sonbahar biter kış yine gelir

Beni kendime bırak öyle git

Nereye saklarsın yıkılmış bir aşkı

Nasıl gizlersin yüreğini

Gözlerin seni seni ele verir

Utanır sevişmezsin

Ellerini seni seni ele verir

Utanır sevişmezsin

Deli gönlüm aşık oldu

Al kendini durma git

Sonbahar biter kış yine gelir

Beni kendime bırak öyle git', 'Nereye saklarsın yıkılmış bir aşkı Nasıl gizlersin yüreğini Gözlerin seni seni ele verir Utanır sevişmezsin Nereye saklarsın yıkılmış bir aş...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/nereye-saklarsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öpmek İsterdim', 'opmek-i-sterdim-haluk-levent-ut2mq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öpmek isterdim ellerini

Gözlerini canım göz bebeğini

Bakışların dargın bakışların durgun

Bilmek isterdim sebebini

Öpmek isterdim ellerini

Gözlerini canım göz bebeğini

Bakışların dargın bakışların durgun

Bilmek isterdim sebebini

Nekadar uzaksın öyle

Yollar bitmiyor

Günler bitti yıllar bitti

Gece gündüz ömür bitti seninle

Öpmek isterdim ellerini

Gözlerini canım göz bebeğini

Bakışların dargın bakışların durgun

Bilmek isterdim sebebini', 'Öpmek isterdim ellerini Gözlerini canım göz bebeğini Bakışların dargın bakışların durgun Bilmek isterdim sebebini Öpmek isterdim ellerini Gö...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/opmek-isterdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Menekşeli Bahar', 'menekseli-bahar-hasan-varol-57wnk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ayakları köpüklüce atım 

Beni uçur uçur 

Sevgilim yalnız kalmasın

Ağlamasın 

Belki gece olur uyur

Ayakları köpüklüce atım 

Beni uçur uçur

Kardeşim hapiste 

Ne yapar ne halde 

Ne yapar nasıl oturur

Ayakları köpüklüce atım

Beni uçur uçur

Yeğenim var Almanya''da

Biz ona o bize hasret

Kavuşmak ne güne durur

Ayakları köpüklüce atım

Beni uçur uçur 

Annem o yoksul köyde 

Babam tarlada neler toplar

Unuttular mı beni acep

Şimdi kırlarda 

Menekşeli bahar var', 'Ayakları köpüklüce atım  Beni uçur uçur  Sevgilim yalnız kalmasın Ağlamasın  Belki gece olur uyur Ayakları köpüklüce atım  Beni uçur uçur Ka...', ARRAY['Türk Edebiyatı','Şiir','Hasan Varol']::text[], 8.5, '{"poet":"Hasan Varol","poet_slug":"hasan-varol","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/menekseli-bahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyun', 'oyun-haluk-levent-50o1g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Arttı harçlar okumak zor

Okusanda bitirmek zor

Bitirirsen iş bulmak zor

İş bulsanda yaşamak zor

Ey bakanlar boş bakanlar

Son verin artık bu eğitim sistemine

Sonunda geldik oyuna

Sonunda geldik oyuna

Sandıklara koştururuz

Oy vermek için sizlere

Kimimiz işçi kimimiz köylü

Umutlarımız düştü yere

O enflasyon düşmek bilmez

Yazık oluyor artık bu güzelim ülkeye

Sonunda geldik oyuna

Sonunda geldik oyuna

Gazeteler yazıyor 

Kayıpları kazaları

Kaç bin tane can alacak

Bu trafik canavarı

O santraller bu yangınlar

Kirletiyor dünyamızı boşu boşuna

Sonunda geldik oyuna

Sonunda geldik oyuna

Sabah okula akşam eve

Yıllar geçiyor sen ne dersen de

Hoca bana takmış yine

Dersten kaldım bu senede

Yaşlı dedem bana soruyor

Oğlum bunca yıl ne okudun

Ne yaptın diye

Sonunda geldik oyuna

Sonunda geldik oyuna', 'Arttı harçlar okumak zor Okusanda bitirmek zor Bitirirsen iş bulmak zor İş bulsanda yaşamak zor Ey bakanlar boş bakanlar Son verin artık bu ...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/oyun-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gece Vakti', 'bir-gece-vakti-haluk-levent-6ie41', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sancı dolu gecelerde bulmuştum seni

Sımsıcak ellerin eritti beni

Annemin öyküleri gibi masum ve sessiz

Kaybettim seni bir gece vakti

Masallarda romanlarda aradım bulamadım

Kaybettim seni bir gece vakti

Bilemezdim şarkıların yakınlığını

Koklamazdım bir çiceği bir çocuk gibi

Yaşamazdım kaldırımları yorulana dek

Kaybettim seni bir gece vakti

Göremezdim karıncayı bir şahin gibi

Kaybettim seni bir gece vakti

Deli deli yağdı yağmur

Gökten kayboldu yıldızlar

Fırtınalar çaldı seni

Bir gece vakti

Bilemezdim şarkıların yakınlığını

Koklamazdım bir çiceği bir çocuk gibi

Yaşamazdım o soğuk o sessiz o çaresiz kaldırımları

Kaybettim seni bir gece vakti

Göremezdim bir boceği

bulamazdım yolumu uçamazdım

dağlarda bir şahin gibi

Kaybettim seni bir gece vakti', 'Sancı dolu gecelerde bulmuştum seni Sımsıcak ellerin eritti beni Annemin öyküleri gibi masum ve sessiz Kaybettim seni bir gece vakti Masalla...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-gece-vakti-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim Uçurtma', 'kalbim-ucurtma-hasan-varol-5bsfr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Marlboro reklamları yükseliyor duraklarda

Beklerken sırtımıza inecekmişçesine

Ben atını seviyorum kovboyun

Şapkasını, bakışlarını, ipini asla! 

Duraklarda eyleşiyorum arada bir

Çeyiz sepetime yorgunluk topluyorum

Ayrılık; öpüşler, kırık bir elveda

Sonra gözyaşları, sıkı bir sarılma.

Duraktan durağa yürüyorum, kirli

Yorgun düşmüş bakımsız sokaklarda

Sigara izmaritleri, cocacola şişeleri, pet kutuları

İliklerimize ileyen pislikler

Umurunda mı çarpık bakışların

Paranın pisliği bu diyorum, kirli işlerin

Benim umurumda.

Duraktan uzaklara bakıp gel diyorum sevgilime

Gel, uyutan bir afyon oldu bu uygulanan ekonomi

Ve ahlakı, beklenmeyen doğal afet, sel baskını gibi

Çok evlilikler sarsıldı bu yıllarda, yıkıldı

sevgileer eridi tüketim reklamları karşısında

tut elimi harlı bir karanfil gibi

gidelim seni seven kalbim uçurtma.', 'Marlboro reklamları yükseliyor duraklarda Beklerken sırtımıza inecekmişçesine Ben atını seviyorum kovboyun Şapkasını, bakışlarını, ipini asl...', ARRAY['Türk Edebiyatı','Şiir','Hasan Varol']::text[], 8.5, '{"poet":"Hasan Varol","poet_slug":"hasan-varol","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kalbim-ucurtma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Gel [Gül Biraz]', 'gel-gel-gul-biraz-haluk-levent-88nuv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Derdime buldum bir çare

Boşver sen gerisi hikaye

Derdime buldum bir çare

Boşver sen gerisi hikaye

Gül biraz öleyim

Allah aşkına

Gel gel gel yanıbaşıma

Aylardır hep peşindeyim

Cilveliyim canım güzelim

Aylardır hep peşindeyim

Cilveliyim canım güzelim

Gül gül biraz öleyim

Allah aşkına

Gel gel gel yanıbaşıma

Bir varmış bir yokmuş

Olanlar olmuş

Gözlerim gözlerini

Arar dururmuş

Ne yaparsan yap

Kısmetin sensin

Samanlığın seyrinde

Onlar olmuş', 'Derdime buldum bir çare Boşver sen gerisi hikaye Derdime buldum bir çare Boşver sen gerisi hikaye Gül biraz öleyim Allah aşkına Gel gel gel ...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gel-gel-gul-biraz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir', 'siir-haluk-levent-97w2t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Baharı hissedemediğim

Kaygımı salamadığım dünyam

Yorgun sözleri süzüp elime

Taş atıp vurduğum sokaklar elveda

Yamaçlarında yüzdüğüm seyhanım

Kavgasında büyüdüğüm mahallem elveda

Okey taşlarının tavla zarlarının

Müzik fonu oluşturduğu her insan

Gözlerimi yaşartan şerefsiz

Ve dudaklarımda dans ettiğim sevgilim elveda

Büstünü parçalayıp insanlığın

Samimi gülüşleri savurdan dudak

Ve yol geçen hanına dönüşen

Bu sanat bu edebiyat elveda

Güneş yakalanacaksa eğer

Sana söz veriyorum 

Kopartıp her bir ışının

Her bir rengini sunacağım sana

Ve şuna inanki sevgilim şuna inan

Diyeceğim merhaba', 'Baharı hissedemediğim Kaygımı salamadığım dünyam Yorgun sözleri süzüp elime Taş atıp vurduğum sokaklar elveda Yamaçlarında yüzdüğüm seyhanım...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/siir-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşamlar', 'aksamlar-haluk-levent-iliig', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Unutamam ki yaşanılan anıların bana verdiği acıları 

Memleketim çok uzak artık yaban gülüm boş diyarlarım 

Benzemiyor şehirler gözlerine, saçlarına güneşin kanı 

Yok yok demek kolay, hasret kokar akşamları 

Akşamlar akşamlar seni benden çaldılar 

Akşamlar akşamlar seni bana yazdılar 

Ürkütmüyor yokluğun kadar hiçbir şey, alay eder kent ışıkları 

Arıyorum arıyorum tenini, geçit vermiyor aşk duvarları 

Benzemiyor şehirler gözlerine, saçlarına güneşin kanı 

Yok yok demek kolay, hasret kokar akşamları 

Akşamlar akşamlar seni benden çaldılar 

Akşamlar akşamlar seni bana yazdılar', 'Unutamam ki yaşanılan anıların bana verdiği acıları  Memleketim çok uzak artık yaban gülüm boş diyarlarım  Benzemiyor şehirler gözlerine, sa...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aksamlar-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pazartesi Günleri', 'pazartesi-gunleri-haluk-levent-crx2s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Toprağım suya karıştı bugun 

Yağmurla yağan sensin gönlüme 

Her sabah adın dolaşır 

Her güne hüzün karışır 

Yar seni seni düşününce 

Dereler çağlar oldu gözlerim ağlar 

Günlerden pazartesi bomboş sokaklar 

 Her gece açar dert çiçekleri 

Şarkılar seni söyler pazartesi günleri 

Aşkıma ihanet günü bugün 

Simsiyah sayfalar gönlüme 

Her sabah adın dolaşır 

Her güne hüzün karışır 

Yar seni seni düşününce 

Dereler çağlar oldu gözlerim ağlar 

Günlerden pazartesi bomboş sokaklar 

Her gece açar dert çiçekleri 

Şarkılar seni söyler pazartesi günleri', 'Toprağım suya karıştı bugun  Yağmurla yağan sensin gönlüme  Her sabah adın dolaşır  Her güne hüzün karışır  Yar seni seni düşününce  Dereler...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/pazartesi-gunleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerelerdesin', 'nerelerdesin-haluk-levent-o72fc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sanki bir ömür oldu 

Canım hangi yerdesin 

Şarkılar seni sordu 

Nerelerdesin 

Kadehler boşaldı sana 

Günlerim doluyor sana 

Nerelerdesin 

Leylim leylim yar beklerim 

Kapı kapı yol gözlerim 

Bugün ayın kaçı yarim 

Nerelerdesin 

Bu şarkım sana isyan 

Canım hangi yerdesin 

Serseri gönlüm figan 

Nerelerdesin 

Buluttan yağmur oldum 

Yunustan nazım oldum 

Nerelerdesin 

Leylim leylim yar beklerim 

Kapı kapı yol gözlerim 

Bugün ayın kaçı yarim 

Nerelerdesin', 'Sanki bir ömür oldu  Canım hangi yerdesin  Şarkılar seni sordu  Nerelerdesin  Kadehler boşaldı sana  Günlerim doluyor sana  Nerelerdesin  Le...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/nerelerdesin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmesin Çocuklar', 'olmesin-cocuklar-haluk-levent-0dd8q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dolaşırım Dünyayı bir uçtan bir diğer uca

Savaşlar yoksul halklar bombalar olen çocuklar

Nükleer denemeler Filistin’den ölümler

Karabağ Azarbeycan Kafkasya neler neler

Terör bomba kin ve nefret dünya bu kadar

İstersen değişir herşey ölmesin çocuklar

Dünya kan içinde dünya yokluk içinde

Haydi sende katıl artık bize ölmesin çocuklar

Düşünürüm Dünya’yı bir uçtan bir diğer uca

Darbeler darbeciler açlık kokan Afrika’da

Çernobil’den iz kaldı sakat doğdu çocuklar

Bosna Irak farketmez Küba’daki kontralar

Terör bomba kin ve nefret dünya bukadar

İstersen değişir herşey ölmesin çocuklar

Dünya kan içinde dünya yokluk içinde

Haydi sende katıl artık bize ölmesin çocuklar', 'Dolaşırım Dünyayı bir uçtan bir diğer uca Savaşlar yoksul halklar bombalar olen çocuklar Nükleer denemeler Filistin’den ölümler Karabağ Azar...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olmesin-cocuklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Antalya’da Sonbahar', 'antalya-da-sonbahar-haluk-levent-o8pi2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anılar hergün seni bana sorarken 

Mektubun geldi nihayet gittiğin yerden 

Güneşe kızdık hatırla yağmura küstük 

Birkaç ay önce vedalaşırken 

Umut taşır yürekler yolculuklarda 

Sarar yine kor ateşin sarsa neye yarar 

Sevgilim bilirsin ne kadar güzeldir 

Antalya’da sonbahar 

Saçların yine ateş renginde mi 

Sımsıcak dudakların kemer gibi mi 

Yat limanı martılar sabah yıldızları 

Bir dahaki mektubunda yazarsın değilmi 

Umut taşır yürekler yolculuklarda 

Sarar yine kor ateşin sarsa neye yarar 

Sevgilim bilirsin ne kadar güzeldir 

Antalya’da sonbahar', 'Anılar hergün seni bana sorarken  Mektubun geldi nihayet gittiğin yerden  Güneşe kızdık hatırla yağmura küstük  Birkaç ay önce vedalaşırken ...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/antalya-da-sonbahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tuttuğun Altın Olsa', 'tuttugun-altin-olsa-haluk-levent-69d9j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ferhat olup dağlar aştım girerim diye gönlüne

Aşık olup sazın çaldım bu dünyanın üstüne

Derdime derman olman için aradım boşuna

Bir daha bir daha çıkmam karşına

Tuttuğun altın olsa bu dünya sana kalsa

İnanki bir ömür boyu bir daha çıkmam karşına', 'Ferhat olup dağlar aştım girerim diye gönlüne Aşık olup sazın çaldım bu dünyanın üstüne Derdime derman olman için aradım boşuna Bir daha bir...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/tuttugun-altin-olsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkiye’m', 'turkiye-m-haluk-levent-egx4m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Haberler kötü söyler yine

Yine konu güneydoğu

Kaç asker ölmüş yine

Kaç anne matem dolu

Bir başka ana o da ağlar Kanber Ateş diye bu ülkede

Türkiyem Türkiyem nereye

Devletin gücü varken çeteler neden niye

İpekçi Mumcu Çetin Emeç hain miydi bu ülkede

Türkiyem Türkiyem nereye

Katiller dışarıda iken Manisa’da öğrenciler

Raporlar işkenceler

Hastane kurbanı Mustafa düzene yenildi sonunda

Kahır çeken emekliler

Sağlık eğitim ekonomi yedi bitirdi ülkemi

Hapse attılar düşünceleri

Bilinçsiz cahil koca kafalar kokainden para kazananlar

Ne duruma düşürdüler güzel ülkemi

Türkiyem Türkiyem nereye

Haberler kötü gelsede herşey kötü gitsede

Umut et yarın güneş başka doğar ülkeme', 'Haberler kötü söyler yine Yine konu güneydoğu Kaç asker ölmüş yine Kaç anne matem dolu Bir başka ana o da ağlar Kanber Ateş diye bu ülkede T...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/turkiye-m-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadolu Diyarında', 'anadolu-diyarinda-haluk-levent-g5cy1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Anadolu diyarında dumansız kaldım

Sardım dört bir yanıma umut dert sardım

Sesini duymak için yollara kaldım

Dağlar beni nice eylesin

Dostum gelmez dağlar nice eylesin

Anadolu diyarında ağaçlı yollar

Dökülür sevdasız kalan yapraklar

Göçtürür kuşları soğuk/yalan rüzgarlar

Dağlar beni nice eylesin

Dostum gelmez dağlar nice eylesin

Şiir

Bir çıra yandı bir mum söndü gündüzden

Hala bardak dolu mu hayır boşalmış arkadaş

Yaptığımız bu deney güneşin kendi ışığından

Hayret suyumuzu buharlaştırıp eksiltmişiz arkadaş

Gelin dedim gelin birlik olalım

Bunu daha aydın güne kavuşturalım

Ayna yapalım ne bileyim su ısıtalım

Su buharlaşırsa depolar satarız arkadaş

O zamanlar gökten yağmur yerine

Kan damlardı annelerin gözbebeklerine

Çocuklar babasız anneler kocasızdı arkadaş

Ne bilgisayarların dünyası

Ne otoyolların grafiği

Ne sokak ortasında mafya hesaplaşması

Hiç biri, hiç biri çözemezdi bu sırrı arkadaş

Kadınlarımız, kadınlarımız vardı

Bin dokuzyüz yirmilerde

Kadınlarımız yirmibirlerde

Yürürlerdi yekpare meşalelerinden tekerlekleriyle

Yürürlerdi Çanakkele’ye

Yürürlerdi Kocatepe’ye

Arşin arşin yükselirdi MUSTAFA KEMAL’in gölgesi

Aşardi aşardi aşardi arkadaş!', 'Anadolu diyarında dumansız kaldım Sardım dört bir yanıma umut dert sardım Sesini duymak için yollara kaldım Dağlar beni nice eylesin Dostum ...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/anadolu-diyarinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani Benim Olacaktın', 'hani-benim-olacaktin-haluk-levent-h3wzs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dünyalar verdim gözlerinin uğruna

Kaçamak saatler sonsuz kelimeler

Unuttun mu yar söz verdin bana

Gitmeyecektin daha neler neler

Şimdi uzaklardasın

Bensiz sevdalardasın

Söyle söyle güneşin kızı ne yapmaktasın

Hani benim hani benim

Benim olacaktın

İki bahar önce okulun bitince

Bana varacaktın', 'Dünyalar verdim gözlerinin uğruna Kaçamak saatler sonsuz kelimeler Unuttun mu yar söz verdin bana Gitmeyecektin daha neler neler Şimdi uzakl...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hani-benim-olacaktin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eller Eller', 'eller-eller-haluk-levent-5hsfj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen yalnız adam duy sesimizi

Paran yetmez yıkmaya direncimizi

Çek git yakamızdan çek git ülkene

Uç uç bu dünyadan bir daha gelme

Eller eller eller eller havaya

Bergama’dan çıktık yola Akkuyu’ya

Eller eller eller eller havaya

Gerekirse yürümeli Ankara’ya

Politik söylemleriniz parasal güçleriniz

Kuruyan nehirler göller sizin eseriniz

Bu köylü bu toprak bu ağaç bizim

Benim ülken çöplük değil çektirin gidin

Eller eller eller eller havaya

Bergama’dan çıktık yola Akkuyu’ya

Eller eller eller eller havaya

Gerekirse yürümeli Ankara’ya', 'Sen yalnız adam duy sesimizi Paran yetmez yıkmaya direncimizi Çek git yakamızdan çek git ülkene Uç uç bu dünyadan bir daha gelme Eller eller...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/eller-eller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlasana', 'anlasana-haluk-levent-f6lxm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kendimi esir aldım

Çalmadı yine telefonlar

Alışırım sanmıştım

Yüreğimde şancım var

Gel etme nazlı güneş

Sensin gönlüme eş

Beni biraz anlasana

Ölürüm aşkına yar

Ölürüm diyar diyar

Beni biraz anlasana

Off sarıl bana

Beni biraz anlasana', 'Kendimi esir aldım Çalmadı yine telefonlar Alışırım sanmıştım Yüreğimde şancım var Gel etme nazlı güneş Sensin gönlüme eş Beni biraz anlasan...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anlasana-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kana, geceyi karıştırmak', 'kana-geceyi-karistirmak-i-smail-cem-pp34t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yakması için binlerce defa güneşe yalvaracağım

Çok ve soğuk bir gündü.

Ve ben anlamıştım ayrılacağımızı.

Sınırlarımızın beklen(e)  meyen bir saldırıya uğradığı 

haberi gibi.

Çiğ köfte tepsisine inen bir yumruk gibi

Rakımın bittiğini anlamam gibi

Öyle birşeydi

Bırakıp gitmen beni.

Son sigaramı da yakmam gibi

Onun bitmesi gibi.

Feci bir şeydi aslında

Zor mu kolay mı alışmak? 

Yok yok alıştım.

Nikotin bitti kanımda, 

Geceyi karıştırdım!', 'Yakması için binlerce defa güneşe yalvaracağım Çok ve soğuk bir gündü. Ve ben anlamıştım ayrılacağımızı. Sınırlarımızın beklen(e)  meyen bir...', ARRAY['Türk Edebiyatı','Şiir','İsmail Cem']::text[], 8.5, '{"poet":"İsmail Cem","poet_slug":"i-smail-cem","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kana-geceyi-karistirmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyleyim', 'neyleyim-haluk-levent-9ja2a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dövülmüşüm geceleri

Tenhalarda neyleyim

Bir tarafım açlık

Bir tarafım pislikmiş

Neyleyim

On dört yaşında işkenceler

Çöpten beslenmişim çok zaman

Ne onurum kalmış ne gururum

Umutlarım çikletlerde

Şekerli Şekersiz

Şekerliymiş

Neyleyim

Dövülmüşüm geceleri

Tenhalarda neyleyim

Bir tarafım açlık

Bir tarafım pislikmiş

Neyleyim

Her gün ölen binlerce aç çocuk

Ucuz ekmek kuyruğunda kavgalar

Alpay Cansel televizyonda

Umutlarım çikletlerde

Şekerli Şekersiz

Şekerliymiş

Neyleyim', 'Dövülmüşüm geceleri Tenhalarda neyleyim Bir tarafım açlık Bir tarafım pislikmiş Neyleyim On dört yaşında işkenceler Çöpten beslenmişim çok z...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/neyleyim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehirden Gidelim Artık', 'bu-sehirden-gidelim-artik-haluk-levent-om22n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gel geç olmadan gün dogmadan

Kaçalım buralardan

Sen sen istersen dünya dar olur

Denizlerin ardından

Dedikodu ekmeğine süremem yarınları

Bir çıkış yol bulalım artık

Sevda gemileri demir almadan

Bu şehirden gidelim artık

Dedikodu ekmeğine süremem yarınları

Üzülmeyi istemem artık

Bu aşkın dizeleri sokaklara taşmadan

Bu şehirden gidelim artık

Kaf dağından ötelere

Yıldızlardan güneşlere

Sen istersen çıkarız göklere

Bu şehirden gidelim artık', 'Gel geç olmadan gün dogmadan Kaçalım buralardan Sen sen istersen dünya dar olur Denizlerin ardından Dedikodu ekmeğine süremem yarınları Bir ...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-sehirden-gidelim-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Gönlüm', 'deli-gonlum-haluk-levent-lc0c4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Deli gönlüm ne olursun anla beni

Unutamam unutmam geçenleri

Biliyorum acı verir aşık olmak

Üzüleceğim deli gönlüm

Aşkın kanunu fermanı vermiş

Üzerine ikimizin resmini çizmiş

Biliyorum felaket aşık olmak

Üzüleceğim deli gönlüm

Gidemem gidemem ben gidemem

Yalnızlık türküsü söyleyemem

Sevdim anlıyor musun deli gönlüm

Deli gönlüm ne olursun affet beni

Unutamam unutmam geçenleri

Biliyorum ölmektir aşık olmak

Üzüleceğim deli gönlüm

Gidemem gidemem ben gidemem

Yalnızlık türküsü söyleyemem

Sevdim anlıyor musun deli gönlüm

Toprağın oldum derdim

Koynuma onu serdim

Hata ettim ağladım gecelerce

Yeni bir aşk bu belki

Sonbahar gibi solar 

Belki de yaşar belki de senelerce', 'Deli gönlüm ne olursun anla beni Unutamam unutmam geçenleri Biliyorum acı verir aşık olmak Üzüleceğim deli gönlüm Aşkın kanunu fermanı vermi...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/deli-gonlum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülendam', 'gulendam-haluk-levent-x7rfg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerinden ötesini 

Göremem göremem ben

Sözlerinden ötesini 

Duyamam duyamam ben

Gümüşyaka köprüsünü 

Ezberledim türküsünü

Ben sana hiç doyamadım

Gençlik çağı geldi geçti 

Döneceksen dön gel artık

Seni ben unutamadım

Ah gülendam can gülendam

Derdim dermanım ölurum ben aman

Saçlarından ötesini 

Tutamam tutamam ben

Ellerinden ötesini 

Saramam saramam ben

Gümüşyaka köprüsünü 

Ezberledim türküsünü

Ben sana hiç doyamadım

Gençlik çağı geldi geçti 

Döneceksen dön gel artık

Seni ben unutamadım

Ah gülendam can gülendam

Derdim dermanım ölurum ben aman', 'Gözlerinden ötesini  Göremem göremem ben Sözlerinden ötesini  Duyamam duyamam ben Gümüşyaka köprüsünü  Ezberledim türküsünü Ben sana hiç doy...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gulendam-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamadın', 'anlamadin-haluk-levent-5jjbq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Savurdum bu gençliği

Aşkın kör bahçesine

Güneşi yağdırdım kar beyaz düşlere

Sen beni anlamadın

Aşılmaz duvarları

Toz ettim yüreğimde

Aşkın kör pençesi saplandı gönlüme

Sen beni anlamadın

Anlamadın anlamadın 

Bir kez olsun sen beni anlamadın

Bu kentin akşamları

Son bulur gözlerimde

Kelebekler özgürdür hislerimse tutsak

Sen beni anlamadın

Aşılmaz duvarları

Toz ettim yüreğimde

Aşkın kör pençesi saplandı gönlüme

Sen beni anlamadın

Anlamadın anlamadın

Bir kez olsun sen beni anlamadın

ŞİİR: Haluk Levent 

Günler su gibi geçer

Şarap testilerinden damla damla

Sevdiceğim sözler kurşun gibi ağır

Ellerim soğuk gözlerim sağır

Sevdiceğim rüzgar Kimi zaman durur

Kimi zaman kudurur

Evren bir kuşun ağzında 

Solucan misali çırpınır durur', 'Savurdum bu gençliği Aşkın kör bahçesine Güneşi yağdırdım kar beyaz düşlere Sen beni anlamadın Aşılmaz duvarları Toz ettim yüreğimde Aşkın k...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/anlamadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakim Amca', 'hakim-amca-haluk-levent-ep78h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düşünmekle yıkılmaz kale duvarları

Ülkeme yakışmıyor trajediler

Anadolu barındıramaz yoz kafaları

Kitaplar yakılamaz ey efendiler

Söylemeli insan 

İnsan yapar onu bu kavram

Sindirmek olmaz özgürlük rüzgarını

Hakim savcı amca açın kapıları

Bırakın düşünen insanları

Sınırını çizemezsiniz

İnsanlığın beyninin

Atamazsınız bir hayvan gibi kafese

Sorgular sizi tüm tarih ve tüm bilim

Hesap verilir birgün

Halkın önünde halkın önünde

Hakim savcı amca açın kapıları

Bırakın düşünen insanları

Zincire vuramazsınız

Kafanızın dışındaki herşeyi

Onursuz yapamazsınız

Doğanın en muhteşem bedenini

Hesap verilir birgün

Halkın önünde halkın önünde

Hakim savcı amca açın kapıları

Bırakın düşünen insanları', 'Düşünmekle yıkılmaz kale duvarları Ülkeme yakışmıyor trajediler Anadolu barındıramaz yoz kafaları Kitaplar yakılamaz ey efendiler Söylemeli ...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hakim-amca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülün Bittiği Yer', 'gulun-bittigi-yer-haluk-levent-9sgj0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana gelemem gülüm gelemem

Sıyrılamam artık izlerinden

Doğrulamam gülüm yürüyemem

Paletler geçiyor dizlerimden

Sana gelemem gülüm gelemem gelemem

Düşlerin olurum düşmanın olurum gelemem

Gülün bittiği yerde içerdeyim

İşkenceler perde perde ne hallerdeyim

Sana gelemem gülüm gelemem

Sarpa sardım kendi izlerimden

Kement atsam yine çekilemem

Çivilendim gülüm gözlerimden

Sana gelemem gülüm gelemem gelemem

Düşlerin olurum düşmanın olurum gelemem

Gülün bittiği yerde içerdeyim

İşkenceler perde perde ne hallerdeyim', 'Sana gelemem gülüm gelemem Sıyrılamam artık izlerinden Doğrulamam gülüm yürüyemem Paletler geçiyor dizlerimden Sana gelemem gülüm gelemem ge...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gulun-bittigi-yer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiçe Açılan Kapılar', 'hice-acilan-kapilar-haluk-levent-xnyj3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiçe açılan kapılar önündesin

Çaresiz mutsuz yapayalnız

Nasılda bezgin bir haldesin

Yaşamak bir düş gibi

Ölmek her gün uykudan uyanmak sanki

Üzülürsün gecelere

Her adımda bir geçmişe

Gülmelisin geleceğe

Yaşayacaksın hiç çaren yok

Vurup vurup kaçanlara

Kazma kürek satanlara

Gülmelisin insanlara

Yaşayacaksın hiç çaren yok

Ölmek her gün uykudan uyanmak sanki

Hiçe açılan kapılar önündesin

Çaresiz mutsuz yapayalnız

Nasılda bezgin bir haldesin

Yaşamak bir düş gibi

Ölmek her gün uykudan uyanmak sanki', 'Hiçe açılan kapılar önündesin Çaresiz mutsuz yapayalnız Nasılda bezgin bir haldesin Yaşamak bir düş gibi Ölmek her gün uykudan uyanmak sanki...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hice-acilan-kapilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeye Dermanım Yok', 'sevmeye-dermanim-yok-haluk-levent-osa0a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Acı çekmek zevkim oldu

Yarınlarım dünden doldu

Şarkılar hep ama hep zehir oldu

Sevmeye dermanım yok 

Uzun uzun hikayeler

Terkettiler birer birer

Bu şehirden bak daha beter

Sevmeye dermanım yok

Sen cennetim ama sen cehennemim

Kaybolan giden acı tatlı günlerim

Sonunda kırılan yokolan benim

Sevmeye dermanım yok', 'Acı çekmek zevkim oldu Yarınlarım dünden doldu Şarkılar hep ama hep zehir oldu Sevmeye dermanım yok  Uzun uzun hikayeler Terkettiler birer b...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevmeye-dermanim-yok-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Samoslu Dimitris', 'samoslu-dimitris-haluk-levent-ceeu6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Torbalıdan aldım sapla samanı

Vurdum Selçuk üstüne

Rakımı hazırlamış Dimitris

Samosun tepesine 

Aynı sazı çalarız Akdeniz''in üstüne

Dimitris canım dostum

Şimdi tarihe küskün

Balıklar sınır dinlemez gülüm

Şarkılar söyler halkım

Aynı sazı çalarız Akdeniz''in üstüne', 'Torbalıdan aldım sapla samanı Vurdum Selçuk üstüne Rakımı hazırlamış Dimitris Samosun tepesine  Aynı sazı çalarız Akdeniz''in üstüne Dimitris...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/samoslu-dimitris-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Varamadım (Hoşçakal Bebek)', 'sana-varamadim-hoscakal-bebek-haluk-levent-zt1rp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akşamın ışıkları vurur parmaklarıma

Güneş batarken

Amcaların gölgesi girer rüyalarıma

Kabus bu dünya 

Duvarlar hep duvarlar

Sıkıştım annemin rahminde

İnsanlar bu insanlar öyle acı öyle yalancı

Hoşçakal hoşçakal bebek...

Düşünürüm insanları küçücük beyinleri

Mutlu olmaya yeter

Vuruyor insancıklar vuruyor insanları

Bu şarkı söylenirken

Şehirler hep şehirler aynı hepsi aynı mezar

Yaşamlar bu yaşamlar öyle acı öyle yabancı 

Hoşçakal hoşçakal bebek...

Seni kendimden çaldım

Tek başıma kaldım

Yalnızlıktan utandım ben

Adımlarımı sattım

Yarınlarımı attım

Sana varamadım ben', 'Akşamın ışıkları vurur parmaklarıma Güneş batarken Amcaların gölgesi girer rüyalarıma Kabus bu dünya  Duvarlar hep duvarlar Sıkıştım annemin...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sana-varamadim-hoscakal-bebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşktan Emir Var', 'asktan-emir-var-haluk-levent-ibh57', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevdam aşıkları utandırır

Aşkı bilmez padişaha ferman yazdırır

Dağlar sırayla bana yol verir

Yarimi göreyim düğün edeyim 

Kara kaşlı yar kara gözlü yar

Sen bana varacaksın

Aşktan emir var', 'Sevdam aşıkları utandırır Aşkı bilmez padişaha ferman yazdırır Dağlar sırayla bana yol verir Yarimi göreyim düğün edeyim  Kara kaşlı yar kar...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/asktan-emir-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Mesaj Gönder', 'bir-mesaj-gonder-haluk-levent-k03xs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gittin gideli İstanbul''dan

Beyaz günlerin hemen ardından

On beş mendil tükettim

Göz yaşlarım arasından 

Döneceğini bile bile

Yağmurlarım döndü sele

On beş mendil yetmedi 

Gözyaşımı sile sile

Bana bir mesaj gönder

Ellerin değsin yeter

Bana bir mesaj gönder

Gözlerin değsin yeter', 'Gittin gideli İstanbul''dan Beyaz günlerin hemen ardından On beş mendil tükettim Göz yaşlarım arasından  Döneceğini bile bile Yağmurlarım dön...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-mesaj-gonder-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmuyor Böyle', 'olmuyor-boyle-haluk-levent-gjnk6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Farkına varamadım bu orantının

Bendeki sen sendeki bana ağır geliyor

Daha fazla ''sen'' ver, ver diyemem ki

Bunu senden isteyemem gururum varmıyor

Sevgi çaba, sevgi emek, sevgi, alın teri

Ama olmuyor, olmuyor böyle

Sen ve ben ayrılıyor birbirinden

Bir ben kalıyorum kelimelerden

Soğuk bir çay masamda ve kağıt kalem

Olmuyor, olmuyor böyle', 'Farkına varamadım bu orantının Bendeki sen sendeki bana ağır geliyor Daha fazla ''sen'' ver, ver diyemem ki Bunu senden isteyemem gururum varm...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/olmuyor-boyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kral Çıplak- Şiir', 'kral-ciplak-siir-haluk-levent-akxyr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uzun kısa bir öykü bu

Sıradan sessiz bir film gibi

Görevim anlatmak oldu

Akıtmak bendeki zehiri

Yıllar önce bir genç vardı

Yüreğini yakan bir sevda

Herşey böyle başladı

Işıklar sönük kaldı

Tutunmuştu... köşe başı

Kalmamıştı açık kapı

Kaçtı durdu yıllar boyu

Herşey böyle başladı

Sonra bakmış dünya yokmuş

Umutları göçmüş gitmiş

Parasızlık yalan sarmış

Çareyi kaçmakta bulmuş

Küçük çarklar büyük çarklar

Birbirinden ne anlar

Döner durur zevke dalar

Yeni dişliler arar

Kendi oldu işte dişli

Bilmediği yola girdi

Gördü bütün gerçekleri

Sustu durdu herkes gibi

Şehir heyecanı aldı

Bunu da kendinden yaptı

Beyaz saçlar gözler söndü

Düşündeki düşte kaldı

Haluk uzak kendine

Kalmamış derman derdine

Yok sorunum mükemmelim

Dese de inanma sözüne

Kral nerde diye sorma

Sende bende bizde onda

Çıplak diyen kral olur

Taç giyen oturur tahtına

Patron burda köyde ağa

Evde koca okulda hoca

Dayı baba abi ana

Kral vardır her tarafta

Krallıklar ülkesinde

Doldurur seven kesesini

Haluk görür kaybedeni

Ne zaman baksa aynaya

İtaat et biz kralız

Toz kondurma kendimize

Aslında yok terzi bile

Giyisileri biz yaparız', 'Uzun kısa bir öykü bu Sıradan sessiz bir film gibi Görevim anlatmak oldu Akıtmak bendeki zehiri Yıllar önce bir genç vardı Yüreğini yakan bi...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/kral-ciplak-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek Böyledir İşte', 'sevmek-boyledir-i-ste-haluk-levent-f8hv0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir düş gördüm sonu olmayan

Gözlerimdeki bulut eridi birden

Odamdaki yıldızlar birer birer sönerken

Sakladığım güneş, çıkıverdi cebimden

Nedir seni sevdiren anlayamadım

Kafam karmakarışık uyuyamadım

Yatağımda boşluksun ama

Yastığımdaki çukursun bana

İşte her gece sen düşlerime düşünce

Yerle bir yelkovan yerle bir akrep

Gündüzleri yok ki zaten

Oyunlar bir bilmece

Ne düşteyim ne gerçekte

Sevmek böyledir işte', 'Bir düş gördüm sonu olmayan Gözlerimdeki bulut eridi birden Odamdaki yıldızlar birer birer sönerken Sakladığım güneş, çıkıverdi cebimden Ned...', ARRAY['Türk Edebiyatı','Şiir','Haluk Levent']::text[], 8.5, '{"poet":"Haluk Levent","poet_slug":"haluk-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevmek-boyledir-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelebeğin Düşü', 'kelebegin-dusu-gokcen-duran-q60y3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Küçük bir tırtıldı, kelebek oldu

Ona, bir günlük hayat sunuldu

Hayatı kısacıktı, durmamalıydı

Kanatlarını çırpıp, bir çınara konmalıydı

Sorguluyordu hayatı, kararlıydı

Çınar ağacına sorular sormalıydı

Sorularına cevaplar bularak, 

Kısacık hayatını anlamlandırmalıydı.

Sordu çınara; 

Niçin yüz yıllar sunulmuş sana

Bana, kısacık bir hayat sunulmuşken

Bir şeyler söyle hayata dair

Yaşamım  mutluluk versin bana

Çınarın cevabı; 

Hayatın güzelliği uzunlukta değildir.

Sana binlerce örnek verebilirim.

Eğer anlamlandırırsam  hayatımı

Bir günü yüz yıla çevirebilirim

Kelebek anlamıştı

Çınar çok şey öğretmişti ona, uçmalıydı

Özgürlüğe sevinçle kanat çırpmalıydı

Bir hayatı bir güne sığdıracaksa

Bir günü yüz yıl gibi yaşamalıydı', 'Küçük bir tırtıldı, kelebek oldu Ona, bir günlük hayat sunuldu Hayatı kısacıktı, durmamalıydı Kanatlarını çırpıp, bir çınara konmalıydı Sorg...', ARRAY['Türk Edebiyatı','Şiir','Gökçen Duran']::text[], 8.5, '{"poet":"Gökçen Duran","poet_slug":"gokcen-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kelebegin-dusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Gari', 'hadi-gari-alim-vedat-suner-akbv9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bak işte geldim

durdum karşına

söyle hadi sevgilim

anlat derdini bana

kalmasın içinde sıkıntı

anlat da rahatla

istersen öldür beni

yeterki SEN mutsuz olma

ne suçum oldu ki

seni sevmekden başka

neden bu tavırların

anlat herşeyi bana...! ! !', 'bak işte geldim durdum karşına söyle hadi sevgilim anlat derdini bana kalmasın içinde sıkıntı anlat da rahatla istersen öldür beni yeterki S...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hadi-gari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günlük''den', 'gunluk-den-alim-vedat-suner-96vo6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bugün yine

dünkü gibi yalnızdım

bu kent''de

yine üzerime geldi

tüm korkularım, endişelerim

açılmadı gene çalan telefon

bugün de dünkü gibi

Lanetler yağdırdım

Sevgilime...', 'bugün yine dünkü gibi yalnızdım bu kent''de yine üzerime geldi tüm korkularım, endişelerim açılmadı gene çalan telefon bugün de dünkü gibi La...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gunluk-den-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyiş', 'bekleyis-alim-vedat-suner-7o939', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bitmiyor geceler

Sonsuz bir zaman var önümde

Yalnızlık hiç çekilmiyor

Resmin varken elimde

Tükenmiyor bu sevda

Sensizlik varken koynumda

Bitmek bilmiyor gece

Son bakışın hala aklımda

Uyku girmiyor gözüme

Hayalin varken önümde

Ben hala sana aşık

Ben hala seninim

Hayallerimle Benliğim''de', 'Bitmiyor geceler Sonsuz bir zaman var önümde Yalnızlık hiç çekilmiyor Resmin varken elimde Tükenmiyor bu sevda Sensizlik varken koynumda Bit...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bekleyis-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belirsiz', 'belirsiz-alim-vedat-suner-f4rjx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Akşam olacak

Ve hüzün dolacak şehre

Ben yine yalnız

Ben yine sensiz olacağım

Belkide vurup başımı dalacağım

Deniz kenarında ufuklara

Belkide yok olacağım

Sensizliğin kaderiyle', 'Akşam olacak Ve hüzün dolacak şehre Ben yine yalnız Ben yine sensiz olacağım Belkide vurup başımı dalacağım Deniz kenarında ufuklara Belkide...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/belirsiz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukkene...', 'cocukkene-alim-vedat-suner-949cn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ben

çocukken

tanımazdım

ferhat ile şirini

leylenın yolunda

ölen

mecnunu

tanımazdım

kötüyü

bilmezdim

ölümü

taki

sevene kadar

SENİ...', 'ben çocukken tanımazdım ferhat ile şirini leylenın yolunda ölen mecnunu tanımazdım kötüyü bilmezdim ölümü taki sevene kadar SENİ......', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cocukkene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutsuzum', 'umutsuzum-alim-vedat-suner-sqhh4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'o gitti artık hiç dönmeyecek

ne gün doğacak artık

nede akşam olacak

senli düştüğüm zamanlarda

esecek artık arkamdan

ayrılık rüzgarı

sevgisiz herşey boş

ve anlamsız karanlık olacak

korku içinde

sensiz geçecek zaman

kalbimde ki acı hiç dinmeyecek

mutsuzum

senden

ayrıyım

        sen gittin

             artık hiç

                  dönmeyeceksin', 'o gitti artık hiç dönmeyecek ne gün doğacak artık nede akşam olacak senli düştüğüm zamanlarda esecek artık arkamdan ayrılık rüzgarı sevgisiz...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/umutsuzum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıpsın', 'kayipsin-alim-vedat-suner-r9hxq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nameydin çığlık oldun

Haykırdım seni dağlara

Dalında Gonca bir güldün

Kokladım koparmadan seni Yanlızlığımda

Şimdiyse

Ne bir çığlık kaldı

Ne de bir kokun

Kaybetmişim herşeyi

Senin gibi

Kayboluyorum

Bu yolda', 'Nameydin çığlık oldun Haykırdım seni dağlara Dalında Gonca bir güldün Kokladım koparmadan seni Yanlızlığımda Şimdiyse Ne bir çığlık kaldı Ne...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kayipsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Kelimem Olsada Adın', 'son-kelimem-olsada-adin-alim-vedat-suner-dp2e7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Son kelimem olsa da adın

Adını kalbime kanımla yazdım

Kalbimden silinirse adın

Yere akacak kanım

Son damla da olsa

Akacak kanım

Seni unutacaksa yarınım

Ölmek benim alın yazım

07.05.2002 / P.tesi

Yer yok, Mekan Yok...', 'Son kelimem olsa da adın Adını kalbime kanımla yazdım Kalbimden silinirse adın Yere akacak kanım Son damla da olsa Akacak kanım Seni unutaca...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/son-kelimem-olsada-adin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senliyse Ölüm', 'senliyse-olum-alim-vedat-suner-t6mae', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her anım sana yazılı

Her dakikam senli geçiyor

Sen yoksun

Gözlerimi sensizlik bürüyor

Nerdesin sevdiğim

Her kimlesin? 

SON gecem olsun razıyım

Seni son kez görmek

Ellerine kavuşmak son isteğim olsun

Ölümse gelen odama

Yeterki senli olsun...', 'Her anım sana yazılı Her dakikam senli geçiyor Sen yoksun Gözlerimi sensizlik bürüyor Nerdesin sevdiğim Her kimlesin?  SON gecem olsun razıy...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/senliyse-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarıkız Mermerleri', 'sarikiz-mermerleri-omer-bedrettin-usakli-tclpr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Afrodit, aşk tahtını kurmuş yüksek başında, 

Yakubun rüyasından sanki iz var taşında...

Şahikanda yaşamış efsane dünyaları, 

Senden birer parçaymış kainatın dağları...

Yalçın tepelerinde kartal saklı yuvalar, 

Eteğinde Aşil''den ses veren Truvalar; 

Binbir çiçek açarken ormanlarında yer yer, 

Saçlarını tararmış körfezinde periler...

Bahar, meşalelerle sende alkışlanırmış, 

Yapraklar solarken de başında ağlanırmış...

Venüs, şen sahilinde yatarmış kumsallara, 

Her taşın bir taç gibi sunulmuş krallara...

İlyad''ı çamlarının dibinde yazmış Homer, 

Lesbos''tan akşamları seyretmiş seni Bodler...

Barbaros, göklerinde tanımış ülkelerini, 

Yeşil ormanlarında yapmış gemilerini...

Sarıkız''ın derdiyle çatlamış kayaların, 

Sarıkız''ı anarak esiyormuş rüzgarın...

Taşında ve suyunda ağlıyor onun sesi, 

Zümrüt tepelerinde türkmenlerin kabesi...

Mağrur güzelliklerin ruhunda ve tenimde, 

Senin yüksek başından dileğim var benim de...

Bir şey istemiyorum, ne çiçek, ne de çemen...

Ne dağ çileklerinden, ne beyaz çam balından, 

Ne gemiler yapılan o kızıl çam dalından...

Ne ceylan, ne de ince türkmen dilberlerinden...

Bir parça istiyorum meşhur mermerlerinden...

Ne üstüne destanlar, sevdalar yazmak için; 

Ne şekilsiz derdime bir şekil kazmak için...

Fıskiyeli havuzlar, heykeller kurmuyorum; 

Mermerinden saraylar yapıp oturmuyorum; 

Bir şelale parçası, bir kevser ister gibi, 

Onu çürütmeyecek bir cevher ister gibi; 

Bir parça istiyorum meşhur mermerlerinden...

Ne ceylan, ne de ince türkmen dilberlerinden; 

Sarıkız''ın gözyaşı damlamış bir yerinden

Bir parça istiyorum meşhur mermerlerinden...

Toprağına gömdüğüm bir dağ sümbülü için, 

Eteğine koyduğum bir küçük ölü için...', 'Afrodit, aşk tahtını kurmuş yüksek başında,  Yakubun rüyasından sanki iz var taşında... Şahikanda yaşamış efsane dünyaları,  Senden birer pa...', ARRAY['Türk Edebiyatı','Şiir','Ömer Bedrettin Uşaklı']::text[], 8.5, '{"poet":"Ömer Bedrettin Uşaklı","poet_slug":"omer-bedrettin-usakli","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/sarikiz-mermerleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenim', 'ogretmenim-suleyman-apaydin-vx23t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yolsuz köye gittin yaya

Gönül verdin çağdaşlığa

Karanlığı del dedinya

Deleceğim öğretmenim

Olur ettin olunmazı

Deldin kaleminle taşı

Bil dedinya bilinmezi

Bileceğim öğretmenim

Karanlığı yırta yırta

Çıkacağız aydınlığa

Işık ol da ak dedinya

Akacağım öğretmenim

Kin gütmedin yüreğinde

Hoş gördün hep densizi de

Her bir canı sev dedinya

Seveceğim öğretmenim

Sor dedinya sen her şeyi

Gör dedinya gerçekleri

Yık dedinya hurafeyi

Yıkacağım öğretmenim

Kuru ekmek zeytin yedin

Karda kışta sürgün gittin

Bildiğinden hiç dönmedin

Ne büyüksün öğretmenim', 'Yolsuz köye gittin yaya Gönül verdin çağdaşlığa Karanlığı del dedinya Deleceğim öğretmenim Olur ettin olunmazı Deldin kaleminle taşı Bil ded...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Apaydın']::text[], 8.5, '{"poet":"Süleyman Apaydın","poet_slug":"suleyman-apaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ogretmenim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anam Bahardır', 'anam-bahardir-kamil-aydemir-9bhnh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'anam günleri eğirir

bize mutluluk örer

fırtına olsak da bizler

o sabrıyla önümüze geçer

güzelliğin her türlüsü anamda vardır

anam bahardır

kırk parçaya bölünür anam

sevindirir hepimizi

anam geceleri yağar yastığına

tanık olmadım

çirkin bir sözü

  kiraz dudaklarına astığına

yıkar günleri hüzünleri ayırır

napuzar tarla gibidir anam

bereket fışkırır

çıplak ağacı çiçeklerle bezetir gibi

yokluğa sevgisini giydirir

bize fakirliğimizi bile sevdirir

anam bahardır

sevmeyi öğretir

çiçekler eksilmez dallarımdan

anam bahardır', 'anam günleri eğirir bize mutluluk örer fırtına olsak da bizler o sabrıyla önümüze geçer güzelliğin her türlüsü anamda vardır anam bahardır k...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/anam-bahardir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bunları Bilebilsen...', 'sen-bunlari-bilebilsen-yucel-donmez-9cmyn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni sanki geçmişteki bir yaşamdan

Tanır gibiyim

Öylesine işlemişsin tutkularıma

Hani insan duyguların ötesine uçar ya

Sabahlara hasret bırakmışsın içimde...

Güneş yaşamdan yana doğar

Soluk alışımın simgesi gibisin

Anlaşılmaz bir yabancılaşmayı kırmışsın 

Düşlerim akşamların gizeminde 

Özlemim bir çift gözlerinle dağılıyor...

Biliyorum her coşkulu umut gibi

Bir gün sende gideceksin

Başka bir yaşamda karşılaşırmıyız

Çağlar ötesindeki bilinmez bir gezegende

Yine trenler taşırmı insanları

Alışırmıyım sensizliğe...

İşte bunları düşünmek kahrediyor ya beni...

İlkbaharda çiçek açan ağaçlar

Sonbaharda yapraklarını döktü

Hiç bir şey eskisi gibi değil

Dünya bir değişim ağrısında

Ha doğurdu doğuracak

Sen değişecekmisin bilinmez...

İşte bunların ağırlığında

Kulaklarımı tıkıyorum...

Doyumsuzluğum bir nehrin

Bin metreden dökülüşü

Hasretin dağlarında sis bulutları

Aşkım Antartikadaki eriyen buzullarda

Yüzyıllar sonraki denizleri taşıracak

Yakın zamanda değişirmiyim bilmem...

İşte bu duyguların tutsaklığında

Bir sigara daha yakıyorum...

Şiirleri yeterince yaşadık

Öyküler yazılamayacak kadar çoğaldı

Seni 30 ciltlik bir romanın

Kapağına taşırım ya

Sen bunları bilebilsen...

İşte hissetmediğini bir gün

Duyacağımdan korkuyorum...', 'Seni sanki geçmişteki bir yaşamdan Tanır gibiyim Öylesine işlemişsin tutkularıma Hani insan duyguların ötesine uçar ya Sabahlara hasret bıra...', ARRAY['Türk Edebiyatı','Şiir','Yücel Dönmez']::text[], 8.5, '{"poet":"Yücel Dönmez","poet_slug":"yucel-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/sen-bunlari-bilebilsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günlük 2001', 'gunluk-2001-yucel-donmez-qgoda', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eski şiirlerimizde kuşluk vakti vardı 

Horozlar öterdi vakitli vakitsiz 

Sabah ezanıyla başlardı günler 

Gusul abdesti buzlu suyla bile alınırdı 

Kargalar öterdi durmadan tepemizde 

Kız arkadaşımız olmazdı 

Kız peşine giderdik... 

İlk çıplak kadını 

Kleapotra filminde gördüm 

Liz Taylor ile nedense yıllar sonra tanışabildik... 

İsmet İnönü’nün elini öptüm 

Turgut Özal ile sohbetim oldu 

Amerika başkanlarıyla şakalaştım 

Aşık Veysel bize saz çaldı 

Nene Hatun’u evinde ziyaret ettik 

Ruhi Su ile birlikte sahne aldık 

Kuzgun Acar ile dağları dolaştık 

Ergin Kolbek akademi çatısından atmazdı kendisini 

İstanbul’da olsaydık 

İlk Kanlı Pazarın canlı tanığı oldum 

Polis bıçağı sokarken bir gencin karnına 

Çektiğimiz filmin karesine takıldı 

Sonra Demirel filmi yasakladı... 

Dündar Kılıç ile oturduk 

Marlo Kemal ile bitirimler dünyasını konuştuk 

Fazıl Hüsnü Dağlarca dağ gibiyken 

Nihat, Ataol, Edip Cansever ve ben 

Bulgar votkası içip edebiyat konuştuk 

Stud Terkel ile tanıştırdığımda arkadaşlarım 

‘biz bu yazarı üniversitede okuduk’dediler 

Tennesse Williams’ın yeğeni ile arkadaş oldum 

Arnold Schwartzenegger''e Türkiye’yi anlattım 

Brooke Shields ile bir gecede sarhoş olduk 

Sophia Loren bana zeki Müren’i sordu 

Sonra Roger Moore ile karşılaştım 

James Bond imajım silindi 

Muhammed Ali’nin evinde yemek yedim 

Türkiye’deki otel projesini konuştuk 

Kararlıydı ancak parkinson gelmeseydi 

Ve bir gün Kadıköy’de, sular idaresinin orada 

Bilmem hangi marka arabanın içinden bir genç 

Kafasını uzatarak bağırdı; 

‘Dayı bu yol yayalar için değil’ 

İyi ama kaldırım diye bir şey yoktu ki... 

Şimdilerde her şey bir çılgın 

Nerede 68 kuşağı nerede yıl 2000 

Nerede yaşadıklarımız, nerede bıraktıklarımız... 

Bakıyorum da, artık o sıcak balıkçı lokantaları yok 

Köprü altında balık ekmek bile kalmamış 

İnsanlar aceleci 

Beyazıt’ta oturup çay içmek bile anı olmuş 

Görürsek birbirimizi eski arkadaşlar ile 

Yine konuşuyor, yine çocuklaşıyoruz 

Dönülmüyor ki gidene... 

Ulaşılmıyor ki yitirilenlere... 

Bir bakıyorsun akşam olmuş 

Bir bakıyorsun beş yıl birden geçmiş 

Oturup düşünüyorsun 

Ne garip dünya 

İnsanlar yaşlanıyor 

Günler yine cıvıl cıvıl 

Birileri beklemelerde takılırken 

Birileri hiç ölmeyecekmiş gibi 

Oysa çocuklar aç olmamalı 

Çocuklar hep gülmeli 

Verecen olmalıyız, sevecen 

Neyse ki,25 yıl daha yaşamayı planlıyorum 

On beş yıl sonra bu şiiri yenilemeyi 

20 yıl sonra kalırsa, bir kahvede tavla oynamayı 

Yaşayan arkadaşlarımın listesini tutmayı 

İşte ne bileyim planlıyorum...', 'Eski şiirlerimizde kuşluk vakti vardı  Horozlar öterdi vakitli vakitsiz  Sabah ezanıyla başlardı günler  Gusul abdesti buzlu suyla bile alın...', ARRAY['Türk Edebiyatı','Şiir','Yücel Dönmez']::text[], 8.5, '{"poet":"Yücel Dönmez","poet_slug":"yucel-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/gunluk-2001-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitseniz Hasret Büyütürsünüz Kalsanız Açlık', 'gitseniz-hasret-buyutursunuz-kalsaniz-aclik-kamil-aydemir-zbhwd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hep uzaktaki küçük şehirler gibi unutulursunuz

tanıyorum sizleri gençler

gitseniz hasret büyütürsünüz

kalsanız açlık

bazılarınızın da sırtında

mutluluğuna saplanmaya hazır hançer başlık

hayattan size her gün

acılar harçlık

siz kumadınız bu çarkı ama

dişlerine doğdunuz

kanarken yurdumuz

hep lal oldunuz

avare gördünüz

kendinize hasretlerden

  açlıklardan bir yaşam ördünüz

sulayın yaşama sevincinizle

yine de solmasın umudunuz

derman olursanız

mutlulukistanda olur yurdumuz', 'hep uzaktaki küçük şehirler gibi unutulursunuz tanıyorum sizleri gençler gitseniz hasret büyütürsünüz kalsanız açlık bazılarınızın da sırtın...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gitseniz-hasret-buyutursunuz-kalsaniz-aclik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Latife’ler Olmasın...', 'yeni-latife-ler-olmasin-yucel-donmez-2mtq9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '''Latife bu toplumdaki insanlardan sadece biriydi. sevilmek istedi hemde çok sevildi, daha çok sevilmek istedi... Onu son gördüğümde yeni Latife''ler olmasın diye dua ediyordu... ''

Artık aramam seni 

Suskunluğun güvertesindeyim 

Bu gemi nereye götürür bilmem 

Kurduğum düşler 

Anılarımız 

Yok olduk anlıyormusun 

Yıktık herşeyi... 

Hadi istediğin oldu 

Seni bırakmazlar artık 

Barlarda sabahlar 

Loş bir odada 

Romantizmin sekse dönüşümünü yaşarsın 

Sonra, 

Yeniden terkedilmişliğin acısı... 

Bu ne ilk, ne son, nede üçüncü beşinci olacak 

Sen ki kaderini böyle çizdin 

Sorun yok... 

Biliyormusun 

Latife yeni çevrelere girsin diye 

Yeni arkadaşlar bulmuş 

Sonra genelev malı olmuştu. 

Latife zekiydi olgundu 

Suçu 20 yaşında olmasıydı 

Körpeliği yıktı ya başını 

Sandıki iltifatlar, ilgiler 

Onu sırça köşklere götürecek. 

Dünyada bir tek o vardı, yine o vardı... 

Bir gün bir otel odasının tozlu köşesinde unutulunca 

Geçmişe dönmek istedi 

Düşünemedi bile geçmişi 

Her şeyin rengi kararmış 

Yaşamın böylesine donacağı ona anlatılmamıştı... 

Sonra Latife’ye ne oldu diyeceksiniz... 

Gelin Latife’nin öyküsünü burada keselim 

Onu yeterince üzdük 

O yeterince üzüldü 

Yeni Latife’ler olmasın diye dua ediyordu son gördüğümde... 

Aşkın gözü kör 

Bazen çatıya konmak isterken 

Bacadan içeri düşüveriyor...', '''Latife bu toplumdaki insanlardan sadece biriydi. sevilmek istedi hemde çok sevildi, daha çok sevilmek istedi... Onu son gördüğümde yeni Lat...', ARRAY['Türk Edebiyatı','Şiir','Yücel Dönmez']::text[], 8.5, '{"poet":"Yücel Dönmez","poet_slug":"yucel-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/yeni-latife-ler-olmasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Roma''yı Yakarım...', 'yine-roma-yi-yakarim-yucel-donmez-vr2wv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Üşüyorum 

Güneş yüreğime doğar mı 

Buz dağları çözülür mü 

Koştuğum yolun sonunda olurmusun 

Beklesem dayanırmıyım... 

Kollarımda özlem kalkanın 

Kurşun işlemez duygularıma 

Sevginin ulu denizlerinde 

Çılgın kasırgalar üretir 

Aşkın yüce doruklarından 

Kanat çırparım... 

Yeter artık 

Bahar doğsun 

Sabrım coşmasın 

Yoksa Neron olur 

Yine Roma’yı yakarım...', 'Üşüyorum  Güneş yüreğime doğar mı  Buz dağları çözülür mü  Koştuğum yolun sonunda olurmusun  Beklesem dayanırmıyım...  Kollarımda özlem kalk...', ARRAY['Türk Edebiyatı','Şiir','Yücel Dönmez']::text[], 8.5, '{"poet":"Yücel Dönmez","poet_slug":"yucel-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yine-roma-yi-yakarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çektiğim Acılar Selamın Olacak', 'cektigim-acilar-selamin-olacak-yucel-donmez-bjegj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''Şimdi sevginin ıssız ormanlarında yolunu arayan bir tutsağım. Elimi tuttuğum her dal seninle kırılıyor. Sana ulaşamamanın yankısını yaşıyorum. Dağlara ulaşabilirsem belki aşarım.'' 



Sana bu üçüncü mektubumu aşkın zindanından yazıyorum. 

İnsan gerçekten sevdiği zaman özlemin tadı daha başka oluyor. O an dünyayı bağışlasalar göremiyorsun… 

Aşkın kör karanlıklarında yolunu arayan bir ceylan yavrusunun ürkek kalp atışlarındasındır. Bu sevgiliye kavuşabilmenin soluksuz çırpınışıdır. Ya sevdiğine ulaşırsın yada bir avcının talihsiz kurşunu seni bulacaktır. İşte o anda yıkılırsın. Kalbine saplanan kurşun değil, sevginin hançeri olur, tükenirsin… 

Şimdi sevginin ıssız ormanlarında yolunu arayan bir tutsağım. Elimi tuttuğum her dal seninle kırılıyor. Sana ulaşamamanın yankısını yaşıyorum. Dağlara ulaşabilirsem belki aşarım. 

Denizi tekrar görebilecekmiyim, dalgalarla boğuşmaya razıyım… 

Belki böylesi daha iyi. Hep bir umut yeşerecek içimde. Çektiğim acılar selamın olacak, öykü acılarla bile olsa surecek… 

Sana tekrar kavuşacağım gün, seni kaybedeceğimden korkuyorum… 

Sevdamı yargıladım 

Prangaya mahkum ettim kendimi 

Artik zindanlarındayım 

Gökyüzünü görmesemde olur 

Şu yoklugun olmasa', '''Şimdi sevginin ıssız ormanlarında yolunu arayan bir tutsağım. Elimi tuttuğum her dal seninle kırılıyor. Sana ulaşamamanın yankısını yaşıyor...', ARRAY['Türk Edebiyatı','Şiir','Yücel Dönmez']::text[], 8.5, '{"poet":"Yücel Dönmez","poet_slug":"yucel-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cektigim-acilar-selamin-olacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sırtıma Aşkını Vurmuşum Dağlar Gibi…', 'sirtima-askini-vurmusum-daglar-gibi-yucel-donmez-j2dhc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''Bir aşk bittiğinde umutlar yeniden canlanır. İstesende unutamazsın, kalbinin bir köşesinden ağrılar girer, Godo''yu beklercesine suskunsundur, patlayacağın günü beklersin. Ve bir gün geriye dönüp anılarına baktığında, her şey o kadar değişmiştir ki... ''

Hava soğuk sevdam 

Kışa bu derece yenilmemiştim 

Bahar çokmu uzaklarda dersin 

Hasretin buz dağları ne zaman erir 

Kalbine yol bulurmuyum oradan? 

Hiç böylesine umutsuz olmadım 

Bir yaprak düştüğünde sobahar dedim 

Gelincikler savruldugunda rüzgari suçladım 

Böylesine hasret çekecegimi 

Söyleselerdi inanmazdım 

Bir gün seni görürmüyüm 

Öyküye yeniden başlarmıyız 

Sen yine o trende olurmusun? 

Sırtıma aşkını vurmuşum 

Dağlar gibi 

Dünyaya meydan okuyorum biliyormusun', '''Bir aşk bittiğinde umutlar yeniden canlanır. İstesende unutamazsın, kalbinin bir köşesinden ağrılar girer, Godo''yu beklercesine suskunsundu...', ARRAY['Türk Edebiyatı','Şiir','Yücel Dönmez']::text[], 8.5, '{"poet":"Yücel Dönmez","poet_slug":"yucel-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sirtima-askini-vurmusum-daglar-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlar Çaresiz Kaldığında...', 'umutlar-caresiz-kaldiginda-yucel-donmez-st385', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''Sen ki, eğlenmek adına harcadın sevgimizi. Çaresizliğinde uykuyu aradın. Oysa, herşeyiyle özgündü yaşadıklarımız. Şimdi yalnızlığın öbür yüzündesin, bunu sen istedin biliyormusun... ''

Mutluluk sadece eglenmekse 

Seninle her gun dans ederim 

Kurtulus ebedi uyumaksa 

Neden yasamak adina savaşıyoruz? 

“Sen ki duygularını 

Üç kuruşluk barlarda harcadın” 

Gerçek bir gün sert rüzgara dönüşür 

Kaçmak istesen bile kurtuluşun olmaz 

Oturup geçmişi yargılarsın 

Anılar duvar örer suratına 

Kuru kuru ağlarsın 

Yaşam dürüstlük üzerinedir 

Ölümsüz aşklar kuşku taşımaz 

Sevildiğini bilirsen düşünürsün 

Düşünürsen doğruyu bulacaksın 

Belki anlık mutluluklar yaşarsın 

Günlük, aylık, belkide yıllık 

Sonra mutluluk korkuya dönüşebilir 

Geç kaldığını anladığında 

Uykuyu arar insan... 

Uyumak aptalca kurtuluş çağrısıdır 

Çare ararsın tükenmiştir 

Bağırırsın duyulmaz 

Dönüp geriye bakarsın, 

Anılar son yapraklarını döküyordur 

Kala kalırsın... 

İşte bundan korkuyorum aşkım... 

Umutların çaresiz kaldığında 

Ben yanında olmayacağım 

Çünkü buna dayanamam', '''Sen ki, eğlenmek adına harcadın sevgimizi. Çaresizliğinde uykuyu aradın. Oysa, herşeyiyle özgündü yaşadıklarımız. Şimdi yalnızlığın öbür yü...', ARRAY['Türk Edebiyatı','Şiir','Yücel Dönmez']::text[], 8.5, '{"poet":"Yücel Dönmez","poet_slug":"yucel-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/umutlar-caresiz-kaldiginda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek', 'gercek-ozgur-arslan-ss52v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gercek nedir bilmek istermisin? 

Hayat nedir sorgulamaya, 

Acı nedir dindirmeye, 

Sevgi nedir paylaşmaya, 

Dostluk nedir sonsuza deyin sürdürmeye, 

Gizli olanı aramaya, sorunun cevabini bulmaya.

Kalbin konuşuyor, Sus ve dinle! 

Bak neler söylüyor kendi kendine: 

''Hayat için nefes almak, 

 Aci için hayati anlamak, 

 Sevgi için  hayati paylaşmak, 

 Dostluk için hayati, aciyi, sevgiyi paylaşmak.''

 Sonra ekliyor, devam ediyor: 

''Hayat diyor bilmece, 

 Aci diyor seçmece, 

 Sevgi diyor kandirmaca, 

 Dostluk diyor hepsinden yüce.''', 'Gercek nedir bilmek istermisin?  Hayat nedir sorgulamaya,  Acı nedir dindirmeye,  Sevgi nedir paylaşmaya,  Dostluk nedir sonsuza deyin sürdü...', ARRAY['Türk Edebiyatı','Şiir','Özgür Arslan']::text[], 8.5, '{"poet":"Özgür Arslan","poet_slug":"ozgur-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gercek-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deymedi Deymedi', 'deymedi-deymedi-bayram-tunca-hnhmt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Deymedi deymedi ak ellerim deymedi

Deymedi deymedi pak tenim deymedi

Deymedi deymedi şu gözlerim deymedi

Deymedi deymedi kem sözüm deymedi

Deymedi deymedi kulağım şahit deymedi

Deymedi deymedi burnum şahit deymedi

Deymedi deymedi dudağım şahit deymedi

Deymedi deymedi azalarım şahit deymedi

Deymedi deymedi yeminim olsun deymedi 

Ne elim, ne dilim haram lokmaya deymedi

Deymedi deymedi yeminim olsun deymedi

Ne elim ne de tenim namahreme deymedi

Eymedi eymedi o başka aşka boyun deymedi

Vermedi vermedi senden başkasına yüz verdi

Sevmedi sevmedi Bayram başka yâr sevmedi

Ama yine de bu kadar çileye bu aşk deymedi

Sanılmasın ki  bu şair Bayram light/soğan erkeği

Yine sanılmasın ki şair Bayram bilmez aşkı meşki

O aşkı bilmeseydi, sayısız aşk şiiri yazabilir miydi

O helal dairesi keyfe kafidir prensibini ilke edindi

B. Tunca/24.11.2002-11.24', 'Deymedi deymedi ak ellerim deymedi Deymedi deymedi pak tenim deymedi Deymedi deymedi şu gözlerim deymedi Deymedi deymedi kem sözüm deymedi D...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/deymedi-deymedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Kentte', 'bu-kentte-haci-yusuf-kiymazarslan-1hsjk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu kentte kaybettim umutlarımı

Çıkarıp koynumdan bulut bulut

Attım sokaklara darmadağın

Ama ne umut.. ne umut...

Umut taşır otobüsler caddelerde

Ilım ılımdır yürekler bir hoş

Dönen tekerleklerde ezik

Gecekondularda nahoş

Türküler duyulur buruk mu buruk

Hasret üstüne yar üstüne

Bu kentte kaybettim umutlarımı

Belki cebecide, Hamamönünde

Başkent doğarken bir akşam üstü

Çıkarıp koynumdan bulut bulut

Bu kent''e verdim umutlarımı

Ama ne umut ne umut...', 'Bu kentte kaybettim umutlarımı Çıkarıp koynumdan bulut bulut Attım sokaklara darmadağın Ama ne umut.. ne umut... Umut taşır otobüsler caddel...', ARRAY['Türk Edebiyatı','Şiir','Hacı Yusuf Kıymazarslan']::text[], 8.5, '{"poet":"Hacı Yusuf Kıymazarslan","poet_slug":"haci-yusuf-kiymazarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-kentte-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rotasız Gemi', 'rotasiz-gemi-haci-yusuf-kiymazarslan-6rklw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sahilde dalga hırçın

Yolar saçlarını maviler içinde

Ezik yaşamaktan sarhoş

Acı şarkılar dilinde

Bilmem hangi kentin kuzey sahilinde

Bir gemi batar boyuna kadar

Hamulesi düşüncedir heyhat! 

Batan günden imdat ister

Doğan güne isyan eder

Bilmem hangi kentin kuzey sahilinde...

Kaptan habersiz tayfalardan

Sola kırar dümeni, sola kırar

Tüm umutlar suyun dibinde

Sarılacak yılan arar

... Kaç senedir sonsuz ufuk, dümen kırış

Sonu gelmeyen deryalar içinde

Meçhul geminin tayfalarında

Acaip yaşayış

Bilmem hangi kentin kuzey sahilinde...

Demirleyecek belki bir gün

Bel bağladığımız güzelim umutlar

Sularda kalacak bütün...', 'Sahilde dalga hırçın Yolar saçlarını maviler içinde Ezik yaşamaktan sarhoş Acı şarkılar dilinde Bilmem hangi kentin kuzey sahilinde Bir gemi...', ARRAY['Türk Edebiyatı','Şiir','Hacı Yusuf Kıymazarslan']::text[], 8.5, '{"poet":"Hacı Yusuf Kıymazarslan","poet_slug":"haci-yusuf-kiymazarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/rotasiz-gemi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Dua', 'son-dua-aysel-gurel-f62z3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gel aşk, sana son duadayım

Düşler içinde yanlışlıktayım

Çöllerin insafsız sıcağındayım

Bu defa sevmeyen ben olmalıyım

Gel aşk gel, bir yeni aşk getir

Tenimde uyuyup nefes alan

Güller açmadan gül gibi kokan

Tam günümdeyim aşk bana gel

Son defa, bu son dua, son dua

Gel durma, bahar vurmuş başıma

Mutsuzum, zor tek başıma

Son defa, bu son dua, son dua', 'Gel aşk, sana son duadayım Düşler içinde yanlışlıktayım Çöllerin insafsız sıcağındayım Bu defa sevmeyen ben olmalıyım Gel aşk gel, bir yeni ...', ARRAY['Türk Edebiyatı','Şiir','Aysel Gürel']::text[], 8.5, '{"poet":"Aysel Gürel","poet_slug":"aysel-gurel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/son-dua-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Sevgini Bana Sakla', 'sen-sevgini-bana-sakla-askin-tuna-33kwk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni seven olabilir

Sen onlara dönüp bakma

Sana aşık olan benim

Sen sevgini bana sakla

Uykuda ki gözler gibi

Söylenmemiş sözler gibi

Açılmamış güller gibi

Sen sevgini bana sakla

Ömründe ki her gününde

Hece hece sözlerinde

Yüreğinin ta içinde

Sen sevgini bana sakla', 'Seni seven olabilir Sen onlara dönüp bakma Sana aşık olan benim Sen sevgini bana sakla Uykuda ki gözler gibi Söylenmemiş sözler gibi Açılmam...', ARRAY['Türk Edebiyatı','Şiir','Aşkın Tuna']::text[], 8.5, '{"poet":"Aşkın Tuna","poet_slug":"askin-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-sevgini-bana-sakla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şeye Tıpatıp Uyan ve Her Şeyi Çoktan Bilenlerin Şarkısı', 'her-seye-tipatip-uyan-ve-her-seyi-coktan-bilenlerin-sarkisi-hans-magnus-enzensberger-0z0th', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir şey yapılması gerektiğini ve de hemen 

çoktan biliyoruz 

ama daha erken olduğunu bir şey yapmak için 

ama artık geç olduğunu bir şey daha yapmak için 

çoktan biliyoruz 

ve işlerimizin yolunda olduğunu 

ve bunun böyle süreceğini 

ve bunun anlamı olmadığını 

çoktan biliyoruz 

ve suçlu olduğumuzu 

ve suçlu oluşumuzda bir suçumuz olmadığını 

ve elimizden bir şey gelmeyişinde suçlu olduğumuzu 

ve bunun bize yettiğini 

çoktan biliyoruz 

ve belki de ağzımızı tutmanın daha iyi olacağını 

ve ağzımızı tutmayacağımızı 

çoktan biliyoruz 

çoktan biliyoruz 

ve kimseye yardım edemiyeceğimizi 

ve bize kimsenin yardım etmeyeceğini 

çoktan biliyoruz 

ve yetenekli olduğumuzu 

ve hiç ve gene hiç arasında seçme yapabileceğimizi 

ve bu sorunu temelden incelememiz gerektiğini 

ve çaya iki tane şeker attığımızı 

çoktan biliyoruz 

ve baskıya karşı olduğumuzu 

ve sigaraların pahalılaştığını 

çoktan biliyoruz 

ve her seferinde bir şeyin olacağını önceden kestirdiğimizi 

ve her seferinde haklı çıkacağımızı 

ve bundan bir şey çıkmayacağını 

çoktan biliyoruz 

ve her şeyin yalan olduğunu 

çoktan biliyoruz 

ve bir şeyi atlatmanın her şey değilde hiçbir şey olduğunu 

çoktan biliyoruz 

ve bizim bunu atlatacağımızı 

çoktan biliyoruz 

ve bütün bunların yeni olmadığını 

ve yaşamanın güzel olduğunu 

ve bunun her şey olduğunu 

çoktan biliyoruz 

çoktan biliyoruz 

çoktan biliyoruz 

ve bunu çoktan bildiğimizi 

çoktan biliyoruz.', 'bir şey yapılması gerektiğini ve de hemen  çoktan biliyoruz  ama daha erken olduğunu bir şey yapmak için  ama artık geç olduğunu bir şey dah...', ARRAY['Türk Edebiyatı','Şiir','Hans Magnus Enzensberger']::text[], 8.5, '{"poet":"Hans Magnus Enzensberger","poet_slug":"hans-magnus-enzensberger","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/her-seye-tipatip-uyan-ve-her-seyi-coktan-bilenlerin-sarkisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KIR Ciceqi', 'kir-ciceqi-gulay-atilay-cwohp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Acılarımı toparlayıp gideceğim bu şehirden 

Yollara düşeceğim, hayalin kalacak ardımda 

Kırık kalpler sokağında sensiz öleceğim 

Ve avuçlarımda bir damla gözyaşı....

****

Kalbimin kırıklarını toplayıp avuçlarıma 

Çekip gideceğim bu şehirden incinecek anılar

Ve bilecekler mi ki? 

Bir sevgiye karşılık yüreğini kanatanı..

**** 

Baharını saklayan yaşlı bir çocuğum ben 

Düşlerin yağmurunda ıslanmış KIR_Ciceqi

Kim dinler kalbimin kırık sesini artık 

Değip geçer ellerime ihanetin rüzgarı 

****

Hangi yağmurları müjdelersen müjdele 

Yeşermez bir daha yangının düştüğü yer 

Hüzün kokuyor artık zavallı KIR_Ciceqi 

Giden dönmedi terketti bütün mevsimler 

****

Bir tek gül kalmadı ömrümün bozkırında 

Şimdi yalnızlığın en tenha kışındayım 

Yüreğime ayaz vuruyor derinden.... 

Bedenime esiyor buzdan deli rüzgarlar 

Üşüyorum! ! ! 

26/Ekim/2002

Değerliği şairim Nuri Can beyin mükemmeliyetinin ispatı benim kalemimden

Teşekkürler Nuri bey....', 'Acılarımı toparlayıp gideceğim bu şehirden  Yollara düşeceğim, hayalin kalacak ardımda  Kırık kalpler sokağında sensiz öleceğim  Ve avuçları...', ARRAY['Türk Edebiyatı','Şiir','Gülay Atilay']::text[], 8.5, '{"poet":"Gülay Atilay","poet_slug":"gulay-atilay","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kir-ciceqi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merak', 'merak-aziz-pinar-0qdl8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu ne gürültü, ne var ne oluyor yukarda

Ne söylenip dururlar insanlar başucumda

İçime işlemekte soğuk yağmur suları

Neler yazılıdır acaba mezar taşımda...', 'Bu ne gürültü, ne var ne oluyor yukarda Ne söylenip dururlar insanlar başucumda İçime işlemekte soğuk yağmur suları Neler yazılıdır acaba me...', ARRAY['Türk Edebiyatı','Şiir','Aziz Pınar']::text[], 8.5, '{"poet":"Aziz Pınar","poet_slug":"aziz-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/merak-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İrticalen', 'i-rticalen-basar-celebi-2b5je', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevincin en kısa sürdüğü gece

Güneşi tahrip eden güvercinler karanlıkta kayboldu

Gül şehre büründü, şehir tene

Yaslandı omuzlarından aşağı karası

Tesadüf değildi hüzün

Ne uzun ne kısaydı

Sevincin en kısa sürdüğü gece

Makas yüklü kıvılcımların gösterisi seyredildi

O ne zehirli döngüydü bilemezsiniz

Siyah saçlarından döküldü çehresine

akşamüstünün çoşkusu

Marmara''da gözleri göründü

Sevinç çok kısa sürdü

Geceyarısıydı

Sevincin en kısa sürdüğü gece

Bir şairin gölgesi hüve-l bakiyle yaşıttı.', 'Sevincin en kısa sürdüğü gece Güneşi tahrip eden güvercinler karanlıkta kayboldu Gül şehre büründü, şehir tene Yaslandı omuzlarından aşağı k...', ARRAY['Türk Edebiyatı','Şiir','Başar Çelebi']::text[], 8.5, '{"poet":"Başar Çelebi","poet_slug":"basar-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/irticalen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Ölüm', 'yalniz-olum-aziz-pinar-iy3td', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biri dolanır gecelerde yalnız

Biri ağlar odalarda yalnız

Biri doğurur hasırlarda yalnız

ve biri ölür kalabalıklarda yalnız..', 'Biri dolanır gecelerde yalnız Biri ağlar odalarda yalnız Biri doğurur hasırlarda yalnız ve biri ölür kalabalıklarda yalnız.....', ARRAY['Türk Edebiyatı','Şiir','Aziz Pınar']::text[], 8.5, '{"poet":"Aziz Pınar","poet_slug":"aziz-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yalniz-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmeyecekmişsin', 'gelmeyecekmissin-basar-celebi-0vc7x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şaha kalkan filizlere demişsin

Duydukların yetim kalacak

Yarım kalmış sesin de ağlamaklı

Rivayete göre gelmeyecekmişsin

Yağmuru kandırdılar sonunda

Beni yağdı

Sahra ıslandı dediler, sahrası yalan

Parmakları buzdan kelebekler

Çiçeklerin derdine baharı beklemişler

Baharda ölen yağmurmuş

Kalan renklerin ağıtlarıysa benmişim sesim de ağlamaklı

Bu bahar gel desem de gelmeyecekmişsin

Bir neden var gibi ellerin uçurumvari

Tutmasan düşeceğim

Tutmasam, tutunmasam

Ne yazgısı suçlu ne kelebeklerin parmakları

Hastalık bu, tedavisi küsülmüş

Hekimler bile haberdar bildiklerimizden

Ve teşhis: 

Yara kapansa bile yere göğe sığsa imiş

Şu bizim yeminlerimiz ki ederken ağlamaklı

Vallahi gelmeyecekmişsin

Zamancılar, ille de beklesin dediler

dört yapraklı yoncayı

Bulunca dört elle sarılsın, baruta yaklaşmasın

Konuşmasın sevdikleri

Lal ayı

Ölümcül

Ve kapana kısılmış sesin -belki ağlamaklı-

Belki de hiç gelmeyeceksin.', 'Şaha kalkan filizlere demişsin Duydukların yetim kalacak Yarım kalmış sesin de ağlamaklı Rivayete göre gelmeyecekmişsin Yağmuru kandırdılar ...', ARRAY['Türk Edebiyatı','Şiir','Başar Çelebi']::text[], 8.5, '{"poet":"Başar Çelebi","poet_slug":"basar-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gelmeyecekmissin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alplerin kardeleni', 'alplerin-kardeleni-salih-ozalasan-yvr22', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgiler vardır, yaşamaya ömür yetmez

Sevgiler vardır, yaşanmakla bitmez

Sevgiler vardır, yaşamaya değmez

Sevgiler vardır, bir ömür versen yine yetmez

Ya benim sana olan sevdam

Sayfalar dolusu yazsam

Yıldızları kelime, somanyolunu virgül diye koysam

Yinede anlatmakla yazmakla bitmez

Aşkımız olur yazılsa, ağır bir roman

Okuyan kendini şokta bulur biran

Yaşayan bana sorsan lütfedip biran

Kaç kalem bitti, kaç sayfa oldu yazılan

Hem yazıyorum hem yaşıyorum 

Seninle hasreti aşkı özlemi

Oldu inanki boyu Dünya''nın enlemi düzlemi

Yüreğimde sevgin oldu bir bahar seli

Seni yaşıyorum sensiz yalnız seni

Senden uzak sana hasret gecemi

İsminle başlatıyorum artık her hecemi

Ömrüme ömür kattı, alplerin kardeleni', 'Sevgiler vardır, yaşamaya ömür yetmez Sevgiler vardır, yaşanmakla bitmez Sevgiler vardır, yaşamaya değmez Sevgiler vardır, bir ömür versen y...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/alplerin-kardeleni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeterince Öptüğümü Sanmıyorum Seni', 'yeterince-optugumu-sanmiyorum-seni-basar-celebi-mihxl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yeterince öptüğümü sanmıyorum seni

 Aruz ölçüsü kadar muntazam

 Ve sonsuz bir ebemkuşağına saklanması gereken kadın

 Yine de huri gibi her yerini görürüm

 Düşlerimi yoklasam

 Ben çağırdım

 Hiç hasretle bilenmeden şiir olan adaların

                                               son hünkarını

 Yaralarımda batırdığın gemilerin isyanı büyüktü

 Medcezirlere binmişti yakamozlar

 Nefretleri açıktı

 Ve açıklara dağ gibi yakışmıştı

 Sen taşırdın aslında

 Köpürdün balçıktan

 Upuzun ve karanfil burcundan

 Yağıverdin en geçlere

 Öksüz bıraktın Halici

                            ve tüm sahili...

 Küsmüştük hep bir ağızdan

 Bir daha gelme

 Bir daha gel-me

 Hüznün küreklere asılmış

 Konar-göçer bir cem vakti pir idi

 Semahla boyandı

                        uzadı gitti...

 Ne vardı sanki

 Ya da

 Ne zalim bir an ki

 Usancıma göçüveren en adi

 Balıkçılların kanadından düşüverdin gönlüme

 Maalesef oldu bir kere

 Ne diyeceğimi bilemiyorum ama

 Değişti kalbimin yeri

 Ve hala yeterince öptüğümü sanmıyorum seni.', 'Yeterince öptüğümü sanmıyorum seni  Aruz ölçüsü kadar muntazam  Ve sonsuz bir ebemkuşağına saklanması gereken kadın  Yine de huri gibi her y...', ARRAY['Türk Edebiyatı','Şiir','Başar Çelebi']::text[], 8.5, '{"poet":"Başar Çelebi","poet_slug":"basar-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yeterince-optugumu-sanmiyorum-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biley Taşı', 'biley-tasi-kemal-varol-wwent', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'eriyen bakışlarımda çözülürdü zamanın uğultusu

gelirdin: dudaklarının arasında yağmurun sesi

unuturdum, uzayıp giden gökyüzü kime kapalı

neden her şey vecdini soldurur

çocukluğunu anlatırken neden mendil ister babasız kadınlar

bilmedim, çünkü herkesin kalbi artık biley taşı

herkes hırpalarken kısık sesle canını

bazı babaların yasıyla yaşarken herkes

savurdum bir sitemle ölümün giz dilini

ne baba ne oğul olabildiğim kadın, bağışla: 

ey yetim, bu aşkta da babanı bulamadın galiba!', 'eriyen bakışlarımda çözülürdü zamanın uğultusu gelirdin: dudaklarının arasında yağmurun sesi unuturdum, uzayıp giden gökyüzü kime kapalı ned...', ARRAY['Türk Edebiyatı','Şiir','Kemal Varol']::text[], 8.5, '{"poet":"Kemal Varol","poet_slug":"kemal-varol","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/biley-tasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avaz', 'avaz-kemal-varol-u3uh7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sokakları gönendirmek için gezinen yüzüm şimdi pas

artık kesif kokularla anılıyor adım ve cismim

her kötülüğe varım artık: annem beni görmüyor

çünkü anneler bir gün icazet verir her çocuğa: 

git ve gözlerin güz olmadan başkalarını öv artık

eski bir sevgilinin hatırasını örter gibi

kapandı ardımdan yedi kilit bir kapı üstüne

yüz sürdüm yolların sonsuz avazına, kalmadım

melekler bakmasın diye uyurken örtünen annem

ben uzak yaşına gelince şimdi naz: 

ah ki büyüttüm çocuklarımı başkalarına!', 'sokakları gönendirmek için gezinen yüzüm şimdi pas artık kesif kokularla anılıyor adım ve cismim her kötülüğe varım artık: annem beni görmüy...', ARRAY['Türk Edebiyatı','Şiir','Kemal Varol']::text[], 8.5, '{"poet":"Kemal Varol","poet_slug":"kemal-varol","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/avaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küfran', 'kufran-kemal-varol-yiw0q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'o rahvan atları anlaşılır kılan sabahlarda

göğsü kasvet sayrılarıyla çarpışıp

delişmen çocuklarını azdırırken dünya

şehrin çarşılarından esen telaş

hıçkırıklarla akşamı karşılayan bir aldanış gibi

babamın incinmiş sesine çökerdi.

yatağına ilk kez akan bir nehrin hırçınlığıyla

karın kapadığı rayları temizleyendi babam.

bir nasihatin başlangıcındaki parmağı hep tehdit,

bütün oğulları kaçgöç,

herkesin yalnız klarnet çalarken duyduğu

kendinin öksüzü ıslak bir adam.

benzemem diye düşünürken

müsvedde oldum ona.

bütün bozgunlara mâlik bir adamdı babam

mahzenlerde sakladığım kitaplar kadar müphem.

eski gazetelerle dönerdi akşamları

yani ki posta katarlarının artıkları..

okuturdu akşamların camlara çarpan geniş sesiyle.

oysa renksiz gazetelerdi çeken bizi

yani yıldız paylaşan üç kardeş

devlet ve babamızdan korurduk kitaplarımızı.

çünkü, sabahına sorardı şehir:

kimdi duvarlara bu kızıl harfleri düşürenler..

kavmim kadar ümmîydi babam

ya da herkes kadar sis.

dağılır bu kirli yarış diye düşünürken

yekûn oldum ona.

bilmediğim bir rabbin secdesine çağırırken beni

suya inen gözlerin tedirginliği sanırdım onu.

çünkü anlamazdı kimse

raylar boyunca hıçkıran bir adamın

bir boşluğa içinden konuştuğunu maraz gecelerini.

çünkü yalnızlık eski kıbleydi doğu’da

kendimizin kapısını çaldıkça başlayan küfrân.

çünkü boşaltılmış köylere fısıltıyla bakan babam

katarlar boyunca gözyaşı şişelerini görmezdi

o, karın kapadığı rayları temizleyendi sadece

yorulunca klarnet çalan, boş vagonlara.

yürürüm diye düşünürken

sebep oldum ona.

gözlerim sarındığım yazlar için ıslakken

onun sefer taslarında kaynamış taşlar,

önünde, gidemediği arafat dağı

solgun takvim yaprakları cebinde..

her akşam kurulan bir saatti babam.

öldürdüklerinin de namazını kılan

acıya vâkıf bir adam.

sırtından kayan hırkasını okşarken

bana yeter sanırdım içimdeki hayâ taşı.

oysa herkes adak,

her şey ses’ti doğu’da.

bu sözle dirilip

bu sözle yaklaşırdım sırtındaki hançere.

babasız büyüyen babamın

oğulsuzluğuna dokunurdum.

ummam, diye düşünürken

sebep oldum ona.

(yaban olaydım gelirdim merhamet sathına

içimdeki bu fazla yaldızı döker

makas değiştiren trenlerin permilerine sığınarak

uzak çocuklarıyla konuşurken

hep sesi titreyen babamın

ilmini anlardım o zaman:

ey bulanık geçmiş, onun gam oğulları

neden babalarla bu kadar sus çocuklar.) 

çırpınan bir saralının, durulduktan sonra

dünyaya fırlattığı o mahzun bakış gibi,

babasına halef olan her çocuğun

bir şerden kopardığı parsa

gün gelir ona da serap olur, diyendi babam.

o zaman şakaklarımdaki parmaklar sâdık değildi

kursağımda daralan bu sözün anlamına.

çünkü lazım gelirdi ki

hiç bir söz bizi töhmet altında bırakmasın

ya da kurulanmasın

çocukluktan arta kalan gözyaşları..

babam kuytu konuşur ve susardı.

katrana bulanmış bir ağacın aleviydi o.

dönmem diye düşünürken

tavaf oldum ona.

kıssalarla büyüyen bir yol eriydi babam

yanlış bir hayatın doğrusunda ısrar.

istasyon çeşmelerinin üşüyen suları gibi

o fer gözlerden gideli çok

o çorak toprak ezel

birbirimizin ayazında bir ibre ve hata:

her baba aslında bir imâdır oğluna.

mevsimler, yıllar ve hayat

ah, böyle böyle geldim huzura.

çiğnedim babamın sancı sırtını

gittim raylarda unutulan hikâyelerin kahrına.

ben o dişi taşların oyuklarında duaydım artık.

alışır, alışır, diye düşünürken

merak oldum ona.

kilitlenen dişlerimi açmak için

bir sedâ kadına vardım sonunda.

oysa, hummayla kıvranırken

babamın yastığıma bıraktığı gazozlar

gibi köpürmüştüm aşklara:

başka biri seyrediyor gözlerinde

sanki bazen kaç kişi -

derdi o üzünç kadın.

bir başıma geçerdim ölüm mülkü vefa topraklarını

sabır çekerdim ağzımdan dökülen vedâ sularına.

soluksuz bir sabahın ayazında

uzun ve ıslak mühürlerle dönerdim sonunda.

fermandır: babayla bozgun her çocuk

hoyrattır elbet aşklarına.

çünkü zamansız yolcuya susar kavşaklar.

dedim, dedim ve

revân oldum ona

haddim bilsem, yorgun sazlıklardan

bir hırka için geçmezdim.

âh, anlardım: sokaklar evlerden de helâk.

bütün gece yağmurda ıslanmış bir köpek gibi

boynumu sebepsiz bir boşluğa uzatarak

bir duvar dibine tüneyip konuşurdum elbet:

babam neden bizden önce kalkardı sofradan..

ama artık geç bağışlanma dilemek ondan

çünkü kara örtüler atılırken üstüme

canıma kesilen paralar da hebâ.

hiç gitmedim kendimden uzağa, diye düşünürken

sıla oldum ona.

göğü ne kadar hatmetsem varamazdım

artık asayla yürüyen bir babanın efkârına.

varamazdım, çünkü gördüm:

yaşlandı babam bulanık sulara benzeyerek.

silinmiş el yazmaları,

boynundaki teslim taşı,

her cuma evimizden çıkan yetim yemekleri

kadar ferahtı giderek azalmış öfkesine..

laf körüğü dünya! 

yaşlandıkça neden yalvaran kabirler

gibi bakardı babalar.

neden! diye düşünürken

medet oldum ona.

ezber bir dille uzandım sayfalara.

umarsız tepeler, suyu azalmış hürmetler dolandım

sabah ezanları kadar kimsesizdim artık.

oysa nasıl da yalandı geçtiğim âyetler

bunca küf, bunca batık ve sır neyi söylerdi

marifet miydi sümbüllerle açılan sesimin örgüsü

beni ehven-i şer’den öteye götürür müydü? 

tâkatsiz dillerin esvâbını yırtan menkıbeler

küllenen bir ocağın başına oturtup

babama o giz sözleri söyletir miydi yeniden:

günüm ve zamanım nerdeyse orda tamamım

nerdeyse şer meleklerim orda hazırım..

rüzgarda dalgalanan bir perde kadar

dokunaklıydı onca aleve susan babamın gözleri.

bakmam diye düşünürken

nişân oldum ona.

yıllarla hatırladım:

kazâ ve belâ ondan yanaymış eski zaman.

kabuğuna alışmış bir yaraya

yeniden ilişmenin hazzı gibi

yaşlandıkça anılar ona yorgan:

keçesine sarınıp dağları uyuttuğu

şehri hınzır bir ıslıkla geçtiği

gençliğinin haram günleri.

ürperdikçe ağlayan babam..

ne bir şarkıya nefes kaldı onda

ne rabbin dağlarına heves.

bütün çocuklarına gizli gizli ağlayan

bir kolun sancısı oldu zamanla.

sabaha karşı, mağlûp trenlerin

sararmış istasyonlara yanaşması gibiydi babam.

herkesin kulak kesildiği bir salâ oldu sonunda.

unuturum diye düşünürken

mürekkep oldum ona:

artık buruşuk bir çarşaf gibi dağılan

yüzüne bakınca duydum ancak:

anneler erken

ölümlerine yakın sevilir babalar.', 'o rahvan atları anlaşılır kılan sabahlarda göğsü kasvet sayrılarıyla çarpışıp delişmen çocuklarını azdırırken dünya şehrin çarşılarından ese...', ARRAY['Türk Edebiyatı','Şiir','Kemal Varol']::text[], 8.5, '{"poet":"Kemal Varol","poet_slug":"kemal-varol","theme":"Türk Şiiri","is_hero":false,"total_lines":175,"source_url":"https://www.antoloji.com/kufran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gazala', 'gazala-kemal-varol-ym6y5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir zaman senden ağlar kaldım gazala

sesim o uzak dağlarda dağdar şimdi

sanki unutmak için var anılar kinimde

ve sanki hep küs tadıyla söylenmiş bir şarkı duyduğum: 

herkes bir gün bir aşkta imkansız hala

ne ırmaklarda haz, ne perçemlerde şefkat var artık

kuşkuyla dönülen aynalar ve kapılar şimdi

yalnızlığa kötü gelen yağmurlar

acıtan tesadüflerin sesi; mutluymuş

ah gazala, her şey eskisinden fena: 

kül büyüt canım ve mümkünse acını unutma', 'bir zaman senden ağlar kaldım gazala sesim o uzak dağlarda dağdar şimdi sanki unutmak için var anılar kinimde ve sanki hep küs tadıyla söyle...', ARRAY['Türk Edebiyatı','Şiir','Kemal Varol']::text[], 8.5, '{"poet":"Kemal Varol","poet_slug":"kemal-varol","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gazala-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mor Sevgilim', 'mor-sevgilim-kemal-varol-pxc4m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir tespih gibi dağılıp hatırlarken seni

öptüm etimdeki kızgın mührün sızısından

dizlerimde işleyen yaraların haylazlığıyla

hayata benzeyen sözler ettim kime rastladıysam

kime baktıysam: birden acıyla bozkır ömrüm

bu kaçıncı düğüm atılan bana, bu nasıl böyle küf

söyle: artık ne, bu harabe kime

boğaza tıkanan yutkunma

nedensiz bir akşamdan kalma nem gibi unutuldum

ah! kim ki kaldı bütün aşklarının yasını tutan: 

aziz sevgilim, her gülün ziyanı neden kokusu kadar', 'bir tespih gibi dağılıp hatırlarken seni öptüm etimdeki kızgın mührün sızısından dizlerimde işleyen yaraların haylazlığıyla hayata benzeyen ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Varol']::text[], 8.5, '{"poet":"Kemal Varol","poet_slug":"kemal-varol","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/mor-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suyun Öte Yakası', 'suyun-ote-yakasi-aziz-pinar-qw83v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu sular hatırlatır, birlikte kurulan hayalleri

Kah Meriç, kah Ege sularının öte yakası

Birbirlerine bakarlarken kendi kıyılarından

Gördükleri kendi yaşamlarının çağrısı

Sıcaklığına dokunur parmak uçları

O sirtaki oynar bizde halay havası.

Her iki oyunda da omuzlarda kolları

Suyun ortasında zaten kesişir yolları

Birbirine uzatılan yeşil zeytin dalları

Tuttukları kendi yaşamlarının dalgası.

Sıcaklığına dokunur parmak uçları

O sirtaki oynar bizde halay havası.

Birbirine hasrettir suyun iki yakası

Görmek isteyip göremediği yarısı

Öyle bir çizilmişki sınırın haritası

Sürdükleri kendi yaşamlarının tarlası.

Sıcaklığına dokunur parmak uçları

O sirtaki oynar, bizde halay havası.

Suyun altında balıklar yaşıyor barışı

Suyun üzerinde sürdürülen ekmek yarışı

Göklerde jetlerin yaptıkları it dalaşı

Yaktıkları kendi yaşamlarının ateşi.

Sıcaklığına dokunur parmak uçları

O sirtaki oynar bizde halay havası.

En güzel mavi derinden akıyor birbirine

Mübadele torunları bakıyor birbirine

Küskün geçen yılları yıkıyor birbirine

Baktıkları kendi yaşamlarının hatırası.

Sıcaklığına dokunur parmak uçları

O sirtaki oynar bizde halay havası.', 'Bu sular hatırlatır, birlikte kurulan hayalleri Kah Meriç, kah Ege sularının öte yakası Birbirlerine bakarlarken kendi kıyılarından Gördükle...', ARRAY['Türk Edebiyatı','Şiir','Aziz Pınar']::text[], 8.5, '{"poet":"Aziz Pınar","poet_slug":"aziz-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/suyun-ote-yakasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevin Gönül', 'sevin-gonul-i-brahim-erkal-kprt8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yanıyor yüreğim, yanıyor

Yine yine secdalanıyor

Başımda yeller dolanıyor

Bahardan olsa gerek

Sevin gönül sevin

Sevin yar geliyor

Yar gelince

Dünyalar geliyor

Doluyor yüreğim, doluyor

Her nefeste aşk soluyor

Bana bir şeyler oluyor

Bahardan olsa gerek', 'Yanıyor yüreğim, yanıyor Yine yine secdalanıyor Başımda yeller dolanıyor Bahardan olsa gerek Sevin gönül sevin Sevin yar geliyor Yar gelince...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Erkal']::text[], 8.5, '{"poet":"İbrahim Erkal","poet_slug":"i-brahim-erkal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevin-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farzet', 'farzet-ali-tekinture-vm6m2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne sen beni gördün, ne ben seni

O büyük tesadüf olmadı farzet

Tanışmamış gibi olalım senle

O sevgi gönlüme dolmadı farzet

Farzet bir rüyaydı, uyandın bitti

Farzet bir hayaldi, kayboldu gitti

Farzet ki gözlerin bir oyun etti

İki gözüm seni görmedi farzet

Artık seni anmam, seni düşünmem

Sevgilimsin diye koşmam peşinden

Uçan kuş misali geçtin başımdan

Ellerim elini tutmadı farzet', 'Ne sen beni gördün, ne ben seni O büyük tesadüf olmadı farzet Tanışmamış gibi olalım senle O sevgi gönlüme dolmadı farzet Farzet bir rüyaydı...', ARRAY['Türk Edebiyatı','Şiir','Ali Tekintüre']::text[], 8.5, '{"poet":"Ali Tekintüre","poet_slug":"ali-tekinture","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/farzet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zorba Aşk', 'zorba-ask-aysel-gurel-iiyrb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dünkü anılar hala

Kalbimde vurgun

Divane oldum aşka

Gönlümü koydum

Ateşi yar eden

Şu canımı eriten

Her darbesi hüküm

Ne dünüm, ne bugünüm

Ben bahar aradım

Yandı güller aldandım

Yağmura, rüzgara

Sığındım, saklandım

Ah inkar yok

İsyan yok

Aşktan başka

Bir ferman yok

Candan tükendi sevda

Zorba aşk, zorba

Seni sevemem bu yürekle

Bir daha asla', 'Dünkü anılar hala Kalbimde vurgun Divane oldum aşka Gönlümü koydum Ateşi yar eden Şu canımı eriten Her darbesi hüküm Ne dünüm, ne bugünüm Be...', ARRAY['Türk Edebiyatı','Şiir','Aysel Gürel']::text[], 8.5, '{"poet":"Aysel Gürel","poet_slug":"aysel-gurel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/zorba-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-serdem-coskun-5ngeu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Böyle böyle küllenir anılar

Anlatınca, yalnız yavaşlar

Hasret gün olur da alevlenir

Belki bir gün başkası sevilir

Değme, kurşun yarası ellerin

Çıkmıyor tenimden izlerin

Öfkeme nefreti ekledim

Sevmeden nasıl unutabilirim

Zaman, yalnız zaman

İhtiyacımız olan

Sonra sonra anladım çok zor

Ha deyince unutulmuyor

Aciz gönlüm dile gelince

Gözlerim sözünde durmuyor

Deşme, gönlüm yaralı bir kuş

Uçmuyor kanadı vurulmuş

Belli değil mi halimden

Ayrılık ne beter, ne zormuş', 'Böyle böyle küllenir anılar Anlatınca, yalnız yavaşlar Hasret gün olur da alevlenir Belki bir gün başkası sevilir Değme, kurşun yarası eller...', ARRAY['Türk Edebiyatı','Şiir','Serdem Coşkun']::text[], 8.5, '{"poet":"Serdem Coşkun","poet_slug":"serdem-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/zaman-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'De Get Yalan Dünya', 'de-get-yalan-dunya-i-brahim-erkal-4ccg9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Salkım salkım üzümdür

Dostum iki gözümdür

Geçmem, geçmem, vazgeçmem

Sevilecek neyin kaldı

Sanki aşlar hep yalandı

Neyine güveneyim

De get yalan dünya

Seni nasıl seveyim

Ömrümü çalan dünya

Aşk zehirli yılan imiş

Genç ömrümü çalan imiş

Yandım, yandım, aldandım

Güzel olan neyin kaldı

Sanki şaklar mazide kaldı', 'Salkım salkım üzümdür Dostum iki gözümdür Geçmem, geçmem, vazgeçmem Sevilecek neyin kaldı Sanki aşlar hep yalandı Neyine güveneyim De get ya...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Erkal']::text[], 8.5, '{"poet":"İbrahim Erkal","poet_slug":"i-brahim-erkal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/de-get-yalan-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amenna', 'amenna-serdem-coskun-51d54', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dayanır mı bu yürek

Dayanır mı mübarek

Etmem hakkım helal

Koyma beni burda tek

Başında ki yazmaya

Elinde ki kınaya

Üstünde ki basmaya

Amenna, amenna

Dayanır mı bu yürek

Dayanır mı mübarek

Başa gelen

Varsa çekilecek', 'Dayanır mı bu yürek Dayanır mı mübarek Etmem hakkım helal Koyma beni burda tek Başında ki yazmaya Elinde ki kınaya Üstünde ki basmaya Amenna...', ARRAY['Türk Edebiyatı','Şiir','Serdem Coşkun']::text[], 8.5, '{"poet":"Serdem Coşkun","poet_slug":"serdem-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/amenna-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Deme', 'gel-deme-ali-tekinture-g2eai', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ardınsıra uzaklara

Gelmem artık, hiç gel deme

Aşk denilen tuzaklara

Düşmem artık, hiç gel deme

Seni olsun güzel yüzün

Seni olsun kışın, yazın

Çekilmiyor senin nazın

Gelmem artık, hiç gel deme

Hasretinden neler çektim

Kendi kendimi kaybettim

Ben sevmeye tevbe ettim

Sevmem artık, hiç gel deme

Tükendi gözümde yaşım

İhtiyar oldu genç yaşım

Sevgilim değil kardeşim

Oldun artık, hiç gel deme', 'Ardınsıra uzaklara Gelmem artık, hiç gel deme Aşk denilen tuzaklara Düşmem artık, hiç gel deme Seni olsun güzel yüzün Seni olsun kışın, yazı...', ARRAY['Türk Edebiyatı','Şiir','Ali Tekintüre']::text[], 8.5, '{"poet":"Ali Tekintüre","poet_slug":"ali-tekinture","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gel-deme-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fidan', 'fidan-suleyman-apaydin-k0s4y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıllar geçip gidecek saçlarım ağaracak

Ne dizlerimde derman ne bende can kalacak

Sessizce çekilirken bana ait köşeme

Gönlüm çocuklarımla bir teselli bulacak

Mutluluk içersinde yüzeceğim tasasız

Mezartaşım altında gönlüm huzur bulacak

Eğer bir gün çözerse birisi bir tek gizi

Bu benim içimdeki en büyük haz olacak

Üzgün olmayacağım doğadan ayrılırken

Binlerce fidan diktim arkamdan yeşerecek

Ben göremezsem bile bahcemin şenliğini

Meyvesini yiyenler bana dua edecek', 'Yıllar geçip gidecek saçlarım ağaracak Ne dizlerimde derman ne bende can kalacak Sessizce çekilirken bana ait köşeme Gönlüm çocuklarımla bir...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Apaydın']::text[], 8.5, '{"poet":"Süleyman Apaydın","poet_slug":"suleyman-apaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/fidan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sızıntı', 'sizinti-hasan-koca-2-xyb2h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yaşamak umudu boynumda

kaç kere saatleri ayarladım

tutmadı bi türlü ayarı

sadece kollarımda bir sızı

bir yarım türkü dilimde dolaşmış

''kapkara sevdalım''

ben göz değmemiş akşamlarımı özlüyorum

sen tütün kokusunu

yavaşlatılımış bir film hayat 

hep tekrar hep tekrar

olmamış meyva tadında

uzanamadım sonsuzluğa 

ellerimin uzun deil

yüreğim uzunsai

ben deilim napalım! 

hiç sitem deil bu yazdığım sade yaşantı

ayrılık olmasaydı, özlem de olmazdı

kılı kırk yarma vaktinde görüşmek üzere

vedalar çoook zor bilirim

ince ve derinden etkiler

ben sevdalı sen..

cilalı taş devrimi özledim

çocuktum asiydim, yavandım

şimdi uzay çağı suskunu ve tutsağı olmaktansa..

boşverr hepsi geçer azizim

sen yaşamanla olan doğrunu bul

ben iyi 1 adamdım oysa ki

ama eskiler der iyi adam olmak yetmez

adam olmayı öğrenmek gerek

hem de tez elden

hayat zaten hatalar ve detaylara sıkışmış 

bir atom çekirdeği gibi

ne fazla sıkmaya geliyo, 

ne tutmaya

bırakalım boş konuşmaları kıyımızda

kaç kez ah çektiysen işte o kadar ölmüşsün demektir.

kaç kez vah çektiysen, o kadar da kaçmışsın

kovalamayım diye en uzağa..

bir can taşıyorum elveda demek banal

veda etmek sahte

gözyaşı dolunay

ve sen hep benimlesin 

kendine iyi bak

göğüme güneş içime ay

24,11,2002 saat 22,45', 'yaşamak umudu boynumda kaç kere saatleri ayarladım tutmadı bi türlü ayarı sadece kollarımda bir sızı bir yarım türkü dilimde dolaşmış ''kapka...', ARRAY['Türk Edebiyatı','Şiir','Hasan Koca 2']::text[], 8.5, '{"poet":"Hasan Koca 2","poet_slug":"hasan-koca-2","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/sizinti-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vurgun', 'vurgun-husrev-hatemi-9h44n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sonbaharlar, son bulmadan ardarda

Ardarda hüzün daraltır yürekleri, 

Dağlar yürekleri kızgın temreni aşkın, 

Eski mızraklarsa, hep mahzenlerde..

Mahzun ve sevinci tanımadan ölmüş, 

Yüreklerle dolu mahzenlerde..

Sonbaharlar, son bulmadan ardarda, 

Ardarda hüzün, zincirleme...

Ardarda kırgınlıklar ardarda.

Süregelen bir durum degildi ki mutluluk

Sürüp gitmedi de, 

Ha evet sürüp gitmedi sonlandıydı

Keder ise zedelenmez bir tabaka içimizde, 

Yüreğimiz onunla sırlanmış.

Böylesine kirlenmiş bir dünyada, 

Hançerlenmiş sayılabiliriz tek tek

Vurgun yedik ömrümüzün derin yerinde

Kargışlar kar gibi yağar ve karanlık,', 'Sonbaharlar, son bulmadan ardarda Ardarda hüzün daraltır yürekleri,  Dağlar yürekleri kızgın temreni aşkın,  Eski mızraklarsa, hep mahzenler...', ARRAY['Türk Edebiyatı','Şiir','Hüsrev Hatemi']::text[], 8.5, '{"poet":"Hüsrev Hatemi","poet_slug":"husrev-hatemi","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/vurgun-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Unutma Beni', 'sen-unutma-beni-erhan-guleryuz-mq41v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Son deminde aksam merhaba dostum hüzün

Yalnizim yine yalniz nerdesin iki gözüm

Böylemi yasanir ayrilik acisi

Gözlerimden anla yeter

Gelde al canimi alda kurtulayim

Ayrilik ölümden beter

Sende unuttum hayalleri

Sende unuttum sevilmeyi

Bari sen unutma beni

Sende unuttum ümitleri

Sende unuttum ben herseyi

Bari sen unutma beni

Yüregimin kiyisina vurdu minicik bir dalga

Tutmaliydim tutamadim kendimi

Bi canim var feda etsem sevdami bilemezsin

Bi acim var anlatsam önünü göremezsin

Herkes unuttu gitti bende unuttum herseyi

Bari... sen unutma beni', 'Son deminde aksam merhaba dostum hüzün Yalnizim yine yalniz nerdesin iki gözüm Böylemi yasanir ayrilik acisi Gözlerimden anla yeter Gelde al...', ARRAY['Türk Edebiyatı','Şiir','Erhan Güleryüz']::text[], 8.5, '{"poet":"Erhan Güleryüz","poet_slug":"erhan-guleryuz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-unutma-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlerken Yüreğim...', 'ozlerken-yuregim-yasar-aslan-hqmf0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'özlerken yüreğim; 

Nisan yağmurlarını gözlerime gömerim.

Sana ulaşamamanın hırsıyla, 

Sıktığım  yumruğumda ve gözlerimde nefretin resmini çizerim.

Nefreti ellerimle boğmak isterim.

özlerken yüreğim; 

Şarkılar ve şiirler  dindirmez özlemimi, 

Göz yaşım teselli vermez yüreğime.

Kanayan yüreğimde bir acı gül filizlenir.

Acıyı kurşunlamak isterim.

özlerken yüreğim; 

Nefes alışın ne denli zor 

gülmenin de imkansız olduğunu, 

Sensiz yaşamın ölüm olduğunu bilirim.

Ölümü şakağından vurmak isterim.

özlerken yüreğim; 

Bedenim yapraklarını döker, 

Yaşam zevk vermez bana. 

Yaşamı kalbinden vurmak isterim.

Özlem  gecelerde isyanlara koşarım.

savaştan çıkmış bir asi.

Ölümü bekleyen bir yatalak hasta.

Sensiz yaşamaktan korkan.

Sensizliği alnından vurmak isterim

Seni özlerken yüreğim; 

Yüreğimin kanayan kesimlerinde sızılarda, 

Nemli odamın duvarlarında, 

Sensizliğin çığlığında, katran karası gecede

Haykırışlarında buluyorum kendimi.

Özlenen 

Özlenensin

Özlemi ellerimle parçalamak isterim.

25 – 11 – 2002   01: 35', 'özlerken yüreğim;  Nisan yağmurlarını gözlerime gömerim. Sana ulaşamamanın hırsıyla,  Sıktığım  yumruğumda ve gözlerimde nefretin resmini çi...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Aslan']::text[], 8.5, '{"poet":"Yaşar Aslan","poet_slug":"yasar-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ozlerken-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalvarırım', 'yalvaririm-ali-tekinture-5unt4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni böyle sensizliğe

Mahkum etme yalvarırım

Bilmediğim meçhullere

Çekip gitme yalvarırım

Bilmiyorum nedir suçum

Günahım ne bilmiyorum

Ölesiye seviyorum

Ne olur gitme yalvarırım

Sen canım, sen kanım, sen aşkım

Sen doğan gün, batan gün

Ben yıkılmış harabe, divane

Ben perişen, sevdalı, avare', 'Beni böyle sensizliğe Mahkum etme yalvarırım Bilmediğim meçhullere Çekip gitme yalvarırım Bilmiyorum nedir suçum Günahım ne bilmiyorum Ölesi...', ARRAY['Türk Edebiyatı','Şiir','Ali Tekintüre']::text[], 8.5, '{"poet":"Ali Tekintüre","poet_slug":"ali-tekinture","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalvaririm-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şafak Kaçta Askerim', 'safak-kacta-askerim-serdem-coskun-21kke', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uykularım kaçtı

Sabahın beşindeyim

İçtimaya kalktı

Çoktan benim askerim

Kimisi Aslı''ya Kerem

Kiminin gözlerinde nem

Kimisi göçtü alemden

Şafak kaçta askerim

Ekmeğim, aşım, helalim

Sen nöbette dururken

Ben seni beklerim

Yollarını gözlerim

Mektubunu aldım

Cevabını gönderdim

Tez gelir eline

Merak etme askerim', 'Uykularım kaçtı Sabahın beşindeyim İçtimaya kalktı Çoktan benim askerim Kimisi Aslı''ya Kerem Kiminin gözlerinde nem Kimisi göçtü alemden Şaf...', ARRAY['Türk Edebiyatı','Şiir','Serdem Coşkun']::text[], 8.5, '{"poet":"Serdem Coşkun","poet_slug":"serdem-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/safak-kacta-askerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Damlası', 'gul-damlasi-reside-murat-h2wd3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çiçek kokan ellerini

Uzat, dinsin aşk acısı

Kar düşer saçlarıma

Güneş ol sen, gül damlası

Hasret bende dağlar gibi

Çekilmiyor gül damlası

Her güzel yar senin gibi

Sevilmiyor gül damlası

Ocağımda tütmez duman

Sensiz halim olur yaman

Dünya yalan, yaşam yalan

Çaresizim gül damlası', 'Çiçek kokan ellerini Uzat, dinsin aşk acısı Kar düşer saçlarıma Güneş ol sen, gül damlası Hasret bende dağlar gibi Çekilmiyor gül damlası He...', ARRAY['Türk Edebiyatı','Şiir','Reşide Murat']::text[], 8.5, '{"poet":"Reşide Murat","poet_slug":"reside-murat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gul-damlasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanoğlu', 'i-nsanoglu-hamza-dekeli-zpkl2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bazen ağlar, bazen güler

Türlü türlü cefa çeker

Yine de hep şükreder

Cefakardır insanoğlu

Aşka düşer sevdalanır

Derde düşer efkarlanır

Kimi ölür, kimi kalır

Misafirdir insanoğlu

İnanırsa kalpten eğer

Aşkı için candan geçer

Hem sevilir, hem de sever

Sedakardır insanoğlu', 'Bazen ağlar, bazen güler Türlü türlü cefa çeker Yine de hep şükreder Cefakardır insanoğlu Aşka düşer sevdalanır Derde düşer efkarlanır Kimi ...', ARRAY['Türk Edebiyatı','Şiir','Hamza Dekeli']::text[], 8.5, '{"poet":"Hamza Dekeli","poet_slug":"hamza-dekeli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/insanoglu-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımdın Sen', 'askimdin-sen-elif-atici-prtwi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sanmaki  yokluğunda mutluyum

Hayır!  yüreğim yaslı

Tarifsiz istemsiz bu acı

Aşkından miras kaldı

Haksızca suçlandım ben

Biliyordun;  tek özlemim aşkımdın sen

Güller yasta, gözler yaşta

söylenmedik doğrular ise; 

sorma! 

Onlar bendeki gururda saklı', 'Sanmaki  yokluğunda mutluyum Hayır!  yüreğim yaslı Tarifsiz istemsiz bu acı Aşkından miras kaldı Haksızca suçlandım ben Biliyordun;  tek özl...', ARRAY['Türk Edebiyatı','Şiir','Elif Atıcı']::text[], 8.5, '{"poet":"Elif Atıcı","poet_slug":"elif-atici","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/askimdin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Pastası', 'ask-pastasi-elif-atici-vu27s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşk turtalı pastadan ben de yaptım

Harcına yeterince sevda kattım

Avuç dolusu umut attım

Hasretle yoğurdum

Sabırla beklettim

Yüreğimin sıcağınada pişirdim

Aşk adında oldu

Aşk tadı yoktu! 

Olmadı...

Beceremedim...', 'Aşk turtalı pastadan ben de yaptım Harcına yeterince sevda kattım Avuç dolusu umut attım Hasretle yoğurdum Sabırla beklettim Yüreğimin sıcağ...', ARRAY['Türk Edebiyatı','Şiir','Elif Atıcı']::text[], 8.5, '{"poet":"Elif Atıcı","poet_slug":"elif-atici","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ask-pastasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göç Vakti', 'goc-vakti-elif-atici-58a2i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir taht''a iki sultan yaraşmaz

İki karpuz bir koltukta taşınmaz

Göçmen kuşum, yaban gülüm

Gitmelisin

Göç vakti

Bu dal seni taşısa da 

Kalmak sana yakışmaz', 'Bir taht''a iki sultan yaraşmaz İki karpuz bir koltukta taşınmaz Göçmen kuşum, yaban gülüm Gitmelisin Göç vakti Bu dal seni taşısa da  Kalmak...', ARRAY['Türk Edebiyatı','Şiir','Elif Atıcı']::text[], 8.5, '{"poet":"Elif Atıcı","poet_slug":"elif-atici","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/goc-vakti-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Çalı', 'kara-cali-elif-atici-mw2cn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yokluğun ecelim olsa da git

Vicdan azabı yaşatma bana

Yeter!  çocuksu sesler

Ağlamasın  kulaklarımda

Hakkım yok seni çalmaya

Kadınını ağlatmaya...

Gülmek benim değil, onun hakkı

Gönül defterim ümitsiz, kapandı

Aklını  da al götür, kalmasın bende

Hatıralar hazır, al işte  valizde 

Yenik düştü kara çalı

savaşamadı melek yüzlerle', 'Yokluğun ecelim olsa da git Vicdan azabı yaşatma bana Yeter!  çocuksu sesler Ağlamasın  kulaklarımda Hakkım yok seni çalmaya Kadınını ağlatm...', ARRAY['Türk Edebiyatı','Şiir','Elif Atıcı']::text[], 8.5, '{"poet":"Elif Atıcı","poet_slug":"elif-atici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kara-cali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavel', 'kavel-hasan-huseyin-korkmazgil-xb9c2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İşime karım dedim, karıma Kavel diyeceğim. 

Ve soluğum tükenmedikçe bu doyumsuz dünyada, 

Güneşe karışmadıkça etim 

Kavel Grevcilerinin türküsünü söyleyeceğim. 

Ve izin verirlerse Kavel Grevcileri, 

İzin verirlerse İstinyeli emekçi kardeşlerim, 

İzin verirlerse Kavel Grevcileri, 

Ve ben kendimi tutabilirsem eğer sesimi tutabilirsem 

O çoban ateşinin yandığı yerde Kavel''de, 

O erkekçe direnilen yerde, Kavel''de 

Karın altında nişanlanıp dostlarımın arasında 

Öpeceğim nişanlımı Kavel kapısında 

Ve izin verirlerse İstinyeli emekçi kardeşlerim 

İzin verirlerse Kavel Grevcileri 

İlk çocuğumun adını Kavel koyacağım', 'İşime karım dedim, karıma Kavel diyeceğim.  Ve soluğum tükenmedikçe bu doyumsuz dünyada,  Güneşe karışmadıkça etim  Kavel Grevcilerinin türk...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Korkmazgil']::text[], 8.5, '{"poet":"Hasan Hüseyin Korkmazgil","poet_slug":"hasan-huseyin-korkmazgil","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kavel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
