INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenim', 'ogretmenim-fulden-sogut-uilff', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Toplandık dizi dizi, 

Sev, okşa, hepimizi, 

Sensin okutan bizi, 

Sevgili öğretmenim.

Doğru yolu gösterirsin, 

Okutur eğitirsin, 

Bize bilgi verirsin, 

Sevgili öğretmenim.', 'Toplandık dizi dizi,  Sev, okşa, hepimizi,  Sensin okutan bizi,  Sevgili öğretmenim. Doğru yolu gösterirsin,  Okutur eğitirsin,  Bize bilgi ...', ARRAY['Türk Edebiyatı','Şiir','Fulden Söğüt']::text[], 8.5, '{"poet":"Fulden Söğüt","poet_slug":"fulden-sogut","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ogretmenim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ailem', 'ailem-fulden-sogut-wcw4q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anneanne, büyükbaba, 

Baba, anne, kardeş var, 

Sanki neşe evi burası, 

Canım ailem.

Herkes sevmelidir, 

Bu güzel aileyi, 

Kim sevmezki, 

Bu güzel şeyi.', 'Anneanne, büyükbaba,  Baba, anne, kardeş var,  Sanki neşe evi burası,  Canım ailem. Herkes sevmelidir,  Bu güzel aileyi,  Kim sevmezki,  Bu ...', ARRAY['Türk Edebiyatı','Şiir','Fulden Söğüt']::text[], 8.5, '{"poet":"Fulden Söğüt","poet_slug":"fulden-sogut","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ailem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyiki Doğdun Oğlum', 'i-yiki-dogdun-oglum-baris-akm-inmrh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İyiki doğdun oğlum! 

Hediye alacak parası olan bir evde

Bir yaş daha büyümenin güldalında

Ne kadar masum, ne kadar mutlusun

İyiki doğdun oğlum! 

Nasılda Dünya''dan habersiz gülümsüyor

Titreyen mumları üfleyen dudakların

Çocuk ışıltılı kahve rengi gözlerin

İyiki doğdun oğlum! 

Ne kadar şanslı olduğunu bilemezsin

Akranlarının bir çoğu kurşun gölgesindeyken

Sen sıcak bir evin doğum günü çocuğusun

İyiki doğdun oğlum! 

Şanslı mısın bilmiyorum

O gün son anda masadan kurtuldun

Şimdi artık okullu çocuksun

İyiki doğdun oğlum! 

Dilerim sen mutlu olursun

Güneşin hiç gölge görmesin

Gökkuşağın hiç solmasın

İyiki doğdun oğlum! 

Hayır, hayır seni unutmadım ilk göz ağrım

Senle büyüyüp ilk kez baba olmayı tattım

İkiniz, hatta tüm çocuklar için dileklerim

İyiki doğdunuz yavrularım

Gün-gece sizin için açık gözlerim

Bilmiyorsunuz sizin için kendimi yaktım

Ama hiç bir zaman suçluluk duymayın

Ben, o zaman ölürüm', 'İyiki doğdun oğlum!  Hediye alacak parası olan bir evde Bir yaş daha büyümenin güldalında Ne kadar masum, ne kadar mutlusun İyiki doğdun oğl...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/iyiki-dogdun-oglum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayattan', 'hayattan-baris-akm-nlxob', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çöken bir memleketin içinde kayboluyor

İlmik ilmik dertle işlenen

Güz baharına kadar biriktirdiğim

Gönül yazması kızıl incilerim

Tepemde hala dik olsa da derbeder, 

İlkbahardan beridir omuzumun eğilmeyen çamı

Anlımın akında martılarımın barınağı

Taşımaya çalıştıkça ezilen başım

Hatırlamıyorum, ne zamandı kayboldu? 

Bir umuttu saman alevi gibi harlanışı

İhtimallerin koynunda belkileri yakışı 

Şimdilerde göçük altının mihrabı

Güz geldi de mi böyle oldu? 

Hayır elbet ama hazan zamanı anlıyor insan

Geç kaldığını ve ''''neden! ''''lerin kırbaçlarını

Her kırbaç biraz daha çökerttikçe bakışlarını

Dünya''nın ormanları yetmiyor 

Kağıdı kalemi olmaya insan denizlerinin

Yetmiyor kırmızı gül kokmuyorsa mürekkebi

Gecelerin ölüm acısı yakıyor her şafak gözlerini', 'Çöken bir memleketin içinde kayboluyor İlmik ilmik dertle işlenen Güz baharına kadar biriktirdiğim Gönül yazması kızıl incilerim Tepemde hal...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hayattan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalı Şehit', 'sevdali-sehit-ahmet-safak-yw4pa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yildizlari toplayip matarama koyarken

Alnima degen kursun kaderimle bulustu

Goturdu  kursun beni uzaga otelere

Geceye niyet etti safaklarla bolustu

Yildizlari al gotur 

Nazli yarime yetir

Ona gidemem ama

Onu kabrime gotur

Ah ana ben olurmuyum 

acep yok olurmuyum

Nazli yarin dilinde

Ad olur kalirmiyim

Mataram yildiz dolu yar icin sakla anne

Hergun benim yerime paptya kokla anne

Kavusuruz otede duslerde bekle anne

Ben nazlimdan ayrildim daglar daga kavustu

Nazli yar beklemsin 

Kinayi saklamasin

Sursun pamuk eline

Kabrime gelsin anne

Ah ana ben olurmuuyum 

Acep yok olurmuyum

Nazli yarin dilinde Ad olur kalirmiyim', 'Yildizlari toplayip matarama koyarken Alnima degen kursun kaderimle bulustu Goturdu  kursun beni uzaga otelere Geceye niyet etti safaklarla ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şafak']::text[], 8.5, '{"poet":"Ahmet Şafak","poet_slug":"ahmet-safak","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sevdali-sehit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-oguz-celik-9aisl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Buruşturulup bir kenara atıldın kağıt gibi.

Sevilmedin hiç kış gibi, 

Hep bahar olman beklendi.

Yapraklanman çiçek açman istendi.

Topraktan gereken desteği alamadın; 

Toprak bile senden onu istemesine rağmen.

Kokan bir çorap gibi durdun hayatın ortasında, 

ve yıkanman istendi.

Bulut su vermedi, yalvardın yine vermedi.

Kokunla kabul edilmek istedin, 

Kabul ettirebilecek birilerini bulamadın.

Hep yalnızdın, hala yalnızsın.

Yalnız mı kalacaksın bu fani dünyada.

Tek yolculuk yapan bir gezginmi olmak istiyorsun.

Konuşmayı, sevmeyi, aşık olmayı denedin mi? 

Denemedin mi yoksa? 

Bırak o zaman şiir okumayı

Etrafındakilere selam ver aşık olmaya çalış.

Tabutunu tek başına taşıyabileceğini mi sanıyorsun! 

Yanılıyorsun sen bir ölüsün', 'Buruşturulup bir kenara atıldın kağıt gibi. Sevilmedin hiç kış gibi,  Hep bahar olman beklendi. Yapraklanman çiçek açman istendi. Topraktan ...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Çelik']::text[], 8.5, '{"poet":"Oğuz Çelik","poet_slug":"oguz-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-194-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Gerçeği', 'hayat-gercegi-oguz-celik-6vsxx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hiç bulutları düşündün mü? 

Neden masmavi gökyüzünde; 

Bazen beyaz, bazen gri olurlar.

Hiç kuşları düşündün mü? 

Kanatlarının altına havayı alarak; 

Nasıl durmadan uçarlar! 

Hiç hayatı düşündün mü? 

Hayatın bazen beyaz; 

Bazen kara günlerini.

Hiç ölümü düşündün mü? 

İnsana ne kadar yakın olduğunu; 

Ama insanın onu hep uzakmış gibi neden düşündüğünü, 

Hiç sevgiyi düşündün mü? 

Karşılıklı olan ve karşılık bulamayanlarını.

Senin sevginin neden karşılık bulduğunu.

Hiç beni düşündün mü? 

Sensiz ne yapabileceği mi; 

Sensiz bir hiç olduğumu.

Boşver bunları, düşünme.

Çünkü düşünebiliyo olsaydın, 

Şu an yanımda olurdun...

07/06/2000

Edirne', 'Hiç bulutları düşündün mü?  Neden masmavi gökyüzünde;  Bazen beyaz, bazen gri olurlar. Hiç kuşları düşündün mü?  Kanatlarının altına havayı ...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Çelik']::text[], 8.5, '{"poet":"Oğuz Çelik","poet_slug":"oguz-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hayat-gercegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle İşte', 'oyle-i-ste-oguz-celik-i8v1j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öyle bir ağladım öyle bir güldüm ki, 

Sorma gitsin.

Yalan olan herşeyi yaşadım.

Ayrılığa dair, ihanete dair.

Yalan olmak yalanı yaşamak istemiyorum.

Çünkü seni çok özlüyorum.

Öyle bir sevdim öyle bir sevildim ki, 

Öyle böyle değil.

Gerçek olan her ne varsa bende gizli.

Aşka dair, sevgiye dair.

Hepsini sana sunuyorum 

Çünkü seni çok seviyorum.

07/12/2000', 'Öyle bir ağladım öyle bir güldüm ki,  Sorma gitsin. Yalan olan herşeyi yaşadım. Ayrılığa dair, ihanete dair. Yalan olmak yalanı yaşamak iste...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Çelik']::text[], 8.5, '{"poet":"Oğuz Çelik","poet_slug":"oguz-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/oyle-iste-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Kız', 'kucuk-kiz-oguz-celik-j2a6s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tek başına sahilde oturuyordu, 

Karşısında duran büyük kente bakıyordu.

Gözleri yaşların yansıttığı kentin ışıkları ile doluydu.

Ellerinin arasına aldığı kafası dalgındı.

Ve bir kentin ışığı kaydı gözünden.

Yere düşene kadar ışık, yıldız gibiydi.

Kayan bir yıldızın insana verdiği hüzün belirdi, 

Göz yaşlarıyla bezenmiş yüzünde.

Nedendir bilmem, ışıkların sönmesi korkusu sardı bedenimi, 

Durgunlukta denizle söz kesmişlerdi; 

Kentin ışıkları şahitliğinde evliliğe hazırlanıyorlardı sanki.

Deniz ile küçük kız.

Dha sonra kendini denizin kollarına bıraktı.

Şahitlerin huzurunda evlendiler ama beni üzen; 

Kentin ışıkları hala yanıyordu.

10/12/2000', 'Tek başına sahilde oturuyordu,  Karşısında duran büyük kente bakıyordu. Gözleri yaşların yansıttığı kentin ışıkları ile doluydu. Ellerinin a...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Çelik']::text[], 8.5, '{"poet":"Oğuz Çelik","poet_slug":"oguz-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kucuk-kiz-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende mi?', 'sende-mi-zafer-ozkay-eqqqo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sende mi gidecektin sevgilim, 

 Sende mi boynumu bükecektin, 

 Sende mi bir güldürüp bin öldürecektini, 

 Sende mi açacaktın bir yara daha yüreğimde.

 Senin için neler yapmadım, 

 Sabahlara kadar senin için ağladım, 

 Yağmurlarda senin için ıslandım, 

 Senin için bu acılara katlandım.

 Senin için neler yapmazdım, 

 Öl deseydin ölmezmiydim, 

 Yan deseydin yanmazmıydım, 

 Senden kalan bu yarayı senden başkası saramaz gülüm.

 Sende mi haince vuracaktın beni, 

 Sende mi terk edecektin, 

 Sende mi kışa çevirecektin baharımı, 

 Sende mi solduracaktın beni gül misali.

 Sende mi sonbaharda yapraklarımı döktürecektin, 

 Sende mi ecel teri döktürecektin vefasız, 

 Sen bir hiçsin sen insafsız vicdansız, 

 Adını Allahsız koydum bırak öyle kalsın.

(17.11.2002 - Karaman)', 'Sende mi gidecektin sevgilim,   Sende mi boynumu bükecektin,   Sende mi bir güldürüp bin öldürecektini,   Sende mi açacaktın bir yara daha y...', ARRAY['Türk Edebiyatı','Şiir','Zafer Özkay']::text[], 8.5, '{"poet":"Zafer Özkay","poet_slug":"zafer-ozkay","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sende-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şair Olsam…', 'bir-sair-olsam-alparslan-aydin-9lm3b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir sahil köşesinde olsam 

Hayalimde sen; gözlerimde batan güneş…

Dalsam gitsem uzaklara, 

Ağlasam ve yine ağlasam

Ve yine…

Kapanmaz açtığın yara.

Bir mezarlık köşesinde olsam, 

Örtse kara toprak, olsa kapkara bedenim.

Dadansa çıyanlar, dolsa cümle böcekler, 

Parçalansam ve yine parçalansam

Ve yine…

Parçalanmaz yalnız sana ait, 

Bu deli, bu yanık yüreğim…

Bir şair olsam, 

En yüce

En yanık sevdalardan alsam muradımı, 

Yazsam ve yine yazsam 

Ve yine…

En güzel aşk şiiri diye 

Satır satır, sayfa sayfa adını…', 'Bir sahil köşesinde olsam  Hayalimde sen; gözlerimde batan güneş… Dalsam gitsem uzaklara,  Ağlasam ve yine ağlasam Ve yine… Kapanmaz açtığın...', ARRAY['Türk Edebiyatı','Şiir','Alparslan Aydın']::text[], 8.5, '{"poet":"Alparslan Aydın","poet_slug":"alparslan-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-sair-olsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Rüyadır Edirne', 'bir-ruyadir-edirne-oguz-celik-yl45s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir rüyadır Edirne, 

Uyandığında kabus görmüş gibisindir.

Başlarken korkak ve yalnızsındır, 

Çıkarken de korkak ve yalnız olursun.

Ter basan vücudundan çıkan koku, 

Sonbahar kokusu gibi gelir sana, 

Kalbin rüyanın yoğunluğunu taşıyamayacak kadar yorgundur.

Tıpkı beynin gibi.

Hayatın devam ettiğini unutursun; zaman zaman..

Gözlerin yorgunluğunu belli eder kapanırken.

Açtığında hala Edirne''desindir ve seviyorsundur.', 'Bir rüyadır Edirne,  Uyandığında kabus görmüş gibisindir. Başlarken korkak ve yalnızsındır,  Çıkarken de korkak ve yalnız olursun. Ter basan...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Çelik']::text[], 8.5, '{"poet":"Oğuz Çelik","poet_slug":"oguz-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bir-ruyadir-edirne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmeyen Sevda', 'gecmeyen-sevda-alparslan-aydin-wj6d7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mecnun’un gönlünden Leyla’sı geçti.

Yunus’un aşk denen rüyası geçti.

Gamlı baykuşların tasası geçti.

Bak sevdan geçmedi, kara gözlü yâr.

Ferhat delmez oldu yalçın dağları, 

Bülbüller unuttu gülü, bağları, 

Geçti şu âlemde sevda çağları, 

Bak sevdan geçmedi, melek yüzlü yâr.

Ağlayan gözlerin yaşları dindi.

Islandı güllerim, sularım yandı.

Kerem’in Aslı’ya sevdası söndü.

Bak sevdan geçmedi, benden gizli yâr.

Gülperi misali hayal kalsan da,

Peri diyarında masal kalsan da,

Sen benden geçerek bir el kalsan da,

Bak sevdan geçmedi, alev sözlü yâr.', 'Mecnun’un gönlünden Leyla’sı geçti. Yunus’un aşk denen rüyası geçti. Gamlı baykuşların tasası geçti. Bak sevdan geçmedi, kara gözlü yâr. Fer...', ARRAY['Türk Edebiyatı','Şiir','Alparslan Aydın']::text[], 8.5, '{"poet":"Alparslan Aydın","poet_slug":"alparslan-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gecmeyen-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dadaşın Türküsü', 'dadasin-turkusu-alparslan-aydin-jzmr8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir türkü söyle bana, 

Şu dadaş ellerinden.

Dadaş misali sert

Dadaş misali mert olsun. 

Çınlasın kulaklarda, 

Yüz değil  bin yıl sonra

Öyle yürekten söyle ki, 

Duymayan namert olsun…

Bir türkü söyle bana, 

Şu karlı dağların doruğunda, 

Kırmızı gülün demet demet olduğu

Yayla yolunda…

Dinlesin Palan seni, 

Coşsun Aras sesinle, 

Erisin buz tutan yürekler, 

Senin “Mükerrem” nefesinle.

Halen daha göç göç olur yollar, 

Huma kuşu yine uçar başımda.

Ve halen daha  ayakları yan basar

Sarhoşluk var dadaşımda.

Güzeller bezenmiş toya giderler, 

Öyle bir güzellik ki akan su durur, 

Dadaşımın yüzünde keskin hançerler, 

Yiğitlik mührünü tarihe vurur.', 'Bir türkü söyle bana,  Şu dadaş ellerinden. Dadaş misali sert Dadaş misali mert olsun.  Çınlasın kulaklarda,  Yüz değil  bin yıl sonra Öyle ...', ARRAY['Türk Edebiyatı','Şiir','Alparslan Aydın']::text[], 8.5, '{"poet":"Alparslan Aydın","poet_slug":"alparslan-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dadasin-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Yazılan Şarkılar', 'sana-yazilan-sarkilar-alparslan-aydin-hlhre', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana şarkılar yazıyorum güzel kız, 

Hiç duymadığın notalarla.

Bir nihavend oluyor, bir kürd-i hicazkâr, 

Ama hepsinde senin ismin, 

Hepsinde yüreğin var.

Sana şarkılar yazıyorum sevdiğim, 

Sensiz gecelerim kadar uzun havalar, 

Senli günlerim kadar kısa  halaylar…

Sevdam kadar dağ, 

Gözlerin kadar deniz, 

Yüreğim kadar ova türküleri yazıyorum.

Sana şarkılar yazıyorum, 

İçinde gözyaşlarım, 

İçinde hayallerim, 

İçinde sevdam olan, 

“Seni sevmediğim yalan” 

Diyip de haykırdığım şarkılar.

Sana şarkılar yazıyorum vefasız, 

Sen hiç dinlemesen, 

Sana yazıldığını bilmesen de…

Hiçbir sözünde ezilmesen, 

Ve hiçbir  notasında büzülmesen de…', 'Sana şarkılar yazıyorum güzel kız,  Hiç duymadığın notalarla. Bir nihavend oluyor, bir kürd-i hicazkâr,  Ama hepsinde senin ismin,  Hepsinde...', ARRAY['Türk Edebiyatı','Şiir','Alparslan Aydın']::text[], 8.5, '{"poet":"Alparslan Aydın","poet_slug":"alparslan-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sana-yazilan-sarkilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sinema Gorevlisi', 'sinema-gorevlisi-yusuf-sabri-bagriacik-z5o3v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'herkese bi yer bulan bi sinema görevlisi... 

bulabiliyor mudur acaba, 

bu acımasız hayatta 

bayanın yanından iki sıra boş bırakıp 

oturacak bir yer

üstelik, 

bahşiş vermesine de gerek yok', 'herkese bi yer bulan bi sinema görevlisi...  bulabiliyor mudur acaba,  bu acımasız hayatta  bayanın yanından iki sıra boş bırakıp  oturacak ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Sabri Bağrıaçık']::text[], 8.5, '{"poet":"Yusuf Sabri Bağrıaçık","poet_slug":"yusuf-sabri-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sinema-gorevlisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Gülümseyişim Bir Veda', 'her-gulumseyisim-bir-veda-bahadir-erdem-bulbul-78a0l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ve gelmişti istenmeyen o an... 

Yüreğindeki an’ları çalıp giden zamana karşı saklı bir öfkesi vardı. 

Ne olacaksa olmalıydı 

Uykular bölünmüş, huzursuzluk çökmüştü sanki kente. 

Aslında umurunda bile değildi yorgunluğu 

Sadece bitmeliydi bu kangren bekleyiş 

Lanet olsun dedi kendi kendine 

Bilinmez bir limana yol alıyordu işte gemiler

Yıldızlar ilk ve en büyük yalanlarını söylüyorlardı

Saatine baktı 

Nasılsa, bundan sonra bakmayacağı türünde şeyler geçti aklından, 

                                                                                                       kızdı kendine 

Nasıl olmuşta böyle düşünebilmişti, 

Kabuslardan uyanırcasına kendini seyretti camlardan

Acımaklı oldu “Allahım bu ben miyim” 

Unutmuştu onu gördüğünde içindeki kör karanlığı

Onu gördüğünde unuturdu kendini 

Oysa paylaşmak değildi bu, hele aşk hiç değildi

Düşünmek istemiyordu aslında neyin ne olduğunu, bıkmıştı, 

Bırakmıştı neyi varsa sevdanın o hırçın nehrine 

Şimdi kendi de bilmiyordu hangi denize karıştığını 

Mutluydu ama kendiyle değil hep bir başkasıyla, 

Sevgiliyle, arkadaşlarla, dostlarla

Yüreğini toplayıp sevdiklerini çıkardığında 

Geriye bir başkası kalıyor ve hiç kendine benzemiyordu 

Yavaş yavaş inanmaya da başlıyordu

Hayatın matematiksel bir denklem olduğuna 

Gözlerini ayıramıyordu sevgilinin gözlerinden,

O bakmasa da bakıyordu, 

Sanki bir giz arıyordu ya da bir şifa

Medet değil, bambaşka bir şeydi bu 

Gülümsüyordu arada bir, 

Oysa biliyordu her gülümseyişinin bir veda olduğunu, 

Bir kez olsun inanmak istemiyordu

Bir kez olsun ” ben de diyordu kavuşanlardan olsam”

Herkes binmişti otobüse yalnız onlar kalmıştı, 

Sarıldılar birbirlerine

Öylesine sıkı sarmıştı ki genç adam 

Ayrılıkların başlangıcında olduklarını 

Ve bu ayrılığın hiç bitmeyeceğini bilircesine iyi oynuyordu rolünü 

Aslında oynamıyordu, kaderini zorluyordu 

Perde yeni açılmıştı, 

Prova değildi, sahnedeydiler...

Ağlamak istemiyordu ama ağlamalıydı, ağladı

Senaryoda vardı 

Son kez kafasını kaldırıp seni seviyorum diye bağırdı sevgiliye 

Çünkü son kezdi... 

Ve gelmişti istenmeyen o an... 

Yüreğindeki an’ları çalıp giden zamana karşı saklı bir öfkesi vardı. 

Ne olacaksa olmalıydı 

Uykular bölünmüş, huzursuzluk çökmüştü sanki kente. 

Aslında umurunda bile değildi yorgunluğu 

Sadece bitmeliydi bu kangren bekleyiş 

Lanet olsun dedi kendi kendine 

Bilinmez bir limana yol alıyordu işte gemiler

Yıldızlar ilk ve en büyük yalanlarını söylüyorlardı

5 KASIM 2000', 'Ve gelmişti istenmeyen o an...  Yüreğindeki an’ları çalıp giden zamana karşı saklı bir öfkesi vardı.  Ne olacaksa olmalıydı  Uykular bölünmü...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Erdem Bülbül']::text[], 8.5, '{"poet":"Bahadır Erdem Bülbül","poet_slug":"bahadir-erdem-bulbul","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/her-gulumseyisim-bir-veda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Brighton Dosyası', 'brighton-dosyasi-yusuf-sabri-bagriacik-zr9dv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'aynı şehirde, aynı hasrette tanıştık usta onunla, unutma! 

aynı açlıktaydık

aynı uzaklıktaydık, sevdiklerimizden

biz aynı aşk''a aşık olduk usta, unutma! 

içimdeki sevginin sözlük anlamı budur usta

bindiğim de yeşilköyden uçağa, 

bi sabah vakti

istekli olup olmamanın önemi kalmadığı bi andı

gidiyordum, arkama bakmadan

nereye olduğunu bilmiyordum.

vardığım da o uzak diyarlara, 

merve oradaydı

yanlızlar tiyatrosunda ki oyununu, 

tek başına sergiliyordu

mutsuzdu, mutsuz olmasına 

ama yüzünde ki o gülüş

hiç eksik olmamıştı

öylesine gülüyordu ki... 

kalktım, onun hayata gülüşü isimli bi oyun yazdım

değiştirdim, yanlızlar tiyatrosunun ismini

aşıklar tiyatrosu yaptım

oynamaya başladık, 

onun hayata gülüşü isimli oyunu

aktördük belki ilk başlarda

ama nedense, 

kullanmadık takma isimler

istemedik

o merve olarak kaldı

ben yusuf

unutma usta...

aktördük ilk başlarda

sonrasında... 

sonrasını brighton''da olanlar bilir

bizi oradan paris''e uğurlayanlar

biz aynı şehri, doyasıya yaşadık

o güzel şehrin sokaklarında, 

bulduk sınırsız mutluluğu

aynı şehirde, aynı hasrette tanıştık usta onunla, unutma! 

aynı açlıktaydık

aynı uzaklıktaydık, sevdiklerimizden

biz aynı aşk''a aşık olduk usta, unutma! 

vakit ayrılığa yaklaştıkça, 

güneş hiç görünmemeye başladı oralarda

yağmurlar eksik olmadı üzerimizden

üstelik yağmurlar hemen kaçmadılar

mazgarlardan okyanusa

içime nasıl yağıyorlardı bir bilsen

ayrılık vaktini düşünürken, sokaklarda

sonunda gitti...

ardına öylesine bakıyordu ki

peşinden koşabilirdim oradan buraya...

bıraktı acıları bana ve gitti

ve başladı, 

onsuz bi türlü geçmeyen o aç, acı, öksüz ve yetim bi hafta

nasıl anlatılır ki yaşanmayan o dakikalar

nasıl anlatılır ki yaşanmayan o zamanda ki acılar

bir hafta...

nasıl olduda çaldı ömrümden o kadar zamanı

ve ben... 

ilk başlarda sadece biraz mutluluk vermek istediğim o kadına

değil mutluluğu verdim hayatımı

birileri pişman olduğumumu düşünüyor ne

yanılmayın dostlarım, 

ustam bilir

nasıl sevdiğimi 

sen söyle usta

aynı şehirde, aynı hasrette tanışmadık mı onunla

aynı açlıkta değilmiydik

aynı uzaklıkta değilmiydik, sevdiklerimizden

ve biz usta

merve ile ben yani

aynı aşk''a aşık olup, 

bütün fikirlerimizi birbirimize göre uyarlamadık mı

sen söyle usta

ben söyleyince, kendisini pofpofladı derler

                 Kasım 2002, İstanbul', 'aynı şehirde, aynı hasrette tanıştık usta onunla, unutma!  aynı açlıktaydık aynı uzaklıktaydık, sevdiklerimizden biz aynı aşk''a aşık olduk u...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Sabri Bağrıaçık']::text[], 8.5, '{"poet":"Yusuf Sabri Bağrıaçık","poet_slug":"yusuf-sabri-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":76,"source_url":"https://www.antoloji.com/brighton-dosyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olur', 'olur-i-brahim-yoruk-9j3vu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerin ok, saçların yay, yüzünse atıcı

Açıyorum göğsümü, yaralasanda olur.

Fazla duramaz burada o eski satıcı

Eş-dost önünde beni, karalasanda olur.

Hatanı ne zaman farkedersin, gidende mi? 

Son pişmanlık fayda vermez, pişmanlık sende mi? 

Artık o bahar tat vermiyorsa suç bende mi? 

Ardıma küfürleri, sıralasanda olur.

Ve aldırış etmeden bana gidersen birgün

Bilinsin artık, senin elindendir ölümüm

Pekala, bağşüstüne; gidişin de kabulüm

Yola bakan perdemi, aralasanda olur', 'Gözlerin ok, saçların yay, yüzünse atıcı Açıyorum göğsümü, yaralasanda olur. Fazla duramaz burada o eski satıcı Eş-dost önünde beni, karalas...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yörük']::text[], 8.5, '{"poet":"İbrahim Yörük","poet_slug":"i-brahim-yoruk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olur-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aman Kimseler Duymasın', 'aman-kimseler-duymasin-gonul-sen-h998g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Deli eder bakışların beni böyle

Hemen baştan çıkarırsın beni böyle

Aman kimseler duymasın

Aman kimseler bilmsin

Sonra düşeriz dillere

Olur mu ki, olmaz mı ki bilmiyorum

Bir kez sevdim dilim yandı, korkuyorum

Olur mu ki, olmaz mı ki bilmiyorum

Yeşil gözler beni yakar, korkuyorum

Sırılsıklam aşık gibi bakıyorsun

Alev alev gözlerinle yakıyorsun

Çapkın çapkın bakıyorsun yüzüme

Güvensem mi ben acaba sözüne

Çapkın çapkın bakıyorsun yüzüme

Şeytan gibi giriverdin kalbime', 'Deli eder bakışların beni böyle Hemen baştan çıkarırsın beni böyle Aman kimseler duymasın Aman kimseler bilmsin Sonra düşeriz dillere Olur m...', ARRAY['Türk Edebiyatı','Şiir','Gönül Şen']::text[], 8.5, '{"poet":"Gönül Şen","poet_slug":"gonul-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/aman-kimseler-duymasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aslanım Koçum', 'aslanim-kocum-serdem-coskun-xiy5e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aslanım koçum

Az kendine gel

Tez bulasın gayreti

Dört duvar değil engel

Sarı bir mevsimdi

Yola vurduk seni

Helalin emzirirken

Bebe yiğidini

Sazını uğrak yeri

Gönlün ince minesi

Hele al bir karşına

Söylesin çilesi

Aslanım koçum

Bu da öldürmez seni

Tez bulasın çareyi

Dört duvar engel değil ki', 'Aslanım koçum Az kendine gel Tez bulasın gayreti Dört duvar değil engel Sarı bir mevsimdi Yola vurduk seni Helalin emzirirken Bebe yiğidini ...', ARRAY['Türk Edebiyatı','Şiir','Serdem Coşkun']::text[], 8.5, '{"poet":"Serdem Coşkun","poet_slug":"serdem-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aslanim-kocum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Önemli Değil', 'onemli-degil-reside-murat-9nux8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kır bakalım şu kalbimi

Yerden yere at şu gönlümü

En sonunda ettin deli

Ne istersin belli değil

Sağın solun belli olmaz

Ne bu halin, vurdumduymaz

Böyle sevda bana uymaz

Ettiğin yanına kalmaz

Önemli değil, önemli değil

Senin canın sağ olsun

Önemli değil, önemli değil

Yeter ki gönlün olsun

Hiç yerinde durmuyorsun

Çağırsam da gelmiyorsun

Sevdiğimi biliyorsun

Yar sevdiğin belli değil', 'Kır bakalım şu kalbimi Yerden yere at şu gönlümü En sonunda ettin deli Ne istersin belli değil Sağın solun belli olmaz Ne bu halin, vurdumdu...', ARRAY['Türk Edebiyatı','Şiir','Reşide Murat']::text[], 8.5, '{"poet":"Reşide Murat","poet_slug":"reside-murat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/onemli-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anana da İnat', 'anana-da-i-nat-askin-tuna-ulq4i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zaten çıgınlara dönmüşüm aşktan

Bin türlü delilik gelir aklıma

Bir de tatlı tatlı gülüşün varya

Basma ne olur can damarıma

Gözüm kara, cansın bana

Sen benimsin yar

Sevdan yara, başıma bela

Dertlerimsin yar

Anana da inat, babana da inat

Alacağım seni yar

Ele güne boşver, hadi hadi koş gel

Saracağım seni yar

Seni gördüğmde içim yanıyor

Öyle uzaklardan bakma ne olur

Deli severken el gibi bakmak

İnan ki güzelim çok zor geliyor', 'Zaten çıgınlara dönmüşüm aşktan Bin türlü delilik gelir aklıma Bir de tatlı tatlı gülüşün varya Basma ne olur can damarıma Gözüm kara, cansı...', ARRAY['Türk Edebiyatı','Şiir','Aşkın Tuna']::text[], 8.5, '{"poet":"Aşkın Tuna","poet_slug":"askin-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anana-da-inat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Deprem Hikayesi', 'bir-deprem-hikayesi-sabri-salman-lrirw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben de çocuktum sizin gibi

Benim de annem, babam,

Benimde okulum, öğretmenlerim, kitaplarım vardı.

Okuyup, öğretmen olmak istiyordum ben de.

İyi insanlar yetiştirmek vatanıma, milletime.

Ortaokula başlayacaktım,

Sevinçliydim, heyecanlıydım

Yeni elbiseler almıştı babam 15 Ağustos’ta.

Öyle güzeldi ki onlar, gece onlarla yatmıştım

Yeni ayakkabılarımı kimse almasın diye

Dolabın altına saklamıştım.

Oysa onu çaldılar, yıkılan binamızın altına sakladılar.

Annem saçlarımı tarardı her sabah,

Babam “Bal bademim” der sarılırdı her akşam.

Benim bütün hayallerim yıkıldı o korkunç gece

Ben depremi sözlükten bilirdim,

Babamsa Erzincan’dan, Adana’dan, Dinar’dan

Yine öylesi bir akşamdı 16 Ağustos’ta

Herkes, evine, sevdiklerine gidiyordu.

Biraz durgundu ninem ,“Kötü bir şey olacak.” diyordu

Babam: “Yeni elbiselerini giy, göreyim.” dediğinde: 

“Okulların açıldığı gün giyeceğim” demiştim.

Yine uykuya daldım, uyanma ümidiyle.

Oysa hiç sabah olmadı

Biliyor musunuz saçlarımı tarayan annem yok artık?

“Bal bademim” sözünü de duyamayacağım babamdan,

Ninem de çok sevdiği dedemin yanına yatamadı

Bir çukura gömmüşler onu.

Artık beni sevemeyecekler.

Sevgi ve gözyaşı bilmeyenlere kurban verdim onları.

Biliyor musunuz? 

Yeni elbiselerimi bir kerecik olsun giyemedim

Yıkılan evimizin altında kaldı

Benim okulum da yok artık biliyor musunuz?

Ah! Suat öğretmenim, ne çok severdim seni.

Hastane odasında, televizyonda gördüm

Koca koca adamlar, ellerinde kelepçe

“Depremde yıkılan evleri yapanlar onlar” dedi Hemşire Abla

Neden yaptınız Amca! Birkaç parça demire, 

Bir avuç çimentoya neden sattınız hayallerimi?

Oysa sizin anneniz, babanız, okulunuz, öğretmenleriniz,

Oyuncaklarınız, yeni oyuncaklarınız var.

Bense annesiz, babasız, okulsuz...

Dilerim ki, böyle felaket bir daha yaşanmasın

Böylesi acıları anlatan bir şiir de

Bir daha yazılmasın!

                                                  (Eylül 1999-Bartın)

" Yan ki üşümesin Yüreğin" adlı şiir kitabından...', 'Ben de çocuktum sizin gibi Benim de annem, babam, Benimde okulum, öğretmenlerim, kitaplarım vardı. Okuyup, öğretmen olmak istiyordum ben de....', ARRAY['Türk Edebiyatı','Şiir','Sabri Salman']::text[], 8.5, '{"poet":"Sabri Salman","poet_slug":"sabri-salman","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/bir-deprem-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nilüferler Zamanı', 'niluferler-zamani-i-smail-erkan-tolay-8jyen', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayatı daima bir bitki, bir çiçek kıvamında yaşar insanlar.Bazıları Kaktüstür, Çalı yada Devedikeni.Öyleki yaklaşanları çizer, yaralar, hep zarar verirler çevrelerine.Yanlarında ne bir ot ne bir çiçek biter.Bazıları zambaktır, şımartılır ama hep yapa yalnız yaşamak zorunda kalırlar.Bazılarıysa Kırçiçekleridir, 

Saf ve güzel ama korumasız.Güzellikleri yüzünden kopartan çok olur onları, farkına bile varamazlar...

Bazen büyür ağaç olur insan.Kendini üstün görür, dik başlılığa kapılır sağlam çınar ağaçları gibi, ama ilk fırtınada kırılır, yok olur gider.Kimi, söğüt ağaçları gibi eğilir en ufak rüzgara bile.Kimi zaman da sarmaşık olur insan, başkalarına dayanmak zorunda hisseder kendini ve hep öyle yaşar, başkalarının sırtından...

Mevsimler geçirir insan, Güller gibi hırçın, Çarkıfelek gibi güleryüzlü, Aslanağzı gibi şakacı, Orkide gibi gururlu, Nergis gibi iddiacı, Menekşe gibi ürkek, Maranta gibi entel, Begonya gibi kompleksli, Fulya gibi kıskanç, Zakkum gibi zehirli, Karanfil gibi hüzünlü ve Lale gibi karamsar olur.

Oysa bir tek çiçek vardırki isteyen, çaba harcayan herkesi arasına katabilen ve bir daha asla geri vermeyen.Nilüferdir bu çiçeğin adı, umut doludur, güçlüdür, direnir acılara ve erişilmezdir suların korumasında.Kendi dünyasındadır o, bu yüzdendirki her gün yeniden yaratabilir kendini.Çiçeğini kopartan olursa yenik düşmez umutsuzluğa, yeni çiçekler sürer köklerinden.Hep sevecendir, hep güler yüzlü, hep umutlu ve daima yenilmezdir o...', 'Hayatı daima bir bitki, bir çiçek kıvamında yaşar insanlar.Bazıları Kaktüstür, Çalı yada Devedikeni.Öyleki yaklaşanları çizer, yaralar, hep ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Erkan Tolay']::text[], 8.5, '{"poet":"İsmail Erkan Tolay","poet_slug":"i-smail-erkan-tolay","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/niluferler-zamani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Annem', 'canim-annem-fatih-erdem-2-a6xax', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Canım annem, canım annem, 

Bana baktın, sıkılmadın.

Beni sevdin, bıkmadın.

Canım annem, canım annem.

Dokuz ay karnında taşıdın.

Of, deyip sıkılmadın.

Beni canın kadar sevdin.

Canım annem, canım annem.

Yüreğimdeki sevgisin

Bana göre bir tanesin, 

Dünyanın en güzel çiçeğisin, 

Canım annem, canım annem.

Benim için eşsizsin, 

Sen bana kardeş gibisin, 

Evde hep şensin, 

Canım annem, canım annem

Beni çok seversin, 

Yanındayım dersin, 

Beni teselli edersin, 

Canım annem, canım annem

Bana nasihat edersin, 

Sen nurlu bir meleksin, 

Evimizin neşesisin, 

Canım annem, canım annem

Yanındaki hazinemsin, 

İçimdeki bilgimsin, 

Sen benim bir tanemsin

Canım annem, canım annem.

İçimdeki sevgimsin, 

Her zaman güneşimsin, 

Sen beni çok seversin

Canım annem, canım annem.', 'Canım annem, canım annem,  Bana baktın, sıkılmadın. Beni sevdin, bıkmadın. Canım annem, canım annem. Dokuz ay karnında taşıdın. Of, deyip sı...', ARRAY['Türk Edebiyatı','Şiir','Fatih Erdem 2']::text[], 8.5, '{"poet":"Fatih Erdem 2","poet_slug":"fatih-erdem-2","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/canim-annem-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükendiğim', 'tukendigim-lord-of-the-dark-uhjo1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ne sevdalar kaldı

içinde sürüklendiğim

ne hayallerim kaldı

her gece düşlediğim

birtek hasretin kaldı

çektikçe tükendiğim', 'ne sevdalar kaldı içinde sürüklendiğim ne hayallerim kaldı her gece düşlediğim birtek hasretin kaldı çektikçe tükendiğim...', ARRAY['Türk Edebiyatı','Şiir','Lord Of The Dark']::text[], 8.5, '{"poet":"Lord Of The Dark","poet_slug":"lord-of-the-dark","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/tukendigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Musandıra', 'musandira-osman-bulent-manav-3douz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'I.

Kağşamış evlerin cumbalarından

Sokağı gözleyen çiçekler gibi

Gerçeği hayalle kanatlandıran

Çocuklardır şehrin asıl sahibi...

Çocuk yüreğinde büyürse umut, 

Kahve köpüğüne dünyalar sığar.

Acıyı sabırla örtmeli sükut, 

Gün doğmadan evvel gör neler doğar...

II.

Hem eski eşya hem masal dolabı, 

Sini, kevgir, maltız, hepsi burada, 

Sabırtaşı, Harkıt, Lokman kitabı, 

Hayal ve hakikat musandırada...

Burası bir turfe dükkan-ı hikem, 

Raflarda rengarenk umutlarımız, 

Kimi harcıalem, kimiyse mahrem, 

Bütün hiçliğimiz, bütün varımız...

Masalsız büyüyor şimdi çocuklar, 

Ne konuşan çiçek, ne ağlayan kuş...

Hayal ülkesinde susunca rüzgar, 

Anka uçup gitmiş, devler uyumuş...

Oysa biz tıkayıp kulağımızı, 

Kevser’in sesini duyabilirdik...

Hışımla camlara vuran poyrazı

Söze kalbetmeyi bir biz bilirdik...

Aşkın ifadesi gözyaşlarıydı, 

Belki de mektubun ucunu yakmak...

İstinye koyunda yaz akşamları, 

Sular sararınca semaya bakmak...

Mevsimler zamansız çıkmazken yola, 

Sevgi gönüldeydi, hem en derinde...

Hep ikindi vakti gelirdi leyla, 

Bütün bir İstanbul, eteklerinde...

Gençken, yürekliyken, kor kor yanarken

Kurduğumuz hayal içre gülendam

Bir özge çiçekti, güneş sönerken, 

Onun kadar güzel inmezdi akşam...

Ağla Alaaddin, kırıldı lamba, 

Her parçası ayrı alıcı buldu, 

İyi para etti haraç mezatta, 

Cinlerin tahtına bilim kuruldu...

III.

Ne çok yıldız vardı çocukluğumda, 

Hepsinde bir masal, bize bakardı...

Cadıları kovup uyuduğumda, 

Üç küçük şehzade yola çıkardı.

Ne çok yıldız vardı çocukluğumda...

Yıldızlar göç etti ve şehir öldü, 

Yorgun sokaklarda yorgun insanlar...

Masallar sır olup göğe süzüldü, 

Bu acıyı bir tek çocuklar anlar, 

Yıldızlar göç etti ve şehir öldü...

Bir yangın büyüyor gözbebeğimde, 

Şavkı yıldızlara vuran bir yangın.

Kim çaldı atımı, kılıcım kimde? 

Ben deli değilim, öyle bakmayın, 

Bir yangın büyüyor gözbebeğimde...

IV.

Bütün damarlardan çekildi şiir, 

Babamı daha çok aramaktayım.

Saatler hızlanıp, öldükçe şehir, 

Onu daha iyi anlamaktayım...

Eski bir rüyanın sudaki aksi, 

Belki bir fidandı, kurutuldu aşk.

Rüyalarımızın rüzgarı dindi, 

Duruldu dalgalar, unutuldu aşk...

Ve gözkapağında bölündü dünya, 

Bir yanda hakikat, bir yanda hayal.

Günahın gölgesi düştü yollara, 

Bir yanda mükafat, bir yanda vebal...

Kapandı pencere, tükendi takvim, 

Denizin kokusu, çok uzaklarda...

Düşler arasında yitti sevdiğim, 

Ceviz lekeleri kaldı duvarda...

Silinip kaybolan mısralar kadar

Acı çekiyordu ölürken, gece...

Şehre veda etti musandıralar, 

Mahrem kuytulara ışık düşünce...', 'I. Kağşamış evlerin cumbalarından Sokağı gözleyen çiçekler gibi Gerçeği hayalle kanatlandıran Çocuklardır şehrin asıl sahibi... Çocuk yüreği...', ARRAY['Türk Edebiyatı','Şiir','Osman Bülent Manav']::text[], 8.5, '{"poet":"Osman Bülent Manav","poet_slug":"osman-bulent-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":79,"source_url":"https://www.antoloji.com/musandira-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Bahar Şiiri', 'son-bahar-siiri-osman-bulent-manav-nfi8n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hakkari yaylalarının soğuk pınarlarına hasret kalan çobanlarla, babası “atta”ya gidip de dönmeyen bebelerin masum ve mahzun bakışlarında saklı olan için...

Bu şiir öfkemiz tutuştuğunda

Göğsümüzü saran ateşe dair

Tek kelam etmeden akşam olunca

Ağlayışımızın hikayesidir...

Kurudu gökyüzü, ne yağmur ne kar...

Bütün aşıkların söndü kandili, 

Dağ gibi yiğitler ve yiğit dağlar, 

Bizim buralardan gitti gideli...

Gittiler, “dünya”yı bize bırakıp, 

Bırakıp öfkeyi, hırsı, telaşı...

Sadece bir defa geriye bakıp

Veda eylediler rüzgara karşı...

Gönlündeki yağmur dinmesin yarim, 

Yüreğin hasretsiz kalmasın sakın.

Hayat bu, bilinmez, belki dönerim, 

Ben yokken sonbahar gelmesin sakın.

Tadını sorarlar hasretin, sana, 

“İstanbul...” desen de kimse anlamaz...

Vuslatın rengini sorduklarında, 

De ki, sonbahara benziyor biraz...

Yayla rüzgarları delirdiğinde

İçine sığınan hislere dokun, 

Sıcacık hüzünler dolar eline...

Varsın artık mevsim sonbahar olsun...

Mevsimin, yeşilden sarıya; ufkun, maviden kızıla; umutların, pembeden griye dönmekte olduğu bir akşamüstüydü. Baharın ölüm haberi geldi dağlardan, bir allı turnanın buğulu bakışlarında...

Soğudu sadrımız, buz kesti alem...

Sahte güneşlerde ısınmak vakti! 

Namus pörsüyünce, satıldı kalem

Ve iyi insanlar ölümü seçti...

Yirmibir yaşında, ahret yolcusu, 

Kardeş kurşunuyla devrildi yere, 

Bir ah eyledi ki, gökler dolusu...

Ölümü anlattı bilmeyenlere...

Onlar anlayamaz ölmeyi anne, 

Dağlar yeşerirken, mevsim baharken

Hiç ölmemişlerdir yirmibirinde

Namluya yaslanıp yari düşlerken...

Öldür ve öl derler, ötesi yoktur! 

Gönülde sevdalar, yürekte kurşun...

Derler ki, burası bizden sorulur, 

Öldürün milleti, vatan sağolsun...

Akar kardeş kanı boz yamaçlara, 

Hayaller, hasretler geride kalır...

Bir yangın köpürür dağ başlarında, 

Vurulan yıkılır, vuran yıkılır...

... ve, herşeyi olmasa da pek çok şeyi bilen büyükler mırıldandılar: Bütün hayali, içinde güneşlerin doğup battığı sevdalı bir yürek tarafından sevilmek olan gencecik gelinlerin gözpınarlarında titreşen utangaç gözyaşlarına sormalıydık aslında; ömrünce gördüğü baharların sayısı yirmibeşi asla bulmayan delikanlıların kanları, paraya, rütbeye, oy’a tahvil edildiğinde kopan fırtınanın neleri alıp götürdüğünü...

Bir “ulu rüya”mız vardı eskiden, 

Ne biz aynı kaldık, ne de Üsküdar...

Şimdi ağlayalım, zira bu giden

Belki sonbahardır, belki son bahar...

Evet, ağlayalım, kirli yüzümüz, 

Ayışığı gibi masum ve sakin...

Kanıyla beslenip büyüdüğümüz

Saf delikanlılar, bizi affedin...

Şiir, tevekkülle isyan etmektir, 

Hırçın rüzgarlara, suskun dağlara...

Umulur ki leyla yeniden gelir, 

Bürünüp akşama ve son bahara...', 'Hakkari yaylalarının soğuk pınarlarına hasret kalan çobanlarla, babası “atta”ya gidip de dönmeyen bebelerin masum ve mahzun bakışlarında sak...', ARRAY['Türk Edebiyatı','Şiir','Osman Bülent Manav']::text[], 8.5, '{"poet":"Osman Bülent Manav","poet_slug":"osman-bulent-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/son-bahar-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Özlemişim..', 'nasil-ozlemisim-lord-of-the-dark-c6t8t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Önce ellerin oldu bulutlar

tenini hissettim yumuşaklığında

yanakların oldu al al pembe bulutlar

sonra parçalandı rüzgarda, 

yüreğimle beraber.

Nasılda Özlemişim Bir Bilsen...! 

bir gece yarısı 

sensizlik düştü yatağıma

önce efkar bastı yüreğimi

sonra hüzün çöktü geceye

bir damla hasret düştü yanağıma

Nasılda Özlemişim Bir Bilsen...! 

gözlerim daldı

gecenin karanlığına, 

Ay sen oldun

Yıldızlar gözlerin, 

bakıştık sabahadek göz göze, 

bu gece ankara sen kokuyordu.

NASILDA    ÖZLEMİŞİM 

                                BİR BİLSEN...!', 'Önce ellerin oldu bulutlar tenini hissettim yumuşaklığında yanakların oldu al al pembe bulutlar sonra parçalandı rüzgarda,  yüreğimle berabe...', ARRAY['Türk Edebiyatı','Şiir','Lord Of The Dark']::text[], 8.5, '{"poet":"Lord Of The Dark","poet_slug":"lord-of-the-dark","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nasil-ozlemisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ortak payda', 'ortak-payda-ahmet-i-plikci-orvax', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir insana bir deger desem

Tum dunya 6 milyar eder

Insanlarin ortak paydasi ne desem? 

Insanin nefsi cikar 

Ben bu toplam degeri

Ortak paydaya bolsem

Bu deger ayni kalir

Ama nefis ortadan kalksa

Bu deger baska eder', 'Bir insana bir deger desem Tum dunya 6 milyar eder Insanlarin ortak paydasi ne desem?  Insanin nefsi cikar  Ben bu toplam degeri Ortak payda...', ARRAY['Türk Edebiyatı','Şiir','Ahmet İplikci']::text[], 8.5, '{"poet":"Ahmet İplikci","poet_slug":"ahmet-i-plikci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ortak-payda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yandığım', 'yandigim-lord-of-the-dark-vwm5y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir ulu deryaymış bitmez sandığım

Yağmursuz bir bulutmuş yar saydığım

Şimdi ağlasammı yansammı bilmem

Bir orman içinde ağaçmış yandığım.

Bir o var sanırdım bu alem içinde

Çok sonra anladım kini kendi içinde

Bir kozalakmış bin yıllık çınar dibinde

Rüzgarla savrulan yaprakmış yandığım.

Daha dün hazırdım dağları delmeye

Aya bile giderdim yarimi görmeye

Gece uzun sürdüde ben rüyamdan uyandım

Kabuslar içinde yalanmış yandığım.

Yüreğimde ısıttım büyüttüm sessizce

Yoktu benden mutlusu bu alem içinde

Sende Şeytan çıktın bin Melek içinde

Rüyasına daldığım hayalmiş yandığım......', 'Bir ulu deryaymış bitmez sandığım Yağmursuz bir bulutmuş yar saydığım Şimdi ağlasammı yansammı bilmem Bir orman içinde ağaçmış yandığım. Bir...', ARRAY['Türk Edebiyatı','Şiir','Lord Of The Dark']::text[], 8.5, '{"poet":"Lord Of The Dark","poet_slug":"lord-of-the-dark","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yandigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece Sana', 'sadece-sana-gurol-genc-pel-van-k8gak', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sence askmı bitti

askı tasıyacak zamanmı

babadan miras siyah uclu kursun kalemim

oda bitti ne komik diymi 

sende bittin.......', 'sence askmı bitti askı tasıyacak zamanmı babadan miras siyah uclu kursun kalemim oda bitti ne komik diymi  sende bittin..........', ARRAY['Türk Edebiyatı','Şiir','Gürol Genç Pel Van']::text[], 8.5, '{"poet":"Gürol Genç Pel Van","poet_slug":"gurol-genc-pel-van","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sadece-sana-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahpusluk İşte', 'mahpusluk-i-ste-edip-cangonul-jbl5c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Elini verirsin de alamazsın

Bilir misin

İşte öyle mahpusluk

Sanki

Kapılmışsın Fırat’ın suyuna da gidermişsin

Gülmek haramdır sana

Ve ağlamak da

Herşeyin vardır ama 

İşte o kadar

Ne gülme 

Ne yoksulun çilesini matematiğe vurma şansın vardır

Oysa matematiğin Allah’ı gibi duyumsarsın kendini

Ya da..........

İnsan vücudu 52 DNA’lık bir şeydir senin için ama

Bir şey

o bir de takılırsın

   ya da şey de

takılır kalırsın

kimi bir roman

kimi bir sözcüktür sana

boku yediğinin resmidir artık', 'Elini verirsin de alamazsın Bilir misin İşte öyle mahpusluk Sanki Kapılmışsın Fırat’ın suyuna da gidermişsin Gülmek haramdır sana Ve ağlamak...', ARRAY['Türk Edebiyatı','Şiir','Edip Cangönül']::text[], 8.5, '{"poet":"Edip Cangönül","poet_slug":"edip-cangonul","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mahpusluk-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol Hali', 'yol-hali-edip-cangonul-pb0t0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir minibüsün üstündesin; 

Altın tahta, 

Üstün tahta, 

Sağın, solun, 

Önün, arkan.

Araba kasise girse

Tıngırsın, mıngırsın

Kafa, göz, 

Sırt, but

Vurur bir o yana bir bu yana.

Ne durduğunu bilirsin minibüsün

Ne gittiğini

Herkes inip binebilir 

Senin gıkın bile çıkamaz, lal olmuşsun

Sırtım acıdı bile diyemezsin

İşte öyle bir yolculuk

Bir top bez içinde

Ne sen bunun farkındasın

Ne minibüs

Minibüs durur bir yazıda

Eller üstünde inersin

İnsanlar baş tarafını tutmak için yarışırlar, hoyrat

Bırakın ulan diyemezsin

Yuvarlanacağın çukura geldiğinde açarlar kapağını tabutun

Aydınlık vardır göremezsin

Toprak sıcak ve yumuşaktır kahrolası tahtalara nispet

Hissedemezsin

Yığınla oksijen molekülü vardır çevrende

Soluyamazsın

Sen bitmişsin', 'Bir minibüsün üstündesin;  Altın tahta,  Üstün tahta,  Sağın, solun,  Önün, arkan. Araba kasise girse Tıngırsın, mıngırsın Kafa, göz,  Sırt,...', ARRAY['Türk Edebiyatı','Şiir','Edip Cangönül']::text[], 8.5, '{"poet":"Edip Cangönül","poet_slug":"edip-cangonul","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yol-hali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı Sen Yaptım', 'aski-sen-yaptim-lord-of-the-dark-n9i0q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senin hayalinle bile yaşamak çok güzel

Hayatımın resmini, hayalinle çiziyorum

En güzel şarkıyı

Sesinin melodisiyle söylüyorum

Gecemi sen yaptım

Her gece gök yüzünde seni izliyorum

Saçlarındaki yıldızları sayıyorum Tek Tek.

Rüzgarı sen yaptım

Kokunu çakiyorum deriin, derin her lodosda

Çiçekleri sen yaptım

Gözüm gibi bakıyorum 

Her sabah onlar SEN açıyor

Sigaramı hasretin yaptım

Heran çekiyorum derin, derin

Sönmesin istiyorum

Durmadan SENİ çekiyorum içime.

Sayfaları sen yaptım

SENİ yazıyorum şiirlerde

Boş sayfalara kazılı

Hece hece ismin duruyor.

Ama artık hayalinle yaşamak istemiyorum

Seni yalnızlığımda yaşamak yerine

Gerçekleşmiş hayaller istiyorum.

Yolları SEN yaptım 

Her gece sana geliyorum 

Her nekadar bitmek bilmesede.

Hasreti artık eskittim

Ben SENİ istiyorum

Artık herşey gibi sevgiyide SEN yaptım 

Seni seviyorum

seni.......SEVİYORUM.......................................,', 'Senin hayalinle bile yaşamak çok güzel Hayatımın resmini, hayalinle çiziyorum En güzel şarkıyı Sesinin melodisiyle söylüyorum Gecemi sen yap...', ARRAY['Türk Edebiyatı','Şiir','Lord Of The Dark']::text[], 8.5, '{"poet":"Lord Of The Dark","poet_slug":"lord-of-the-dark","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/aski-sen-yaptim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nostaljimi Ne?', 'nostaljimi-ne-edip-cangonul-py4lk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Artık bülbül ağlamıyor 

         Güle

Rotatifler basıyor notalarını

          Türkülerin

Aşkı bile çocuklar çiziktiriyor

          Sıralara

Ve

Hiç birimize yer yok

           Türkçe kitaplarında

Türkçe sadece virgül

Sevda gül

Gül ustam gül

Pirim

Yananlar ozan

Biz ölü', 'Artık bülbül ağlamıyor           Güle Rotatifler basıyor notalarını           Türkülerin Aşkı bile çocuklar çiziktiriyor           Sıralara ...', ARRAY['Türk Edebiyatı','Şiir','Edip Cangönül']::text[], 8.5, '{"poet":"Edip Cangönül","poet_slug":"edip-cangonul","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/nostaljimi-ne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Gönüle Düşünce', 'gonul-gonule-dusunce-suleyman-apaydin-0zape', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yürüyen kul koşar olur

Gönül gönüle düşünce

Yüce dağdan aşar olur

Gönül gönüle düşünce

Duvarlar dağlar delinir

Krallar tahtlar devrilir

Uğruna kelle verilir

Gönül gönüle düşünce

Ne pranga zindan engel

Ne bey paşa sultan dinler

Ölüme gülerek gider

Gönül gönüle düşünce', 'Yürüyen kul koşar olur Gönül gönüle düşünce Yüce dağdan aşar olur Gönül gönüle düşünce Duvarlar dağlar delinir Krallar tahtlar devrilir Uğru...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Apaydın']::text[], 8.5, '{"poet":"Süleyman Apaydın","poet_slug":"suleyman-apaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gonul-gonule-dusunce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devam mı....?', 'devam-mi-yavuz-turhan-yt05t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '-Aşkımız devam edecekmi? diye soracak olursan...

  devamı olursa gelişir... ve serpilir yüreğine.

bedenin  belki bir aşka vurulurken, 

gözyaşların doldurmaya başlayacak

kafandaki boşlukları....

başlarken her yeni aşka; 

ayrılığa da kurulmuş alcak zaman.

her şey geliştikçe güzelleşecek..güzelleştikçe yaşanacak

yaşandıkça da 

daha anlamlı kılınacak  günler..

güneş çoğu zaman batıdan doğacak.

ama doğudan batmayacak...

serpilmeye devam edecek..

ta ki başımızda soğuyana dek.........', '-Aşkımız devam edecekmi? diye soracak olursan...   devamı olursa gelişir... ve serpilir yüreğine. bedenin  belki bir aşka vurulurken,  gözya...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Turhan']::text[], 8.5, '{"poet":"Yavuz Turhan","poet_slug":"yavuz-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/devam-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuslat ve Ayrılık', 'vuslat-ve-ayrilik-gokcen-duran-qh4d2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ayrılık kadehte olsa 

İçeriz dem be dem...

Vuslat ab-ı hayat olsa

Dökeriz dem be dem....', 'Ayrılık kadehte olsa  İçeriz dem be dem... Vuslat ab-ı hayat olsa Dökeriz dem be dem.......', ARRAY['Türk Edebiyatı','Şiir','Gökçen Duran']::text[], 8.5, '{"poet":"Gökçen Duran","poet_slug":"gokcen-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/vuslat-ve-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yillar sonra', 'yillar-sonra-suleyman-apaydin-eblj3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yillar sonra gördüm seni

Gözlerinde hüzün vardi

Tutamadim ellerini 

Bir oglun bir kizin vardi

Ak düsmüstü saclarina

Titreyen bir sesin vardi

Gülüyordu yüzün amma

Yüreginde sizin vardi

Bir hüzünlü sonbahardi

Mehtap yine dolunaydi

Gir koluma diyemedim

Bir oglun bir kizin vardi

Yasanilan kara sevda

Unutulmaz bir cirpida

Dillerin inkar etse de

Dudaginda izim vardi

Yillar yili yarim kalan

Sana bir cift sözüm vardi

Ar ettim de diyemedim

Bir oglun bir kizin vardi', 'Yillar sonra gördüm seni Gözlerinde hüzün vardi Tutamadim ellerini  Bir oglun bir kizin vardi Ak düsmüstü saclarina Titreyen bir sesin vardi...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Apaydın']::text[], 8.5, '{"poet":"Süleyman Apaydın","poet_slug":"suleyman-apaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yillar-sonra-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakamda Eylül Sarısı', 'yakamda-eylul-sarisi-kamil-aydemir-3lz55', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'içimde sıcaklığını giyinmiş dün yürür

sevmesini bilmiyorsa 

insan sevgi dolu yürktede boğulur

bakışların mavisi

avucumda sevgi okyanusu olur

alnımda berbat izi yoksulluğun

ama acılar sağır

yüreğimde yokluğun

taşıyamayacağım kadar ağır

yakamda eylül sarısı

yaşam öğretti bana

sevdiğiyle gidiyormuş insanın yarısı

yüreğim biraz da bundan asi

yarınsız sevda benimkisi

yakamda eylül sarısı', 'içimde sıcaklığını giyinmiş dün yürür sevmesini bilmiyorsa  insan sevgi dolu yürktede boğulur bakışların mavisi avucumda sevgi okyanusu olur...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yakamda-eylul-sarisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuyorum', 'korkuyorum-ercan-gencer-gszic', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Korkularımla yürüyorum karanlıkta, 

Sense karanlığı hiç bilmeden gidiyorsun. 

Siyahın gözlerime verdiği elemi

Ne kadar silsem de bitmez ki 

Kabullenemiyorum her zaman olamaz gece 

Sabaha kavuştuğumda hayaline uzanırım belki

Bilmelisin sensiz nefes almak istemiyorum 

Hep senin yanında olmalıyım

Bilmelisin arkadaşlarımı sevmiyorum artık 

Hepsi birer yalancı, 

Senin benimle uyandığını görmeyi çok istiyorum 

Biliyorum sus diyeceksin, hayalperest diyeceksin 

Yanarım ama nafile yüreğim sızlamakta 

Biriciğim nerede sıcaklığın 

Üşümekte ellerim sakın bırakma 

İçimdeki soğuk kışta yanlız bırakma beni 

Sevgilim neden neden her yer karanlık 

Nerede hayallerim? nerede güneşim? 

Aynalarda neden göremiyorum kendimi

Neden ısıtmıyor bedenimi kanım

Neden sevdiğim neden 

Neden içimi sensizlik korkusu sardı 

Nereye gidiyorsun, gitme ne olursun

Yüzümde sensizliğin hüznü olmasın 

Ağlayamıyorum artık

Gözlerime mühür vurmuşlar

Konuşamıyorum artık 

Dilimi koparmışlar

Herkes görmemezlikten geliyor beni 

Tanıyan yok sanki beni küçük dünyamda

Hiç biri umrumda değil 

Tek isteğim ve hayalim 

Seninle olmak her an

Son güzüm olmayacak bu güz

Yürüyorum sevdiğin kuru yapraklarda 

Hayallerimle, sana aç kalbimle

Sana koşuyorum 

Görüyorum artık seni 

Kolarını açmış bekliyorsun beni 

Bağıra bağıra geliyorum sana 

Seni seviyorum...

Sen şimdi mışıl mışıl uyuyosun, 

Ben hep seni düşünüyorum.

Şimdi ağlıyorum, 

Yanında olamadığıma.

Sen rüyanda beni görmelisin, 

Kalbim gülüyor aslında, 

Kalbinin anahtarı ellerimde.

Sesim üzülmüyecek, 

Sesinle karıştığında.

Gözlerimde mutluluklar olacak, 

Gözlerindeki ışığı görünce.

Şiirlerimde hüzün olmayacak, 

Aynı şiirleri okuduğumuzda.

Hayallerim gerçek olcak, 

Aynı haylleri kurduğumuzda.', 'Korkularımla yürüyorum karanlıkta,  Sense karanlığı hiç bilmeden gidiyorsun.  Siyahın gözlerime verdiği elemi Ne kadar silsem de bitmez ki  ...', ARRAY['Türk Edebiyatı','Şiir','Ercan Gencer']::text[], 8.5, '{"poet":"Ercan Gencer","poet_slug":"ercan-gencer","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/korkuyorum-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan Ağlayacaksın', 'kan-aglayacaksin-cengiz-yazici-ux5vv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen daha  tazesin, 

Dağ gibi umutların var.

Bense isyansı ihtiyar, 

İçimde sadece, 

Hayallerimin kırıntıları var.

Yolun çok başlarındasın, 

Çekilecek acılara, 

Salaksı dertlere gebesin.

Beleşino hataların, 

Faklarına basacaksın.

Ümitle bakarken yarınlara, 

Bal damlası gözlerinle.

Sen, bensiz günlerinde, 

Sessiz sessiz, 

Kan ağlayacaksın.', 'Sen daha  tazesin,  Dağ gibi umutların var. Bense isyansı ihtiyar,  İçimde sadece,  Hayallerimin kırıntıları var. Yolun çok başlarındasın,  ...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kan-aglayacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehirde', 'bu-sehirde-cengiz-yazici-3htmg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu şehirde hava zamansız kopar.

Yağmur sanki bardaktan boşanır.

Aşağıda sel olur, dereler taşar, 

Ejderha olur dere, denize koşar.

Varoşlarındaysa bu şehrin, 

El kadar bebem, 

Bir damla su için ağlar.

Alkol su gibi boşalırken, 

Şişelerden bardaklara, 

Zerre kadar ses çıkmaz, 

Ödenen adisyonlara, 

Beri tarafta, 

Çöpten ekmek toplarken

Bu şehrin başka insanları, 

Sadece vitrinden bakar 

Bu şekilde yaşayan insanlara.

Emeksizdir bu şehrin sevgileri, 

Rahimlerin, çalınmıştır bebekleri.

Genç kızlar, bir gün afişte, 

Ertesi gün el değmemiş bakire.

Kafirleri herkesten fazla dindar.

Dindarları ise bir o kadar kafir.

Mezarlıkları ticaret hanedir bu şehrin, 

Fuhuşlar yapılır mezar aralarında, 

İmam kılığına girmiş sahtekarlar, 

Okudukları dualara besmelesiz başlar...!', 'Bu şehirde hava zamansız kopar. Yağmur sanki bardaktan boşanır. Aşağıda sel olur, dereler taşar,  Ejderha olur dere, denize koşar. Varoşları...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bu-sehirde-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söker Atarım O Kalbi Kökünden.', 'soker-atarim-o-kalbi-kokunden-cengiz-yazici-hafb5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir kez daha doğmayacaksa güneş, 

Yıldızlar gelişi güzel serpiştirilmişse, 

gökyüzüne, 

Ay, alaysı bakıyorsa dayıvari tepeden, 

Ve utanacaksam seni sevmekten, 

Söker atarım o kalbi kökünden.

Birgün başkaldıracaksa, içimdeki sana.

Ellerim gırtlağındadır, onu parçalarcasına.

Ve bir gün, 

Sana yazdığım şiirlerim yetim kalacaksa, 

Söker atarım o kalbi kökünden.', 'Bir kez daha doğmayacaksa güneş,  Yıldızlar gelişi güzel serpiştirilmişse,  gökyüzüne,  Ay, alaysı bakıyorsa dayıvari tepeden,  Ve utanacaks...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/soker-atarim-o-kalbi-kokunden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstisnalar', 'i-stisnalar-cengiz-yazici-an3b7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her ne kadar, 

Bozmasada kaideyi istisnalar.

Bir kez bozmaya görsün, 

Önünde ne kural kalır, 

Nede kanunlar.

Ne kadar gerçek varsa hayatta, 

Bir okadar da umut var.

Anlayana pek rastlanmaz, 

Gerçekler, 

Hep satır aralarında saklıdır....''', 'Her ne kadar,  Bozmasada kaideyi istisnalar. Bir kez bozmaya görsün,  Önünde ne kural kalır,  Nede kanunlar. Ne kadar gerçek varsa hayatta, ...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/istisnalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşenin Dostu Olmaz Dediler.', 'dusenin-dostu-olmaz-dediler-cengiz-yazici-190bf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir anlatsam yüeğimde neler var, 

Hani, seninim diyen o nazlı yar? 

Şu ömre kimbilir daha neler sığar.

Düşenin dostu olmaz dediler.

Bir vefasız viran etti hanemi, 

Onun için terk ettim ben bu yerleri.

Saysinde oldum, bir asi serseri, 

Düşenin dostu olmaz dediler.

Bir kaç mektubun kaldı, 

Ortadan yırtılmış bir resmin, 

Birde kulaklarımda yankılanan, 

O ilk günkü sesin.

Hep seni düşünüp, ben beklerken, 

Düşenin dostu olmaz dediler.', 'Bir anlatsam yüeğimde neler var,  Hani, seninim diyen o nazlı yar?  Şu ömre kimbilir daha neler sığar. Düşenin dostu olmaz dediler. Bir vefa...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dusenin-dostu-olmaz-dediler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Huysuz ve Hırçın.', 'huysuz-ve-hircin-cengiz-yazici-3mg15', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karadeniz dalgalarına benziyordu, 

Bir günü bir güne uymuyordu.

Yağan kar taneleri gibiydi, 

Gökten inerken masum, 

Doruklarda ise çığ oluyordu.

Hırsızdı.

Duygularımı çalıyordu.

Başkalarına satıyordu.

Reçetesiz ilaçların, 

Son tabletiydi.

Şifa yerine can alıyordu.

Kalpazandı.

Karşılıksız sahte duygular basıyodu.

Alıcısı çoktu, 

Çokta iyi kazanıyordu.

Sahte pazarların, 

Sanal tezgahlarında

Tavan yapıyordu.

Bir gün yiyeceği çelmeyi, 

Hiç hesaplamıyordu.

O gün geldi sabırlar tükendi, 

Ve yedi tekmeyi.

.....

Keşke, ah! keşke, 

Anlatmak istediklerimi

Bir anlayabilseydi.', 'Karadeniz dalgalarına benziyordu,  Bir günü bir güne uymuyordu. Yağan kar taneleri gibiydi,  Gökten inerken masum,  Doruklarda ise çığ oluyo...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/huysuz-ve-hircin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatmak istedikleri bir şeyler var.', 'anlatmak-istedikleri-bir-seyler-var-cengiz-yazici-upxuj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gölgesi düşmeyen ağaçların, 

Ötmeye yemin etmiş serçe kuşların, 

Doruklarında kar tutmayan dağların, 

Anlatmak istedikleri bir şeyler var.

İyileşmez kangrensi yaraların, 

Yarınları umutsuz, sokaktaki çocukların, 

Çiçeklere küskün, balsız arıların, 

Anlatmak istedikleri bir şeyler var.

Tohumlara dargın, kıraç toprakların, 

Bir yudum süte muhtaç yavruların, 

''''anne''''sözüne hasret kısır anaların, 

Anlatmak istedikleri bir şeyler var.

Yaşananlar bunlarken, 

Bunca gerçek varken, 

Yaşananlar bunlarsa, 

Eyer bunlar doğruysa, 

Bir dinleyelim bakalım....!', 'Gölgesi düşmeyen ağaçların,  Ötmeye yemin etmiş serçe kuşların,  Doruklarında kar tutmayan dağların,  Anlatmak istedikleri bir şeyler var. İ...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/anlatmak-istedikleri-bir-seyler-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'sahtekar', 'sahtekar-cengiz-yazici-bhc0a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu memleketin her taşının altında, 

Bir başka sahtekar çıkar.

Ve he gün bir başka sahtekarlık, 

üretilir demokratik, özgür beyinlerde.

İsteyen herkese, 

Kadının her çeşidi satılır, aşikar.

İsteyenlere yarısı kadın, 

Yarısı erkekler var.

Oda olmazsa naylon bayanlar.

Yeterki sen, 

Cüzdandan haber ver.

Hastahane kapılarında, 

Hasta yakınlarında, 

Bulunmazken tek bir aspirin.

Uyuşturucu haplar, 

Ayaklı eczanelerde var.', 'Bu memleketin her taşının altında,  Bir başka sahtekar çıkar. Ve he gün bir başka sahtekarlık,  üretilir demokratik, özgür beyinlerde. İstey...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sahtekar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canitous', 'canitous-kucuk-i-skender-gv7br', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'junkie can''a

Kelimelerden kurtulur ölen

mesafeler kendi tasarrufunca kısalır

çünkü can, biz gittiğimiz yerin hayvanıyız

Ne etin heybetindeki yüksek ateş tanrısı

ne de şuursuzca akraba çıkmak karşılar artık

hayat içersinde seninle benim yapışık kafataslarımızı

çünkü can, biz aynı ölüyü kemiren kurdun, olmayan ayaklarıyız', 'junkie can''a Kelimelerden kurtulur ölen mesafeler kendi tasarrufunca kısalır çünkü can, biz gittiğimiz yerin hayvanıyız Ne etin heybetindeki...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/canitous-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Carta', 'carta-kucuk-i-skender-38eel', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'pederastlara..

yavaşça içi boşalan hayvanın

gözlerinin özlenen küfe dönüştüğü, 

silikon dirsekleri mercana dayalı kadından

şatolara yitik 1 dul kanın cinayeti

çivi kentin demirden binalarında

bıçaktaki spermi yedi amadeus ve porsuk

ve sokaktan süvari general ilmühali

geçerken omuzlarında organik apoletler

aynaya ucukesik parmakla yazmıştı adını 2 cin

mor merdivenin ta başından fi sonuna

upuzun, karımtrak 3 martı tüyü, altmış dokuz hadisesi, 

dalgalanıyordu o saralı çürükasker çocuğun

yaşlı kabaetlerinde

ayna manya alamanya bayrağı dövmesi

sarmal karanlığın kasıklardan

aralık bir caz makamına kayması, 

tuzun içinde rakı

buzun yolunda kuyruklu 4 piyano

gibi sokuluyordu yüzüme porselen dudakları

şimdi limanda ve istasyonda

ve terminalde ve ''çıplak şose''de

secdeye varmakta alyans tırtılı, 

-kim vardı orada, diyorsun

-avuçlarım kanıyor, diyorum

kerhanede bıçaklanan 5 safkan dönmeyle

arandaki ipekten g, öbekkordonuna

konmakta zemheri böcekleri

kanunla neyin içten teğetinde

dolanmakta bir lir maralı, ah şiş, 

inşaat iskelesinde kendini asmış 6

kağıttan yelkenlide

çocukluğumun konvansiyonel aşk resitalleri

(ne kadar küçük mavinin gözleri

ne kadar kısa mavinin kirpikleri

ne ele gelmez bir menem hatıra şu

siyanür gömütü sürgün süitleri)

manzaralardan arta kalan bir arena bu

7 yerde kılıç içinde bir boğa burcu, 

tahtının arkasına gizlenen bir defn-i hilal

taçta gotiğin yılanları, hepsi yarım çapulcu

otelin mimarının vücudunun

bir yanı gençmiş bir yanı mumya

lala, sütunların gerisinde öldü

köprücük kemiklerinin boşluklarında

8 siyah lavanta fırkateyni!', 'pederastlara.. yavaşça içi boşalan hayvanın gözlerinin özlenen küfe dönüştüğü,  silikon dirsekleri mercana dayalı kadından şatolara yitik 1 ...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/carta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akasyalar', 'akasyalar-kucuk-i-skender-tpw41', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'dışarda.

kristal bir tekrar olsun istemiş haz tavı.

şekli buluğ ise itibar uyandırır ölümü.

şüphesiz.

kindir tartaklar göğün boşluklarındaki aşkı.

su göçünün aksindeki ibne gölü.

uygundur.

tınılı parmakuçlarının hazin kül dansı: 

kaynamış zampara gözlerin yorgun düğümü.

teşhirde.

ses geçirmeyen görüntülerin toy eşkıyası! 

vücudu örterken inler mi düşgücü...

sırılsıklam.

o kopartacak karanlık kanın kabuklarını.

o kaplayacak insan derisiyle metal üzüntüsünü.

biliyor yılan

bir kımıldasa devrilecek akasya ağacının süngüsü.', 'dışarda. kristal bir tekrar olsun istemiş haz tavı. şekli buluğ ise itibar uyandırır ölümü. şüphesiz. kindir tartaklar göğün boşluklarındaki...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/akasyalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kunboz', 'kunboz-kucuk-i-skender-h1uk1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Büyük bir yer sarsıntısı bizimkisi

fethettiği kente giren

komutanın ayaksesleri var sevişmelerimizde

Sanki ne anladım bugüne kadarki aşklardan

biraz hüzün işte, belki biraz da ıstırap

geriye kalanı, bir gece denize açılıp kaybolan çocuklar: 

karıştırılan eski bir kitabın içinden kayıp düşen, o kırık hayal', 'Büyük bir yer sarsıntısı bizimkisi fethettiği kente giren komutanın ayaksesleri var sevişmelerimizde Sanki ne anladım bugüne kadarki aşklard...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kunboz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hitchcock''un Aynası', 'hitchcock-un-aynasi-kucuk-i-skender-yy351', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'saklanış kıpırtılı

zarar baharları: içerilmemiş ilk sahte, 

hayata müdahele etmiş

takma etik

dingin raks - - zar ötesi zafer

gel, sebebe seril ey fütur

(yalnızlığın ilk maddesi gereğince)

altı adet sen varsın şimdi içerde

kan aşağıdan geçecek

sonbaharın kesik ayakları ve

başka gözüm

çıkıp oraya doğru hep aktığı

eşkıya obua', 'saklanış kıpırtılı zarar baharları: içerilmemiş ilk sahte,  hayata müdahele etmiş takma etik dingin raks - - zar ötesi zafer gel, sebebe ser...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hitchcock-un-aynasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçcep', 'i-ccep-kucuk-i-skender-otc62', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir buzun içinden geçti adım

anlatmak mı? büyülenmenin

temsili teması o. Suistimal

edilmiş düş arkası; çocuk

şövalyelerin bahçedeki havuzda

gördükleri tahta telefon

-casus aynanın arandığı-

söyleyerek arındığı kül in.

gözlerinden gizli bir şey kalmadı.

polis

hiçbirzaman bulamadı ölünün

tarihi yüzünü

içimdeki dava düştü', 'bir buzun içinden geçti adım anlatmak mı? büyülenmenin temsili teması o. Suistimal edilmiş düş arkası; çocuk şövalyelerin bahçedeki havuzda ...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/iccep-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fizikçiyi Dinliyorum', 'fizikciyi-dinliyorum-faruk-gorgulu-s09g4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'fizikçiyi dinliyorum gözlerim kapalı

önce hafiften bir vektor yaziyor

yavas yavas kapaniyor

yorgun dusmus goz kapaklarim

uzaklarda degil, çok yakinda

tahtadaki arkadasimin

hiç durmadan cirpinislari

fizikciyi dinliyorum gozlerim kapali

fizikciyi dinliyorum gozlerim kapali

dakikalar geciyor derken..

busbutun dusuyor goz kapaklarim

tahtadaki arkadaslarım idare ediyor

dayanin koclarim

fizikciyi dinliyorum gozlerim kapali

fizikciyi dinliyorum gozlerim kapali

serin serin iskele

civil civil Alanya sahili

hasır da insanlar sevdali

kendimi oralarda hayal ediyorum

fizikciyi dinliyorum gozlerim kapali

sevdalim geciyor hayalimden

ve bana goz kırpıyor

bir sey vuruyor kafama o anda

fizikci olmali

fizikciyi dinliyorum gozlerim acik', 'fizikçiyi dinliyorum gözlerim kapalı önce hafiften bir vektor yaziyor yavas yavas kapaniyor yorgun dusmus goz kapaklarim uzaklarda degil, ço...', ARRAY['Türk Edebiyatı','Şiir','Faruk Görgülü']::text[], 8.5, '{"poet":"Faruk Görgülü","poet_slug":"faruk-gorgulu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/fizikciyi-dinliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhbar', 'i-hbar-kucuk-i-skender-xpwpp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Harfler veriyorum gecemin vitrinine

isimsiz kalacak

bu kere, hançerlenmiş körebe

Ulaştığım muazzam zerre titrek bakıyor

üşüyor, daha çook üşüyecek

zalim melek indirilirken kelimeye

sana başka nur yok diyor tek tek eksik vecize', 'Harfler veriyorum gecemin vitrinine isimsiz kalacak bu kere, hançerlenmiş körebe Ulaştığım muazzam zerre titrek bakıyor üşüyor, daha çook üş...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ihbar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalı Güzeli', 'yali-guzeli-orhon-murat-ariburnu-zso2l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaşların eski sekize benzer yalı güzeli

Gözlerin yeni elife

Ellerinden mısralar dökülür

Kıvrım kıvrım

Duruşundan gün doğar çifter çifter

Serçe parmağın

Muzip bir harikadır

Kalbimi okşar

Lakin

Sana aşık olduğumu söyleyemem

BABANDAN KORKULUR', 'Kaşların eski sekize benzer yalı güzeli Gözlerin yeni elife Ellerinden mısralar dökülür Kıvrım kıvrım Duruşundan gün doğar çifter çifter Ser...', ARRAY['Türk Edebiyatı','Şiir','Orhon Murat Arıburnu']::text[], 8.5, '{"poet":"Orhon Murat Arıburnu","poet_slug":"orhon-murat-ariburnu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yali-guzeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Kere İki', 'i-ki-kere-i-ki-orhon-murat-ariburnu-j0gbl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevdimse seni sevmişim

Rüzgar olmuş peşin sıra esmişim

Yolumda izlerin var bilinmez

Gözümde nazların var görülmez.

Sevdimse seni sevmişim

Kırk haneli ağızlara düşmüşüm

Canım ciğerim

Hürriyetim, 

SEVDİMSE SENİ SEVMİŞİM', 'Sevdimse seni sevmişim Rüzgar olmuş peşin sıra esmişim Yolumda izlerin var bilinmez Gözümde nazların var görülmez. Sevdimse seni sevmişim Kı...', ARRAY['Türk Edebiyatı','Şiir','Orhon Murat Arıburnu']::text[], 8.5, '{"poet":"Orhon Murat Arıburnu","poet_slug":"orhon-murat-ariburnu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/iki-kere-iki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babandan Korkulur, Gelmezsin ki...', 'babandan-korkulur-gelmezsin-ki-orhon-murat-ariburnu-fxyek', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senin için neler yaparım neler

Kaşına gözüne ümitler

Dudaklarına ışıklar sürerim

Saçlarına çiçekler takarım

Seni gönlümce süsler, gözlerim

Kaf dağının ardındaki Hürriyetim

Sevgilim, edepsizim, şirretim

Senin için nelerimden geçmem

Hele bir gelsen

GELMEZSİN Kİ! ..', 'Senin için neler yaparım neler Kaşına gözüne ümitler Dudaklarına ışıklar sürerim Saçlarına çiçekler takarım Seni gönlümce süsler, gözlerim K...', ARRAY['Türk Edebiyatı','Şiir','Orhon Murat Arıburnu']::text[], 8.5, '{"poet":"Orhon Murat Arıburnu","poet_slug":"orhon-murat-ariburnu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/babandan-korkulur-gelmezsin-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimyasal Aşk', 'kimyasal-ask-faruk-gorgulu-e3xtz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir turlu cozemedigim üçlü formul gibisin

sulfirik aside döndurur gidisin

atomlarimi parcaladi ''''seni seviyorum'''' deyisin

cabuk gel sevgilim oksitlendi yuregim.

feda olsun sana butun elektronlarim

ne olur seninle ionik bag kuralim

kabul etmezsen elektronlarimi alirim

dayanamam belki radyasyon dagitirim', 'bir turlu cozemedigim üçlü formul gibisin sulfirik aside döndurur gidisin atomlarimi parcaladi ''''seni seviyorum'''' deyisin cabuk gel sevgilim...', ARRAY['Türk Edebiyatı','Şiir','Faruk Görgülü']::text[], 8.5, '{"poet":"Faruk Görgülü","poet_slug":"faruk-gorgulu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kimyasal-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denizkızı Handan''ın Karada Bilenmesi', 'denizkizi-handan-in-karada-bilenmesi-perihan-magden-7urfq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çizgilerle gidiyorum bu gece, 

çizgilerle geliyorum

Bir balık göz oluyor, 

sinsi sinsi sırıtıyor bir diğeri

Bir el şahlanıyor yanıbaşımızda

Kan kesmiş diğeri, rengi: 

yeşil çarpsın - böğürtlen rengi

Bir çizgi yana kayıyor, kıskaç çamur yalan dolan

Sağ gözüm güvenme sol gözüme

Handan, ne var ne oluyor

Yamacımdan kayıyorsun yerlere

Niye be anam, şuracıkta beş kardeşiz

Beşi de bir, beşi de bir, beş kardeşin beşi de bir

Handan, sana diyorum - baksana gözüme

İnanma hiç; film onlar, roman, resimli roman

Ekmek çarpsın araba çarpsın tır çarpsın

Handan n''olursun, birazcık üzülme

Kuyruğunu kesmeliyiz bak önce

Şu resimli yalanları yırtmalıyız

Yürümeyi öğrenmelisin yavaştan

Önce trabzanlara tutun şu kuş elinle

Gözlerin, bebeklerin en bebek mavisi

Saç saçabildiğin kadar saçlarından kuzgunu

Adımlar, ilk başta acıtırlar inan

Kendi açtığı yaraya şehvetle katlanır insan

Yeter ki o bokçuvalları dikilmesinler önümüze

Neyse ne, cengaverler gibi yanındayım ben

At o ilk adımı, dayan omzuma

Yürümek soluk almaya benzer

bir başladı mı duramaz hiçbir Handan.', 'Çizgilerle gidiyorum bu gece,  çizgilerle geliyorum Bir balık göz oluyor,  sinsi sinsi sırıtıyor bir diğeri Bir el şahlanıyor yanıbaşımızda ...', ARRAY['Türk Edebiyatı','Şiir','Perihan Mağden']::text[], 8.5, '{"poet":"Perihan Mağden","poet_slug":"perihan-magden","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/denizkizi-handan-in-karada-bilenmesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçtığım İyi Aile Evleridir', 'kactigim-i-yi-aile-evleridir-perihan-magden-3c0zi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kahve fincanındaki okyanuslarda yitik gemiyim

Sancak direğimde ölü bir kedinin sırıtkan gözleri

Ahçıbaşı, tayfa, kaptan; korkarım tek yolcu benim

Seyir defterimde uğramam gereken limanlar

- Hoşçakal artık gitmeliyim

Beynimde çamaşır iplerinin mandallaşmış ağırlığı

Kaçtığım iyi aile evleridir

Beyaz masa örtülerinde gülüyor lekeler

Bilmemkaçıncı çorbanın boğan sıcaklığı

- Elinize sağlık, çok lezzetli

Kezzap yeşili tanımadık gözler

Trenle kaçıyorum hiç gitmediğim Hong Kong''tan

Yürüyen camda gördüğüm, bir gece ansızın duyduğum

Allı morlu bir hasret türküsü gibi uzuyor eller

- Acısından koyma mideme dokunuyor

Öldürülen birmilyonsekizinci kızılderili gibi ağlama kapımda

Paspasın altında anahtarı ellerimin

Sana yazmıyorum sana yazdığım mektubu

Satırlar acıyı dokuyor kağıdın beyazına

- Gözlüğümü versene iyi göremiyorum

Telefon sarısını yürütmüşler cebimden

Yarım kaldı mutluluk tablosu

Biliyorum sabah sabah boyamak zor denizi

Üç dörtlük sırıtıyor, dişlerinde gözleri

- Çok sıcak burası, gölgeye geçelim

Karasularımda ak bir balina

İpe dizmeliyim tüm mavileri

Darağacına çekip boğuyorum güneşi

Kanayan ellerim, üşüyen benim

- Kar yağsın avuçlarım ağlıyor.', 'Kahve fincanındaki okyanuslarda yitik gemiyim Sancak direğimde ölü bir kedinin sırıtkan gözleri Ahçıbaşı, tayfa, kaptan; korkarım tek yolcu ...', ARRAY['Türk Edebiyatı','Şiir','Perihan Mağden']::text[], 8.5, '{"poet":"Perihan Mağden","poet_slug":"perihan-magden","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kactigim-iyi-aile-evleridir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sınavda', 'sinavda-faruk-gorgulu-rrpph', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ağlasam sesimi duyarmisiniz sınavlarda

dokunabilirmisiniz kagidima kaleminizle

bilemezdim sorularin bu kadar kazik, 

yanitlarinin bilinmez oldugunu

sınava girmeden once

bir yol var gorebiliyorum

sorularin yanitlerinin bulmak kolay

bir hayli yaklasiyorum

tam kopyayi çekmeye baslarken, 

hocaya yakalaniyorum', 'ağlasam sesimi duyarmisiniz sınavlarda dokunabilirmisiniz kagidima kaleminizle bilemezdim sorularin bu kadar kazik,  yanitlarinin bilinmez o...', ARRAY['Türk Edebiyatı','Şiir','Faruk Görgülü']::text[], 8.5, '{"poet":"Faruk Görgülü","poet_slug":"faruk-gorgulu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sinavda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soru Çiçeği', 'soru-cicegi-perihan-magden-wczxc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biliyorum, senin görevlerin var

Bayram sabahlarını başlatmak görevin

Çocukları sallamak sevgi salıncağında, 

Yürek bağlarına salıvermek

Biliyorum, senin görevlerin var

Sıcaklar örüyorsun ellerinde, 

Yanarmış ellerin, bulanırmış gönlün

Biliyorum senin görevlerin var

Fırıldakların tahtasını bulmalısın ormanda

Karşıki dağın ardında balon şişirmelisin

İyilik türküleri belletmelisin dünyaya

Çocuklar kıkır kıkır gülebilmeli

Biliyorum, senin görevlerin var

Bi dolu kaynar su dökünüversem, 

Ansızın bulutlar inse gözlerime

Sorsam yeniden ve çok istesem

Benimle köşebaşına gelir misin?', 'Biliyorum, senin görevlerin var Bayram sabahlarını başlatmak görevin Çocukları sallamak sevgi salıncağında,  Yürek bağlarına salıvermek Bili...', ARRAY['Türk Edebiyatı','Şiir','Perihan Mağden']::text[], 8.5, '{"poet":"Perihan Mağden","poet_slug":"perihan-magden","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/soru-cicegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Manolyalı Ev', 'manolyali-ev-adil-i-zci-q7emi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'H. Ergülen''e

Nasıl bulabilirim, neler ve kimlerdendir

Yollarda bazı günler öyle durup

Bir şey var, derin bakış istiyor

-Bundan belki; sessizce eskiyorum ben de-

Manolyalı ev: Derin bakış istiyor: 

Kimler, hangi zamandır görünmeden hiç

İçe dönük bahçe, alt kat; günün çoğu

Hepsi bir büyü üzre, avuç sıcaklığında

Pencere, stor masa, onca kağıt, kalemler

Ve fincanlarla orada uzun süre

İnsansız da aynı; ruh hep deviniyor...

Üst kat, yağmurun ve her şeyin beklendiği

Düşlük! Ve dinlerken geçilen uykular için

Gök ve deniz için! Haziranlar, balkondan

Manolyalar için, ayışığındaki ten gibi

Ve ten gibi koka koka; dokunulmaz

Koklanmaz bile; periler gibi narin

Uykuda çarpan düşünce gibi. Gök açılıyor

İçindeki güzelin rüzgarı dağıldıkça

Bu düşten başkasına silkinirim: 

Eğilmişsin, yüzünü koklatmak üzre...

Yollardayım, gece yağmur gelip geçmiş

Gök açık ve deniz yakın, lacivert

Ama soğuk ruhumuza kadar incecik ki

Haziranlar, manolyalı ev; kışa hazırlık!', 'H. Ergülen''e Nasıl bulabilirim, neler ve kimlerdendir Yollarda bazı günler öyle durup Bir şey var, derin bakış istiyor -Bundan belki; sessiz...', ARRAY['Türk Edebiyatı','Şiir','Adil İzci']::text[], 8.5, '{"poet":"Adil İzci","poet_slug":"adil-i-zci","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/manolyali-ev-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ege Boydan Boya Mavi', 'ege-boydan-boya-mavi-elif-su-alkan-isiyo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ege boydan boya mavi

Ayvalık yolları

Zeytinlikler incir ağaçları

Çamlık Koyu Çay Bahçesi

Ve durgun deniz

Kıyıda doğduğum hastane

Senin büyüdüğün ev

Yanıbaşından geçtim Ayvalık''ın

Şeytan Sofrası''nı gördüm uzaktan

Karanlıkta belli belirsizdi yollar

Eski Rum evleri uykuda

Rıhtımda balıkçılar susmuş

Kedilerin karnı tok

Yıldızların ortasında anneannemizin yüzü

Sarımsaklı Plajını anımsar mısın Tozan? 

Beyaz dutun tadı damağımızda

Tenimiz tütün gibi kararıncaya dek

Yuvarlanırdık kumda

Ne inceydin ne güzeldin

Baktıkça kıskanırdım seni

Dalgaları kucaklardım telaşla

Bağırırdım Bırakma Ellerimi

Nerde çocukluğumuzun yaz akşamları

Neden böyle ağlar olduk

En doğal karanlığından gecenin

Neden korkar olduk Tozan', 'Ege boydan boya mavi Ayvalık yolları Zeytinlikler incir ağaçları Çamlık Koyu Çay Bahçesi Ve durgun deniz Kıyıda doğduğum hastane Senin büyüd...', ARRAY['Türk Edebiyatı','Şiir','Elif Su Alkan']::text[], 8.5, '{"poet":"Elif Su Alkan","poet_slug":"elif-su-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ege-boydan-boya-mavi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerimi Kapatsam', 'gozlerimi-kapatsam-cengiz-bektas-efb1y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gözlerimi kapatsam

cenneti düşünürüm

denizliyi görürüm

haney evleri

bahçeleri bağları

elmayı narı

ak kara dut

erik

kavakları ya kavakları

ak toprak kokusu duvarın

içime çekerdim

nereden anımsadım şimdi

kapatsam gözlerimi

cenneti

denizliyi görürüm

arıkları ya arıkları

içinde çocukluğum yalnayak

kumruları duyarım

ağustosböceklerini

karınca katarları

horozları ya horozları

nereden anımsadım şimdi

gözlerinizi kapatsanız

cenneti düşünseniz

çocukluğumun denizlisini

görmediniz ki

göremezsiniz', 'gözlerimi kapatsam cenneti düşünürüm denizliyi görürüm haney evleri bahçeleri bağları elmayı narı ak kara dut erik kavakları ya kavakları ak...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Bektaş']::text[], 8.5, '{"poet":"Cengiz Bektaş","poet_slug":"cengiz-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gozlerimi-kapatsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tanem', 'bir-tanem-faruk-gorgulu-2gdgk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sen giderken birtanem

butun kuslar susacak

cicekler renk degistirip

belki hepsi solacak

gonlum huzun icinde

her an seni soracak

ben bu kalbi sana verdim

yalniz sende kalacak', 'sen giderken birtanem butun kuslar susacak cicekler renk degistirip belki hepsi solacak gonlum huzun icinde her an seni soracak ben bu kalbi...', ARRAY['Türk Edebiyatı','Şiir','Faruk Görgülü']::text[], 8.5, '{"poet":"Faruk Görgülü","poet_slug":"faruk-gorgulu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-tanem-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'I Love You', 'i-love-you-faruk-gorgulu-7l4ko', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'look at your eyes

onlar very nice

bir kerecik look at me

ondan sonra forget me

if you beni sevmessen

hayat olur bana kuyu

but genede i love you', 'look at your eyes onlar very nice bir kerecik look at me ondan sonra forget me if you beni sevmessen hayat olur bana kuyu but genede i love ...', ARRAY['Türk Edebiyatı','Şiir','Faruk Görgülü']::text[], 8.5, '{"poet":"Faruk Görgülü","poet_slug":"faruk-gorgulu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/i-love-you-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözler', 'gozler-faruk-gorgulu-q087f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir gun gozlerin dolarsa

eger yaninda degilsem

gozlerinin doldugu yerdeyim! 

senin goz yaslarin olmak isterdim

gozlerinde dogup, 

yanaklarinda yasayip

dudaklarinda ölmek icin

sevmek mutluluksa eger

ben seninle mutluyum

ayrilmak olmekse

ben zaten öluyum

gozler vardir sozleri anlatir

sozler vardirgozleri aglatir

goz yaslari acinin sessiz sozleridir

hayat yasamaya deger

yasatani varsa eger', 'bir gun gozlerin dolarsa eger yaninda degilsem gozlerinin doldugu yerdeyim!  senin goz yaslarin olmak isterdim gozlerinde dogup,  yanaklarin...', ARRAY['Türk Edebiyatı','Şiir','Faruk Görgülü']::text[], 8.5, '{"poet":"Faruk Görgülü","poet_slug":"faruk-gorgulu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozler-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dişimin Kovuğu', 'disimin-kovugu-reha-basogul-tq084', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne kadar garip! 

bir fındık attım ağzıma

girdi dişimin kovuğuna

dilim döndü yaklaştı ona

ama inatçı bizimki

yanaştırmadı hiç kenarına

ufak olmasına ufaksın anladım da

beni kaç saattir deli ettin

kaç kürdanı da geri çevirdin

sen ne çekilmez birşeymişsin

sayende 

kaç defa volta attım

kaç bardak su içtim bilirmisin

çaresi de yokmuş

sen isteyince çekip gidenlerdenmişsin

bana ders oldu

söz bundan sonra

dişimin kovuğunu dolduracaksa biri

ya da geldiğin fındık kabuğunu

ben yemin ettim

en az senin kadar ilgilenmeli

yoksa başa bela

akla ziyan 

dili hiç sorma

o hepten perişan

valla olsaydım senin kadar

inan gözümden kaçmazdı

şu bizim doğayı kirleten adamlar

gör bak o zaman

nasıl çıldırttırdım onları sabaha kadar...', 'Ne kadar garip!  bir fındık attım ağzıma girdi dişimin kovuğuna dilim döndü yaklaştı ona ama inatçı bizimki yanaştırmadı hiç kenarına ufak o...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/disimin-kovugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskisi Gibi', 'eskisi-gibi-sabahattin-ali-bn4fw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seneler sürer her günüm, 

Yalnız gitmekten yorgunum; 

Zannetme sana dargınım, 

Ben gene sana vurgunum.

Başkalarına gülsem de, 

Senden uzakta kalsam da, 

Sevmediğini bilsem de

Ben gene sanavurgunum.

Dağları aşınca başım, 

Geri kaldı her yoldaşım, 

Gerl sevgilim, gel kardaşım, 

Ben gene sana vurgunum.

Gönlüm seninkine yardı, 

Aynı şeyleri duyardı; 

Ayaklarımız uyardı...

Ben gene sana vurgunum.', 'Seneler sürer her günüm,  Yalnız gitmekten yorgunum;  Zannetme sana dargınım,  Ben gene sana vurgunum. Başkalarına gülsem de,  Senden uzakta...', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Ali']::text[], 8.5, '{"poet":"Sabahattin Ali","poet_slug":"sabahattin-ali","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/eskisi-gibi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırlayan Delikanlılar Tangosu F', 'hatirlayan-delikanlilar-tangosu-f-kucuk-i-skender-2oahg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'akşamın

sonrası baktığıyla suçlandığı yere kurayazdı yuvasını

yine de yazgısı ertelenmiş tembel kalp de

bilir hatalarını hatırlayan delikanlıların girdaplarıyla

gidip geldiği dolaplarda düşürülmüştür çocuk çığlıkları

ile konuşan bir adamın yeminidir çünkü duyduğu

hisler ne anlatabilir ki ağzını midye kesen ü harfi

bilakis en hüzünlü bataklıktır, mesela pişmanlık huyları

inildiğinde içeri ve çıkıldığında fazla dışarı

o kanlı baraka: aşağıya doğruki tepeler

in doruklarına uzanan barut tarlaları

özlemişlerdir korkuluklarını ve konuklarını

lacivert matem giysileri içersindeki akşamın

sonrası

			akşamın

sonrası akladığıyla suçlandığı yere ağlayayazdı acısını

yine de ümidi ertelenmiş tembel kalp de

bilir hatalarını hazırlayan delikanlıların gizli arzularıyla

gidip geldiği vakumlarda düşürülmüştür eşkıya çığlıkları

ve eşkıya çığlığı ki

aklar bir ölü gibi haklı macerasını', 'akşamın sonrası baktığıyla suçlandığı yere kurayazdı yuvasını yine de yazgısı ertelenmiş tembel kalp de bilir hatalarını hatırlayan delikanl...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hatirlayan-delikanlilar-tangosu-f-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Co', 'co-kucuk-i-skender-fgyby', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hiddetin asit tekamülünde istikrarsız

yağmurun ayağı altında yürüyen firuze kız

geriye dönüp bakamayacak kadar çok o

Belli kentin sokaklarında H'' için kaldı

sudan neyi dilenirsen dilen sensin işte

dönüşte otelde oda bulamazsın. bulma zaten

saten. saten diyordum, satendir bazen elem', 'Hiddetin asit tekamülünde istikrarsız yağmurun ayağı altında yürüyen firuze kız geriye dönüp bakamayacak kadar çok o Belli kentin sokakların...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/co-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmeden Önce', 'gitmeden-once-orhan-alkaya-21boo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'erken kalkın hanımlar, beyler

vaktidir, uzatmayın boş yere

kaç kere yazıldı kimbilir, karnaval

yeri değildir dünya, ne de sevecen

bir yatak odası. bir bok olacağı yok

kavramlar ve kavimler eritti çoktan

bu manzarayı. yetmezliğinizle avunun

siftinip gittiniz bir biçilmiş yol boyu

gitgide gidilemez bir yerden mi gidemiyorsunuz

pek mi hoşnutsunuz ikiyi hayda! aşmış yüzlerinizden

zekanızın altında bir getto mu kurdunuz yoksa

bilinemezleriniz mi ürkütüyor yoksa sizi

ölüm! sandığınız kadar soğuk mu? saklandığınız

her yerde birkaç kupür mü gizlenir

son nefesinde kendisini özleyen kimdir

neden uzun ölür her anne

ahmaklık bakaloryasını uzun eşek geçmek

aşkla otuzbir çekmek, ot içmek, ot biçmek

çok zamandır aşağılanıyor oysa. fevkalade

sağlıklı bir yasayla yönetiliyor hayatlarımız

: altta ve güneyde kalanın canı çıkarsa çıksın

cebine üç beş banknot sıkışmış kim ayırt eder

kuzeyi güneyi güneşi ve batışı

uzlaşalım o vakıt: çok yaşa zararsızlık

düzayak hayatlardan kime ne; zerzevatçıyı

ve sabun satıcısını haneye çağırın, oldu işte

üst katlardan halı silkelemek tehlikesiz

ve serbesttir oysa. mobilyalardan ve köpüklü

deterjanlardan ve su hazneli süpürgelerden ve kirtim

kirtleri yasaklayan özel harekat şubesinden kurtulmuş

bir halınız varsa eğer; hanımlar, beyler, bekleyin

aşağıdan yukarıya doğru devrim yapsınlar

yukarıdan aşağıya ırzına geçin devrimin

olmadı çekip gidin; ısrarla söylemiyorum ama

pek bir canınız çekerse: siktirip öyle gidin

bir bok yok hanımlar, beyler ve itiraf edenler

iki yüz kişi iki buçuk milyar dünyalıdan zengin

bir haftalık karıyla Microsoft''un, açlık

unutulup gider Malthus''ün geometrisine rağmen

El Debba''da akbaba gezmez aç kızların peşinde

kir pas içinde tiner çocukları bir hamam görse

akça pakça pek de güzel olurlar sanki

zannedin ki bir hamam var onlar için ve iki

kere iki etmektedir iki! gelip de görün ki

kuvarkını yitirmiş lepton kadar compressed işte

el yazması tadını ve zihin olanca akışını gömüp

manyetoları ve kıçınızı büyüten high technology

ah! gitmezseniz eğer binip günahsız atlarınıza

bu ısrar ruhumuzu yakacak, dikkatimizi. kimliğimizi

ateşe vermeden çok önce kendi kıblemizde

hayatımızı; pakça gerdanlı, kruvaze -göbekgizler-

kostümlü, manasız bakışlı, beyazlatılmış

ahlaklarıyla veled-i akçaları, kahkahalarıyla

doymamış dimağları ve yaprak sarma kuramlarıyla

başbaşa ve hükümsüz bırakmak acıtıyor canımı

borsaya sürülmüş şu piçkuruları, şu nimet budalaları

bir dünyalı zaafıyla ve kanatılmamış dudaklarıyla

canımı acıtıyor ve erteliyorum birkaç gün için gidişimi

fazla kalmış olmak ayıptır, vaktı ıskaladım, biliyorum

inliyorum gidebilmek için, öf! kaç düğüm fazla attım

pişmedim hala, büyüyemedim kızım, annem ve baba

- bir çocuğu olmak hele, yeniden üretmektir

ıcığıyla bilinen yeryüzü yaşamasını ve kışkırtır, 

soyundan geleni saklayıp koruma telaşını. - haydi

hop! toparla kendini hep güzel kadınların sevgilisi

arkada bırakacağı gözünü yaşarken derlemiş Adem

söyle k''ale alınmasa da sözünü, sana ne ala: 

gitmeden önce söylemek istediğim birkaç söz var

ve keyifle kıracağım birkaç burun kemiği, hala', 'erken kalkın hanımlar, beyler vaktidir, uzatmayın boş yere kaç kere yazıldı kimbilir, karnaval yeri değildir dünya, ne de sevecen bir yatak ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Alkaya']::text[], 8.5, '{"poet":"Orhan Alkaya","poet_slug":"orhan-alkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/gitmeden-once-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Temmuz Külleri', 'temmuz-kulleri-kucuk-i-skender-e3uhc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '(bir) : 

''üç şehzadenin yolları

ayrıldı böylece''

dedi kristalleşen yağmurun altındaki akrep.

kim bilir, kanı devşirebilir miydi geride kalan

tahrip gücü yüksek casus, 

ya da katlanabilir miydi ölüm

parmakuçlarıyla yaklaştığı sükseli surete.

(iki) : 

''üç şehzadenin yolları

ayrıldı böylece''

dedi film müziklerine geçen gece.

iki kardeşin yanından ayrılan öbür kardeş nerede...

kim bilir, tenlerden akan ruhun arkasına sığınan

yalnızlığı etkili, korkunç sedyede; 

kıstaslarıyla kokladı cismi

rahmine kılıç adı koydu

''gelmeyeceğim peşinizden''

diye bağırdı üçüncü şehzade

''gidin ılık oyuklardaki uğultulu mesafeye...''

iki miydiler üç mü

ikiye üç suç mu

kararsın patlak dudaklarıyla masala ait kraliçe! 

(üç) : 

''üç şehzadenin yolları

ayrıldı böylece''

biliyorlardı, başkaları buna benzer şeyler yazmıştı

kalbe karşı gelmişlerdi -kafiye olsun-

elden ele dövme geçirmişlerdi / güne gündüz gelin düşmüştü

öpüştüler

öpüşmelerine kuşlar hücum etti

oradan geçiyordum

inanın yalnızca dikkatimi çekti

dikkatim yere düştü / yer, düşüyle barışıktı

şimdi bilmiyorum

gerçekte hangisi hangisine aşıktı

ah, üçünün gizli gizli sevişmelerine sığınan

o, kimin kaldırılacağı belirsiz sedye: 

''üç şehzadenin yolları

ayrıldı böylece''

üçünü de tanımam

üçün birinden sözetmem kimseye!', '(bir) :  ''üç şehzadenin yolları ayrıldı böylece'' dedi kristalleşen yağmurun altındaki akrep. kim bilir, kanı devşirebilir miydi geride kalan...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/temmuz-kulleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Çocuk Yılında I', 'dunya-cocuk-yilinda-i-behcet-necatigil-zg5kb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bütün çocuklar

Yokluk bilmesinler

Et, şeker, süt bulsunlar

Giyimli, tok ve rahat', 'Bütün çocuklar Yokluk bilmesinler Et, şeker, süt bulsunlar Giyimli, tok ve rahat...', ARRAY['Türk Edebiyatı','Şiir','Behçet Necatigil']::text[], 8.5, '{"poet":"Behçet Necatigil","poet_slug":"behcet-necatigil","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dunya-cocuk-yilinda-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Çocuk Yılında II', 'dunya-cocuk-yilinda-ii-behcet-necatigil-cunsu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her çocuk bir nur topudur, 

Paçavralar içine bile düşse

Bir nur topudur.

Dar çağlara gelmese, 

Değmese hoyrat ayaklar, 

Ç
..........
..........', 'Her çocuk bir nur topudur,  Paçavralar içine bile düşse Bir nur topudur. Dar çağlara gelmese,  Değmese hoyrat ayaklar,  Ç .......... ..........', ARRAY['Türk Edebiyatı','Şiir','Behçet Necatigil']::text[], 8.5, '{"poet":"Behçet Necatigil","poet_slug":"behcet-necatigil","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dunya-cocuk-yilinda-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Temmuz Tikleri', 'temmuz-tikleri-behcet-necatigil-5k9pn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yanda, altta, üsttekiler

Yirmi yedi daire apartman

Yatmış sanki ölüm uykusuna

Donmuş zaman.

Çıt yok

Eriyen camlardan

Kavrulmuş perdelerde

En ufak bir kıpırtı.

Ne sokaktan geçen taşıt, 

Su saatlerinde tıkırtı - -

Ne kapı önündeki ağaçta

Ku
..........
..........', 'Yanda, altta, üsttekiler Yirmi yedi daire apartman Yatmış sanki ölüm uykusuna Donmuş zaman. Çıt yok Eriyen camlardan Kavrulmuş perdelerde En...', ARRAY['Türk Edebiyatı','Şiir','Behçet Necatigil']::text[], 8.5, '{"poet":"Behçet Necatigil","poet_slug":"behcet-necatigil","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/temmuz-tikleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teleks', 'teleks-behcet-necatigil-skulu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biten yokuşta

Başlayan düzlük, 

Bellekte kalanlar

Unutulmuş olsa', 'Biten yokuşta Başlayan düzlük,  Bellekte kalanlar Unutulmuş olsa...', ARRAY['Türk Edebiyatı','Şiir','Behçet Necatigil']::text[], 8.5, '{"poet":"Behçet Necatigil","poet_slug":"behcet-necatigil","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/teleks-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzerine', 'uzerine-behcet-necatigil-cxmld', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yazgı üzerine çok şey yazıldı

Kağıt üzerine yazıldı.

Sarkan gerdan, kırı
..........
..........', 'Yazgı üzerine çok şey yazıldı Kağıt üzerine yazıldı. Sarkan gerdan, kırı .......... .............', ARRAY['Türk Edebiyatı','Şiir','Behçet Necatigil']::text[], 8.5, '{"poet":"Behçet Necatigil","poet_slug":"behcet-necatigil","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/uzerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşürken', 'usurken-behcet-necatigil-xmr1a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Birini düşünmek

Ne yapar şimdi

Camdan bakarak

Savrulan karları düşü
..........
..........', 'Birini düşünmek Ne yapar şimdi Camdan bakarak Savrulan karları düşü .......... .............', ARRAY['Türk Edebiyatı','Şiir','Behçet Necatigil']::text[], 8.5, '{"poet":"Behçet Necatigil","poet_slug":"behcet-necatigil","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/usurken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su', 'su-ceren-bagislar-tfh65', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'köprüyü yıkan

bir avuç su...

derine geri döndü ve...

adressiz adadan, sıcak

topraktan, anadilsiz kıtadan

geldiği düşünülmüştü.

köprüyü yıktı

bir avuç su...

yırtıldı, kasvetli entarisi

günebakanların.

yitip dalgayı soyundular

	denize...

geldi, ıslattı, gitti.

derine geri dönüldü ve...

lodos kurudu serçelerin üzerinde; 

dalgayı çalarken deli fişek poyraz

sardunyanın yaprağından düştüm

günlerin körpe toprağına.

köprü yıkıldı

celladı bir avuç su...

derini tanıdık...', 'köprüyü yıkan bir avuç su... derine geri döndü ve... adressiz adadan, sıcak topraktan, anadilsiz kıtadan geldiği düşünülmüştü. köprüyü yıktı...', ARRAY['Türk Edebiyatı','Şiir','Ceren Bağışlar']::text[], 8.5, '{"poet":"Ceren Bağışlar","poet_slug":"ceren-bagislar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/su-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazar', 'hazar-emel-i-rtem-yur72', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'beni kapat, adım Hazar

iç denizim ben

beni saymaz atlaslar

nedzinde gölüm ben

dinip rüzgarı yelpazesinden

mermerle kaplanıp...

sonra -künfekan- işaretler

karanlığa yazılıp...

dört milyar yıl önce başlayıp ölmeye

hala ölüp ölüp her yeni nefesle

ikizini yutan günahkarım ben

ama ben de seslerin içinden geçeceğim

kesişen zamanlar kucağımda saflaşıp...

her safta bir harfin okunuşu göverip...

çürüyen küre olup gülüş böylece...

-herkesin beklediği infilak buydu işte

deyip cennetinden geçeceğim

benim denizimi aç burkamı aç burkamı

içindeki haneler takatsız göreceksin

Hazar olup aktığımı dünyadan

ve bir kerpiçten inmeye başlayıp

uzak zamanların ayıp, son arzusuna

bozulmuş tövbelerle dönüp duruyor sema

-evet! elveda, Künfekan - canım acıyor-

ne yapacaksın beni gömmekten başka

zira yanar, yanacak ruhun bu ölü başkalıkta', 'beni kapat, adım Hazar iç denizim ben beni saymaz atlaslar nedzinde gölüm ben dinip rüzgarı yelpazesinden mermerle kaplanıp... sonra -künfek...', ARRAY['Türk Edebiyatı','Şiir','Emel İrtem']::text[], 8.5, '{"poet":"Emel İrtem","poet_slug":"emel-i-rtem","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/hazar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cayan Yeller Şiiri', 'cayan-yeller-siiri-ender-ozbay-34zym', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir rüzgar gelip

penceremde oyalandı bir zaman...

ıslığı yoktu...

kahve dediğin acı olmalı, 

çiçek dediğin şöyle iy''ce kokmalı

çocuk dediğin koşuşup sıçramalı

	diye söylenip

	vardım yanına: 

sen bir rüzgarsın oysa! 

kumların tanesi neden sayılı? ..

niçin yapraklar ağaçta hala

	bu sonbahar gününde? ..

ya şimdi güller

güllüğünden cayarsa, 

ana analığından; 

ferhad cayarsa

	ferhad''lığından şimdi? ! ..

nic''olur dünya! 

		dedim

gözlerimden taşan

uçurumsu korkuyla.

tınmadı.

işte yüzüm

işte sabah...

yalanım varsa! ..

ender özbay

(Varlık, kasım 2002, sayı 1142)', 'bir rüzgar gelip penceremde oyalandı bir zaman... ıslığı yoktu... kahve dediğin acı olmalı,  çiçek dediğin şöyle iy''ce kokmalı çocuk dediğin...', ARRAY['Türk Edebiyatı','Şiir','Ender Özbay']::text[], 8.5, '{"poet":"Ender Özbay","poet_slug":"ender-ozbay","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/cayan-yeller-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çivi', 'civi-deniz-durukan-iv6w2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne sperm izi, ne doğmamış çocuk korkusu

çürük bir elma tadı dudaklarımda

artık korkmuyorum ayna

kızıl bir pencereden bakıyorum hayata

bir cinayeti paylaşıyoruz, ürkek

kırık dökük karanlığı kestikçe

çoğalıyoruz dar alanda

geniş aşklar yaşıyoruz

şimdi demiri hiç atılmamış

kırmızı sandallar geçiyor içimizden

alçalıp yükselen bir akşamda

sözlerin

boşalıyor ağzıma

bilindik suçlar işliyoruz

küf kokan odalarda

suç iyidir! 

kirli bir delikten aktıkça

pıhtılaşan tırnak izidir, eskidir

ayna! gittikçe büyüyor içimdeki ölü

aşkın paslı bir çivi gibi

çiziyor yüzümü.', 'Ne sperm izi, ne doğmamış çocuk korkusu çürük bir elma tadı dudaklarımda artık korkmuyorum ayna kızıl bir pencereden bakıyorum hayata bir ci...', ARRAY['Türk Edebiyatı','Şiir','Deniz Durukan']::text[], 8.5, '{"poet":"Deniz Durukan","poet_slug":"deniz-durukan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/civi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tuna Ötenel', 'tuna-otenel-halim-yazici-rs69u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'çiçekleri kokladığında kırmızı başlıklı kurt

sarı ten rengi mozaik kalbim sesim

çiğ tanesi mor ve buz/dan yapılan ışık rakkasım

sevişme vaktim mavi notam sevgilim

büyümektesin emzirdiğim sütüm

yazılan kar tadında sürgit bir ömrün.', 'çiçekleri kokladığında kırmızı başlıklı kurt sarı ten rengi mozaik kalbim sesim çiğ tanesi mor ve buz/dan yapılan ışık rakkasım sevişme vakt...', ARRAY['Türk Edebiyatı','Şiir','Halim Yazıcı']::text[], 8.5, '{"poet":"Halim Yazıcı","poet_slug":"halim-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/tuna-otenel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buluşma Hüznü', 'bulusma-huznu-huseyin-atabas-8k1nk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uçurumlar oyuyor yüreğime birileri

	eski bir testerenin paslı hüznüyle, 

üstüne yağmur çiseliyor çocukluğumun.

Ben mi? İncecik özenlerle durmadan

	güneşin doğuşunu işliyorum

kuşların konamadığı gök/yüzüne! ..

Korkularıma çiçek adları veriyorum, 

kalemin kağıtla buluştuğu o ilk ayrılıkta

sevebiliyorum elimin okşama hünerini.

Ömrüm dibine çöken zaman tortusu

	getirmese de bir daha geri

öptükçe ağzının ipekleşen servetini! 

Aşkın adı gülüşün oluyor arındıkça, 

yüzün ben tarlası, eteğinde dağçilekleri

ve bir sincap sevecenliği bakışlarında.

Ayın erken doğuşudur mahçupluğun: 

	güzdür ve değirmenler susuzdur, 

unum yok benim, güneşim paranoya! ..

Ele veriyor kadının biri içyüzünü, 

bir başkası ağlamamak için gülüyor: 

sonunda mağarayı buluyor kör yarasa.

Anlıyorum yine de tüm olup bitenleri, 

	''cep''im kapsama dışı

buluşma ihtimalim yanımdaysa! ..', 'Uçurumlar oyuyor yüreğime birileri 	eski bir testerenin paslı hüznüyle,  üstüne yağmur çiseliyor çocukluğumun. Ben mi? İncecik özenlerle dur...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Atabaş']::text[], 8.5, '{"poet":"Hüseyin Atabaş","poet_slug":"huseyin-atabas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bulusma-huznu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ebruli', 'ebruli-huseyin-yurttas-5bimx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sen geçtin

duruldu şiirim

şimdi hasretin ince yeli

ölümseyen yüzünde o solgun

ırmağın

sönmüş kır ateşleri

savrulan kül, neyi söyler

zaman, kırgın düşlerle yaralı

aşkın kayıp baharında

kış izleri

önünden geçtiğimiz aynalar

gizlese de karanlığımızı

yollarımız karla kaplı

sessizlik sınır tanımıyor

mavi bir damar

usulca mora eğiliyor

sonra her şey ebruli', 'sen geçtin duruldu şiirim şimdi hasretin ince yeli ölümseyen yüzünde o solgun ırmağın sönmüş kır ateşleri savrulan kül, neyi söyler zaman, k...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Yurttaş']::text[], 8.5, '{"poet":"Hüseyin Yurttaş","poet_slug":"huseyin-yurttas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ebruli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buğu Banyosu', 'bugu-banyosu-lale-muldur-pmgb4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kırgızistan''da batık bir vadide

Men seni bela sandım.

Kalbimden uzakta çok uzakta bir kurt öldü.

Şarap kızılı bir lale sızıpdur şimdi orada farkında mısın? 

Geceyarısı batkıları ve al kanlar içinde ekşimden

öle budum. Yıllar ve yıllar var ki Bizansiyya''nın

tungasında erg
..........
..........', 'Kırgızistan''da batık bir vadide Men seni bela sandım. Kalbimden uzakta çok uzakta bir kurt öldü. Şarap kızılı bir lale sızıpdur şimdi orada ...', ARRAY['Türk Edebiyatı','Şiir','Lale Müldür']::text[], 8.5, '{"poet":"Lale Müldür","poet_slug":"lale-muldur","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bugu-banyosu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçek', 'cicek-zafer-ekin-karabay-ofmz1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ipatya''ya

toprağa değen su dokununca anlatır

elinde kalan mektubu, durula

gözlerini sakındığın yarına

çiçek sandığın kadar açacaktır

sorma mektubun huyu böyle, yoksa

kim benzetir harfleri, toprağa değen suya

ben benzetiyorum işte, bir de elini

dokununca mektubun ruhuma', 'ipatya''ya toprağa değen su dokununca anlatır elinde kalan mektubu, durula gözlerini sakındığın yarına çiçek sandığın kadar açacaktır sorma m...', ARRAY['Türk Edebiyatı','Şiir','Zafer Ekin Karabay']::text[], 8.5, '{"poet":"Zafer Ekin Karabay","poet_slug":"zafer-ekin-karabay","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/cicek-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Hayatı Anlat', 'bana-hayati-anlat-yusuf-alper-lnuyu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Upuzun zaman oldu kendimle

Konuşmadım

Başbaşa verip tartmadım hayatı

Yürüdüm mü koştum mu

Erik ağacının kışın çiçek açması

Kanlı bir gömleğin kuyuda eskimesi

İki yar arasında kaygan

Buzlu bir yol muymuş düşe kalka

Yorgun akşamları koynunda ağırlayan

Hayat bu yaşadım mı yordum mu

Genç şairin neden kendini boğduğunu

Üzüldüm yıllarca çok yıllarca üzüldüm

Göğekinler gibi kendini biçip gider

Yesenin Mayakovski Can Nilgün İlhami

Josef Silvia Kaan Soysa ve Zafer

Hangi fırtına orağı elinize verdi; biçti

Oysa Ece daha dün pirifani göçüp gitti

Enis çok yaşayacak, Beşir Fuad acısıyla

''Bir torba kemik kalıncaya kadar''

Ölüp dirilsek de her gün yeniden

Anka küllerimizden doğar

Anlat demeyin kendini öldürmeyi

Nasıl anlatılır bir düğüm karanfil boynunda

Sevgili balkonunda yağlı kurşunlar

Bir jiletin bilekte sınav vermesi

Nasıl anlatılır çakılan kuş betona

İnsan bazen uçurum başındadır

Kimi zaman ipin ucunda

Ama sonsuzdan gelip sonsuza gidişin

Bir virgülü olsun olmak varsa

Hayatın bağrındadır

Bana hayatı anlat birlikte yaşamayı', 'Upuzun zaman oldu kendimle Konuşmadım Başbaşa verip tartmadım hayatı Yürüdüm mü koştum mu Erik ağacının kışın çiçek açması Kanlı bir gömleği...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Alper']::text[], 8.5, '{"poet":"Yusuf Alper","poet_slug":"yusuf-alper","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bana-hayati-anlat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balta Limanı', 'balta-limani-seref-bilsel-xeh9g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zafer Ekin Karabay''a

Kalbini yiyerek büyüyor ay

soğuk, sırlı bir akşam

dargın bir göğü andırıyor ellerin

-ben ağzın olsam-

başının üstünden indir onları derim

Burada istenmiyorsun çocuk

kanlı bir kuş konmuş sesine

kızılağaçlardan terk...

senin yüzünden

Çıldır''da okula giden iki ırmak

		          donmuş...

Çok kırmızı elma yiyorlar burda

aklın, başının yüzüğü, yiyorlar

kalbin! göğsüne düşen bulut

durmadan bir şey yiyorlar burda

buluttur, yüzüğün içinden geçen

		          demiyorlar', 'Zafer Ekin Karabay''a Kalbini yiyerek büyüyor ay soğuk, sırlı bir akşam dargın bir göğü andırıyor ellerin -ben ağzın olsam- başının üstünden ...', ARRAY['Türk Edebiyatı','Şiir','Şeref Bilsel']::text[], 8.5, '{"poet":"Şeref Bilsel","poet_slug":"seref-bilsel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/balta-limani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığımı Dinliyorun Günlerdir', 'yalnizligimi-dinliyorun-gunlerdir-alim-vedat-suner-58pg3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yalnızlığımı dinliyorun günlerdir

hiç evlenmeyecek olan 

rahibeler gibi

manastıra kapanmış gibi

yeşillikler, dalga sesleri

ve

beni ben yapan

Yalnızlığımla...

10.06.2002 / P.tesi / Çınarcık', 'yalnızlığımı dinliyorun günlerdir hiç evlenmeyecek olan  rahibeler gibi manastıra kapanmış gibi yeşillikler, dalga sesleri ve beni ben yapan...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yalnizligimi-dinliyorun-gunlerdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gibiyim...', 'gibiyim-alim-vedat-suner-58dm5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çatlamış toprak üzerindeki

Dipsiz çukurlar gibiyim

Kurumaya yüz tutmuş

Gonca bir gül gibiyim

Sahile vuran

zorunlu bir dalga gibiyim

Ben Sensiz

Bir Hiç gibiyim...! ! !', 'Çatlamış toprak üzerindeki Dipsiz çukurlar gibiyim Kurumaya yüz tutmuş Gonca bir gül gibiyim Sahile vuran zorunlu bir dalga gibiyim Ben Sens...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gibiyim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzi Kaldı', 'i-zi-kaldi-alim-vedat-suner-xbslr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kimi Sevdiysem

Terketti beni gitti

Her aşkım bende

Unutulmaz izi kaldı

Kimi öptüysem

Hatıralarım etrafımı sardı

Her öpücükden zevk alsamda

Senin dudaklarının izi kaldı

Hangi kıza baksam

Seni hatırlatır bana

Unutmak istesemde

Unutamam

Gözlerinin izi kaldı..

11.06.2002 / Salı', 'Kimi Sevdiysem Terketti beni gitti Her aşkım bende Unutulmaz izi kaldı Kimi öptüysem Hatıralarım etrafımı sardı Her öpücükden zevk alsamda S...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/izi-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Aynı', 'hep-ayni-alim-vedat-suner-bc5hq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Denize vuran her dalga

Seni hatırlatır bana

Mekan belki farklı 

ama

Sesler hep aynı

Deniz kokusu aynı

Hele sevdiğim, 

Sensizliğin kokusu

Sensizliğin acısı

Hep

Ama hep aynı

10.06.2002 / Çınarcık / Beyaz Bahçe', 'Denize vuran her dalga Seni hatırlatır bana Mekan belki farklı  ama Sesler hep aynı Deniz kokusu aynı Hele sevdiğim,  Sensizliğin kokusu Sen...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hep-ayni-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüyorum', 'usuyorum-alim-vedat-suner-56u4f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Üşüyorum

Güneşde kavrulan bedenim yansa da

Ruhum üşüyor

Nedenini bilemediğim

Bilemeyeceğim...

Yalnızlığın soğuk rüzgarı vuruyor

Dost sandıklarım sırtımdan vuruyor...

Lanet olsun....

Dünya

Beni beslemeyecek kadar

Meşgul...

Ben Yalnızlığımda üşüyorum..! ! !', 'Üşüyorum Güneşde kavrulan bedenim yansa da Ruhum üşüyor Nedenini bilemediğim Bilemeyeceğim... Yalnızlığın soğuk rüzgarı vuruyor Dost sandıkl...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/usuyorum-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'sen-oyle-zannet', 'sen-oyle-zannet-reside-murat-oggjd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çoktan sonuna geldik

Yalanlarla ezildik

Aşktan yana ne varsa

Bak sıfırı tükettik

Canım sıkıldı

Büyü bozuldu

Bitti bu masal

Gönlüm yoruldu

Umrumda değil

İstersen isyan et

Ayrılık yokmuş

Sen öyle zannet

Senin gönül kapında

Yeteri kadar bekledim

Sınırı var sabrın da

Gerçeği hiç görmedin', 'Çoktan sonuna geldik Yalanlarla ezildik Aşktan yana ne varsa Bak sıfırı tükettik Canım sıkıldı Büyü bozuldu Bitti bu masal Gönlüm yoruldu Um...', ARRAY['Türk Edebiyatı','Şiir','Reşide Murat']::text[], 8.5, '{"poet":"Reşide Murat","poet_slug":"reside-murat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-oyle-zannet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybedenler', 'kaybedenler-sezen-aksu-wflez', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne hazin değil mi sevgilim hikayemiz

Malesef pek farkı yok diğerlerinden

İtiraz etmedik, itiraf etmedik

Kaybedenlerdendik diğerlerinden

Bari sen sonradan birazcık mutlu oldun mu

El yordamıyla iyi, kötü bir yol buldun mu

Hiç hayır dedik mi, soru sordun mu

Memnun değilim aldığım haberlerinden

Beni sorarsan şahitsiz suçlar gibi

Kınalı kanadı kırılmış kuşlar gibi

Yazı gelmeyen upuzun kışlar gibi

Unutulmuş diyarında düşünüyorum', 'Ne hazin değil mi sevgilim hikayemiz Malesef pek farkı yok diğerlerinden İtiraz etmedik, itiraf etmedik Kaybedenlerdendik diğerlerinden Bari...', ARRAY['Türk Edebiyatı','Şiir','Sezen Aksu']::text[], 8.5, '{"poet":"Sezen Aksu","poet_slug":"sezen-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kaybedenler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittiğin O Gün', 'gittigin-o-gun-tahir-paker-m9rfq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yollarıma engel, tuzak kurdular

Bu gönlümü yüz bin yerden vurdular

Düşmanlar halime gülüp durdular

Benden ayrılıp da gittiğin o gün

Sanki bu kalbime kurşun sıktılar

Sanki beni darağacına astılar

Sanki beni diri diri yaktılar

Benden ayrılıp da gittiğin o gün

Gündüzüm karardı, güneşim battı

Bir burukluk çöktü, gözyaşım aktı

Bir görsen halimi feleğim şaştı

Benden ayrılıp da gittiğin o gün', 'Yollarıma engel, tuzak kurdular Bu gönlümü yüz bin yerden vurdular Düşmanlar halime gülüp durdular Benden ayrılıp da gittiğin o gün Sanki bu...', ARRAY['Türk Edebiyatı','Şiir','Tahir Paker']::text[], 8.5, '{"poet":"Tahir Paker","poet_slug":"tahir-paker","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gittigin-o-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku ve Kokusu', 'korku-ve-kokusu-reha-basogul-e7p0s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'tenden kaçan kokular sır gibi dilimde

ahenklerin yarını bitmiş

dünü aramış korku treninde

bir sıratsa kokulardan korkmak

raydan çıkmışım ben

o acısı yolcu

sevinci kömür olmuş trende', 'tenden kaçan kokular sır gibi dilimde ahenklerin yarını bitmiş dünü aramış korku treninde bir sıratsa kokulardan korkmak raydan çıkmışım ben...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/korku-ve-kokusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İncikar', 'i-ncikar-adem-konan-lwrgf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tanrım ne çok yürüdümse ben değilim

kıyılar geride kaldı, ben diplerde

bir yer geliyor ki anlamsızlaşıyor bütün çabalar

tırnaklarınla kaz kaz bitmiyor bu sözler de

hiç bir şey görünmüyor...

Ne kaldı ki yürünecek; sadece bir ayartı

oysa çoktan varmalıydım varılacak olan yere

yaprakları kanatarak fark ettim çok içerdeyim

gördüm hala dönenler var kendi uçurumundan

hayret insan nasıl döner kendi uçurumundan! ? 

Öyle bir yüzlem’olurdum ben olsaydım

ya da bütün yakınmalar dinerdi

bir kelime bulsaydım bir kelime

renk değiştiren beyza

gibi akıtarak ruhumu kandillere...

Bu da bir başka yanılgı; beni herkes ben sanıyor

döküyorlar bana kuşkularını

ve herkesler durduğumla tanıyor

gizlice dönüştüğümün farkına varmıyorlar

bıraktıkları yerde sanıyorlar oysa çoktan ordayım...

Daha bir tutunuyorum kendime ve yalnızlığıma

kendi içimde bile ne kadar çok derinlere işlemişler beni

bir yığın söz altındayım, bir çok boş bakış içinde

kimseler fark etmiyor, adem sanıyorlar beni

sanki kaybolmuşum gibi bakıyorlar...

Sahiden de kaybolmuşum

elimde bir inci...', 'Tanrım ne çok yürüdümse ben değilim kıyılar geride kaldı, ben diplerde bir yer geliyor ki anlamsızlaşıyor bütün çabalar tırnaklarınla kaz ka...', ARRAY['Türk Edebiyatı','Şiir','Adem Konan']::text[], 8.5, '{"poet":"Adem Konan","poet_slug":"adem-konan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/incikar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykulu Nergis', 'uykulu-nergis-adem-konan-mqdxc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uyu...Gölde yüzen nilüfer gibi 

Bir kuşun kanadını okşuyor gibi uyu... 

Sanki rüyalardan gülümser gibi 

Bir çiçeği ruhunla kokluyor gibi uyu...

Açsın kapısını rüyalar sana 

Bakıp gülümsesin dünyalar sana 

Ümit var, sevinç var, sevgi var sana 

Yüreğinde bir mercan saklıyor gibi uyu...

Uykular dağıtsın kederlerini 

Sağaltsınlar inciyen yerlerini 

Uyuyorken açık tut ellerini 

Gökyüzünden bir müjde bekliyor gibi uyu... 

Uyu..Düşünceler seni yoruyor 

Ellerin anlamsız sözle doluyor 

Duygular birikip deniz oluyor 

Bir kıyıdan denize bakıyor gibi uyu... 

Çiçek solar bir gün kokusu kalır

Söz uçar geriye duygusu kalır

Gözün ne feri ne uykusu kalır

Şimdi duygular seni çekiyor gibi uyu...

Söz hançerdir konuştukça kanatır

Bir damla duygudan bir aşk yaratır

Sanırsın ki biri masal anlatır

Bir adam sana masal okuyor gibi uyu...

Ben yazarım ama bilmem kim okur

Gökyüzü kararsın, sen hayaller kur

Gökten inci inci dökülsün yağmur

Yağmurlar saçlarını yıkıyor gibi uyu...

Fısıltılı bir ses çağırsın seni

Söyle kim okşasın kim sarsın seni

Bir melek öperek uyarsın seni

Bir sevgi ırmağında akıyor gibi uyu...', 'Uyu...Gölde yüzen nilüfer gibi  Bir kuşun kanadını okşuyor gibi uyu...  Sanki rüyalardan gülümser gibi  Bir çiçeği ruhunla kokluyor gibi uyu...', ARRAY['Türk Edebiyatı','Şiir','Adem Konan']::text[], 8.5, '{"poet":"Adem Konan","poet_slug":"adem-konan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/uykulu-nergis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin İkiz Kardeş', 'gozlerin-i-kiz-kardes-ali-dost-aydin-9joc9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerin ikiz kardeş

               iki kara gül

dikenleri batıyor gözlerime

kararıyor dünyam

kara bir cennete 

        giriyorum

iki kara kapıdan

orada seni görüyorum

iki kara gül var elinde 

elime alıyorum

ellerinmiş meğerse 

biliyorum 

öldürecek beni 

elin elime

gözün gözüme 

değerse

Gözlerin ikiz kardeş

bir kara güneş

baktıkça 

yanıyor gözlerim

anlam veremiyorum 

parıltısına

hiç bir kara da 

hiç bir renkte 

göremiyorum

gözlerin kadar pırıldayanı 

 o zaman 

ap ayrı bir yere koyuyorum

ulaşılamaz bir yere

ve uzaktan bakabiliyorum 

ancak gözlerine 

Gözlerin ikiz kardeş 

iki kara kış 

iki kara bahar

iki kara yaz

yüreğimi saklıyorum derinlere 

belkide başka mevsimlere

saklıyorum.

biliyorum

haykıracağım 

bir gün sevdiğimi 

tüm evrene

26/11/2002', 'Gözlerin ikiz kardeş                iki kara gül dikenleri batıyor gözlerime kararıyor dünyam kara bir cennete          giriyorum iki kara k...', ARRAY['Türk Edebiyatı','Şiir','Ali Dost Aydın']::text[], 8.5, '{"poet":"Ali Dost Aydın","poet_slug":"ali-dost-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/gozlerin-ikiz-kardes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilirim Dönersin', 'bilirim-donersin-meltem-seyhan-ppfo0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bilirim seversin beni sen

Nasıl olsa bana dönersin

Bilirim geçici bir heves seninki

Başka türlüsü mümkün değil ki

Bilirim kıyamazsın sen bana

Bütün bu olanlar tatsız bir şaka

Belki de bir kabus geçen aramızda

Uyanınca bitecek nasıl olsa

Bilirim gerçek aşk solmaz

Bensiz senin huzurun olmaz

Ben beklerim istersen çok ya da az

Yeter ki sen bana bir tek satır yaz', 'Bilirim seversin beni sen Nasıl olsa bana dönersin Bilirim geçici bir heves seninki Başka türlüsü mümkün değil ki Bilirim kıyamazsın sen ban...', ARRAY['Türk Edebiyatı','Şiir','Meltem Seyhan']::text[], 8.5, '{"poet":"Meltem Seyhan","poet_slug":"meltem-seyhan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bilirim-donersin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet Ağrısı', 'gurbet-agrisi-baris-akm-nj352', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öyle bir yerindeyim Dünya''nın

Öyle bir yerinde yolların

Uçsuz bucaksız bir yerinde

Kaybolmuşluğun ötesinde

Bilmiyorum adı nedir sensizliğin

Adına ne denir yalnız uyanılan seherin

Bir sen kavgasındayım sonbaharın

Her uyanışta bin eksiliyor yapraklarım

Züğürt tesellisi bu biliyorum

Biliyorum da, böyle böyle avunuyorum

Yoksa ben rüzgarları çoktan kaçırmışım

Şimdilerde yaprak kıpırdatanlara tebessümüm

Sen hep bir hayaldin enikonu

Sen hayallerimdeki şiir olarak kalacaksın

Ne kalem görmüş, ne dökülmüş dudaktan

İnceden esen esmer bir sızısın

Adın yok, düşlerim odunsuz, kömürsüz, 

Perdelerim çöl misali çiçeksiz, gülsüz

Kapıldım gidiyorum bu gece de aysız

Yine mehtapsız kahbe gökyüzü

Ya çatır çatır bulutları

Ya da ben gibi bükük boynu

Bir yaprak daha düşüyor bak, gözü yaşlı', 'Öyle bir yerindeyim Dünya''nın Öyle bir yerinde yolların Uçsuz bucaksız bir yerinde Kaybolmuşluğun ötesinde Bilmiyorum adı nedir sensizliğin ...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gurbet-agrisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurur', 'gurur-meltem-seyhan-0ivym', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her bir noktası acısa da bedenimin

Tam ortası yansa da yüreğimin

Sırf kendime inat, sırf size inat

Kapılmayacağım akıntıya

Yıkabilirse yıksın bentlerimi

Islatabilirse ıslatsın gözlerimi

Kırsın direncimi kırabilirse

Tek bir geri adım attırsın mümkünse

Sormasın kimseler derdimi

Düşünmesinler halimi mecalimi

Ben her şeyi gömmüşüm içime

Deşmesinler derinlerimi', 'Her bir noktası acısa da bedenimin Tam ortası yansa da yüreğimin Sırf kendime inat, sırf size inat Kapılmayacağım akıntıya Yıkabilirse yıksı...', ARRAY['Türk Edebiyatı','Şiir','Meltem Seyhan']::text[], 8.5, '{"poet":"Meltem Seyhan","poet_slug":"meltem-seyhan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gurur-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tablo', 'tablo-meltem-seyhan-xv6i6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir tablo çizmeye başladik seninle ikimiz

Öyle sıcak, öyle samimi, öyle tertemiz

Geçirdiğimiz son gün bitecek olan

Ve tanıştığımız ilk gün başladığımız

Önceleri sen ve ben vardik siyah ve beyaz

Bir de mevsimler sırayla bahar ve yaz

Aşkımızı ekledik renklerle hiç solmayan

Usandırmamıştı onu ne fazla naz ne niyaz

Uzun uzun seyrettik tablomuzun ilk halini

Bazen öfkeye boyanıverdi keskin ve ani

Farkettik hemen beraber sildik tüm izlerini

Yorulduk ama hiç ayırmadık ellerimizi

Nihayet turuncu yuvamızı ekledik tuale

Bir siyah damatlık ve beyaz bir gelinlikle

Sevgi ve minneti koyduk her köşesine

Ve söz verdik hiç gözyaşı olmasın diye', 'Bir tablo çizmeye başladik seninle ikimiz Öyle sıcak, öyle samimi, öyle tertemiz Geçirdiğimiz son gün bitecek olan Ve tanıştığımız ilk gün b...', ARRAY['Türk Edebiyatı','Şiir','Meltem Seyhan']::text[], 8.5, '{"poet":"Meltem Seyhan","poet_slug":"meltem-seyhan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tablo-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kilim', 'kilim-yetik-ozan-79z33', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'El emeği, alın teri, göz nuru; 

Bu kilimde üç çilenin yünü var, 

Boşa değil şu kibiri, gururu, 

Yedi iklim, dört köşede ünü var.

Renk almış yaylanın çiçeklerinden, 

Desen tutmuş buğday başaklarından, 

Gök kuşağı ağmış saçaklarından; 

Üzerinde bir ilkbahar günü var.

Her teli bir pınar olup akmada, 

Her düğüm yar gözü gibi bakmada, 

Biçimler el ele halay çekmede; 

Sanki ortasında köy düğünü var.

Bir ucunda bir destana başlanmış, 

Bir ucunda gülle bülbül eşlenmiş, 

Bir ucunda acı gerçek işlenmiş, 

Bir ucunda tatlı düşler tünü var.

Yunus Emre tapınanda yüz koymuş, 

Karacoğlan saz çalanda diz koymuş, 

Köroğlu dört nala geçmiş iz koymuş; 

Boylamında erenlerin yönü var.

Höyük gibi bengiliği yaşıyor; 

Bağrında bir kutlu gömü taşıyor, 

Yaşı nice yüzyılları aşıyor; 

Bu kilimde uygarlığın dünü var.', 'El emeği, alın teri, göz nuru;  Bu kilimde üç çilenin yünü var,  Boşa değil şu kibiri, gururu,  Yedi iklim, dört köşede ünü var. Renk almış ...', ARRAY['Türk Edebiyatı','Şiir','Yetik Ozan']::text[], 8.5, '{"poet":"Yetik Ozan","poet_slug":"yetik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kilim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alacağın Olsun', 'alacagin-olsun-metin-usengec-kadwo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beni böyle terk ettin ya

Alacağın olsun

Dönüp arkana bakmadın ya

Alacağın olsun

Yapma dedim yaptın ya

Alacağın olsun

Yaptın ama gönül almadın ya

Alacağın olsun

Bekledim hep değişmedin ya

Alacağın olsun

Beni yıktın,mutlu musun? 

Alacağın olsun

Gecelerim gündüz oldu,uyudun mu? 

Alacağın olsun

İnsanlara bakabildin,gülebildin mi? 

Alacağın olsun

Ahımı aldın yüreğimi yaktın ya

İki elim iki dünyada yakanda olsun..

25-Aralık-2002  23:00

Seninde Yüreğin Yansın Ben Gibi..', 'Beni böyle terk ettin ya Alacağın olsun Dönüp arkana bakmadın ya Alacağın olsun Yapma dedim yaptın ya Alacağın olsun Yaptın ama gönül almadı...', ARRAY['Türk Edebiyatı','Şiir','Metin Üşengeç']::text[], 8.5, '{"poet":"Metin Üşengeç","poet_slug":"metin-usengec","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/alacagin-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Örgütlemişler Baharı', 'orgutlemisler-bahari-gulcemal-durdu-t6gzs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gömdüğümüz kitaplar çiçeklenmiş

Örgütlemişler baharı

Karakolların önü

Lacivert yeşil sarı

Menekşeyle fesleğenler şifreli

Bildiri dağıtıyorlar güpegündüz

Bahçesinde polis şefinin

Balkonunda penceresinde

Unuttum adlarını adları neydi

İdris miydi Nuray miydi Eren mi

Girmişler saksılara adları sarmaşık

Evreni yontuyorlar sırça parmaklarıyla

Kırlarda bayırlarda papatyalarda telaş

Gömdüğümüz kitaplar çiçeklenmiş

Örgütlemişler baharı', 'Gömdüğümüz kitaplar çiçeklenmiş Örgütlemişler baharı Karakolların önü Lacivert yeşil sarı Menekşeyle fesleğenler şifreli Bildiri dağıtıyorla...', ARRAY['Türk Edebiyatı','Şiir','Gülcemal Durdu']::text[], 8.5, '{"poet":"Gülcemal Durdu","poet_slug":"gulcemal-durdu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/orgutlemisler-bahari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnfilak', 'i-nfilak-gulcemal-durdu-w83do', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir şiir toplayarak tüm renklerini

ve basarak bağrına sözcüklerini

                                      intihar etti

kendini yaktı kitap

ve sevgi

bir sözcüğe astı bedenini

ve bir kalem

kırılmamak için idam sephalarında

tohumundan infilak etti', 'bir şiir toplayarak tüm renklerini ve basarak bağrına sözcüklerini                                       intihar etti kendini yaktı kitap ve...', ARRAY['Türk Edebiyatı','Şiir','Gülcemal Durdu']::text[], 8.5, '{"poet":"Gülcemal Durdu","poet_slug":"gulcemal-durdu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/infilak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Gel', 'hadi-gel-gulcemal-durdu-yg8xv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Göz göze geldiğimiz gün gibi gel

İlk dokunduğun an gibi gel

Uzaklara dalmışken birden

Omzuma dokunan el gibi gel', 'Göz göze geldiğimiz gün gibi gel İlk dokunduğun an gibi gel Uzaklara dalmışken birden Omzuma dokunan el gibi gel...', ARRAY['Türk Edebiyatı','Şiir','Gülcemal Durdu']::text[], 8.5, '{"poet":"Gülcemal Durdu","poet_slug":"gulcemal-durdu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hadi-gel-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar', 'bahar-gulcemal-durdu-x3dy2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bugün kuşlar kaçmadı benden

uzattım elimi okşadım penceremden

sırtımda buluttan gömlek

ellerim ayaklarım

üstüm başım hep çiçek

içimde kıpır kıpır yine o garip böcek

hayra alamet değil

beni deli edecek

ya o mevsim gelmiştir

ya sevdiğim gelecek', 'bugün kuşlar kaçmadı benden uzattım elimi okşadım penceremden sırtımda buluttan gömlek ellerim ayaklarım üstüm başım hep çiçek içimde kıpır ...', ARRAY['Türk Edebiyatı','Şiir','Gülcemal Durdu']::text[], 8.5, '{"poet":"Gülcemal Durdu","poet_slug":"gulcemal-durdu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bahar-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sancılı Serüven', 'sancili-seruven-gulcemal-durdu-55d97', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ne zaman bir şiire otursam

bir kuş gelir gitmez olur

sessizlik çekilir kuytusuna

fırtınayı başlatan delisin sen

ben

      dalına tutunamayan

                   yaralı kuşun

uçup gitmek isterim

kaçıp gitmek isterim

bir imge apansız gelir

tutunur kanayan yerlerime gitmez olur

doğururum sancılar çekerim

hüznün ortasında unutulmuş akşamım belki

kendine küskün bir deli

bir sözcük takılır aklıma

deliler gibi sevimli

ne zaman bir şiire otursam

sen gelirsin aklıma

gözlerim görmez olur', 'ne zaman bir şiire otursam bir kuş gelir gitmez olur sessizlik çekilir kuytusuna fırtınayı başlatan delisin sen ben       dalına tutunamayan...', ARRAY['Türk Edebiyatı','Şiir','Gülcemal Durdu']::text[], 8.5, '{"poet":"Gülcemal Durdu","poet_slug":"gulcemal-durdu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sancili-seruven-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Kenarlıkları', 'ask-kenarliklari-gulcemal-durdu-s7geq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sesimsen yankımdan döneyim

dokunuşumsan aşklarımı vereyim

kız deli şey niye gelmedin

bak bira soğuyup duruyor

deniz kendiliğinden güzel

kuşlar sesime konup

                        konup kalkıyor

bir uçurum martının kanadına

                                 çizdiriyor kendini

her şey gelecekmişsin gibi

şu masa

köşede duran tuzluk

bir paket sigara

öylece kalmış

kesildiğinin farkında değil karanfil

garson sigaramı yakıyor

adam gülücükler gönderiyor masama

resim

       çerçevesine sığmazmış gibi

biran soğuyup duruyor

gelmeyecekmişsin gibi

gün

ayrıldığın güne dönüyor

karanfil kesildiği bıçağın ağzına

garson ateşini alıyor sigaramdan

adam gülüşlerini

resim çerçevesine dönüyor

perdesiz pencerede

bir kadınla bir çocuk

gülüşünü kandırmış götürüyorlar

ardından gözlerimi götürüyorlar

yetmezmiş gibi

yokluğunu üstüme salıyorlar

sanki gelmeyecekmişsin gibi

senden kalan tek şey

her şey

sanki gelmeyecekmişsin gibi', 'sesimsen yankımdan döneyim dokunuşumsan aşklarımı vereyim kız deli şey niye gelmedin bak bira soğuyup duruyor deniz kendiliğinden güzel kuşl...', ARRAY['Türk Edebiyatı','Şiir','Gülcemal Durdu']::text[], 8.5, '{"poet":"Gülcemal Durdu","poet_slug":"gulcemal-durdu","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/ask-kenarliklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Senfonisi', 'i-stanbul-senfonisi-gulcemal-durdu-a3nyi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'soğuk bir İstanbul akşamısın

üstün başın ayrılık

ey uzun yolların vazgeçilmez yolcusu

bu ayrılık sana

nereden kaldı

gittiğin her kent

ötekine istasyon

yalnızlık kokuyorsun

zemheriyle karışık

bütün telefonlar yüzüne kapanıyor

bütün kapılar suratına

kimliğini kaybettin

o eski garlarda

birden

bir dostun geliyor aklına

o eski garlarda

içinde ılık bir İzmir akşamı

körfezde bir vapur irkiliyor

kaybolan eski yıllarda

ey uzun yolların vazgeçilmez yolcusu

derelerle aktın

yağmurlarla yağdın

rüzgarlar kuytulardan çıkarıp geldi seni

bahar geldi

sen geldin

çiçek açtı

sen geldin

seni vuracaklar çocuk

incecik gülüşünden vuracaklar

ben ondan korkuyorum

sen yüreklerin dayanılmaz sancısı

bu sevmeler sana nereden kaldı

martılarla uçtun

mahpuslarda yattın

dikenli teller

yargısız infazlar

ve bu uzun hayat...

hangi köprülerden

mayın tarlalarından

en güzel şiirimizdin

şairlerle vurdular seni

seni vuracaklar çocuk 

incecik duruşundan vuracaklar

ben ondan korkuyorum', 'soğuk bir İstanbul akşamısın üstün başın ayrılık ey uzun yolların vazgeçilmez yolcusu bu ayrılık sana nereden kaldı gittiğin her kent ötekin...', ARRAY['Türk Edebiyatı','Şiir','Gülcemal Durdu']::text[], 8.5, '{"poet":"Gülcemal Durdu","poet_slug":"gulcemal-durdu","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/istanbul-senfonisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kitabım', 'kitabim-fulden-sogut-if88o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni okuyarak, 

Bilgi ediniriz, 

Bizi okuttuğun için, 

Seni severiz.

Canım kitabım, 

Seni çok seviyorum, 

Sen benim biricik kitabımsın, 

Canım kitabım.', 'Seni okuyarak,  Bilgi ediniriz,  Bizi okuttuğun için,  Seni severiz. Canım kitabım,  Seni çok seviyorum,  Sen benim biricik kitabımsın,  Can...', ARRAY['Türk Edebiyatı','Şiir','Fulden Söğüt']::text[], 8.5, '{"poet":"Fulden Söğüt","poet_slug":"fulden-sogut","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kitabim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçekler', 'cicekler-fulden-sogut-9onma', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çevrenin en güzel, 

Canlı varlığıdır, 

Çiçekler çevreyi süsler, 

Her rengi vardır.

Herkes sever bu, 

Güzel çiçekleri, 

Kim sevmez ki, 

Bu güzel şeyi.', 'Çevrenin en güzel,  Canlı varlığıdır,  Çiçekler çevreyi süsler,  Her rengi vardır. Herkes sever bu,  Güzel çiçekleri,  Kim sevmez ki,  Bu gü...', ARRAY['Türk Edebiyatı','Şiir','Fulden Söğüt']::text[], 8.5, '{"poet":"Fulden Söğüt","poet_slug":"fulden-sogut","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cicekler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşli Bir Cumartesi', 'gunesli-bir-cumartesi-onder-karadag-bezeo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '...

İnce zar gibi aramızda

Dilsiz ellerimiz durur

Günsüz bir gölgenin ardında 

Kanamış bir mendil kurur

Uysal, yaramaz, zenci, beyaz 

Çingene pembesi, kara

Kalabalık uluslu bir yüz

Bir kadını tamlıyor, üç renk

Yordamsız bakışlarında...

Kırmızı elif, Tokatlı; Kürtka

Mavi duygu, Marmara’dan

Siyah gül, savrulur Ege’den 

başka başka coğrafyalara...

Anayurtsuz çocukluğunda

Özetliyor bunlar seni

Kaybolup gidiyorsun

Saklambaç oyunlarında...

Eprimiş bir sevdadır, şimdi

Tam ortasında göğsünün

Kanamış bir mendil de kurur

Ve...

Kasvetli bir tanrıgeneral

Yarasa gibi asılmış durur

Sıvasız duvarında 

gençliğimizin...

...

Ömrüme şakıyorsun

Güneşli bir cumartesi.

(02.11.2002 Çim. Kalesi)', '... İnce zar gibi aramızda Dilsiz ellerimiz durur Günsüz bir gölgenin ardında  Kanamış bir mendil kurur Uysal, yaramaz, zenci, beyaz  Çingen...', ARRAY['Türk Edebiyatı','Şiir','Önder Karadağ']::text[], 8.5, '{"poet":"Önder Karadağ","poet_slug":"onder-karadag","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gunesli-bir-cumartesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Gün Yepisyeni Bir yüz', 'her-gun-yepisyeni-bir-yuz-onder-karadag-j9zwy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her gün yepisyeni bir yüz

Kendi baharının çingenesi

Bir kadın. Bahçesinin

Gündelikçi sevinçlerini

Dağıtırdı herkese...

Mart çiçeğinin açışı kadar.

Ancak aybaşlarında

İç kanamalarında sevişirdi

Ve yanıma geceyle gelirdi

Süt kokulu ihanetleriyle...

Bir gökyüzü sererdi üstüme

Bencil, gücenik

Ben ölürdüm...

Ve bana derdi; 

Her gül kendine kanar 

Ateşler yanar külüne.

(05.06.2002 Abidos)', 'Her gün yepisyeni bir yüz Kendi baharının çingenesi Bir kadın. Bahçesinin Gündelikçi sevinçlerini Dağıtırdı herkese... Mart çiçeğinin açışı ...', ARRAY['Türk Edebiyatı','Şiir','Önder Karadağ']::text[], 8.5, '{"poet":"Önder Karadağ","poet_slug":"onder-karadag","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/her-gun-yepisyeni-bir-yuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan', 'i-syan-hafize-zuluflu-98y5e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sabrı tükendi beklemelerimin

Bugün isyan çıktı yüreğimde

Çekti kılıcını bütün umutlar

Bir bir üzerime çullandı

Sessiz çığlıklar

Fayda vermedi ne öfke zırhım

Ne sabrımın geri kalanı

Deldi geçti gözlerinden beter

Bir kurşun

Devrildi bedenim', 'Sabrı tükendi beklemelerimin Bugün isyan çıktı yüreğimde Çekti kılıcını bütün umutlar Bir bir üzerime çullandı Sessiz çığlıklar Fayda vermed...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/isyan-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Geri Ver', 'bana-geri-ver-esma-ozdemir-29gqg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gel kardeşim seninle bizim ellere gidek; 

Dumanlı dağlarımı bana geri ver! 

Özgürlüğü, sevgileri üleşek; 

Yüce yaylalarımı bana geri ver! 

Puslu gözlerimi doruklara bırak; 

Mavi gökyüzümü bana geri ver! 

Okşamsı elimizle bir çiçeğe dokunak; 

Lale, sümbül, menekşemi bana geri ver! 

Cıldıroluk''u elele çıkak

Çökek''e varınca biraz oturak

Duaların Düz''ü gülerek geçek

Çalca''nın ardındaki yaylamı bana geri ver! 

Şu obada apak bir çadır kurak

Buralarda üç ay kadar oturak

Çam kökünden akılganlar toplayak

Baygın kokar ormanımı bana geri ver! 

Şu dağın başında bir kurban kesek

Karadeniz''le ufukta hasret giderek

Tekeli Yaylası''na selam gönderek

Dünek Baba! Toprağımı bana geri ver! 

Özdemir Kardeşim, özüm sözümdür

Gurbet ele göçmek alın yazımdır

Bu beni coşturan gönül sazımdır

Çocukluk yıllarımı bana geri ver!', 'Gel kardeşim seninle bizim ellere gidek;  Dumanlı dağlarımı bana geri ver!  Özgürlüğü, sevgileri üleşek;  Yüce yaylalarımı bana geri ver!  P...', ARRAY['Türk Edebiyatı','Şiir','Esma Özdemir']::text[], 8.5, '{"poet":"Esma Özdemir","poet_slug":"esma-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/geri-bana-ver-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldüreceksiniz Beni', 'oldureceksiniz-beni-hilmi-tanrikulu-ueo98', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nerdeyim? sanki yaşadıklarım beni sevmiyor gibi... bir ada tekbaşıma ölüme terkedilmiş gibiyim ve tek mal varlıyım iki parça giysim olduğu halde ve bu adayı kimsenini hiçbir zaman bulamayacağı halde hırsızlardan korkuyorum...neyim ben ve kimim? yaşananlar nerdere? neler yaşayacağım? delimiyim? hayır. sadece aşık ve adasında yalnız bir yürek...yalnızlık iyidir... güçlüdür yalnız insan...öyleyim ki; yaşamıyorum, ölmedim...ellerim bedenimi arıyor bulamıyor...sonumda yok, başlangıcımda... gözlerim paramparça ve hiçbirşey göremiyor...kendimi ve yaralarımı göremiyorum.konuşuyorum olmayan birsürü insanla ama, şarkı bile söyleyemeycek kadar kekemeyim...koşmuyor, uçmuyorum ama gidiyorum...ölmedim, yaşamıyorum...

bir gün beni öldüreceksiniz; 

ah benim sevgili kabuslarım...', 'Nerdeyim? sanki yaşadıklarım beni sevmiyor gibi... bir ada tekbaşıma ölüme terkedilmiş gibiyim ve tek mal varlıyım iki parça giysim olduğu h...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/oldureceksiniz-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya-', 'ruya-hilmi-tanrikulu-5d3em', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uyandım...

Etimde üçyüz altmış derece dönen, 

bıçakla, 

Utanmasam küfredecektim, 

Ozon tabakasına.

Ne rüyaydı...', 'Uyandım... Etimde üçyüz altmış derece dönen,  bıçakla,  Utanmasam küfredecektim,  Ozon tabakasına. Ne rüyaydı......', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ruya-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüce Milletim', 'yuce-milletim-fatih-cinar-1l67d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'asırlık çınarlar gibi yıllanan

asi nehirler gibi çağlayan

tarihini kılıçla kan ile yazan

bir tanesin benim yüce milletim

çıldıran, deliren şeref namus deyince

maruz kalsada tarihte birçok kalleşliğe

leke sürdürmedi sürdürmez şerefine

delikanlı mert yüce milletim

cephede mehmetçik kılar namazı

islamın bekçisi''dir bırakmaz al sancağı

dilinden hiç düşürmez peygamberi allahı

inançlı imanlı yüce milletim

temelleri atılmış şehit kanıyla

süngüye takılmış kanlı başıyla

rengini kanından alan bayrağıyla

dünyada birtek yüce milletim

hiç bir tarif yetmiyor şanını anlatmaya

mürekkepler yetişmiyor tarihini yazmaya

bekle az kaldı özlenen aydınlık şafaklara

hakka tapan cesur yüce milletim', 'asırlık çınarlar gibi yıllanan asi nehirler gibi çağlayan tarihini kılıçla kan ile yazan bir tanesin benim yüce milletim çıldıran, deliren ş...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yuce-milletim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayasofyanın Sessizliğinde', 'ayasofyanin-sessizliginde-fatih-cinar-yvc94', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bu garip sessizlik yakışmıyor hiç sana

küsme kutsal ayasofya fatihin torununa

ne oldu şimdi beş vakit okunan ezana

seni böyle susturan zihniyet batsın

hediyesin bize fatih sultandan

müjdelendin halka resurullahtan

kardeşinde inliyor yahudinin zulmundan

seni böyle susturan zihniyet batsın

dikilirken minareler kesildi bir çok kurban

şimdi namerdin elinde inliyorsun yalnızlıktan

dayan ayasofyam az biraz daha dayan

seni böyle susturan zihniyet batsın

müze yaptılar birçok namert basıyor bağrına

ayasofyam hasret secdeye varan başlara

zamanında hizmet etti büyük padişahlara

seni böyle susturan zihniyet batsın

parelendi gönlüm yanıyor içim

suçluysam eğer kesilsin bu dilim

sözü geçmiyor merdin dediği oluyor piçin

seni böyle susturan zihniyet batsın

sanki bizans uşağı avrupa yalakası

türk''e kolay yine ayasofyalar alması

bizden kork ermeninin karakıllı papazı

seni böyle susturan zihniyet batsın', 'bu garip sessizlik yakışmıyor hiç sana küsme kutsal ayasofya fatihin torununa ne oldu şimdi beş vakit okunan ezana seni böyle susturan zihni...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ayasofyanin-sessizliginde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yas', 'yas-mehmet-tamac-7ub1t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gülüşünde eski acılar taşıyanların

como una sola flor seremas

como una espıga ondularamas

bilinçsizce mırıldanışta ansızın

hatırlanan bir şarkı gibidir dönüşündeki o haz

henüz bitmez gönlümdeki bilindik yas.', 'gülüşünde eski acılar taşıyanların como una sola flor seremas como una espıga ondularamas bilinçsizce mırıldanışta ansızın hatırlanan bir şa...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tamaç']::text[], 8.5, '{"poet":"Mehmet Tamaç","poet_slug":"mehmet-tamac","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yas-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahpe Avrupa (Avrupanın Öteki Yüzü)', 'kahpe-avrupa-avrupanin-oteki-yuzu-fatih-cinar-nqcgp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Avrupa Birliği Sarhoşlarına! ! ! 

ellerinde oyuncaksın zalim şeytanların

mezesin masasında sarhoşların ayyaşların

zarsın kağıtsın ellerinde kumarbazların

hani nerede asaletin kahpe avrupa 

papazın kilisede vaaz veriyor

kızlığın hangi doktorda kaç kez dikiliyor

tarihte aldığın dersler sana yetmiyor

frenlerin tutmuyor kahpe avrupa

saçların gökkuşağı gibi boyalı

iş bilmez ellerin manikürlü cilalı

yüreğin paslı kömür gibi karalı

kumaşın hiç leke tutmuyor kahpe avrupa

sevişirsin çılgın gibi sokaklarda

kırıştırırsın babanla yaşıt adamlarla

mahkemede son bulan deneme nikahlarla

modernlikten bahseder kahpe avrupa

kafası boynuzlu siyah keçisin

babası üç tane fahişenin piçisin

temizlikten habersiz yağlı domuz leşisin

aslı belli olmayan kahpe avrupa

karnında bebekle olursun gelin

günaha bulanmış baştan ayağa bedenin

böyle medeniyet seninolsun senin

kucaktan kucağa gezen kahpe avrupa

daracık pantolonu giyersin kıçına

boyaları sürersin renk renk tırnağına

diskolarda barda süren yaşamına

ben acıyorum senin kahpe avrupa

gözler bu yaşananlara bakakalmasın

sözler bir kulaktan girip diğerinden çıkmasın

ahireti bilenler hak yolundan ayrılmasın

ibret oldun inananlara kahpe avrupa', 'Avrupa Birliği Sarhoşlarına! ! !  ellerinde oyuncaksın zalim şeytanların mezesin masasında sarhoşların ayyaşların zarsın kağıtsın ellerinde ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/kahpe-avrupa-avrupanin-oteki-yuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Anlamalısınız', 'beni-anlamalisiniz-turgay-kaygi-4ahjp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'beni anlamalısınız

anlamalısınız

gerçekler çok soğuk

böyle soğuk, 

buz gibi kış gecelerinde

benim gibi sizde

yalanlara sarınmalısınız

inanın

herkesin yalan olduğunu bildiği

yalanlar bile

konyak gibi ısıtır içini insanın; 

denemelisiniz mutlaka

beni dinlemelisiniz

hiç farkı yoktur hiç

mutluluğu arayan insanla

kuyruğunu kovalayan köpeğin

içinizi gıdıklarken

mısraları şairlerin

ne kadar mutsuz doğup, 

ne kadar mutsuz öldüklerini de

bilmelisiniz

böyle soğuk, 

buz gibi kış gecelerinde

yalanlar bitip tükendiğinde

varsa bir şişe konyağınız; 

şanslısınız

bana inanmalısınız

devirince

bir şişe konyağı

içiniz ısınıyor bir yandan

bir de

şahit oluyor insan

yelkovanı geçtiğine

akrebin

bunu ne ben uydurdum

durup dururken

ne de durup dururken

zamanın yeni bir huyunu duymaktasınız

kanunları katıdır

yaşamın; 

''hepiniz ölmelisiniz! ''

ama

ölmeden

ve sevdiğiniz insanlar sizi

sevdiklerinizin yanına gömmeden önce

akrebin yelkovanı nasıl geçtiğini de

mutlaka görmelisiniz! ..

(inegöl,25.11.2002)', 'beni anlamalısınız anlamalısınız gerçekler çok soğuk böyle soğuk,  buz gibi kış gecelerinde benim gibi sizde yalanlara sarınmalısınız inanın...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kaygı']::text[], 8.5, '{"poet":"Turgay Kaygı","poet_slug":"turgay-kaygi","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/beni-anlamalisiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amelya', 'amelya-turgay-kaygi-7ayqv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'amelya hey! 

sen kim olduğunu biliyor musun? 

ya da benim kim olduğumu? 

arıyor musun sende kendini

sokaktan geçen insanların yüzünde? 

amelya! 

kızgınım sana! 

neden bu kadar çekiyorsun kendine beni? 

neden hayırlar bu kadar kolayken

körolası belkilerde direniyorsun? 

biliyorum! 

senin kim olduğunu bulmam için

önce benim kendimi tanımam gerek! 

zormuş amelya! 

ne zormuş düşününce! 

o uzak denizlerde

kimselerin görmediği adaların

kimselerin görmediği kıyılarına vuran dalgalar

gibi

hayırsız gözlerin 

süzülünce

bir defa ruhuna insanın, 

anlamamak ne mümkün

acı çekmeden yok olmanın imkansızlığını...

amelya gülme bir daha yüzüme! 

aklımı çelme amelya aklımı! 

zamanımı da çaldığın yere geri bırak! 

sende gördün bak! 

seninle benim

paylaşacak hiçbir şeyimiz yok! 

ya bir gece yarısı 

girdiğin gibi

çık git sensizliğimden

bir gece yarısı artık, 

ya da

göğsüme sapladığın her neyse şu; 

en derine sok! 

(inegöl,25.11.2002)', 'amelya hey!  sen kim olduğunu biliyor musun?  ya da benim kim olduğumu?  arıyor musun sende kendini sokaktan geçen insanların yüzünde?  amel...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kaygı']::text[], 8.5, '{"poet":"Turgay Kaygı","poet_slug":"turgay-kaygi","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/amelya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı', 'sari-oguzkan-bolukbasi-4olju', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sarı

sonbahardır yapraklarda

hüzündür çiçeklerde

yaşamın iç çekmesidir

eski resimlere dalıp

fotoğraflar sararıp ta silinmeye başladığında görüntüler

saçların sarı kalır aklımda esintiler sarıdır', 'sarı sonbahardır yapraklarda hüzündür çiçeklerde yaşamın iç çekmesidir eski resimlere dalıp fotoğraflar sararıp ta silinmeye başladığında gö...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökgürültüsü', 'gokgurultusu-radovan-pavlovski-u5pvs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çocuğun ilk sözleri gibi yapraklanmış orman 

Şu yokuşu bir tırmanayım hele, tepece 

rüzgarlardan bir çocuk bezi bulurum terimi silmeye. 

Tanrım, 

birdenbire görünüyorum her şeyi 

ve bahar gökgürültüsünde 

sesini duyuyorum canlı her şeyin 

Yeraltı krallıkları üzerinden 

uçarcasına yürüyorum 

Gördüğüm ve duyduğum her şey 

madem ki benim, yalvarırım, Tanrım, 

hepsini elimden al 

sesten ve dinlediğim gökgürültüsünden mada. 

(Çeviren: Suat Engüllü)', 'Çocuğun ilk sözleri gibi yapraklanmış orman  Şu yokuşu bir tırmanayım hele, tepece  rüzgarlardan bir çocuk bezi bulurum terimi silmeye.  Tan...', ARRAY['Türk Edebiyatı','Şiir','Radovan Pavlovski']::text[], 8.5, '{"poet":"Radovan Pavlovski","poet_slug":"radovan-pavlovski","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gokgurultusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek Sevgi', 'gercek-sevgi-ahmet-etik-3y22u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana olan sevgim yalan degil 

Bu dünaya sensiz umrumda degil 

Bir tek seninle mutluyum 

Sensiz yasamak istemyorum 

Biliyorsun yanliz seni seviyorum 

Senden baskasini sevemem ben 

Ömrümün sonuna kadar beklesemde 

Bir kalbim var oda sende 

Herzaman seni düsünüyorum 

Ayrilik hancer oldu saplandi kalbime 

Eritiyor beni günden güne 

Gelde kapa bu yarayi gönlümde 

Herseye dayanirim ben 

Bir tek sensizliye dayanamam 

Herzaman duga ediyorum tanrima 

Seni almadan beni alsin yanina 

Bunu böyle bil corumlu güzelim 

Sana olan askim kutsaldir 

Canimdan degerlisin benim icin 

Seni kaybedersem beni ölmüs bil', 'Sana olan sevgim yalan degil  Bu dünaya sensiz umrumda degil  Bir tek seninle mutluyum  Sensiz yasamak istemyorum  Biliyorsun yanliz seni se...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Etik']::text[], 8.5, '{"poet":"Ahmet Etik","poet_slug":"ahmet-etik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gercek-sevgi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dehşet', 'dehset-radovan-pavlovski-46fmg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karanlık. 

Burnunun ucunu bile göremiyor insan, 

kalkmış türkü söylüyorsun oysa sen. 

-Hadi ölüversene artık, 

diye gakıyor karga. 

-Duan batsın, 

sen de türkü söyle artık 

günün ağarsın. 

-Türkünün dehşetinden 

çıkıver, kökün 

tepesinden iniver; 

türkünün 

dünyanın neresinde 

yankılandığını işitebilmem için. 

-Hadi ölüversene artık, 

diye gaklıyor karga. 

Karga, 

sen de türküye dur artık 

kes şu gaklamayı ya da 

konuş insansan eğer. 

Hava başka yere akıyor. 

(Çeviren: Suat Engüllü)', 'Karanlık.  Burnunun ucunu bile göremiyor insan,  kalkmış türkü söylüyorsun oysa sen.  -Hadi ölüversene artık,  diye gakıyor karga.  -Duan ba...', ARRAY['Türk Edebiyatı','Şiir','Radovan Pavlovski']::text[], 8.5, '{"poet":"Radovan Pavlovski","poet_slug":"radovan-pavlovski","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dehset-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savaş Şimşekleri', 'savas-simsekleri-radovan-pavlovski-i9n0s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zaten bilemezsin sen uykuda 

nereye kadar uzar gider 

yaşayanların zamanı 

ölülerin zamanı nereye kadar 

Güneşin ve düşün 

gölgesinin düştüğü yere kadar 

saplar durursun hançerlerini 

ya nereye vurdu yıldırım, nerede karardı gün 

ağlama duvarı hangi duvardı 

şimşeklerin 

beyaz odasına çıkıyorsun 

ağlamanın öpücüğü 

ve adımları ayrılığın 

seni izleyen. 

(Çeviren: Suat Engüllü)', 'Zaten bilemezsin sen uykuda  nereye kadar uzar gider  yaşayanların zamanı  ölülerin zamanı nereye kadar  Güneşin ve düşün  gölgesinin düştüğ...', ARRAY['Türk Edebiyatı','Şiir','Radovan Pavlovski']::text[], 8.5, '{"poet":"Radovan Pavlovski","poet_slug":"radovan-pavlovski","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/savas-simsekleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demedim mi?', 'demedim-mi-alim-vedat-suner-mqo7b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bu gönülden geçme

yaşayamazsın demedim mi? 

üşüyen bedenin için

sıcak ten bulamazsın demedim mi? 

yüzüne her gülen

dostundur dedim mi? 

seni sevmeyende

senin için ölür dedim mi? 

sana kötü söz söyledim mi? 

senden benim için

ölmeni istedim mi? 

tek seni sevdiğimi SÖYLEMEDİM Mİ?', 'bu gönülden geçme yaşayamazsın demedim mi?  üşüyen bedenin için sıcak ten bulamazsın demedim mi?  yüzüne her gülen dostundur dedim mi?  seni...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/demedim-mi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ben Olayım', 'bir-ben-olayim-alim-vedat-suner-yw2rt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ela gözlerinde bir ben olayım

Sana doyan tek ben olayım

Üşüyor bedenim gireyim koynuna

Koynunda uyuyan bir ben olayım...', 'Ela gözlerinde bir ben olayım Sana doyan tek ben olayım Üşüyor bedenim gireyim koynuna Koynunda uyuyan bir ben olayım......', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-ben-olayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Akşam', 'bu-aksam-alim-vedat-suner-1nv3y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'uyandırma derin uykularda

senle doluyum şuan

elde edemediğim aşkınla

bir hoşum bu akşam

kaldırma başını omzumdan

sıcağında olayım her an

tenine hasret kalmadan

avareyim bu akşam...', 'uyandırma derin uykularda senle doluyum şuan elde edemediğim aşkınla bir hoşum bu akşam kaldırma başını omzumdan sıcağında olayım her an ten...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bu-aksam-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Seni', 'ask-seni-alim-vedat-suner-bpvme', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Perde arkası provadasın

Çıkmak ürpertiyor insan yüzüne

Alışmamışsın sevmeye sevilmeye

Korkutuyor AŞK SENİ

Son makyajını yapmışsın kulis de

Saklamak için güzelliğini

Boyalar içine bürünmüşsün

Çünkü korkutuyor AŞK SENİ...', 'Perde arkası provadasın Çıkmak ürpertiyor insan yüzüne Alışmamışsın sevmeye sevilmeye Korkutuyor AŞK SENİ Son makyajını yapmışsın kulis de S...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ask-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sone-1', 'sone-1-alim-vedat-suner-rkz26', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Keşkelere düşsemde

Sonkez olsun yüzüne

''Keşke ayrılmasaydık, 

                   Seni hala seviyorum''

Deseydim....! ! !', 'Keşkelere düşsemde Sonkez olsun yüzüne ''Keşke ayrılmasaydık,                     Seni hala seviyorum'' Deseydim....! ! !...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sone-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünmeyle Başladı Duygular Körelmeye!', 'dusunmeyle-basladi-duygular-korelmeye-turgay-kaygi-hditb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''meltem''e''

İnsan denilen düşünen hayvan, 

muzdan bıkmayıp, 

tadına merak salmasaydı

diğer yaratıkların, 

ne sen beni tanırdın

ne de ben seni! 

ama bana sorarsan; 

bir palmiye gölgesinde

muz hevenklerine dayayıp da

başımı, 

okyanusun ufkunda

güneşlerin doğup

ayların batmasını, 

ayların doğup

güneşlerin batmasını

seyrederek ehlikeyif

geçirmek

bana bahşedilen ömrü

hiç de fena olmazdı

gibime geliyor! 

(inegöl,26.11.2002)', '''meltem''e'' İnsan denilen düşünen hayvan,  muzdan bıkmayıp,  tadına merak salmasaydı diğer yaratıkların,  ne sen beni tanırdın ne de ben seni...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kaygı']::text[], 8.5, '{"poet":"Turgay Kaygı","poet_slug":"turgay-kaygi","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dusunmeyle-basladi-duygular-korelmeye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unut Onu', 'unut-onu-ahmet-safak-tw2ll', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kavgalardan cikmis birinin

Asra civi cakmis birinin 

Sevdasindan donmeyip

yanmis birinin yuregisin 

Unut onu gitsin gonlum

Ey gonlum deli gonlum divane gonlum

Ey gonlum deli gonlum avare gonlum

Demedimmi ondan sana yar olmaz 

Bu sehir bize diyar olmaz

Unut onu gitsin gonlum

Bu ask burda bitsin gonlum

Don sen gene yoluna 

Vefasizin dalina

Tutma, yigitlik sende kalsin gonlum

Davul bile dengi dengine

Vurulmus hey onun aklina 

Yuregimki kaf daginda 

O kaprisin bataginda

Yardim et de ciksin gonlum', 'Kavgalardan cikmis birinin Asra civi cakmis birinin  Sevdasindan donmeyip yanmis birinin yuregisin  Unut onu gitsin gonlum Ey gonlum deli go...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şafak']::text[], 8.5, '{"poet":"Ahmet Şafak","poet_slug":"ahmet-safak","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/unut-onu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoksun Sanırım...', 'sen-yoksun-sanirim-alim-vedat-suner-8jutx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sabah kalktığımda

yanımdasın diye

yatağın sol tarafına geçmem

aç çıkarım evden

son ana kadar

kalkıpda kahvaltı hazırlayacaksın

demli bir çay koyacaksın

sonrada gelip

      Eskiden olduğu gibi

sarılacaksın boynuma sanarım...

birtürlü yediremem kendime

beni ortada bırakıp gittiğine

gözlerim dolar, dalarım bazen

sensiz geçirdiğim gecelerde...', 'sabah kalktığımda yanımdasın diye yatağın sol tarafına geçmem aç çıkarım evden son ana kadar kalkıpda kahvaltı hazırlayacaksın demli bir çay...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-yoksun-sanirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zehirli Kurşun', 'zehirli-kursun-omer-tirendez-k8wuj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sürgünlerdeyim! 

Beni, aşkın  kurşunu  vurdu.

Kendimden  uzaklaştım.

Haksız  değilim! 

Ben; ben değilim, sen  olamadım...

Seviyorum  seni, kanamadım  sana...

Parmağında  alyans, yatağında! 

Yorganında, ben  olmam  lazım.

Seviyorum  seni, seviyorum...

Aşkınla  yanan, aşkınla  tüten.

Hem  ben  ağlıyorum, 

Hem seni  ağlıyorum! 

Gözlerim  varya, onlar  köreldi...

Neden  bırakıp  gittin? 

Bir  elvedayı bile, 

Çok  gördün; sen  için

Senin  için, yanan  zavallı  yüreğime...

Ben  buradayım, gitmedim.

Fakat, bana  ''''yoksun '''' diyorlar! ..

Sırf  senin  yüzünden, 

Madara  oldum  hayata...

Yaptığını  beğendin  mi? 

Dalga geçiyorlar, Ti ye  alıyorlar...

Benimle   oyun  oynadın, diye...

Bari  oyunbozanlık   yapmasaydın! 

Daha  onaltı  yaşındaydın, 

Mahallemize  taşındığınızda.

Daha  ilk  görüşte  vurulmuştum.

Kömür  karası  gözlerine! 

Zaten  ilk   kurşunu 

Orada  sıktın  kalbime.

Şimdi  o  kurşun   bile, 

Sana  zehrini kusuyor...

Hatırlarsın; ilk  buluştuğumuz  yeri.

Şahintepesi, yaşlı  çınar''ın altı...

Az  ötemizde, bir  başka  çift, 

Hala   görürüm  onları...

Evlenmişler, yuvalarını  kurmuşlar.

Bana seni  sordular, ikimizi  sordular.

Kalbime sapladığın   kurşunu   çıkardım.

KURŞUN; sana  olan  zehrini  kustu! ..', 'Sürgünlerdeyim!  Beni, aşkın  kurşunu  vurdu. Kendimden  uzaklaştım. Haksız  değilim!  Ben; ben değilim, sen  olamadım... Seviyorum  seni, k...', ARRAY['Türk Edebiyatı','Şiir','Ömer Tirendez']::text[], 8.5, '{"poet":"Ömer Tirendez","poet_slug":"omer-tirendez","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/zehirli-kursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Gibi Gel', 'yagmur-gibi-gel-alim-vedat-suner-tyjjm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bırak düşüncelerinide

Düşlerinle gel

Aniden yola çık

Sağnak yağmur gibi gel

''Nerden çıktın sen'' diye sormam

Değişmediysen eğer

Adın gibi engin ol yeterki

Yağmur gibi gel...', 'Bırak düşüncelerinide Düşlerinle gel Aniden yola çık Sağnak yağmur gibi gel ''Nerden çıktın sen'' diye sormam Değişmediysen eğer Adın gibi eng...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yagmur-gibi-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nöbette', 'nobette-aziz-pinar-mgd3k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir geceki...

Yalnızlık uzanıyor

İstesende istemesende tutuyorsun.

Gökte binlerce yıldız, 

Yanında pırıl, pırıl biz deniz olsada

Yalnızlığın koynundasın.

Sen onbir-bir nöbetçisi asker

Ne düşünür, nerelerde dolaşır

Hangi yıldıza uzanırsın.

Bu gece ikimizde yalnızlığa mahkumuz

Sen bir yıldızda, ben bir yıldızdayım...

Sakın üzülme askerim

Vatan toprağındayız

İkimizde bayrağın

Ayyıldızındayız...', 'Bir geceki... Yalnızlık uzanıyor İstesende istemesende tutuyorsun. Gökte binlerce yıldız,  Yanında pırıl, pırıl biz deniz olsada Yalnızlığın...', ARRAY['Türk Edebiyatı','Şiir','Aziz Pınar']::text[], 8.5, '{"poet":"Aziz Pınar","poet_slug":"aziz-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/nobette-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar', 'kar-i-clal-aydin-1zyz9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karlı bir aksamdı Ankara da

Son kez elele yürümüştük

Bitmesin istediğim yola kısacık beraberliğimizin bütün anılarını sığdırmıştık...

Yazarsın bana demiştin bende yazarım sana sık sık, 

Ağlıyordum, 

Sen görmeyesin diye kaldırmıyordum başımı

Elimi daha sıkı tuttun 

Anlıyordum 

Bu ayrılığa dayanmıyordu kalbim...

Öğrettiğim çiçek adlarını unutma dedin, 

Kelebekleri kitap arasında kurutma, 

Sık sık fotoğraf çektir yolla bana, 

Kitaplarım sana emanet, incitme kimseyi, kin büyütme kalbinde beni bekle...

Yol bitti gidiyordun artık, 

Gittin! 

Sokakta gördüklerimi filmdeki aktörleri sen sandım bir süre, 

Kin büyütmedim kalbimde söz vermiştim sana diye, 

Kitaplarını okudum kelebeklere dokunmadım, 

Öğrendiğim çicek adlarına yenilerini ekledim, 

En çok fesleğeni, çoban heybesini, aksam sefasını sevdim.

Seni beklerken çok sey öğrendim, 

Yolunu gözlediğim, sevdiğim ilk adam

Nasılsa bulacaktır seni diye her görüşümde aynı güçle seslendim; 

Uçak babama selam söyle, 

Beni kötü rüyalarımdan uyandıran, sevdiğim ilk adam bir bilsen! 

Seni nasıl özledim.

Kar yağıyor şimdi otuz yaşım bitti.

Kitapların bende, kelebekler gibi kar taneleri, 

Kendi yolumda yürürken hiç unutmadım o cümleyi; 

Selamını aldım babacığım 

Kin büyütmedim kalbimde, 

Küçük kızının gözleri; 

Hala senin çiceklerinde.

Uçak! 

Babama selam söyle....', 'Karlı bir aksamdı Ankara da Son kez elele yürümüştük Bitmesin istediğim yola kısacık beraberliğimizin bütün anılarını sığdırmıştık... Yazars...', ARRAY['Türk Edebiyatı','Şiir','İclal Aydın']::text[], 8.5, '{"poet":"İclal Aydın","poet_slug":"i-clal-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/kar-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olacak Halim', 'ne-olacak-halim-i-clal-aydin-n8447', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen bu satırları okurken ben cok uzaklarda olacağım...

Böyle başlardı bütün bildiğimiz mektuplar, 

Biliyormusun? Bu ikimizin hikayesi, 

Şu anda nerdesin, ne yapmaktasın; 

Bildiğim yerlerdemisin yoksa hiç görmediğim bir evin penceresinde mi, 

Sevdiklerin özlemi sardımı nicedir kalbini, 

Pişman mısın başlamadıkların için, iç cekiyorsundur şimdi

Düşünüpte yazmadığın yazıpta yollamadığın mektupları saklıyormusun hala, 

Kafanda hep aynı cümle biliyorum ne olacak halim, 

Ah, biriktirdiğimiz bütün hevesler nasılda hızla tükendiler.

En çok kimi özledin, en çok neyi bekledin? 

Şimdi düşlediklerimin neresindesin...

Dedim ya.

Bu ikimizin hikayesi...

Islandımız bütün yağmurları, dudak kanatan kalpli sızı aşklarımızı, 

Bizi buluşturan kaldırımları, 

İşte bütün bunları bütün bunları yazıyorum.

Ben unutmadım diye

Hatırlıyormusun sonunu değiştirmediğimiz filmleri

Hayatın gerceğidir sandığımız kabullenilmiş yenikliği 

Bir ağızdan söylediğimiz en kahraman cenkliği, 

Büyürken vazgectiklerimizi yada vazgeçittirdikleri seyleri, 

Ne Olacak Halim...

Çabuk mu büyüdük dersin 

Biliyorum..

NE Olacak Halim...

Sen bu satırları okurken, ben nerde olacağım kim bilir.

Neleri bırakmış olacağım birde, 

Ne aşkları 

Ne başlangıçları 

Ne ayrılıkları tıpkı senin gibi.

Biliyormusun...

Tek sorum var kendimle şimdi

Ahhh 

Ne Olacak Şimdi Halim....', 'Sen bu satırları okurken ben cok uzaklarda olacağım... Böyle başlardı bütün bildiğimiz mektuplar,  Biliyormusun? Bu ikimizin hikayesi,  Şu a...', ARRAY['Türk Edebiyatı','Şiir','İclal Aydın']::text[], 8.5, '{"poet":"İclal Aydın","poet_slug":"i-clal-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ne-olacak-halim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fotoğraf', 'fotograf-alisan-satilmis-lonzr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çehrende koparılmış

Bir gül tebessümü

Umudu yorgun düşmüş

Birine uzanmış, sunulmuş

Ama nedense mutlu olamamış

Fotograf! 

Hüznün resmedildiği

Mutlu yada mutsuz

Yaşanmış bir anın tadı

Bakışın ilk günkü gibi

Dolu, dolu

Ama o ne? Gözlerin va saçların

Yaşanmışlığın hayal kırıklığı

Savruluyor ufkumda

Darma dağınık 

Alevde yanıp yok olan

Fotografın gibi...', 'Çehrende koparılmış Bir gül tebessümü Umudu yorgun düşmüş Birine uzanmış, sunulmuş Ama nedense mutlu olamamış Fotograf!  Hüznün resmedildiği...', ARRAY['Türk Edebiyatı','Şiir','Alişan Satılmış']::text[], 8.5, '{"poet":"Alişan Satılmış","poet_slug":"alisan-satilmis","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/fotograf-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyordum', 'seni-seviyordum-i-clal-aydin-hjrni', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana uzak kentlerden birinde zamanın bir yerinde seni ve senli günleri anımsattı akşam güneşi...

Onca zamanın üstünde eskimeyen bir düşüncesin şimdi

İnsan hergün anımsar mı aynı gözleri 

SENİ SEVİYORDUM ve senin haberin yoktu 

Saçlarını izliyordum uzaktan, kulağının arkasına düşüşü ve burnun, herkesten başkaydı işte...

Güldüğün zaman yukarıya bakardın; 

Yukarı kalkan başın ve gülen gözlerin vardı...

Ne güzeldiler sen bilmiyordun...

BEN SENİ SEVİYORDUM...

Kalbime sığmıyordu aklımdan geçenler 

Duvarlara, vitrin camlarına, kaldırımlara çarpıyordu

Geri dönüyordu, çoğalarak

Senin sesini duyduğum masalarda erteliyordum herşeyi, herseyi erteleyişim oluyordun 

Kalp ağrısı oluyordun, 

Birlikte soluduğumuz sokak isimleri oluyordun, 

Mevsimler değişiyor ve büyüyorduk, 

Dönemeçler geçiyor, köprüler göze alıyorduk ve bazen tekin olmayan suların üzerinden atlıyorduk

Cesurduk...

Ufuk çizgisi maviydi, gün batımı hep turuncu ve kırmızıydı bütün karanfiller...

Ben SENİ SEVİYORDUM sen bilmiyordun...

Sevinçlerim oluyordun arasıra sen hiç bilmiyordun

Sonra herhangi biri oldun, bütün sevinçlerim bittikten sonra

Yağmurlar yağdı, serin haziran akşamları

Derken bir gün uzaktan gördüm seni...

Saçların bana inat başın herseye meydan okuyarak işte yine aynı 

Kalbimi acıttı her zamanki gibi...

Değiştik sanıyordum ve sen yine bilmiyordun 

Şimdi bunları anlatsa sana birileri kim bilir yada boşver bilme en iyisi...', 'Sana uzak kentlerden birinde zamanın bir yerinde seni ve senli günleri anımsattı akşam güneşi... Onca zamanın üstünde eskimeyen bir düşünces...', ARRAY['Türk Edebiyatı','Şiir','İclal Aydın']::text[], 8.5, '{"poet":"İclal Aydın","poet_slug":"i-clal-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/seni-seviyordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyümese miydim?', 'buyumese-miydim-alisan-satilmis-jmp8a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sözüm ona büyüdüm ben.

Hala yırtmaçlı ceket

İspanyol paça pantolon giyiyorum

Ya ayakkabıları? 

Hala derin kuyu lastiği

Ve okuduğuma göre

Miladdan önca yalın ayakmış 

İnsan! 

Büyümese miydim? 

Diş ağrısı sözler arasında

Akvaryumdaki balık

Kafeste bir kuş

Kaybolmazdım belki

En güzeli ben zizin adnınıza

Aklımı takıp uçurtmalar kanadına

Mektepe gidip okuma yazma öğreneyim

Bir lisan bir insan

Hadi ordan sende şizofren! 

Kahkahalarda boğulmak

Anlaşılmazlık...Unutulmak

Bakışlarda hep yargılanmak

İşte bu benim derdim

Sözüm ona büyüdüm ben

Fransızcada biliyorum gayri

Ama fotogreflar küfrediyor bana

Büyümese miydim?', 'Sözüm ona büyüdüm ben. Hala yırtmaçlı ceket İspanyol paça pantolon giyiyorum Ya ayakkabıları?  Hala derin kuyu lastiği Ve okuduğuma göre Mil...', ARRAY['Türk Edebiyatı','Şiir','Alişan Satılmış']::text[], 8.5, '{"poet":"Alişan Satılmış","poet_slug":"alisan-satilmis","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/buyumese-miydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türküler be Güzelim', 'turkuler-be-guzelim-alisan-satilmis-xikyb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bilmelisin bu yorgun gözlerin

Seyrinde depreşen

Ama dudaklardan dökülmeyen

Sözlerin adı nedir? 

Şarkılar söylemek istediğim

İçliliğime kanıpta aldanma sakın

Samun ekmek gibi açlığım

Şiir hiç değil bu vakit

Efsane günlere

Yürek mahkum olurken

Türküler be güzelim

Bana böyle dokunan', 'Bilmelisin bu yorgun gözlerin Seyrinde depreşen Ama dudaklardan dökülmeyen Sözlerin adı nedir?  Şarkılar söylemek istediğim İçliliğime kanıp...', ARRAY['Türk Edebiyatı','Şiir','Alişan Satılmış']::text[], 8.5, '{"poet":"Alişan Satılmış","poet_slug":"alisan-satilmis","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/turkuler-be-guzelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşlandı Kafa Kağıdımız', 'yaslandi-kafa-kagidimiz-alisan-satilmis-jkyaf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yediden onsekize gelinceye dek

Kakalı oyuncaklar sevdik hep

Diş biledik, kin tuttuk

Yamalıksız pantolon, önlük giyen

Okul önlerine Ford granada ile bırakılan

Burjuva veletlerine tükürerek

Derken bir anarşi talaşı

Aklımız ermeye başladı

Yetmişlerden...seksenlere geldik

Saçlarımız yine alabulus kesikti hep

Olmadı gıran tuvalet bir elbisemiz

Rugan pabuçlar yerine

İşte öyle ayakkabılar giyerdik

Bir haki parkeyle yetindik

Genç kızlarla flört takılmadan

Kitaplar sevdik..sonra silahlar edindik

İç savaş kanıyla beslenirken namlular

Öldük öldük dirildik..

Mutlu olmadığımızı bile bile...

Dişlerimiz arasında çiçekler çiğnedik

Bir parantez açtık(-)  doğum ve ölüm

Ara kesitti yitti teneşir suyuyla

Akan gençliğimiz

İşte doksanlara geldik

Delinip fişlendi, sonra yaşlandı

Kafa kağıdımız', 'Yediden onsekize gelinceye dek Kakalı oyuncaklar sevdik hep Diş biledik, kin tuttuk Yamalıksız pantolon, önlük giyen Okul önlerine Ford gran...', ARRAY['Türk Edebiyatı','Şiir','Alişan Satılmış']::text[], 8.5, '{"poet":"Alişan Satılmış","poet_slug":"alisan-satilmis","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yaslandi-kafa-kagidimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşanan', 'yasanan-alisan-satilmis-me6xt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ölür sevdalarım

Gün batımı..gün doğumu

Pusuya düşmüş gözlerimde

Yol verin dağlar yol verin bana

Kanatlarım kırıktı

Bakışlarım durgun

Mevsimler mevsim içinde öldüğünde

Bulur işte o zaman

Bende birşeyler her yan

Suskuluk, bakışmak, konuşmak

Ne varsa yaşanan

Dolu dolu usulca yavaş

Elveda demeden

Bir düğme ilikleme zamanında

Yok olup gitmiş

Say ki yar dudağınca güzel olan

Yol verin dağlar yol verin bana

Yürek vurur yüreğimle yan yana

Hasretim çiğdem kokusuna

Nergis bakışına

Alıcı kuşların kanat vuruşuna', 'Ölür sevdalarım Gün batımı..gün doğumu Pusuya düşmüş gözlerimde Yol verin dağlar yol verin bana Kanatlarım kırıktı Bakışlarım durgun Mevsiml...', ARRAY['Türk Edebiyatı','Şiir','Alişan Satılmış']::text[], 8.5, '{"poet":"Alişan Satılmış","poet_slug":"alisan-satilmis","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yasanan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdigimle...', 'sevdigimle-neslihan-ayakta-wdb9y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gozlerimi kapatsam da

Yaninda olsam bir an

Kalp atislarimizin melodisinde

Dogaya biraksak kendimizi

Sehvetimiz kleopatranin dogdugu yerde dogsa

Kimsenin dokunamadigi bir ask

Gizli merdivenimizden insek duygusallik denizimize

Elele, heyecan dolu

Yanagina bir opucuk kondursam

Ve o an ikimizde gokyuzune baksak

Bir yildizin kaydigini gorsek

Ayni seyi diledigimizi bilerek

Gozgoze gelip gulumsesek

Sonra oylece sarilip kalsak

Birakmamacasina

Gerisi, iyilik, guzellik...', 'Gozlerimi kapatsam da Yaninda olsam bir an Kalp atislarimizin melodisinde Dogaya biraksak kendimizi Sehvetimiz kleopatranin dogdugu yerde do...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevdigimle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ask Sask', 'ask-sask-neslihan-ayakta-noz3s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Askin alevi sarmissa tum bedenini, 

Kime ne senin hayat felsefenden.

Saskinlik icinde toparlayamiyorsan dagittiklarini

Birak gitsin, 

Saskinlik herkese yakisir! 

(29.03.99)', 'Askin alevi sarmissa tum bedenini,  Kime ne senin hayat felsefenden. Saskinlik icinde toparlayamiyorsan dagittiklarini Birak gitsin,  Saskin...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ask-sask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Danset Benimle', 'danset-benimle-neslihan-ayakta-poe60', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni dusluyor gelecegim

Yuregime hapsoldugum anlarda

Yildizlara dil yapiyorum

Icindeki melodiyi dinletiyorlar bana

Kalabaliklarda yalniz kalmak

Hayallere mahsussa

Yagmur damlam

Gozgoze geldigimizde

Karanlik sokaklarda

Ay isiginda danset benimle

Kelebekler gezerken hucrelerimizde

Yagmur bulutlari her neredeyse

Hayallerimiz gozlerimizde parlarken

Inci tanem, hazinem

Ellerimi uzattigimda 

Karanlik sokaklarda

Ay isiginda danset benimle

Okyanuslar varken aramizda

Ruzgarin ugultusu

Dalgalarin hisirtisi 

Melodimiz olsun sevgilim

Sadece kapat gozlerini

Ve dolunayda

Danset benimle

(11.11.01)', 'Seni dusluyor gelecegim Yuregime hapsoldugum anlarda Yildizlara dil yapiyorum Icindeki melodiyi dinletiyorlar bana Kalabaliklarda yalniz kal...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/danset-benimle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gozlerimden Sev Beni', 'gozlerimden-sev-beni-neslihan-ayakta-z1zqo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gercekleri sevmelisin; 

Benim gerceklerim gozlerimde, 

Gozlerimden sev beni! 

Anlamalisin sevginin degerini, 

Gunesin dogdugu yerde yasamalisin

Hayaller kadar uzak belki

Ama gozlerim kadar gercektir inan! 

Bir kac sayfa cevirecegim seninle, 

Anlasilmayacak kadar ozel

Ve unutulmayacak kadar degerli olacaklar.

Bir kac gulumseme olacak

Sevgimizin sahitleri, 

Zaman denen cilginligi

Kum tanelerinin mecburiyetinde yasayacagiz.

Ve sen uysal bir ruzgar gibi seveceksin beni.

Gercekleri yaratan sensin! 

Gercekleri sevmelisin: 

Benim gerceklerim gozlerimde, 

Gozlerimden sev beni! 

(23.02.99)', 'Gercekleri sevmelisin;  Benim gerceklerim gozlerimde,  Gozlerimden sev beni!  Anlamalisin sevginin degerini,  Gunesin dogdugu yerde yasamali...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gozlerimden-sev-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melekler Agladi', 'melekler-agladi-neslihan-ayakta-ms4ml', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgiyi tanimak isteyen

Melekler vardi bir gun.

Ve ertesi gun, 

Agladilar! 

Cunku sevgi olmustu

Bir zalimin kollarinda..

Gururdu, inkardi

Zalimi zalim yapan, 

Yalanlardi cogu zamanda! 

Sebep uretmek kolaydi

Ve hep bir sebep olmasi sartti.

Yalanlar okundu, 

Mumlar yakildi

Ve melekler agladi..

(09.01.00)', 'Sevgiyi tanimak isteyen Melekler vardi bir gun. Ve ertesi gun,  Agladilar!  Cunku sevgi olmustu Bir zalimin kollarinda.. Gururdu, inkardi Za...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/melekler-agladi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygu Denklemi', 'duygu-denklemi-neslihan-ayakta-7z77h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gunler geciyor

Haftalar, aylar

Belki de yillar

Ne onemi var 

Bir omur gecmiyor mu sonucta

Ask teget geciyor yuregimden

Karesini, kupunu aliyorum duygularimin

Elde var kocaman bir yalnizlik

Sonsuzluk isaretine bakip gulumsuyorum

Dogru denklemi bir gun kuracagim

Gunler gecmeye devam ediyor

Ben hala yalnizim.

(28.05.01)', 'Gunler geciyor Haftalar, aylar Belki de yillar Ne onemi var  Bir omur gecmiyor mu sonucta Ask teget geciyor yuregimden Karesini, kupunu aliy...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/duygu-denklemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aska', 'aska-neslihan-ayakta-8o9a6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir bilmeceydi askimiz

Ne sen bilebiliyordun cevabi

Ne de ben

Ip uclarini birlestirerek ilerliyorduk

Bir sey vardi ki asikar

Ayni yonde degildik

Bana verdigin ip ucu kesilmisti adeta

Benimkileri tutamiyordun

Ya da suclu sen degildin

Veya ben

Cunku olmuyordu iste

Istesekte ne sen bana

Ne de ben sana 

Ulasamiyorduk

Ne cok yon vardi

Kuzey, guney, dogu, bati disinda

Unutmustuk ya da hatirlamak

Istemezcesine umursamiyorduk matematigi

O nokta icin sonsuz secenek vardi

Hazir degildik aska! 

(18.06.01)', 'Bir bilmeceydi askimiz Ne sen bilebiliyordun cevabi Ne de ben Ip uclarini birlestirerek ilerliyorduk Bir sey vardi ki asikar Ayni yonde degi...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/aska-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnizligim Kiskansin', 'yalnizligim-kiskansin-neslihan-ayakta-qrcao', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ruzgara germek istiyorum gogsumu

Kollarimi uzatmak goge

Ya bulutlardir carem ya kuslar

Ya da o erisilmez yildizlar

Deliksiz bir evrendeyim

Ucsuz bir bosluk

Gozlerimden yagmur ciseliyor

Ben islaniyorum

Nefesim firtinam oluvermis

Yalnizligim beni isitmiyor

Eh dolunay, eh sinem

Ey sevgili, ey can

Bana bir selamini ilet

Yalnizligim kiskansin! ! ! ! ! ! ! ! 

(22.02.02)', 'Ruzgara germek istiyorum gogsumu Kollarimi uzatmak goge Ya bulutlardir carem ya kuslar Ya da o erisilmez yildizlar Deliksiz bir evrendeyim U...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yalnizligim-kiskansin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ask=Su', 'ask-su-neslihan-ayakta-zsdny', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gemiye bindim

Cok kalabalik

Icecek bir bardak su yoktu

Bir adaya gittik

Cok kalabalik

Icecek bir bardak su yoktu

Bir ruya gordum

Karsi kitadaydim

Icecek bir bardak su yoktu

Gittim gezdim dunyayi

Onumuze bir bardak su koyan olmadi

Sokagima dondum

Sana geldim

Ictim suyumu kana kana! 

(24.07.00)', 'Bir gemiye bindim Cok kalabalik Icecek bir bardak su yoktu Bir adaya gittik Cok kalabalik Icecek bir bardak su yoktu Bir ruya gordum Karsi k...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ask-su-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eksik', 'eksik-neslihan-ayakta-987qe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sanki bes yildizli bir oteldeyim

Otel colun ortasinda

Eksiksiz sanki

Kalbimi doyuramiyor sadece

Ailem disinda 

Etrafta insan yok

Aldanma onlar yabanci bana

Neden yuregim ozleminle agliyor

Ey dunua verdigini almayi

Neden bu kadar seviyorsun

Aliskanliklardan kurtulmak zordur

Bilmez misin

Sanki bir sarayda besliyorsun beni

Unuttugun bir sey yok mu sence

Icimde ki ben hep sanslisin diyor

Bir cok insandan cok daha sanslisin

Diyorum ya eksiksiz sanki

Kalbimi doyuramiyor sadece....

(08.05.01)', 'Sanki bes yildizli bir oteldeyim Otel colun ortasinda Eksiksiz sanki Kalbimi doyuramiyor sadece Ailem disinda  Etrafta insan yok Aldanma onl...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/eksik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk için', 'ask-icin-salih-ozalasan-xtwoi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Neler yazdım, neler yaşadım, aşk''a dair

Korkuları, hasreti, özlemi, vesair

Sevmeyeceğim dedim, 

Bazende aptalca aşk dediğin nedir

Gel görki yüreğimde 

Hep yaralar aşk''a dair

Kapanmadı hep kanıyor için için

Sevdalara şarkılar yazmak rutin oldu benim için

Yapamadım hayatım geldi geçti bir seçim

Neler kaybetmedimki ben umutsuz aşk''lar için

Geceler boyu ağlamalar hep benim için

Sanki vefasız sevgiler benim için 

Sevmesinimi bilmiyorum, 

Yoksa vakitmi geç sevgi için

Sevgililer mi ağlatan

Benmi doğmuşum ağlamak için

Yüreğime bakıyorum

Herşeyini vermiş aşk için

O zaman bana hasret bana özlem ne için

Sevgiler bana zalim 

Sevgiliye çıkmaz hiç sesim

Bir gün belki sevgiliye seni sevdim

Demeye fırsat kalmadan bitecek son nefesim

Kimbilir belkide seni seviyorumu duymadan

Gelip bulacak beni bir anda ecelim

Ama olsun ben yinede demeyeceğim

Bırakın sevmekten vaz geçelim

Aşk ağlatır belki yoksa karşılığı

Yaşam aşktır, yinede onu seçelim

Sevmek olsada gençliğime bedelim

Ağlarken, kahrolurken, son nefeste

Son sözüm; haydi yine sevelim

Y.Tarihi 27-11-2002 saat 01.16', 'Neler yazdım, neler yaşadım, aşk''a dair Korkuları, hasreti, özlemi, vesair Sevmeyeceğim dedim,  Bazende aptalca aşk dediğin nedir Gel görki ...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ask-icin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kış gitmeden yaz geldi', 'kis-gitmeden-yaz-geldi-mansur-balci-xayi0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dağın hareminde doğan çocuklar

dağın eteğine gömüldüler

acıyı soğutur diye sığınmıştık dağlara

yaşadıkça yalınlaştı acılarımız

nemini bulunca yumuşar sanarak

çok uzun bekledik toprağın devrilmesini

aklımızı tütsüleyip ceylan yavrularıyla

düşlerimizden yollar geçirdik

sonra yollarda dolaştırdık düşlerimizi

çalınır israfilin bakır borusu diye

ipek bir heceyle açmıştık tarihin penceresini

adı hiç duyulmayacak tuzaklardan öğrenip

adı duyulmamış tuzaklarda uyuduk

yıllarca yağmur bekledik göllerin ortasında

ıskalamasın geceleri ay bizi diye

güneşe uzattık kara ağaç gölgesini

içimizde şiirler, türküler dolaştırıp yatıştık

anladık ki her ağacın mülkü gölgesi kadar

anladık ki eskiden dağların bir gücü varmış

dağların eteğine gömülmeyen çocuklar

yol yorgunu ve sıkılgan elleriyle

gelip şehrin girişini yumrukluyorlar

dağın cevabını taşıyan doğu döğmeleriyle

çok uzaklardan bakarak yalnızca konuştular

         eskiden güneşe durmanın bir gücü vardı

         güneşi ıskaladığımız sabahlarda anladık

         kara ağaç gölgesinde toprak döl vermez

bildik.her ağaç toprağının mülküdür

dağın haremine inen su kesilince

fırtına ve çamur toparlar otağını

söz yalpalar geri döner, barut kokusu susar

söz zirveden iner, kale burçları büyür

söz alınıp verilir, kıble yönünü bulur

son sözler yorumlanmaz, rahlede açık kalır

bildik.her ağacın mülkü toprağı kadar

dağın haremine inen su kirlenince

seni ölmeden önceydi, bildik

bu dünyadan sağ kurtulan olmamış

her taşın yüzü vardır, doğru yerden bakarsak

eskiden taşa bakmak, bir hüner meselesiymiş', 'dağın hareminde doğan çocuklar dağın eteğine gömüldüler acıyı soğutur diye sığınmıştık dağlara yaşadıkça yalınlaştı acılarımız nemini bulunc...', ARRAY['Türk Edebiyatı','Şiir','Mansur Balcı']::text[], 8.5, '{"poet":"Mansur Balcı","poet_slug":"mansur-balci","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/kis-gitmeden-yaz-geldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fare', 'fare-mansur-balci-twlt9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bu karanlık ormandan çıkan kim

kim bu karanlık ormandan atılan atlı

koynumdan fırlattığım beyaz flamalarla

herkes nereye koşuyor, atları yoran kim

mevsimler dönse de peş peşe

barbar güzellikte toprak tav tutmaz

büyüsü dağılmış saçlarını kızıla boyasan

kamaşan ayaklarını yıkamak gibi birşey

boşluğa bırakılmış ölümden,  bizi korkutan ne

bir bilgisayar dosyasıyla kopardım gidiyorum ipimi

küçük bir click! sesi düşlerimi yorumlayan

cebinize bıraktığım e-mailimi unutup

sanal bir ormandayım tutan kim beni

beni kim ormanın kapısına mühürleyen

arkamdan gelen metalik ses kimin

otların terinde yorulan serkeşliğimi giyindim

kim bilir eğrelti otların yerini ormanda, sor

herkes kırmızı başlıklıysa, kurt olan kim

ormanın kıyısında duranlar, beklenen ne

devletin şahsi dosyası kadar karışık yüzleriyle

bir bilgisayar tıkırtısı kadar soğuk

kızıla boyanmış kadınların saçlarına dalarak

izimi süren kim, dünya olan içimdeki boşlukta

neden orman diyorlar, ışığı yutan coğrafyadayım

üst üste yığılmış çocuk başları, her adım çamur

teravihler, istavrozlar, uçuklamış dudaklar

ortası delik bir taşın altında dinlenen

delik deşik bir yaprak olarak şair

her sayı kendi öncesini tekrarlar diye

her sayıyı sonrasına yolculuk sanarak

her küfür kendisini doğrular, bildin

gırtlağına takılan lokmaların meridyenleri için

diyetini öde

üretim hatası olan boğazından inmiyor kelimeler

öde

bir bir çekilirken kelimelerle kehribar dilinden

kimin mührü bu, ormanın kapısında alnımıza vurulan

ölümü tatmamış bıçak kadar bakir şiir

cinayetlere doymuş bir kılıç kadar parlak söz

ormanın gövdesine su veren ipek

göçüp gitmiş şairlerin anısını kanatıp dururken

kavak, çınar, zerdali, bataklık otu

kim demiş burası için orman, yakından yangın yeri

koynumda kehribar yalnızlığımı taşıyorum

boynumda tarihin mührü yok artık

sanal bir alemdeyim, sadist bir fare dolaştırıyorum

                    çünkü bugüne verdiğim cevap şu

                    param parça mekanlarda büyüyen trajik acı

                    umudu diri tutmak için beslenen öfke

                    ormanın tarihi yapılırken bekleyen sessizlik

                    yangınları yangınlarda söndürün, iktidarı yakın

                    ormandaki mührün anlamı budur', 'bu karanlık ormandan çıkan kim kim bu karanlık ormandan atılan atlı koynumdan fırlattığım beyaz flamalarla herkes nereye koşuyor, atları yor...', ARRAY['Türk Edebiyatı','Şiir','Mansur Balcı']::text[], 8.5, '{"poet":"Mansur Balcı","poet_slug":"mansur-balci","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/fare-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne Duy Sesimi', 'anne-duy-sesimi-selvi-celik-7s5k4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senin yanındayken, 

Ağlamayı bile beceremezdim, 

Gözlerimden akan yaşlar  utanırdı.

Tane tane süzüle süzüle dökülürdü.

Şimdi sellere karıştı durmuyor anne.

Sessizliği inletiyor yırtıcı sesim.

Sözüm feryada karışı dinmiyor anne.

Göğsümde ateş volkan oldu taşıyor, 

Vucudumu alev alev yakıyor anne.

Emanet ettigin sevğiye

Íhanet ettim geri veremem anne.

Bunda benim şucum yok.

Caldılar sevgilerimi geri bulamadim anne.

Son kez birşey verirmisin istesem anne.

Dinmeyen isyanımı, göğsünde ağlarken

  saçlarımı oksayarak son nennini söyleyip

   sustururmusun anne.

Seni hüsrana ugratmak istemezdim anne.

Cınar ağacı gibi bildigin yavrun yıkıldı, 

Ne yaprakları yeşerdi gönlünde, 

Nede gölgesi göründü güneş altında.', 'Senin yanındayken,  Ağlamayı bile beceremezdim,  Gözlerimden akan yaşlar  utanırdı. Tane tane süzüle süzüle dökülürdü. Şimdi sellere karıştı...', ARRAY['Türk Edebiyatı','Şiir','Selvi Çelik']::text[], 8.5, '{"poet":"Selvi Çelik","poet_slug":"selvi-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/anne-duy-sesimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıkıldım', 'yikildim-selvi-celik-2810y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Daglarin tasi idim kirilmazdim.

Cinar agaci gibi yikilmazdim.

Sonu olmayan yollar gibi bitmezdim.

Anlamadan dinlemedim yikildim.

Yürekliydim yigitler misali.

Gururluydum baba yüregile.

Peflihandim gücümle.

Korkusuzdum ölümsüz gibi.

Anlamadan dinlemeden yikildim.

Seller gibi cosardim yeller gibi eserdim.

Nehirlerin suyuydum akardim.

Gecelerin yildiziydim parlardim.

Günes gibi yakar, ay gibi dogardim.

Anlamadan dinlemeden yikildim.

Rüyalari gercek sayardim.

Umutlarim hic bitmeden yasardi.

Hayalleri kurmasini bilir severdim.

Anlamadan dinlemeden yikildim.

Gonca gibi acmadan kokardim.

Derdi gami hic sayar, 

Aglamayi bilmeden gülerdim.

Anlamadan yikildim..', 'Daglarin tasi idim kirilmazdim. Cinar agaci gibi yikilmazdim. Sonu olmayan yollar gibi bitmezdim. Anlamadan dinlemedim yikildim. Yürekliydim...', ARRAY['Türk Edebiyatı','Şiir','Selvi Çelik']::text[], 8.5, '{"poet":"Selvi Çelik","poet_slug":"selvi-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yikildim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erkekler aglamaz sözün sakin inanma', 'erkekler-aglamaz-sozun-sakin-inanma-ahmet-etik-ggcqb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gideceksen bakma gözyaslarima

Git artik kendi yoluna

Kalayim kanayan yüregimle tek basima

Erkekler aglamaz sözüne sakin inanma

Dönüp bakma sakin ardina

Bende aramayacagim seni bir daha

Unutacagim elbette seni

Dünya batinca

Yeminliyim sevmiyecegim bir daha

Düsmeyecegim bir kadinin tuzagina

Tüm güzelikleri öldürdü bu sevda

Kötüyüm kötü gelme sakin yanima

Gideceksen bakma gözyaslarima

Git artik kendi yoluna

Kalayim kanayan yüregimle tek basina

Erkekler aglamaz sözün sakin inanma', 'Gideceksen bakma gözyaslarima Git artik kendi yoluna Kalayim kanayan yüregimle tek basima Erkekler aglamaz sözüne sakin inanma Dönüp bakma s...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Etik']::text[], 8.5, '{"poet":"Ahmet Etik","poet_slug":"ahmet-etik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/erkekler-aglamaz-sozun-sakin-inanma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kum Saati', 'kum-saati-halide-nusret-zorlutuna-h2rem', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir kum saatinde erimiş gibi, 

Zaman parça, an parça parça.

Hangi zalim oktur delen bu kalbi? 

Göğsümden dökülen kan parça parça.

Benim değil artık, yaşamıyor dün.

Doğar mı  doğmazmı beklediğim gün? ...

Bu yalan dünyada ne var ki bütün, 

Huzur parça parça, can parça parça.

Yaşanmamış ömre yan parça parça! ...', 'Bir kum saatinde erimiş gibi,  Zaman parça, an parça parça. Hangi zalim oktur delen bu kalbi?  Göğsümden dökülen kan parça parça. Benim deği...', ARRAY['Türk Edebiyatı','Şiir','Halide Nusret Zorlutuna']::text[], 8.5, '{"poet":"Halide Nusret Zorlutuna","poet_slug":"halide-nusret-zorlutuna","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kum-saati-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Gel Ya Haber Gönder', 'ya-gel-ya-haber-gonder-hafize-zuluflu-cba7f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Farkında değilsin belki

Ama

Ankara’daki herşeyin

Çok özledi seni

Hatıralar bırakmıyor yakasını

Bakmasa oturduğun yöne

Tutsa kendini

Yüzün gülümsüyor

İşte şu köşeden

Kapının arkasından geçerken

Sarılışına takılıyor ayağı 

Sendeliyor

Bilemezsin nasıl zorda

İçine çakılmış bir çivi gibi duruyor

Geliyorum deyip de gelmeyişin

Hadi kalk gel

Ya da bir haber gönder

Rahatlasın içi', 'Farkında değilsin belki Ama Ankara’daki herşeyin Çok özledi seni Hatıralar bırakmıyor yakasını Bakmasa oturduğun yöne Tutsa kendini Yüzün gü...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ya-gel-ya-haber-gonder-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz', 'deniz-murat-tali-ti9x5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gittiğin ülkelerde deniz yok 

kalabalığa sarmış tekneler arasında 

yitip gitmiş yansımaları denizin.

Bak insanlar evlerini sandallara kurup 

taşımışlar denize

deniz o eski deniz değil

Su da o eski su 

ay bile yitik duruyor gecede emanete vermiş ışığını

vestiyeri binlerce bulut kapıcısı sadece bir yıldız

(ışığınızı yitirmeden yaşama dair olmanız dileğiyle...)', 'gittiğin ülkelerde deniz yok  kalabalığa sarmış tekneler arasında  yitip gitmiş yansımaları denizin. Bak insanlar evlerini sandallara kurup ...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/deniz-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sensiz Yaşıyorum', 'seni-sensiz-yasiyorum-huseyin-ucak-2x1ku', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gün daha başlıyor sensiz

Izdıraplar çileler bitmeksizin

Seni unutmak mümkün olsa gülüm

Olmuyor yapamıyorum sensiz

Bilmeden aşk şarabını içmişim

Çare bulamıyorum bu derde

Aşkının serhoşuyum

Kaybettim benliğimi

Seni sensiz yaşıyorum gülüm

Ne olur anla beni

                              SENİ SEVİYORUM

                                      GÜLÜM', 'Bir gün daha başlıyor sensiz Izdıraplar çileler bitmeksizin Seni unutmak mümkün olsa gülüm Olmuyor yapamıyorum sensiz Bilmeden aşk şarabını ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Uçak']::text[], 8.5, '{"poet":"Hüseyin Uçak","poet_slug":"huseyin-ucak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-sensiz-yasiyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nankör', 'nankor-huseyin-ucak-pqzzi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne günler vardı mazide kaldı

Ne aşklar yaşandı

Sonunda çaresizce yarım kaldı

Sende artık mazide yaşıyorsun

Hep o aynı gülüş ve bakışlarla

Artık mazileri süslüyorsun.

Her an, her dakika hatta her saniye 

Seni düşünürdüm önceleri

Bu aralar demek ki her şey gibi 

Bende zamanla birlikte değiştim

Ve bir kalemle kalbimdeki

O eşsiz sevgine bir çizik atabildim

Hala gördüklerime inanamıyorum biliyormusun? 

Seni bir yabancının kollarında görünce

Yıkıldım kaldım inanamadım seni kaybetmeme

Seni başkasının yanında görmeye dayanamadım

Şimdi ise değerin yok gözümde

Ne yapsanda artık affetmem seni

Bilemiyorum belkide beni kıskandırmak için yaptın

Sevin artık sevine bilirsen

İstediğini yap

Gönlümdeki eşsiz sevgini sildin attın

Bundan sonra senin adın ay yüzlü değil

Bundan sonra senin adın nankör anlıyormusun

                       - NANKÖR -', 'Ne günler vardı mazide kaldı Ne aşklar yaşandı Sonunda çaresizce yarım kaldı Sende artık mazide yaşıyorsun Hep o aynı gülüş ve bakışlarla Ar...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Uçak']::text[], 8.5, '{"poet":"Hüseyin Uçak","poet_slug":"huseyin-ucak","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/nankor-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bu Şiiri Okurken', 'sen-bu-siiri-okurken-ahmet-selcuk-i-lkan-672qz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen bu şiiri okurken

Ben çoktan bu şehirden gitmiş olacağım

Artık ne özlemlerimi duyacaksın bıçak yarası

Ne de telefonların çalacak gece yarısı

Ve bu zavallı yüreğim olmayacak artık

Kaprislerinin hedef tahtası...

Seni sana

Beni bir akıl hastanesine

Bırakıp gideceğim bu şehirden

Nasılsa kavuşamadım sana

Nasılsa dudaklarının kıyısına varamadım

Nedense bütün çıkmaz sokaklar adresim oldu

Ve nedense bütün kırmızı ışıkları üzerime yaktın

Ne yaptımsa

Bir türlü sana yaranamadım

Artık adressiz

Işıksız

Ve öylesine ıssızım

Dünlerin kadar eskiyim

Verdiğin acılar kadar paslıyım

İşte çıkıp gidiyorum hayatından

Nasılsa fark etmez senin için

Belki çok şanslı

Belki de en yaşlıyım...

Artık

Pusulam hasreti

Saatim yalnızlığı

Ve takvimler sensizliği gösteriyor bana

Neylersin 

Yolcu yolunda gerek

Belki bundan sonra

Belki senden sonra

Adam olur bu “asi yürek”

Ve dersini alır da bu sevdadan

Bir daha 

Boyundan büyük denizlere

Asılmaz kürek

Yarın bu saatlerde

Ben yollarda olacağım

Sen kimbilir kaçıncı uykunda

Masal mavisi bir rüyada

Ve elbette o korsan yüreğin

Yine pusuda

Oysa

İlk defa sesimi duymayacaksın

Sitemlerin sahipsiz

Soruların cevapsız kalacak

Belki ilk defa içini kemirecek yokluğum

Tanımadığın bir koku içini saracak

Ve ilk defa kendinle hesaplaşacaksın

Ne oldu? 

Ne oluyor? 

Ne olacak? 

Sonra 

Bir gözün kör

Bir kulağın sağır

Bir ayağın kırık

Bir kolun kesik

Düşeceksin yollara

Yani baştan başa yarım

Yani baştan başa eksik

Bütün duvarlar üstüne yıkılacak

Belki ilk defa

“Unutuldum” diyerek için sızlayacak

Ve sen bu şiiri okurken

Ayrılığımız çoktan başlamış olacak

Belki de son tesellin

Sana yazdığım “bu son şiir” olacak

Ve kimbilir

Unutulmuş bir gecenin tam ortasında

Başucundaki bir radyoda

Uykusuz bir şair yüreğini çınlatacak

Ve bir daha fısıldayacak kulaklarına

Sana adanmış bu satırları

“Bütün şehirler uyur

İstanbul uyumaz

Ve birgün

Bütün sevenler unutur seni

Ama bu “şair yürek”

ASLA UNUTMAZ...”', 'Sen bu şiiri okurken Ben çoktan bu şehirden gitmiş olacağım Artık ne özlemlerimi duyacaksın bıçak yarası Ne de telefonların çalacak gece yar...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/sen-bu-siiri-okurken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masadakiler', 'masadakiler-ayse-coskun-qk663', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aynı masada oturuyor

Uğultulu tepe; baykuş

Yalnız çınar; eksik deniz

Yanlış yerlerde oturuyorlar

Baykuşun çınara

tepenin denize ihtiyacı var

Kendine olabilmek için

yüzünü suyuna döküp

kalbini okuyabilmek

kalbini okutabilmek için

Ayni maviye sarılıp

gizlice soyunabilmek için

Saydıklarım yetmedi mi

Hiç mi değil bir söz anlamı

Kalbimi acıtmak için çalıyor

en korktuğum şarkı; 

shape of my heart.', 'Aynı masada oturuyor Uğultulu tepe; baykuş Yalnız çınar; eksik deniz Yanlış yerlerde oturuyorlar Baykuşun çınara tepenin denize ihtiyacı var...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Coşkun']::text[], 8.5, '{"poet":"Ayşe Coşkun","poet_slug":"ayse-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/masadakiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kraliçe', 'kralice-ayse-coskun-vb60h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Savaş bitti

Ve biz sayfalar dolusu yenildik

Tutmaz eller ordusu

suskun diller korosu

Ölüm ve acıların taçsız kraliçesi

gene ağlamak ve gene suskun vedalar mı? 

Gün devrildi ellerimizden

güneş terkedildi

Kaf Dağı''nın ardında

yeşerecek ümit kalmadı

Öyle çöküverdi gece

hiç sis yok

herşey gerçek

Herşey çok net

herşey çok acı.', 'Savaş bitti Ve biz sayfalar dolusu yenildik Tutmaz eller ordusu suskun diller korosu Ölüm ve acıların taçsız kraliçesi gene ağlamak ve gene ...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Coşkun']::text[], 8.5, '{"poet":"Ayşe Coşkun","poet_slug":"ayse-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kralice-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıskanırım', 'kiskanirim-tuba-tutar-ve61c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kıskanırım nikotinle iyi geçinen dudaklarını

Kıskanırım sinendeki yarayı saran o buhuru

İsterimki sonsuzluğa uzanan sevgimde

Benim dudaklarım sarsın dudaklarını

Benim tenim ilaç olsun sinendeki yaraya

İsterimki içinde dörtnala ben koşayım

Kanat çırpan o ürkek kuş ben olayım

İsterimki sessiz çığlığımla

Gözlerimdeki süt buğusuyla

O kocaman yüreğinde her daim ben olayım

İsterimki ömrünce şiirlerim dağıtsın seni

İsterimki ömrünce beni yaşa', 'Kıskanırım nikotinle iyi geçinen dudaklarını Kıskanırım sinendeki yarayı saran o buhuru İsterimki sonsuzluğa uzanan sevgimde Benim dudakları...', ARRAY['Türk Edebiyatı','Şiir','Tuba Tutar']::text[], 8.5, '{"poet":"Tuba Tutar","poet_slug":"tuba-tutar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kiskanirim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderken', 'giderken-ayse-coskun-zmr78', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hoşgeldin''imi alır giderim

oda da müzik de senin olur

gözlerinde çayın buğusu kalır

özlediğin herşey zamansızca uçuşur

-hatırlamak istemezsin-

Yorgun bir sandalye üstü hırkası

Öylece bırakılmış, sabaha geceden iz

Dalgalı saçlarında billur ışık

yastığa düşen yüzün

Sessizce kıvrıldığım yanından

usulca kalkar giyinirim

Nota falan da gerek kalmaz

hoşgeldin''imi alır giderim.', 'Hoşgeldin''imi alır giderim oda da müzik de senin olur gözlerinde çayın buğusu kalır özlediğin herşey zamansızca uçuşur -hatırlamak istemezsi...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Coşkun']::text[], 8.5, '{"poet":"Ayşe Coşkun","poet_slug":"ayse-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/giderken-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yılbaşı Seramonisi', 'yilbasi-seramonisi-ayse-coskun-l100o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nasıl güzel yine gülen gözlerin

ve saçların halka halka omuzunda

Ne kadar kısa sürede ne çok uzamışlar

-beni sevmemenden nefret ediyorun

O''nu niye istediğini anlamıyorum-

Çayım soğudu, kalkıp gitmeliyim aslında

Herkes endişeli bir sessizlikle bana bakıyor

Öyle yabancıyım ki hepsine

bir zamanlar arkadaştık oysa

Şu darmadağın masanın başında

üzüntüyle ağlayacağım

Bütün yılbaşını da böyle geçireceğim

Sen O''nu düşüneceksin

ben seni düşüneceğim satır aralarında

Bu kafede bir çayla

en uzun oturma rekoru kıracağım

Yanından kalkmamak için ne gerekirse yapacağım

seni özlemek zorunda kalmamak için

senden ayrılmamak için.

O kıza yok olduğunu, gittiğini söyleyeceğim

O kızı kendi ellerimle öldüreceğim...', 'Nasıl güzel yine gülen gözlerin ve saçların halka halka omuzunda Ne kadar kısa sürede ne çok uzamışlar -beni sevmemenden nefret ediyorun O''n...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Coşkun']::text[], 8.5, '{"poet":"Ayşe Coşkun","poet_slug":"ayse-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yilbasi-seramonisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Körkütük!', 'korkutuk-abdulkadir-karaman-to7bg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sızılar ta derinden, karınca ölse kâlbim

Emelim yaşatmaktır, korkarım öldürmekten. 

Üzsem haksız birini, tirtir titrer her yerim.

Târifsiz zevk alırım, üzgünü güldürmekten. 

Ne anlamsız kin, garaz: ne mânasız dövüşmek! 

Güzellikler dururken, çirkine rağbet saçma! 

En güzel armağandır varlıklara sevişmek...

Kolaylamak nîmetken; zorlamak, zahmet saçma! 

Gözüm sevgi pınarı, göğsüm muhabbet bağı.

Bakarım sevgi ile, muhabbetle sararım

Ruhumdan doğar coşkun sevinçlerin ırmağı.

Kim sevgiye muhtaçsa bulana dek ararım. 

Her göz benim mihrabım, evimdir her kâlp benim 

Bir yol vardır erişen, ararım bıkmaksızın

Ben herkesi severim, olmasa hiç sevenim

İşlerim duygulara, bir daha çıkmaksızın. 

Şu pejmürde hâlime bakıp ta şaşırmayın

Bu rütbe, üniforma seçtiğim şekil değil. 

Sabır sonsuz deryâdır, yüklenip taşırmayın

Asıl olan sevgidir, bilinsin nâkil değil. 

Çok kötü olsa bile, kimseye hor bakamam

İyilik şiarımdır, neyse bilmem kötülük? 

Kâlp sevginin üssüdür; incitemem, yıkamam

Sarhoşum ben sevgiden, inanın ki körkütük. 

06/07/2001', 'Sızılar ta derinden, karınca ölse kâlbim Emelim yaşatmaktır, korkarım öldürmekten.  Üzsem haksız birini, tirtir titrer her yerim. Târifsiz z...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/korkutuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Hep Benimsin', 'sen-hep-benimsin-ali-tekinture-v5ye4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni benden alıp gittin sevgilim

Seninle yaşayan o can benimdir

Bir gece uykunda duyarsan bir ah! 

Acılı, hüzünlü o da benimdir

Ellere gitsen de elin değilsin

Ezelden ebede sen hep benimsin

Böyle inanmışım böyle bilinsin

Taktığın duvaklar tüller benimdir

Güzel gözlerinle baktığın yerde

Gördüğün hayaller, düşler benimdir

Sevmek bu, delice aşık olmak bu

Seninle var olan her şey benimdir', 'Beni benden alıp gittin sevgilim Seninle yaşayan o can benimdir Bir gece uykunda duyarsan bir ah!  Acılı, hüzünlü o da benimdir Ellere gitse...', ARRAY['Türk Edebiyatı','Şiir','Ali Tekintüre']::text[], 8.5, '{"poet":"Ali Tekintüre","poet_slug":"ali-tekinture","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-hep-benimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardelen', 'kardelen-ahmet-agdere-5eoje', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sorma hali; nasılım, iyi miyim diye, 

Tohumsuz bir ağaç gibiyim yeryüzünde. 

Mevsimleri şaşıran çiçeğe benzedim, 

Yazlarda öldüm, kışlarda geldim yeniye! 

Kar altındaki beni koklayıp öldürdün. 

Sızlattırdın ağlattın da düşmana güldün. 

Madem gidecektin ne diye aldın mührü; 

Ve benden ıraklardan ırağa sürdürdün!', 'Sorma hali; nasılım, iyi miyim diye,  Tohumsuz bir ağaç gibiyim yeryüzünde.  Mevsimleri şaşıran çiçeğe benzedim,  Yazlarda öldüm, kışlarda g...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kardelen-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birader', 'birader-osman-oztunc-8fhg5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hey güzel insan benim canım kardeşim! 

Tek tabancasın bu aralar

Dostların vardı senin, sevdiğin bir kız

Neredeler şimdi, neredeler

Bir sen ağlarsın birde martılar

Yalnızlığına senin

Fişlenmişsin, seni de bitirirler dostum, 

Haydutlar gezer bu şehirde

Sen benim çocukluk arkadaşımsın ulan, 

Sen gardaşımsın ulan

Seni bırakmam tek başına birader

Gel ölelim beraber

Bu şehir şehirlerin hayırsızıdır

Toprağı suyu değişmeli

İnsanı insanların uğursuzudur

Sonuna kadar dövüşmeli

Bir sen yanarsın birde namlular

Hürriyet sevdana senin

Mimlenmişsin, onlar seni ısırmadan

Sen onları yemelisin', 'Hey güzel insan benim canım kardeşim!  Tek tabancasın bu aralar Dostların vardı senin, sevdiğin bir kız Neredeler şimdi, neredeler Bir sen a...', ARRAY['Türk Edebiyatı','Şiir','Osman Öztunç']::text[], 8.5, '{"poet":"Osman Öztunç","poet_slug":"osman-oztunc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/birader-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilinmezlerden', 'bilinmezlerden-ahmet-agdere-w3pvx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Temizden hatıra kalan geriye; 

Uğruna can feda eden bedenle... 

Bilinmezlerde artık ruh ve o yar, 

Alış denilen yürekle birlikte! 

Dön desem, dönmez zaman ve sevgili; 

Ölmüşlerdir uzakta gizli gizli...

Nabız ile saatim öter tik tak; 

Deliler de söylenir sesli sesli! 

İbre yaşam,cevap yok yürekten, 

Yalvarır bileğe, ses yok bilekten. 

Olmuyor, olmayacak da sanırım, 

Rüya gecelerde çıkan bellekten... 

Ud sesi gelir uzaktan; dertliyim...

Mahpustayım, soğuk demirde elim! 

Ses yok yine gardiyandan bu gece; 

Anladım geleceksin benim yelim! ..', 'Temizden hatıra kalan geriye;  Uğruna can feda eden bedenle...  Bilinmezlerde artık ruh ve o yar,  Alış denilen yürekle birlikte!  Dön desem...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bilinmezlerden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmiş Sanıyordum Geçmişi', 'gecmis-saniyordum-gecmisi-umut-ulbegi-ilar7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bugün eskileri karıştırdım

sayfa sayfa seni okudum yüreğimde

seni kaybettiğim günün gecesinde

ellerimle gökyüzünü yırtıp

seni inkar edişimi hatırladım

Bugün eskileri karıştırdım

eskiler yepyeni oldu gözlerimde 

asırlar sonra lav püskürten yanardağlar gibi

seni sevdiğimi hatırladım.', 'Bugün eskileri karıştırdım sayfa sayfa seni okudum yüreğimde seni kaybettiğim günün gecesinde ellerimle gökyüzünü yırtıp seni inkar edişimi ...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gecmis-saniyordum-gecmisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarhoş', 'sarhos-omer-hayyam-wm14f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Testimizi kırdın, şarabımızı döktün

Korkarım ki tanrım sen de sarhoş oldun', 'Testimizi kırdın, şarabımızı döktün Korkarım ki tanrım sen de sarhoş oldun...', ARRAY['Türk Edebiyatı','Şiir','Ömer Hayyam']::text[], 8.5, '{"poet":"Ömer Hayyam","poet_slug":"omer-hayyam","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/sarhos-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Salomeye', 'salomeye-friedrich-nietzsche-orn8b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öyle bir hayat yaşadım ki

Cenneti de gördüm cehennemi de

Öyle bir aşk yaşadım ki

Tutkuyu da gördüm pes etmeyi de

Bazıları seyrederken hayatı en önden

Kendime bir sahne buldum oynadım

Öyle bir rol vermişler ki

Okudum okudum anlamadım

Kendi kendime konuştum bazen evimde

Hem kızdım hem güldüm halime

Sonra dedim ki "söz ver kendine"

Denizleri seviyorsan, dalgaları da seveceksin

Sevilmek istiyorsan, önce sevmeyi bileceksin

Uçmayı seviyorsan, düşmeyi de bileceksin

Korkarak yaşıyorsan, yalnızca hayatı seyredersin

Öyle bir hayat yaşadım ki, son yolculukları erken tanıdım

Öyle çok değerliymiş ki zaman

Hep acele etmem bundan, 

Anladım...', 'Öyle bir hayat yaşadım ki Cenneti de gördüm cehennemi de Öyle bir aşk yaşadım ki Tutkuyu da gördüm pes etmeyi de Bazıları seyrederken hayatı...', ARRAY['Türk Edebiyatı','Şiir','Friedrich Nietzsche']::text[], 8.5, '{"poet":"Friedrich Nietzsche","poet_slug":"friedrich-nietzsche","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/salomeye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mihrace', 'mihrace-i-brahim-yoruk-54ziw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seneler önce

güzel bir kız yaşardı bu köyde; 

adı Mihrace.

Ben ona, o bana aşıktı, 

dokunsam kırılır, öpsem aglardı.

Böğütlenler arsında usulca

göze çarpan kısık bir ışıktı; 

kaçar kovalanır, yorulmazdı.

Çocuktu oysa...

Eline elma şekeri yakışır

ve mavi elbisesi çok şıktı.

Gece olunca göremezdim ben onu

fakat hep geceleri büyürdü o; 

büyürdü, olurdu yürek kadar.

Sabahları üşürdü, tir tir olurdu bedeni, 

böğürtlen toplardı sepet sepet, 

sonra susardı, hiç konuşmazdı; 

gideceğimi seziyordu besbelli.

Konuşsa bir dert konuşmasa bir dert; 

konu gitmekten açılınca hiç suzmazdı.

beni katil ilan eder, kendisini ceset, 

belliki ölüler unutulunca ağlardı.

Beni kente uğurladı, kendisi köyde kaldı.

Sabahtı, üşüyordu mihracem; 

hoşçakal bile demedi, el bile sallamadı.

Farkettimde, gözleri uzun uznun ardımda kaldı', 'Seneler önce güzel bir kız yaşardı bu köyde;  adı Mihrace. Ben ona, o bana aşıktı,  dokunsam kırılır, öpsem aglardı. Böğütlenler arsında usu...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yörük']::text[], 8.5, '{"poet":"İbrahim Yörük","poet_slug":"i-brahim-yoruk","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/mihrace-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bir Kadınım', 'ben-bir-kadinim-yusuf-hayaloglu-tb3yj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kavrulur şu kanlı gözlerimde günler

    Akşamdan bir sancıyla

    Koklanmış bir gül gibi hayallerim ayak altında

    Yol vermez yol vermez ağlamaya gururum

    Yılların aynasında 

    Horlanmış vücudumda memelerim derin acıda

    Ben bir kadınım ben bir insan

    Taşırım karnımda paramparça can

    Bir yanımda cevahir, bir yanımda kan

    Bir yanım şiir destan, bir yanım kirli fistan

    Bir yanım güller açmış, bir yanım viran

    Savrulur şu tozlu saçlarımda rüzgar

    Çıldırtan bir hışımla

    Saklanmış bir sır gibi, şiirleri ateş hattında

    Dayanmaz dayanmaz bu baskıya yürürüm

    Sabrımın bir anında

    Elimin hamuruyla çeker giderim

    Canım burnumda

    Ben bir kadınım ben bir insan

    Taşırım karnımda paramparça can

    Bir yanımda cevahir, bir yanımda kan

    Bir yanım şiir destan, bir yanım kirli fistan

    Bir yanım güller açmış, bir yanım viran

    Yusuf Hayaloğlu', 'Kavrulur şu kanlı gözlerimde günler     Akşamdan bir sancıyla     Koklanmış bir gül gibi hayallerim ayak altında     Yol vermez yol vermez a...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Hayaloğlu']::text[], 8.5, '{"poet":"Yusuf Hayaloğlu","poet_slug":"yusuf-hayaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ben-bir-kadinim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çingene', 'cingene-ayse-coskun-nvak4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Unutturmaz düşlerini çingene

Ölüm benim en kutsal hazinem

Düşmek seçimine ortaklık

Bir soru işaretine cevap kader

Boğulmak yok, nehri taşıyor

Omuzlarının izleri, siyah

Bir sevince dair bildiği

Üç satır, hepsi gece

: Dayan Atlas''ın omzuna! 

Kimseler terketmeyecekmiş

Ah ne feci, inandırmıyor artık

Küllerini sakladığım bir koca dolap

köklerim topraksız, ağlamaksız hayat

Çekip gitmak istiyorum

Ama kimenin bana verebileceği

bir şansı daha yok

Bir daha 

O''nın kadar dostum olmayacağını sanmıştım...

Unutturmaz düşlerini çingene

ölüm benim en kutsal hazinem.', 'Unutturmaz düşlerini çingene Ölüm benim en kutsal hazinem Düşmek seçimine ortaklık Bir soru işaretine cevap kader Boğulmak yok, nehri taşıyo...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Coşkun']::text[], 8.5, '{"poet":"Ayşe Coşkun","poet_slug":"ayse-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cingene-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nezaketen', 'nezaketen-ayse-coskun-9792g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ölüyorum nezaketen

Bir ince ses çıkıyor boğazımdan

bir sahte tebessüm dudağımda

Biliyorum çünkü

Canım yanacak, üşüyeceğim

gülümsemem yüzümde donup kalacak.

Ölüyorum nezaketen

Ve bıktım ömrüm boyunca nezaketten

Kaba bir adam gibi 

boğularak, bağırarak ölmek

nasip olmadı işte.

Ölüyorum nezaketen

kibarca gülümseyerek.', 'Ölüyorum nezaketen Bir ince ses çıkıyor boğazımdan bir sahte tebessüm dudağımda Biliyorum çünkü Canım yanacak, üşüyeceğim gülümsemem yüzümde...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Coşkun']::text[], 8.5, '{"poet":"Ayşe Coşkun","poet_slug":"ayse-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/nezaketen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Für Elise I', 'fur-elise-i-ayse-coskun-jjzmb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Vedalaşıyorum sesinle

Senin şarkılarını dinleyerek

Son kez geziniyor parmaklarım yüzünde

saçlarında vesaire

Bir tren yolcusu gidiyor işte

''Sisler içinde kaybolur''; kim dediyse

özleyeceğim, hem de çok...

Sanırım çok az görüşeceğiz artık

Kızgınlığım geçti, sadece üzüntü

Başım ağrıyor, sanırım delirdim az önce

Umutsuz vaka, kayıp artık

Gamlı baykuş (!)   detlerim yeterince ağır

seni tanıyor olmak yetmez mi...

Sen de bağımdaş oldun demek

Ne garip bir konvoy bu; ben, sen ve o

tutkular aptallaştı

hiçbirşey anlamlı gelmiyor artık

Kitabı okudum

çok tanıdık bu yüzden bana

Üzüntüm sana, tesadüfe bak

Gerçekten en kötüsü iyi anlaşan iki bağımdaşmış

Renkler benziyor diye mi? 

senkrona da başlamıştık değil mi..

Çok tanıdık şey kaldı, 

Odamda yırtık kağıt parçaları

oysa hepsi senin için hazırlanmıştı

-molekül halindeler şimdi

halımın üstünde-

Sigara dumanı üstümü ört, 

koru beni kendimden lütfen...', 'Vedalaşıyorum sesinle Senin şarkılarını dinleyerek Son kez geziniyor parmaklarım yüzünde saçlarında vesaire Bir tren yolcusu gidiyor işte ''S...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Coşkun']::text[], 8.5, '{"poet":"Ayşe Coşkun","poet_slug":"ayse-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/fur-elise-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben de özleyeceğim seni', 'ben-de-ozleyecegim-seni-ayse-coskun-pqfv3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir kez daha çalıyor işte; 

aşk körlüktür

Dalga geçercesine mırıldanıyorum

Sıcak bir temmuz gecesi

buz gibi yalayıp geçiyor yüzümü sözler

sözlerin

yaşanan herşey.

Havai fişekler parlıyor dışarıda

Böyle kutluyorum yasımı

fişeklere karşı gözyaşları

buruk bir şarkıyla; 

aşk körlüktür.', 'Bir kez daha çalıyor işte;  aşk körlüktür Dalga geçercesine mırıldanıyorum Sıcak bir temmuz gecesi buz gibi yalayıp geçiyor yüzümü sözler sö...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Coşkun']::text[], 8.5, '{"poet":"Ayşe Coşkun","poet_slug":"ayse-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-de-ozleyecegim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk''ın yüreğimde hep seveceğim seni', 'ask-in-yuregimde-hep-sevecegim-seni-salih-ozalasan-sx673', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçimde bir hasret 

Dudağımda fısıltıya benzer bir isim

Gözlerimde gizliden bir ağlama

Titreyen elimde sana yazan kalemim

Önümde uzun bir sayfa

Sana yazıyorum, okuyamayacağın satırları

Noktalar virgüller karmakarışık

Anlatamıyorum isyan etmiş duyguları

Bana veda etmişsin ne yazayım

Neden niçin nasıl sorayım

Bugün karadan da kapkarayım

İstiyorum; seni seviyorum, gitme yazayım

Oysa çoktan çekip gitmişsin 

Yelken açmışsın başka sevgilere

Gözlerin parlıyor ışıl ışıl yüreğin neşeli

Sana bir haller olmuş onu tanıyıp onu seveli

Yüreğinde kalmamış eski aşkının

Bana dair bir nebze izleri

Elveda ile başlayıp hoşçakalla biten sözleri

Duymaktan çınlıyor kulak dipleri

İçimde bir yara kanıyor aşkının izleri

Ölmek ne hoş olurdu, ama olmuyor

Duymak bana veda eden sözleri

Yüreğimden kan damlıyor sarı sayfalara

Yazıyorum, farkında olmadan 

Asla okuyup göremeyeceğin sözleri

Aşka dair ne varsa kalacak bende izleri

Silinir sanma, kandı onun mürekkebi

Sana güle güle, bana hoşçakal

Aşkın yüreğimde hep seveceğim seni

Y.Tar.27-11-2002 Saat 19.27', 'İçimde bir hasret  Dudağımda fısıltıya benzer bir isim Gözlerimde gizliden bir ağlama Titreyen elimde sana yazan kalemim Önümde uzun bir say...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ask-in-yuregimde-hep-sevecegim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canan', 'canan-huseyin-i-lhan-xdjj1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Canan

Can karşılığında istemektir 

Bir tebessüm çalıp dudağından 

Adını aşk koyup 

Sonra zamana salmaktır 

Avare kalmaktır 

Akrepe dost 

Yelkovana yoldaş 

Rüzgara sırdaş olmaktır 

Bir şiir çekerek kınından 

getirmek kapına 

Sonra kovulmak kapından 

Boylu boyunca yatmak yalnızlığa 

Şiirlerden hicran 

Şarkılardan bir hüzzam acılığı 

Toplanınca avuçlarıma 

Acıyarak 

Kanayarak 

Korkarak uzaklaşırım ya yanından 

Ve tüm acılığıyla 

Sarıp sarmaladığım aşk 

Yaş olup akar 

Âh olup çıkar ya masumane 

İstemektir 

Canan. 

Canan... 

Aşk leylde, leyl masumiyettir 

Ve her mecnun 

Bir masumiyet kurbanı 

sevdanın tüttüğü odalarda 

demlenip dolarım meydanlara 

Kıyasıya savaşırım kendimle 

Çıkamam içimden 

Çıkamam gözlerinden 

Kangren olmasıdır umutların 

Aşkın kördüğüm özlemiyle 

Kaybolmasıdır kendisinde 

Bir kızıl akşam süzerek pencereden 

Ayıklamak közlerini 

Bastırmak yüreğine 

Gençliğimin tam ortasında 

Kaybetmek bedeliyle 

Dudağından bir katreye 

Susamaktır 

Kaldırım taşlarının ısısını 

Hissetmeye başladığımdan beri 

İçimde ve dışımda 

Cadde cadde 

Sokak sokak 

Aramaktır 

Canan. 

Canan... 

Ne acıdır ki tatlısı gözlerinin 

Bir baktım bir daha bakamıyorum 

Yeter mi bir ömür? 

Ölmek için yeter 

Ve ölümüne çektiğim acı 

Yaşamak için 

Toprak çeker içine 

Ateş çeker 

Kalem korkar hicrandan 

Satır satır akmak için kağıtlara 

Kağıt korkar 

Yine de çekmez saçların kancasını 

Yankısı ellerimden 

Sızar şehre 

Keskin olur sancısı ayrılığın 

Alev alır yedi tepe 

Ak kanatlarımla 

Gözlerine baka baka 

Uçmaktır 

Ayrılmak için 

Gözlerinden 

Ve ulaşmak için 

Gözlerine 

Canan 

H.HÜSEYİN İLHAN', 'Canan Can karşılığında istemektir  Bir tebessüm çalıp dudağından  Adını aşk koyup  Sonra zamana salmaktır  Avare kalmaktır  Akrepe dost  Yel...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin İlhan']::text[], 8.5, '{"poet":"Hüseyin İlhan","poet_slug":"huseyin-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":77,"source_url":"https://www.antoloji.com/canan-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir gönül serüveni', 'bir-gonul-seruveni-huseyin-i-lhan-kciyw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Rotasız bir hayat yaşıyordum 

Boğazımda yaşamın kirli elleri 

Tarumar bir yürek taşıyordum 

Menzilim eşyanın solgun emelleri 

Karanlıklara sataşıyordum 

Rotasız bir hayat yaşıyordum 

Bir ışık gördüm ufukta parlayan 

Koşmak istedim aydınlığa bütün gücümle 

Ne cesaretim vardı, ne dizde derman 

Kalemimden dökülen efkarlı cümle 

Yazdı hasretleri aşkıma ferman 

bir ışık gördüm ufukta parlayan 

Beklenmedik bir andı, yaz akşamıydı 

Bir güneş vurdu nemli toprağıma 

Yağmur duası sonrası gül bayramıydı 

Bir ak kuş kanadı düştü yaprağıma 

Sevda mevsimiydi, aşk baharıydı 

Beklenmedik bir andı yaz akşamıydı 

Sen geldiğin zamandı. 

H.Hüseyin İlhan', 'Rotasız bir hayat yaşıyordum  Boğazımda yaşamın kirli elleri  Tarumar bir yürek taşıyordum  Menzilim eşyanın solgun emelleri  Karanlıklara s...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin İlhan']::text[], 8.5, '{"poet":"Hüseyin İlhan","poet_slug":"huseyin-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-gonul-seruveni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim memleketimi', 'ozledim-memleketimi-ahmet-etik-rg45p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Özledim memleketimi

Caddelerde gezen insanlari

Sokaklari dolduran cocuklari

Elele gezen asiklari

Özledim memleketimi

Kendi dilimi konusanlari

Dostlari, Arkadaslari

Ve tüm insanlarini

Özledim memleketimi

Yazin günesin altinda yanmayi

Kisin kartopu oynamayi

Ve dört mevsimini

Özledim memleketimi

Ezan sesini duymayi

Bayramlari kutlamayi

Ayilece toplanmayi

Özledim memleketimi

Vatanimi, Milletimi

Dalgalanan BAYRAGIMI

Özledim TÜRKIYEMI', 'Özledim memleketimi Caddelerde gezen insanlari Sokaklari dolduran cocuklari Elele gezen asiklari Özledim memleketimi Kendi dilimi konusanlar...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Etik']::text[], 8.5, '{"poet":"Ahmet Etik","poet_slug":"ahmet-etik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ozledim-memleketimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk ateşi', 'ask-atesi-salih-ozalasan-0ecqn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana sitem etmeyeceğim

Duymayacaksın asla kem sözleri

Sen veda et ben etmeyeceğim

Yüreğimden duyacaklar hep o nağmeleri

Aşka dair yazacağım, kimse bilmeyecek

Yüreğimdeki sana ait sitemleri

Aşk''ım ve aşk''ımıza ait dizeleri

Yazacağım, okuyacaklar sana inat değilmi

Kâlbi kararmışlar okuyup 

Öğrenecekler bu sayfalarda sevmeyi

Onlarda bilecek, güldüklerine ağlayacaklar

Sevgiye tutsak olacak yürekleri

Onlarda hissedecek taaa yüreklerinde

Sıcak yataklarında yakan ateşleri

Ahu gözlü bir ceylan olacak

Isıtmayacak onları herzamanki güneşleri

Papatyalardan fal tutacaklar

Altın kafeslerde ağlayacak yürekleri

Nefrete ihanete uzak, yabancı

Sevgiyle dolup taşacak gönülleri

Seni seviyorum, ÇOK seviyorum

Olacak dudaklarından dökülen cümleleri

Sen yüreğimden uçup gittin ya

Sana inat aşk''la dolduracağım tüm yürekleri

Her adım başı göreceksin

Sevdalara uzanmış Aslı''ları, Kerem''leri

Dudaklarında esefle anacaklar

Hoşcakal buraya kadar diyenleri

Y.Tar.27-11-2002 Saat 19.49', 'Sana sitem etmeyeceğim Duymayacaksın asla kem sözleri Sen veda et ben etmeyeceğim Yüreğimden duyacaklar hep o nağmeleri Aşka dair yazacağım,...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ask-atesi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilberim', 'dilberim-mahir-toprak-skj8g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Deli olmak varmış bu sevdaya

İyilikle dolu bu kara gözlü deryaya

Loş odada her oturuşumda

Beyanat veririm sevgimden duvardaki aynaya

Elbette seveceksin birgün seni sevdiğim kadar

Rüzgar gibi akacaksın kalbin dur deyinceye kadar

İnmeden sürecek bu aşk gezisi, bu dünyada

Mahir deyip ölüm kapını çalıncaya kadar.', 'Deli olmak varmış bu sevdaya İyilikle dolu bu kara gözlü deryaya Loş odada her oturuşumda Beyanat veririm sevgimden duvardaki aynaya Elbette...', ARRAY['Türk Edebiyatı','Şiir','Mahir Toprak']::text[], 8.5, '{"poet":"Mahir Toprak","poet_slug":"mahir-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dilberim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Istanbul''u Özledim', 'istanbul-u-ozledim-hasan-sami-emiroglu-nj2rv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Isterseniz yem edin beni

Bogazda baliklarin oltasina

Isterseniz dikin beni

Bir gökdelen gibi

Istanbul''un ortasina...

Ben Istanbul''u özledim

Istanbul beni

Arayacaksan Istanbul''da

Bul beni...

Düsseldorf.1994', 'Isterseniz yem edin beni Bogazda baliklarin oltasina Isterseniz dikin beni Bir gökdelen gibi Istanbul''un ortasina... Ben Istanbul''u özledim ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sami Emiroğlu']::text[], 8.5, '{"poet":"Hasan Sami Emiroğlu","poet_slug":"hasan-sami-emiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/istanbul-u-ozledim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Bir Gül', 'hadi-bir-gul-lord-of-the-dark-vt6in', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gözlerinde bir gelincik yansıması

dudaklarında bir gül.

yanağına bir menekşe dokunası

tebessüm et yar hele bir gül.

sesinde yardiye seni yaşarken

umutsuz olma yar bir gül.

şiirde sen varken araya girdi virgül

ona inat yar hele bir gül.

gökteki yıldızlar kıskanırken seni

göğe bak  bir gül.

içime hapsettim aşk diye seni

tutsaksın diye üzülme hadi bir gül.

alın yazıma yazdım seni yar diye

gözlerime bak yar hele bir gül.... :)', 'gözlerinde bir gelincik yansıması dudaklarında bir gül. yanağına bir menekşe dokunası tebessüm et yar hele bir gül. sesinde yardiye seni yaş...', ARRAY['Türk Edebiyatı','Şiir','Lord Of The Dark']::text[], 8.5, '{"poet":"Lord Of The Dark","poet_slug":"lord-of-the-dark","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hadi-bir-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşı', 'gozyasi-burak-pala-g0wb3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sigaramı her çekişimde dumanıyla beraber gitmek istiyorum buralardan, gökyüzünün derinliklerine..

sonra süzülüp karışmak istiyorum bir yağmura ve inmek istiyorum dudaklarına bir yağmur damlasında..

ve sonra süzülüp içine akmak istiyorum..

hissetmek istiyorum bütün acılarını, dertlerini 

ve seninle yeniden doğmak istiyorum gözyaşında...', 'sigaramı her çekişimde dumanıyla beraber gitmek istiyorum buralardan, gökyüzünün derinliklerine.. sonra süzülüp karışmak istiyorum bir yağmu...', ARRAY['Türk Edebiyatı','Şiir','Burak Pala']::text[], 8.5, '{"poet":"Burak Pala","poet_slug":"burak-pala","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gozyasi-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluk Kışları', 'cocukluk-kislari-oguzkan-bolukbasi-fgbxs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'portakal kabuğu yaktınız mı sobada

bir küçük odada

kış pencerelerinden bakınca sokağa

ateşe sarılmak istersiniz uyku çeker canınız

o kışlar soğuk olurdu nedense

dedemse

hiç üşümezdi

cigara tellendirirdi keyifle

biz bahçede komşu kızı elifle

kardan adamlar yapardık

kardan kafalar ve gövdeler

kış pencerelerinden akşamları

beklerdik ellerinde filelerle gelen babaları

soyup portakalları

yakmak için kabukları

o kışlar soğuk olurdu nedense

kar kalkmazdı

sular donardı

efkarlar bile

sevdalar bile

yaza takılmış ayaz yanlış bir eklemeydi sözlükte

bir odadan diğer odaya geçmek ne zordu

tüm ev ısınmak için tek odaya doluşurdu

çişlerimiz donardı bir çıksak

dişlerimiz zangır zangır

uyumak sobanın koynunda bir kedi misali

sabah donmuş bir keyiftir 

kış pencereleri açılır sonuna dek

havalar girer eve

ve annemiz mutfakta

kahvaltı hazırlar

haydi çocuklar okula', 'portakal kabuğu yaktınız mı sobada bir küçük odada kış pencerelerinden bakınca sokağa ateşe sarılmak istersiniz uyku çeker canınız o kışlar ...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/cocukluk-kislari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Öpmek', 'seni-opmek-gokcen-duran-edzcn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dağ   başlarında  açan 

Bir  kır  çiçeğiydin

Üzerinde  sis...

Gözlerinde   gizem...

Etrafında  uçurumlar  vardı

Yıldızlar  kadar  uzaktın  bana

Ama   seni   seviyordum

Ancak   yağmurlarla  geliyordun  bana

Beklenmedik zamanlarda

Ve  bir  gün  ansızın

Güzel  bir  bahar  sabahı 

Sırılsıklam  oldum  gelişinle

Solan  güllerime  can verdi

Gelişin, gülüşün,  dudakların...

Öptüm  seni  hayat  veren  dudaklarından

Bir utançla birlikte  mutluluk yerleşti

Şeytani  tebessümüne

O tebessüm  saklı  şimdi dudaklarında

Ve  ben biliyorum ki, 

Kurşun kalemle  çizilmiş yüzünün kenarındaki

O  en  belirgin  işaretin  benden  kaldığını...', 'Dağ   başlarında  açan  Bir  kır  çiçeğiydin Üzerinde  sis... Gözlerinde   gizem... Etrafında  uçurumlar  vardı Yıldızlar  kadar  uzaktın  b...', ARRAY['Türk Edebiyatı','Şiir','Gökçen Duran']::text[], 8.5, '{"poet":"Gökçen Duran","poet_slug":"gokcen-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/seni-opmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasan Adam''la Muhhabet', 'hasan-adam-la-muhhabet-ozan-rari-7iqme', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir geceydi diğerlerinden farklı olmayan 

Odada oturup konuşuyorduk geçmişten, aşklardan

Yine söz döndü dolaştı sana

Güzel hatıralara diğer yandan çirkin anılara! 

Bir tuhaf oldum yine

Neden, niye, nasıl dedim kendime

Hasan dediki: kararlı bir insan var karşımda 

İstediğini yapan, tutuğunu koparan

Oysa ben böyle değildim bilirsin beni! 

Duyunca bunu; seni değiştiren şeyler yaşamışsın ondan olsa gerek dedi

Öyle dedim içimden çaresiz, teslim olmuşcasına.

Of Hasan ne olacak bu iş, hayatımın kadınıydı o! 

Sızlamaz mı yüreği, kendisiyle başbaşa kalmaz mı o? söyle bana dostum

Madem sevmişti niçin dayanamadı son nefesine kadar! 

Nedir gerçek haklı kimdi Hasan cevap sende mi arkadaş

Son aslında belli, yanacağım ateşte kavuşamadığım insanın hayaliyle

Sesin yok, gözlerin yok yoksun tüm yokluğunla güzel

Sensiz bende yokum be kadınım

Ararsan beni bir gün göremezsin beni bulamazsın

Çünkü ben sen giderken kayboldum hemde hiç bulunmamak üzere...', 'Bir geceydi diğerlerinden farklı olmayan  Odada oturup konuşuyorduk geçmişten, aşklardan Yine söz döndü dolaştı sana Güzel hatıralara diğer ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hasan-adam-la-muhhabet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorum Seviyorsun Beni', 'biliyorum-seviyorsun-beni-ozan-rari-o2rxz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yanından geçtim bugün hissetin mi beni? 

Arada sırada baktım eski eserime

Etrafında insanlar sen ise eksik gibiydin

Beni arıyordun, istiyordun sanki

Bir bilsen nasıl tutuyordum kendimi seni çekip almamak için

Bu aralar rüyalarıma giriyorsun ama gel al beni demiyorsun

Eski sözlerim geliyoru aklıma: 

Hani ne olursa olsun yanındaydım, seni sevip gül gibi bakıcaktım sana! 

Oysa sen solmak istedin, koptun benden bilinmezliğe doğru

Suçlarım oldu tabi, hatalıydım kimi zaman kabul

Bu demek değildi ki sana tapan insanı kopar at içinden

Özlüyorum seni bebek gel bana tekrar isyan edelim hayata

Mutluluğu kıskandıralım huzurumuzla, aşkımızla hatta saflığımızla

Kararsızsın anlıyorum korkuyorsun benden kendince

Ama unutma ki seviyorsun beni, kimseyi sevmediğin kadar...

(27 Kasım 2002_Bilkent-Ankara)', 'Yanından geçtim bugün hissetin mi beni?  Arada sırada baktım eski eserime Etrafında insanlar sen ise eksik gibiydin Beni arıyordun, istiyord...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/biliyorum-seviyorsun-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorunlu Kız Psikolojisi', 'sorunlu-kiz-psikolojisi-ozan-rari-3g4l5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir bakışta anlaşılıyor sahiden ama öğrenildikten sonra

Yürüyüşlerindeki uyuşukluk, dalgın ve boş bakışlı gözlerinden 

Özellikle mutsuzluk timsali o solmuş yüzleri onlar ele veren

Dert yumağıdır onlar, hataya birinci dereceden meyilli olma başarısı söz konusudur onlar için

Ya birçok sorun onları yıkan, 

Ya da tek şeydir akılarını başlarından alan.

Ailesiyle kopuk ilişkisi olanı tanıdım, 

Gelecekten korkup şaşırtanını, 

Sevgilisinden çektiği ızdırabı anlatanı, 

Öte yandan kendini hiç haksız bulmayanı! 

Dedimya sorun bu adı üstünde uğraşsan kabahat, 

Kendi hallerinde bıraksan başka türlü

Of of uzak durun benden olsun kafam biraz rahat

Herkezin derdi kendine zaten

Bırakın bu yolları bence

İşe yarayın biraz, faydalı olun dünya''ya! 

(Kendini zorla hayata küstürmeye çalışan kızlara)', 'Bir bakışta anlaşılıyor sahiden ama öğrenildikten sonra Yürüyüşlerindeki uyuşukluk, dalgın ve boş bakışlı gözlerinden  Özellikle mutsuzluk t...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sorunlu-kiz-psikolojisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurun Anısına Sana', 'yagmurun-anisina-sana-i-smail-ozabaci-1vbmr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yavaş yavaş ışıkları söndü kentin; 

Ben solgun renkli kağıtlara yazıyorum şimdi yokluğunu, 

Yağmur çiselerken penceremin dışında, 

Ben ''beni yağmurun kokusundan tanı''diyorum sana; 

Yalnızım işte bir yurt odasında, 

Alt tarafı yoksun yanımda, 

Alt tarafı ellerin yok, 

Alt tarafı gözlerin yok, 

Birde saçlarındaki fesleğen kokusu, 

Nasılda yansır rüyalarıma, 

Ve yerleşmişken bilinç altıma sensizlik, 

Senle yürüdüğümüz caddeler, 

Senle içtiğimiz bir bardak çay, 

Anlatır durur yokluğunu bana, 

Işıklar söner korkarsın biliyorum, 

Biliyorum, 

Mavi anılarını almadan uyuyamazsın, 

''Beni yağmurun kokusundan tanı'' demiştim ya sana, 

Biliyorum, 

Yağmur senin gözlerinde saklı, 

Koklayamazsın! 

Şimdi uyumalıyım, 

Şimdi seni atıp benliğimden, 

Şimdi seni silip gözlerimden, 

Bu yorgun bedeni uyutmalıyım, 

Sensiz bir gün daha geçmeli

Senszi bir gece daha, 

Bir yurt odasının aydınlığında, 

Yavaş yavaş ışıkları söndü şehrin, 

Ve dindi yağmur, 

''Beni yağmurun kokusundan tanı''', 'Yavaş yavaş ışıkları söndü kentin;  Ben solgun renkli kağıtlara yazıyorum şimdi yokluğunu,  Yağmur çiselerken penceremin dışında,  Ben ''beni...', ARRAY['Türk Edebiyatı','Şiir','İsmail Özabacı']::text[], 8.5, '{"poet":"İsmail Özabacı","poet_slug":"i-smail-ozabaci","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yagmurun-anisina-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-salih-ozalasan-fbasj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşk yüreğimde çağlayan deniz

Aşk dudaklarımdaki son dua

Aşk ulaşamadığım duygular

Aşk sensiz yaşanmayan

Aşk gecenin parlayan yıldızı

Aşk günle doğan kızgın Güneş

Aşk yüreğimdeki tik tak sesi

Aşk tek yol sana uzanan

Aşk ciğerlere cekilen nefes

Aşk dudaklarda duyulan ses

Aşk bazen altın bir kafes

Aşk sen varsan güzel olan

Aşk hissedilirse gözlerde parlayan

Aşk terkedildiğinde zehirli bir yılan

Aşk tadamadığında baldan tatlı her zaman

Aşk zehir zemberek kaçtığında avuçlarından

Aşk doğmak yeni bir hayata

Aşk konmak kelebek gibi daldan dala

Aşk dolanmak aklı bir karış havalarda

Aşk seninle başladı ve bitti buralarda

Y.Tarihi 27-11-2002 Saat 22.32', 'Aşk yüreğimde çağlayan deniz Aşk dudaklarımdaki son dua Aşk ulaşamadığım duygular Aşk sensiz yaşanmayan Aşk gecenin parlayan yıldızı Aşk gün...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ask-115-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sizin Sevdanız Bu Şiir', 'sizin-sevdaniz-bu-siir-alisan-satilmis-rm6oc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Selam hepinize baharsız

Çilehanelerden...

Çilemi, ızdırabımı/kinimi, öfkemi

Canevinden duyanlar

Sizin sevdanız bu şiir

Sizlersiniz kara günlerimize

Ak/ak aydınlıklar

Selam size baharsız çilehanelerden

Ey gönülleri gurbet hüznüyle yananlar

Ses gelmeyen çift camlarda

Beni bekleyenler

Selam hepinize baharsız

Çilehanelerden...

Görüş günü/mektup günü

Kahrettiğim vefasızlar

Ne gam/ne keder

Hüzünlü anılara

Sevdim sisi bir kere

Ne yarınların kalleşliğine

Ne melali anlamayan nesle

Sitemimiz yok bizim

Yazgımız nefer doğup

Nefer ölmek bizim

Sizin sevdanız bu şiir..', 'Selam hepinize baharsız Çilehanelerden... Çilemi, ızdırabımı/kinimi, öfkemi Canevinden duyanlar Sizin sevdanız bu şiir Sizlersiniz kara günl...', ARRAY['Türk Edebiyatı','Şiir','Alişan Satılmış']::text[], 8.5, '{"poet":"Alişan Satılmış","poet_slug":"alisan-satilmis","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sizin-sevdaniz-bu-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Aşımına İade', 'zaman-asimina-i-ade-alisan-satilmis-xgdzq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hücremde, özlemim yıldızlarım

Yüklü gökyüzü

Ağular kusar her saniye dakika içinde

Hisseder betonu, romatizmal bacaklarım

İnat ya

Yağmur yüklü bulutlara hasret duygularım

Damarımdan ta beyne kadar

Hep hayalimde gezer

Yükseklerde süzülen kartal

Alçalışlarda kanat çırparak

Karanlıkları solur, küfleri solur

Oksijensiz nefeslerde, gümbürtülü yürek

Histeri nöbetine tutulmuş

Küfürlerinin falakalarında

Mosmor olur tabana kuvvet kaçışlarım

Deparlı ayaklar

Onursuzluk, altına alınan şahsiyetim

İtişli, kakışlı, arkadan tekme vuruşlu

Hücrelerde yeniden kazanılır

İADELİ, en okkalı küfürlerle.', 'Hücremde, özlemim yıldızlarım Yüklü gökyüzü Ağular kusar her saniye dakika içinde Hisseder betonu, romatizmal bacaklarım İnat ya Yağmur yükl...', ARRAY['Türk Edebiyatı','Şiir','Alişan Satılmış']::text[], 8.5, '{"poet":"Alişan Satılmış","poet_slug":"alisan-satilmis","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/zaman-asimina-iade-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ziyaretçilerin Mahkum Çilesi', 'ziyaretcilerin-mahkum-cilesi-alisan-satilmis-pu7uu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nizamiye kapısında kalabalıklar

Çoluk, çocuk, nişanlı, yavuklu, ana, baba, gönüldaş

Canhıraş bakışlarda bekleyiş

Hasret dolu günlerin vuslat özleminde

Uzanıp sevgiye hasret elleri/inince damgalar

Kol bileklerine/firarilerin önlem mührü diye

Bir aşağılanma/bir horlanma

Gariplikler/garipliği/yurttaş/vatandaş

Yasaklar ülkesi/görüş günlerinin/mahkum

Ziyaretçi çilesi/hele bir de cezaevinden

Sevip saydığın/asker iteklemesi

Ne garip yasakların bitmez/tükenmez çilesi

Ziyaretçilerin mahkum çilesi

Binbir telaş/ne zorluklar/ne teslimiyetçi tavırlar

Geç demenin yorgunluğunda/feri geçmiş gözlerin

Çift camlar ses geçirmez/buz kesen kabinler

Arkasında/soğuk beton iklimlerinde

Hoş geldin/demenin hazzını tadınca/unutulur

Onca badire/hasret dolu günlerin vuslat gününde

O anda çöker öyle bir velvele/kabin denen yere

Uğultu/üstüne uğultu/bütün konuşmalar/bakışlar

Ne sorular/ne cevaplar/noktasızdır bütün laflar

Çift camlar ses geçirmez/ziyaretçi kabinlerinde

Anlaşılan tek şey/bakışların derinliğinde

Buğulu camların ötesinde/berisinde

Hüzünlerin kardelen gülümsemesi

Ve, ziyaret bitmiştir, düdük sesi/mahkumların

Ziyaretçi çilesi/işte o zaman ötelere/ötelere

Hüznümüz/görüş günlerinin içimizde bıraktığı

Çileli günlerin ayrılık özleminde...', 'Nizamiye kapısında kalabalıklar Çoluk, çocuk, nişanlı, yavuklu, ana, baba, gönüldaş Canhıraş bakışlarda bekleyiş Hasret dolu günlerin vuslat...', ARRAY['Türk Edebiyatı','Şiir','Alişan Satılmış']::text[], 8.5, '{"poet":"Alişan Satılmış","poet_slug":"alisan-satilmis","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ziyaretcilerin-mahkum-cilesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerim Kan Çanağı', 'gozlerim-kan-canagi-alisan-satilmis-qmdr9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zaman tılsımıyla yürüdü

Debdebeli yaşayışların menziline

Gün vampir sırıtışlarında ağladı

Gözlerim kan çanağı

Bir demet sümbül/sehpaları lanetledi

Rengimi kirlettiniz diye

Yağmur ve hüzün yan yana

Alır sevdalarımı döker

Hücre penceremden/şafaklarda mahpus olduğum

Cezaevinden sürgünlendiğim/güne

Yorgun bir hüzün çaresizliği gözümde büyür

Ağıt üstüne

Neşterlenmiş yaralarım

Hazan iklimlerinde kanar

Eylül’lerde hoyratça biçtiği/katlettiği

Kıyıcıların tırpan vuruşunda

Zaman küheylan tılsımıyla yürüdü

Debdebeli yaşayışların menziline

Gün vampir sırıtışlarında ağladı

Üçayakları, urganlı

Destursuz hükümlerde

Gözlerim kan çanağı', 'Zaman tılsımıyla yürüdü Debdebeli yaşayışların menziline Gün vampir sırıtışlarında ağladı Gözlerim kan çanağı Bir demet sümbül/sehpaları lan...', ARRAY['Türk Edebiyatı','Şiir','Alişan Satılmış']::text[], 8.5, '{"poet":"Alişan Satılmış","poet_slug":"alisan-satilmis","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gozlerim-kan-canagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Bir Şiir', 'oyle-bir-siir-alisan-satilmis-8ggb9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çırpındık bir ağıt faslında

Yüreğimiz alabora

Okyanuslara açılan bir gemide

Darağacı iklimlerine çiçekler sunduk

Sesimizi duyan yok

	Sevdalarımız muhtaç, cankurtaran simidine

Boğuluyorum, boğuluyoruz bu anaforda

Yaşamaya çalıştık zamanda

Uzatan yok elini, hatırlayan yok dünü

Mazim kocarken gün be gün

	Haykırdık mazi mimberinden

Kimdik? Neydik biz..! 

Çırpınmamız boşuna

	Limanlar kayıp

Siz, memnun görünenler, nerelerdeydiniz? 

	Nerdeydiniz? 

Güldüler sesimize

	Bizimle, benimle çırpındı pusula! 

Sahiplendiler, kimliğimize! ..

Boğdular bizi bir ağıt faslında

Gün ortasında, karanlıkta

Yandık Vallahül Alem insanlık adına

	Alem seyirci kaldı feryadımıza...', 'Çırpındık bir ağıt faslında Yüreğimiz alabora Okyanuslara açılan bir gemide Darağacı iklimlerine çiçekler sunduk Sesimizi duyan yok 	Sevdala...', ARRAY['Türk Edebiyatı','Şiir','Alişan Satılmış']::text[], 8.5, '{"poet":"Alişan Satılmış","poet_slug":"alisan-satilmis","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/oyle-bir-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan Sevgilere', 'yalan-sevgilere-umit-keskin-x1tho', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Utanıyorum 

kaybettigim yıllarıma

utanıyorum

kaybettiğim gururuma

çünkü; 

haketmedikleri sevgiyi verdim onolara

kuramadığım, 

belkide kuramayacağım, yuvama; 

Ağlıyor gözlerim.

Yaşamamı gerektirecek hiçbir ümidim kalmadı

Bana yeter de artar dediğim aşklarım 

Beni yakıp bitiren oldular.

Bağladılar elimi dilimi

Ne birşey sordum

Ne de bir şey yapabildim

En mükemmeline kadar bekliycem dedim

Her bulduğumu o zannettim

Sonunda onun olamayacağına inandım, inandırıldım.

Yolda yürüdüğümde

Arabaya bindiğimde

Televizyon izleyip, radyo dinlediğimde

düşünecek bir sevgilim yoktu...

olamadı

Belki de suçu biraz kendimde arayıp

Sormalıyımki; 

Benim için ne yaptılar? 

Ben onlar için ne yaptım?', 'Utanıyorum  kaybettigim yıllarıma utanıyorum kaybettiğim gururuma çünkü;  haketmedikleri sevgiyi verdim onolara kuramadığım,  belkide kurama...', ARRAY['Türk Edebiyatı','Şiir','Ümit Keskin']::text[], 8.5, '{"poet":"Ümit Keskin","poet_slug":"umit-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yalan-sevgilere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelebek', 'kelebek-orhan-altan-y762n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Koşarken en güzel papyonlu kelebeğin peşinde

Kaybetmişken yolunu sığ sularda

Ve düşmüşken

Ve kan içindeyken dizlerin...

Bir ben kaldım yanında, 

Ama 

Kırık dökük...', 'Koşarken en güzel papyonlu kelebeğin peşinde Kaybetmişken yolunu sığ sularda Ve düşmüşken Ve kan içindeyken dizlerin... Bir ben kaldım yanın...', ARRAY['Türk Edebiyatı','Şiir','Orhan Altan']::text[], 8.5, '{"poet":"Orhan Altan","poet_slug":"orhan-altan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kelebek-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek', 'sevmek-orhan-altan-mf49w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevmek korkutucu bir şey

korkarken sevemiyor insan.

Ama ölmek...

Bazıları ölüyor sevsende

ve sevgi doğuyor

ölüm doğar mı? 

Belkide bulurlar sonsuzluğu

cennet bulunur mu?', 'Sevmek korkutucu bir şey korkarken sevemiyor insan. Ama ölmek... Bazıları ölüyor sevsende ve sevgi doğuyor ölüm doğar mı?  Belkide bulurlar ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Altan']::text[], 8.5, '{"poet":"Orhan Altan","poet_slug":"orhan-altan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevmek-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuyu', 'kuyu-orhan-altan-qe8sk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dipsiz bir kuyuda düşüyorum ben

yada sana koşuyorum 

öyleki karanlık 

göremiyorum...

Bazen bir papatya görüyorum 

etrafı ipek koza

sonra o papatyanın bütün polenlerinin

sen olduğunu fark ediyorum

ağlıyorsun...

Çemberlerin başı sonu yoktur 

kuyularında...

Dipsiz bir kuyuda düşüyorum ben

yada sana koşuyorum

öyle ki karanlık 

göremiyorum...', 'Dipsiz bir kuyuda düşüyorum ben yada sana koşuyorum  öyleki karanlık  göremiyorum... Bazen bir papatya görüyorum  etrafı ipek koza sonra o p...', ARRAY['Türk Edebiyatı','Şiir','Orhan Altan']::text[], 8.5, '{"poet":"Orhan Altan","poet_slug":"orhan-altan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kuyu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayan gözlerim', 'aglayan-gozlerim-salih-ozalasan-f7woq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine ağlayan bir çift göz

Herzaman olduğu gibi benim gözlerim

Yine çağlayan bir nehir

Yine dağları deliyor sözlerim

Yine isyanlardayım, felekle başım dertte

Yine bana zalim, acımasız kaderim

Yüreğimde aşkın hançeri saplı 

Tanrıya açılmış yalvaran ellerim

Sevdalar bana zalim 

Sevgili insaf etmez yüreğime

Mecnundan yok hiç farkım

Acınacak belkide benim son halim

Kalmamış hayatta kalma nedeni

Nerde bu Dünya''nın kadir kıymet bileni

Yerlerde sürünür gördüm her seveni

Gülü başkaları koklamış bense dikeni

Varmı benden başka yare hasret çekeni

Sevdalara yanıp duman duman tüteni

Aşk söyletir dert ağlatır her düşeni

Bana sevda olmuş hep gülün dikeni

Bulamamış gönlüm bir kadir kıymet bileni

28-11-2002 - 00.15', 'Yine ağlayan bir çift göz Herzaman olduğu gibi benim gözlerim Yine çağlayan bir nehir Yine dağları deliyor sözlerim Yine isyanlardayım, fele...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/aglayan-gozlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aids', 'aids-kucuk-i-skender-7mzfx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bana bir sonbahar fısılda

senden başka masumiyetim yok

çocukluğum tek tabanca

Herşeyi geriye saymaktan yorgunum

kaç intiharım varsa o kadar sevgilim var

içimdeki tabiat sana doğru fırlama

çıplak elle tuttuğum bir elektrik teli bu muamma', 'Bana bir sonbahar fısılda senden başka masumiyetim yok çocukluğum tek tabanca Herşeyi geriye saymaktan yorgunum kaç intiharım varsa o kadar ...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/aids-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ante Mortem Şarkısı', 'ante-mortem-sarkisi-kucuk-i-skender-qcc3z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bilinçsizce şekilleri birleştiriyorsun

yalnızca kesici bir alet edineceksin belki de..

Korkuyorum..

korkularım, geceyarıları uyanıp aya bakıyor

Ay, tanrının bıraktığı parmakizi gökyüzünde! 

Ben, bu aşkta uzaya açılacağım yekpare, 

diyorsun. giyinmişsin. kararlısın anlaşılan.

Sınırını izinsiz geçen kaç düşman askeri vardı ki sanki

Dur! Yabancı! Parola! 

Hiçbir vahşi kurt

insana sığınmaz yaralandığında! 

Parola: suskun kalakalan dudaklarda

vurularak yakalanmış firari bir sevgili..

hani

ecelle aramda gerili sestelleri

içinden süzülür ya

rüzgar gibi bir melankoli

diye yazmıştın, bilmem hatırlar mısın, 

tanıştığımız gün çakıltaşlarını kaydırarak

bir ebru ustası edasıyla yalıçapkını denize..

İşte tam bu esnada, şimdi, ayrılırken

casus hatıra uçakları beliriyor ardı ardına

radar ekranı yeşil nemli gözlerinde! 

Sonbahara takılmış bir ağaç

çığlık çığlığa nasıl düşürürse yapraklarını

Bir kelebek

nasıl saklarsa ruhunda meleklerin öldürdüğü bir tırtılı

öyle bir trajediyle

Öyle bir dönüşümle kabulleniyorum

kendi doğana sırnaşmanı! 

Mutluluklar diliyorum sana yavrum

yalnızca kesici bir alet edineceksin belki de..

Bekliyorum..

bekleyişlerim, geceyarıları uyanıp aya bakıyor

Ay, suçlu bir tanrının robot resmi gökyüzünde!', 'Bilinçsizce şekilleri birleştiriyorsun yalnızca kesici bir alet edineceksin belki de.. Korkuyorum.. korkularım, geceyarıları uyanıp aya bakı...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ante-mortem-sarkisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aradelik', 'aradelik-kucuk-i-skender-9u6qh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kesirli urların aksettiği su burunları

anlatırlardı vazgeçilemeyen esrar: 

kutupları

Zıvana gibi bir aysbergin göğsünde

delikanlı tarihlerden kalma

transatlantik jilet yaraları

rocker olmak isteyen penguenlerin duaları', 'Kesirli urların aksettiği su burunları anlatırlardı vazgeçilemeyen esrar:  kutupları Zıvana gibi bir aysbergin göğsünde delikanlı tarihlerde...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/aradelik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkinci İblis', 'i-kinci-i-blis-kucuk-i-skender-t2tu7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kilitlenen yüreğiyle ağlamaya, kararsız gücün önünde.

	Tek çocuklu dünya gibi, dökülmeyi özlemiş. Birbi-

	rinin içinden sızan taylardı, o son kez su olarak

	görünen ve sonra gidecek olan okyanusun ve ok-

	yanusun altında uyurken gizlenen lir sesli ça-

	yın.

İntihar, hayallerin bana borcudur; 

	tığını yere atarken ay. Koynunda: 

Limanda yanan gemiler, uzun savaşlar ertesi; çıldırtan

	kundak, çıldırtan kül, sakinleştiren şüpheler; 

Ruh düşer geceye, en korkunç anından delirmenin; bir

	gül bir güle: -Ben atık bok kokacağım

					der, 

Yeryüzü aralanır

	yeryüzü aralanır ve

Yeryüzüne yar yüzü girer;', 'Kilitlenen yüreğiyle ağlamaya, kararsız gücün önünde. 	Tek çocuklu dünya gibi, dökülmeyi özlemiş. Birbi- 	rinin içinden sızan taylardı, o so...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ikinci-iblis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzleri Neden Seyreden', 'i-zleri-neden-seyreden-kucuk-i-skender-s7hce', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'soylu soyunuş gecesi

sözcük öldürmekten dönen soylu unutuş kuşu; han

çerime erkek çıkartır ağrısını ve duadır bir çeşit

dokunması dudakların geçerek başka dudaklardan; Seni

		seyreden

cerrah çocuklara, o kayıp yalnızlıkların arka çiçekleri

ne, harbe girmiş kentlere ve yaşlı müzisyenlere, ilkokullara, 

izi yitirilmiş meryem aşklara inen yolda bulduğun

ve baktığında karşı kıyıda kendini uykuya yatırdığın

		dürbün; 

oysa kalbi ikmale kalmıştır dünyanın, ben sen çıplak

yatarken göğsüne vuran siyah mehtabım der su çatlarsa, 

su çatlarsa akmaya başlar son kalan gözü hüznün, 

su çatlarsa yanmaya başlar öncelikli ten. Benizkızı

yüzer yüzünde o delikanlının, Kama ile açılır artık Sözlük; 

çetelemi kiralık melek tutar; 

bir hazine gibi çıkartılır açlığım ve hayvanlığım

koynundan bakırın; bir dalgayı atar omuzlarına şal

yerine denizden yeryüzümüz, bedenimiz yere sıkışmış

yüzümüzdür; bir cinnet çetesi kurarım bütün üyeleri

akşam olan, sana sokulan, ellerini ellerime tıkıştıran, 

evsahibi barınağından attırır baharı ve martla

ağustostan doğma bir vahşi tay olur aşkım; 

		kim bilir

akort bozulduğunda ben nerede ölmüş, öldürülmüş olurum

parmakuçlarımdaki, avcumdaki bu çivi izleri neden', 'soylu soyunuş gecesi sözcük öldürmekten dönen soylu unutuş kuşu; han çerime erkek çıkartır ağrısını ve duadır bir çeşit dokunması dudakların...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/izleri-neden-seyreden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vardı Büzüşüp Utanan', 'vardi-buzusup-utanan-kucuk-i-skender-001n2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bu ne tehlikeli mürebbiye: bakınca ezberle

yeceğim bir hadis gibi yaz

geçecekti sonbahara doğru süratli bir otomobil; 

ah tabii o şimdi ölmüş

görünen çocuğun bir rehbere anlattığı son

aşk nedir biliyor musun seni üçüncü tekil şahıs

sayan seferde askerin sol üst cebindeki resim

de arkalarda durup başını öne eğen ilk adam; 

büyük bir gülümsemeyle geçecekti yaz

dığım bir hikayenin bütün kahramaları

kutsal bir viyolonselden porteye doğru

geçecekti sonbahara süratli bir otomobil

içersinde sarı saçlı iblis ve herhangi bir tanrı

ya inanmak mıydı çıplak modelin apışına yağan

kar, teni tutan boran, ağzı kitleyen zemheri; 

istikrarlı bir çekiliş yaşıyorduk sevişme

lerimizde memelerimiz vardı büzüşüp utanan

ların önünde hatim indirdim dudaklarımı

dudaklarınıza matem tülü üstünden

yazdı', 'bu ne tehlikeli mürebbiye: bakınca ezberle yeceğim bir hadis gibi yaz geçecekti sonbahara doğru süratli bir otomobil;  ah tabii o şimdi ölmü...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/vardi-buzusup-utanan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toksin', 'toksin-kucuk-i-skender-xg974', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sarman Oytun''a..

Bu gece

gökyüzü, yeryüzüne düşecek

altında durma! 

Bir süre yalnız

bir süre sırsız kalacak

gezegen

toprakla kilitlenecek kör fesleğen', 'Sarman Oytun''a.. Bu gece gökyüzü, yeryüzüne düşecek altında durma!  Bir süre yalnız bir süre sırsız kalacak gezegen toprakla kilitlenecek kö...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/toksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memleketler', 'memleketler-baris-akm-d5erc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çöller gördüm

Aç, susuz, bitap insanlar

Peşlerinde sinek sürüleri

Dünya''dan bihaberdiler

Toprak yerine çöl kıyılarında

Tepelerinde sopa tanrı adına

Yeryüzünde cenneti belki gördüm

Koşuyor insanlar biteviye

Bir dilim ekmek hayat pahasına

Haftada iki gün yaşıyorlar

Orada-burada

Pazartesi açlar çalışmazlarsa

Bir yer gördüm, ruhlarına işlemiş para

Pislik gırtlaklarında

Bunlarda Dünya''dan bir haber Dünya''da

Yağmur ve güneşin toprağında

Dillerinde tanrı çıkar uğruna

Memleketi düşünüyorum sonra

Özeniyorlar cahil cühela sonuncuya

Bilmiyorlar mumları sönecek onlarla

Öğrenecekler hayat kaç para

Kıymetini bilmedikleri bu coğrafyada

Onlar gibi olmayı başardıkça', 'Çöller gördüm Aç, susuz, bitap insanlar Peşlerinde sinek sürüleri Dünya''dan bihaberdiler Toprak yerine çöl kıyılarında Tepelerinde sopa tanr...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/memleketler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutuldummu Yoksa', 'tutuldummu-yoksa-hulya-arisan-i25fs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tatlı bir serhoşluk var

 yüreğim de.

Unutmuştum epeydir, 

uzak kalmıştım aşka.

Tutuldum mu yoksa

beni sarmaladı S E V D A N...

Istanbul      Kasım 2002', 'Tatlı bir serhoşluk var  yüreğim de. Unutmuştum epeydir,  uzak kalmıştım aşka. Tutuldum mu yoksa beni sarmaladı S E V D A N... Istanbul     ...', ARRAY['Türk Edebiyatı','Şiir','Hülya Arısan']::text[], 8.5, '{"poet":"Hülya Arısan","poet_slug":"hulya-arisan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/tutuldummu-yoksa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ummak Ormanı', 'ummak-ormani-baris-akm-yu6ti', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşam geçiyor ummak ormanında

Bir tutam hayat yasak kiminde insana

Gidiyoruz bata çıka umudun gülü sıra

Sakın gül dediğin nedir deme

Dünya dönüyor gül ile diken hatırına

Gün geliyor isyan ediyoruz dağa taşa

Gün geliyor düşüyoruz yollarına

İnsan garip bir manzume işte soluk aldıkça

Ne eğri dinler ne yasak tanır göğsündeki serçe

Pır pır uçmak ister her günün seherinde

Ölür gider kanadı kırılınca', 'Yaşam geçiyor ummak ormanında Bir tutam hayat yasak kiminde insana Gidiyoruz bata çıka umudun gülü sıra Sakın gül dediğin nedir deme Dünya d...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ummak-ormani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalsam diyorum', 'kalsam-diyorum-baris-akm-f2s70', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kalsam diyorum buralarda

İstemeden, sevmedende olsa

Upuzun bir mecburi hizmetin 

Zehirli koynunda

Ne fark eder dilin olsada başka

Dinin ve meshebin öyle

İnsan aynı her yerde 

Bencil yaşamı, yaşam belledikçe

Ne olacak? 

Günün biri döneceğimde

Doğup büyüdüğüm akasyalı kaldırımlara

Ihlamur kokulu sokaklara

Mimoza gözlü ada yollarına

Dertlerin rengi değişecek belki orada

Gurbet kalacak geride kalmasına da

Eski değirmen başlayacak seni öğütmeye

Toprak hasreti yerine

Dönünce ilk iş uzun aradan sonra

İlk defa kurufasulye yiyeceğim 

Alıştığım o kırmızı acılı tatla

Çoban salataya zeytinyağı dökeceğim

Sos denen sentetizm yerine

Ve limonun hasını sıkabileceğim gönlüne

Belki şimdi yazamadığım

Ki gurbet bindi hepsinin üstüne

Yazabilirim belki sevda tadında

Aşktan dem vururum karanlık tellerime

İnsan yüreğine dokunurum kalem yettiğince de

Ne pahasına? 

Kalsam diyorum buraların yaban cenderesinde

Dönsem diyorum birde toprağın kokusuna

Kaldım işte iki arada bir derede

Dönmem lazım gözümde tüten maviş şehre', 'Kalsam diyorum buralarda İstemeden, sevmedende olsa Upuzun bir mecburi hizmetin  Zehirli koynunda Ne fark eder dilin olsada başka Dinin ve m...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/kalsam-diyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet Akşamları', 'gurbet-aksamlari-baris-akm-gpjlv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yağmur sonrasıydı bu akşam

Uzanışım kumsal yoluna

Karmaşık alemin ortasında

Amaçsız, umarsız bir akşam daha

Ayak izlerine takılıyor gözlerim

Yeni konmuşlar besbelli kumsalın tenine

Bir yer buluyor ayaklarımda kendine

Yaban kum tanelerinin aralarında

Ara ara dalıp gidiyor gözlerim

Kah karanlığın, kah ufkun ötesine

Dönüp geliyorum zaman dürtünce

Siyah gölgemi bırakıp oraya

Ve işte koca dünyada bir başımayım

Birer birer kapanıyor kapılar sokakta

Dikilme zamanı geliyor gözlerin tavana

Sokak lambaları bile yalnız değil dışarıda

Bir gece daha aynıyım

Sızılar hareleniyor gözlerimde

Hasret zehir zemberek soluğumda

Yollar gelmiyor, gidemiyorum bende', 'Yağmur sonrasıydı bu akşam Uzanışım kumsal yoluna Karmaşık alemin ortasında Amaçsız, umarsız bir akşam daha Ayak izlerine takılıyor gözlerim...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gurbet-aksamlari-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Güzel', 'bir-guzel-baris-akm-czu5a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gurbetin bu akşamında

Bir güzel yürüyor sahilde

Güzel olmaya güzel ne kelime

Bir de o şortu gismeseydi ya

Çıplak dolaşsaydı demiyorum aman ha

Ama hiç değilse arkasında sexy yazmasa

Belki dönüp bakardım bir daha

Tepeden tırnağa endamına

Şimdi sadece şortu kaldı aklımda

Birde o kelime haspadan geriye', 'Gurbetin bu akşamında Bir güzel yürüyor sahilde Güzel olmaya güzel ne kelime Bir de o şortu gismeseydi ya Çıplak dolaşsaydı demiyorum aman h...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bir-guzel-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Son Nokta', 'aska-son-nokta-baris-akm-d743d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Artık ne acı çekmek daha fazla

Gahi mecnun gahi kerem misali

Ne de acı çektirmek istiyorum

Kah Leyla gibi kah Aslı gibi

Vurup sürgünlere bir çift gözü

Kurtuluş savaşlarını ben çoktan kaybettim

Ne içimin Roma''sı kaldı ne de Nazım''ın Cuba''sı

Yakmak vardı Neron gibi, memleketi

Ben de yaktım içimdeki tüm kentleri

Şimdi her yer savaş sonrası

Çok sürmez gönül şehrinin titrekte olsa ışıması

Varsın bir daha açılmayacak olsun kapıları

Eski kapıları açıldı da ne oldu

Şimdiden sonra sürgülü kalsın kilidi

Zaten yıllar öncesinden anlımda müebbet damgası

Af çıkacak da değilki umayım yarını

Beceremem ben gün bu gün demeyi 

Yaşamaksa yaşarım gizli dünyamı

İçindeki kara mizahın çizgilerini

Üçüncü hamur kağıtta soluk renklerini', 'Artık ne acı çekmek daha fazla Gahi mecnun gahi kerem misali Ne de acı çektirmek istiyorum Kah Leyla gibi kah Aslı gibi Vurup sürgünlere bir...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aska-son-nokta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saf Duygular', 'saf-duygular-hulya-arisan-p6408', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir rüya 

yaşadım seninle, 

Gece başlayan

sabaha kadar süren...

Düşle gerçeğin

birbirine karıştığı.

Her dakikanın saatler sürdüğü

muhteşem zaman sürecini

paylaştım seninle...

Adını koyamadım, 

koymalımıydım.

Düşündüm bulamadım.

her doğan bebeğe ad konur....

Bu farklı olmalı, 

ad konmamalı

özgür ve doğal bırakmalı

saflığını korumalı... 

Her doğan bebeğe ad konur, 

bu farklı olmalı, 

ad konmamalı, 

SONSUZA bırakmalı...

İstanbul   Kasım  2002', 'Bir rüya  yaşadım seninle,  Gece başlayan sabaha kadar süren... Düşle gerçeğin birbirine karıştığı. Her dakikanın saatler sürdüğü muhteşem z...', ARRAY['Türk Edebiyatı','Şiir','Hülya Arısan']::text[], 8.5, '{"poet":"Hülya Arısan","poet_slug":"hulya-arisan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/saf-duygular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Bu Aşk Ölümsüz! ..', 'bu-ask-olumsuz-mustafa-engin-karatay-yzbcz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu öfke, bu nefret, bu kîn ve gurûr; 

Ölümsüz aşkımın, büyük delîli...

Sanma ki; akan tek gözyaşı kurur! 

Her biri, sevgimin susmayan dili...

Kanlı gözlerimi gören farkeder; 

Pıhtı tutmaz hâlde yazıyor ismin

Hicrân Irmağı''na, aktıkça keder; 

Kıvrım kıvrım sanki, çizilir resmin...

Anılar, taptâze gelip; ağlarken, 

Gün gibi, ân gibi karşımda durur! ..

Gidişin köz gibi, yürek dağlarken; 

Her saat başında, Bin Sille vurur! ..

Erir mi bu sevdâ zamân çarkında? 

Biter mi zannettin, olur mu heder? 

Bitmez, bitmeyecek! Herkes farkında! ..

Bilmem ki vicdânın; vicdânın ne der? 

31.10.2002   Münih  04:15', 'Bu öfke, bu nefret, bu kîn ve gurûr;  Ölümsüz aşkımın, büyük delîli... Sanma ki; akan tek gözyaşı kurur!  Her biri, sevgimin susmayan dili.....', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bu-ask-olumsuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlıyorsun', 'agliyorsun-ahmet-ersin-tasel-ki9pb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Umut şimşekleri çakar 

Yapayalnız yüreğinde

"Onu ararken"

Karanlığı delercesine

Aydınlatan bir ışık huzmesi

Aniden başlayan yağmur...

Şimdi o karanlıkta

Bulutların arkasında 

Saklanan ay ışığı altında

Bir göl kıyısında

Gözlerinden düşen yaşla dağılan 

Sudaki aksimin dalgalanmasını seyrediyorum

Gecenin soluğunu çekiyorum

Derin derin...

Toprağın kokusu içine doluyor

Düşen damlalarla her yer pıtır pıtır inliyor

Bir gürültü patlıyor

Ürperiyorsun

Hatırlıyorum

Her şey onunla başladı, onunla bitecek

Yağmurla gözyaşlarım birbirine karışıyor

Soruyorum hangimiz ağlıyor diye

Ben mi yoksa şu içine kapanmış

Hırçın gök kubbe mi

Parmağımı yeni oluşan 

Çamurun içine batırıyorum

İşte her şey böyle başladı böyle bitecek

Ne demişler 

Topraktan geldik

Toprağa döneceğiz

Allah''tan geldik...

Allah''a döneceğiz...', 'Umut şimşekleri çakar  Yapayalnız yüreğinde "Onu ararken" Karanlığı delercesine Aydınlatan bir ışık huzmesi Aniden başlayan yağmur... Şimdi ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ersin Taşel']::text[], 8.5, '{"poet":"Ahmet Ersin Taşel","poet_slug":"ahmet-ersin-tasel","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/agliyorsun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'De', 'de-ahmet-ersin-tasel-02ov0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zaman...

Zaman 

Bundan yıllar önceydi

Kız çok sevdi

Hissettiklerine karşı günlerce savaştı

Yeniden tekrar yeniden kaybetti

Sokak karanlıktı

Yürürken düşündü

Başını eğdi 

Tutkundu

Kararını verdi 

Teslim olacaktı

Ertesi gün...

Yüzyüze geldikleri ilk an

Sana aşık oldum dedi

Yanakları kızarmadı

Oğlan kısa bir an düşündü

Ben...

Ben sana karşı böyle hissetmiyorum dedi

Kızın iri gözleri doldu 

Belli etmedi

Cesaret utanmadı

Gurur burkuldu 

Onur doğruldu

Ayrıldılar

Zaman...

Zaman 

Yıllar sonra oldu

Oğlan yalnızdı

Düşündü 

Başını eğdi

Kalemi aldı 

Yutkundu

Seni kırdım affet

Gururuma yenik düşmüştüm o gün

Diyemedim işte

Dolan boncuk gözlerin aklımdan çıkmıyor

Ben de

Dedi

Kalem yazdı

Hikaye bitti

An zamana 

Zaman o ana teslim oldu

Geçen geri gelmedi', 'Zaman... Zaman  Bundan yıllar önceydi Kız çok sevdi Hissettiklerine karşı günlerce savaştı Yeniden tekrar yeniden kaybetti Sokak karanlıktı ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ersin Taşel']::text[], 8.5, '{"poet":"Ahmet Ersin Taşel","poet_slug":"ahmet-ersin-tasel","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/de-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek', 'tek-ahmet-ersin-tasel-tjkha', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana ilksin diyemem

Çünkü senden sonrasını hiç düşünmedim', 'Sana ilksin diyemem Çünkü senden sonrasını hiç düşünmedim...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ersin Taşel']::text[], 8.5, '{"poet":"Ahmet Ersin Taşel","poet_slug":"ahmet-ersin-tasel","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/tek-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Git', 'gel-git-ahmet-ersin-tasel-zldhg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sonun oyunu sahnede 

Perde perde

Gel git anlar 

Neyi anlatıyor? 

Dudaklarda birkaç hece

Artık unutulmuş cümleler

Aşınmış hayatlar...

Çıkacak sahil yok...

Vurgun yedikten sonra

Girdaplara takılmak gırtlakta

Bilinen kim? 

-Bilinmeyen

Mümkün mü? 

O kadar büyük ki

Sonun oyunu sahnede 

Perde perde

Kendini aramak denen 

Yalan belki de

İpler kimin elinde? 

Dudaklarda birkaç hece

Artık unutulmuş cümleler

Vurgun yedikten sonra

Girdaplara takılmak gırtlakta

Yolda yürürken

Birden uyanıp

Aynı yerde duruyor 

Buluyorum kendimi

Ne geçmişten, 

Ne gelecekten, 

Bir ses var

Bir ses var

Sadece şimdiyi fısıldıyor...', 'Sonun oyunu sahnede  Perde perde Gel git anlar  Neyi anlatıyor?  Dudaklarda birkaç hece Artık unutulmuş cümleler Aşınmış hayatlar... Çıkacak...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ersin Taşel']::text[], 8.5, '{"poet":"Ahmet Ersin Taşel","poet_slug":"ahmet-ersin-tasel","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gel-git-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babam', 'babam-ahmet-ersin-tasel-8z7to', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir adam var...

Ufak tefek

Ama yaptıkları büyük

Gençken o da yalnız yaşamış

Gün gelip evlenmiş

Taş kalbi zamanla yumuşamış

Ne yapacağını bilememiş

Söküp atmış hemen

Beğenmemiş

Yüreğinden kopardığı çamuru

Zamanı geçmeden yoğurmuş hamuru

Ömrünün sonuna doğru

Heykeller yapmaya başlamış elleriyle

Küçük küçük

Bir adam var...

Düşüncelerinde olduğumu bildiğim

Kalbine bir an olsun giremediğim

Belki de hamurumdan

Bir adam var...

Şimdi, uzaklarda bana

Yerini bildiğim 

İşte ben 

O adamın

Sertleşen hamuruyla yaptığı

Son eseriyim', 'Bir adam var... Ufak tefek Ama yaptıkları büyük Gençken o da yalnız yaşamış Gün gelip evlenmiş Taş kalbi zamanla yumuşamış Ne yapacağını bil...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ersin Taşel']::text[], 8.5, '{"poet":"Ahmet Ersin Taşel","poet_slug":"ahmet-ersin-tasel","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/babam-492-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şey Zamanında Güzel', 'her-sey-zamaninda-guzel-ahmet-ersin-tasel-zg2pq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayaline sarıldığım günler oldu.

Şimdiden yaz sonunu hayal ediyorum.

Dalgaların sesini, 

Geceleri öten cırcırları, 

Yalpalanan sandalları, 

Mehtap sefalarını, 

Uçları kurumuş yaprakları

Çam kokusunu, 

Suya özlem duyan 

Kurumuş toprakları özlüyorum.

Her şey olduğu gibi güzel.

Elimde olsa, yüzünü bir kez görmüş olsam!

Resminle kaplardım gökleri.

Aramama gerek kalmasın

Tüm insanlar 

Aşkın büyüklüğünü yeniden anlasınlar diye.

Zamanı gelmeden, 

Yüzünü daha görmeden, 

Şimdiden, 

Seni deli gibi seviyorum.

Oysa her şey olduğu gibi güzel

Çünkü sahibi

Buz gibi yalnızlıkta, 

En derin boşlukta, 

Kaybolunmuş karanlıkta bile

Alev alev yanan

Işıl ışıl parlayan

Yitirilmemiş umutları yerleştirmiş göklere

Her şey olduğu gibi güzel

Ve sevdiğim

Her şey zamanında güzel

Zamanı gelmeden seni sevmişim meğer', 'Hayaline sarıldığım günler oldu. Şimdiden yaz sonunu hayal ediyorum. Dalgaların sesini,  Geceleri öten cırcırları,  Yalpalanan sandalları,  ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ersin Taşel']::text[], 8.5, '{"poet":"Ahmet Ersin Taşel","poet_slug":"ahmet-ersin-tasel","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/her-sey-zamaninda-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Gecesi', 'ask-gecesi-reha-basogul-ps2y3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hüzzam kendinden geçmiş, bu gece sahtekâr

tanbur cenk eylemiş, çığlığı zülfikar

rebap ihya yolunda, bedenimde hünkâr

Aşk gecesi bu gece 

gönlümde acı bir şerbet var

Ötüyor alevler denizime durmuş asi

düşünmek hepimize olmuş bu anda vahi

haydi durma dön, karşında işte sani

Aşk gecesi bu gece

gönlümde acı bir şerbet var

Kaçıyor meclisimden biri, adı mazlum

yakalayamam onu, ben basit bir kulum

süslenmiş mahşere elbet düşecektir yolum

Aşk gecesi bu gece

gönlümde acı bir şerbet var

dilim karanlık, gözüm gümüşten kamerî

hüznüm sancılı, yaram derinden firdevsi

sözüm bitmiş, duramam ki yeniden mahfi

Aşk gecesi bu gece

gönlümde acı bir şerbet var

sağıma soluma yerleşmiş, nurdan bir iclâl

adını anamam, biliyor bunu arzuhâl

kaybettim dilimin dinini, kanıyor inceden lâl

Aşk gecesi bu gece

gönlümde acı bir şerbet var

sorarım fani dilime niye konuşursun udî

bilmez misin kimsesizim nedir bu cebri

yaklaş kalbime, uyandırmayalım iblisi

Aşk gecesi bu gece

gönlümde acı bir şerbet var

ayyaş dolaşalım ki bu gece 

                                               üflenelim neyden

nefes olalım ki bu gece 

                                               bezenelim sesten

aşık olalım ki bu gece 

                                               doğalım bir''den

Aşk gecesi bu gece

gönlümde acı bir şerbet var', 'hüzzam kendinden geçmiş, bu gece sahtekâr tanbur cenk eylemiş, çığlığı zülfikar rebap ihya yolunda, bedenimde hünkâr Aşk gecesi bu gece  gön...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/ask-gecesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Hep Çocuktuk', 'biz-hep-cocuktuk-hakan-keskin-pva2v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Büyük kitaplar okuduk

adı kendinden büyük.

Büyümedik.

Büyük sözler söyledik yaşama ve insana dair.

Büyümedik.

Küçük acılara kurban ettik büyük mutluluklarımızı.

Kuşanıp sevdaları yorgun yüreklerimize

sürdük umutları

üzerine gelecek zamanların.

Avuçlarımızda kurumuş çiçekler, 

ve hüzünlü bakışlar kaldı gözlerimizde.

Çocukluğumuz...

El değmemiş korkularıyla gömüldü geçmişimize.

Yıllarımızı adadık kavgalarımıza.

Her şeyi; 

Ama her şeyi bilmek istedik.

Her şeyi yapmak, 

Her şeyi tanımaktı amacımız.

Ve dünyayı yaşanır kılmak için ettik güya onca lafı.

Anladık yanlıştı bir şeyler.

Hep geç anladığımız her şey gibi.

Ve anladık

zamanın gerisinden sürüklendi hep bilincimiz.

geciken sevmelerimiz gibi.

Ve şimdi zamanın öylesine bir yerinde.

Ne geri dönmesi olası, 

ne de ışığı görmesi...

Bedelini ödeyemedik yaşamın.

Ağır geldi.

Kaldıramadık yükünü, 

sosuz mutluluklara gebe kavgaların

ve –sonsuzluğu teslim almak istercesine- büyük aşkların.

Çünkü bizden büyüktü onlar.

Çünkü, 

biz hep çocuktuk.', 'Büyük kitaplar okuduk adı kendinden büyük. Büyümedik. Büyük sözler söyledik yaşama ve insana dair. Büyümedik. Küçük acılara kurban ettik büy...', ARRAY['Türk Edebiyatı','Şiir','Hakan Keskin']::text[], 8.5, '{"poet":"Hakan Keskin","poet_slug":"hakan-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/biz-hep-cocuktuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol III', 'yol-iii-hakan-keskin-px8v4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yol…

Ya ayrılıkla başladı

	Ya ayrılık vardı ucunda yolun.

Ve yine ayırıyor beni bir şeylerden.

…

Sigaraya gitti elim.

Şeritlere takıldı yine gözlerim

	kesik kesik akan

		Sevdalarım gibi.

Bir “ay” büyüttüm içimde

		karanlığa inat.

Oysa gün ışığında yitirmiştim sevdiğim ne varsa.

Bilmediğim bir yoldu yürüdüğüm

		her durakta bir parçamı bırakarak.

Yanlızca küçük bir ışık görme umudunu taşıdı direnişim

ama yine yenik ayrılıyorum bu meydan savaşından.

Şimdi demir alıyorum usul usul

		açık denizlere

			küskün…

Onarıp yorgun gövdemi

Yol almak için yeni bir limana

	bu defa savaşı kazanmak umuduyla.

Yol…

Durmuyor.

Hiç durmadı.

Hiç usanmadı

	hep koparıp aldı umutlarımı benden.

ben hep umut ettim yine

	ama o hep daha güçlü geldi

		alıp gitti nem varsa yaşama

 ve sevgiye dair.

Yoruldum.

Yol kenarlarındaki gölgelerle oynadım bir ara.

Teybin sesini açtım.

Bir sigara ve bir-iki küçük sohpet…

Geçmiyor zaman...

Susuyorum.

Yolu seyre dalıyorum yeniden.

Adını fısıldıyorum sessizce...

		hoşuma gidiyor.

Gülüşün geliyor aklıma... 

		gülüyorum ben de.

Hiç durmadan akıyor yol

	ve her an biraz daha alıp götürüyor beni senden.

Ağırlaşıyor gözkapaklarım

Yeniliyorum uykuya.

	…	

		elimi tutuyorsun

		usulca öpüyorum parmaklarından

		gülüyorsun.

		gülüyorum ben de.

		üzgünüm diyorsun sonra, 

			ben bin kere ölüyorum.

…

Gün ağarmış.

Sigaraya uzanıyor yine elim.

Sen hala uyumamış bana bakıyorsun.

Ne yana dönsem oradasın.

Usulca kapattım gözlerimi.

	…

		elimi uzattım yine

			üzgünüm dedin 

		ben hep yeniden denedim

			sen hep üzgündün.

	…

Yine bitti bir yolculuk.

Ne yağmur vardı ardında gecenin

Ne de sıcak bir rüzgar yüzümü okşayan.

Üşüdüm

	hiç üşümediğim kadar.

Tükenmiştim.

Sense üzgündün sadece.

Zor geliyor vazgeçmek.

Ne olur sen de dön deme.

Ne olur uyma sen de içimdeki korkak çocuğa.

Bırak uzasın gece

	bitmesin yol

Hiç bilmeyeyim sonunu

Sen hiç tutma ellerimden istersen

Ama dön deme ne olur.', 'Yol… Ya ayrılıkla başladı 	Ya ayrılık vardı ucunda yolun. Ve yine ayırıyor beni bir şeylerden. … Sigaraya gitti elim. Şeritlere takıldı yine...', ARRAY['Türk Edebiyatı','Şiir','Hakan Keskin']::text[], 8.5, '{"poet":"Hakan Keskin","poet_slug":"hakan-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/yol-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızıl Karanlık', 'kizil-karanlik-hakan-keskin-4pi8r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir mum aleviyle boyanır

	her gece kızıla.

Saçların kızıl…

Dudakların kızıl…

Gece kızıl. 

Erir içim bir mum ışığıyla

		gözlerinde.

Şarap sarhoşluğunda başım

Sözcüklerim yalpalar dudaklarımda.

Anlatamıyorsam gülüm çaresizliğimi

		beceremediğimden bakmayı.

Ve titriyorsam üstüne küçücük bir mumun

		korktuğumdandır karanlıktan.

Bir mum daha yak benim için 

		getiremezse sonunu gecenin tek mum.', 'Bir mum aleviyle boyanır 	her gece kızıla. Saçların kızıl… Dudakların kızıl… Gece kızıl.  Erir içim bir mum ışığıyla 		gözlerinde. Şarap sar...', ARRAY['Türk Edebiyatı','Şiir','Hakan Keskin']::text[], 8.5, '{"poet":"Hakan Keskin","poet_slug":"hakan-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kizil-karanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuzluk Doğdu Sonundan', 'sonsuzluk-dogdu-sonundan-umut-ulbegi-ihgn5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tadına var geleceğinin

yüreği kilitli

yazgısı derisine kazınmış çocuk

Vadiler çılgın yağmurlarla yıkandığında 

ve gökyüzü yeryüzüne kan kokusu almış 

kurt sürüleri gibi yaklaştığında

açacaksın kapılarını

unutulan geçmişinin

Tadına var geleceğinin

doğuşun günahtı

ilk sözcüklerin yasak

adımların lanet 

kanatlarının altından meydan okuyordun yaratılışına 

Gücünü gece gördü

güçsüzler gördü

ölümsüzler gördü

Gölgeni yanına almış, ikiz yıldırımlar gibi düştüğünde dağlara

ve dağları denizlere kadar kovalayıp

küçük tepeleri özgür bıraktığında 

açıldı kapıların

Yüreği prangalı

gözleri yazgısıyla dağlanmış çocuk

yoktu artık

sonsuzluk doğdu

sonundan', 'Tadına var geleceğinin yüreği kilitli yazgısı derisine kazınmış çocuk Vadiler çılgın yağmurlarla yıkandığında  ve gökyüzü yeryüzüne kan koku...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sonsuzluk-dogdu-sonundan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlardı Kız Kulesi', 'aglardi-kiz-kulesi-canan-sagmen-ov461', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dilimden düşen iki kelime

Sessiz bir tarihti 

Meryem Ana’nın kız kardeşi 

Üsküdar’da masum bir bakire

Gülümserken  simsiyah gecede 

Gördüğüm ışıklı bir aydı 

Çivilenen  puslu semada 

 Oturmadan evvel karşısına 

Aşinaydım ona

Yalnızlığımla 

Yüzümün kırık aynalarından 

Düşen elem  taneleriyle 

Geçmiş zaman masallarını 

Aşıp gelmiş eklenmiştim geceye

Aykırı  değildim 

Hem sakin ve huzurlu, 

Kız Kulesi bir efsane miydi? 

Ama aşıktık hiç yoktan 

O bir şehri İstanbul güzeli 

Edası yok kimsede 

Mağrurdu olabildiğince

Çok geçmeden bir martının  kanadı

Çığlık çığlığa acıtırdı bizi

Yanardı içimiz

Ağlardı Kız Kulesi

Şarap şişelerinde bir şölendi 

Masal yaşamım, gerçekliğim

Balıkçı tekneleri

Yakamozlarla süslerken geceyi 

Ellerimin buz kesmişliğiyle 

Savrulurdu tütünün en efkarlısı 

Onun dingin narin gövdesine 

İstanbul’aydı şiirim sevdam

Kız kulesi üşürdü yalnızlığından 

Ben ağlardım

(13/11/2002)', 'Dilimden düşen iki kelime Sessiz bir tarihti  Meryem Ana’nın kız kardeşi  Üsküdar’da masum bir bakire Gülümserken  simsiyah gecede  Gördüğüm...', ARRAY['Türk Edebiyatı','Şiir','Canan Sağmen']::text[], 8.5, '{"poet":"Canan Sağmen","poet_slug":"canan-sagmen","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/aglardi-kiz-kulesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet Geceleri', 'gurbet-geceleri-kemalettin-kamu-hektc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bekçisiyim, bu serin

Bu siyah gecelerin

Gurbetten daha derin

Bir yara yok içimde! 

Korku bilmez ölümden

Her gün yeniden ölen

Bir bade gibi neden

Biteyim bir içimde! 

Ne aşkım, ne emelim

Soluk bir karanfilim

Ben gurbette değilim

Gurbet benim içimde!', 'Bekçisiyim, bu serin Bu siyah gecelerin Gurbetten daha derin Bir yara yok içimde!  Korku bilmez ölümden Her gün yeniden ölen Bir bade gibi n...', ARRAY['Türk Edebiyatı','Şiir','Kemalettin Kamu']::text[], 8.5, '{"poet":"Kemalettin Kamu","poet_slug":"kemalettin-kamu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gurbet-geceleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden', 'yeniden-canan-sagmen-beopf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu güzel kasım sabahı 

Güneşli günler 

Bu  bahar havası 

Kuşların cıvıltısı

Ah ne güzel 

Bir bebeğin ışıltılı gözleri 

Avuçlarken gün ışığını, 

Parmaklarımdan akan ışık hüzmeleri 

Göğü kucakladım sıcacıktı

Sağnak bir yağmur sonrası

Bir bukalemin gibi

Ebemkuşağının o eşsiz renkleri 

Attım üzerimdeki 

O eski 

O yılgın kabuğu

Artık

Dağlar kadar güçlü 

Vadiler kadar huzurlu

Bir ırmağın berrak maviliği

Çayır yeşili 

Yaşamın solan tüm renkleri 

Bir bir boyadım sizi 

Yeniden buldum 

Kaybettiğim umudu

Dün gece usulca 

Yıldızlar fısıldadı 

Ah yıldız olmak 

Ne güzel 

Ömrümüz narin bir kelebek

Ölüm ansızın gelecek 

Giderken de 

Gülümsemek 

Hepsi bu 

Yaşam bundan ibaret 

(27/11/2002)', 'Bu güzel kasım sabahı  Güneşli günler  Bu  bahar havası  Kuşların cıvıltısı Ah ne güzel  Bir bebeğin ışıltılı gözleri  Avuçlarken gün ışığın...', ARRAY['Türk Edebiyatı','Şiir','Canan Sağmen']::text[], 8.5, '{"poet":"Canan Sağmen","poet_slug":"canan-sagmen","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/yeniden-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzmir''e Tahassür', 'i-zmir-e-tahassur-kemalettin-kamu-vsm6v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anne, deniz nerde, yalımız nerde? 

Hani gideceğimiz İzmir''e der de

Beni uyuturdun dizinde anne! 

Geçende ablam da öyle diyordu

Bu bahar İzmir''e girmezse ordu

Kanmam sözünüze sizin de anne! 

Yeşil bir bahara büründü dağlar

Bülbüllü bahçeler, üzümlü bağlar

Kimlerin işine yarıyor anne! 

O bağlar nerede, bahçeler nerde? 

Her akşam güneşin battığı yerde

Gözlerim İzmir''i arıyor anne! 

Şimdi bir kuş olsam, kanadım olsa

İzmir''e giden yol eğer bu yolsa

Bir başıma bile giderim anne! 

Bir çetin bilmece sorsam Paşa''dan

Söylemem memleket bağışlamadan

Mutlaka İzmir''i isterim anne!', 'Anne, deniz nerde, yalımız nerde?  Hani gideceğimiz İzmir''e der de Beni uyuturdun dizinde anne!  Geçende ablam da öyle diyordu Bu bahar İzmi...', ARRAY['Türk Edebiyatı','Şiir','Kemalettin Kamu']::text[], 8.5, '{"poet":"Kemalettin Kamu","poet_slug":"kemalettin-kamu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/izmir-e-tahassur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz', 'guz-kemalettin-kamu-uwa85', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kurudu artık otlar

Bitmiyor tazeleri

Birikinti sularda

Yaprak cenazeleri

Döndü yayladakiler

Erdi dağlara batı

Ovalar daha geniş

Kayalar daha katı

Başım avuçlarımda

Bir ağır külçe hüzün

Düşüyor gözlerime

Çiğ taneleri güzün', 'Kurudu artık otlar Bitmiyor tazeleri Birikinti sularda Yaprak cenazeleri Döndü yayladakiler Erdi dağlara batı Ovalar daha geniş Kayalar daha...', ARRAY['Türk Edebiyatı','Şiir','Kemalettin Kamu']::text[], 8.5, '{"poet":"Kemalettin Kamu","poet_slug":"kemalettin-kamu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/guz-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söğüt', 'sogut-kemalettin-kamu-byu7u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dalın eğri büğrü yaprağın ince

Rengin iğdeleşir rüzgar esince

Yazın şemsiyesin yaşlıya gence

Güzün derelere verirsin öğüt.

Sılacı dibinde unutur çile

Esintin avutur bozkırı bile

Dökün tozlarını sabah yeliyle

Akşam güneşi ile boyunu büyüt.

Bir tünek olmadan kolların kara

Yollama gölgeni öbür bahara

Yaprak dökümünde uyup rüzgara

Yorgun dallarını sallama söğüt.', 'Dalın eğri büğrü yaprağın ince Rengin iğdeleşir rüzgar esince Yazın şemsiyesin yaşlıya gence Güzün derelere verirsin öğüt. Sılacı dibinde un...', ARRAY['Türk Edebiyatı','Şiir','Kemalettin Kamu']::text[], 8.5, '{"poet":"Kemalettin Kamu","poet_slug":"kemalettin-kamu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sogut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Üzülme', 'sen-uzulme-erdem-demirkol-ehkls', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gül yanaklarına çiğ düşmesin, 

Ben, senin için ağlarım.

Konuşma, yorulmasın dudakların, 

Ben, gözlerinden anlarım.

Gözlerin süzgün olmasın.

Sen hep gül, ben üzülürüm.

Buğday yanığı tenin ürpermesin, 

Senin yerine ben üşürüm.

Sen rahat uyu sevdiceğim.

Ben hep uyanık olacağım.

Geceleri sakın korkme bebeğim.

Seni yıldızlarda bulacağım.

Dert etme gözleri can yakanım, 

Yalan olsun, sözlerine kanarım.

Üzülme, kışlada elbet gün doğacak.

Şafakta, ellerin ellerimde olacak.

Sen üzülme, ne olursa olsun.

Ölmek mi? O da senin için olsun.

(27.09.2002-Hadımköy/İST.)', 'Gül yanaklarına çiğ düşmesin,  Ben, senin için ağlarım. Konuşma, yorulmasın dudakların,  Ben, gözlerinden anlarım. Gözlerin süzgün olmasın. ...', ARRAY['Türk Edebiyatı','Şiir','Erdem Demirkol']::text[], 8.5, '{"poet":"Erdem Demirkol","poet_slug":"erdem-demirkol","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sen-uzulme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerimi Vermedim', 'gozlerimi-vermedim-yavuz-selim-dizdar-epj0p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bütün organlarımı bağışladım

Bir gözlerimi bıraktım kendime 

Kimse sana

Benim baktığım gözlerle bakmasın diye', 'Bütün organlarımı bağışladım Bir gözlerimi bıraktım kendime  Kimse sana Benim baktığım gözlerle bakmasın diye...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Selim Dizdar']::text[], 8.5, '{"poet":"Yavuz Selim Dizdar","poet_slug":"yavuz-selim-dizdar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gozlerimi-vermedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günaydın II', 'gunaydin-ii-murat-tali-2ygbf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'notalardan ayrılmışta gelmiş bir ezgi, 

bir kuş ötmesi onlarca kalan yaprak arasından, 

bir düş seslerin içinden çıkıp gelen, 

korkulukları yıkılmış evlerden, 

çamurdan asfalta dönmüş sokaklar arasından, 

paçası kirlenmiş çocuklardan, 

gölgelere sığınıp yüzünü güneşten kaçıran insanlardan, 

ifade edilemeyen kelimelerden, 

sıyrılıp gidemediğimiz ve bir türlü de varamadığımız yarınlarımızdan, 

binlerce güzellikten uzakta yaşadığımız KENDİMİZe

binlerce güzel ses ile eşlik ederek GÜNE katılmak dileğiyle

GÜNAYDIN', 'notalardan ayrılmışta gelmiş bir ezgi,  bir kuş ötmesi onlarca kalan yaprak arasından,  bir düş seslerin içinden çıkıp gelen,  korkulukları ...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gunaydin-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SarpA SarmaK', 'sarpa-sarmak-siyar-durul-w0ysg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Alınan her nefes sonrası, havaya karbondioksitle karışık hüzün bırakılırdı o zamanlar.

Bir iki ölçü umut vardı, hayata katılmak için bekleyen.

Önce çukurca bir kalp alınır diye başlayan tarifleri hiç uyduramadık kitabına...

Aşk yapacağız derken göz çıkardık! 

Parktaki salıncağın yalnızlığıyla başlayan gecelerde, mumla uyku aradık samanlıkta.

Gez, göz, arpacık doğrultusu sadece benim defterimde üçgen oluşturdu! 

Aynanın arkasında, görevi yansımak olan görüntümün kaybolmasıyla anladım, 

Yittiğimi! 

Tüm cümleler yüklemsiz kaldı! 

(Başlık: Özgür HATEM)', 'Alınan her nefes sonrası, havaya karbondioksitle karışık hüzün bırakılırdı o zamanlar. Bir iki ölçü umut vardı, hayata katılmak için bekleye...', ARRAY['Türk Edebiyatı','Şiir','Şiyar Durul']::text[], 8.5, '{"poet":"Şiyar Durul","poet_slug":"siyar-durul","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sarpa-sarmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökkuşağında Kalan Şehir', 'gokkusaginda-kalan-sehir-umut-ulbegi-zweec', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şimdi gidiyorum

çok sevdiğim bu şehri bırakıp 

ardıma bile bakmadan kaçıyorum

Yalnızlığımla dolduruyorum içimdeki ıssızlığı

Sevda sancısını örtüyor ayrılık

Hayalini kurduğum sıcaklığın sonu mu geliyor yoksa 

uzaklardan esen soğuk rüzgarlarla seni yitiriyor muyum? 

Bilemediğim

belki de bilmek istemediğim acıların keskin çığlıkları

yakıp geçiyor gökyüzünü

Umutsuzluğuma umutsuzluk katıyor görmek

ilkbaharları yıkıp geçen sonsuz hüznü

İkimiz de bir tünelin içindeyiz ama sen baştasın

bense çıkmak üzereyim karanlıktan

Seni uçurmak istediğimde gökkuşağının yedinci rengine

yüzünde kaderciliğinin simgesi umursamazlığınla gerilerde kalıyorsun

ben renkten renge dolaşırken bebeğim

sen okyanusta bir taş kadar soğuk ve umarsızca

bekliyorsun sonunu doğan günün ve yalnız gecenin', 'Şimdi gidiyorum çok sevdiğim bu şehri bırakıp  ardıma bile bakmadan kaçıyorum Yalnızlığımla dolduruyorum içimdeki ıssızlığı Sevda sancısını ...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gokkusaginda-kalan-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırk Haramilerin Esiri', 'kirk-haramilerin-esiri-nazim-hikmet-ran-1spge', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geniş dallardan sızan gecenin gölgesiyle, 

Ormanda uğuldayan yağmurların sesiyle, 

Bu akşam renklerini kaybedince her çiçek. 

Bir kahraman esirin kolları kesilecek. 

Bu bir şanlı erdir ki Rabbi bulmuş kanında. 

Bir kere düşürmeden yüksek mağrur alnında. 

Alevden bir sancağın taşımış gölgesini. 

Memleketler çökermiş yükseltince sesini. 

Tam altı yüz yirmi yıl bir nur için döğüşmüş, 

Fakat günün birinde kafir eline düşmüş. 

Şimdi ezmek istiyor onu kırk haramiler, 

Bu son akşam kalbinde rabbi bulmazsa eğer. 

Ormanda renklerini kaybedince her çiçek.', 'Geniş dallardan sızan gecenin gölgesiyle,  Ormanda uğuldayan yağmurların sesiyle,  Bu akşam renklerini kaybedince her çiçek.  Bir kahraman e...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kirk-haramilerin-esiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arhaveli İsmail''in Hikayesi', 'arhaveli-i-smail-in-hikayesi-nazim-hikmet-ran-8yx3d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ateşi ve ihaneti gördük. 

Düşman ordusu yine başladı yürümeğe. 

Akhisar, Karacabey, 

Bursa ve Bursa''nın doğusunda Aksu, 

çarpışarak çekildik... 

920''nin 

29 Ağustos''u: 

Uşak düştü. 

Yaralı 

ve dehşetli kızgın 

fakat toprağımızdan emin, 

Dumlupınar sırtlarındayız. 

Nazilli düştü. 

Ateşi ve ihaneti gördük. 

Dayandık 

dayanmaktayız. 

1920 Şubat, Nisan, Mayıs, 

Bolu, Düzce, Geyve, Adapazarı: 

İçimizde Hilâfet Ordusu, 

Anzavur isyanları. 

Ve aynı sıradan, 

3 Ekim Konya. 

Sabah. 

500 asker kaçağı ve yeşil bayrağıyla Delibaş 

girdi şehre. 

Alaeddin tepesinde üç gün üç gece hüküm sürdüler. 

Ve Manavgat istikametlerinde kaçıp 

ölümlerine giderken 

terkilerinde kesilmiş kafalar götürdüler. 

Ve 29 Aralık Kütahya: 

4 top 

ve 1800 atlı bir ihanet 

yani Çerkez Ethem, 

bir gece vakti 

kilim ve halı yüklü katırları, 

koyun ve sığır sürülerini önüne katıp 

düşmana geçti. 

Yürekleri karanlık, 

kemerleri ve kamçıları gümüşlüydü, 

atları ve kendileri semizdiler... 

Ateşi ve ihaneti gördük. 

Ruhumuz fırtınalı, etimiz mütehammil. 

Sevgisiz ve ihtirassız çıplak devler değil, 

inanılmaz zaafları, korkunç kuvvetleriyle, 

silâhları ve beygirleriyle insanlardı dayanan. 

Beygirler çirkindiler, 

bakımsızdılar, 

hasta bir fundalıktan yüksek değillerdi. 

Fakat bozkırda kişneyip köpürmeden 

sabırlı ve doludizgin koşmasını biliyorlardı. 

İnsanlar uzun asker kaputluydu, 

yalnayaktı insanlar. 

İnsanların başında kalpak, 

yüreklerinde keder, 

yüreklerinde müthiş bir ümit vardı. 

İnsanlar devrilmişti, kedersiz ve ümitsizdiler. 

İnsanlar, etlerinde kurşun yaralarıyla 

köy odalarında unutulmuştular. 

Ve orda sargı, 

deri 

ve asker postalları halinde 

yan yana, sırtüstü yatıyorlardı. 

Koparılmış gibiydi parmakları saplandığı yerden 

eğrilip bükülmüştü 

ve avuçlarında toprak ve kan vardı. 

Ve asker k
..........
..........', 'Ateşi ve ihaneti gördük.  Düşman ordusu yine başladı yürümeğe.  Akhisar, Karacabey,  Bursa ve Bursa''nın doğusunda Aksu,  çarpışarak çekildik...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/arhaveli-ismail-in-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Manastırlı Hamdi Efendi ve Reşadiyeli Veli Oğlu Mehmet''in Hukayesi', 'manastirli-hamdi-efendi-ve-resadiyeli-veli-oglu-mehmet-in-hukayesi-nazim-hikmet-ran-u859j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '«Bu hamiyetli ve cesur, Manastırlı Hamdi Efendi olmasaydı, İstanbul felâketinden kim bilir haber almak için 

ne kadar intizarlar içinde kalacaktık. İstanbul''da bulunan nâzır, mebus, kumandan, teşkilâtımız mensupları 

içinden bir zat çıkıp vaktiyle bize haber vermeği düşünmemiş olduğu anlaşılıyor. Demek ki cümlesini heyecan 

ve helecan kaplamıştı. Bir ucu Ankara''da bulunan telin İstanbul''da bulunan ucuna yanaşamayacak kadar 

şaşkın bir hale gelmiş olduklarına bilmem ki hükmetmek caiz olur mu? » 

(Nutuk, s.295, Devlet Basımevi, İstanbul 1938) 

920''nin 16 Martı. 

Öğleden evvel 

saat onda 

makina başında şöyle bir telgraf aldı Ankara''daki: 

«Der-aliye 16/3/1920. 

İngilizler bastı bu sabah 

Şehzadebaşı''ndaki Muzika karakolunu. 

Müsademe edildi. 

İşgal altına alıyorlar İstanbul''u şimdi. 

Berâyi malûmat arzolunur. 

Manastırlı Hamdi.» 

920''nin 16 Martı. 

Harbiye Nezareti telgrafhanesi buldu Ankara''yı: 

«Etrafta dolaşıyor İngiliz askerleri. 

Şimdi işte 

İngiliz askerleri giriyorlar nezarete. 

İşte giriyor
..........
..........', '«Bu hamiyetli ve cesur, Manastırlı Hamdi Efendi olmasaydı, İstanbul felâketinden kim bilir haber almak için  ne kadar intizarlar içinde kala...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/manastirli-hamdi-efendi-ve-resadiyeli-veli-oglu-mehmet-in-hukayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kız Vardı Japonya''da', 'bir-kiz-vardi-japonya-da-nazim-hikmet-ran-d5uns', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir kız vardı Japonyada 

ufacık, tefecik bir kız, 

Bir bulut vardı dünyada 

işi: öldürmekti yalnız. 

Bu bulut bu kızcağızın 

öl
..........
..........', 'Bir kız vardı Japonyada  ufacık, tefecik bir kız,  Bir bulut vardı dünyada  işi: öldürmekti yalnız.  Bu bulut bu kızcağızın  öl .......... ....', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-kiz-vardi-japonya-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulut mu Olsam', 'bulut-mu-olsam-nazim-hikmet-ran-yy8fh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Denizin üstünde ala bulut 

yüzünde gümüş gemi 

içinde sarı balık 

dibinde mavi yosun', 'Denizin üstünde ala bulut  yüzünde gümüş gemi  içinde sarı balık  dibinde mavi yosun...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bulut-mu-olsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklar Ölebilir Yarın', 'cocuklar-olebilir-yarin-nazim-hikmet-ran-0bp5f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çocuklar ölebilir yarın, 

hem de ne sıtmadan ne kuşpalazından 

düşerek te değil kuyulara filân; 

çocuklar ölebilir yarı
..........
..........', 'Çocuklar ölebilir yarın,  hem de ne sıtmadan ne kuşpalazından  düşerek te değil kuyulara filân;  çocuklar ölebilir yarı .......... ............', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/cocuklar-olebilir-yarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum', 'dogum-nazim-hikmet-ran-0mmk2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anası bir oğlancık doğurdu bana; 

kaşsız, sarı bir oğlan, 

masmavi kundağında yatan 

bir nur topu, üç kilo ağırlığında. 

Benim oğlan 

dünyaya geldiği zaman, 

çocuklar doğdu Korede, 

sarı ay çiçeğine benziyorlardı. 

Makartır kesti onları, 

gitti
..........
..........', 'Anası bir oğlancık doğurdu bana;  kaşsız, sarı bir oğlan,  masmavi kundağında yatan  bir nur topu, üç kilo ağırlığında.  Benim oğlan  dünyay...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dogum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyayı Verelim Çocuklara', 'dunyayi-verelim-cocuklara-nazim-hikmet-ran-jxye5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dünyayı verelim çocuklara hiç değilse bir günlüğüne 

allı pullu bir balon gibi verelim oynasınlar 

oynasınlar türküler
..........
..........', 'Dünyayı verelim çocuklara hiç değilse bir günlüğüne  allı pullu bir balon gibi verelim oynasınlar  oynasınlar türküler .......... .............', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/dunyayi-verelim-cocuklara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyi Bildirir Sayılar', 'neyi-bildirir-sayilar-nazim-hikmet-ran-3sycp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sayılar bebelerin kundakları 

sayılar tabutları şehirlerin 

öldürülmüş 

öldürülebilecek olan 

sayılar yaklaşan bir şeyleri bildirir 

sayılar bildirir uzaklaşan bir şeyleri 

nedir yaklaşan bize 

bizden uzaklaşan nedir 

dünya savaşı: I 

dünya savaşı: II 

14''ten 18''e 39''dan 45''e 10 yıl 54 milyon ölü 

49 milyon sakat 

ölülerle sakatların memleketi 

103 milyon nüfuslu bir memleket 

ve ayrıca öksüzleri delileri yanık taşlarıyla 

ve gidenlerden biri evimizdendi 

gitti dönmedi bir daha 

19''unda mıydı 40''ında mıydı aklımda kalmamış 

döndü iki gözü kör 

gök gözlü müydü kara gözlü müydü aklımda kalmamış 

döndü dizkapağından kesik sol bacağı 

döndü ve kapısını bulamadı evinin 

14''ten 18''e 39''dan 45''e 10 yıl 54 milyon ölü 

49 milyon sakat 

yeryüzünde yuvarlak hesap ve şimdilik 2,5 milyarız 

% 80''imiz aç 

dişlerimiz dökülüyor 

dişetlerimiz yara içinde 

ölü derilerimiz çatlak 

hele çocuklarımız 

sallanan koca kafaları 

kırış kırış yüzlerinde kederli iri gözleriyle 

ve eğri büğrü incecik bacakları üstünde karınları 

davul gibi', 'sayılar bebelerin kundakları  sayılar tabutları şehirlerin  öldürülmüş  öldürülebilecek olan  sayılar yaklaşan bir şeyleri bildirir  sayılar...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/neyi-bildirir-sayilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ses', 'ses-nazim-hikmet-ran-ef3td', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çeneni avuçlarının içine alıp, 

duvara dalıp 

kalma! . 

Çeneni avuçlarının içine alma! . 

Kalk! 

Pencereye gel! 

Bak!', 'Çeneni avuçlarının içine alıp,  duvara dalıp  kalma! .  Çeneni avuçlarının içine alma! .  Kalk!  Pencereye gel!  Bak!...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ses-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Parmaklarımdaki Kırlangıç', 'parmaklarimdaki-kirlangic-umut-ulbegi-tawg4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevdan

yalnızlık bahçesi

ve sen en değerli çiçeğisin o bahçenin

ulaşılması zor

ulaştığımda renklerin soluyor

uçuyorsun parmaklarımdan

güneşe bakıyorsun

bir kırlangıç gibi

güneşe kaçıyorsun

Sonum olacaksın

sonum

yalnızlık bahçesi

Ben en değersiz çiçeğiyim o bahçenin

ve sen ezip geçiyorsun.', 'Sevdan yalnızlık bahçesi ve sen en değerli çiçeğisin o bahçenin ulaşılması zor ulaştığımda renklerin soluyor uçuyorsun parmaklarımdan güneşe...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/parmaklarimdaki-kirlangic-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aylardan Kış', 'aylardan-kis-aydanur-sarac-nni3a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sadece siz değil her şey, siz gibi kirlendi.

avlunuzda heceleriniz

yarım heceleriniz senem hanım, 

güzünü sevmeyen, 

elleriniz var aylardan kış

unutmadım, siz beni... çocukluğumdan severdiniz.

neler saklıyordu gözleriniz, gizil aşklar mı...

hani kuşlar uçurduğunuz, 

mektup uçlarından kıskançlıklar

o, gönül sesiniz, 

siz miydiniz diyor, masallar fısıldadığım çocuk

kül kedisini, kar tanelerini... siz de severdiniz

elleriniz sütliman, her ölümün silahı, her bitişin.

..............................

“parklarda onlarca kadın” * ağlatır mı sizi senem hanım

bir afgan’ın dramı, arjantin’de soygunlar

“bir ceviz ağacı”** olsam ne çıkar

ya da nasıl yenir taze bir ceviz 

kirlenmedikçe elleriniz, 

kuşlar konmuyorsa bahçenize.

gökten üç elma nereye düşmüş 

pembe düşler görmüş mü birileri, bir düşünün...! 

bir sabah kapımızda umacılar

askıya aldıklarında kalbimi, 

büyüdüm... senem hanım, büyüdüm korkularla.

* Özcan Öztürk 

** Nazım Hikmet', 'sadece siz değil her şey, siz gibi kirlendi. avlunuzda heceleriniz yarım heceleriniz senem hanım,  güzünü sevmeyen,  elleriniz var aylardan ...', ARRAY['Türk Edebiyatı','Şiir','Aydanur Saraç']::text[], 8.5, '{"poet":"Aydanur Saraç","poet_slug":"aydanur-sarac","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/aylardan-kis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çakı', 'caki-refika-altikulac-1pyn9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Fırlattı çakısını toprağa

tozlu gümüş tadıyla dünya

misket oyunu

yarın hüzünle

alkışlanan ölüm

ceplerinde savaş

bir banka sığmayan

iki yalnızlığın kentiydi göğsü

nedir doğuran cinayeti

tabutuna sığmayan ayaklarıyla

meydan okuyan

bir dar sokağın

anlaşılmaz hüzünlerini saçlarına serpen

geleceğin düşe açılan kapılarından

oyuncak bebeğini

dizlerinde yatıran küçük kız çocuğu: 

korsan! 

korsan! 

kılıcının ucundan

damlayana baksana

bir yılan dolanıyor sandım parmaklarına

fırlatıp attım çakımı toprağa', 'Fırlattı çakısını toprağa tozlu gümüş tadıyla dünya misket oyunu yarın hüzünle alkışlanan ölüm ceplerinde savaş bir banka sığmayan iki yalnı...', ARRAY['Türk Edebiyatı','Şiir','Refika Altıkulaç']::text[], 8.5, '{"poet":"Refika Altıkulaç","poet_slug":"refika-altikulac","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/caki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cemreler gibisin', 'cemreler-gibisin-arif-aydin-6yyqc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Cemreler gibisin

Göz kırpan yıldızların altında

Ellerimde, ellerinin sıcaklığını yaşarken, 

Okyanusların mavi tonları gibi  tarifsiz

Gönlüme işlediğim renkleriyle

Gözlerimi kapatamıyorum.

en son hali kalsın istiyorum, 

gözlerimde gözlerinin

baharların kokusu sinmiş senden bana

cemreler gibisin sevdiğim 

bir  havaya 

bir suya 

bir toprağa 

ve tabii yüreğime  bir anda düşen

hissettiğim sıcaklıkla  müjde  gibisin

bahar yeli gibi, gönlüme hafiften esip

usulca bedenimi saran serinliğe alışırken 

değişen mevsimle  ayrılan sevdalı sesin, 

bu, bu senin sevdan  olsa da, sevdalım

cemreler gibi kısa bir süreli  de olsan

bir nefes sevgi gibi  görünmeyen 

baharın müjdecisi olarak

başka bir baharda yine görüşürüz. 

Bu değişen mevsiminde; 

bu sevdada gülün dikeni de var elbet

bu sonbahar yapraklarımı bitiremez 

bu karlar da beni üşütemez 

ben bu kışı da  atlatırım güzelim

fırtınayı da, yağmuru da 

kaç  güzelim kaç bu mevsimden

ben buradayım elbet bir gün geleceksin

birlikte atacak bu yürek ümitvarım 

başka bir baharda yine görüşürüz.

cemreler gibisin dedim ya.

26.03.200, Ank.', 'Cemreler gibisin Göz kırpan yıldızların altında Ellerimde, ellerinin sıcaklığını yaşarken,  Okyanusların mavi tonları gibi  tarifsiz Gönlüme...', ARRAY['Türk Edebiyatı','Şiir','Arif aydın']::text[], 8.5, '{"poet":"Arif aydın","poet_slug":"arif-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/cemreler-gibisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlu ''Son'' Perde', 'mutlu-son-perde-umut-ulbegi-oyqde', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çok değil bir kaç yıl önce

ilk turlarını atarken yeryüzünde

hiç farkedememişti

yaşamın bir tiyatro 

kendisinin 

''Evde kalmış kız''

rolünde olduğunu

Çok değil bir kaç yıl önce

volta atarken yeryüzünde

hiç farkedememişti

bu tiyatronun toz pembe olmadığını

anladı

karısının tırnaklarını hissettikçe

sahnedeki genç adam

Çok değil birkaç yıl önce

genç adam

ve evde kalmış kız

bu sahnede 

son perdede 

evlendiler.

17.08.1996', 'Çok değil bir kaç yıl önce ilk turlarını atarken yeryüzünde hiç farkedememişti yaşamın bir tiyatro  kendisinin  ''Evde kalmış kız'' rolünde ol...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mutlu-son-perde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay ışığını sevdim yüzünde, gönül diye', 'ay-isigini-sevdim-yuzunde-gonul-diye-arif-aydin-mdfsk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gülleri sevdim kokuları sendendir diye

Denizi sevdim dalgası gözlerindir diye

Güneşle yandım sıcaklığı sevgindir diye

Ay ışığını sevdim yüzünde, gönül diye

Ankara,01 Nisan 2002', 'Gülleri sevdim kokuları sendendir diye Denizi sevdim dalgası gözlerindir diye Güneşle yandım sıcaklığı sevgindir diye Ay ışığını sevdim yüzü...', ARRAY['Türk Edebiyatı','Şiir','Arif aydın']::text[], 8.5, '{"poet":"Arif aydın","poet_slug":"arif-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ay-isigini-sevdim-yuzunde-gonul-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kafes', 'kafes-refika-altikulac-ai5x1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Emily Dickinson’a

Kafka’dan geçince yolum

güneş yılgını parmaklıklar 

beni sev Emily

beni sev diye ağlar

çoğu zaman böyle

sabaha karşı dururken

cebimdeki çılgın dizeler

sorular kuşanıyor

çelimsiz gövdesinden dökülen

sonbahar yapraklarına aldırmadan

toprağı bir avuç taşırmaya çalışan Emily mi? 

boğazında ikindi şarkılarıyla bir adamın

Pazar filesinden dökülen

adamdan önce evine varan

kafes kırıkları yaşamın

kedinin hırlamasına takılıyor

hüküm giymiş yolculuğuna uğurluyor

bir gün batımı öyküsünü

Kafka’dan geçmeli miydi yolum

geçilemeyecekse kafes

Emily yürürken eteğinin hışırtısına takılan

beni sev Emily

beni sev diye ağlayan

kafes kırıklarını

her adımında toprağı taşırmakta kullanan

Pazar yorgunu bir adam', 'Emily Dickinson’a Kafka’dan geçince yolum güneş yılgını parmaklıklar  beni sev Emily beni sev diye ağlar çoğu zaman böyle sabaha karşı durur...', ARRAY['Türk Edebiyatı','Şiir','Refika Altıkulaç']::text[], 8.5, '{"poet":"Refika Altıkulaç","poet_slug":"refika-altikulac","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kafes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evina Dilemin', 'evina-dilemin-abdullah-taybogan-34eo2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Jiyana yeki deste wideye			

Hevalti ji usaye 

Qedere kısmete 

Lı ser yeki dıkın mal

Na ezbeni na 

Balaxwe bide bele

Ka wer pıştaxwe

Bıt feleke u

Bere xwe bıt cihane

Jimıra bej heval u bej

Te kedera kul u birina beje

Ha xwejiya cihane beje

Ka te çı jimıra beje

Bele jımıra bej u bej

le jiyana rasti bej heval

jimıra behsa evine

Behsa roje bık heval

Evin mina cihaneye

Roj ducar lı wane

Lé le evinamın 

Ewkes dijware

Le nave we bela

Dilemınde bimine 

Ne lı ser zimen', 'Jiyana yeki deste wideye			 Hevalti ji usaye  Qedere kısmete  Lı ser yeki dıkın mal Na ezbeni na  Balaxwe bide bele Ka wer pıştaxwe Bıt fele...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Tayboğan']::text[], 8.5, '{"poet":"Abdullah Tayboğan","poet_slug":"abdullah-taybogan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/evina-dilemin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bodrum''da', 'bodrum-da-halikarnas-balikcisi-62swq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yokuş başına geldiğinde 

Bodrum''u göreceksin, 

Sanma ki sen 

Geldiğin gibi gideceksin 

Senden öncekiler de

Böyleydiler 

Akıllarını hep Bodrum''da 

Bırakıp gittiler...', 'Yokuş başına geldiğinde  Bodrum''u göreceksin,  Sanma ki sen  Geldiğin gibi gideceksin  Senden öncekiler de Böyleydiler  Akıllarını hep Bodru...', ARRAY['Türk Edebiyatı','Şiir','Halikarnas Balıkçısı']::text[], 8.5, '{"poet":"Halikarnas Balıkçısı","poet_slug":"halikarnas-balikcisi","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bodrum-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırla', 'hatirla-alfred-de-musset-zhrg3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hatırla, çekingen Tan Güneşe 

        Mutlu sarayını açtığı zaman; 

        Hatırla, geçerken dalgın gece 

        Düş kurup gümüş tülünün altından; 

Göğsün küt küt atarken hazlar davet edince, 

Gölge seni akşamın düşlerine çekince, 

                Ormanların dibinde 

                Bir ses mırıldanır, dinle: 

                        Hatırla. 

        Hatırla, gün gelip beni kader 

        Sonsuza dek senden ayırınca, 

        Üzüntü, sürgün ve seneler 

        Bu çaresiz kalbi soldurunca; 

Düşün son elvedayı, hazin aşkımı düşün! 

Yokluk ve zaman hiçtir insan sevmeye görsün. 

                Kalbim çarpıp durdukça, 

                O hep diyecek sana: 

                        Hatırla. 

        Hatırla, soğuk toprak altında 

        Kırık kalbim sonsuza dek uyurken; 

        Hatırla, yalnız çiçek mezarımda 

        Böyle usul usul açıyorken, 

Seni bir daha görmeyeceğim, ama ölümsüz ruhum 

Sadık kızkardeş gibi dönüp gelecek sana. 

        Gecenin içersinde 

        İnleyen sesi dinle: 

                Hatırla.', 'Hatırla, çekingen Tan Güneşe          Mutlu sarayını açtığı zaman;          Hatırla, geçerken dalgın gece          Düş kurup gümüş tülünün a...', ARRAY['Türk Edebiyatı','Şiir','Alfred De Musset']::text[], 8.5, '{"poet":"Alfred De Musset","poet_slug":"alfred-de-musset","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hatirla-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pepa''ya', 'pepa-ya-alfred-de-musset-uxj13', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Pepa''cığım, gece ilerleyip de

Annen odasına çekildiği an

Sen lambanın altında yarı üryan

Duaya başlarsın ya, eğilip de; 

Hani rahatı kaçmış ruhun, seni

Gecenin koynuna terkettiği an; 

Başlığını atarsın da başından

Yatağına bir bakarsın ya hani; 

Evin bütün insanlarını saran

Ağırlık yaklaşır ya, adım adım; 

Güzelim, sevgilim, Pepita''cığım, 

Ne düşünürsün acaba o zaman? 

Kimbilir belki bir garip kadını, 

Çok acıklı bir romanda kahraman.

Ümidin zoruyla meydana çıkan, 

Hakikatinse yalanladığını.

Belki de ancak doğura doğura

Bir fare doğuran kocaman dağlar, 

Hiçbir vakit yaşanmamış sevdalar, 

Şekerlemeler, belki de bir koca.

Ah! Belki de senin kadar iyi

Bir kalbin dostça açılmalarını; 

Esvabını, oyun havalarını; 

Belki de beni, belki hiçbir şeyi.', 'Pepa''cığım, gece ilerleyip de Annen odasına çekildiği an Sen lambanın altında yarı üryan Duaya başlarsın ya, eğilip de;  Hani rahatı kaçmış ...', ARRAY['Türk Edebiyatı','Şiir','Alfred De Musset']::text[], 8.5, '{"poet":"Alfred De Musset","poet_slug":"alfred-de-musset","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/pepa-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaliforniya''da Bir Süpermarket', 'kaliforniya-da-bir-supermarket-allen-ginsberg-1ke2g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seninle ilgili neler geçiyor aklımdan, Walt Whitman, 

başağrısıyla yürürken kenar mahallerde ağaçların altından, 

ürkekçe seyrederek dolunayı.

Açgözlü bitkinliğimle satın alacak imgeler aranırken neon

meyve süpermarketine uğradım, senin siparişlerini düşleyerek! 

Şu şeftalilere bir bak ya da şu alacakaranlıklar! Aileler tam

takım alışverişte: Koridorlar, kocalarla dolup taşıyor! Avakadoların

içinde kadınlar, domateslerin içinde bebekleri! ya sen, Garcia Lorca, 

senin ne işin vardı karpuzların orada! 

Gördüm seni, Walt Whitman, çocuksuz, yalnız, koca obur, dolaptaki

etlerin arasında dolanırken ve dikizlerken tezgahtar çocukları.

İşittim seni birşeyler sorarken: Kim katletti bu domuz pirzolalarını? 

Muzlar kaça? Sen, Meleğim misin benim?                                         

                                   İzleyerek seni dolandım parlak konserve 

yığınları arasında

ve dükkan dedektifi takip etti hayalimde.

Beraberce adımladık koridorları bu ıssız düşümüzde, 

enginarları tadarak, dondurulmuş lezzetlerin her birinden aşırıp

kasaya hiç uğramadan.

Nereye gidiyoruz, Walt Whitman? Bir saate kalmadan kapanacak

kapılar. Sakalın hangi yönünü gösteriyor gece? 

(Dokunuyorum kitabına ve süpermarket serüvenimizi düşlüyorum, 

 bir garip hissediyorum kendimi.) 

Issız sokaklarda mı yürüyeceğiz bütün gece?  Gölgeler gölgeler

ekliyor ağaçlar, tek ışık yok evlerde, bir başımıza kalacağız ikimiz de. 

Mavi arabalar geçerken yanımızdan sesiz klübelerimize doğru yol

alacak mıyız dersin, yitik sevgi Amerikasını düşleyerek? 

Ah, sevgili atam benim, kır sakallı, aylnız ve yaşlı cesaret hocası, 

nasıl bir yerdi senin Amerikan, küreklere asılıp terk ettiğinde

buraları Charon ve sen dumanlar içindeki sahile çıkıp izlediğinde

geminin kayboluşunu karanlık sularında Lethe''nin?', 'Seninle ilgili neler geçiyor aklımdan, Walt Whitman,  başağrısıyla yürürken kenar mahallerde ağaçların altından,  ürkekçe seyrederek dolunay...', ARRAY['Türk Edebiyatı','Şiir','Allen Ginsberg']::text[], 8.5, '{"poet":"Allen Ginsberg","poet_slug":"allen-ginsberg","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/kaliforniya-da-bir-supermarket-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanın altında Rond', 'canin-altinda-rond-aloysius-bertrand-i8bef', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hemen hemen  kare biçimde, 

                           yıkıntılarla çevrili ağır 

                           bir binaydı, ve hala bir

                           saati bulunan kulesi bütün

                           mahalleye egemendi.

                                      Fenimore Cooper

Aziz Yuhanna''nın büyük çanın altında bir rond dansı

yapıyordu on iki büyücü. Sırayla fırtınayı çağırdılar, 

ve alay halinde karanlığı delen on iki ses saydım

yatağımda, korku içinde.

Hemen bulutların arkasına saklandı ay, ve yıldırım ve

kasırgayla karışık bir yağmur kırbaçladı penceremi, 

ormanda sağnağa tutulan nöbetçi turnalar gibi bağırırken 

rüzgar gülleri.

Kırıldı, duvara asılı lavtamın ince teli; kafesinde

kanat çırptı saka kuşum; çevirdi, masamın üzerinde

uyuklayan Roman de la Rose''un bir sayfasını, meraklı

bir ruh.

Ama birden bir yıldırım gürledi Aziz Yuhanna''nın

yukarılarında. Yitip gitti, ölümcül bir darbe yiyen

büyücüler, ve meşale gibi yandığını gördüm siyah çanın

içinde büyücü kitaplarının.

Arafın ve cehennemin kırmızı alevleriyle tarıyordu

gotik kilisenin duvarlarını bu korkunç ışık, ve devsel

heykelinin gölgesi Aziz Yuhanna''nın uzanıyordu komşu

evlerin üzerinde.

Paslandı rüzgargülleri; inci grisi bulutlar eritti ay; 

çatı kenarlarına damla damla düşer oldu yağmur, ve 

açınca pek iyi kapanmamış penceremi, fırtınanın 

silkelediği yaseminimden çiçekler attı meltem, yastığımın

üzerine.', 'Hemen hemen  kare biçimde,                             yıkıntılarla çevrili ağır                             bir binaydı, ve hala bir       ...', ARRAY['Türk Edebiyatı','Şiir','Aloysius Bertrand']::text[], 8.5, '{"poet":"Aloysius Bertrand","poet_slug":"aloysius-bertrand","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/canin-altinda-rond-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şabbat''a gidiş', 'sabbat-a-gidis-aloysius-bertrand-zz2fq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir düzine insan vardı orada biralı çorba içen, ve her

birinin elinde bir ölünün önkol kemiği kaşık niyetine.

Ocak kızarmıştı kor ateşte, mumlar mantarlaşıyordu

dumanın içinde, ve tabaklardan bir mezar kokusu

yayılıyordu ortalığa, baharda.

Ve güler ya da ağlarken Maribas, sanki inlediği

duyuluyordu bir yayın, üç teli üzerinde kırık bir 

kemanın.

Bu sırada, içyağı ışığında, şeytanca tavırla bir asker, 

bir büyücü kitabı açtı masaya, ve bir kızarmış sinek

düştü kitaba.

Kocaman, tüylü karnından bir örümcek tırmandı büyülü

kitabın kenarına, henüz vızıldarken bu sinek.

Ama çoktan uçup havalanmıştı bacadan bay ve bayan 

büyücüler, kimileri ata biner gibi süpürgenin üzerinde, 

kimileri bir maşanın üzerinde, ve bir tava sapında Maribas.', 'Bir düzine insan vardı orada biralı çorba içen, ve her birinin elinde bir ölünün önkol kemiği kaşık niyetine. Ocak kızarmıştı kor ateşte, mu...', ARRAY['Türk Edebiyatı','Şiir','Aloysius Bertrand']::text[], 8.5, '{"poet":"Aloysius Bertrand","poet_slug":"aloysius-bertrand","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sabbat-a-gidis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buzul', 'buzul-andre-du-bouchet-8dlh3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1

Rüzgar

büyük yüz

donmuş

kıpırdanan

taş

ya da doruk

rüzgar.

2

Kapı, beyaz hava.

3

Yanmayı sürdürdüğüm sıkı toprak üzerinde, hava

öldüresiye sıkarken bizi, tanımıyoruz artık

duvarı. Birdenbire kaplıyorum sende önceki şu

                                                                 boşluğu.

4

İkinci dönemeçte, kör eden dalgası bir

buzulun, birkaç tutam hava.

5

Besleniyorum bir taşlar ateşiyle

vazgeçiyorum

bir el var

uzanmış

havada

ona bakıyorsun

onu benden edinmiş gibi

her yerde çizgilerimiz

parıldıyorlar.', '1 Rüzgar büyük yüz donmuş kıpırdanan taş ya da doruk rüzgar. 2 Kapı, beyaz hava. 3 Yanmayı sürdürdüğüm sıkı toprak üzerinde, hava öldüresiye...', ARRAY['Türk Edebiyatı','Şiir','Andre Du Bouchet']::text[], 8.5, '{"poet":"Andre Du Bouchet","poet_slug":"andre-du-bouchet","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/buzul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düzleştirme', 'duzlestirme-andre-du-bouchet-usq9o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çiyin anısını koruyorum bulunmadığım bu

yol üzerinde

                                          yeniden bağlayan

rüzgarın umutsuzluğunda.

                                           Bu gök, esintisinin

sonunun açığa vurduğu toz halindeki yerde.

Alanda, 

               uyumuşken bile, bulduğum

               önümde, dün soluk aldım.

Yer tarafından karşılanmış, görebildiğim

yolun alanı gibi.

       uzun süre kalıyorum günün ortasında.', 'Çiyin anısını koruyorum bulunmadığım bu yol üzerinde                                           yeniden bağlayan rüzgarın umutsuzluğunda.    ...', ARRAY['Türk Edebiyatı','Şiir','Andre Du Bouchet']::text[], 8.5, '{"poet":"Andre Du Bouchet","poet_slug":"andre-du-bouchet","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/duzlestirme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esintiden Uzakta', 'esintiden-uzakta-andre-du-bouchet-3g40m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çarpmış olarak, tanımadan, havaya, biliyorum, 

şimdi, güne doğru inmeyi.

Bir ses gibi, tam da dudaklarında, 

parıltıyı kurutacak.

Kıskaçları bu alanın, 

                                               bizim için kayıp, 

                      ama buraya dek.

Ağzımıza varmayan bu araziye ulaşıyorum, 

çiye sarılan araziye.

Üzerinde yürüdüğüm yer değiştirmiyor, 

                                                           alan büyüyor.', 'Çarpmış olarak, tanımadan, havaya, biliyorum,  şimdi, güne doğru inmeyi. Bir ses gibi, tam da dudaklarında,  parıltıyı kurutacak. Kıskaçları...', ARRAY['Türk Edebiyatı','Şiir','Andre Du Bouchet']::text[], 8.5, '{"poet":"Andre Du Bouchet","poet_slug":"andre-du-bouchet","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/esintiden-uzakta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam Duası', 'aksam-duasi-arthur-rimbaud-wtmug', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sapı eğri bir pipo gibi, ağza kurulmuş, 

Ya da bir Melek gibi berberin ellerinde, 

Yaşayıp gidiyorum işte öyle oturmuş

Bardaklar arasında, duman yelkenlerinde.

Tatlı yaralar açar içimde binlerce düş

Sıcak dışkılar gibi boş bir güvercinlikte; 

Bakarım ki yaramın kabukları soyulmuş, 

Kanıyor yüreğim altın sıvıyla birlikte.

Sonra, bütün düşleri yalayıp yuttuğum an, 

İndirince mideye otuz kırk bardak birayı, 

Bir boşalma gereği sıkıştırır o zaman.

Lübnan selvilerinin Tanrısı gibi tatlı, 

Sidiğini göklere, yükseklere attıran

Ben kulunuzu bağışlayın siğilotları!', 'Sapı eğri bir pipo gibi, ağza kurulmuş,  Ya da bir Melek gibi berberin ellerinde,  Yaşayıp gidiyorum işte öyle oturmuş Bardaklar arasında, d...', ARRAY['Türk Edebiyatı','Şiir','Arthur Rimbaud']::text[], 8.5, '{"poet":"Arthur Rimbaud","poet_slug":"arthur-rimbaud","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/aksam-duasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asılmışların Balosu', 'asilmislarin-balosu-arthur-rimbaud-as8ng', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Balıkçıl darağacında

                                           Selahattin''in şövalyeleri

                                           Dansediyor, dansediyor

                                           Şeytan''ın şövalyeleri.

Yüzleri buruşuk, küçük, kara kulakları

Çekmiş sayın Belzebuth bir iple gökyüzüne

Oynuyorlar şakırdadıkça kunduraları

Tutulmuşlar bir Noel ezgisinin hüznüne.

Kara orglar gibi ince, uzun kollarını

Bak şimdi kucaklıyor çarpık, küçük kuklalar

Bir zamanlar aksoylu hanımların sıktığı

Bilekleri iğrenç bir aşkla dokunmadalar.

Hoyda! şen oyuncular, artık düşünmeyen baş! 

Takla atılabilir sehpalar öyle uzun! 

Hop! Bilinmesin artık bu ya da dans ya da savaş! 

Gıcırdarken kemanı kudurmuş Belzebuth''un.

Ey bundan sonra sandal giymeyecek ayaklar! 

Hepsi derilerinden gömleklerini sıyırmış: 

Ama böyle çok daha memnun görünüyorlar

Başları üstüne kar beyaz bir şapka örmüş.

Titriyor bir tutam et arık çenelerinde

Çatlak kafalarına sorguç yapmış kargalar: 

Çarpıp karton zırhlara gözüpekler, yiğitler

Ölü karanlıklarda sanki dolanıyorlar.

Esiyor balosuna iskeletlerin poyraz! 

Darağacı inliyor demirden bir org gibi

Koşuyor ormanlarında aç kurtlar avaz avaz: 

Gökyüzü andırıyor kızıl bir cehennemi.

Hoyda, beni de alın yaslı kabadayılar

Kırık parmaklarından geçen sessizce, bir bir

Bir aşk tesbihi solgun omuriliklerinde: 

Bura manastır değil, ölüler ülkesidir.

Oh! işte ortasında ölüler dansının bak

Sıçrıyor çılgın bir iskelet gökyüzünde

Sürüklenmiş boşluğa, at gibi şahlanarak

Sanki katı ipi boynunda duruyor yine.

Çatlayan uyluğunda büzmüş on parmağını

Dalgacı gülüşlere benzeyen çığlıklarla

Ve bir soytarı gibi barınağa girip

Sıçrıyor kemiklerin şarkılı balosunda.

Balıkçıl darağacında

Selahattin''in ölüleri

Dansediyor, dansediyor

Şeytan''un şövalyeleri.', 'Balıkçıl darağacında                                            Selahattin''in şövalyeleri                                            Dansedi...', ARRAY['Türk Edebiyatı','Şiir','Arthur Rimbaud']::text[], 8.5, '{"poet":"Arthur Rimbaud","poet_slug":"arthur-rimbaud","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/asilmislarin-balosu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çapkın Kız', 'capkin-kiz-arthur-rimbaud-lwfqb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kahverengi bir salon, cila ve meyva kokan, 

Kurulmuş koca iskemleye tıkınıyordum, 

Bir Belçika yemeği, buyursun canı çeken, 

Yeter ki karnım doysun, aldırmayıp yiyordum, 

Rahattım - oh ne güzel çalar saatin sesi-

Derken, mutfak açıldı, sürünmüş, sürmelenmiş, 

Kılık kıyafetine ise biraz boş vermiş, 

Yanaştı cilvelenip aşevi hizmetçisi.

İstediği tatlı bir öpücüktü sanırım

Belçikalı kızları bakışından tanırım, 

Fazla çatal kaşıkları masadan topladı, 

Dudak büktü gülerek çocuk bir yüzle bana: 

Bastırıp parmağını şeftali yanağına, 

''Buramı üşütmüşüm, dokun anlarsın'' dedi.', 'Kahverengi bir salon, cila ve meyva kokan,  Kurulmuş koca iskemleye tıkınıyordum,  Bir Belçika yemeği, buyursun canı çeken,  Yeter ki karnım...', ARRAY['Türk Edebiyatı','Şiir','Arthur Rimbaud']::text[], 8.5, '{"poet":"Arthur Rimbaud","poet_slug":"arthur-rimbaud","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/capkin-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çalınmış Yürek', 'calinmis-yurek-arthur-rimbaud-7s6p4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Üzgün yüreğim akıyor gemiye, 

Bir gevişlik tütün salyası gibi; 

Çorba artıkları yüzümde, niye? 

Üzgün yüreğim akıyor gemiye; 

Ya bu kaba saba sözler ne diye? 

Adamların bu zevzek gülüşleri? 

Üzgün yüreğim akıyor gemiye

Bir gevişlik tütün salyası gibi.

Hep belden aşağı edepsiz laflar

Onu nasıl baştan çıkardı, bakın! 

Dümende de o biçim resimler var, 

Sevişmeler, kalkmış cinsel organlar...

Siz ey beni büyüleyen dalgalar, 

Alın kirli yüreğimi, arıtın

Hep belden aşağı edepsiz laflar

O''nu nasıl baştan çıkardı, bakın! 

Tütünün posası çıktı çıkacak

Ey çalınmış yürek n''eyleyeceğim? 

Ayyaş hıçkırıkları başlayacak, 

Tütünün posası çıktı çıkacak; 

Midem boşalıp boşalıp dolacak, 

Ben ki, yenmiş yutulmuşsa yüreğim, 

- Tütünün posası çıktı çıkacak -

Ey çalınmış yürek n''eyleyeceğim?', 'Üzgün yüreğim akıyor gemiye,  Bir gevişlik tütün salyası gibi;  Çorba artıkları yüzümde, niye?  Üzgün yüreğim akıyor gemiye;  Ya bu kaba sab...', ARRAY['Türk Edebiyatı','Şiir','Arthur Rimbaud']::text[], 8.5, '{"poet":"Arthur Rimbaud","poet_slug":"arthur-rimbaud","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/calinmis-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bilmece', 'bir-bilmece-edgar-allan-poe-yzdw5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '''Nadiren buluruz'' der Solomon Don Dunce, 

     ''En derin sonede yarım bir fikri.

Bütün o gevşek dokulu nesneler arasından, birden görürüz

     Kolayca, bir Napoli bonesinin ardından gördüğümüz gibi-

Döküntünün döküntüsü-Bir Lady onu nasıl giyebilir ki? 

Yine de çok ağırdır senin Petrark''çı kumaşından-

Baykuş tüylü bir saçmalık ki en hafif üfleyiş

Kağıda çevirir onu sen yuttururken.''

Ve, gerçekte yeterince haklıdır Güneş.

Sıradan kumaşlar kötü yutturmacalardır

    -kısa ömürlü ve geçirgen öylesine-

Ama bu, şimdi-ona güvenebilirsiniz-

Sabit, koyu, ölümsüz, -değeri adların

Yardımıyla gizlenen içindeki.', '''Nadiren buluruz'' der Solomon Don Dunce,       ''En derin sonede yarım bir fikri. Bütün o gevşek dokulu nesneler arasından, birden görürüz   ...', ARRAY['Türk Edebiyatı','Şiir','Edgar Allan Poe']::text[], 8.5, '{"poet":"Edgar Allan Poe","poet_slug":"edgar-allan-poe","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-bilmece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eulalie-Bir Şarkı', 'eulalie-bir-sarki-edgar-allan-poe-lzoqw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kendi başıma yerleşmişim

        Bir keder dünyasına, 

Ve durgun sular gibiydi ruhum, 

Ta ki güzel ve zarif Eulalie benim

        Utangaç gelinim olanaca-

Ta ki sarı saçlı körpe Eulalie benim

       Güler yüzlü gelinim olanaca.

      Ah, az-daha az parlak

      Yıldızları gecenin

 O pırıl pırıl gözlerinden

Ve ne buharın bulutsu ışıltısı

İnci rengiyle ve morla Ay-yansımalı, 

Yarışabilir mütevazi Eulalie''nin en sıradan saç buklesiyle-

Yarışabilir parlak gözlü Eulalie''nin en özensiz ve

      Önemsiz buklesiyle.

      Ne Kuşku-ne Acı

      Gelir bundan böyle, 

Çünkü ruhu verir bana ağlama isteğini, 

      Ve bütün gün

      Işıldar, güçlü ve parlak

Astarte uzayda, 

Sevgili Eulalie''sine bakarken anaç gözleri-

Körpe Eulalie''sine bakarken menekşe gözleri.', 'Kendi başıma yerleşmişim         Bir keder dünyasına,  Ve durgun sular gibiydi ruhum,  Ta ki güzel ve zarif Eulalie benim         Utangaç ge...', ARRAY['Türk Edebiyatı','Şiir','Edgar Allan Poe']::text[], 8.5, '{"poet":"Edgar Allan Poe","poet_slug":"edgar-allan-poe","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/eulalie-bir-sarki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Benim Adımdır', 'bu-benim-adimdir-adonis-81y2a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kollarında bir güneş ölür, 

Gece gömmem onu diye tutturmuştur, 

Sürekli dalgalanmalarla 

Deniz öğretti ona, 

Nasıl çıkacağını kendinden, 

Hem de hep kendi kalıp.', 'Kollarında bir güneş ölür,  Gece gömmem onu diye tutturmuştur,  Sürekli dalgalanmalarla  Deniz öğretti ona,  Nasıl çıkacağını kendinden,  He...', ARRAY['Türk Edebiyatı','Şiir','Adonis']::text[], 8.5, '{"poet":"Adonis","poet_slug":"adonis","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bu-benim-adimdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kötü Zamanlardan bir Aşk Şarkısı', 'kotu-zamanlardan-bir-ask-sarkisi-bertolt-brecht-3lpty', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Arkadaş olmamıştık birbirimizle

Ama oturduk birlikte aynı yerde

Ve sarılıp yattığımızda birbirimize

Aydan daha yabancıydık birbirimize.

Ve karşılaşsak bugün çarşı-pazarda

Dövüşebiliriz belki bir kaç balık için.

Arkadaş olmamıştık birbirimizle

Sarılıp yattığımızda birbirimize', 'Arkadaş olmamıştık birbirimizle Ama oturduk birlikte aynı yerde Ve sarılıp yattığımızda birbirimize Aydan daha yabancıydık birbirimize. Ve k...', ARRAY['Türk Edebiyatı','Şiir','Bertolt Brecht']::text[], 8.5, '{"poet":"Bertolt Brecht","poet_slug":"bertolt-brecht","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kotu-zamanlardan-bir-ask-sarkisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Saat Beklemek Çok Uzun İş', 'bir-saat-beklemek-cok-uzun-i-s-emily-dickinson-w1haf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir saat beklemek çok uzun is, 

Aşk biraz ötede duruyorsa; 

Kısadır sonsuzluğu bekleyiş, 

Sonunda aşk armağanı varsa..', 'Bir saat beklemek çok uzun is,  Aşk biraz ötede duruyorsa;  Kısadır sonsuzluğu bekleyiş,  Sonunda aşk armağanı varsa.....', ARRAY['Türk Edebiyatı','Şiir','Emily Dickinson']::text[], 8.5, '{"poet":"Emily Dickinson","poet_slug":"emily-dickinson","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-saat-beklemek-cok-uzun-is-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim Unutacağız Onu', 'kalbim-unutacagiz-onu-emily-dickinson-9s1dq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalbim, unutacağız onu, 

Bu gece, sen ve ben.

Ben ışığı unutayım, 

Onun sıcaklığını sen.

Unuttuğun vakit, söyle bana, 

Ola ki düşüncem donar.

Acele et, oyalanırken sen, 

Hatırlayabilirim tekrar.', 'Kalbim, unutacağız onu,  Bu gece, sen ve ben. Ben ışığı unutayım,  Onun sıcaklığını sen. Unuttuğun vakit, söyle bana,  Ola ki düşüncem donar...', ARRAY['Türk Edebiyatı','Şiir','Emily Dickinson']::text[], 8.5, '{"poet":"Emily Dickinson","poet_slug":"emily-dickinson","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kalbim-unutacagiz-onu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1764', '1764-emily-dickinson-hnrev', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'En hüzünlü ses en tatlı ses

En çılgın ses büyüyen, -

Kuşların sesidir baharda, 

Gece hoş bir tat bırakıp giderken.

Mart''la Nisan arasındaki çizgi-

O büyük sihirli sınır

Ötesinde Yaz, nefes alsa duyulur

Yakınlıkta, kararsızlıklar yaşamaktadır.

Bir zamanlar bizimle eyleşen

Dostları hatırlatır bir bir, 

Ki ayrılığın kara büyüsüyle büyüyen

Hasretleri artık insafsızca derindir.

Yasını tuttuğumuz ne varsa

Hatıra gelir yeniden, 

Ötmesin isteriz kuşlar

Sussun isteriz bu siren.

Bir kulak deşebilir bir kalbi

Bir mızrak kadar kıvrak, 

Keşke kalbe bu kadar tehlikeli

Bir şekilde yakın olmasaydı kulak.', 'En hüzünlü ses en tatlı ses En çılgın ses büyüyen, - Kuşların sesidir baharda,  Gece hoş bir tat bırakıp giderken. Mart''la Nisan arasındaki ...', ARRAY['Türk Edebiyatı','Şiir','Emily Dickinson']::text[], 8.5, '{"poet":"Emily Dickinson","poet_slug":"emily-dickinson","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/1764-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Marienbad Ağıdı', 'marienbad-agidi-johann-wolfgang-von-goethe-z8d35', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Artık ne bekleyebilirim, yeniden

Buluşsam da o gonca çiçekten

Cennet ve cehennem seni bekliyor

Duygular kararsızlık dalgalarında sarsılırken, 

Bitsin bu kuşkular artık! İşte gök kapında

Kaldırıyor yerden seni kollarıyla

İşte cennete kabul edildin, keşke

Değer olsaydın sonsuz güzel hayata

Artık ne istek, ne umut, ne tutku kaldı

Burasıydı yöneldiğin içten çabalarla

Karşında görünce eşsiz güzelliği

Yanık gözyaşlarının kaynağı tükendi

Gün nasıl da hızla çarptı kanatlarını

Zamanı önüne katıp sürer gibi

Akşamki öpücük bir mühür dudaklarda

Yarınki güneşin de aynen göreceği

Sakin bir yürüyüşteydi zaman, 

Kız kardeşler gibi, benzer ve benzemeyen

Son öpücüğün nasıl da tatlı kıyıcılığı

Kesiveriyor aşkın kusursuz örgüsünü

Şimdi acele, tedirgin koşan, sakınıp eşiğinden

Ardından alevler içinde bir melek geliyor gibi

Göz, karanlık yola yorgun bakıyor

Dönüp baktı: Kapı kilitli duruyor

Şimdi kendine bile kilitli olan bu gönül

Sanki hiç açılmamış, mutluluk saatlerini

Gökteki bütün yıldızlarla yarışarak

Onun yanında hiç yaşamamış gibi

Usanmış, utanmış, bungun, hüzünlü

Karanlıklar içinde soluksuz gönlü

Bu dünyadan geride ne kaldı? Sarp kayalar

Kutsal gölgelerle taçlandırılmadı mı? 

Ürünler olgunlaşmadı mı? Yeşillikler canlı, 

Irmak ve otlaklar boyunca uzanmıyor mu? 

Ve yeryüzü ötesinin büyüklüğü 

Biçimli ve biçimsiz kubbelenmiyor mu? 

Nasıl da aydınlık ve kırılgan, hafif ve ince

Ciddi bulutlar korosundan altı kanatlı melek

Tıpkı o, yukarıdaki mavi gök

Buhar gibi karışıveren maviliğe

Böylece gördün danslar içinde sevinçli

O, sevgililer sevgilisini.

Yalnızca birkaç dakika izin sana

Onun yerine bir hayli tutup bırakmaya

Yüreğine geri dön, daha kolay bulabilirsin orda

Değişen biçimlere oynarken onu.

Pek çok resim giderek oluşturuyor birini

Böyle binlerce kez ve hep hep sevgili

Kapılarda bekliyordu, karşılar gibi

Adım adım mutlu etti beni

Bir daha koştu son öpücükten sonra

Bir son daha kondurmaya dudaklarıma

Nasılda canlı şimdi anısı

İçimde alevden harflerle yazılı.

O gönül ki, yüksek surlar yaptırmış

İçinde korumak için kendini ve sevdiğini 

Onun yerine de sevinç duyuyor bu aşktan

Yalnızca ona açınca kapılarını tanıyor kendini

Böylece kendi sınırları içinde daha özgür

Ve yalnızca ona teşekkür için atıyor yüreği

Sevme gücü ve gereksinim

Karşılıklı sevgiyle yok edildi

Sevinçli tasarılar için umudun neşesi

Karar ve eylem için hemen bulundu

Aşk bir heyecansa seven için, 

Ben en hoş örneğiyim bunun.

Beni böyle kılan onun varlığı! Nasıl bunaltıcı

Bir korku akıl ve beden üstünde, istenmeyen ağırlık: 

Tüyler ürpertici hayaller dolu

Yürek boşluğunun ıssızlığında.

Şimdi eşikte umudun bilinen şafağı

Işıyor güneşin yumuşak aydınlığında.

Tanrı''nın verdiği huzuru bu evrende

Akıldan çok mutluluk veren - okuduğumuza göre -

Karşılaştırıyorum aşkın huzuruyla, 

Sonsuzca sevdiğin yanındaysa bu dünyada

Gönül rahatlar, bozamaz hiçbir şey o derinde

Duran anlamı, o anlam ait olmaktır sevdiğine...', 'Artık ne bekleyebilirim, yeniden Buluşsam da o gonca çiçekten Cennet ve cehennem seni bekliyor Duygular kararsızlık dalgalarında sarsılırken...', ARRAY['Türk Edebiyatı','Şiir','Johann Wolfgang von Goethe']::text[], 8.5, '{"poet":"Johann Wolfgang von Goethe","poet_slug":"johann-wolfgang-von-goethe","theme":"Türk Şiiri","is_hero":false,"total_lines":78,"source_url":"https://www.antoloji.com/marienbad-agidi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay', 'ay-jorge-luis-borges-3n1t3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sessiz arkadaşlığı ayın eşlik ediyor sana, 

dalgın gözlerinin bugün toza dönüşmüş

bir bahçe ya da avluda onu son kez çözümlediği

-zamanın derinliğinde yitip gitmiş- o akşam

ya da geceden bu yana. Son kez mi? 

Biliyorum, biri çıkıp şöyle diyebilir

günün birinde sana, tam da gerçeği söyleyerek: 

Parlak ayı görmeyeceksin artık, tükettin

yazgının sana bağışladığı fırsatların toplamını.

Tüm pencerelerini açsan da dünyanın, boşuna.

çok geç artık. Onu bulamayacaksın bir daha.

Yaşamımız boyunca keşfeder ve unuturuz

o alışılmış güzelliğini gecenin. Biliriz, 

göktedir hep ay. Oysa iyi bakmak gerekir ona.

Kim bilir, belki de sonuncusudur!', 'Sessiz arkadaşlığı ayın eşlik ediyor sana,  dalgın gözlerinin bugün toza dönüşmüş bir bahçe ya da avluda onu son kez çözümlediği -zamanın de...', ARRAY['Türk Edebiyatı','Şiir','Jorge Luis Borges']::text[], 8.5, '{"poet":"Jorge Luis Borges","poet_slug":"jorge-luis-borges","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ay-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyum Ben', 'oyum-ben-jorge-luis-borges-8x1tu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben kardeşinin imgesini ya da gölgesini

(ikisi de aynı şey)   sessizliğin ya da kadehinin

aynasında izleyen o boşyüce gözlemciden

daha az boşyüce olmadığını bilen biriyim.

Ben, benim suskun dostlarım, salt unutuştan

Başka bir öç ya da bağışlanma olmadığını

bilen kişiyim. Bir tanrı bu garip

Çözümü sunmuş her türlü insan kinine.

Bunca gezip dolaşmama karşın, tekil çoğul, 

Yorucu, garip, kendimin ve başkasının

zamanının labirentini bir türlü çözemedim.

Hiç kimse değilim ben. Kimseye kılıç çekmedim

savaşta. Yankıyım, unutuşum, hiçliğim ben.', 'Ben kardeşinin imgesini ya da gölgesini (ikisi de aynı şey)   sessizliğin ya da kadehinin aynasında izleyen o boşyüce gözlemciden daha az bo...', ARRAY['Türk Edebiyatı','Şiir','Jorge Luis Borges']::text[], 8.5, '{"poet":"Jorge Luis Borges","poet_slug":"jorge-luis-borges","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/oyum-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgün', 'surgun-jorge-luis-borges-usnuc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biri iz sürüyor İthaka yollarında, 

unutmuş kralını yıllarca önce

Troya’ya giden; 

biri yeni ele geçirdiği toprakları düşünüyor, 

yeni sabanın, oğlunu, ve belki de mutlu.

Yerkürnin sınırları içinde ben, Ulisses, 

Hades’in derinliklerine indim

ve yılanların aşk düğümünü çözen

Tebai’li Tiresias’ın hayaletini gördüm, 

bir de, ovada aslanların gölgelerini öldüren

ve Olimpos’ta oturan Harekles’in hayaletini.

Biri yürüyor bugün Bolivar ve Şili’de, 

belki de mutlu, belki değil.

Ben o olmak isterdim.', 'Biri iz sürüyor İthaka yollarında,  unutmuş kralını yıllarca önce Troya’ya giden;  biri yeni ele geçirdiği toprakları düşünüyor,  yeni saban...', ARRAY['Türk Edebiyatı','Şiir','Jorge Luis Borges']::text[], 8.5, '{"poet":"Jorge Luis Borges","poet_slug":"jorge-luis-borges","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/surgun-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim', 'sevgilim-william-shakespeare-xedu5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey sevgilim, nerelerde dolaşıyorsun böyle? 

Geliyor seni candan seven aşığın dur onu dinle. 

Elemi de, neşeyi de beste yapmış diline. 

Uzaklaşma şirin yarim. 

Yolculuklar, aşıkların buluşmasıyla nihayetlenir. 

Her tanrı kulu bunu bilir. 

Aşk nedir? Ahret demek değildir her halde. 

Çınlamalıdır neşesi bu anın gene bu anın kahkahalarıyla 

Çünkü ne olacağı yarının meçhulümüzdür hala, 

Boş yere vakit geçirmekten artık yoktur bir salah: 

Öyle ise gel öp beni, genç ve tatlı sevgilim, 

Ömrü pek azdır gençliğin.', 'Ey sevgilim, nerelerde dolaşıyorsun böyle?  Geliyor seni candan seven aşığın dur onu dinle.  Elemi de, neşeyi de beste yapmış diline.  Uzakl...', ARRAY['Türk Edebiyatı','Şiir','William Shakespeare']::text[], 8.5, '{"poet":"William Shakespeare","poet_slug":"william-shakespeare","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgilim-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beş Parmak Dağında Endymion', 'bes-parmak-daginda-endymion-jorge-luis-borges-2oz0r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uyuyordum doruğunda dağın. Ve güzeldi

yılların yıprattığı yıktığı gövdem.

Yukarda, elen ormanında, yavaşlatıyordu

Kentaur dörtnal koşusunu

gözetlemek için uykumu. Hoşlanıyordum

düş görmek için uyumaktan ve o öteki, 

bellekten kurtulan arındırıcı düşe kavuşmak için

yeryüzünü yaşamanın yükünden kurtaran

düşe kavuşmak için uyumaktan.

Tanrıça Diane, o aynı zamanda ay olan, 

görüyordu uyuduğumu dağın üzerinde.

İndi, yavaşça, kollarıma.

Altın ve aşk, yanan gecede! 

Sıkıyordum ölümlü gözkapaklarımı.

Görmek istemiyordum, balçık dudaklarımın

kutsallığına saygısız davrandığı yüzü.

İçime çektim ayın kokusunu

ve adımı ünledi ölümsüz sesi.

Kavuşan arık yanaklar! 

Aşkın ve gecenin ırmakları! 

İnsan buseleri ve gerilimi yayın! 

Bilmiyorum ne kadar sürdü mutluluğum.

Öyle şeyler vardır ki ne salkım

ölçebilir ne çiçek ne de narin kar.

Herkes kaçtı benden. Korkutuyordu herkesi

ayın gönül verip sevdiği erkek.

Yıllar geçti. Çılgına çeviriyor beni, 

bir korku, uyandığım zaman. Düşünüyorum, 

gerçek miydi, bir düş müydü yoksa

dağın doruğunda yaşadığım o altın çalkantı.

Boş yere tekrarlıyorum kendi kendime

geçmişin anısı ve düş, tek ve aynı şeydir diye.

Yalnızlığım dolaşıyor yavan yollarında

yeryüzünün; ama ben, arıyorum, 

hep arıyorum, eskil gecesinde tanrıların, 

o duygusuz ayı, kızını Zeus''ün.', 'Uyuyordum doruğunda dağın. Ve güzeldi yılların yıprattığı yıktığı gövdem. Yukarda, elen ormanında, yavaşlatıyordu Kentaur dörtnal koşusunu g...', ARRAY['Türk Edebiyatı','Şiir','Jorge Luis Borges']::text[], 8.5, '{"poet":"Jorge Luis Borges","poet_slug":"jorge-luis-borges","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bes-parmak-daginda-endymion-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğu Lansing''de Bir Anahtar', 'dogu-lansing-de-bir-anahtar-jorge-luis-borges-k8fo2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir anahtarım ben perdahlı çelikten.

Keyfe bağlı değil düzensiz profilim.

Görmediğim bir dolapta uyuyorum

belirsiz puslu uykumu, bir anahtarlıkta.

Bir kilit var beni bekleyen.

Bir tek. Dövme demirden kapı

katı kristalden. Bir ev var

öte yakada, gizli ve gerçek.

Yukarda, aynalar, alacakaranlıkta, 

görüyor boş aynalar geceleri, gündüzleri, 

görüyor ölülerin fotoğraflarını

ve incecik geçmişlerini fotoğrafların.

Çevireceğim bir gün kilidin dilini

ve iteceğim ağır kapıyı.', 'Bir anahtarım ben perdahlı çelikten. Keyfe bağlı değil düzensiz profilim. Görmediğim bir dolapta uyuyorum belirsiz puslu uykumu, bir anahtar...', ARRAY['Türk Edebiyatı','Şiir','Jorge Luis Borges']::text[], 8.5, '{"poet":"Jorge Luis Borges","poet_slug":"jorge-luis-borges","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dogu-lansing-de-bir-anahtar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendine Kıyan', 'kendine-kiyan-jorge-luis-borges-g8e9m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiçbir yıldız kalmayacak gecede.

Ne de gecenin kendisi kalacak.

Öleceğim ve benimle birlikte ölecek

çekilmez, katlanılmaz evrenin tümü.

Yok edeceğim piramidleri, madalyaları, 

yüzleri ve anakaraları.

Yok edeceğim birikimini geçmişin.

Toza dönüştüreceğim tarihi

ve tozu toza.

Son kez batan güneşe bakıyorum.

Son kuşu duyuyorum.

Kimseye kalıt bırakmıyorum hiçliği.', 'Hiçbir yıldız kalmayacak gecede. Ne de gecenin kendisi kalacak. Öleceğim ve benimle birlikte ölecek çekilmez, katlanılmaz evrenin tümü. Yok ...', ARRAY['Türk Edebiyatı','Şiir','Jorge Luis Borges']::text[], 8.5, '{"poet":"Jorge Luis Borges","poet_slug":"jorge-luis-borges","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kendine-kiyan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sone 3', 'sone-3-william-shakespeare-tzqrq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aynaya bak da şunu gördüğün yüze söyle: 

Sıra gelmiştir artık bir yaze yüz yapmana, 

Güzelliğini hemen yenilemezsen şöyle, 

Yeryüzü yoksun kalır, lanetlenir bir ana.

Hiçbir güzel var mı ki el sürülmemiş rahmi

Senin sürdüğün çiftin ekinini tepecek? 

Sırf kendini sevmenin mezarını ister mi, 

Geleceği ahmakça durdurur mu bir erkek? 

Sen annenin aynası olmuşsun da o sende

Bulmuştur gençliğinin güzelim baharını; 

Kendi dinç varlığınla görürsün pencerende

Kırışıklara rağmen, şu altın yıllarını.

  İstersen ki varlığın unutulsun bitsin, 

  Bir kuru başına öl, izin de ölüp gitsin.', 'Aynaya bak da şunu gördüğün yüze söyle:  Sıra gelmiştir artık bir yaze yüz yapmana,  Güzelliğini hemen yenilemezsen şöyle,  Yeryüzü yoksun k...', ARRAY['Türk Edebiyatı','Şiir','William Shakespeare']::text[], 8.5, '{"poet":"William Shakespeare","poet_slug":"william-shakespeare","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sone-3-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sone 11', 'sone-11-william-shakespeare-cz8er', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gençliğin günden güne kalırken gerilerde

Bir yavru yaratırsan alsın diye yerini, 

Dinçken can verirsen o körpe can ilerde

Senden göçen gençliğe varıp yaşatır seni.

Böyle sürecek akıl, güzellik ve başarı; 

Yoksa cinnet, yaşlanmak, çürümek var yer altında: 

Hiç kimse düşünmese gelecek kuşakları, 

İnsanlık sona erip giderdi üç batında.

Dünya çoğalmak için doğmayanlarla dolu, 

Kaknem, kakavan, kaba: kısırlıktan bitsinler; 

Yaradan vermiş sana en iyiyi, en bolu, 

Bu cömert aramağana cömertçe karşılık ver

  Seni kendine mühür yapmış, bunu böyle bil: 

  Sen de eşler yap diye, ölüp git diye değil.', 'Gençliğin günden güne kalırken gerilerde Bir yavru yaratırsan alsın diye yerini,  Dinçken can verirsen o körpe can ilerde Senden göçen gençl...', ARRAY['Türk Edebiyatı','Şiir','William Shakespeare']::text[], 8.5, '{"poet":"William Shakespeare","poet_slug":"william-shakespeare","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sone-11-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidersen', 'gidersen-ali-atmaca-9basv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gelirsen.. 

Ölümüne bir ilkbaharda gel, 

Peşinde nisan yağmurları olsun.

Ellerinde bir günlük kelebekler

Bilirsin... 

Korkarım kara kışlardan

Ve

Ferman çıktı, bir nefes canıma 

Hıçkırıklar kol geziyor, soluklarımda

Darağacında ölüm soğukluğu

Olsun gülüm...

Sen ılık bir sevda kat koynuma 

Elinde, bir tutam gül olsun

Yaralı ceylan, ağıtlarını unuttursun

Bir ahmakıslayan ertesi gel.

Gökkuşağının altından geç, 

Kelimelerden sonsuzu seç

Son gün, son ıslığım olsun

Ellerinde gün işığı, 

Kınalı kuşlar olsun

Ve 

İllede söylenmemiş şiirler, dudağında

İçinde sapsarı hüzünler olsun

Bir sevda alsın, gitsin aklımı

Ayrılığı unuttursun

Ve

Gidersen de tebessümlerle git gülüm

Bir penbe düş bırak toprağıma 

Ağlama, ağlama 

İsmim dudağında kalsın', 'Gelirsen..  Ölümüne bir ilkbaharda gel,  Peşinde nisan yağmurları olsun. Ellerinde bir günlük kelebekler Bilirsin...  Korkarım kara kışlarda...', ARRAY['Türk Edebiyatı','Şiir','Ali Atmaca']::text[], 8.5, '{"poet":"Ali Atmaca","poet_slug":"ali-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gidersen-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-ali-atmaca-qi75i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'şehirler özlerdim..

yeşili sevdaya çalan şehirler..

tabakaya yürek sarılıp içilen şehirler

hep o şehri özler, hep o gemiyi beklerdin

beklediğin gemiler gelmezdi, o şehrin limanlarına

sen gemi zannederdi, o vura vuar giderdi takasıyla

yüreğinle yanlız kalırdın

usulca bir martı konardı saçlarına 

bir taş atardın denize, deniz küserdi

takaya el eder, boynunu bükerdin

sonra... 

yaramaz çocuklar gibi gülerdin

ağlamazdın anlatmazdın

masallar avutmazdı seni, ninniler uyutmazdı

kaçmak dizğinlenirdi yüreğine 

yüreğin kaçmalara tutsak

kaçamazdın ki...

oysa yollar seni bekler, toprak seni çekerdi

gitsen olmaz, kalsan belki

yalan söylerdim... 

ellerin çirkin değildi

ellerinde bir ceylan, süt emzirirdi yavrüsüna 

sanki bir ana, giden oğluna ağıtlar yakardı

giden ve dönmeyecek olan, oğluna

hiç yaşamamışcasına tutardım

ölecekmişcesine bırakmazdım

ellerini..', 'şehirler özlerdim.. yeşili sevdaya çalan şehirler.. tabakaya yürek sarılıp içilen şehirler hep o şehri özler, hep o gemiyi beklerdin bekledi...', ARRAY['Türk Edebiyatı','Şiir','Ali Atmaca']::text[], 8.5, '{"poet":"Ali Atmaca","poet_slug":"ali-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ozlem-84-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoktun', 'yoktun-emre-ozdamar-qrhs4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Pembe bir rüyayı bölüşürken gecelerde

Bir haber bile yoktu senden

Yoktu haberi umarsız gözlerinin

Üşüyen ellerimden', 'Pembe bir rüyayı bölüşürken gecelerde Bir haber bile yoktu senden Yoktu haberi umarsız gözlerinin Üşüyen ellerimden...', ARRAY['Türk Edebiyatı','Şiir','Emre Özdamar']::text[], 8.5, '{"poet":"Emre Özdamar","poet_slug":"emre-ozdamar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yoktun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sone 15', 'sone-15-william-shakespeare-mr606', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'düşünüyorum da, dünyada büyüyen ne varsa, 

bir an tutunabiliyor yetkinlik noktasında; 

şu koca sahnede sergilenen tüm oyunlarsa, 

gizliden gizliye hep yıldızların etkisinde. 

bakıyorumda, bitkiler gibi çoğalıyor insanlar, 

aynı gökten açılıyor ya da kapanıyor yolları; 

gençlikte kabarıyor, inişe geçince sönüyorlar, 

silinmeye başlıyor akıllardan gösterişli günleri. 

o görkemli gençliğin geliyor gözlerimin önüne; 

savruk zaman belki çöküşle tartışmaya girdi bile, 

gençlik gününü, karanlık geceye döndürsek mi diye. 

         AMA SEVGİN UĞRUNA ZAMAN''LA SAVAŞI SÜRDÜREN BEN, 

        YENİDEN AŞILIYORUM SANA, O NE GÖTÜRÜRSE SENDEN...', 'düşünüyorum da, dünyada büyüyen ne varsa,  bir an tutunabiliyor yetkinlik noktasında;  şu koca sahnede sergilenen tüm oyunlarsa,  gizliden g...', ARRAY['Türk Edebiyatı','Şiir','William Shakespeare']::text[], 8.5, '{"poet":"William Shakespeare","poet_slug":"william-shakespeare","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sone-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin', 'gittin-emre-ozdamar-azyj1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gittin.....

Ve yalnızca gittin

Dilimin ucuna gelen her ne ise

Onlarıda alarak.

Şakısız, yankısız ve ışıksız kaldım

İçimdeki kandilleri söndürerek gittin

Nereden bilecektim gülüşlerinin

Ardında saklarken kendini

O bildik gözlerinde birgün

Sessizce yiteceğimi

Nereden bilecektim sevgilim', 'Gittin..... Ve yalnızca gittin Dilimin ucuna gelen her ne ise Onlarıda alarak. Şakısız, yankısız ve ışıksız kaldım İçimdeki kandilleri söndü...', ARRAY['Türk Edebiyatı','Şiir','Emre Özdamar']::text[], 8.5, '{"poet":"Emre Özdamar","poet_slug":"emre-ozdamar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gittin-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşlar', 'yaslar-berk-berk-tfe36', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerim gözlerini almış karşısına

Anlatıyor nasıl aktığını yaşların...

Anlatıyor nasıl ağladığını

Akamayanların...', 'Gözlerim gözlerini almış karşısına Anlatıyor nasıl aktığını yaşların... Anlatıyor nasıl ağladığını Akamayanların......', ARRAY['Türk Edebiyatı','Şiir','Berk Berk']::text[], 8.5, '{"poet":"Berk Berk","poet_slug":"berk-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yaslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredeyim Ben?', 'neredeyim-ben-yasar-aslan-xdk3u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dona kaldı sevinçlerim 

Ayazdayım, üşüyorum, 

Korkuyorum. 

Kelimeler boğazımda düğümlendi.

Aynalar konuşmuyor, 

Toprak suskun, 

Yıldızlar nerede? 

Susmuş bu şehir, 

Susmuş zemheri karanlık

Konuşun... 

Nedir bu yalnızlık? 

Neredeyim ben? 

Rüzgar da esmiyor, 

Çiçekler inadına solgun, inadına açmıyor.

Üşüyorum.

Güneş doğmuyor. 

Yazı olmayan kıştayım, 

Kimse yok, 

Kimsem yok, 

Söyleyin...

Neredeyim ben? 

Dağlara kâr yağmıyor, 

Ay bakmıyor  yüzüme, 

Her yanım çığlık, 

Her taraf kan içinde.

Neredeyim ben?', 'Dona kaldı sevinçlerim  Ayazdayım, üşüyorum,  Korkuyorum.  Kelimeler boğazımda düğümlendi. Aynalar konuşmuyor,  Toprak suskun,  Yıldızlar ne...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Aslan']::text[], 8.5, '{"poet":"Yaşar Aslan","poet_slug":"yasar-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/neredeyim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilirmisin...', 'bilirmisin-umit-keskin-ivalh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen yalnızlıgın ne oldugunu bilirmisin? 

günler geceler boyunca hasretinle geçen uykusuzlugun

her telefon çalışında''belki odur''diye

parmaklarımın nasıl titredigini bilirmisin? 

telefonu açıp sesini duyamayınca

kalbimin nasıl kırıldıgını bilirmisin? 

ve tam seni bulmuşken hemencecik kaybetmeyi

canım seni öpmek istediginde

yanımda bulamamak nedir bilirmisin? hergün derdinden gözyaşı dökmeyi bilirmisin? 

ama öyleya! tüm bunları nasıl bilebilirsin.

çünkü sen asla kimseyi

BENİM SENİ SEVDİGİM KADAR SEVEMESSİN...', 'Sen yalnızlıgın ne oldugunu bilirmisin?  günler geceler boyunca hasretinle geçen uykusuzlugun her telefon çalışında''belki odur''diye parmakla...', ARRAY['Türk Edebiyatı','Şiir','Ümit Keskin']::text[], 8.5, '{"poet":"Ümit Keskin","poet_slug":"umit-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bilirmisin-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk Oyunu', 'mutluluk-oyunu-reha-basogul-ulzq5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnsan 

korkar

mutlu olmaktan

çünkü

emin değildir

kendinden kaçırdıklarından

insan

sapar

anılara dokunmaktan

çünkü

emin değildir

güçlüyü oynamaktan

insan

bakar

çıkmaz sokaktan

çünkü

emin değildir

yoluna kusacaklardan

insan

ağlar

yalnız kalmaktan

çünkü

emin değildir

boşlukta solacaklardan

insan

kusar

gecesiz karanlıktan

çünkü

emin değildir

ışığın doğurduklarından

insan

kaçar

gerçeği duymaktan

çünkü

emin değildir

yüreğine bakanlardan

insan

solar

buruşmuş kağıttan

çünkü

emin değildir

kalemin ağlamasından

insan

doğar

yargısız tabiattan

çünkü

emin değildir

ölümün korkuttuklarından

insan 

oynar

mutluluk oyunundan

çünkü

emin değildir

insanlığın sapacağından', 'İnsan  korkar mutlu olmaktan çünkü emin değildir kendinden kaçırdıklarından insan sapar anılara dokunmaktan çünkü emin değildir güçlüyü oyna...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/mutluluk-oyunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda', 'veda-seref-isildak-53vgg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalkmak gerekmeyecek yataktan

   ne de uykusuw kalmak

Ölü bir ışıkla yadınlanacak

                       acılar

                       mutsuzluklar

                       karşılıklı haksızlıklar

                       Ve bir boşlukta salınıp durucak sonsuza değin

Sonsuza değin

mızmız bir alev gibi anılar

yaşatırken öldürecek

öldürürken yaşatıcak...

29 Ekim 1995', 'Kalkmak gerekmeyecek yataktan    ne de uykusuw kalmak Ölü bir ışıkla yadınlanacak                        acılar                        mutsu...', ARRAY['Türk Edebiyatı','Şiir','Şeref Işıldak']::text[], 8.5, '{"poet":"Şeref Işıldak","poet_slug":"seref-isildak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/veda-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zorunsama', 'zorunsama-seref-isildak-6kd62', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beton duvarlarla dolu

çocukluğun tasasız sokakları

Kıyıda köşede kalmış

 hâlâ yeşil bahçeli mutluluk oyunları..

tarihin içinde bir var oluş anı değil

tarihin kendisidir 

yaşanan her anı...

hasretler toplamı

arayışlar çıkarımı

acılar çarpımı

ayrılıklar bölümü

Bir de......

biteviye sürecek yalnızlığın sancısı.....

AŞK ACISI......

Hepsi Ama hepsi insan olma çabası

Yeniden ve başka biri olmak

Elbette herkes için geçerli bir olanak

Oysa...

geçmişin yapraklarından sızan özlem

değişen iklimlerde

peşini bırakmayan bir ikilem

''Gönüllü'', gönülsüz

terk-i diyar

aslı biraz da ölümdür

yeni coğrafyalar, başka toplumlar

-BİR NEVİ İNTİHAR-

Ne kalmışsa içimde bunca zaman sonrası

bir o kadar da bana yabancı

Ben gurbette değil

gurbet benim içimde

                   dehşetli bir acı

Gözlerimde sıkıyönetim

                      yüreğimde darağacı........

14-17 Mayıs 1999 / Ankara', 'Beton duvarlarla dolu çocukluğun tasasız sokakları Kıyıda köşede kalmış  hâlâ yeşil bahçeli mutluluk oyunları.. tarihin içinde bir var oluş ...', ARRAY['Türk Edebiyatı','Şiir','Şeref Işıldak']::text[], 8.5, '{"poet":"Şeref Işıldak","poet_slug":"seref-isildak","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/zorunsama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '17. Bronz Kedi Monoloğu', '17-bronz-kedi-monologu-mehmet-ali-yolcu-u9qc2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir hüzün akşamından gelirdim 

ellerim aralıksız ıslaktı

yüreğimde yitirdikçe o saygın gökleri 

inanılmaz yangınları sorardım 

oysa postalları merak ederdi herkes 

ve öz saygısını yitirmiş olan herkes 

bir gürültüden başka bir şey değildi

o zaman adımın tuhaf yankısıyla 

bir hüzün akşamından gelirdim...', 'Bir hüzün akşamından gelirdim  ellerim aralıksız ıslaktı yüreğimde yitirdikçe o saygın gökleri  inanılmaz yangınları sorardım  oysa postalla...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Yolcu']::text[], 8.5, '{"poet":"Mehmet Ali Yolcu","poet_slug":"mehmet-ali-yolcu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/17-bronz-kedi-monologu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yak Beni', 'yak-beni-orhan-seyfi-sirin-ut8su', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hal vurup, harman savur

Didik didik et beni

Karlı ateşlerde yak

Uçurumdan at beni

Alev alev yak beni

Nefes nefes çek beni

Bir mavzer al omzuna

Kurşunlayıp yık beni

Toprak olam, ek beni

Pamuk olam, bük beni

Kervan olam elinde

Diyar diyar çek beni

Çarmıha ger, çek beni

Mengene ol, sık beni

Bir mavzer al eline

Gülle gülle yık beni', 'Hal vurup, harman savur Didik didik et beni Karlı ateşlerde yak Uçurumdan at beni Alev alev yak beni Nefes nefes çek beni Bir mavzer al omzu...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Şirin']::text[], 8.5, '{"poet":"Orhan Seyfi Şirin","poet_slug":"orhan-seyfi-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yak-beni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını Sen Koy', 'adini-sen-koy-gulten-cicek-0z57d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Özlerim ben seni, seninle bile

Vuslat mı, hasret mi, adını sen koy

Aşkınla yakıp da düşürdün dile

Sevgi mi, nefret mi, adını sen koy

İlk ve son aşkımdın, gençlik çağımda

Sevgi çiçeğimdin, gönül bağımda

Öyle yer etmiştin, kalp otağımda

Sıla mı, gubet mi, adını sen koy

Aşkını ateşi yakar, kavurur

Rüzgarım olursun, aşkla savurur

Bağrımı delersin, bakınca durur

Nazar mı, hiddet mi, adını sen koy', 'Özlerim ben seni, seninle bile Vuslat mı, hasret mi, adını sen koy Aşkınla yakıp da düşürdün dile Sevgi mi, nefret mi, adını sen koy İlk ve ...', ARRAY['Türk Edebiyatı','Şiir','Gülten Çiçek']::text[], 8.5, '{"poet":"Gülten Çiçek","poet_slug":"gulten-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/adini-sen-koy-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardelen', 'kardelen-hayrullah-pasalioglu-srqn6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu bendeki bir dert ki, anlatamam kimseye

Kulak verip de beni dinler misin kardelen? 

Sardı tüm benliğimi, mecalim yok gülmeye

Sende benle ağlayıp, inler misin kardelen? 

Mis gibi sıla kokan eş, dost mektuplarında

Taze güller yeşerir eski anılarında

Hatıralarla dolu gurbet akşamlarında

Hasret denen türküyü söyler misin kardelen? 

Bütün duyguları bir deftere yazmanın

Dertlerini duymayan duvara anlatmanın

İçinde ne var ise hep içine atmanın

Ne demek olduğunu bilir misin kardelen? 

Dostu oldum kaç defa sabahsız gecelerin

Defterimde yeri yok, anlamsız hecelerin

Çözemedim bir türlü bu zor bilmecelerin

Cevabını sen bana çözer misin kardelen? 

Ne kadar tattırsa da ayrılık acısını

Unutamazsın yine onun hatırasını

Bir kenara bırakıp acısı, tatlısını

Hepsini bir kalemde siler misin kardelen? 

Anlat sende içini, dök dışına ne varsa

Hiç düşünme kalbimi, bırak yansın yanarsa

Bu derdi sen benimle paylaşır mısın, yoksa

Bakıp bakıp halime güler misin kardelen? 

Bilirim ben yerini, sormam sana nerdesin

Senin yurdun dağlarda, sen hep yükseklerdesin

Nasıl gelsem yanına, her zaman göklerdesin

Eğilip de elimden tutar mısın kardelen? 

Ah gurbet, sen içimde dinmeyen bir sancısın

Bazen iyisin amma çoğu zaman acısın

Ey kardelen! Sen bana neden yabancısın

Çaldım işte kapını, açar mısın kardelen? 

Senin de gözlerin yaşlı, ağlamışsın besbelli

Yoksa sen de benim gibi naçar mısın kardelen

Bu topraktan çıkıp da dağları delmişsin ya

Mevsimin gelmeyince açar mısın kardelen? 

Derdimi de dinledin, sana ağır gelirse

Yine toprak altına kaçar mısın kardelen? 

Ya ölüm günü gelip de alırlarsa ruhumu

Benimle gökyüzüne uçar mısın kardelen?', 'Bu bendeki bir dert ki, anlatamam kimseye Kulak verip de beni dinler misin kardelen?  Sardı tüm benliğimi, mecalim yok gülmeye Sende benle a...', ARRAY['Türk Edebiyatı','Şiir','Hayrullah Paşalıoğlu']::text[], 8.5, '{"poet":"Hayrullah Paşalıoğlu","poet_slug":"hayrullah-pasalioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/kardelen-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Yazdım', 'sana-yazdim-bahaettin-karakoc-dh9a8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mürşidimi soranlara, hep seni tarif ettim,

Her zaman dizlerinin dibiydi, benim mektebim; 

Ben tuttum sabırla çile çile yazdım...

Çeksen bile koruyucu kanatlarını üstümden,

Senin öğrettiklerinle şimdi ben ayakatayım; 

Anlarsın, bu şiiri sana yazdım...

Her gece yıldızları yakan elimsin diye,

Beynime, yüreğime tercüman dilimsin diye

Adını adımla bile bile yazdım...

Dil susunca uğuldar içimizde ki mağara,

Gönül Mansur gibi bin kez çekilip dara; 

Anladım adını güle yazdım...

Şair oğlu şairim, redd-i miras hakkım yok,

Gider gittiği yere, yaydan fırlayan ok; 

Bunu her menzile yazdım...', 'Mürşidimi soranlara, hep seni tarif ettim, Her zaman dizlerinin dibiydi, benim mektebim;  Ben tuttum sabırla çile çile yazdım... Çeksen bile...', ARRAY['Türk Edebiyatı','Şiir','Bahaettin Karakoç']::text[], 8.5, '{"poet":"Bahaettin Karakoç","poet_slug":"bahaettin-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sana-yazdim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok mu Gördünüz', 'cok-mu-gordunuz-ali-i-hsan-birgul-20h5n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beni sevdiğimden ayıran eller

Bana bu sevgiyi çok mu gördünüz

Ömrümde ilk defa yüzüm gülmüştü

Bir kere gülmeyi çok mu gördünüz

Ne zararım vardı benim sizlere

Suçum neydi, benden ne istediniz

Gözünüz mü kaldı mutluluğumda

Bir kere gülmeyi çok mu gördünüz

Benim de hakkımdı; sevmek, sevilmek

Yalnızlık ne demek, bilir misiniz

Onunla bağlıydım ben bu hayata

Bana yaşamayı çok mu gördünüz', 'Beni sevdiğimden ayıran eller Bana bu sevgiyi çok mu gördünüz Ömrümde ilk defa yüzüm gülmüştü Bir kere gülmeyi çok mu gördünüz Ne zararım va...', ARRAY['Türk Edebiyatı','Şiir','Ali İhsan Birgül']::text[], 8.5, '{"poet":"Ali İhsan Birgül","poet_slug":"ali-i-hsan-birgul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cok-mu-gordunuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazık Olacak', 'yazik-olacak-ali-i-hsan-birgul-u7ozf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Böyle çok severken birbirimizi

Kim derdi ki sonumuz hüsran olacak

Her gün ağlatırsan, üzersen beni

Sevgilim bu aşka yazık olacak

Kırıyorsun beni sebepsiz yere

Acı veriyorsun seven kalbime

Bu gurur, bu inat böyle sürerse

Sevgilim bu aşka yazık olacak

Çılgınca severken değiştin birden

Benden kaçar oldun, bilmem ki neden

Bir çare bulalım, her şey bitmeden

Sevgilim bu aşka yazık olacak', 'Böyle çok severken birbirimizi Kim derdi ki sonumuz hüsran olacak Her gün ağlatırsan, üzersen beni Sevgilim bu aşka yazık olacak Kırıyorsun ...', ARRAY['Türk Edebiyatı','Şiir','Ali İhsan Birgül']::text[], 8.5, '{"poet":"Ali İhsan Birgül","poet_slug":"ali-i-hsan-birgul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yazik-olacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşamdan Akşama', 'aksamdan-aksama-halil-gokkaya-6d3lh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hatıralar bir çığ gibi,

Çöker akşamdan akşama.

Umutlar ters yöne kürek,

Çeker akşamdan akşama...

Yollara çöksede hüzün,

Kaybolup gitse de izin.

Mehtap olur güzel yüzün

Çıkar akşam dan akşama...

Ufukta kaybolur güneş

Yalnızlığım dağlara eş.

Hasretin içimde ateş

Yakar akşamdan akşama...

Kapımda bir gururun devi,

Talan oldu gönül evi.

Yokluğun kalbime çivi,

Çakar akşamdan akşama...

Kapanır bir bir kapılar

Gözlerim hayale dalar

İsmin dilimi parçalar

Diker akşamdan akşama', 'Hatıralar bir çığ gibi, Çöker akşamdan akşama. Umutlar ters yöne kürek, Çeker akşamdan akşama... Yollara çöksede hüzün, Kaybolup gitse de iz...', ARRAY['Türk Edebiyatı','Şiir','Halil Gökkaya']::text[], 8.5, '{"poet":"Halil Gökkaya","poet_slug":"halil-gokkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aksamdan-aksama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellere Söyleyemedim', 'ellere-soyleyemedim-salih-kivanc-p7tc8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mevsimler boşuna geçti, sessiz sedasız

Birikti duygular, dile getiremedim

Yağmurlu bir gündü, çıkıp gittin ansızın

Seni sevdiğimi ellere söyleyemedim

Yol boyunca hem yürüdüm, hem düşündüm

Nice baharlar, göçmen kuşlar geldi geçti

Sen kaldın düşlerimde cananım olarak

Seni sevdiğimi ellere söyleyemedim

Şimdi dağlar dumanlı, gönlümde hüzün var

Güller solmuş, lalelerde sisli bir hüzün var

Gittin gideli içimde tarifsiz bir sıkıntı var

Seni sevdiğimi ellere söyleyemedim', 'Mevsimler boşuna geçti, sessiz sedasız Birikti duygular, dile getiremedim Yağmurlu bir gündü, çıkıp gittin ansızın Seni sevdiğimi ellere söy...', ARRAY['Türk Edebiyatı','Şiir','Salih Kıvanç']::text[], 8.5, '{"poet":"Salih Kıvanç","poet_slug":"salih-kivanc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ellere-soyleyemedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Çok Seviyorum', 'seni-cok-seviyorum-gulten-cicek-m79pi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anlatmaya çalışsam

Söylenmez biliyorum

Sensizliğe alışsam

Seni çok seviyorum

Anlatamam, bilemem

Kalbimdesin, silemem

Çağırmazsan gelemem

Seni çok seviyorum

Sen gözümde birinci

Eşi olmayan inci

Sensin hayat sevinci

Seni çok seviyorum

Kalbimde ağrısın sen

İlk aşka çağrısın sen

Nasıl sevdim bir bilsen

Seni çok seviyorum

İşte bugün aynı yer

Sen de sevdiysen eğer

Aşkıma karşılık ver

Seni çok seviyorum', 'Anlatmaya çalışsam Söylenmez biliyorum Sensizliğe alışsam Seni çok seviyorum Anlatamam, bilemem Kalbimdesin, silemem Çağırmazsan gelemem Sen...', ARRAY['Türk Edebiyatı','Şiir','Gülten Çiçek']::text[], 8.5, '{"poet":"Gülten Çiçek","poet_slug":"gulten-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seni-cok-seviyorum-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boynumuz Bükük şimdi', 'boynumuz-bukuk-simdi-orhan-seyfi-sirin-hp51s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senden yana bende bir coşkun ırmak akardı

Köprülerim atılmış, setlerim yıkık şimdi

Her bahar ilk şimşekler göğsümüzde çakardı

Kırılmış güller gibi, boynumuz bükük şimdi

Pek çok düşler görürüm, gecelerin bağrında

Hayalin gülümser, hep karşıma çık der gibi

Neden boynumuz bükük, yıldız yağmurlarında

Kırılmış güller gibi, kırık çiçekler gibi', 'Senden yana bende bir coşkun ırmak akardı Köprülerim atılmış, setlerim yıkık şimdi Her bahar ilk şimşekler göğsümüzde çakardı Kırılmış gülle...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Şirin']::text[], 8.5, '{"poet":"Orhan Seyfi Şirin","poet_slug":"orhan-seyfi-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/boynumuz-bukuk-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Bilir?', 'kim-bilir-reha-basogul-rkavw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hani

sorarırız ya

birbirimize: 

bu dünyayı

çok okuyan mı

çok gezen mi bilir? 

ben; 

hem çok okudum

hem çok gezdim

ama hala cevabını bilemedim...

kim bilir

belki de

çok soran bilir...', 'hani sorarırız ya birbirimize:  bu dünyayı çok okuyan mı çok gezen mi bilir?  ben;  hem çok okudum hem çok gezdim ama hala cevabını bilemedi...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kim-bilir-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskiden Bilmezdim Yalnızlığı', 'eskiden-bilmezdim-yalnizligi-yilmaz-guney-djrvd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eskiden bilmezdim yalnızlığı 

Bir ağaç nasıl yalnız değilse ormanında 

Bir çiçek kendi dalında 

Eskiden bilmezdim yalnızlığı 

Yalnızlığın içinde 

Şimdi yalnız, yalnız mıyım 

Kopuk muyum dalımdan 

Uzağında mı kaldım ormanın', 'Eskiden bilmezdim yalnızlığı  Bir ağaç nasıl yalnız değilse ormanında  Bir çiçek kendi dalında  Eskiden bilmezdim yalnızlığı  Yalnızlığın iç...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Güney']::text[], 8.5, '{"poet":"Yılmaz Güney","poet_slug":"yilmaz-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/eskiden-bilmezdim-yalnizligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor Olan Sevmek', 'zor-olan-sevmek-metin-usengec-c0n26', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zamanla unutur muyum seni

Diner mi acılar yüreğimde

Kapanır mı içimdeki kocaman boşluk

Geceler seni aratır mı bana

Sever miyim yeniden bir başkasını

İnanır mıyım sevgiye tekrar

Uçar mı yüreğim eskisi gibi

Güvenir miyim artık insanlara

Affeder miyim seni asla

Hakkım helal olurmu ki sana

Geçer mi sensiz uzun günler

Ölebilir miyim huzur içinde

Kolay olan terk edip gitmek

Zor olanmış kalpten sevmek

İsterdim ki güzellikler dilemek

İsterdim ki seni mutlu etmek

Hak mı şimdi bu günleri görmek..

28-Aralık-2002  17:30

Ne Senden Vazgeçebildim Nede Sevginden..', 'Zamanla unutur muyum seni Diner mi acılar yüreğimde Kapanır mı içimdeki kocaman boşluk Geceler seni aratır mı bana Sever miyim yeniden bir b...', ARRAY['Türk Edebiyatı','Şiir','Metin Üşengeç']::text[], 8.5, '{"poet":"Metin Üşengeç","poet_slug":"metin-usengec","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/zor-olan-sevmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük Aşkım', 'buyuk-askim-yavuz-selim-dizdar-byzm2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu satırlar kalemimin ucundan dökülürken

saat gecenin birine yaklaşıyordu

inan sadece seni düşünüyordum

hatıralarım iki nokt arasındaki en kısa yol gibi

hep sana götürüyordu beni

Ey sevgili

sana aşık olduğumdan beri

ne uyku var gözümde

ne tadı var akşamları içtiğim tavşan kanı çayın

nede anlamı sensiz yediğim mayonezli kumpirin

Seni sevmeden önce ben gerçekten bendim

seni sevdikten sonra

ben benliğimi kaybettim

şimdi senden bir tek şey istiyorum

Yum gözlerini

içindeki akışın sesini dinle

aç şimdi bak gözlerime

gözlerindeki özlemi gözle...', 'Bu satırlar kalemimin ucundan dökülürken saat gecenin birine yaklaşıyordu inan sadece seni düşünüyordum hatıralarım iki nokt arasındaki en k...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Selim Dizdar']::text[], 8.5, '{"poet":"Yavuz Selim Dizdar","poet_slug":"yavuz-selim-dizdar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/buyuk-askim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlarım', 'aglarim-i-hsan-raif-hanim-ilimk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Neden gülmesin gül gibi yüzler; 

Niçin ağlasın o güzel gözler, 

Niye sevgiye sevimsiz sözler, 

Söylenir diye şaşar ağlarım.

Şu gördüğümüz rengarenk, çiçek, 

Sevdalı bülbül, arı, kelebek, 

Yekdiğerini bırakıp gidecek: 

Vefasızlığa bakar ağlarım.

Solmasın dersin sünbülüm, gülüm; 

Yarin elinden alacak ölüm; 

Bütün dünyayı inletse ünüm; 

Çaresizlikten coşar ağlarım.

Neş''e gizlenir çöker bir melal; 

Her vücud, her şey mahkum zülal; 

Son nefese kadar tükenmez cidal, 

Tükenmez derdim sayar ağlarım.

Aklım ermiyor of, ne haldir bu! 

Yaşamak için dert, mihnet kaygu; 

Bir zevke bedel bin acı duygu; 

Duygusuz felek sorar ağlarım.

Zalimler ceza görmeli elbet.

Mazlumlar niçin çeksinler zahmet? 

Hak çiğneniyor, nedir bu hikmet? 

Haksızlıklara yanar ağlarım.

(Gözyaşları adlı kitabından)', 'Neden gülmesin gül gibi yüzler;  Niçin ağlasın o güzel gözler,  Niye sevgiye sevimsiz sözler,  Söylenir diye şaşar ağlarım. Şu gördüğümüz re...', ARRAY['Türk Edebiyatı','Şiir','İhsan Raif Hanım']::text[], 8.5, '{"poet":"İhsan Raif Hanım","poet_slug":"i-hsan-raif-hanim","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/aglarim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Sevdadan Geçersin', 'bu-sevdadan-gecersin-i-hsan-raif-hanim-21gp5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Niçin beni yan bakışla süzersin? 

Sözlerime neden dudak bükersin? 

Bugün sever, yarın belki üzersin

Gel üzülme, bu sevdadan geçersin.

Sevsen de hoş, sevmesen de sen beni, 

Ben vahşiyim, hiç sevdirtmem kendimi; 

Bu halimle incitirim ben seni; 

İncinmeden bu sevdadan geçersin.

Bülbül gibi aşık olma her güle; 

Vefasızdır, gül inanmaz, bülbüle; 

Çünkü şakır lalelere, sünbüle; 

Sünbül gibi aşkın solar geçersin.

(Gözyaşları adlı kitabından alınmıştır.)', 'Niçin beni yan bakışla süzersin?  Sözlerime neden dudak bükersin?  Bugün sever, yarın belki üzersin Gel üzülme, bu sevdadan geçersin. Sevsen...', ARRAY['Türk Edebiyatı','Şiir','İhsan Raif Hanım']::text[], 8.5, '{"poet":"İhsan Raif Hanım","poet_slug":"i-hsan-raif-hanim","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bu-sevdadan-gecersin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serzeniş', 'serzenis-meltem-seyhan-4ja1e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Söyleyecek sözüm

Makul bir özrüm yok

Hayatı yaşanır kılacak

Bildiğim hiçbirsey yok

Hepsinden kötüsü

Mutsuz yüzüme sebep

Hiçbir derdim de yok

Bıktım dinlemekten

Dinlenip bunalmaktan

Yutkunup da susmaktan

Bıktım büyük meselelerden

Küçük sevinçlerden

Sokaktaki çocuklara

Acıyıp üzülmekten', 'Söyleyecek sözüm Makul bir özrüm yok Hayatı yaşanır kılacak Bildiğim hiçbirsey yok Hepsinden kötüsü Mutsuz yüzüme sebep Hiçbir derdim de yok...', ARRAY['Türk Edebiyatı','Şiir','Meltem Seyhan']::text[], 8.5, '{"poet":"Meltem Seyhan","poet_slug":"meltem-seyhan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/serzenis-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim Seni', 'ozledim-seni-abdullah-ozturk-35oce', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Susmuyorum inadına

Suskunluğumu fırsat bilip suskunluğum

Gözlerini getiriyor aklıma

Ben aklımda gözlerini istemiyorum

Kuştüyü hayata koymuşum ömrümü

Daha sonra seni tanıdım

Ve gittin

Anladım ki hayat denen şey çok daha sertmiş

Yaşamak diyorlar adına

Yaşamayı becerenler

Ben ölümü sevdim

Beceremesem de

Yoruldum

Beklemekten

Beklemeyi bilmekten

Sevemesem de 

Beklemeyi sevmekten

Seni seviyorum

Senden olan herşeyi

Özlemi de

Şimdi bir kızım var özlemden

Sana benziyor

Kokusunu teninden

Ruhunu gözlerinden

Hırçınlığını saçlarından almış

Adını benden

Adı “yok”', 'Susmuyorum inadına Suskunluğumu fırsat bilip suskunluğum Gözlerini getiriyor aklıma Ben aklımda gözlerini istemiyorum Kuştüyü hayata koymuşu...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Öztürk']::text[], 8.5, '{"poet":"Abdullah Öztürk","poet_slug":"abdullah-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ozledim-seni-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnadına Sevdim', 'i-nadina-sevdim-mehmet-sisli-0tvnp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her gece ayrılık şarkıları dinliyorum

Bıkmadan inadına

Tam şuan resmin var duvarda 

Sagımda sen solumda sen

Varoluyorsun bir anda

Ölümse ölüyorum işte

Acı çekmekse yok olurcasına

Her gün ayrılık şarkıları dinler oldum

Göz yaşları içinde

Gecenin kahpe kucagında 

Sabahın hasret ayazlarında

Mutsuzlugumsa başarıdın işte

Hapsetmekse esirin oldum sonunda

Ayrılık üzerine yazılan satırları

İçiyorum yudum yudum

Bıkmadan inadına

Oysa oysa ben hiç kavuşamadım seninle 

Belki bir gün ayrılırız diye

Bedeli olmalı galiba

Belkide gözümde büyüttüm

Gönlümde yücelttim ben seni

Sevmeye kalktım olmayan yüregini', 'Her gece ayrılık şarkıları dinliyorum Bıkmadan inadına Tam şuan resmin var duvarda  Sagımda sen solumda sen Varoluyorsun bir anda Ölümse ölü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şişli']::text[], 8.5, '{"poet":"Mehmet Şişli","poet_slug":"mehmet-sisli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/inadina-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni anlatmak', 'seni-anlatmak-sair-khan-xytzt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni anlatmak yeni doğmuş bir bebeğe isim koymak kadar zor... 

Sevgiyi sepete doldurmak, yağmur suyuyla bir nehir akıtmak kadar zor... 

Seni tanımak önce kendi bedenimi tanımak, ardından seni tanıyabilmekti. 

İnsan kendini tanımadan nasıl seni tanıyabilirdi. 

Seni anlatmak çok zor.. 

Sözlükte eksik bırakılmış, tarif edilmemiş, adı konmamış tüm kelimeler sendin 

.Gelmemiş tüm baharlardaki dalllarda öpüşen kuşlar sendin. 

Ayın hilalindeki en büyük hare sendin. 

Cezvede kaynayan kahve telvesindeki kahverengilik sendin ve gözlerin... 

Sıcak yaz günlerinde serin esen her yel nefesin. 

Ağır ağır hüşuyla salınan söğüt dalları saçların. 

Asırlara şahitlik yapmış dev meşenin gövdesi gövden. 

Kafesteki muhabbet kuşunun ürkekliği ruhunun dünyaya yansımasıydı. 

Seni başka nasıl tarif edebilirdim ki. 

Kovada yaşaması beklenen bir balık gibisin. 

Oysa sen özgürce dolaşabileceğin büyük denizlerde yaşamalısın. 

Tarlada güneşe bağrını açan günebakan gibisin. 

Hoyrat ve kendi asilliğinde... 

Gökyüzündeki en parlak yıldız gibisin sadece isteyene görüneninden. 

Deniz diplerinde dalanlara çarpan güçlü bir vurgunsun; asil, asi ve deli başı bozuk... 

Güzelliğinle büyüleyip içinde, bağrında çarpıveren. 

Oysa senin sevdan buydu. 

Severken, vurgun yiyordu tüm sevdiklerin... 

Tıpkı benim gibi...', 'Seni anlatmak yeni doğmuş bir bebeğe isim koymak kadar zor...  Sevgiyi sepete doldurmak, yağmur suyuyla bir nehir akıtmak kadar zor...  Seni...', ARRAY['Türk Edebiyatı','Şiir','Şair Khan']::text[], 8.5, '{"poet":"Şair Khan","poet_slug":"sair-khan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/seni-anlatmak-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek', 'tek-mehmet-sisli-wod65', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün olur göçerim bu dünyadan 

Okursun bu satırları haberim olmadan

İkimiz için sadece ikimiz

Başaramasakta biz tek yüregiz

Yokluğunda yüreğim tutuşur oldu

Ama vakit doldu, doldu birtanem 

Yaşasın istedim bu yürek

Sonsuza kadar

Ama şimdi o yürek tek', 'Bir gün olur göçerim bu dünyadan  Okursun bu satırları haberim olmadan İkimiz için sadece ikimiz Başaramasakta biz tek yüregiz Yokluğunda yü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şişli']::text[], 8.5, '{"poet":"Mehmet Şişli","poet_slug":"mehmet-sisli","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tek-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vapur', 'vapur-volkan-alper-0r3b0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Madde ve ruh rayından çıkmıştı                                                  

Ve sonra ölüm geldi    aklıma                                                     

Onu da diğerlerinin yanına gönderip                                           

Düşünce vapurunda seyahate başladım', 'Madde ve ruh rayından çıkmıştı                                                   Ve sonra ölüm geldi    aklıma                              ...', ARRAY['Türk Edebiyatı','Şiir','Volkan Alper']::text[], 8.5, '{"poet":"Volkan Alper","poet_slug":"volkan-alper","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/vapur-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geldin mi?', 'geldin-mi-ahmet-kurnaz-7i4d0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Varlığın bir kış güneşi kadar kısa oldu.

Bir geceyarısı gelmiştin, 

yine bir gün ortasında gittin, 

gün dönmeden daha.

Ey; gizli sevda''m, suçum, günahım, 

Gün ortasında kaybettiğim hazan sabahım.

Yine mi başladı sensiz günler, 

yine şafak vaktinde seni mi bekleyeceğim.

her senenin yaz başlarında.

Döndün diyordum, 

dönmemişsin.

içimde ateştin yıllar boyunca, 

söndün sanırdım, 

sönmemişsin.

Yanıyorsun içimde tüm sıcaklığınla, 

dumansız issiz.

Şimdi kaç yürekten sürülecek, 

hangi anılardan silineceğim.

hangi gurbet akşamında 

ağlayacağım gidişine, 

ve, dönmeyişine.

Biliyorum boğulacak ruhum, 

seni görmeyince gözüm sokaklarda.

senin açtığın kapının, 

sesini duymayınca kulaklarım.

Eriyeceğim, 

bir mum gibi.Damla damla, 

tükeneceğim.

                     25 EYLÜL 2002/Elbistan', 'Varlığın bir kış güneşi kadar kısa oldu. Bir geceyarısı gelmiştin,  yine bir gün ortasında gittin,  gün dönmeden daha. Ey; gizli sevda''m, su...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurnaz']::text[], 8.5, '{"poet":"Ahmet Kurnaz","poet_slug":"ahmet-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/geldin-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Banadır dönüşleri yalnızlıkların', 'banadir-donusleri-yalnizliklarin-murat-tali-1ut23', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir gün

düşerse yalnızlığa iklimler

kutuplardan düşen bir buz saplanır okyanus 

derinliğine

balinaların püskürttüğü su donar havada

üşür eskimo gülüşleri

üşür kutup ayıları

üşür foklar ve penguenler

tutunurum ellerine 

sıcaklığınla dönerim ekvator kızgınlığına ve çöl yalnızlığıma', 'bir gün düşerse yalnızlığa iklimler kutuplardan düşen bir buz saplanır okyanus  derinliğine balinaların püskürttüğü su donar havada üşür esk...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/banadir-donusleri-yalnizliklarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer', 'eger-rudyard-kipling-s3gxa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eğer, bütün etrafındakiler panik içine düştüğü

ve bunun sebebini senden bildikleri zaman

sen başını dik tutabilir ve sağduyunu kaybetmezsen; 

Eğer sana kimse güvenmezken sen kendine güvenir

ve onların güvenmemesini de haklı görebilirsen; 

Eğer beklemesini bilir ve beklemekten de yorulmazsan

veya hakkında yalan söylenir de sen yalanla iş görmezsen, 

ya da senden nefret edilir de kendini nefrete kaptırmazsan, 

bütün bunlarla beraber ne çok iyi ne de çok akıllı görünmezsen; 

Eğer hayal edebilir de hayallerine esir olmazsan, 

Eğer düşünebilip de düşüncelerini amaç edinebilirsen, 

Eğer zafer ve yenilgi ile karşılaşır

ve bu iki hokkabaza aynı şekilde davranabilirsen; 

Eğer ağzından çıkan bir gerçeğin bazı alçaklar tarafından

ahmaklara tuzak kurmak için eğilip bükülmesine katlanabilirsen, 

ya da ömrünü verdiğin şeylerin bir gün başına yıkıldığını görür

ve eğilip yıpranmış aletlerle onları yeniden yapabilirsen; 

Eğer bütün kazancını bir yığın yapabilir

ve yazı-tura oyununda hepsini tehlikeye atabilirsen; 

ve kaybedip yeniden başlayabilir

ve kaybın hakkında bir kerecik olsun bir şey söylemezsen; 

Eğer kalp, sinir ve kasların eskidikten çok sonra bile

işine yaramaya zorlayabilirsen

ve kendinde ''dayan'' diyen bir iradeden

başka bir güç kalmadığı zaman dayanabilirsen; 

Eğer kalabalıklarda konuşup onurunu koruyabilirsen, 

ya da krallarla gezip karakterini kaybetmezsen; 

Eğer ne düşmanların ne de sevgili dostların seni incitmezse; 

Eğer aşırıya kaçmadan tüm insanları sevebilirsen; 

Eğer bir daha dönmeyecek olan dakikayı, 

altmış saniyede koşarak doldurabilirsen; 

Yeryüzü ve üstündekiler senindir

Ve dahası

sen bir İNSAN olursun oğlum...', 'Eğer, bütün etrafındakiler panik içine düştüğü ve bunun sebebini senden bildikleri zaman sen başını dik tutabilir ve sağduyunu kaybetmezsen;...', ARRAY['Türk Edebiyatı','Şiir','Rudyard Kipling']::text[], 8.5, '{"poet":"Rudyard Kipling","poet_slug":"rudyard-kipling","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/eger-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babama Selam Söyle', 'babama-selam-soyle-i-clal-aydin-wscsl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karlı bir akşamdı Ankara''da; 

Son kez elele yürümüştük, 

Bitmesin istediğimiz yola.

Kısacık beraberliğimizin bütün anılarını sığdırmıştık.

Yazarsın bana demiştin.

Bende yazarım sana sık sık.

Ağlıyordum....

Sen görmeyesin diye kaldırmıyordum başımı.

Elimi daha sıkı tuttun, 

Anlıyordun....

Bu ayrılığa dayanmıyordu kalbim, 

Öğrettiğim çiçek adlarını unutma dedin, 

Kelebekleri kitap arasında kurutma, 

Sık sık fotoğraf çektir, yolla bana, 

Kitaplarım sana emanet, 

İncitme kimseyi, kin büyütme kalbinde...

Beni bekle...

Yol bitti, gidiyordun artık; gittin

Sokakta gördüklerimi, filmlerdeki aktörleri sen sandım bir süre, 

Kin büyütmedim kalbimde söz vermiştim sana diye, 

Kitaplarını okudum, kelebeklerine dokunmadım, 

Öğrendiğim çiçek adlarına yenilerini ekledim, 

En çok fesleğeni, çoban heybesini, akşam sefasını sevdim.

Seni beklerken çok şey öğrendim, 

Yolunu gözlediğim, sevdiğim ilk adam...

Nasıl olsa bulacaktır diye, her görüşümde aynı sesle seslendim

Uçak, babama selam söyle! 

Beni kötü rüyalardan uyandıran sevdiğim ilk adam...

Bir bilsen seni nasıl özledim...

Kar yağıyor şimdi, otuz yaşım bitti, 

Kitapların bende, kelebekler gibi kar taneleri, 

Kendi yolumda yürürken hiç unutmadım o cümleyi; 

Selamını aldım babacığım, 

Kin büyütmedim kalbimde....

Küçük kızının gözleri hala senin çiçeklerinde.

Uçak, babama selam söyle! 

Uçak, babama selam söyle!', 'Karlı bir akşamdı Ankara''da;  Son kez elele yürümüştük,  Bitmesin istediğimiz yola. Kısacık beraberliğimizin bütün anılarını sığdırmıştık. Y...', ARRAY['Türk Edebiyatı','Şiir','İclal Aydın']::text[], 8.5, '{"poet":"İclal Aydın","poet_slug":"i-clal-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/babama-selam-soyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Şey', 'guzel-sey-haci-yusuf-kiymazarslan-zqc9u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beklemek güzel şey

Umudu yitirmezcesine

Kalplerdeki arzuyu

Serinletmek güzel şey

Bakarken uzaklara

Gözler nemli, bulanık

Gün doğar, gün batar ufukta

Uyanıklık güzel şey

Sürüncemede ne kalmış dünyada

Anılar eğri büğrü kabında

Bir el, bir göz ve yarın

Yeşilliği bilmem kaçıncı baharın

Yarım kalmış [çay] güzel şey

1.2.1966', 'Beklemek güzel şey Umudu yitirmezcesine Kalplerdeki arzuyu Serinletmek güzel şey Bakarken uzaklara Gözler nemli, bulanık Gün doğar, gün bata...', ARRAY['Türk Edebiyatı','Şiir','Hacı Yusuf Kıymazarslan']::text[], 8.5, '{"poet":"Hacı Yusuf Kıymazarslan","poet_slug":"haci-yusuf-kiymazarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/guzel-sey-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulunmaz', 'bulunmaz-haci-yusuf-kiymazarslan-vl8yx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kuş olurum dolaşırım havada

Güneş olur kızarırım semada

Anladım ki şu kocaman dünyada

Gönlü hoş edecek ferman bulunmaz.

Kalbim ateş saçar kor evi gibi

Talihse karşımda kaf devi gibi

Usandım hayattan Bedevi gibi

Dolaşsam çölleri kervan bulunmaz.

Aldırmayıp el alemin sözüne

Hamle etsem talimin izine

Tükürmek istesem kalkıp yüzüne

Bu kez dizlerimde derman bulunmaz.

Çoğu istemem ben kuluyum azın

Tadını görmedim baharın yazın

Talinden bicav olan Kıymaz''ın

Derdini serecek harman bulunmaz.

17.3.1966', 'Kuş olurum dolaşırım havada Güneş olur kızarırım semada Anladım ki şu kocaman dünyada Gönlü hoş edecek ferman bulunmaz. Kalbim ateş saçar ko...', ARRAY['Türk Edebiyatı','Şiir','Hacı Yusuf Kıymazarslan']::text[], 8.5, '{"poet":"Hacı Yusuf Kıymazarslan","poet_slug":"haci-yusuf-kiymazarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bulunmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluk', 'yokluk-haci-yusuf-kiymazarslan-s4xt7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gelme kapıma yokluk

Kapım küçücük kırılır

İnsanca yaşamak isterim

Yıllardır, yüzüm soğuk

Çalma kapımı, üşürsün yokluk.

Neyim var alacaksın bilmem

Dönüp dolaşırısın çevremde

Odun derdi, kömür derdi gördüğün gibi

Çökertti böyle çabuk

Çalma kapımı, üşürsün yokluk.

Arkadaşlığımdan var mı kazancın

Zenginler bilirim büyük büyük

Ya da kaf dağının arkasında

Paralar akarmış oluk oluk (!)

Oraya git, oraya git yokluk.

Gelme kapıma yokluk

Kapım çürüktür yıkılır

İnsana doğdum anamdan

Bakma sen yüzüm soğuk

Çalma kapımı, üşürsün yokluk.

22.1.1967 Ankara', 'Gelme kapıma yokluk Kapım küçücük kırılır İnsanca yaşamak isterim Yıllardır, yüzüm soğuk Çalma kapımı, üşürsün yokluk. Neyim var alacaksın b...', ARRAY['Türk Edebiyatı','Şiir','Hacı Yusuf Kıymazarslan']::text[], 8.5, '{"poet":"Hacı Yusuf Kıymazarslan","poet_slug":"haci-yusuf-kiymazarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yokluk-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Falancanın Çocuğu', 'falancanin-cocugu-haci-yusuf-kiymazarslan-uqfsp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen falancanın çocuğu oynayan

Bisikletin, oyuncakların güzel

Ellerin tertemiz sabun kokar

İmrenirim.

Kıskanç mıyım? ne gezer

Benim olmadı hiçbir şeyim 

Elimi kanatarak at yapardım söğütten

Ata binerdim.

Ben çocuk saati dinelemeden uyurdum

Hikaye anlatırdı anam geceleri...

Keloğlan padişahın küçük kızını alırdı

Avunurdum.

Ama şimdi anlıyorum ki...

Padişahın küçük kızını ancak sen alabilirsin.', 'Sen falancanın çocuğu oynayan Bisikletin, oyuncakların güzel Ellerin tertemiz sabun kokar İmrenirim. Kıskanç mıyım? ne gezer Benim olmadı hi...', ARRAY['Türk Edebiyatı','Şiir','Hacı Yusuf Kıymazarslan']::text[], 8.5, '{"poet":"Hacı Yusuf Kıymazarslan","poet_slug":"haci-yusuf-kiymazarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/falancanin-cocugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soğan ile Ekmek', 'sogan-ile-ekmek-haci-yusuf-kiymazarslan-s42zy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen bilmezsin Ali çavuşu azizim

Ne adamdı be birader ne adam

Dünyayı yüklesen ıh demezdi bir kere

Gül gibi geçinirdi.

Hamallık vergiydi ona sanki

Anasından hamal doğmuş sanırdın

Hele yiyişi vardı soğan ile ekmeği

Vallahi iştahlanırdın.

Ne var ki ince hastalık

Bırakmadı yakasını herifin

Allah''dan geldi neylersin

Çoluk çocuğu perişan kaldı.

Bir öğle vakti dev gibi adam

Güm diye gitti aramızdan...

Sen bilmezsin Ali çavuşu azizim

Soğan ile ekmeği de bilmezsin.

16.8.1965', 'Sen bilmezsin Ali çavuşu azizim Ne adamdı be birader ne adam Dünyayı yüklesen ıh demezdi bir kere Gül gibi geçinirdi. Hamallık vergiydi ona ...', ARRAY['Türk Edebiyatı','Şiir','Hacı Yusuf Kıymazarslan']::text[], 8.5, '{"poet":"Hacı Yusuf Kıymazarslan","poet_slug":"haci-yusuf-kiymazarslan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sogan-ile-ekmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birtanem', 'birtanem-ali-fikri-karadeniz-oczl9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni bir sır gibi sakladım yüreğimde, 

Kimseler eremez, bulamazlar Birtanem, 

Bir nefes ötemde, koca bir özlem bende, 

Çırpınışlar içimde, sevgim sana Birtanem! ! ! 

Bilirmisin; düşüncelerin içierisinde bir gerçek olduğunu, 

Seni hissedebilmek için sebepsiz suskunluğumu, 

Bilirmisin bir gülüşünde bende ki mutluluğu, 

Haykırışlar içinde sevgim sana Birtanem! ! ! 

Uzaklarda olsanda Seni anmak ne güzel, 

Böyle dize dize Seni yazmak ne güzel, 

Her umudun ardında Seni bulmak ne güzel, 

Sonsuzluklar içinde sevgim sana Birtanem! ! ! 

                                               Ali Fikri Karadeniz', 'Seni bir sır gibi sakladım yüreğimde,  Kimseler eremez, bulamazlar Birtanem,  Bir nefes ötemde, koca bir özlem bende,  Çırpınışlar içimde, s...', ARRAY['Türk Edebiyatı','Şiir','Ali Fikri Karadeniz']::text[], 8.5, '{"poet":"Ali Fikri Karadeniz","poet_slug":"ali-fikri-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/birtanem-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anılara Dair', 'anilara-dair-huseyin-i-lhan-lrliz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Göz bebeklerimiz kavuştuğunda 

Unuturduk yanıp sönen dünyayı 

Yalnız ikimiz kalırdık hayatta 

Anlatırdık mecnunu ve Leyla''yı 

Ne vakit evlerde ışıklar yansa 

Ayrılma vaktiydi, annen beklerdi 

Gecelerde hasret...Geçmeyen zaman 

Duvar saatimiz sanki teklerdi 

Menekşe parkında okul çıkışı 

Kalplerimiz daha hızlı çarpardı 

Nasıl da unuttuk o ilk bakışı 

Menekşe parkında dün anladım ki 

Yıllar çalmış sevgimizi bir tanem 

Eski masamızda bir ağladım ki 

H.HÜSEYİN İLHAN', 'Göz bebeklerimiz kavuştuğunda  Unuturduk yanıp sönen dünyayı  Yalnız ikimiz kalırdık hayatta  Anlatırdık mecnunu ve Leyla''yı  Ne vakit evler...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin İlhan']::text[], 8.5, '{"poet":"Hüseyin İlhan","poet_slug":"huseyin-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/anilara-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cenazene Gelemedim! Yetişemezdim; Kusura Bakma!', 'cenazene-gelemedim-yetisemezdim-kusura-bakma-turgay-kaygi-zdaz6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '‘melih cevdet dostlarına kavuşmuş dün! ’



bu sabah duydum 

vefat ettiğini

dün sabah üstüme çöken sisten

belliydi zaten

olacağı bir şeylerin

oldu işte; 

dün varsın

bugün yoksun

tevekkeli değil; 

hani 

ağlamak gelir içinden de

bir müddet tutarsın kendini, 

kasırgalar esedururken ruhunda

sonra

bir anda 

biriktirdiğin ne var ne yoksa

irili ufaklı, 

sen istemeden boşalıverir 

gözlerinden; rahatlarsın

onun gibi, 

bugün sanki

biraz ağlayıp da açılmış 

güzel fakat dertli bir kız çocuğuna benziyor 

hava

inanamadım ilk önce

ama

gazetede de görünce

“Türk edebiyatı bir devi yitirdi”

başlıklı 

6 santime 11 santim ebatında

vefat haberini, 

birden

üç gündür

yaklaşan kurdun kokusunu almış

hırçın bir at gibi

huysuzlanarak

ve dört can düşmanımmış gibi

bakarak

etrafımı saran

dört duvara; 

10 metrekare odamda

neden hiçbir şey düşünemeden 

saatlerce yürüdüğümü anladım

söyleme fırsatı da bulamadım sana; 

oğlum olursa söz! 

melih koyacağım adını, 

bana senden geçen 

ismi koyulmamış şeyler adına, 

ve her şeye rağmen

şu an her neredeysen

bende bir gün

oraya geleceğim; 

biliyorum! 

ve her ne kadar 

mahzun olsam da bir parça

şimdi biraz gülümseyebiliyorum; 

hepsi bu! 

dostum! 

bahçedeki adını bilmediğim 

bir ağaca takıldı da gözüm 

az önce pencereden, 

aklıma geldi; 

acaba

ağaçlar 

tüm yaprakları döküldüğü zaman mı

anlarlar

kışın geldiğini? 



(inegöl,29.11.2002)', '‘melih cevdet dostlarına kavuşmuş dün! ’ bu sabah duydum  vefat ettiğini dün sabah üstüme çöken sisten belliydi zaten olacağı bir şeylerin o...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kaygı']::text[], 8.5, '{"poet":"Turgay Kaygı","poet_slug":"turgay-kaygi","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/cenazene-gelemedim-yetisemezdim-kusura-bakma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevince', 'sevince-ugur-ozudogru-xuy4v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ağaçlar bir başka bu bahar

rüzgar dalların ucunu okşuyor

insan sevince böyle mi oluyor

farklı bir hava sanki soluduğum

eminim sizin ordan geliyor

mavi bir martının kanadında', 'ağaçlar bir başka bu bahar rüzgar dalların ucunu okşuyor insan sevince böyle mi oluyor farklı bir hava sanki soluduğum eminim sizin ordan ge...', ARRAY['Türk Edebiyatı','Şiir','Uğur Özüdoğru']::text[], 8.5, '{"poet":"Uğur Özüdoğru","poet_slug":"ugur-ozudogru","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sevince-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annemi özledim', 'annemi-ozledim-salih-ozalasan-oksf1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bugün yine hasretin düştü yüreğime

Dikildi güzel hayalin bakıyor gözlerime

Rüya desem değil, dalmışım farklı bir aleme

İki damla gözyaşı aktı gözlerimden anne

Nasıl özlemişim, muhtaçmışım tatlı sesine

Kucağım açık kaldı, sarılamadım hayaline

Seni sevmek her zaman en güzel yüreğimde

Özleminse kor alev yığını inanki anne

Özlemişim başımı dizine yaslamayı

Azarlayınca rol yapıp ağlamayı

Şimdi senin gözlerinle görüyorum Dünya''yı

Meğer bazen ben seni ne kadar üzmüşüm anne

Ben sevgiyi senden öğrenmişim

Ah bilseydim sensiz özlem çekermişim

Susuz kalmış çiçek gibi boyun bükermişim

Ayrılırmıydım dizinin dibinden anne

Biliyorum sende özledin çok ama çok beni

Hasretim yakıyor mimberim kutsal sineni

Bir zamanlar göğsünde uyuturken beni

Şimdi başım öksüz, sinen özlem doldu anne

Selâm olsun benden size

Bu ayrılıklar farz olmuş herkese

Kızınızı telli duvaklı gelin etmek gurur size

Şimdi bir er girsede gönlüme

Senin sevgin, senin hasretin, taptaze duruyor anne

Kızınız sizi hep özledi, 

Bazı geceler ağladı hasretinizle

Belki hala büyümedim 

Bir küçük kızım gözünüzde

Yüreğimde hasretin büyüdü dağlar gibi anne

Y, Tar.29-11-2002 Saat 12.50', 'Bugün yine hasretin düştü yüreğime Dikildi güzel hayalin bakıyor gözlerime Rüya desem değil, dalmışım farklı bir aleme İki damla gözyaşı akt...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/annemi-ozledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askerime', 'askerime-salih-ozalasan-fhilr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dayanmak ne zormuş sevdiğim hasretine

Uzakta olmak alev bakışlım gözlerine

Alışmıştı kulağım aşk fısıldayan sözlerine

Vatan borcu olmasa kan dolacak yüreğime

Sana hasret kalmak ölümden beter

Kalmadı gücüm, dizlerim titrer

Yüreğim fırtınalarda bir liman bekler

Kaptansız bir gemiyim senin hasretinle

Diyorlar sayılı gün çabuk geçer

Yiğit olan bu borcu mutlak öder

Tanrım asker yolu gözleyene sabır ver

Sabır taşına döndü yüreğim hasretinle

Sararmış yazdığın mektuplar elimde

Satır satır, nokta nokta ezberimde

Seninde özlem gizlenmiş sözlerinde

Sevdamı dağlara sor, yıkıldı hasretinle

Belki sende hayal kurarsın

Yedi dokuz gece nöbetinde

Ben öylesine özlem doluyumki

Her gece nöbetteyim yüreğimde hasretinle

Her güne bir yıldız seçtim gökyüzünde

Yeni bir samanyolu göreceksin döndüğünde

Akşamın habercisi çoban yıldızını gördüğünde

Sor ona bak ne haldeyim hasretinle

Y.Tar.29-11-2002 Saat 10.20', 'Dayanmak ne zormuş sevdiğim hasretine Uzakta olmak alev bakışlım gözlerine Alışmıştı kulağım aşk fısıldayan sözlerine Vatan borcu olmasa kan...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/askerime-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Murad', 'murad-mahmut-okur-rw6t9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her nefes içtiğim bu mahzun aşkın

Derdinden süzdüğüm feryadım ol gel! 

Bir hasret damlası, sonsuza kaçkın

Sırrıma ermeye üstadım ol gel! 

Sen garip gönlümü derdinle dola

Derdimsin, derdimsen kime ne ola? 

Bir ben değil sana alem müptela

Her dem coşmalarda serhadım ol gel! 

Ola ki anmazsam ismini bir an

Kopacak kıyamet, duracak devran

Özümden tane tane saçılan

Duama altun taç, hep yadım ol gel! 

Sözlerim var sözler sığmıyor dile, 

Çilem var dilerim dolmasın çile! 

Kalbim ki göğsümden ayrılsa bile

Alemde biricik muradım ol gel!', 'Her nefes içtiğim bu mahzun aşkın Derdinden süzdüğüm feryadım ol gel!  Bir hasret damlası, sonsuza kaçkın Sırrıma ermeye üstadım ol gel!  Se...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Okur']::text[], 8.5, '{"poet":"Mahmut Okur","poet_slug":"mahmut-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/murad-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüyalarım Yanıyor', 'ruyalarim-yaniyor-falka-sarp-dx46u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Onu sevmiyorum

Nokta kadar, virgül kadar, zerre kadar

Nerden çıkardınız sevdiğimi

Tırnağımın ucu kadar onu seviyorsam

İki gözüm önüme aksın

İlahi kuşlar niye gülüştünüz

Yalancı mıyım ben

Hiç yalan söylediğimi gördünüz mü

Kırıntılarla doyar mıyım

Bakın gözlerime, var mı mavilerimde izi

Ellerimi tutun, geçen yaz gibi mi

Damarlarımda ki kan çoktandır durgun akıyor

Nabzımda ki vuruşlarda delicelik kalmadı

Çiçeklenmiyorum

Ayazlanmıyorum adını duyunca

Falan filanca biri gibi

Yabancı artık bana

Onu sevmiyorum

Vallahi sevmiyorum

Ateş sevilir mi, kurşun sevilir mi

Gözlerini kapatmış güneş

Yıldızlarını yitirmiş siyah

Binlerce ah sevilir mi

Sessiz çığlığın kırbaçlı sesinin arasından

Kara bir trenin ışık hızıyla geçtim

Aşkıma dair, sevdama dair, ona dair

Ne varsa yüreğimin derinlerinde

Çivi söker gibi söktüm

Cımbız cımbız kopardım hücrelerimden onu

Of demeden

Onu sevmiyorum

Hiç sevmemiş gibi sevmiyorum

Aldım kendimi kalabalığından

Çekip gittim yalnızlığıma

Onu severken, onu özlerken rüyalarım yanıyordu

Alevler yastığımı, yorganımı sarıyordu

Küllendi saçlarım

Küllendi uyanır uyanık

Onu sevmiyorum

Çiçekler tanığım, gökyüzü tanığım, aynalar tanığım

Hiç birine onu yeniden sevmemek için

Bir kez bile bakmıyorum

Sevdaya alışık güllerim bu yüzden solmuş olmalı

Umursamıyorum

Yine de kapar kapamaz gözlerimi

Rüyalarım yanıyor', 'Onu sevmiyorum Nokta kadar, virgül kadar, zerre kadar Nerden çıkardınız sevdiğimi Tırnağımın ucu kadar onu seviyorsam İki gözüm önüme aksın ...', ARRAY['Türk Edebiyatı','Şiir','Falka Sarp']::text[], 8.5, '{"poet":"Falka Sarp","poet_slug":"falka-sarp","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/ruyalarim-yaniyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyada Olmaz', 'dunyada-olmaz-sibel-karabas-18pv3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dilimi yakarken hasret sözcüğü

Ayrılsak diyorsan, dünyada olmaz

Ele sebil edip aşk pınarını

Dağıtsak diyorsan, dünyada olmaz

Seninle tatmışken aşkı, neşeyi

Var mı bir kalemde silmek her şeyi

Hayale döndürüp bütün gerçeği

Unutsak diyorsan, dünyada olmaz

Aşkın meleğini kurnaz sanırken

Sen vefasız çıktın, eli kınarken

Gönlümüz sönmeyen aşkla yanarken

Ayrılsak diyorsan, dünyada olmaz

Zamanla silinmez bu aşkın izi

Unutmak olur mu birbirimizi

Başka sevdalarla kalplerimizi

Avutsak diyorsan, dünyada olmaz', 'Dilimi yakarken hasret sözcüğü Ayrılsak diyorsan, dünyada olmaz Ele sebil edip aşk pınarını Dağıtsak diyorsan, dünyada olmaz Seninle tatmışk...', ARRAY['Türk Edebiyatı','Şiir','Sibel Karabaş']::text[], 8.5, '{"poet":"Sibel Karabaş","poet_slug":"sibel-karabas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dunyada-olmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haydi Uyan', 'haydi-uyan-niyazi-yildirim-gencosmanoglu-9utoo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Er meydanlarından çekilir oldum

Çorak iklimlere ekilir oldum

Eğilmek bilmezdim bükülür oldum

Sürer mi bu gaflet daha kaç sene

Uyanıp kendine dönmeyi dene

Acımda ne varsa kurudan, yaştan

Al Dede Korkut''tan Hacı Bektaş''tan

Malazgirt, Tuna, doğ yeni baştan

Dilerim Allah''tan bu devran döne

Uyan durma uyan, uyumak nene

Boşaldın boşaldın dolabilmedin

Gidişin o gidiş gelebilmedin

Döktüğün kanları alabilmedin

Şah damarlarına yapışan kene

Sömürür mü seni daha kaç sene

Seni aldatmasın batı denilen

Onun mayasıdır katı denilen

Onun iç yüzüdür kötü denilen

Budur öz suyunu sömüren kene

Sen uyan, onu da uyandır gene

Sen Oğuz Ata''nın has milletisen

Sen Son Peygamberin has ümmetisen

O seni boğmadan boğ ümmetisen

Uyan durma uyan, uyumak nene

Kalk, doğrul yerinden, yürü geç öne

Medet ummaya gör kızıl surattan

Seni mahrum koyar aşktan, murattan

Çağla Sakarya''dan kükre Fırat''tan

Kara kızıl, sarı sür, topla yine

Bunlardır özünü sömüren kene

Düşün, kaç parçaya bölmüşler seni

Sonsuz bir sahraya salmışlar seni

Kanadını kırıp yolmuşlar seni

Kalk, doğrul yerinden, yürü geç öne

Uyanıp da kendine gelmeyi dene

Destanlar yazılır şanına layık

Yine de erişmez ününe layık

Olusan soyuna, dinine layık

Geçer bu gafletin, sürmez çok sene

Uyan durma uyan, uyumak nene', 'Er meydanlarından çekilir oldum Çorak iklimlere ekilir oldum Eğilmek bilmezdim bükülür oldum Sürer mi bu gaflet daha kaç sene Uyanıp kendine...', ARRAY['Türk Edebiyatı','Şiir','Niyazi Yıldırım Gençosmanoğlu']::text[], 8.5, '{"poet":"Niyazi Yıldırım Gençosmanoğlu","poet_slug":"niyazi-yildirim-gencosmanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/haydi-uyan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizi Kimse Ayıramaz', 'bizi-kimse-ayiramaz-abdulkadir-nurlu-5mwio', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zincirleri kırıp geldik

Engelleri aşıp geldik

Canı cana katıp sevdik

Bir can iki sayılamaz

Bizi kimse ayıramaz

Sevda dersen sevda bizde

Yürek dersen yürek bizde

Beraberiz son nefeste

Bir can iki sayılamaz

Bizi kimse ayıramaz

Yüreğimiz, dilimiz bir

Hislerimiz, kalbimiz bir

Hissederiz, görürüz biz

Bir can iki sayılamaz

Bizi kimse ayıramaz', 'Zincirleri kırıp geldik Engelleri aşıp geldik Canı cana katıp sevdik Bir can iki sayılamaz Bizi kimse ayıramaz Sevda dersen sevda bizde Yüre...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Nurlu']::text[], 8.5, '{"poet":"Abdulkadir Nurlu","poet_slug":"abdulkadir-nurlu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bizi-kimse-ayiramaz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen mutlu ol', 'sen-mutlu-ol-salih-ozalasan-nh2n0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Söyle mutlumusun şimdi

Ellerimle öldürdüm hem seni hemde beni

Sana adamıştım ben bu yüreği

Silip attım bir kalemde şimdi herşeyi

Mutlu ol mutluluk sana en güzeli

Bir gün bir yerde hatırlarsan beni

Deme sakın vardı sadece kalemi

O kalemin sendin anlamadın mürekkebi

Bir gün belki yine yazacak

O kalemin son mürekkebi

Bilesin hep sevgi saygı

Özlemle anacak Salih seni

Gönül dostu yapmıştı

Sadece ama sadece seni

Bir daha gönül dostu olmayacak

Kimse alamayacak asla yerini

Y.Tar.29-11-2002 Saat 21.36', 'Söyle mutlumusun şimdi Ellerimle öldürdüm hem seni hemde beni Sana adamıştım ben bu yüreği Silip attım bir kalemde şimdi herşeyi Mutlu ol mu...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-mutlu-ol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elma Kabuğu', 'elma-kabugu-ilgin-polat-nnsbp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'şiir defterimin arasındaki: 

elma kabuğu gibi; 

ya hep defterimde kal, 

ya da benimle.

                        2002', 'şiir defterimin arasındaki:  elma kabuğu gibi;  ya hep defterimde kal,  ya da benimle.                         2002...', ARRAY['Türk Edebiyatı','Şiir','Ilgın Polat']::text[], 8.5, '{"poet":"Ilgın Polat","poet_slug":"ilgin-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/elma-kabugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Yağmurları', 'sevda-yagmurlari-sinan-arslan-92igx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yağıyor gene sevda yağmurları, 

Bir tek bana yağıyor

Gene korunmak için bir saçak altı arıyorum; 

Biliyorum; 

Ne kadar korunmak için uğraşsamda, 

Bir tarafım ıslanacak, sırılsıklam olacak.

VE hiçbir zaman kurumadığı gibi, yine kurumayacak.

Islanan tarafda kalbim olacak.

Sonra; 

Kuruması için ascağım kalbimi bir çamaşır ipine

Kan kırmızı rengi solup beyaza çalacak.

Ama ilk günkü gibi ıslak olacak, 

Çünkü sevda yağmurları, 

Yağdı, yağıyor yağacak.

                                      08.02.2002 avcılar', 'Yağıyor gene sevda yağmurları,  Bir tek bana yağıyor Gene korunmak için bir saçak altı arıyorum;  Biliyorum;  Ne kadar korunmak için uğraşsa...', ARRAY['Türk Edebiyatı','Şiir','Sinan Arslan']::text[], 8.5, '{"poet":"Sinan Arslan","poet_slug":"sinan-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevda-yagmurlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melih Cevdet Anday''a', 'melih-cevdet-anday-a-ahmet-kurt-1rrzl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaç ulu çınar devrildi, 

Yaşlı dünyada, 

Kim bilir ne kadar, 

Sırada bekleyen. 

Mısralara, 

Gün hasret örmekte. 

Hasret doğmakta sabahlar, 

Düşünce kadar.

Dünya

Bir ustayı ağırlamada, 

Son yolculuk 

Ve son bir durakta, 

Birkaç yaşlı göz, 

Sessiz ağlamakta, 

Yüreğimde binlerce

Melih Cevdet 

Doğmakta.

Karanfil kokuları arasında.

Titrek dudaklar, 

Bükülmüş boyunlarda.

Ey koca çınar, 

Serinleyecek gölgen, 

Serinletecek satırların, 

Unutmayacak canların var.

Arkanızdan yürekler dolusu, 

Dualar ve fatihalar.', 'Kaç ulu çınar devrildi,  Yaşlı dünyada,  Kim bilir ne kadar,  Sırada bekleyen.  Mısralara,  Gün hasret örmekte.  Hasret doğmakta sabahlar,  ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/melih-cevdet-anday-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Sabah, Yanılmak! ..', 'her-sabah-yanilmak-attila-i-lhan-o87i3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sabah olmak her gece kolay mı sanırsınız

bulutları dağıtıp güneş olarak doğmak

denizle gök arasında çiy yorgunu şehre

kurşun kubbeleri buğulu minareleri ıslak

soğuk bir trenden inmiştiniz / yalnızdınız

bilmem kaçıncı defadır / yine yanılmıştınız

hiç uyumamıştınız / gözleriniz yanıyordu

yolculuk sanki bitmemişti / birdenbire

kendinizi vagonda unuttuğunuzu sandınız

sanki katar soluk soluğa tırmanıyordu

dumanlı rampaları / bir kılıç gibi çıplak

tiz çığlıklarıyla aydınlığı doğrayarak

bilmem kaçıncı defadır / yine yanıldınız

jilet mavisi bir kadın elinde purosu

değdiği yer açılıyor çok fena keskin

kim olduğunu bilen yok / işin doğrusu

yüzünü kaybetmiş aynalarda arıyordu

amerikan bara tünemiş sek vodka içiyor

geçmişinden rusça bir şarkı arayarak

sarhoş olmamak en büyük korkusu

bilmem kaçıncı defadır / yine yanıldınız

elbet en kötüsü sokaklarda tutuklanmak

hani bir kere iki yanınızda iki sivil polis

beyoğlu''ndan çekilip nasıl koparılmıştınız

nabız gibi vuran o kötü ve karanlık his

yakanızı hala bırakmadı asla bırakmayacak

bilmem kaçıncı defadır / yine yanıldınız', 'sabah olmak her gece kolay mı sanırsınız bulutları dağıtıp güneş olarak doğmak denizle gök arasında çiy yorgunu şehre kurşun kubbeleri buğul...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/her-sabah-yanilmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neydi O Bir Zamanlar', 'neydi-o-bir-zamanlar-attila-i-lhan-xmau6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'istanbul ve sen / neydi o bir zamanlar

sanki gençliğime doğru yaşlanıyordum

çengelköy''de yaz unutulmaz erguvanlar

hangi yanıma dönsem seni bulurdum

içimdeki lambanın kırıldığı anlar

istanbul ve sen / sırılsıklam yaşananlar

yanardöner bir ayna yeniden ruhum

çengelköy''de yaz unutulmaz erguvanlar

gözlerinin sisinde sevdalı bir yolcuyum

hayal meyal gemiler dumanlı ilkbahar

istanbul ve sen / ikinizden kalanlar

tekrar tekrar ısrarla yaşayıp durduğum

çengelköy''de yaz unutulmaz erguvanlar

rüya mıdır gerçek mi kendi kendime sorduğum

istanbul ve sen / neydi o bir zamanlar', 'istanbul ve sen / neydi o bir zamanlar sanki gençliğime doğru yaşlanıyordum çengelköy''de yaz unutulmaz erguvanlar hangi yanıma dönsem seni b...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/neydi-o-bir-zamanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Süheyla Değildi Adın', 'suheyla-degildi-adin-attila-i-lhan-1gu8p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hangi bulutlara niçin sarındın

gözlerindeki mavi kimin gökyüzü

	süheyla değildi başkaydı adın

gülüşlerin donuk neş''e öksüzü

o erken sonbahar görüntüsü

inceden inceye boyanmaz mıydın

kirpiklerinin lacivert örtüsü

	süheyla değildi başkaydı adın

ellerin buz gibi ağzının büzgüsü

kaç yalnızlığın gizli üzüntüsü

ne yapsan ne etsen anlaşılmadın

belki sebep kendini aşmak dürtüsü

	süheyla değildi başkaydı adın

nabızlarında pişmanlığın gürültüsü

gülümsemen soğumuş çiçek ölüsü', 'hangi bulutlara niçin sarındın gözlerindeki mavi kimin gökyüzü 	süheyla değildi başkaydı adın gülüşlerin donuk neş''e öksüzü o erken sonbahar...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/suheyla-degildi-adin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'An Düşmesi', 'an-dusmesi-kucuk-i-skender-418q3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'büyük yavanlığın zaman

kazandığı susuz gezegenlerin

arazisi! tarifsiz lanetlenişlerin

kuvvetli masumiyetiyle alay

eden merhale! talan

edilmiş yalnızlıkların tersyüz

çevrilerek bekletilmesiyle anlamlanmış

sahte mukaddes, sahte susayış, sahte

sabrediş izi! 

toprak ve tüllerin kralı! zehrin bilgisi! 

sen rüzgara uzat kalbinin mimarını ve

çöz suyu deryadan, kat mermere, 

acıt yeryüzünü!', 'büyük yavanlığın zaman kazandığı susuz gezegenlerin arazisi! tarifsiz lanetlenişlerin kuvvetli masumiyetiyle alay eden merhale! talan edilmi...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/an-dusmesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşiret', 'asiret-kucuk-i-skender-ts1dd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kurbanlar geçsin uyuşmuş girdapların zorundan

köpekler göğe bakarken dellensin

tipiye tutunan gecenin, kopup dağılsın siyah parmakları

Sofradan kalkana dek vurulmasın sakın ha düşman

son lokmayı yutana dek suyuna göz dikilmesin ve

en güzel aşk masalları anlatılsın kalbe bağladığı atına

mühim misafirlere ayrılan battaniye serilsin, cesedinin üstüne', 'Kurbanlar geçsin uyuşmuş girdapların zorundan köpekler göğe bakarken dellensin tipiye tutunan gecenin, kopup dağılsın siyah parmakları Sofra...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/asiret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Dair', 'aska-dair-kucuk-i-skender-n1yjg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'aşk, biraz aşağılanmıştır

kadın terzilerin neresinden baksam

irtifa kaybeder hücum ve şiddet

geri sayım: dört-üç-iki-bir-sıfır

patlar yükselir gider ağzım! 

ağzım bana lazım

diye bağırır parmak çocuk

çocuk parklarında salıncaklar hızlanır

kaydıraklar ağlar

bir kadeh rakı dökülür üstüne ömrümün

alkolik annem geceden özür diler

neden sevgi

	onca derbeder ve serseri

bir şık bıçak darbesiyle

yarar karanlığı

yürür giderim orda ileri geri

orda aşk

küçülür.. küçülür..

küçülür biter en güçlü sesiyle!', 'aşk, biraz aşağılanmıştır kadın terzilerin neresinden baksam irtifa kaybeder hücum ve şiddet geri sayım: dört-üç-iki-bir-sıfır patlar yüksel...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/aska-dair-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş Böcekleri', 'ates-bocekleri-kucuk-i-skender-8xmsl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yarayı okşadıkça dökülüyor kabuklar) ... (diyemezsin

oysa belirsizliktir

ormanlarına pusu kurdurtan hayvanları. Kim bilir

hangi çağın karanlığında iki ateş böceği

gibi iki omzuna konmuştuk sevgili siyahını öpecek

ve ölecek olan, kanını

terine nişanlanmış o yaralı delikanlının.

hayır, bugün inanmıyorum ben gitgide büyüyen ellerine

ellerin büyüdüğü şehirlerde

gözlerin ettiği sözleri kesme cüreti gösterilir

ve o kesilen sözlerin üstüne

oğlanlardan yüzülmüş ipek tenden tüller serilir

		gümüş yünden kuşlar örtülür

gideceksin. belli. git o halde seni çağıran beldeye

benim ilmim sistir de! 

benim ilmim suçtur de! 

ve unut sonra o iki ateş böceğini

kaldır başını ardından

gökyüzünde tek bir ateş böceğinin

bölünüp

kendisinden iki ateş böceği oluşunu

şaşkın bakışlarla, utanç içinde gözle! 

benim sisim sensin de! 

benim suçum sensin de! 

belli belirsiz bir akyanus beni üstlensin

yarayı okşadıkça dökülen kabuklarla dolu sesinde!', 'yarayı okşadıkça dökülüyor kabuklar) ... (diyemezsin oysa belirsizliktir ormanlarına pusu kurdurtan hayvanları. Kim bilir hangi çağın karanl...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ates-bocekleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Aralama Etüdleri I,', 'ay-aralama-etudleri-i-kucuk-i-skender-dki3u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sonra aniden geyşa! Bilinçsizce, 

bir anlamı olmalıymış gibi bunun

önce biraz tedirginlik ve öfke, 

ardından çokca telaş ve savurganlık: Tahmini

gezegenin son astronotu -Niye Kimse

Fizikten Sözetmiyor Bu Evde -Ve Ben Niye

yukardaki, aşağıdaki komşunun da çocuğuyum

annem kilitlerken cinimi kilere; Daniel Hatırladım

şimdi, bazı mayıs aylarında ellerim olmazdı Ve Ben

çoğu kez Janis Joplin ve Jim Morrison Baladları

adına şarkılar da söylenmiş sonbaharın

sonra aniden çıkagelmiş unutulmuş bir kuzeniydim; 

O Adam Terasta Ne Yapacaktı

Kadını Gerçekten Seviyor muydu

Kadın Bebek Beklediğini Neden Söylemiyordu

Peki, Adam Bazı El Yazmalarını Nereye Saklamıştı

geyşa! beni işitiyor musun, geyşa! 

bu buzlu cam, bu buzlu cam diyorum sana, 

bu buzlu cam hangi filmimin jeneriği.. Ah tabii, 

kalbim, bir içsavaşta kaybettiğim fosfor at!', 'Sonra aniden geyşa! Bilinçsizce,  bir anlamı olmalıymış gibi bunun önce biraz tedirginlik ve öfke,  ardından çokca telaş ve savurganlık: Tah...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ay-aralama-etudleri-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Aralama Etüdleri II,', 'ay-aralama-etudleri-ii-kucuk-i-skender-1v0u8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Melek hastalığı: bir dokunun titiz Aranışı

müfettiş bir cin gibi bakarak tutunur gözü

akla sonradan gelecek olan sırtını duvara

vermiş gülüş, dişler arasında sıkıntılı dol

aşan tırnak, üstünde Manhattan ve beni sev

en tilki, cevaplamayacağım mektuplarım ve

r; bir merdiven var sonra çıkıp da inmeyec

eğim; infilak etmiş bir yaradılışla yakl

aşıyorum gecenin gecenin kanlısına elim

de yalnız

ca bir

fırıldak ve şehir haritası bir gül oros

pusuyum bir gül ib

nesiyim bir gül bana söyle bir

tek ben duy

ayım neredeyim ne yapıyorum ve sen neden nered

esin, ama

ay aralama etüdlerin

desin	      ay      de

orada	        desin', 'Melek hastalığı: bir dokunun titiz Aranışı müfettiş bir cin gibi bakarak tutunur gözü akla sonradan gelecek olan sırtını duvara vermiş gülüş...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ay-aralama-etudleri-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayakhavlusu', 'ayakhavlusu-kucuk-i-skender-psb03', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nefesi kokan bir denizatı mıyım ben

ruhumun terkisinde harita fragmanları

ve suratımda patlamış frambuazlı pasta

İle nereye kadar giderim böyle mağrur

böyle boydan boya aşağılanmış

cilası çizilmiş ama adamakıllı sakallı

ne tencereyim ne de bir kapak uğruna yuvarlanıyorum

Nefesi kokan bir denizatı mıyım ben

ya da bir komedi filminin en baba esprisi

finale doğru seyirciyi elleriyle boğan

Çok önceden alınmış bir karar gibi yaşıyorum

bir adım eksik atsam

hatıralarım, acılarım ayaklanıyor

ne dağı tanırım ne de içimdeki aşk tavşan', 'Nefesi kokan bir denizatı mıyım ben ruhumun terkisinde harita fragmanları ve suratımda patlamış frambuazlı pasta İle nereye kadar giderim bö...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ayakhavlusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baç', 'bac-kucuk-i-skender-9nrcj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Esmer koy kızının adını hep, 

ölümden toplanmış haraçtır ruh

dokunurken birbirine kıyasıya iki ten

Kumral koy oğlunun adını hep, 

cinayetlerden arttırılmış suçtur his

karışırken birbirine önemli iki erkek bülten

son kuruşuna kadar soy aşkı, henüz vakit varken', 'Esmer koy kızının adını hep,  ölümden toplanmış haraçtır ruh dokunurken birbirine kıyasıya iki ten Kumral koy oğlunun adını hep,  cinayetler...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bac-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Barbiebebek', 'barbiebebek-kucuk-i-skender-4cw8b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dikkatimden kaçmış aşk, 

nüfus cüzdanımda

küçük bir ayna parçası yapışık vesikalık fotoğraf yerine

Çocuk omuzlarında kayısı oyunları korosu ve

o on yedi yaşına sığdırmaya çalıştığın masum erkek

yağmursu gülümsemen belki de her yazılı casusta tekrar ettiğim

peygamber öldü! çünkü ben seni hiç çıplak görmedim', 'Dikkatimden kaçmış aşk,  nüfus cüzdanımda küçük bir ayna parçası yapışık vesikalık fotoğraf yerine Çocuk omuzlarında kayısı oyunları korosu ...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/barbiebebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz', 'beyaz-kucuk-i-skender-4btu8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir orman yangınında nasıl çaresizce

yuvasında ölümü bekleyen

çocukkarınca

Bir usta avcı gibi duvarıma astım

vurduğum bütün jilet darbelerini

bileklerime pervasızca

çünkü kan kalıyor turuncudan güneş çıkınca', 'Bir orman yangınında nasıl çaresizce yuvasında ölümü bekleyen çocukkarınca Bir usta avcı gibi duvarıma astım vurduğum bütün jilet darbelerin...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/beyaz-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pusu Metinleri', 'pusu-metinleri-kucuk-i-skender-gs0r7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'I.

savurarak

kirpikleri filtresi ıslatılmış ve dişlenmiş

bir kar tortusunun yerleştiği geceden, 

dışarı bir balkon gibi uzanan iri gözleriyle

yeni ölmüş bir timsahın

henüz buharlaşmamış şaşkınlığına bitişik

bir ruha teslim ettik elbirliğiyle

siyah kuzgunları.

gagalarımızda fosilleşmiş baldır aryaları.

yurdumun dışı: çelik gemici hikayeleri.

sertleşirken gözkapaklarına sürülen

rujlar ve ojeler bir mezara süzülen tenleri

ensekökünden bele eğimli manastırdaki o son

plastik peygamberin o son kanlı miğferi.

sanki

edilememiş, edilemeyen sözlere

tek bacaklı bir şahin indirir gibi

belirsiz bir kan çantası sarkıtıyordu çizik öpüşlere

diklemesine saplanan tozlusoğuk mavi.

vakitsiz ve feci

bir feci vakte bağımlı mülteci

gibi kendi pusumuzda cüzzamlıydık.

ben

beni delice seven bir hüzünle büyüdüm.

ben

beni delice çeken bir kainatla büyülüydüm.

her gezegende benim de emeğim var.

işte! 

bir avize düştü! 

bir avize düştü gökyüzünden yeryüzüne! 

kırık! 

vah kırık çocuk! 

kırık ve vah titrek çocuk! 

senin dudaklarınla ıslanıp korkunç ışıltılarıyla aktılar

törenlerle, törelerle, uzak tuzaklarla yıldızlar! 

her gezegende senin de emeğin var! 

kanatlarımızda tuza yatırılmış topuk iksirleri.

bir sokak köpeğine atılan zehirli et gibi

atarken birbirimize koyaklarda vücutlarımızı

inan tek ümidim yoktu, ümide ihtiyacımız yoktu

belki biraz şevkat, belki biraz umarsız sızı! 

tehlikeliydi

dokunuşlarımız tehlikeli ve lekeliydi! 

bir şarapnel parçası düşercesine şarap taslarımıza

dışımızdaki hükmün testeresi deydi kafataslarımıza! 

beni bir kaşın kaatil yapacakken öbürküsü teskin etti! 

beni bir kaşın vurdu, öbürküsü teşhir etti! 

nasıl duygusalım değil mi sevgilim

yoruyor seni bu yorgunluk ve kimi basit mısralar

ama bu uzay macerasında

senin dudaklarınla ıslanıp

korkunç ışıltılarıyla kaydılar

törenlerle

törelerle

uzak tuzaklarla yıldızlar! 

gelelim şiirin son dörtlüğüne: 

hazır mısın: 

yüksek sesle okuyarak geçir günlüğüne: 

Bir Erkeğin Bir Erkeğe Teğet Kaldığı Çemberde

Suyun yüzü Kızarır, Suyun Kalbi Sıkışır

Bu Aşkın En Büyüğü Tanrı & İsa Arasındaysa Eğer

Gümüşüm! Çavom! Bu Odeonda

Bize Susmak, Bize Sevişmek Yaraşır! 

II.

eğeli

güllerin

ürperen

kokusu

çarparak

alkolünün

göz

kamaştıran

yamacına

üzüyordu

üstüne

çektiği

örümcek

alevlenen

rüzgarı

tüketilmiş

mermi

ıslıklarının

mevzilendiği

şahane

kıkırdak

püsküllerinin

ısrarlı

ıssız

kahramanlığı

üzüyordu

ve

karanlıkta

birikerek

ulaşıyordu

amacına

ölüm

başlıklı

bir

yarattığın

sunduğu

pembe

kör

kadırga

ılık

lacivert

çıplaklığıyla

sepya

telaşlı

soluğuyla

bir

anlık

şehvet

sayılabilir

miydi

o

tahrike

açık

muamma

anlatılmadı

hiç

kimseye

muhtelif

toyluklarla

süslü

naif

ama

durgun-

kasıklara

mıhlanan

paslı

drama

üzüyordu

ve

ürkerek

yaklaşıyordu

aşığına

felaketli

kabullenmiş

bir

erkek

kraliçenin

sunduğu

tahta

pasta

III.

yorucu görüntüler iletiyor telapatik suçlar

suretin gölgeliğine uzanan uyuşturucunun ucunda, 

mesela kemiklere çentik bir rimel sedası

mesela şakaklara çarpan loş ve temsili oda.

komedyenlerin kesildiği bir mezbahanın

çok yakınlarında

ya da

ötesinde bir hissin, bir hissin ortasında

havaya uçan yarım dua

havaya konan eksik travma.

bir iki üç

bir iki üç

hakiki boşluğun yalancı boşluğa her reveransında

damarları şaha kaldıran

bir terkediliş

damarları şaha kaldıran

hayali bir karşılama.

yırtık smokinler

sökük papyonlar

kucaklarda bir demet bombalı papatya!', 'I. savurarak kirpikleri filtresi ıslatılmış ve dişlenmiş bir kar tortusunun yerleştiği geceden,  dışarı bir balkon gibi uzanan iri gözleriyl...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":166,"source_url":"https://www.antoloji.com/pusu-metinleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Flucin', 'flucin-kucuk-i-skender-7c1tu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölüm, doğası gereği eğlendirici.

Flu cin giymiş bir delikanlı içi

n: ama uzun yola çıkarken

yanına insan almalı bir deli.

tereddüt etmeden ertelemeli esrarı

gözkenarlarında yürürken düşgücü dersleri.

Belirsizliğin yüzüne yayılırken sağlıklı acı: 

birdenbire karşılaşılınan çizgiler-daireler

etrafta kimse yokken çivilenmeli, çakılmalı

sıçrarken tenin pırıltılı nefretinde diğer

değişmeler: katlı duran meşhur çatı katı

ve oranın suçlu sakinleriyle kurulan masum bağlantı.

Uşak ve zehir. Uşak ve entrika.

Ateşe kalbini bahşiş bırakan sahip.

Dokunuşun sütü. Yırtılan yabani hayvanların

salyalarında kalan düğümlü, ıslak ip. Jilet

cevaplamasın demek

bulaşıcı bir kaosta o kösnül intiharı.

anlamak değil sorun, 

enseden öpmek. Enseyi uygun bir çiftleşmede

korkunun kasnağına gererek ürpertmek.

O, hala lacivertlere bürünmüş çatlak bir cımbızla

otomobillerden lastik ayıklıyor

O, hala peltemsi bir atığın görkemli hücumunda

karanlık liderlerin delik deşik kaslarını sayıklıyor

KUTU. UĞURLU KUTU. UĞURLU DAR KUTU.

mezarı ağzına alıp bağlamış etmüzik

kızgın yağız esmer gururlu DAR KUTU.

Özel bir kart açılışı kılların çarpıştığı

kalabalık dialoglarda sessiz ve olgun.

biraz göl canavarları, biraz su perileri, 

biraz dürbünle uzakları tarama alışkanlığı

dudaklarımda bir yara taşıma şanssızlığı.

köpürtülmüş siyah saçlar

köpürtülmüş siyah avuçlar

köpürtülmüş siyah yaz meyvaları: 

şimdi yağmalanmış bir ülkenin dağlarında

birbirine sarılmış baygın uyuyan

kuşlara hayal götürür çağıyla çakışan melek

ve meleğin espri hapları

kızgın yağız esmer gururlu DAR KUTU

perişan kumral terli tekerlekli PUSU

mutlu son kabusu! 

Kesici aletlerle yakın bir yatakta uyuşturucu

hep alkol hep alkol hep alkolün tekrarında

bilincin kanlı ucu.

aşka çökerken

ölüm, doğası gereği eğlendirici.', 'Ölüm, doğası gereği eğlendirici. Flu cin giymiş bir delikanlı içi n: ama uzun yola çıkarken yanına insan almalı bir deli. tereddüt etmeden e...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/flucin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garam', 'garam-kucuk-i-skender-40p76', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yeryüzünü gökyüzüne itiraf ederek başlıyorum; 

vardın; klasik döşenmiş yüzünle

bir gemi indirilir gibi denize

indirildim sessizce bedenine, o gece

dudaklarına sığınmış ölü martınla hep

söylenmesi askıya alınmış aşk adına

ballarımı aldın en güzel çiçeğimden

ne sarılıyordum kabusuma

ne de bir müzik parçası bitiyordu, 

itiyordum sesimi kulaklarına doğru

duy beni duy beni duy beni Hayta

tasarlanmış bir gezegen değil bu

ormandaki tek yalnız hayvan benim

kar yağıyor üşüyorum donacağım Hayta

avcımı arıyorum bir çabuk

istediğim, sıkılacak bir kurşun

kendi kanımı görmek istiyorum Hayta

bir gelinlik gibi giyeceğim kanımı bir başıma

kocam karanlığın ruhuna uzanacağım sonra

duvağımı en korktuğum canavarlar kaldıracak

ve ağzıma deyecek hafifçe uzay

bekaretimi hüsrana saklıyorum Hayta

tasarlanmış bir gezegen değil bu

tanrı dediğimiz, şaşkınlığımızın karakutusu

ellerim artık senin suyunda denizyosunu

felaketten arta kalanlar senin olsun

gözlerine deprem olmak için ne yapmalı

kasıklarını yıkıp geçen sel

kim bilir şimdi nerelerde ve

şimdi hangi güzel çocuklar çırılçıplak

yüzüyor içinde, yüzüyor senin için de! 

Hayta! mum bitiyor

Hayta! padişahımı devirdiler

sarayda nereye saklayacağım küçük şehzademi

			ve tahta atını

o da ağlıyor

biz bu yalnızlığa ne zaman yazıldık

ne zaman günışığına çıkarttılar sevdamızı

mektuplarımızı taşıyan ulak niye öldürüldü

mektuplarımızı şimdi kim okuyor

mektuplarımı şimdi kim yakacak

bak, öfkem firarda, Hayta! 

bak, öfkem firarda! 

prangasında yasadışı güller açan; 

madem kalbime bırakılmış şu yeni yurdum uçurum

ilk kez, ama ilk kez

yeryüzünü gökyüzüne şikayet ederek başlıyorum

ölümüm evcilleşmeyecek asla sen olsan da Hayta!', 'yeryüzünü gökyüzüne itiraf ederek başlıyorum;  vardın; klasik döşenmiş yüzünle bir gemi indirilir gibi denize indirildim sessizce bedenine, ...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/garam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Manti Palas', 'manti-palas-kucuk-i-skender-r6bzf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ters yönden geliyor elinde palaska ve deri pantolonun

	altında iphis''ten üzülme bir istridye ah

	nohut tuvallerdeki az filiz yukardaki

	pırlanta patlatan bahçeyi dipteki ölü ser

	aya sürükler - kalçalar garajda trompet ça

	lacak)   adam gelip dokunup nefesini alıp g

	ötürürse

	beyoğlu, mahmuzlarını taksim''e vursa

	kırbaç elden düşse fiuvv allah muhafaza! .

lastik! lastik! gözlerinden biri takılmış gözbebeği d

	önüyor da kirpik iğne takılmış fiuvv fiuvv

	ediyor haremağasının nur içi mağarası..

şapkasını çıkartıp öyle giriyor a; atıp bacaklarını o

	muzlarına inletiyor tükürüksüz hançer kab

	zasında yumruğum kınında yumruğum arka

	sından yaklaşıp şehzadenin o kumru tarihinde

	n tek tüy tek kıymık tek çubuk tadilattak

	i gövdeleriyle ön kesen bodyguard cüceler

	ibne! 

	çekil! 

	elleme! uyku haplarının arasında ne arard

	ı tek taşaklı basastin parmaklarından aka

	n hırs cinleri! salta similya! sanırım si

	z biriktirilen kana naz yapacaktınız ölüm

	fiuvv çekerek geçmeseydi kalbinizin boyay

	nasından, geriye doğru dönüldüğünde boynu

	zlarından salkım salkım nefret ve aşk top

	landığında trompet)   nasılsa esrar da içil

	ecek zıvana yerine kafamı takacaksınız da

ibneler koleje gitmeyecek, otomobil orada park edecek

	fiuvv deri pantolonun kapısında oğlanlarl

	a dansederek şarkı söyleyen muallaktaki u

	ğraş, sözünüzü unutmayın, kendini ölümler

	le özetleyen bir adamın fiuvvuyla gülümse

	r özkedibalığıgillerden gelme büyükoğlum!', 'ters yönden geliyor elinde palaska ve deri pantolonun 	altında iphis''ten üzülme bir istridye ah 	nohut tuvallerdeki az filiz yukardaki 	pırl...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/manti-palas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zihinboşluğu', 'zihinboslugu-kucuk-i-skender-eq1h4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir porno dergiyi karıştırırken

rüzgarın darmadağın ettiği

şehirlerarası mezarlıklarda

Dedim ki partizanca

bu fırtına, boşalmak üzere olan

dağların sıklaşan soluğu''dur

çünkü üstümde incecik bir gömlekle geçecek kış', 'Bir porno dergiyi karıştırırken rüzgarın darmadağın ettiği şehirlerarası mezarlıklarda Dedim ki partizanca bu fırtına, boşalmak üzere olan d...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/zihinboslugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yükselendeğerler', 'yukselendegerler-kucuk-i-skender-k0n40', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bitirilmiş bir gövdenin akşamüstü müziği! 

yüzümü sokuyorum suya, bitkilere ve şevke

memnun oldum diye sesleniyor çürük bir mürdüm eriği! 

Gücümle birleşiyoruz kaşlarımız alınmış: 

gerçekleştirilmesi imkansız bir savaş taktiği

gibi duruyor sol elleri sol ellerimde! 

şu ağaçta sallanan ölüyü görüyor musun diyor o anki körün biri', 'Bitirilmiş bir gövdenin akşamüstü müziği!  yüzümü sokuyorum suya, bitkilere ve şevke memnun oldum diye sesleniyor çürük bir mürdüm eriği!  G...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yukselendegerler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kedi, Pati, Kuyruk, Bıyık, Röya', 'kedi-pati-kuyruk-biyik-roya-kucuk-i-skender-hjv5q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ateş çizerken yüzünün arkasındaki genetik kalbi

fırsattan istifade bir yalanın yeminli şahitleri

ölüm tarihi: çevirisi imkansız bir aşkın tahlili.

sonbahardan sonra hiçbir kan akışkan olmayacak.

kopartılan alt dudağın yerinde çünkü

şevk süsü verilmiş bir sihirbaz kostümü.

düşülen kuyunun suyuna karışan insanı sever şiddet, 

biraz bok koksa da her sevgilinin elleri için için

bu gece nöbette asla öksürmeyecek anarşist çocuklar.

barıştım ağaçların nikahlandığı ormanların rüzgarıyla

şimdi benden sonraki indirsin süet pantolonunu.

bıçaklı plajın yüzme bilmeyen güzel cankurtaranı

karşılık vermeyecek sevgine o gül balığı! 

senin bir arpı dolaşan delişmen parmaklarını

emecek emecek

emip duracak tenden buharlaşan sperm yağı!', 'ateş çizerken yüzünün arkasındaki genetik kalbi fırsattan istifade bir yalanın yeminli şahitleri ölüm tarihi: çevirisi imkansız bir aşkın ta...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kedi-pati-kuyruk-biyik-roya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşlar', 'kuslar-perihan-magden-jcs97', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kandırmaca taşları bu kuşlar

Akıllarına geldikçe baharı ötüyorlar

Sabah pencereyi açtım

Sokaklar kış, kuşlar bahar.', 'Kandırmaca taşları bu kuşlar Akıllarına geldikçe baharı ötüyorlar Sabah pencereyi açtım Sokaklar kış, kuşlar bahar....', ARRAY['Türk Edebiyatı','Şiir','Perihan Mağden']::text[], 8.5, '{"poet":"Perihan Mağden","poet_slug":"perihan-magden","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kuslar-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Singapur Yolcusu', 'singapur-yolcusu-perihan-magden-ma4ye', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir sümüklüböceğin gümüş pabucundan şampanya içiyordunuz girdiğimde

Kolyeniz koptu - inciler çin ve tane tane döküldü yerlere

Peki siz kimdiniz, peki Singapur nerede kalmıştı

Sarıhummadan ölüp de yalnızlıktan sıkılıp dönen çingene

Kapıyı çaldığında - dedem: pamuk saçlı, mavi gözlü

Doğru söyleyin duydunuz mu, duymadınız mı

Neden beni yumurta topuklu gangsterler kovalamıyordu

Işıkların göle yansıdığı o meşum gece

Kahkahanız buz tutmuştu saçak saçak yerlere sarkıyordu

Girmemle çıkmam iki oldu, brahmanın sunduğu şekerli pirinç

Kobranın yeditül dansı - her şey kartpostallaşıyordu

Ben kaçıyordum Singapur nerede kalmıştı - Eyvah! 

Sular çekildi, midye kabukları denizanaları onların kızları sırıtıyor

Delhi alevler içinde türbanlar tutuşuyor

Koltuğu yeni kaplattım kahve döküldü üstüne

Ay tam da filmin en heyecanlı yerinde

Ben kaçıyordum sokaklar çiş kokuyordu

Hava kararmıştı, adama sordum

Singapur nerede kalmıştı, Singapur?', 'Bir sümüklüböceğin gümüş pabucundan şampanya içiyordunuz girdiğimde Kolyeniz koptu - inciler çin ve tane tane döküldü yerlere Peki siz kimdi...', ARRAY['Türk Edebiyatı','Şiir','Perihan Mağden']::text[], 8.5, '{"poet":"Perihan Mağden","poet_slug":"perihan-magden","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/singapur-yolcusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşaretler', 'i-saretler-yavuz-ozdem-2j34y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'El alıştırmasıdır türküleri onların

Aşka ve çalışmaya dair

Geriye suyun mili gibi

Emzirmenin aslı kalır

Çocukluk suretidir sesleri onların

Kendi temmuzlarıyla yanan

Bir gövdeden bir gövdeye

Ağaç diplerinde sevişgen

Erken düğünlerinde mayalı

Dillendirmenin şehvetidir

O seslerle toplanan

Süt gibi oğullar gırtlağıdır

İlk geceye göllenen

Zifir gibi bir ilk olur oysa gece

Gider bütün yücelticiliği o seslerin

İş türküleriyle akacaktır artık sular

Aşk bitmiş ateş sönmüştür.', 'El alıştırmasıdır türküleri onların Aşka ve çalışmaya dair Geriye suyun mili gibi Emzirmenin aslı kalır Çocukluk suretidir sesleri onların K...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Özdem']::text[], 8.5, '{"poet":"Yavuz Özdem","poet_slug":"yavuz-ozdem","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/isaretler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çetin Bahis', 'cetin-bahis-tahir-abaci-bno97', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne zaman deftere yazılsa hicran arkasına çıkar

Gül düşer elinden naçarın

Deme ki ol seher gidecek olmuştur

Zihni pencerenin fotoğrafını çekmiştir

Hepimiz ve hiçbirimiz suç ortaklarıyız

Safranın kimyadan hoyratça ayrıldığıyız

Tut ki karakollardan cehennem kaçkını gibi sorulmuştur

Demir yolu makası kör hatta çevrilmiştir

Şiirin de olmazdı bazen siluet bazen sima olmasan

Hep kördüğüm cazip, meçhul güzel, ret soylu

Güllerde gamzeler için bakışım kurulmuştur

Güz otelleri tam ortasından yarılmıştır

Biz bir göz için dünyayı mavi velveleye veririz

Ninemin zelzeleleri ise hep zemheriye denk

Sanma ki senden başkası siyanüre yorulmamıştır

Atlas Okyanusu rıhtımlara baskın vermemiştir

Yol sargısını çözmeden gidelim çavlanlara

Sıçanlara kalsın hatıra mahzeninde dağdağa

Mevsimsiz eski mesele yakar ruhsarı denilmiştir

Güneşe hasret evler artık kundağını çözmüştür', 'Ne zaman deftere yazılsa hicran arkasına çıkar Gül düşer elinden naçarın Deme ki ol seher gidecek olmuştur Zihni pencerenin fotoğrafını çekm...', ARRAY['Türk Edebiyatı','Şiir','Tahir Abacı']::text[], 8.5, '{"poet":"Tahir Abacı","poet_slug":"tahir-abaci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cetin-bahis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kibir', 'kibir-seval-esasli-ews0u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben bu kalbin hesabını sorar mıydım sırçalardan

Bıkıp usanmayaydım kırılıp durmasından

Dudaklarımı ısırarak yüzerken acı sularda

Saçlarından çeke çeke uykuya yatırır mıydım

Diline biberler o saydam tenine zırh mı değdirirdim

Ona soyunmayı üstelik şehvetle öğretendim

Özür mözür dilemem kusurum yok

Yağmurları yanlış yorumlamışım hepsi bu

Döktümse şu berbat şiiri çamura belenmiş eteklerimden

Ey hayat topla bulutlarını artık ve çekil üstümden

Ben sana benden iyisini doğururum', 'Ben bu kalbin hesabını sorar mıydım sırçalardan Bıkıp usanmayaydım kırılıp durmasından Dudaklarımı ısırarak yüzerken acı sularda Saçlarından...', ARRAY['Türk Edebiyatı','Şiir','Seval Esaslı']::text[], 8.5, '{"poet":"Seval Esaslı","poet_slug":"seval-esasli","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kibir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derin Yazgı', 'derin-yazgi-serkan-ozan-ozagac-vxdwn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Duvarlar, korkular, bu soğuk odaların uzağında

Bir bahçe durur, sessiz! Rüzgarı hayalimize düşen

Gideriz... Yol alır birden Aşk''lar yeni iklimlere

Kimin kalbinden savrulur, o gül; hüzne dönüşen? 

Yaz da bitti! Dönelim, aradığımız belki bir liman

İşte! Mevsimler arkasından bir tekne mi görünür? 

Ki ağlaşır yüzümüze değdikçe dalgalar

Bizimdir, derin sularda çırpınan acılı ömür! 

Sen ve ben, karanlığın baktığı sulardan geçerek

Başka yerde olmak isteriz; vücudumuzdan ötede! 

Ama Mutluluk ve Haz, kalpteki kayalardan da yüksek

- Döneriz yazgımıza, tekrar gidebilmek''çin düşlere', 'Duvarlar, korkular, bu soğuk odaların uzağında Bir bahçe durur, sessiz! Rüzgarı hayalimize düşen Gideriz... Yol alır birden Aşk''lar yeni ikl...', ARRAY['Türk Edebiyatı','Şiir','Serkan Ozan Özağaç']::text[], 8.5, '{"poet":"Serkan Ozan Özağaç","poet_slug":"serkan-ozan-ozagac","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/derin-yazgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zehirli Çiçek', 'zehirli-cicek-cezmi-ersoz-ngc1m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşk, ölümün dudaklarından öptüğü zaman

yüreğimdeki zehirli çiçeği

usulca bıraktım dünyanın dışına...

Aşk, ölümün dudaklarından öptüğü zaman

son kez ayaklanır düşevlerimde bastırılmış yangınlarım

mahcup ve sinsi bir konuk gibi yaşlandığım düşevlerim...

Aşk, ölümün dudaklarından öptüğü zaman

cesedim sahile vurur

insanların kıskanarak topladığı cesedim...

Aşk, ölümün dudaklarından öptüğü zaman

kelimelerin hatırasını sokaklara fırlatırım...', 'Aşk, ölümün dudaklarından öptüğü zaman yüreğimdeki zehirli çiçeği usulca bıraktım dünyanın dışına... Aşk, ölümün dudaklarından öptüğü zaman ...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/zehirli-cicek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgün Kendi Odasında', 'surgun-kendi-odasinda-cezmi-ersoz-yd06a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kendini yalanlayan gölge zamanlardan

düşman kiracılarımla geldim.

Ruhumda iskeletim uğulduyordu

terk edilmiş bir köprü gibi

inançsızlıktan, 

''ailede ölmek'' maskesiyle geldim.

Oysa masum sayardı kendini o

bencilliğin alevinde ısınır, 

düş saatlerinde misafirdi.

Kutsal sırrım diye

sahipsiz lanetimi fısıldayınca kulağına

gözyaşlarım boyandı

kayboluşunun sahici renkleriyle.

Artık düşleri düşman ona

masumiyeti zehirliyor bencilliğini

Tenine kazıdığım inançsızlık saatleriyle

sürgün kendi odasında

Şaşkın yüreğinin hatırası

şehirde oynattığım tek gecelik bir film şimdi...', 'Kendini yalanlayan gölge zamanlardan düşman kiracılarımla geldim. Ruhumda iskeletim uğulduyordu terk edilmiş bir köprü gibi inançsızlıktan, ...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/surgun-kendi-odasinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili Anne Çocuk Fahişe', 'sevgili-anne-cocuk-fahise-cezmi-ersoz-8hoqb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çocuk fahişe

şehvetin aynasında

kutsal masalını arıyor

yüzündeki sahipsiz spermler

çocukluğundaki ilahilerin serinliğini taşıyor

Yaşı yok fahişe

günahın içinde erdemi görüyor

yokluğa düşe düşe

ruhunun hallerini ezberliyor

Sevgili Anne... Çocuk fahişe

tahta kapısından çıktığı

bahçesine geri dönüyor

birbirine karışıyor şimdi

ayla güneş, sonra yıldızlar...

peki, bu melek kahkahasını kim atıyor?', 'Çocuk fahişe şehvetin aynasında kutsal masalını arıyor yüzündeki sahipsiz spermler çocukluğundaki ilahilerin serinliğini taşıyor Yaşı yok fa...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevgili-anne-cocuk-fahise-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çatlamaya Koşan At', 'catlamaya-kosan-at-cezmi-ersoz-yap3f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşk için kötü olmayı seçtim

kavuşmaların önünden koştum hep

acısını senden çıkarttım

içine çekmeye unuttuğun kalbinden

Son gece anladım

bu sessizlikten bir yangın kuşu doğacak

çatlamaya koşan bir at, hırpalanmış

unutmuş yarışı

Aşk için kötü olmayı seçtim

sahipsiz yüzlerimin tuzağına düşürdüm seni

özlemini büyük tuttum tenimizin uyumundan

Sevdikçe öldüren aşk için

kötü olmayı seçtim...', 'Aşk için kötü olmayı seçtim kavuşmaların önünden koştum hep acısını senden çıkarttım içine çekmeye unuttuğun kalbinden Son gece anladım bu s...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/catlamaya-kosan-at-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yok musun Sen?', 'sen-yok-musun-sen-suat-oktay-wozhv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'öyle bir bulut yağdırmıştı ki yağmuru üzerime 

ne ıslandığımı ayrımsadım, ne de üşüdüğümü..

oysa güz güneşiydi yağmurda beni ısıtan

güz güneşiydi gönlümü çelen.

sihirli dudaklardan kalbe atılan bir çentikti..

yağmur olup bulutla gelen, 

gözyaşı olup sel gibi akan, 

güz güneşiyle iliklerine kadar ısınan ben miydim? 

elveda bile diyemeden, eski bir dosta.. 

yağmurda unutulan gözyaşı mıydı? 

ya güneşte kavrulan? 

ya terk edilen? 

hangi masallar, hangi yalan şiirler, 

hangi ninniler rüyalarıma girmedi ki, senin yerine! 

Sen, güz güneşi gibi bir görünen bir kaybolan, sen 

sonbahar bulutu gibi beni sırıl sıklam eden, 

sen yok musun sen? 

Şimdi neredesin? 

Peki ya ben? 

30/11/02', 'öyle bir bulut yağdırmıştı ki yağmuru üzerime  ne ıslandığımı ayrımsadım, ne de üşüdüğümü.. oysa güz güneşiydi yağmurda beni ısıtan güz güne...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-yok-musun-sen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaaflar', 'zaaflar-bertolt-brecht-5sfqp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senin hic yoktu

Benimse vardi bir tane, 

Seviyordum.', 'Senin hic yoktu Benimse vardi bir tane,  Seviyordum....', ARRAY['Türk Edebiyatı','Şiir','Bertolt Brecht']::text[], 8.5, '{"poet":"Bertolt Brecht","poet_slug":"bertolt-brecht","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/zaaflar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Nefes', 'son-nefes-reha-basogul-4fnxr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düşündüm ki; 

insan son nefesinde

neleri doldurur içine

ve çeker

bitmesini istemezcesine.

düşünsenize

son nefes 

son an

son düşünce bu

o son nefeste

Düşündüm ki; 

insan son nefesinde

yalnızca aşklarını çeker içine

düşünsenize

aşık olduğu zamanlarda

düşünmüşlerse

hangi aşkı ölümsüz 

hissetmişlerse 

bitmesini istemezcesine

onları düşünürler 

o son nefeste

Düşündüm ki; 

bu konuda da hiç yazmamış şairlerde

bulamadım son nefeslerini hiçbir dizede

düşünsenize

her anı anlatmak için düşünüp

şiire aşık oluyorlar

bitmesini istemezcesine

son nefese gelince

hiçbirşey yazmadan

kaçıp gidiyorlar

o son nefeste

Düşündüm ki; 

zeka bu yüzden verilir

Ve hisler

en derin nefesini alır

bitmesini istemezcesine

o son nefeste

Düşündüm ki; 

aklımı düşününce nefesimi

nefesimi düşününce aklımı kaçırıyorum

ben çok düşündüm dostlar

son nefesimin vereceği karar: 

düşünmek akla zarar

ne kadar düşünmüşsek

kabirde o kadar azab var', 'Düşündüm ki;  insan son nefesinde neleri doldurur içine ve çeker bitmesini istemezcesine. düşünsenize son nefes  son an son düşünce bu o son...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/son-nefes-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyaya', 'dunyaya-sevinc-keles-8wfxt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Neleri unutuyor insan 

nelere göz yumuyor, hesapsızca

neleri istiyor umutsuzca

nelere inat satıyor kalbini alıyor dersini

nelere cefa, nelere vefa diyor

bilinmiyor, bilemiyor insan

gözlerden gönüle düşen her ağır yaş gibi, 

yaşıyor, yaşlanıyor insan 

bir daha gelmemek üzere gidiyor insan 

toprakla kucaklaşıyor, hayatla vedalaşıyor

gönüllere düşüyor bir ah! bir ah ki...

bir daha gelsem dünyaya 

neleri uğruna feda eder, neleri eda ederdim güzelim dünyaya...', 'Neleri unutuyor insan  nelere göz yumuyor, hesapsızca neleri istiyor umutsuzca nelere inat satıyor kalbini alıyor dersini nelere cefa, neler...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Keleş']::text[], 8.5, '{"poet":"Sevinç Keleş","poet_slug":"sevinc-keles","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dunyaya-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet', 'gurbet-gokcen-duran-m76lj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gurbetlik   zordur   üzer  insanı

Sıla   çeker   gurbetin  gamını

Analar,  babalar, kızlar  hep bekler

Gelmeyenler,  dertlerine  dert  ekler

Her  bayram  gözler  bakar  yollara

Ağrı  başlar,  baş  yaslanır  kollara

Burkulur  yürekler  nemlenir  gözler

teselli  edemez  onları  sözler

Zaman  geçer,  gönüller efkarlanır

Bu  bir kısır  döngüdür  tekrarlanır

Ey  gurbet!  Senin  evin  yıkılsın.

Gözlerin  dolsun,  boynun  bükülsün...', 'Gurbetlik   zordur   üzer  insanı Sıla   çeker   gurbetin  gamını Analar,  babalar, kızlar  hep bekler Gelmeyenler,  dertlerine  dert  ekler...', ARRAY['Türk Edebiyatı','Şiir','Gökçen Duran']::text[], 8.5, '{"poet":"Gökçen Duran","poet_slug":"gokcen-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gurbet-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefasız Yar', 'vefasiz-yar-gokcen-duran-5021p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Acıyla kanayan her yara, 

Bir gün elbet sağalır.

Tutulduysan vefasız yara, 

Dertler her gün çoğalır.', 'Acıyla kanayan her yara,  Bir gün elbet sağalır. Tutulduysan vefasız yara,  Dertler her gün çoğalır....', ARRAY['Türk Edebiyatı','Şiir','Gökçen Duran']::text[], 8.5, '{"poet":"Gökçen Duran","poet_slug":"gokcen-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/vefasiz-yar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzünü Silkeledim', 'yuzunu-silkeledim-gokcen-duran-iq2ur', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Silkeledim   yüzünü, 

Tebessüme    hasret   yüzünden

Acılar  düşsün  diye.

Silkeledim   yüzünü, 

Taktığın  maskelerin  altından

Saklı  yüzün   düşsün  diye.

Silkeledim  yüzünü, 

Umutsuz,  yaralı  gözlerin

Gözlerime   düşsün  diye.

Silkeledim  yüzünü, 

Hırsızlara   çaldırdığın  benliğinden

Umutlar  düşsün  diye.

Silkeledim  yüzünü

Ve   yüzümü

Silkeledim, 

Yüzünden  buzlara  asılı

Bir  hülya  düştü.

Silkeledim, 

Benliğimden  sana  adanmış

Bir sevda düştü.', 'Silkeledim   yüzünü,  Tebessüme    hasret   yüzünden Acılar  düşsün  diye. Silkeledim   yüzünü,  Taktığın  maskelerin  altından Saklı  yüzün...', ARRAY['Türk Edebiyatı','Şiir','Gökçen Duran']::text[], 8.5, '{"poet":"Gökçen Duran","poet_slug":"gokcen-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yuzunu-silkeledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahkumiyet', 'mahkumiyet-gokcen-duran-4gnld', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Acıyla  kanayan  her  yara

Sağalır  bir gün  elbet

Kalbini  çaldırdıysan  yara

Mahkumiyet  müebbet', 'Acıyla  kanayan  her  yara Sağalır  bir gün  elbet Kalbini  çaldırdıysan  yara Mahkumiyet  müebbet...', ARRAY['Türk Edebiyatı','Şiir','Gökçen Duran']::text[], 8.5, '{"poet":"Gökçen Duran","poet_slug":"gokcen-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/mahkumiyet-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarın Gelmeyecek…', 'yarin-gelmeyecek-sair-birtanem-adcga', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gün benim için yarın hiç gelmeyecek.

Ben yaşadıkalarımla kalacağım 

Sana doyamadan, seni özgürce sevemeden

Uzaklara gideceğim senden                                              

Uzak gibi görünsede bir Fatiha kadar yakın olacağım sana

Benim için okuyacağın dualarında ruhum yaşayacak.        

Sevgim senin anılarında yerini alacak.		

Seni severek gideceğim senden uzaklara	

Bir daha sana hiç dönememecesine				 

Sen ise ait oldukarınla, ait olduğun  yerde kalacaksın 

Artık sana ait olandan başka kimseler 

Seni sevip özlediğimi söyleyemyecek

Bir daha yüzümü görüp sesimi duymayacaksın

Benim yüzümden başkalarından laf duymayacaksın.

Ama ben seni gökyüzünden seni hep izleyeceğim.

Seninle ağlayıp seninle güleceğim.

Seni özleyip, seveceğim

Ruhum bir daha hayat buluna kadar.

(10/09/2002)', 'Bir gün benim için yarın hiç gelmeyecek. Ben yaşadıkalarımla kalacağım  Sana doyamadan, seni özgürce sevemeden Uzaklara gideceğim senden    ...', ARRAY['Türk Edebiyatı','Şiir','Şair Birtanem']::text[], 8.5, '{"poet":"Şair Birtanem","poet_slug":"sair-birtanem","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yarin-gelmeyecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim İşim Bu..', 'benim-i-sim-bu-sair-birtanem-2ulx1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Benim işim bu seni düşünmek

Günleri birbirine ekleyip

Sana kavuşmayı beklemek

Göz yaşlarımı içime akıtıp

Kaderimden seni dilenmek..

Benim işim bu seni hayal etmek

Hergece başımı yastığa koyup

Pamuk tenindeki kokunu hissetmek 

Bütün gece sana sıkıca sarılıp

Sabah uyanınca içten bir günaydın demek.

Benim işim bu sana şiir yazmak

Sana ait duygularımı biriktirip

Güzel kelimelerle sana anlatmak

Her zaman Tanrı'' ya avuç açıp

Seni benden almasın diye yalvarmak

Benim işim bu seni delice sevmek

Seni sevmenin büyüklüğüne inanıp

Bu ömrümü  sana feda etmek

Aşkımdan gün be gün eriyip

Yinede seni delice sevmek..

(25/11/2002)', 'Benim işim bu seni düşünmek Günleri birbirine ekleyip Sana kavuşmayı beklemek Göz yaşlarımı içime akıtıp Kaderimden seni dilenmek.. Benim iş...', ARRAY['Türk Edebiyatı','Şiir','Şair Birtanem']::text[], 8.5, '{"poet":"Şair Birtanem","poet_slug":"sair-birtanem","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/benim-isim-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokaklarda', 'sokaklarda-i-brahim-yoruk-sjtwq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben sevdayı sokak çocuklarında gördüm, 

Umutlu, saygılı, kırılgan...

Tabureleri tahttır onların, 

Sandıkları hazine; 

Düşmezdi niyazları kalplerinde anaların.

Ben ağlamayı sokak çocuklarında gördüm; 

Kirli avuçlarıda, sıcak suratlarında, 

Direnişlerinde, giysilerinde, kalplerinde, yüreğinde...

Velvelesiz yaşamaktı gaye, 

Gaye sükuttu, yalnız ve dilsizce.

Ben gülmeyi sokak çocuklarında gördüm; 

Çekingen, naif, mahçup...

Misket oynarken köprü altlarıda, 

Biraz müteşekkül, biraz mütenasip, 

Ve biraz münzevi bir sevinçtir ki

Ömre sığmaz yüreklerinde.

Ben hasreti sokak çocuklarında gördüm; 

Sıcak ve dağlanmış yüreklerinde...

Sokakların da anne-babası yok, 

Yolların da, kaldırımların da...

Halbuki...Daha ne kaldı ki: 

Sıcak bir yuva, sevgi dolu bakış, 

Ve şefkatli bir dokunuştan başka...', 'Ben sevdayı sokak çocuklarında gördüm,  Umutlu, saygılı, kırılgan... Tabureleri tahttır onların,  Sandıkları hazine;  Düşmezdi niyazları kal...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yörük']::text[], 8.5, '{"poet":"İbrahim Yörük","poet_slug":"i-brahim-yoruk","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sokaklarda-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilenci', 'dilenci-i-brahim-yoruk-mto6c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu kadar kolay olamaz unutmak beni, 

Her yürüdüğün yerde ayak izim var.

Saracak birgün, bencil kokum enseni; 

Her kokladığın gülde benim kokum var.

Gün gelecek, saçına düşecek aklar, 

Gün gelecek, seni de ısletacak yağmurlar, 

Gün gelecek, seni de alacak topraklar

Aşk ahirete göçmeden deli edecek seni.

Öreceksin kaderinin ağlarını belki bir gün, 

Önce söz sonra nişan ve sonra düğün.

Çocuklsrın olacak beni unuttuğun gün

Kapına gelen dilenci mahvedecek seni.

Kapını çocukların açacak dilenci diye

Koşacaklar''''anne dilenci geldi diye

Diyeceksin: üç-beş kuruş verinde gitsin evine

İşte o üç-beş kuruş satın alacak seni.', 'Bu kadar kolay olamaz unutmak beni,  Her yürüdüğün yerde ayak izim var. Saracak birgün, bencil kokum enseni;  Her kokladığın gülde benim kok...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yörük']::text[], 8.5, '{"poet":"İbrahim Yörük","poet_slug":"i-brahim-yoruk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dilenci-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana kendim geldim.', 'sana-kendim-geldim-pervin-adalioglu-xcb2t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sağ tarafımda esmer bir yaz mevsimi

sol yanımda sarımtrak güz

mazide kalanlar apayrı

güz yağmurlarına astım onlarıhepsi bir bir eriyip yok oldular

rüzgarları kokladım balkondan 	

saçlarımı okşadılar	

gecelerce.	

güneşi aldım gündüzden	

yıldızları sevenlere bıraktım 	

bir kalbim vardı sevdiğine değil	

sevildiğine verdim.	

yürüdüm karanlıklarda 	

aydınlıkları arkama aldım.	

sağ tarafımda esmer bir yaz mevsimi	

sol yanımda sarımtrak güz	

ben önümü seçtim	

önümde buğday bir bahar 	

bu baharda aşkın yolları deniz kıyısı	

yarin açık kolları tepenin arkasındaki sahil kasabasında	

yıldızlar daha bir parlak	

dalgalar daha bir hırçın bu baharda	

sevgiler daha romantik	

umutlar daha yeni yeşermiş	

renkler daha canlı	

tıpkı pınara düşmüş gökkuşağı gibi.	

ben önümü seçtim	

arkamı sırtlandım	

yol kıyılarına saçtım.	

sana kendim geldim.	

tüm içtenliğimle...	

kabul eder misin? 	

26 Kasım 02

Salı  16: 25

Denizli', 'sağ tarafımda esmer bir yaz mevsimi sol yanımda sarımtrak güz mazide kalanlar apayrı güz yağmurlarına astım onlarıhepsi bir bir eriyip yok o...', ARRAY['Türk Edebiyatı','Şiir','Pervin Adalıoğlu']::text[], 8.5, '{"poet":"Pervin Adalıoğlu","poet_slug":"pervin-adalioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/sana-kendim-geldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizli Kalan Aşk', 'gizli-kalan-ask-pervin-adalioglu-sbcp4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sanki baharda yürüyorum

bu ıslak yapayalnız şehirde

bir başka güzel saçların yağmurdan ıslanmışsa

sevgilin varsa yağmurda yürüyorsun

sokaklardan geçiyorum bildiğim bilmediğim

öyle vurgun öyle samimi öyle ılık 

öyle aşık

okşuyor ki damlalar

içime ruhuma iniyor sesleri

ve sen

her tuttuğum damlada sen varsın

ya aşkın sevdan 

tutamadığım her damladasın.

sanki baharda yürüyorum

ağaçlar bir bir yapraklarını üzerime serpiştirirken

ben onlarla dans ediyorum.

o yapraklarda sen gizlisin 

tıpkı içimde kaldığın gibi gizli...

09: 15

25 Kasım 02

Pazartesi

Denizli', 'sanki baharda yürüyorum bu ıslak yapayalnız şehirde bir başka güzel saçların yağmurdan ıslanmışsa sevgilin varsa yağmurda yürüyorsun sokakla...', ARRAY['Türk Edebiyatı','Şiir','Pervin Adalıoğlu']::text[], 8.5, '{"poet":"Pervin Adalıoğlu","poet_slug":"pervin-adalioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gizli-kalan-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Pas ki Yüreğimde', 'bir-pas-ki-yuregimde-hasan-sami-emiroglu-5bpqm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgilerden kalinti mi? 

Buluntu mu, calinti mi? 

Bir paski yüregimde

Ne türlü oldugu bilinmez.

Silmek isterim.... Silinmez....

Kumla ogdum, gazla sildim

Önünde bas kirip egildim

Eskiden böyle degildim

Bir sevda ki yar basina

Bir dert ki karsi gelinmez

Netsem, neylesem, silinmez...

Düsseldorf.1991', 'Sevgilerden kalinti mi?  Buluntu mu, calinti mi?  Bir paski yüregimde Ne türlü oldugu bilinmez. Silmek isterim.... Silinmez.... Kumla ogdum,...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sami Emiroğlu']::text[], 8.5, '{"poet":"Hasan Sami Emiroğlu","poet_slug":"hasan-sami-emiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-pas-ki-yuregimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sazsız Gitarsız', 'sazsiz-gitarsiz-hasan-sami-emiroglu-hi540', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yanik yanik, türküler söylersin

Sazsiz  gitarsiz...

Söyler de beni ikiye bölersin

Allahsiz kitapsiz...

Düsseldorf.2002', 'Yanik yanik, türküler söylersin Sazsiz  gitarsiz... Söyler de beni ikiye bölersin Allahsiz kitapsiz... Düsseldorf.2002...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sami Emiroğlu']::text[], 8.5, '{"poet":"Hasan Sami Emiroğlu","poet_slug":"hasan-sami-emiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sazsiz-gitarsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi başlıyor gerçek sevda', 'simdi-basliyor-gercek-sevda-hilmi-tanrikulu-3emlh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şimdi başlıyor gerçek sevda.

Başkalarıyla aynı yastıkta, 

Birbirimizi hatırladığımızda.

Özlendiğimizi bildiğimizde, yaklaşacak hüzün.

Sıkıntı hatırlayacak hayallerimizi, 

Cehennemi yaşayacağız yataklarımızda.

Gözlerimiz kapanacak, elini tuttuklarımıza bakarken, 

Gözlerimiz geçecek yüreğimizden.

Tutun(a)  mayacağız.

Sırtımızı dönüp, kağıtlarla birleştiklerimize, 

Ağlayacağız.

Islandıkça yastıklarımız, 

Aşk utanacak kendinden...

Yalnızken alkol damlatacağım kanıma, 

Damla damla.

Sen parçalara ayrılacaksın.

O’ na, kendine, bana bölüneceksin.

Yerin dibine düşünce düşlerim, 

Bedenimi kurtaramayacaksın, 

Ardımdan ağlayacaksın.

Gözükünce fotoğraflar, 

Susacak konuşamayacak dudaklar.

Dünya batacak alnımıza, 

Farkına bile var(a)  mayacaksın.

Sevda başlıyor.

Korkacağız seviştiklerimizden.

Mutlu gibi görünüp, 

Oyuncakları kandırırken, 

Gerçek çıkacak kitapların içinden.

Okunurken ben, 

Okunurken bendeki sen, 

Gerçek çıkacak kitapların içinden.

Yüreğin gözükecek, sözlerimin yüzünden.

Görecekler.

Ama yüzünü çalamayacak hırsızlar, 

Kilitleyeceğim sevdamızı okyanuslara, 

Bulamayacaklar...

Başlıyor sevda.

Ellerimiz bedenini bildiklerimizi, 

Tekrar tekrar keşfedecek.

Birbirimize dokunuyormuş gibi yapacağız, 

Dokun(a)  mayacağız.

Yazacağım eskisi gibi.

Bitmeyecek kitaplar ve okunanlar.

Sen yine okuyacaksın beni, 

Eskisi gibi.

Eskisi gibi acıyacaksın bana, 

Hırslarımı görmezden gelip, 

Kendini yazdıracaksın bana.

Yazdıkça bakacaksın kendine, 

Kendinden büyük olan, 

Bendeki kendine. 

Kendin, içimdeki sevgin ve ben, 

Her gece açacağız, 

Her gün solacağız.

Solacağız senle ben.

Sevdalar  başlayacak etrafımızda yeniden.

Farklı olarak benimkinden.

Biz geçeceğiz tarihten.

Tarih biz unutmayacak, 

Hep hatırlayacak.

Biz dönülmeze gittikten sonra, 

Tarih bizi kendine yazacak.

Sevda başlıyor, 

Sevda başlamaya devam ediyor.

Kara sevda...

Acı sevda...', 'Şimdi başlıyor gerçek sevda. Başkalarıyla aynı yastıkta,  Birbirimizi hatırladığımızda. Özlendiğimizi bildiğimizde, yaklaşacak hüzün. Sıkınt...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/simdi-basliyor-gercek-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sencil Sözler', 'sencil-sozler-ersin-korkut-t62pn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sürgün ettim maviyi, boynu bükük

Gökyüzüne siyahı resmettim kırık kalemimle

Gece uykuda, derin

Oysa benim yıldızımı çalmışlar ve ben ağlamaklıyım

Göz bebeklerim eriyik

Kim bilir hangi serseri şehirde astılar seni

Ve hangi çocuk benim dedi senin için

Silip silip seni çizdim geceye

Boşluğa merdiven dayadım

Kollarımı ve ayaklarımı açıp sen oluyorum sensizliğe inat.', 'Sürgün ettim maviyi, boynu bükük Gökyüzüne siyahı resmettim kırık kalemimle Gece uykuda, derin Oysa benim yıldızımı çalmışlar ve ben ağlamak...', ARRAY['Türk Edebiyatı','Şiir','Ersin Korkut']::text[], 8.5, '{"poet":"Ersin Korkut","poet_slug":"ersin-korkut","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sencil-sozler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmalı', 'olmali-hilmi-tanrikulu-3u59h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sonra…

Sonra yürümeliyim, 

En zamansızından yağmur olmalı, 

İnsanların sesi kısılmalı, 

Doğrularla konuşmalıyım…	

Mısralar yazılmalı, 

Altına tarih atılmayan, 

Kime yazıldığı anlaşılmayan.

Özneleriyle oynanmalı, anlamlar katılmalı, 

Okununca sayfaları müsvette kullanılmamalı…

Biraz müzik olmalı, 

Sözlerini anlamamalıyım…

Sadece olmalı.

İki tek arkadaşım olmalı, 

Hakkında kötü sözler duymadığım, 

Garip şehirlere koşmamalıyım…

Hiç olmazsa hayali olmalı, 

Adını kimseye söyleyemediğimin, 

Tarih kararsız kalmalı ikimizi yazmakta, 

Zorlanmalı, bilinmediğimden, beni anlamakta….

Bir kenarı olmalı denizin, 

Yürürken rastladığım, 

Çöp kutusu olmalı izmaritlerimi atacağım…

Mavi pantolonu olmalı yalnızlığımın, 

Gözüme takılmalı, 

Ayaküstü konuşmalıyım, mavi pantolonlu yalnızlığım ile, 

Uzun zamandır görmediğim, 

Ve umursamadığım arkadaşlarım gibi.

Ayrı ayrı gideceğimiz yollar olmalı, 

Sırılsıklam ayrığımız olmalı…

Kemancı bir kız olmalı, 

Gözleri bırakılıp, müziğine bakılmalı.

Ayaklarının altında dünya korkmalı, 

Kıskanmalıyım, 

Kendinden geçişini, 

Üzülüp hallerimi yarıda kesme şansım olmalı…

Birde özlediklerim olmalı, 

Benden habersiz kelimelerime sahip.

Haritalara bakmalıyım, 

Gözlerimle kavuşmayı sayıklamalıyım.

Kentlerin isimleri takılmalı ulaşamamazlığıma, 

Kafiyeler serpiştirmeliyim sonlarına… 

Kitapçılar açılmalı, 

Yeni yeni, 

Aranılan bir kitap olmalı, 

Dostlarımın tavsiye ettiği…



Köşe başında bir dilenci olmalı, 

Geçen her çifti sevgili sanan.

Herkese iltifatlar yağdırmalı, 

Yada önünden geçerken elini tutamadığımla, 

Bizi birbirimize yakıştırmalı.

Şehir onu kendine mıhlamalı…

Geleceği kullanılmamış bir çocuk olmalı, 

Bir tek oyuncağı için ağlamalı.

Akşamları kendime ölürken, yanımda uyumalı, 

Azrail’den korkup annesinin yanına koşmalı…

Öyle olmalı, 

Ki; 

Sonra hayat olmalı…', 'Sonra… Sonra yürümeliyim,  En zamansızından yağmur olmalı,  İnsanların sesi kısılmalı,  Doğrularla konuşmalıyım…	 Mısralar yazılmalı,  Altın...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/olmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım dostlarım', 'canim-dostlarim-hilmi-tanrikulu-b1ogt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Masal anlatmıyorum.

Yavaş yavaş, 

Uzak oluyorum.

Yeni dostlar kazandırdım, 

En güzelleri birleştirdim.

Şimdi, 

Çekiliyorum aranızdan, gürültüyle, 

Ve siz anlamadan.

Beni kabullenmek zor olmuştu, 

Unutmak kolay olacak.

Kolay olmasa da, 

Elinizde bir tek yokluğum kalacak.

Ne uzun geceler devirdik, 

Canım dostlarım.

Geceler, geceler, 

Artık uzun geceler ol(a)  mayacak, 

Gece, 

Hep gece olacak.

Pamuk ipliği taşıyamadı beni.

Koptu sonunda.

Somurtkanlığım kazandı

Ve siyah kazandı.

Kırmızıyı vermediler bana.

Canım dostlarım.

Şimdi, 

Son üç yudum kadehimde kalan, 

Erkekler ağlamaz derler, 

Yalan.

Gözyaşı her şarkıyla, yeniden.

Dünyanın kuralına göre, 

Yaşadığım her şeyi anlattım size.

Küçükken elime çorap geçirip, 

Yaptığım kardan adamlar hariç.

İhtiyacım oldu anlatmaya, 

Yalnızlığıma yakalanmadığımda.

Acı...

Acımayın bana dostlarım.

Küçük bir kavanoza atılmış, 

Renkli, yalnız bir balık oldum.

Bana bakıp, gülüştüler, 

İstedikleri zaman beslediler, 

Boynuma uçan balon bağlayıp, 

Alay ettiler.daha uzun yaşatmakla tehdit ettiler.

Acı...

Acımayın bana dostlarım.

Verdiğim değeri karşılayamadınız, 

Çoğu zaman.

Haklıydınız.

Her karşıladığınızda, 

Ben daha fazlasını verdim.

Hak ettiniz.

Dostum olmakla, 

Bana sahip olmayı, 

Hak ettiniz.

Canım  dostlarım.

Sizleri seviyorum.

Ölüm, ayrılık dostlarım.

Unutmayın beni, 

Bırakmayın.

Belki yaşamadığımız geceler vardır.

Atmadığımız kahkahalar vardır.

Belki de  şu an, 

Bağıra bağıra söyleyeceğimiz, 

Şarkılar çalınıyordur.

Yaşayın.

Sizleri seviyorum.

Geceler boyu, 

Yokluğumu mutlu edin.

Canım dostlarım...', 'Masal anlatmıyorum. Yavaş yavaş,  Uzak oluyorum. Yeni dostlar kazandırdım,  En güzelleri birleştirdim. Şimdi,  Çekiliyorum aranızdan, gürült...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/canim-dostlarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen gerek', 'sen-gerek-hilmi-tanrikulu-t6l5l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen gerek...

Bir anlık bakışlarıma.

Göz kapaklarımın, 

Altına...

Korku mumlarla, hep yanmakta.

Sen var oldukça, 

Ayrılık, hüzün kendini kandırmaca, 

Sen var oldukça.

Sen gerek; 

Kelimelerime.

Önceden ve sonradan, 

Olduğu gibi.

Günümde ve gecemde, 

Olduğun gibi.

Sen gerek  biraz.

Hala, 

Sen  gerek biraz...', 'Sen gerek... Bir anlık bakışlarıma. Göz kapaklarımın,  Altına... Korku mumlarla, hep yanmakta. Sen var oldukça,  Ayrılık, hüzün kendini kand...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-gerek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beşe çeyrek kala', 'bese-ceyrek-kala-hilmi-tanrikulu-c1kzy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sabaha karşı beşe çeyrek kala, 

Kavuştuk.

Gözlerimizde uyku vardı, 

Ağlayamadık.

Heyecandan yüzüne bakamadım, 

Konuşamadık bile.

Yollara karşı gelmenin cesareti

Ve onları yenmenin gururuyla, 

Gülüşemedik bile.

Uzak yakın olabilmiş miydi? 

 Yakın hala çok uzak mıydı? 

Sormadık.

Yaşamadık kavuşan hikayeleri, 

İçimiz serinledi, 

Rahatladık.

Şimdi yaptığımız garipti, 

Sonrasını hiç bilmiyorduk.

Bu zamanlarda hep uyurduk.

Bu gece hayat sürpriz yaptı, 

Kavuştuk...

Gözlerimizde uyku vardı, 

Ağlayamadık...', 'Sabaha karşı beşe çeyrek kala,  Kavuştuk. Gözlerimizde uyku vardı,  Ağlayamadık. Heyecandan yüzüne bakamadım,  Konuşamadık bile. Yollara kar...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bese-ceyrek-kala-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bütün yalanlarınızı biliyorum', 'butun-yalanlarinizi-biliyorum-hilmi-tanrikulu-2t6ge', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bana söylediğiniz bütün yalanları, 

Biliyorum.

Kendimi yalanlarınızdan seçiyorum, 

Yalan oluyorum.

Kurşun kalemle aynalara yazıyorum, 

Gerçekleri, 

Kolayca siliyorum.

Yalanlarınıza, 

Saygı gösteriyorum.

   

Kurşun kalemle aynalara yazıyorum, 

Düşlerimi, 

Kolayca siliyorsunuz.

Heveslerime aldırmıyorsunuz.

Çantamı alıp gökyüzüne atlıyorum.

Şehirdeki bütün yalanları görmek için.

Görüp en yalansız sokağa, 

Düşmek için.

Düşüp, düşlerimi, 

Düşlemek için.

Bana saldıran sokak sarhoşlarına, 

Yalanlarımı kusuyorum.

Bulamıyorum, 

Ben hangi yalanın söylemiyim? 

İlk yalanımı söylerken yakalandım.

Çizgi kahramanlara.

Rengarenk bir hapishane çizdiler bana.

İçine koydular yalanımı.

Beni kapattılar sonsuzluğa.

Kopuk kopuk hikayeler yazdım içerde, 

Hepsini oynadılar.

Parmaklıklardan gördüm, 

Düşlerimi gerçeklediler yalandan.

Eski hikayeler okudum.

Siz yokken.

Anladım, 

Eskiden sevilenler yalansa, 

Bugün doğru.

Bugün yaşananlar yalansa, 

Eski doğru.

Her yalan doğru değil, 

Yalan olan yalanda varmış.

Dostlarım öğretmediler bana, 

Yalansız yaşanamıyormuş.

Şehir yalanlara kucak açmış, 

Doğruların yan tarafında.

Sokağımdan, 

Gözyaşları akıyor şehrin.

Doğrular boğuluyor.

Bir iki tane kurtarabiliyorum.

Kendimi doğrulardan seçiyorum, 

Yalan oluyorum...', 'Bana söylediğiniz bütün yalanları,  Biliyorum. Kendimi yalanlarınızdan seçiyorum,  Yalan oluyorum. Kurşun kalemle aynalara yazıyorum,  Gerçe...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/butun-yalanlarinizi-biliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizken', 'sensizken-hilmi-tanrikulu-rpkn3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sensizken yaşamı kandırdım, 

Sabah uyanmadım.

Gözlerimi zorlamadım.

Ciğerlerimi ağlattım.

Sadece sigara içtim kahvaltıda, 

Üstüne bir sigara daha.

Sensizken şehrimizi yalnız bıarktım.

Akşama doğru sevdam terledi, 

Deniz kenarına oturup serinlettim.

Bir  geminin gidişini izledim.

Ağlamadım.

Simitçilere inat, 

Aç durdum.

Güneşi beklerim, batmadı.

Kızıp dünyayı çevirdim geriye.

Biraz baktım güne, 

Sonra bıraktım günü geceye.

Sensizken bütün kızlara baktım.

Benzetemedim yüzüne hiç kimseyi.

Kimisi baktı yüzüme, 

Kimisi aldırmadı bile.

Sen doğmadan önce söylenmişti, 

Sensizlik bilmiyor sevmeyi.

Sensizken aldattım seni.

Yoktun.

Yalnızlığa karşı gelemedim.

Resimlerine baka baka, 

Yalnızlıkla seviştim.

Yokluğunla bakıştım.

Aynı yastıkta yattım.

Yalnızlığım az geldi.

Hayalini de aldım koynuma.

Hayalinle aldattım seni, 

Tek başıma.

Sensizken çok yazdım, 

Beğenmedim, 

Hepsini yaktım.

Sensizken kimse anlamadı beni.

Aradılar, öğrenemediler yerimi..

Uğraşmadılar  biliyorum.

Aşık deyip geçtiler.

Hissettim.

Geceleri aklına geldim özleyenlerimin, 

Aya bakıp aldandılar, 

Gurbet var içinde gözlerimin.

Sensizken bir şey yemedim.

Üç günde bir balık ekmek, 

O kadar.

Birde aklıma gelince, 

Kendimi yedim.

Ayırdım ruhumdan, 

Sana kadar.

Sensizken pek yaşamadım.

Yaşamı kandırdım.

Yaşadım...', 'Sensizken yaşamı kandırdım,  Sabah uyanmadım. Gözlerimi zorlamadım. Ciğerlerimi ağlattım. Sadece sigara içtim kahvaltıda,  Üstüne bir sigara...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/sensizken-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmişimi bozdurdum', 'gecmisimi-bozdurdum-hilmi-tanrikulu-zrzki', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biliyor musun? 

Son zamanlar, 

Geçmişimi bozdurdum, 

Yaşadıklarımda yiyorum.

Kızdırdım biraz fotoğrafları.

Peşimden geldi, donuk gibi duran yüzün.

Yarından yenileri için söz aldı.

Kalmadı elimde yalnızlığın listesi, 

Hepsin aldım yetmedi.

Tüttüm gecekonduların, bacalarında, 

Ziyaret ettim yaşlıları yataklarında.

Hepsini yaptım, 

Bir gün etmedi.

Son zamanlar, 

Saatimi kendim ileri alıyorum.

Şarkılar tükendi boğazımda, 

Zamanın yatsıdan sonrasında.

Gülemedim arkadaşlarıma.

Gecelerden de kara, 

Rivayetlerden de zorda.

Bugünler renkleri boyayamadı, 

Akşam siyah beyaz ulaştı sabaha.

Sabah, dünü içtim kahvaltıda, 

Soğumuş biraz, 

Dönüp ısıtamadım.aç duruyorum son zamanlarda.

Biliyor musun? 

Son zamanlar, 

Geçmişimi bozdurdum, 

Yaşadıklarımda yiyorum...', 'Biliyor musun?  Son zamanlar,  Geçmişimi bozdurdum,  Yaşadıklarımda yiyorum. Kızdırdım biraz fotoğrafları. Peşimden geldi, donuk gibi duran ...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gecmisimi-bozdurdum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni öldü sanmışlar', 'beni-oldu-sanmislar-hilmi-tanrikulu-936qr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Akşamı geceye salarken, 

Komşularım kapımı kırdı.

Kan sızmış odamdan, 

Beni öldü sanmışlar.

Polisi aramışlar, 

Ambulansı çağırmışlar.

Hepsi trafiğe takılmışlar.

Komşularım kapımı kırmışlar.

Oysaki ölen ben değildim, 

Bedenimdi.

Ben hala yaşıyorum.

Komşularım boşuna korkmuşlar.

Karanlığa bak, 

Saklanıyorum.

Komşularım bulamıyorlar...', 'Akşamı geceye salarken,  Komşularım kapımı kırdı. Kan sızmış odamdan,  Beni öldü sanmışlar. Polisi aramışlar,  Ambulansı çağırmışlar. Hepsi ...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/beni-oldu-sanmislar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendime emanet ettim seni', 'kendime-emanet-ettim-seni-hilmi-tanrikulu-di8xx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kendime emanet ettim seni.

Gece, 

Pencereden sokağı gördüm, 

Korundum.

İçindeyim, sokak çocuklarının

Çakal gibi akıllarının.

Günahlarını bilirim, 

Kötüsünü yerim düşlerinin.

Tiner bile uyuşturamaz.

Hiç birisi sana bir şey yapamaz.

Gökyüzüne atlarım.

Gökyüzündeyimdir.

Papatyaların falına bakamayacak kadar, 

Gözlerim yukarı uçar.

Yağmurunu içerim bulutların, 

Kendime çarparım şimşekleri, 

Rengi solmasın diye saçlarının.

Kendime emanet ettim seni, 

Elimi kestim, 

Ağlamadım.

Gözümün içine açlık kaçtı, 

Aç kaldım.

Uykum sırtıma vurdu, 

Sabaha kadar taşıdım.

Kendime emanet ettim seni.

Gece, 

Pencereden sokağı gördüm, 

Korundum...', 'Kendime emanet ettim seni. Gece,  Pencereden sokağı gördüm,  Korundum. İçindeyim, sokak çocuklarının Çakal gibi akıllarının. Günahlarını bil...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kendime-emanet-ettim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili kabuslarım', 'sevgili-kabuslarim-hilmi-tanrikulu-vze1d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir ağaç bir de ben, 

Varım burada.

Ölmedim, 

Yaşamıyorum.

Sırtımı dayadığım ağaç nefes alıyor.

Benim havam bozuluyor.

Gözlerimi kapatırken, başımı çeviriyorum.

Son çabaları yüreğimin.

Hissediyorum.

Gözlerimi düşünen yok burada, 

Görecek bir şeyde yok.

Kendime dokunmaya didiniyorum.

Kendimi bulamıyorum.

Ellerimi çözüyorum kelepçelerden, 

Oturduğum yere dokunuyorum.

Oturduğum yeri bulamıyorum.

Bomboşum bomboş.

Uçmuyorum, düşmüyorum.

Her taraf kitaplık, 

Her taraf bembeyaz, 

Ne kış, ne yaz.

Islanmıyorum, kurulanmıyorum.

Ayaklarımı arıyor adımlarım, 

Aslında yürümüyorum.

Yürüyemiyorum, duramıyorum.

Gözlerim kırmızı, 

Bir yerler yine bayram mı? 

Kulaklarım çınlıyor, duyamıyorum.

Puslu buralar, toprağı verimsiz.

Bir ağaç var, birde ben, 

Ne özgürüz, ne hapis.

Kalbim atmıyor, 

Yaşıyorum...

				

                                                    ...Bir gün öldüreceksiniz beni, 

                                                         ah benim, 

                                                         sevgili kabuslarım...', 'Bir ağaç bir de ben,  Varım burada. Ölmedim,  Yaşamıyorum. Sırtımı dayadığım ağaç nefes alıyor. Benim havam bozuluyor. Gözlerimi kapatırken,...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sevgili-kabuslarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günaydın ey şehir', 'gunaydin-ey-sehir-hilmi-tanrikulu-przw4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Oturuyoruz  denize yakınca, 

Masumluğu tartışılan arkadaşlarımla.

Bir işaret garsona, 

Ucuz bir şeylere ihtiyacı olan masaya, 

Saygıyla...

Muhabbet başlasa, dönecek elbet.

Sen o zaman kahkahaları seyret.

Eksik olmayacak, sevmesem de siyaset, 

İçkiler bitiyor,  garsona el et.

Kafam dönecek belli.

Kulağında eli, 

Çakır keyfimin.

Kaldı mı gitmediğimiz yeri, 

Rengarenk şehrimin? 

Bu fahişeler hep burada, 

Elimden bir şey gelmiyor, acısam da.	

Kim ne buldu yine? 

Başlamış yine kavga.

Ayırsak mı, 

Girip savaşsak mı? 

Hangisi haklı acaba? 

Ağzımızın tadı bozuldu, 

Çorbacıda alacağız biraz sonra, 

Soluğu...

Sabah olsa da evime gitsem.

Uyumak pahalı buralarda.

Şehrimin kumsalında, 

Yer de kalmaz bu zamanda...

Çıkıyoruz çorbacıdan, 

Zaman saymaya başlıyor sabahtan.

Günaydın, 

Ey şehir, 

Başım dönüyor...', 'Oturuyoruz  denize yakınca,  Masumluğu tartışılan arkadaşlarımla. Bir işaret garsona,  Ucuz bir şeylere ihtiyacı olan masaya,  Saygıyla... M...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/gunaydin-ey-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorsun sanacaktım', 'seviyorsun-sanacaktim-hilmi-tanrikulu-jsn6g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Konuştuk...

Kelimelerimde dans ettin.

Bilmesem, 

Seviyorsun sanacaktım.

Gözlerinde yandı gözbebeğim, -

Bileklerini kesti yüreğim.

Tutuştu ellerim.

Korktum.

Bilmesem, 

Seviyorsun sanacaktım...', 'Konuştuk... Kelimelerimde dans ettin. Bilmesem,  Seviyorsun sanacaktım. Gözlerinde yandı gözbebeğim, - Bileklerini kesti yüreğim. Tutuştu el...', ARRAY['Türk Edebiyatı','Şiir','Hilmi Tanrıkulu']::text[], 8.5, '{"poet":"Hilmi Tanrıkulu","poet_slug":"hilmi-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/seviyorsun-sanacaktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dua', 'dua-nilgun-akcay-gh0up', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerim...

Karanlığın ışığıyla..

                       Buluştuğunda.

Kum saatim kırıldığında...

Yaşam boyu ruhumu saran

KEŞKE kabusumdan kurtar beni...

                         ALLAHIM..!', 'Gözlerim... Karanlığın ışığıyla..                        Buluştuğunda. Kum saatim kırıldığında... Yaşam boyu ruhumu saran KEŞKE kabusumdan k...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Akçay']::text[], 8.5, '{"poet":"Nilgün Akçay","poet_slug":"nilgun-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dua-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık..!', 'artik-nilgun-akcay-d3dj5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Artık mevsimsiz yaşamayı öğrendim.

Sonbaharı yaşadım, kışı özledim.

İlkbaharla yazı hiç bilmedim...

Sararan yapraklarla dans ettim.

Beyaz karlar oldu kefenim.

Toprakla kucaklaştı bedenim.

Sevgilerim, kaygılarım, herşeyim...

İki beyaz güvercin yükseldi mezarımdan.

Biri sevgilerimi, diğeri kaygılarımı aldı ruhumdan

Sevgilerimi denizin yakamozuna...

Kaygılarımı gecenin kucağına gömdüler....

Ölüm sana tek çare dediler....', 'Artık mevsimsiz yaşamayı öğrendim. Sonbaharı yaşadım, kışı özledim. İlkbaharla yazı hiç bilmedim... Sararan yapraklarla dans ettim. Beyaz ka...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Akçay']::text[], 8.5, '{"poet":"Nilgün Akçay","poet_slug":"nilgun-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/artik-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefret...!', 'nefret-nilgun-akcay-iicrk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bağlılığın bedelinin ihanet..

Sevgininkinin de nefret...

Olduğunu geç öğrendim.

Geç öğrendim...

Dostlukların bir kalemde

Silinebileceğini.

Geç öğrendim, İhtirasların

Mutlulukları boğacağını.

Geç öğrendim Dostum..

Ölüm''ün bile...

NEFRET''i yenemeyeceğini.', 'Bağlılığın bedelinin ihanet.. Sevgininkinin de nefret... Olduğunu geç öğrendim. Geç öğrendim... Dostlukların bir kalemde Silinebileceğini. G...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Akçay']::text[], 8.5, '{"poet":"Nilgün Akçay","poet_slug":"nilgun-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/nefret-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulacağım', 'bulacagim-nilgun-akcay-42gsn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geçmişim...sinsi bir yılan., 

Sinmiş yüreğimin karanlıklarına.

Geleceğim...İnatla karanlıklarda saklı.

Bir adım attıktan sonra...

Dönemem istesem de..

Ve... O son dönemeçten sonra, 

Usul usul kucak açacak; 

Gel... dercesine.Yumuşak bir sıcaklık, 

Akacak damarlarıma ılık ılık...

Ölümün sevgi dolu soluğu.

Ve BEn... onunla...

Bulacağım mutlu sonu...', 'Geçmişim...sinsi bir yılan.,  Sinmiş yüreğimin karanlıklarına. Geleceğim...İnatla karanlıklarda saklı. Bir adım attıktan sonra... Dönemem is...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Akçay']::text[], 8.5, '{"poet":"Nilgün Akçay","poet_slug":"nilgun-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bulacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle Beni...', 'bekle-beni-nilgun-akcay-g8vv4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerim yorgun..

Gönlüm yorgun, 

Bedenim yorgun yaşamaktan...

Ölümü istiyorum..Ölmek huzuru hissetmek.

Uzanmak istiyorum kara topraklara..

Dostum diyebileceğim, dayanacağım..

Biri olsun istiyorum..

Fani dünyada bulamadığım huzura..

Kavuşmak istiyorum..

Koşmak istiyorum Ölüm''e...

Onu çağırıyorum...

Günün, gecenin her saati..

Uzak..çok uzak bir yerden...

Sesleniyor SANKİ..

Kavuşmamız yakın sabret... BEKLE BENİ..

Dercesine.', 'Gözlerim yorgun.. Gönlüm yorgun,  Bedenim yorgun yaşamaktan... Ölümü istiyorum..Ölmek huzuru hissetmek. Uzanmak istiyorum kara topraklara.. ...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Akçay']::text[], 8.5, '{"poet":"Nilgün Akçay","poet_slug":"nilgun-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bekle-beni-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çözüm..!', 'cozum-nilgun-akcay-gy0b3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıllarıma..

Geçen yıllarıma bakıyorum..

Ne görüyorum biliyor musunuz.? 

Koskocaman hatalar zinciri..

Kıramadığım, yok edemediğim hatalar.

Gelecek yıllarımı düşlüyorum.

Ne görüyorum biliyor musunuz.? 

Koskocaman bir KAOS denizi...

Ve..Denklemi çözüyorum.

Hatalarım Kaosumu kabusa çeviriyor...

Tek çözüm... ÖLÜM...!', 'Yıllarıma.. Geçen yıllarıma bakıyorum.. Ne görüyorum biliyor musunuz.?  Koskocaman hatalar zinciri.. Kıramadığım, yok edemediğim hatalar. Ge...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Akçay']::text[], 8.5, '{"poet":"Nilgün Akçay","poet_slug":"nilgun-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/cozum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Perde...', 'son-perde-nilgun-akcay-9ldpb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gerçeğin son perdesi

Uzakların en uzağı...

Kör geceler..

Bekliyor kollarında sonumu.

Sadece..

İnan sadece...

Gözyaşlarınız çaresiz kaldığında

Yüreğiniz yanacak...

Kar yağacak üzerime...

Yağmur yağacak belki de.

Ama, zaman sizlere...

Sonsuz acıları unutturacak..

Gelen gider..Giden dönmez...

Bir daha diyeceksiniz...

Üzülmeyin..DOSTLARIM...

Elbet alışır gözleriniz...

Soğuk mermerlere...

Yazılan ismime..', 'Gerçeğin son perdesi Uzakların en uzağı... Kör geceler.. Bekliyor kollarında sonumu. Sadece.. İnan sadece... Gözyaşlarınız çaresiz kaldığınd...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Akçay']::text[], 8.5, '{"poet":"Nilgün Akçay","poet_slug":"nilgun-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/son-perde-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-i-brahim-sahin-gmve1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seninle olmanın zor olduğunu 

Düşünürdüm 

Sensiz olmanın imkansızlığını anlayana kadar

Ne yazıkki 

Anladığım zaman 

Sensizdim', 'Seninle olmanın zor olduğunu  Düşünürdüm  Sensiz olmanın imkansızlığını anlayana kadar Ne yazıkki  Anladığım zaman  Sensizdim...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Şahin']::text[], 8.5, '{"poet":"İbrahim Şahin","poet_slug":"i-brahim-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sen-195-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sevdikçe', 'ben-sevdikce-i-brahim-sahin-63bn7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sevda yüklü bulutlardan 

nefret dolu yağmurlar yağarmış

terkedenlerin gecelerine 

ölüm yüklü katarlardan 

yepyeni yaşamlar  akarmış 

zalimlerin  bedenlerine 

ben sevdikçe 

siz sustukça', 'sevda yüklü bulutlardan  nefret dolu yağmurlar yağarmış terkedenlerin gecelerine  ölüm yüklü katarlardan  yepyeni yaşamlar  akarmış  zalimle...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Şahin']::text[], 8.5, '{"poet":"İbrahim Şahin","poet_slug":"i-brahim-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ben-sevdikce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mücadele', 'mucadele-cetin-sen-er9nm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Artık dayanamıyorum

Gücüm Kalmadı

Yirmibeş yıllık

Yıllanmış Bacaklarım

Kambura Dönmüş

O Güzelim omuzlarım

Artık Yeter Bırak

Demeye Başladılar

Ama İhanet Edemem

Zorluklardan Yılamam

Kazanacağım

Göreceksin seni de alacagım

Gülüm sen olmasan

bunca kahır çekilmez

Ölümüne sevmeye devam

Kazanana kadar...', 'Artık dayanamıyorum Gücüm Kalmadı Yirmibeş yıllık Yıllanmış Bacaklarım Kambura Dönmüş O Güzelim omuzlarım Artık Yeter Bırak Demeye Başladıla...', ARRAY['Türk Edebiyatı','Şiir','Çetin Şen']::text[], 8.5, '{"poet":"Çetin Şen","poet_slug":"cetin-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mucadele-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mana', 'mana-cetin-sen-jhkya', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgi demek GÖRMEK

Saygı demek ANLAMAK

Mutluluk demek YAŞAMAK

Bilgi demek OKUMAK

Dost demek BULMAK

Bulupta YAŞAMAK

Arkadaş demek PAYLAŞMAK

Aşk demek UGRUNA ÖLMEK

Benliğinle, Bedeninle, Nefsinle ONUN OLMAK', 'Sevgi demek GÖRMEK Saygı demek ANLAMAK Mutluluk demek YAŞAMAK Bilgi demek OKUMAK Dost demek BULMAK Bulupta YAŞAMAK Arkadaş demek PAYLAŞMAK A...', ARRAY['Türk Edebiyatı','Şiir','Çetin Şen']::text[], 8.5, '{"poet":"Çetin Şen","poet_slug":"cetin-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/mana-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Aşk Hikayesi', 'bir-ask-hikayesi-leyla-bilgic-wl79b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalbimi ellerine bırakalı çok oldu

Sen farkında olmasan da

Yıkık harabelere dönüşü yüreğimin

Çok uzak değil

Gördüğümde seni her defasında parçalanışı yeniden

Ve toplayamadığım kalıntılar

Yıkıntılarından geriye bana kalan

Bu kadar acımasız olmalı mıydı gözlerin

Silerken  bir kere bile doyasıya bakmadığın gözlerimi? 

Ellerimi mahkum etmeli miydi sensizliğine

Ellerin, “o”nun ellerine dokunabilsin diye? 

Çığlık çığlık savaş meydanlarında yanarken ve

Her atımı yüreğimin kırık bir vazo misali

Camları delip geçerken zavallı “ben”i

Ben seni teslim ediyordum bensizliğe! 

Kendimi sana mahkum edip, 

Aşkımdan bana kalanları toplamalıyım.

Sensiz yaşamak zor, 

Benim olmasan da

Onun olduğunu bilerek yaşamak, daha kanatıyor içimi...

Gözlerimden nefret ediyorum

Kurtulabilseydim, söküp atabilseydim, katlanmak

Sensizliğine alışmak bu kadar dağlamazdı gönlümü

Alışmak, gerçeklerini bile bile yalan söylemek kendine

Ve aldatmak

Aldandığını ve aldattığını bile bile

Her gün biraz daha saplanmak  ihanet çukurlarına...

Çıkamayacağım bataklıklarda çırpınmak fayda etmiyor

“Gel, sevginle yıka beni” desem

Sevginin, “o”nun olduğu aklıma geliyor

Susuyorum.



Yazık, 

Zaman aktı gitti avuçlarımın arasından

Geçmişe teslim ettiğim her saniyede

Aşkını daha çok büyüttüm içimde

Ruhumu senin ruhunla buluşturduğumda

Habersizdi bakışların

Bir o kadar da anlamsız

Suçlamaya hakkım yoktu seni, biliyorum

Sadece

Seni senden çalıyordum kendimce

Ve kendime yeni “sen”ler yaratıyordum

Ancak yabancı “sen”ler söküp alabilirdi

Sızlayan kalbimin acısını

Almadı...

Yarattığım “sen”ler daha çok

Hissettiriyordu yokluğunun o garip soğukluğunu

Sızlayan yalnız kalbim değil

Tüm benliğim parça parça

Bedenim donuktu artık

Ben yokoluyordum, eriyordum

Yanan mum misali

Geriye yapayanlız bir beden bırakıp

Rüzgarın aldı götürdü alevimi

Her yanımı saran bir karanlık var

Üşüyorum, titriyorum

Esen rüzgarlar senin sıcak rüzgarların değil

Kulağıma “çaresizliğimi” fısıldayan

Düşman rüzgarlar, kara bulutlar

Bana benim karanlığımı anlatıyorlar

Kabulleniyorum.

Çaresizlik, 

Parmakların dokunabildiği halde

Sahip olamamakmış ellerindekine

Çaresizlik, 

Sevgilerin arasında

Mahrum kalmakmış sevdandan

Çaresizlik, 

Aşkını ölesiye yaşatırken

Senin gözleririnin kör olmasıymış

Çaresizlik, 

Ölüm karşısında değil

Aşkın karşısında kıstırmış yüreğimi

“Duvarları çaresizlikten, parmaklıkları sensizlikten

bu hapishanede

Ardında bıraktığın yüreğim hala nefes alıyorsa

Bu aşkımızın duvarları aşacağını bildiğimdendir”

Derdim korkusuzca, gözlerimi kör edebilseydim

Ya da isyan edebilseydim kadere

Şimdi kaderimin söyledikleri

Senin sessizce söylemek istediklerin: 

“ Aşkımın duvarları aşması bir hayal, inandığım

Duvarları çaresizlikten, parmaklıkları sensizlikten

bu hapishanede

ardında bıraktığın yüreğim

nefes bile almıyor artık”', 'Kalbimi ellerine bırakalı çok oldu Sen farkında olmasan da Yıkık harabelere dönüşü yüreğimin Çok uzak değil Gördüğümde seni her defasında pa...', ARRAY['Türk Edebiyatı','Şiir','Leyla Bilgiç']::text[], 8.5, '{"poet":"Leyla Bilgiç","poet_slug":"leyla-bilgic","theme":"Türk Şiiri","is_hero":false,"total_lines":86,"source_url":"https://www.antoloji.com/bir-ask-hikayesi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keman Ağıtı 1', 'keman-agiti-1-gunseli-basar-frxai', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yanıyor bir kent

sokaklarında dargın, üzgün acı çığlıklar

zayıf bir kadının gözlerinden fırlayan çıglığı

''ahh! ! ..billur şakıyan ırmaklar 

şenlik ateşleri göğün 

bilseydim, uzatırmıydım kirpiklerimi böyle! ! ..', 'yanıyor bir kent sokaklarında dargın, üzgün acı çığlıklar zayıf bir kadının gözlerinden fırlayan çıglığı ''ahh! ! ..billur şakıyan ırmaklar  ...', ARRAY['Türk Edebiyatı','Şiir','Gunseli Başar']::text[], 8.5, '{"poet":"Gunseli Başar","poet_slug":"gunseli-basar","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/keman-agiti-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşlar-2', 'yaslar-2-berk-berk-7iqqp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir çocuk var orada duran...

Beşiktaş sahilinde...

Elinde bir sigara var sonu yanan...

Denizi seyrediyor...

Belki bir deniz kızı çıkarda

Onu oradan kurtarır diye...

Soğuğa dayanıyor içine işlesede...

Gözlerinden yaşlar akmıyor...

Kalmadı ki yaş gözünde...

Bekliyor gelmeyecek olanı... 

Umutları tükensede 

Bekliyor aşkını...', 'Bir çocuk var orada duran... Beşiktaş sahilinde... Elinde bir sigara var sonu yanan... Denizi seyrediyor... Belki bir deniz kızı çıkarda Onu...', ARRAY['Türk Edebiyatı','Şiir','Berk Berk']::text[], 8.5, '{"poet":"Berk Berk","poet_slug":"berk-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yaslar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-berk-berk-tjc58', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sessiz, soğuk ve rusuzsa

Ölüm...

Ben; 

Sessiz, soğuk ve ruhsuzum...', 'Sessiz, soğuk ve rusuzsa Ölüm... Ben;  Sessiz, soğuk ve ruhsuzum......', ARRAY['Türk Edebiyatı','Şiir','Berk Berk']::text[], 8.5, '{"poet":"Berk Berk","poet_slug":"berk-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/olum-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hancı', 'hanci-kelkitli-summani-4mayu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönlüm handır ben hancı

Çok yolcular geçti bu handan

Biri saçlarıma beyaz bir tel

Kimide suratıma bir çizgi ekledi.

Yıllardır hanımdaki loş köşede 

Biri var ki bekliyordum onu

Yağmurla geldi beklediğim o

Bana mutluluk veren yolcu

Geç geldin tez gitme sakın

Biraz olsun gözlerime bakın

Senin için ayırdığım şu yatak

Sandım ki senelerce boş kalacak.

Gidecekmisin özlediğim yolcu? 

Meramın ayrılmaksa eğer...

Vedalaşmam seninle bil

Elinin sıcaklığı var elimde

Vedalaşmam seninle bil! 

Unutma şu karanlık köşede 

Sana ayırdığım yatak sıcak

Gitsende inan, hep sıcak kalacak...

Üzülerek uğurluyorum döneceksin umuduyla

Gözlerim geleceğin yolda

Geldiğinde göreceksin beni

Yine sen yolcu, ben bekleyen hancı! ..', 'Gönlüm handır ben hancı Çok yolcular geçti bu handan Biri saçlarıma beyaz bir tel Kimide suratıma bir çizgi ekledi. Yıllardır hanımdaki loş ...', ARRAY['Türk Edebiyatı','Şiir','Kelkitli Summani']::text[], 8.5, '{"poet":"Kelkitli Summani","poet_slug":"kelkitli-summani","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hanci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türküm', 'turkum-kelkitli-summani-detm3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Cihan bilsin ben bir Türküm! 

Dinim omuzumda şeref yüküm, 

Taşımak için bir adım ileri

Ya Allah deyip...

Altaylardan yola çıkmışım.

Bir kapı, bir konak uğruna hey! ..

Dağlarda, vadilerde, yollarda 

Yürürken olmuşum büklüm, büklüm

Bir sevda uğruna Diyar-ı Ruma varmışım.

Riyakar karşımdadır hep

Gün geçmez ki sormasın bana o

Türkmüsün yoksa müslüman mı? 

Şüphen mi var? Ey rezil-i rüsva

Hem müslüman, hemde Türküm

Bire mel''un şeytan...

İslam ile şereflenmiş yüce Türküm.

Ey katmerli mel''un bilesin ki...

Kalbim tek, soyum tek, Allah''ım tek

Dergahda, yolda, mizanda müslim

Gergefte, oyada, törede Türk''üm

Maziden almış ilhamı ülküm

Gözüm atide, Türkoğlu Türk''üm

Ey benim Allahım! ..

Çok şükür müslüman Türk''üm!', 'Cihan bilsin ben bir Türküm!  Dinim omuzumda şeref yüküm,  Taşımak için bir adım ileri Ya Allah deyip... Altaylardan yola çıkmışım. Bir kapı...', ARRAY['Türk Edebiyatı','Şiir','Kelkitli Summani']::text[], 8.5, '{"poet":"Kelkitli Summani","poet_slug":"kelkitli-summani","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/turkum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Defteri', 'siir-defteri-duygu-gunkut-rnxhb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgili defter, 

ne kadar da yalnız olurdun

sayfaların boş

ben olmasaydım.

kelimelerimi sana bırakıyorum

benden sonra

yalnızlığınızı paylaşın.', 'Sevgili defter,  ne kadar da yalnız olurdun sayfaların boş ben olmasaydım. kelimelerimi sana bırakıyorum benden sonra yalnızlığınızı paylaşı...', ARRAY['Türk Edebiyatı','Şiir','Duygu Günkut']::text[], 8.5, '{"poet":"Duygu Günkut","poet_slug":"duygu-gunkut","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/siir-defteri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-duygu-gunkut-pdcwb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gün tutuşa tutuşa

bir kaç dakika daha

yaşamaya çalışıyor

kentin camlarında.

bulutlar biraz küskün gibi

pek alışamadılar

bu başıboş

bu plansız ve kuralsız

sağanaklara.

kaç kişi, 

acaba kaç kişi daha

benim gibi

ancak bir yaprak kadar pürüssüz

akşamın işgali altında.

bacalar gönülsüzce tütüyor

birkaç sahipsiz kuşun

zaman zaman konakladığı

balık derisi kadar kaygan ve ıslak

kiremit çatılarda.

Yağmursuz şiir olmaz, 

şiirsiz hayat...

İnsanın kendi kuşatmasını kaldırmasıdır

yaşamayı anlamak.', 'Gün tutuşa tutuşa bir kaç dakika daha yaşamaya çalışıyor kentin camlarında. bulutlar biraz küskün gibi pek alışamadılar bu başıboş bu plansı...', ARRAY['Türk Edebiyatı','Şiir','Duygu Günkut']::text[], 8.5, '{"poet":"Duygu Günkut","poet_slug":"duygu-gunkut","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yasamak-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devran Döner', 'devran-doner-kelkitli-summani-e32vm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir kezde şu gelen pri faniye bak

İnsanlık meydanına divan kurulmuş

Binbir cefa simada, sende iyi bak

Esin için yüzüne, ibret kurulmuş.

Yürümek ister zavallı pir hayhayda

Kafa yerde sırt bel vermiş havada

Topuk dalda dizler bükük bacaklarda

Omuzuna çaresizlik, tahtı kurulmuş.

Gözler arkadan gelen civanı gözler

Yardım umuduyla belki bir şey söyler

Bizim ihtiyar boş umutları düşler

Umut dünyasına, taverna kurulmuş.

Birşey kalmaz sokakta umut bulana

Ne hayaller yenik düştü şu zamana

Düşünsen sıra sana da gelir sana

Yürüdüğün yollara, tuzak kurulmuş.

Yavrum sanma bu araba böyle gider

Devran döner, gücün biter, sersem gider

O günde gören geçer, bakan gider

İnsanlık dümenine, insan kurulmuş.

Taze çiçeksin dokunsam kırılırsın

Etrafı gözet, umarım arınırsın

Güzeli görür, güzele sarılırsın

Güzellik diyarına, pazar kurulmuş.

Sümmani iyi bak şu açık divana

İbret alki kalmasın ahir zamana

Ömrünü de katma sap ile samana

Bak umut meydanına harman kurulmuş!', 'Bir kezde şu gelen pri faniye bak İnsanlık meydanına divan kurulmuş Binbir cefa simada, sende iyi bak Esin için yüzüne, ibret kurulmuş. Yürü...', ARRAY['Türk Edebiyatı','Şiir','Kelkitli Summani']::text[], 8.5, '{"poet":"Kelkitli Summani","poet_slug":"kelkitli-summani","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/devran-doner-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kötüsü Olmaz', 'kotusu-olmaz-kelkitli-summani-rjc2h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bulursa ehlini makam

Makamın kötüsü olmaz

Sinan''ı yaparsa inan

Yapıtın kötüsü olmaz.

Lazımdır kaptana yelek

Fırsatı verirse felek

Denizler olursa melek

Kaptanın kötüsü olmaz.

Müşteri aradığını

Bulursa ihtiyacını

Pazarcı alır karını

Pazarın kötüsü olmaz.

Niyetin halis olursa

Özüne sevgi dolarsa

Gözlerin güzel bakarsa

İnsanın kötüsü olmaz.

Sümmani ne ekersen ek

Ellerin onu biçecek

Gerçekler zehir zemberek

Gerçeğin kötüsü olmaz.', 'Bulursa ehlini makam Makamın kötüsü olmaz Sinan''ı yaparsa inan Yapıtın kötüsü olmaz. Lazımdır kaptana yelek Fırsatı verirse felek Denizler o...', ARRAY['Türk Edebiyatı','Şiir','Kelkitli Summani']::text[], 8.5, '{"poet":"Kelkitli Summani","poet_slug":"kelkitli-summani","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kotusu-olmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadolum', 'anadolum-kelkitli-summani-gvcs5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Malazgirt''te açıldı kapın yurt oldun

Nazlı güzel, adı güzel Anadolum

Palikarya''ya mezar, Alperen''e yurt oldun

Nazlı güzel, adı güzel Anadolum...

Serdar''ın Alparslan''ın yolunda erenlerin

Uğruna başkoymuş Alperenlerin

Kırlarında çiçeklerin, ovaların var derin

Nazlı güzel, adı güzel Anadolum...

Toprağında izler var desen desen

Kutsalsın kutsal vatanımsın sen...

Medeniyetlere beşik oldun sen

Nazlı güzel, adı güzel Anadolum...

Saldıran sinsi sırtlanların vardı mazide

Eksik olmayacak vahşi çakallar atide...

Alparslan Gaziden torunların var şimdide, 

Nazlı güzel, adı güzel Anadolum...', 'Malazgirt''te açıldı kapın yurt oldun Nazlı güzel, adı güzel Anadolum Palikarya''ya mezar, Alperen''e yurt oldun Nazlı güzel, adı güzel Anadolu...', ARRAY['Türk Edebiyatı','Şiir','Kelkitli Summani']::text[], 8.5, '{"poet":"Kelkitli Summani","poet_slug":"kelkitli-summani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anadolum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O İnsan', 'o-i-nsan-kelkitli-summani-0ft59', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sülük olur damarına yapışır

Ürpertmeden emer; kanını o insan

Münasipse yerinde birde söver

Malınıda alır gider o insan

Ademoğlu başı kıllı tanınmaz

Yalancıdır, nankör olur düzenbaz

İnan ki yer, içer de çalar saz

Sümmani''ye gözükmesin o insan! ..', 'Sülük olur damarına yapışır Ürpertmeden emer; kanını o insan Münasipse yerinde birde söver Malınıda alır gider o insan Ademoğlu başı kıllı t...', ARRAY['Türk Edebiyatı','Şiir','Kelkitli Summani']::text[], 8.5, '{"poet":"Kelkitli Summani","poet_slug":"kelkitli-summani","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/o-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyler', 'beyler-kelkitli-summani-l6k18', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Keyfiniz yerinde maşallah! ..

Bir garibanın çocuğuyum beyler

Vatanım, milletim, namusum için

Savaşmaya, dövüşmeye, vuruşmaya

Şehit, şehit olmaya geldim beyler...

Siz veletlerinizi göndermeyin! ..

Bir garibanın çocuğuyum beyler

Şehit olursam bu topraklarda ben

Keyfiniz artacaksa zevkiniz

Mezarımın üzerinde oynayın beyler! ..', 'Keyfiniz yerinde maşallah! .. Bir garibanın çocuğuyum beyler Vatanım, milletim, namusum için Savaşmaya, dövüşmeye, vuruşmaya Şehit, şehit ol...', ARRAY['Türk Edebiyatı','Şiir','Kelkitli Summani']::text[], 8.5, '{"poet":"Kelkitli Summani","poet_slug":"kelkitli-summani","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/beyler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Gör ki Zaman', 'gel-gor-ki-zaman-alim-vedat-suner-h5877', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dağılmış eşyaların odaya

Zaman akıp gider

Masa üzerindeki saatden

Heran görünür diye

Dağlar arkasından yüzün

Hep ileri aldım ben saatleri

Gel görki zaman; 

Dünle Sevişmeyecek kadar hızla akıp eriyor...

(Salvador Dali''nin resmine bakarak dökülan bir kaç kelime..)', 'Dağılmış eşyaların odaya Zaman akıp gider Masa üzerindeki saatden Heran görünür diye Dağlar arkasından yüzün Hep ileri aldım ben saatleri Ge...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gel-gor-ki-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Riyakar', 'riyakar-kelkitli-summani-5avgr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dost aradım, insan kapısında

Nankörü çok, gerçek bulamadım

Mümin tanınır, Tanrı kapısında

Sahtesi çok, gerçek bulamadım

Hak arabası her an hazırdır

Koşacakları at da şeytandır

Dışları olgun, içleri hamdır

Araba hazır, at bulamadım

Kitap okurlar, edep erkan yok

Kaz gelmiyorsa, tavuk, tavuk yok

Deryada gezecekler vapur yok

Binecekleri yat bulamadım

Lisanlarındaki, sır durulmaz

Söyleyecekleri, keşf olunmaz

Oturacakları, yer bulunmaz

Cennet katında, kat bulamadım

Tanrı yaratmış kavim-be-kavim

Müjdeli kavim Türk''e dahilim

Muhteremlerin soyunu benim

Yaslayacağım, soy bulamadım.

Sümmani göründüğün gibi ol

Olacaksan yen içinde kol ol

Boldur alemde güzel renkler bol

Riyayı kapar renk bulamadım.', 'Dost aradım, insan kapısında Nankörü çok, gerçek bulamadım Mümin tanınır, Tanrı kapısında Sahtesi çok, gerçek bulamadım Hak arabası her an h...', ARRAY['Türk Edebiyatı','Şiir','Kelkitli Summani']::text[], 8.5, '{"poet":"Kelkitli Summani","poet_slug":"kelkitli-summani","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/riyakar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seçmek', 'secmek-berk-berk-canjn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayatım ellerimde şu an...

Gözlerimi kapasam kaçacak... 

Rüzgar çıksa uçacak... 

Yere düşürsem kırılacak...

Ne yapsam kaçacak... 

Yapmam gereken tek şey düşünmek.. 

Ne yapmak istiyorum? 

Ya yaşamak ya ölmek...', 'Hayatım ellerimde şu an... Gözlerimi kapasam kaçacak...  Rüzgar çıksa uçacak...  Yere düşürsem kırılacak... Ne yapsam kaçacak...  Yapmam ger...', ARRAY['Türk Edebiyatı','Şiir','Berk Berk']::text[], 8.5, '{"poet":"Berk Berk","poet_slug":"berk-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/secmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ülkümüz', 'ulkumuz-kelkitli-summani-rd8ww', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hakikat iki dünya var gerçekte

Biri ölümlü, öbürü ölümsüz

İstenen denge, özgürsün tercihte

Mevla''ya kulluk müşterek ülkümüz

Biz ülkücüyüz hakkı hak biliriz

Hak yiyenleri biz mel''un biliriz

Hakkın emrini biz mizan biliriz

Mizanla hizmet insanlık ülkümüz

Bu gün halkımı renk renk ayıranlar

Bu amcam, dayım diye kayıranlar

Duyun meclise kavgayı sokanlar

Birlik, bütünlüki, kardeşlik ülkümüz

Milleti yolup kuşa çevirenler

Töreyi yakıp muma döndürenler

Ey! çıkar için merhaba diyenler

Sizi islahta atide ülkümüz

Yalan ün yapmış, dolan şaha kalkmış

Yalan dolanla gerçek rafa kalkmış

Suçluyu takip, bu af ile kalkmış 

Adil devlettir temelde ülkümüz.

Bu gün banadır bilki yarın sana 

Umutsuz olma, iman et mevlana

Yaradanı sev, hürmet et insana

İnsana hürmet ebedi ülkümüz

Sümmani varis ol iki dünyaya

Dalarsan hayale, düşersin gama

Hak için çıktınsa bu gerçek yola

Hedefe varmak nihai ülkümüz.', 'Hakikat iki dünya var gerçekte Biri ölümlü, öbürü ölümsüz İstenen denge, özgürsün tercihte Mevla''ya kulluk müşterek ülkümüz Biz ülkücüyüz ha...', ARRAY['Türk Edebiyatı','Şiir','Kelkitli Summani']::text[], 8.5, '{"poet":"Kelkitli Summani","poet_slug":"kelkitli-summani","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ulkumuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezarım', 'mezarim-kelkitli-summani-v6y03', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hak vaki olur, 

Bir gün ölürsem eğer

Mezarımın üzerine gerin, 

Dalgalansın kırmızı bir ipek! 

Ve bir delik delin ortasından, 

Parlasın gökteki ay ve yıldız...

İsli puslu bir ışık istemem, 

Kandilim olsun

Üzerindeki ay ve yıldız

Alında kanım olan bayrak! 

Rahat uyumak isterim

Serin ve emin gölgende

Yabancı eli değmesin kabrime

Üzerimde dalgalan ebedi

Vatanlaşsın gölgende

Canım olan, mezarım! ..', 'Hak vaki olur,  Bir gün ölürsem eğer Mezarımın üzerine gerin,  Dalgalansın kırmızı bir ipek!  Ve bir delik delin ortasından,  Parlasın gökte...', ARRAY['Türk Edebiyatı','Şiir','Kelkitli Summani']::text[], 8.5, '{"poet":"Kelkitli Summani","poet_slug":"kelkitli-summani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mezarim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen herkesi dostmu sanıyorsun? ?', 'sen-herkesi-dostmu-saniyorsun-salih-ozalasan-h9m54', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevda dediğin neydiki dostum

Sen sevdalara yelken açıyorsun

Sevdalar sana ne gerek dostum

Sen her dost sandığına kucak açıyorsun

Yüreğinde yer varmıki sana verecek

Gönlüne sultan, yoluna yoldaş sanıyorsun

Kalmışmıki sevdayı bilen yürekler

Sen her gördüğünde yürekmi var sanıyorsun

Ağlıyorsun boşyere geceler boyu

Değermi onun için gözyaşı döküyorsun

Sinen olmuş pare pare

Her tiktak sesi veren et parçasını yürekmi sanıyorsun

Duyduğun her tatlı sözü

Yürekten döküldümü sanıyorsun

Herkes gülüp oynaşır bu alemde

Sen aptalca Cehennem''iölmeden yaşıyorsun

Y.Tar.30-11-2002 Saat 23.41', 'Sevda dediğin neydiki dostum Sen sevdalara yelken açıyorsun Sevdalar sana ne gerek dostum Sen her dost sandığına kucak açıyorsun Yüreğinde y...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-herkesi-dostmu-saniyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bıraktığın Yerdeyim', 'biraktigin-yerdeyim-suleyman-akin-w2irn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir ateş düşerde yüreğine, ararsan beni sevdiğim! 

Bil ki yoruldum, gidemedim, uzaklarda değilim.

Yarım kalmış, çaresiz sevdaların, ilk acısında, 

Oynanmış, kırılmış gönüllerin, son sancısında, 

Gidene dökülen gözyaşının,  her damlasında, 

Sevmeye küsmüş yüreğinin,  tam ortasında, 

Yokluğunla beni başbaşa bıraktığın yerdeyim.

Issız, sessiz, kimsesiz, isimsiz bir yerdeyim, 

Çaresiz, dertli, ümitsiz, sensiz  divaneyim.

Yıkılmış, eskimiş, anılarla dolu bir  viraneyim, 

Gittin, ama unutma, hep o bıraktığın yerdeyim.

Kalbim kırık, umutlar tükenmiş, yıkılmış hayallerim, 

Gönlüm yasta, gözler kurumuş, boş kalmış ellerim, 

Sevgim hüsran, şarkılar hazin, mezar olmuş gecelerim, 

Çabam nafile, esirin olmuşum, hâlâ bıraktığın yerdeyim.

Bir gün, ağır gelirde sevgin, yıkılırsa dünyan başına, 

Her gün kırılırsa kalbin, kalırsan kimsesiz bir başına, 

Çekip giderse senin gibi, acımadan, kıyma gözyaşına, 

Yıkılma sen  benim gibi, gel, hâlâ bıraktığın yerdeyim.

  (Kasım – 2002)', 'Bir ateş düşerde yüreğine, ararsan beni sevdiğim!  Bil ki yoruldum, gidemedim, uzaklarda değilim. Yarım kalmış, çaresiz sevdaların, ilk acıs...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Akın']::text[], 8.5, '{"poet":"Süleyman Akın","poet_slug":"suleyman-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/biraktigin-yerdeyim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkinci Bahar', 'i-kinci-bahar-yavuz-turhan-no7eq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sanırım ikinci bir  bahar yaşadığın.

sevgiyle kucakladığın.

özlemle beklediğin.

umudun, sevginin, artık ertelenmeyeceği, 

sıcak bir bahar.

sabahları esen rüzgarda, 

saçlarını savuracağın.

dokun duğun her çiçeğin, etrafa kokular saldığı.

avucuna aldığın toprağın, 

sana hayat verdiği.

bir ikinci bahar yaşadığın.', 'sanırım ikinci bir  bahar yaşadığın. sevgiyle kucakladığın. özlemle beklediğin. umudun, sevginin, artık ertelenmeyeceği,  sıcak bir bahar. s...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Turhan']::text[], 8.5, '{"poet":"Yavuz Turhan","poet_slug":"yavuz-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ikinci-bahar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duman Oluruz', 'duman-oluruz-aziz-pinar-ldmzr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bacalardan yağar durur

Arabalar atar durur

Nefesler onu savurur

Duman oluruz biz duman...

Çıkıp şöyle güverteye

Temiz hava dolsun diye

Sağdan soldan gelir yine

Duman soluruz biz duman...

Zevke yakar, hüzne yakar

Üst baş dona kadar kokar

İçme desen öyle bakar

Duman saçarız biz duman...

Küçücük bir odadasın

Çoluk, çocuk oradasın

Yavru ciğerler ne yapsın

Duman dolarız biz duman...

Sinemada, tiyatroda

Toplantıda, seminerde

İki ara bir derede

Duman kalırız biz duman...

Otobüste, minibüste

Yasak olsa ne farkeder

Sürücüler yakar üfler

Duman gideriz biz duman...

Duvarlara asılsada

İçilmesin istensede

Kimse bakmaz yazılsada

Duman okuruz biz duman...

İnişlerde, yokuşlarda

Korularda, ormanlarda

İzmaritler atılıda

Duman buluruz biz duman...

Derlerki kanser oluyor

Hem savuran, hem soluyan

Henüz çok azınlıktalar

İçmeyene saygı duyan

Duman oluruz biz duman...', 'Bacalardan yağar durur Arabalar atar durur Nefesler onu savurur Duman oluruz biz duman... Çıkıp şöyle güverteye Temiz hava dolsun diye Sağda...', ARRAY['Türk Edebiyatı','Şiir','Aziz Pınar']::text[], 8.5, '{"poet":"Aziz Pınar","poet_slug":"aziz-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/duman-oluruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vampir Rotası', 'vampir-rotasi-kucuk-i-skender-l7wt5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yalnızca iki el ateş edeceksin

çünkü aşk, israf değil! 

içinde gizlenen siyah beyaz hayvan

haplanmış gözlerine çöken terk-i diyar

kalbinin çıkışındaki esrarlı sudan sebep

ve tetikteki on birinci parmak

bir kancalı kurdun yorgun kayalıklara oturup

aşağılardaki kalın ve büyük bağırsakları seyrettiği

gecenin tamamlanışında senin cesaretinle

senin yüzünü bir cerrah ustalığıyla değiştiren

o yüce kinle, o masum şiddetle

yeniden

hep hep yeniden tanımlanacak! 

bir başka deyişle sen olan karşındaki cesedin

iri ve patlak göğüslerine gömülü dişlerinin arasından

kendi sahte varoluşunun

kendi kanlı spermlerinin

zamklı suretlerine doğru sürükleneceksin sersefil! 

korkma! 

yalnızca iki el ateş edeceksin

çünkü intihar, menzil değil!', 'yalnızca iki el ateş edeceksin çünkü aşk, israf değil!  içinde gizlenen siyah beyaz hayvan haplanmış gözlerine çöken terk-i diyar kalbinin ç...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/vampir-rotasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-perihan-magden-a7kpj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Pencereleri kapama

	sonra çiçekler üşüyor

Kuş kanadından bu perdeler, 

okşayabilirsin

Sağ gözümün camı kırık

	basma üstüne

	dağılır, 

	      sıçrar mavi

kirlenebilirsin

Kilisede pirinç

	sıkılgan paskalya yumurtaları

ve inan, 

	çok yorgunum bu gece

sen

	gidebilirsin

Bir yezitlik var gazoz içişinde

Beni minareden itişinde bi itlik

Bi puştluk var aşağı inişinde

Yine o karıya gitmişsin

Ders kitapları gibi durma köşelerde

Ben, 

	hatçanamız kadar cefakar

Buruşuk, 

	bumburuşuk

Üsküdar''da düşen mendil

	Ziftpekmezi

	      Karaboncuk.

	İçeri, 

	      girebilirsin.', 'Pencereleri kapama 	sonra çiçekler üşüyor Kuş kanadından bu perdeler,  okşayabilirsin Sağ gözümün camı kırık 	basma üstüne 	dağılır,  	     ...', ARRAY['Türk Edebiyatı','Şiir','Perihan Mağden']::text[], 8.5, '{"poet":"Perihan Mağden","poet_slug":"perihan-magden","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gece-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Travers', 'travers-kucuk-i-skender-rah7q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dolaşıp bir ceninin uygun dokusunu

en çok uzatarak da

geç kalmış köylü zigotu

Bir magmaya dökülen gözyaşıyla

güven ortamlarına çekilen

sik sustalılar gibi

indirdiler külün camını', 'Dolaşıp bir ceninin uygun dokusunu en çok uzatarak da geç kalmış köylü zigotu Bir magmaya dökülen gözyaşıyla güven ortamlarına çekilen sik s...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/travers-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Transs', 'transs-kucuk-i-skender-eucdu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İğne kutusunda sweet dreams

sakallı kadınlar yorucudur

tedavisi imkansız küf ve falçata

Cerrah seni sevmiyor o çok kötü

plastik örtünün altında duruyor

olmasın kanlı kız, kanlı şamata

bisturinin ucundan üflüyorlar onu yeniden hayata', 'İğne kutusunda sweet dreams sakallı kadınlar yorucudur tedavisi imkansız küf ve falçata Cerrah seni sevmiyor o çok kötü plastik örtünün altı...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/transs-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terminal', 'terminal-kucuk-i-skender-xq53l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Met cezirine takılarak buradaki cinnetin

uzaklara sürüklenen eski aşkların içinden

atlayabilir mi korkusuzca bir deli aslan

Ve böyle bir sirkin kapısında

çocuklara indirimli satılır mı

vasiyet niyetine biletler

kimse utanmaz mı pistte dönerken iskelet filler', 'Met cezirine takılarak buradaki cinnetin uzaklara sürüklenen eski aşkların içinden atlayabilir mi korkusuzca bir deli aslan Ve böyle bir sir...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/terminal-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehla', 'sehla-kucuk-i-skender-cpc82', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karanlık koridorda

çelik bıçaklar üstünde yürüyor

tahta tanrı

Sevgilinin paslı ağzında

opal gözlü sümüklüböcek

görünüyor çift kağıdın içinden

valse gidiyor tabut', 'Karanlık koridorda çelik bıçaklar üstünde yürüyor tahta tanrı Sevgilinin paslı ağzında opal gözlü sümüklüböcek görünüyor çift kağıdın içinde...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sehla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürtük', 'surtuk-kucuk-i-skender-7w0fu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uykuya doğru diz çökmüş cam kesiği bir

korkunç hayalin peşisıra

öpücüklere boğulmuş ayrılık lisanı

İşsiz dudaklarda hiç tereddüt etmeyen kelimeler

bir türlü sadede gelemeyen aşklara

akarken ve yuvarlanırken

doğruldu intikal maddi manevi sevdalı', 'Uykuya doğru diz çökmüş cam kesiği bir korkunç hayalin peşisıra öpücüklere boğulmuş ayrılık lisanı İşsiz dudaklarda hiç tereddüt etmeyen kel...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/surtuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçüstü', 'sucustu-kucuk-i-skender-1o202', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sirkime girme mecnun kalp

kendi koynunda kendini

kendi koynunun belirsizliğine atarsın

Tahrike açıktır çünkü ölümlü dünyanın hüznü

şehvetli gülleri yalayıp birer birer

acının paramparça tahakkümünde

diline dikenin kanlı zehrini katarsın!', 'Sirkime girme mecnun kalp kendi koynunda kendini kendi koynunun belirsizliğine atarsın Tahrike açıktır çünkü ölümlü dünyanın hüznü şehvetli ...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sucustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıfat', 'sifat-kucuk-i-skender-tzcvp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hüzünde kırıldım

masum suda kırılan hınzır ışık gibi

geçtim içinden hastalarımla salgın acının

Bahara doğru cehennemi gördüm

emrivaki, duru, hasbelkader yarı uykulu

zebanilerin kemikli ayak parmaklarında

ölüme sorarsanız: yalan! ben yalnızca / kendimi uydurdum', 'Hüzünde kırıldım masum suda kırılan hınzır ışık gibi geçtim içinden hastalarımla salgın acının Bahara doğru cehennemi gördüm emrivaki, duru,...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sifat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sezgi', 'sezgi-kucuk-i-skender-wkvio', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hava uğulduyor babası ölmüş sarı kuşun

gagasında eflatun bir ummanla uçarken

bilinçaltını delip çıkmış gümüş kurşun

Kalple kapatmak gerek yarayı

yoksa yaraya yayılır uzun uzun

bir Küskünlük Sarayı

çocuk takım yıldızlar, üfleyip söndürürler ışıklarını', 'Hava uğulduyor babası ölmüş sarı kuşun gagasında eflatun bir ummanla uçarken bilinçaltını delip çıkmış gümüş kurşun Kalple kapatmak gerek ya...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sezgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahnetasarım', 'sahnetasarim-kucuk-i-skender-byrvk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sesli çınar vücüdunla tırmandığın kuru sardunya

ve ağzına sığdırdığın üçüncü avcundaki acuna

silah temin ettiği saptanan, kasıklarındaki kara sauna

Gözlerine sesleniyorum: hey dikkat et, arkanda

kendi damarlarıyla sana saldırmaya

hazırlanıyor simsiyah köpükleriyle o unutulmaz şampanya

bil! ben: meçhul asker anıtınım senin, her çağdaki düellomuzda', 'Sesli çınar vücüdunla tırmandığın kuru sardunya ve ağzına sığdırdığın üçüncü avcundaki acuna silah temin ettiği saptanan, kasıklarındaki kar...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sahnetasarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Prosedür', 'prosedur-kucuk-i-skender-a1bdx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir doktor nasıl dinlerse

hastasının göğsünü, işte öyle dayalı

kulaklarım gökyüzüne

Çünkü farkındayım

ölüm büyük bir hırıltıyla başlayıp

tarifi imkansız bir hayalle son bulacak

uçurumdan sarkıtıp sepetimi hayalet bakkala bağıracağım', 'Bir doktor nasıl dinlerse hastasının göğsünü, işte öyle dayalı kulaklarım gökyüzüne Çünkü farkındayım ölüm büyük bir hırıltıyla başlayıp tar...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/prosedur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Prestij', 'prestij-kucuk-i-skender-6bfho', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sık sık açılıp kapanan bir kalp müzayedesinde

yarısı tutuşmuş bir ışığın ma''kus suretinde durur

terkedilmiş aşıklar

Uyandırmayın onları sözdeki derin uykularından

bölmeyin ''gözlerdir bir sevdanın çatalı''

diye iç geçirerek sayıklamalarını

onların indirildiği istasyonda, siz camdan bakmayın sakın', 'Sık sık açılıp kapanan bir kalp müzayedesinde yarısı tutuşmuş bir ışığın ma''kus suretinde durur terkedilmiş aşıklar Uyandırmayın onları sözd...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/prestij-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Poleatpoet', 'poleatpoet-kucuk-i-skender-85mb2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ordan seyredeceğine, hayatıma gir

dedi özel şova ait bir şiir

kasabalı, pembe yanaklı bir filme

Yüzlerce fil-karınca hikayesine

konu olmuş senin çocukluğunu sırtlayan eşcinsellerimiz

-ki öperlerken tahrik olurlar babalarının ellerini

son terbiyesizliğimiz sayılır artık, yeryüzüne çık evimizden deyişimiz', 'Ordan seyredeceğine, hayatıma gir dedi özel şova ait bir şiir kasabalı, pembe yanaklı bir filme Yüzlerce fil-karınca hikayesine konu olmuş s...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/poleatpoet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Peyderpey', 'peyderpey-kucuk-i-skender-2j6q3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çatıdaki fare, geceleri melek oluyor

ve külotlu çorap giymiş bacakları kemik

bir kadın

Tanrım! tanrım! diye inleyerek sarkıyor

göbeğimdeki misafir kuyudan içeri

doğru darmadağın

ölüm değil bu. bir sünger emiyor beni', 'Çatıdaki fare, geceleri melek oluyor ve külotlu çorap giymiş bacakları kemik bir kadın Tanrım! tanrım! diye inleyerek sarkıyor göbeğimdeki m...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/peyderpey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öbür', 'obur-kucuk-i-skender-twyxm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kayalık, kaygan bir zemin üzerine teslim edilmiş zoraki

kutuların tozlu dillerinde herbir ağızdan lanetlenen

mağaraların mihraklarındaki çıplak, abdal adamların

kinayelerini sevmez insana muhtaç gökcisimciklerinde

mahşeri azgın bir karı gibi koynuna almış tabiatların

kılıksız çelişkilerinde apansız beliren ruhsatsız endişe; 

zimmete geçirilen şaibe! der! 

akılda sıkı sıkıya tutulan muhbir buğu

ve henüz adı konmamış hayvanlar

şimdi nerelerde birbirlerine geçit verirler de

ölüm, elinde yanan bir kibrit çöpüyle durur

ilk ateşi tutuşturduğu cehennemde; 

tek şıklı o çirkef kutsanışın ileri geri gidip

gelen dansöz göbeğinde sıkışıp kalmış eski mi eski

artık kimsenin sözünü etmediği paslı ziller çaldı mı

doğru kainat sınıfına derse koşan mikro talebelerde

kalmış olmasın kibritlerin zoraki kutularındaki

çocukluk anılarım hamamböcekleri;', 'kayalık, kaygan bir zemin üzerine teslim edilmiş zoraki kutuların tozlu dillerinde herbir ağızdan lanetlenen mağaraların mihraklarındaki çıp...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/obur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oturmaodası', 'oturmaodasi-kucuk-i-skender-ob3hu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Blleksiz bir tanrıdan korkuyorum yavrum

onun için

sana elveda deyişim

İçime saklanmana gerek yok! 

ne kadar kaçarsan kaç evrenden

ardında, astrolojinin bütün body-guard''ları seferber

unutma! kediler yalnızca balık burcu yerler', 'Blleksiz bir tanrıdan korkuyorum yavrum onun için sana elveda deyişim İçime saklanmana gerek yok!  ne kadar kaçarsan kaç evrenden ardında, a...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/oturmaodasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otopark', 'otopark-kucuk-i-skender-xned1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Belli, karar vermiş, bir metafora görünecek

senin soyunduğun gecede kan bulurken kendine

kabul edilmez tenlerin ağında soğuyan örümcek

Güzel çocuk! cevapsız bırakılıyor bak çıplaklığın! 

uygunsuz arzuların insanı cezbeden gerçeğinde

sen herşeyden önce, kaybettiğin savaşa dargındın! 

boyalı aşk bakışlarında, kirpiklere takılıveren yangın!', 'Belli, karar vermiş, bir metafora görünecek senin soyunduğun gecede kan bulurken kendine kabul edilmez tenlerin ağında soğuyan örümcek Güzel...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/otopark-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otoban', 'otoban-kucuk-i-skender-32rqz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kar, buza tutunursa yaşar! lacivert

parmaklıklara çivili prenslerin hislerindeki

buhurdandan üfleniyor parçalı bulutlu suçlar

Sanırım, aranıyorum uzunca bir vakittir

velakin, ağzıdaki delidolu akrepli tedbir

dolunayda haleleri aralar

düşük voltajda hala çaresiz kurtadamlar', 'Kar, buza tutunursa yaşar! lacivert parmaklıklara çivili prenslerin hislerindeki buhurdandan üfleniyor parçalı bulutlu suçlar Sanırım, aranı...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/otoban-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ortasöz', 'ortasoz-kucuk-i-skender-kq2wn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Göt deliğindeki yüce ruh! 

ferah bir antreye bırakıldı

karakutu

Uyuyan güzel delikanlılar

sertleşen çükleriyle selamladılar

kan kırmızı kurdu

ölürken ''hoşçakalın'' demedi kimse', 'Göt deliğindeki yüce ruh!  ferah bir antreye bırakıldı karakutu Uyuyan güzel delikanlılar sertleşen çükleriyle selamladılar kan kırmızı kurd...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ortasoz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Opera', 'opera-kucuk-i-skender-17fdz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ayak bileğindeki halhal

kutsal bir kitap gibi parlarken

derin vücuduna

Çözümsüz bir öç duygusu

ile dolaşıyor kötü melekler

darmadağın hayata sığdırdığın dudaklarına

eğilip öpüyorum nehri', 'Ayak bileğindeki halhal kutsal bir kitap gibi parlarken derin vücuduna Çözümsüz bir öç duygusu ile dolaşıyor kötü melekler darmadağın hayata...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/opera-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Naturel', 'naturel-kucuk-i-skender-48kii', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Pet Shop Boys''a...

Yüzüm antik bir kabartma gibi kaleye gitti

ısıtılmış böceklerle birleşme anında, 

prensip olarak yalnız bir aşkla.

Yaramaz çocuklar kapalı ağızlarında bataklık tutar

sanki hangi şair yazdığı şiir için ölür

prensip olarak yoğun ateş altında.

boş arazide reklam almaz ecnebi cinler', 'Pet Shop Boys''a... Yüzüm antik bir kabartma gibi kaleye gitti ısıtılmış böceklerle birleşme anında,  prensip olarak yalnız bir aşkla. Yarama...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/naturel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Miyandar', 'miyandar-kucuk-i-skender-fg9t7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kuru dudaklarla yaklaştı ince bir ruh halinin yayıldığı

- Kaybolduk, dedi, yere yıkıldı kadifevazogözler-

ne kadar da uslu sırtında taşıdığı yaralı karanfil

Uzatıp döktüm iksiri kusur dudaklarına

dayayıp dinledim kalbinin üstünde kulağımı

geliyordu tren -Kim bilir, diye mırıldandım

belki de bir sevgilinin geceleri diken üstünde diken diken', 'Kuru dudaklarla yaklaştı ince bir ruh halinin yayıldığı - Kaybolduk, dedi, yere yıkıldı kadifevazogözler- ne kadar da uslu sırtında taşıdığı...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/miyandar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mes''ut', 'mes-ut-kucuk-i-skender-cnm0e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uyuyor suyun üzerindeki jelatin çocuk

başı yosunlara gömülü

çıplak bedeni akşam sefası

Gördüğü rüya kim bilir kaçıncı kopya

çıktığı yolculuk eski bir romandan alıntı

bindiği gemi sanki battı batacak

udun kavminde, belli, bu çocuk duman olacak', 'Uyuyor suyun üzerindeki jelatin çocuk başı yosunlara gömülü çıplak bedeni akşam sefası Gördüğü rüya kim bilir kaçıncı kopya çıktığı yolculuk...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/mes-ut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mesaj', 'mesaj-kucuk-i-skender-vvpnt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Vadiye vahşi veda, kızgın sularla iniyor

sünger kayalıkların uğultusuna

eşlik ediyor ırksız güneş

Telaşlı temasların temsili, kanyonda

boynuzlu dağ çıtırtılarına doğru

koro halinde yaklaşıyor işte

tabiat, tek gözlü cin gibi ayakucumda', 'Vadiye vahşi veda, kızgın sularla iniyor sünger kayalıkların uğultusuna eşlik ediyor ırksız güneş Telaşlı temasların temsili, kanyonda boynu...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/mesaj-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir', 'bir-kucuk-i-skender-ei691', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gel süs! çılgınlığımı gecele

son fırsatım ben! beni benimle büyüle! 

kendimden çıkan yılan! sok beni büyüyle! 

nerdesin süs! nasıl bir haberim bilemem! 

ters mi döndüm, doğru mu yüzüm! 

kime hamileyim! kim doğurur beni yeniden! 

yüreğimin civarlarındaki küle gideceğim! 

aşk! seni kirime sabitleyeceğim! istiyorum! 

bir tutuşma biçimiyim, Kuran''ım, ateş rahlemdedir! 

çığrından çıkan bedenimi çağına iade ediyorum! 

buz tutmuş bir ruhum ben! 

erirsem geri dönemem!', 'gel süs! çılgınlığımı gecele son fırsatım ben! beni benimle büyüle!  kendimden çıkan yılan! sok beni büyüyle!  nerdesin süs! nasıl bir haber...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Burç', 'burc-kucuk-i-skender-ka40n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yorucu böceklerin yaşlanışlarında

gizli durur mu acaba

bir sineğin gidip gelip cama çarpışı

Ve aslında insandan sonra hayat var mı

diye sorar mı bir çocuk

tanıştığı ilk manolyaya

yelelerine güneş takar mı çapkın atlar', 'Yorucu böceklerin yaşlanışlarında gizli durur mu acaba bir sineğin gidip gelip cama çarpışı Ve aslında insandan sonra hayat var mı diye sora...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/burc-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deliimam', 'deliimam-kucuk-i-skender-7ulz9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İncecik bir çirkinliğe dönüşüyor bazı gözlerim

ikinci el kentin bütün mühürlü denizfenerlerine

intihar mektuplarını bırakmışım eski bir aktörün

Siyah duvarlara çarpa çarpa öldürdüğüm horoz

şimdi kendinden başkasını uyandırmaz

şöyle bir uzanıyorum da huzur içinde musalla taşıma

biliyorum, benim cemaatim dağ geyikleridir yalnızca', 'İncecik bir çirkinliğe dönüşüyor bazı gözlerim ikinci el kentin bütün mühürlü denizfenerlerine intihar mektuplarını bırakmışım eski bir aktö...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/deliimam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilemma', 'dilemma-kucuk-i-skender-68o2i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kavrulur günbatımına doğru

çapkın kadınların günahkar kasıkları, 

bir şeytan çıkartma ayinidir kasıkları, 

ki: el uzanır, ruh bulanır

suspus ormanların en çetrefil

en mukaddes

en itinalı

en muazzam

en kanlı yanışlarında, 

uykuya giren şehirli çocuk yılanın tuttuğu

niyet gibi, masumiyetinden gü toplayan bir rüyada

en tehlikeli

en ahlaksız

en muazzam

en kanlı rüyada

yokluk ile varlık arasındaki şahane boşluğa doğru! 

belki de yılan yalnızca

ayağa kalkıp suçu üstüne alamadığı için suçlu!', 'kavrulur günbatımına doğru çapkın kadınların günahkar kasıkları,  bir şeytan çıkartma ayinidir kasıkları,  ki: el uzanır, ruh bulanır suspus...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dilemma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Döpiyes', 'dopiyes-kucuk-i-skender-0oacb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kopuyor ressamla heykeltıraşın dostluğu

bakarlarken

bir yeni ölünün ağzından içeri

Ressam diyor ki: bu, paletteki deliktir

atılıyor heykeltıraş: 

hayır! bu, olsa olsa çekicin sonsuzluk madeni

biri boyarken öbürü yontuyor cinin cesedini', 'Kopuyor ressamla heykeltıraşın dostluğu bakarlarken bir yeni ölünün ağzından içeri Ressam diyor ki: bu, paletteki deliktir atılıyor heykeltı...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dopiyes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşük', 'dusuk-kucuk-i-skender-rhnns', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yasak kartların çevrildiği

beyaz dillerin çemberinde

alkışlanan kara haber

Bir filmin sonunu önceden bilmek

gibi bir boşluğu gerisin geri

dönmek

başımı dayayacağım omuzlara mayın döşemişler', 'Yasak kartların çevrildiği beyaz dillerin çemberinde alkışlanan kara haber Bir filmin sonunu önceden bilmek gibi bir boşluğu gerisin geri dö...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dusuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Embriyo', 'embriyo-kucuk-i-skender-5u2p2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sokularak soğuğa ileri çıkışından

bir uzun saçlı yelkenin

notalara ayak atarken sihir

Şimdi nerede ağlıyor billur

kanatırken son rüzgarın

sessiz kimliğini

cesedi tanınmayacak haldeyken aşkın', 'Sokularak soğuğa ileri çıkışından bir uzun saçlı yelkenin notalara ayak atarken sihir Şimdi nerede ağlıyor billur kanatırken son rüzgarın se...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/embriyo-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emin', 'emin-kucuk-i-skender-cfnm3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Rüyalardan geçerek gelen

engerek buhar çizmekte

gaz odası taslaklarını

Bir kolun uyku anında

kıvrılıp örtmesi gibi yüzü

aşk örtüyor hüznü

şeref madalyalarından tanıyorum gökyüzünü', 'Rüyalardan geçerek gelen engerek buhar çizmekte gaz odası taslaklarını Bir kolun uyku anında kıvrılıp örtmesi gibi yüzü aşk örtüyor hüznü şe...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/emin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fassbinder', 'fassbinder-kucuk-i-skender-4lbix', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kanı dönmüş işte. maymun ne yapsın.

denizciyse.. çiçekleri bilmez o. beyaz

bir satırla geldiğinde, çocukların gözü

önünde

         sürdürdüğü ıslaklık, hatta suç..

okşanır. uzak. renksiz meyvaları var.

istemem. caz durur. sarılır. danseder.

kim. nerede mezarı. öldürülmüş mü.

elinde bir bebeğin kafası

onu ekleyeceği bir sonbahar arar. bulsa.

takacak. anlıyor musun. gitmeyeceksin.

öp. pişir. misafirler aç / misafirler pis.

bant sardı. onu konuşturamadılar. onu

götüremediler. çiçekleri bilmez o.

saten miço. leylak miço. orospu miço.

geminin kıçında miçonun adı yazılı

spermle. geminin canı acıyor.

filikaları yakmış kadınlar. kan dönmüş işte.', 'kanı dönmüş işte. maymun ne yapsın. denizciyse.. çiçekleri bilmez o. beyaz bir satırla geldiğinde, çocukların gözü önünde          sürdürdüğ...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/fassbinder-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fincan', 'fincan-kucuk-i-skender-scpg4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kontrolden çıkmış aşk etkinlikleri

için baktığım yerlerden uzaklar

nasıl da köpük köpük

Zararına sevilmiş erkeklerden

geriye kalan diz çöküşler

eğeler törpüler zımparalar

hatırlıyorum o kadar ıssız değildi maceralar', 'Kontrolden çıkmış aşk etkinlikleri için baktığım yerlerden uzaklar nasıl da köpük köpük Zararına sevilmiş erkeklerden geriye kalan diz çöküş...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/fincan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Füme', 'fume-kucuk-i-skender-krov0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kadını öldürmeme yardımcı ol

dedi tek basamaklı muhakeme üzerinde

kırmızıya tutunarak ayakta durmaya çalışan

gün adamı rüzgarı entarilerken de, geride

ovaları ağ yapan bilicilerin yorgunlukları

birikmişse de onları satın alarak geçinen

saatten çocuğun kırparak geçtiği

sözlü denizlerin upuzun yarıkları boyunca

uzanmış uyuyan büyük böceklerin ağızları

nı birleştiren siyah kalın çizgide yürüyen abbas

gereken gerçeği harekete geçirmiş ve

çarklarla bobinlerin birbirlerine karışmasını

önleyen suni izdivaca tanık olmuştu bile büyü

aracılığıyla; o gürültüde büyümeyle meşgul

olma inancı benimser benimsemez rah

iplerle imamlar özel bir dans ederlerken ben

ayakparmaklarımın ucunda dönüyordum arda ben; ben

döndükçe kafatasımda ters yöne çevriliyordu beynim

cesaretini yitirmiş topraklar güllerini

uzatarak uzlaşıyorlardı lalelerini, el

meyvası veren ağaçların dallarına güceniyor

ölülerini taşıyan kuşlarla, aşk

-ateşin kasasında saklıyordum- şarkılarımı

gelmiyordu

açılışıma davetli yeryüzü', 'kadını öldürmeme yardımcı ol dedi tek basamaklı muhakeme üzerinde kırmızıya tutunarak ayakta durmaya çalışan gün adamı rüzgarı entarilerken ...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/fume-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garden', 'garden-kucuk-i-skender-e2ty3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Siyah havuçların arasında haç ve

ikisi çıplak suçsuz üç konfeti

mağduru

Fırfır, lame ve rengarenk kordelalarla

süslü bir ölümün

ağzında sakladığı tek atımlık soluğu

toprak da veriyor insana', 'Siyah havuçların arasında haç ve ikisi çıplak suçsuz üç konfeti mağduru Fırfır, lame ve rengarenk kordelalarla süslü bir ölümün ağzında sakl...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/garden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haram', 'haram-kucuk-i-skender-zwjur', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'En gelişmiş suç aletiyle kainat

ne kadar bir hızla çarpabilir

metruk alnıma

İade edilmesi mecburi biçimsizlik''te

hangi sonsuzluğu alaya alabilir

çatalsız sataşma

mahluk: silindir yumurta', 'En gelişmiş suç aletiyle kainat ne kadar bir hızla çarpabilir metruk alnıma İade edilmesi mecburi biçimsizlik''te hangi sonsuzluğu alaya alab...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/haram-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kademe', 'kademe-kucuk-i-skender-rqsmf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Boş bir sinema salonunda oynuyor

tek başına çektiğim siyah beyaz

sessiz son film

Ne kuşları seyreden kedi kadar heyecanlıyım artık

ne de o kuşlar kadar

salak ve kendine hakim

kamera stop! yalnızlığıma kapalı gişeyim', 'Boş bir sinema salonunda oynuyor tek başına çektiğim siyah beyaz sessiz son film Ne kuşları seyreden kedi kadar heyecanlıyım artık ne de o k...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kademe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kancalıkurt', 'kancalikurt-kucuk-i-skender-c0zas', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kuşatılmış kalede hayatta kalan son asker

sağ ve sol elini koyuyor nefes nefese

bir terazinin iki kefesine

Bilgelerin beslediği binlerce erkek tavus

kuyruklarını açıyor

kulelerin kana bulanmış gece sessizliğinde

kılıcına işiyor galip komutan mahzun, aşağıda, lime lime', 'Kuşatılmış kalede hayatta kalan son asker sağ ve sol elini koyuyor nefes nefese bir terazinin iki kefesine Bilgelerin beslediği binlerce erk...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kancalikurt-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karaltı', 'karalti-kucuk-i-skender-831aq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bak! gece geliyor! sakın üstüme basma! 

bronz boynuzlarımda kedi tiryakileri! 

terkedildiğim kentte benim de bir küfür bütçem var! 

sonuna kadar yabancıyım suratımdaki çukura! 

yatağımdaki boy aynası: bu otelin bütün gölgesi, 

dışardaki adamın çocukluk çetelesi! 

geri dönmeden önce bir mektup yazıp postalamalı! 

zarfın içine kulaklar, gözler ve sözde yeminler de koymalı! 

ben buralara sevmek için gelmiştim

vuruldum gönlümün oturumunda ayağımın tozuyla! 

sevgili belirsiz! 

bir tıkırtı olur suda büyüyen ur

bak! gün gelir, fedakar bir bıçakla kesersin

ortadan ikiye bölünür ruhundaki tuhaf karaltı

kasıklarında, müstesna sahibinin imzası: 

simsiyah bir 666!', 'bak! gece geliyor! sakın üstüme basma!  bronz boynuzlarımda kedi tiryakileri!  terkedildiğim kentte benim de bir küfür bütçem var!  sonuna k...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/karalti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşmekeş', 'kesmekes-kucuk-i-skender-8k77k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalçalarında o serçenin yüzükoyun yatan

yolunmuş tüyleri üzerinde

bir top mermisini beklerken, pıtırtı

Sonra yuvarlanırken gagasyla kanatları arasında

kötü budanmış gökkuşağı

yağmurun en toy tarafından

bazı delikanlılarda seraptır göbekdeliği', 'Kalçalarında o serçenin yüzükoyun yatan yolunmuş tüyleri üzerinde bir top mermisini beklerken, pıtırtı Sonra yuvarlanırken gagasyla kanatlar...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kesmekes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kilise', 'kilise-kucuk-i-skender-gg0k9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tarafsız iki atom taneciği gözleriyle

çan kulelerine tırmanırken günün

en güzel saatleri

O, elinde eline yakışan çivi izleriyle

avucunda su taşıyamayan bir peygamber

olarak alındı son akşam yemeği menüsüne

servisi yaptı emektar hizmetçi anne', 'Tarafsız iki atom taneciği gözleriyle çan kulelerine tırmanırken günün en güzel saatleri O, elinde eline yakışan çivi izleriyle avucunda su ...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kilise-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kolera', 'kolera-kucuk-i-skender-186na', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kaskatı dişilik organıyla dayanmış

kentin bütün girişlerine

küstah, yarısı yanık orospu

Terkedilmiş adli tıp binası göz

lerinde tedbiri elden bırakmayan

bir ümidin otopsisi

korteji selamlıyor ölümsüz orospu uzaktan, sinsi sinsi', 'Kaskatı dişilik organıyla dayanmış kentin bütün girişlerine küstah, yarısı yanık orospu Terkedilmiş adli tıp binası göz lerinde tedbiri elde...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kolera-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köşedendönence', 'kosedendonence-kucuk-i-skender-up2et', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ters serilmiş bir halının deseni olmasın sakın bütün tarih

tanrının yarıcanlı kalmış tahtından, lunaparktaki

komünist tuvalete doğru uzanan

Bir yaralı sarrafım orada kendine değer biçemeyen

kentin altında sade gazoz-beyaz leblebi var

ve kurasız yuvarlanıyorum tek atın döndüğü atlıkarıncadan

her aşkta dönmedolaptayım ve kesiliyor elektrik ben en tepedeyken', 'Ters serilmiş bir halının deseni olmasın sakın bütün tarih tanrının yarıcanlı kalmış tahtından, lunaparktaki komünist tuvalete doğru uzanan ...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kosedendonence-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurabiye', 'kurabiye-kucuk-i-skender-u0quk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'tülay''a

Ani bir atakla gelişti aşk

soğuğa diş geçiren köpeğin güneşi erise

bakışları, çizgileri gün basacak

Evet, ilk ben parçalamıştım atomu

takla atan otomobilden

son ben çıkartıldım ölü olarak

duyuyor musun, ısınacağı bir gerçek arıyor düş', 'tülay''a Ani bir atakla gelişti aşk soğuğa diş geçiren köpeğin güneşi erise bakışları, çizgileri gün basacak Evet, ilk ben parçalamıştım atom...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kurabiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşburnu', 'kusburnu-kucuk-i-skender-9jdms', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Krupiye köşkünde eski bir minder

yüzüdür nasırlı hatıralarıyla o

nahoş kalender

Elinde tuttuğu mor kadehte

zehirli bir meyva suyudur

çocukluk aşkı küçük İskender

bilakis, papağana doğru kalkar geç oldu diye Bizans', 'Krupiye köşkünde eski bir minder yüzüdür nasırlı hatıralarıyla o nahoş kalender Elinde tuttuğu mor kadehte zehirli bir meyva suyudur çocuklu...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kusburnu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Sinek', 'kucuk-sinek-kucuk-i-skender-khq9k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'körelmiş

düzenlenen gözlerdeki aşk ve kırgınlık varyetesi, 

saplı duran kurşun, saplı duran bıçak, saplı duran neşter

suya saplı duran balık, göğe saplı duran şimşek

unutmuş, kalbi bir pelerin gibi tutup savuran sesi..

Tabiattan geçen yolcu

düşürmüş içindeki anı.

buğulanmış bir tene

çocuk, 

yazarken adını: 

arkalarına dönmüş nesneler.', 'körelmiş düzenlenen gözlerdeki aşk ve kırgınlık varyetesi,  saplı duran kurşun, saplı duran bıçak, saplı duran neşter suya saplı duran balık...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kucuk-sinek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lucky Luke', 'lucky-luke-kucuk-i-skender-7fhnz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir tür sana yatkın canlı

gibi ilerledim adım adım

buzdolabındaki son tene

alkolün gerdiği ipteki cambaz

düşerken su ile yaralanır ve

sürtündüğü hava ile iyileşirmiş

ya, ben, çağrıldığım her ruh

seansında, bütün sorulara

EVET

dedim. Hatırla! biz hep

reenkarnasyonlarımızda

iki kızkardeştik gerisin geri..

hatta bir keresinde..

ah, unuttum! Sır''dı! Bağışla!', 'bir tür sana yatkın canlı gibi ilerledim adım adım buzdolabındaki son tene alkolün gerdiği ipteki cambaz düşerken su ile yaralanır ve sürtün...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/lucky-luke-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maske', 'maske-kucuk-i-skender-ynffv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaralı ateşlere gelen söz

parçalanmış atların sırtında

ödeşiyor çağının tırmanışıyla

Yırtılıyor yüzün altındaki

büyük kas yığını ve

dantel lif

yabancıyı bu gece herkes tanıyor', 'Yaralı ateşlere gelen söz parçalanmış atların sırtında ödeşiyor çağının tırmanışıyla Yırtılıyor yüzün altındaki büyük kas yığını ve dantel l...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/maske-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Matematik', 'matematik-kucuk-i-skender-0znoh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Köpeğin havladığı spiral

dönerek düşüyor üstüne

simsiyah bir kristal harın

Son kez öpüşüyorlar elleriyle

dumanı yararak ilerliyor

kan kantosu

müzik kesilince duruyor su', 'Köpeğin havladığı spiral dönerek düşüyor üstüne simsiyah bir kristal harın Son kez öpüşüyorlar elleriyle dumanı yararak ilerliyor kan kantos...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/matematik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Menenjit', 'menenjit-kucuk-i-skender-ghsxa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yorulur bazı soruların soru işaretleri

takılırken kancalarına

terkedilmiş hayatların bedeli

Ertelenmiş cinayetlere katil yetişmez

kimse göstermez bir başkasına

kullandığı son cinayet aletini

hiçbir hayvan teslim almaz kendini', 'Yorulur bazı soruların soru işaretleri takılırken kancalarına terkedilmiş hayatların bedeli Ertelenmiş cinayetlere katil yetişmez kimse göst...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/menenjit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsimidir', 'mevsimidir-attila-i-lhan-qkcno', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'mevsimidir

müphem bir meltem yoklar dal uçlarını

	gizlice ürperir yaseminler

körfezde deniz dalgın

bilinmez hangi aşktan arta kalmış

	vahim bir yalnızlığı dinler

mevsimidir

artıke erken kararır sular

her biri bir bulut ardına sinmiş yıldızların

korular terk edilmiş

	ağaçlar duman duman

	     yalılar tenha

	kanlıca ilk yağmurla serinler

mevsimidir

	nedense ölmeye heveslenir insan

uzaya

	bir avuç yıldız tozu gibi savrulmaya

	rayından çıkmıştır yaşamak

	bir eskimişlik duygusu nereye baksan

gücü yetmez kimsenin kimseyi kurtarmaya

çünkü ne güzeller

	zehir zemberek güzeldir artık

ne zehir zemberek çirkindir

	     yeni çirkinler', 'mevsimidir müphem bir meltem yoklar dal uçlarını 	gizlice ürperir yaseminler körfezde deniz dalgın bilinmez hangi aşktan arta kalmış 	vahim ...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/mevsimidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Gemileri', 'yagmur-gemileri-attila-i-lhan-redff', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'o gemiler ki yağmur taşır

gece sabaha karşı birden

korkularımıza bulaşır

gök gürültüsüyle derinden

o gemiler ki yağmur taşır

gözümüz kamaşır şimşeğinden

o gemiler ki başkalaşır

çelişkinin diyalektiğinden

gücü çok sonra anlaşılır

insana eklediğinden

o gemiler ki başkalaşır

gelişir değiştirdiğinden

o gemiler ki şafağa ulaşır

ümitlerimizin ateşinden

devrimden devrime yanaşır

nasıl da büyür kendiliğinden

o gemiler ki şafağa ulaşır

bir çığlık gibi bedreddin''den', 'o gemiler ki yağmur taşır gece sabaha karşı birden korkularımıza bulaşır gök gürültüsüyle derinden o gemiler ki yağmur taşır gözümüz kamaşır...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yagmur-gemileri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanılsama', 'yanilsama-attila-i-lhan-iww3o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hiç görmediğim gökler vahşi yeşil

ağır şehirler oturmuş altına

içinden sular geçiyor erimiş cam

parıltıdan göz gözü görmez olmuş

bu kız sevdiğim o kız değil

bir başka yüz takmışlar suratına

kendisiyle kavgalı sabah akşam

kirpikleri maviymiş dudakları mormuş

insanlarla yanılmış eski sahil

şarkılar asılı günün her saatına

hangi rastladığıma kimi sorsam

kimin kim olduğunu bilmiyormuş

denizin üstü yıldız çil çil çil

dağların arkasında saklı fırtına

kötü bir rüyadaymışız tamam

ne yapsan bir sona ermiyormuş', 'hiç görmediğim gökler vahşi yeşil ağır şehirler oturmuş altına içinden sular geçiyor erimiş cam parıltıdan göz gözü görmez olmuş bu kız sevd...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yanilsama-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen-ler', 'sen-ler-baris-akm-9fihv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen, sen ve sen ne kadar çoksun

Usandım sen-le uğraşmaktan

Yıllar varki sen-in için var insan

Savaş sebebi sen-in doyumsuzluğun

Özene bezene yeşillenen Dünya

Dudaklarının arasında sen-in

Sen iyisin-kötüsün, 

Ya da güzel-çirkin veya zengin

Sen istediğin kadar yaşanır-sın

Bir ahu, bir engerek-sin

Yahut bulunamayacak hint kumaşı-sın

Sen ne kadar güçlü ve ulaşılmaz-sın

Adem oğlu-kızı çok çekti sen-den

Hiç dinmeyecek acılar denizi-sin

Sen için yırttık okyanuslarını Dünya''nın

Gökkuşağını serdik de yaranamadık altına ayaklarının

Sayende bağlarını kopardık tütün balyalarının

Sen-in elinde tüpleri yangınların

Nerede gizli sırrın? 

Mümkün mü çözülme ihtimalin? 

Gün gelip sen-siz yaşanacak mısın? 

Biz ben-ler ölümünün eşiğine geldik sen-sizliğin

Yorgunluğunda her geçen sen-siz günün

Hüsranlar topluyoruz akşamleyin

Sen, sen ve sen, kıymetini bilin sen olmanın

Şan-şöhret, para-pul ve ben sen-in kölen

Bilesin gün gelecek sen-de''''sen''''diyeceksin

Bir sen-in peşinde lime lime dökülecek etin

Göreceksin ıstırabını, sen diye inleyenlerin 

Anlayacaksın kıymetini namludaki son kurşunun

Ey sen-ler artık sevinin

Bugün kına gecesi, yarın düğün 

Smokinler ve en güzel tuvaletler sandıktan çıksın

Bu günden öte bayramı her gün sen-lerin

Atlı karıncayla dönün, çocuklar gibi şenlenin

Düşlerini vurdum sen-lerle açılan gözlerimin', 'Sen, sen ve sen ne kadar çoksun Usandım sen-le uğraşmaktan Yıllar varki sen-in için var insan Savaş sebebi sen-in doyumsuzluğun Özene bezene...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sen-ler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün', 'bugun-selvi-celik-2ed50', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sende biliyordun kirmizi gülleri sevdigimi, 

Bahcemdeki güllerime konan kelebekleri kovmadim, 

Hic kiskanmadim, varsin onlarda koklasinlar.

Bugün beni sevsin diye, etrafimda dönen masun bakisli

    kedimi oksayip sevmedim.

Hic aglamadim bugün.

Hic tasa etmedim bugün.

Ne penceremin kösesinde sen geleceksin diye, 

Yollarini beklerken gecmisimi düsündüm, 

Ne kaygi ettim gelecegimin umutsuzligina.

Nede seninle papatya dolu kirlarin üzerinde sarmas dolas hayalini kurdum.

Oooff...

Bugün zaman durdu saatimin akrebi hic kipirdamadi sanki.

Ne yillarca gögüs gerdigim hayatin agirligini, 

Nede bedenimin yorgunlugunu hissettim.

Bugün aynamla yüzlesmedim.

Saclarimin aklarina bakim ela gözlerimden damlalari sizdirmadim.

Ne güclü oldugumu, 

Nede zaafiyetimi hissetim.

Bugün hic birsey dert etmedim.

Sanki bir an var olusu ve yoklugu yasadim.

Bugün öylesine bügun''ü yasadim...', 'Sende biliyordun kirmizi gülleri sevdigimi,  Bahcemdeki güllerime konan kelebekleri kovmadim,  Hic kiskanmadim, varsin onlarda koklasinlar. ...', ARRAY['Türk Edebiyatı','Şiir','Selvi Çelik']::text[], 8.5, '{"poet":"Selvi Çelik","poet_slug":"selvi-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bugun-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadın', 'kadin-aybike-ferda-kilic-j77vj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Soluk yüzlü bir sonbahardı sevdiği kadın

Nasırlı parmaklarına bakmaya doyum olmazdı kadının

Çoktan eskitmişti biçare yosmalıkla kadınlığını.', 'Soluk yüzlü bir sonbahardı sevdiği kadın Nasırlı parmaklarına bakmaya doyum olmazdı kadının Çoktan eskitmişti biçare yosmalıkla kadınlığını....', ARRAY['Türk Edebiyatı','Şiir','Aybike Ferda Kılıç']::text[], 8.5, '{"poet":"Aybike Ferda Kılıç","poet_slug":"aybike-ferda-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/kadin-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soguk Gece', 'soguk-gece-ozgur-arslan-7mc45', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Cansiz bedenlerin yattiği mezarliklar, 

karanlik, korkulu, bilinmiyen dehlizler, 

Hayat çemberini tamamlayan toprak.

Ağaçlar, otlar, gecenin çocuklari, sevilmeyen yaratiklar, 

duyulmamiş melodiler ile ölüm türküsü, 

gerçeğin kendisi, kimsesiz, sahipsiz mezarlar.

Uğulduyan rüzgar, gıcırdayan kapı, 

dans eden  alev parçası, 

gecenin büyüleyen yüzü, 

sırları kapatan zifiri karanlik.

Büyük hesaplaşmaya hazırlık, 

cevapsız kalan sorulara yanit arayişi, 

gecenin donuk hüznü ile yoğrulan bir baş ağrısı, 

Hepsi sonsuza giden yolun acisi, bilinmezliği, vesairesi......', 'Cansiz bedenlerin yattiği mezarliklar,  karanlik, korkulu, bilinmiyen dehlizler,  Hayat çemberini tamamlayan toprak. Ağaçlar, otlar, gecenin...', ARRAY['Türk Edebiyatı','Şiir','Özgür Arslan']::text[], 8.5, '{"poet":"Özgür Arslan","poet_slug":"ozgur-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/soguk-gece-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sari şeker', 'sari-seker-ozgur-arslan-nvc1b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sessiz gecelerde yanliz kaldiğimda, 

dostlarin uzakta olduğunda bile yanimda.

Ezberden değil gerçekten, 

içinden geldiği gibi yaşayan.

Rastlanti eseri tanidiğim ama

kolay kolay kaybetmek istemediğim, 

Acisini, dertlerini dinlediğim, 

zaman zaman güldüğüm, güldürdüğüm.

Yanimda olduğunda sevindiğim, 

sari şekerime sevgilerle...', 'Sessiz gecelerde yanliz kaldiğimda,  dostlarin uzakta olduğunda bile yanimda. Ezberden değil gerçekten,  içinden geldiği gibi yaşayan. Rastl...', ARRAY['Türk Edebiyatı','Şiir','Özgür Arslan']::text[], 8.5, '{"poet":"Özgür Arslan","poet_slug":"ozgur-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sari-seker-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik Zaten Ölümdü', 'sensizlik-zaten-olumdu-baris-duren-k6az9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dün akşam yine seni düşündüm, 

birşey tıkandı boğazıma ağlayamadım, 

ölümmü yoksa sensizlikmi korkuttu ayırt edemedim, 

çünkü farkı yoktu, 

''ÖLÜM SENSİZLİKSE SENSİZLİK ZATEN ÖLÜMDÜ''', 'Dün akşam yine seni düşündüm,  birşey tıkandı boğazıma ağlayamadım,  ölümmü yoksa sensizlikmi korkuttu ayırt edemedim,  çünkü farkı yoktu,  ...', ARRAY['Türk Edebiyatı','Şiir','Barış Düren']::text[], 8.5, '{"poet":"Barış Düren","poet_slug":"baris-duren","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sensizlik-zaten-olumdu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tebeşir', 'tebesir-ahmet-ersin-tasel-i80f1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kırık bir tebeşir

Anlatılması gereken çok şey var

Siyahın üzerine yeşille yazdım

Yanakların solmasın

Ümit her zaman var

Ay ışığında dolaşan gölgeler

Bir ara içinden çıkıp 

Dışarı şöylece gözat

Farklı bir soluk almalısın

Aradım yeni kapıları araladım

Unuttuğunda 

Esen rüzgarla gelen 

Toprak kokusunu solumalısın

Sana olanları anlatır', 'Kırık bir tebeşir Anlatılması gereken çok şey var Siyahın üzerine yeşille yazdım Yanakların solmasın Ümit her zaman var Ay ışığında dolaşan ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ersin Taşel']::text[], 8.5, '{"poet":"Ahmet Ersin Taşel","poet_slug":"ahmet-ersin-tasel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/tebesir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden', 'yeniden-ahmet-ersin-tasel-kxt5s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnızlık yükünü 

Hissetmeli artık

Susmalı...

Zamanla...

Değişmişsin yeniden

Kanat açmalara karşı

Tut ellerimden

Bu garip bir rüya

Bu yüzü tanıyorum bir yerlerden', 'Yalnızlık yükünü  Hissetmeli artık Susmalı... Zamanla... Değişmişsin yeniden Kanat açmalara karşı Tut ellerimden Bu garip bir rüya Bu yüzü t...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ersin Taşel']::text[], 8.5, '{"poet":"Ahmet Ersin Taşel","poet_slug":"ahmet-ersin-tasel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/islik-sesleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol', 'yol-ahmet-ersin-tasel-cmoz3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ölüm diyarında

Yürürüm korkularımın üstüne 

Yürürüm adım adım karanlıkta

Bir adım sonrasını bilmeden

Önümü görmeden

Sonunu düşünmeden

İlk adım sağlamsa

Sonra diğeri

Sonra diğeri

Yürürüm korkularımın üstüne 

Artık büyüdüm

Güvenirim hep ona

Çünkü destektir yanımda bana

Yavru kuşun ilk uçuşu vardır ya yuvadan

Kalbinin pır pır atışı

Kendini boşluğa bir telaşla bırakışı 

İlk kanat çırpışı sağlamsa 

Sonra diğeri 

Sonra diğeri

Uçar korkuları üstüne 

Korkmadan

Bilirim ki uçana kanat

O kanatlar için göğü veren

Bana da yürümem için adım

İlerlemem için yol vermiştir', 'Ölüm diyarında Yürürüm korkularımın üstüne  Yürürüm adım adım karanlıkta Bir adım sonrasını bilmeden Önümü görmeden Sonunu düşünmeden İlk ad...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ersin Taşel']::text[], 8.5, '{"poet":"Ahmet Ersin Taşel","poet_slug":"ahmet-ersin-tasel","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yol-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kandil*', 'kandil-bayram-tunca-eqfpv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hey dost bak bu gece kandil 

Kulağın çınlarsa, andığımı bil

Senin için dua ettiğimi de bil

Sabaha dek, hep zikreder dil

Bugün iki büklüm olsun nice bel

Duadan, karıncalansın nice ak el

Affımız için olsun, gözyaşımız sel

Gönül bağında ılgıt ılgıt essin yel

Dostlarım bugün bari, olmayın el

Yoksa dayanmaz bu acıya bu bel

Hem gökten iner sayısızca melek

Halimize şahit olurlar sabaha dek

Gelin yarenler bu gece tövbe istiğfar edek

Ağlayıp, yalvaralım, Allah’a tâ sabaha dek

Bu gece yapılan dualar belki, bin yıla denk 

Belki bir daha nasip olmaz böyle bir ahenk

01.12.2002-12.01', 'Hey dost bak bu gece kandil  Kulağın çınlarsa, andığımı bil Senin için dua ettiğimi de bil Sabaha dek, hep zikreder dil Bugün iki büklüm ols...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kandil-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Nefes*', 'son-nefes-bayram-tunca-vvynk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Öyle bir derin çekilir ki, o son nefes

Dost ve düşman kulak kesilir herkes

Keşke, ibret alabilse, bundan herkes

Çünkü, mutlak tadar, bu acıyı herkes

30.11.2002-11.30', 'Öyle bir derin çekilir ki, o son nefes Dost ve düşman kulak kesilir herkes Keşke, ibret alabilse, bundan herkes Çünkü, mutlak tadar, bu acıy...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/son-nefes-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Gören Adam', 'dus-goren-adam-oguzkan-bolukbasi-34vmp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kapıları çalmalıyım

soğuk günlerde sıcak

sıcak günlerde serin kapıları

gülen yüzler bakmalı aralıktan

ne istediğimi anlamalı

bir yer göstermeliler odada rahat etmem için

çayı demlemeli evin ortanca kızı

nasılım iyi miyim anlatmalıyım

bir kase sohbetle doymalıyım

her çaldığım kapıda mutluluk bulmalıyım', 'kapıları çalmalıyım soğuk günlerde sıcak sıcak günlerde serin kapıları gülen yüzler bakmalı aralıktan ne istediğimi anlamalı bir yer gösterm...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dus-goren-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku', 'korku-ahmet-ozdemir-qrdku', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani onca çiçek arasından, 

Birisi çıkar da “Ben” der gibi, 

Bahar bahar sana bakar

Bakışlarını ondan alamazsın, 

Karmaşık duygulardır, 

Gözlerinden yüreğine doğru akar

İlgi odağın olur kaçamazsın

-“Önce ilgi duymuştum sana! ”

O ki, artık senin için özeldir

“Çiçek dalında güzeldir”

Koparmaya kıyamazsın 

Çekingen, ürkek, çocuksu, 

Koklamak isteği ile dolarsın, 

Doyasıya, dokunmak öpmek arzusu, 

-“Sonra, arzular olmuştum seni”

Yoktur rengin önemi, ondan yansısın yeter ki, 

Yeter ki onun olsun kokusu

Yapmacıklardan uzak mı uzak, 

Aynı mekan ve zamanda yaşamak, 

Yanında olmaktan hoşlanırsın kuşkusuz, 

-“Kuşkusuz hoşlanıyordum senden.”

Varsın, kimi öyle, kimi böyle görsün

Senin çiçeğindir o, o ki sevgilindir hem, 

Gözünde güzellerden güzeldir her dem.

Yeni açmış goncadır bakmaya doyamadığın, 

Engelleri aşıp ona eresin gelir, 

Yaprağını dikenini sevesin gelir, 

-“Galiba seviyorum seni güzel çiçek”

Cazibe vardır, yer çekiminden güçlü, 

Gizemli ışıktır pervanesi olduğun, 

Yırtar kalbini, kanatır, 

Kadife okşayışı sanırsın, diken değil.

Eğer aşk dedikleri bir zehirli çiçekse, 

Zehrini, derman niyetine içersin.

-“Sana aşık olmaktan korkuyorum.

Biliyorum korkunun ecele faydası yok, 

elverir ki bu rüya olmasın”', 'Hani onca çiçek arasından,  Birisi çıkar da “Ben” der gibi,  Bahar bahar sana bakar Bakışlarını ondan alamazsın,  Karmaşık duygulardır,  Göz...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özdemir']::text[], 8.5, '{"poet":"Ahmet Özdemir","poet_slug":"ahmet-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/korku-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece', 'bu-gece-ali-ulvi-kurucu-h23de', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Buldu hep derdine dermânını canlar bu gece, 

Nura garkoldu bütün kevn-ü mekanlar bu gece, 

Kabey-i zât-i Muallâyı tavaf eylediler, 

Ezeli vuslatın aşkıyla yananlar bu gece! ...

Doğdu alemlere rahmet o hidayet güneşi

Onun aşkıyle yanan gönlünü dağlar bu gece..

Âşıkın kalbi bu gün seyr-i cemâl alemidir, 

Buldu Leylasını Mecnun, coşar ağlar bu gece...

Sen de pervane kesil nuruna artık Ulvi! 

Ne tecellilere makes ulu dağlar bu gece...', 'Buldu hep derdine dermânını canlar bu gece,  Nura garkoldu bütün kevn-ü mekanlar bu gece,  Kabey-i zât-i Muallâyı tavaf eylediler,  Ezeli vu...', ARRAY['Türk Edebiyatı','Şiir','Ali Ulvi Kurucu']::text[], 8.5, '{"poet":"Ali Ulvi Kurucu","poet_slug":"ali-ulvi-kurucu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bu-gece-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gençlik', 'genclik-i-smail-eski-8ffeb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dün yine sensiz ve sebepsiz geçtim Gümüşsuyun’dan

Kanatırcasına yüreğime bir ok saplandı derinden

Neydi beni buraya sürükleyen bilmiyordum

Gecenin bir vaktinde son seferini yapacak otobüsü bekliyordum

Bir yolcu edasıyla son bir sigara daha yaktım

Cebimden çıkan ufak bir fotoğrafa bakarak

Hüzünlendim

Bir ben yalnızdım gecede, bir de park etmiş yolcu otobüsü.

Elim soğuk kaportanın üstünde, diğerinde  sigara.

Travesti edasıyla bir insan geldi yanıma.

Boş ver lan dedi kulağıma.

Donmuştum, kanım donmuştu.

Gece kahrediyordu hiç durmadan.

Soluğu elimde kitaplarla gittiğim dünkü okulda aldım.

Kabataş’tı burası kaldırımlarını bir bir ezdiğim

Elimden tutup hoyratçasına hayata savuran

Bir kartal edasıyla semalarında uçtuğum İstanbul

Haydarpaşa’dan, Sirkeciden ben geldim diyordum adeta

Görüyordum önümü, tepeleri aşıyordum da

Bir sana takılıyordu ay ışığında kanatlarım

Dönüyordum dönüyordum soluklanacak bir yer

Isınacak bir baca kuytusu arıyordum.

Seni yaşadım, İstanbul’u yaşadım dün bütün gece

Bir çıkar yol aradım sisli bulutların arasında

Kuşlara yarenlik ettim, yaralarını sardım İstanbul’un

Gece yine seni bana vermedi.

Toros ekspresini bekledim, 

Atadan kalma toros ekspresi’de yoktu yerinde.

Kanatlarımı kanatırcasına geçtim ve terk eyledim.

İstanbul’u ve seni', 'Dün yine sensiz ve sebepsiz geçtim Gümüşsuyun’dan Kanatırcasına yüreğime bir ok saplandı derinden Neydi beni buraya sürükleyen bilmiyordum G...', ARRAY['Türk Edebiyatı','Şiir','İsmail Eski']::text[], 8.5, '{"poet":"İsmail Eski","poet_slug":"i-smail-eski","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/genclik-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-i-smail-eski-vdnxd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen rüyalarımdaki kız her seyahatte sana koşmak

Gözünü karartırcasına

Gelen her telefona senli açmak sensiz telefonlara

Belki de yaşanan bu

Yaşamak seni başka bir bedende

Çiçeklendim bir başka bedende

Gonca açmıyorum artık

Hep Nilüfer, 

Nilüfer açıyorum

Gizemli, gizemli

Bu aralar içiyorum gece demeden gündüz demeden

Soğuk demeden sıcak demeden gidiyorum bir kente

Kırmızı demeden Beyaz demeden Turuncu seviyorum

Nişanlı demeden evli demeden seviyorum seni

Ara ara başkasını seviyorum

Kıraç demeden Düş demeden

Ben aşkı seviyorum kaçarak

Kaçıyorum köşe bucak, seviyor demeden

Elimi tutamadan seviyor diyor dilim.', 'Sen rüyalarımdaki kız her seyahatte sana koşmak Gözünü karartırcasına Gelen her telefona senli açmak sensiz telefonlara Belki de yaşanan bu ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Eski']::text[], 8.5, '{"poet":"İsmail Eski","poet_slug":"i-smail-eski","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/dus-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan', 'i-syan-i-smail-eski-cvmbf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İsyan bu dağlara inat uzayan yollara inat

Sevgiye, hasrete, özleme inat

Kaf dağında okyanus kadar imkansız

Pırlanta kadar kusursuz olsan da inat

İçtiğim sigaranın dumanında 

Bir kadın oynuyor siyah bulutların içinde

Derin derin bir nefes daha çekiyorum

Ve kan ve boşa atılan bir izmarit daha

Kız oğlan kız sevgimiz bozulmuş artık

İmkansızlar zorlamış son dakikalar için

Yaşanmış ve devrilmiş her şişede

Bir gerçek yatmış

Uzunca iki el atımı silah sesi

Bir aşk yatıyor yerde

Gecenin alacasında  kırmızı bulutlar

Siyah kırmızı bulutlar sevdanın yalancı bekçisi 

Gecenin dadasında kısa bir ürperti 

Ve ardından kopan fırtınada yine sen

Ağaçlar iç çekiyor derin derin

Kuru yapraklar ağlıyor sevdaya

Duvarlar arasında kalmış bir kurt gibi

Parçalıyor içimi sevdan

Her ulumasında kafamda çığlıklar içinde

Bir çocuk ağlıyor

Ve arkasında hep gözyaşı kalıyor.

Konuş sevdiğim uzaklarda olsan da konuş

Son bir kez kulaklarımda çınlasın sesin

Son bir kere sesinin titremesiyle hayalini kurayım

Ve ayrılığın bitip tükenmeyen açısını tatmak üzere

Son yolculuğa ayrılayım.', 'İsyan bu dağlara inat uzayan yollara inat Sevgiye, hasrete, özleme inat Kaf dağında okyanus kadar imkansız Pırlanta kadar kusursuz olsan da ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Eski']::text[], 8.5, '{"poet":"İsmail Eski","poet_slug":"i-smail-eski","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/isyan-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koca Konak', 'koca-konak-i-smail-eski-lef2d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hey gidi koca konak 

Sende mi beni bırakıp gidecektin

Cebimde eski alemlerin resmi

Dilimde hep aynı şarkı

Mezem biraz peynir birkaç gözyaşı

Gecenin koynuna düştü mü yalnızlık

Naram sokağın sonundan duyulurdu.

Bakmayın bana içiyorum diye

Bizim ki dertten tasadan değil

Yüreğimde çıban çıkmış

Kanıyor namussuz sabah akşam

Yazmaya da böyle aşladım

Yazdıklarım ateş oldu ısıttı soğuk gecelerde

Bu namussuzunda sonuna geldi mi tadı bir başka oluyor.

İçsen bir türlü içmezsen bir türlü maksat duman olsun.

Dün yolda gördüm seni

Yeni ayılmıştım rüya değildi 

Üç adım kaldı iki kelime boğazıma düğümlendi

Keşke ama olmuş köpekler gibi görmeseydim.

Dursaydı zaman

Yaşananlar bir sabahın başlangıcında gece yaşanan kabuslar gibi bitseydi

Her şey bu kadar kağıda yazıldığı gibi kolay olsaydı.

Babamdan kalmış iki kelimenin miyadını yitirmediğini de unutmuştum.

Çoraptan çıkmış baş parmağım gibi 

Boğulmuştum yaşadıklarımdan.

Yürüdüğüm kaldırımları sayar olmuştum.

Sabah 76 gece 77 oluyordu.

Senden hoş geldin aramıza deyip, sabah yine gitmiş bu şerefsiz diyordum

Mozart dinlemeye böyle başladım şarap içmeye başladığım gibi

Bizim deli kız yine gitar çalıyor pencerede

Gecenin bir vakti bozacılar yok artık sokaklarda 

Onun yerine durex diye bağırıyorlar

Bir kadın çığlık çığlığa YETER LAN diyor

HAYKIRIYOR! ! ! 

Kanımı içtiniz lan.

Konağın kapısında durdum küfrettim olana bitene. Sende sattın bizi koca konak

Üşüdüm ellerimde titriyor yüreğimde

Kolları kangren olup kesilen insanlar gibiyim sarılmak istiyorum! ! ! 

Bakıyorum uzaktan, içerde hiç durmayan müzik sesi ve çılgınca vals eden çift.

Hatırladım Leyla’yı  Aslı’yı ve burada gramofondan yükselen sesle yüreğimi vermiştim.

Oysa şimdi yüreğimi asalı 3 ay 3 gün oldu

Bir lokma sevgi geçmedi boğazından yemin ederim şahitlik ettim.

Yazmaya başladığımda yüreğimi bir çocuğa vermiştim.

Saf ve temiz bir ifadeyle kırılacak gibi en ince yerinden yakalamıştı.

Bir daha hatırlanmayacak kahramanlar gibi içindekileri kenarı atmıştı.', 'Hey gidi koca konak  Sende mi beni bırakıp gidecektin Cebimde eski alemlerin resmi Dilimde hep aynı şarkı Mezem biraz peynir birkaç gözyaşı ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Eski']::text[], 8.5, '{"poet":"İsmail Eski","poet_slug":"i-smail-eski","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/koca-konak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kır Çiçeği', 'kir-cicegi-i-smail-eski-roafp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Daha düne kadar bütün çiçeklere renk körü gibi bakan bir insan

Şimdi dünyalar kadar güzel bir o kadar narin bir kır çiçeğinin

İnce yapraklarına bir damla çiğ düşürmüş

Kır çiçeğinin haberi olmamış, 

Yıldızlar şahitlik etmiş gencin yüreğinden düşürdüğü her damlaya

Yaban otları sararmış kır çiçeğinin etrafını

Her gün temizlemeye kalksa da

Genç kendi kendine nafile demiş doğanın kanunu bu

Ben yazmadım bozamam

Bir sonraki baharı beklerim, zaman her derde deva demiş

O gece şehre yağmur yağmış

Genç cama vuran şimşeğin ışığıyla uyanmış 

Bir gökyüzüne bir de gönül bahçesine bakmış

Yağan yağmur değilmiş gencin gözyaşlarıymış

Gözyaşları o kadar doluymuş ki yaban otları kır çiçeğinin etrafına yığılmış

Gencin gönlünde yere göğe sığmayan bir mutluluk

Bütün gücüyle kalktığı yatağından

Bir saksıyla gönül bahçesine koşmuş

İncitmeden en ince yerinden topraktan çekip

Gönül bahçesinin en güzel yerine dikmiş

Ve sonra bütün güller terk eylemiş gencin gönül bahçesini kır çiçeğinin aşkından.

“ Çiçeğim eski bir atasözü var zararın neresinden dönersen kâr çiçeğim. Senin henüz hayatının baharı yazı benim gönül bahçeme sen düştün kır çiçeğim Hiç sevgiyi bulamam derken şansım değişti. Gönlümün imdadına bakışların yetişti.”', 'Daha düne kadar bütün çiçeklere renk körü gibi bakan bir insan Şimdi dünyalar kadar güzel bir o kadar narin bir kır çiçeğinin İnce yapraklar...', ARRAY['Türk Edebiyatı','Şiir','İsmail Eski']::text[], 8.5, '{"poet":"İsmail Eski","poet_slug":"i-smail-eski","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kir-cicegi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar Hüznü', 'sonbahar-huznu-i-smail-eski-hagc3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sonbaharlar hüznü taşır, arkasında ayrılıkları getirir.

Korkak bir ifadeyle aşkı fısıldar, Aşk yoktur aslında.

Yalnız ve yalnız tek sevgili vardır.

Yaprak dökümüdür artık.

Bir çöpçünün kovasında bekler, yere düşen her yaprak.

Sessizce ve kimsesizce ayrılır dibinden.

İçten içe bulutlar ağlar son yolculuğa.

Artık öpüşmeler, bir sonraki bahara kalmıştır.

Gelecek bahar ne zaman gelir kimseler bilmez.

Bilinmeyen bir bahar kimleri getirecektir, 

Kimleri de küstürecektir sevgili bilmez.

Sadece o kavuşma anını bekler.

Bir daha kavuşma olmayacağını bile bile, 

Yanar en ince yerinden.

Toprak hiç bu kadar mesut olmamıştır.

Bu ayrılışa tek şahit odur da, hiç üzülmez sevinir ayrılışa.

İçten içe sarılır yaprağa, üzüntünün verdiği kasvetle 

Kendini bırakır kara toprağa.

Bir sonraki bahara yeni bir filizlerle başlayacağız.

Toprağın kokusunu biz çekeceğiz sinemize

Yalancı sonbahara inat, yalancı aşklara inat, 

Sevmeyeceğiz en derinden, Bizi seven toprağa inat.

Korkusuzca atlayacağız toprağın kara sinesine, ve ardında gelen ÖLÜME.', 'Sonbaharlar hüznü taşır, arkasında ayrılıkları getirir. Korkak bir ifadeyle aşkı fısıldar, Aşk yoktur aslında. Yalnız ve yalnız tek sevgili ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Eski']::text[], 8.5, '{"poet":"İsmail Eski","poet_slug":"i-smail-eski","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sonbahar-huznu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Dostum', 'can-dostum-i-smail-eski-p1iks', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dostum can dostum

Güvendiğim dağlar bir bir üzerime yıkıldı

Canımı sattılar can pazarlarında

Ciğerlerimi lime lime edip köpeklere yedirdiler

Yinede bir ah demedim.

Oysa bak şimdi sen gidiyorsun

Yürekten can gidiyor

Bir damla yaş süzülüyor yanağımdan

Veremli hastalar gibiyim

Bir yanım hasta bir yanım uçurum

Yaklaşma diyorum ya umudum

Bak yine uçurum sonundayım

Yine karşıki sahillerde güneş doğuyor

Ben yine gecenin bitmesini bekliyorum

Bu bekleyişler hep uzuyor hep üzüyor

Bir yüreğime birde parmaklarıma hakim olamıyorum

Gecenin bir yarısında şiirler yazıyorum

Bir yanımda sigara paketleri  bir yanımda şişeler

Anlayacağın dostum serseri mayın gibiyim

Bir sen vardın beni anlayan birde rüzgar

Rüzgarlar gibiydim esip savuran

Şimdi gecenin ayazında bir tüy dahi kıpırdamıyor.

Sende gideceksen eğer arkana bakma

Bakanların hali nice olur diye de sorma

Sorarsan eğer sende geri dönmüş olursun

Dönersen seni kolundan tutar çekerler

Yalnızlıklarına senide bir hiç uğruna eklerler

Bunu bir ağıt bin öğüt say ve koru değerlerini

Kalbine yaz öğütlerimi

Kalbine yaz ki her geri dönüşünde kanatsın yüreğini

Sabahın alacasında dövüşürken aklan kara

ELVEDA CAN DOSTUM.....', 'Dostum can dostum Güvendiğim dağlar bir bir üzerime yıkıldı Canımı sattılar can pazarlarında Ciğerlerimi lime lime edip köpeklere yedirdiler...', ARRAY['Türk Edebiyatı','Şiir','İsmail Eski']::text[], 8.5, '{"poet":"İsmail Eski","poet_slug":"i-smail-eski","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/can-dostum-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cehenneme Giden Yolda', 'cehenneme-giden-yolda-i-smail-eski-h6fh4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Cehenneme giden yolda

Yazılar yazdım, notlar bıraktım

Bir öpücük kondurdum vazodaki güle 

Solmasın diye, bir damla göz yaşı bıraktım

Vişne çürüğü bir rujla imzaladım aynayı

Kapıyı çekerken anahtarlarımı içeride bıraktım

Araba kapıdaydı, karlar yağmıştı

Zar zor ilerledim yolda

Ayaklarım çekmiyordu

Taksiyle uzaklaştım caddeden

Boynumdan kravatı, kalbimden seni

Seni atamadım

Gece tarifesiydi, kar yağıyordu

Yolun sonunda Azrail bekliyordu, 

Azrail hızdı, ısınmaktı, toprağa yarenlikti

Nemli toprak ağırdı, soğuktu

Bedenim daha soğumamıştı

İnsanlar vardı, talk veriliyordu

İnsanlar bir bir uzaklaştı

Ayaklarım bağlıydı, çenem tutulmuştu

Bir ahhh bile diyemeden, son nefesimi tükettim 

Komşum 48 doğumlu Ahmet’ti

Kalbinde 7.65 bir mermi, 

Çok ağrı yapıyor diyordu

Defteri imzaladım senetler hazırdı

Kabulümdü cezam, Cezam alınyazımdı

Çekmesi, ödemesi kolay tek başına zordu

Zaman durmuştu kolumdaki saatin pili bitmişti.

Hava azalıyor toprak basıyordu

Tahtalar çürüyordu

Bayramdı göğsümde, başımda çiçekler vardı

Dualar ediliyordu. Bayramlar çok uzaktı

Sen yoktun bayramların tadı yoktu.

Sen geldin, yanında biri vardı, hayal meyal hatırladım

Elinde bir çocuk adı bahtiyar

Ne kadar BAHTİYARRRR', 'Cehenneme giden yolda Yazılar yazdım, notlar bıraktım Bir öpücük kondurdum vazodaki güle  Solmasın diye, bir damla göz yaşı bıraktım Vişne ç...', ARRAY['Türk Edebiyatı','Şiir','İsmail Eski']::text[], 8.5, '{"poet":"İsmail Eski","poet_slug":"i-smail-eski","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/cehenneme-giden-yolda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sana Ağır Gelirim 1', 'ben-sana-agir-gelirim-1-kamil-aydemir-ig37r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gözlerim dese de yaklaş

güzel kız benden uzaklaş

üzerine sinebilir mapusluğun kokusu

titreyişim acemiliğimin açlığımın korkusu

öpmeye eğilirken de bir çiçeği

incitmekten korkarım doğrusu

bir kadının dukdaklarına

dudaklarımı kondurmadan

ince belinde kolumu ısıtmadan

düştüm mapusdamına

onbeş sene tükettim tamı tamına

kendimi yaşamadan

    yaşatmaya çalıştım başkalarını

miknatıs gibi çekiyor

benden uzak tut dudaklarını

yüreğime kıpır kıpır bir ırmak akar

belki yanaklarımda gamzelerini takar

yanaklarıma sürersen yanaklarını

şimdi ben yüzyıllık çınar gibi deneyimli

yeni yürüyen çocuk gibi toyum

acılar özlamler küpüyüm

karşılayamam senin duygularını

yıllarca sarılıp yattım buz gibi duvarlara

alışık değilim kışın ortasında baharlara

nefesini örtersen üstüme biraz daha

esmer teninde mor güllerle çıkarsın sabahlara', 'gözlerim dese de yaklaş güzel kız benden uzaklaş üzerine sinebilir mapusluğun kokusu titreyişim acemiliğimin açlığımın korkusu öpmeye eğilir...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ben-sana-agir-gelirim-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Yama Tutmaz 2', 'sevgi-yama-tutmaz-2-kamil-aydemir-ia0lq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dün seni görmeseydim

yüreğime bir kat daha acı örmeseydim

gamzelerin yerinde istanbul sokaklarındaki gibi çukurlar

gözlerin sanki göz değil

ülkemin doğusundaki öğrencilerini yitirmiş okullar

belli ki parayla mutlu olamamışsın

bende bıraktıklarını bulamamışsın

ince eler halin vardı

beni mutluluğun resmini çizdiğimiz günlerdeki heycan sardı

gözlerimi kucaklayan gözlerin gözlerimden utandı

bastırılmış duyguların ayaklandı

yüreğin seni benden uzaklaştıran ayaklarını rehin aldı

miting alanından göstericileri nasıl sökerse polis

öylesine hoyratça biri girdi koluna

devam ettirdi yoluna

darılma bana gülüm ama

dün kendin kıydın bugününe

sana özümle geldim

eylül saraylarında dimdiktim

sevgimin önünde eğildim

içindeki çocuğu dinlemedin

uslanmaz arzularına yenildin

aşkı özgürlüğü kirletenlerin safına girdin

paranın konuştuğu

   loş ışıklı kişiliksiz sokaklarda direncini bitirdin

kanadına değmişken mutluluk denen kuşu yitirdin

hadi mektuplarımı resimlerimi yak diyeceğim

yüreğini ne yapacaksın

                              yüreğini

yaktılarda sıvas''ta otuzyedi aydını

  doğulu kardeşlerimin köylerini

      tükettiler mi özlemlerini

gönül sevdiğini unutmaz

sevgi yama tutmaz', 'dün seni görmeseydim yüreğime bir kat daha acı örmeseydim gamzelerin yerinde istanbul sokaklarındaki gibi çukurlar gözlerin sanki göz değil ...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/sevgi-yama-tutmaz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatın içinde Hayasızca', 'hayatin-icinde-hayasizca-mehmet-ozgur-arik-cxddp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hep ertelenen bir an hiç yaşanmamaya mahkumdur

Boşuna akan ırmaklarmı var yüreğimizde 

Çokmu coşkun bir denizde maviye hasretliğimiz

Sevdiğimizi bulmak yada bulduğumuzu sevmek tercihi en zor olan seçenektir bu sınavda

Yinede korkutmasın seni bu sevdanın ateşi her yangın önce başladığı yeri yakar

Sana küçük kendime büyük gelen yüreğimde yıllar geçsede senin adın yazar

Ve bilki sevdiğim uslanmaz ruhum yaşadıkça seni sever seni sevdikçe yaşar

      Bir gün gökyüzü sensizliğe ağlarsa eğer 

Yere düşen her damlada seni anarım 

      Çünkü sen sana güzelliklerin en güzeli verilenisin.

                                                          Yasemin Emine BAYRAK', 'Hep ertelenen bir an hiç yaşanmamaya mahkumdur Boşuna akan ırmaklarmı var yüreğimizde  Çokmu coşkun bir denizde maviye hasretliğimiz Sevdiği...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özgür Arık']::text[], 8.5, '{"poet":"Mehmet Özgür Arık","poet_slug":"mehmet-ozgur-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hayatin-icinde-hayasizca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sınırsızca Sevmek', 'sinirsizca-sevmek-mehmet-ozgur-arik-ap1fq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevmek, hatırlamak ve paylaşmak bir gülü dalında 

Yüreğin sevgi üretmiyorsa iyi bir üretici deyilsindir

Türkü ve umut tadında sınırsızca sevmenin arsızlığında yüreğim 

Açık bıraktım gönül kapılarımı  sevdaya gem vurmamak için 

Ne aşklara doyar bu gönül nede doymak için sever

Yarım kalmış yaşanmasına pranga vurulmuş nice aşkların temelinden sarsılmış duygular var

Gönül bahçelerinden koparılan her gülün hesabını veremezki hayat.

Şimdi boğazımda düğümlenmiş her hece gözlerimden süzülen yağmur damlalarına yüz tuttu.

Ve seninle yaşanmamış her buzumsu geceye inat sarıldım hayaline.

Şimdi yüreğim hür, gözlerimde umut sesleniyorum sana seni sınırsızca seviyorum.

Ama ne seni görmeden yaşayacak güçlüğüm 

Nede seni görmeye dayanacak kalbim var.

                                                     Yasemin Emine BAYRAK', 'Sevmek, hatırlamak ve paylaşmak bir gülü dalında  Yüreğin sevgi üretmiyorsa iyi bir üretici deyilsindir Türkü ve umut tadında sınırsızca sev...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özgür Arık']::text[], 8.5, '{"poet":"Mehmet Özgür Arık","poet_slug":"mehmet-ozgur-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sinirsizca-sevmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam Mahkumu..', 'yasam-mahkumu-nilgun-akcay-rcn7g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bakışlarda başlayan, bakışlarda biten bir hikayedir bu.Özleyen yürek; gündüzleri esir, geceleri özgürdür.Bütün duyguların anası gece çıplak bir yanlızlık sunar.. Doğa, bir tablo çizer ruhumun tuvaline.Bütün renkler birbirine benzer...Hepsi Simsiyah..! Beyazı yumuşak bir dokunuş olarak hisseder ruhum...Siyahın beyaza kavuşmasını yüreğim özlemle bekler..

Kara toprak beyaza bürünmüş bedenimi hasretle kucaklarken; hayat anlamsızlıklar içinde kahkahalarla son bulur gözlerimde.Tüm çirkinlikleri rehin alan gece...Yaşanmamış duyguları hapseder koynuna...

Uzanıp hayal kurduğum kapkaranlık gecelerde,Ah Keşke dediğim tüm anılarım gecenin koynunda avutur beni... Ve...Gün hiç doğmasın isterim.... 

Çünkü BEN; 

Her gece.. 

Kurarım darağacımı.. 

Ruhumun derinliklerine. 

Celladım olur gururum.. 

Ve..Ben..Her gece ölen.. 

Yaşam mahkumuyum.

''>', 'Bakışlarda başlayan, bakışlarda biten bir hikayedir bu.Özleyen yürek; gündüzleri esir, geceleri özgürdür.Bütün duyguların anası gece çıplak ...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Akçay']::text[], 8.5, '{"poet":"Nilgün Akçay","poet_slug":"nilgun-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yasam-mahkumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimsesiz Düşüm', 'kimsesiz-dusum-gokcen-duran-x1rye', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kimsesiz  düşlerime yar  düşüyor yar...

Simsiyah  saçlarıma  kar düşüyor kar...', 'Kimsesiz  düşlerime yar  düşüyor yar... Simsiyah  saçlarıma  kar düşüyor kar......', ARRAY['Türk Edebiyatı','Şiir','Gökçen Duran']::text[], 8.5, '{"poet":"Gökçen Duran","poet_slug":"gokcen-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/kimsesiz-dusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kilim Yaptım Gönlümü', 'kilim-yaptim-gonlumu-gokcen-duran-9aswh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kar  altından  kardelenler  derdim

Gece  siyahı  saçlarına  tak  diye

Mum  yaptım  gönlümü,  gönlüne verdim

Kapkaranlık  gecelerde  yak  diye

Kilim   yaptım  gönlümü,  gönlüne verdim

Soğuk   kış   geceleri  üşüme   diye

Her bir desenini  bir  sevdadan  derdim

Aşkın ebruli renk cümbüşünü gör  diye', 'Kar  altından  kardelenler  derdim Gece  siyahı  saçlarına  tak  diye Mum  yaptım  gönlümü,  gönlüne verdim Kapkaranlık  gecelerde  yak  diy...', ARRAY['Türk Edebiyatı','Şiir','Gökçen Duran']::text[], 8.5, '{"poet":"Gökçen Duran","poet_slug":"gokcen-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kilim-yaptim-gonlumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Yüzlüye Çaresiz Mektup', 'ay-yuzluye-caresiz-mektup-huseyin-ucak-9c4xx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Genç ile kız daha lisenin başında tanışmışlardı

Kısa zamanda sıkı arkadaş olmuş

İlişkileri gitgide ilerlemiş bir birlerine bağlanmışlardı

Kız bir gün arkadaşına kanıp sebepsiz yere

Çocuktan ayrılmıştı

Çocuk ne olduğunu anlayamıyor kusuru kendinde arıyordu

Kız sonradan çok pişman olmuştu

Bir türlü çocukla konuşmaya cesaret edemiyor

Kendini affedemiyordu

Derken yıllar sonra çocuktan bir mektup geldi

AY YÜZLÜM (Genç Kız''a Yazıyor)

Merhaba… Ay yüzlüm

Yine seni düşünüyorum bu günlerde

Yine her şeyi sana benzetiyorum

Her an her dakika seni görüyorum karşımda

Ne yaptıysam vazgeçemedim karşı koyamadım bu huyuma

Biliyorum hala seni seviyorum Ay yüzlüm

Hala anlamıyorum neden uydun başkasına 

Neden beni yaktın seni böyle severken

Bağlıydım sana delice esirindim

Neden yaptın neden Ay yüzlüm

Hiç bir şey yerini tutmuyor

Sana olduğum kadar başkasına aşık olamıyorum

Artık anmak istemiyorum ayrılığın adını

Ay yüzlüm seninle çıkarmak istiyorum mutluluğun tadını

Aradan aylar yıllar geçti

Yine de sönmedi sana olan aşkımın ateşi

Aksine bitmesi gerekirken seni gördükçe 

Aynı coşkuyla aynı heyecanla çapmakta kalbim

Sana bağlanmışım elimde olmadan

Ama sen farkında değilsin Ay yüzlüm

Beklide farkındasın beklide naza çekiyorsun

Yalnız; dayanamıyorum artık çekemiyorum bu acıyı

Önceden ne güzeldi seninle ilişkimiz

Her sözün ümit vericiydi şimdi neredeler hani

Nereye kayboldular ansızın senin gibi

Gene de suçlayamıyorum seni

Biliyorum bir arkadaş uğruna yaktın ikimizi de 

Sormadan yapamıyorum bütün bunlara değermiydi? 

Bütün bu acılara, çileye, ızdıraba, yalnızlığa

Bir gül vermiştin bana hatırlıyor musun sakla demiştin

O gül durmakta hala bir kenarda

Rengi solduğu halde maziyi yaşatmakta

Bir o vefalı çıktı eski günlerden bu yana

Bilmiyorum neden bu mektubu yazdım

Şimdilik bitiriyorum maziyi boş ver Ay yüzlüm

Beklide ben yine kendimce saçmalıyorum

             

                                      Sağlıcakla kal Ay yüzlüm

                                        '' SENİ SEİYORUM '' 

MEKTUBA CEVAP (Kız Gence Yazıyor)

Bilemezsin o günlerden beri ne çektiğimi

Yaptıklarımın acısını çekiyorum hala

Biliyorum deymezdi böyle bir arkadaşa

Yok yere yaktım ikimizi de

O eski günlerden beri sende hiç aklımdan çıkmıyorsun

Ne kadar pişmanım biliyor musun? 

Yaptıklarımdan dolayı kendimi affedemiyorum

Sana dönmeyi çok istedim Ay yüzlüm

Yüzüm yoktu geri dönmeye suçluydum biliyorum

Benden sonra çok kişiyle çıkmışsın belli

Senin gibi bende çok kişiyle çıktım

Belki onların sayesinde seni unuturum sandım

Yapamadım yapamadım Ay yüzlüm

Senin sevgini hiç birinde bulamadım

Şimdi senin yanında olmak için neler vermezdim

Beni affede bilecek misin Ay yüzlüm

Kavuşmamız imkansız artık

Elveda Ay yüzlüm

AİLE BASKILARI

Annesiyle babası oğullarının bu durumuna çok üzülüyorlardı

Onu gördükçe ne yapacaklarını bilemiyorlar

Kadere lanet ediyorlardı

Çocuğun yaşı da ilerlemiş askerliğini bitirmişti

Anne baba oğullarının mürvetini

Bir an önce görmek istiyorlardı

Anne daha önceden birini beğenmişti bile

O kızı oğluna eş olarak almak istiyordu

Günlerce çocuğu ikna etmeye çalıştı

Bir kerede olsa görmesini istiyordu anne

Çocuk annesinin ısrarlarına dayanamayınca 

Çaresiz kabul etmek zorunda kaldı

'' Müsait bir günde gider görürüz dedi'' annesine

Kalbi hala Ay yüzlüsündeydi çocuğun

Birkaç gün sonra bir haber geldi Ay yüzlüsünden

Yıkıldı genç olduğu yerde kala kaldı

İnanmak istemedi olamaz böyle bir şey dedi kendi kendine

Ay yüzlüsünü trafik kazasında kaybetmişti

Bitkin bir şekilde eve döndü genç

Eve geldiğinde annesini ağlarken gördü

Merakla sordu annesine 

'' Ne oldu neden ağlıyorsun anne''

Annesi hıçkırıklar arasında cevap verdi

Görmeni istediğim kız vardı ya oğlum

Onu bu gün trafik kazasında kaybettik dedi

Çocuk kulaklarına inanamadı

Annesinin, görmesini istediği kişi

Canından çok sevdiği Ay yüzlüsünden başkası değildi

Kader yine onlara yapacağını yapmıştı

Yine ağlarını örmüştü bu iki gencin aşklarının üstüne



KADERE İSYAN

Çocuk Ay yüzlüsünün ölümünü kabullenemiyordu

Bütün bunların bir rüya olmasını istiyor

Allah''a Ay yüzlüsünün geri dönmesi için yalvarıyordu 

Gün geç tikçe yaşama arzusunu yitirmişti

Her gün ay yüzlüsünün mezarına gidip saatlerce 

Ağlıyor kadere durmadan isyan ediyordu

Çocuk ay yüzlüsünün acısından 

Kendini içkiye vermiş sabah akşam sürekli içiyordu

Anne ve baba  oğullarının bu durumu karşısında 

Bir şey yapamıyor

Çaresiz çocuğun yok oluşuna şahit oluyorlardı

Tek çare evlenmesi diye düşünüyorlardı

Böylece ay yüzlüsünü unutur hayatını düzeltir sanıyorlardı

Bir gün çocuk yine içmiş zil zurna sarhoş olmuştu

Her an her dakika ay yüzlüsünü düşünüyor 

Durmadan adını zikrediyordu

Nere gittiğini bilmeden ve o sarhoş haliyle durmadan

Dolaşıyordu sokaklarda 

Çevresine dikkat etmeden yürüyordu

Oysa caddenin ortasındaydı

Karşısından gelen arabayı bile görmüyordu

Ansızın ay yüzlüsünü gördü genç

Onu çağırıyordu el uzatmış gel diyordu

Genç tereddüt etmeden ay yüzlüsüne uzandı

Ve o uzanmayla birlikte tüm acıları son buldu

Dünyada buluşamadılar ama ruhları ahrette buluştu

İkisi de birbirine  ahrette kavuştu.

                                                                            23.03.2002

                                                                         Hüseyin UÇAK', 'Genç ile kız daha lisenin başında tanışmışlardı Kısa zamanda sıkı arkadaş olmuş İlişkileri gitgide ilerlemiş bir birlerine bağlanmışlardı Kı...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Uçak']::text[], 8.5, '{"poet":"Hüseyin Uçak","poet_slug":"huseyin-ucak","theme":"Türk Şiiri","is_hero":false,"total_lines":129,"source_url":"https://www.antoloji.com/ay-yuzluye-caresiz-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum Seni Sevgili, Seviyorum', 'seviyorum-seni-sevgili-seviyorum-ugur-i-lhan-u2pdd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seviyorum seni sevgili, seni seviyorum

Sana, gidiyorum derken, içimde büyüyen çığlıklarımı duyabildiğin için.

Seviyorum seni sevgili, seni seviyorum.

Yaşadığım öfkelerimin içinde, büyüyen sevgimi hissedebildiğin için.

Seviyorum seni sevgili, seni seviyorum.

Tüm, imkansızlıklara karşın, imkanım olmayı başardığın için.

Seviyorum seni sevgili, seni seviyorum.

Bana her an dişiliğimi yaşattığın için.

Seviyorum seni sevgili, seni seviyorum.

Kelepçeli ellerini bana büyütebildiğin için.

Seviyorum seni sevgili, seni seviyorum.

Prangalarına rağmen bana gelmeye başardığın için.

Seviyorum seni sevgili, seni seviyorum.

Bir gün, ayrılacağımızı bildiğin halde, sevdana sımsıkı tutunduğun için.

Seviyorum seni sevgili, seni seviyorum.

Göz bebeklerinde sakladığın o küçük çocuğu bana tanıttığın için.

Seviyorum seni sevgili, seni seviyorum

Dilinde açan sözcük çiçeklerini, bana derleyip verebildiğin için.

Seviyorum seni sevgili, seni seviyorum

Bedenimde raks eden parmak uçlarını, ruhuma hançerleyebildiğin için.

Seviyorum seni sevgili, seni seviyorum

Yüreğimi, yüreğinle sıcacık kılabildiğin için.

Seviyorum seni sevgili, seni seviyorum.

Bana bir kez daha,  kendimi kandırma fırsatı verdiğin için.

Seviyorum kendimi sevgili, seviyorum beni.

Asla aşktan vazgeçmeyeceğimi bir daha bana anımsattığın için......', 'Seviyorum seni sevgili, seni seviyorum Sana, gidiyorum derken, içimde büyüyen çığlıklarımı duyabildiğin için. Seviyorum seni sevgili, seni s...', ARRAY['Türk Edebiyatı','Şiir','Uğur İlhan']::text[], 8.5, '{"poet":"Uğur İlhan","poet_slug":"ugur-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/seviyorum-seni-sevgili-seviyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Kurt, Kim Kuzu', 'kim-kurt-kim-kuzu-ugur-i-lhan-oj80o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Neden bu kadar aptal bu yaşam.

Neden bu kadar doğrularla yanlışlar karışıyor artık.

Kimin doğrusu, kimin yanlışı, neyin doğrusu, neyin yanlışı.

İnsan-hayvan-bitki

Hangisi daha duyarlı

Hangisinin daha fazla doğruları var

Ya da hangisinin yanlışları

Kim yönetiyor kimi.

Kim izin veriyor yönetilmelere

Neye göre, nereye kadar.

Ne zaman durulacak

Nerede durulacak

Bilen var mı

Ya da bilmek mi istemiyoruz.

Usanmayı mı unuttuk.

Uzanmaktan keyif mi almaya başladık

Sizi bilmem. Ben usandım.

Hep isyanlar doğurdum anaç kimliğimde

“Dur” demelerim yetmedi, bir şeyleri durdurmaya.

Sesim kayboldu, melemelerin arasında.

Bir tutam ot  için kuyruk sallayan

Minik, çaresiz, çoban güdümünde ki sürü hep daha çoktu çünkü.

Daha mı kolay sürüden biri olmak. 

Kurtlar mı kapar sürüden kaçanı

Hangi kurt, nasıl bir kurt.

Çoban, sizi kurttan koruyor güya.

Ama bilin artık 

İki ayaklı kurtlara pazarlamak için.

Ağasından zam alabilmek için....

Evine bir somun ekmek götürebilmek için.

Ey be sürü. Bir isyan edebilsen, 

Sınırlı topraklarla yetinmekten vazgeçip  de, doğanın hakimi bir olabilsen.

Üreten sensin, ama kurban da

Hadi uyan be kuzucuk

Dağıl dağlara, dağıl ovalara

Senin bu yaşam.

Artık adaklık koyun olma be kuzucuk. 

Bitsin aptalca kan dökülmeler

Bitsin artık, Allah’ın verdiği topraklardan 

Allah’ın verdiği kulunun sınırları

Bitsin artık...

Sizi bilmem ama ben usandım...

Uğur ilhan', 'Neden bu kadar aptal bu yaşam. Neden bu kadar doğrularla yanlışlar karışıyor artık. Kimin doğrusu, kimin yanlışı, neyin doğrusu, neyin yanlı...', ARRAY['Türk Edebiyatı','Şiir','Uğur İlhan']::text[], 8.5, '{"poet":"Uğur İlhan","poet_slug":"ugur-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/kim-kurt-kim-kuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı Zaman', 'yalanci-zaman-ugur-i-lhan-qvw8y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'YALANCI ZAMAN

Umutlar gene soldu bu gece karanlığında

Gene karlar yağdı çiçeklenen dallarıma

Zamansızlığın zamanımıydı yoksa bu

Zamansızlığın içinden gelen

Yoksa yalnızca yalancı zaman mı

Uğur İlhan/2000', 'YALANCI ZAMAN Umutlar gene soldu bu gece karanlığında Gene karlar yağdı çiçeklenen dallarıma Zamansızlığın zamanımıydı yoksa bu Zamansızlığı...', ARRAY['Türk Edebiyatı','Şiir','Uğur İlhan']::text[], 8.5, '{"poet":"Uğur İlhan","poet_slug":"ugur-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yalanci-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Artık', 'gel-artik-ugur-i-lhan-33z3a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ayrılığın soluk kesen soğuğunu yaşıyor yüreğim

Göz pınarlarımdan düşen her bir damlacık

Bir buz tanesine dönüşüyor hemen oracıkta

Dudaklarımdan kelimeler yerine

Ayrılığın hıçkırıkları dökülüveriyor

Ellerim dokunamıyor senden başka hiçbir nesneye

Sanki uyuştu parmaklarım 

Hissetmiyor ki başka bir sıcaklık

Gel, kat sıcaklığını sıcaklığıma

Erit beni gözlerinin içinde

Kaybolalım zamansızlık uçurumlarında

Bir kuşun kanadına uzanalım sessizce

Uçursun bizi sevda çiçeklerinin açtığı bahçelere

Gel sevdiğim gel artık

Kat sıcaklığını sıcaklığıma

Uğur İlhan/1997', 'Ayrılığın soluk kesen soğuğunu yaşıyor yüreğim Göz pınarlarımdan düşen her bir damlacık Bir buz tanesine dönüşüyor hemen oracıkta Dudaklarım...', ARRAY['Türk Edebiyatı','Şiir','Uğur İlhan']::text[], 8.5, '{"poet":"Uğur İlhan","poet_slug":"ugur-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gel-artik-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerimdeki Çiçekler Islak', 'gozlerimdeki-cicekler-islak-ugur-i-lhan-ooz7g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine ruhuma yağmurlar yağıyor bugün

Gözlerimdeki çiçekler ıslak

Sensizlik dondurdu bedenimi

Üşüyorum sıcaklığın benden uzak

Al bak yüreğim avuçlarımda

Isıt dudaklarınla üşümesin

Korkma dokun ona ruhunla

Sar vuslat yapraklarını üşümesin

Uğur İlhan/1997', 'Yine ruhuma yağmurlar yağıyor bugün Gözlerimdeki çiçekler ıslak Sensizlik dondurdu bedenimi Üşüyorum sıcaklığın benden uzak Al bak yüreğim a...', ARRAY['Türk Edebiyatı','Şiir','Uğur İlhan']::text[], 8.5, '{"poet":"Uğur İlhan","poet_slug":"ugur-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gozlerimdeki-cicekler-islak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Hala Sen', 'sen-hala-sen-ugur-i-lhan-j0tj9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gece gene düştü sensizliğimin yanı başına

Ayın yakamozu ısıtmıyor ki beni

Açmıyor ki kanatlarını yüreğimdeki martılar

Yıldızlar saramıyor ki bedenimi

Sen hala sen

Bende saklı kalmışken

2001', 'Gece gene düştü sensizliğimin yanı başına Ayın yakamozu ısıtmıyor ki beni Açmıyor ki kanatlarını yüreğimdeki martılar Yıldızlar saramıyor ki...', ARRAY['Türk Edebiyatı','Şiir','Uğur İlhan']::text[], 8.5, '{"poet":"Uğur İlhan","poet_slug":"ugur-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sen-hala-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksulum Buralarda', 'yoksulum-buralarda-ugur-i-lhan-y8m7q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yoksulum buralarda

Yüreğim çizik içinde, kanıyor..

Sen yoksun, yoksulum buralarda

Sensizim, nefesine hasret

Tenine, sıcağına, sözüne hasretim.

Benim olmayan sana.

Uğur ilhan/10 mayıs.2002', 'Yoksulum buralarda Yüreğim çizik içinde, kanıyor.. Sen yoksun, yoksulum buralarda Sensizim, nefesine hasret Tenine, sıcağına, sözüne hasreti...', ARRAY['Türk Edebiyatı','Şiir','Uğur İlhan']::text[], 8.5, '{"poet":"Uğur İlhan","poet_slug":"ugur-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yoksulum-buralarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Adam Sevdim Ege den', 'bir-adam-sevdim-ege-den-ugur-i-lhan-iwz1z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir adam sevdim ege den...

Ege gibi rüzgarlı

Ege gibi sıcak

Bir adam sevdim.

Ege gibi girdaplı

Ege gibi ketum

Bir adam sevdim

Ege kadar hoş

Ege kadar uzak.

Bir adam ve ege ve ben

Ve ben uzak...

Uğur ilhan', 'Bir adam sevdim ege den... Ege gibi rüzgarlı Ege gibi sıcak Bir adam sevdim. Ege gibi girdaplı Ege gibi ketum Bir adam sevdim Ege kadar hoş ...', ARRAY['Türk Edebiyatı','Şiir','Uğur İlhan']::text[], 8.5, '{"poet":"Uğur İlhan","poet_slug":"ugur-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-adam-sevdim-ege-den-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Yoksulluğu Sevmiyorum', 'ben-yoksullugu-sevmiyorum-ugur-i-lhan-imktz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben yoksulluğu sevmiyorum

Ortada bir tencere, boş bir kavanoz

Ve bir kap zeytin, bir baş soğan

Dizilmiş etrafına dört çocuk

Ve erken eskimiş bir kadın

Gözleri acı bakıyor kameraya

Bir adam oturmuş yanlarına 

Yardım etmeye çalışıyor sözüm ona

Onlarsa sıktıkları yumruklarında

Utançlarını saklıyorlar

Buruk izliyorum onları

En küçük bebe 3 yaşında

Sumak kızılı saçları, çapaklı gözleri 

Bakıyor annesine, ''neden'' der gibi

Ben yoksulluğu sevmiyorum

Kamera evi dolaşıyor

Onur çalan bir hırsız gibi

Yerde çatlak bir leğen

Yanında pas tutmuş bir maşrapa

Etrafta karafatmalar

Sanki yoksulluğu, acıyı paylaşıyorlar

''burada mı yıkanıyorsunuz '' diyor

Yardım etmek isteyen adam

Utanç düşüyor eskimiş kadının yüzüne

''evet'' diyor, gözlerini saklarken

Suçlu sanıyor bir anda kendisini

Oysa suçlu onlar mı

Ben yoksulluğu sevmiyorum

Gözlerine buğu düşüyor 

Yardım etmek isteyen adamın

Pencereler naylon kaplı

Cam nerede, cam pahalı

Ben yoksulluğu sevmiyorum

Minik kız, köşede bir yumak olmuş

Yardım etmek isteyen adam yanına gidiyor, 

Ağzında sahte tebessüm

Kız, gözlerini kaçırıyor bu yabancı amcadan

''okula gitmiyor musun'' diyor, 

 Hiç tanımadığı adam 

''I-ıh'' diyor, yumak olmuş minik kız

''ne istiyorsun benden'' diye soruyor adam

''Okul'' diyor minik kız, sadece okul

Oysa ayağında çorap yok, titriyor ayacıkları

Ben yoksulluğu sevmiyorum

Uyanıyor evin büyük oğlu, önce saklanıyor, 

Yardım etmek isteyen adamdan 

Adam ona da soruyor

''ne istersin benden''

Çocuk naçar bakıyor adamın gözlerine

''Kitap'' diyor, sadece kitap 

Acıkmış, susamış koca bir adam gibi

Ben yoksulluğu sevmiyorum

Adam, armağanlar veriyor her birine

Kadının yumulmuş avcuna, biraz para

Mutlu oldular sanıyor, 

Yüzlerinde, kayıp neşeyi arıyor umutla

Ben yoksulluğu sevmiyorum

Erken eskimiş kadın, sarılıyor çocuklarına

''Yalancı umutlara kanmayın'' der gibi

Adam, düşmüş omuzlarıyla çıkıyor evden

Belki de yeni yoksullara gidecek

Bir avuç mutluluk dağıtacak bir kez daha

Bizlerse, gözleri yaşlı, izleyeceğiz gene

Boş kapları, çatlak leğenleri

Karafatmalar, paslı maşrapaları

Ben yoksulluğu sevmiyorum

.

Nesini seveyim ki...', 'Ben yoksulluğu sevmiyorum Ortada bir tencere, boş bir kavanoz Ve bir kap zeytin, bir baş soğan Dizilmiş etrafına dört çocuk Ve erken eskimiş...', ARRAY['Türk Edebiyatı','Şiir','Uğur İlhan']::text[], 8.5, '{"poet":"Uğur İlhan","poet_slug":"ugur-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/ben-yoksullugu-sevmiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüyorum', 'oluyorum-adem-bozdag-j2zh3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ruhumun sırlar ardındaki kapısı

 Dolaşır  durur dmarlarımda

 Esrarengiz bir gayedir kalp acısı

 Bitmiş ömrüm şu genç yaşımda

 Sokak aralarında geçen çocukluğum

 Amaçsız bir kahraman gibi çığlıklarım

 Titrer içimde sessiz acı yolculuğum

 Çaresizliğimle kaybolur hıçkırıklarım.

 Duyabilir misiniz  karanlıktan gelen sesimi

 Artık geç kaldınız çok geç düşüyorum

 Düşerken yere tutarmısınız elimi

 Bakın anlayın artık, ben ölüyorum', 'Ruhumun sırlar ardındaki kapısı  Dolaşır  durur dmarlarımda  Esrarengiz bir gayedir kalp acısı  Bitmiş ömrüm şu genç yaşımda  Sokak araların...', ARRAY['Türk Edebiyatı','Şiir','Adem Bozdağ']::text[], 8.5, '{"poet":"Adem Bozdağ","poet_slug":"adem-bozdag","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/oluyorum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kışbeyazı', 'kisbeyazi-bulent-savkin-zuewm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Unutmuşum kışı, 

Lapa lapa yağan karın usta ressamlığını, 

Her anı fırça darbeleriyle değiştiren, 

Beyazı yaşamla özdeşleştiren...

Birinci fırça ince, 

Sık hareketlerle salınırken

Tualde beyaz başlar gülümsemeye.

Kış çelik gibi soğuk, 

Beyaz ise donuktur.

Bu soğuk donukluğun gülümsemesi

İnanılmazdır ressamın elinde.

İkinci fırça kalın, 

Ağır ağır hareketlidir.

Beyaz çözülür yayılır ortaya

Mavi ve yeşil sırıtır bu olaya

Giderek artarken kar lapa lapa

Yükseklerden iner bir örtü, 

Şiir yazılır gibi bir kağıda.

Toprağın örtülür üstü

Uyusun diye, unutulsun diye

Sonra yeni bir fırça gelir

İnce bir nakış gibi işlenir, 

Detaylar bir bir belirlenir.

Kimi bir saçağa yuvalanır, 

Kimi garibin omzuna

Çatılar beyazlanır, dinlenir.

Yer hareketlenip işlenir.

Ayakizleri, kardanadam ve kadın

Kartoplarıyla dillenir.

Beyaz kalın bir kremadır, 

Bu pastada uzak duvarlar.

Figürandır ağaçlarda kuşlar, 

Boyunlarda al yeşil atkılar

Eldivenlerse renk renk

İşte bu ahenk

Bitmesin dedirtir insana

Bu fırça darbeleri.

Sakinleşir sokaklar bir bir.

Bozacı seslenir sadece

Gece, çocuklar boza ister

Anneler seslenir camdan

O tirat, herkese inat

Çarpıp saçaklara

Döker yollara yollara.

Yollar ıslak soğuk ve parlaktır.

Yeni bir gün doğarken geceye

Beyaz yerini almıştır, 

Beyaz hayattır.

            (07,01,2002

         Ümraniye -İstanbul)', 'Unutmuşum kışı,  Lapa lapa yağan karın usta ressamlığını,  Her anı fırça darbeleriyle değiştiren,  Beyazı yaşamla özdeşleştiren... Birinci f...', ARRAY['Türk Edebiyatı','Şiir','Bülent Şavkın']::text[], 8.5, '{"poet":"Bülent Şavkın","poet_slug":"bulent-savkin","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/kisbeyazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Sarhoş', 'sensiz-sarhos-bulent-savkin-yem30', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uyandım açtım gözlerimi

Bir gün önceki sözlerini duydum

          sanki rüyamda

Yeniden, yeniden yaralanıp kırıldım.

Zehirli bir hayat şarabı içmiştim sanki

Midem bulanıyor, canım çekiliyordu.

Bir kahve bir soda içsem dedim

Mutfağa sallanarak girdim.

Başımmı dönüyordu? 

Başımı döndüren mi sendin? 

Senmiydin, sözlerinmiydi yoksa? 

Diktim sodayı başıma, 

Kana kana içtim

Dünkü sözlerini içiyordum sanki

Yandı boğazım, gözlerimden yaş geldi.

Kahveye sordum aşk bu mu? 

Taşarak, köpüklerini atarak yanıtladı

Adeta aşkın yokluğunu kanıtladı.

Küfrederek doğan güne

Hayata, aşka, rüyaya, düne

Boş odalara bakarak döndüm

Sensizliğe demirlemiş yatağıma...

                        (15.01.2002

                      Çiftehavuzlar.İST.)', 'Uyandım açtım gözlerimi Bir gün önceki sözlerini duydum           sanki rüyamda Yeniden, yeniden yaralanıp kırıldım. Zehirli bir hayat şarab...', ARRAY['Türk Edebiyatı','Şiir','Bülent Şavkın']::text[], 8.5, '{"poet":"Bülent Şavkın","poet_slug":"bulent-savkin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sensiz-sarhos-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kutlu Olsun', 'kutlu-olsun-naside-gokturk-3rpik', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Doğum günün kutlu olsun

Yalnızsan yalnızlığın

Çoğulsan çoğulluğun

Bensizliğin kutlu olsun', 'Doğum günün kutlu olsun Yalnızsan yalnızlığın Çoğulsan çoğulluğun Bensizliğin kutlu olsun...', ARRAY['Türk Edebiyatı','Şiir','Naşide Göktürk']::text[], 8.5, '{"poet":"Naşide Göktürk","poet_slug":"naside-gokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kutlu-olsun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Platonik Duygular', 'platonik-duygular-ahmet-gumustekin-dbg9r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Garip bir duygu yüklenir içine, 

İsteksiz bir tebessüm

boş bir bakış belirir yüzünde! 

Anlam yoktur hiçbir şeyde, 

Gece bitmek, zaman geçmek bilmez.

Yanlızlık acı gelir.

Acı her geçen dakika

daha fazla kaplar benliğini, 

İçindeki artık sen değilsindir, 

Tanıyamazsın kendini.

Hayallerin vardır yerine getireceğin, 

İdeallerin vardır uğruna mücadele edeceğin.

Bu mücadelende destek ararsın kendine, 

Arkadaşlıklar yeterli gelmez artık.

Sevgiyi dışarıda ararsın.

Oysa burnunun dibindekini görmezsin.

Ya da hep acaba... 

Onu kaybedermiyim dersin.

Emin olamazsın.

Öyle ya senin için en acı olanı

Onu kaybetmektir, 

Çünkü onun arkadaşlığı bile 

Senin için sığınacak bir limandır

Bu curcunada.

Bu limanıda kaybedersen

fırtınada alabora olup

hayatın gerçekliği içerisinde boğulur gidersin.

İşte bu yüzden onu gözünden bile sakınırsın, 

Zarar görmesin diye.', 'Garip bir duygu yüklenir içine,  İsteksiz bir tebessüm boş bir bakış belirir yüzünde!  Anlam yoktur hiçbir şeyde,  Gece bitmek, zaman geçmek...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Gümüştekin']::text[], 8.5, '{"poet":"Ahmet Gümüştekin","poet_slug":"ahmet-gumustekin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/platonik-duygular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarına Ölmek', 'yarina-olmek-bulent-savkin-yxfac', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Doğan gün işarettir yarına

İradedışıdır etkilemek seheri.

İki ileri bir geri

Durunca bir yürek

İşarette kalınır

Oysa güneş ürkek

Yeniden doğacaktır

kalanların üzerine 

ve giden unutulacaktır

Sevdaları gidince

sözleri yitince

son kez anıldığında 

gerçekten bitecektir.

           (15.01.2002

          Çiftehavuzlar.İST.)', 'Doğan gün işarettir yarına İradedışıdır etkilemek seheri. İki ileri bir geri Durunca bir yürek İşarette kalınır Oysa güneş ürkek Yeniden doğ...', ARRAY['Türk Edebiyatı','Şiir','Bülent Şavkın']::text[], 8.5, '{"poet":"Bülent Şavkın","poet_slug":"bulent-savkin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yarina-olmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Bulmak', 'seni-bulmak-aytac-altinok-5h6vq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yarınları unutup yüreğime sahip çıkamamak istemem

Yıldızları gözlerinde saklayıp orda uyumalıyım

Geceleri yitrdiğimde sen ol yanımda ki ölmeyeyim

Sen hasretini koyup gitme yeter ki sevdalım

Oyuncağım ol kaybedip bulduğumda sevindiğim

Suyum ol sana susadığımda kanarak içeyim

Aşım ol, ekmeğim ol hayatımı sana vereyim

Yeter ki yanımda ol bu gece uyuyayım..

Yollarım ol hasretten vuslata kavuştur yüreğinle

Koynumdaki resmin içime işlesin sana öleyim

Bir yanım bahara bir yanım güze bakarken sen gel

Gel ki yüreğim sıcaklığına yeniden kavuşsun...', 'Yarınları unutup yüreğime sahip çıkamamak istemem Yıldızları gözlerinde saklayıp orda uyumalıyım Geceleri yitrdiğimde sen ol yanımda ki ölme...', ARRAY['Türk Edebiyatı','Şiir','Aytaç Altınok']::text[], 8.5, '{"poet":"Aytaç Altınok","poet_slug":"aytac-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-bulmak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi ki', 'i-yi-ki-i-brahim-yavuz-bildik-t3ve4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'i y i   k i

iyi ki habersiz geliyor ölüm

yoksa

boşaltırdık içini yaşamın

iyi ki habersiz geliyor ölüm

biz öldürmeden umutları

iyi ki

sadece sanıyoruz

yeterince dost olmadıklarını

iyi ki görünmüyor

riyâlara gömülü yosun tutmuş kaygan yürekler

yoksa

nasıl sanardık sevenlerin çokluğunu

yoksa 

nasıl sevebilirdik insanları

iyi ki habersiz geliyor ölüm.

                                29.04.2000 adana', 'i y i   k i iyi ki habersiz geliyor ölüm yoksa boşaltırdık içini yaşamın iyi ki habersiz geliyor ölüm biz öldürmeden umutları iyi ki sadece ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yavuz Bildik']::text[], 8.5, '{"poet":"İbrahim Yavuz Bildik","poet_slug":"i-brahim-yavuz-bildik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/iyi-ki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarhoşluğum', 'sarhoslugum-meric-kumbul-cxga3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kelebek ömrü bir hayale düşüyor, 

yolunu şaşırmış göçmen bir kuş kanadında

uçup gidiyor mevsimlik aklım.

Sonra birden soğuk diyarlarda uyanıyorum 

neyse ki bir kibrit kutusuna sığdırdığım umutlarım cebimde

çıkarıp bir bir yakıyorum onları

yine de üşüyorum

Ama yine de bu titrek soğuğu seviyorum!     

Uykulu sessizliğimde dalıyorum tekrar; 

bir tebessüm yetiyor sönük yelkenlerimi doldurmaya

ve sürüklüyor beni ıssız, çıkılmaz girdaplara

bu kez dibinde uyanıyorum bir bardağın 

dolu olsa tek yudumda içeceğim bu kadehi.                      Oysa her uyanışımda boş buluyorum

yine de sarhoş oluyorum 

ama yine de bu boş kadehteki sarhoşluğu seviyorum! 

Yine de seviyorum!', 'Kelebek ömrü bir hayale düşüyor,  yolunu şaşırmış göçmen bir kuş kanadında uçup gidiyor mevsimlik aklım. Sonra birden soğuk diyarlarda uyanı...', ARRAY['Türk Edebiyatı','Şiir','Meriç Kumbul']::text[], 8.5, '{"poet":"Meriç Kumbul","poet_slug":"meric-kumbul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sarhoslugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melih Cevdet Anday''a ithafen', 'melih-cevdet-anday-a-ithafen-baris-akm-5dzew', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şiirlerdeki mevsim sonbaharda bıraktın 

Sustu belki bir yüreğin kalemi

Belki söndü bir ateşin bedeni

Sonbaharda bekleyen kuşlar öksüz şimdi

Belki demem şaşırtmasın

Ölmez geride iz bırakanların nûru

Elbet yaşar içinden ağrı işlediğin gökkuşağı

Dinlenme zamanın gelmiş olabilir mi? 

Yoksa adına ne denir böyle gidişin? 

Susan sadece bir kalem değilki

Kapanan bir çift göz hiç değil heleki

Melih Cevdet Anday O''nun adı

Adının altında acemi bir kalemin, adına bir şeyler

yazmaya çalışması ne kadar zormuş meğer, 

bağışla saygıdeğer usta desem duyar mısın? 

Duyupta bağışlar mısın? 

Hiç kuşkum yok bağışlarsın...

Nur  içinde yat güzel insan...', 'Şiirlerdeki mevsim sonbaharda bıraktın  Sustu belki bir yüreğin kalemi Belki söndü bir ateşin bedeni Sonbaharda bekleyen kuşlar öksüz şimdi ...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/melih-cevdet-anday-a-ithafen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nafile', 'nafile-aziz-pinar-wa68a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nafile ne yapsam aşk bu kadarmış

Sıcağı kalmadı bitti güneşin

Yalnız ayrılıktı ölüm değildi

Gözlerime perde oldu gidişin

Ayrılık esmeyen uslu rüzgardı

Ayrılık rüzgarlar bir fırtınaydı

Ölüm gibi geldi dünyam karardı

Gözlerime perde oldu gidişin', 'Nafile ne yapsam aşk bu kadarmış Sıcağı kalmadı bitti güneşin Yalnız ayrılıktı ölüm değildi Gözlerime perde oldu gidişin Ayrılık esmeyen usl...', ARRAY['Türk Edebiyatı','Şiir','Aziz Pınar']::text[], 8.5, '{"poet":"Aziz Pınar","poet_slug":"aziz-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/nafile-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Yaşamak', 'seni-yasamak-bahri-sohtorik-7jayk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilirmisin ne demektir

Seni yaşamak, 

Kavramların ötesinden

Seni hissetmek, 

Erişilmez güzellikleri paylaşıp da

Gökkubbeye yukardan bakmak

Damarlarda dolaşıp, kalpte atmak

Bu bedende o ateşi yakmak

Bilirmisin ne demektir', 'Bilirmisin ne demektir Seni yaşamak,  Kavramların ötesinden Seni hissetmek,  Erişilmez güzellikleri paylaşıp da Gökkubbeye yukardan bakmak D...', ARRAY['Türk Edebiyatı','Şiir','Bahri Sohtorik']::text[], 8.5, '{"poet":"Bahri Sohtorik","poet_slug":"bahri-sohtorik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seni-yasamak-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmzaya Beş Kala', 'i-mzaya-bes-kala-bahri-sohtorik-k4nq4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne de güzel yaratmıştır yaradan

Aylar yıllar geçse bile aradan

Yaşadığım anlar zaten sıradan

Buradayım, şu imzaya beş kala

Sen en güzel demlerini yaşarsın

Kına yakmış, duvak takmış, coşarsın

Ciğerlerim pare pare deşersin

Buradayım, şu imzaya beş kala

Gözyaşımı kattım akan sellere

Elemimi verdim esen yellere

Gülüşümü eş kılarak güllere

Buradayım, şu imzaya beş kala

Bir telaştır aldı aklın yerini

Gören gözler görmez mi kederini

Bir öpüşle noktalasan da beni

Buradayım, şu imzaya beş kala', 'Ne de güzel yaratmıştır yaradan Aylar yıllar geçse bile aradan Yaşadığım anlar zaten sıradan Buradayım, şu imzaya beş kala Sen en güzel deml...', ARRAY['Türk Edebiyatı','Şiir','Bahri Sohtorik']::text[], 8.5, '{"poet":"Bahri Sohtorik","poet_slug":"bahri-sohtorik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/imzaya-bes-kala-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışkanlık Olsun Gülümsemen', 'aliskanlik-olsun-gulumsemen-derin-oger-srjlg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Son sözünü söyleme

Salatası olur lafın

Uzakta kalsın yılların isi

Belki yağmur sana da çiseler

Küçük defterler kapandığında

Büyüğüdür açılan

Gerçek olan değilmidir

En son farkedilen

Alışkanlık olsun gülümsemen.........', 'Son sözünü söyleme Salatası olur lafın Uzakta kalsın yılların isi Belki yağmur sana da çiseler Küçük defterler kapandığında Büyüğüdür açılan...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/aliskanlik-olsun-gulumsemen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüyor Güneş', 'usuyor-gunes-murat-tali-nn5wq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gün, hep gülüşle teslim etmiyor kendini geceye

gece, hep çiğ taneleriyle başlamıyor güne

tanyeri hep kızıl olmuyor

saatler hep aynı ilerlemiyor günün içinde

korkulukları açılmıyor pencerelerin

dalgalar aynı sessizlikle vurmuyor sahile

batıyor kimi zaman tekneler denizlerde

dervriliyor en güçlü ağaçlar hafif rüzgarlarda

mutluluk her zaman sarmıyor 

beyaz duvakların sardığı gibi 

bir gelinin başını

kimi zaman bulutlarda terketmiyor güneşi

üşüyor insan yalnızlığından

üşüyor güneş....', 'gün, hep gülüşle teslim etmiyor kendini geceye gece, hep çiğ taneleriyle başlamıyor güne tanyeri hep kızıl olmuyor saatler hep aynı ilerlemi...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/usuyor-gunes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşi Yitirir Zaman', 'gunesi-yitirir-zaman-murat-tali-aa56v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'odada yanan sobanın 

sıcaklığı vuruyor yüzüme

düşünüyorum... 

sıcaklığınla sardığın tenimi

ürperiyorum 

şimdi soğuk bir kış günü yaşanıyor belki dışarıda

belki seni de soğuk rüzgarlar sarıyor

sarsam düşlerimle ısınırmı ellerin

sıcak nefesimi katsam

çözülürmü buz tutmuş nefesin

yaprakları yok ağaçların 

çıplaklığıyla sarmalarken binlerce 

üşümüşlüğü

sıcaklığıyla saran var mı onlarıda 

kış ne yaman ayrılıklar doğurur 

ve yeşili yitirir gün

güneşi yitirir zaman

sıcaklığı yitirir insan

terkettiğim, 

terkedildiğim sıcaklıklarla gel', 'odada yanan sobanın  sıcaklığı vuruyor yüzüme düşünüyorum...  sıcaklığınla sardığın tenimi ürperiyorum  şimdi soğuk bir kış günü yaşanıyor b...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gunesi-yitirir-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varlığını Arayan Çocuk', 'varligini-arayan-cocuk-umut-ulbegi-bbjcn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yarım kalan geceyi tamamladım

parmaklarım usta bir manevrayla sardı kurbanını

içime çektim ilkel korkularını

ve korkusuz gözlerle süzerken yırtılan bedenimi

yasakladım ona cehennem kapılarını

Gözlerini aldım önce

sonra kollarını ve bacaklarını

geceye dumanlı kırmızılar kattım

Tanrı''nın tualini yeniden yarattım

Dudaklarını kıpırdatıyordu belki

belki en sansürsüz küfürleriydi onlar 

hiçbiri yankılanmadı o mavi sokakta

ses telleri ellerimdeyken

Çırılçıplaktı

tersyüz ettim bir anda vücudunu

bulutların yıldızlara

yıldızların denizlere yaptığı gibi

önce kalbi 

sonra ruhu

ve soru işaretleriyle dolu beyni 

katıldı değişime 

4. caddede 

seçim yatırımı parklarından birinde

yalnız bir çocuk heykeli var

çocuk olamamış yalnızlıktan

kuşlara düşman

şimdi o 

hem katil

hem insan.', 'Yarım kalan geceyi tamamladım parmaklarım usta bir manevrayla sardı kurbanını içime çektim ilkel korkularını ve korkusuz gözlerle süzerken y...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/varligini-arayan-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairler*', 'sairler-bayram-tunca-p8qb1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öpüştü mü, kalemleri kağıtla

Yanar yürekleri, aşkla/şevkle

Fırtınalar kopar, belleklerinde

Girdaplar oluşur, deryalarında

Heceleri, belleklerinde süzerler

Kelimelerle methiyeler düzerler

Bazen sevindirip, bazen üzerler

Aynı duyguları onlar da yaşarlar

Onlar, deste deste şiirler yazarlar

Dost/düşman herkesle paylaşırlar

Bazen alkışlanıp, bazen taşlanırlar

Her insan gibi onlar da yaşlanırlar

Heceleri göz nurlarıyla harç yaparlar

Kelimelerle, şiir kuleleri inşa ederler

Bazen içinden bazen dışından bakarlar

Beğenmediklerini yıkıp tekrar yaparlar

İnsanlar, bir yılda dört mevsim yaşarlar

Şairler ise, günde dört mevsim yaşarlar

Bazen, yazda kışı veya kışta yazı yaşarlar

Bilen bilir, bilmeyen şairin haline şaşarlar

Onların duyuları, sanki alıcı anten gibidir

Duyguları da, sanki azgın dalgalar gibidir

Yiyip/içtikleri her şeyden farklı haz alırlar

Görüp, duyup, tattıklarını da şiirleştirirler 

Sanki, gece kuşu misali uyumazlar geceleri

Yazarlar da fakat anlaşılmaz bazen heceleri

Mecnun zanneder, onları görenlerin niceleri

Taşa/taca aldırmadan, yazarlar onca şiirleri

Bazıları gibi hisli, bazısı gibi yaşlıdır gözleri

Ama çoğu kez, kılıçtan bile keskindir sözleri

Öyle ki bir sözle ya başlatır, ya keser savaşı

Yine sözle, ya kestirir başı, ya affettirir başı

Esen yelden etkilenen yaprak gibidir hisleri

Bazen, kabaran dalgalar misalidir duyguları

Çoğu zaman, dumanlı dağlar gibidir başları

Bazen, oku gerilmiş yay gibidir hilal kaşları

Çok azı enaniyetli olsa da ekseriyeti izzetlidirler

Sevmezler zilletle yaşamayı ondan dikbaşlıdırlar

Bazı baldan tatlı, bazı baltadan keskindir sözleri

Bazen ay’ın on dördü misali mıknatıslıdır gözleri

Şairlerimiz, toplumun ve yaşadığı asrın aynasıdırlar

Yazdıkları şiirlerle de tarihimize not düşmüş olurlar

Nice yüzyıllar gelip/geçse dahi şairler unutulmazlar

Çünkü, şiirleri belleklerde, isimleri yüreklerdedirler

11.11.2002-11.11', 'Öpüştü mü, kalemleri kağıtla Yanar yürekleri, aşkla/şevkle Fırtınalar kopar, belleklerinde Girdaplar oluşur, deryalarında Heceleri, bellekle...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/sairler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulut Mevsimi', 'bulut-mevsimi-umut-ulbegi-qycjn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dün bulutlandım

ciddiyim

resmen bulutlandım

ilk yağmuru ben yağdırdım işte

yeni doğmuş bebeğin ilk gözyaşları

ilk çığlık

Ben yağmur gibi geldim sana dün

sen toprak gibi alsaydın beni içine 

bulutlanmazdım', 'Dün bulutlandım ciddiyim resmen bulutlandım ilk yağmuru ben yağdırdım işte yeni doğmuş bebeğin ilk gözyaşları ilk çığlık Ben yağmur gibi gel...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bulut-mevsimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş Böceği', 'ates-bocegi-abdullah-karaduman-h0k7h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen benim ateş böceğimsin

Karanlıkta parlayan, yolumu aydınlatan

Güneş doğsun istemem, korkarım kaybolmandan

Sen benim ateş böceğimsin

Karanlığıma yıldız gibisin

Okyanusumda bir inci

Karda açan tek çiçeksin

Sen hiç ateş böceği gördün mü?', 'Sen benim ateş böceğimsin Karanlıkta parlayan, yolumu aydınlatan Güneş doğsun istemem, korkarım kaybolmandan Sen benim ateş böceğimsin Karan...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karaduman']::text[], 8.5, '{"poet":"Abdullah Karaduman","poet_slug":"abdullah-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ates-bocegi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Hatırla...', 'beni-hatirla-yasar-aslan-tpzj1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her denize baktığında beni hatırla, 

Uçan martıların kanatlarında olacağım, 

Nerede bir sokak çocuğu görsen beni hatırla, 

Ben o  sokak çocuğunun gözlerinde  saklı olacağım.

Nerede bir rüzgar eserse  sesini dinle, 

Sana  şarkılar söylüyor olacağım...

02 – 12 – 2002    4: 30', 'Her denize baktığında beni hatırla,  Uçan martıların kanatlarında olacağım,  Nerede bir sokak çocuğu görsen beni hatırla,  Ben o  sokak çocu...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Aslan']::text[], 8.5, '{"poet":"Yaşar Aslan","poet_slug":"yasar-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/beni-hatirla-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günümüzde Şair olmak', 'gunumuzde-sair-olmak-bayram-tunca-co5rd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Günümüzde şair olmak demek

Zindanlara göze almak demek

Çileyi baştan kabullenmek demek

Ateşten bir gömlek giymek demek

Çilenin bin bir çeşidini göze almak

Bu yolda yürürken, vardır susamak

Belki, birileri tarafından susturulmak

Belki olasılıktır, bu yolda öldürülmek

Vardır, sanık sandalyesine oturmak

........lerde bir cani gibi yargılanmak

Neticesinde belki var mahkum olmak

Hatta, belki  ömür boyu yasaklı olmak

Bak şiir okuyanın bile kırık kolu kanadı

Ağır Mahkemede mahkum ettiler sanatı

Sanık sandalyesine oturttular sanatçıyı

Tayyib Erdoğan’da tattı bizzat bu acıyı

Günümüzde şair olmak çok zor sanattır

Sanat, televole pazarında satılmaktadır

İsterse, lâl-ü güher yazıp söylesin şair

Değilse medyatik, söylediği önemsizdir

Ondandır hem dili, hem kalemi tutuktur

Kadir/kıymet bilen yok, yüreği buruktur

Söyleyeceğini söyleyemedi, dili tutuktur

Yazacaklarını yazamadı, kalemi tutuktur

Dileğim odur ki; şairlerimiz susturulmasın

Yağmur yüklü bulutlar gibi dolup boşalsın

Söyleyeceklerini özgürce sansürsüz yazsın

Şiir severler de özgürce sansürsüz okusun

B. Tunca/09.11.2002-14.09', 'Günümüzde şair olmak demek Zindanlara göze almak demek Çileyi baştan kabullenmek demek Ateşten bir gömlek giymek demek Çilenin bin bir çeşid...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gunumuzde-sair-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Gözlüme', 'guzel-gozlume-zulkuf-cengiz-sgf59', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Elini bir uzatsan...güneş dogacak yüzüme, 

Saçların bir başka dalgalanacak...GÖKYÜZÜNDE...

Ellerin beni seçerken, , , nefesinin hissetmek tenimde

Yüreğine dokunmak..çocuksu bir gülüşle 

Senden beni anlamak...veya...

Anlatmak sana olan duyğuları

Geceyi yüzünü çevirirsen yaşayacağım...

Gözlerini kapama ağlayacağım..

Ve sen beni anladığında? ? ? ? ? ? 

SENİ SEVİYORUM diye haykıracağım

Dağları bakışınla eritip sevenleri kavuşturacaksın...

Sevgileri gönlüme yalnızca sen dolduracaksın...

Zaman senden izin isteyecek geçmek için 

Yağmurlar senin olduğun yere güzel....

Olmadığın yeri ezip geçecek...

Kar sen istersen yağacak...

Rüzgar sen istersen esecek...

Denize rengini sen söyleyeceksin...

Gül olup hep güleceksin..gönül bahçemde

ve yaşama sen anlam vereceksin güzel gözlüm 

GÜZEL GÖZLERİNLE

bu şiir sade ve sadece dünyanın en tatlı en güzel en sıcak ve sevgilerin en sonsuzunu hakeden serpil için yazılmıştır(04/06/2002)', 'Elini bir uzatsan...güneş dogacak yüzüme,  Saçların bir başka dalgalanacak...GÖKYÜZÜNDE... Ellerin beni seçerken, , , nefesinin hissetmek te...', ARRAY['Türk Edebiyatı','Şiir','Zülküf Cengiz']::text[], 8.5, '{"poet":"Zülküf Cengiz","poet_slug":"zulkuf-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/guzel-gozlume-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmüş Bir Arkadaştan Mektup', 'olmus-bir-arkadastan-mektup-melih-cevdet-anday-qwu07', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eskisi gibi yaşıyorum

Gezerek, düşünerek..

Yalnız biletsiz biniyorum vapura, trene

Pazarlıksız alış-veriş ediyorum.

Geceleri evimdeyim, rahatım yerinde

(Bir de sıkılınca pencereyi açabilsem)

Ah... başımı kaşımak, çiçek koparmak

El sıkmak istiyorum arada bir..', 'Eskisi gibi yaşıyorum Gezerek, düşünerek.. Yalnız biletsiz biniyorum vapura, trene Pazarlıksız alış-veriş ediyorum. Geceleri evimdeyim, raha...', ARRAY['Türk Edebiyatı','Şiir','Melih Cevdet Anday']::text[], 8.5, '{"poet":"Melih Cevdet Anday","poet_slug":"melih-cevdet-anday","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/olmus-bir-arkadastan-mektup-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgün Gemisi', 'surgun-gemisi-adem-bozdag-jcrc2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beyaz bir gemi seçtim senin için

Her sahile bir müjde

Her limana bir hüzün versin diye

Her kalkışta damla damla

Fırtınalar kopar gönüllerden

Meçhul bir sessizliğin

Yolcusu olur senin için

O Gemi hayalimde

Şimdi tek bir kürek var elimde

Akıntıya mağlup olmuşum

Yüreğim kanar

Savurur  beni hırçın dalgalarkayalıklara

Acılar denizinde boğuluken

Duyarım yosunların hıçkırıklarını

Bilki sevmekten yorulmadım

Sanmaki yüzerken boğulmuşum

Bilki aşkımı kalbimde taşıyacağım

Bilki yalnızlığın içinde kaybolmuşum

Şimdi ırmaklar benim için ağlar

Kan akar büyük yalnızlıklar içinde', 'Beyaz bir gemi seçtim senin için Her sahile bir müjde Her limana bir hüzün versin diye Her kalkışta damla damla Fırtınalar kopar gönüllerden...', ARRAY['Türk Edebiyatı','Şiir','Adem Bozdağ']::text[], 8.5, '{"poet":"Adem Bozdağ","poet_slug":"adem-bozdag","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/surgun-gemisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Gelir', 'gun-gelir-adem-bozdag-4l1o9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağlamak yakışmaz sana

Gülmeyi unutan kalbim  

Sadece acı ver bana

Yalnız Allah tır sevgilim

Güngelir arasan beni

Yağmur altında yalnızım

Bakışlarım yakar seni

Gökyüzünde bir yıldızım

Elbet bu benim kaderim

Yoktur kimselerle kavgam

Yalnız yolumdan giderim

Vurmayın bu benim sevdam

Gün gelir aklına gelirsem

Çilekeş sokaklarda yalnızım

Aşk yeli gibi esersem

Üzülme bu alınyazım.', 'Ağlamak yakışmaz sana Gülmeyi unutan kalbim   Sadece acı ver bana Yalnız Allah tır sevgilim Güngelir arasan beni Yağmur altında yalnızım Bak...', ARRAY['Türk Edebiyatı','Şiir','Adem Bozdağ']::text[], 8.5, '{"poet":"Adem Bozdağ","poet_slug":"adem-bozdag","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gun-gelir-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Geldim', 'sana-geldim-gokcen-duran-awrjh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mısraların  arasından   koşarak   geldim.

En   zor  kafiyeleri   yoklayarak   geldim

Bin   bir   şiir  yazmıştım, 

En   güzelini  sana  saklayarak   geldim.

Elime   kırmızı  gül   alarak   geldim.

Kalbime  bir avuç  kar  saçarak geldim.

Bin  bir   sır  saklı  kalbimde, 

En  güzelini  sana  açarak  geldim.', 'Mısraların  arasından   koşarak   geldim. En   zor  kafiyeleri   yoklayarak   geldim Bin   bir   şiir  yazmıştım,  En   güzelini  sana  sakl...', ARRAY['Türk Edebiyatı','Şiir','Gökçen Duran']::text[], 8.5, '{"poet":"Gökçen Duran","poet_slug":"gokcen-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sana-geldim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle Bana', 'soyle-bana-gokcen-duran-26kvx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Söyle   bana, 

Kaç   şairin

Ölüm   fermanı

Yırtıldı  elinde  ki, 

Mısra  divanı  kalpler

Sende   atıyor



Söyle   bana, 

Hangi   umutsuz   gözlere

Umut   verdin  ki, 

Sevdalı  gözler gemileri

Sende   yakıyor



Söyle  bana, 

Hangi  sevdaları

Besledin  avuçlarında  ki, 

Aşık, maşukta  şefkati

Sende  tadıyor



Söyle   bana, 

Hangi   simyacının

İksirine  sahipsin  ki, 

Ölümsüzlük   çeşmesi

Sende  akıyor', 'Söyle   bana,  Kaç   şairin Ölüm   fermanı Yırtıldı  elinde  ki,  Mısra  divanı  kalpler Sende   atıyor Söyle   bana,  Hangi   umutsuz   göz...', ARRAY['Türk Edebiyatı','Şiir','Gökçen Duran']::text[], 8.5, '{"poet":"Gökçen Duran","poet_slug":"gokcen-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/soyle-bana-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Baharım', 'i-lk-baharim-aziz-pinar-1j1vb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Coşkun akan selde sensin

Ilık esen yelde sensin

Kucak, kucak gülde sensin

Sen benim ilk baharımsın...

Yeşil beyaz dağlarınla

Çiçek taşan dallarınla

Kuytudaki karlarınla

Sen benim ilk baharımsın...

Yaşım kırkbeş, belki elli

Geçen tüm baharlar gibi

Gönlüm coşkun, gönlüm deli

Sen benim ilk baharımsın...', 'Coşkun akan selde sensin Ilık esen yelde sensin Kucak, kucak gülde sensin Sen benim ilk baharımsın... Yeşil beyaz dağlarınla Çiçek taşan dal...', ARRAY['Türk Edebiyatı','Şiir','Aziz Pınar']::text[], 8.5, '{"poet":"Aziz Pınar","poet_slug":"aziz-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ilk-baharim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arama Beni..', 'arama-beni-ugur-deniz-ulkegul-92mup', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu kaçıncı akşam, 

   Şimdi yokluğunu koysam cebime, 

   Birazda özleminden alıp yüreğime, 

   Deliler gibi dolaşsam......

   Belaya bulaşsam delikanlı öfkemle, 

   Aransam yani, durup dururken, 

   Tutup kodese tıksalar, soğuk suda ıslatsalar, 

   Sökseler birer birer tırnaklarımı, 

   Bana unutturur mu sanıyorsun, 

   Bende bıraktıklarını.......

   Bu kaçıncı, boran, 

   Kaçıncı yangın bu, kaçıncı alev

   Umutlarımı savurup yakan.....

   Adresini yitirdim, 

   Seni kurtlar sofrasında, 

   Üç beş çakala yedirdim.......

   Şimdi kalemin ucundasın, 

   Şiirin tadında...

   Sen diyesim geliyor her sözün başlangıcında...

   Siyah bir çizgi oluyorsun beyazın utandığı, 

   Düşlerim tıkanıp kalıyor boğazıma, 

   Bir yalan oluyorsun, 

   Dünyada ki bütün çocukların inandığı......

   Bu kaçıncı sorgu, 

   İçimde yeniden, 

   Ve yeniden beliren arsız bir korku.....

   Üstelik sigaram da az önce bitti, 

   Üstelik çayım da soğudu bardakta, 

   Üstelik sevişmek istedi canım yine, 

   Ter kokumuzun sindiği, dağınık bir yatakta..

   Yani kelepçesiz ama tutuklu halimle sana, 

   Can çekişiyor yine sevdam......

   Her gün binlerce kalem kırılıyor elimde, 

   Binlerce kalem kırılıyor yüreğimde.....

   Yazdığım sözler anlamsız kılıyor varlığını, 

   Bazen yol oluyorsun, 

   Bazen bulut, 

   Bazen ün..

   Ve her buluşumda binlerce kez kayboluyorsun, 

   Seni yitirdiğim gün............

   Şimdi arama beni, 

   Bütün utanmaların sahibi benim, 

   Bütün suçların faili, 

   Bütün ayrılıkların şiddetli mümessili..

   Arama beni gülüm, 

   Bütün yorgunluklar benim, 

   Bütün tükenişler, 

   Bütün terkedilişler.......

   Bulsan bile bir şey değişmeyecek biliyorum, 

   O günden beri, sen bana yaklaştıkça, 

   Ben gidiyorum.....................................

   03..12..2002', 'Bu kaçıncı akşam,     Şimdi yokluğunu koysam cebime,     Birazda özleminden alıp yüreğime,     Deliler gibi dolaşsam......    Belaya bulaşsa...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/arama-beni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram', 'bayram-gaffar-karadogan-k0bzh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bayram geliyor haberiniz ola

Bırakın kederi bir kenara

Her yer sevince kesecek

Böyle olmalı

Böyle diyor tüm inançlar

Ve de felsefi akımlar

Bayram geliyor haberiniz ola

Bir telaş olmalı orta yerde

Evler kendinin en güzeli

Giyitler kendi sınıfının en güzeli

Yemekler kendi kültürünün en güzeli

Bayram namazı ile başlardı gün

Önce gidilirdi toprak altındakilere

Gidilirdi başka dünyalara

Ardından ziyaretler gırla

Oruç tutulmasa da

Bayram geliyor haberiniz ola

Oruç tutmadık ama

Şarabı da kesmiştik bir ay boyunca

Belli mi olur

Gazaba gelmek var işin ucunda

Bayram geldi

Verin kendinizi şaraba ve aşka.', 'Bayram geliyor haberiniz ola Bırakın kederi bir kenara Her yer sevince kesecek Böyle olmalı Böyle diyor tüm inançlar Ve de felsefi akımlar B...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bayram-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden', 'neden-gaffar-karadogan-u2xa5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O titreyen ses

Silinmiş yüz ifadesi

Yere bekan gözler

Bir kaç damla göz yaşı

Nedendir? 

Med-cezirler

Nedendir? 

Tutsaklığımız birbirimize', 'O titreyen ses Silinmiş yüz ifadesi Yere bekan gözler Bir kaç damla göz yaşı Nedendir?  Med-cezirler Nedendir?  Tutsaklığımız birbirimize...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/neden-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelemem', 'gelemem-ali-niku-y63w0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gelemem, hiç gelemem 

böyle naza cilveye 

vallahi de gelemem 

eğrilen baş olsada 

sim kuşak kuşansada 

söylemleri batsa da 

böyle naza işveye 

vallahi de gelemem 

alımıyla çalımıyla 

kaf dağında burnuyla 

kiraz gibi dudağıyla 

baygın göz süzmeye 

vallahide gelemem 

süzüm süzüm süzülse 

dudağını kıvırsa 

hıhh, diye çalım satsa 

kendini birşey sansa 

vallahi de gelemem 

araya biri girse 

aramızı düzeltse 

kırgınlıklar son bulsa 

iki cihan bir olsa 

vallahi de gelemem 

eski ben şöyle dursun 

derse, yenisi gelsin 

hatır gönül kırmadan 

birazcık yere insin 

vallahi de gelemem 

billah ben ben olamam', 'gelemem, hiç gelemem  böyle naza cilveye  vallahi de gelemem  eğrilen baş olsada  sim kuşak kuşansada  söylemleri batsa da  böyle naza işvey...', ARRAY['Türk Edebiyatı','Şiir','Ali Niku']::text[], 8.5, '{"poet":"Ali Niku","poet_slug":"ali-niku","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gelemem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Kimim', 'ben-kimim-ali-niku-dyf4n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ilkin bir sperm idim 

serseri mayın gibi 

uygun ortam bulunca 

patlayarak oluştum 

nefes aldığım anda 

sen bebeksin dediler 

çocukluğu es geçip 

gençlikle kucaklaştım 

olgunluğu içimde 

yapayalnız yaşadım 

evrimi tamamlarken 

varlığımı keşfettim 

yokluğumu ararken 

ölüsün sen dediler 

işte, vardım ve yoktum 

şu kısacık döngüde 

kalp kırmadan var olsak 

şu ölümlü dünyada... 

21.11.2002...niku', 'ilkin bir sperm idim  serseri mayın gibi  uygun ortam bulunca  patlayarak oluştum  nefes aldığım anda  sen bebeksin dediler  çocukluğu es ge...', ARRAY['Türk Edebiyatı','Şiir','Ali Niku']::text[], 8.5, '{"poet":"Ali Niku","poet_slug":"ali-niku","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ben-kimim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fal', 'fal-ali-niku-utxxh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'inanmamak mümkün mü 

kahvenin telvesine..? 

ne zaman ki toplanıp 

dostluğa hatır katsak 

hemen fincan çevrilir 

hayaller dağıtılır 

yüreciğin kabarmış 

bir uzun yol diyorlar 

üç vakitten bahsedip 

umut aşılıyorlar... 

20.11.2002..niku', 'inanmamak mümkün mü  kahvenin telvesine..?  ne zaman ki toplanıp  dostluğa hatır katsak  hemen fincan çevrilir  hayaller dağıtılır  yüreciği...', ARRAY['Türk Edebiyatı','Şiir','Ali Niku']::text[], 8.5, '{"poet":"Ali Niku","poet_slug":"ali-niku","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/fal-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekârlığa Veda', 'bek-rliga-veda-ali-niku-aabca', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bahar''la yaz''ın kucaklaştığı bir günde

işle haşır neşir geçen günün birinde...

birini ısırdı gözüm, seyirir olduğunda

narin bir pantolon, alımlı gösteriyordu 

çok etkilemişti beni, öyle göründüğünde.! 

ama çok kıskanmıştım, birinin görmesini

denemek için yaklaştım çekinerek yanına

hiç sevmiyorum dedim, böyle giyen hanımı

boynunu eğerek utandı, sessizce uzaklaştı

öğle paydosunda, çıkıyorduk yemeğe

o alımlı genç hanım evine doğru gitti

bana şirinlik için pantolon değişmeye

işte o anda çaktı tüm şimşekler beynime

sonra fırsat kolladım, evlenelim demeye...

derken, olanlar oldu sessizce evlenmiştik

bir sınamak uğruna aile oluvermiştik...', 'bahar''la yaz''ın kucaklaştığı bir günde işle haşır neşir geçen günün birinde... birini ısırdı gözüm, seyirir olduğunda narin bir pantolon, al...', ARRAY['Türk Edebiyatı','Şiir','Ali Niku']::text[], 8.5, '{"poet":"Ali Niku","poet_slug":"ali-niku","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bekarliga-veda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buraya Kadar', 'buraya-kadar-jim-morrison-f5esu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Buraya kadar güzel dostum

buraya kadar tek dostum

ayrıntılı planlarımız buraya kadar

başka ne varsa buraya kadar

ne güvenlik, ne sürpriz buraya kadar

gözlerine bakmayacağım bir daha

neler olacağını tahmin edebiliyor musun

böylesine sınırsız ve özgürce

umutsuz bir ülkede

umutsuzca bir yabancının eline muhtaç

buraya kadar güzel dostum

buraya kadar eski dostum

buraya kadar ilgisiz dostum

buraya kadar tek dostum

buraya kadar

acı veriyor seni bırakmak 

ama beni izlemeyeceksin artık

gülüşler ve tatlı yalanlar buraya kadar

ölmeye çalıştığımız geceler buraya kadar

buraya kadar', 'Buraya kadar güzel dostum buraya kadar tek dostum ayrıntılı planlarımız buraya kadar başka ne varsa buraya kadar ne güvenlik, ne sürpriz bur...', ARRAY['Türk Edebiyatı','Şiir','Jim Morrison']::text[], 8.5, '{"poet":"Jim Morrison","poet_slug":"jim-morrison","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/buraya-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelirim', 'gelirim-ali-niku-t40fw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dostluğun kapısı istesende kapanmaz.

dostluğa hasretlik prangası vursanda 

kamplara bölünüp, parçalansak da

kapıya gerek yok, yüreğe gelirim.

yürekte yer yok diyorsan eğer 

istediğin baskasıymış meğer 

türlü bahaneler etmeye değer 

hiç sorun eyleme, dalağa gelirim

dalak problem şekerin mi var 

insülin gerekli zamanın mı dar? 

dostluğun kapısı bir bana duvar 

hiç sorun eyleme dudağa gelirim... 

dudagının rengi kiraz''a dönse 

sarhoş sofrasında mey ile yense 

mehtabın kızardıgı, zamanda gelse 

ışıl-ışıl bakan göze gelirim...', 'dostluğun kapısı istesende kapanmaz. dostluğa hasretlik prangası vursanda  kamplara bölünüp, parçalansak da kapıya gerek yok, yüreğe gelirim...', ARRAY['Türk Edebiyatı','Şiir','Ali Niku']::text[], 8.5, '{"poet":"Ali Niku","poet_slug":"ali-niku","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gelirim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Bu', 'hayat-bu-yavuz-turhan-y1f33', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İşte hayat bu; 

bazan bir insan çıkar karşına, 

bazan bir şarkı-türkü, 

bazan da bir şiir.

ölüm kadar soğuk ve sessiz oluruz.

ve aldatılmış.

düşünürüz: 

tanrı  bu acıları neden yaşatır? 

kimimiz boyun eğeriz, 

kimimiz isyan ederiz.

ellerimizi yeniden toprağa vurup, 

ayaklanırız.

yeniden yıkımlara gideriz.

hayat denen bu yolda.

hüzün yüklenmiştir bedenlerimiz.

karşımıza çıkacak acılar için tedarikliyizdir.

cebimizde durur, 

ama yüreğimizi yakmaktadır.

hayat budur işte gözbebeğim.

yaşayacaklarımız, 

özlemlerimiz, 

ilerde değil, 

uzaklardadır.

........................

hatta imkansızdır.', 'İşte hayat bu;  bazan bir insan çıkar karşına,  bazan bir şarkı-türkü,  bazan da bir şiir. ölüm kadar soğuk ve sessiz oluruz. ve aldatılmış....', ARRAY['Türk Edebiyatı','Şiir','Yavuz Turhan']::text[], 8.5, '{"poet":"Yavuz Turhan","poet_slug":"yavuz-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hayat-bu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alpler''de Randevu', 'alpler-de-randevu-mustafa-engin-karatay-i8tv9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Alpler''in eteğinde, bir yağmur çiseliyor

Günün ilk ışıkları, şafaktan kesiliyor

Kuşların cıvıltısı, neyzen âheng saçıyor

Sabâhın bu vaktinde, içimi hoş açıyor

Gül bahçesi âdetâ, etrâfım çiçek dolu

Eflâtun Erguvanlar, kaplamış sağı-solu

Az ilerde parke yol, önünde yaşlı Çınar

Arslanların ağzında, fıskiyeden Üç pınar

Büyük Üstâd Göthe''nin, Tunç Heykeli dikilmiş

Çok derinlere dalmış, düşünmeye çekilmiş

Altında plaket var; bir kaç yazı üstünde

San''âtına övgüler, sergilenmiş Büstü''nde

Biraz daha yürüdüm, Kuzey-Batı Yönü''ne

En sonunda ulaştım, Tiyatro''nun önüne...

Baktım Elif bekliyor, tam da vaktinde gelmiş

O da ne; aman, aman, sandığımdan güzelmiş...

Şaşkın şaşkın bakışla, bir süzdü beni şöyle; 

Parladı iki gözü, tebessüm etti öyle...

Üzerime vazîfe, verdim hemen selâmı

Başlatmış olduk tabi, böylelikle kelâmı

Kıyâfeti pek düzgün, hepsi yerli yerine

Kahverengi başörtü, yakışmış üzerine...

Müthiş kibâr cümleler, dilinden dökülüyor

Yüreğimin yağları, eriyip sökülüyor

Nâme gibi işliyor, çok da zarîf ses tonu

Cezbedici yapıyor, meziyyetleri O''nu...

***

Sohbet, muhabbet derken, epeyce de dolaştık

Felâket esprili, iyi de şakalaştık

Muhabbet fenâ sardı, ama bunun sonu yok

Nerden bilsin içimi; oysa derdim, acım çok...

Etkilendi benden ya, kalbim dolu nâfile

Vaktiyle kaptırmışım, kendimi bir Gâfil''e...

Dedim; 

- Sakın sevmeye kalkıp, bana ümid besleme! 

- Boş yere bekleyip de, hayâlini süsleme! 

- İyisin, hoşsun ama, benden sana yâr olmaz! ..

- Hümeyrâ''nın Makâmı; Yüz Elif olsa, dolmaz! ..

- Say ki düş âleminde, gördük güzel bir rüyâ, 

- İkimiz de derinden, uykudaymışız gûyâ...

***

- Ayrılık vakti geldi, yavaş yavaş gidelim...

- Bahtımız böyle imiş, artık vedâ edelim...

23.06.2001   Bodensee   11: 35', 'Alpler''in eteğinde, bir yağmur çiseliyor Günün ilk ışıkları, şafaktan kesiliyor Kuşların cıvıltısı, neyzen âheng saçıyor Sabâhın bu vaktinde...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/alpler-de-randevu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Kanatsız Saatleri', 'gecenin-kanatsiz-saatleri-kadir-koz-7zud7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'en fazla üşüdüğüm oluyorsun

gecenin kanatsız saatleri

o dağdan bu dağa vuruyor yüzün

gözünden tanıyorum kirpiklerini

çarşaf çarşaf askerlik anılarını

dinlermiş gibi yapmak gibi zor işi

başarıyorum

durmadan subay dövüyor

gülmüyormuş gibi yapmak gibi zor işi de

başarıyorum

sesinin görünmeyen ipleri

kement

sigaram

vahşi at

ve duvar boşluğunda soluyorum kederi

neyse

nerde kalmıştık abi

tam anlayamadım en son söylediğini

ne demişti sana

kumar masasında patakladığın

rütbeli', 'en fazla üşüdüğüm oluyorsun gecenin kanatsız saatleri o dağdan bu dağa vuruyor yüzün gözünden tanıyorum kirpiklerini çarşaf çarşaf askerlik ...', ARRAY['Türk Edebiyatı','Şiir','Kadir Köz']::text[], 8.5, '{"poet":"Kadir Köz","poet_slug":"kadir-koz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gecenin-kanatsiz-saatleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Filmin Kritiği', 'bir-filmin-kritigi-kadir-koz-7q4mu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ey hüznümün çiçeği

açma

ben libyalı ömer muhtar değilim

gözlüğüm yok

şehit çocuklarını güldüremem

ata binecek kadar da

cesur değilim

çöl

sırtlan kuşatması

süngü

vampir tırnağı

gebeydi kadın

neresinden vurmak gerek zamanı

kurşunsuz tüfek

sen 

git ömer muhtar

mazlum halklara ayet serperek

yaşa

ben hüznümün çiçeğiyle

bağlarım ipi

bacağıma

kaçacak kadar da

namert değilim', 'ey hüznümün çiçeği açma ben libyalı ömer muhtar değilim gözlüğüm yok şehit çocuklarını güldüremem ata binecek kadar da cesur değilim çöl sır...', ARRAY['Türk Edebiyatı','Şiir','Kadir Köz']::text[], 8.5, '{"poet":"Kadir Köz","poet_slug":"kadir-koz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bir-filmin-kritigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Revnakdar İpuçları', 'revnakdar-i-puclari-kadir-koz-7xwzk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kaldırım kalesine saldıran istismar bayrakları

illegal dualarla ilerliyor

zabıtalar aşkına

vurun

püskürtün akınları

fırsat bu fırsat çöpçü

süpürge taklası at

maaşına zam iste

nasıl olsa kurtaramazsın kaldırımları

boyacılar

çözüm sizsiniz

ya genel greve gidin

ya da yeşile boyayın ayakkabıları

dilenciler

göreyim sizi

toprak bedava kokmaz

kazıyın betonları

demin demidir

artık

şehri baldan tatlı yağmurlar yıkamalı', 'kaldırım kalesine saldıran istismar bayrakları illegal dualarla ilerliyor zabıtalar aşkına vurun püskürtün akınları fırsat bu fırsat çöpçü s...', ARRAY['Türk Edebiyatı','Şiir','Kadir Köz']::text[], 8.5, '{"poet":"Kadir Köz","poet_slug":"kadir-koz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/revnakdar-ipuclari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arama', 'arama-i-brahim-sahin-ctxmh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aramanın amacıdır Ayrı bilmesen de

Bulacağın hep gayrdır  Ayrı sende 

Aşk ayrıdır gayrdan ötede

Maşukta bulacağın gayrdır istemesende', 'Aramanın amacıdır Ayrı bilmesen de Bulacağın hep gayrdır  Ayrı sende  Aşk ayrıdır gayrdan ötede Maşukta bulacağın gayrdır istemesende...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Şahin']::text[], 8.5, '{"poet":"İbrahim Şahin","poet_slug":"i-brahim-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/arama-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kafam Kıyak', 'kafam-kiyak-charles-bukowski-390ab', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'en bağlayıcı emek

kutsanmış bir bayrak altında

iki yakanı bir araya getirmeye

çalışmaktır.

başkalarıyla

niyet benzerliği

aptalı

kaşiften ayırır.

bunu herhangi bir

bilardo salonunda, 

hipodromda, 

barda, üniversitede

ya da kodeste öğrenebilirsin.

insanklar yağmurdan kaçar

ama su dolu küvetlerde

otururlar.

milyonlarca insanın

hidrojen bombasından korkması

epey kasvetli

ancak 

zaten yaşamıyorlar ki.

yine de para kazanmaya

kadın kapmaya

mantıklı davranmaya çalışmayı

bırakmıyorlar.

ve sonunda Büyük Barmen

olanca beyazlığı ve saflığı

gücü kuvveti ve gizemiyle öne eğilip

yeterince içtin, der, 

tam da keyif almaya başladığında.', 'en bağlayıcı emek kutsanmış bir bayrak altında iki yakanı bir araya getirmeye çalışmaktır. başkalarıyla niyet benzerliği aptalı kaşiften ayı...', ARRAY['Türk Edebiyatı','Şiir','Charles Bukowski']::text[], 8.5, '{"poet":"Charles Bukowski","poet_slug":"charles-bukowski","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kafam-kiyak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimde Yalçın Dağlar', 'yuregimde-yalcin-daglar-abdulkadir-karaman-kgs3y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüreğimde yalçın dağlar…

Umudu kül olanım ben! ..

Gözlerimde kalbim ağlar…

Bahar gonca solanım ben! ..

Gerçek nerde, ben nerdeyim? 

Kendime kendim perdeyim

Her nefes bir siperdeyim

Cephelerde talânım ben! ..

Âlem benim için varsa..! ? 

neden canım, tenim parsa? 

Biri, derdim nedir, sorsa? 

Her kapıyı çalanım ben! ..

Bir gölgeden ibâretim

Canımda sılam, gurbetim

Hem misalim, hem ibretim

Hem gerçek hem yalanım ben! ..

Bir bilen yok kıymetimi

Kim? işgâlde devletimi

Ele verip servetimi

Mağdur, muhtaç kalanım ben! ..

Dumanıyım bir sarp dağın

Derler, yok mu sığınağın? 

Yeryüzünde darmadağın

Gökyüzünde îlanım ben! ..

Ne yaşattım, ne yaşadım

Sevinç, sevgiye susadım

Dert, çile, gama hasadım

İşgal olmuş alanım ben! ..

30.11.02', 'Yüreğimde yalçın dağlar… Umudu kül olanım ben! .. Gözlerimde kalbim ağlar… Bahar gonca solanım ben! .. Gerçek nerde, ben nerdeyim?  Kendime ...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yuregimde-yalcin-daglar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilimde Sessiz Sevda', 'dilimde-sessiz-sevda-birsen-saygin-c443n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen istedin, sustu dilim

Senli sohbetleri bir yabancı gibi dinledim, 

Sessizliği yükledim sesime, 

Ya da çekip gittim ilgisizce.

Gülüşümün yarısını silip, attım içime, 

Coşkularımı olmadık bahanelerin

Ardına gizledim.

Senin üzerine yürümesin insanlar diye, 

Ben yalnızlığa yürümeyi seçtim.

Suskunluğum, 

 Ayrılığın hüznü sanılıyor besbelli

“İyimisin” diye soruluyor aradabir

Rolümü öyle iyi oynuyorum ki, 

Ama utanıyorum..alkışlayamıyorum kendimi.

Akşam olunca; 

Sahneden kulise koşar gibi 

Uzaklaşıyorum soru işareti bakışlardan, 

Evime taşıyorum içimdeki mutluluğu

Koşar adım.

Bir şarkının nakaratı gibi

Dolanıyor dilime adın.

Karanlığa, duvarlara, kendime anlatıyorum seni

Boş odalara savuruyorum içimdeki sesleri

Adını anmayı

Yasakladığından beri.

                                25 / 11 / 2002', 'Sen istedin, sustu dilim Senli sohbetleri bir yabancı gibi dinledim,  Sessizliği yükledim sesime,  Ya da çekip gittim ilgisizce. Gülüşümün y...', ARRAY['Türk Edebiyatı','Şiir','Birsen Saygın']::text[], 8.5, '{"poet":"Birsen Saygın","poet_slug":"birsen-saygin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/dilimde-sessiz-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canımıniçi', 'caniminici-ali-fikri-karadeniz-z6tbl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönül soğuk, gönül yanlız, gönül sensiz, 

İçimde ki fırtınalar dinmiyor! 

Bir tek Sen varsın yüreğimde, 

Buram buram kar yağıyor...

Bir gönül sayfası açtım bembeyaz, 

Saçlar beyaz, ruhum beyaz, sevgim beyaz; 

Canımıniçi bembeyazsın! ! ! 

Tıpkı düşlerimde, tıpkı yüreğimde ki gibi; 

Seni sevmek onur veriyor bana, 

Gündüzümde gecemde, her yerimdesin

Canımıniçi Sen Birtanemsin! ! ! 

Öyle bir sevda ektim, 

Öyle mutluyum ki ben! ! ! 

Öyle huzur doluyum, 

Öyle sarhoşum ki ben, 

Aşkı seninle tattım seninle yaşıyorum; 

Canımıniçi Seni Çok Seviyorum! ! !', 'Gönül soğuk, gönül yanlız, gönül sensiz,  İçimde ki fırtınalar dinmiyor!  Bir tek Sen varsın yüreğimde,  Buram buram kar yağıyor... Bir gönü...', ARRAY['Türk Edebiyatı','Şiir','Ali Fikri Karadeniz']::text[], 8.5, '{"poet":"Ali Fikri Karadeniz","poet_slug":"ali-fikri-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/caniminici-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Anlatan Şiir', 'beni-anlatan-siir-yavuz-selim-dizdar-6605t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen bakınca neden içim bir garip olur, 

Soğuk terler boşanır sırtımdan

Kalbim hızlı hızlı çarpar

Ve yüzüne bakarken 

Kıpkırmızı olurum utancımdan

Kalkıp uzaklaşırım, 

Çekilip bir köşede sessiz sessiz ağlarım

Hayalin ardıma düşer

Ve sanki o güzel ellerin gözlerimi siler

Düşüncelerimi hayaline bile söyleyemem; 

Mahvolurum hırsımdan

Islak gözlerimi gözlerine uzatırım

Uzatırım lakin bir türlü ulaşamam sana 

Ben onlara bakar bakar doyarım

Neden bilmem sen dönersin başkasına

Bense ölürüm kahrımdan

Ellerim ellerine değince 

Kalbimi avucunda hissederim

Bütün söyleyeceklerim gözlerimde

Duygularımsa avucundadır

Neden bir türlü farkına varmazsın

Ve ben utanırım yalnızlığımdan

Aslında bunların sebebini biliyorum

Aklımdan bin türlü düşünce geçiyor

Söylemek istiyor söyleyemiyorumü

Dilimin ucuna kadar geliyor; 

Fakat hep orada kalıyor

Seni seviyorum diyemiyorum...', 'Sen bakınca neden içim bir garip olur,  Soğuk terler boşanır sırtımdan Kalbim hızlı hızlı çarpar Ve yüzüne bakarken  Kıpkırmızı olurum utanc...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Selim Dizdar']::text[], 8.5, '{"poet":"Yavuz Selim Dizdar","poet_slug":"yavuz-selim-dizdar","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/beni-anlatan-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tuval', 'tuval-nuri-gunduzalp-t4tcp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Resmini süt beyaz bir tuvale

bembeyaz bir kalemle işledim

Ve seni

Bir dolu tusak günlerde

ancak böyle gizleyebildim', 'Resmini süt beyaz bir tuvale bembeyaz bir kalemle işledim Ve seni Bir dolu tusak günlerde ancak böyle gizleyebildim...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gündüzalp']::text[], 8.5, '{"poet":"Nuri Gündüzalp","poet_slug":"nuri-gunduzalp","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/tuval-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '... Oldum', 'oldum-nuri-gunduzalp-xngyn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ana ben ozan oldum

Okuyup yazan oldum

Teneke bile değil iken

Aş pişen kazan oldum', 'Ana ben ozan oldum Okuyup yazan oldum Teneke bile değil iken Aş pişen kazan oldum...', ARRAY['Türk Edebiyatı','Şiir','Nuri Gündüzalp']::text[], 8.5, '{"poet":"Nuri Gündüzalp","poet_slug":"nuri-gunduzalp","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/oldum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığın Resmi', 'yalnizligin-resmi-yunus-gedik-iz5kb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalnızlığın resmini çiziyorum yine

Gecenin ağırlığını omzuma alıp seni unutmaya çalışıyorum 

Bildiğin ne kadar koyu ton varsa

Sürüyorum düşüncelerim üzerine

En çok siyah kullanıyorum

Siyah saçlarının rengi

Siyah gözlerinini rengi

Ve siyah kaderimin rengi

Ne kadar çabalasamda olmuyor 

Düşüncelerimi yansıttığım tuval hala bulanık 

Ve ben kör bir ressam gibi

Seni hissederek çiziyorum 

Ve hala seviyorum seni ilk gün gibi

Bitirmeyi hiç bir zaman başaramasamda

Yalnızlığımın resmini

Artık üzülmüyorum 

Ve hiç kimseye anlatamasamda sevgimi

Hala seni yaşıyorum

Hala seni düşünüyorum

Ve hala seviyorum seni ilk gün gibi', 'Yalnızlığın resmini çiziyorum yine Gecenin ağırlığını omzuma alıp seni unutmaya çalışıyorum  Bildiğin ne kadar koyu ton varsa Sürüyorum düşü...', ARRAY['Türk Edebiyatı','Şiir','Yunus Gedik']::text[], 8.5, '{"poet":"Yunus Gedik","poet_slug":"yunus-gedik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yalnizligin-resmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gunesin gozleri''nden', 'gunesin-gozleri-nden-ali-riza-arslan-2o5j8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '...

gözler açılır ağır gelen başlangıçta ya da hafif

fırtınalı ve genç, diri ve dolgun göğün altında

akar ağırca dolanır bütün çevreleri

dolanır ve sararak bakışları arkasından, geleni gideni onarmadan

sığındığı koyu. gözlerin renkli taşlardan, zümrüt ve altın.

saydamlık heceler dolgun isimlerini nesnelerin

zamanın altında toz, ağır su 

ve hafif doğan güneş aralarından yükselerek

çepeçevre sezerek doğudan ve batıdan

alevlenerek. Eski şarkılarda ormanın taşlarını

fısıldayan çalıdaki kuşlar, meyve arayan

bitimsiz gölgeler

eğilen başlar

açılan yüzler

kımıltısız rüzgârda

kıvrımları genişleyen zincirler

geceleyin yalımlı çukurlarına yatarlar

ve anlaşılmayan dizeleri gösterirler yaşam sunağından

...

halklar ve sürüler geçiyor sığ yerinde bir nehrin

zamanı umursamayan taşlar arasında ve gece

halklar ve arkası olmayan bir öykü söyleyerek, 

kini, öfkeyi, şu dumanı sürükleyerek dağılan sürüler

sırtlarındaki hançerle beslenen tepeler

ağır adımlar, yüksek boşluklar, yalancı kabuklar

yağmurla başlayan çatlak sesleri ve kıvrılarak

yükselip düşen şu dudaklar

verebilir mi bir ağıt gerçek annemize 

ve babamıza sorabilir miyiz acılı yüzünü onun

çanaklarda artık kalmış ömür çemberi

kaplanmış taşları? 

göğün kapaklarını

bilinen kıvrımları

köklerimizi ve mavi olmayan gökyüzünü ve denizi

anlayabilir miyiz fısıldasa taşlar kulağımıza?', '... gözler açılır ağır gelen başlangıçta ya da hafif fırtınalı ve genç, diri ve dolgun göğün altında akar ağırca dolanır bütün çevreleri dol...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Arslan']::text[], 8.5, '{"poet":"Ali Rıza Arslan","poet_slug":"ali-riza-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/gunesin-gozleri-nden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim Hoşçakal', 'sevgilim-hoscakal-funda-ayture-vlghj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Titrek kandilli göklerimde

İnanmıştım aşka oysa

Ellerinin limon çiçeği kokusuna vurgundum

Yüreğim, her tipide, her boranda

Seni örtünmüştü üstüne

Ben hep aşka ve hep sana inanmıştım bu dünyada

Sığındığım koy, dokunduğum ten

Hep sendin

Sense, hırçın yağmurlarla döküldün sokaklarıma

Bir serçenin kanını buladın ellerine

Gidiyorum sevgilim hoşçakal

Artık limon çiçeği kokmuyor ellerin

Ardımdan katırtırnakları ağlayacak

Üşüyecek naftalin

Hoşçakal sevgilim hoşçakal

En derin inançmış aşk

Yama tutmuyor

                       Funda Aytüre Az', 'Titrek kandilli göklerimde İnanmıştım aşka oysa Ellerinin limon çiçeği kokusuna vurgundum Yüreğim, her tipide, her boranda Seni örtünmüştü ü...', ARRAY['Türk Edebiyatı','Şiir','Funda Aytüre']::text[], 8.5, '{"poet":"Funda Aytüre","poet_slug":"funda-ayture","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sevgilim-hoscakal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asla! ..', 'asla-i-brahim-ozcan-aaj7k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kopardım bütün ipleri 

   Attım bütün köprüleri 

   Yaktım onca gemileri 

   Batırdım birer birer 

   Baltıklara gömüldüler 

   Gidiyorum..gidiyorum... 

   Diyordu ya şair 

   Ölümün ikiz kardeşi 

   O meş''um ayrılığa dair 

   Devran döndu...ben de gidiyorum.. 

   Hangi okla vurursan vur ardımdan 

   Hangi parçamı koparsanda canımdan 

   Hançerin pas tutmaz ki kanımdan 

   Kelam edersem eğer haram olsun 

   Emdigim her damla süt anamdan 

   Hangi hücresine hapsetsende yüreğinin 

   Hangi idama 

   Hangi sürgüne göndersen de 

   Her neyle suçlarsan suçla diledigin 

   Ama...Sevemeyişimle; asla! ..



Yasal Uyarı: İbrahim Özcan''ın bütün şiirleri noter tesbitli olup, izinsiz kullanılamaz,  yayınlanamaz ve ya alıntı yapılamaz;  telif hakları bakımından İLESAM (İlim ve Edebiyat Eserleri Sahipleri Meslek Birliği Uyesidir.

iletişim  90 536 293 86 38', 'Kopardım bütün ipleri     Attım bütün köprüleri     Yaktım onca gemileri     Batırdım birer birer     Baltıklara gömüldüler     Gidiyorum..g...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Özcan']::text[], 8.5, '{"poet":"İbrahim Özcan","poet_slug":"i-brahim-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/asla-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nil Hastalığı', 'nil-hastaligi-gaffar-karadogan-f1u2k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hani bir nefrit vardı

    önce podositlerin ayaklarını kaybettirdi

    kimse fark etmedi

    sonra on gram protein kaybettirdi

    yüzü gözü şişti çocuğun

    herkes fark etti

    doktor steroid dedi

    nefrit cevap vermedi

    acelemiz yok dört ay bekleriz

    ama hala cevap vermedi

  

    çağırın siklofosfamid ve siklosporini

    minimal değişiklik yapma sırası bizde

    bir yanda 

    siklofosfamidin gonadal toksisitesi

    bir yanda

    yüzü gözü şiş çocuğun sesi

  

    cevap verdi nefrit

    gelin gram konusunda anlaşalım

    bir gram bile protein kaybına 

    tahammülümüz yok

    kararlıyız 

    kuracağız selektif bariyeri', 'hani bir nefrit vardı     önce podositlerin ayaklarını kaybettirdi     kimse fark etmedi     sonra on gram protein kaybettirdi     yüzü gözü...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/nil-hastaligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fertilizasyon', 'fertilizasyon-gaffar-karadogan-d38jx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'biri ovum

insanın en tarihi hücresi

geçmişi ıntrauterin dönemde

biri sperm

insanın en yeni hücresi

yeni başlıyor öyküsü

buluşacaklar 

tuba uterinada

ovum hazırlık içinde

kutup cisimleri oluşturulmuş

kromozomlar yarıya inmiş

yaşamın yarısı var onda 

bekliyor ampullada

milyonlarca sperm omuz omuza

taşıyorlar sanki

olimpiyat meşalesini

yolları uzun işleri zor

nazlıdır bekletmeye gelmez ovum

işte göründüler

ve gördüler ovumun kemotaksisini

bir denizci feneri gibi

buluştular ampulla kıyılarında

tek hücre var artık

iki yaşam yarısı

çıkıyorlar büyük yolculuğa', 'biri ovum insanın en tarihi hücresi geçmişi ıntrauterin dönemde biri sperm insanın en yeni hücresi yeni başlıyor öyküsü buluşacaklar  tuba u...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/fertilizasyon-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Crocodile Sendromu', 'crocodile-sendromu-gaffar-karadogan-nsuds', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'akıttı göz yaşını 

nervus fasiyalis, yedinci sinir

çiğnetti bir lokmayı

nervus trigeminus, beşinci sinir

birleştiler bir timsah anatomisinde

beşinci ile yedinci

çiğnerken ağladı timsah

yavrusunu yedi 

tutamadı göz yaşlarını

kardeşini öldürdü insan

zafer çığlığı attı

ağlayamadı

timsahtan geri kaldı', 'akıttı göz yaşını  nervus fasiyalis, yedinci sinir çiğnetti bir lokmayı nervus trigeminus, beşinci sinir birleştiler bir timsah anatomisinde...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/crocodile-sendromu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahmure', 'mahmure-gaffar-karadogan-wfauo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'acının başlangıcıydı doğum

böbreğini kaybetti

çocuğuyla beraber

anne olamadı mahmure

bir böbrek bulundu

yaşasın! 

mahmureyle birlikte

baskı altında olmalı

alıcının bir yanı

kardeşlik için

ne tuhaf

altın rengindeydi

transplante edilen böbreğin idrarı

sorarsanız Mahmut Hocama

transplant böbreğin idrarının 

ayarı bile vardı

düşmez yirmidörtten aşağı

onyedi yıl yaşadı

misafir böbrek 

mahmure ile birlikte

ayrılık vakti geldi 

yılların sonunda

böbrek mahmureye küstü

mahmure hayata', 'acının başlangıcıydı doğum böbreğini kaybetti çocuğuyla beraber anne olamadı mahmure bir böbrek bulundu yaşasın!  mahmureyle birlikte baskı ...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/mahmure-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tolerans', 'tolerans-gaffar-karadogan-ucxvw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kendinden olana tolerans

kaybolunca

kemirmeye başlarlar seni

makrofajlarca

küçük parçalara ayrılır

işlenirde sunulursun

immün sistem sofrasına

yaralısın artık

bir yanın yangı yeri

yaranı dostuna göster

ancak o anlar seni

beklemek olmaz artık

damar endotelinde

veya dalak sinüzoidinde

duyarlı bir lenfosit isen 

duramazsın yerinde

bir süpresör T hücresi olmuşum

immünitenin yok edildiği 

alanlara gidiyorum

su damlası olsamda

yangına 

yangıya gidiyorum

belki bowman aralığı

belkide disse aralığıdır

ulaşılacak yer

hızla ilerleyen  glomerulonefriti

hızla ilerleyen otıimmün hepatiti

hızla ölenleri düşünüyorum

ierliyorum yangı yerine

önce ulaşırım diye

yanıma immünsüpresif ailesini alıyorum

kalabalık oluyorum

gidiyorum gidiyorum

kendinden olanı tanımayanı

protesto ediyorum', 'kendinden olana tolerans kaybolunca kemirmeye başlarlar seni makrofajlarca küçük parçalara ayrılır işlenirde sunulursun immün sistem sofrası...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/tolerans-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık', 'kirik-gaffar-karadogan-0vgpu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Parçalı kırık 

Kalbim

Kallus kadar

Direngen artık', 'Parçalı kırık  Kalbim Kallus kadar Direngen artık...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kirik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömür', 'omur-gaffar-karadogan-sjzq2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ömür dediğin nedir ki

eritrosit için yüzyirmi gün

aşırı duyarlılık 

hesapta yoksa eğer', 'ömür dediğin nedir ki eritrosit için yüzyirmi gün aşırı duyarlılık  hesapta yoksa eğer...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/omur-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hastane Koridorları', 'hastane-koridorlari-gaffar-karadogan-kgdhn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir hastane koridorunda 

yaşandı yaşanacak anlattıklarımız

kapıdan giriyorum

başlıyor yeni bir dünya

selam veriliyor 

göz göze gelinince

böyle başladı

kısa ama verimli iş günü

önce Cemil Abi merhaba

bazıları Cemil Efendi derler

dilim varmaz

dilin kemiği yok 

kemikten güçlü ve işlek

sinir hücreleri var dilin

kökleri motor kortekste

işi yokuşa sürmez Cemil Abi

taşırdı kliniğin yükünü

vakur ve sessiz

altıncı kattan zemin kata

çekilirdi

tomografiler ve diğer filmler

çekilirdi

bunca yük 

karın tokluğuna

nöbet sonrası bir asistan

Kıdemli Numan

sanada merhaba

gidiyor bölüm başkanına

olanı biteni anlatacak

kaç yaralı var kaç ölü

kimler geldi 

kimler geçti 

bu koridorlardan

rapor edilecek

nöbette çıkan sorunlar

raporda çıkan sorunlar bölümü

yine boş yine sessiz

bir hemşirenin sesidir

sessizliği bozan

refakatçılar dışarı

günaydın Nuran Hemşire

cevap veriliyor

doktorum ordırları versene

ordırım yok 

ricam olur hemşire

hastalara biraz olsun gülümse

yerleri parlatıyor

Personel Zihni merhaba

unuturmuyum seni

karnın ağırıyor diye

mide MR’si istediğini

intörn arkadaşlar merhaba

bedava çalışan öğrenciler

gönül ile gönülsüzlük arasında

border line hizmetliler

hummalı bir çalışma var odalarda

akdıkları çıkardıkları yazıldı hastaların

tartıldı iki ayağı üstünde durabilenler

emir ve görüşlerinize hazırız hocam 

buyrun kliniğe

tarzını alırda gelir hoca

çeker gider bir süre sonra

bize tarzdan esintiler kalır

gün boyunca

ben susarda susarım

bir progres yazarım

bir yazarım

biraz da şair', 'bir hastane koridorunda  yaşandı yaşanacak anlattıklarımız kapıdan giriyorum başlıyor yeni bir dünya selam veriliyor  göz göze gelinince böy...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/hastane-koridorlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğa', 'doga-markus-de-sade-5u7ic', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Doğa, eğer hissettiklerimizi kınasaydı, 

Bizde bu zevkleri uyandırmazdı, 

Herşey doğadandır...', 'Doğa, eğer hissettiklerimizi kınasaydı,  Bizde bu zevkleri uyandırmazdı,  Herşey doğadandır......', ARRAY['Türk Edebiyatı','Şiir','Markus De Sade']::text[], 8.5, '{"poet":"Markus De Sade","poet_slug":"markus-de-sade","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/doga-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Felaket Tellalı', 'felaket-tellali-gaffar-karadogan-en5rb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ben felaket tellalıyım

geldim ve söyledim

bir konsültasyon esnasında

kronik renal yetmezlikli hastaya

evre üçü yaşıyorsun

ufukta diyaliz var

ufuk nerede? ne zaman? 

kimse bilemez

felaket tellalıyım

müneccim değilim

olacağı biliyorum

gerçeği biliyorum

zamanından haberim yok

toz pembe tablolarda 

fırçam yok ki benim

bildiğimi söylerim sadece

felaket geldiğinde 

psikojenik şok yaşanmasın

yaşam gerçek olsun diye', 'ben felaket tellalıyım geldim ve söyledim bir konsültasyon esnasında kronik renal yetmezlikli hastaya evre üçü yaşıyorsun ufukta diyaliz var...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/felaket-tellali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarışma', 'yarisma-gaffar-karadogan-rd76z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'haydi gelin

büyük doktor kimdir yarışmasına

hünerinizi alında gelin

hile yok bu yarışmada

gelin

kalp cerrahları

beyin cerrahları

genel cerrahlar

gelin

kardiyologlar

dahiliyeciler

ve tüm dahili branşlar

anlatmaya başladılar sırayla

konuştu kalp cerrahı

bacağından çıkarıp damarı

kalbine yamadım adamın

on yıl, yirmi yıl yaşattım

sıradaki

beyin cerrahı konuştu

kafasından boşaltınca hematomu

bir ömür bağışladım

sıradaki

genel cerrah konuştu

barsağı delinmiş

dalağı yırtılmıştı

ölümden çevirdim hastayı

sıradaki 

dahiliyeci anlattı

lenfomada kür sağladım

ketoasidozu yaşattım

sıradaki

kardiyolog konuştu

perikarttan boşaltıca sıvıyı

en büyük mutluluğu ben yaşadım

mangalda kül kalmamıştı

yarışmanın sonunda

sıra geldi birinciyi açıklamaya

birinci seçilemedi

megaloman hezeyanlarınız var

dendi yarışmacılara', 'haydi gelin büyük doktor kimdir yarışmasına hünerinizi alında gelin hile yok bu yarışmada gelin kalp cerrahları beyin cerrahları genel cerra...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/yarisma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedenlerimizi Laflarla Sakatlıyoruz', 'bedenlerimizi-laflarla-sakatliyoruz-jim-morrison-c18zo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sex, yalanlarla dolmuş, 

Beden, gerçeği görmeye çalışsada, 

Kurallarla bastırılmış olduğundan, 

Beceremiyor! ! 

Bedenlerimizi, laflarla sakatlıyoruz, 

Toplum, gerçekten hissettiğimizi, 

SÖYLEYEMEMENİN, başarı olduğunu, 

öğretmiş bize.', 'Sex, yalanlarla dolmuş,  Beden, gerçeği görmeye çalışsada,  Kurallarla bastırılmış olduğundan,  Beceremiyor! !  Bedenlerimizi, laflarla saka...', ARRAY['Türk Edebiyatı','Şiir','Jim Morrison']::text[], 8.5, '{"poet":"Jim Morrison","poet_slug":"jim-morrison","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bedenlerimizi-laflarla-sakatliyoruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hipofiz', 'hipofiz-gaffar-karadogan-bb6ic', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'dizilmişler yan yana

inci tanesi gibi

hücre gurupları

anterior hipofizde

birkaç aksın orta yerinde

denizin mavisini çalıp

damıtmışlar 

tiroid uyarıcı hormonu

bazofilik hücreler

bununlada kalmayıp

uyardılar gonadları

uyardılar zona fasikülatayı

bizi büyütüp adam etmeye

söz vermişler sanki

asidofilik hücreler

annemizin sütü bereketlenmiş

karaciğerden filizlenmiş

büyüme faktörleri

sapı kesilince hipofizin

karıştı birden ortalık

süt salgılandı meme uçlarından

prolaktin tavana vurdu

libido deniz seviyesinde

ne demeli

damacanla işemeye

hükümdar bez 

demişler ya hipofize

sapı olmayan hükümdar

neye yarar', 'dizilmişler yan yana inci tanesi gibi hücre gurupları anterior hipofizde birkaç aksın orta yerinde denizin mavisini çalıp damıtmışlar  tiroi...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hipofiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aydın', 'aydin-gaffar-karadogan-e9700', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'trafik kazası

araç içi

araç dışı

aynı 

aydının sonu

nörosensoriyel işitme kaybı

iki dil bilirdi aydın

gün geldi 

iki dudak okudu

arkasından  konuşulmadığında', 'trafik kazası araç içi araç dışı aynı  aydının sonu nörosensoriyel işitme kaybı iki dil bilirdi aydın gün geldi  iki dudak okudu arkasından ...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/aydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HIV', 'hiv-gaffar-karadogan-xbfd7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'çift kat eldiven

koruyucu gözlük

birde maske 

ekledim kostümüme

tedbirli bir kıyafet olup

yaklaşıyorum

HIV pozitif hastaya

saatli bomba imha edasıyla

imha olmaktan korkarak

sülfür ağırlıklı bir gaz

kaçırıyor hasta

birkaç vücut odağından

gazla bulaş yok literatürde

literatür olmasada

literatür olasımda yok

bu yaşlarda', 'çift kat eldiven koruyucu gözlük birde maske  ekledim kostümüme tedbirli bir kıyafet olup yaklaşıyorum HIV pozitif hastaya saatli bomba imha...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hiv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tıp', 'tip-gaffar-karadogan-mjnp2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bilimsel bir yaşam

şiir yazılacak kadar

eleştirilecek

öykünülecek

alkışlanacak

kişiliğinize sığacak kadar', 'bilimsel bir yaşam şiir yazılacak kadar eleştirilecek öykünülecek alkışlanacak kişiliğinize sığacak kadar...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/tip-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İndüksiyon', 'i-nduksiyon-gaffar-karadogan-17xf9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'düşünün ki bir lösemi

eritroid veya lenfoid

ne fark eder hasta için

kanda dolanıyor

basiretsiz hücreler

ilikten yeşeren

birkaç normal hücre 

yetmiyor bedenimize

kemoterapi protokolü ile

saldırdık 

İsrafilin bedenine

yaş ile kuru 

bir arada yandı

iliği kurudu adamın

yeni filizler yeşerecek

bekliyoruz 

kemik iliğinden

ip üzerinde yürürken

derin aplazi döneminde

herşeye açığız

kanama, enfeksiyon vesaire

beyaz ak pak hücrelerden

yoksun bir bünye ile

ateşlendik bir kere

direniyoruz

vankomisine dirençli enterokoklara

dayanınca kapısına

multiorgan yetmezliğinin

kimse kuş konduramadı

bu hastaya', 'düşünün ki bir lösemi eritroid veya lenfoid ne fark eder hasta için kanda dolanıyor basiretsiz hücreler ilikten yeşeren birkaç normal hücre ...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/induksiyon-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Kağıt', 'uc-kagit-gaffar-karadogan-nvn3d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gel vatandaş 

ne alırsan üç kağıda

mevki, makam, kariyer

üç kağıda

elinde üç kare as olana

oyun olmuş yaşam

her şey üç kağıda', 'gel vatandaş  ne alırsan üç kağıda mevki, makam, kariyer üç kağıda elinde üç kare as olana oyun olmuş yaşam her şey üç kağıda...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/uc-kagit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Genetik Şifre', 'genetik-sifre-gaffar-karadogan-0wi2n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çocukluk orada

Karşıda oyun sahasında

Koşuyor sağa sola

Tükenmez enerji ile

Düşe kalka

Duyuyor musunuz çocuklar

Genetik şifre çözülmüş

Çocuklar çocuk kalacak 

Kirlenmeyecek dünya

Kimin umurunda', 'Çocukluk orada Karşıda oyun sahasında Koşuyor sağa sola Tükenmez enerji ile Düşe kalka Duyuyor musunuz çocuklar Genetik şifre çözülmüş Çocuk...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/genetik-sifre-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yin Yang', 'yin-yang-gaffar-karadogan-1yo3m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'düşünce aynamdan

bakın şimdi dünyaya

ne başlangıcını görürsünüz

ne de sonunu dünyanın

kimsenin değil

oracıkta yaşanan

en uzun oyundur

bir uçta yin 

diğer uçta yang', 'düşünce aynamdan bakın şimdi dünyaya ne başlangıcını görürsünüz ne de sonunu dünyanın kimsenin değil oracıkta yaşanan en uzun oyundur bir uç...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yin-yang-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resim', 'resim-gaffar-karadogan-rvftb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yarım kalmış bir resim

masada duran

resim yarım

öykü tamdır oysa

öyküdür resimi tamamlayan

bütünü görür göz 

baktığında

oksipital lob 17. alan

gördüklerimizin saklandığı yer

bizim arşivimiz

yeni mesajlar gönderir

frontal loba

düşünce üretmek kalır

düşünceler mızrak olur 

çıkar yola

çıkar yol 

zamana kalır', 'yarım kalmış bir resim masada duran resim yarım öykü tamdır oysa öyküdür resimi tamamlayan bütünü görür göz  baktığında oksipital lob 17. al...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/resim-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadın Memeleri', 'kadin-memeleri-gaffar-karadogan-cx9lt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir kadının memesini gördüm

pakistanda

emzirirken bebesini

huzurlu ve sakin

bereketin sembolü

bir kadının memesini gördüm

afrikada

sergilenirken

elden ayaktan farksız

sıradanlığın sembolü

bir kadının memesini gördüm

monacoda

transparan arkasında

cinsel obje

erotizmin sembolü

bir kadının memesini gördüm

ameliyat masasında

kanlı ve kesik

sorunların sembolü', 'bir kadının memesini gördüm pakistanda emzirirken bebesini huzurlu ve sakin bereketin sembolü bir kadının memesini gördüm afrikada sergileni...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kadin-memeleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yerçekimi', 'yercekimi-gaffar-karadogan-efydu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gece oldu

baktılar gökyüzüne

farklı ruh halleriyle şairler

Melih Cevdet baktı

ayın ondödüydü

ve parlayan ayları gördü

çifter çifter

Can Yücel baktı bu kez

boktan yarım ay dedi

bir tek sözüne bakıyormuş

dolunay olmak için

birde ben baktım

yürüyen adamlar gördüm

ayın üstünde

bayrak dikmeye çalışıyorlar

sahip olmak hırsıyla

zapt etmek duygusunu 

taşımışlar aya

yavaş ve gülünç

hareket ediyorlar

istesede kavga edemez onlar

kozlarını paylaşmak için

bir yerin 

çekimine ihtiyaçları var', 'gece oldu baktılar gökyüzüne farklı ruh halleriyle şairler Melih Cevdet baktı ayın ondödüydü ve parlayan ayları gördü çifter çifter Can Yüce...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yercekimi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maskeler', 'maskeler-gaffar-karadogan-tife6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'maskeler düşüyor

yeryüzüne

yüzlerden

beliriveriyor yüz hatları

pişkince gülen

keratinleşmiş yüz derisi

kaybolmuş sinir uçları

tükürsen

yağmur bile zanedilmeyecek', 'maskeler düşüyor yeryüzüne yüzlerden beliriveriyor yüz hatları pişkince gülen keratinleşmiş yüz derisi kaybolmuş sinir uçları tükürsen yağmu...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/maskeler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlah Gözlerin', 'i-lah-gozlerin-cemal-safi-8s5tg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Medet bekliyorum vurduğu yerde

Oralı olmuyor siyah gözlerin.

Gönlümü dağlıyor gördüğü yerde 

Kanıma susamış silah gözlerin.

Her yalan sözüne iftira ekler

Sayısız suçunu sırtıma yükler

Cenneti müjdeler ibadet bekler

Şeytanın taptığı ilah gözlerin.

Feryadım asılsız şikayet değil

Laf değil söz değil rivayet değil

Yetim hakkı değil cinayet değil

Korktuğum en büyük günah gözlerin', 'Medet bekliyorum vurduğu yerde Oralı olmuyor siyah gözlerin. Gönlümü dağlıyor gördüğü yerde  Kanıma susamış silah gözlerin. Her yalan sözüne...', ARRAY['Türk Edebiyatı','Şiir','Cemal Safi']::text[], 8.5, '{"poet":"Cemal Safi","poet_slug":"cemal-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ilah-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terminal Dönem', 'terminal-donem-gaffar-karadogan-vmp7v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hastalıklardan biri

geç fark edilmiş

ilerliyor tıptan hızlı

ilkel hücreler topluluğu

tümör diyorlar adına

ilkellik başlayınca

bitiyor yaşam

başlıyor yaşam savaşı

beyinde zapt edilmiş 

birkaç odak

solunum merkezi 

neredeyse tutulacak

yapılacak bir şey kalmayınca

terminal dönemdedir hasta

nasıl anlatmalı

gözü yaşlı anneye

terminal dönemi

dolambaçlı laflar buluyoruz

herşeyin bittiğini anlatan

ölüm işte şuracıkta

hastanın yanı başında

anlaşılınca gerçrek

ölürse kurtulur düşüncesi başlar

hasta ölür

kurtulur

ölüm kurtuluş olur', 'hastalıklardan biri geç fark edilmiş ilerliyor tıptan hızlı ilkel hücreler topluluğu tümör diyorlar adına ilkellik başlayınca bitiyor yaşam ...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/terminal-donem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güven', 'guven-gaffar-karadogan-ly89j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gece ıssız ve karanlık

taş döşemeli sokakta

damlardan boşalan yağmur sesleri

ayak seslerine karışıyor

büyük adımlarla yürüyen baba

koşar adım yetişmekte 

küçük çocuk

babasının elini tutunca 

hissettiklerimdir diyor güven

süzülüyorlar yay gibi

Diyarbekir sokaklarında

yıllar geçiyor

çocuk adam oluyor

baba yaşlanmış

yürüyorlar yine aynı sokakta

kollar yanyana

güvenecek kimse yok artık

kendilerinden başka', 'gece ıssız ve karanlık taş döşemeli sokakta damlardan boşalan yağmur sesleri ayak seslerine karışıyor büyük adımlarla yürüyen baba koşar adı...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/guven-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşlanma', 'yaslanma-gaffar-karadogan-r7y25', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'seratonin ve betaendorfin

mutluluk medyatörleri

doktor numunesi gibi

parayla satılmazlar 

kendimiz üretmeliyiz

fırtınalarla boğuşarak

hiç yılmadan çalışarak

azalınca sinaptik aralıkta

mediyatörler 

yüz hatlarımız gerginleşir

alnımızda bir omega çizgisi

alınyazımız olur

uykusuzluk

iştahsızlık

işgücünde azalma

bir semptomlar zinciri

çöker hayatımıza

çöreklenirse

kronikleşir anlayacağınız

kaçınılmazdır biyoloji yaşlanma

kronolojik yaşımız otuz iken

ulaşmışızdır elli yaşın', 'seratonin ve betaendorfin mutluluk medyatörleri doktor numunesi gibi parayla satılmazlar  kendimiz üretmeliyiz fırtınalarla boğuşarak hiç yı...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yaslanma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz', 'biz-gaffar-karadogan-06yvn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'şikayetinde kan varsa

hekime görünür ancak

yurdumun insanı

Ordulu Adem

sıvacı ustası

ondört yaşında ilkokuldan terk

ömrünün kırkıncı yılında

idrarında kan gördü bir sabah

geçer dedi bekledi

geçmedi

otları kaynatıp içti

geçmedi

avurtları çöktü

“dağ gibiydim eridim.” dedi kendi kendine

yeşil kartını kaptı

sağlık hizmeti aramaya çıktı

sunulmayan hizmet 

aranarak bulunur elbet

göründü hekime

evre üç mesane tümörü

çıkardılar mesaneyi 

idrar yolu karın duvarına bağlandı

şaşılacak şeydi

rüyasında görse inanmazdı

başına geldi inandı

olsun dedi Ordulu Adem

böyle de yaşarız

olacaklardan habersiz

üç ay geçirdi

idrarı kesildi birden 

hortladı tümör

idrar yolunu tıkadı

adem üremi ile tanıştı

artık palyatif girişimler vardı gündemde

sözler yine klasik

“elimizden geleni yapıyoruz.”

ve bu orta metrajlı film

bitecekti bir gün

“elimizden geleni yaptık” sözüyle', 'şikayetinde kan varsa hekime görünür ancak yurdumun insanı Ordulu Adem sıvacı ustası ondört yaşında ilkokuldan terk ömrünün kırkıncı yılında...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/biz-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş', 'ates-gaffar-karadogan-0nvrv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'vücudumuzun o en tanıdık alarmı

bizi yatağa

ev halkını telaşa düşüren ateş

kapılıveriyorduk hemen

birşeyler yapmalı duygusuna 

ateşle başlayıp mum gibi eriten

ve ölümle biten 

öyküler vardı dedelerimizden kalan

yüzyılların felaket tellalıydı o

hekimlerin ise bulmaca sorusu

bul bakalım sebebini

üç hafta süre tanırlar bize

yoksa adı değişecek

nedeni bilinmeyen ateş olacak

bilinmeyenler

vaka takdimlerinin konusudur

hasta onlarca hekimin konuğu 

bir bilen çıkar diye

yüzde doksan bulunur 

akılcı bir yaklaşımla

pirojenlerin kaynağı

ve hep bilinmeyen 

bir yüzde vardır

bizi düşünmeye sürükleyen', 'vücudumuzun o en tanıdık alarmı bizi yatağa ev halkını telaşa düşüren ateş kapılıveriyorduk hemen birşeyler yapmalı duygusuna  ateşle başlay...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ates-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözaltı', 'gozalti-gaffar-karadogan-9gxvf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hayata hazırlıksız yakalandık

gözaltındayız

suçumuz hayata hazırlanmamak

gözaltı süremizi bilmiyoruz

bilmeden yaşıyoruz hayatı

konuşmama hakkımızı mı kullansak? 

şeytanın avukatını mı çağırsak? 

söz hakim bey

çalışacağız mı desek

suçu kabul edip

iyi halden mi salıverilsek

yoksa salıversek kendimizi

inceldiği yerden kopsa', 'hayata hazırlıksız yakalandık gözaltındayız suçumuz hayata hazırlanmamak gözaltı süremizi bilmiyoruz bilmeden yaşıyoruz hayatı konuşmama hak...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gozalti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üçüncüler', 'ucunculer-gaffar-karadogan-gt9er', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'iki kişi aşık olunca

yaşamak düşer

üçüncüye

üçüncüler çoğalmış

üçüncü çoğul şahıs olmuş onlar

ben ve sen tekilken

aşk ile birleşmiş 

birinci çoğul şahıs olmuşuz biz

konu olmuşuz

konuk olmuşuz

konuşulmuşuz', 'iki kişi aşık olunca yaşamak düşer üçüncüye üçüncüler çoğalmış üçüncü çoğul şahıs olmuş onlar ben ve sen tekilken aşk ile birleşmiş  birinci...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ucunculer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluğunuz! ! ? ? ?', 'dostlugunuz-sair-karagozlum-7gi19', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne yapsam ne etsem

nerelere gitsem

kimlerden kacsam

basim darda kime

güvenip yardim istesem

hangi dostan vefa beklesem.

Iyi ve kötü günde dediler

''Biz dostuz'' diye övündüler

yaptoigim her iyilikte ''sensin'' dediler

yikildigimda derttasinla ezdiler

ezdirdiler.

Nerde dediginiz dostlugunuz? 

Arkadasinizi ne cabuk unuttnuz? 

Dost demistim güvencim onlara sonsuz

Düsdügünde batakliga saplanirsin

tutunacak dost elini bulamazsin

bogulurken dert deniin icinde

uzakdan bakar dostun gizlice

Bilseydim bu kadar aci oldugunu.......................

Bilseydim dostun yalan oldugunu...........................

Bilseydim beni kendi cikarlari icin kullandiklarini......

Bana sikilan her kursunda bir gül atar

dünya böyle kurulmus...........................

onlarin seviyesine düssem elime ne gecer? ? ?', 'Ne yapsam ne etsem nerelere gitsem kimlerden kacsam basim darda kime güvenip yardim istesem hangi dostan vefa beklesem. Iyi ve kötü günde de...', ARRAY['Türk Edebiyatı','Şiir','Şair Karagözlüm']::text[], 8.5, '{"poet":"Şair Karagözlüm","poet_slug":"sair-karagozlum","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dostlugunuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Renkler', 'renkler-gaffar-karadogan-wq3nl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'o yıllar(ım)

histoloji preparatı kadar renkli 

en çok hematoksilen 

taşısa da hayat

ben prusya mavisini sevdim', 'o yıllar(ım) histoloji preparatı kadar renkli  en çok hematoksilen  taşısa da hayat ben prusya mavisini sevdim...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/renkler-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-gaffar-karadogan-r4eto', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'şimdi (öz)  eleştiri zamanıdır

(öz)  eleştiri zamanı

geniş zamandır

(öz)  eleştiride geniş olma zamanıdır', 'şimdi (öz)  eleştiri zamanıdır (öz)  eleştiri zamanı geniş zamandır (öz)  eleştiride geniş olma zamanıdır...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zaman-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhum', 'ruhum-gaffar-karadogan-nc47b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yalnız kaldım

ruhumu besliyorum

öykülerle, şiirlerle, şarkılarla

besliyorum da ruhumu 

öyle çıkıyorum

sokaklara

güzel insanlara

güzel sözler söylerim 

öyle çıkarım

sokaklardan alanlara

söylerimde

şiir tadında söylerim

öyle çıkarım 

alanlardan yarınlara', 'yalnız kaldım ruhumu besliyorum öykülerle, şiirlerle, şarkılarla besliyorum da ruhumu  öyle çıkıyorum sokaklara güzel insanlara güzel sözler...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ruhum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-gaffar-karadogan-jn652', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'eski elbiseler eski düşler

severim eski elbiseleri

düşleride

benimle eskidiler

yenisi ile değişseler

değişmem 

gerçek geçiyor düş yolunda

uygun adım 

uydurun adımları

basmayın düş kırıklarına', 'eski elbiseler eski düşler severim eski elbiseleri düşleride benimle eskidiler yenisi ile değişseler değişmem  gerçek geçiyor düş yolunda uy...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dus-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fıkra', 'fikra-gaffar-karadogan-gvu1k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yıl 2001

çocukluğumdan beri bekliyorum

daha giremedik avrupa topluluğuna

nedense

bir İngiliz

bir Fransız

birde Türk vardı

fıkralarda

trajik komik bir olay

sonunda bir kahkaha

yine geldi üçü biraraya

yarışacaklar belli

kondular karanlıga

biri kurşun sıktı

diğeri küfür etti

karanlığa

bir kurşun birde küfür

kurşun üçüncüyü vurmuş

mum yakacak üçüncü

kalmamıştı bu fıkrada', 'yıl 2001 çocukluğumdan beri bekliyorum daha giremedik avrupa topluluğuna nedense bir İngiliz bir Fransız birde Türk vardı fıkralarda trajik ...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/fikra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlar', 'yildizlar-gaffar-karadogan-f6f51', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yıldızlar kayıyor bu gece

yavaşça ağır bir senfoni gibi

uzun ve anlamlı dilekler

tutulsun istiyorlar

dikin gözlerinizi gökyüzüne

dünyanın çocukları

yeni bir  destan yazalım bu gece', 'yıldızlar kayıyor bu gece yavaşça ağır bir senfoni gibi uzun ve anlamlı dilekler tutulsun istiyorlar dikin gözlerinizi gökyüzüne dünyanın ço...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yildizlar-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda', 'sevda-gaffar-karadogan-1oxfh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'diyarbekir  burçlarının dibinde

oturmuş dalmışım seyre

yalnız değilim 

sevdalıyım

sevdiğim şimdi ege''de

yalnız değilim

sevdalıyım', 'diyarbekir  burçlarının dibinde oturmuş dalmışım seyre yalnız değilim  sevdalıyım sevdiğim şimdi ege''de yalnız değilim sevdalıyım...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sevda-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güvercin', 'guvercin-sair-karagozlum-lc7ui', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Boynu bükük bir güvercin gibi

tek ayak üstünde yasiyorum

yalnizlik canima tak etmis

canim kadar sevdigim

beni birak gitmis.

Acilr icinde

güvendigim daglara kar yagmis

dertler yine benim basimda kalmis

gözümdeki yaslar üzüntüden sel gibi akmis.

Derdimi kim anlar

benim gibi bir garip icin kim yanar

yalan dolan yasiyorum

kalan günlerimi sayiyorum

yalnizligin acisina dayanamiyorum

senden uzakta gurbet ellerde kaliyorum

ne zormus bu ayriliga katlanmak

seni kara topragin altinda birakmak

günahsiz yere sensiz yasamak.

yillarca sana alisamadim

özlemini kaybettikten sonra anladim

faydasiz agliyorum sensizlige

vermiyor kara toprak seni geriye

Nasil alisirim gidisine

nasil dayanarim sensizlige

dayanamaz oldum bu ayriliga

yeter artik.................

beni de al yanina.', 'Boynu bükük bir güvercin gibi tek ayak üstünde yasiyorum yalnizlik canima tak etmis canim kadar sevdigim beni birak gitmis. Acilr icinde güv...', ARRAY['Türk Edebiyatı','Şiir','Şair Karagözlüm']::text[], 8.5, '{"poet":"Şair Karagözlüm","poet_slug":"sair-karagozlum","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/guvercin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Said Paşa İmâmı', 'said-pasa-i-m-mi-mehmet-akif-ersoy-ns3g7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Coşar âvîzeler artık, köpürür kandiller; 

Bu ışık çağlayanından bütün âfâk inler! 

Yalının cebhesi, Ülker gibi, baştan başa nûr; 

Nîm açık pencereler, reng ü ziyâdan mahmûr.

Al, yeşil, mâvi fenerlerle donanmış kıyılar; 

Serv-i sîmînler atılmış suya, titrer par par.

Dalgalardan seken üç çifte kayıklar sökerek,

Süzülür sâhile, şâhin gibi, yüzlerce kürek.

Bir taraftan bu akın yükseledursun karaya; 

Bir taraftan dökülür öndeki saflar saraya.

Rıhtımın taşları, zümrüt gibi, Îran halısı:

Suda bitmiş çemen, üstünde de Sultan Yalısı! 

Renk renk açmış o başlar, biriken mahşere bak:

Fes, arâkiyye, sarık, yazma, bürümcük, yaşmak,

Taylasan, takke, nazarlıklı hotoz, âbânî,

Mâvi boncuk, oyanın türlüsü, dal dal yemeni.....

Ama birçokları da’vetli değilmiş, kime ne? 

Bu açılmaz kapılar, şimdi, açık her gelene.

Avlu, dış bahçe, harem bahçesi, taşlık, yer yer,

Medd ü cezrin ebedî sâhası: Boy boy siniler,

Ki donandıkça o başlarla, hemen, çepçevre,

Tablalar, aydede çıkmış gibi, başlar devre! 

Yayılır baygın, ılık bir buğu, bir tatlı duman; 

Çözülür büsbütün âvâre sinirler o zaman.

Kafalar tütsüyü aldıkça döner, mest-i hayât; 

İki el bir baş için, kim kime artık? Heyhât! 

Orta katlar, sofalar, belli ki da’vetlilere:

Sofralar tahtanın üstünde değil bir kerre; 

Bir de, oldukça merâsimle mükellef huzzâr; 

Sonra, kalkıp oturanlar bütün ashâb-ı vakàr.

Yatsı bir hayli geçer, çifte ezanlar verilir; 

Yazma seccâdeler artık yere, boy boy, serilir.

Doğrulur Kıble’ye herkes, kılınır şimdi namaz; 

Derken «âmin! » çekilip arz edilir Hakk’a niyaz.

— Başlayın Mevlid’e! 

— Lâkin, hani? Mevlid-han yok! 

— Sordurun! 

— Hiç de gören bir kişi, bir tek can yok! 

— Üsküdar’dan gelecek sözde, olur şey mi ki bu? 

Bâri söz verme...

— Adam sen de, bırak meczûbu! 

— Bence aynıyle kerâmet delinin gelmediği:

Şu ilâhîcilerin hepsi okur ondan iyi.

— Bilemem.

— Dinlediniz şimdi...

— Evet, çok yüksek...

Ama hazretle kıyâs etmeye gelmez.

— Ne demek? 

— O anaç bülbüle eş beslemez artık yuvalar.

— Pek uçurdun, a beyim! 

— Yok, ben uçurmam, o uçar.

Sâde bir gelse... Fakat gelmedi, bilmem ki neden? 

— Beklemek nâfile, hâlâ ne gelen var, ne giden! 

— Harem ağsında haber...

— Anlayabilsek, ne diyor? 

— Okuyun, beklemeyin emrini tebliğ ediyor.

Gâlibâ Vâlide Sultan gazab etmiş hocaya...

— Gazab ettiyse, çanak tuttu herif, doğrusu ya.

Bir saray halkını -sultanla berâber- hiçe say; 

Bunca da’vetliyi, da’vetsizi beklet bir alay; 

«Oyun ettim size; hey sersem adamlar! » diye, gül! 

Çekilir nağme değil... Neymiş, anaçmış bülbül! 

— Kim bilir, özrü mü var? 

Dinleyemem varsa bile! 

Başlanır Mevlid’e mu’tâd olan âdâbıyle; 

Önce tevhîd okunur, gaşy ile dinler herkes.

O, güzel, sonra, müessir, sekiz on parlak ses,

Kimi yerlerde ilâhî, kimi yerlerde durak; 

Kimi yerlerde cemâ’atle beraber coşarak,

Kalan üç bahri terennümle, çekerken «âmîn! »

Ta uzaklarda çakar zulmet içinden bir enîn.

Gecenin kalbi durur; ürperir inler, cinler; 

Açılan pencereler, göz kulak olmuş, dinler.

O enîn karşıki sâhilden açılmaz mı biraz,

Sûr-i Mahşer gibi sesler çıkarır, şimdi, Boğaz! 

Tutuşur, cebhe-i Sînâ’ya döner, sîne-i cev:

Sanki yüzlerce yanık ney savurur, yer yer, alev! 

Kayalardan, kıyılardan bir ateştir çağlar:

Lâhn-i Dâvûd ile inler yine gûyâ dağlar! 

Âh o kudsî nefes eşbâha ederken sereyan,

-Karalar vecd ile pür-cûş, sular pür-galeyan-

Dem çekip, dem tutarak etmeye başlar feryâd,

Boğaz’ın her tarafından bir İlâhî inşâd:

«Sultân-ı Rusül, Şâh-ı Mümecced’sin, efendim! 

Bîçârelere devlet-i sermedsin, efendim! 

Menşûr-i «Le amrük»le müeyyedsin efendim! 

Dîvân-ı İlâhî’de ser-âmedsin, efendim! 

Sen Ahmed ü Mahmûd u Muhammed’sin, efendim! 

Hak’tan bize Sultân-ı Müeyyed’sin, efendim! »

........................................................................

Kesilir, gitgide, tedrîc ile sesler artık,

Aktarır sâhile mevlidciyi bir köhne kayık.

Koşarak, doğruca mâbeyne alır karşı çıkan; 

«Nerde kaldın, hoca? der, Vâlide Sultan o zaman,

Sen de kalleşlik edersen, bize eyvahlar ola! »

— Henüz akşamdı ki, gelsem diye, düştüm de yola,

Yürüdüm haylice... Derken -hele sen kısmete bak! -

Öteden karşıma bir yaşlıca hâtun çıkarak,

«Azıcık dursana, oğlum! » dedi. Durdum, nâçar.

— Göğsün îmanlıya benzer, sana bir hizmet var,

Ama reddetme ki, zâten beni mahvetmiş ölüm:

Bir perîşan anayım, dağ gibi evlâd gömdüm! 

Kızımın cânı için, bâri bu kırkıncı gece,

Şöyle bir Mevlid okutsam, diyorum, kendimce.

Nasıl etsem? Okuyan çok ya, benim yufka elim...

Hocasın, elbet okursun; hadi oğlum, gidelim.

Ne olur bir yorulursan, hadi, bekletme, günah! 

Sen benim yavrumu şâd et ki, rızâen li’llâh,

İki dünyâda azîz eylesin Allah da seni.

Hâtunun sözleri dîvâneye döndürdü beni; 

Ne saray kaldı hayâlimde, ne sultan, ne filân; 

«Çile dolsun, yürü öyleyse, dedim, oldu olan! »

Size yüzlerce adam Mevlid okur benden iyi,

Ama bîçâre kızın, bağrı yanık, anneciği,

Yoklasın merdini, nâ-merdini, insan diyerek,

Eli yüzlerce heyûlâya deyip boş dönecek! 

Fukarânın seneler, belki, siler göz yaşını; 

Hangi taş pekse, hemen vurmaya baksın başını,

Elin evlâdına yanmaz parasız bir kimse! 

Çâresizdim sizi bekletmede, beklettimse.

— Hoca! der Vâlide Sultan, beni ağlatma, yeter! 

Yeniden Mevlid okursun bize, da’vâ da biter.

Hilvan, 15 Haziran 1347 (1931)', 'Coşar âvîzeler artık, köpürür kandiller;  Bu ışık çağlayanından bütün âfâk inler!  Yalının cebhesi, Ülker gibi, baştan başa nûr;  Nîm açık p...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Ersoy']::text[], 8.5, '{"poet":"Mehmet Akif Ersoy","poet_slug":"mehmet-akif-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":123,"source_url":"https://www.antoloji.com/said-pasa-imami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Stres', 'stres-gaffar-karadogan-rdjh6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'karşılaşınca bir stresle

ilk kez

salgılanıverir sinir uçlarından 

nor adrenalin

tanıdık olmayan strese cevabımız

çıktı karşımıza 

ikinci kez aynı stres

böbrek üstü bezinden 

kana karıştı adrenalin

tanıdık strese cevabımız

sempatomimetik aminler var kanda

dolaşıyorlar tüm vücudu

uyararak reseptörleri

göz bebeğimiz büyümüş

daha hızlı çarpıyor yüreğimiz

kan basıncımız yükseklerde

saldırıya hazır

bir savunma halidir yaşadığımız', 'karşılaşınca bir stresle ilk kez salgılanıverir sinir uçlarından  nor adrenalin tanıdık olmayan strese cevabımız çıktı karşımıza  ikinci kez...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/stres-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konuk', 'konuk-gaffar-karadogan-ydup4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hep taşımışız 

kısa süre anlamını 

konuk kelimesinin özüne

gidecek gözüyle bakıldı

konuklara

henüz gelmişken

bu dünyaya

taşımaya devam ettik 

ağırlanmak kelimesini

konukluğun özüne

kısa süre ağırlandık 

konuk olduk 

insanlık tarihine', 'hep taşımışız  kısa süre anlamını  konuk kelimesinin özüne gidecek gözüyle bakıldı konuklara henüz gelmişken bu dünyaya taşımaya devam ettik...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/konuk-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Saati', 'olum-saati-gaffar-karadogan-og5to', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'tüm saatleri 

ölüme beş kalaya kurdum

içiyorum

aşkın zehirini

ölüme beş kalana kadar

ziller çalıyor

uyanın zilleri 

değilki bunlar 

uyanalım 

bırakın çalsın 

ölüme beş var arkadaşlar', 'tüm saatleri  ölüme beş kalaya kurdum içiyorum aşkın zehirini ölüme beş kalana kadar ziller çalıyor uyanın zilleri  değilki bunlar  uyanalım...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/olum-saati-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Homeostazis', 'homeostazis-gaffar-karadogan-zzydn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'düzen içinde çalışma halidir

homeostazis

bozulan bir denge

matem içindeler

hastaya yakın çevreler

kurmak için düzeni 

kullanıyoruz tıbbı

tümeyakın yöntemleriyle

gecikince şifa

tüm yöntemler denenmelidir

diye düşünür

hastaya yakın çevreler

kolları ve bacakları tutmayan

guillain barre sendromlunun

başında gördüm 

ak sakallı dedeyi 

getirmişler ziyaretçi formatında

binlerce kilometre öteden

bastonuna dayanmış bahsediyor

beterin beterinden

kaderden ve cennetten

dosyaya not düşmemişti ak sakallı

oysa iki satır da olsa 

yazmalıydı 

geleneksel yöntemle

psikoterapi yaptığını', 'düzen içinde çalışma halidir homeostazis bozulan bir denge matem içindeler hastaya yakın çevreler kurmak için düzeni  kullanıyoruz tıbbı tüm...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/homeostazis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkış', 'cikis-gaffar-karadogan-6fsh4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yüzlerce hasta çıkardık

dahiliye kliniğinden

kimi evine gitti 

kimi toprağa

düzenlerken çıkış kağıdını 

sonuç bölümüne ne yazılacak 

hep düşünürdük

en uygun kelimeyi 

bulalım diye

bazen şifa yazılırdı

hastalıktan tam kurtulma

bazen salah

düzelme vardı hastamızda

olduğu gibi gönderince

haliyle yazılırdı

ne kadar hali varsa

uygun kelimeyi bulmak

hiç zor değildi

eksitus yazıldığında', 'yüzlerce hasta çıkardık dahiliye kliniğinden kimi evine gitti  kimi toprağa düzenlerken çıkış kağıdını  sonuç bölümüne ne yazılacak  hep düş...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/cikis-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-gaffar-karadogan-5x7p1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kişiliklerle yaşamak zor

zor kişiliklerle

yaşıyoruz 

sağnak yağmur

kavurucu sıcakta

yaşar gibi 

suçları yok onların

istemediler zor kişilikler olmayı

değiştiremezsiniz 

tabiat değişmez ki 

rüzgarın yönü belirlendi

yelkenleri açtı

zor olmayanlar

çıkmışlar yola 

selam verecekler

her limana

her limanda 

iyiki varsınız

düşüncesine kapılıp

ufka bakanlara', 'kişiliklerle yaşamak zor zor kişiliklerle yaşıyoruz  sağnak yağmur kavurucu sıcakta yaşar gibi  suçları yok onların istemediler zor kişilikl...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yasamak-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onlar', 'onlar-gaffar-karadogan-qoa0m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'oyun havaları türküler

dudakları süsleyen

tatlı bir ıslıkla

yürümek varken

tarihi karartıpta yazmışlar

megaloman paranoidler

en kalın ve kanlı tarihi 

bulamazsınız onları 

bilimde ve sanatta

yer alamazlar ki onlar

insanların gönlünde

kara tarihimizde varlar

kara talihimizde', 'oyun havaları türküler dudakları süsleyen tatlı bir ıslıkla yürümek varken tarihi karartıpta yazmışlar megaloman paranoidler en kalın ve kan...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/onlar-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saldırı', 'saldiri-gaffar-karadogan-17p9l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kendime yaptığım

silahsız bir saldırıdır

bu şiir

kesici ve delici sözlerle

en yontulmayan yanlarıma

işte başlıyorum

bir dokundum

yontulmayan yanım yaralı

bin aah işitiliyor

yetmezmi bu saldırı

hadi herkes 

kendini yontma devrine', 'kendime yaptığım silahsız bir saldırıdır bu şiir kesici ve delici sözlerle en yontulmayan yanlarıma işte başlıyorum bir dokundum yontulmayan...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/saldiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günah Keçileri', 'gunah-kecileri-gaffar-karadogan-cr389', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'günahı neydi 

bu keçilerin

neden böyle ağlamaklı

bağırıyorlar

hastane koridorlarında

işleri ne? 

hepsi de spastik kolon olmuşlar

keçileri kaçırınca ben

günahımda kalmayacak

doktorluğumda', 'günahı neydi  bu keçilerin neden böyle ağlamaklı bağırıyorlar hastane koridorlarında işleri ne?  hepsi de spastik kolon olmuşlar keçileri ka...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gunah-kecileri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Primum', 'primum-gaffar-karadogan-6ob7y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'önce zarar verme

sonra? 

zararın neresinden 

kesin dönüş yaparsak

zarardayız yine

tek karımız var

o da avuntumuz', 'önce zarar verme sonra?  zararın neresinden  kesin dönüş yaparsak zarardayız yine tek karımız var o da avuntumuz...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/primum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keskin Sirke', 'keskin-sirke-gaffar-karadogan-snhah', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir şubat gününde

çekildi sorguya 

keskin sirke

yalanlar kuşanmıştı sinsice

yalandan zırh yapılmaz ki 

mumunu da yakmıştı 

çaresiz yalancı

sönecekti beş vakte kalmadan

boğulacaktı karanlıkta', 'bir şubat gününde çekildi sorguya  keskin sirke yalanlar kuşanmıştı sinsice yalandan zırh yapılmaz ki  mumunu da yakmıştı  çaresiz yalancı s...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/keskin-sirke-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayılar', 'ayilar-gaffar-karadogan-i17zn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'köprüden geçinceye kadar

diyorlar ki 

ya sabır demeli 

köprü uzun ve kalabalık

ayılar

çok sayıdalar

atlamak da çare değil

köprüden

aşağıda nehirde de varlar

yarıya kadar batmış suya 

boz ayı

sıçramasını bekliyor

somon balığının

bulmuşlar 

nehrin en dingin kıyısını 

gidiyorlar somonlar

üremeye tek sıra

öğreneceğimiz varmış somonlardan

geçmek için köprüden

ayıları sayarak', 'köprüden geçinceye kadar diyorlar ki  ya sabır demeli  köprü uzun ve kalabalık ayılar çok sayıdalar atlamak da çare değil köprüden aşağıda n...', ARRAY['Türk Edebiyatı','Şiir','Gaffar Karadoğan']::text[], 8.5, '{"poet":"Gaffar Karadoğan","poet_slug":"gaffar-karadogan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ayilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bukebarane*', 'bukebarane-tugba-gurelli-ln6gp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kabuğunu kaldırır gibi aşkın

Göğünde eksiliyorum

Hiç dize de dökülür müymüş kollarından insanın

Anlamıyorlar mı ne

Bense uzun uzun içinin balkonlarını öpüyorum...

Çocukca bakıyorlar yüzüme

Sevmek için önce kırmızıya boyanmak gerekmiş

Hem kim öğretti ki bunu bana

Gözlerini ters çevirip yağmuru iste diyorlar

Ben ''bukebarane'' diyorum, ben ''bukebarane''

Yağmurumuza karışıyor tanrının gözyaşları...

Sessizce çarmıha geriliyorum...

*)  bukebarane: Kürtçe''de yağmur gelini', 'Kabuğunu kaldırır gibi aşkın Göğünde eksiliyorum Hiç dize de dökülür müymüş kollarından insanın Anlamıyorlar mı ne Bense uzun uzun içinin ba...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Gürelli']::text[], 8.5, '{"poet":"Tuğba Gürelli","poet_slug":"tugba-gurelli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bukebarane-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerin Ellerime', 'ellerin-ellerime-mahmut-okur-0ow6t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ellerin elime değdi bir kere

Nafile ne yapsam, ne yapsam boştur.

Gönül bak dilenci, beydi bir kere

Bir ümid ardından koştur ha koştur.

Hayal, hayal, uzak; varılmaz bir yer.

Bir ses var ki bana hiç erilmez der.

Ellerini benim ellerime ser! 

Ne olur? Farketmez, gönül sarhoştur, 

Yanmışsa elinden gayri bir hoştur.

Ellerin, ah, değdi elime benim.

Ellerin elime değdi bir kere...

Ellerin, 

    Benim...', 'Ellerin elime değdi bir kere Nafile ne yapsam, ne yapsam boştur. Gönül bak dilenci, beydi bir kere Bir ümid ardından koştur ha koştur. Hayal...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Okur']::text[], 8.5, '{"poet":"Mahmut Okur","poet_slug":"mahmut-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ellerin-ellerime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-berna-ocakcioglu-eq2pf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beni hasretini ezberlediğim İstanbul''a götürün 

Önce kumsala durmadan öpücükler konduran 

Dalgaları seyredeyim, kıskanayım tertemiz sevdalarını. 

Sonra bir yağmur alsın Üsküdar''a giderken 

Setresi uzun, eteği çamur katipleri göreyim 

Orhan Veli''nin İstanbul''una götürün beni 

Gözlerimi kapayıp dinlediğimde duyduğum 

''Cıvıl cıvıl Mahmutpaşa'' 

''Serin serin Kapalı Çarşı'' olsun 

Sevdiğine siz diyebilen saygılı aşıklara rastlayayım sonra 

''Ağlasam sesimi duyar mısınız mısralarımda'' 

Deyişini sessizce dinleyeyim. 

Sonra Münir Nurettin''den Mikrofonsuz şarkılar dinleyip 

Ruhumu besleyeyim. 

Beni ''Gecesi Sümbül, Tükçesi Bülbül kokan'' 

İstanbul''a götürün 

Yalıların alt katlarına misafir olan oynak suları seyredeyim. 

Cumbada otursun iş işlesin kadınlar 

Kafesli pencerelerden ut sesleri yayılsın akşama. 

Topkapı’ya gideyim sonra 

Surlardan “tarihin gözleriyle” bakayım İstanbul''a 

Ada vapurunda uçuşsun saçlarım, 

İşportacıların emek kokan seslerini dinleyim 

Semalarında uçuşan bulutlarında Fatih''ten kalma kıratın 

Şahlanışına hayret edeyim, 

Minareler gökyüzüne uzanıp seslensin ezanları. 

Çamlıca’ya giderken 

''Aşk Bahçesinin Bülbülüyüz'' 

Diyen üç gülüne rastlayım Yesari Asım''ın 

Onlardan parasız yaşayıp eğlenmenin sırrını alıp 

Heybeli''de her gece mehtaba çıkan aşıkların 

Sandalına atlayım 

Mehtabı seyrin zevkine bir dem de ben dalayım 

Nargilelerinin dumanıyla dert paylaşanlara 

El sallayım 

Bir akşamda bütün meyhanelerini dolaşayım İstanbul''un 

Sevdiğimi arayım kadehlerdeki dudak izlerinde 

En büyük sıkıntım dedikodu olsun 

''Geç bunları anam babam bir kalemde'' deyip 

Gülüp geçeyim. 

Beni gök temizi İstanbul''a götürün 

Köprüde balık ekmek yiyim 

Akşam serinliğini kaynatan semaverlerinden 

Bir bardak demli çay içip 

Bir vapur ıslığında geri döneyim.', 'Beni hasretini ezberlediğim İstanbul''a götürün  Önce kumsala durmadan öpücükler konduran  Dalgaları seyredeyim, kıskanayım tertemiz sevdalar...', ARRAY['Türk Edebiyatı','Şiir','Berna Ocakçıoğlu']::text[], 8.5, '{"poet":"Berna Ocakçıoğlu","poet_slug":"berna-ocakcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/istanbul-a-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çelik Kafes', 'celik-kafes-berna-ocakcioglu-72p46', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu akşam o kadar çılgın ki rüzgar 

Kapıl da  önüme gidelim diyor 

İçimde hüzünle karma duygular 

Gözünden yaşları süzüver diyor 

Ey gönül! 

Sevgiden ümidini kes 

Sevmek diye bir şey yok unutmuş herkes 

Şimdi yüreğimde çelik bir kafes 

Kapat sevgiyi buraya ve unut diyor. 

Diyardan diyara gezer ya rüzgar 

Sordum ona sevgi nerede var 

Anladım görmemiş şimdiye kadar 

Sevgi bir masalmış dillerde diyor.', 'Bu akşam o kadar çılgın ki rüzgar  Kapıl da  önüme gidelim diyor  İçimde hüzünle karma duygular  Gözünden yaşları süzüver diyor  Ey gönül!  ...', ARRAY['Türk Edebiyatı','Şiir','Berna Ocakçıoğlu']::text[], 8.5, '{"poet":"Berna Ocakçıoğlu","poet_slug":"berna-ocakcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/celik-kafes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek', 'gercek-mahmut-okur-82thk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Elleri kalbinin mahrem yerinde, 

Tutamaz onları sen atamazsın.

Sızladıkça yaran her seferinde

Uğraşır, didinir kanatamazsın.

Bir gölgedir belki parçalar seni, 

Hem varda hem yokta kurcalar seni, 

Toprak ol, toprağa saçalar seni, 

Yine de gölgeni sen satamazsın.

Sen ölsen, ölmesen ah ne gam ona? 

Çilen bu, çaren yok, çaban boşuna

Yaklaşıyorken bak, o sonsuz sona, 

Unutulursun sen, unutamazsın! 

Sen garip, tutuldun, sen tutamazsın...

Elleri kalbinin mahrem yerinde...

        Yaran, 

                  Derinde...', 'Elleri kalbinin mahrem yerinde,  Tutamaz onları sen atamazsın. Sızladıkça yaran her seferinde Uğraşır, didinir kanatamazsın. Bir gölgedir be...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Okur']::text[], 8.5, '{"poet":"Mahmut Okur","poet_slug":"mahmut-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gercek-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahara ve Sana', 'bahara-ve-sana-berna-ocakcioglu-lq3tq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bacalardan süzülen 

Son dumanlarda sevdim seni 

Leyleklerin göç zamanı 

Ben rüzgarla savrulan 

Son hüzün dumanı 

Yavru bir serçenin 

Ürkek kanata vuruşunda yüreğim 

Sen karşı damda 

Devinimsiz duran 

Leylek kadar duyarsız 

Sevecen ama uzaksın 

Bahara ümit bağladım 

Ümitlerimi çiçeklere 

Çayırlar büyürken 

Toprağı giydirmeye 

Gündöndüler kur yaparken güneşe 

Ve ben 

Her sabah sularken gözyaşı çiçeğimi 

Sevgi büyütüyorum gönlümde 

Bahara ve sana.', 'Bacalardan süzülen  Son dumanlarda sevdim seni  Leyleklerin göç zamanı  Ben rüzgarla savrulan  Son hüzün dumanı  Yavru bir serçenin  Ürkek k...', ARRAY['Türk Edebiyatı','Şiir','Berna Ocakçıoğlu']::text[], 8.5, '{"poet":"Berna Ocakçıoğlu","poet_slug":"berna-ocakcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bahara-ve-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-berna-ocakcioglu-l11wg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sensiz 

Yalnızlığın avuçlarına ağlıyorum bak 

Esen rüzgar kokunu getirmiyor 

Sensiz 

Aydınlıklar yeşertmiyor umutlarımı 

Neyleyim saatler seni vurmuyor 

Yağmur damlalarında 

Ilık nefesin yok 

Dudaklarım hasretinin soğuğunda üşüyor 

Bu sahilde seni değil kollarım 

Senden kalan anıları sarıyor', 'Sensiz  Yalnızlığın avuçlarına ağlıyorum bak  Esen rüzgar kokunu getirmiyor  Sensiz  Aydınlıklar yeşertmiyor umutlarımı  Neyleyim saatler se...', ARRAY['Türk Edebiyatı','Şiir','Berna Ocakçıoğlu']::text[], 8.5, '{"poet":"Berna Ocakçıoğlu","poet_slug":"berna-ocakcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sensiz-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vebal', 'vebal-mahmut-okur-72aec', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beynimde ilmek ilmek sadece bir hayal var.

Simsiyah bir boşluğa akıttığım kemal var.

Alnımda kara leke, ümidimde zeval var.

Bir gölge ve bir ece, yıllar yılı bu hal var.

İşte böyle her gece; 

Başucumda hayalin bir tezadı sayıklar

Kan oturmuş ruhumun diyetini açıklar.

Sorulur ellerinden gönlümdeki kırıklar! 

Vefasız, şimdi gam çek, duyulsun hıçkırıklar! 

Bilirsin, 

     Bir, 

        Vebal var......', 'Beynimde ilmek ilmek sadece bir hayal var. Simsiyah bir boşluğa akıttığım kemal var. Alnımda kara leke, ümidimde zeval var. Bir gölge ve bir...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Okur']::text[], 8.5, '{"poet":"Mahmut Okur","poet_slug":"mahmut-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vebal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Kız', 'kucuk-kiz-berna-ocakcioglu-rdz8i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Küçük bir kızdım yanakları çilli 

Seviyordum kara yağız bir genci 

Bir vardı bir yoktu 

Bayramlarda geliyor 

Yüreğimi alıp gidiyordu bayram sonu 

Onun sesi sürükledi beni 

Onun kara gözleri 

Çarpım tablosundaki sıfır gibi 

İçinde kendinin olmadığı 

Tüm düşleri yok etti 

APTAL! ! ! 

Ya görmedi sevdiğimi 

Ya işine gelmedi 

Küçük bir kızdım 

Yüreği umut dolu 

Seviyordum bir yakının oğlunu 

Düşlerimin ateş böceğiydi 

Aptallaştırır 

Şaşırtırdı yolumu 

Gözlerinin sessiz emirleri 

Utangaç çocuk yüreğim 

Sevdiğini ne gizledi 

Ne de söyledi 

Sevgisiyle mühürlendi yüreğim 

Ondan başkası giremedi 

Onsuz kaç bayram geldi geçti 

Küçük kızın sevgisi hiç tükenmedi. 

Öyle birisi çıksa karşıma şimdi 

Bir saniyede uyandırsa ümitlerimi 

Çocuksu ilkbaharlarımın 

Açıverse leylak rengi düşleri

Mart -2000', 'Küçük bir kızdım yanakları çilli  Seviyordum kara yağız bir genci  Bir vardı bir yoktu  Bayramlarda geliyor  Yüreğimi alıp gidiyordu bayram ...', ARRAY['Türk Edebiyatı','Şiir','Berna Ocakçıoğlu']::text[], 8.5, '{"poet":"Berna Ocakçıoğlu","poet_slug":"berna-ocakcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kucuk-kiz-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'RaBıTa', 'rabita-mahmut-okur-t0iw2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'mezarıma toprağım

kendi ruhumda pişer.

ömrümde her yaprağım

kendi elimden düşer.

beni görüp bir kimse

şöyle ruhuma inse

hak verir de o sese

bana bir mezar eşer.

(1999)', 'mezarıma toprağım kendi ruhumda pişer. ömrümde her yaprağım kendi elimden düşer. beni görüp bir kimse şöyle ruhuma inse hak verir de o sese ...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Okur']::text[], 8.5, '{"poet":"Mahmut Okur","poet_slug":"mahmut-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/rabita-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçtiğimde', 'vazgectigimde-berna-ocakcioglu-yhwqq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevmek seni 

Sanki hiç bir şeyin önemi yokmuş gibi 

Sevmek ve 

Dünün köşelerinde aramak seni 

Zaman gelip geçmiyormuş gibi 

Perişan saatlerde 

Yürüdüğüm caddelerde özlemek seni 

Beraberce adımlamış gibi 

Buruk gölgeler arasında 

Her gün beklemek seni 

Sanki varmışsın, gelecekmişsin gibi 

Ve umutsuzluk içinde bile umut gizlemek 

Tam vazgeçtiğimde bulacakmış gibi.', 'Sevmek seni  Sanki hiç bir şeyin önemi yokmuş gibi  Sevmek ve  Dünün köşelerinde aramak seni  Zaman gelip geçmiyormuş gibi  Perişan saatlerd...', ARRAY['Türk Edebiyatı','Şiir','Berna Ocakçıoğlu']::text[], 8.5, '{"poet":"Berna Ocakçıoğlu","poet_slug":"berna-ocakcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/vazgectigimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerede ortadirek', 'nerede-ortadirek-salih-ozalasan-nw58m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yokluk fakirin avuntusu

Bolluk zenginin kuruntusu

Yokmu bunun bir ortası

Hayat olmuş sitem tarlası

Fakir kahreder hayatın çilesine

Zengin kendini koyar herşeyin tepesine

Sanki karundur emirler verir çevresine

Ortadirek sığacak bunun neresine

Bir zamanlar son hız girmişti

Politikacıların cep cantasına

Balık gibi takılmıştı her atışta oltasına

Şimdilerde oda girdi tarihin tozlu sayfasına

Bir zengini birde fakiri kaldı ülkemin

Biri dolar euro hisse senedi ile evlidir

Diğeri karnı guruldar, simitle geçinir

Ortada kimse kalmamış garibim ezilir

Yine seçim zamanı bolca vaat verilir

Seçim biter bir taraf sevinir, bir tarafta yerinir

Meydanlarda fakire umut, bolkeseden verilir

Bankalarda zengine krediler sormadan önerilir

Kimi banka kurar kimi holdink

Çalışana sigara parası ücret verilir

Mecliste konuşulur öneriler verilir

Desdekse sadece zengine verilir

Kimi avrupa birliği der

Kimiyse hayır tam bağımsızlık

Korkarım biz yine bunlarla aldadıldık

Fakirliğe razıydıkya, inşallah sınıra dayanmaz açlık

Dönmüş miğdeler boş ambara

Sanki olmuşlar birer taşlık

Allah’ım zengine bol para

Biz fakirlerede ihsan et sağlık

Y.Tar.03-12-2002, Saat 22.45', 'Yokluk fakirin avuntusu Bolluk zenginin kuruntusu Yokmu bunun bir ortası Hayat olmuş sitem tarlası Fakir kahreder hayatın çilesine Zengin ke...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/nerede-ortadirek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Kapıları', 'gecenin-kapilari-attila-i-lhan-zp5cn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bütün kapılar kapandı, dışardayım

Birden karşıma çıkmayın korkuyorum

Uykusuzum fena halde, sokaktayım

Karanlık bastırdı mı bozuluyorum

Fena bir yerimden koptuğum doğru

Kendimden çok fazla yaşamaktayım

Nereye bağlanacak bu işin sonu

Aslında ben kimim meraktayım

Bütün kapılar kapandı, sokaktayım...', 'Bütün kapılar kapandı, dışardayım Birden karşıma çıkmayın korkuyorum Uykusuzum fena halde, sokaktayım Karanlık bastırdı mı bozuluyorum Fena ...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gecenin-kapilari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar', 'bahar-tevfik-mengulluoglu-lz5l0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir bahar daha geçer buralardan

Bir esinti okşar anıları

Paketlenen umutlar yığılır

Geceye ezgiler damlar

Takvimi olmayan  Aşklar

yelkovan akrep arasında sıkışıp göçer

Bir bahar daha geçer buralardan

Kuşlar şarkısını söyler mavilere

Saki doğrulur 

testisinden boşaltır aşklarını

Çiçekler sarhoş olur

Gün uzar geceye yakarır

Kuşlar Aşık olur mavilere

Aşkını sevdiğine ilan eder dilsiz bir Aşık

Güneş Dünya''yı dansa kaldırır

Dönüyür dünya

Anadoluda Ozanlar doğrulur

Bir türkü yankılanır durmadan.

Bir bahar Daha geçer Buralardan', 'Bir bahar daha geçer buralardan Bir esinti okşar anıları Paketlenen umutlar yığılır Geceye ezgiler damlar Takvimi olmayan  Aşklar yelkovan a...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bahar-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sibirya Konukları', 'sibirya-konuklari-i-ldeniz-kurtulan-v0eu8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Onlar güneş görmeyen yerde öldüler

Onlar, buzlara gömüldüler.

Bu tren Sibirya''ya gidiyor, 

Solofki''de seneler çürütmüşüz, 

Ormanlarında çamlar devirmişiz.

Ve ölüvermişiz ansızın

Ne gecesi

        ne gündüzü belli olmayan bir yerde

Mevsimsiz bir anda ölmüşüz.

Bizi buzlara gömmüşler, 

Ve sonra gelenler olmuş başka

İrili ufaklı insan kütleleri

İçinde Türk''ü, Ermeni''si, 

Macar''ı, Alman''ı olmuş.

Biz

bu yolun yolcuları, 

Biz Sibirya konukları

Geceli gündüzlü ülkelerdeniz

Biz aşka inanmışız

Biz hür yaşamışız

Şimdi

Ölmüşsek, 

      Ölüyorsak, 

              Öleceksek

Yaşamasını bildiğimizdendir.', 'Onlar güneş görmeyen yerde öldüler Onlar, buzlara gömüldüler. Bu tren Sibirya''ya gidiyor,  Solofki''de seneler çürütmüşüz,  Ormanlarında çaml...', ARRAY['Türk Edebiyatı','Şiir','İldeniz Kurtulan']::text[], 8.5, '{"poet":"İldeniz Kurtulan","poet_slug":"i-ldeniz-kurtulan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sibirya-konuklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Adam', 'yalniz-adam-suat-taser-0qrfd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gece

Camlarda damlalar

Bir kadın

Solgun bir çiçek

Yalnızlıklar içinde

Kapısı kapalı perdesi inik

Ayak sesleri gelir geçer

Rüzgâr sırılsıklam

Son kadehini içer

Basık tavanlı bir meyhanede

Yalnız adam

Sırtında gelinlik elbisesi

Yirmi yaşında bahar

Menekşeler hercai

Işıklar bir söner bir yanar

Havada buram buram leylâk kokusu

Avuçları ateş içinde

Her adımda çamur

Bu karanlık bu yalnızlık bu yağmur

Hele bu kadın

Her adımda çamur

Bu karanlık bu yalnızlık bu yağmur

Gece

Rüzgâr sırılsıklam

Uzaklarda bir yere yıldırım düşüyor

Evin yolunda yalnız adam

Yalnız adam üşüyor', 'Gece Camlarda damlalar Bir kadın Solgun bir çiçek Yalnızlıklar içinde Kapısı kapalı perdesi inik Ayak sesleri gelir geçer Rüzgâr sırılsıklam...', ARRAY['Türk Edebiyatı','Şiir','Suat Taşer']::text[], 8.5, '{"poet":"Suat Taşer","poet_slug":"suat-taser","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yalniz-adam-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmek Kaderim Diyedir', 'olmek-kaderim-diyedir-hasan-simsek-pdn66', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben her işin başı sevgi diyorum

Dünya güzel yaşamak iyi diyorum

Daha evvel sabah ezanından

Siz uykudayken uyanıyorum

Toprakta bir buğu bir duman

Eğilip öpüyorum toprağı ıslak alnından

Yere uzanıyorum

Bir gökyüzü dost diyorum bir yeryüzü

Şüphesiz Allah''a inanıyorum

Her yerde hazır ve nazır olan.

Kaderime güveniyorum

Alınterime güveniyorum

Ellerim hayatla sarmaş dolaş

Ellerime güveniyorum

Mekân tutup yerleşiyor içimde hey

Gökler dolusu mavi bir şey

Aşk mı desem umut mu desem

Beş duyum tetiktedir

Hayretle bakıyorum ne görsem

Şu ırmak diyorum şu köprü şu taş

Şu iğde ağacı çiçektedir

Kokusundan tanıyorum

Ortalık ışıyor yavaş yavaş

Güneş doğuyor

Sigaramı güneşten yakıyorum

Karınca buğday taşıyor görüyorum

Yol silkinip uzanıyor

Dağ rahatça yerleşiyor görüyorum

Başım dinç gözüm çıralı

Ayağa kalkıyorum

Gün pazartesidir yahut salı

Kendimi vakte bırakıyorum

Kalın kirli bir gömlek gibi

Soyunup atıyorum üzerimden geceyi

Giyinip kuşanıyorum gündüzü

Kanım damarlarımda özsu

Canım tenimde burcu burcu

Çabam savaşma gücüm yeni

Dilimde bir memleket türküsü

Çalışmaya gidiyorum

Duyduğum ne hazdır ne de elem

Bunca telaşım, tehâlüküm, acelem

Ölmek kaderim diyedir, yaşamak vazifem

Ben her işin başı sevgi diyorum

Dünya güzel yaşamak iyi diyorum', 'Ben her işin başı sevgi diyorum Dünya güzel yaşamak iyi diyorum Daha evvel sabah ezanından Siz uykudayken uyanıyorum Toprakta bir buğu bir d...', ARRAY['Türk Edebiyatı','Şiir','Hasan Şimşek']::text[], 8.5, '{"poet":"Hasan Şimşek","poet_slug":"hasan-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/olmek-kaderim-diyedir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarına', 'yarina-abdurrahman-efem-8sscy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hiç anlamadım

Ve hiç öğrenemeyeceğim 

Yarının benle alıp veremediğini

Ben mi yarını hak etmiyorum yarın mı beni', 'Hiç anlamadım Ve hiç öğrenemeyeceğim  Yarının benle alıp veremediğini Ben mi yarını hak etmiyorum yarın mı beni...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahman Efem']::text[], 8.5, '{"poet":"Abdurrahman Efem","poet_slug":"abdurrahman-efem","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yarina-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'El''e', 'el-e-serra-aybars-ojjci', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kışın gelmesiyle eldiven altına saklanırlar, 

Üşürler onlar, ısıtmalı, 

Dalda gördüğün elmayı almak için uzanırsın, 

Tutarsın, hissedersin..

Derste söz almak için 10da birini kulanırsın, 

Otobüste tutunmak için 2şer 3er, 

Ağladığında gözyaşlarını silmek için, 

Sevdiğine sevgini göstermekte, 

''Seni seviyorum''diyemediğin durumlarda yazmakta, 

Kızdığın sırada parçalama, dağıtmada, 

Şiir yazmakta....', 'Kışın gelmesiyle eldiven altına saklanırlar,  Üşürler onlar, ısıtmalı,  Dalda gördüğün elmayı almak için uzanırsın,  Tutarsın, hissedersin.....', ARRAY['Türk Edebiyatı','Şiir','Serra Aybars']::text[], 8.5, '{"poet":"Serra Aybars","poet_slug":"serra-aybars","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/el-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Havuz', 'havuz-serra-aybars-btj86', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüzme bilmiyorum ben

Ayak çırp diyorlar, yapamıyorum

Renkli renkli kolluklar öneriyorlar

Ördekli simitler

Batıyorum, düşüncelerimde boğuluyorum..', 'Yüzme bilmiyorum ben Ayak çırp diyorlar, yapamıyorum Renkli renkli kolluklar öneriyorlar Ördekli simitler Batıyorum, düşüncelerimde boğuluyo...', ARRAY['Türk Edebiyatı','Şiir','Serra Aybars']::text[], 8.5, '{"poet":"Serra Aybars","poet_slug":"serra-aybars","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/havuz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-ruzin-azerhan-ct4kd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çöker sis gibi geceler; atılırım kollarına karanlığın

Boşlukta bir son ararım

Hiçbirşey senin gibi sonsuz değil annem

Kor küllerinde yürürken hayatın

Yanar kavrulur heryerim

Hiçbirşey kolların kadar sıcak değil annem

Küçükken kaybolan bebeklerimdi

Büyüdüm umutlarım yitti

Hiçbirşey acı olmadı birdamla gözyaşından annem

Sesini işitmek; kokunu duymak

Dokunmak sana; seni hissetmek

Hiçbirşey anlamlı olmadı bukadar annem

02.05.1999', 'Çöker sis gibi geceler; atılırım kollarına karanlığın Boşlukta bir son ararım Hiçbirşey senin gibi sonsuz değil annem Kor küllerinde yürürke...', ARRAY['Türk Edebiyatı','Şiir','Ruzin Azerhan']::text[], 8.5, '{"poet":"Ruzin Azerhan","poet_slug":"ruzin-azerhan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/annem-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkma', 'korkma-ruzin-azerhan-h9j97', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayattan korkma

Bırak acılar yüreğine

Sevinçler iliklerine işlesin

Yaşamak bir oyunsa

En iyi sen oyna

Perde kapanınca

ÇOK GÜLECEKSİN', 'Hayattan korkma Bırak acılar yüreğine Sevinçler iliklerine işlesin Yaşamak bir oyunsa En iyi sen oyna Perde kapanınca ÇOK GÜLECEKSİN...', ARRAY['Türk Edebiyatı','Şiir','Ruzin Azerhan']::text[], 8.5, '{"poet":"Ruzin Azerhan","poet_slug":"ruzin-azerhan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/korkma-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ufak Bir Şikayet Dürtüsü', 'ufak-bir-sikayet-durtusu-charles-bukowski-62a0g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'aslında olanlar

ve olması gerekip de olmayanlar

ilginç.

görmeye değer bir yer dünya, 

bizi yarı-uyur yakalayan

ve daha işimizin bittiğini anlayacak

kadar yaşlanmadan öldüren

örümcekler ve ağlarla örülü

bir orospu değilse karındır

karın değilse vergi koşuşturması

veya ekmek ya da içkidir, 

ya da birisi kayıyordur karına

sen aşağıda dükkanda

onu ipekler içinde yaşatmak için kıçını yırtarken.

ya da altılı ganyana

veya ota sarmışsındır

belki bulmaca çözmeye

belki de vitaminlare ya da Beethoven''a.

ama 30 metrelik bir yatta neler

olduğunu görmelisin: 

genç güzel kadınların başka birine

neler yapabildiğini görmek

vazgeçirtir seni özgürlükten

küçük dergiler ve Tolstoy''dan.

ve o adamın umurunda bile değildir, 

cimri bir kadeh doldururken şöyle der sana, 

o orospu var ya

tavşanlar bile onun kadar düzüşemez, 

eğer paran yoksa

daha olayı kavrayamadan

ya bunarsın yaşlılıktan

ya da ölürsün.

ve kız orada dikilir trabzanın yanında

bir içim su

altın güneşi ve som altından, 

dünyanın en büyük yüzme havuzunda balıklar

dolanırlar, ve hatta gülümser sana

sen aşağıya inerken daha fazla şişe

ve çizme çıkarmaya

ve efendinin midyelerini kazımaya; 

ama, ah, seni domuz! -senin yaptıklarının

hepsini söyledi bana, erkek söyler ya- ki bu da

sen ve benim iyi

ya da yeterince yaşamadığımızı söylemenin

bir başka yoludur.', 'aslında olanlar ve olması gerekip de olmayanlar ilginç. görmeye değer bir yer dünya,  bizi yarı-uyur yakalayan ve daha işimizin bittiğini an...', ARRAY['Türk Edebiyatı','Şiir','Charles Bukowski']::text[], 8.5, '{"poet":"Charles Bukowski","poet_slug":"charles-bukowski","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/ufak-bir-sikayet-durtusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bergama da bir gün', 'bergama-da-bir-gun-riza-aslan-v2psy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bilinmezliğin

o buruk tadı

güneşin soğuğu içinde

kabuslara giren perilere inat

birbirine benzeyen

aynı yerde başlayan

aynı yerde biten

hep bir yere 

gittiğini sanıp

aslında gitmediğin

mekansız, sınırsız

göz göre göre 

kendini kandırdığın

bu mekan

bu zaman

biter mi? 

bir gün

ovalamaktan ağrıyan 

gözlerinle

ufkun son noktasında

kelimelerin boğazda düğümlenip

kördüğüm olduğu o en son noktada

yeter diye haykırılabilecek

bu anlamsız günler

biter mi? 

bir gün

her yeni günle

yeniden başlayan

ve her yeni günle

biraz daha büyüyüp güzelleşen

karamsallık gülleri

solar mı? 

bir gün

04  Aralık  2002', 'bilinmezliğin o buruk tadı güneşin soğuğu içinde kabuslara giren perilere inat birbirine benzeyen aynı yerde başlayan aynı yerde biten hep b...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bergama-da-bir-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram', 'bayram-omer-bayhan-brxne', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çocukluğumda, 

Bayramlar şeker kağıdına sarılıydı..

Sarı, kırmızı, menekşe alası parlak kağıtlara..

Cebimde özenle avuçladığım şekerlemenin, 

iki ucundan kıvrık jelatini her düzleştirdiğimde, 

yüreğimin en yüksek tondan tıkırtısını sanki şakaklarımda hisseder, 

titrek davranışlarla çıkarıverirdim, bayramlarımı ortaya..

Önce bir faytonda bulurdum kendimi..

Binlerce cıvıltının arasında kulak kabartıp, 

parke taşlarında atın nal sesleri kütürderken, 

hala anamın ve babamın dudak sıcaklığı dururdu yanaklarımda..

Yerinde duruyor mu diye, kontrol ettiğim bozuk paralarımla, 

sadece satın alabileceğim bayram oyuncaklarının değil, 

bayram''cılarında hayalini kurardım.

Atlı karıncaların gözleri cam gibi donuk, 

                                            katı vucutlu, 

                                                            yelesi sert atları üzerinde

kaptırıp müziğin ahengine kendimi, 

kah pekos bill..Kah red-kit olmanın kıvancını yaşardım.

İri kalın bilekleri ile bizi sonsuza iten bayramcının, 

kırmızı kayık salıncaklarında evrene uçar, 

çocuksu korkularımı bastırıp içime, 

küçük kardeşimin heyecanını devralmaya çalışırdım.

Müdavimiydim köftecilerin..

Abonesi olmuştum turşucuların..

Her bayram sonunda olduğu gibi, 

Mide fesatıydı..Bayram sonunda karşılaştığım..

Benim çocukluğumda, 

Şeker kağıdına sarılıydı bayramlar..

Sarı, kırmızı, menekşe alası parlak kağıtlara..

ÖMER BAYHAN', 'Çocukluğumda,  Bayramlar şeker kağıdına sarılıydı.. Sarı, kırmızı, menekşe alası parlak kağıtlara.. Cebimde özenle avuçladığım şekerlemenin,...', ARRAY['Türk Edebiyatı','Şiir','Ömer Bayhan']::text[], 8.5, '{"poet":"Ömer Bayhan","poet_slug":"omer-bayhan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bayram-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kız Bana Emmi Dedi', 'bir-kiz-bana-emmi-dedi-karacaoglan-am5n5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Değirmenden geldim beygirim yüklü

Şu kızı görenin del''olur aklı

On beş yaşında kırk beş belikli

Bir kız bana emmi dedi neyleyim

Birem birem toplayayım odunu

Bilem dedim bilemedim adını

Albıstan yanaklı Türkmen kadını

Bir kız bana emmi dedi neyleyim

Bizim ilde urum olur uc olur

Sızılaşır bozkurtları aç olur

Bir yiğide emmi demek güç olur

Bir kız bana emmi dedi neyleyim

Karac''oğlan der ki n''olup n''olayım

Akan sularınan ben de geleyim

Sakal seni makkabınan yolayım

Bir kız bana emmi dedi neyleyim', 'Değirmenden geldim beygirim yüklü Şu kızı görenin del''olur aklı On beş yaşında kırk beş belikli Bir kız bana emmi dedi neyleyim Birem birem ...', ARRAY['Türk Edebiyatı','Şiir','Karacaoğlan']::text[], 8.5, '{"poet":"Karacaoğlan","poet_slug":"karacaoglan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-kiz-bana-emmi-dedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Tren', 'kara-tren-seyit-ahmet-duzen-7sv8l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çokşey yazıldı ayrılığa dair

Yazmalıydım ama ne

Ayrılık yazdım sen

Seni yazdım ayrılık

Düşündükçe çoğalıyordun içimde

Sende yolculuk telaşı

Ben de hoşçakal

Bir istasyondaydı ayrılığın

Kara idi seni taşıyan tren

Sen gittin ya çıkmadi kalbimden

Bindiğin kara tren

Sen veda yazdın

Karaladım hemen gel

Sirensesleriyle irkilen ben

Yazamıyorum ayrılığı

Şimdi gel

Gelki bir istasyon bulsun

İçimdeki kara tren', 'Çokşey yazıldı ayrılığa dair Yazmalıydım ama ne Ayrılık yazdım sen Seni yazdım ayrılık Düşündükçe çoğalıyordun içimde Sende yolculuk telaşı ...', ARRAY['Türk Edebiyatı','Şiir','Seyit Ahmet Düzen']::text[], 8.5, '{"poet":"Seyit Ahmet Düzen","poet_slug":"seyit-ahmet-duzen","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kara-tren-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bilirmisin', 'sen-bilirmisin-fazil-husnu-cakiroglu-okke5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen beni tanirmisin? 

Yada sonsuz dünyami bilirmisin? 

Sen hic sonsuzluga göz kirpan yildizlarimi, 

Bulutlardan yagmur bekleyen catlamis topragimi, 

Icine kapandikca kapanan ormanlarimi, 

Sen ne bilirsinki? 

Sen herseyi bildigini sanirsin.

Oysa o tatli nininin altinda iniltiyi, 

Ayaz gecelerdeki buz catirtilarini, 

Issiz daglarin korkunc yanlizlik cigliklarini, 

Sen ne bilirsinki kendinden baska? 

Suskunlugun feryadi, 

Tebesümün aciyi, 

Aydinligin karanligi getirecegini bilmezsin.

Üsür gecede yalnizliklar.

Usanir paylasilmamis asklar.

Ve utanir adi konmamis yasanmisliklar.

Sen hic dile gelmeyen sözlerin kalem ucu anini, 

Titrek hayallerin gölgesinde yasamayi, 

Yada günbatimi sarhoslugunun ardindan

Sarpa sarmis karamsarliklarla yogruldunmu? 

Bilmezsin ki! 

Sen bir kendini bilirsin.

Cünkü sen yanliz kendini yasiyorsun.

                                                     Fazil Hüsnü Cakiroglu', 'Sen beni tanirmisin?  Yada sonsuz dünyami bilirmisin?  Sen hic sonsuzluga göz kirpan yildizlarimi,  Bulutlardan yagmur bekleyen catlamis top...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Çakıroğlu']::text[], 8.5, '{"poet":"Fazıl Hüsnü Çakıroğlu","poet_slug":"fazil-husnu-cakiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sen-bilirmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-fazil-husnu-cakiroglu-s3o3g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ölüm! 

Kendi sesinin

Kendi beninde

Yanki bulmamasi.

Düs! 

Bir ötekinin

Bir berikinin

Uykusuna ansizin

Gelip girmesi.

Ve yasam

Ikilemler arasinda

Her sonun baslangicin da

Daima ilk.', 'Ölüm!  Kendi sesinin Kendi beninde Yanki bulmamasi. Düs!  Bir ötekinin Bir berikinin Uykusuna ansizin Gelip girmesi. Ve yasam Ikilemler aras...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Çakıroğlu']::text[], 8.5, '{"poet":"Fazıl Hüsnü Çakıroğlu","poet_slug":"fazil-husnu-cakiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/olum-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızıma', 'kizima-mehmet-kemal-tumac-ca28m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gün olup sende ağlayacaksın  yavrum 

kızacaksın yalnızlığına. 

her çaresiz kaldığında, 

gözyaşlarını biriktir büyük bir çukurda 

kağıttan gemilerini yüzdürerek 

avunmayı öğren gözyaşlarında.', 'gün olup sende ağlayacaksın  yavrum  kızacaksın yalnızlığına.  her çaresiz kaldığında,  gözyaşlarını biriktir büyük bir çukurda  kağıttan ge...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kemal Tumaç']::text[], 8.5, '{"poet":"Mehmet Kemal Tumaç","poet_slug":"mehmet-kemal-tumac","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kizima-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Für Elie II', 'fur-elie-ii-ayse-coskun-mtg86', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yazık oldu sana da be

Scorpions çalıyor, nasıl bas yazmış

dokunaklı, başka ne denir

Gece, soğudu toprak, aklım karışık

Sanırım delirdim demiştim ya, galiba gerçek

-oysa küçük şeyler bunlar değil mi? -

Keşke Cem Karaca gibi; ''bence artık sen de''

oysa hala; ''woman, I''m only a man''

Bunu dinlediğimde aydınlanmıştı aklım

Dün, gecenin bir yarısı, oda savaşırken

Bana ''tanımazsın'' dedin, her dediğin anlamlı

Kadın gibi düşünüyor senin de aklın...', 'Yazık oldu sana da be Scorpions çalıyor, nasıl bas yazmış dokunaklı, başka ne denir Gece, soğudu toprak, aklım karışık Sanırım delirdim demi...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Coşkun']::text[], 8.5, '{"poet":"Ayşe Coşkun","poet_slug":"ayse-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/fur-elie-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Für Elise III', 'fur-elise-iii-ayse-coskun-qqgpi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'notların bitmesine dair

umudum tükenmek üzere

Umudum tükenmek üzere

birçok şeye de dair

Osman Serhat diyor ya

''bir gün seni ne yere 

ne göğe koyabildiğimi anlayacak 

ve üzüleceksin''

Böyle birşey hissettiğim

Pis bir egoizm belki de

narsistçe, kimbilir

Keşke burada olsan şimdi

Bu kadar işte

tüm soruların cevabı.', 'notların bitmesine dair umudum tükenmek üzere Umudum tükenmek üzere birçok şeye de dair Osman Serhat diyor ya ''bir gün seni ne yere  ne göğe...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Coşkun']::text[], 8.5, '{"poet":"Ayşe Coşkun","poet_slug":"ayse-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/fur-elise-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Für Elise IV ve Son', 'fur-elise-iv-ve-son-ayse-coskun-awxyt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen olmasaydın

bir başkası olurdu

sürüklenirdim yine

Bu kadar yakınken

Böyle uzak olmak

bu kadar benzemek mi suç? 

Gitmek zamanı geldi

n''olurdu biraz üzülsen...

Aslında upuzun bir kelimedir

hoşçakal...', 'Sen olmasaydın bir başkası olurdu sürüklenirdim yine Bu kadar yakınken Böyle uzak olmak bu kadar benzemek mi suç?  Gitmek zamanı geldi n''olu...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Coşkun']::text[], 8.5, '{"poet":"Ayşe Coşkun","poet_slug":"ayse-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/fur-elise-iv-ve-son-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Vapur Bizi Nereya Götürecek', 'bu-vapur-bizi-nereya-goturecek-ayse-coskun-go39b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu vapur bizi nereye götürecek

savruluyoruz baksana

Çok özlenmiş sevgililer gibi

hiç gelmiyor bize hayatı yaşamak sırası.

Bu vapur bizi nereye götürecek

Hangi limanda bulacağız

yitik gençliğimizi

Ya da yüzümüzdeki kırışıklıkları

hangi deniz iyi edecek

Kim birleştirdi ki bizi

kim ayıracak, kim derleyecek

bu vapur bizi nereye götürecek? 

Seçili yılları yaşadım

Hatırladıklarımdan ötesi yok

seni arama yollarını biliyorum

ne halta yarıyor ki zaten gerisi

Ne kaptanım ne denizci

hiç de anlamam zaten

Takıldığım peşin sıran

gerisinin hükmü yok

Kayıp güneş, sana soruyorum, bir kez daha

Bağırarak ama sorgu değil, kavgasız

Baksana savrulmuşuz, yokuz artık

söyle, bu vapur bizi nereye götürecek

bizden daha ne kadar daha uzağa?', 'Bu vapur bizi nereye götürecek savruluyoruz baksana Çok özlenmiş sevgililer gibi hiç gelmiyor bize hayatı yaşamak sırası. Bu vapur bizi nere...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Coşkun']::text[], 8.5, '{"poet":"Ayşe Coşkun","poet_slug":"ayse-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bu-vapur-bizi-nereya-goturecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşime', 'esime-mehmet-kemal-tumac-b11wo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gün olup kapımızı çaldığında ölüm.

birimizin ağlayacağı muhakkak 

ve 

çocuklarımızın 

ölüm hak miras helal diyeceği...', 'gün olup kapımızı çaldığında ölüm. birimizin ağlayacağı muhakkak  ve  çocuklarımızın  ölüm hak miras helal diyeceği......', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kemal Tumaç']::text[], 8.5, '{"poet":"Mehmet Kemal Tumaç","poet_slug":"mehmet-kemal-tumac","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/esime-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece üzerine 1', 'gece-uzerine-1-mehmet-kemal-tumac-iy1b3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kendimi dinleyebildiğim için 

geceleri çok  seviyorum. 

askerlerin üç-beş nöbeti gibi

şiire kalkıyorum.', 'kendimi dinleyebildiğim için  geceleri çok  seviyorum.  askerlerin üç-beş nöbeti gibi şiire kalkıyorum....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kemal Tumaç']::text[], 8.5, '{"poet":"Mehmet Kemal Tumaç","poet_slug":"mehmet-kemal-tumac","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gece-uzerine-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulurmuş', 'unutulurmus-i-brahim-erkal-iu2tm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayatın tadı tuzuydun 

Sanki kınalı kuzuydun 

Menekşelerin kızıydın

Adın baharmıydı senin 

Vazgeçilmez bir tutkuydun 

Gönül bahçemin ufkuydun 

Gittinde kimlere uydun 

Adın sevdamıydı senin 

Yokluğun ateşten gömlek 

Dayanamaz buna yürek

Unuttum istemeyerek

Adın hasretmiydi senin 

Her nefeste seni aldım

Her gece uykusuz kaldım 

Sanki çölde susuz kaldım 

Adın Leyla mıydı senin

Unuturmuşum adını 

Anlatırmışım tadını

Haya kırsın inadını

Sende buna gülmelisin 

İşte buna üzülmelisin.', 'Hayatın tadı tuzuydun  Sanki kınalı kuzuydun  Menekşelerin kızıydın Adın baharmıydı senin  Vazgeçilmez bir tutkuydun  Gönül bahçemin ufkuydu...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Erkal']::text[], 8.5, '{"poet":"İbrahim Erkal","poet_slug":"i-brahim-erkal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/unutulurmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mesafeler...', 'mesafeler-tulin-askan-r8n2s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Armizdaki mesafeler nekadar uzun olursa olsun, 

sonsuzluga giden tumyollara adini yazdim, 

hangi yoldan gecersen gec, 

seni sevdigimi okuyacaksin...', 'Armizdaki mesafeler nekadar uzun olursa olsun,  sonsuzluga giden tumyollara adini yazdim,  hangi yoldan gecersen gec,  seni sevdigimi okuyac...', ARRAY['Türk Edebiyatı','Şiir','Tulin Askan']::text[], 8.5, '{"poet":"Tulin Askan","poet_slug":"tulin-askan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/mesafeler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çirkin Ördek Yavrusu''nun Hayata Dair Düşünceleri', 'cirkin-ordek-yavrusu-nun-hayata-dair-dusunceleri-turgay-kaygi-fankx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''hayat; 

tanrıyı yaratmamla başlayan ve o''nu yok edeceğim güne kadar sürecek olan zaman dilimidir. 

işte ben o gün geldiğinde bir daha mutsuzluk nedir bilmeyeceğim...''

kısa bir süre

öncesine kadar

dünyaya gelmeseydim

birçok şeyden tasarruf edilirdi

diye

düşünüyordum

sudan mesela

ya da havadan, ekmekten, 

psikiyatristler 

kompleks diyorlar

buna

fakat

başkalarına da olur mu bilmem! ; 

bana bazen alacaklıymışım gibi

geliyor hayattan

yani, 

nasıl anlatsam; 

günde onbir saat çalışıp da

iki lokma geçirince

boğazımdan içeri

ve 

bir zamanlar 

kralların soluduğunu bildiğim havayı

çekebildiğim için 

içime

şanslı hissediyorum 

kendimi

ama

ne kadar içsem

ne kadar yunsam da

suya kanamıyorum 

elimde değil

balıkçıların yakalayıp

karaya attığı

şaşkın balıklar gibi

değil 

benim suya hasretim

sığ yerlerine razı değilim 

denizin

ben

okyanusların en derin

yerlerinde

ötesini-berisini düşünmeden

asi ve hür

gezinebilmek istiyorum...

diyeceğim şu ki aslında; 

insanlar, 

yani biz; 

bir sarayın bodrumundaki

fareler gibiyiz

ne yaşadığımızdan haberi var

bu sarayın sahibinin, 

ne de umrunda

neyi isteyip, 

neyi istemediğimiz

ben buna inanıyorum, 

isteyenler

tanrının canı sıkılmasın diye

oynanmakta olan bir piyesin

başrol oyuncusu olduklarına

inanabilirler

(inegöl,04.12.2002)', '''hayat;  tanrıyı yaratmamla başlayan ve o''nu yok edeceğim güne kadar sürecek olan zaman dilimidir.  işte ben o gün geldiğinde bir daha mutsu...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kaygı']::text[], 8.5, '{"poet":"Turgay Kaygı","poet_slug":"turgay-kaygi","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/cirkin-ordek-yavrusu-nun-hayata-dair-dusunceleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyun Bozan', 'oyun-bozan-eymen-ozcelik-5yetb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölümü cazip kıldığın oldu mu

Hayatında...

Renklendiremediğin resimlerin

Adını bilemediğin çiçeklerin

Algılayamadığın dokunuşlar

Yarım kalmasına üzüldüğün sevdalar

Oldu mu bilmiyorum; 

Hepsini kana bulayan 

Bir oyun bozan.

Ama benim; 

Ölümün ta kendisi

Rengarenk bir resmim

Adını verdiğim ilk çiçek

Hissettiğim tek dokunuş

Üzüldüğüm son sevdam

Oldu; 

Hepsini kana bulayan

Bir oyun bozan.', 'Ölümü cazip kıldığın oldu mu Hayatında... Renklendiremediğin resimlerin Adını bilemediğin çiçeklerin Algılayamadığın dokunuşlar Yarım kalmas...', ARRAY['Türk Edebiyatı','Şiir','Eymen Özçelik']::text[], 8.5, '{"poet":"Eymen Özçelik","poet_slug":"eymen-ozcelik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/oyun-bozan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üçüncü Yol', 'ucuncu-yol-yetik-ozan-vnqjx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sayıyorsan beni kendine yakın

Hem ben bilem hem sen bil, bilişelim, 

Benim köyüm senin kentine yakın; 

Hem ben gelem hem sen gel, gelişelim.

Ağustos içti de yerin suyunu

Kuruttu pınarın serin suyunu, 

Irak kuyuların derin suyunu

Hem ben alam hem sen al, alışalım.

Güneşin hıncı var, bulutun nazı, 

Bileğin gücü yok, yüreğin hazı, 

Tarlada tırpanı, halayda sazı

Hem ben çalam hem sen çal, çalışalım.

Ben tutmuşum beni kul eden yolu, 

Sen tutmuşsun seni el eden yolu, 

Bizi bize doğru ileten yolu

Hem ben bulam hem sen bul, buluşalım.', 'Sayıyorsan beni kendine yakın Hem ben bilem hem sen bil, bilişelim,  Benim köyüm senin kentine yakın;  Hem ben gelem hem sen gel, gelişelim....', ARRAY['Türk Edebiyatı','Şiir','Yetik Ozan']::text[], 8.5, '{"poet":"Yetik Ozan","poet_slug":"yetik-ozan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ucuncu-yol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidenlere Vefa', 'gidenlere-vefa-ali-niku-5g2ts', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'geçmişle gelecek duygusal bir an için

biraraya gelmişti ortak bir bedende

uhrevi bir havayı teneffüs etmek için

birisi düşler iken geçmişte olanları

bir diğeri çaresiz beklemekte dua''yı

karanfil''le beyaz gül, hatırlatırsa an''ı

birisi bekler onu, gelenler ağlamaklı

unutmamak ne iyi, hatırlamak zamanda

gidenler yaşamışlık, gelenler beklemede

iki can bir bedende oluşmuş düşüncede

iyilik anıldıkça, vefasızlık zihinde

bir tatlı rüzgar eser gelenlerin içinde...

işte geldim gidiyorum, gelemem bir daha 

sizede örnek olsun yaşanmışlık da sefa

düzeltme şansın hiç yok, buraya geldiğinde

keşke demek faydasız geriye dönülmez ki

dönsen beş para etmez, yapılanlar o anda

gelmeden hesabına vade farkı bırakma

yaşarken peşin yaşa, peşin öde dostlukta...

bayramlara coşkuyu sarmalamadan gider

hüzünlü anlar için arefe''den hatırlar

bir buket çiçek ona yetecekmi bilinmez

hatıralar uğruna bunu mecbur hisseder

bir yeşillik örtüye toprak yataklık eder

o toprağın altında bekleyenlere vefa

bekleyen toprak olmuş, anılarda olsada...', 'geçmişle gelecek duygusal bir an için biraraya gelmişti ortak bir bedende uhrevi bir havayı teneffüs etmek için birisi düşler iken geçmişte ...', ARRAY['Türk Edebiyatı','Şiir','Ali Niku']::text[], 8.5, '{"poet":"Ali Niku","poet_slug":"ali-niku","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gidenlere-vefa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gamlanma Gönül', 'gamlanma-gonul-karacaoglan-ju6ym', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kemler iyi göremez

Gamlanma gönül gamlanma

Bin kaygu bir borç ödemez

Gamlanma gönül gamlanma

Koyun meler kuzu meler

Sular hendeğinde dolar

Ağlayanlar bir gün güler

Gamlanma gönül gamlanma

Yiğit yiğidin yoldaşı

At yiğidin öz kardaşı

Sağlık her şeyin başı 

Gamlanma gönül gamlanma

Naçar Karac''oğlan naçar

Pençe urup göğsün açar

Kara gündür gelir geçer

Gamlanma gönül gamlanma', 'Kemler iyi göremez Gamlanma gönül gamlanma Bin kaygu bir borç ödemez Gamlanma gönül gamlanma Koyun meler kuzu meler Sular hendeğinde dolar A...', ARRAY['Türk Edebiyatı','Şiir','Karacaoğlan']::text[], 8.5, '{"poet":"Karacaoğlan","poet_slug":"karacaoglan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gamlanma-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Bir Şiirsin Sen', 'eski-bir-siirsin-sen-ensar-aktas-1smq7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eski bir şiirsin sen durdukça yıllanırsın

Gözden çok ıraksın, ama gönülden çok yakındasın

Gözlerimi mahrum bıraktın o gül yüzünden ama

Hayalin senin kadar zalim değil, her gece rüyamdasın

Eski bir şiirsin sen soldukça yeşerirsin

Bir ağustos akşamıydı sessiz sedasız çekip gidişin

Şimdi bana zemheri oldu sayende her mevsim ama

Her seher yeliyle birlikte bana baharlar estirirsin

Eski bir şiirsin sen okudukça okunursun

Bardaktan boşalır gibi gözlerimden akar durursun

Bir kıvılcım kadar cürümün kalmamış belki ama

Kalbimi her nefeste yakıp kül gibi kavurursun

Eski bir şiirsin sen hatıra defterimde

Aşk dolu sevda dolu hâlâ her sözcüğünde

Ne silinir ne çıkarsın, kazılısın beynimin köşesinde

Gül kokulu hayat dolu eski bir şiirsin sen ezberimde

Rotterdam/Gouda,02.12.2002', 'Eski bir şiirsin sen durdukça yıllanırsın Gözden çok ıraksın, ama gönülden çok yakındasın Gözlerimi mahrum bıraktın o gül yüzünden ama Hayal...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/eski-bir-siirsin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutganlığımı Unuttum', 'unutganligimi-unuttum-ensar-aktas-8t267', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Unutganlığımı unuttum ben yine seni hatırladım

Saçlarından yaptığım uçurtmayı bulutlara uğurladım

Sende unuttuğum bana söz vermiştim seni anmayacağıma

Sözümü tutamadım yine gözlerinde unuttuğum gözlerimi yaşarttım

Madem gidecektin niçin beni de aldın yanına

Bir veda busesiydi benimkisi kondurduğum yanağına

Sen adını unuttun benim dudaklarımda

Bense dudaklarımı unutmuşum senin yanaklarında

Mademki unutmakta ecel olacaktı unutulmamakta

Niçin unutamadım seni, beni unuttuğun aşk şarkılarında

Sen beni canlı canlı gömdün kalbinin bir kenarına ama

Ben senin kalbinde unutmuşum canımıda, aşkımıda

Unutganlığımı unuttum ben yine seni hatırladım

Gözlerinden kopardığım gökkuşaklarını köprü yaptım

Sevda ülkelerinden geçip cennetine varayım derken

Ayağım takıldı sende unuttuğum anılara cehennem ateşiyle yandım

Rotterdam,03.12.2002', 'Unutganlığımı unuttum ben yine seni hatırladım Saçlarından yaptığım uçurtmayı bulutlara uğurladım Sende unuttuğum bana söz vermiştim seni an...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/unutganligimi-unuttum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Birşey Söyle', 'bana-birsey-soyle-ensar-aktas-z1leg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bana birşey söyle

İstersen kız bağır ‘Seni sevmiyorum’ de

‘Senden nefret ediyorum’ de

Yeterki bana birşey söyle

Karanlıkta bırakma sevenlerin dünyasını aniden

Sen aç gözlerini doğ güneş gibi yeniden

Ben severek ölürüm senin yerine

Vazgeçmek pahasına senden ve sevginden

Yeterki aç gözlerini bana birşey söyle

Rotterdam,03.12.2002', 'Bana birşey söyle İstersen kız bağır ‘Seni sevmiyorum’ de ‘Senden nefret ediyorum’ de Yeterki bana birşey söyle Karanlıkta bırakma sevenleri...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bana-birsey-soyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam', 'yasam-berk-berk-azj3v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözümü açtım, yalnızdım çok

Bakındım çevreme, tanımadığım yüzler...

Bir korku, sert bir hareket, bir sürü gözyaşı

Sonradan öğrendim, doğmakmış bu...

Bir kişilik arayışı, ufak tefek bunalımlar

Bilinmez yollara girişler, acı verici kayboluşlar...

Bir sürü ilkler silsilesi, sonu gelmeyen hüsranlar

Sonradan öğrendim, büyümekmiş bu...

Bir gün bir nefret yeşerir, içinde bir yerde

Karşı koyamazsın güzelliğine, hayran kalırsın...

Büyütürsün onu, dayanamazsın, sonunda koşarsın

Sonradan öğrendim, ölmekmiş bu...', 'Gözümü açtım, yalnızdım çok Bakındım çevreme, tanımadığım yüzler... Bir korku, sert bir hareket, bir sürü gözyaşı Sonradan öğrendim, doğmakm...', ARRAY['Türk Edebiyatı','Şiir','Berk Berk']::text[], 8.5, '{"poet":"Berk Berk","poet_slug":"berk-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yasam-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşey Aşk İçindi', 'hersey-ask-i-cindi-ensar-aktas-hzhs7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Elime tutuşturulan yırtık bir kağıt parçasının üzerinde aynen şöyle yazılıydı

‘Herşey aşk içindi’

Seni gözünü bile kırpmadan kendini bıraktığın bir boşluğun yamacında bulduklarında

Cebinden bana ait bir resim ve birde bu kağıt parçası çıkmış

Evet, herşey aşk içindi

Belki senin uğruna Ferhat gibi dağları delmeye kalkışmadım

Ama sana kavuşmak için gece gündüz demeden sıra sıra dağları aştım

Ve her bir dağın arkasına vardığımda sana bir adım olsun yaklaşmayı umuyorken

Senden bin adım daha uzaklaştığımı farkettim

Kendimi uçsuz bucaksız karanlık yadellerin kuçağında buldum

Ama senden uzaklaştığım her bir adımda

Kalbimin sana bin ışık yılından daha fazla yaklaştığını hissettim

Evet, herşey aşk içindi

Hani giderken yüzümü kaldırıp gözlerine bakacak cesareti bulamamıştım

Boğazım düğüm düğüm olmuştu da ne ‘hoşçakal’ diyebilmiştim

Nede sana veda edebilmiştim

Oysa yüreğim avazı çıkarcasına ‘Seni seviyorum! , Seni seviyorum! ’ diye haykırıyordu

Evet, herşey aşk içindi

Sana ne el sallayabilmiştim

Nede elimi kaldırıp yanağında donakalan iki damla gözyaşını silebilmiştim

Senden kaçarcasına attığım her adımda maksatım ne senden kaçmaktı

Nede kendimi Yusuf gibi yadellerin kör kuyularına attırmaktı

Benim tek düşüncem aramızdaki bütün engelleri kaldırıp sana öyle varmaktı

Sana engelsiz, eksiksiz bütün benliğimle, tertemiz yüreğimle kavuşmaktı

Gel görki sevmesini beceremediğim gibi, kavuşmasını da beceremedim

Meğer ben ufacık engellere meydan savaşları açadururken

En büyük düşmanım, kaderin sillesini hiç hesaba katmamışım

Evet, herşey aşk içindi

Sen ettiğin yeminlerdeki gibi beyazları giymiş önümde öyle sessiz sedasız yatıyorsun

Ama ben sana dokunamıyorum bile

Çünkü üzerindeki beyazlar rüyalarını süsleyen telli duvaklı beyazlar değil

Ve aramızdaki engeller artık bitmek bilmeyen uzun mesafeler de değil

Şimdi sadece iki avuç kara toprak var aramızda

Ve başucuna diktikleri mermer taşın üzerinde de yine o yazı var

‘Herşey aşk içindi’

Evet, herşey aşk içindi

Sen o esrarlı bakışlarının ardındaki masmavi dalışlarını

Daldıkça sanki şeytan üçgeninin kucağında sessiz sedasız kayboluşlarını

Ve gözlerine esir düşmüş beynimi kemirip duran soruların cevaplarını

Esrarengiz bir edayla kendinle birlikte sırra kadem bastırıp gittin ya

Düşünüyorumda yoksa bütün cevaplar bu üç anlamlı sözcüktemi saklı

‘Herşey Aşk İçindi’

Evet, herşey aşk içindi

Ben seni sevdiğim kadar hiçbir şeyi ve hiç kimseyi sevmedim

Ve tek istediğim seninle vuslata ermek olduğu halde bunu da beceremedim

Ama birgün bir kuytuda benimde cansız bedenimi buldukları zaman

Cebimden bir çift yüzük ve birde o yırtık kağıt parçası çıkacak

Üzerinde titrek ellerinle yazdığın o gizemli cümle

‘Herşey aşk içindi’

Haklısın, herşey aşk içindi

Rotterdam,25.11.2002', 'Elime tutuşturulan yırtık bir kağıt parçasının üzerinde aynen şöyle yazılıydı ‘Herşey aşk içindi’ Seni gözünü bile kırpmadan kendini bıraktı...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/hersey-ask-icindi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Gibi', 'ask-gibi-serhan-karaduman-1xg35', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yazılan tüm şiirleri

Birine adamaktandır içimdeki delil

O’na sen demeyi de seviyorum

Sevgili demeyide

Ya sana o desem

Sen ne dersin sevgili?', 'Yazılan tüm şiirleri Birine adamaktandır içimdeki delil O’na sen demeyi de seviyorum Sevgili demeyide Ya sana o desem Sen ne dersin sevgili?...', ARRAY['Türk Edebiyatı','Şiir','Serhan Karaduman']::text[], 8.5, '{"poet":"Serhan Karaduman","poet_slug":"serhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ask-gibi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Kızmayın', 'bana-kizmayin-berk-berk-itfas', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Faili meçhuldu diye anılmak istiyorum ben...

Hiç kimse bilmemeli katilimi, adı saklanmalı

Ortaya çıkmamalı hiçbir zaman...

Önce intihar sanılmalı.yazık denmeli

Ama çok geçmeden cinayet olduğu anlaşılmalı...

Bir kaç kişi salya sümük ağlamalı arkamdan

Bu en önemli noktalardan biri...

Bu arada cenaze törenime çelenk yollamayın sakın...

Bağışta bulunun bir yerlere, mesela

Failinin Meçhul Kalmasını İsteyenler Derneği...

Olabilir bu... Hem en azından banada uyar...

Çok kalabalık olmasın cenaze törenim

(tabutumu boş bırakın, beni yakın ve külleri

                                                                 savurun denize...)

Bir kaç yakın arkadaş (dost değil)   bulunsun yeter bana...

Sadece kuzenim gelsin aileden (hangisi sormayın

                                                                            o bilir kendini...)

Mezarımın yeri dar olsun...

Çok yer kaplamak istemem daha fazla bu dünyada...

On dakikadan fazla durmayın mezarımın başında, nasılsa

Önce her hafta, sonra her ay, zamanla senede bir, sonunda

Uzun aralarla  geleceksiniz... İstemiyorum bunu...

Dünyada rahat bırakmadınız beni, 

Hiç olmazsa orada huzurlu ve yalnız bırakın beni...

Failim meçhul kalsın, çıkmasın ortaya, bulunmasın...

Eğer öğrenirseniz bir gün, sakın

Bana kızmayın...

                                                                      02.12.2002', 'Faili meçhuldu diye anılmak istiyorum ben... Hiç kimse bilmemeli katilimi, adı saklanmalı Ortaya çıkmamalı hiçbir zaman... Önce intihar sanı...', ARRAY['Türk Edebiyatı','Şiir','Berk Berk']::text[], 8.5, '{"poet":"Berk Berk","poet_slug":"berk-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bana-kizmayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlar', 'yildizlar-berk-berk-tuq3t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne zaman gökyüzüne baksam

Yıldızları göremem 

Ben...

Nedendir bilmem...

Belkide herşeyi 

Karanlık görmek

İstediğimden...

Ki bir o kadar da 

Korkarım karanlıktan

Ben...', 'Ne zaman gökyüzüne baksam Yıldızları göremem  Ben... Nedendir bilmem... Belkide herşeyi  Karanlık görmek İstediğimden... Ki bir o kadar da  ...', ARRAY['Türk Edebiyatı','Şiir','Berk Berk']::text[], 8.5, '{"poet":"Berk Berk","poet_slug":"berk-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yildizlar-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Ve Sen', 'i-stanbul-ve-sen-vedat-koparan-3i6op', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uzanıp dokunacak kadar ötemdesin 

Ah le yar der duygular 

Oysa biz geceyi nasılda güne erdirirdik

Serçe çırpınışlarında sokaklar 

Sokaklar serin üşür, sokaklar gecenin koynunda 

Ben sana dokunacakken dokunamam ellerim üşür 

Gecenin kör karanlığında 

İstanbul’da bir rehin var şahan kaçaklarında 

Yüreğim sürürken gecenin üşümüşlüğünde 

tırıs adımlarla 

Hep sensin aklımda her yürek atımımda 

Uçuk mavi bir adam 

Sensizliği, sessizliği derinden duyar İstanbul’da 

Bir yürek bir yüreği nasıl taşır 

Bir kıyıdan bir kıyıya 

Geçerken Üsküdar vapuru 

İnci gibi görünür boğaz köprüsü 

Sahile dizilmiş ışık parıltıları dans eder 

Çiçekçiler bağırır 

Al bir sevgiliyi götür yüreğinde 

Çiçek olsun ellerinde 

Ben seni şuan işte böyle taşıyorum 

Ey sevgili İstanbul sevgilerimle 

Yalnızlar rıhtımında oldum 

Duygu kaçaklarımla

Koca kentte kayboldum 

Bir ben varım 

Birde bende olan senle İstanbul''da.. 

Vedat Koparan 02–12–2002', 'Uzanıp dokunacak kadar ötemdesin  Ah le yar der duygular  Oysa biz geceyi nasılda güne erdirirdik Serçe çırpınışlarında sokaklar  Sokaklar s...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/istanbul-ve-sen-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül ÜşürseTitrer Yürek Yanarsa', 'gul-usursetitrer-yurek-yanarsa-nuri-can-63je3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '”...hayat bize mutlu olma şansı vermedi sevgili.

biz kendimizden başka herkesin üzüntüsünü üzüntümüz, 

acısını acımız yaptık çünkü.

dünyanın öbür ucunda hiç tanımadığımız

bir insanın göz yaşı bile içimizi parçaladı. 

kedilere ağladık, kuşların yasını tuttuk...

yüreğimizin zayıflığı kimi zaman hayat

karşısında bizi zayıf yaptı. aslında ne güzel 

şeydir insanın insana yanması sevgili...

ne güzeldir bilmediğin birinin derdine

üzülebilmek ve çare aramak. ben bütün

hayatımda hep üzüldüm, hep yandım.

yaşamak ne güzeldir be sevgili...sevinerek, 

severek, sevilerek, düşünerek... ve o

vazgeçilmez sancılarını duyarak hayatın... “

Yılmaz Güney

Git  gide  kirletiyorlar  gökyüzünü  Anne

Umutlarıda  tüketiyorlar  hep  beraber / sevgileri de

dillerinde  en  ince  yalanlar, süslü  ve  sisli  yüzleriyle

soğuk yüreklerinde  ne  acıma ne sevgi

kimin  eli  kimin  cebinde

kimin  eli  kimin  neresinde  belli  değil

bense  öyle  acemi  ve  şaşkın

boş  kalan  ellerimi  bir  ömür

nereye  koyacağımı  bilemedim

bilemedim, hangi  yalanla  kimi  nasıl   soyacağımı

buz üstünde yürümeyi seçtim  kendi hesabıma

maske diye bir not düşürmedim yüzüme

bukalemuna çalan rengimde olmadı

tuttuğum her insanın elinde/ ellerim kirlendi

gözlerim kirlendi/ baktığım her insanın gözlerinde

yüreğimi sarktım umut kuyularına her defasında

her defasında yangın çektim su yerine, acı çektim

ne bir gün ışığı aktı içime ne de  bir yağmur damlası

rezil bir dünyanın orta yerinde 

hüzün ben oldum düşen her yaprakta

her savaşta vurulan ben oldum

 yandı  gözlerimde son ümitlerim

yıkıldı hayallerim

ıstırabın en derin okyanusuna gömüldüm

suskunum, susuzum, yaralıyım anne

gözlerim, ruhum, bedenim yorgun.

durmadan  kirletiliyor/ kanıyor  zaman /kimse  aldırmıyor

kimse  yanmıyor /sevincini  ateşe  döken  gelincik  çiçeklerine

dönüp  bakmıyor  çığlıklarına  çocukların

kapkara  bir  nehir  gibi

acı akıyor  yüzünde  yoksulların her akşam

tüm çabalarımıza ragmen, temiz tutamadık güzelliklerimizi

herşeyin kirletildiği bir dünyada

 hep vurgun kaldı bir yanımız

bir yanımız aşka acıya ayarlı

dumanlar  yürüyor  her  akşam

beton  yığınlarıyla örtülü / sevgisiz  kentler  üstüne

zifiri  karanlıklar

kimse  kimsenin  yasını  tutmuyor anne

bölüşmüyor  acısını

Sarılki

kokun  sinsin  tenime  /sevgin  işlesin  yüreğime

bu  yalancı  dünyada kimim  varki  başka  gözlerimden  öpecek

içimi  ısıtacak bu  karanlık  soğuk  kış  gecelerinde

Sarılki

serinlensin  ateşler  içindeki  alnım

yorgunum  anne

beynim  tenim  ellerim  yorgun

kendime  sürgün  yaşamaktan

sevgiye  tanımlar  aramaktan

tüm  bu  oldu  bittilere

insanın  kayıtsızlığından  yorgunum  anne

yoruldum  anne ağrılarım sızılarım  yorgun

ihanetler  yedi umudumu,  sevgimi,  düşlerimi

her  gece  yalnızlıklar  sürüyorum/ kanayan  yerlerime

ellerime  çaresizlikler  yüklüyorum

üşüyorum  bu  karanlık  gecelerde  sarıl  bana

oysa  hiç  dönmedim  sırtımı  insanın  emeğine

öpmedim  namerdin  elini/ eğilmedim  zalimin  önünde

ama  ezildim bir  çaresizin  bakışından

bir  annenın  yakarışından

bir  babanın  haykırışından

utandım  anne dünyayı  kirli  bahçesine  çevirenlerden

aç  insanların  kederinden  utandım

bombalanan şehirlerden

insanların  kayıtsızlığından tüm bu  oldu  bittilere

insanlığımdan  utandım  anne  insanlığımdan

heyhatki, 

bizi ağlatan acılar güldürüyor başkalarını

yürek yanarsa titrer anne gül üşürse

kaç insan soyundan ihanet görmüş, kaç gül dikeninden

mademki ihanet var, 

öz elleriyle boğsun gül emen çocuklarını anneler

ve şairler ihanet etsin şiirlerine

 yazmasınlar bir daha gül yüzlü  sevgililerine  şiirler

her mısrası kurşun olup saplansın yüreklerine

....ve ben

bunca  kalabalıkların ve bunca  mekanların  içinde

her defasında yarası kanayan şiirler damlarken içime

yüreğimdeki  yağmurlarla, herkesin  bildiği  bu  dünyada

adresi  olmayan  yitik mektuplar  gibi  yorgun

yavru  bir  kedi  gibi  yalnız ve sahipsiz

öyle mi? 

vayyy.

...........

ben nazlı bir yaprağım dalından düşmüş

alın beni üşüdüğüm yerden

kalbinizin üstüne tutun pul pul

vicdanınızın üstüne

aynı soydanım sizinle

yok başka bir umarım alın beni üşüdüğüm yerden

yok başka kimsem kiminle konuşsam

sizin elleriniz var soyan, evleriniz var kocaman

sokaklarda gecekondularda yatmadınız  karda kışta

bir dilim ekmeğe avuç açmadınız

utanan biz olduk yoksulluğumuzdan

utanan anam oldu, babam bacım gardaşım

ben nazlı bir yaprağım dalından düşmüş

alın beni üşüdüğüm yerden

kalbinizin üstüne tutun pul pul

vicdanınızın üstüne

aynı soydanım sizinle', '”...hayat bize mutlu olma şansı vermedi sevgili. biz kendimizden başka herkesin üzüntüsünü üzüntümüz,  acısını acımız yaptık çünkü. dünyanın...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":118,"source_url":"https://www.antoloji.com/gul-usursetitrer-yurek-yanarsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seni Ömre Bedel Sevdim', 'ben-seni-omre-bedel-sevdim-vedat-koparan-dl9af', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben Seni Ömre Bedel Sevdim

Ben seni mevsimler gibi sevdim 

Yanan bir gül değildi ellerimde 

Yanan bir gün hiç değildi 

Yanan bir ömürdü

Seven yüreğimde sevildikçe..!

Vedat.K 25-11-2002', 'Ben Seni Ömre Bedel Sevdim Ben seni mevsimler gibi sevdim  Yanan bir gül değildi ellerimde  Yanan bir gün hiç değildi  Yanan bir ömürdü Seve...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ben-seni-omre-bedel-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanal Sevişmeler', 'sanal-sevismeler-metin-yalti-dx0sl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ya uyduda hata var

Ya da biri duymuş olmalı

Bulutlar toplanmış gurupta

Fiskos eder gibi

Çok mu açıktı konuştuklarımız 

Kızarmış utançtan yüzleri', 'Ya uyduda hata var Ya da biri duymuş olmalı Bulutlar toplanmış gurupta Fiskos eder gibi Çok mu açıktı konuştuklarımız  Kızarmış utançtan yüz...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sanal-sevismeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülleri Sana Bırakıp Dikenlere Gidiyorum', 'gulleri-sana-birakip-dikenlere-gidiyorum-nuri-can-3m0bu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gülleri sana bırakıp dikenlere gidiyorum

Gidiyorum 

bütün acılarımı vurup sırtıma 

umutları bırakıp başucuna 

ıtırları, menekşeleri, kırgüllerini bırakıp 

şiirlerimi sarıp bohçama 

yüreğimin yangınına gidiyorum 

hoşca kal usulboylum, güzel gözlüm hoşca kal 

Gidiyorum 

gözyaşlarımı papatya diye saçlarına takıp 

yüreğimdeki yağmurlarla bir ırmağa akmaya gidiyorum 

içimde yeşerttiğim tüm çimenler sana kalsın 

sana kalsın baharçiğdemleri, kırgelincikleri, kırkkanatlılar 

gülleri sana bırakıp dikenlere gidiyorum 

Gidiyorum 

başımda gam, gözlerimde nem 

toplayıp önüme düşen gölgeleri

savurup acılı rüzgarlara gözyaşlarımı

 gidiyorum 

 bütün hatıraları bırakıp geride 

ve usulca çekip kapıyı ardımdan

alıp başımı  gidiyorum buralardan 

şafak sökmeden kimseler görmeden 

yağmurun yağmadığı çöllere gidiyorum 

sevgi dolu yüreğimi bir ıssızda yakmak için

Hoşça kal suyundan çimdiğim dere 

kana kana içtiğim pınar 

say ki, hiç yaşamadım bu yerlerde 

nazlı çiçeklerini okşamadım baharın 

bozguna uğramış bir bostanın hüznüyle 

bir yaprağın ürpertisine yazıp ömrümü 

çekip gidiyorum buralardan 

Çekip gidiyorum bir bilinmeze doğru 

hem yol, hem yolcu olmaya 

acılarımla başbaşa kalmaya 

bütün yıldızları takıp kanatlarıma 

rüzgarların uğultusunda kaybolmaya gidiyorum 

Yüreğimin sızılarında damıttığım her şiiri bin kez öperek 

ve sökerek sevgiden yana ne varsa göğsümde 

gecelerin zifiri saçlarında çıkıp yola 

dağlı bir ırmak gibi çarpa çarpa kıyılara

içimdeki yaraları kanatmaya 

bir ceylanın gözlerinde ağlamaya gidiyorum 

Bütün borçlarımı ödedim alacaklarımı erteledim 

artık ne diyecek bir sözüm kaldı sevdiklerime 

ne okuyacak bir şiirim 

gözlerimin içinde iki damla gözyaşı gibi 

bakmadan ardımdaki uçurumlara 

alıp götürüyorum yüreğimdekileride 

hoşca kal usulboylum, güzel gözlüm hoşca kal', 'Gülleri sana bırakıp dikenlere gidiyorum Gidiyorum  bütün acılarımı vurup sırtıma  umutları bırakıp başucuna  ıtırları, menekşeleri, kırgüll...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/gulleri-sana-birakip-dikenlere-gidiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavuşmak', 'kavusmak-erdal-usluer-9s3vq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dört ay kıştan sonra

Yine kavuştu gözler.

Sessiz sakin bakıştılar

yıldızlar gibi.

Işık saçıyordu çevresine

İki çift mutlu göz

güneş gibi.

Kalpler her zamankinden 

daha hızlı atarken

Seviyoruz diyorlardı

Kumrular gibi

ve

Eller titredi, sesler düğümlendi, 

Dizlerdeki bağlar çözüldü.

Uçtular gökyüzüne

Ruhlar gibi.', 'Dört ay kıştan sonra Yine kavuştu gözler. Sessiz sakin bakıştılar yıldızlar gibi. Işık saçıyordu çevresine İki çift mutlu göz güneş gibi. Ka...', ARRAY['Türk Edebiyatı','Şiir','Erdal Usluer']::text[], 8.5, '{"poet":"Erdal Usluer","poet_slug":"erdal-usluer","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kavusmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öp cehennem olayım', 'op-cehennem-olayim-sukru-yildiz-o38ju', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Suyun suyla seviştiği gecedeyim

Başım hafif ağrısı var

Koynumda sen varsın

Aklımda sen varsın

Yolumda sen varsın

Şimdi yapraklarını döküyor

Sonbahar geldi

Bilinen bir alışkanlık gibi

Canım acıyor

Seni sevdiğim gibi

Nerede o şehri yakan ateş

Nerede kaldı sessizliğin tadını bilen gülüşün

Yapraklar neden sarı

Yeşil mi güzeldi? 

Sarı mı? 

Kim benden önce yeşildi

Kim benden sonra sarı

Rengini kaybetmiş mekanların ürkek kuşu

Kanadında hangi renk var

Iraktan mı geldin, 

Gökkuşağının altından mı geçtin

Koynumdaki yara senin mi? 

Gurbetteki ölüm benim mi? 

Suç senin midir? 

Benim midir? 

Gel günaha girelim

Koynunda bir Ferhat, bir Mecnun olayım

Kara ordularla

Geçmiş zaman cadılarıyla harbe durayım

Senle olayım

Öyle öleyim

Tanrılar kıskansın seni

Ben seni kıskanırım kendimden

Öp cehennem olayım

Ateş olup yanayım

Yanıp da, sende sen olayım

Bırak artık beni

Edepsizliğin koynunda yüzeyim

Nerde isem orada durayım

Ölüm şeridinden geçip

Gözlerinde tanrı olayım

Öp hadi beni

Cehennem olayım, yanayım', 'Suyun suyla seviştiği gecedeyim Başım hafif ağrısı var Koynumda sen varsın Aklımda sen varsın Yolumda sen varsın Şimdi yapraklarını döküyor ...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Yıldız']::text[], 8.5, '{"poet":"Şükrü Yıldız","poet_slug":"sukru-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/op-cehennem-olayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölürüm, öp beni..', 'olurum-op-beni-sukru-yildiz-lc4ga', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Merhabasız geçen günlerimin etrafında dönüyor dünya

Ay beni unuttu

Yıldızlar yalnızlık şarkıları söylüyor

İçimdeki kor şeytanın ateşinde pişiyor

Direncim üstünden muhteşem silahlarıyla, ordular geçiyor....

Sahne devam ediyor; 

Karşıdaki evlerin kapıları, kapalı bu gün

Dumanı tütmüyor artık aşkın

Ortaçağ cadılarının bereket zamanındayım

Öylesine doğmuşum

Yanlış doğmuşum

....Bakasım geliyor

Göresim sevesim geliyor

Bakamıyorum

Sevemiyorum

Ölesim geliyor....

Karnım açıkmış gibi, açıkmışım

Dokunmuşum umuduma

Sen dokunmaktasın ellerindeki nasıra

Anlamaktasın yüreğinin durgunluğunu

Dinlemektesin eski zaman şarkıları arasındaki, 

tütünsüz çalgıları, çalgıcıları....

Bense dumanlı bir geceden geçmekteyim....

Eski zamandan kalmayım bilirsin

Çevremi eli curalı aşıklar sarmış

Uzak şehirlerin birinden bir destan anlatır

Beni anlatır aslında, 

Benden geçer seni anlatır

Kökleri yerinden kopmuş bizi anlatır

Hep hüzün çöker

Hep sancılar yüreğimi

Ben seni, sen seni dinlemektesin

Ben, beni dinleyeceğim günleri beklemekteyim...

....Bakasım geliyor

Göresim sevesim geliyor

Bakamıyorum

Sevemiyorum

Ölesim geliyor....

Mecnun, Leylasından kopmuş, veliye benziyor

Ferhat, dağları delmiş, deliye benziyor

Romeo, Juliyeti görmüş ölüye benziyor 

Senin bana bakan gözlerin gülüm, aşka benziyor

Ölürüm, öp beni.....

5 Ekim 02', 'Merhabasız geçen günlerimin etrafında dönüyor dünya Ay beni unuttu Yıldızlar yalnızlık şarkıları söylüyor İçimdeki kor şeytanın ateşinde piş...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Yıldız']::text[], 8.5, '{"poet":"Şükrü Yıldız","poet_slug":"sukru-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/olurum-op-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgem', 'golgem-i-brahim-yavuz-bildik-aphar', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ya bir günbatımında

ya da

bir sağnakla gideceğim

gölgem sana düşmeyecek

1 mayıs 2001', 'ya bir günbatımında ya da bir sağnakla gideceğim gölgem sana düşmeyecek 1 mayıs 2001...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yavuz Bildik']::text[], 8.5, '{"poet":"İbrahim Yavuz Bildik","poet_slug":"i-brahim-yavuz-bildik","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/golgem-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızgın Fırtınalar', 'kizgin-firtinalar-erdem-demirkol-2mo65', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kızgın frtınalar kopuyor başımda, 

İri taneler düşüyor her yanıma.

Yolcuyum iki kapı arasında.

Nedendir çekilen bunca çile? 

Yaşamakmış, dünyada çekilmez çile.

Zaman, bir yol gaibe uzanan.

Zaman, saklananlara şahit olan.

Zamansız acıların ilacı zaman.

Hayattaki endişe yaşamakmış.

Hayaller mi bizi hayata bağlayan? 

Sevdadan mı gönlümdeki mutluluk? 

Bu sevda yaşamak mı yoksa? 

Her köşe başında bir sorumluluk.

Günahların hesabı korkulardan sorulsa.

Ah! Kızgın fırtınalar kopuyor başımda.

Kızgın fırtınalar kopuyor başımda.

Erimez karlar düştü saçlarıma.

Kalmaz dünya, ölmek var şükür.

Ne zevk hissesi, ne mutluluk hissi.

Hava bedava, buna da şükür.

(13.10.2002-Hadımköy/İST.)', 'Kızgın frtınalar kopuyor başımda,  İri taneler düşüyor her yanıma. Yolcuyum iki kapı arasında. Nedendir çekilen bunca çile?  Yaşamakmış, dün...', ARRAY['Türk Edebiyatı','Şiir','Erdem Demirkol']::text[], 8.5, '{"poet":"Erdem Demirkol","poet_slug":"erdem-demirkol","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kizgin-firtinalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avucumda Hayaller', 'avucumda-hayaller-erdem-demirkol-gbqjy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Büyük hayalleri vardır insanların, 

Ağırlığında ezildikleri düşünceler.

Bir elimde dünya, bir elimde hayaller.

Terazi misali değişir düşünceler.

Aklımda hayalin ve hayaller.

Fakat hiç olmayacaksın sen gerçekten.

Hangisi gerçekleşir ki hayallerden? 

Yine de usanmaz insan hayal etmekten.

Haram ettiler güneşi bize.

Sürgün istekler, avucumda hayaller.

Mülteciyim, yine kaçak saatler.

Gidiyorum, elveda güzel gelecekler.

Gözümde yaşlar, avucumda hayaller.

(17.10.2002-Hadımköy/İST.)', 'Büyük hayalleri vardır insanların,  Ağırlığında ezildikleri düşünceler. Bir elimde dünya, bir elimde hayaller. Terazi misali değişir düşünce...', ARRAY['Türk Edebiyatı','Şiir','Erdem Demirkol']::text[], 8.5, '{"poet":"Erdem Demirkol","poet_slug":"erdem-demirkol","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/avucumda-hayaller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağla', 'agla-cahit-i-pekoglu-aj0ou', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ağla yüreğim ağla

sevdiğinde terk etmiş seni.

Ağla gözlerim ağla

bakacak neyin kaldıki hayatta.

Ağla ellerim ağla

tutunacak bir canınmı kaldı dünyada...

Ağla kaderim ağla

aşka doyamadın ruhunda.

Ağla burnum ağla

koklayacak gülün yok artık dalında.

Ağla dudaklarım ağla

şerbetini içtiğin dil''de yok artık dünyanda...

Ağla bedenim ağla

titreyenle, titreyemiyorsun bir yatakta.

Ağla göğsüm ağla

başını koyan gülün yok şimdi koynunda.

Ağla kaderim ağla

aşka doyamadın ruhunda...', 'Ağla yüreğim ağla sevdiğinde terk etmiş seni. Ağla gözlerim ağla bakacak neyin kaldıki hayatta. Ağla ellerim ağla tutunacak bir canınmı kald...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/agla-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şey Senin Elinde', 'her-sey-senin-elinde-gursel-colak-3pdos', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne yapmam gerekir? 

Seni mutlu edebilmem için

Benim ol desen, olamam! 

Benimle kal desen, kalamam! 

Geri dönme desen, yapamam! 

O zaman beni unut desen, unutamam! 

Ne olur, isteme benden yapamıyacağım şeyleri.

İste mutluluk, vereyim sana.

Canımı istesen al senin olsun derim

Seni mutlu edecekse hemen veririm.

Tanıdın beni bir kere

Unut unutabilirsen

Anma adımı bir daha

Eğer anmayabilirsen

Biliyorsun yapamazsın

Aynı benim yapamadığım gibi.

Girmişiz sonu olmayan

Çıkmaz bir sokağa

Kalplerdeki sevgidir adı sokağın

Girmişiz bu sokağa bir kere

Gelde geri dön dönebilirsen.

Sökte at olan sevgini atabilirsen

Ama benden söküp atmamı isteme

Sevmek, Sevilmek, Unutmak ve Unutulmamak 

Her Şey Senin Elinde

Gelde yap yapabilirsen!', 'Ne yapmam gerekir?  Seni mutlu edebilmem için Benim ol desen, olamam!  Benimle kal desen, kalamam!  Geri dönme desen, yapamam!  O zaman beni...', ARRAY['Türk Edebiyatı','Şiir','Gürsel Çolak']::text[], 8.5, '{"poet":"Gürsel Çolak","poet_slug":"gursel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/her-sey-senin-elinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seni Seviyorum', 'ben-seni-seviyorum-cem-veysel-gul-61izn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hakkim degil biliyorum ama, 

Kimi zaman sorguluyorum yinede.

Dünyayi.sevgiyi ve zamani.

Cogu zaman dünya yalan diyorum, 

Ama gercek ve yürek yakan acilar cektiriyor.

Sevgi neden kalici mutluluklara yetmiyor

Aciya, mutluluga, huzne ve gözyasina, 

Yani seninle olan herseye sevdaliyim 

Neden sevenler sevda denizinde mutlulukla yürüyemiyor? 

Engel yasaklarmi, zamanmi yoksa sevgi düsmanlarimi. 

Acimasizlarin icinde en acimasizi zaman galiba, 

Yanliz kendi istedigi gibi gün, ay, yil olarak gecen 

Sensiz gecen ve aci veren zaman. 

Fakat sadece bedenensensizim bunuda unutma. 

Bu sevgi yasanmali yasakta olsa 

Yasanabilecegi en son ana kadar yasanmali. 

Insan hayatinda bir cok kez sever, 

Ama hayatinda bir kere cok sever. 

O bir kereyi sende bulduysam yasamaliyim seni. 

Ben seni cok seviyorum 

Bugün ilk defa gercek bakiyorum sana 

Seninle olan herseye sevdaliyim iste. 

Nasilki ucsuz bucaksiz cöller seraba tutkunsa 

Bende o kadar tutkunum sana. 

Ve su an bir serap gibi cöllerinde olmak isterim, 

Sevgimi, özlemimi ve hasretimi cöllerinde gör! 

Ama gösterme kimselere ki kiyamet kopacak demesinler. 

Cünkü hic bir serap sevgim ve özlemimim gibi 

Gercek ve mükemmel olmadi. 

Ben senin cölünde serap 

Sen benim serabimda tutkumsun. 

Tüm benligimle ve hücrelerimle 

Seviyorum seni ey sevgili... 

07.12.2002 /saat: 12: 30 

Schwäbisch Gmünd/Almanya 

Cem Veysel Gül', 'Hakkim degil biliyorum ama,  Kimi zaman sorguluyorum yinede. Dünyayi.sevgiyi ve zamani. Cogu zaman dünya yalan diyorum,  Ama gercek ve yürek...', ARRAY['Türk Edebiyatı','Şiir','Cem Veysel Gül']::text[], 8.5, '{"poet":"Cem Veysel Gül","poet_slug":"cem-veysel-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ben-seni-seviyorum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hicran Benimdi', 'hicran-benimdi-nami-kemal-3ofot', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hicran benimdi yad ellerin oldu.

gözleri siyahtı aynı kalbi gibi

seni seviyorum dedi

ama beni bıraktı gitti...', 'hicran benimdi yad ellerin oldu. gözleri siyahtı aynı kalbi gibi seni seviyorum dedi ama beni bıraktı gitti......', ARRAY['Türk Edebiyatı','Şiir','Namı Kemal']::text[], 8.5, '{"poet":"Namı Kemal","poet_slug":"nami-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hicran-benimdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Hatırası', 'ayrilik-hatirasi-i-smail-cem-cgioa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gecenin siyah yağmuru

Sarmıştı dörtyanımızı

Biraz ağlamaklı

''''Ayrılmalıyız'''' dedin.

Ayrılmalıyız kızıl nefer! 

Ve ben neden diyemeden

Gökyüzü çaktı flaşını

Gece, yapraksız ağaç ve ıslak ten

İşte ayrılığımızın fotoğrafı....', 'Gecenin siyah yağmuru Sarmıştı dörtyanımızı Biraz ağlamaklı ''''Ayrılmalıyız'''' dedin. Ayrılmalıyız kızıl nefer!  Ve ben neden diyemeden Gökyüz...', ARRAY['Türk Edebiyatı','Şiir','İsmail Cem']::text[], 8.5, '{"poet":"İsmail Cem","poet_slug":"i-smail-cem","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ayrilik-hatirasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarınlar', 'yarinlar-ahmet-senkabak-xrh3m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'zamanı eritip dudaklarına sur

yolları kitap aralarına bırak....kurusun

kırgınlıgımı benim içime göm

bekle...! 

yarınlar gelince

gerceğin zembili düşte boşanacak

.....

yuzun gözlerimde yanarmı?', 'zamanı eritip dudaklarına sur yolları kitap aralarına bırak....kurusun kırgınlıgımı benim içime göm bekle...!  yarınlar gelince gerceğin zem...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şenkabak']::text[], 8.5, '{"poet":"Ahmet Şenkabak","poet_slug":"ahmet-senkabak","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yarinlar-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esirgedin Benden', 'esirgedin-benden-necati-cumali-ggwnn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüzüne bakmaya doyamazdım

Durmadan dolanırdım gözlerinin ardında

Ellerini durmadan tutmak isterdim

Ürkerdin kuşkuların kalelerinde tutsak

Esirgedin benden, hep esirgedin...

Saçlarının samanyolları harman yerleri

Uzanmak isterdim gözlerim açık yastığında

Göğüslerinin rüzgarlı serin tepeleri

Koşmak isterdim solumak terli terli

Donardın kollarımda aşktan korkarak

Atlarım vardı güneşten yeleleri

Dörtnala sürdüm kapına çektim

İndirdim yerle bir ettim kaleleri

Yığdım önüne nem varsa kucak kucak

Esirgedin benden, hep esirgedin...

Dünyayı yanyana seninle dolaşmak

Denizleri doluyelken aşmak isterdim

Çizmek karalamak yeniden yaşamak dizmek

Kocaman bir sözlükte kelimeleri tek tek

Esirgedin benden, hep esirgedin...

Belleğimde çamlıklar dizilir ardarda

Bir müzenin geçitleri döner dönerim

Gördüğüm hep gençlik güzellik günlerin

Aşkımızdan tüm esirgediklerin için

Bir duruşun var sanırım ağladın ağlayacak.', 'Yüzüne bakmaya doyamazdım Durmadan dolanırdım gözlerinin ardında Ellerini durmadan tutmak isterdim Ürkerdin kuşkuların kalelerinde tutsak Es...', ARRAY['Türk Edebiyatı','Şiir','Necati Cumalı']::text[], 8.5, '{"poet":"Necati Cumalı","poet_slug":"necati-cumali","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/esirgedin-benden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dil Senin Söz Senin', 'dil-senin-soz-senin-sabri-gurbuz-tcfsa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tutarız şemsin şavkını sine-i leylinde bademin

Bu cemal senin; elma senin, kiraz senin, badem senin

Çekilse temaşadan ol mehtap ne gam, mah cemal senin

Bu leyl senin, şevk senin, mehpare senin, nurpare senin

Nice memleket sema nedir bilmez, gurbetinde senin

Bu yol senin, kervan senin, vuslat senin, garb-ı şark senin

Sabri der ya; sen kamersin, gönül med-cezirinde senin

Bu gönül senin, dil senin, söz senin..Umrunda mı senin? 

                                  5-12-2002', 'Tutarız şemsin şavkını sine-i leylinde bademin Bu cemal senin; elma senin, kiraz senin, badem senin Çekilse temaşadan ol mehtap ne gam, mah ...', ARRAY['Türk Edebiyatı','Şiir','Sabri Gürbüz']::text[], 8.5, '{"poet":"Sabri Gürbüz","poet_slug":"sabri-gurbuz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dil-senin-soz-senin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diz Kırdım Karşında', 'diz-kirdim-karsinda-sabri-gurbuz-omvis', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çökmüşüm seneler sırtımda yük

Yalvaran sesime şaşarım şimdi

Artık aynaların yemini büyük

Diz kırdım karşında son kez şimdi

Bilki ümitle beslenir tehir

Beklemeye gücüm yetmeyecektir

Gençliğin bendeki ömrü ahir

Diz kırdım karşında son kez şimdi

                 3-12-2002', 'Çökmüşüm seneler sırtımda yük Yalvaran sesime şaşarım şimdi Artık aynaların yemini büyük Diz kırdım karşında son kez şimdi Bilki ümitle besl...', ARRAY['Türk Edebiyatı','Şiir','Sabri Gürbüz']::text[], 8.5, '{"poet":"Sabri Gürbüz","poet_slug":"sabri-gurbuz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/diz-kirdim-karsinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatımın Gülpembesi', 'hayatimin-gulpembesi-sabri-gurbuz-sjpye', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayatımın gülpembesi

Menekşemde kelebeksin

Yeter ayrıya gezdiğin

Beni ne çok bekletirsin

Al yaramın merhemisin

Fikrin ince semeresi

Bilmem neden naz edersin

Kalbimi mecnun edensin

Yüzün dört mevsim bahardır

Gönlüme çiçek açtırır

Ümitlerim bembeyazdır

Hayalin beni şaşırtır

Bekledim de bunca sene

Hicran dolandı ateşe

Akkor ki bende göresin

Aşk rahat vermedi kalbe

              2-12-2002', 'Hayatımın gülpembesi Menekşemde kelebeksin Yeter ayrıya gezdiğin Beni ne çok bekletirsin Al yaramın merhemisin Fikrin ince semeresi Bilmem n...', ARRAY['Türk Edebiyatı','Şiir','Sabri Gürbüz']::text[], 8.5, '{"poet":"Sabri Gürbüz","poet_slug":"sabri-gurbuz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hayatimin-gulpembesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Perçem', 'percem-sabri-gurbuz-0kqck', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gece siyahı perçem

Yüzün iki parça gün

An olur perçem peçe gibi

An olur perçem pençe gibi

Örterken aydınlığını peçe

Parçalar pençe yüreğimi

                    24-11-2002', 'Gece siyahı perçem Yüzün iki parça gün An olur perçem peçe gibi An olur perçem pençe gibi Örterken aydınlığını peçe Parçalar pençe yüreğimi ...', ARRAY['Türk Edebiyatı','Şiir','Sabri Gürbüz']::text[], 8.5, '{"poet":"Sabri Gürbüz","poet_slug":"sabri-gurbuz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/percem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Açığa Vurdu', 'yagmur-aciga-vurdu-sabri-gurbuz-gnfvk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yağmur açığa vurdu

Yüzüm kire doymuştu

Ve bir maskeydi

Her zaman sığınağım

Kimliğim mi oydu

Yoksa o mu bendim

İşte yağmur açığa vurdu

Orda

Aynada bir yabancı

  

               17-11-2002', 'Yağmur açığa vurdu Yüzüm kire doymuştu Ve bir maskeydi Her zaman sığınağım Kimliğim mi oydu Yoksa o mu bendim İşte yağmur açığa vurdu Orda A...', ARRAY['Türk Edebiyatı','Şiir','Sabri Gürbüz']::text[], 8.5, '{"poet":"Sabri Gürbüz","poet_slug":"sabri-gurbuz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yagmur-aciga-vurdu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehrin Uzağında', 'sehrin-uzaginda-sabri-gurbuz-5z4o4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir yalıçapkını süzülür

Hiçde havamda değilim

Çalılar bacağıma sürünür

Bir keçiyolunun izindeyim

Mevsimi yere düşürmüşüm

Rüzgar kışa dönecek gibi

Çiçeklerin açmasını umursamaz

Yanağına kar düşürme emeli

Dizde dermanım direnmez

Hevesimi avlar dönerim

Karanlık bir kenarda durmaz

Medeniyete muhtaç dönerim

                  16-11-2002', 'Bir yalıçapkını süzülür Hiçde havamda değilim Çalılar bacağıma sürünür Bir keçiyolunun izindeyim Mevsimi yere düşürmüşüm Rüzgar kışa dönecek...', ARRAY['Türk Edebiyatı','Şiir','Sabri Gürbüz']::text[], 8.5, '{"poet":"Sabri Gürbüz","poet_slug":"sabri-gurbuz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sehrin-uzaginda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Özleyen Yalnızlık', 'seni-ozleyen-yalnizlik-sabri-gurbuz-xgdlt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Belki çile kırbacı

Öfkemin şaklayan sesi

Öyle keskinki taşlar

Suyu sekerek geçme emi

Sakin bombaya kanma

İçime birikmiş bu koma

Aklım çaresiz tekrara

Yılan kendi kuyruğunda

Yalnızım bu ömrün kucağında

Etimde diş izleri

Bana susmayı öğret

Çiçek, bulut, deniz ol gel



                 19-11-2002', 'Belki çile kırbacı Öfkemin şaklayan sesi Öyle keskinki taşlar Suyu sekerek geçme emi Sakin bombaya kanma İçime birikmiş bu koma Aklım çaresi...', ARRAY['Türk Edebiyatı','Şiir','Sabri Gürbüz']::text[], 8.5, '{"poet":"Sabri Gürbüz","poet_slug":"sabri-gurbuz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-ozleyen-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nimete Açlık Gerek', 'nimete-aclik-gerek-sabri-gurbuz-tiqhg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yufkadan perdeli yürek

Işık için yangına kürek

Ruh lal-ü ebkem bir direk

Nimete açlık gerek

                 5-12-2002', 'Yufkadan perdeli yürek Işık için yangına kürek Ruh lal-ü ebkem bir direk Nimete açlık gerek                  5-12-2002...', ARRAY['Türk Edebiyatı','Şiir','Sabri Gürbüz']::text[], 8.5, '{"poet":"Sabri Gürbüz","poet_slug":"sabri-gurbuz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/nimete-aclik-gerek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karamsar Coşku', 'karamsar-cosku-sabri-gurbuz-2nffq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mağlubum bir parça ümidim yok

Gül yok, gülşen yok, bahar yok

Gün çamurda söndü

Filiz vereceği yok

Yadım anılmaz dost dilinde

Düşman bi-vefa, cana kastı yok

Hal dile gelirde yangın içinde

Bir selamlık teselli bile yok

                     18-11-2002', 'Mağlubum bir parça ümidim yok Gül yok, gülşen yok, bahar yok Gün çamurda söndü Filiz vereceği yok Yadım anılmaz dost dilinde Düşman bi-vefa,...', ARRAY['Türk Edebiyatı','Şiir','Sabri Gürbüz']::text[], 8.5, '{"poet":"Sabri Gürbüz","poet_slug":"sabri-gurbuz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/karamsar-cosku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hançerin Ucunda', 'hancerin-ucunda-sabri-gurbuz-dvdwo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düşer geceme bir tutku gibi

Gecelerki huzur mahzenim

Akkor ocak oldular şimdi

Uykularım parampaça

Bir işkence yada tedrisat

Bu ağır ağır işleyen kanaviçe

Ruhumla körebe oynayacak

Bir hançerin ucunda

Yanıma birikir mazi

Arada unutuş perdesi

Belki ciğer köz olacak

Ama bilemeyecek sebebini

Boyum düşer toprağa

Ne yere ne göğe çeviremem yüzümü

Şimşek ve fidan elele verip

Hapsedecekler hüznümü

                      16-11-2002', 'Düşer geceme bir tutku gibi Gecelerki huzur mahzenim Akkor ocak oldular şimdi Uykularım parampaça Bir işkence yada tedrisat Bu ağır ağır işl...', ARRAY['Türk Edebiyatı','Şiir','Sabri Gürbüz']::text[], 8.5, '{"poet":"Sabri Gürbüz","poet_slug":"sabri-gurbuz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hancerin-ucunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duvardan Süzülen', 'duvardan-suzulen-sabri-gurbuz-jvsx3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Duvardan süzülen

Bir hayal hevesi

Başlamadan sönen

Kıvılcım tanesi

Duvardan süzülen

Ardını merak ateşi

Azmini taşıyamayan

Hantal ve yalnız

Duvardan süzülen

Hatıratın leşi

Dört duvardan sadece biri

Loş gecede seçilebilen

Duvardan süzülen

Açlığın nefesi

Gücü aşmaya yetmedi

Bıraktı kendini

Duvardan süzülen

Bir mezar taşı

Kırpılmış ve yazısız

Yaşadığından kalan

                     16-11-2002', 'Duvardan süzülen Bir hayal hevesi Başlamadan sönen Kıvılcım tanesi Duvardan süzülen Ardını merak ateşi Azmini taşıyamayan Hantal ve yalnız D...', ARRAY['Türk Edebiyatı','Şiir','Sabri Gürbüz']::text[], 8.5, '{"poet":"Sabri Gürbüz","poet_slug":"sabri-gurbuz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/duvardan-suzulen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilenci', 'dilenci-sabri-gurbuz-kb3jr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kırağı ve çiğ

Seherin çocuğu

Ben buz kesmiş

Titreyen harabe

Azim ve ısrar

Ümidin çocuğu

Ben testembel

İnatçı ucube

Tatlı ve tuzlu

Lokmanın çocuğu

Ben bir deri bir kemik

Açlık çukuru

Yardım ve ikram

Merhametin çocuğu

Ben yalvarmadayım

Dilenci buyruğu

             13-11-2002', 'Kırağı ve çiğ Seherin çocuğu Ben buz kesmiş Titreyen harabe Azim ve ısrar Ümidin çocuğu Ben testembel İnatçı ucube Tatlı ve tuzlu Lokmanın ç...', ARRAY['Türk Edebiyatı','Şiir','Sabri Gürbüz']::text[], 8.5, '{"poet":"Sabri Gürbüz","poet_slug":"sabri-gurbuz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dilenci-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beynim Kırıştı Yüzüme', 'beynim-kiristi-yuzume-sabri-gurbuz-9v9t6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beynim kırıştı yüzüme

Rakam bir kontür daha attı

Ara sıra hatırlarım

Geri sayımın durmadığını

Yoksa uykumda hep küçüğüm.

Bir sığınak gibi rüyalar

Uyanmak ölümün diğer adı

                    14-11-2002', 'Beynim kırıştı yüzüme Rakam bir kontür daha attı Ara sıra hatırlarım Geri sayımın durmadığını Yoksa uykumda hep küçüğüm. Bir sığınak gibi rü...', ARRAY['Türk Edebiyatı','Şiir','Sabri Gürbüz']::text[], 8.5, '{"poet":"Sabri Gürbüz","poet_slug":"sabri-gurbuz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/beynim-kiristi-yuzume-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zürafa', 'zurafa-kucuk-i-skender-eowwv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'birhan keskin''e..

Telaşlı bir kış yağmuru gibi

içim vıcık vıcık serçe..

zannediyorum sadece! 

Bir dahaki sefere ölü doğarım..

annem üç gün ağlar..

kendi kırığımda kemikleşirim..

indirilen şalter misali, kapanır gözlerim', 'birhan keskin''e.. Telaşlı bir kış yağmuru gibi içim vıcık vıcık serçe.. zannediyorum sadece!  Bir dahaki sefere ölü doğarım.. annem üç gün a...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/zurafa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zından Güncesi', 'zindan-guncesi-kucuk-i-skender-zofwo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tahtına çık kalbim! 

Orada sen mutlusun! 

Köpürmüş ağzıyla gece

Çatallanmış körpe sesiyle gece

indi inecek

indi inecek şimdi surlara ve zalim kalbim gerçeğe! 

Damarlarım da kanasın

Damarlarım da karışsın taşıdığı kana ve kanlı aynaya, 

canlı cinlere cansız peri kanadı takacaksın

eyleme, portakal kabuklarına ve kanlı aynaya baka baka! 

duvar diplerine biriken toz gibi

ömür kırıntıları birikmiş asaletine! 

giden trendesin, gelen trendesin veremli, tifolu, aids''li

kah cellatsın urganı gözyaşlarınla yağlayan

kah şarampolsün

aşkların sevgililere kapalı gizli görüşmelerinde, 

buhardasın, kalıptasın, çatlasın kafatasın! 

dağılsın artık, güzellikler içre itinalı sözüm

dışarda istanbul var kalbim! 

orada sen, en incelikli ölüsün!', 'Tahtına çık kalbim!  Orada sen mutlusun!  Köpürmüş ağzıyla gece Çatallanmış körpe sesiyle gece indi inecek indi inecek şimdi surlara ve zali...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/zindan-guncesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Velayet', 'velayet-kucuk-i-skender-0mjso', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öyle bir orman ki bazen hiç ağaç yok

şeffaf sincaplar tırmanıyor ceviz gözlerine

iki dudağı arasında çocukluğu soğuk kelepçe

Ben ki bir zaman önce epey yaşlanmışım

sevdaya sadrazam kellesi dayanmıyor

akdeniz''e karışıyorum kah osmanlı kah elen

bir çocuk, bizim kim olduğumuzu soruyor Allah''a birdenbire', 'Öyle bir orman ki bazen hiç ağaç yok şeffaf sincaplar tırmanıyor ceviz gözlerine iki dudağı arasında çocukluğu soğuk kelepçe Ben ki bir zama...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/velayet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümit', 'umit-kucuk-i-skender-nvwkl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözbebeklerinden şahlanan kayışları

gererek arkaya doğru apansız

bir tanımsızlık hissiyle

Bakışlarından ölümsüzlük dersi alan

tanrıların sofrasında nemli bir tuzluk

gibi tıkalıyken kalbim

parmağımdan çıkartamadığım bir yüzüksün sen', 'Gözbebeklerinden şahlanan kayışları gererek arkaya doğru apansız bir tanımsızlık hissiyle Bakışlarından ölümsüzlük dersi alan tanrıların sof...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/umit-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arabesk', 'arabesk-kucuk-i-skender-gbojl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'adımı ilk söylediğin gün 

kan geldi kulaklarımdan o gece 

aceleyle çıkıp evden 

seni aradım saatlerce 

bulsam vuracaktım 

sen ölünce dudaklarından öpecektim, 

mikrop kapmasın diye 

tentürdiyot sürecektim ağzıma 

buna bütün eczaneler gülecekti 

allah belamı versin 

seviyorum işte ne yapayım 

kavuşmak yalnızca varsayım, zayıf ihtimal 

özlem hararetli bir esin, kırık bir hayal 

ama zulmeden, kahreden o mavi sesin 

''acı çekeceksin, yok olacaksın'' diyor hâlâ 

ve isyan ediyorum allaha 

olmalısın, diye haykırıyorum 

evet, evet, ordasın 

hatta bir cübben 

cübbenin de kürklü yakaları var! 

ve ben, ölünce yapışacağım o yakalara 

yanıt ver, diye bağıracağım, yanıt ver 

neden neden neden neden neden neden 

beni bütün şeytanlar alkışlayacak 

seni ilk gördüğüm gün 

bir martı oydu iki gözümü de', 'adımı ilk söylediğin gün  kan geldi kulaklarımdan o gece  aceleyle çıkıp evden  seni aradım saatlerce  bulsam vuracaktım  sen ölünce dudakla...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/arabesk-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bodrum', 'bodrum-kucuk-i-skender-d088b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kim nereye kadar yabancıdır ki

elinde

tek sıkımlık tabancasıyla

Ve bir kent hayvanı edasıyla

kim nereye kadar yaşar ki

kendi ipliklerine inmişken mutant çocuklar

iki bahar arasında tutulmuş bir dilektir yaz', 'Kim nereye kadar yabancıdır ki elinde tek sıkımlık tabancasıyla Ve bir kent hayvanı edasıyla kim nereye kadar yaşar ki kendi ipliklerine inm...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bodrum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deklere', 'deklere-kucuk-i-skender-f1bx4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yatırmış akarsu yatağına

bir erkek su örümceğini öpüyor zorla

mutlu bir erkek kurbağa

Sazların gözbebeklerindeki akşamüstü mahmurluğu

dolduruyor günlüğünü yalnız dolaşan

hüzünlü lezbiyen kuğuların

gece olunca, grup sekse davetli bütün bir orman', 'Yatırmış akarsu yatağına bir erkek su örümceğini öpüyor zorla mutlu bir erkek kurbağa Sazların gözbebeklerindeki akşamüstü mahmurluğu doldur...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/deklere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dördüncü İblis', 'dorduncu-i-blis-kucuk-i-skender-3ty2h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Açıp baktım o mezara, yaradan kabuğunu

sıyırır gibi; gözleri: katılaşmış cerahat, çö-

zülüp eridi ilk sunuşumda daha; takip edilmiş

kemiklerde kırılmış bir ağzın trafik kazası, 

tutup eteğinden fırtınanın, homurdanarak sa-

raydan kaçan.

	Buzunllardan beri kapanmadı onun uçurumu, 

örtsem de üzerini kavlarla, bıraktıklarında o

artık derileri yatağa, nehrin dönüp dolaşıp

kendi kaynağına kavuştuğu yere, balıkların tek

sıra karaya çıktıkları anda.

	Ah kimya ah kimya. nasıl zor ayrılırsa

oksijen hidrojenden suda, ya da, nasıl imkan-

sızsa alüminyumun birleşmesi kobaltla; hatır-

la beni sen ey ölümlü nympha! tutup eteğinden

bir içakıntının, homurdanarak denizlerden ka-

çan.

	Randevusuna gelmeyen eş

nuhun gemisindeki.

		mülayim tayfuna peşkeş

çeken, ruhuma girişteki

		mıknatıslı seki; ay oyalar

çocuklar ev kozalarında büyürken, 

rüyalarımla yokluğun

boşlukta bir liken,', 'Açıp baktım o mezara, yaradan kabuğunu sıyırır gibi; gözleri: katılaşmış cerahat, çö- zülüp eridi ilk sunuşumda daha; takip edilmiş kemikler...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dorduncu-iblis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evarkadaşı', 'evarkadasi-kucuk-i-skender-l21w8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ölü kuşlara attığın yem

suladığın kırık dal

hatırlayamadığın telefon numarası

Nedendir bilmem

zamanın keskin yüzünde vücut bulan o ihmal

o yabancılık merakı, o ihanet ihtirası

ağladıkça temizlenip parladılar mutfakta seni bekleyen bulaşıklar', 'Ölü kuşlara attığın yem suladığın kırık dal hatırlayamadığın telefon numarası Nedendir bilmem zamanın keskin yüzünde vücut bulan o ihmal o y...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/evarkadasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herhangi', 'herhangi-kucuk-i-skender-mzwae', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'az önce geldiğinizi hatırlıyorum dedi komiser

herifi gömdük, kızdan ise reçel yapacağız, 

benim de bir devletim var şu anda ilkokulda, 

bana bir kere verse emekli olurum onursuzluktan

farkeder mi iktidara prezervatif olmuşken ruhum!', 'az önce geldiğinizi hatırlıyorum dedi komiser herifi gömdük, kızdan ise reçel yapacağız,  benim de bir devletim var şu anda ilkokulda,  bana...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/herhangi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karo Valesinin İntikamı', 'karo-valesinin-i-ntikami-kucuk-i-skender-xmgy5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bilmeden, sormadan, ağlamadan

neredeyse eğiliyordum dumanla; 

kasatura ve vals

cinnet ve raks

doğrulacaktı iyi iki ayağı üzerinde gömülü

durduğum yorgun buharlardan; 

gümüştüm.

gümüştüm, bunu söylemiş olmalıyım! 

alüminyum bir el aynasıyla geçmişti çocukluğum

bakır bir boy aynasında bir asırlık kapris

ve ete, ve ete misafir gelen harcai duam

olgunlaşıp dökülmüştü birer birer his his...

neden tekrarlanıyordum hiç değişmeden

hiç bilmeden, hiç sormadan, ağlamadan..

ölü doğmuş, sufli bir uzak akraba gibi

kabullenmiştim

aşkı motosikletimin arkasına almayı; 

gidiyorduk: otobandaydı

64 model maceram, 

orada ucuz nefeslere çan

takmış yanlış

hayvanlar, 

bir öcü bir yalnızlık yapmak için

bir ikramı bir red saymak için

safdilli, orospu ve şeffaftılar

onlar, lüzuma açtılar

onlar, mütevazılığa açtılar

onlar sıraya girip sırayla rahmimi açtılar! 

rahmimde halayık cesetlerim

ve dört bir cihana kıvrak, meşhur böcekler götüren

rock-jazz ya da new wave kalbim

ya da kalbimin solo iktidarını elinden alan

meşgul mahşer kalmıştı. Kazılmıştım.

içimden tarihi bir intihardan başka birşey çıkmamıştı! 

gümüştüm. ölmüştüm. gömülmüştüm.

sessizce. Bunu söylemiş olmalıyım! 

size kendimi akıtamadan gitmiştim; 

açık denize ulaşamadan sürünerek kuruyan

asil bir ırmağın son asi damlasıydım, 

kirpiğinizde kalmıştım, tahakküme takılmıştım, 

yatağımdan derinliğinize düşememiştim; 

siz bir bardak suydunuz, ben en çok bundan korkuyordum

anneme sizi anlatmıştım o kararmıştı

dışarı çıkmış içersini tabiata ihbar etmişti; 

neden yine çöpadamdım hiç büyüyemeyen

hiç bilmeyen, hiç sormayan, hiç ağlamayan: 

dört kez ağlamıştım topu topu zaten: 

birincisi, okumayı söküp çıkarttığım gündü zamandan, 

ikincisi, ilk sertleştiğim dirim, ah o mel''un çığlık, 

sonrakini, söylemedem de olur, 

son kere, gümüşü işittiğim o körkaranlık! 

bugün hep ağlıyorsam kızmayın

çünkü doğarken hiç ağlamadım ben! 

bunu söylemiş olmalıyım! 

çünkü doğarken hiç ağlamaz ibneler! 

ama, otobanda, sürerken 64 model maceramı

orada, zavallı şefkat misyonerleri

zavallı küçük yabancılar

zavallı kitapsız peygamberler

zavallı erk pezevenkleri, yani sizler, 

aldırmayarak kasvetinizin hışmına ve

kendinizden bile habersiz

kanatmaya başladınız ricamı

cahilce, aptalca, önlemsiz! 

ah ne yazık! ah ne yazık! 

tatmin etmedi hırsınızı bir türlü

ölü ele geçirilmiş aşk mektuplarım! 

asla coplanmadı

kurduğunuz hayallere kalkan çükleriniz! 

siz, virajsız yolların sözde usta sürücüleri! 

siz, yokuşaşağının kolaycı sözcüleri! 

bilmeden, sormadan, ağlamadan

az daha eğiliyordum dumanla; 

ben ananızın.mıyım

haydi durmayın

..kin beni! ..', 'bilmeden, sormadan, ağlamadan neredeyse eğiliyordum dumanla;  kasatura ve vals cinnet ve raks doğrulacaktı iyi iki ayağı üzerinde gömülü dur...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":76,"source_url":"https://www.antoloji.com/karo-valesinin-intikami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuluk', 'korkuluk-kucuk-i-skender-evosn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Küçük hayvanları sevdiğimizi

neden gizledik sanki

onca zaman

Çok güçlü patlamalar esnasında

koynumuza aldığımız

sıvı cesetler

şuralardan bir yerden başlıyordu çocukluk', 'Küçük hayvanları sevdiğimizi neden gizledik sanki onca zaman Çok güçlü patlamalar esnasında koynumuza aldığımız sıvı cesetler şuralardan bir...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/korkuluk-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Bakar Kör', 'o-bakar-kor-kucuk-i-skender-txhlu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'çekinir

aymaz korsanla istiridye arasına konan o tenha, 

gerilir ve

mevsimine yerleşir uçuşan pusuya aklınca yapışan.

Kalınır geriye! Yaralı gecelerle kalınır geriye! 

isteksizce şekillenen büyülü bitki hücrelerinde

bir alevlenişi

bir vücuda gelişi yüreklendiren o mahzun siren, 

bilinir karşı vakte geçiş ve

örtbas edilir ecele doğru kırık ceninlerle

kanın sağ salim karaya çıktığı o işveli muamma!', 'çekinir aymaz korsanla istiridye arasına konan o tenha,  gerilir ve mevsimine yerleşir uçuşan pusuya aklınca yapışan. Kalınır geriye! Yaralı...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/o-bakar-kor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyuncak', 'oyuncak-kucuk-i-skender-q24ch', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kelimelerden kıyıya çıkan kalp

arp çalarak kandırdı bütün

masum deniz kabuklarını

Ve yangına otostop çeken

ateş böcekleri içindi

belki sosyalizm

atıma atlayıp düşlerime döndüm o gece', 'Kelimelerden kıyıya çıkan kalp arp çalarak kandırdı bütün masum deniz kabuklarını Ve yangına otostop çeken ateş böcekleri içindi belki sosya...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/oyuncak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paçavra', 'pacavra-kucuk-i-skender-v2m5l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerime yumurtlayan hasret

iyileştirir mi bir akıl hastasını

ansızın sabaha karşı

Ve yine ansızın bir sabaha karşı

ben de delirir miyim

unutursam gördüğüm son harikulade rüyayı

durmayın. siz kaçın kurtulun. ben oyalarım hatıraları', 'Gözlerime yumurtlayan hasret iyileştirir mi bir akıl hastasını ansızın sabaha karşı Ve yine ansızın bir sabaha karşı ben de delirir miyim un...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/pacavra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Peçete', 'pecete-kucuk-i-skender-d8zec', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karanlık elyaf kadifesini aralıyor

engin kekliğin

zülüf zülüf içinde

Bir buruşukluk bu

hayata sığdırılmaya çalışılan

kırık dökük vesvese

ve sabaha karşı tüm kentte yükseklik korkusu', 'Karanlık elyaf kadifesini aralıyor engin kekliğin zülüf zülüf içinde Bir buruşukluk bu hayata sığdırılmaya çalışılan kırık dökük vesvese ve ...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/pecete-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sihirbaz', 'sihirbaz-kucuk-i-skender-q8nqo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşgücüne deyerken korkuyorsun

İri ve nadide bir kış parçası aslında o

soğuğum, bir aşktan bir başka aşka firarında

Oysa isim vermeden konuşur rüzgar

bütün hayvanların gözleri nemli

bütün kontratlar nesnelerin tekelinde

ah, duyuyorsun, çünkü sen de mor bir buhar taşıyorsun tek elinde', 'Düşgücüne deyerken korkuyorsun İri ve nadide bir kış parçası aslında o soğuğum, bir aşktan bir başka aşka firarında Oysa isim vermeden konuş...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sihirbaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah Prömiyer', 'siyah-promiyer-kucuk-i-skender-6fkz2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '''O, anlar! ''a

İnanma, geçitin sonunda çıkış yokk

O iki çıplak adam da seni orada beklemiyorr

Sessizlik farklı bir anamnezdii

Son konuşan, ilk sözü etmiş demektirr

Bundan sonra yüzümde facia beslemeyeceğimm

Kalbimi blues zindanlarında boğdurdumm

Uzun bir yazıda gözden kaçan bir firari harfimm

Ne benle başlıyor kelime ne de benle bitiyorr

Bu gezegenin tozuyum kendimi yine sileceğimm

Sana gelmiyorum bu yara başka hastalıktann

Bir hatıra bile değilsin ben içeri girerkenn

Ben dışarı çıkarken fil mezarlığı artık yüzünn

Yüzümü yüzüne yeni yıkanmış kefenn

	şeklinde seriyorum boyunca, iyii

Aşktan bana her mevsim çığ düşüyorr

Aşkın mı? böyle bir şarkı dinlemiştimm

Ne kimse söylüyordu ne de ben eşlik ediyordumm

Damdan dama atlarken düşen bir kedinin gözlerii

	var işte şimdi kana batan yüzümdee

Yüzümü ellerinin arasına all

Hani tutarmış gibi bir sincap, cevizinii

İnanma, geçitin sonunda çıkış yokk

Ve dönme geri, arkadaki giriş de kapalıı

Senin yüzün benim yüzüme şüphesiz gizligeçitt

Benim yüzüm senin yüzünle paketlii

Bedenimi değil, bir tımarhaneyi sunuyorum sanaa

İçim cıvıl cıvıl deli çocuklar bahçesii

Kan falıma baktırdım bir vakte kadar ölüm görünüyorr

Ve deli gömleği gibi duruyor yüzüm kafatasımdaa

Hiç tanığım olmuyor hiç yaşadıkçaa

Ve içimdeki dava düşüyor sen içeri girerkenn

Ben dışarı çıkarken, anla, bambaşka bir inzivaa', '''O, anlar! ''a İnanma, geçitin sonunda çıkış yokk O iki çıplak adam da seni orada beklemiyorr Sessizlik farklı bir anamnezdii Son konuşan, il...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/siyah-promiyer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şampanya', 'sampanya-kucuk-i-skender-laoxh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'enis batur''a

Rıhtımda duruyor eflatun tay

suya deyiyor paramparça toynakları

gözçukurlarında rüzgar gülleri

Taya doğru aralıyorum fosforlu jaluziyi

iskambil oynadığım yaşlı güzel kadın kızıyor

ve deviriyor masanın üzerindeki eflatun feneri

yanan kumarhanenin üstünden atlıyor o muhteşem süvari', 'enis batur''a Rıhtımda duruyor eflatun tay suya deyiyor paramparça toynakları gözçukurlarında rüzgar gülleri Taya doğru aralıyorum fosforlu j...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sampanya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terapi', 'terapi-kucuk-i-skender-7fqf9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Görevinin bilincinde suçum

tatlıya bağlanmayacak asla

fenalığımın görüntüsü

Uzanıp bakıyorum da çatılardaki

gangster kedilerin aşk hayatlarına

ileriye doğru adam gibi bir öç örtüsü

içimde bir leylek bir leyleği öperken öleceğim nü', 'Görevinin bilincinde suçum tatlıya bağlanmayacak asla fenalığımın görüntüsü Uzanıp bakıyorum da çatılardaki gangster kedilerin aşk hayatları...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/terapi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'The Ant', 'the-ant-kucuk-i-skender-to5l1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'durunuz! 

kaç kalibre o bakışlar

eh evet bir tanrıda sabaha vakitleri! 

durunuz! 

kaç yerimden vurdunuz! 

kaç yerimde artık sorumsuz kuş yaraları var! 

sorarım

kaç yerimde yerimden ettiniz beni! 

kaç yerim şimdi lapa lapa kanar! 

saysam sayılmazsınız asırlarla

konsam taşımaz gövdeniz içimi

öpsem çatlar kırılır dudaklarınız

dudaklarınız bir karşı çıkış biçimi

sarılsam sarılsam günlere sığmaz seyehatim

anlıyorum

sizin bir tavrınız oksijen

bir tavrınız bal gibi uranyum! 

ah gidilemeyecek kadar sapa

dönülemeyecek kadar uzaksınız

çiçek açsanız baharla aram bozulur

sizi bana bırakmaz bu yalnızlığınız

çünkü biz ikimiz

yanlış yapamayacak kadar yalnızız! 

sesler yalanlar mı geceleri

gözuçlarına tırmanan siyah tavşanlar

akşam inince kaybolur mu, 

sizi seviyorum

sizi pek seviyorum

sizi sevmem bize ayıp olur mu..

bırakmalı kibarlığı! sonsun işte! sonsun! 

sonumda biletimi kesen yaman giyotinsin! 

ben istiyorum! ben istiyorum diyorum! 

unut! giyotin tek hamlede insin!', 'durunuz!  kaç kalibre o bakışlar eh evet bir tanrıda sabaha vakitleri!  durunuz!  kaç yerimden vurdunuz!  kaç yerimde artık sorumsuz kuş yar...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/the-ant-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhumu Gömdüm Kalbimdeki Makbere', 'ruhumu-gomdum-kalbimdeki-makbere-salih-ozalasan-8z17c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bende gidiyorum gözüm ardımda

Gidenlerin asla dönmediği o yere

Kurumuş gözyaşlarım yanaklarımda

Ağlıyamıyorum; 

Ruhumu gömdüm kalbimdeki makbere

Kalemim artık bana mezar taşı

Son sayfamsa adıma yazılmış kitabe

Yazdıklarım denizde bir nokta

Yazamadıklarım yeterdi yüzlerce hatibe

Kimse anlamadıya kısa ömrümde beni

Kan ağladı yüreğim sandılar hep lâtife

Yüreğimi adadım görmedim seveni

Sevdam alındı nedense hep hafife

Ferhat olup dağları deldim ne çare

Sayfalarca yazdım yine ben biçare

Yazdığımı okuyanın oldu yüreği pare pare

Sevdamı isbat edemedim yinede ben o yare

Kalmadı artık hayatta bir umudum

Yüreğimde asla onmaz bu yare

Benden sonra selam olsun 

Başka diyecek şeyim kalmadı o yare

Gidip gelmemek gelip görmemek 

Var diyeceğim ama ne çare

Gidişim son gidiş, zor söylemek

Ruhumu gömüyorum kalbimdeki makbere

Y.Tar.05.12.2002 Saat 23.18', 'Bende gidiyorum gözüm ardımda Gidenlerin asla dönmediği o yere Kurumuş gözyaşlarım yanaklarımda Ağlıyamıyorum;  Ruhumu gömdüm kalbimdeki mak...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ruhumu-gomdum-kalbimdeki-makbere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Trainspotting', 'trainspotting-kucuk-i-skender-kf2lz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kelime kapandı! Koptu sonbaharın kellesi! 

Tam kana dokunacakken, içimde acı bir fren sesi! 

Kıl döndü

Zürafaya karıştı gözlerimiz

Eh

Kırık kaşlar altında kıpır kıpır kırmızı noktalar

ebruli iç huzursuzluğu

bir çırpıda yağıp kaçan abi yağmur

ve o birkaç arkadaşın öldüğü, öldürüldüğü aşk! 

şimdi, başında durup derinliğine bağırdığımız kuyu

biliyorum! bütün boktan ayrılıkları bu kuyu uydurdu! 

örnek vermek gerekirse, elbette ben de sıradayım! 

rehin aldım kalp yoksulluğunu

dünya atlaslarına girmekten kaçınan

o meşhuuur

	sır adayım! 

domalsın önümde kötülüğün soyağacı

şartsa, yeterse, 

	tek başıma ölmeye de adayım! 

Eh

Kelime kapandı! Hükmetti sessizlik ve ot! 

Damarlarımıza düştü uçak! Nedensiz güldü pilot!', 'Kelime kapandı! Koptu sonbaharın kellesi!  Tam kana dokunacakken, içimde acı bir fren sesi!  Kıl döndü Zürafaya karıştı gözlerimiz Eh Kırık ...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/trainspotting-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzatmalısevgililer', 'uzatmalisevgililer-kucuk-i-skender-kz7vk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir masaya kaç kapıdan girilir meridyeni incitmeden

talaz talaz alkolün haydut kaldığı portreler

gibi biraz üşümüş biraz yorgun biraz vakti dar

Beyoğlu, insana mezar toprağı olur çöker

urlarımızla çiçeklenir hayatlarımıza dair masallar

haşlanmış martı, his sote ve şiir kızartması

açığa vurulamayan sırlarımızda kalır aşkın filistin askısı', 'Bir masaya kaç kapıdan girilir meridyeni incitmeden talaz talaz alkolün haydut kaldığı portreler gibi biraz üşümüş biraz yorgun biraz vakti ...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/uzatmalisevgililer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ü Dönüşü', 'u-donusu-kucuk-i-skender-1qgea', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'regl görür mü masumiyet..

görür. helak olmuş ıstıraptır o. görürler.

regl görür mü sükunet..

görür. tasvirin yakayı ele vermesidir o. görürler.

regl görür mü ''aşk için ölmeli, aşk o zaman aşk''..

görür. yatırım götürülmüştür kalptir o. görürler.

regl görür mü çıkış, terkediş, veda..

görür. gecede yatıya kalmaktır o. görürler.

çünkü regl: 

	azilden firar eden komünist', 'regl görür mü masumiyet.. görür. helak olmuş ıstıraptır o. görürler. regl görür mü sükunet.. görür. tasvirin yakayı ele vermesidir o. görürl...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/u-donusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana be Anam', 'sana-be-anam-perihan-magden-9isy9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerin Topkapı çarşısı gibi be anam

İçine girince bi kalabalıklaşıyorum

İte kakıla varıyorum orta yerine

Alacasına bulacasına afallıyorum

Adımı söyleyişin var be anam

Anamdan yeni doğmuş gibi oluyorum

Bi yerin değince bi yerlerime

Sıcak basmış kıyılara dönüyorum

Ağzını topla - deyişin var ya anam

Süt dökmüş çomarlara dönüyorum

On dakika sürüyor sürmesine ya

İcabında bey kesilip edep saçıyorum

Gözünü gözüme damlatışın yok mu be anam

Böğrüme böğrüme bıçaklanıyorum

Yüreğim zonk zonk atıyor kafamda

Mayın yemiş balıklar gibi dolanıyorum

Tophane''ye bile takılmam be anam

Yeter ki yüreğini gerip sen iste

Barbut atmayıveririm kancık ikindilerde

Ellerini avucumdan yere tükürme', 'Gözlerin Topkapı çarşısı gibi be anam İçine girince bi kalabalıklaşıyorum İte kakıla varıyorum orta yerine Alacasına bulacasına afallıyorum ...', ARRAY['Türk Edebiyatı','Şiir','Perihan Mağden']::text[], 8.5, '{"poet":"Perihan Mağden","poet_slug":"perihan-magden","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sana-be-anam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzelmiş Helen', 'guzelmis-helen-perihan-magden-1d1xc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güzeldi Helen

Bi mişli geçmiş zaman eki gibi, 

	süzülüp beyaz fıstanının içinden

Paris''e aktı.

Etleri sarkmıştı yerinden, 

Paris amuda kalktı.

Güzeldi Helen

Ve Truva savaşları, 

	yetmişlik bir ninenin

	kütükleşmiş bedeninin

Yüzü suyu hürmetine çıkmadı.

Keleğe geldi Paris

Biri çıkıp niçinini yazmadı.', 'Güzeldi Helen Bi mişli geçmiş zaman eki gibi,  	süzülüp beyaz fıstanının içinden Paris''e aktı. Etleri sarkmıştı yerinden,  Paris amuda kalkt...', ARRAY['Türk Edebiyatı','Şiir','Perihan Mağden']::text[], 8.5, '{"poet":"Perihan Mağden","poet_slug":"perihan-magden","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/guzelmis-helen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'El Filan', 'el-filan-perihan-magden-0cf6t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senin gözlerinde iyilik kuşları varmış

Hepsini vurmuşlar

Çiçekleri sevdirmemişler sana

	- Anan çiçeklerini sular sabahtan akşama

	Baban elde tüfek mimoza bekler

Kadifeler giydirmişler örneğin

Boyunbağı, beyaz çorap; iyi çocuk

Çarşamba günleri ıspanaklı börek

Salçalı köfte yanına

Benim istasyonlarımda bilinmedik trenler

Bildik düdüklerini çalıyor

Ağaçları kucaklıyorum, saçlarımı tarıyor dallar

Afrikalı bir kadının kolyesini aşırıyorum boynundan

Sonra iyiyim çokça, sağlığım yerinde

Hava durumunu dinliyorum salı sabahları

Perşembe günleri asfalt döküyorum

Günaydın diyorum durduk yerde

Ama ne rastlantı bir yerde oturuyoruz

Sen ağlıyorsun, ben bağışlıyorum

Eski bir gramofon kadar hoşgörülü

İyi şeylerden söz ediyorum

İçerden birisi saati bağırıyor

	- Hep birisi vardır, saati bağırır

Eğri hoşçakallar oynuyor dudaklarımızda

Kıyılarıma bir dalga çarpıyor, 

Biniyorum beyazlığına

Parmaklarım iki yanıma yapışmış

El filan sallıyorum.', 'Senin gözlerinde iyilik kuşları varmış Hepsini vurmuşlar Çiçekleri sevdirmemişler sana 	- Anan çiçeklerini sular sabahtan akşama 	Baban elde...', ARRAY['Türk Edebiyatı','Şiir','Perihan Mağden']::text[], 8.5, '{"poet":"Perihan Mağden","poet_slug":"perihan-magden","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/el-filan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Depo Çavuşu Konyalı Mustafa''nın Şiiri', 'depo-cavusu-konyali-mustafa-nin-siiri-yilmaz-erdogan-hjm7j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ağbi, dedi

bir söz var, 

dilimle yüreğim arasına sıkışmış

belki on yıl belki onbeş

gider gelir

usumun uslanmayan yerlerine, 

bir şiirinde, dedi

yazarsan, dedi

çok makbule geçer

belki makbul saymayacağım bu isteğim, 

yazarsan eğer, dedi

şöyle kocaman harflerle: 

İSYANLARDAYIM, diye

kepime yazdığım gibi şöyle, 

o kepi hep çıkarırız

ne zaman ismin anılsa hanemizde...

olur dedim be çavuşum, 

yazarız...

şiir dediğin kimin içindir mustafa?', 'ağbi, dedi bir söz var,  dilimle yüreğim arasına sıkışmış belki on yıl belki onbeş gider gelir usumun uslanmayan yerlerine,  bir şiirinde, d...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Erdoğan']::text[], 8.5, '{"poet":"Yılmaz Erdoğan","poet_slug":"yilmaz-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/depo-cavusu-konyali-mustafa-nin-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavilere Uyanmak', 'mavilere-uyanmak-yilmaz-erdogan-tozop', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yedi iklim geçer, 

ağarıp solan güz ışıklarından

yalan pencerelere doğru...

uykularda olur ne olursa

	yangınlar, 

		takvim ziyanları, 

			gömülü sevdalar...

iksir gibi yayılır

hücrelerimin rehavetine ıslaklığın

düş tüccarları ağır mesaidedir...

uykularda olur ne olursa, 

talanlar

ve beton serinliği

inşaat halindeki aşkların...

uykularda ölür ne ölürse, 

	kıpırdayan su

		gülümseyen yel...

yedi iklimin oralarda

kavalını kırmış bir çobandır

gökyüzü, 

aklında new orleans

heybesinde caz! 

yedi iklimin

bar olduğu yerdedir uykunun

alkol imparatorluğu

kalabalık avındadır bakışlar...

uykularda olur ne olursa, 

bitmez efkar kırları

bazı saçlarda

ve ölüm gibi suskunluklar açar

derin kuyularda...

ve şaka gibi

ve sarsak sarsak

ve kımıl kımıl

bir yaşamaktır

MAVİLERE UYANMAK

en kesif karanlıklara kafa tutan

gözlerinin mavisine kuşanmak...

senin kanatların var, 

benim köylü yüreğim...

operada tezek kokusu

bu şehirdeki varlığım! ..

beni taşıyacak vesaitim yok

bu caddeüstü sevdada

ellerinden gayrı..

''gayrı dayanamam ben bu hasrete''

ya beni de yitir

ya sen de git

beni götürdüğün yere...

türküleri sev

yalan kahkahalardan uzak dur

canımın suyuyla yıka ellerini..

aklımın maharetiyle giydir

en mavi yerlerini...

senin adın

buzul mavisi! 

çünkü mavilerde uyur, 

benden sana geçen

sende beni kalkındıran ne varsa! 

sevdiğim, açlığımın uzak ufku, 

her sabah; 

güneşten ne zaman işaret alırsan

ne zaman dar gelirse soluğun

böyle uzun sarılmaklara, 

fikrini kurcalarsa eğer

açık korkular, 

işte o zaman

mavilere, 

mavilere

uyandır beni...', 'yedi iklim geçer,  ağarıp solan güz ışıklarından yalan pencerelere doğru... uykularda olur ne olursa 	yangınlar,  		takvim ziyanları,  			gö...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Erdoğan']::text[], 8.5, '{"poet":"Yılmaz Erdoğan","poet_slug":"yilmaz-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/mavilere-uyanmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeyi Bile Beceremedim', 'sevmeyi-bile-beceremedim-sair-karagozlum-xt4mz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dedilerki gün gelir sende seversin

sevmek neymis ögrenirsin

vazgec deseler vazgecemezsin

 ben sevmeyi bile beceremedim.

Gün geldi kalbsiz dediler

caliszim cabaladim

sandimki baglandim

cok gec olmadan

yanildigimi anladim

ben sevmeyi bile beceremedim.

Sende sev yanarsin dediler

sevdaliya aci cektirirler

tövbelimiyimmi sevdaya bilemedim

ama

ben sevmeyi bile beceremedim.', 'Dedilerki gün gelir sende seversin sevmek neymis ögrenirsin vazgec deseler vazgecemezsin  ben sevmeyi bile beceremedim. Gün geldi kalbsiz de...', ARRAY['Türk Edebiyatı','Şiir','Şair Karagözlüm']::text[], 8.5, '{"poet":"Şair Karagözlüm","poet_slug":"sair-karagozlum","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevmeyi-bile-beceremedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanım', 'tanim-yilmaz-erdogan-2xdh9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kısaydı kalem

ömrü yetmedi

	uzamaya

kaybolmuş

tılsımlı

aceleci bir gezginin

kurulmuş kumsaatiydi

	ağlamaya

adını soruyorlar

adını söylemiyor

hırçın bir yağmurum ben

harflerim yetmez

akrostiş ya da

kartvizit

	yapmaya

şiir bir sezdirmedir diyor

lamsız an''lar için

imgeler yalan söyler

yalanı şiir eyler imgeler

dokunduğun yerlerde

izsiz ıssız sesler kalıyor

adsız ama

elmacık kemikleri belirgin

mısralar başlıyor

saçlarının kaldığı yerden

	konuşmaya

adını soruyorlar

adını söylemiyor

biraz da susmaktır diyor

şiirimi okumak

usta işi bir tabloya

yeniden yeniden

yeniden bakmak

van gogh''un kulağıyla duymak

tanrısal seslerini hayatın

pazar günkü bir sokaktır

cismim

vesaitin yetmez

yeryüzümü

	adımlamaya

adını soruyorlar

adını söylemiyor

efsunlu kaldırımlar boyu

açık açık susabilen

sınırsız şehirsiz

uzadıkça vatansız

çoğaldıkça isimsiz

yurttaşlarım yaşar

dünyanın on bir yanında

	yalnızlaştıkça

adını soruyorlar

susun diyor şiirim

yeri yurdu sahibi olmayan

haymatlos bir piç

bir gölgenin yorgunluğuyum ben

yazılması unutulmuş günahlar için bir fihrist

bin yıl sonrası için bir ajanda

anlatmaktan sıkılmış

bir meddahım ben

otopsisiz gömülmüş!', 'kısaydı kalem ömrü yetmedi 	uzamaya kaybolmuş tılsımlı aceleci bir gezginin kurulmuş kumsaatiydi 	ağlamaya adını soruyorlar adını söylemiyor...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Erdoğan']::text[], 8.5, '{"poet":"Yılmaz Erdoğan","poet_slug":"yilmaz-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/tanim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yedi Uyuyanlar Masalı', 'yedi-uyuyanlar-masali-yilmaz-erdogan-vcjmg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'biraz kekredir derler buranın suyu

beşe beş dayanakları vardır duvarlarının

çünkü toprak kayar uyku zamanı

taş yerinde değil düşerken ağırdır nasıl

ki ağrı''da dipsiz kuyular

yedi uyuyanlar mağarada

telefon sesini duyarlar da

üşenirler açmaya yedi uyuyormuşgibiyapanlar

mağarada

pamuk prenses çözmüş sorununu üvey annesiyle

ayna fişteklemiyor güzellik meselesini

-ayna ayna! söyle bana, benden güzeli var mı dünyada? 

-vallahi pamuk prenses var ama onun da yatağı kötü diyorlar...

kendini cüce zannedemiyor

uyuyor çünkü yedi andavallılar

biraz kekredir derler buranın masalları

prens geliyor gerçi öpemiyor fakat

uyku kokan ağızları

ve aradan yıllaaaaar yıllaaar geçiyor...

derken uyanıyor yedi''den biri

hassiktir diyor amma uyumuşum be...

çıkıyor kahvaltılık birşeyler almaya

dömüyor fakat...

ve derler ki altı keriz uyumaktadır hala

ege''de

turistik bir mağarada...', 'biraz kekredir derler buranın suyu beşe beş dayanakları vardır duvarlarının çünkü toprak kayar uyku zamanı taş yerinde değil düşerken ağırdı...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Erdoğan']::text[], 8.5, '{"poet":"Yılmaz Erdoğan","poet_slug":"yilmaz-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yedi-uyuyanlar-masali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taşıran Damla', 'tasiran-damla-cemal-sureya-wzp6p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Arı mısın türkü boku musun ne

Seviyorum seni taşıran damla

Adın yazılı gün sonlarına

Kaldırdığın toz anayol tozu

Arı mısın türkü boku musun ne

Gün gelir bir sürü şey

Zoruna gitmeye başlar gerçeğin

Yenilgiler de birikir ilenç de

Kentlerin sarı gözeneklerinde

Zoruna gitmeye başlar 
..........
..........', 'Arı mısın türkü boku musun ne Seviyorum seni taşıran damla Adın yazılı gün sonlarına Kaldırdığın toz anayol tozu Arı mısın türkü boku musun ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tasiran-damla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Volta', 'volta-yalcin-aydin-tj3pc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Voltalarla dolanıyorum dünyayı

Mahkum sanki ayaklarım.

Oysa güneş vuruyor yüzüme! 

Martıları dinleyebiliyorum! 

...

Kıskançlığım başka...', 'Voltalarla dolanıyorum dünyayı Mahkum sanki ayaklarım. Oysa güneş vuruyor yüzüme!  Martıları dinleyebiliyorum!  ... Kıskançlığım başka......', ARRAY['Türk Edebiyatı','Şiir','Yalçın Aydın']::text[], 8.5, '{"poet":"Yalçın Aydın","poet_slug":"yalcin-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/volta-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açıklama', 'aciklama-huseyin-kerim-ece-zei7q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kafdağına götürsün diye varlık sırrımı, 

Bak, ufuktan ufuka uçan kuşa anlattım, 

Düzler bahane buldu, ovalar yorgun düştü, 

Doruklara tırmanan bir yokuşa anlattım, 

Önüme çıktı kader ülkesi perde perde, 

Bildim, binbir macera yaşanır gecelerde

Issız kalınca yürek endişeyle seherde, 

Gündüz ile canlanan o coşuşa anlattım, 

Elbisede tereddüt, aynalarda pürtelaş, 

Ve eşya gölgesine gömülü binlerce baş, 

Kırar camdan evleri vaktin savurduğu taş, 

Hali, sonsuza koşan bir uçuşa anlattım.

18/2/2002

Zaandam', 'Kafdağına götürsün diye varlık sırrımı,  Bak, ufuktan ufuka uçan kuşa anlattım,  Düzler bahane buldu, ovalar yorgun düştü,  Doruklara tırman...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kerim Ece']::text[], 8.5, '{"poet":"Hüseyin Kerim Ece","poet_slug":"huseyin-kerim-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/aciklama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ötelerden Gelen Misafir İçin', 'otelerden-gelen-misafir-i-cin-huseyin-kerim-ece-pkmq1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '(Oğlum Abdussamed Tarık’ın doğumundan bir hafta sonra.)

Çok beklettin ya, işte sonunda geldin bize, 

Gelişinle gül yüzlü mehtâp indi denize, 

Geldin. Hoş geldin bebek, fecir yeniden açtı, 

Gönlümüz çoktan beri bu sevince muhtaçtı, 

Sen geldin, çeşmelerden ab-ı hayat boşandı, 

Sen geldin, yuvasından yavru kuş havalandı, 

Sen geldin, gülücükler yayıldı ufuklara, 

Sen geldin, mavi ışık tırmandı doruklara, 

Sen geldin, aynalarda cümbüşe döndü renkler, 

Sen geldin, dile geldi türkülerde ahenkler, 

Ey ezgilerde adı zaman gibi uzayan, 

Ey yüzünün renginde fezaları saklayan, 

Ey Yüce Rabbimizin, en güzel armağanı, 

Ey gülücük mahşeri, ey sevincin harmanı, 

Ey bayram şekeri, ey gönlümüzün düğünü, 

Ey geçmişin yarını, ey geleceğin dünü, 

Sen dünyaya değil de, kalbimize hoş geldin, 

Hoş geldin buralara, bana, bize; hoş geldin, 

Sen geldin, intizârın ukdeleri çözüldü, 

Sen geldin, evimizde herkesin yüzü güldü, 

Can bebek, artık geldin; gözlerinle konuştum, 

Düşlerim gerçek oldu, hayalime kavuştum, 

Bakışında dünya var, ay dönüyor yüzünde, 

Gecesinde bayram var, sevinç var gündüzünde, 

Sen geldin, zambaklarda bahar telaşı oldu, 

Sevinçten, gözlerimden gözyaşlarım savruldu, 

Ne iyi ettin, geldin öteler ötesinden, 

Payımı alıyorum mehtâbın bûsesinden, 

Geldin de dalımızda çiçek açtı tomurcuk, 

Bahçemizde taptaze bahar oldun, be çocuk, 

Bu müstesna gelişi, anlatır hangi kelâm? 

Selâm sana ey bebek, gönül dolusu selâm.

Şimdi dokunayım mı yüzüne gözlerimle? 

Gel desem, gelir misin kafdağına benimle? 

Güllerle geldin, keklik ötüşü yanağında, 

Binbir avize yanar sımsıcak kundağında, 

Seni yatakta değil, kalbimde buluyorum, 

Uzak yerlerden o can kokunu alıyorum, 

İşte beklenen muştu, güvercin kanadında, 

İşte özlenen sevgi, bu bebeğin adında, 

Yüreğin semasında yükseldikçe yükseldin, 

İşte tebessümlerle nihayet çıka geldin, 

Şimdi gül, gülistanda güllerin hiç solmasın; 

Gül ki, yanaklarında hiç karanlık olmasın...

27/5/2002 Zaandam', '(Oğlum Abdussamed Tarık’ın doğumundan bir hafta sonra.) Çok beklettin ya, işte sonunda geldin bize,  Gelişinle gül yüzlü mehtâp indi denize,...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kerim Ece']::text[], 8.5, '{"poet":"Hüseyin Kerim Ece","poet_slug":"huseyin-kerim-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/otelerden-gelen-misafir-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dürdane Hanım', 'durdane-hanim-yalcin-aydin-l3a8f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Otuzuncu yılında kapatmış defteri, kitabı

bağrında üç avuntu, 

üç amaç...

Üçüncünün kokusunda

hala ararken erkeğin özlemini, 

ilk gözağrısı da terk etmiş onu! 

vermiş toprağa...

O bir kadın

O bir ana

O bir insan...

Kimbilir kaç kez dokundu yalnızlığına! 

Veya; 

cesaret edemedi belki

ne kendine

ne başkasına...

Artık son kokladığı da yok! 

bir on yıldır

onu da ekmiş geçmişine, geleceğine...

Yüreğinde kalan sadece ortanca! 

Ortanca! 

kocası

kızı

belbağladığı...

Bir de kendisi! 

Hasretin üstüne yatmayı bekleyen...', 'Otuzuncu yılında kapatmış defteri, kitabı bağrında üç avuntu,  üç amaç... Üçüncünün kokusunda hala ararken erkeğin özlemini,  ilk gözağrısı ...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Aydın']::text[], 8.5, '{"poet":"Yalçın Aydın","poet_slug":"yalcin-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/durdane-hanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yudum Kadar', 'bir-yudum-kadar-huseyin-kerim-ece-e3e14', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayat bir yudum kadar, yutuldu yutulacak, 

Başucuna asılan kandilin ömrü ne az; 

Her bir damla çatıyı bak kökünden sarsacak, 

Evde hazine gibi pırlantadan bir enkaz, 

Hayalin ateşiyle parlıyor yetim ocak.

Güneş batacak, akşam inecek gökten; bildim, 

Ben bu gerçeğin aptal bir cahili değildim.

Bir baksana; yapraklar durmadan sararıyor, 

Her bir yüzde Eylûl’ün hatırası kalıyor, 

Pencere küçülüyor, gökyüzü kararıyor, 

Kolları bir korkunun ipleri yakalıyor, 

Kalbin ufuklarını kara haber sarıyor.

Güneş batacak, akşam inecek gökten; bildim, 

Alacak defterinden boş umutları sildim.

Çiçeklerin açışı başka bahara kaldı, 

Denizde unutuldu kurtuluşun vapuru, 

Lâmba söndü, muslukta hayat suyu azaldı, 

Taşıdığım mücevher doldurmadı çukuru, 

Bütün sermayeyi bir hoyrat dilenci çaldı.

Güneş batacak, akşam inecek gökten; bildim, 

Bu gerçeğin önünde bir kez daha eğildim.

22/9/2002 Zaandam', 'Hayat bir yudum kadar, yutuldu yutulacak,  Başucuna asılan kandilin ömrü ne az;  Her bir damla çatıyı bak kökünden sarsacak,  Evde hazine gi...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kerim Ece']::text[], 8.5, '{"poet":"Hüseyin Kerim Ece","poet_slug":"huseyin-kerim-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-yudum-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Barış Türküsü', 'baris-turkusu-ali-niku-r232o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'maraş''la kayseri arasındayız

tekir yaylası''nda araç içinde

mavzer gümbürtüsü keleş''in sesi

korkuyu yaşatır araç içinde

siperdeki mehmet bakar yukarı

yüreğinde yavuklunun özlemi

bir bezginlik, perişanlık diz boyu

er mektubu niyetine korkuyu

dağlardaki delikanlı ham traş

attığı mermiye katarsa telaş

yaşam onun ama uğraşı beleş

içindeki korku mavzer''e bağlı

canhıraş feryatlar, silah sesleri

emir komutayla hücum, ileri

kardeşi, kardeşe kırdıranları

korkuyu serbest bırakın artık

kimisi çekildi, kimisi kaçtı

yaşamın güneşi yeniden açtı

iki tarafa birden hoşgörü saçtı

sevgi ile barış korkuya bedel...', 'maraş''la kayseri arasındayız tekir yaylası''nda araç içinde mavzer gümbürtüsü keleş''in sesi korkuyu yaşatır araç içinde siperdeki mehmet baka...', ARRAY['Türk Edebiyatı','Şiir','Ali Niku']::text[], 8.5, '{"poet":"Ali Niku","poet_slug":"ali-niku","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/baris-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönüşlere Hasret', 'donuslere-hasret-aziz-pinar-7f00s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir yerin olamalı veda etmak için

Bir köyün olmalı, bir toprağın mesela

Şöyle iç çekip bir gurbet şehrinde

Hasretlerine ah etmelisin mesela...

Sarı başlaklar olmalı rüzgarınla salınan

Yaz ortasında bir testi su olmalı mesela

Terlerle ıslanan bağrına dökülürken

İçişlerine ah etmelisin mesela...

Bir sevgilin olmalı veda ederken

Hemde kara sevdalısından mesela

Dönüşlerine tutuklandığın uzaklarda

Bekleyişlerine ah etmelisin mesela...

Bir toz bulutu kalmalı vedalara eklenen

Geride kalanlar özlemi yüklemeli mesela

Bitmez tükenmez karanlık gecelerde

Sarılışlarına ah etmelisin mesela...

Bulutlar yağmur yüklü gelmeli vedalarda

Damlalar ağladığını saklamalı mesela

Sırılsıklam unutulduğun sokaklarda

Islanışlarına ah etmelisin mesela...

Bir kaybedişin olmalı vedaların ardından

O kör gidişlerine ah etmelisin mesela

Gelişlerinde bir bekleyen bulamazsan

Dönüşlerine ah etmelisin mesela...', 'Bir yerin olamalı veda etmak için Bir köyün olmalı, bir toprağın mesela Şöyle iç çekip bir gurbet şehrinde Hasretlerine ah etmelisin mesela....', ARRAY['Türk Edebiyatı','Şiir','Aziz Pınar']::text[], 8.5, '{"poet":"Aziz Pınar","poet_slug":"aziz-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/donuslere-hasret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İklimleri Kendin...', 'i-klimleri-kendin-asli-durak-fwo9z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kapandı bir kitap daha

yorumsuz kaldı satır araları

öksede saka mıydı bu kadın

isyanın sularında 

şimdi

böyle başı dik

sen yine iklimleri kendin kılarak git

gün gelir hatırlanır belki: 

hiçbir şeyi anlamak için aşıp geldik her şeyi

ve yok artık kendimizden başka geçeceğimiz

aştığımız sınırlara yüklediğimiz anlam kadar yakın

demirlemeseydi keşke yorgun aklımın kıyısına

senli, sensiz anılarım

göğüs kafesinde çırpınırdı tutsak bir kuş

şaşardık 

nasıl da unutmuştuk derin ürperişleri

sen belki de hiç bilmeden 

öperdin incinmişliğimi

aradığımız ne varsa şimdi uzak ve yabancı

boşuna mı tutunduk umudun gök kuşağına

yine dolduramadı boş kareleri

umarsızca beklediğimiz

bilmece tutkunu birileri

ben

 yine

nereye göç etti kuşların ey yitik ülke

derim kendime

süzülürüm direnişin sularında başım dik

sen

iklimleri kendin sanarak 

git', 'kapandı bir kitap daha yorumsuz kaldı satır araları öksede saka mıydı bu kadın isyanın sularında  şimdi böyle başı dik sen yine iklimleri ke...', ARRAY['Türk Edebiyatı','Şiir','Aslı Durak']::text[], 8.5, '{"poet":"Aslı Durak","poet_slug":"asli-durak","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/iklimleri-kendin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklı Karanfil', 'sakli-karanfil-asli-durak-6h0y3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'eğreti karanfil rüyasındayım

umulmadık rüzgarlar peşinde 

bayram çocuğu ruhum

gözleri bayraklı Jan Dark

oysa nasıl da yorgunum bak

hüzünler evidir artık yüzüm

camlarımdan buz bıyıklı 

kış adamlar sarkar

kapımda anahtarları gömülü sayısız kilit

-ve her kilit kendini acıtır biraz-

izin verme hüzzama  uzakta kalsın

sen dik duruşlar giyin hayatın aynasında

umut dudağımın kıyısında karanfil

ben gülle kül arasında gelgit 

bir saklı kent', 'eğreti karanfil rüyasındayım umulmadık rüzgarlar peşinde  bayram çocuğu ruhum gözleri bayraklı Jan Dark oysa nasıl da yorgunum bak hüzünler ...', ARRAY['Türk Edebiyatı','Şiir','Aslı Durak']::text[], 8.5, '{"poet":"Aslı Durak","poet_slug":"asli-durak","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sakli-karanfil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmanın Sularında', 'unutmanin-sularinda-asli-durak-farx4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'son ilaç

tek doz

tek vuruş

bitti işte söylenecek sözler uçmuş

aklımın hangi adasını dolaşsam: 

rehin bıraktığın ahtapot kolların

iç sözlüğümden yeni anlam aramak boş

anılarımın krallığından atıldın

unutmanın sularında artık 

sayfalarından yaptığım kayık

kokunu al

bakışını topla aynalarımdan

bu son hatırlayışım omzunda duruşunu 

dalından kopmuş  ak bir yaprağın

tek dozluk altın vuruş

bitti işte 

sihirli son söz de 

uçmuş', 'son ilaç tek doz tek vuruş bitti işte söylenecek sözler uçmuş aklımın hangi adasını dolaşsam:  rehin bıraktığın ahtapot kolların iç sözlüğüm...', ARRAY['Türk Edebiyatı','Şiir','Aslı Durak']::text[], 8.5, '{"poet":"Aslı Durak","poet_slug":"asli-durak","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/unutmanin-sularinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntihar Eden Şiir', 'i-ntihar-eden-siir-ali-galip-4bbah', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sanırım gerçeklerle yüzleşiyordum

Şiir yazıyordum evet

Dünyadaydım son dünyalı günlerdi belki öyle dilenmişti 

Kalemler kırıldı duydum

Loş ışıklara karışan sözlerde(kulağımdaki kayıp yırtık) 

Kalemler hep tıraşlı kalsın

(İşte benim yalnızlığım

Manyaklığa güdülen içtadımlı gezegen) 

Kelimelerse hep genç

Mademsin, 

Kelime değilsen ne? 

Şiirlerimiz bize benzemezdi çünkü: 

Post umutlardan sakınıp

Postu deldiren eşkıyalar', 'Sanırım gerçeklerle yüzleşiyordum Şiir yazıyordum evet Dünyadaydım son dünyalı günlerdi belki öyle dilenmişti  Kalemler kırıldı duydum Loş ı...', ARRAY['Türk Edebiyatı','Şiir','Ali Galip']::text[], 8.5, '{"poet":"Ali Galip","poet_slug":"ali-galip","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/intihar-eden-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göz Yaşlarım Donuyor', 'goz-yaslarim-donuyor-abdusselam-bugur-gjhwv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir ekim akşamında aldılar beni, 

Yaktılar yüreğimi.

Duygularımı çaldılar benden

Kopardılar ümitlerimi…

Yedi kat yerin dibine gömdüler…

Ben aşkı yüreğime akıtım

Damarlarıma dağıtır belki

Kan gibi…

Dilek dilediğim

Yıldızlar avuçlarımda 

Ben, 

Denizlerin en kızılı

Nehirler kadar coşkun

Bak şimdi durgun sular

Gibiyim.

Artık hüzün yağmurlarıda

Ağlatmiyor beni, 

Göz yaşlarım donuyor yüreğimde...

Ben sevda çölünde

Sevda içimde bir garip.

Aşk deyince

Bir şeyler tıkanıyor boğazıma

Konuşamıyorum...

…………

Bir sevgi diyorum, 

Bir sevgi...

Aşkı dağıtsa hücrelerime

Anlaşılmaz sözcüklerle haykırsaydım

Ayrılığın yok olası yüzüne…

Belki bulurdum

Kendimi…', 'Bir ekim akşamında aldılar beni,  Yaktılar yüreğimi. Duygularımı çaldılar benden Kopardılar ümitlerimi… Yedi kat yerin dibine gömdüler… Ben ...', ARRAY['Türk Edebiyatı','Şiir','Abdüsselam Bügür']::text[], 8.5, '{"poet":"Abdüsselam Bügür","poet_slug":"abdusselam-bugur","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/goz-yaslarim-donuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savaşçı', 'savasci-derin-oger-8ol1s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bırakamam seni kara tahtam.

Yurdumun uçsuz bucaksız köylerine götürdüm.

Susuz, 

Yolsuz köylerine.

Ayşeler tanıdım yalın ayak.

Aydınlığa susamış, Fatmalar gördüm.

Eşkıya kol gezerken dağlarımda, 

Yalnız bekledim seni.

Kartal tünediği yerlere tırnakla kazıdım.

Kağnıyla taşıdım bugünlere…

Haçlı ordusuydu bilmezlik.

Bir avuç askerdi kalem! 

Görev Türkiye’m kadar kutsal, 

Yürek Atatürk! 

Bırakmadım.

Nasıl bırakırım seni nasıl! 

Sana alfabemi yazana, 

Dumlupınar, Sakarya’da yatana, 

Cephesine mermi çeken anaya, 

Sözüm var.

Yeminim var.

Karanlık can verene dek, 

Savaşçıyım.', 'Bırakamam seni kara tahtam. Yurdumun uçsuz bucaksız köylerine götürdüm. Susuz,  Yolsuz köylerine. Ayşeler tanıdım yalın ayak. Aydınlığa susa...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/savasci-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-i-brahim-erkal-fknpy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yağmur yağar ben yürürüm 

Gözlerini düşünürüm 

Sen yanımda olmayınca 

Üzülürüm, üzülürüm

Seviyorum allah için 

Yalanım yok seviyorum 

Seviyorum allahımdan 

Seni hergün diliyorum 

Yağmur yağar ıslanırım

Düşlerime yaslanırım 

Ben bir deli fişek gülüm

Sen gelince uslanırım.', 'Yağmur yağar ben yürürüm  Gözlerini düşünürüm  Sen yanımda olmayınca  Üzülürüm, üzülürüm Seviyorum allah için  Yalanım yok seviyorum  Seviyo...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Erkal']::text[], 8.5, '{"poet":"İbrahim Erkal","poet_slug":"i-brahim-erkal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yagmur-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maske', 'maske-reha-basogul-prhsi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'herbirimizin yüzünde 

çeşit çeşit maske

Doğduktan sonra

alınır bir tane

ölmeden önce 

satılır bin tane

herbirimizin yüzünde 

çeşit çeşit maske

benzemez 

hiçbiri birbirine

giyilir

duruma göre

herbirimizin yüzünde 

çeşit çeşit maske

görünce

göremezsin çirkinliğini

göremeyince

görürsün güzelliğini

herbirimizin yüzünde

çeşit çeşit maske

gün gelir

ağlar sevdiğine

gün gelir

güler sevmediğine

herbirimizin yüzünde

çeşit çeşit maske

bazen

doğruyu gizler

sevmediğinden

bazen

yanlışı ister

sevdiğinden

herbirimizin yüzünde

çeşit çeşit maske

gece

yokedilir varolanı

gündüz

varedilir yokolanı

herbirimizin yüzünde

çeşit çeşit maske

az bulunur

hep çıkarılamayanı

zor bulunur

hiç takılamayanı

herbirimizin yüzünde 

çeşit çeşit maske

kanmaz

kendisinin söylediğine

kanar

başkasının söylemediğine

herbirimizin yüzünde

çeşit çeşit maske

Ve böylece

gelir ki

ölüm döşeğine

karşılar herbirimizi 

karanlıktan bir maske

koyulur 

tüm maskeler öne

sorulur ki

uyar

bu duruma hangi maske

girer

tek başına kabire

istenir ki 

benzemelidir

herbirimize

doğarken giydirilene

herbirimizin yüzünde

çeşit çeşit maske', 'herbirimizin yüzünde  çeşit çeşit maske Doğduktan sonra alınır bir tane ölmeden önce  satılır bin tane herbirimizin yüzünde  çeşit çeşit mas...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/maske-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğuma Selam Söyle Anne', 'cocukluguma-selam-soyle-anne-hamdullah-arvas-0owdy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bu gün bayram anne

her şeye rağmen inanmak yani

umuda insanlığa güzelliğe

bu gün bayram

bir sızı var içimde

ince ve mavi

küçüldükçe küçülüyor yüreğim

bir sokak lambasında

kimsecikler yok

çocukluğum bile

çocukluğuma selam söyle anne', 'bu gün bayram anne her şeye rağmen inanmak yani umuda insanlığa güzelliğe bu gün bayram bir sızı var içimde ince ve mavi küçüldükçe küçülüyo...', ARRAY['Türk Edebiyatı','Şiir','Hamdullah Arvas']::text[], 8.5, '{"poet":"Hamdullah Arvas","poet_slug":"hamdullah-arvas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/cocukluguma-selam-soyle-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ziyaretçi', 'ziyaretci-seyit-ahmet-duzen-553b9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ziyretçi

Ziyaretçi kartı almadan giriyorum

İnsanların hayatına

Ziyaretçi kartı almıyorum ki! 

Tanısınlar bilsinler beni.

Eksikliğim kartım degil 

Birde barındıramıyorum

Aşk''ı içimde...

Bundandır.

Hep bir yanım boş, yaralı.

Dokunduğunda gözyaşlarim

Sırılsıklam bırakır boslugumu

Yine eksikliğim aglatiyor

Beni...

Agladıkça aşk''ı anımsayan.

Ziyaretçi saatlerini bilmiyorum.

Eşşref saatlerini de.

Onların...

Çalarım kapılarını açılmaz.

Eşiğinde beklerim kapının

Gelen olmaz

İçlerinde kalamıyorum.

Aşk''ta içimde...

Ziyaretçiyim  hayatlarina

Kabullenen olmaz..', 'ziyretçi Ziyaretçi kartı almadan giriyorum İnsanların hayatına Ziyaretçi kartı almıyorum ki!  Tanısınlar bilsinler beni. Eksikliğim kartım d...', ARRAY['Türk Edebiyatı','Şiir','Seyit Ahmet Düzen']::text[], 8.5, '{"poet":"Seyit Ahmet Düzen","poet_slug":"seyit-ahmet-duzen","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ziyaretci-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Doyulurmu', 'aska-doyulurmu-cahit-i-pekoglu-tuyeh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşk

doyuncaya kadar yaşanır gülüm.

Sen aşka

çok çabuk doydun''be gülüm.

Ben galiba

gerçek aşka doyamıyan biriydim.

Sen gerçekte

gerçek aşkı yaşayamadın gülüm...

Sorma bana sakın

sana aşkı anlatamam.

Onlarca sevgilerin içinde

insan bir kere aşık olur gülüm...

Sen aradın 

ne aradığını bilmeden inanki gülüm.

Şimdi anlıyorumki yaşamak istediğine

bile pişman oldun gülüm...

Aşk 

doyuncaya kadar yaşanır gülüm.

Aşkına hiç doyamadım

yaradan şahidimdir gülüm...', 'Aşk doyuncaya kadar yaşanır gülüm. Sen aşka çok çabuk doydun''be gülüm. Ben galiba gerçek aşka doyamıyan biriydim. Sen gerçekte gerçek aşkı y...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aska-doyulurmu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayallerim Hep Seninle', 'hayallerim-hep-seninle-cahit-i-pekoglu-d8ee3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Neden hep 

hayal kurarım bilemiyorum.

Yaşadıklarımdan çok

yaşayamadıklarımı hayal ediyorum.

Hayalimden, hayaline

yaşattıklarını helal et diyorum...

Yine ruhum sana bürünürken

Olmayacak bir hayal, kuruyorum.

Bayramda olsun seni görmeyi

hayal ederken.

Bırak görmeyi

hasret kaldığım, sesini bile duyamıyorum...

Neden hep

hayal kurarım bilemiyorum.

of allahım of

sevdiğimden kurtulamıyor, yine onu düşlüyorum.

Ruhu sanki beni esir almış

nefes aldığım her yerde onu hissediyorum...

Hayalinin, hayalime

artık sahip olduğunu düşünürken.

Nedendir bilemiyorum

gerçeğiyle değil, hayallerlemi yaşıyorum.

Neden hep

hayallerim seninle yaşıyor bilemiyorum...', 'Neden hep  hayal kurarım bilemiyorum. Yaşadıklarımdan çok yaşayamadıklarımı hayal ediyorum. Hayalimden, hayaline yaşattıklarını helal et diy...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hayallerim-hep-seninle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hesap Sorun', 'hesap-sorun-cahit-i-pekoglu-4288n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaybolan dünlerimemi

kaybolan yüreğimemi yanayım.

Yoksa bu uslanmaz 

sevdalı başamı vurayım.

Sorun, sorun bana hesap sorun 

eyyy sevenler...

Yüreğim görüyorsunuzki sınıfta kaldı

benimki tekrarı yaşanamayan bir aşktı.

Bu aşkta garip olan bendim

gerçek sınıf geçilecek yüreği seçemedim.

Sorun, sorun bana hesap sorun 

eyyy sevenler...

Aşkı oyun kılanla

sınıfımı geçmeye kalktım.

sevdim, sevdim yüreğimi verdim

zamansız açan, bir güle yenildim.

Sorun, sorun bana hesap sorun 

eyyy sevenler...', 'Kaybolan dünlerimemi kaybolan yüreğimemi yanayım. Yoksa bu uslanmaz  sevdalı başamı vurayım. Sorun, sorun bana hesap sorun  eyyy sevenler......', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hesap-sorun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Yelkenlisinde Bir Ömür', 'hayat-yelkenlisinde-bir-omur-onur-bozdag-tepvh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öleceğim günü bekliyorum

O günü bekliyorum sabırsızca

Belki de acizliğimdendir

Bunu bilemem ama

Bildiğim birşey var

Türküler acılarımı unutturmuyor artık

Yaralarımı daha da

Öyle bir deşiyor ki, Onun verdiği acılara katlanamıyorum.

Halbuki türküler benim ağrı kesicimdi

Ne zaman derdim olsa, 

Ya da ne zaman, 

Ayrılığının acısı bastırsa

Türkülere sığınırdım ben

Çünkü, 

Bütün türkülerde, 

Sen vardın benim için.

Kimi zaman, oğlunu kaybetmiş bir ana

Kimi zaman, sevdiğine kavuşamamış bir Mecnun...

Kimi zaman, hasretinden yanmış bir aşık

Kimi zaman, ezilmiş bir millet

Kimi zaman da yakılmış bir ozan...

Türkülerdeki seni sevdim ben.

Aslında türküleri, 

İçinde sen olunca sevdim.

Belki de bu yüzden, 

Acı veriyor artık türküler

Yani türkülerde hala sen varsın

Herşey aynı...

Tek fark, 

Bu ilacın yaptığı etki galiba

Önceleri beni mutluluğa götürüp, 

Acılarımı unutturuyordu

Şimdi ise zehir gibi, 

Beni yavaş yavaş öldürüyor.

Ama ben yine de, 

Vazgeçemem türkülerden

Dedim ya ölmeyi istiyorum diye...

Hayat çok garip aslında, 

O kadar fırtınalardan kurtuluyorsun, 

Bazen bütün umutların

Fırtınaya kapılıp gidiyor, 

Yine de hayatta kalmak, mutlu olmak için

Herşeyi yapıyorsun.

Gün geliyor, 

Bir anda herşeyden kurtulup, 

Ölmek istiyorsun.

Hasretin, özlemin gücü bu olsa gerek

Ya da ayrılığın açtığı yaranın acısı...

Bütün gece uyku girmiyor gözüme

Bütün gece, 

Ben fotoğrafına bakıyorum, 

Fotoğrafın bana

Ve bütün gün, 

Senden bir haber bekliyorum.

Hayallerimde mutlu dünyalar yok artık

Aslına bakarsan, 

Hayallerimde bir dünya var mı, 

Ya da hayallerim var mı? 

Cevap vermek zor.

Neden böyle olduğunu da

Anladığımı sanma

Ya da sana neden

Seni sevdiğimi söyleyemediğimi

Belki de her zaman

Aramızda engeller vardı...

Hayat bir yelkenliye benziyor biraz

Yani, 

Rüzgarın yönü belirler yönünü

Belki biraz da, 

Koca bir akarsuya...

Önüne ne gelirse gelsin

Akacak bir yol bulan

Ve durmadan akan, Zman gibi...

Hayat durmadan akıyor

Ve ben, 

Hayat yelkenlisinde, 

Meçhule doğru yol alıyorum.

Hayatın rüzgarı, 

Senden uzaklaştırıyor beni

Ama ne olursa olsun

Bu aşk bitmeyecek...

Belki birgün rüzgar kesilecek

O güne kadar, 

Hasretle bekleyeceğim seni

Gelmeyeceğini bildiğim halde...

Küçük umutlar, 

Yaşama sarılmama yetmiyor artık

Yani ben, 

Yine de ölmeyi istiyorum

Çünkü, 

Seni Çok Seviyorum', 'Öleceğim günü bekliyorum O günü bekliyorum sabırsızca Belki de acizliğimdendir Bunu bilemem ama Bildiğim birşey var Türküler acılarımı unutt...', ARRAY['Türk Edebiyatı','Şiir','Onur Bozdağ']::text[], 8.5, '{"poet":"Onur Bozdağ","poet_slug":"onur-bozdag","theme":"Türk Şiiri","is_hero":false,"total_lines":91,"source_url":"https://www.antoloji.com/hayat-yelkenlisinde-bir-omur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Milyonlarca Soru Kazınmış Hafızama', 'milyonlarca-soru-kazinmis-hafizama-seyit-ahmet-duzen-ygcq3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Milyonlarca soru kazınmış hafızama

Çocuklugumdan bu yana.

Bir türlü yanıtlayamadığım

Tükemedi sorularim.

Cavaplarım da  vardı, çok.

Çoçuk beynimle kavramaya çalışırdım.

Anne bu kim? _baba

Baba bu kim? _anne

Sonra kardeşliği öğrendim, kardeşlerimi.

Sevgiyi öğrendim zamanla sevilmeyi

Bu günse 

Hala cevapsiz sorularım var.

Anne aşk ne? 

Baba aşk ne? 

Dünden  yarına; sessiz kalmalar cevap.

Sorularımız yarına bulmaca

Bulmacalarımız tekerleme dilimizde.

Tekerlemelerimizle  kaynaşmıştık.

Unutuverdik aşkı.

Aşklarımız sahte

Sana sesleniyorum sevgili

Daha aslını öğrenmeden

Niye bu sahteçilik?', 'Milyonlarca soru kazınmış hafızama Çocuklugumdan bu yana. Bir türlü yanıtlayamadığım Tükemedi sorularim. Cavaplarım da  vardı, çok. Çoçuk be...', ARRAY['Türk Edebiyatı','Şiir','Seyit Ahmet Düzen']::text[], 8.5, '{"poet":"Seyit Ahmet Düzen","poet_slug":"seyit-ahmet-duzen","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/milyonlarca-soru-kazinmis-hafizama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Git', 'artik-git-onur-bozdag-n1i2t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Artık git...

O bütün ayrılığa teslim olmuşluğunla, 

Ellerini ellerimden, gözlerini gözlerimden, 

Ve boşvermişliğini sevgimden al git.

Ayrılığa esir et kendini

Ve beni...

Eğer bir gün sıkılırsan bu esaretten

Ya da korkarsan onun gücünden, 

Beni hatırla...

İşte ben o zaman; 

İkimizin de çok sevdiği, 

Yürümeyi yeni öğrenen çocukların

Masum ve saf gözlerinde bir bakış, 

İşte ben o zaman; 

Çatlamış toprak üzerinde

Nasırlaşmış ellerini gökyüzüne doğru tutmuş

Ve olmayan bulutlardan yağmur isteyen

Bir köylünün içindeki umut, 

İşte ben o zaman; 

Sevdasını yüreğine gömmüş

Ve yaşamın gereksizliğine kendini inandırmış

Çirkinliklerden bıkmış, 

İnsanların içindeki kötülüklerden korkmuş

Bütün güzellikleri, mutlulukları unutmuş

Ve bunları yaşamak isteyen

Fakat elinden hiç birşey gelmeyen, 

Bir aşık olacağım...

Belki baktığında göremeyeceksin beni, 

Belki de, 

Hiç bakmayacaksın.

Ama ne olur beni, 

Güzelliklerde hatırla

Ve eğer, 

Olur da özlersen beni birgün, 

Mutlaka buluşuruz aynı yerde.

Belki de, 

Buluşamayız, 

Bir Ömür Boyu...', 'Artık git... O bütün ayrılığa teslim olmuşluğunla,  Ellerini ellerimden, gözlerini gözlerimden,  Ve boşvermişliğini sevgimden al git. Ayrılı...', ARRAY['Türk Edebiyatı','Şiir','Onur Bozdağ']::text[], 8.5, '{"poet":"Onur Bozdağ","poet_slug":"onur-bozdag","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/artik-git-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Tutsağı', 'ask-tutsagi-onur-bozdag-izqy7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalbim seninle kaldı

Aşkım seninle kaldı

Hasret zaten benimleydi

Tel örgüler arkasında

Güneşim sahipsiz kaldı

Hayallerim yarım kaldı

Acılar zaten benimleydi

Kalın duvarlar arkasında

Anılar dışarda kaldı

Dostlar dışarda kaldı

Kuşlar zaten dışardaydı

Parmaklıklar arkasında

Gökyüzü uzakta kaldı

Balıkçılar dünde kaldı

Deniz zaten uzaktaydı

Gardiyanlar arkasında

Özgürlük imkansız kaldı

Türküler yarıda kaldı

Sevgi zaten vurulmuştu

Bir namlunun arkasında', 'Kalbim seninle kaldı Aşkım seninle kaldı Hasret zaten benimleydi Tel örgüler arkasında Güneşim sahipsiz kaldı Hayallerim yarım kaldı Acılar ...', ARRAY['Türk Edebiyatı','Şiir','Onur Bozdağ']::text[], 8.5, '{"poet":"Onur Bozdağ","poet_slug":"onur-bozdag","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ask-tutsagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram Sabahı', 'bayram-sabahi-salih-ozalasan-xvh6b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen hiç ağladınmı bayram sabahı

Herkesin gülüp oynadığı bir saatte

Sen gözyaşlarını gizledinmi sevdiklerinden

Hıçkırıklara boğuldunmu bir köşede

Yüreğin titredimi hiç 

Çocukların ellerini öptüğünde

Gözyaşını içine akıttınmı hiç

Öksüz yetim kimsesiz gördüğünde

Ben çok ağladım hemde çok

Bayram sabahlarında, arifelerde

Bayramlıklar giyildiğinde şen şakrak

Ben çok içimi çektim çok

Mezar taşlarına çok sarıldım

Ağıtlar yaktım anlamsızca göklere

Bazen isyan ettim kahırlandım

Ağlamaktan kan doldu gözlerime

Bayramlar ellere sevinç

Bana matem geçti ömrümce

Coşkulu bir bayram sabahı

Yaşamadım ben şöyle gönlümce

Yüreğim hep ezik 

Hasret yaşadım baba sevgisine

Bir bayram sabahı coşkulu

Tutunup gelemedim baba eline

Çocuklarım ne zaman sarılıp öpse

Bir hasret bir acı çöktü içime

İçim kan ağladı, sahte bir gülüş

Gözyaşımı akıttım hep içime

Bugün yine bayram, yine hüzün

Ne olur bakın şöyle öksüz yetime

Saçını okşamasanda, bakmasanda yüzüne

Bir kere olsun kendini koy yerine

Bilirmisin sen sarıldığında sevdiğine

Onların kan damlar yüreğine

Bir selam etsen mutluluk dolar

Onların küçücük yüreklerine

Bir versen bin verir yüce Tanrım

Yetime bir nebze mutluluk verdiğinde

Y.Tar.06-12-2002 Saat 16.42', 'Sen hiç ağladınmı bayram sabahı Herkesin gülüp oynadığı bir saatte Sen gözyaşlarını gizledinmi sevdiklerinden Hıçkırıklara boğuldunmu bir kö...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/bayram-sabahi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Sensiz', 'yine-sensiz-onur-bozdag-j34l6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayaller...

Benim hayallerim...

İçinde herzaman senin olduğun hayaller

Ben bile yokum bazılarında

Hayallerin iki kapısı var

Biri insanı gerçeğe ve yalnızlığa götürür.

Bu kapıdan geçince anlar insan

Hayatın boşluğunu...

Başarmaya uğraştığın her şey

Sana saçma gelir

Bazen insan kendini bile

Et ve keikten oluşan, 

Toprağın bir parçası, 

Ve günü geldiğinde, 

Teslim edilecek bir emanet sanar

Bu hayallerin bir de diğer kapısı var

Bu kapı da insanı, 

Diğer bir hayale götürür.

İnsan kendisinin ne olduğunu fark etmez, 

Nerede yaşadığını düşünmez, 

Ve kim olduğunu...

Hayat ona toz pembe gelir.

Hayal kurarken aklına gelmez insanın

Bir gün düşünceleri yüzünden, 

Birilerinin canı sıkılıyor diye, 

Ezileceği, susturulacağı, 

Hatta kalleşçe öldürüleceği...

Hayallerin en büyük ve en güzel malzemesi 

Aşktır...

Çünkü aşk bağımlılıktır, 

Aşk sensiz olmaktır, 

Aşk, 

Ders çalışmam gerekirken, 

Seni düşünüp şiir yazmaktır

Aşk hayal kurmaktır...

Hayallerin iki kapısı var; 

Biri insa nı gerçeğe, 

Diğeri başka bir hayale götürür.

İkinci kapıdan kaç kere geçersen geç, 

Sonunda birinci kapıdan mutlaka geçersin.

Ve mutlaka anlarsın hayatın boşluğunu...

Belki bir gün, 

Benim seni ne kadar çok, 

Ve karşılıksız sevdiğimi de anlarsın.

Ama neye yarar? 

Bir şairin dediği gibi: 

''Ağustos böcekleri bir mevsim yaşar''', 'Hayaller... Benim hayallerim... İçinde herzaman senin olduğun hayaller Ben bile yokum bazılarında Hayallerin iki kapısı var Biri insanı gerç...', ARRAY['Türk Edebiyatı','Şiir','Onur Bozdağ']::text[], 8.5, '{"poet":"Onur Bozdağ","poet_slug":"onur-bozdag","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/yine-sensiz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mor Aşk Baladı', 'mor-ask-baladi-tugba-gurelli-ykfhp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bacakları da kanar mı insanın deme bana ne olur

Beni senle yıka, beni sesinle yıka

Beni '''' mor teninle '''' yıka

Tanrının kuluyla yıkadığı gibi bedenini

Günahlarınla yıka beni.

Gözyaşları da yanar mı insanın deme bana ne olur

Arzu lekesi iç denizinde hayata döküldüğün gibi

'''' Çıplaklığın mor kuyularına '''' inip utanmadan

Iskalanmış dil uçlarınla sever gibi 

Sev beni.

Islığı da ağlar mı insanın deme bana ne olur

Gazoz kapağına yazıp aşkı kanat hayatın ''''mor dudağını ''''

- tanrı saç diplerinde gizliymiş -

Bir rol var ellerimin arasında ama ben değil

Kirpiklerimden güz damlıyor şimdi deniz mevsimi.

Rolünü iyi oynayan var mı peki aramızda?', 'Bacakları da kanar mı insanın deme bana ne olur Beni senle yıka, beni sesinle yıka Beni '''' mor teninle '''' yıka Tanrının kuluyla yıkadığı gib...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Gürelli']::text[], 8.5, '{"poet":"Tuğba Gürelli","poet_slug":"tugba-gurelli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mor-ask-baladi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Mavi', 'deli-mavi-gunes-kara-ycf47', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu sabah uyandığımda

Üstümde bir sonbahar hüznü

Seni düşünmekteyim	

Bir Ekim sabahı yatağımda, 

Çıkıvermen ansızın karşıma

Eski dostluğumuzun dönüşmesi aşka

Sevgi ile sarılman bana

Aniden gelmen İstanbul’a

Seni düşünmekteyim

Bu Ekim sabahında

Yatağıma uzanmış düşlerdeyim

Yaşamak dolu dolu aşkı

Uzaktan hissetmek sevgini

Kediciğim deyişini

Seni.. yalnız seni seveceğimi

Düşlemekteyim, bir sonbahar sabahında

DELİ MAVİ''mi', 'Bu sabah uyandığımda Üstümde bir sonbahar hüznü Seni düşünmekteyim	 Bir Ekim sabahı yatağımda,  Çıkıvermen ansızın karşıma Eski dostluğumuzu...', ARRAY['Türk Edebiyatı','Şiir','Güneş Kara']::text[], 8.5, '{"poet":"Güneş Kara","poet_slug":"gunes-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/deli-mavi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun Gece', 'yorgun-gece-sair-uney-s2mkm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Öyle yorgun ki bu yüreğim

Bir türküye sığınmak tek dileğim

Bir şiire okumak herşeyi



Bütün dünyayı örtün gözlerime

Soluğu kesilmiş bir akşam yağıyor üzerime

Başıma ağır ağır vuran bu hasretin

Paramparça bir ufku sunuyor ellerime...



Ellerim.

Ak gerdanında yolunu yitirmiş

Geceyi iyi eden ellerim.

Soğuktan bıçak kesilmiş gibi

Titrek ve sahipsiz.

Ben hangi yana dönsem şimdi

Hangi parkta otursam

Hangi vapura binsem

Hangi sahil bahçesinde

Kırık bir iskemleye çömelsem

Hangi yağmurun ıslattığı 

Soğuk gecede yollara düşsem

Ellerim dışarda ellerini özlerim...', 'Öyle yorgun ki bu yüreğim Bir türküye sığınmak tek dileğim Bir şiire okumak herşeyi Bütün dünyayı örtün gözlerime Soluğu kesilmiş bir akşam ...', ARRAY['Türk Edebiyatı','Şiir','Şair Üney']::text[], 8.5, '{"poet":"Şair Üney","poet_slug":"sair-uney","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yorgun-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Umut', 'son-umut-sair-uney-dd30w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Elveda en son umut

Saklı gülüşlerim

Dilimdeki son türkü

Bu kaçan son tren

Bahar çok uzak artık

Varıp varacağın son yer

Terkedilmiş ıssız bir liman



Savrulup giden yıllar

Uğuldayan bu deli rüzgar

İliklerime sinmiş yalnızlık

Son türkümü çağırıyor bana

Meleklerin kanadına yazılmış son türküm



Ki azalıyorum gitgide

Her akşam ruhumdan bir parçayı

Gözyaşlarım içinde salıyorum göğe

Ve ben azaldıkça azıyorum

Duramıyorum yerimde

Eli kanlı bir katil oluyorum

Umudu göğsünden vurulmuş

Yüreğimi parça parça ediyorum

Kaçıyorum hayattan öylece

Kendimden kaçıyorum



Hiçbir şey bağlamaz beni artık

Suskunluğumu bozuyorum

Ve haykırıyorum göğe



Ben bir iflah olmazım

Aşka meyil koymazım

Ne istiyorsunuz benden

Hiçbir kaba sığmazım...



Sığamasam da hiçbir yüreğe

Ve kalmadıysa da hiçbir umudum

Gideceğim öylece...

Gidebildikçe yürüyeceğim

Ve yürüyebildikçe düşleyeceğim...

Düşlerim sahipsiz kalmasın diye...', 'Elveda en son umut Saklı gülüşlerim Dilimdeki son türkü Bu kaçan son tren Bahar çok uzak artık Varıp varacağın son yer Terkedilmiş ıssız bir...', ARRAY['Türk Edebiyatı','Şiir','Şair Üney']::text[], 8.5, '{"poet":"Şair Üney","poet_slug":"sair-uney","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/son-umut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmamaya', 'unutmamaya-sair-uney-rd8o0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen her sabah bir 

Umut çiçeği açan yüreğinle

Şafağı arkana alıp

Bir ok gibi dalıyorsun günün içine



En ağır yükünü taşıyorken hayatın

Yorgunluk çöküyor üstüne

Issız bir geceyi düşlüyor dizlerin

Yüreğinde sıcaklığı bir elin



Böyle anlarda gülüşün kalıyor sadece

Etrafında dizilmiş masaların

Sonbahar yaprakları gibi sararmış

O kaygısız yüzlerinin üstünde



Sen orada öylece dururken ve hayatın

Dört bir yanına atarken kendini kimbilir

Penceresi açık hangi kalbe dokunursun

Dokunuşunun büyüsüyle hangi ölüyü diriltirsin



Dünyayı bir kartpostal resmiyle severken

Akşamın sofrasında yarına ertelenir gülüşlerin

Ay geceye bir yağmur gibi damlarken sen 

Söylenmemiş bir aşkın tınısını mırıldanırsın



Artık hiçbir şey için geç kalmış sayılmazsın sen

Soyun esmerliğini hayatın kirli yüzüne

Lal bir bakış kalsın, geriye bakmazsızın yürüdüğün 

Issız yollarını, her hatırlayışında  bu kentin...



Bu kent seni sol göğsünün altında taşırken

Hep bir ağustos sıcağıyla kaynayan yüreğinde

Nisan yağmurları hiç eksik olmasın........', 'Sen her sabah bir  Umut çiçeği açan yüreğinle Şafağı arkana alıp Bir ok gibi dalıyorsun günün içine En ağır yükünü taşıyorken hayatın Yorgun...', ARRAY['Türk Edebiyatı','Şiir','Şair Üney']::text[], 8.5, '{"poet":"Şair Üney","poet_slug":"sair-uney","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/unutmamaya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Rengin Hikayesi', 'uc-rengin-hikayesi-semsi-belli-5s7lw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni ilk gördügüm gün

Kırmızılar giymistin

Gözlerin alev alev

Seviyorum demistin

Hatırlar mısın? 

ikinci gördügüm gün

Yesiller giymistin

Yaprak gibi tazeydin

Beni bekle demistin

Hatırlar mısın? 

Seni son gördügüm gün

Sarılar giymistin

Solan ümitler gibi

Ve yanında baska biri

Kırmızıda aşkı, yesilde ümidi

Sarıda ihaneti gördüm

Kırmızı dudaklım, yesil gözlüm

Sarı saçlım aldattın beni

Ne çabuk unuttun sarkımızı

Gurbete gideni

Dönmez mi sandın?', 'Seni ilk gördügüm gün Kırmızılar giymistin Gözlerin alev alev Seviyorum demistin Hatırlar mısın?  ikinci gördügüm gün Yesiller giymistin Yap...', ARRAY['Türk Edebiyatı','Şiir','Şemsi Belli']::text[], 8.5, '{"poet":"Şemsi Belli","poet_slug":"semsi-belli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/uc-rengin-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmece', 'bilmece-semsi-belli-1wsvc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir güzel kız çocuğu var uzakta

Siyah gözlerinde nem

İsmi benim defterlerimde sık sık geçer

Ama size söyleyemem.

Bazen düşünürüm de geçen günleri.

Bir hoş olur ürperirim

''Ben çok kadın tanıdım ama

Onu fazla sevmiştim'' derim.

O güzel kız çocuğu şimdi kadındır

Günleri hem aşksız, hem tasasız

Kocası, evi çocukları vardır.

Biri oğlan, biri kız

Kim olduğunu sormayın... Söyler miyim hiç

Dallar kuruyunca eğilmez

Defterlerim, şiirlerim bilir onu sevdiğimi

Kendisi bile bilmez.', 'Bir güzel kız çocuğu var uzakta Siyah gözlerinde nem İsmi benim defterlerimde sık sık geçer Ama size söyleyemem. Bazen düşünürüm de geçen gü...', ARRAY['Türk Edebiyatı','Şiir','Şemsi Belli']::text[], 8.5, '{"poet":"Şemsi Belli","poet_slug":"semsi-belli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bilmece-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilir misin İbrahim Ethem''i?', 'bilir-misin-i-brahim-ethem-i-ahmet-agdere-b595e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O ki çıkarmıştır başından dünyevi tacı; 

Kudretini yaymak için ruh ve nefisine.

Feshetmiştir makam, akçe ve ordu gücünü,

Hükmetmek için, mücerret ruh ve bedenine.

Bırakmıştır ardında ince cariyeleri; 

Koklatmak için kendini sonsuz sevgiliye.

Ve gün gelmiş ki, söz geçirmiştir onun dili; 

İnsanlardan sonra balıkların yüreğine.', 'O ki çıkarmıştır başından dünyevi tacı;  Kudretini yaymak için ruh ve nefisine. Feshetmiştir makam, akçe ve ordu gücünü, Hükmetmek için, müc...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bilir-misin-ibrahim-ethem-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana', 'sana-berk-berk-m41uz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Özür dilerim...

Annesinin en değerli

Vazosunu kıran

Haylaz bir çocuk gibiyim 

Şimdi...

Suçunu bilen

Ancak

Sadece af dileyebilen, 

Korkak bir çocuk gibi...

Senden

Özür diliyorum...', 'Özür dilerim... Annesinin en değerli Vazosunu kıran Haylaz bir çocuk gibiyim  Şimdi... Suçunu bilen Ancak Sadece af dileyebilen,  Korkak bir...', ARRAY['Türk Edebiyatı','Şiir','Berk Berk']::text[], 8.5, '{"poet":"Berk Berk","poet_slug":"berk-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sana-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutku', 'tutku-hulya-arisan-mq4ss', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gecelik bir düş''tü, ne çılgınca öpüş''tü.

Saçlardan ayaklara, şehvetle dökülüştü...

Sanki beyaz zambaktı, nasıl ateşli baktı.

Açan iki tomurcuk bak, ellerimi yaktı...

Tenlerimiz kavuştu, tüm kanımız tutuştu.

Uçtuk başka âleme, ruhlarımız buluştu...

İstanbul,   Kasım 2002', 'Bir gecelik bir düş''tü, ne çılgınca öpüş''tü. Saçlardan ayaklara, şehvetle dökülüştü... Sanki beyaz zambaktı, nasıl ateşli baktı. Açan iki to...', ARRAY['Türk Edebiyatı','Şiir','Hülya Arısan']::text[], 8.5, '{"poet":"Hülya Arısan","poet_slug":"hulya-arisan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/tutku-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdam Deli Gibi', 'sevdam-deli-gibi-hulya-arisan-u4v1k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevdam deli gibi, 

Coşkun akan pınar gibi, 

Sıra dağlar duyun beni, 

Aşkımı verin geri.

Gözlerinin esiriyim, 

Kalbinin kölesiyim, 

Öyle bir sevdim ki seni

Ölene dek seninleyim.

İstanbul, 20 temmuz 2002', 'Sevdam deli gibi,  Coşkun akan pınar gibi,  Sıra dağlar duyun beni,  Aşkımı verin geri. Gözlerinin esiriyim,  Kalbinin kölesiyim,  Öyle bir ...', ARRAY['Türk Edebiyatı','Şiir','Hülya Arısan']::text[], 8.5, '{"poet":"Hülya Arısan","poet_slug":"hulya-arisan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevdam-deli-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler ve Ben', 'geceler-ve-ben-ahmet-ozturk-lnjc2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dört duvarlarda yalnızım

Karanlık hep yanıbaşımda volta atıyor

Ağlamayı unutan gözlerim bir kitap sayfalarında

Bir duvarlarda  bir de halımın dağınık püsküllerinde

Suskunluk bir silah gibi üzerimde

Çevreme korku salıyor doğrultmasam da kimselere

Kimseler ezbere yaşıyor haybeye  oynuyor

Ezberleyemediğimi farkedemiyorlar oyunlu sarmaşıklarından 

Ya da ilişemiyorlar 

Geceler o kadar uzun ve o kadar yürekten

Telaffuz edemediğim bir noktadayız

Geceler ve ben

Ne eski sevgililer ne de  eski dostlar

İkimiz yani

Ben, şehrin bütün ışıklarına isimler veriyorum

Geceler, gökteki bütün yıldızlara isimler veriyor

Şarkılar hep yavaş ve hep burası

Tufanlarda seyreden suskunluğum bir silah

Sadece beni vuruyor her seferinde

Beynimden aşağıya kanlar akıyor 

En ufak bir yaram yok sızacağı

Acının inkılabıdır geceyle omuz verip de çektiğimiz

(Kasım 2002)', 'Dört duvarlarda yalnızım Karanlık hep yanıbaşımda volta atıyor Ağlamayı unutan gözlerim bir kitap sayfalarında Bir duvarlarda  bir de halımı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Öztürk']::text[], 8.5, '{"poet":"Ahmet Öztürk","poet_slug":"ahmet-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/geceler-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çınar', 'cinar-ahmet-ozturk-hiwln', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Elleri bağlı bir çınarım şimdi

Hangi çiçek bilebilir sonbaharda solacağını

Hangi ağaç sonbaharda yapraklarını dökeceğini

Ya meczup nerden bilecek varlığındaki özün

Hayalleri filizlenmeden kaybolup gideceğini 

Yakacağı ağıtın boşa yanacağını

Hep kuru kalacak bir çınarım anladığım

Yapraklarım yok ki gözyaşı dökeyim

(00: 51)

(7 Aralık 2002)

(Cumartesi)

(Etiler)', 'Elleri bağlı bir çınarım şimdi Hangi çiçek bilebilir sonbaharda solacağını Hangi ağaç sonbaharda yapraklarını dökeceğini Ya meczup nerden bi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Öztürk']::text[], 8.5, '{"poet":"Ahmet Öztürk","poet_slug":"ahmet-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cinar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatın Dört Mevsimi', 'hayatin-dort-mevsimi-salih-ozalasan-z8o19', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Baharı yaşamak nede güzeldir değilmi

Oysa bir yılın vardır dört mevsimi

Sonbahar ne kadar sarartsada herşeyi

Bembeyaz karlar onun eseri değilmi

Sonbaharda olgunlaşıp dökülmese tohumlar

İlk baharda acaba ne yeşerirdi

Karlar altında kaynaşmasa toprakla

Lale sümbül böyle güzel kokarmı

İnsanda öyle değilmi

Onunda yokmu dört mevsimi

Çocukluk ve gençlik dönemi

Olgunluk ardından yaşlılık, artık ninemi dedemi

Hadi buradan çıkar at bakalım

Atabilirmisin hayatından bir dönemi

Yaşamaya mecbursun mutlaka 

Öyle yada böyle her dönemi

Elbet vardır çocukluğunu çok seven

Sor bakalım severmi, yoksulluk çekeni

Ya gençliğe ne demeli

Ya hiç olmamışsa onu seveni

Olgunluk dönemi bir başka alem

İyi bir eş yoksa giymiştir başına kefeni

Ya yaşlanıp ele muhtaç olmaya ne demeli

Yerlerde sürünür aç kalır yoksa iyi bir nesebi

Tanrı öyle bir denklem kurmuşki hayata

Mutlaka vardır herşeyin bir sebebi

Y.Tarihi 07.12.2002 saat 01.04', 'Baharı yaşamak nede güzeldir değilmi Oysa bir yılın vardır dört mevsimi Sonbahar ne kadar sarartsada herşeyi Bembeyaz karlar onun eseri deği...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hayatin-dort-mevsimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunsana', 'dokunsana-erkan-yanar-65six', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dokunsana yüreğinle fırtınalar kopan yüreğime

Görmüyor musun nasıl da bağırıyor

Seni seviyorum diye

Dokunsa gözlerime kendimi hapsettiğim gözlerinle

Görmüyor musun nasıl da ışıldıyor

Seni seviyorum

Dokunsana ellerime hiç bir zaman dokunamadığım ellerinle

Görmüyor musun nasıl da çağırıyor

Gel artık ne olur diye', 'Dokunsana yüreğinle fırtınalar kopan yüreğime Görmüyor musun nasıl da bağırıyor Seni seviyorum diye Dokunsa gözlerime kendimi hapsettiğim gö...', ARRAY['Türk Edebiyatı','Şiir','Erkan Yanar']::text[], 8.5, '{"poet":"Erkan Yanar","poet_slug":"erkan-yanar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dokunsana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gemi', 'gemi-salih-ozalasan-8it0u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şimdi kalktı bu limandan bir gemi

İçinde o kadar çoktuki gözü yaşlı gideni

Sanki uzaklara gitmek istemez gibiydi

Hep karaya kırılıyordu nedense dümeni

Vardı her halde içinde çok sevda çekeni

Belkide dostlarından ayrılmak istemeyeni

Ya çocuklarından ayrı, yada geride kalan anneleri

Sanki yas tutar gibiydi vallahi yelkeni

İçim burkuldu izledim bir köşeden

Ta uzaklardan duyuluyordu veda sireni

En arkalarda ağlayan belki bir sevgili

Elinde kenarları oyalı bir yemeni

Belkide içinden dua ediyordu

Kırılır inşallah gidemez dümeni

Kırılsa ne olacakki, 

Kalkacak bu limandan daha yüzlerce gemi

Y.Tar.07-12-2002 saat 22.35', 'Şimdi kalktı bu limandan bir gemi İçinde o kadar çoktuki gözü yaşlı gideni Sanki uzaklara gitmek istemez gibiydi Hep karaya kırılıyordu nede...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gemi-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-mahmut-beran-lzh9u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bahçeleriniz kalmadı.

Beton bloklarsınız yanyana.

Hergün biraz daha kuruyor teniniz, 

Irmağına küsen denizler gibi çölleşeceksiniz.

Suskunsunuz, 

Gökyüzü çiçeklerinin altında.

Gövdeli aşklarınız, 

Aynı ölçüde elbiseleriniz, 

ve yüreklerinizle, 

Evlerinize benziyorsunuz, 

Soğuk.

Şimdi bütün aynaları kırıyorsunuz.

yok, kalmadı bakacak yüzünüz.

Hayat, yeni intiharlara gidip gelirken, 

İnanmıyor artık hiçbir mazeretinize.

Düşlerinizde dar, eşyalarınız kadar.

O sehpanın bir ayağındada sizin eliniz var.', 'Bahçeleriniz kalmadı. Beton bloklarsınız yanyana. Hergün biraz daha kuruyor teniniz,  Irmağına küsen denizler gibi çölleşeceksiniz. Suskunsu...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Beran']::text[], 8.5, '{"poet":"Mahmut Beran","poet_slug":"mahmut-beran","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hayat-65-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyanın Hali', 'dunyanin-hali-alaaddin-kulcuoglu-wz2j8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dönmeye başlayalı yaşlı dünya

Çok şeyler yaşadı insanlar 

İki binli yıllarda

Uzay avucumuzda

Uzaklar yakın 

Ve doktorlar 

Ölümden döndürebiliyor insanı

Çok şeyler değişti dünyada

Bilim ve teknikle, sevgiyle

Ve binlerce yıldır

İnsan insan olalı 

Bazı şeyler hiç değişmedi

Değişmedi açlıklar savaşlar ve ölüm 

Değişmedi insanın insana yaptığı zulüm.', 'Dönmeye başlayalı yaşlı dünya Çok şeyler yaşadı insanlar  İki binli yıllarda Uzay avucumuzda Uzaklar yakın  Ve doktorlar  Ölümden döndürebil...', ARRAY['Türk Edebiyatı','Şiir','Alaaddin Külcüoğlu']::text[], 8.5, '{"poet":"Alaaddin Külcüoğlu","poet_slug":"alaaddin-kulcuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dunyanin-hali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'bahar...', 'bahar-ahmet-senkabak-8cr4a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'güneşi avuçlarınla basıp

akşamı ayaklarıma bırakıyorsun....sensizken

çekip gidiyor 

bulutlara gülümsemendeki göz izin

ben kendi ellerimle getirdiğim bu canı sana

sen sensizliği verip ödüllendiriyorsun', 'güneşi avuçlarınla basıp akşamı ayaklarıma bırakıyorsun....sensizken çekip gidiyor  bulutlara gülümsemendeki göz izin ben kendi ellerimle ge...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şenkabak']::text[], 8.5, '{"poet":"Ahmet Şenkabak","poet_slug":"ahmet-senkabak","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bahar-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 've', 've-ahmet-senkabak-k1f6m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 've hala daha 

seviyorum sanır

sabırdan kefen giydirdiğim

süslü yosma 

...

ne bilsinki

korpe umutlara kıragı çaldıgını....', 've hala daha  seviyorum sanır sabırdan kefen giydirdiğim süslü yosma  ... ne bilsinki korpe umutlara kıragı çaldıgını.......', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şenkabak']::text[], 8.5, '{"poet":"Ahmet Şenkabak","poet_slug":"ahmet-senkabak","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ve-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanık', 'sanik-nail-abbas-sayar-vy4rn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir kuş kanadı kırılır

Sorumlusu sanki benim

Kars''ta bir yiğit vurulur

Sorumlusu sanki benim 

Dana öküzü götürür

Ortaya yokluk oturur

Terzi el iğne batırır

Sorumlusu sanki benim

Vuranların kaçanların

Kardeş kanı içenlerin

Konanların göçenlerin

Sorumlusu sanki benim

Sekize bölünmüş dinin

Vietnam''a vuran Çin''in

Atoma sıkışmış kinin 

Sorumlusu sanki benim

İnek almaz, buzağ emmez

Koyun kurdu görür tınmaz

Aş, odun yok ocak yanmaz

Sorumlusu sanki benim

Tümünden suratlar asık

Tavanlar tabandan basık

Ceryan yok ışıklar kesik

Sorumlusu sanki benim', 'Bir kuş kanadı kırılır Sorumlusu sanki benim Kars''ta bir yiğit vurulur Sorumlusu sanki benim  Dana öküzü götürür Ortaya yokluk oturur Terzi ...', ARRAY['Türk Edebiyatı','Şiir','Nail Abbas Sayar']::text[], 8.5, '{"poet":"Nail Abbas Sayar","poet_slug":"nail-abbas-sayar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sanik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Kalan Bu Şehri Yakmayı Çok İstedim', 'sensiz-kalan-bu-sehri-yakmayi-cok-i-stedim-nurullah-genc-4bd2z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sensiz kalan bu şehri yakmayı çok istedim 

mavi bir aleve dönüştürdüm kalbimi bir anda 

tutuşturmak istedim beni böyle umarsız 

bırakıp gittiğin bu zalim şehri 

yakamadım gözlerin dikildi karşıma bir caddenin tam ortasında 

inanılmaz güzel bakıyordu gözlerime hafif ıslak 

en özel en bilinmeyen türleri açmıştı papatyaların 

hatıralarınla titriyordu içim kuşlar kanatıyordu gönlümü 

gri bulutlar geçiyordu göğümden 

anlamak üzreydim neron’un roma’yı neden yaktığını 

karanlık bir koridor açıldı önümde anlayamadım 

yenik düşmüş bir napolyon kadar mutsuzdum aslında 

intihara kalkışan hitler kadar çaresiz 

yakmak üzreydim ki bu şehri hatıraların 

içli bir yağmur gibi boşandı üzerime 

kediler geçti birden kavşaklarından şehrin 

acı acı miyavladılar gözlerime baktılar kızgındılar kırgındılar 

onlar da tutulmuşlar anladım sana bendeki kadar 

onlar da terk ettiğin bu şehri çaresiz 

yakmak istiyorlar yakamıyorlar 

saçların dikildi karşıma bir sokak köşesinde 

her telinde parmaklarımın izleri parlıyordu 

benzersiz kokunu alıyordu kıvrımlarından rüzgar 

gözleri doluyordu saçlarına bakan kedilerin 

her biri bir kenarda darmadağın 

çömelip kalıyordu yutkunuyordu 

rengi kaçıyordu pencerelerde perdelerin 

nereye yürüdüysem bakışın, duruşun, sesin 

anladım söndürmeliyim tutuşan yüreğimi 

kendimi yakmış olurum yakarsam bu şehri 

çünkü sen her şeyinle bendesin', 'sensiz kalan bu şehri yakmayı çok istedim  mavi bir aleve dönüştürdüm kalbimi bir anda  tutuşturmak istedim beni böyle umarsız  bırakıp gitt...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Genç']::text[], 8.5, '{"poet":"Nurullah Genç","poet_slug":"nurullah-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sensiz-kalan-bu-sehri-yakmayi-cok-istedim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk maskesi', 'mutluluk-maskesi-sair-aleyna-jzyav', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mutluluk maskesi takmışım yüzüme, 

Bakan aldanır o boş veren halime.

Her gören beni sözde mutluyum sanır, 

Akan suların altında yanan ateş mi aranır?', 'Mutluluk maskesi takmışım yüzüme,  Bakan aldanır o boş veren halime. Her gören beni sözde mutluyum sanır,  Akan suların altında yanan ateş m...', ARRAY['Türk Edebiyatı','Şiir','Şair Aleyna']::text[], 8.5, '{"poet":"Şair Aleyna","poet_slug":"sair-aleyna","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/mutluluk-maskesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Nedir Anne?', 'hayat-nedir-anne-yusuf-hayaloglu-g0htu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'benim hiç sapanım olmadı anne, 

ne kuşları vurdum, 

ne de kimsenin camını kırdım... 

çok uslu bir çocuk değildim ama, 

seni hiç kırmadım, hep boynumu kırdım. 

ben hayatım boyunca 

bir tek kendimi vurdum! .. 

suskun görünsem de, 

fırtınalı ve mağrurdum anne. 

bir mızrak gibi, 

aynada hep dik durdum anne! .. 

ben sana hiçbir gün laf getirmedim, 

leke sürmedim. 

ama göğsümü çok hırpaladım, 

kalbimi çok yordum... 

ben hayatım boyunca, en çok kendimi sordum! ... 

benim hiç sevgilim olmadı anne, 

ne bir yuva kurdum, 

ne bir gün şansım güldü... 

öpemeden bir bebeğin gidişini, 

tükendi gitti çağım... 

kimi yürekten sevdiysem, 

yüreğini başkasına böldü... 

bir muhabbet kuşum vardı, 

o da yalnızlıktan öldü... 

sen beni göğsünde 

hep acılarla mı soğurdun anne? 

yoksa evlat diye, 

koca bir taş mı doğurdun anne? 

eziyet değilim, zahmet değilim, 

musibet hiç değilim; 

bir senin mi balına sinek kondu, söylesene! 

doğurdun da beni, 

ne ile yoğurdun anne? 

benim hiç hayalim olmadı anne... 

ne seni rahat ettirdim, 

ne kendim ettim rahat... 

bir mutluluk fotoğrafı bile çektirmedi bu hayat! 

kaybolmuş bir anahtar kadar 

sahipsizim anne... 

ne omzumda bir dost eli, 

ne saçımda bir şefkat... 

say ki yollardan akan, 

şu faydasız çamurdum anne... 

say ki ıslanmaktım, üşümektim, 

say ki yağmurdum anne! 

bunca yıldır gözyaşlarını, 

hangi denizlere sakladın? 

oy ben öleyim, 

Sen beni ne diye doğurdun anne?', 'benim hiç sapanım olmadı anne,  ne kuşları vurdum,  ne de kimsenin camını kırdım...  çok uslu bir çocuk değildim ama,  seni hiç kırmadım, he...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Hayaloğlu']::text[], 8.5, '{"poet":"Yusuf Hayaloğlu","poet_slug":"yusuf-hayaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/hayat-nedir-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitti Ah Gitti', 'gitti-ah-gitti-yusuf-hayaloglu-cecxd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gitti ah.., 

gecelere hüzünleri serperek 

yarali bir kus gibi kanarcasina gitti.., 

yalvaran gözlerime, elemi pay ederek, 

bir kabahatmis gibi, kacarcasina gitti... 

gitti ah.. 

sarkilara bel baglamak faydasiz. 

üstüme kapilari kaparcasina gitti... 

gecenin geldigini haber vermeden; hirsiz... 

yasanmis bir ömrü calarcasina gitti 

gitti ah... bir nehirdi, 

yazamadigim siirdi. 

yüzüme son bir defa 

bakarcasina gitti... 

gitti ah... 

gözyaslari yanaklarimda kaldi. 

hayatin perdesini cekercesine gitti... 

belki doyulmamis toz pembe bir masaldi. 

gögsümden yüregini sökercesine gitti... 

gitti ah... 

karsilasmak ömür boyu imkansiz. 

beni hazanda koyup bahar dalina gitti... 

bilmiyorum ne yapsam, ne söylesem anlamsiz. 

ayrilmisti dünyamiz; kendi yoluna gitti... 

gitti ah... bir mevsimdi, 

cizemedigim resimdi. 

kalbime bir civiyi, 

cakarcasina gitti...', 'gitti ah..,  gecelere hüzünleri serperek  yarali bir kus gibi kanarcasina gitti..,  yalvaran gözlerime, elemi pay ederek,  bir kabahatmis gi...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Hayaloğlu']::text[], 8.5, '{"poet":"Yusuf Hayaloğlu","poet_slug":"yusuf-hayaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gitti-ah-gitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınım', 'kadinim-yasar-aslan-t2wlv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dudağımdan silinmeyen  yâra, 

Yalnızlığın resmini ben çizerim.

Sensizliğin çığlıklarına ben kulaç açarım.

Dudağından şarabı, 

Demli, demli ölümü ben içerim kadınım.

Sen rahat uyu 

geceye özlemi nakış, nakış dikerim... 

Sen rahat uyu 

ben sensizliği kana, kana içerim...', 'Dudağımdan silinmeyen  yâra,  Yalnızlığın resmini ben çizerim. Sensizliğin çığlıklarına ben kulaç açarım. Dudağından şarabı,  Demli, demli ö...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Aslan']::text[], 8.5, '{"poet":"Yaşar Aslan","poet_slug":"yasar-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kadinim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna Gibi', 'ayna-gibi-neslihan-ayakta-3ply0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gizlenmiş sesimin rengi, 

Sırlarım ele vermiş birden kendini.

Benliğim sulara düşmüş, 

Gümüş olmuş çayırların rengi.

Gökyüzünde bir kızıllık hükmediyor, 

Kuşların çığlıklarını duyuyorum.

Her birinin kanat sesi, 

Beni daha bir uzağa götürüyor.

Durmuş düşünüyor bir kız! 

Ona yaklaşamıyor

Sadece uzaktan uzağa seyrediyorum.

Öylesi düşünceli ki; 

Hiçbir şey düşünemiyor gibi.

Anlam arıyor kendince

Ve beni görünce seviniyor.

Gözlerimi açıyorum...

(07.11.99)', 'Gizlenmiş sesimin rengi,  Sırlarım ele vermiş birden kendini. Benliğim sulara düşmüş,  Gümüş olmuş çayırların rengi. Gökyüzünde bir kızıllık...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ayna-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Gozlum', 'kara-gozlum-neslihan-ayakta-dh8w0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Neden öyle bakıyorsun, anlamsızca

Anlasana kalbim hep senin yanında.

Etrafımda bir çok insan var ama, 

Gönlüm sana tutuldu bir anda.

Gözlerin oldu ilk aklımı çelen, 

Sözlerindi aklımdan silinmeyen.

Gidişindi beni kahreden, 

Anla artık gel yanıma.

Seni bir anda çözemezdim, 

Neden bir şans daha vermedin.

Kalbimi sana verdim.

Anlasana bütün kapılar açık sana.

Hediyeler anlamsız senin yanında

Gönlüm apansız bir uçurumda

Kavramlarım karıştı sen ortaya çıkınca

Anlasana anlamsız herşey sen olmayınca

(27.10.1998)', 'Neden öyle bakıyorsun, anlamsızca Anlasana kalbim hep senin yanında. Etrafımda bir çok insan var ama,  Gönlüm sana tutuldu bir anda. Gözleri...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kara-gozlum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'E Deger', 'e-deger-neslihan-ayakta-wshta', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Elinde olanın değerini bilmeyene

En iyi iyilik; 

Elindekini elinden almaktır! 

(01.11.99)', 'Elinde olanın değerini bilmeyene En iyi iyilik;  Elindekini elinden almaktır!  (01.11.99)...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/e-deger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarı Çalıntı', 'yari-calinti-neslihan-ayakta-q9eib', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sıkıldım herşeyden; 

Zevke veda herşeyde

Veda artık herşeye! 

Neden ki bilemiyorum; 

Vazgeçtim gözlerinden, 

Vazgeçtim kalmaktan! 

Giderim tutamaz kimseler beni, 

Giderim ne mutluluklar vardır.

Zorunluluklar zor değildir o zaman.

İşte o zaman güzeldir hayat.

Bir gün gelir, her zamanki gibi.

Bir gün gelir herşeyin sırası! ...

(02.11.99)', 'Sıkıldım herşeyden;  Zevke veda herşeyde Veda artık herşeye!  Neden ki bilemiyorum;  Vazgeçtim gözlerinden,  Vazgeçtim kalmaktan!  Giderim t...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yari-calinti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sus', 'sus-neslihan-ayakta-eevhh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüreğimden geçenleri

Söyleyemez ki sözlerim.

Gözlerime bakma sakın

Yalancıdır gözbebeklerim.

Ümidimi çalmışlar benden

Ne olur neden demesin sözlerin! 

(09.09.99)', 'Yüreğimden geçenleri Söyleyemez ki sözlerim. Gözlerime bakma sakın Yalancıdır gözbebeklerim. Ümidimi çalmışlar benden Ne olur neden demesin ...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sus-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yücelik', 'yucelik-neslihan-ayakta-3f7q9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Herkeste birşey, 

Gökyüzünde bir elalık, 

Saçlarımda gezen bir el var.

Gözlerimse bir çağlayana bakan, 

Kalbimde dört duvar bir aşk var.

Renkler zehir olmuş, 

Millet zevkte, alemde! 

Çatlamış dudaklar, 

Sözler tükenivermiş, 

Kulağımda bir ınıltı...

Ne gök var ne de mavi, 

Sevgi oluvermiş teali.

(02.11.99)', 'Herkeste birşey,  Gökyüzünde bir elalık,  Saçlarımda gezen bir el var. Gözlerimse bir çağlayana bakan,  Kalbimde dört duvar bir aşk var. Ren...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yucelik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Isimsiz', 'isimsiz-neslihan-ayakta-x2cgv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mutlu olmaktı herşey, 

Oysa içim hala kan ağlıyor! 

Gurur neymiş ki; 

Bu kadar acıtan gurur mu? 

Hayır elbette ki aşk! 

Aynalar küsmüş bana, 

Hiçbirşey gülmüyor buralarda.

Sevgi yüce, sevgi acımasız, 

Sevgim hep isimsiz bir diyarda! 

Kan ağlıyor isimsiz kalan sevgim.

Gün geçtikçe azalıyor gözyaşlarım.

Güçleniyorum, direniyorum ama beyhude! 

Dayanmak zorundayım bu gözyaşı seline.

Çağırıyorum o yari kollarıma.

Gelmiyor, kanıyor yaram yine! 

Şu ki hayal ise yarim; 

Giderim, kollarında hayal olmak isterim.

Bir hayal ki; hayal olmak, 

Bana kalır sevgisiz yaşamak! 

(25.11.99)', 'Mutlu olmaktı herşey,  Oysa içim hala kan ağlıyor!  Gurur neymiş ki;  Bu kadar acıtan gurur mu?  Hayır elbette ki aşk!  Aynalar küsmüş bana,...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/isimsiz-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan Sevgi', 'yalan-sevgi-neslihan-ayakta-3uw3e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karanlıkta yalanlarda kapanıyordu

Ama gün elbette ki doğacaktı.

Kuşların sesiyle gün uyandı, 

Yalanlar gözlerini açtı...

Ellerinde bir avuç sevgi vardı, 

Kollarında ise başka biri! 

Korkumun okları seni yaraladı, 

Gurur dediğin o saçma şey kaldı

Ve ellerindeki sevgiyi rüzgara bıraktı.

Ben yalnızlığın pençelerinde

Korkuma yenik düştüm

Sense kayboldun 

Gölgenle birlikte! 

(26.11.99)', 'Karanlıkta yalanlarda kapanıyordu Ama gün elbette ki doğacaktı. Kuşların sesiyle gün uyandı,  Yalanlar gözlerini açtı... Ellerinde bir avuç ...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yalan-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Perşembe', 'persembe-neslihan-ayakta-b0syk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir zaman ki o diyarda var olan, 

Bir zaman, 

Asla yetinemediğim.

Bir aşk ki sana duyduğum, 

Bir aşk; 

Asla yakalayamadığın.

Göklerdeki mavi o kadar berrak, 

Sen ki bu kadar ahval, 

Ben yüce bir boşlukta kaybolmuş...

Dünya kendi tekerinde, 

Dolunay hep o tarihte takılmış! 

Geri isterim çoğu anları.

Nafile bilirim, 

Çağıramam dudakları! 

Gözler kaçsada, bedenle uzak olsada, 

Yatağımdaki soğukla, gözlerimdeki yaşla

Uyuyacağım, mutlu rüyalara...

(27.11.99)', 'Bir zaman ki o diyarda var olan,  Bir zaman,  Asla yetinemediğim. Bir aşk ki sana duyduğum,  Bir aşk;  Asla yakalayamadığın. Göklerdeki mavi...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/persembe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı Bekleyiş', 'yalanci-bekleyis-neslihan-ayakta-wcge9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sessizliğin sesini bekle! 

Bir ışık doğacak inan.

Kulaklarımda şen kahkahalar var.

Soluk dallara serpilmiş renkli çiçekler gördüm, 

Suyun içinde yanan ateş

Ama göklere bakınca hep mavi gördüm hep

Diyenler yalan söylemiş; 

Sen yoksun, adın yazmıyor orada! 

Ben varım, özgürlük kokuyor anla.

Söyleyemez çiçekler gerçekleri

Avutursun hep kendini, 

Kedini alır okşarsın, 

Bir de yağmura bakarsın, 

Dakikaları sayıp yatağa yaklaşırsın! 

Boştur kurulan hayaller, 

Göğe varıp kendini ararsın...

(27.11.99)', 'Sessizliğin sesini bekle!  Bir ışık doğacak inan. Kulaklarımda şen kahkahalar var. Soluk dallara serpilmiş renkli çiçekler gördüm,  Suyun iç...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yalanci-bekleyis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Tanınmıyor', 'sevgi-taninmiyor-neslihan-ayakta-xhynn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerdi herşey

Ama bir dokunuş değildi sevgi! 

Gözlerime baksaydın bir kere, 

Kendini görmeyi deneseydin

Anlayacaktın sevgiyi! 

Çünkü sendin gözlerimdeki, 

Çünkü sevgiydi gözlerim.

Dudaklarımdaki izler sana ait değildi, 

Olmadı hiçbir zaman! 

Yalnız rüzgarın marifetiydi.

Saçlarımıza dokunan hep ellerindi, 

Keşke sen olsaydın dokunan.

Bir de hiç aşkım olamadın

Sadece aşkımı sahiplenen bencildin.

Bir sevgi yaşamaya çalıştım, 

Senin sevgiyi  tanımadığını anladım...

(28.11.99)', 'Gözlerdi herşey Ama bir dokunuş değildi sevgi!  Gözlerime baksaydın bir kere,  Kendini görmeyi deneseydin Anlayacaktın sevgiyi!  Çünkü sendi...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevgi-taninmiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılış', 'ayrilis-neslihan-ayakta-2s2o3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Demek başka biri var

Zaten ben de ayrılmayı düşünüyordum.

Güle güle git, arkana da bakma! 

Delikanlı gider...

Genç kız söylenir; 

Başka biriymiş

Zaten sevgi diye de birşey yok! 

Ama neden içim acıyor...

Hayır onu seviyor olamam! 

Delikanlı ise şaşkındır; 

Niye hiç tepki vermedi

Demek ki bu kadar basitti diye düşünür.

Sevgi böylece gönülden gönüle, 

Elden ele saklanır

Ve herkes mutlu olmaya çalışır.

(20.12.99)', 'Demek başka biri var Zaten ben de ayrılmayı düşünüyordum. Güle güle git, arkana da bakma!  Delikanlı gider... Genç kız söylenir;  Başka biri...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ayrilis-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suskun Duvarlar', 'suskun-duvarlar-levent-kizildag-0p0xd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sus 

tüm denizler dinlesin

gecelerin sessizligini.

aşk bir dalga gibi çarpar labirentlere

sevgi, en derinden gelir, 

ve en olmazından hayallerin.

bir de lacivert gecelerdeki, 

suskun duvarlar.

Onlar, göçmen kuş sürüleri, 

Aşıp gider yarınları.

10.02.2002', 'Sus  tüm denizler dinlesin gecelerin sessizligini. aşk bir dalga gibi çarpar labirentlere sevgi, en derinden gelir,  ve en olmazından hayall...', ARRAY['Türk Edebiyatı','Şiir','Levent Kızıldağ']::text[], 8.5, '{"poet":"Levent Kızıldağ","poet_slug":"levent-kizildag","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/suskun-duvarlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lime Lime Sevdalar', 'lime-lime-sevdalar-levent-kizildag-5koqd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İsterse

Senden essin tüm rüzgarlar, 

Zaten ümit dediğin ne ki? 

Hepsi hepsi bir kuru dalga

Hayat denizinde.

Engel olurmu acaba? 

Yosunlaşmış aşklar, 

And içilmiş yarınlara, 

Lime lime sevdalara.

10.01.2002', 'İsterse Senden essin tüm rüzgarlar,  Zaten ümit dediğin ne ki?  Hepsi hepsi bir kuru dalga Hayat denizinde. Engel olurmu acaba?  Yosunlaşmış...', ARRAY['Türk Edebiyatı','Şiir','Levent Kızıldağ']::text[], 8.5, '{"poet":"Levent Kızıldağ","poet_slug":"levent-kizildag","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/lime-lime-sevdalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teslim-i Aşk', 'teslim-i-ask-sabri-gurbuz-tnkeo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir giysi al üzerine

İstersen saatlerce konuşalım

Rengini ve yakışıp yakışmadığını

Trafiği durdurmak 

Ve rahatça karşıya geçmek için

İtikleyiver ansızın beni yola

Ağlamak veya sığınmak için

Göğsüme yaslan yıllarca

Veya bıçakla, hiç düşünmeden

Konuş hiç durmadan

İstersen duvar, istersen onayın olurum

Öfkene de küfrüne de açık kulağım

Nereye koyarsan dünyanda

Ben orada bir bibloyum

Emrine hassas robotum istersen

Ne romandan çıkma aşığım

Ne de içimde köle isyanı taşırım

Sadece seni severken varım

                         7-12-2002', 'Bir giysi al üzerine İstersen saatlerce konuşalım Rengini ve yakışıp yakışmadığını Trafiği durdurmak  Ve rahatça karşıya geçmek için İtikley...', ARRAY['Türk Edebiyatı','Şiir','Sabri Gürbüz']::text[], 8.5, '{"poet":"Sabri Gürbüz","poet_slug":"sabri-gurbuz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/teslim-i-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buğuya İsmin', 'buguya-i-smin-sabri-gurbuz-rc7qh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Penceremin eriyen buğusuna

İsmini titreyen ellerim yazdı

Dışardaki fırtına ve yağmuru

İçimdeki hasret ateşi sardı

                        8-12-2002', 'Penceremin eriyen buğusuna İsmini titreyen ellerim yazdı Dışardaki fırtına ve yağmuru İçimdeki hasret ateşi sardı                         8-...', ARRAY['Türk Edebiyatı','Şiir','Sabri Gürbüz']::text[], 8.5, '{"poet":"Sabri Gürbüz","poet_slug":"sabri-gurbuz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/buguya-ismin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cezb-i Endam', 'cezb-i-endam-sabri-gurbuz-gzl7u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kerratla şamar aşkeder fırtına

Al döker yanağa bu cebri hava

Yanar dide kısık bakar etrafa

Yinede cezbolur gönül endama

                      8-12-2002', 'Kerratla şamar aşkeder fırtına Al döker yanağa bu cebri hava Yanar dide kısık bakar etrafa Yinede cezbolur gönül endama                     ...', ARRAY['Türk Edebiyatı','Şiir','Sabri Gürbüz']::text[], 8.5, '{"poet":"Sabri Gürbüz","poet_slug":"sabri-gurbuz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/cezb-i-endam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaktı Geçti', 'yakti-gecti-sabri-gurbuz-nr1j9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kandil elinde bir aşina endam geçti

Kandil ateşi ölürken o yaktı geçti

Sessiz hayali kaldı, adı aşka geçti

O zehrini bilmeden derdi saçtı geçti

  

                         8-12-2002', 'Kandil elinde bir aşina endam geçti Kandil ateşi ölürken o yaktı geçti Sessiz hayali kaldı, adı aşka geçti O zehrini bilmeden derdi saçtı ge...', ARRAY['Türk Edebiyatı','Şiir','Sabri Gürbüz']::text[], 8.5, '{"poet":"Sabri Gürbüz","poet_slug":"sabri-gurbuz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yakti-gecti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Prangalı Hasretin', 'prangali-hasretin-onur-bozdag-vg5dw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine aynı masa, yine aynı lamba

Ve yine aynı ben...

Değişen sen misin yoksa? 

Ben kaybettim artık bütün umutları

Ben, seni götüren minibüsün kalktığı durakta

Arkandan el sallayan sapsarı bir yaprağım artık

Ama ruhum yine loş, yine soğuk

yine havasız düşünceler hücresinde

Ve kalbimde prangalar...

Bu hüzün biter birazdan

Yine seni düşünürken uyur kalırım

Kimbilir belki seni görmem bu gece rüyamda

Ve rahatça uyurum

Yine seni görürsem rüyamda

Tamamdır artık...

Yine aynı kabus, yine aynı karabasan

Yine aynı, 

Bir metre uzağımdayken, ve dilimin ucundayken

Seni seviyorum cümlesi, 

Kilometrelerce uzağımda olman...

Seni sevdiğimi aslında türkülerde haykırdım ben

Neyse, 

Beni tanırsın sen.

Belki de tek sen tanırsın...

Ben yine aynı ben...

Allah kahretsin bütün insanları diyemiyorum

Allah kahretsin sen varsın.

Ama ben mahkumum bu mutsuzluğa

Belki de bu yüzden yaklaşamıyorum sana

Ve belki de bu yüzden söyleyemiyorum

Seni sevdiğimi...

Ve bakamıyorum o herzaman gülen gözlere

O öldüren bakışlara

Seni saçma sapan birkaç kelimeyle anlatmak, 

Ne kadar mantıksızsa, 

Bütün sevgi dolu sözlerde, cümlelerde

şiirlerde seni ve sana olan aşkımı görmek, 

O kadar mantıklı.

Gece hep sana yazılacak artık.

ve birgün vuslatı yakalarsak, 

Acısını çıkartırız bütün mutsuzlukların

Yıldızları sayarız geceleri, 

Ve aşkımızı türküler anlatır o zaman

Bunlar uzak şimdilik.

Şimdilik sadece hasret yolcusuyum ben.

Emekçi''nin dediği gibi: 

''Ahmed Arif hasretinden prangalar eskitmiş ya, 

Beni böyle eskiten de prangalı hasretin''

Belki bitanem, 

Kırarım bu prangaları birgün.

İşte o gün kuşlar mutluluğa havalanır', 'Yine aynı masa, yine aynı lamba Ve yine aynı ben... Değişen sen misin yoksa?  Ben kaybettim artık bütün umutları Ben, seni götüren minibüsün...', ARRAY['Türk Edebiyatı','Şiir','Onur Bozdağ']::text[], 8.5, '{"poet":"Onur Bozdağ","poet_slug":"onur-bozdag","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/prangali-hasretin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda', 'elveda-murat-hakki-yasar-6wd2a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Haydi gel 

Yoksa kaybolacağım karanlıklarda

Belki sisli bir kış gecesi 

Belki hüzünlü bir sonbahar akşamı

Cesedimi bulacaklar camurlar arasında

Gelip sana haber verecekler

Şaşıracaksın...

Bir elinde resmin 

Bir elinde silahı vardı diyecekler

İnanmıyacaksın. 

Kalkıp geleceksin sonra bana

Cesedimi görünce taş kesileceksin 

Senin için neler çektiğimi bir bir anlayacaksın 

Tutup ellerimden af dileyeceksin 

Affet beni 

Seni çoktan affettiğimi

Bilmeyeceksin 

Eğilip sarılacaksın soğuk bedenime

İşte o an bir fısıltı duyacaksın

Dudaklarımdan ELVADA

(KONYA/ILGIN

07.12.2002)', 'Haydi gel  Yoksa kaybolacağım karanlıklarda Belki sisli bir kış gecesi  Belki hüzünlü bir sonbahar akşamı Cesedimi bulacaklar camurlar arası...', ARRAY['Türk Edebiyatı','Şiir','Murat Hakkı Yaşar']::text[], 8.5, '{"poet":"Murat Hakkı Yaşar","poet_slug":"murat-hakki-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/elveda-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki gözüm', 'i-ki-gozum-mehmet-akalin-tr9bx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İki gözüm; 

kokunu özledim, 

girdim yatağıma 

tenin geldi aklıma.

Tenini birde terini özledim...

        

      (14.11.1999-Erzincan)', 'İki gözüm;  kokunu özledim,  girdim yatağıma  tenin geldi aklıma. Tenini birde terini özledim...                (14.11.1999-Erzincan)...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akalın']::text[], 8.5, '{"poet":"Mehmet Akalın","poet_slug":"mehmet-akalin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/iki-gozum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem''e', 'ozlem-e-mehmet-akalin-61ow5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tut ellerimi tut, 

yüreğimi al, beni al.

Seni özledim ben, 

al bende ne varsa Özlem, 

seni ver...

     (18.11.1999-Erzincan)', 'Tut ellerimi tut,  yüreğimi al, beni al. Seni özledim ben,  al bende ne varsa Özlem,  seni ver...      (18.11.1999-Erzincan)...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akalın']::text[], 8.5, '{"poet":"Mehmet Akalın","poet_slug":"mehmet-akalin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ozlem-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlıyorsun Ama...', 'anliyorsun-ama-onur-bozdag-0hq6i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşamın ne tuhaf bir bilmece olduğunu sen anlıyorsun

Aslında anlıyorsun, bir zaman sonra

Konuşmalarda sesim çatal çatal olduğunda, 

Çözümsüz yalnızlıklarda dalıp gittiğimi...

Anlıyorsun yanlmıyorum

Ama beni anlaman gücüme gidiyor

Çünkü anlıyorsun, ve yoksun

Anlıyorsun, ve gelmiyorsun hepsi bu...

Biliyorsun, herşeyi biliyorsun

Sensiz geçen günlerin karabasanlara, 

Apansız çığlıklara dönüştüğünü...

Anlıyorsun yanılmıyorum

Biliyorsun sen bu değilsin...

Gözlerim biraz daldığında

Sıcak öpüşlerle gülümsemeliydin korkularıma

Aşkın hiç bilinmeyen resmi olmalıydı yüzümüz

Ve geceleri...

Işık demetleriyle gelen hayaller biriktirmeliydik

Ayrı olsak bile...

Senden ayrılmak nasıldır düşünemiyorum

Hiç ayrılmadık biz.

Çünkü hiç kavuşmadık...

Ayrılmak herhalde bir lambayı kapatmak gibi, 

Yani kapatmak için açmış olmak lazım.

Ve insanlar da öyle...

Aydınlığı anlaması için karanlığı, 

İyiliği anlaması için kötülüğü, 

Sevgiyi anlaması için nefreti, 

Göstermek gerek, 

Biliyorum...

Sen bunların hepsini biliyorsun yanılmıyorum

Ama beni anlaman gücüme gidiyor, 

Çünkü anlıyorsun, yoksun...

Aşkı kendi rengiyle taşımak vardı.

İçimizi sancılar bastığında, 

Ve avuçlarımızda sıcaklığımızla erirken keder

Yürümek vardı kimselerin bilmediği yerlere...

Öylesine hesapsız, 

Öylesine beklenmedik.

Yürümek vardı...

Yağmurda sessizliğe doğru.

Benim sessizliğim bir çığlıktı

İşte bu sessizlikte, 

Ama sen anlamadın...

Bir tek bunu anlamadın, 

Anlamadın, ve yoksun...

Hepsi bu.', 'Yaşamın ne tuhaf bir bilmece olduğunu sen anlıyorsun Aslında anlıyorsun, bir zaman sonra Konuşmalarda sesim çatal çatal olduğunda,  Çözümsüz...', ARRAY['Türk Edebiyatı','Şiir','Onur Bozdağ']::text[], 8.5, '{"poet":"Onur Bozdağ","poet_slug":"onur-bozdag","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/anliyorsun-ama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Dost', 'ey-dost-mehmet-akalin-hzuqu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey dost; 

güzel dost.

İncitme, kırma

benim sende kalan

emanetimi.

Beni kırma, burkma yüreğimi...

    (19.11.1999-Erzincan)', 'Ey dost;  güzel dost. İncitme, kırma benim sende kalan emanetimi. Beni kırma, burkma yüreğimi...     (19.11.1999-Erzincan)...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akalın']::text[], 8.5, '{"poet":"Mehmet Akalın","poet_slug":"mehmet-akalin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ey-dost-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Gözlü Yar', 'guzel-gozlu-yar-mehmet-akalin-5t0bd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güzel gözlü yar, 

nedem seni? 

Sevdan bir yangın, 

yürekte açan bir karanfil, 

adın özlem senin.

Alıp saram seni, 

öpem gözlerinden...

   (11.12.1999-Erzincan)', 'Güzel gözlü yar,  nedem seni?  Sevdan bir yangın,  yürekte açan bir karanfil,  adın özlem senin. Alıp saram seni,  öpem gözlerinden...    (1...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akalın']::text[], 8.5, '{"poet":"Mehmet Akalın","poet_slug":"mehmet-akalin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/guzel-gozlu-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanmda Olsaydın', 'yanmda-olsaydin-mehmet-akalin-qctji', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yanımda olsaydın 

solgunlaşmazdı bu yüz, 

aramazdı umudu yollarda

hastalıklı ağlamaklı göz.

Tepeden tırnağa özlem olmazdı.

   (16.09.2000-Erzincan)', 'Yanımda olsaydın  solgunlaşmazdı bu yüz,  aramazdı umudu yollarda hastalıklı ağlamaklı göz. Tepeden tırnağa özlem olmazdı.    (16.09.2000-Er...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akalın']::text[], 8.5, '{"poet":"Mehmet Akalın","poet_slug":"mehmet-akalin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yanmda-olsaydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Yıldızın', 'senin-yildizin-sair-karagozlum-1pe4g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gece olmus

karanlik kaplamis dünyani

yine yalnizliginla basbasasin

herzamanki gibi

gökyüzüne bak isil isil

parlayan bir yildiz var

bhep yanindadir ezelden beri.', 'Gece olmus karanlik kaplamis dünyani yine yalnizliginla basbasasin herzamanki gibi gökyüzüne bak isil isil parlayan bir yildiz var bhep yani...', ARRAY['Türk Edebiyatı','Şiir','Şair Karagözlüm']::text[], 8.5, '{"poet":"Şair Karagözlüm","poet_slug":"sair-karagozlum","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/senin-yildizin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Arkadaşım', 'canim-arkadasim-sair-karagozlum-g6zib', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Canim arkadasim

tek dertortagim

sende olmasan

derdimi kiminle paylasirim

dermanimi kimde ararim

iyiki varsin 

canim arkadasim

sende olmasan

kim ceker derdimi

su ücgünlük dünyada tek varligim', 'Canim arkadasim tek dertortagim sende olmasan derdimi kiminle paylasirim dermanimi kimde ararim iyiki varsin  canim arkadasim sende olmasan ...', ARRAY['Türk Edebiyatı','Şiir','Şair Karagözlüm']::text[], 8.5, '{"poet":"Şair Karagözlüm","poet_slug":"sair-karagozlum","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/canim-arkadasim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '13-9', '13-9-tahir-ehad-ozar-xnxsm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'tırtılın ayak izleri

kutsanmış adımlar üzerine

ya da kandırılışlıklar nedeniyle

kelebeklerin uzun özlemli

tek varlıklı yaşamsal haklarına

tecavüzden kaçınarak

hissetmek ayak izlerini

dilemekten korkarak 

istemek', 'tırtılın ayak izleri kutsanmış adımlar üzerine ya da kandırılışlıklar nedeniyle kelebeklerin uzun özlemli tek varlıklı yaşamsal haklarına te...', ARRAY['Türk Edebiyatı','Şiir','Tahir Ehad Ozar']::text[], 8.5, '{"poet":"Tahir Ehad Ozar","poet_slug":"tahir-ehad-ozar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/13-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Utandırmasın', 'ask-utandirmasin-mahmut-temizyurek-8wbaq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ey kente tutsaklığımı duyuran bahar 

soluğumu kırağıya düşerken saf 

bakışımı tahliyeci kızların yüzü  gibi tuhaf yakaladın 

bana aşkın yeşil yaylasını da söyle 

Aşk! ayırmak kalabalıktan kalbini 

Serseri kalbim savuracak beni çarptıkça 

uygar beynimi yora zora 

Bağrı yumuşak kayaların rahminde uyuyup 

yeraltı sularının yolunda yürüyecek 

geride kalacak sennehri, bennehri ve siznehri 

Güvenilir arkadaş. İyi kılavuz 

dipsiz göz nehrinin yatağı 

Nem ve gövdenin 

ten ve dalganın ve harlayan hayatın cebri 

silip atacak üzerimden dünyanın kuburunu 

bana geçmişten ne kibir ne rant 

korkunç hayret vadisinde 

yitik vadide 

Aşk utandırmasın kimseyi 

Dün çok yakın / Yarın 

Uzakbıraksakın''dan sonraysa 

ya HazırolMamak ya TekmilDiyar''ın

bakır kazanlarına konmaksa 

varmak değil, aslolan varolmaksa 

Aşk utandırmasın kimseyi. 

(İz ve Rüya)', 'Ey kente tutsaklığımı duyuran bahar  soluğumu kırağıya düşerken saf  bakışımı tahliyeci kızların yüzü  gibi tuhaf yakaladın  bana aşkın yeşi...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Temizyürek']::text[], 8.5, '{"poet":"Mahmut Temizyürek","poet_slug":"mahmut-temizyurek","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ask-utandirmasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakar Mısın?', 'bakar-misin-berk-berk-nod9m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sanki bir hafiflik war

Üzerimde...

Bir eksiklik...

Bir şey unutmuş

gibiyim...

Acaip görüyorum etrafı...

Anlamsız ve 

Soğuk bakışlarım...

Bir bakar mısın? 

Yoksa ruhumu 

Sizde mi bıraktım?', 'Sanki bir hafiflik war Üzerimde... Bir eksiklik... Bir şey unutmuş gibiyim... Acaip görüyorum etrafı... Anlamsız ve  Soğuk bakışlarım... Bir...', ARRAY['Türk Edebiyatı','Şiir','Berk Berk']::text[], 8.5, '{"poet":"Berk Berk","poet_slug":"berk-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bakar-misin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerimiz', 'ellerimiz-berk-berk-s6q5x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bakışlarda umutsuzluk vardı

Sanki giderken...

Bir hoşçakalı bile

Çok gördük birbirimize...

En kötüsü 

Ellerimizdi...

Ayrılmamak için 

Kenetlendiklerinde

Birbirlerine...', 'Bakışlarda umutsuzluk vardı Sanki giderken... Bir hoşçakalı bile Çok gördük birbirimize... En kötüsü  Ellerimizdi... Ayrılmamak için  Kenetl...', ARRAY['Türk Edebiyatı','Şiir','Berk Berk']::text[], 8.5, '{"poet":"Berk Berk","poet_slug":"berk-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ellerimiz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin Getir', 'gozlerin-getir-ali-kinik-iyjrv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerini getri yarı umtsuzluguma

Yaprak gibi döküleyim önüne

Solayım, beter olayım

Gözlerini getir, 

Öleyim...

Bilmeden çocukça sevildigini, 

Ve bayram sabahınca beklendigini, 

Kaf Dagı''ndan güneş getirir gibi, 

Gözlerini getir.

Getir gözlerini, 

Öleyim...

Kimsesizim İlk kez bu kadar suskunum

Sana söyleyemiyorum

Yıldızlara uzanmışım her akşam

Ve baglanmış

Ve kınanmış

Ve karşında hep yitirmişim

Ne olur

Gözlerini getir

Öleyim...

Ben biraz şairim, biraz divane

Çarmıha gerseler öldüremezler

Sırrım saçımda degil yüregimdedir

İstersen dost, istersen düşman gibi

Gözlerini getir

Ustam! getir gözlerini 

Öleyim..

Ben yine kaybettin, görmüyormusun? 

Şafak yangınından yaralı çıktım

Ve ben ustam, 

Gözlerinle yakılası bir şiire başladım

Kaçtıkça sana döndüm

Ve artık gülü bıraktım, 

Menekşe yapragını

Kitaplarımı, 

Suskun maceramı...

Bu şiir bitsin

Bana, peşinş bıraktıgım bir hayatı degil, 

Gözlerini getir.

Ustam! getir gözlerini, 

ÖLEYİM...', 'Gözlerini getri yarı umtsuzluguma Yaprak gibi döküleyim önüne Solayım, beter olayım Gözlerini getir,  Öleyim... Bilmeden çocukça sevildigini...', ARRAY['Türk Edebiyatı','Şiir','Ali Kınık']::text[], 8.5, '{"poet":"Ali Kınık","poet_slug":"ali-kinik","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/gozlerin-getir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Sokaklarda', 'bu-sokaklarda-adem-bozdag-zu0mz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben hayatı bu sokaklarda öğrendim

Aşkı dostluğu ve acılarıda

Ben senin bakışlarını  sevdim

Yağmur çiselerken

Bana gülümsemeni

Tak tak ayak sesleri, 

Kalbimi hızlandıran nefesini

Ve beninsanların neşesini

Görür oldum bu sokaklarda

Yıldırımların ezgisiyle büyüdüm

Ben hayatı bu sokaklarda öğrendim

Cennetimi uykularımda buldum

Senin için kokladım gülleri

Kırçiceklerini topladım avuçlarımda 

Sevince kapılma hissini

Bir türlü yakalayamam

Mıh gibi saplanmış biracı var

Göğsümden çıkaramam

Ben hayatı bu sokaklarda öğrendim

Kabus gibi üzerime çöken karanlıklar

Yalnızlığa tutsak bıraktı beni bu sokaklarda...', 'Ben hayatı bu sokaklarda öğrendim Aşkı dostluğu ve acılarıda Ben senin bakışlarını  sevdim Yağmur çiselerken Bana gülümsemeni Tak tak ayak s...', ARRAY['Türk Edebiyatı','Şiir','Adem Bozdağ']::text[], 8.5, '{"poet":"Adem Bozdağ","poet_slug":"adem-bozdag","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bu-sokaklarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OYorumsuz', 'oyorumsuz-adem-bozdag-yhtwx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O sevgiye duyduğu hasreti 

Yüreğinin en derin  köşesine gömdü

Geçen onca yılın ardından artık söndü

Çünkü ayrılık acısıyla yaralıydı yüreği

Bir umut bekliyordu dünyadan

Çözülmemiş duyguları insanlara kapalıydı

Oysa çok az bir mutluluk istemiş

Kimini deliler gibi sevmiş

Aşkı için dünyalarını vermiş

Kimileri onu hiç sevmemiş, değer bile vermemiş

O da herkes gibi zamana isyan etmiş

Uykusuz gecelerinde kalemi ışık olmuş

Şiirleri onun için konuşmuş

Ayrı düşmüş unutulmuş

Kimi gün ağlamış, kimi gün susmuş

En büyük nefreti, ihanetti

İki yüzlü insanlardan tiksinmişti

O acıyla yaşamış, ayrılığa alışmıştı

Şimdi tek bir dostu bile kalmamıştı

Zamana boyun eğmiş, yenilmişti

O aşıktı herşeye

Hayatının son sahnesinde

Çaresizdi, 

Hayallerine düşüyordu son kurşun

Ve birde bitmeyen uykusuz geceler

Ve işte şiirlerindeki son heceler', 'O sevgiye duyduğu hasreti  Yüreğinin en derin  köşesine gömdü Geçen onca yılın ardından artık söndü Çünkü ayrılık acısıyla yaralıydı yüreği ...', ARRAY['Türk Edebiyatı','Şiir','Adem Bozdağ']::text[], 8.5, '{"poet":"Adem Bozdağ","poet_slug":"adem-bozdag","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/oyorumsuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatanım', 'vatanim-adem-bozdag-33aha', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben bir Türk''üm gururluyum

Şerefim güzel vatanım

Dünyada tek ulusluyum

Vatana kurbandır canım

Türk''üm ben dilim Türkçe''dir

Herşeyim güzel vatanım

Dünyada güzel lehçedir

Dökülsünsana son kanım

Şanım yalnız tek hecedir

Namusum güzel vatanım

Dinim İslam pek yücedir

Feda olsun sana canım

Gencim hareket doluyum

Tarihim güzel vatanım

Yarınlardan umutluyum

Sensiz olmasın bu canım

Kimseye Atam eğilmez

Ne Yunan, ne İngilize

İnanın bu dava burada bitmez

Muhtacız daima birbirimize.', 'Ben bir Türk''üm gururluyum Şerefim güzel vatanım Dünyada tek ulusluyum Vatana kurbandır canım Türk''üm ben dilim Türkçe''dir Herşeyim güzel va...', ARRAY['Türk Edebiyatı','Şiir','Adem Bozdağ']::text[], 8.5, '{"poet":"Adem Bozdağ","poet_slug":"adem-bozdag","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/vatanim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazan Mevsimi', 'hazan-mevsimi-ozcan-nevres-g8fp0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Savruluyorlar oradan oraya

Umutsuz aşıklar gibi

Tutunacak dalları kalmamış

Tutunacak dalımdın bir zamanlar

Terk ettiğinden beri

Mekanım oldu meyhaneler

Unutmak için gelirler

Aşkta, işte yitilmişler

Meyhane denilen bu izbe yere

Kırk yıllık dost gibi 

Kaynaşırlar birbirlerine

Yitik umutlar yitik aşklar anlatılır 

Ahlar vahlar içinde

Yaşanmamış aşklar 

Yaşanmış gibi hayalleri süsler

Kendi dertlerini, terk edilmişliklerini

Her şeyi, ama her şeyi unutursun

Anlatan kişilerin dertlerine

Anlatanlarla ortak olursun 

Onların acılarıyla yanar yıkılırsın

Hesabı ödeyip evinin yolunu tuttuğunda

Terk edilmişliğin acısı çöker yine içine

İçin için ağlarsın

		Özcan NEVRES

13 Ağustos 2002', 'Savruluyorlar oradan oraya Umutsuz aşıklar gibi Tutunacak dalları kalmamış Tutunacak dalımdın bir zamanlar Terk ettiğinden beri Mekanım oldu...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hazan-mevsimi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-tuncay-durmus-u9m72', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gozlerinde yasarim

Maviligin uslanmaz sarhoslugunu

Bir simsek cakar ama anlatamam

Sevginin sicakligi dolar citir citir

O gozlerin, o gozlerin var ya

Onlar benimdir

Gormesemde', 'Gozlerinde yasarim Maviligin uslanmaz sarhoslugunu Bir simsek cakar ama anlatamam Sevginin sicakligi dolar citir citir O gozlerin, o gozleri...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Durmus']::text[], 8.5, '{"poet":"Tuncay Durmus","poet_slug":"tuncay-durmus","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gozlerin-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Inadina Sevmek', 'inadina-sevmek-keren-okol-9oz6o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bunun adi inadina sevmek

kim olursa olsun yaninda 

ve hangi dudaklardan duyarsan duy

seni seviyorumu umurumda degil, 

ben yinede her sabah sana uyanir 

her gece sana uyurum.

kimin umrunda ki beni sevmemen

gozyaslarim disinda.

gozyaslarim bulut olup

daha sonra yagmur gibi yagsa saclarina 

ve onun elleri oksayarak sacini, atar mi damlalari

kaldirim kenarina.

bilsem bu sorunun cevabini

en azindan haber isterdim istanbul sokaklarina dair

gozyaslarimdan.

birgun sokak ortasina islak birsekilde seni seviyorum yazilmissa 

bil ki benim gozyaslarim yazmistir.

buna inadina sevmek diyorlar', 'bunun adi inadina sevmek kim olursa olsun yaninda  ve hangi dudaklardan duyarsan duy seni seviyorumu umurumda degil,  ben yinede her sabah s...', ARRAY['Türk Edebiyatı','Şiir','Keren Okol']::text[], 8.5, '{"poet":"Keren Okol","poet_slug":"keren-okol","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/inadina-sevmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Yaşamak', 'seni-yasamak-yusuf-kilinc-l7qns', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben seni yaşıyorum şimdi kalbimin en derin yerinde

Ben seni görüyorum şimdi gözlerimin senden başkasını görmeyen bebeğinde

Ben seni düşlüyorum şimdi beynimin her köşesinde

Ben seni sayıklıyorum şimdi aldığım her nefesimde

Ve ben seni anlatıyorum şimdi yazdığım her şiirimde.', 'Ben seni yaşıyorum şimdi kalbimin en derin yerinde Ben seni görüyorum şimdi gözlerimin senden başkasını görmeyen bebeğinde Ben seni düşlüyor...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Kılınç']::text[], 8.5, '{"poet":"Yusuf Kılınç","poet_slug":"yusuf-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/seni-yasamak-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Beklemek', 'seni-beklemek-yusuf-kilinc-1xo6t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir zevktir seni beklemek

Bir zevktir gözlerine kilitlenmek

Bir zevktir yüreğinde yer etmek

Bir zevk olsa gerek seni sevmek', 'Bir zevktir seni beklemek Bir zevktir gözlerine kilitlenmek Bir zevktir yüreğinde yer etmek Bir zevk olsa gerek seni sevmek...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Kılınç']::text[], 8.5, '{"poet":"Yusuf Kılınç","poet_slug":"yusuf-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/seni-beklemek-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Her Şeysin', 'sen-her-seysin-yusuf-kilinc-8esq4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Damarlarımda dolaşan kansın gitiğinde donuklaşan geldiğinde dolaşansın

Ses tellerimde figansın gittiğinde çığlıklaşan geldiğinde suskunlaşansın

Gönlümde yaramsın gittiğinde azgınlaşan geldiğinde durgunlaşansın

Sen cansın sen canansın ölümüme ferman hayatıma can katansın.', 'Damarlarımda dolaşan kansın gitiğinde donuklaşan geldiğinde dolaşansın Ses tellerimde figansın gittiğinde çığlıklaşan geldiğinde suskunlaşan...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Kılınç']::text[], 8.5, '{"poet":"Yusuf Kılınç","poet_slug":"yusuf-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sen-her-seysin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda Niyetine', 'veda-niyetine-aziz-pinar-q4brt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Soğuk bir son Aralık akşamı

Bir vapur kalkar karşı kıyıdan

Dumanı kaplar ufkumu..

Bir el uzaklaşır sıcaklığıyla

Bir çift göz ıslanır hıçkırıklarla

Bir gönül parçalanır...

Terkedilmişliğin acısı

Soğuktan daha çok sızlatır

El sallarken ufuklara

Veda niyetine...', 'Soğuk bir son Aralık akşamı Bir vapur kalkar karşı kıyıdan Dumanı kaplar ufkumu.. Bir el uzaklaşır sıcaklığıyla Bir çift göz ıslanır hıçkırı...', ARRAY['Türk Edebiyatı','Şiir','Aziz Pınar']::text[], 8.5, '{"poet":"Aziz Pınar","poet_slug":"aziz-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/veda-niyetine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Tepesi', 'ask-tepesi-aziz-pinar-7mmrs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu güneşli yer, bu tepede

Ilgıt, ılgıt rüzgar esiyor

İki aşık konuşuyor

Gözleri birbirinde...

Aşağıda deniz masmavi

Karşı kıyıda hayal kıpırtılar

İki aşık yürüyor

Elleri birbirinde...

Düşünceler geleceğe dair

Beklentiler mutluluğa

İki aşık bekleşiyor

Gönülleri birbirinde...

Gün yatıyor boğazın üstüne

Güneş ufka kaçtı kaçacak

İki aşık ayrılıyor

Kalpleri birbirinde...', 'Bu güneşli yer, bu tepede Ilgıt, ılgıt rüzgar esiyor İki aşık konuşuyor Gözleri birbirinde... Aşağıda deniz masmavi Karşı kıyıda hayal kıpır...', ARRAY['Türk Edebiyatı','Şiir','Aziz Pınar']::text[], 8.5, '{"poet":"Aziz Pınar","poet_slug":"aziz-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ask-tepesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ömrü Adamak', 'bir-omru-adamak-yusuf-kilinc-3888t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yakılmış bir türkünün ezgisiyim ben

Dağlanmış bir yüreğin sancısıyım ben

Vurulmuş bir ceylanın acısıyım ben

Adanmış bir ömrün suçlusuyum ben

Doğmamış bir günün yolcusuyum ben

Sevilmemiş bir kalbin parçasıyım ben

Uğranmamış bir limanın yalnızlığıyım ben

Unutulmuş bir aşkın anısıyım ben

Sürülmemiş bir ömrün sefasıyım ben

Bitirilmemiş bir gecenin sabahıyım ben

Yaşatılmamış bir aşkın kurbanıyım ben

Adanmış bir ömrün suçlusuyum ben

Ödenmemiş bir borcun hesabıyım ben

Kafeslenmiş bir bülbülün feryadıyım ben

Ulaşılmamış bir aşkın kaynağıyım ben

Adanmış bir ömrün suçlusuyum ben.', 'Yakılmış bir türkünün ezgisiyim ben Dağlanmış bir yüreğin sancısıyım ben Vurulmuş bir ceylanın acısıyım ben Adanmış bir ömrün suçlusuyum ben...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Kılınç']::text[], 8.5, '{"poet":"Yusuf Kılınç","poet_slug":"yusuf-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-omru-adamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şikayetim Var', 'sikayetim-var-yusuf-kilinc-fb1gx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yağmur ormanlarında sesin var

Islak topraklarda nefesin var

Ürkek ceylanlarda adresin var

Deşilmiş yüreğimde ise elemin var

Adressiz mektuplarımda sözlerin var

Yıkılmış duvarlarımda izlerin var

Atılmış duygularımda hislerin var

Yakılmış bedenimde hasretin var

Soğuk namlularda gidişin var

Acımasız dünyada terkedişin var

Beni bitirdin helalin var

Sana bir de sitemim var

Sevdim diyemedin işte şikayetim var.', 'Yağmur ormanlarında sesin var Islak topraklarda nefesin var Ürkek ceylanlarda adresin var Deşilmiş yüreğimde ise elemin var Adressiz mektupl...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Kılınç']::text[], 8.5, '{"poet":"Yusuf Kılınç","poet_slug":"yusuf-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sikayetim-var-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şey Seninle Güzel', 'her-sey-seninle-guzel-yusuf-kilinc-fw8sv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güzel şeydir seninle hayata merhaba demek

Güzel şeydir tabiattan sesini dinlemek

Güzel şeydir gül bahçesinden seni seçmek

Güzel şeydir yanan yüreğime seni serpmek.', 'Güzel şeydir seninle hayata merhaba demek Güzel şeydir tabiattan sesini dinlemek Güzel şeydir gül bahçesinden seni seçmek Güzel şeydir yanan...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Kılınç']::text[], 8.5, '{"poet":"Yusuf Kılınç","poet_slug":"yusuf-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/her-sey-seninle-guzel-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Volkan Gibi', 'volkan-gibi-yusuf-kilinc-6zv36', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Akarsın yüreğimden oluk oluk kan gibi

Yakarsın bedenimi tıpkı bir volkan gibi

Şad eylersin beynimi aynı bir sultan gibi

Eşersin kalp yaramı aynen bahçıvan gibi', 'Akarsın yüreğimden oluk oluk kan gibi Yakarsın bedenimi tıpkı bir volkan gibi Şad eylersin beynimi aynı bir sultan gibi Eşersin kalp yaramı ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Kılınç']::text[], 8.5, '{"poet":"Yusuf Kılınç","poet_slug":"yusuf-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/volkan-gibi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Sevseydin', 'beni-sevseydin-yusuf-kilinc-okenq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mecnun seni görseydi çöllere düşmezdi

Ferhat seni tanısaydı dağları delmezdi

Kerem seni bilseydi Aslı''yı sevmezdi

Sen beni sevseydin aşk intihar etmezdi', 'Mecnun seni görseydi çöllere düşmezdi Ferhat seni tanısaydı dağları delmezdi Kerem seni bilseydi Aslı''yı sevmezdi Sen beni sevseydin aşk int...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Kılınç']::text[], 8.5, '{"poet":"Yusuf Kılınç","poet_slug":"yusuf-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/beni-sevseydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sabah Ölümü', 'bir-sabah-olumu-ali-galip-e5vmi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir sabah ölümü

Yaşamla değiştirmek istersin bir masayı donatmak gibi

İpi bir makaraya dolamak kadar yakın  her şey  yakın

Aşkı hatırlamak aşkı

Suçlayanlardan bile daha acı verir

Sokaklar: sende kalan yalnızlığım

Sokaklar  yağmur sonrası nekahet 

********

Aşkla imzalanan ateşkeslerimi aradım

Buralılığı hayatı altında ezilmiş

Göksüz bir apartman almanağı kalmışım sırtıma

Ateşin iştahını üflemişim ruhuma(fakat)

Anlamazsın bir istanbul tutturmuşum karanlığımız bol

İşte ben bir amme hizmeti gibi dolduruşa gelişimle gördün

Şimdi nasıl tanıtmalı bu salyalı ağzı tan kuşatmasına

Sonra fi anında heybelerini arala aynalara benden miras: 

Yalnızlık....

Aptallığın ve ölümün kör düğüldüğü atlas.', 'Bir sabah ölümü Yaşamla değiştirmek istersin bir masayı donatmak gibi İpi bir makaraya dolamak kadar yakın  her şey  yakın Aşkı hatırlamak a...', ARRAY['Türk Edebiyatı','Şiir','Ali Galip']::text[], 8.5, '{"poet":"Ali Galip","poet_slug":"ali-galip","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-sabah-olumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntiharın Anatomisi', 'i-ntiharin-anatomisi-seyhmus-baran-aydin-y550p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kazandığım yanlış zaferlere

Doğru süsü verirken

Marazi bir aşkın kollarında tutsaktım

Kırık parçaları toplamak benim işim değildi artık

Vazgeçmiştim ahlakı sorgulamaktan

Boşverlerim yeni dendenler kazanıyordu

Kilidi kaybolmuş günlüğümde

Ve hala utanıyordum

Şiirlerimin okunmasından

Hangi günü gördük ki akşam olmamış

Nidaları yükseliyordu köşedeki izbe birahaneden

Hayatın bir imtihan olduğunu söylüyordu sarhoşun biri

Devrilen her bardak

Yeni bir bilgelik katıyordu hayata

Katıksız yalnızlığımın solgun düşlerinde

İlahi dinlerken içen birini görüyordum hep

Büyük ihtimal annesini özlüyordu

Uçsuz bucaksız bir özlemdi bu belki de

Ve ben seni düşünürken

İntihar süsü veriyordum

Her gece katlettiğim kelimelere...', 'Kazandığım yanlış zaferlere Doğru süsü verirken Marazi bir aşkın kollarında tutsaktım Kırık parçaları toplamak benim işim değildi artık Vazg...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Baran Aydın']::text[], 8.5, '{"poet":"Şeyhmus Baran Aydın","poet_slug":"seyhmus-baran-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/intiharin-anatomisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İklimlerde Seni Aramak', 'i-klimlerde-seni-aramak-yusuf-kilinc-2xw8w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Soğuk iklimler olmazsa, ateşin anlamı olmaz

Çekingen bakışlar olmazsa, gözlerin anlamı olmaz

Açan çiçekler olmazsa, baharın anlamı olmaz

Yanan  yürekler olmazsa, sevmenin anlamı olmaz', 'Soğuk iklimler olmazsa, ateşin anlamı olmaz Çekingen bakışlar olmazsa, gözlerin anlamı olmaz Açan çiçekler olmazsa, baharın anlamı olmaz Yan...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Kılınç']::text[], 8.5, '{"poet":"Yusuf Kılınç","poet_slug":"yusuf-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/iklimlerde-seni-aramak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Aramak', 'seni-aramak-yusuf-kilinc-b003d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güzel şeydir sevdanın sevdalısı olmak

Güzel şeydir aşkının ateşinde kavrulmak

Güzel şeydir bir ömrü yoluna adamak

En güzel şey ise bugünlerde arayıp yarınlarda seni bulmak', 'Güzel şeydir sevdanın sevdalısı olmak Güzel şeydir aşkının ateşinde kavrulmak Güzel şeydir bir ömrü yoluna adamak En güzel şey ise bugünlerd...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Kılınç']::text[], 8.5, '{"poet":"Yusuf Kılınç","poet_slug":"yusuf-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/seni-aramak-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Yanmak', 'sana-yanmak-yusuf-kilinc-6h7ps', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiçbir deprem sarsmadı dünyayı 

Senin beni sarstığın kadar

Ve hiçbir yangın yakmadı Roma''yı

Senin beni yaktığın kadar', 'Hiçbir deprem sarsmadı dünyayı  Senin beni sarstığın kadar Ve hiçbir yangın yakmadı Roma''yı Senin beni yaktığın kadar...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Kılınç']::text[], 8.5, '{"poet":"Yusuf Kılınç","poet_slug":"yusuf-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sana-yanmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerine Sormak', 'gozlerine-sormak-yusuf-kilinc-i88z8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölümü gözlerine sor, benden öğrenemezsin

Yakmayı kendine sor, benden öğrenemezsin

Vurmayı bakışına sor, benden öğrenemezsin

Sevmeyi bana sor, kendin bilemezsin.', 'Ölümü gözlerine sor, benden öğrenemezsin Yakmayı kendine sor, benden öğrenemezsin Vurmayı bakışına sor, benden öğrenemezsin Sevmeyi bana sor...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Kılınç']::text[], 8.5, '{"poet":"Yusuf Kılınç","poet_slug":"yusuf-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gozlerine-sormak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Olmasa', 'ask-olmasa-salih-ozalasan-6ydzi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşamak güzel hayatı acısıyla tatlısıyla

Bazen kahretsenizde gönül sevdasıyla

Bitmiyor hayat ne kadar mutsuz olsanızda

Bir ışık aranan hep karanlığa baksanızda

Kalbinize söz geçmiyor, hiç umut olmasada

Eremediğine özlem bitmiyor, hep yüzünüze vursada

Sevgiye bir hasret bir özlem kalmasa

Yaşamın ne anlamı kalırki, yürekte aşk olmasa

Aşk için gözyaşı dökmek bile çok güzel

Yüreğinize akmışsa sizden habersiz bir güzel

Sevmesede o artık sizin için hep özel

Sevilirseniz serenad, yoksa söylersiniz hep gazel

Y.Tar.09-12-2002 Saat 01.36', 'Yaşamak güzel hayatı acısıyla tatlısıyla Bazen kahretsenizde gönül sevdasıyla Bitmiyor hayat ne kadar mutsuz olsanızda Bir ışık aranan hep k...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ask-olmasa-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyiş', 'bekleyis-selvi-celik-6xpa5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Birgün geleceksin diye, 

Hergün umutla yaşadım.

Hiçbir zaman kaybetmedim umudumu.

Ne bugün nede yarınlarda.

Sanki hiç gitmemissin gibi, 

Koşarak gelip boynuma sarılmanı koklamanı, 

Kulagıma beni sevdiğini fısıldamanı bekledim.

O yüzden kapıları hep açık bıraktım..

Ne günler nede aylar oldu sankı, 

Sensizliği hiç yasamadım.

Her odamın her köşesinde sen varsın.

Her gelen sesde.

Her bakışta sen.

Her nefesde sen varsın.

Eğer birgün unutursam, 

O bana bulut renkli ğözlerinle, 

   marum marum bakışını.

Sensizligin tam ortasındayımdır.

Gel ne olur, dön ne olur sensizligi bilmeden.

Unutmam unutamam seni.

Sen bende bir can, 

Sen bende bir beden, 

Sensiz yaşamak olurdu bir son.

O yüzden kapıları hep açık bıraktım..', 'Birgün geleceksin diye,  Hergün umutla yaşadım. Hiçbir zaman kaybetmedim umudumu. Ne bugün nede yarınlarda. Sanki hiç gitmemissin gibi,  Koş...', ARRAY['Türk Edebiyatı','Şiir','Selvi Çelik']::text[], 8.5, '{"poet":"Selvi Çelik","poet_slug":"selvi-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bekleyis-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-yasar-aslan-2ilh0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gecenin sessizliğinde, yanında olmamı istersen, 

Gözlerindeki yaşta, yanağındaki tebessümde olacağım.

Yağmurlarda düşün beni. 

Üzerine yağacağım.

Beni ararsa gözlerin, bir kar tanesindeyim.

Sesimi rüzgarda bulursun ancak.

Saçlarım fırtına, 

Ellerim ateştir sevgilim.

Dağlarda yalnız ceylan, 

Denizde batık bir gemi, 

Yuvası dağılmış güvercinim ben.

Suyu akmaz nehir, 

Yıldızsız bir geceyim.

Bomboş bir şehir.

Anlaşılmaz bir şiirim ben.

Biraz sevgi, biraz da korku...

Yaşayan acıyım ben...

08 - 12 - 2002      02: 05', 'Gecenin sessizliğinde, yanında olmamı istersen,  Gözlerindeki yaşta, yanağındaki tebessümde olacağım. Yağmurlarda düşün beni.  Üzerine yağac...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Aslan']::text[], 8.5, '{"poet":"Yaşar Aslan","poet_slug":"yasar-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ben-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birdenbire', 'birdenbire-ayperi-ottekin-basoglu-o49zh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Birdenbire doğar sevgi

Masum bir aşk heyecanla.

Sevgi akar damarlarda

Birden doğar gülümseme. 

Birden doğan sevdalarda

Kimi uzun kimi kisa.

Bulunca sen, güzel yaşa

Kıymetin bil yüz yıllarca. 

Mahsun şiir birdenbire

Doğuverir yüreğinde

Solar çiçekler gönlünde

Ölür insan birdenbire', 'Birdenbire doğar sevgi Masum bir aşk heyecanla. Sevgi akar damarlarda Birden doğar gülümseme.  Birden doğan sevdalarda Kimi uzun kimi kisa. ...', ARRAY['Türk Edebiyatı','Şiir','Ayperi Ottekin Başoğlu']::text[], 8.5, '{"poet":"Ayperi Ottekin Başoğlu","poet_slug":"ayperi-ottekin-basoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/birdenbire-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüze Göze Bulaştırılmış Bir Üşengeçlikten Notasyonlar', 'yuze-goze-bulastirilmis-bir-usengeclikten-notasyonlar-charles-bukowski-kkuij', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir kadın geçiyor yanımdan ona bakıyorum

ve biliyorum ki varlığından

düşünce

ve kurtlar silinmiş

anlamıyor başarılı erkeklerin

ne kadar hayvan olabileceğini

bilmiyor formül tembelliğine

yakalandığını

pis bir ikindi vakti pis bir mutfakta oturmuş

onu seyrediyorum

portakal ve Cadillac''ları düşleyerek

yürüyor

beynimde bir palmiye ağacına atıyorum

kadını

madden tecavüz edip

manen tükürüyorum

gözüne

gerçekte küçük bir çocuğun

umumi bir helaya yazdığı birkaç sözcükten

başka birşey olmadığını görüyorum

bu sayısız ve şok edici

kavrayışlar

bu pislik

hayat

teni beyaz ve sarkmış

mor bir külot var

kıçında

işte bundan çıkıyor

savaşlar

büyük tablolar

intiharlar

harpler

kayabilim

ve münzeviler.', 'bir kadın geçiyor yanımdan ona bakıyorum ve biliyorum ki varlığından düşünce ve kurtlar silinmiş anlamıyor başarılı erkeklerin ne kadar hayv...', ARRAY['Türk Edebiyatı','Şiir','Charles Bukowski']::text[], 8.5, '{"poet":"Charles Bukowski","poet_slug":"charles-bukowski","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yuze-goze-bulastirilmis-bir-usengeclikten-notasyonlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Sensizlik', 'seninle-sensizlik-sadik-orel-fkha4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni anla nolursun ben seni anlayamadım; 

Sen beni anla bari.

Seni karşımda görüpte elini tutamamak, kokunu alamamak, yüzüne bakamamak...

Beni çehennemin ortasına bırakıyor.

Bençe sende bunu istemiyorsun

Veya ben öyle zannediyorum

Bırak öyle zannedeyim

Sevgin kalbimde kalsın, 

Kalsınki başka sevgiler gelip tüketemesin sevgini...', 'Beni anla nolursun ben seni anlayamadım;  Sen beni anla bari. Seni karşımda görüpte elini tutamamak, kokunu alamamak, yüzüne bakamamak... Be...', ARRAY['Türk Edebiyatı','Şiir','Sadık Orel']::text[], 8.5, '{"poet":"Sadık Orel","poet_slug":"sadik-orel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seninle-sensizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-metin-usengec-kcvx5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geçen gün rüyamda gördüm seni 

Aramızda kısacık mesafe sen bana ben sana bakıyoruz 

Senin yanında senin çocukların benim yanımda bizim çocuğumuz 

Kız çocuğu...zaten hep kızım olsun isterdim. 

Sana olan sevgim yarı yarıya ona kaymış sanki 

Senden bana o kalmış gibi..ona sarılıp seviyorum. 

Onda seni buluyorum sanki.annen o diyorum. 

Seni ne kadar çok sevdiğimi anlatmaya çalışıyorum kızımıza.. 

13-Haziran-2002 Sabahı..

Hasretim Gül Yüzüne..Seni Çok Özlüyorum..', 'Geçen gün rüyamda gördüm seni  Aramızda kısacık mesafe sen bana ben sana bakıyoruz  Senin yanında senin çocukların benim yanımda bizim çocuğ...', ARRAY['Türk Edebiyatı','Şiir','Metin Üşengeç']::text[], 8.5, '{"poet":"Metin Üşengeç","poet_slug":"metin-usengec","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ruya-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözkapaklarım kipriklerime...', 'gozkapaklarim-kipriklerime-mustafa-konuk-6onl4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen ve Ben

gözkapaklarım kipriklerime

yenik düştüğünde

yalnızlığım biter..

çünkü bütün rüyalarımın

başrol oyuncuları

sen ve ben ve mekanı heryer...', 'Sen ve Ben gözkapaklarım kipriklerime yenik düştüğünde yalnızlığım biter.. çünkü bütün rüyalarımın başrol oyuncuları sen ve ben ve mekanı he...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Konuk']::text[], 8.5, '{"poet":"Mustafa Konuk","poet_slug":"mustafa-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gozkapaklarim-kipriklerime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masallar', 'masallar-i-clal-aydin-m0gks', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Daha uyanmamalıydık masallardan.Ne zaman bitti o eşsiz ormanlar, yollar? ne zaman ayrıldı yolları şehzade ile ipek kızın? ve ne zaman vazgeçti yakışıklı prens yüzyıl uyuyan güzeli uyandırmaktan? Ne zaman yoruldu aladdin lambasını ovmaktan? iyilik perileri, sevimli cinler şimdi neredeler? Daha uyanmamalıydık...Masallar hep o renkte ve aynı inandırıcılıkta kalmalıydı kalbimizde.Bir şey oldu, bir yerlerde.Büyüdük mü küstük mü birşeylere ne; inanmaz olduk masallara.Dinlemez olduk ve anlatmadık bir daha.Belki anlatılacak masalımız kalmadı, çabuk yordu hayat bizi.Oysa ne güzeldi küllerinden yeniden doğan Anka kuşu, Kaf dağının ardındaki o gizemli ülke, lal bir oba uşağı ile güzeller güzeli bey kızının başkaldıran sevdası.Nasıl özlüyoruz geçmişi...Neden özler ki insan? Hele birde mutsuz bir çocuksanız...Çocuktuk çünkü.İnanıyorduk.Köprüler geçmemiş, aldatmamış, aldatılmamış, bedeller ödememiş, ayrılık ve hasret mektupları okumamıştık.Ve dizlerimizi kanatmamıştı henüz hayat.İnanıyorduk, duruyduk, saftık, çocuktuk.Şimdi anlatacak bir masalımız bile yok, bir köşesine sığınacak...', 'Daha uyanmamalıydık masallardan.Ne zaman bitti o eşsiz ormanlar, yollar? ne zaman ayrıldı yolları şehzade ile ipek kızın? ve ne zaman vazgeç...', ARRAY['Türk Edebiyatı','Şiir','İclal Aydın']::text[], 8.5, '{"poet":"İclal Aydın","poet_slug":"i-clal-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/masallar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyuyor musun?', 'uyuyor-musun-hasan-cifci-tqrru', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beklerim ben seni, gelmesen de...

Çırpınan yüreğimi duyuyor musun? 

Uykular terk etti beni, aklım sende.

Yoksa sen uyuyor musun? 

(7 Aralık 2002, Oran-ANKARA)', 'Beklerim ben seni, gelmesen de... Çırpınan yüreğimi duyuyor musun?  Uykular terk etti beni, aklım sende. Yoksa sen uyuyor musun?  (7 Aralık ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çifci']::text[], 8.5, '{"poet":"Hasan Çifci","poet_slug":"hasan-cifci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/uyuyor-musun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-suna-edip-iq1v8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'aktığı yatak

şahit

ırmaklar

