INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sinema Kapılarında', 'sinema-kapilarinda-sukru-erbas-r46mt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'XI. 

Benim dünyayı sevmem için

Dünya beni sevmeli.

Tertemiz giysilerim olmalı

Ütülü, ince yakışan.

Bir kızı sevmeliyim dupduru

Yağmur mavisi, bulut buğusu

Gökyüzü gibi sakin

Gülmeli gözlerinin içi', 'XI.  Benim dünyayı sevmem için Dünya beni sevmeli. Tertemiz giysilerim olmalı Ütülü, ince yakışan. Bir kızı sevmeliyim dupduru Yağmur mavisi...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Erbaş']::text[], 8.5, '{"poet":"Şükrü Erbaş","poet_slug":"sukru-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sinema-kapilarinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Genelev Mektupları', 'genelev-mektuplari-sukru-erbas-km3dh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'I.

Tenime yabancılaştım, etime

Göğsüme kollarıma kalçalarıma

Bacaklarıma yabancılaştım.

Saçlarım o eski güzelliğini 

Çoktan yitirdi

Şimdi yalnız bilmem neden 

Zaman zaman yüzüme vuran

Bir utancı perdeliyor sadece.

Oysa önceleri oysa eskiden

Salınca tarkları tel tel

Düşle ülkesinden sevgiler ülkesinden 

Yağmur serinliğinde, incecik

Yumuşacık bir el

Bulutlardan yüreğime kayardı.

Gözlerim kaçamak bakışlarda

Kirpiklerim kırık

Boynum bir çocuğun pembe ağzında

Ürperdikçe  uzardı.

Dudaklarım dersen, dudaklarım

Öptüğüm aynalarda kaldı.

Tenime yabancılaştım, etime

Acıma sevincime insan yanıma

Kendime yabancılaştım.

II.

Giysiler alırım nedense

Nerelerde ne zaman giyeceksem

Bir eski alışkanlık işte

İlk gençlikten kalma.

Oysa bir dantel külot bir gecelik

Çok bile.

(Şimdilerde sütyeni de çıkardık)

Giysiler alırım giyilmez

Çıplaklığıma. 

Arada bir çarşı pazar

Doktor dönüşleri daha çok

Eser de aklıma; 

Çocuğuna çeşit çeşit

Kazaklar örecek

Evcimemn bir ev kadını gibi

Yün alırım şiş alırım tığ alırım

Nasıl sevinirim bir bilsen

Nasıl mutlanırım.

III.

Bu insan başları sıra sıra

Bu kalabalık

Camlardaki bu sürekli kalabalık

Bana bakkal dükkanlarını

Anımsatır hep.

Içerde boy boy konserve kutuları 

Sabun kalıpları yağ paketleri

Sıralı bakkal dükkanlarını.

Kararsız bir müşteri

Etiketi görememiş

Korkarak alacağı malın ederinden

Girer içeri.

Kimi gün bir yaşlı yaşına güvenerek

Hoyrat davranışlarda rahat

Kimi gün bir çocuk ürkek mi ürkek

Ayva sarı terlerini silerek

Düşer üstüme.

IV.

Yüreğimde yüz gurbeti taşısam da

Kalçalarımda bir erkeği taşımasam.

Yıldım demenin de bir anlamı yok

Saçlarıma sinmiş bu çiğ kolonya

Tenimdeki bu vazelin kokularından.

Penceresiz per
..........
..........', 'I. Tenime yabancılaştım, etime Göğsüme kollarıma kalçalarıma Bacaklarıma yabancılaştım. Saçlarım o eski güzelliğini  Çoktan yitirdi Şimdi ya...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Erbaş']::text[], 8.5, '{"poet":"Şükrü Erbaş","poet_slug":"sukru-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/genelev-mektuplari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapı Zilinde İsmimiz', 'kapi-zilinde-i-smimiz-aziz-pinar-oi1si', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dışarıda mevsim bahar

Birde Nisan yağmurları

Çiçeklere tutunmuşlar

Aşkımızın damlaları

Şemsiyeyi kapatalım

Bulutlara uzanalım

Sırılsıklam ıslanalım

Söyleyelim şarkıları

Dışarıda mevsim bahar

Yağsın sevgi yağmurları

Özlem duyup susamışlar

Aşkımızın damlaları

Bir yuvaydı hayalimiz

Kapı zilinde ismimiz

Ben çalıpta sen açınca

Birleşecek ellerimiz', 'Dışarıda mevsim bahar Birde Nisan yağmurları Çiçeklere tutunmuşlar Aşkımızın damlaları Şemsiyeyi kapatalım Bulutlara uzanalım Sırılsıklam ıs...', ARRAY['Türk Edebiyatı','Şiir','Aziz Pınar']::text[], 8.5, '{"poet":"Aziz Pınar","poet_slug":"aziz-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kapi-zilinde-ismimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirle Söyleşi', 'siirle-soylesi-emre-gumusdogan-0r70z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'illa da bir yerlerde vurulmak varsa 

ko kollarında olsun 

dala konmaz hırçınlığımda 

eve dönmediğim geceler 

ya da şiire durduğum sabahlar 

sevdiğim nakış işler 

sabırdır 

bende inadına 

kaşlarının arasına gererim şiir hamağımı 

ne var ki 

her kitap başka yazmış seviyi 

''ibibikler öte'' dursun 

kimse gelmez 

özgürlüğümün tanığı 

alanlar ve kadınlarım oldu 

bencilce sevdim her ikisini... 

oysa 

geminden kurtulmuş şehvet değildi içimdeki 

insan yanımın dışa vurumu 

kızma ey şiir 

ihanet etmedim sana 

ölümcül boşluklar kutuplarımda yansırken 

nasılda ensesinden vurur adamı 

usundaki yalnızlık 

bir elim kabzasında kalemin 

bir elim şakağımda 

filistin askılarından kurtuldum 

senden kurtulamadım ey şiir 

güzel yanın bu olsa gerek 

umut yanın 

ve uçkuru düğüm tutmaz 

kız oğlan kız saltanatın', 'illa da bir yerlerde vurulmak varsa  ko kollarında olsun  dala konmaz hırçınlığımda  eve dönmediğim geceler  ya da şiire durduğum sabahlar  ...', ARRAY['Türk Edebiyatı','Şiir','Emre Gümüşdoğan']::text[], 8.5, '{"poet":"Emre Gümüşdoğan","poet_slug":"emre-gumusdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/siirle-soylesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yardım Et', 'yardim-et-aziz-pinar-x6z66', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Rüzgara karıştı yardım çağrısı

Ulaşsaydı sana koşar gelirdin

Sensiz diner mi hiç gönül ağrısı

Tutunsaydı sana coşar gelirdin

Ne şimşekler çaktı yıldırım indi

Fırtınalar gökten aşkı getirdi

Gemilerim battı yelken delindi

Ümidim bitmedi koşar gelirdin', 'Rüzgara karıştı yardım çağrısı Ulaşsaydı sana koşar gelirdin Sensiz diner mi hiç gönül ağrısı Tutunsaydı sana coşar gelirdin Ne şimşekler ça...', ARRAY['Türk Edebiyatı','Şiir','Aziz Pınar']::text[], 8.5, '{"poet":"Aziz Pınar","poet_slug":"aziz-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yardim-et-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşığınım', 'asiginim-salih-ozalasan-kenir', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öyle bir aşka düşmüş ki gönül

Gözyaşını uğrunda eylemiş bade

Bir volkan olmuş, yanıyor alev alev

Baharı yaşamamış hiç bu vadide

Bir çiçeğe sevdalanmış, yoktur bir eşi

Bin yılda bir yetişir, öylesine nadide

Koklamaya kıyılmaz, eller koparma peşinde

Billahi sönük kalır  yanında, ihtişamlı orkide

Rengini kıskanır doğduğunda gökkuşağı

İsterim olmak ömür boyu onun uşağı

Yayılır ondan bir koku misk''i amber ovadan aşağı

Sevdasından kurmuş etrafına herkes otağı

Gönlüme ferman geçmez, onsuz hayat çok acı

Kirpikleri ok olmuş, yok yarasının ilacı

Bülbülüm narına ağlarım kalmadı gözüm yaşı

Razıyım verse eliyle, basmaya bağrıma taşı

Kıskanır hilâl inadına ince kaşı

Ceylanı andırır mahzundur âhuzar bakışı

Tanrım işlemiş özenmiş ona her nakışı

Aşığıyım bin cana değer, onun bana şöyle bir bakışı

(Y.Tar.15.12.2002 Saat 13.00)', 'Öyle bir aşka düşmüş ki gönül Gözyaşını uğrunda eylemiş bade Bir volkan olmuş, yanıyor alev alev Baharı yaşamamış hiç bu vadide Bir çiçeğe s...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/asiginim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Banarım Yarama', 'siir-banarim-yarama-emre-gumusdogan-55mes', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sokulursun 

gün batımında kızıllığın 

sularda / gök yangın / 

tüner gözbebeklerime 

sıyrılır kınından yürek 

aşklar büyütür 

düşlerimi emzirerek 

bükülürsün 

tavında demir / akkor/ 

alevleri yalar dilim 

tomurcuklanır yıldızlar 

ay ışığı delice sarmaşır suyla 

dokundukça çoğalır / kırılır tılsım / 

yatağını bulur 

gece mavisi bir nehir 

yok olursun 

yaprağını dökerken gece 

devinir bir sözcüğün rahibe inadında 

bulamam sesini 

sesimin yanında 

şiir banarım yarama', 'sokulursun  gün batımında kızıllığın  sularda / gök yangın /  tüner gözbebeklerime  sıyrılır kınından yürek  aşklar büyütür  düşlerimi emzir...', ARRAY['Türk Edebiyatı','Şiir','Emre Gümüşdoğan']::text[], 8.5, '{"poet":"Emre Gümüşdoğan","poet_slug":"emre-gumusdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/siir-banarim-yarama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Link', 'link-erol-cankaya-0bjd0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sesin hızı ne, ışığınki kaç, kaç km/sn? 

Bir kabloda elektron hızıyla yol alıyorum

Hedefim ebced hesabıyla bir ışık yılı 

Sesim iyi geliyor mu iyi dinle şimdi, 

Adının s’si, eylülün e’si, neler yaşadık biz’in n’si. 

Öyle bir uyuşuk kadran ki bu gavurcasına

Açıkça küfrü hakkediyor baştaki iki 9

Neyse ki fazla bekletmiyor çevik 44

Bana ne çimenlerinden publarından ilgilenmiyorum

1’le giriyorum metrolarına o kibirli şehrin

Bir heceli bir bombayım on iki aya kurulmuş

İstanbul’un i’si, çaresizliğin ç’si, o’su of çekmenin. 

İnanır mısın bilmem unutmuyorum çiçeklerini

Haftada üç mektup nasıl delirtirse insanı öyle

Tarih ve Toplum aldım yarın postalayacağım

Herkesler iyidir sen kendini koru, kodluyorum, 

Keith Jarrett’ın k’sı, ağlıyorumun a’sı, m’si Marmaris’in. 

Yeni yeni cesaret ediyorum pencerenden bakmaya

Boğaz’ın suratı asık, üstelik şimdiden puslu

Kayıp giden hiçbir tankere yüz vermiyor

İlk sigaramı inadına üstüne fırlatıyorum

Anılar yoranın a’sı, çilenin ç’si, olmuyorun o’su. 

Sanki otobüsteyiz sağımıza almışız Akdeniz’i

Kadranın her dönüşü hızlı bir viraj sana doğru

İki ayrı 2 çeviriyorum yeni dört yıllar için

Sonraki numara elbet gizli miladımızdaki 7

Kavuşmanın k’sı özlemin ö’sü, Sozzo’nin z’si.

Bir kabloya sığınmış ülkeler nehirler aşıyorum

Biraz da şaşkınım bakalım neler icat edecek daha 

Kahraman Graham Bell, en büyük telefon idaresi

Ama kodlamak gerekiyor o kadar olucek artık

Lorca’nın l’si, üşüyor musunun ü’sü, yalnızımın y’si. 

Sevgilim, tarafsızlık BBC’ye bile kalmamış

Tarafgir bir tutumla en çok mektubunu bekliyorum

Birazdan odandayım sesinle sevişmek için 

Okyanusların o’su, Üsküdar’ın r’si, u’su uzun gecelerin. 

Yüreğin hızı ne, ayrılığın kaç, kaç km/sn? 

Sakallarıma kadar elektrik yüklüyüm

Enerjimi dört yılı ateşlemekten aldım

Yüreğim tam ulaşmıyor mu n’olur iyi dinle, 

Mistral’in m’si, hasretten geberiyorumun m’si. 

Ve son kez çaldı zil, karşımda sesin işte

Sesin, zifiri Boğaz’ın en aydınlık şimşeği.', 'Sesin hızı ne, ışığınki kaç, kaç km/sn?  Bir kabloda elektron hızıyla yol alıyorum Hedefim ebced hesabıyla bir ışık yılı  Sesim iyi geliyor ...', ARRAY['Türk Edebiyatı','Şiir','Erol Çankaya']::text[], 8.5, '{"poet":"Erol Çankaya","poet_slug":"erol-cankaya","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/link-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mesnevi''den', 'mesnevi-den-mevlana-celaleddin-rumi-ye056', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşkın şerarı ateşi ta bağrıma düştü, 

     Ahım işiden yandı deyu başıma üştü, 

     İmdadıma eşkim ile dide yetişti, 

     Hepsi kalıp acz dediler: ''eyvah'', 

     Yansın ko dedim, sönmeye söndürmeye Allah.', 'Aşkın şerarı ateşi ta bağrıma düştü,       Ahım işiden yandı deyu başıma üştü,       İmdadıma eşkim ile dide yetişti,       Hepsi kalıp acz ...', ARRAY['Türk Edebiyatı','Şiir','Mevlana Celaleddin Rumi']::text[], 8.5, '{"poet":"Mevlana Celaleddin Rumi","poet_slug":"mevlana-celaleddin-rumi","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/mesnevi-den-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Poems to a Mysterious Woman', 'poems-to-a-mysterious-woman-robert-desnos-h3vzd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'I have dreamed so much of you

that you lose your reality.

Is there still time to reach that living body

     and kiss on that mouth the birth

     of the voice which is dear to me.

I have dreamed so much of you, 

that my arms accustomed while embracing your shadow

     to folding over my breast would not bend

     to the shape of your body perhaps.

And that, before the real appearance of what has haunted me

     and ruled me for days and years

I should become doubtless a shade, 

O sentimental scales

I have dreamed of you so much that it is no longer right

     for me to awaken. I sleep standing my body exposed to

     all the appearances of life and love, and you, the only

     one who counts today for me, I could touch your brow

     and your lips less

than the lips and brow of the finest person who came.

I have dreamed so much of you

walked so much, spoken, lain with your phantom that all

     I have to do now perhaps is to be a phantom among

     phantoms and a ghost a hundred times more than the

     ghost who walks and will walk gaily over the sun-dial

     of your life.', 'I have dreamed so much of you that you lose your reality. Is there still time to reach that living body      and kiss on that mouth the birt...', ARRAY['Türk Edebiyatı','Şiir','Robert Desnos']::text[], 8.5, '{"poet":"Robert Desnos","poet_slug":"robert-desnos","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/poems-to-a-mysterious-woman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cenk Koray''ın Son Mirası', 'cenk-koray-in-son-mirasi-cenk-koray-3iri0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sizin hiç canlı  canlı kolunuzu kestiler mi? 

Hiç elinizi uzattınızmı ocakta yanan ateşin üzerine? 

Demir tokmakları, başınıza başınıza indirdilermi iri yarı adamlar? Gözü dönmüş birileri, kırdılarmı parmaklarınızı? 

Tel örgülere takıldımı sırtınız yerlerde sürünürken? 

Birisi gelip kolunuzu kıvırdımı arkaya, zorlayarak ''''çat''''diye kırıverdi mi? 

Çaresizlik denilen, çaresi bulunamayan tek gerçek, sarıldımı boğazınıza? 

Adamın biri gelip iki gözünüze iki parmağını sokup, kör ettimi sizi? 

Büyük değirmen taşlarını getirip koydularmı üzerinize sırt üstü yatarken? 

İyice bilenmiş bir bıçağı, böğrünüze sokup çevirdilermi 360 derece? 

Ayağınız kayıp yola düştüğünüzde, bacağınızın üzerinden hiç kamyon geçti mi? 

Su diye size uzatılan bardağı kafanıza diktiğinizde, içinde asit olduğunu farkettiniz mi? 

Demir bir çubuk, boğazınızdan girip boynunuzun arkasından çıktımı hiç? 

Yolda sessiz sakin yürürken, aniden birisi gelip suratınızın en ortalık yerine muhteşem bir yumruk savurdumu? 

Balkondan düşen koca bir saksı, tam kafanızın ortasına indimi? Evinizin alev alev ateşler içinde yandığını seyrettinizmi? Bir insanın sel suları içinde çırpına çırpına can verdiğini gördünüzmü? 

Veya bütün bunları görmemiş, yaşamamış bile olsanız, biraz düşününüz..İşte bunların hepsi bir anda benim başıma geldi.19 yıl babalık etmeye çalıştığım, ALLAH ın bana emaneti, canım, gülüm, hayatım, herşeyim, bitanem, sebeb-i hayatım, evladım, oğlum Nihad,3 dakika içinde yok olası kollarımın arasında ölüp gitti.Yapacak hiçbirşeyim yoktu.Kapının camı, şahdamarını kesmişti.Fıskıye gibi kan fışkırıyordu.Kan fışkırıyordu, umutlarım, istikbalim, hayatım yerlere dökülüyordu.Bana yakın durması gereken ölüm, beni ölmeden öldürüyordu.

Bugün senden ayrılalı tam 1 yıl oldu.365 günün birtanesinde bile seni göremedim, elini tutamadım, yanağını öpemedim, bağrıma basıp sıkı sıkı sarılamadım.Evde tek başıma otururken, kapıda anahtar dönmedi ve sen içeriye girmedin.Bir tek gece odanın ışığı yanmadı.Ben kapını açıp ''''yatıyorum, sen yatmıyormusun? ''''diye soramadım.

YAŞAMAK CANIMI SIKMAYA BAŞLADI.

Gül senin aradığına dair bir tek not vermedi tam 365 gündür.

Bu kadar çabuk mu unuttun beni diye düşünüyorum zaman zaman.Ama beni unutmayacağını, unutmadığını biliyorum, bende biliyorum, Halanda biliyor, Eniştende, Ece de.Ama oradan bir bağlantı kurulması mümkün değil...

Günler geçiyor arslanım.Her geçen dakikayı, beni sana yaklaştırdığı için seviyorum.Eskiden nasıl üzülürdüm, zaman geçiyor, bir gün senden ayrılıcağam diye.Ama şimdi, herşey tersine döndü.

Herşeye tahammül edebiliyor insan.ALLAH böyle bir sabır vermiş kullarına.Ama tahammülü olmayan bir tek şey var; senin sevginden mahrum olmak.Bunu hissedememek.İŞTE ÖLMEDEN BU ÖLDÜRÜYOR İNSANI..........

              CENK KORAY......', 'Sizin hiç canlı  canlı kolunuzu kestiler mi?  Hiç elinizi uzattınızmı ocakta yanan ateşin üzerine?  Demir tokmakları, başınıza başınıza indi...', ARRAY['Türk Edebiyatı','Şiir','Cenk Koray']::text[], 8.5, '{"poet":"Cenk Koray","poet_slug":"cenk-koray","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/cenk-koray-in-son-mirasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak Lambasının Aşkı', 'sokak-lambasinin-aski-vasili-konciyannis-bqcke', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sokakta bir lamba  yalnızbaşına

Sevdiği yukarı sokakta, 

Sokak lambalarına aşk yasak

Sen orda 

Bense burda

Sokakta ağlar lamba 

Ulaşamadığı Aşkına', 'Sokakta bir lamba  yalnızbaşına Sevdiği yukarı sokakta,  Sokak lambalarına aşk yasak Sen orda  Bense burda Sokakta ağlar lamba  Ulaşamadığı ...', ARRAY['Türk Edebiyatı','Şiir','Vasili Konciyannis']::text[], 8.5, '{"poet":"Vasili Konciyannis","poet_slug":"vasili-konciyannis","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sokak-lambasinin-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol Bitince', 'yol-bitince-zerrin-oktay-0fg7u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yürürken yaşamın kıyısında

bir yol çevreme göz attım 

uçsuz bucaksız ufukta 

bir ben baktım, bir bana baktım. 

Zamanın bittiği yerde 

sonrasızlığa soluklandım 

ve toplayınca gücümü 

bir adım daha attım. 

Umut, düşün yitişine ürkek 

gönül aşkın ölümüne suskun 

kara delik son öyküyken 

güneşi kırmızıya boyadım...', 'Yürürken yaşamın kıyısında bir yol çevreme göz attım  uçsuz bucaksız ufukta  bir ben baktım, bir bana baktım.  Zamanın bittiği yerde  sonras...', ARRAY['Türk Edebiyatı','Şiir','Zerrin Oktay']::text[], 8.5, '{"poet":"Zerrin Oktay","poet_slug":"zerrin-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yol-bitince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saat 12: 00', 'saat-12-00-sair-khan-7lihv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Saat öğlen 12; kuzeyden rüzgar hala acımasızca esiyor, saçlarım darmadağın

Sanki senin bugün gittiğini bilircesine, sanki üşümediğimi bilmezcesine

Senin gidişinin ilk günü, tüm duyularım organlarım hissiz

Bu kış günü ne boğazdan esen rüzgarın soğukluğu üşütüyor beni

Nede siste gemisini karaya oturtmamak için düdüğünü çalan kaptanın feryadı

Bu gün ormanın yağmurla bezendiği kokuyu da almıyor burnum

Hiç susmayan telefonlarım bile rahatsız etmiyor beni

İnsanlar aç olan karınlarını doyurmaya inerken sıra sıra 

Ben gönlümün açlığının gurultusu ile ardından yalnızca bakıyorum

Tek tadını aldığım aktığını hissettiğim gözyaşımın tuzlu tadı

Bir avuç kadar büyüklükteki yüreğim zaten senin sevgini bile sığdıramamıştı ki

Sensiz her gün geçecek dakikalara nasıl dayansın? 

Derin uykulardan uyanmış gibi gözlerim şiş beynim bulanık hani derler ya 

“Ne yerdeyim ne de gökte”işte aynen öyleyim.

Hani san çok kızardım ya işte sen sakın kızma”içim çoook sıkılıyor”

Şimdi sen dersin ne yani ölüme mi gittik çok mu uzaktayız yapma böyle

Ama şunu da bilirsin aşkım bırak saat ve dakika  metre ile ifade edilen uzaklığı

Ben senden bir karıştan fazla olan ayrılığa gurbet derim gurbet....

Saat öğlen hala 12; vakit geçmiyor bana inat Sanki oda eziyet çektirmekten hoşlanıyor, 

sanki oda biliyor geçersem bu adam vuslata  sılaya kavuşacak.

Canım odamdan çıkmak istemiyor nasıl çıkayım ki Vücut olmuş robot hemen sağa 

İki adımdan sonra sağda pencereye ağaçların arasından bakıp güzelliği izlemeye alışmış

Ama şimdi bakarda o güzelliğin yeri başkasının aldığını görürsem? 

Ya da onun bıraktığı o boşlukta onun varlığını hissedemezsem; yok asla bakamam

Sen varlığın bana fazla gelirken yoluğunu görmek...........

Şimdi tek yapabildiğim gökyüzüne bir örtünün gelip karanlık yorganını örtmesi

Gel artık kimsesizlerin karanlığı gel ki benim güneşim doğsun', 'Saat öğlen 12; kuzeyden rüzgar hala acımasızca esiyor, saçlarım darmadağın Sanki senin bugün gittiğini bilircesine, sanki üşümediğimi bilmez...', ARRAY['Türk Edebiyatı','Şiir','Şair Khan']::text[], 8.5, '{"poet":"Şair Khan","poet_slug":"sair-khan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/saat-12-00-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen/Ben', 'sen-ben-murat-tali-qmlrq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hüznün nerede yitmiş sevgili

sararmış yaprakları da yok artık ağaçların

bir kuru dala, birde rüzgara kalmış bedenim

kuşkonmazlara döndü mekansızlığım

ardıç kuşlarını yitirdim 

saka ötüşlerini 

ve serçe çığlıklarını

Nuh tufanında kurtulan iki canlı gibiydi zaman ve zamansızlık

Biri seni alırken diğer beni götürüyordu 

Sen/ben zaman olunca ben/sen zamansızlık oluyordum

Akşamı sen/ben yaptılar ben/sen gündüz oldum.

Gecede yıldızı sen/ben yaptılar gündüze güneş ben/sen oldum.

Yitip giden dalgalardan düştük KAF dağının ardına

Güneşin doğduğu yerde sen battığı yerde ben vardım

Ne dün ne de önceki gün GÜN doğmadı.

Tıpkı doğmayan/doğamayan diğer günler gibi', 'hüznün nerede yitmiş sevgili sararmış yaprakları da yok artık ağaçların bir kuru dala, birde rüzgara kalmış bedenim kuşkonmazlara döndü meka...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-ben-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şemsiyeli durak', 'semsiyeli-durak-murat-tali-wxnoz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 've gün

bitiyor

binlerce hüznü kar damlası yapıp döküvermişti saçlarıma

gözlerini kısan insanlar çarparak ilerliyorlardı benden içeri

ve benden geri

gözlerimi açtım yıldız yıldız kar tanesi gördüm

üşüyen insanlar gördüm

açılmış şemsiyelerle kapatılmış

duraklardan geçtim

gözlerim halen açık

ve dışarıda lapa lapa kar yağıyor..', 've gün bitiyor binlerce hüznü kar damlası yapıp döküvermişti saçlarıma gözlerini kısan insanlar çarparak ilerliyorlardı benden içeri ve bend...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/semsiyeli-durak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Akşam', 'bu-aksam-muzaffer-taskirmaz-ssfsp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ufukta doğan, güneşe bak

Yine ışıklar sönük, dertler saçıyor

Bu gün de akşam oldu, güneş batıyor

Kalbimde bir hüzün, yine başlıyor

Batma akşam güneşi, batma bu akşam

İçimde dertler var, gitme bu akşam

Yalnızlığın korkusu,  sardı benliğimi

Beni burada yalnız, bırakma bu akşam

Belki yarın doğarsın, belki doğmazsın

Doğsan bile beni, hiç bulamazsın

Geçen her gün dertlenir, beni ararsın

Sönmüş güneşe bakıp, sende yanarsın', 'Ufukta doğan, güneşe bak Yine ışıklar sönük, dertler saçıyor Bu gün de akşam oldu, güneş batıyor Kalbimde bir hüzün, yine başlıyor Batma akş...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bu-aksam-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amaç', 'amac-sehnaz-kart-6hd9q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün en sonunda yaptım işte, 

ulaştım amacıma 

sensizliğin derinlerinden çıka çıka…

Verdiğimde ellerine o kağıdı, 

sanki içimdeki güvercini sana verdim, 

amacımı kaybettim hayat için…

Sana ulaştığımda bile, 

seni daha çok kaybettim.

Seni daha her geçen saniye daha çok severken

ışığını kaybettiğimi farkettim- mumun dibine ışık vermediğini çok geç öğrendim.

Güneşin kılıcına 

karşı gelemedim.

Yıldızlar haber verdi bana

-kara haber tez duyulurmuş…

…hiç sevmediğin aslında beni…

Ne zaman ki ulaştım gökyüzüne, 

su gibi kayıp gittin ellerimden, tutamadım- saydamdın.

                                      Sana ulaştığım anda, 

                                      seni daha çok kaybettim…', 'Dün en sonunda yaptım işte,  ulaştım amacıma  sensizliğin derinlerinden çıka çıka… Verdiğimde ellerine o kağıdı,  sanki içimdeki güvercini s...', ARRAY['Türk Edebiyatı','Şiir','Şehnaz Kart']::text[], 8.5, '{"poet":"Şehnaz Kart","poet_slug":"sehnaz-kart","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/amac-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağlanış', 'baglanis-sehnaz-kart-r5lds', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bağlanmışım artık

bırakamam ki…

Başlamışum bir kere

sevmeye…

Gökkuşağının yedi rengi var derler, 

ama hiçbir zaman görmedim onun yedi rengini

Hiçbir zaman göstermedi, 

hissettirmedi bile…

Ancak üç rengini görüyorum senin, 

kırmızını, sarını ve mavini.

Ana hatlarınla açığa vurmaya çalışıyorum senin benliğini, 

Her ne kadar denemekle kalsam da… 

Sen bana hiç göstermedin kendini, 

Hep denizin diplerinde kaldın…

Sevgini açığa vurmadan, 

Gökkuşağıyla bağdaştın.

Ben ise, heybetli köşklerin gösterişli avizelerinin bir lambası bile olamadım…

Bir sanat eseri değil bu ortadaki, 

Yaratılan şey cansız değil.

Ben sizdenim aslında, 

Sen beni yabancı yaptın dünyaya, 

Seni farklı sanmıştım, 

Çok geçmişti ki, artık, 

Yanıldığımı anladım.

Şimdi ise vazgeçtim seni keşfetmekten, 

Seni yaşamaktan vazgeçtim.

Yağmur yağarken seni düşünmekten, 

Rüzgar estiğinde seni tenimde hissetmekten vazgeçtim.

Yalnızca

Sen olmaktan, 

Yıldızlardan, 

Ve o dakikalardan vazgeçemedim.

Sevgisizliğe cesaret edemedim.

Sensizliğe göğüs geremedim.

…

Maviye boyanmış gökyüzüne

En sonunda yenildim.', 'Bağlanmışım artık bırakamam ki… Başlamışum bir kere sevmeye… Gökkuşağının yedi rengi var derler,  ama hiçbir zaman görmedim onun yedi rengin...', ARRAY['Türk Edebiyatı','Şiir','Şehnaz Kart']::text[], 8.5, '{"poet":"Şehnaz Kart","poet_slug":"sehnaz-kart","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/baglanis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-sehnaz-kart-nnbiu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalnızım

bu soğuk odada

karşımda da kocaman bir ayna…

Yalnızım tamamen

bu acımasız dünyada

ben- hayallerimle başbaşa…

Yalnızım ben…

Yalnızım bu anlamsız hayatta, 

sen varsın karşımda 

yalnızca.

Bana bakıyor, gülümsüyorsun…

Ama yalnızca o beyaz kazaklı resminde.

Aslında sen de yoksun…

Terkettin bu dünyayı yıllar önce, 

beni de…

Benim her zaman arzu edip, hiç bir zaman beceremediğimi

sen bir anda yapıverdin.

Kendi isteğinle, kendi bilincinle.

Gittin buralardan, yoksun be yar…

Yüreğimde kapanmayacak bir delik açtın, 

Kapatmaya çalıştın

Kapanmadı.

Kalbi deliktir aşıkların

cüzzamdan beterdir aşk…

bulutların arasında

seni bulunca güneşe doğru koşmaktır aşk…', 'Yalnızım bu soğuk odada karşımda da kocaman bir ayna… Yalnızım tamamen bu acımasız dünyada ben- hayallerimle başbaşa… Yalnızım ben… Yalnızım...', ARRAY['Türk Edebiyatı','Şiir','Şehnaz Kart']::text[], 8.5, '{"poet":"Şehnaz Kart","poet_slug":"sehnaz-kart","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yalnizlik-88-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahte Gülücükler', 'sahte-gulucukler-erkon-aydin-610nv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çilesiz bir günüm yok sen olmayinca. 

Çogalir dertlerim yoklugunda. 

Sensiz günlerin anlami yok yasantimda. 

Sahte gülücükler sarmis bedenimi, ihanetler örtmüs üzerimi. 

Sessiz geçen günler, unutturamiyor seni bana. 

Söz geçiremez oldum, senle dolu duygularima. 

Faydasi yok aglamanin olmayisina. 

Sahte gülücükler sarmis bedenimi, ihanetler örtmüs üzerimi. 

Sensizlige çare olamaz hiç kimse, 

dolduramaz yerine güzeller güzeli bile. 

Hasretim, o içten gülüsüne. 

Sahte gülücükler sarmis bedenimi, ihanetler örtmüs üzerimi. 

Gezinmek senin geçtigin sokaklarda, 

aci veriyor senden koparilan canima, 

gittin gideli sen, söndü hayatimda 

Sahte gülücükler sarmis bedenimi, ihanetler örtmüs üzerimi. 

Düsünmek seni, senin olan herseyi. 

Göz önüne getirmek sevdigim seni. 

Sendin ruhumun kaybolan degeri. 

Sahte gülücükler sarmis bedenimi, ihanetler örtmüs üzerimi.', 'Çilesiz bir günüm yok sen olmayinca.  Çogalir dertlerim yoklugunda.  Sensiz günlerin anlami yok yasantimda.  Sahte gülücükler sarmis bedenim...', ARRAY['Türk Edebiyatı','Şiir','Erkon Aydın']::text[], 8.5, '{"poet":"Erkon Aydın","poet_slug":"erkon-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sahte-gulucukler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızıl Saçlı', 'kizil-sacli-ufuk-nazim-ahq5o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kızıl saçlım, 

Gülüşünde zamanı eritiyorsun, 

Kainatın köhne meşalelerini, 

Gülüşünle tutuşturuyorsun.

Farkındamısın.

Taştan bir mekanda, 

Taşlara taşıyorsun gülüşünü, 

Tarihi aşıyor, 

Zamandan taşıyorsun.

Farkındamısın.

Sen gülünce yüreğimde anaforlar, 

Kulaklarımda uğultular, 

Ve baktığım her yerde sen, 

Beni koparıyorsun zamandan.

Farkındamısın.

Sonsuza yakınsarken, 

Taşlara çizdim suretini.

Kızıl saçlım, 

Zamanı ufuklarla boyadım kızıla.

Farkındamısın.', 'Kızıl saçlım,  Gülüşünde zamanı eritiyorsun,  Kainatın köhne meşalelerini,  Gülüşünle tutuşturuyorsun. Farkındamısın. Taştan bir mekanda,  T...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kizil-sacli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoruldum', 'yoruldum-erkon-aydin-3efpv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yoruldum

		

		 Su fani dünyaya geldim geleli, 

 Bir sevda pesinde kostum yoruldum. 

 İnsan olup kendim bildim bileli, 

 Azgin seller gibi costum duruldum. 

 Sevgi sevgi diye türküler yaktim, 

 Sevda ülkesinde ben bir duraktim. 

 Nem var nem yokise size biraktim, 

 Sarmasik misali actim sarildim. 

 Bir güzel görünce figanim artti, 

 Askin kantarina cikarip tartti. 

 Kum tanesi gibi sacti firlatti, 

 Sevda cöllerinden astim yoruldum. 

 Kırkbesinde koca belim büküldü, 

 Saclarim yolundu tel tel döküldü. 

 Umutlarim iplik iplik söküldü, 

 Buzdaglari gibi dondum kirildim. 

 Hayat penceresin kapayip actim. 

 INCE bir han idi cok gelip gectim. 

 Sevda irmagindan bir zerre ictim, 

 Vefasiz bir yare taptim vuruldum', 'Yoruldum 		 		 Su fani dünyaya geldim geleli,   Bir sevda pesinde kostum yoruldum.   İnsan olup kendim bildim bileli,   Azgin seller gibi co...', ARRAY['Türk Edebiyatı','Şiir','Erkon Aydın']::text[], 8.5, '{"poet":"Erkon Aydın","poet_slug":"erkon-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yoruldum-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sone 88', 'sone-88-william-shakespeare-wfjgk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gün gelip artık bana değer vermez olduğunda,

Senin yanında yer alıp kendime karşı çıkacağım,

Hor görüp yüz çevirdiğini gördüğüm zaman bana; 

Haksızlık etsen de, senin hakkını savunacağım.

En zayıf yanlarımı en iyi ben bildiğime göre,

Çekinmeden açığa vurup arka çıkabilirim sana,

Kusurlarımdan hangisi benim için en büyük lekeyse

Beni kaybederken büyük şan kazanırsın aynı anda.

Üstelik bu işte benim için de kazanç var; 

Çünkü seven düşüncelerim sana yöneldikçe daima,

İster istemez kendime vereceğim zararlar,

Sana yarar sağlarken, kat kat yarar getirecek bana.

Öyle bağlıyım ki ben sana, öyle ki benim sevgim,

Sen haklı olasın diye, her haksızlığı üstlenirim...', 'Gün gelip artık bana değer vermez olduğunda, Senin yanında yer alıp kendime karşı çıkacağım, Hor görüp yüz çevirdiğini gördüğüm zaman bana; ...', ARRAY['Türk Edebiyatı','Şiir','William Shakespeare']::text[], 8.5, '{"poet":"William Shakespeare","poet_slug":"william-shakespeare","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sone-88-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-ziya-osman-saba-4xs88', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni görüyorum yine İstanbul

Gözlerimle kucaklar gibi uzaktan

Minare minare, ev ev 

Yol, meydan

Geliyor Boğaziçi''nden doğru

Bir iskeleden kalkan vapurun sesi

Mavi sular üstünde yine

Bembeyaz Kızkulesi

Bir yanda, serin sabahlarla beraber

Doğduğum kıyılar: Beşiktaşım

Baktıkça hep, semt semt, yer yer

Beş yaşım, on beş yaşım, ah yirmi yaşım

Durmuş bir tepende okuduğum mektep

Askerlik ettiğim kışladır ötesi

Bir gün bir kızını benim eden 

Evlendirme dairesi

Benim de sayılmaz mı oralar

Elimi tutar gibi iki yanımdan

Babamın yattığı Küçüksu

Anamın toprağı Eyüpsultan

Önümde, açık kollarıyla boğaz

Çengelköy''den aktarma Rumelihisarı

İstanbul, İstanbul''um benim

Kadıköy''ü, Üsküdar''ı

Gün olur, Köprü ortasında durur

Anarım, Adalar''da çamların uykusunu

Gün olur, Beyoğlu''nu özler içim

Koklamak isterim Tünel''in kokusunu

Bulut geçer üstünden

Gemi gelir yanaşır

Bir eski türküdür, kulağıma fısıldar

''İçi dolu çamaşır.''

Göğünde tanıdım ayın on dördünü

Kırlarında bilirim baharı

Her şey içimde, her şey

İstanbul yadigarı

Bir daha görüyorum seni dünya gözüyle

Göğün hep üstümde, havan ciğerlerimdedir

Ey doğup yaşadığım yerde her taşını

Öpüp başıma koymak istediğim şehir', 'Seni görüyorum yine İstanbul Gözlerimle kucaklar gibi uzaktan Minare minare, ev ev  Yol, meydan Geliyor Boğaziçi''nden doğru Bir iskeleden ka...', ARRAY['Türk Edebiyatı','Şiir','Ziya Osman Saba']::text[], 8.5, '{"poet":"Ziya Osman Saba","poet_slug":"ziya-osman-saba","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/istanbul-65-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayrun-Nisa', 'hayrun-nisa-yasar-donmez-w53az', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen sümbülsün, sen papatya, sensin lalezar

Ben deliyim, ben biçare, sensiz tarumar

Tatlı sözle gönlüm alsan ne olur ki yar

Şimdi kaldım yad ellerde yüreğimde nar

Sen goncasın yüreğimde açmazsın bir an

Gonca açmazsa güzeldir sevgili canan

Harab oldum özleminle tenim kan revan

Azabınla serabınla can feryat figan

Sen rüzgarsın, sen sam yeli, tatlı bir meltem

Mecnun oldum, aşık oldum, çarpıldım birden

Müstesnasın yerin kalbim her zaman her dem

Sevdim seni ne yapayım sevdiğim...... Biricik yeğenim kübra', 'Sen sümbülsün, sen papatya, sensin lalezar Ben deliyim, ben biçare, sensiz tarumar Tatlı sözle gönlüm alsan ne olur ki yar Şimdi kaldım yad ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Dönmez']::text[], 8.5, '{"poet":"Yaşar Dönmez","poet_slug":"yasar-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayrun-nisa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sinir Krizleri', 'sinir-krizleri-yasar-donmez-3mj5r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çok yalnızdım dünyamda, ama biraz mutluydum

Hep içimde nefretin ızdırabını duydum

Görürdüm ırakları, sığamazdım somuta

Yanlış yaptın bana sen, cezan ölümdü hatta

Şimdi ne oldum bilmem bu değişen ne idi

Belki senin o sefil tavırların biledi

Zihnimin kem değmemiş ama bıçaklarını

Bu gününden ne haber, düşünme hiç yarını

Gözünü bir kaparsın, bir açarsın kötürüm

Bedenin yel yemiştir, kafansa boş bir cürüm

Taşımak ağır gelir hele kopmaya görsün

Hayallerimde bin kez işte böyle ölürsün', 'Çok yalnızdım dünyamda, ama biraz mutluydum Hep içimde nefretin ızdırabını duydum Görürdüm ırakları, sığamazdım somuta Yanlış yaptın bana se...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Dönmez']::text[], 8.5, '{"poet":"Yaşar Dönmez","poet_slug":"yasar-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sinir-krizleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme...', 'gitme-onur-bozdag-2fjjc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Duvarlar anlatmıyor seni bana

Bir türkü bitiyor, 

Bir başkası başlıyor senin hayalinle...

Dışarıda yağmur, 

Dışarıda rüzgar, 

Dışarıda soğuk...

Ve içeride saat, 

Hasreti yalnızlık geçiyor.

Gecenin bir vakti, 

Hasretinle boğuşuyorum...

Kulaklarımda yankılanıyor sesler, 

''Gitme''diyor, 

''Bu şarkı yarım kalır, gitme...''

''Keder eş oldu yenemiyorum ah sensiz''diyor, 

''Bir tek seni sevdim gerisi yalan''diyor...

Ve ben elim kolum bağlı

Umutlarım kafeste bir kuş misali, 

Seni düşünüyorum...

Kurumuş bir güldeki saklı sevdayı düşünüyorum...

Yağmurdaki toprak kokusunu, 

Sonbaharda sararmış yaprakları, 

Ve uçup giden turnaları...

Hepsi sen...

Hepsi hasret, 

Hepsi yalnızlık, 

Ve belki de hepsi, 

Küçücük bir umut, 

Soğuk bir gecede, sıcacık içime dolan...', 'Duvarlar anlatmıyor seni bana Bir türkü bitiyor,  Bir başkası başlıyor senin hayalinle... Dışarıda yağmur,  Dışarıda rüzgar,  Dışarıda soğuk...', ARRAY['Türk Edebiyatı','Şiir','Onur Bozdağ']::text[], 8.5, '{"poet":"Onur Bozdağ","poet_slug":"onur-bozdag","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gitme-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyevi Aşkların Son Gecesi', 'dunyevi-asklarin-son-gecesi-seyhmus-baran-aydin-5i2fk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni sevmem imkan dahilindeydi

Ama aksi

Alakası dahilinde bile değil

Seni unutmanın mümkünatı yoktu

Her hakikat bir platonik ediyordu

Hüzün lekeli matematik defterimde...', 'Seni sevmem imkan dahilindeydi Ama aksi Alakası dahilinde bile değil Seni unutmanın mümkünatı yoktu Her hakikat bir platonik ediyordu Hüzün ...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Baran Aydın']::text[], 8.5, '{"poet":"Şeyhmus Baran Aydın","poet_slug":"seyhmus-baran-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dunyevi-asklarin-son-gecesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küsen Sevgiliye', 'kusen-sevgiliye-selen-secsev-blk5f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ne yaptım ne ettım söyle günlerimiz gecerken neşeyle

kabahat hangimizde bilmiyorum söyle sevgilim halen küsmüsün

bir garibim zannetme sen bu garip herseye boyun eger bir insana bu kadar eziyet yeter söyle sevgilim halen küsmüsün', 'ne yaptım ne ettım söyle günlerimiz gecerken neşeyle kabahat hangimizde bilmiyorum söyle sevgilim halen küsmüsün bir garibim zannetme sen bu...', ARRAY['Türk Edebiyatı','Şiir','Selen Seçsev']::text[], 8.5, '{"poet":"Selen Seçsev","poet_slug":"selen-secsev","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/kusen-sevgiliye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-birol-ozkan-q0cpu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir ayrılık olursa

Kaç gün sürer? 

Kaç kez unutmazsın? 

Neler hatırlatır, 

neler kaçırır seni benden? 

Kaçacağın yer neresidir, 

gerçek midir benden uzak? 

Düşünür müsün hiç? 

GÖNÜL''ü duyduğunda bir yerden

tüylerin ürperir mi? 

ikinci kez dinleyebilir misin? 

Yoksa kapatıp, ıssızlıkta ağlar mısın? 

sessiz sessiz.......

Bir mavi gördüğünde

içine bakar mısın? 

yoksa yine

gizleyerek gözlerini ağlar mısın

kimse görmeden? 

Peki deniz

Her zaman yanında, 

her an karşında istersen

işte orada der misin elini uzatıp? 

Konuşur musun kimse duymadan, 

martılardan mı çekinirsin, 

yoksa korkar mısın hırçın dalgalardan? 

Bir fotoğraf elinde, 

bakabilir misin? 

Hatırlar mısın? 

o anı yaşayabilir misin bir daha? 

Yürüyebilr misin sahilde, 

bilmediğin caddelere, sokaklara girebilir misin? 

cesaretin olur mu? 

yoksa görmek mi istemezsin sevdiğini? 

Peki bir yalan daha söyler misin, 

sevdiğin için? ..............', 'Bir ayrılık olursa Kaç gün sürer?  Kaç kez unutmazsın?  Neler hatırlatır,  neler kaçırır seni benden?  Kaçacağın yer neresidir,  gerçek midi...', ARRAY['Türk Edebiyatı','Şiir','Birol Özkan']::text[], 8.5, '{"poet":"Birol Özkan","poet_slug":"birol-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ayrilik-86-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını Koyamadığım Şiir', 'adini-koyamadigim-siir-dafne-avril-livorced-ay-w7sgw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün yine seni düşündüm saatlerce 

Kine, nefrete, umutsuzluğa inat bir sevgiyle...

Yine seni sevdim delice...

Düşümde hayal kırıklıkları vardı, 

Hayal kırıklıklarımda hüzün, 

Hüznümde gözyaşı, 

Gözyaşımda sonsuzluk, 

Sonsuzluğumda o hiç yeşermeyen umutlarım, 

Ve umutlarımda; 

Hiçbir zaman kavuşamayacağım

Sen vardın...

Dün yine seni andım sadece

Karşılıksız sevginin ağırlığı

Omuzlarıma çökmüşçesine

Ve o yükün altında ezilircesine...

Ve ben dün; 

Yine seni sevdim delice...

Sana hiçbir zaman kavuşamayacağımı bile bile...', 'Dün yine seni düşündüm saatlerce  Kine, nefrete, umutsuzluğa inat bir sevgiyle... Yine seni sevdim delice... Düşümde hayal kırıklıkları vard...', ARRAY['Türk Edebiyatı','Şiir','Dafne Avril Livorced Ay']::text[], 8.5, '{"poet":"Dafne Avril Livorced Ay","poet_slug":"dafne-avril-livorced-ay","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/adini-koyamadigim-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizlerle Dolu Kadına Şiirler', 'gizlerle-dolu-kadina-siirler-robert-desnos-92iyb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gizlerle Dolu Kadına Şiirler

O kadar düşündüm ki seni, 

gerçekliğini yitirdin.

Vakit var mı daha erişebilmek için bu canlı vücuda ve öpebilmek 

	İçin bu ağzın üstünde sevdiğim sesin doğuşunu

Öylesine düşündüm ki seni

uyamıyacak artık vücudunun çizgilerine, 

gölgeni kucaklarken göğsümde 

kavuşmaya alışık kollarım belki de

Ve günlerdir, aylardır beni yöneten 

	aklımdan hiç çıkmayan şeyin gerçek görünüşü önünde

	bir gölge olcağım şüphesiz, 

ey duygusal dengeler, 

O kadar düşündüm ki seni vakit yok uyanamam, iş işten geçti.

	Ayakta uyuyorum, vücudum, aşkın, yaşamın bütün görüntülerine 

	Açık ve sen bugün benim için değerli tek insan, karşıma çıkan

 ilk alna, dudaklara dokunabilirim de 

senin alnına dudaklarına dokunamam.

O kadar düşündüm ki seni

O kadar yürüdüm, konuştum, yattım  ki senin hayalinle bana kalan

tek şey belki de hayaller arasında bir hayal olmak, bana kalan tek şey

yaşamımın güneş saatinde keyifle gezinen, 

gezinecek olan gölgenin yüz katı gölge olmak', 'Gizlerle Dolu Kadına Şiirler O kadar düşündüm ki seni,  gerçekliğini yitirdin. Vakit var mı daha erişebilmek için bu canlı vücuda ve öpebilm...', ARRAY['Türk Edebiyatı','Şiir','Robert Desnos']::text[], 8.5, '{"poet":"Robert Desnos","poet_slug":"robert-desnos","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gizlerle-dolu-kadina-siirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürümelisin', 'yurumelisin-ahmet-senkabak-l9nj0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'dilinden kalkan sözcükler

kanatlarını çırpa çırpa

dolanıyor kulaklarımda

biliyorsun

gözlerinde yakalandı; mayıs çiçekleri

sen....rüzgarın kızısın

           insan yanısın umutların

denizleri cekmişsin kötünün önüne

yürüyeceksin

yürümelisin...!', 'dilinden kalkan sözcükler kanatlarını çırpa çırpa dolanıyor kulaklarımda biliyorsun gözlerinde yakalandı; mayıs çiçekleri sen....rüzgarın kı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şenkabak']::text[], 8.5, '{"poet":"Ahmet Şenkabak","poet_slug":"ahmet-senkabak","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yurumelisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateşler', 'atesler-ahmet-senkabak-teaau', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ateşler atıp

yakıp gitmek derdin değil

                           biliyorum

bende saklı kalmış hüznün

beni kalbinin arka nehirlerine döktün

akıyorum karanlığa

mutlumusun? 

kağıttan dağlara yaslanıyormusun?', 'ateşler atıp yakıp gitmek derdin değil                            biliyorum bende saklı kalmış hüznün beni kalbinin arka nehirlerine döktün ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şenkabak']::text[], 8.5, '{"poet":"Ahmet Şenkabak","poet_slug":"ahmet-senkabak","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/atesler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzerine Alanin', 'uzerine-alanin-osman-oztunc-vd4va', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sozumuz meclisten disari hasa

Beyler gorduk efendiler tanidik

Desen ar gelecek dole usaga

Beyler gorduk efendiler tanidik

Madem sordun bende diyeyim amca

Af dileriz cemil cumleden once

Velakin sohbete soze gelince

Beyler gorduk efendiler tanidik

Yeminliler bu milleti bolmeye 

Karpuz gibi dilim dilim dilmeye 

Dilinen parcaya pazar olmaya

Beyler gorduk efendiler tanidik

Yoklukla devleti koturum yapan

Milletin sirtina oturum yapan

Gelecek secime yatirim yapan

Beyler gorduk efendiler tanidik

Cikip kursulerden nutuk savuran

Konusup meydani kasip kavuran

Inip shakira dan guzel kiviran

Beyler gorduk efendiler tanidik

Ciz etsin yuregin diyeyimde ciz

Her firsatta alemin kizini taciz

Eder kendi avradini ilgiden aciz

Beyler gorduk efendiler tanidik

Is bulmaya gelen bayana dumduz

Ya sarkintilik var yada tecavuz

Ne kadar bedava ne kadar ucuz

Beyler gorduk efendiler tanidik

Bir birine iftira bas donduren

Ne yalanlar duydum kani donduran

Yetimi kandiran dulu kandiran

Beyler gorduk efendiler tanidik

BUrda olsalarda gostersem tek tek

Fakat sorun bunlarda degilki tek

Avradindan baska herkese erkek

Beyler gorduk efendiler tanidik

Eveti unutup yes artik diyen

Nasil tespit ettin pes artik diyen

HEr dogru soylenmez sus artik diyen

Beyler gorduk efendiler tanidik

Mecburum demeye duyunuz bu sart

Bildiginiz buyuklerin hepsi carrtt

Az da olsa mayadan mert oglu mert 

Beyler ogrduk efendiler tanidik

Duy beni ablasi babasi genci

Duyun ruhunuza gecsin bu sanci

Bazisi oglanci bazisi subyanci

Beyler gorduk efendiler tanidik

BU milletin diliysen yaz gec diyen

Degil isen sazindan  vaz gec diyen

Suclu isem benide ez gec diyen

Beyler gorduk efendiler tanidik

Hey Osman'' i Osman yapan sevda

Istirabin bile muhtesem bir sey

Insan suretinde ya bilmiyomki ney

Beyler gorduk efendiler tanidik', 'Sozumuz meclisten disari hasa Beyler gorduk efendiler tanidik Desen ar gelecek dole usaga Beyler gorduk efendiler tanidik Madem sordun bende...', ARRAY['Türk Edebiyatı','Şiir','Osman Öztunç']::text[], 8.5, '{"poet":"Osman Öztunç","poet_slug":"osman-oztunc","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/uzerine-alanin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup', 'mektup-ozgun-enver-bulut-9mbsw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'rüzgar ve yağmur diyor ki

insanın kaybolduğu bir uçurumdur bu kent

ve sarhoş masalarından arta kalan para üstüdür artık aşk.

sahte sözcükler kadar çarpar kalbin duygusuz gecelerde

yalandır sana bakan gözlerdeki cılız ışıltı

yalandır dudakların zehir kokan kırmızısı

ah uykusuz gecelerim

yeryüzünün soluksuz kalmış bütün topraklarında yanan kalbim

geçmiş zaman kavimlerinde arama ihaneti

seni ölüme yaklaştıracak herşey biraz ihanettir

herkezin seni konuştuğu ve sana taptığı günleri düşün

düşün gücünün altında sinen ve büyülenenleri

''''kardeşlerim, yarenlerim, dostlarım, yoldaşlarım, sevgililerim''''

beni anlamaya çalışanlar ve anlamayanlar

ucuz bir masal değil yaşanılanlar ellerimi tutun yeter

ellerimi tutun yeter. rüzgar bunu diyor

sarılın ona diyor yağmur

tapmak ve küçümsemek iktidarın iki rengidir

oysa bilgelerin dudaklarından dökülen sadece öğüttür

övgülerse biraz öfkedir ve yürek aldatır

bir mektuba başlar gibi bakmak istiyorum sana

sözün büyüsüyle sallanan saçların kapasın yüzümü

bırak biraz da böyle sızlasın vicdanım

derinde ipe dizilmiş yaralarım tümden değil

bu gerçek, esmer ve dile ait

kırılgan ilişkiler sırtımda yük

işte bu anlarda bırak her yerimi şiir sarsın

işte bu anlarda bırak yalnızlık üstümü örtsün

geceye gömdüm bakışların anlamını

say ki konacak bir dalım yok

say ki sokaklara düşmüş bir gölgeyim

hakkım olmayan kötülükler sarsıyor yüreğimi

ve nedensizce yalan söylüyor tanıdığım insanlar

şimdi ben acıyan ve örselenen bir adamım

hayatın önünde itiraf ediyorum

anlamak temiz kalmak kadar başlangıçtır', 'rüzgar ve yağmur diyor ki insanın kaybolduğu bir uçurumdur bu kent ve sarhoş masalarından arta kalan para üstüdür artık aşk. sahte sözcükler...', ARRAY['Türk Edebiyatı','Şiir','Özgün Enver Bulut']::text[], 8.5, '{"poet":"Özgün Enver Bulut","poet_slug":"ozgun-enver-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/mektup-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zulanda Yaşıyorum', 'zulanda-yasiyorum-ahmet-senkabak-7a5hi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'masanın üstündeyim 

çercevenin içinde

kımıldamadan sana bakıyorum

...

sen dönüp duruyorsun odada, kaygılı

zaman zaman irkiliyorsun

odadaki sessizliği ayak seslerin, kırıyor

.....

odayı saran öfkeni

eşyaların yankısına bırakıyorsun

gözlerinle daglıyorsun geçmişi

....

tırnaklarını yiyorsun

kafanda taşıdığın ben

ağır geliyorum....

müthiş bir yorgunluk çöküyor bedenine

....

''kar yağıyordu elin elimi bıraktığında

sende bir bilet....anıların yolcusuydun artık! ''

....

çekip sandalyeye oturuyorsun

ellerin arasına alıyorsun başını

saçların ne kadar uzamış....

sıkılıyorsun saçlarından

.......

gün dönüyor

cama yapışıyor karanlık

ışığa dokunacak parmakta, sigara

titriyorsun açlıktan

....

kapının zili çalıyor

....

masanın üstündeki ben

zulanda buluşuyoruz

...

saçlarını hiç kesme

..............', 'masanın üstündeyim  çercevenin içinde kımıldamadan sana bakıyorum ... sen dönüp duruyorsun odada, kaygılı zaman zaman irkiliyorsun odadaki s...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şenkabak']::text[], 8.5, '{"poet":"Ahmet Şenkabak","poet_slug":"ahmet-senkabak","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/zulanda-yasiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemin Soluğunda', 'ozlemin-solugunda-ozgun-enver-bulut-zp2y5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sanıyorum özlediğim gündü.dündü.

elveda kadar bir boşluktu ayrılık

geceydi.sana değiyordu.

saçlarım gözlerin diyordu.

ötelerde dağılan yürekler gibi efkarlıyken sular

düşen yıldızlar kadar eksilir gökyüzü

gündüz hükmü olmayan gölge

hüzündür.düşer geceye.

iz sürer bir baba

gölge yanar.

sanıyorum özlediğim gündü.dündü.

gitarın eskiyen tellerinde eriyordu sözlerim

kimsenin merak ettiği de yoktu

ölüm sadece öleni yakıyordu

ötekiler yangından çok uzaktı.

nasıl düşerim ardına şimdi

dudakların böyle giz doluyken

hançeri suluyor gözyaşlarım intihar öncesi

uzaksın. hangi mefsimde öleceğimi düşünüyorum

babam da uzak

anneme benziyor acılı kadınlar

kırık tırnaklarıyla geziyorlar

sanıyorum özlediğim gündü. dündü.

gözlerim kördü. kötülük vurmuştu

günahlarımı temizliyordu kalbin

düşündüğüm son barınaktı istanbul

sarsıyordu. özlemin soluğumdu. soğuktu.

ellerin kayıyordu.', 'sanıyorum özlediğim gündü.dündü. elveda kadar bir boşluktu ayrılık geceydi.sana değiyordu. saçlarım gözlerin diyordu. ötelerde dağılan yürek...', ARRAY['Türk Edebiyatı','Şiir','Özgün Enver Bulut']::text[], 8.5, '{"poet":"Özgün Enver Bulut","poet_slug":"ozgun-enver-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ozlemin-solugunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklerken Sevebilmek Seni', 'beklerken-sevebilmek-seni-mehmet-ali-kadakal-sprma', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ömrümün yarısı seni sevmekle geçti

Kalan yarısı beklemekle dönmeni

Geciken otobüsler vardır bilirsin

Kış sabahları, alacakaranlıkta

Üşümüş gözlerinde umut olur

Uzakta duyulan her motor sesi

Gelen beklenen olmaz çok zaman

Sıcak bir kış yolculuğu gibidir seni sevmek

Uzak bilinmeyenlere

Beklemekse zahmetsiz

Dal gibi kalmak

Ta ki gelene kadar beklenen

Ertelemek tüm işleri

Ya beklenen gelmezse

Varsın gelmesin

Ben beklerken de seni seviyorum

Gelmek nasıldır bilmem

Hiç giden olmadım

Uğurlamalardır işim

Gidenlerin ardından sallanan

Beyaz mendiller biriktiririm ben

Bir de ayrılık şiirleri

Kış gibi soğuk

Çığlık gibi isyankar şiirler

Ben beklerken gelirsen bir gün

Ve bulamazsan mührünü

Kalbimde gözlerinin

Anla ki artık ağlamak vaktidir 

Gelen beklenen olmamıştır yine', 'Ömrümün yarısı seni sevmekle geçti Kalan yarısı beklemekle dönmeni Geciken otobüsler vardır bilirsin Kış sabahları, alacakaranlıkta Üşümüş g...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kadakal']::text[], 8.5, '{"poet":"Mehmet Ali Kadakal","poet_slug":"mehmet-ali-kadakal","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/beklerken-sevebilmek-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buluşma', 'bulusma-ozgun-enver-bulut-uh5tj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sabah

rüzgarının

pencereden

içeriye

girmesi

kadar

güzeldir

seni

sevmek

ve

seni

sevmek

imgenin

tutkuyla

buluşup

göz

kırpmasıdır

şiire...', 'sabah rüzgarının pencereden içeriye girmesi kadar güzeldir seni sevmek ve seni sevmek imgenin tutkuyla buluşup göz kırpmasıdır şiire......', ARRAY['Türk Edebiyatı','Şiir','Özgün Enver Bulut']::text[], 8.5, '{"poet":"Özgün Enver Bulut","poet_slug":"ozgun-enver-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bulusma-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aranıyor', 'araniyor-ozgun-enver-bulut-dcxjn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'eskisi gibi olmayan çizgiler kadar yalnızdır düşler

harap ve kısa uzun ve üzgün

günbegün yok olan doğumuzdaki kenttir

ve yönsüz bir kadırgadır mavisiz denizlerde

anlamını yitirmiş sözler saklanacak mekan arıyor

oysa mekansız büyüyor aşklar

saklanamıyor, çabuk yitiyor ve sır olmaktan çıkıyor

sır saklanabildikçe sırdır diyor bir ses

aranıyor ilanlarında kaybolan aşklarının izini sürüyor

zaman dicle kadar yorgun fırat kadar bağlı

yalnızca acılar anlaşılabiliyor ayrılıklar karmaşıkça

vicdanı farklı kılan ayrıntılardır diyorum

işte tam burda yağmalanıyorum

ayrıntıları anlatamıyor aranıyor ilanlarına gizleniyorum.

dostlar uzaklarda ötelerde berilerde

bir yerlerde sonuçta, farkeder mi

sigara dumanı kadar renkli

şarap kadar kırmızıdırlar en fazla

yalnızlığa yüreksizlik diyorlar

en çok da yüreklerinden kanıyorlar

ey sevgili, göçmen kuşlar çocuklukta kaldı

çığlık özgürleştirmiyor kanatları

gittikçe azalıyor sevgi çoğalan azı dişleri

biz kadırganın yelkenlerini tual sanıyoruz hala

ölüm bile sefer sayısı kadar mesai yapıyor

bahar yorgunu anılar tükenerek geçiyor boğazdan

en çok mazlumlar haklı yenilen de hep onlar

sabır bedenin içten içe çürüyüşünün adıdır diyor oğlum

devler masal kahramanı geriye cüceler kalıyor

bir de o çok sevdiğimiz çocuklar', 'eskisi gibi olmayan çizgiler kadar yalnızdır düşler harap ve kısa uzun ve üzgün günbegün yok olan doğumuzdaki kenttir ve yönsüz bir kadırgad...', ARRAY['Türk Edebiyatı','Şiir','Özgün Enver Bulut']::text[], 8.5, '{"poet":"Özgün Enver Bulut","poet_slug":"ozgun-enver-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/araniyor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Askerleri', 'askin-askerleri-salih-ozalasan-4ecsz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nasılda güvenmiştim vefasız kalbime

İhanet etmez diyordum asla bedenime

Siper etmez diyordum beni aşkın hançerine

Gözyaşı girmez diyordum asla gecelerime

Bir oyun sandım kandım gülüşlerine

Bir anda kapıldım titreten öpüşlerine

Beni hayallere salan tatlı sözlerine

Sevgiyle parlayan güzel gözlerine

Şimdi gecelerim, çığlık çığlığa yalnızlık

Günler uzadı, fersah fersah ayrılık

Özlem içimde sinsi sinsi aklımda çılgınlık

İsyan etmek geliyor hep bedenime

Yüreğimde yeni bir sevda alev alev

Prangalar vurulmuş paslı zincirler bedenimde

Amansız bir savaş aşkın askerleriyle

Başka bir el gezinirken bedenimde

Sadece anlamsız bir bakış

Ondan ötesine izin yok beynimde

Yeniden mutluluk çok zor belkide bende

Kalbim asla izin vermiyor mutluluğa bedenime

Yenik düştüm kalbimin sevdiğine, 

İhanet etsemde benliğime

Bir daha dönemem geri

Gidiyorum kalbimin sevdiğine

İhanet belki çok acı

Ama muhtaçmışım bir sevgiye

Yüreğim benim, yüreğimde sevdiğim

Asla hükmedemem artık bedenime

Y. Tar 10-11-2002 Saat 10.00', 'Nasılda güvenmiştim vefasız kalbime İhanet etmez diyordum asla bedenime Siper etmez diyordum beni aşkın hançerine Gözyaşı girmez diyordum as...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/askin-askerleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Ayrılık', 'adi-ayrilik-salih-ozalasan-2hx3a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Adı ayrılık soyadı hasret

Lakabı sonserseri, mekanı mynet

Baharı tanımaz, sonbaharda hep

Onun gecesi bir dert, gündüzü ayrı dert

İsterki hep hoş sohbet

Zamanı varmı sormaz başıma dert

Bazen sitemlerinden bunaltır beni

Şeytan diyor şu serseriyi gebert

Bir kıyabilsem varya ben ona

Ancak edebiliyorum tatlı sert

Sanki benim derdim bana yetmez

Geceler boyu ederim muhabbet

Sitemkarımya etmeyelim haksızlık

Bir bilseniz nede hoş sohbet

Dilinden ya bal damlar, yada sitem dert

İkisinin ortasını bulsa Dünya''da vallahi tek

Dili sivri, hele bir kalemi varki

Düşenin bu Dünya''yı lazım etmesi terk

Sevgilere kucak açmış yüreği

Benim serserim bu Dünya''da tek

Y.Tar.18-10-2002 Saat 20.34', 'Adı ayrılık soyadı hasret Lakabı sonserseri, mekanı mynet Baharı tanımaz, sonbaharda hep Onun gecesi bir dert, gündüzü ayrı dert İsterki hep...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/adi-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Kalbimde Kalacaksın Değilmi', 'hep-kalbimde-kalacaksin-degilmi-salih-ozalasan-uw3v5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben hep sevdim biliyorsun değilmi

Kalbi güzel olan herkesi

Ben bazen çok ağladım değilmi

Bazen seçtim kötü kalplileri

Ama vazgeçmedim sevmekten

Sevmek hayatın kaynağı değilmi

Gülü sevdim dikeni sevdim

En çok seni sevdim değilmi

Gülün bazen çabuk geçti mevsimi

Dikense elimi kanattı kestim değilmi

Ama sen ama sen kırıyorsunya kalbimi

Bir seni sevmekten vazgeçemedim değilmi

Seninle hüzün güzel neş''e bir başka

Bir ömür solmayacak olan sensin değilmi

Kederime yazmasada yazan kalem seni

Gitmek yok hep orada kalacaksın değilmi

Y.Tar 03-11-2002 Saat 15.23', 'Ben hep sevdim biliyorsun değilmi Kalbi güzel olan herkesi Ben bazen çok ağladım değilmi Bazen seçtim kötü kalplileri Ama vazgeçmedim sevmek...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hep-kalbimde-kalacaksin-degilmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başlıyor', 'basliyor-ahmet-murad-32qo1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-Başlıyor.

-Bitiyor.

-Bana korkular yetiyor.

-Gidiyor.

-Geliyor.

-Küçük beynimi deliyor.

-Yürüyor.

-Duruyor.

-Onulmaz sorular soruyor.

-Gülüyor.

-Ağlıyor.

-Beni kendine bağlıyor.

-Seviyor.

-Sevmiyor.

-Bu kadar düşünmeye değmiyor.', '-Başlıyor. -Bitiyor. -Bana korkular yetiyor. -Gidiyor. -Geliyor. -Küçük beynimi deliyor. -Yürüyor. -Duruyor. -Onulmaz sorular soruyor. -Gülü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Murad']::text[], 8.5, '{"poet":"Ahmet Murad","poet_slug":"ahmet-murad","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/basliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek Bu Değilmi', 'sevmek-bu-degilmi-salih-ozalasan-usc8b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Baktınmı hiç gözlerime

Sevdiğimi söylerken sana seni

Dinledinmi hiç kalbimin sesini

Uzanıp tuttuğunda titreyen ellerimi

Sana olan sevgim değilmi

Bu hayata bağlayan umut beni

Sen yoksan nedir hayatın değeri

Ben sana sensiz 

Dünya''yı da verseler istemem demedimmi

Yüreğime nokta nokta işlenen

Azgın nehir olup çağlayan

Tam hayattan umut kesdiğimde

Beni hayata bağlayan

Söyle senin sevgin değilmi

Y.Tar 21-10-2002 Saat 18.55', 'Baktınmı hiç gözlerime Sevdiğimi söylerken sana seni Dinledinmi hiç kalbimin sesini Uzanıp tuttuğunda titreyen ellerimi Sana olan sevgim değ...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevmek-bu-degilmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siz', 'siz-salih-ozalasan-5uhan', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Siz hiç akdenizde günbatımını

Yüreğiniz kan ağlayarak izledinizmi

Denize vuran kızıl yakamozda

Uzaklarda birini özledinizmi

Gözyaşınızı yüreğinize akıttınızmı

Morarmış gözlerinizi gizledinizmi

Siz hiç umutsuz bir sevdaya tutulup

Günler boyu yol gözledinizmi

Siz hiç yıldız saydınızmı

Gecenin karanlığında uykuyu bölmek için

Yıldızlara sevdiğinizin ismini verip

Onlara selam ettinizmi geceler boyu

Siz hiç benim gibi sevdinizmi

Görmeden çok uzakta bir sevgiliyi

Siz yüreğinizde hiç sevda gizledinizmi

Yüreğiniz sel olup çağlarken

Sevmiyorum oda kim diyebildinizmi

Siz karşılığında gözyaşına boğulduğunuz

Bir sevgiye göğüs gerebildinizmi

Dahası siz hiç yüreğinizi

Parça parça bölebildinizmi

Y.Tr.12-10-2022  Saat 16.00', 'Siz hiç akdenizde günbatımını Yüreğiniz kan ağlayarak izledinizmi Denize vuran kızıl yakamozda Uzaklarda birini özledinizmi Gözyaşınızı yüre...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/siz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Olmasan', 'sen-olmasan-kelkitli-summani-ekwxs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şaire, nasıl bakılır

Arif Nihat sen olmasan? 

Çocuk, nasıl anlatılır, 

Arif Nihat sen olmasan? 

Mavi karanlıkta kalır

Güneş batar, ay tutulur, 

O renk, nasıl anlatılır, 

Arif Nihat sen olmasan? 

Unutur öpmeyi canlar, 

Yetim kalır al dudaklar, 

Rüzgarı öpen bayraklar, 

Arif Nihat sen olmasan

Ölür güzelim nineler, 

Ninniler biter ninniler, 

Giymez gelin gelinlikler, 

Arif Nihat sen olmasan.

Petekler arısız balsız, 

Yar duvaksız, nehir salsız, 

Denizler kalır kayıksız, 

Arif Nihat sen olmasan.

Çürümüş iki yanağı, 

Tarih olmuş vapurları, 

Bulamazdım anlatanı

Arif Nihat sen olmasan.

İçerdim ben bu dünyada, 

Kadeh kırdım köhne barda, 

Oynardım ben sazda barda, 

Arif Nihat sen olmasan.

Sigaram var sarım sarım, 

Elime alır bakarım, 

Yakmadan çöpe atarım, 

Arif Nihat sen olmasan.

Sabırsızdır bil çocuklar, 

Boş kalmasın o sokaklar, 

Ciddi doğar bil çocuklar, 

Arif Nihat sen olmasan.

Neye yarar o karalar, 

Olmasa yarımadalar, 

Kurulmaz mavi sofralar, 

Arif Nihat sen olmasan.

Çocukları, ağaçları, 

Canlı sever canlıları, 

Kim bilir bu gizli sırrı, 

Arif Nihat sen olmasan? 

Kalemin ok, gönlün yayı, 

Düşman olur ondan payı, 

Gökte güneş olmaz ayı, 

Arif Nihat sen olmasan.

Anlatmaz torunlarını, 

Haramların o tadını, 

Arzulamaz helalini, 

Arif Nihat sen olmasan.

Bilemezdik aşk satanı, 

Hortum olan o kadını, 

Sade dudak ve tadını, 

Arif Nihat sen olmasan.

Dağlar dağlar size ağlar, 

Yağmur yüklü o bulutlar, 

Onları kim yere bağlar, 

Arif Nihat sen olmasan? 

Estergon''u anlatacak, 

Tarihimiz şan bulacak, 

Destanını kim yazacak, 

Arif Nihat sen olmasan? 

Mazimizi satır satır, 

Saray, kale, türbe, yatır, 

Neslimize kim anlatır, 

Arif Nihat sen olmasan? 

Yavuz''ları kim anacak, 

Kahpeliği kim bozacak, 

Bayrak şair kim olacak, 

Arif Nihat sen olmasan? 

'' Mozaleyi yok '' sayacak, 

Türbeyi kim, kim anacak, 

Ata''yı kim, kim bilecek, 

Arif Nihat sen olmasan? 

Orduların öncüleri, 

Zaferlerin, Bozkurt''ları

Atatürk''ün çocukları, 

Kim bilecek, kim onları, 

Arif Nihat sen olmasan?', 'Şaire, nasıl bakılır Arif Nihat sen olmasan?  Çocuk, nasıl anlatılır,  Arif Nihat sen olmasan?  Mavi karanlıkta kalır Güneş batar, ay tutulu...', ARRAY['Türk Edebiyatı','Şiir','Kelkitli Summani']::text[], 8.5, '{"poet":"Kelkitli Summani","poet_slug":"kelkitli-summani","theme":"Türk Şiiri","is_hero":false,"total_lines":81,"source_url":"https://www.antoloji.com/sen-olmasan-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığın Askerleri', 'yalnizligin-askerleri-salih-ozalasan-1vutu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalnızlığın askerleri esir almış yüreğimi

Hücre hapsindeyim geceleri

Prangalar vurulmuş yüreğime

Sana mahkum, sensin yaşıyorum günleri

Cezam seni sevmek

Bilmiyor yalnızlığın askerleri

Yürekleri taşlaşmış kararmış gönülleri

İstemiyorlar benim seni böylesine sevmemi

Kızgın demirlerle dağladılar bedenimi

Kollarım taşımıyor artık zincirleri

Bilmiyorlarki değiştirmez hiçbirşey asla fikrimi

Söküp alamaz kalbimden asla seni

Sende orda hapsolmuşsun

Farkında değil, yanlızlığın askerleri

Y.Tar.29-10-2002 Saat 17.40', 'Yalnızlığın askerleri esir almış yüreğimi Hücre hapsindeyim geceleri Prangalar vurulmuş yüreğime Sana mahkum, sensin yaşıyorum günleri Cezam...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yalnizligin-askerleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek Nedirki', 'sevmek-nedirki-salih-ozalasan-o0znq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreklerde hep çilekeş şarkılar

Yakılır karakaşa kara göze ağıtlar

Sevdalara yol alır farkında olmadan ayaklar

Uyku tutmaz gözleri ateş olur yataklar

Kıskanırsın bakan gözlerinden

İstersin feyz alsın hep sözlerinden

Bazen bal bazen zehir damlayan sözlerinden

Ruhun zindanda yüreğin kahırdan çatlar

Gözünden sakınırsın nazara gelmesin

İstersin kimselere selam vermesin

Bir seni sevsin başka sevgi bilmesin

Gözünün içine bakarda kaçamak gelir bakışlar

Aşk budur yüreğinde yaralı ceylan

Herdoğan günde birbaşka heyecan

Kalpten kalbe olur daim seyelan

Seven kalbin sahibine hep korkular

Seviyorsan yoktur rahat bir günün

Avuçlarında solacak sanırsın gülüm

Bir gün görmesen yaşarsın bin ölüm

Sevgi hasret hasrete bağlanır umutlar

Y.tar.05-11-2002 Saat 19.27', 'Yüreklerde hep çilekeş şarkılar Yakılır karakaşa kara göze ağıtlar Sevdalara yol alır farkında olmadan ayaklar Uyku tutmaz gözleri ateş olur...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevmek-nedirki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldırım Aşkı', 'yildirim-aski-salih-ozalasan-wnr63', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen, Sen yokmusun sen

Nasıl, Niçin, 

Nereden, girdin hayatıma

Beyaz atlı prens desem

Değilsin

Senin bir atında yok aslında

Nasıl tanıdım seni

Nasıl çevirdin beni

Biranda böyle şaşkına

Oysa ben hiç inanmazdımki

Masallarda sanırdım

Yıldırım aşkına

Şaşkınım, allak bullak oldu hayatım

Heryerde sen çıkıyorsun karşıma

Baktığım heryerde sen

Oda yetmedi sanırım

Şimdi birde girdin rüyalarıma

Gönlüme dur diyorum, 

Durmuyorki

Dinlemez oldu artık sözümü

Bu nasıl aşk böyle

Görmeden aşık oldum senin yüzünü

Of Allah''ım of offf! ! ! 

Çaresizim; esir etti gecemi gündüzümü

Nasıl oldu anlıyamadım amma

Birlikte paylaşır olduk

Hem sevincimizi, hemde hüznümüzü

Bir gecede yıldırım aşk

Beni ne hale düşürdü gördünüzmü

Y.Tar.15-10-2002 Saat 16.15', 'Sen, Sen yokmusun sen Nasıl, Niçin,  Nereden, girdin hayatıma Beyaz atlı prens desem Değilsin Senin bir atında yok aslında Nasıl tanıdım sen...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yildirim-aski-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ziyafet Var', 'ziyafet-var-ahmet-murad-b3olf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kıskıs gülüşmeler ve sessiz bir bekleyiş.

Sönen lambalar.

İbresi geriye dogru duvarda saat.

Yüzüme bakan aynalar.

Küflenmiş perdeler, yarıya kadar açık.

Dökülüyor ağızlardan salyalar.

Biteviye bakıyor çingene yüzlü kapı. 

Patlıyor şampanyalar.

Ziyafet var beynimin zift karası sofrasında.

Çalıyor tepemde kumpanyalar.

Birden bir serzeniş ve kendine geliş.

Bitiyor korkulu rüyalar.

Sen aklıma geliyorsun güzel yüzünle

Benim oluyor dünyalar.', 'Kıskıs gülüşmeler ve sessiz bir bekleyiş. Sönen lambalar. İbresi geriye dogru duvarda saat. Yüzüme bakan aynalar. Küflenmiş perdeler, yarıya...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Murad']::text[], 8.5, '{"poet":"Ahmet Murad","poet_slug":"ahmet-murad","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ziyafet-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sığındım Ben', 'sigindim-ben-kelkitli-summani-d6mvl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düşündüm ki...

Ben ne idim ben ne oldum

Ben sırrına sığındım ben

Düşündüm ki...

Hava oldum  suyun oldum

Deryalara sığındım ben

Düşündüm ki...

Besin oldum yemek oldum

Midelere sığındım ben

Düşündüm ki...

Alkan oldum nutfe oldum

Bedenlere sığındım ben

Düşündüm ki...

Nutfe idim bir can oldum

Anarahme sığındım ben

Düşündüm ki...

Umut oldum bebek oldum

Kucaklara sığındım ben

Düşündüm ki...

Uyanıktım uyur oldum

Beşiklere sığındım ben

Düşündüm ki...

Emeklerdim yürür oldum

Sokaklara sığındım ben

Düşündüm ki...

Allah dedim mümin oldum

Yaradana sığındım ben

Düşündüm ki...

Ağlar idim güler oldum

Mutluluğa sığındım ben

Düşündüm ki...

Gece idim gündüz oldum

Şafaklara sığındım ben

Düşündüm ki...

Büyüdüm de engin oldum

Olgunluğa sığındım ben

Düşündüm ki...

Muşuk idim aşık oldum

Güzellere sığındım ben

Düşündüm ki...

Leyla idim mecnun oldum

Kara çöle sığındım ben

Düşündüm ki...

Gemi idim yüzer oldum

Limanlara sığındım ben

Düşündüm ki...

Olgunlaştım ekin oldum

Harmanlara sığındım ben

Düşündüm ki...

Anız idim saman oldum

Mereklere sığındım ben

Düşündüm ki...

Maraz idim dert oldum 

Hekimlere sığındım ben

Düşündüm ki...

Neticede mefta oldum

Tabutlara sığındım ben

Düşündüm ki...

Dört omuzda yolcu oldum

Topraklara sığındım ben', 'Düşündüm ki... Ben ne idim ben ne oldum Ben sırrına sığındım ben Düşündüm ki... Hava oldum  suyun oldum Deryalara sığındım ben Düşündüm ki.....', ARRAY['Türk Edebiyatı','Şiir','Kelkitli Summani']::text[], 8.5, '{"poet":"Kelkitli Summani","poet_slug":"kelkitli-summani","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/sigindim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazerfen', 'hazerfen-kelkitli-summani-38acs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yücelmişsen eğer gönlümüzde, 

Gönlümüzün yücesini Galata sanma, 

Sanıpta uçma gönlümüzden, 

                               HAZARFEN..

Üsküdar bil gönlümüzdeki yerini

Uç, uçta gel gönlümüze kon

Konağımızda konuk ol, 

                               HAZARFEN..', 'Yücelmişsen eğer gönlümüzde,  Gönlümüzün yücesini Galata sanma,  Sanıpta uçma gönlümüzden,                                 HAZARFEN.. Üsküda...', ARRAY['Türk Edebiyatı','Şiir','Kelkitli Summani']::text[], 8.5, '{"poet":"Kelkitli Summani","poet_slug":"kelkitli-summani","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hazerfen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halı', 'hali-kelkitli-summani-3nk15', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir damla suda saklıydın

Kuzu oldun, koyun oldun

Deri ve posta büründün

Koç-koyun diye göründün.

Kırkıldın, yıkandın suda

Tarandın, boyandın sonra

Kirman ile fabrikada

Eğrildinde iplik oldun

Tezgahlarda ter dökerek

İlmiklleri ful sayarak

Neticede tarak tarak

Dokunupta halı oldun

Dürdü, tutdu rafa koydu

Adı saray, atlas, aksu

Alan satan eli tuttu

Mekanlara eşya oldun.', 'Bir damla suda saklıydın Kuzu oldun, koyun oldun Deri ve posta büründün Koç-koyun diye göründün. Kırkıldın, yıkandın suda Tarandın, boyandın...', ARRAY['Türk Edebiyatı','Şiir','Kelkitli Summani']::text[], 8.5, '{"poet":"Kelkitli Summani","poet_slug":"kelkitli-summani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başka Kentin Çocukları', 'baska-kentin-cocuklari-melih-coskun-0zmho', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir başka kentin çocuklarıydı onlar

Başka zamanlarda yaşadılar

Başka zamanlarda dövüştüler

Olmadık zamanlarda türküler söylediler

Şiirler söylediler sabaha karşı

Dağ başlarında ateş yaktılar, 

Gelecek sabahı beklediler

Korkmadılar, 

Etrafı saran dişi kanlı

Kurt sürülerinden, 

Tepelerinde uçuşan leş kuşlarından, 

Bir şafak vakti

Aşık oldular güneşe, 

Ve bir akşam güneş batınca 

Öldüler...

31 Ekim 2002

23: 03', 'Bir başka kentin çocuklarıydı onlar Başka zamanlarda yaşadılar Başka zamanlarda dövüştüler Olmadık zamanlarda türküler söylediler Şiirler sö...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/baska-kentin-cocuklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyüdük', 'buyuduk-melih-coskun-bbq6g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Büyüdük bugün

O eski resimlerde gülen çocuk yok artık

O sokak artık eskisi gibi

Uzun görünmüyor, 

Sihrini kaybetti artık 

Büyümek hürriyeti.

Çocukluğumun şehri değil bu şehir

Bu sokaklar, bu bahçeler

Çocukluğumun dünyası değil artık bu dünya

Dünyada büyüdü benimle birlikte

Büyüdükçe kaybetti güzelliklerini

Bu daracık şehir İstanbul değildir artık

Yürüdüğüm sokaklarda çocukluğum yok

Büyüdük bugün

Çoğaldı gözyaşı döktüğümüz mezar taşları

Büyüdük ve gurbeti gördük bugün

Büyüdük bugün

Büyüdük ve

Türkü söylemeyi öğrendik.

Bu şehir İstanbul değildir 

Ve o resimlerde gülen çocuk ben değilim artık...

23 Eylül 2002

21: 59', 'Büyüdük bugün O eski resimlerde gülen çocuk yok artık O sokak artık eskisi gibi Uzun görünmüyor,  Sihrini kaybetti artık  Büyümek hürriyeti....', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/buyuduk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merak', 'merak-cem-bektas-c1xlw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çiçekler neye ağlar buralarda? 

Ya sen bücür kurbağa, sen neye ağlarsın genelde? 

Her hüznü duymak istiyorum bu köyde yaşanan...

Her acının elinden azıcık tutmak istiyorum.

Bizim oralarda çiçekler arılara ağlar, 

Ne ihtiraslıdır onlar... Ah bilemezsin.

Öyle yanıltıcıdır ki bakışları leylakların, 

Sözüne kansan, acı çeken nesillerine ve

Bitmek bilmeyen gecelere ağladıklarını sanırsın.

Ama onlar yalancıdırlar... inanma.

Bizim oralardaki çiçeklerin hepsi, 

Gizlice arılara ağlar.

Kurbağalar ise senden az daha yeşil, 

Ve epey uzundurlar.

Bilmiyorum sen de sever misin ama, 

Onlar en çok baharı severler... suyu bir de.

Yani bir de öyle haylazdırlar ki sorma gitsin...

Bir an duramazlar tüm bahar ve yaz boyunca, 

Sonrasında kurutur sonbahar! 

Suların üzerinde yuva kurdukları, 

O geniş ve kalın damarlı yaprakları.

Evet... Sonbahar kurutur onları.

Bizim oralarda yuvası kurumuş kurbağaların, 

Bilemezsin nasıl ağladıklarını.

Onlar yeniden baharın gelmesi için, 

Asker gibi gün sayarlar.

Mevsim dönümüne kaç gün kaldığını

Hesaplarken görürsün onları...

“Sekiz gün geçtiyse ne kalır elde? ”

işte böyle...

Ya sen bücür kurbağa, sen neye ağlarsın genelde?', 'Çiçekler neye ağlar buralarda?  Ya sen bücür kurbağa, sen neye ağlarsın genelde?  Her hüznü duymak istiyorum bu köyde yaşanan... Her acının ...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/merak-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakın Bu Fezayı', 'birakin-bu-fezayi-ahmet-murad-lujrg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gece vakti ama bu biraz farklı.

Aydınlık gelmeyecek gibi.

Kara bulutlar içinde gece, sis perdesi var.

Görünmüyor bardağın dibi.

Çığlık çığlığa kargalar mısır koçanları boş.

Bir eksiklik sevgi hissi.

Diller kılıç kadar keskin, kulaklar sese yırtık.

Bu dedemden kalan son giysi.

Bombardıman sağnağı alaturka beynime çarpan.

Kusmugu medeniyet aşının.

Sersemleten balyozu iniyor kafalara vampir çetenin.

Bırakın bu fezayı başka ğöğe taşının.', 'Bir gece vakti ama bu biraz farklı. Aydınlık gelmeyecek gibi. Kara bulutlar içinde gece, sis perdesi var. Görünmüyor bardağın dibi. Çığlık ç...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Murad']::text[], 8.5, '{"poet":"Ahmet Murad","poet_slug":"ahmet-murad","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/birakin-bu-fezayi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bire Varalım', 'bire-varalim-kelkitli-summani-jmsnz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ha kızıl olmuş ha kara

Olmamalı kalbi kara

Kötülüğün sonu yoktur.

Rabbine var var kardeşim, 

Birlik olup bire varalım. 

Bekir, Ömer, Osman, Ali

Bak Alevi Sünni hani? 

Birlik bu canın emeli...

Rabbine var var kardeşim, 

Birlik olup bire varalım. 

Dördü bir, bire varalım

Aynı yola bir varalım

Menzil tek bile varalım.

Rabbine var var kardeşim, 

Birlik olup bire varalım. 

Kıblemiz birdi ezeli

Mazi Türklükle bezeli

Sünni hem Alevi Ali...

Rabbine var var kardeşim, 

Birlik olup bire varalım.', 'Ha kızıl olmuş ha kara Olmamalı kalbi kara Kötülüğün sonu yoktur. Rabbine var var kardeşim,  Birlik olup bire varalım.  Bekir, Ömer, Osman, ...', ARRAY['Türk Edebiyatı','Şiir','Kelkitli Summani']::text[], 8.5, '{"poet":"Kelkitli Summani","poet_slug":"kelkitli-summani","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bire-varalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk-Japon İşbirliği', 'turk-japon-i-sbirligi-cem-bektas-xggq7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İstanbul’ un nesi güzeldir? 

Diye sordu bir Japon.

Dedim ki ben de yabancıyım, 

Gel beraber bulalım.

O dedi ki ben duydum, 

Meşhurmuş Eminönü.

Oraya dedim gidersek, 

Bir hüzünlü anım var tazelenir.

Mısır Çarşısı dedi, meşhurmuş.

Yok dedim orada, 

Cebinde ne varsa erir.

Galata dedi, Ortaköy, Üsküdar? 

Bak dedim Japon kardeş, 

Ben senden önce ne İstanbul’ u, 

Ne Japonları bilirdim.

Bana Japon ne deseler, 

Bir tür balık derdim.

Şimdi öğrendim ya insansınız, 

Ama bak zaten

Senin gözlerin çekik

İyice mi çekeceksin çekici yerlere gidip? 

Gel dostum seninle, 

Bu şehrin her sabah

Bin bir dertle uyanan ve 

tek öğün aşla kırk öğün çalışarak

sizin samurayları bile kıskandıran

o kahraman yerlilerinin yaşadığı

bir iç şehire götüreyim.

Dedi ki ne buluruz orada

Dedim ne diliyorsak Allah’ tan bela olarak

Hepsi vardır orada.. Onlar seni bulur.

Dedi ki, 

Ora belalı ise niye orada yaşarlar? 

Dedim ki, 

İşte onlar onun için kahramanlar.

Dedi ki, 

Hani yabancıydın? 

Dedim ki, 

En az senin kadar.', 'İstanbul’ un nesi güzeldir?  Diye sordu bir Japon. Dedim ki ben de yabancıyım,  Gel beraber bulalım. O dedi ki ben duydum,  Meşhurmuş Eminön...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/turk-japon-isbirligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yürek Resmi Çiz Ellerinle', 'bir-yurek-resmi-ciz-ellerinle-melih-coskun-syea1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir yürek resmi çiz ellerinle

Kirletilmemiş bembeyaz kağıtlara

Tertemiz bir yürek resmi çiz

Unutma ki bu beden emanettir sana bu dünyada

Topraktan alınmış bir emanet

Bir gün istemesen de alacaktır geri... 

Bu yürek, 

Bu eller, 

Bu gözler senin değil aslında

Güzel yaşamalısın

İyi yaşamalısın ki

Hıyanet etmiş sayılmayasın emanete

Gitmelisin ayaklarının gidebileceği her yere

Bakmalısın gözünün görebildiği en uzak ufuklara

Düşünmelisin düşünebileceğinin en güzelini

Sevmelisin yüreğinin sevebileceğinden daha da çok

Ve bilmelisin ki

Emanet olmayan 

Sana ve bir tek sana ait olan 

Düşüncendir bu dünyada 

Bu beyin senindir sonsuza dek 

Ve sonsuzluktan sonrada

Beyninde filizlenen aydınlıklar

Toprağın emaneti değildir sana

Güneşin sıra dışı bir armağanıdır

Ve hürriyetin armağanıdır sana beyninin

Ne kadar özgürsün diye sorduğunda 

Kendi beynine ve düşüncene

Elbette ki düşünebildiğin kadar diyecektir sana

Ve ne kadar yaşayacağım diye sorarsan 

Bu yarını karamsarlıklarla dolu dünyada

Yüreğinin taşıdığı yere kadar diyecektir sana...

Sen bu yolun sürekli giden bir yolcususun

Farz etki bir otobüs bu hayat

Hepimiz aynı otobüsün yolcularıyız

Kimimiz biletli kimimiz kaçak bu yolculukta

Kimimiz kurulmuş en rahat koltuklarına otobüsün

Kimimizin ayakta duracak yeri bile yok

Gülüyor birimiz 

Ağlıyor onumuz

Derin bir ah çekiyor ayaktaki yolcuları 

Oturan anlamıyor ayaktakinin halinden

Bir gerçek vardır bu otobüste 

Herkesin bildiği 

Ancak bilmemezlikten geldikleri değişmez gerçek

Bir gün biteceğidir bu yolculuğun

Ağlayanıyla, güleniyle

Ayakta gidenleriyle, oturanlarıyla

Aynı yolun yolcusuyuz hepimiz

Ve asıl önemli olan bu hayatta

Yürüyerek tüketmek değil

Herkesin yürüdüğü bu aşınmış yolları.

Asıl önemli olan

Bir yürek resmi kazıyabilmektir tırnaklarınla

Yürüdün yollara

Senden sonra yürüyenlerinde görebileceği

Tertemiz bir yürek resmi çiz ellerinle

Emanet etme bu yüreği sakın

Sende sonra yürüyecek olana

Tırnaklarınla kazınmış bu yürek 

Armağanın olsun

Bu yolun yolcusuna...

17 Kasım 2002

22: 39', 'Bir yürek resmi çiz ellerinle Kirletilmemiş bembeyaz kağıtlara Tertemiz bir yürek resmi çiz Unutma ki bu beden emanettir sana bu dünyada Top...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/bir-yurek-resmi-ciz-ellerinle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlar', 'i-nsanlar-kelkitli-summani-0chva', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bilemem maksatları nedir ama, 

Bir yerlere gider bunca insanlar.

Bilemem onu dönerlermi ama, 

Dönüşü de var derler gidin insanlar.

Murat eden derviş Hak''ka varırmış, 

Yola çıkan yolcu menzil alırmış, 

İyilik eden ahir hayra varırmış, 

İsyan eder kötülüğe insanlar.

Erken kalkan yolcu daim yol almaz.

Hayırsa maksadı bu da güç olmaz.

Erken evlenen her gelin yar olmaz.

Yaradan isterse olur insanlar.

Uzun ömür, sağlık dedi koştular.

Tuzaktan kaçarken faka bastılar.

Uzamadı ömür yolda kaldılar.

Sırtta gidip kabre girdi insanlar.', 'Bilemem maksatları nedir ama,  Bir yerlere gider bunca insanlar. Bilemem onu dönerlermi ama,  Dönüşü de var derler gidin insanlar. Murat ede...', ARRAY['Türk Edebiyatı','Şiir','Kelkitli Summani']::text[], 8.5, '{"poet":"Kelkitli Summani","poet_slug":"kelkitli-summani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/insanlar-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '2+2=4 Etmez Her Yürekte', '2-2-4-etmez-her-yurekte-derin-oger-l8f08', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hadi akşamlarımı da al

Hadi günü de ekle geceye

Yirmi dört saatim olsan ne olur

Dudaklarımda dur kirpiğimden dökül

Gözlerimde büyü gönlümde çöl ol

Karşımda savaş çığlıkları atsan ne olur

Deryalar kadar durgun bu sevgiye

Sen sadece gözbebeğimdeki gerçeksin

Zannetme ki şiirler yazan olur gölgene

Zannetme ki yakarsın dünyayı ateşinle

2+2=4 etmez her yürekte

Gelişin gidişini anlarsın

Anlarsın anarsın bir gün çaresizlikle.......', 'Hadi akşamlarımı da al Hadi günü de ekle geceye Yirmi dört saatim olsan ne olur Dudaklarımda dur kirpiğimden dökül Gözlerimde büyü gönlümde ...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/2-2-4-etmez-her-yurekte-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nafile', 'nafile-kelkitli-summani-5twb5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Padişahımdan buyruk aldım dostlar, 

İzin almak suya düştü nafile...

Arşa yükselen kederimi dostlar

Şehit Osman da duymadı nafile...

Varacağım diye bekler dururlar

Şimdi yollara bakıp somurturlar

Babaları, Bayburt''ta cadde turlar

Onlar figanımı duymaz nafile...

Yavrularım anlamaz padişahım

Çıksada semaya avazım ahım

Sokaklarda  dolaştım can yoldaşım

Sokaklarda anlamadı nafile...

Yaptığımız iş başımızdan aşkın(!)

Yüzümüze bakar askerler şaşkın

Telefonun var ey topçu er Aşkın

Konuştu bitmedi derdi.. nafile...

Ahı gitmiş vahı kalmış haraptır

Sevgi saygı onun için azaptır

İnsanlıktan nasip almamış zattır

Nasiplenmez bundan sonra nafile...

Devran padişahın bayram sizindir

Zalimden arzumuz bir gün izindir

Kelkit kazam Gümüşhane ilimdir.

Bildiğim yerlerde şaştım nafile...

Bayramınız mübarek olsun dostlar

Şeytan gelir-gider kalbimi yoklar

Der ki: Firar et arasın bulsunlar

Bilinki şeytana uymam nafile...

Hasret dinsin diye divana durdum

Gelmiş-geçmişime Kur''an okudum

Gönül dünyamdan vesveseyi kovdum

Gönlümde ki hasret dinmez nafile...

Umut yok benden kurbanımı kesin

Şad olurum eş, dost, çocuklar yesin

Babamın ruhuna dua edilsin

Beklemeyin beni gelmem nafile...

Sümmani insan olana ne derler

Başımızın üstünde yer ederler

Olmayana neyin çocuğu derler? 

Bir bayramda böyle geçti nafile...', 'Padişahımdan buyruk aldım dostlar,  İzin almak suya düştü nafile... Arşa yükselen kederimi dostlar Şehit Osman da duymadı nafile... Varacağı...', ARRAY['Türk Edebiyatı','Şiir','Kelkitli Summani']::text[], 8.5, '{"poet":"Kelkitli Summani","poet_slug":"kelkitli-summani","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/nafile-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırılırım Sana', 'kirilirim-sana-kelkitli-summani-oderj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerinin nurunda buldum aşkı

Bakışın hayat verdi, hayat verdi bana

Paylaşalım bu hayatı ve aşkı

Dönülmez yoldayım tutkunum sana

Saçım yele, ömrümü sana verdim

Bil aşkının ateşinde ısındım

Yuvam diye de kalbine sığındım

Çıkmam inan, çıkmam vurgunum sana 

Ben ölürüm sevgim kalırsa soluk

Ya sıcak severim ben yada soğuk

Samimiyet güzel, döneklik bozuk

Dönersen bu yoldan küserim sana

Sümmani güzel sevdanı serde tut

Kesilmez Allah''tan kesilmez umut

Aşkım yücedir; sevgilim başta tut

Bırakma yere kırılırım sana', 'Gözlerinin nurunda buldum aşkı Bakışın hayat verdi, hayat verdi bana Paylaşalım bu hayatı ve aşkı Dönülmez yoldayım tutkunum sana Saçım yele...', ARRAY['Türk Edebiyatı','Şiir','Kelkitli Summani']::text[], 8.5, '{"poet":"Kelkitli Summani","poet_slug":"kelkitli-summani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kirilirim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emmi', 'emmi-kelkitli-summani-py2ut', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aklım erdiğinde sayardım

Dayı, teyze, bibi, emmi...

Arasında yoktun bunların emmi

Aramıza girdi kara kedi

Tanımadım, tanıyamadım seni

İçim yanar elliğine ağlarım...

Bir fırsattı gurbette buluştuk

Sen yeğen, ben emmi dedim

Kan karışık kavuştuk...

Sayısını çocukların senden öğrendim

Buluşamazdık olmasaydı gurbet öyküsü

İçim yanar öykümüze ağlarım...

Maziyi unutsam, atiyi özlesem de

Sen geçmişine ve geleceğine

Nokta koydun bir celsede

Götürdün beraberinde

Senin ile düşlediğim anıları

İçim yanar anılarıma ağlarım...

Eğmedin boyun sağlığında 

Hiçkimseye, hiçbir ferde

Bildiğim bir kez boyun eğdin emmi

O da seni yaratan Allah''a

Yiğit doğdun, yiğit yaşadın, yiğit öldün

İçim yanar yiğitliğine ağlarım...

Çok sevinçliyim sen olmasanda

Bu gün hep hanende toplandık

Yokluğun buluşturdu bizi mekanında

Gözyaşları arasında biz, bizi tanıdık

Kabrin nur,  mekanın cennet olsun

İçim yanar yokluğuna ağlarım... EMMİ!', 'Aklım erdiğinde sayardım Dayı, teyze, bibi, emmi... Arasında yoktun bunların emmi Aramıza girdi kara kedi Tanımadım, tanıyamadım seni İçim y...', ARRAY['Türk Edebiyatı','Şiir','Kelkitli Summani']::text[], 8.5, '{"poet":"Kelkitli Summani","poet_slug":"kelkitli-summani","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/emmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı Bahar', 'yalanci-bahar-muammer-tukenmez-bc32d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu sabah yol kenarındaki ağaçlarda, 

Yalancı bahara inanıp açan çiçekleri gördüm.

Öylesi umut dolu öylesi mutluydular ki, 

Bir anda onlarda kendimi gördüm.

Gördümde üzüldüm.

Bak şimdi kar yağıyor, inandığımız o bahara', 'Bu sabah yol kenarındaki ağaçlarda,  Yalancı bahara inanıp açan çiçekleri gördüm. Öylesi umut dolu öylesi mutluydular ki,  Bir anda onlarda ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Tükenmez']::text[], 8.5, '{"poet":"Muammer Tükenmez","poet_slug":"muammer-tukenmez","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yalanci-bahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Akşam', 'dun-aksam-muammer-tukenmez-67tlx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dün akşam sen uyurken

Bir yıldız kaydı gökyüzünde

Deniz kenarında bir adam senin için

Şiirler okudu yıldızlara ve aya

Bir ara ay kayboldu bulutlar arasında, 

O an iki damla gözyaşı döküldü gözlerinden

Terk edişin geldi gözlerinin önüne aniden.', 'Dün akşam sen uyurken Bir yıldız kaydı gökyüzünde Deniz kenarında bir adam senin için Şiirler okudu yıldızlara ve aya Bir ara ay kayboldu bu...', ARRAY['Türk Edebiyatı','Şiir','Muammer Tükenmez']::text[], 8.5, '{"poet":"Muammer Tükenmez","poet_slug":"muammer-tukenmez","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dun-aksam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabah', 'sabah-muammer-tukenmez-ajil6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gün sabah niye olmuyor.

Her yer sessiz ve karanlık

Yeter, gün doğsa artık.

Nasıl bitmez bir gece ki bu

Bitsin bu sensizlik, bitsin bu karanlık

Ne olur gel artık.', 'Bu gün sabah niye olmuyor. Her yer sessiz ve karanlık Yeter, gün doğsa artık. Nasıl bitmez bir gece ki bu Bitsin bu sensizlik, bitsin bu kar...', ARRAY['Türk Edebiyatı','Şiir','Muammer Tükenmez']::text[], 8.5, '{"poet":"Muammer Tükenmez","poet_slug":"muammer-tukenmez","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sabah-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmkansız', 'i-mkansiz-muammer-tukenmez-d2jwv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yarın güneş batıdan doğa bilir yada

Bir akşam ay dünyayı terk edip gidebilir uzaklara

Bir sonbahar günü tüm kuşlar inanıp göçmen kuşlara

Gidebilir o uzak diyarlara

Hatta bir sabah kalkdığında bir bakarsın  tüm dostların

Terk edip gitmışlar seni

Bir ben asla terk etmem seni

Birgün beni unuttup gidecegini bildiğim halde

Bir ben asla unutmam seni.', 'Yarın güneş batıdan doğa bilir yada Bir akşam ay dünyayı terk edip gidebilir uzaklara Bir sonbahar günü tüm kuşlar inanıp göçmen kuşlara Gid...', ARRAY['Türk Edebiyatı','Şiir','Muammer Tükenmez']::text[], 8.5, '{"poet":"Muammer Tükenmez","poet_slug":"muammer-tukenmez","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/imkansiz-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna', 'ayna-muammer-tukenmez-z3h38', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen hiç aynaya bakma

Göremezsin kendini

Çünkü senin için '' Yüzsüz '' diyorlar', 'Sen hiç aynaya bakma Göremezsin kendini Çünkü senin için '' Yüzsüz '' diyorlar...', ARRAY['Türk Edebiyatı','Şiir','Muammer Tükenmez']::text[], 8.5, '{"poet":"Muammer Tükenmez","poet_slug":"muammer-tukenmez","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/ayna-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duvar', 'duvar-muammer-tukenmez-nqfd5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzun zamandır  sana anlatamadıklarımı

Dün akşam evde tek başıma

İki kadeh rakı içerken

Odamın duvara anlattım öylece

Uzun uzun senden bahsettim ona

Sabırla sessizçe  dinledi

Bir ara ayağa kalkıp sana gelmek istedim.

O an düşerken yaslanıp tutdu beni 

''Hadi yat artık''derken o kadar ağlamışım ki yanında

Nemden bem beyaz kabarcıklar oluvermiş duvarında

''İnsanı gam, duvarı nem ölürür'' yazı verdi bağrında', 'Uzun zamandır  sana anlatamadıklarımı Dün akşam evde tek başıma İki kadeh rakı içerken Odamın duvara anlattım öylece Uzun uzun senden bahset...', ARRAY['Türk Edebiyatı','Şiir','Muammer Tükenmez']::text[], 8.5, '{"poet":"Muammer Tükenmez","poet_slug":"muammer-tukenmez","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/duvar-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durusu', 'durusu-muammer-tukenmez-ox3qp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Duru sakin bir su gibisin kimi zaman

Gözyaşlarım damla damla damlarken üzerine

Halka halka yayılıp kaybolup gitmektesin.', 'Duru sakin bir su gibisin kimi zaman Gözyaşlarım damla damla damlarken üzerine Halka halka yayılıp kaybolup gitmektesin....', ARRAY['Türk Edebiyatı','Şiir','Muammer Tükenmez']::text[], 8.5, '{"poet":"Muammer Tükenmez","poet_slug":"muammer-tukenmez","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/durusu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Külliyen Yalan', 'kulliyen-yalan-muammer-tukenmez-0nqip', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dağ dağa kavuşmaz ama

İnsan insana kavuşurmuş

Ben sana niye kavuşamadım  o zaman', 'Dağ dağa kavuşmaz ama İnsan insana kavuşurmuş Ben sana niye kavuşamadım  o zaman...', ARRAY['Türk Edebiyatı','Şiir','Muammer Tükenmez']::text[], 8.5, '{"poet":"Muammer Tükenmez","poet_slug":"muammer-tukenmez","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/kulliyen-yalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakarsan Bağ Bakmazsan?', 'bakarsan-bag-bakmazsan-muammer-tukenmez-u2ikt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bakarsan bağ bakmazsan

''Mahvolurum''.', 'Bakarsan bağ bakmazsan ''Mahvolurum''....', ARRAY['Türk Edebiyatı','Şiir','Muammer Tükenmez']::text[], 8.5, '{"poet":"Muammer Tükenmez","poet_slug":"muammer-tukenmez","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/bakarsan-bag-bakmazsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamazsın', 'anlamazsin-muammer-tukenmez-5aywx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yanlız kaldığım zaman

Bulutlar geçer gözlerimin üzerinden

Kara kara bulutlar

Ve ardından damla damla yağmur başlar.

O ara birşey sorma sakın

Nasılsa, anlatsam anlamazsın.', 'Yanlız kaldığım zaman Bulutlar geçer gözlerimin üzerinden Kara kara bulutlar Ve ardından damla damla yağmur başlar. O ara birşey sorma sakın...', ARRAY['Türk Edebiyatı','Şiir','Muammer Tükenmez']::text[], 8.5, '{"poet":"Muammer Tükenmez","poet_slug":"muammer-tukenmez","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/anlamazsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulut', 'bulut-muammer-tukenmez-ly6f3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biliyormusun bulutları bile kıskanırdım.

Sen onları seviyorsun diye

Oysa şimdi sen yoksun ya

Kıskanacak ne bulut kaldı nede umut yüreğimde', 'Biliyormusun bulutları bile kıskanırdım. Sen onları seviyorsun diye Oysa şimdi sen yoksun ya Kıskanacak ne bulut kaldı nede umut yüreğimde...', ARRAY['Türk Edebiyatı','Şiir','Muammer Tükenmez']::text[], 8.5, '{"poet":"Muammer Tükenmez","poet_slug":"muammer-tukenmez","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bulut-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz İnsanlar', 'biz-i-nsanlar-orhan-seyfi-orhon-vm7xf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', ''' İnsanız, en şerefli mahlûkuz! ...''

Deyip de pek fazla

Övünmemiz haksız: 

Atamız elma çaldı cennetten.

Biz, o hırsızların çocuklarıyız!', ''' İnsanız, en şerefli mahlûkuz! ...'' Deyip de pek fazla Övünmemiz haksız:  Atamız elma çaldı cennetten. Biz, o hırsızların çocuklarıyız!...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Orhon']::text[], 8.5, '{"poet":"Orhan Seyfi Orhon","poet_slug":"orhan-seyfi-orhon","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/biz-insanlar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Şey', 'i-ki-sey-orhan-seyfi-orhon-z40hj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İki şey var ki, genel kâidedir, 

İki şey var ki, değişmez asla! 

Bir: 

Kirpiden post olmaz! 

Bir de; 

'' İnsan'' denilen mahlûktan, 

Dost olmaz!', 'İki şey var ki, genel kâidedir,  İki şey var ki, değişmez asla!  Bir:  Kirpiden post olmaz!  Bir de;  '' İnsan'' denilen mahlûktan,  Dost olma...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Orhon']::text[], 8.5, '{"poet":"Orhan Seyfi Orhon","poet_slug":"orhan-seyfi-orhon","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/iki-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevmek', 'seni-sevmek-i-lyas-salman-wlryc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey insan! 

Ey güzel insan! 

Seni sevmek, balığı Urfa''da avlamaktır. 

Balıklı gölde, yasak olduğu için güzeldir. 

Ey insan, ey güzel insan! 

Seni sevmek, Munzur dağlarında kınalı keklik avıdır 

Hani keklikler yorulur da kara düşünce kalkamaz 

İşte o zaman vurmak kolaydır... 

Ey insan, ey güzel insan! 

Seni sevmek, yedisinde bir çocuğun, günlük gelirine konmaktır 

Alaca şafakta çıkmıştır işe, 

Simidinin yarısını satmıştır, 

Yüreği küçülmüştür elleri büyüdükçe... 

Ey insan ey güzel insan! 

Seni sevmek, bir trencinin tren altında kalması gibidir, 

Hani çığlığı düdük sesine, 

Hasreti raylara takılı kalır... 

Ey insan ey güzel insan! 

Seni sevmek, kaşarlanmış bir celladın, kendini asması gibidir. 

Hani asılı cesedine bakıp hem güler hem ağlarlar ya 

Oysa bir avuç gözyaşıdır astıkları bedeninden arta kalan... 

Ey insan ey güzel insan! 

Seni sevmek, zordur, çelişkidir, ölümle yaşamın kardeşçe birliğidir, 

Ölünün mezarını görüp ölümden vazgeçmesi gibidir... 

Buna rağmen seni seviyorum, 

Ama anlarsan seviyorum, 

Anlamazsan geberiyorum...', 'Ey insan!  Ey güzel insan!  Seni sevmek, balığı Urfa''da avlamaktır.  Balıklı gölde, yasak olduğu için güzeldir.  Ey insan, ey güzel insan!  ...', ARRAY['Türk Edebiyatı','Şiir','İlyas Salman']::text[], 8.5, '{"poet":"İlyas Salman","poet_slug":"i-lyas-salman","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/seni-sevmek-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşporta Aşklara', 'i-sporta-asklara-ufuk-nazim-3czbu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geçenlerde Kadıköyde buldum, 

İşporta bir aşk.

Deniz yakın gök mavi, 

Ve dalgalar gibi narindi.

Oysa birazdan oda satılacaktı.

İşportada güzel bir aşk, 

Sokak sokak aranacaktı.

Bulunup kaybolacak buluttular.

Yakın bir zamanda, 

Bulunacak bir mısradır onlar.

Gelip geçen boğazın mavisini, 

Pasa bulayan hurdaydı onlar, 

Geriye dönmemeyi öğretendi onlar.', 'Geçenlerde Kadıköyde buldum,  İşporta bir aşk. Deniz yakın gök mavi,  Ve dalgalar gibi narindi. Oysa birazdan oda satılacaktı. İşportada güz...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/isporta-asklara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Yazıyorum', 'siir-yaziyorum-ali-safak-bali-eanx0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şiir yazmaya karar verdim

ve paylaşmaya duygularımı 

şiir dostlarıyla, 

şiirsi dostluklarıma rağmen...', 'Şiir yazmaya karar verdim ve paylaşmaya duygularımı  şiir dostlarıyla,  şiirsi dostluklarıma rağmen......', ARRAY['Türk Edebiyatı','Şiir','Ali Şafak Balı']::text[], 8.5, '{"poet":"Ali Şafak Balı","poet_slug":"ali-safak-bali","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/siir-yaziyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aileme...', 'aileme-ozgul-ozyilmaz-zfkp1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Özlemişim anamı 

Yıllar önce çocukken kaybettiğim babamı..

Öyle bir anımdayım ki şimdi 

Yapayalnızım, yok kimsem yanımda..

Biri toprakta, biri uzak diyarlarda…

Bir onların sıcaklığına muhtacım

Onların beni sarıp sarmalamasına var ihtiyacım.

Özlemişim dizlerine yatmayı

Kucaklarında uyuklamayı..

Üşümüşüm yalnızlıktan

Yetmiyor dost, arkadaş varlığı

Özlemişim ben özümü

Özlemişim bir anamı bir de topraktaki babamı..

Şimdi! Şu an istiyorum onlara yakın olmayı, 

Kollarımı boyunlarına dolamayı..

Yalnızlık, özünden ayrılık fena kor yüreğime

Hele bir de çaresizlik var ya….

Ah anam, ah babam

Sizde özler misiniz ana-babanızı? 

Sizde hisseder misiniz o yalnızlığı? 

Sizde ister misiniz o sıcak güvenli kolları? 

İster de siz de mi bulmazsınız onları? 

Özlemişim o çocukluğu, o sorumsuzluğu

Bilirim yaş 34 ama ya o içimdeki büyümeyen çocuk? 

Ya ona nasıl anlatayım ben şimdi

Bamam öldü, anam uzaklarda

Sevdalınsa bir başka dünyalarda diye..

Bilir, herşeyi bilir de

O içindek çocuktur ona bunları yaşatan yürekte

Ve yine çok iyi bilir ki; 

İstesede istemesede hayat onu acıyla büyütmekte..', 'Özlemişim anamı  Yıllar önce çocukken kaybettiğim babamı.. Öyle bir anımdayım ki şimdi  Yapayalnızım, yok kimsem yanımda.. Biri toprakta, bi...', ARRAY['Türk Edebiyatı','Şiir','Özgül Özyılmaz']::text[], 8.5, '{"poet":"Özgül Özyılmaz","poet_slug":"ozgul-ozyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/aileme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-ozgul-ozyilmaz-jmkb0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Belki çok fazla görüşemedik, konuşamadık

Belki pek çok şeyi doyasıya paylaşamadık

Yollarımız kesişti, bir dönem birlikte yaşadık..

An oldu bir tebessümü

Zaman oldu mekanı paylaştık.

Gün geldi, dertleri, hüznü tattık..

Ve sonra, 

Yollarımız ayrıldı vedalaştık..

Her birimiz başka bir yöne dağıldık

Başkalarıyla kaynaştık.

Hayat.. Yaşam.. dedik savaştık..

Her birimiz kendimizce yaşadık..

Bitmeyecek sandığımız ömürde

Daha çok var derken

Anlayamadan vaktin dolduğunu

Toprakla kucaklaştık..

(10.12.2001)', 'Belki çok fazla görüşemedik, konuşamadık Belki pek çok şeyi doyasıya paylaşamadık Yollarımız kesişti, bir dönem birlikte yaşadık.. An oldu b...', ARRAY['Türk Edebiyatı','Şiir','Özgül Özyılmaz']::text[], 8.5, '{"poet":"Özgül Özyılmaz","poet_slug":"ozgul-ozyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hayat-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-ozgul-ozyilmaz-nz1wx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'O iki kelime

Yüreğimde çığ gibi büyüyen

Susturamadığım

Ama söylemeye korktuğum

Ve dayanamayıp da itiraf ettiğim..

Biliyorum söylemek; 

Belki çok erken, belki de yanlış

Ama elimde değil ki..

O içimde coşkuyla çoğalıp

Dudaklarımdan taşan iki kelime..

“Seni Seviyorum”.

Korkutuyor beni söylemesi, hissetmesi.

İçinde “sen” olması düşüncesi

Yüreğimi havalandırıyor.

İçimde öylesine kökleniyor, öylesine büyüyorki

Korkuyorum..

Korkuyorum çünkü karşılığını hiç duyamamaktan

Onca istememe rağmen belki de bundan

Seninleyken hiç kulağına fısıldayamamam..

Bir gün o kahrolası geç kalmışlığın “keşke”lerinde kıvranmamak için

İnatla yazıyorum işte, 

Sen beni sevmesen de ben seni seviyorum…

İçimde bir telaş

Sanki vakit dar

Sanki bir daha zamanım olmayacak

Sana; seni ne kadar çok sevdiğimi söylemeye..

İşte bu yüzden bunca ısrar, bunca itiraf

Dar vakitlere geniş zamanları sığdırmak için bütün bu uğraş.

Ben seni sevmelerin telaşında

Sen ketumluğun inadında..

Bekleyeceğim birtanem, bekleyeceğim

Gün gelipte sevdamla görebilmeyi seni yangınlarda

Hakkıyla duyabilmeyi o iki kelimeyi dudaklarında..

Evet canımıniçi, 

Söylemeye korktuğun

Duymak için ise öldüğüm o iki kelime..

Yüreğinden kopup gelmedikçe

Her hecesinde hissetmedikçe

Sakın söyleme! 

Söylemeki o büyülü iki kelime anlamsızlaşmasın

Bir balon gibi sönük kalmasın! ! 

Söylediğinde, gözlerinde o ışıltıyı görebilmeli, 

Dudaklarındaki dökülüşünden gerçekliğini hissedebilmeliyim ki

O iki kelime hak ettiği yerde yaşasın.', 'O iki kelime Yüreğimde çığ gibi büyüyen Susturamadığım Ama söylemeye korktuğum Ve dayanamayıp da itiraf ettiğim.. Biliyorum söylemek;  Belki...', ARRAY['Türk Edebiyatı','Şiir','Özgül Özyılmaz']::text[], 8.5, '{"poet":"Özgül Özyılmaz","poet_slug":"ozgul-ozyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/seni-seviyorum-99-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan', 'i-syan-ozgul-ozyilmaz-s7g6o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine kara bulutlar çöktü yüreğime, yine içimin bunaltısı sıktı boğazımı

Dellendim yine, düşünemez oldum sağlıklı, uyku uyuyamaz oldum geceleri, 

Yüreğimde bir fırtına! Boğazımda bir el! ! Beynimde balyozlar! ! 

Korkuyorum..! Korkuyorum aklımı yitirmekten! 

Öfkemle birilerine zarar vermekten..

Öfkeliyim! Gerginim! Her an patlamaya, tahrip olmaya ve tahrip etmeye meyilliyim.

Öyle bir noktasına geldim ki herşeyin, 

“Yeter artık! Defolun! Düşün yakamdan! Beni rahat bırakın! ” diye haykırıp

Çekip gitmek istiyorum buralardan..

Kaybolmak, kimseyi görmemek ve duymamak istiyorum..

Artık tahammül gücüm tükendi, sabrım uçtu gitti! Bitti artık! ! 

Herkesin herşeyin canı cehenneme! 

Tek istediğim; BENİ RAHAT BIRAKIN! ! ! 

Sormayın, sorgulamayın, zorlamayın, BENİ YALNIZ BIRAKIN! ! 

Bıktım kaprisinizi çekmekten! 

Bıktım istemediğim şeylere hatır, gönül işi katlanmaktan. YETER ARTIK! YETER! 

Aile iseniz aile gibi olun! Kendi başınıza da birşeyler yapın! 

Arkadaş iseniz arkadaş gibi olun! 

Dadınız olamam, her an sizi arayamam ve her an sizi görmeye de dayanamam! 

BEN BÖYLEYİM! 

Değişiklik ister yüreğim, daralırım hep aynı ortam, aynı muhabbet bunalırım! 

Yeterince problemim var, yeterince acı çeker yüreğim, 

Bir de sizler bunaltmayın! “ALLAH KAHRETSİN SİZİ” dedirtmeyin! 

Beni o noktalara getirmeyin! 

Allah rızası için çekilin, gidin ve beni BENİMLE BIRAKIN! 

Zorlamayın beni istemediğim şeyleri yapmaya

Huzura, anlayışa, olduğum gibi, sessizce kabul görmeye ihtiyacım var şu an..

En çok da YALNIZ KALMAYA..

Aslında herbirinizi ÇOK AMA ÇOK SEVİYORUM..

Ve istemiyorum sizleri kırmak, sizleri üzmek.. 

Ama görünmez zincirler vurmayın hayatıma, 

Ambargolar koymayın yolun yarısından sonra kalan zamanıma! 

Zaten üzgünüm, zaten çaresizim, bir de sizler sokmayın beni iyice çıkmaza..

Tek istediğim huzur bulacağım, sığınabileceğim güvenli, sıcak kollar..

Ama zorla almaya kalkmayın beni kollarınıza, bırakın, ben istediğimde gelirim size..

Biliyorum sizin de ihtiyacınız var sevgiye, sıcak kollara ama zorla olmaz! 

Hazır değilsem öfkemden başka hiç birşey alamazsınız, 

Hatta uzaklaşırım sizden, istemem görmek, duymak, 

Geri gider ayaklarım, nefret etmeye başlar duygularım..

İşte bu yüzden zaman zaman ANLAYIN ve uzak durun benden..

Bırakın toparlanayım, bırakın soluk alayım, ben iyi olmazken size nasıl faydalı olayım? 

Nasıl gülsün yüzüm içim öfkeyle çağlarken, çığlık çığlığa haykırırken? 

Olmuyor işte ve bir türlü ANLAMIYORSUNUZ! 

İşte bütün mesele de bu! 

Anlamıyorsunuz neyse, destek olamıyorsunuz, o da tamam! 

Ama ALLAH RIZASI İÇİN köstek de olmayın hayatıma! ! 

Yük olmayın sırtıma, kasvet olmayın yüreğime, 

ÇÜNKÜ BIKMIŞIM! ÇÜNKÜ TÜKENMİŞİM! 

ARTIK TAŞIYAMIYORUM, HİÇBİR ŞEYİ VE HİÇ KİMSEYİ! ! 

Ben ne yapacağımı bilmezken, ben geleceğime umutla bakamazken

Bir de sizler tüketmeyin beni..

Üç günlük dünyada, üç kuruşluk imkanlarımın da içine etmeyin

Onları da bencilliklerinizle bana zehir etmeyin! 

Kendi başıma, kendi halimle, olduğu kadarla da mutlu olmasını bilirim ben! 

Yeter ki siz elleşmeyin, beni bana bırakın ilişmeyin! 

Yok ki size zararım, yük değilim ki hiçbirinize, 

Saygıdan öte hiçbir şey istemiyorum sizlerden, yalnızca KARIŞMAYIN, YARGILAMAYIN! 

Ben kendi doğrularımla, siz kendi doğrularınızla dilediğinizce yaşayın

Sadece benden UZAK DURUN.. Ve lütfen SUSUN daha fazla KONUŞMAYIN..', 'Yine kara bulutlar çöktü yüreğime, yine içimin bunaltısı sıktı boğazımı Dellendim yine, düşünemez oldum sağlıklı, uyku uyuyamaz oldum gecele...', ARRAY['Türk Edebiyatı','Şiir','Özgül Özyılmaz']::text[], 8.5, '{"poet":"Özgül Özyılmaz","poet_slug":"ozgul-ozyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/isyan-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çekip Gitmek', 'cekip-gitmek-ozgul-ozyilmaz-wn4ht', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalanlar, bir başka bakar gidene

Mutludurlar giden için, 

Zincirleri kırıcak cesareti gösterebildiği için

Ama üzgündürler kendi köşelerinde

Birini daha yolculamaktan, 

Sevdikleri birini daha kaybetmekten..

Sanırlarki giden çok mutludur, kolaydır çekip gitmek

Dostları bırakmak geride, alışkanlıkları silmek

Başlamak yeniden, 

Sil baştan bir başına gayret göstermek..

Oysa ne acı, ne zordur gitmek

Heleki yüreğiyle seven, gönülden bağlı olan için..

Kolay görünür, pırıltılıdır gitmek kalanlara

Bir giden bilir, 

Bırakıp terk etmek zorunda kalan bilir yüreğindekini

Canının yanmasını, içindeki paniği, korkularını..

Ama hayat.. 

Şartlar zorlar herkesi bir şekilde

Ve gün gelir herkes bir giden olmak zorunda kalır

Kural bu, çare bu … 

Hangi günki cesareti, güveni 

Belkide ihaneti yaşar insan

İşte o gün başkaldırır, düşer yollara 

Yaşamdır öğreten, tecrübedir yol gösteren

Yaşanmışlardır acı veren…

Ve bir taş basar yüreğine, set çeker duygularına, 

Dalar düşüncelere, yüreğince, aklınca, 

Çaresizlikle bir çare aramaya

Acı da verse bazen, 

Kaçınılmazdır bırakıp gitmek bir an önce

Bırakılıp gitmektense bir gün.. 

Kolay mıdır herşeyi riske etmek? 

Gitmek bilinmeze, bir yanı gitmekten ölürken insanın..

Ama hani o yapılması gerekenler vardırya, 

Hani umut, hani belkiler vardırya 

İşte onları yükler sırtına, yüreğine, 

Gözünde yaş, içinde fırtınalar, çekip gider insan.

Her insanın bir gün yaptığı 

Yapmak zorunda kaldığı gibi…

(15.08.2000)', 'Kalanlar, bir başka bakar gidene Mutludurlar giden için,  Zincirleri kırıcak cesareti gösterebildiği için Ama üzgündürler kendi köşelerinde ...', ARRAY['Türk Edebiyatı','Şiir','Özgül Özyılmaz']::text[], 8.5, '{"poet":"Özgül Özyılmaz","poet_slug":"ozgul-ozyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/cekip-gitmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Aşkın Başlaması', 'bir-askin-baslamasi-baki-ayhan-t-pm65a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir aşkın başlaması: 

ruhla yontulması sert bir ağacın

bir anahtar sessizce açar doğayı

bir la sesi başlatır fırtınayı

çeker bıçağını hırçın rüzgar

hızla çevirir yıpranmış sayfayı: 

bir aşkın başlaması

ne süzülürse içine ince bir dalın

serinlikler onu gezdirir yüreğinde

son ışığın peşinde olan yolcular

yaşamı asarlar günün ucuna

kısık bir sesle başladıkları şarkı: 

bir aşkın başlaması

kendini ıssız zamanlarda yitirip

ışığın sonunu arayanlar

yağmuru sevinçle karşılarlar her zaman 

bütün bildiği budur hayatı anlayanların

yırtılmış sayfanın yerine yapıştırılması: 

bir aşkın başlaması

unutulan her güzellik geçmişe karışmaz

yeni güzelliklere eklenir bazısı

bu yüzden en güzeldir en son sevilen

bütün güzellikleri kendine birleştiren

ırmakları, okyanusları, bitimsiz yağmurları

bir güz sabahı kapınıza getiren! 

böyle zamanlarda güzeldir bir şarkıyla uyanması

uykunuzu titretir uzadıkça la sesi ince

kadının ayakları suya değince: 

bir aşkın başlaması

ipekler altında kabaran göğüslerin tadıyla

gizine erişilmiş sevişmelerin yeni zamanları

bütün hayatı içerecek, 

o garip hışırtının böceği aranacak her köşede

anlamsız sayılacak sonra

ışıkların kırgınlıklara kırılarak yansıması...

eşyalar birbirine karışmış

mutluluk kendini mahzende unutmuş olacak, 

böyle bir tablonun usulca indirilmesi duvardan: 

bir aşkın başlaması

yeni şeyler ezberlemenin yanlışlığı

bilgiye sığınmak ve kutsamak katılığı

gümüş bir gemiyi getirmek diplerden

savrulan bir uçurtmayı gökte unutmak

doğayı değiştirmek temiz sulara eğilirken

gümüş bir gemiyi diriltmenin yanılsaması

zamanın akışını hızlandırmak: 

bir aşkın başlaması

en sonra: 

birdenbire eski yağmurları anımsamak

kırmızı sincapların eskimeyen sıçrayışlarında

okyanusun esnek akışlarında

altın renkli bir balığın sırtında dalgalanmak

en eski çağların güne kavuşan hızında

yırtık albümlerin yeni resimlerle yamanması

kalbin yenilgileri kanıksaması

enginlere açılması gülümseyerek

titrek günler içinde kırışmalarla: 

bir aşkın başlaması

szahal 17.12.2002', 'bir aşkın başlaması:  ruhla yontulması sert bir ağacın bir anahtar sessizce açar doğayı bir la sesi başlatır fırtınayı çeker bıçağını hırçın...', ARRAY['Türk Edebiyatı','Şiir','Baki Ayhan T.']::text[], 8.5, '{"poet":"Baki Ayhan T.","poet_slug":"baki-ayhan-t","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/bir-askin-baslamasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-selami-ozturk-103o8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dün gece cok kırıldım

Bir bana inanmadıgın için

Bir sesimi duyupta konusmadıgın için

Öyle çekip gitmek varmı kızınca

Hadi sen çektin gittin usulca

Oysa ben, 

Ne seni bırakabilirim nede ben gidebilirim....

Ayaklarım tutulur.. uykular kabus olur.. 

Geceler ise hiç yetişmez sabaha...

Bir daha bırakıp gitme

Olurmu

Öyle usulca', 'Dün gece cok kırıldım Bir bana inanmadıgın için Bir sesimi duyupta konusmadıgın için Öyle çekip gitmek varmı kızınca Hadi sen çektin gittin ...', ARRAY['Türk Edebiyatı','Şiir','Selami Öztürk']::text[], 8.5, '{"poet":"Selami Öztürk","poet_slug":"selami-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gitme-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizlik', 'sessizlik-selami-ozturk-s5qip', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dostlar sevdigim gömleklere benzer benim için

En sevdigim gömlegi hergün giyerim

Digerlerini de severim ama onu hergün giyemem

Hergün giydigim gömlekte ben varım

Terim siner ruhum siner duygularım siner...

ben varım

Sen benim her gün giymek istedigim gömlegimsin

Sana bir sır

Acı vermek istersen bana 

Oda sessizligindir.', 'Dostlar sevdigim gömleklere benzer benim için En sevdigim gömlegi hergün giyerim Digerlerini de severim ama onu hergün giyemem Hergün giydig...', ARRAY['Türk Edebiyatı','Şiir','Selami Öztürk']::text[], 8.5, '{"poet":"Selami Öztürk","poet_slug":"selami-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sessizlik-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Diye', 'sen-diye-zafer-keskin-5y48r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir siirdi sendiye

Butun gamlar gonlume

Herkederi sen diye

Cekipte geciyorum

Goz yaslarim sarabim

Mezem oldu sigaram

Her kadehin ardindan

Yakipta geciyorum

Bir masaldi sendiye

Turlu dertler omrume

Her kederi sendiye

Cekipte geciyorum

Goz yaslarim sarabim

Mezem oldu sigaram

Herkederin ardindan

Yakipta geciyorum', 'Bir siirdi sendiye Butun gamlar gonlume Herkederi sen diye Cekipte geciyorum Goz yaslarim sarabim Mezem oldu sigaram Her kadehin ardindan Ya...', ARRAY['Türk Edebiyatı','Şiir','Zafer Keskin']::text[], 8.5, '{"poet":"Zafer Keskin","poet_slug":"zafer-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fotoğraflar', 'fotograflar-zeren-cangert-s40fw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eski fotoğraflar ellerde 

Bakılıyor o eski yüzlere 

Ne mutlu, ne sevinçli, ne temiz yüzümüz var 

Biz aslında neymişiz be 

O günler geri gelir mi? 

Babanız kucağına alır mı bir daha sizi? 

Anneniz öper mi bir daha, öyle sıcak? 

Hapsettik yüzlerimizi fotoğraflara 

Bir daha aynı bakamayacağız. 

Aynı gülemeyeceğiz, 

Aynı tutamayacağız, babalarımızın elini. 

Emziklerimiz boynumuzdan salınmayacak, 

Doğum günlerindeki o sevinç ve mutluluk, 

Bu kadar net okunmayacak yüzlerimizden. 

O resimler çekilirken hep kendimizdik. 

Yanağımızdaki çukurları, 

Ağzımızı şişirip kapatmazdık. 

Dağınık saçlarımızı iyi toparlayamazdık. 

Gözlüklerimiz de hiç bir zaman, 

Bu kadar büyük olmayacak. 

Şimdi gülüyoruz ama 

Bu kadar komik olamayacağız bir daha 

O fotoğraflardaki sizdiniz. 

Bütün yaşanmışlığı ile 

Sizin gerçekleriniz.', 'Eski fotoğraflar ellerde  Bakılıyor o eski yüzlere  Ne mutlu, ne sevinçli, ne temiz yüzümüz var  Biz aslında neymişiz be  O günler geri geli...', ARRAY['Türk Edebiyatı','Şiir','Zeren Cangert']::text[], 8.5, '{"poet":"Zeren Cangert","poet_slug":"zeren-cangert","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/fotograflar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Yaprağı Gibisin Yastığımda', 'gul-yapragi-gibisin-yastigimda-emre-gumusdogan-skayq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'nerede başlıyor bu ayrılık 

nerede bitiyor 

sınırı nerede bilmiyorum 

öyle bir günde geliyorsun ki 

gittiğini unutuyorum o an 

var mısın yok musun 

gül yaprağı gibisin yastığımda 

saçlarında yosun kokusu 

hangi limanlardan geldin 

hangi mavilerde yıkandın 

her gelişin 

bir tükenişe başlatıyor yaşamı 

bu yazgının kör ruhuna inat 

denizlerinde yitirip yeniden buluyorum kendimi 

sende benim gibi 

doyumsuz musun 

güvercinim / ürkek ve sıcak / 

sokulmuş koynuma uyuyorsun 

dalgalar kıyıları dövedursun 

rüzgarlar pencereme vuradursun 

üşümez sen varken ellerim 

alıp gitme sıcaklığını 

ne olursun', 'nerede başlıyor bu ayrılık  nerede bitiyor  sınırı nerede bilmiyorum  öyle bir günde geliyorsun ki  gittiğini unutuyorum o an  var mısın yok...', ARRAY['Türk Edebiyatı','Şiir','Emre Gümüşdoğan']::text[], 8.5, '{"poet":"Emre Gümüşdoğan","poet_slug":"emre-gumusdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gul-yapragi-gibisin-yastigimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle Başlamıştık Seninle', 'boyle-baslamistik-seninle-mehmet-bor-t3bz9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir tesadüf, 

başka birşey değil di, 

O''rada beklemem.

Senin geçişin.

Meraklı gözlerin, 

üzerine kilitlenişi.

Kimse birşey, 

söylemesin, 

O benim, 

sözcüklerinin, 

dudaklarımdan sarf edilişi.

Duymuş tun.

Hoşuma gitmişti, 

ümitlenmiş, 

gururlanmıştım.

Böyle başlamıştık seninle, 

evet, evet

tamamen böyle olmuştu.

Mümkün değil yanlış

hatırlamam, 

Zira; 

fena etkilemiştin 

beni.

Dün gibi hatırlıyorum.

üzerinde 

kot bir pantolon

beyaz bir bluz

saçların muntazam 

kesilmiş

omuzundan aşağıya

akıyordu.

Tatlı bir tebessüm

davetkar bakışlı 

siyah gözler

ve 

edalı yürüyüşün.

Böyle başlamıştık seninle

sonrası

konuşmalar

arka, arkaya yazılan

mektuplar

aştan kesilmiş

birbirimizle doyuyorduk sanki.

Böyle başlamıştık seninle.

düşlediğimiz gibi

sevgimiz 

gün be gün

olgunlaşıp geliyordu.

bir tutam olmuştu adeta günler

batan güneşin ardından

doğan yıldızlar 

kıskanıyordu 

bizi.

Ne oldu da

karanlık çöktü birden

hani; 

yüce sevgi

hayaller

sevgi yuvası

aşkımızın meyveleri

isimlerimizi kazıdığımız

ağaçlar, masalar.

Ne oldu da

kısıtlanmıştı

birbirimize 

karşı özgürlüğümüz

ne oldu da

kine dönüştü gözlerimiz.

Nasıl hazırlamışlardı

nasıl kıymışlardı

nasıl müsaade etmiştik

nasıl başarmışlardı.

Geçen günler

yıpratıp savuruyordu

ikimizi

Tabii ki

çaba sarfettik

çözemediğimse

biraraya gelemiyor

engelleniyorduk

seninle.

Sonrasını...

Anlatmama gerek varmı? 

bilmiyorum..

Terk etmiştim, 

seninle paylaştığım

şehri.

Zamana bırakmıştım.

Herşeyi 

ve 

seni.

Unutamadım.

Unutamadım.

Böyle başlamıştık seninle.

Ne yazık ki; 

Başladığımız gibi

bitiremedik seninle...', 'Bir tesadüf,  başka birşey değil di,  O''rada beklemem. Senin geçişin. Meraklı gözlerin,  üzerine kilitlenişi. Kimse birşey,  söylemesin,  O ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bor']::text[], 8.5, '{"poet":"Mehmet Bor","poet_slug":"mehmet-bor","theme":"Türk Şiiri","is_hero":false,"total_lines":97,"source_url":"https://www.antoloji.com/boyle-baslamistik-seninle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varmı..?', 'varmi-ali-niku-yf3j7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'birileri var diyor

kimilerinde tık yok

kimisinin tasviri

diğerine hiç uymaz

bazıları kendi yapar

bazıları anlamaz

herkesi bir toplasak

biraya getirsek

hadi uzlaşın desek

orada kavga olur

belkide bir katliam

hani sevgi var idi

tüm dinlerin içinde', 'birileri var diyor kimilerinde tık yok kimisinin tasviri diğerine hiç uymaz bazıları kendi yapar bazıları anlamaz herkesi bir toplasak biray...', ARRAY['Türk Edebiyatı','Şiir','Ali Niku']::text[], 8.5, '{"poet":"Ali Niku","poet_slug":"ali-niku","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/varmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bektâşi', 'bekt-si-ali-niku-5as43', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bektaşi camiye gitmiş

hoca oturur mimberde

amaç fetva vermekmiş

dinleyenlerse yerde

allah ne yerde demiş

nede gök yüzünde

ne sağımızda durur

arama hiç solunda

bektaşi duramamış

oturduğu yerinde

hoca sen ne diyorsun

boşa kıvranıyorsun

yok diyeceksin amma

becer edemiyorsun...', 'bektaşi camiye gitmiş hoca oturur mimberde amaç fetva vermekmiş dinleyenlerse yerde allah ne yerde demiş nede gök yüzünde ne sağımızda durur...', ARRAY['Türk Edebiyatı','Şiir','Ali Niku']::text[], 8.5, '{"poet":"Ali Niku","poet_slug":"ali-niku","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bektasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devrez Kıyısında', 'devrez-kiyisinda-muammer-mermer-f4zqc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Devrez kıyısında bir köy

Bize değil bu çan sesleri

Uzak bir hatıradır şimdi

Pırıl pırıl ezan sesleri

Devrez kıyısında bir köy

Damları sivri külah

Uzanır ta nehre kadar

Cıvıl cıvıl insan sesleri

Durgundur tertemiz devrez

Adına ne türkü yakılmış ne kurban

Alır götürür uzaklara sessizce

Sularında kaybolan sesleri', 'Devrez kıyısında bir köy Bize değil bu çan sesleri Uzak bir hatıradır şimdi Pırıl pırıl ezan sesleri Devrez kıyısında bir köy Damları sivri ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Mermer']::text[], 8.5, '{"poet":"Muammer Mermer","poet_slug":"muammer-mermer","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/devrez-kiyisinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efsane bir Ülke Buz Dağları', 'efsane-bir-ulke-buz-daglari-firat-utkan-ugyzg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen

bunca yaşadıklarından sonra

bırakmışsın kendini

o

Huzur dolu

Sakin

Sessiz

Yavaş

Semazenlerin dinginliğine

Bense

hâlâ çırpınıyorum

Senin

Efsane bir ülke zannettiğin

Buz dağlarının ortasında

Canlı

Yeşil

Denizin dibinde

Şimdi

kolaysa

beni dizginle', 'Sen bunca yaşadıklarından sonra bırakmışsın kendini o Huzur dolu Sakin Sessiz Yavaş Semazenlerin dinginliğine Bense hâlâ çırpınıyorum Senin ...', ARRAY['Türk Edebiyatı','Şiir','Fırat Utkan']::text[], 8.5, '{"poet":"Fırat Utkan","poet_slug":"firat-utkan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/efsane-bir-ulke-buz-daglari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Sen Olmasaydın', 'sen-olmasaydin-cemal-karsavran-v3914', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen olmasaydın gece doğmazdı güne

Çember olur başımda sigaramın dumanı

Her nefes alışımda seni alırım seni

Yanan bir sevdadır dudaklarımda

Sen olmasaydın günle gelen fısıldayarak

Güneş kadar sıcak olmazdım günle

Kanım akıp gitmezdi ılık ılık damarlarımda

Bir sonbahar sabahında hafif esen rüzgarla

Sen olmasaydın adım atıp nefes alışlarımda

Bitermiydi onca yol zamanlara sığmayan

Gözlerimde uçuşan uğur böceğimdin ki

Benimle yürüyen gölgem değilde sendin

Tutarmıydı parmağım mavi yazan kalemi

Yürekten durmaz akar sevdadır dedikleri

Bir gün senle başladı senle biterde

Durmaz döner mutluluğun çemberi başımda

Sen olmasaydın.....', 'Sen olmasaydın gece doğmazdı güne Çember olur başımda sigaramın dumanı Her nefes alışımda seni alırım seni Yanan bir sevdadır dudaklarımda S...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-olmasaydin-69-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karmaşığım Aşkına', 'karmasigim-askina-firat-utkan-kzz9y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hep Eylül''e demişlerdi kara

Onüç Ekim''de dedin elveda

Oysa ölünce gelecektik tekrar bir umutla

Bir kuş olarak dünyaya

Sen umudumu öldürdün

Çünkü öldürmek için benzetmişsin beni

Fırtına Kuşu Albatrosa

Mevlana ölür sevgi olur

Sevgi büyür aşk olur

Aşk can bulur kuş olur

Kuş kanat açar adaya 

Adakuşu olur 

Fırtına Kuşu Albatros özler ama 

Yalnız kalır

Ve bıraktığın ben

Yine de 

Alıkoyamadığım özlemlerim arasında

Umudum geçirmişken yelkovanı boğazıma

Başlayacağım dakikaları teker teker

Saat aralıklarıyla saymaya

Kızıl bir kuşak çekildiğinde hayata

Hani on metreye yükselirmiş ya Amazonlar baharda

İşte o sevgi dolu coşkun duygularla

Yalnızım

Sevgimi sahiplenip duyguları bıraktın bana

Bu baharda

Ve ben Amazonlarda

Ve sen, benim şahsımda

Telefonun diğer ucunda

''Tanıyamadığım'' dediğin tüm insanlara

Son sözünmüş meğer

Kurabiye yanıyor.', 'Hep Eylül''e demişlerdi kara Onüç Ekim''de dedin elveda Oysa ölünce gelecektik tekrar bir umutla Bir kuş olarak dünyaya Sen umudumu öldürdün Ç...', ARRAY['Türk Edebiyatı','Şiir','Fırat Utkan']::text[], 8.5, '{"poet":"Fırat Utkan","poet_slug":"firat-utkan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/karmasigim-askina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elvedasız', 'elvedasiz-ali-kalayci-4q4ry', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ne sen duydun

elime tutuşturduğun

ak ağızlı menekşelerin

külhan kahkahalarını

ne ben farkına vardım.

geldiğim aynı tren

şehrinizden ayrılırken

sevdim yolculukları

sonra kuru gözlerle bakıştık 

bakışlar arasından

dudağının hizasına

kızılcacık kondurulmuş bir öpücük

muhbir olabilirdi

s e v d a m a, 

affet diyebilseydin', 'ne sen duydun elime tutuşturduğun ak ağızlı menekşelerin külhan kahkahalarını ne ben farkına vardım. geldiğim aynı tren şehrinizden ayrılırk...', ARRAY['Türk Edebiyatı','Şiir','Ali Kalaycı']::text[], 8.5, '{"poet":"Ali Kalaycı","poet_slug":"ali-kalayci","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/elvedasiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Şarkı', 'son-sarki-zafer-keskin-8ba1z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu sana son mesajim

Seni son gorusumdu

Belkide yalan yanlis

Sana son gulusumdu

Kalbime gomdum artik 

Boktan duygularimi

Senin icin bugece

Inan son olusumdu

Yaktim seni anlatan

Butun siirlerimi

Hem askimi hem beni

Maziye gomdum seni

Sildim telefonumdan

Hem askimi hem seni

Bu gece ya bitisim

Yada son bitisimdi

Korma ugruna artik

Bolmem uykularimi

Bu gece sonkez ictim

Bara son gelisimdi

Inadina bir askla

Sevmekti benimkisi

Neyim var neyim yoksa

Oynamistim ugruna

Kelimeler tukendi

Heceler iflaz etti

Son noktaydi bu gece

Seni son sevisimdi 

                                            zafer keskin', 'Bu sana son mesajim Seni son gorusumdu Belkide yalan yanlis Sana son gulusumdu Kalbime gomdum artik  Boktan duygularimi Senin icin bugece In...', ARRAY['Türk Edebiyatı','Şiir','Zafer Keskin']::text[], 8.5, '{"poet":"Zafer Keskin","poet_slug":"zafer-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/son-sarki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabıkasız Suların Uykusu', 'sabikasiz-sularin-uykusu-ali-kalayci-fp7eo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'hışımla geçer 

tan ortası

yağmalanmış düşler sürüsü

kenar sokaklardan.

ay dölleri bulaşır gölgelerinden 

şehre örtük bütün kapılarıma.

ölesiye cenabet, ölesiye yataklarda 

şadırvanlar ayağıma kapanmaz 

denizler sırnaşmaz kasıklarıma

su uyur ben uyurum.

                                    

her sabah

bir intikam tebliği

bir cenaze alayı boşalır sakallarımdan.

meydanlar sakallarımla çoğalır

inançları yuhalanmış insanlarla beraber

sakallarım zapta geçer

zapta geçer resmi tatil, 

dernekler kanunu, proletarya

her sabah gözlerime kan yürür

kan yürür ben yürürüm.

yürüdükçe şenlenir mahkemeler

acılar onarılır, onarılır ilahiler

yürüdükçe su uyur

yer gürler, bela ilerler..

en ummadığın anda

bir namlu apansız kendini ihbar eder 

sen değil ben ölürüm.', 'hışımla geçer  tan ortası yağmalanmış düşler sürüsü kenar sokaklardan. ay dölleri bulaşır gölgelerinden  şehre örtük bütün kapılarıma. ölesi...', ARRAY['Türk Edebiyatı','Şiir','Ali Kalaycı']::text[], 8.5, '{"poet":"Ali Kalaycı","poet_slug":"ali-kalayci","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sabikasiz-sularin-uykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dil Bulamadım', 'dil-bulamadim-zafer-keskin-zsyr1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bildigin baska bir lisanin varmi

Beni anladigin dil bulamadim

Sayende sasirdi gonul pusulam

Gonlune girecek yol bulamadim.

Seni ben bir mabet yapmisken once

Herseyden vazgecip tapmisken once

Bildigim yollardan sapmisken once

Ufkunda tutar bir dal bulamadim.

Huzuru biraktim karanliklara

Bir ufkun bin cikmaz yollara kara

Sen gonul zengini bense fukara

Muhurlu gonlune pul bulamadim.', 'Bildigin baska bir lisanin varmi Beni anladigin dil bulamadim Sayende sasirdi gonul pusulam Gonlune girecek yol bulamadim. Seni ben bir mabe...', ARRAY['Türk Edebiyatı','Şiir','Zafer Keskin']::text[], 8.5, '{"poet":"Zafer Keskin","poet_slug":"zafer-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dil-bulamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Benim Sarı Tanburam', 'gel-benim-sari-tanburam-pir-sultan-abdal-of0ux', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gel benim sarı tamburam,

Sen ne için inilersin? 

Içim oyuk, derdim büyük,

Ben anın''çin inilerim

Koluma taktılar teli,

Söyletirler bin bir dili,

Öldüm ayn-ı cem bülbülü,

Ben anın''çin inilerim.

Koluma taktılar perde,

Ugrattılar bin bir derde.

Kim konar, kim göçer burda? 

Ben anın''çin inilerim.

Göğsüme tahta döşerler,

Durmayıp beni okşarlar,

Vurdukça bağrım deşerler

Ben anın''çin inilerim.

Gel benin sarı tamburam,

Dizler üstünde yatıram,

Yine kırıldı hatıram,

Ben anın''çin inilerim.

Sarı tamburadır adım,

Göklere ağar feryadım,

Pîr Sultan''ımdır üstadım,

Ben anın''çin inilerim.', 'Gel benim sarı tamburam, Sen ne için inilersin?  Içim oyuk, derdim büyük, Ben anın''çin inilerim Koluma taktılar teli, Söyletirler bin bir di...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gel-benim-sari-tanburam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkü', 'turku-karacaoglan-qcfs5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her sabah her sabah gelir geçerler

Dünyalar durdukça durası kızlar

Bir vefa görmedim kaşı karadan

Allah''ım muradı veresi kızlar

Kızlar güzel güzel aslı huriden

Yeryüzünü lale sümbül bürüden

Kasvetli gönlümün gamın eriden

Karanlık gecemin çırası kızlar

Donadaydım yeşil ile al ile

Besliyeydim şeker ile bal

Boğum boğum al kınalı al ile

Gelin olup bize varası kızlar

Karac''oğlan bir sümbülcük yetirsem

Yetirsem de gölgesinde otursam

Kulağı küpeli bir yar getirsem

Babamın evine giresi kızlar', 'Her sabah her sabah gelir geçerler Dünyalar durdukça durası kızlar Bir vefa görmedim kaşı karadan Allah''ım muradı veresi kızlar Kızlar güzel...', ARRAY['Türk Edebiyatı','Şiir','Karacaoğlan']::text[], 8.5, '{"poet":"Karacaoğlan","poet_slug":"karacaoglan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/turku-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdilik', 'simdilik-ali-kalayci-o6c5j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gözlerimin değdiği yüksek camlarda

son turunci caka, 

son günbatısı konak 

bu mehdi çığırtkanı 

bu kızıl kanatlı akşam.

övünecek hatıram olmadığındandır 

şimdilik hayattaysam 

her şeyi derviş telaşsızlığıyla yaşadım.. 

          

yanaştığım her sulakta

şükretmekten usandım

yoruldum yataklarda

sabahı kollamaktan

kentlerden de nefret ettim

hazır kadınları ve bütün şairleriyle

saltanat sofralarından

öç almayı şeref saydığımdandır

şimdilik hayattaysam

bir korkunun eşiğindeyim gülüm

bana selamet dile

bütün zırhım harcıalem bir ümit 

başka şeyler kuşanmadım

beni bekaretinle tembihle.', 'gözlerimin değdiği yüksek camlarda son turunci caka,  son günbatısı konak  bu mehdi çığırtkanı  bu kızıl kanatlı akşam. övünecek hatıram olm...', ARRAY['Türk Edebiyatı','Şiir','Ali Kalaycı']::text[], 8.5, '{"poet":"Ali Kalaycı","poet_slug":"ali-kalayci","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/simdilik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ela Gözlü Nazlı Dilber', 'ela-gozlu-nazli-dilber-karacaoglan-gv0iy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ela gözlü nazlı dilber

Koma beni el yerine

Altın kemerin olayım

Dola beni bel yerine

Hecine gönlüm hecine

Yiğide ölüm gecine

Al beni zülfün ucuna

Sallanayım tel yerine

Gel kız karşımda dursana

Şu benim halim sorsana

Zülfünden bir tel versene

Koklıyayım gül yerine

Karac''oğlan der n''olayım

Kolun boynuma dolayım

Nazlı yar kölen olayım

Kabul eyle kul yerine', 'Ela gözlü nazlı dilber Koma beni el yerine Altın kemerin olayım Dola beni bel yerine Hecine gönlüm hecine Yiğide ölüm gecine Al beni zülfün ...', ARRAY['Türk Edebiyatı','Şiir','Karacaoğlan']::text[], 8.5, '{"poet":"Karacaoğlan","poet_slug":"karacaoglan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ela-gozlu-nazli-dilber-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boynu Yeşil Gövel Ördek', 'boynu-yesil-govel-ordek-karacaoglan-dovv0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Boynu yeşil gövel ördek

Sana bir göl gerek idi

Kanadının biri yeşil 

Biri de al gerek idi

Bir göl gerekti yüzmeğe

Yüzüp eğrice gezmeğe

Aşıkın bağrını ezmeğe

Sana bir dil gerek idi

Bulunmaz aşkın ilacı

Sevip ayrılması acı

Yüzdüğün gölün sıyacı

Karanfil gül gerek idi

Karac''oğlan fikrinde 

Daim Hakk''ın zikrinde

Ak göğsünün çukurunda

Sana bir ben gerek idi', 'Boynu yeşil gövel ördek Sana bir göl gerek idi Kanadının biri yeşil  Biri de al gerek idi Bir göl gerekti yüzmeğe Yüzüp eğrice gezmeğe Aşıkı...', ARRAY['Türk Edebiyatı','Şiir','Karacaoğlan']::text[], 8.5, '{"poet":"Karacaoğlan","poet_slug":"karacaoglan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/boynu-yesil-govel-ordek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedendir de Kömür Gözlüm Nedendir', 'nedendir-de-komur-gozlum-nedendir-karacaoglan-nchj3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nedendir de kömür gözlüm nedendir

Şu geceki benim uyumadığım

Çetin derler ayrılığın derdini

Ayrılık derdine doyamadığım

Dostun bahçesine yad eller dolmuş

Gülünü toplarken fidanın kırmış

Şurda bir kötünün koynuna girmiş

Şu benim sevmeye kıyamadığım

Kömür gözlüm seni sevdim sakındım

İndim has bahçeye güller sokundum

Bilmiyorum nereler''ne dokundum

Belli bir haberin alamadığım

Karac''oğlan der ki yandım da öldüm

Her deliliği ben kendimde buldum

Dolanıp da kavil yerine geldim

Kavil yerlerinde bulamadığım', 'Nedendir de kömür gözlüm nedendir Şu geceki benim uyumadığım Çetin derler ayrılığın derdini Ayrılık derdine doyamadığım Dostun bahçesine yad...', ARRAY['Türk Edebiyatı','Şiir','Karacaoğlan']::text[], 8.5, '{"poet":"Karacaoğlan","poet_slug":"karacaoglan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nedendir-de-komur-gozlum-nedendir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mustafa Kemal''in Kağnısı', 'mustafa-kemal-in-kagnisi-fazil-husnu-daglarca-wryqf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yediyordu Elif kağnısını

Kara geceden geceden

Sanki elif elif uzuyordu inceliyordu

Uzak cephelerin acısıydı gıcırtılar

İnliyordu dağın ardı yasla

Herbir heceden heceden

Mustafa Kemal''in Kağnısı derdi kağnısına

Mermi taşırdı öteye, dağ taş aşardı

Çabuk giderdi, çok götürürdü Elifcik

Nam salmıştı asker içinde

Bu kez herkesten evvel almıştı yükünü

Doğrulmuştu yola, önceden önceden

Öküzleriyle kardeş gibiydi Elif, 

Yemezdi, içmezdi, yemeden içmeden onlar

Kocabaş çok ihtiyardı çok zayıftı

Mahzundu bütün Sarıkız, yanısıra

Gecenin ulu ağırlığına karşı, 

Hafiftiler, inceden inceden

İriydi Elif kuvvetliydi kağnı başında

Elma elmaydı yanakları, üzüm üzümdü gözleri

Kınalı ellerinden  rüzgar geçerdi daim

Toprak gülümserdi çarıklı ayaklarına

Alını yeşilini kapmıştı, geçirmişti

Niceden niceden

Durdu birdenbire Kocabaş, ova bayır durdu.

Nazar mı değdi göklerden, ne? 

Dah etti, yok.Dahha! dedi, gitmez.

Ta gerilerden başka kağnılar yetişti geçti gıcır gıcır

Nasıl durur Mustafa Kemal''in Kağnısı

Kahroldu Elifcik, düşünceden düşünceden

Aman Kocabaş, ayağını öpeyim Kocabaş, 

Vur beni, öldür beni, koma yollarda beni.

Geçer, götürür ana çocuk mermisini askerciğin

Koma yollarda beni, kulun köpeğin olayım

Bak hele üzerimden ses seda uzaklaşır

Düşerim gerilere iyceden iyceden

Kocabaş yığıldı çamura

Büyüdü gözleri büyüdü, yürek kadar

Örtüldü gözleri örtüldü hep

Kalır mı Mustafa Kemal''in Kağnısı bacım

Kocabaşın yerine koştu kendini Elifcik

Yürüdü düşman üstüne yüceden yüceden.', 'Yediyordu Elif kağnısını Kara geceden geceden Sanki elif elif uzuyordu inceliyordu Uzak cephelerin acısıydı gıcırtılar İnliyordu dağın ardı ...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 8.5, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/mustafa-kemal-in-kagnisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git Buralardan Uzaklara', 'git-buralardan-uzaklara-gokcen-duran-auxa0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreğimin   kıyısına   demirleyen  gemi

Çiğ  düşen  bu  sabah, kimi  bekliyorsun

Götürecekken  rüzgar  seni  enginlere

Git  buradan  uzaklara, neyi bekliyorsun

Birazdan  yüreğimde  fırtınalar  kopacak

Dolunay  doğacak,  med- cezirler olacak

Ne  anne, ne baba,  ne de yar,  kalacak

Git buradan uzaklara, neyi bekliyorsun', 'Yüreğimin   kıyısına   demirleyen  gemi Çiğ  düşen  bu  sabah, kimi  bekliyorsun Götürecekken  rüzgar  seni  enginlere Git  buradan  uzaklar...', ARRAY['Türk Edebiyatı','Şiir','Gökçen Duran']::text[], 8.5, '{"poet":"Gökçen Duran","poet_slug":"gokcen-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/git-buralardan-uzaklara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Aşkı''m', 'tek-aski-m-ozan-yazan-8p9l1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'A klıma hayalin düşsün varsın, 

          Ş iir olup ismin dudaklarımda aksın, 

          K imbilir kime, niye aşıksın? 

          I ssız diyarlarda bilmiyorsun ki kimin AŞKI''sın..

          E y ozan md derdine bulunmaz çare, 

          L eb-i deryalarda içmekle kapanmaz yare, 

          L alelerin yine soldu, can pare pare, 

          İ bret oldu sevdan cümle şaire..

          B ak; acıyan tavrını takınmış güneş, 

          E lemim ummanlara, uludağlara eş, 

          Ş air ettin ya beni bile, bravo yani AŞKI ELLİBEŞ..', 'A klıma hayalin düşsün varsın,            Ş iir olup ismin dudaklarımda aksın,            K imbilir kime, niye aşıksın?            I ssız di...', ARRAY['Türk Edebiyatı','Şiir','Ozan Yazan']::text[], 8.5, '{"poet":"Ozan Yazan","poet_slug":"ozan-yazan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tek-aski-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mona-Lisa Ağıdı', 'mona-lisa-agidi-tahir-yuksel-v8g3d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yaratıcı köleler ihanet etti yarattıklarına

tek ve misilsiz

tek ve misilsiz yaratıcıyı üçe eşlediler

ve damla damla şeytan şurubu

ayırdı da köleleri tevhîdden

seni yarattılar /mona-lisa/ yalnız ve çâresiz

evrenin ortasında boynu bükük çiçek susamışlığında sen

onlar

aşkın namus olduğunu inkâr edip

put ve çan /kadınlara secde eylediler/ neron kahkahasınca

ve seninle

mona-lisa

simgelediler kadının yalnızlığını

kendileri tanrı''yı da üçlerken

ey dinle

dinle batı''nın mağrur ve masum kadını

ey analığı elinden alınmış

ey kölelerin yarattığı köle

yeni doğmuş bebek sesi nasıldır

anneler gününde

ana okulunun kafeslediği çocuk cıvıltılarını

seni lîme lîme eden giyotinler mi parçaladı

yapayalnız kılındığın fırça darbelerine eş

ikinci sınıf insan kalitesinde

bir çocuk emzirmeni bile çok gören

ve seni ilik ilik sömüren /hürriyet aşkıyle/

tanrını üçleştiren

ve seni tekleştiren batı

muson rüzgârı tebessümünü 

karaborsa fotoğraflarda sattı eşya gibi

sattı seni mona-lisa

ağlamak isterdim ey

senin ezilmişliğin için mona-lisa

gözyaşlarım çok değildi sana

şefkatini sömürenler

bende de bırakmadılar /gözyaşlarını/ ey

ağlayamam

ağlayamam sana mona-lisa', 'yaratıcı köleler ihanet etti yarattıklarına tek ve misilsiz tek ve misilsiz yaratıcıyı üçe eşlediler ve damla damla şeytan şurubu ayırdı da ...', ARRAY['Türk Edebiyatı','Şiir','Tahir Yüksel']::text[], 8.5, '{"poet":"Tahir Yüksel","poet_slug":"tahir-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/mona-lisa-agidi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaç Boyut', 'kac-boyut-mestan-ozyer-qr2e7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kaç boyut vardır bir yaşamda

Kaç yaşam sığar bir ömre

Kaç geceden sonra geçer özlem

En çok kaç kişiyi sevebilir bir insan

kaçını unutabilir

Ve kaç yaradan sonra hissedilmez olur acı

Bir bilsem

(İzmir-2002)', 'Kaç boyut vardır bir yaşamda Kaç yaşam sığar bir ömre Kaç geceden sonra geçer özlem En çok kaç kişiyi sevebilir bir insan kaçını unutabilir ...', ARRAY['Türk Edebiyatı','Şiir','Mestan Özyer']::text[], 8.5, '{"poet":"Mestan Özyer","poet_slug":"mestan-ozyer","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kac-boyut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nuh''un Gemisine Binemeyenler', 'nuh-un-gemisine-binemeyenler-tahir-yuksel-7gal1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'toz kanatlı kelebekler gördüm fırtınaya tutulmuş

bîçâreliğin lügat karşılığınca

ve tutunacak bir merkep kuyruğu da bulamamışlardı

şeytancasına

bilmem kaçıncı nuh tufanı''nda', 'toz kanatlı kelebekler gördüm fırtınaya tutulmuş bîçâreliğin lügat karşılığınca ve tutunacak bir merkep kuyruğu da bulamamışlardı şeytancası...', ARRAY['Türk Edebiyatı','Şiir','Tahir Yüksel']::text[], 8.5, '{"poet":"Tahir Yüksel","poet_slug":"tahir-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/nuh-un-gemisine-binemeyenler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çabuk Büyü Çocuk', 'cabuk-buyu-cocuk-melih-coskun-ufr0r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çabuk büyü çocuk

Ödenecek borcun var daha senin 

Borçlu doğdun sen

Yurdunda doğan her çocuk gibi

Borçlusun, 

Çabuk büyü, 

Erken yürü ki 

At kendini sokaklara

Mendil sat, ayakkabı boya 

Kalabalık kaldırımlarında şehrinin, 

Okula gidemeyeceksin

Gitmene gerek yok zaten

Hayat çok şeyler öğretecek sana

Öğreneceksin kaçmayı zabıtadan

Kovalamayı bir lokma ekmeği kar altında, 

Yüreğin erken büyüyecek 

Yüreği erken yaşlanmış bir çocuk olacaksın

Biraz daha büyüdüğünde küçük hayaller kuracaksın

Sıcak bir yuva, sıcak bir yemek belki de

Parçalayacaklar yırtıcı kuşlar 

Bu küçük hayallerini bile senin

Çabuk büyü çocuk 

Daha çok borcun var ödenecek

Büyü ki öde borcunu...

7 Haziran 2002 

23: 59', 'Çabuk büyü çocuk Ödenecek borcun var daha senin  Borçlu doğdun sen Yurdunda doğan her çocuk gibi Borçlusun,  Çabuk büyü,  Erken yürü ki  At ...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/cabuk-buyu-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözümü Diktiğim Yer', 'gozumu-diktigim-yer-melih-coskun-vfhh5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözümü dikip kaldığım yerdedir hayallerim

Kimi zaman bir meydandadır 

Bir delikanlının gür sesiyle haykırdığı, 

Kimi zaman bir dağ başındadır 

Özgürce söylendiği türkülerin

Gözümü dikip kaldığım yerde kavgam var, 

Sevdam var bir kuş tüyü gibi yumuşacık...

19.06.2002

23: 52', 'Gözümü dikip kaldığım yerdedir hayallerim Kimi zaman bir meydandadır  Bir delikanlının gür sesiyle haykırdığı,  Kimi zaman bir dağ başındadı...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gozumu-diktigim-yer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzelliğe Dair Ne Varsa', 'guzellige-dair-ne-varsa-melih-coskun-ebitf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Paylaşılmış dünyada güzelliğe dair ne varsa

Bugün bize hüzün kalır 

Bugün bize pişmanlık 

Bugün yitik devrimlerin acısı kalır

Sevmeyi bile çok görürler bugün bize

Dokunulmamış 

Bir kar tanesi gibi beyaz sevmeleri 

Çok görürler bu koca yüreklere

Ama umutlarımızı bırakmayacağız onlara

Saklayacağız zulamızda

Toprağın altına gömeceğiz

Yarın gün doğmadan sulayacağız toprağı

Güneşle birlikte yaracak toprağı

Yükselecek hızla göğe

Hafiften bir tebessüm başlayacak o zaman yüzlerde

Yürekteki zincirler parçalanacak 

O gün gelecek 

Artık sadece sevinçten ağlayacağız

Şarkılar söyleyeceğiz meydanlarda yüz binlerle

Şiirler okuyacağız bağırarak 

Sabahlara kadar  koşacağız

Güneşin doğduğu yere doğru

Özgür olacağız o gün...

06.07.2002

23: 48', 'Paylaşılmış dünyada güzelliğe dair ne varsa Bugün bize hüzün kalır  Bugün bize pişmanlık  Bugün yitik devrimlerin acısı kalır Sevmeyi bile ç...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/guzellige-dair-ne-varsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk', 'mutluluk-melih-coskun-tyke9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Baharını kendin getireceksin 

Tırnaklarınla kazımaya gerek kalmadan güneşi

Dağları aşmaya gerek yok mutluluk için

Mutluluk sana o kadar yakın ki

Uzandığında tutabileceksin onu

Mutluluk yaprağıdır bir ağacın

Bir bebeğin gülücüğüdür kaygısızca

Birbiriyle kenetlenmiş iki eldir.

Mazlumun inancıdır mutluluk, geleceğe dair

Sıcak bir aş adına, ekmek adına, 

Bir türküdür mutluluk

Acı yüreklerde söylenen.

Bir hastanın iyileşme umududur mutluluk

Mutluluk iki çekingen dudak arasından sızan

Birkaç kelimedir.

Sevmektir insanları 

Hiçbir çıkar gözetmeksizin...

5 Haziran 2002

21: 56', 'Baharını kendin getireceksin  Tırnaklarınla kazımaya gerek kalmadan güneşi Dağları aşmaya gerek yok mutluluk için Mutluluk sana o kadar yakı...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/mutluluk-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşanana ve Yaşanmayana Dair', 'yasanana-ve-yasanmayana-dair-melih-coskun-6ioqr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşıyoruz, içimizde geçmiş günlerin hüznü

Yaşanmamış günlerin sıkıntısı

Geçmiş günlerin pişmanlığı

Yaşanmamış günlerin umudu,

29 Nisan 2002

22: 22', 'Yaşıyoruz, içimizde geçmiş günlerin hüznü Yaşanmamış günlerin sıkıntısı Geçmiş günlerin pişmanlığı Yaşanmamış günlerin umudu, 29 Nisan 2002 ...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yasanana-ve-yasanmayana-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair Armağanı', 'sair-armagani-tahir-yuksel-wb9cs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'takvimle kumar oynayarak yeniden başlıyorum şiire

böğürtlenlerin -ki kimse sevmez zahir- raksıdır yeşil çuhalarda

uluyan kar fırtınalarını iç ceplerime yerleştirdim

rüzgâr kadar aç değilim artık toprağa ve suya ve ateşe

ellerim demir potasında mumyalandı

çiçekleri anıt yaptım hergün yeşeren sevgilerin adına

ellerim aç değildir umutsuz rüyâlara

-gece yarılarında bir sürü uyur gezer-

kentin sokaklarında

ama elleri sade et ve kemikten bir de kan

rüyâları sevecenlik dolu görkemli rüyâları

bulutların cengine kahkaha atıyorlar

-ısırgan otlarıyla koyun koyuna-

ve göğermiş söğütten düdük kavlatıyorlar

çiçek topluyorlar allı-morlu sevgilileri için

kan ve et elleriyle de

benim ellerim sıcakta daha sıcak soğukta daha soğuk

ne çiçek toplar cânan için ne selâm verir eşe dosta

ve kalem ancak benim ellerimde

teker teker karalar takvim yapraklarını çakırkeyf olana dek

çakırkeyf deyince aklıma hep çakırdikeni gelir

toprak sevdâsına çamura bulaştığım hayâl

cennet zamanında en güzel rüyâların

alevden zıpkınların delik deşik ettiğinde yüreciğimi

umutlarım daha kırılmamış yumurtada kalmıştır

takvim ellerimde tutsaktır

kemiredursun saatin dişlileri vehimle yüklü ânı

dumanlı anılarla süslü saniyeler

ağsın kurşun yoğunluğunca ve tüy hafifliğinde

yıldızları katrana bulanmış lacivert göklerden

güneşi bir başka metodla

hele şükür deyip ufalayarak

dilencilere dağıttığım taş sokaklarda

şiirin imbiğini paramparça edip

yetim yavruları ısıttığım buzlarla

sanat adına işlediğim cinayeti

altın bilezik gibi koluma takıp

ve fırtınalara karşı mum şavkınca da olsa dün

bugün haykırdığım boğazım yırtılırcasına

ve patlattığım atom bombalarına eş yaralı gönülleri

salonların lüksünden kurtarıp

iğrenç bir çöp gibi atılmış sokaktaki insanlara

umut götürerek

hediye ediyorum beni ezip geçen -bende tutsak-

ipince ve upuzun zamanı', 'takvimle kumar oynayarak yeniden başlıyorum şiire böğürtlenlerin -ki kimse sevmez zahir- raksıdır yeşil çuhalarda uluyan kar fırtınalarını i...', ARRAY['Türk Edebiyatı','Şiir','Tahir Yüksel']::text[], 8.5, '{"poet":"Tahir Yüksel","poet_slug":"tahir-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/sair-armagani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arz-ı Hâl', 'arz-i-h-l-tahir-yuksel-41vgz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bizdeki bu gidişe

söz etsem değer dişe

hesap gelmezse işe

kitap tersten okunur

hacet yok cim''e lâm''a

her yanı binbir yama

söylenecek çok ama

zülf-ü yâre dokunur', 'bizdeki bu gidişe söz etsem değer dişe hesap gelmezse işe kitap tersten okunur hacet yok cim''e lâm''a her yanı binbir yama söylenecek çok ama...', ARRAY['Türk Edebiyatı','Şiir','Tahir Yüksel']::text[], 8.5, '{"poet":"Tahir Yüksel","poet_slug":"tahir-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/arz-i-hal-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliğin Ortasında', 'sensizligin-ortasinda-soner-demirez-uggrc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sensizliğin ortasında, yine seninleyim, 

Bitmeyen bir hasret kavurmakta tenimi, 

Ben sana hasretim peki ya sen? 

Sen neler yapmaktasın benden uzaklarda? 

Gelirmiyim aklına ara sıra olsa da? 

Dudakların özler mi dudaklarımı? 

Öpüştüğümüz yerler ağlamakta şimdi, 

Yüreğime yaren olmakta...

Bir yunusum, aşkınla okyanuslar dolaşan, 

Ferhat''ım yüce dağları delen, 

Mecnun''um çölde serabın gören, 

Ben böyleyim, sana hasretim bitanem...

Beni anlamazsın anlayamzsın canım canözüm...

Aşılmaz diyarları aştım geldim sana, 

Her gece saçlarını okşamak için odana, 

Yıldızlar kadar uzak, yüreğin kadar yakındım...

Hiç hissettin mi varlığımı yanında_? 

Geceler boyu saçlarını okşayan ellerimi hissettinmi_? 

Sen uyurken ben baş ucunda beklerim geceleri...

Sen rahat uyu bebeğim ben seni kollarım...

Alnına bir öpücük ondururum usulca...

Sabaha kadar seyrederim masum güzelliğini, 

Hasretinle yanan düşüncelerimi, yüreğimi avuturum...

Yokluğunda da varsın dünyamda her an...

Sen rahat uyu bebeğim...

Gecenin kör karanlığında ben varım yanında, 

Baş ucunda duruyorum yavrum...

Can siperane bekliyorum seni...

Saçının ipeksi dokunuşu parmaklarımda, 

Mis kokusu geliyor burnuma, 

Gözlerinden öpüyorum...

Sen rahat uyu gözbebeğim....', 'Sensizliğin ortasında, yine seninleyim,  Bitmeyen bir hasret kavurmakta tenimi,  Ben sana hasretim peki ya sen?  Sen neler yapmaktasın bende...', ARRAY['Türk Edebiyatı','Şiir','Soner Demirez']::text[], 8.5, '{"poet":"Soner Demirez","poet_slug":"soner-demirez","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sensizligin-ortasinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Aydınlık Ben Gece', 'ay-aydinlik-ben-gece-soner-demirez-gypqn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben gecenin içinde geceyim, 

Sen gökteki ay''ımsın  dünyamı aydınlatan..

Her gece evimin terasından gördüğüm, 

Görmeye doyamadım gülyüzün gökteki...

Binlerce yıldız arasından bakıyorsun bana, 

Ve gülüyorsun umarsızca...

Yüreğime esen ılık meltem oluyorsun gecelerce, 

Bense bir damla nur''una hasret gece...

Bak yaz yağmuru yağmakta yine üzerime, 

Çisil çisil yağıyorsun ay yüzlüm, 

Çisil çisil dökülüyor nur''lu ışığın...

Bedenim karalarından kurtuluyor sayende...

Bu nasıl özlem canım canözüm_? 

Elalem güne hasret, ben sana...

Gün geceye kavuşsun artık boğuluyorum, 

Sen doğ tekrar ve bana gülümse çok uzaklardan...

Ellerim sana uzansın tekrar, 

Uzanayım sana kavuşabilmek için, 

Ellerimle değil, bedenimle değil, 

Yüreğimle kavuşayım sana....

Gökyüzünün enginlerinde bir sen bir ben....

Uzanıp öpeyim seni, dudaklarım serinlesin...

Ve seni sarayım bedenimde, 

İnan bebeğim az kaldı, inan çok azz...', 'Ben gecenin içinde geceyim,  Sen gökteki ay''ımsın  dünyamı aydınlatan.. Her gece evimin terasından gördüğüm,  Görmeye doyamadım gülyüzün gök...', ARRAY['Türk Edebiyatı','Şiir','Soner Demirez']::text[], 8.5, '{"poet":"Soner Demirez","poet_slug":"soner-demirez","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ay-aydinlik-ben-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmedin Beee', 'gelmedin-beee-soner-demirez-1bwlc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne çok özledim seni bilemezsin bitanem, 

Sözleşmiştik seninle hani gelecektin_? 

Beni yanlızlığma bıraktın yine bu gecede, 

Bir ben birde ben yanlızlığım bebeğim...

İçimde bir sıkıntı var birde özlem, 

En güzel yerimde ise sevdan, 

Geleceğini beklerken yazdım sana şiirimi, 

Ama sen hala gelmedin, gelmedin be gülüm...

Seni bekledim gülüm...

Bak hala bekliyorum gözüm yollarda, 

Sana susamışım sana hasretim be gülüm, 

Gel gelde kurtar beni yanlızlığımdan, 

Gözlerim dalmış karanlık geceye, 

Seni aramakta gözlerim satırlarda, mısralarda, 

Bekliyorum ve bekleyeceğim canım, 

Son nefesimi verene dek bekleyeceğim.

Mıh gibi çakılı kaldım olduğum yere, 

Ayrılmayacağım burdan, 

Belkide anıt mezar olurum ne dersin..

Aşkının yarattığı koca bir divane oldum

Pişmanda değilim aşkım, 

Olmayacağımda bebeğim.

Sen beklettikçe bekleyeceğim bitanem..

Az mı koştum peşinden, , 

Demek şimdide sıra bekleme sırası, 

Olsun ben beklerim gülüm.

Kendi kendime konuşmaktayım şimdi, 

Sen hala gelmedin, gelmedin be gülüm, 

Gelmeyeceksinde biliyorum....', 'Ne çok özledim seni bilemezsin bitanem,  Sözleşmiştik seninle hani gelecektin_?  Beni yanlızlığma bıraktın yine bu gecede,  Bir ben birde be...', ARRAY['Türk Edebiyatı','Şiir','Soner Demirez']::text[], 8.5, '{"poet":"Soner Demirez","poet_slug":"soner-demirez","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gelmedin-beee-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklı Olan Sever mi ?', 'akli-olan-sever-mi-soner-demirez-m2gqh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1)  sevdim

Canımdan öte can saydım seni, 

Varlığın bir başka güzel yokluğun ölümdü...

Yüreğimin çarpıntısı sanaydı bebeğim..

Baharda ektiğim güller bile filiz verdi..

Sevgin açmadı tomurcuklarını...

Yüreğimdeki baharlarıda alıp gidiyorsun şimdi...

Seni öyle sevdimki bahar toprağının suya hasretiyle, 

Bülbülün güle aşkıyla sevdim seni...

Keremin tutkusu mecunun aşkıyla çölde kum oldum.

Uykusuz gecelerde gördüm seni, 

Saçlarını okşadım geceler boyu, 

İçimdeki sevdan kusursuz bir aşktı...

Ama sevdam seni şımarttı...

İşte işte bitanem sudan çıkmış balığım, 

Balığın suya aşkıyla sevdim seni..

Senin için vazgeçtim bu canımdan...

Hiçe saydım yaradın verdiğini...

Sen bilmedin bilmeyeceksin sevgimi

     2)  neydim ben

Neydim ben gözünde oyuncakmı_? 

Beni okadar çok kullandın ki; 

Benden bıkmış olmana şaşırmam yanlış...

    3)  gidiyorsun

Bu sefer kal demeyeceğim..

Git gidebildiğince uzağa, 

Kaçır kendini benden ve yaklaşmayı deneme..

Sana lanet bile okuyamayacak kadar çok sevdim...

Bilmedin kadrimi kıymeti sen...

Bir gelip başını taşlara vuracak ağlayacaksın...

Nasıl bir sevgiyi nasıl bir yüreği hiçe saydım diyerek...

Sahte değil gerçek gözyaşlarına boğulacaksın...

Dostların arkadaşları  yetmeyecek göz yaşlarını silmeye...

Ben severek ayrılıyorum senden nefretle değil...

Gün gelecek anlayacaksın kaybettiğini...

Ama nafile vakit çok geç olacak...

İşte o zaman başını duvarlara vurma boşa...

Giden geri gelirmi sanıyorsun_? 

Gelmeyecek  bitanem gelmeyecek...

Bir gün ansızın çıkacağım karşına...

Gözlerin dolacak tutamayacaksın akan yaşları...

Başın öne eğilecek çünkü suçlu olan sensin..

Yüzünü çevirecek bakamayacaksın yüzüme....

Kimbilir belki evlenmiş olacaksın...

Yanında çocukların olacak belkide...

Hani o hayalini kurduğumuz çocuklar ama babaları başka....

Yinede severim onları senden bir parça oldukları için...

Ama giden geri gelmez...

İçinde hep duyarsın bu pişmanlığı...

Düştüğün karanlıktan çıkmazsın.....', '1)  sevdim Canımdan öte can saydım seni,  Varlığın bir başka güzel yokluğun ölümdü... Yüreğimin çarpıntısı sanaydı bebeğim.. Baharda ektiğim...', ARRAY['Türk Edebiyatı','Şiir','Soner Demirez']::text[], 8.5, '{"poet":"Soner Demirez","poet_slug":"soner-demirez","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/akli-olan-sever-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Eylül', 'yine-eylul-melih-coskun-vgnxb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'I

Yine gece oldu 

Girdik eylülün en karanlık yerine

Beynimde postal sesleri

Yüreğimin üzerinden tanklar geçiyor

Kuşatıyorlar ağaçları ordular

Sarartıyorlar yaprakları

Yeter artık sonbahar geldi diyorlar

Bir komutan erteliyor bütün sevdaları 

İkinci bir emre kadar 

Bir çocuk bakıyor pencereden 

Korkulu, tedirgin, 

II

O çocuk büyüdü bugün

O çocuk büyüdü ve bakıyor yine pencereden

Yine  korkulu, tedirgin

O çocuk bakabilecek mi pencereden 

Umutlu, sevinçli

III

Eylül koy bugün doğan bütün çocuklarının adını

Eylül’ ün kederini taşısınlar yüreklerinde...

Ve büyümeli o çocuklar

Kurmalılar tanksız, postalsız, silahsız bir dünyayı...

12 Eylül 2002

 23: 31', 'I Yine gece oldu  Girdik eylülün en karanlık yerine Beynimde postal sesleri Yüreğimin üzerinden tanklar geçiyor Kuşatıyorlar ağaçları ordula...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yine-eylul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Sıcaklarda Hüzünlenmek', 'bu-sicaklarda-huzunlenmek-melih-coskun-aq7dc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu sıcaklarda

Hüzünlenmek bile zor be güzelim

Yemek, içmek, düşünmek

Yaşamak yalnızlığı zor be güzelim

İsyan kokar bu havalar

Eriyen kaldırımlarında şehrimin

Başkaldırırken gökyüzüne

Düşünmek özgürlüğü

Viva Liberta diye haykırmak gibi, 

Bahar rüzgarlarıyla savrulan yurdumun dağlarında

Şunu anlamadık ki güzelim

Hayat saymak değil bitmez tükenmez şafakları

Hayat bugün yaşamak hürriyeti doyasıya

Düşünmek dağları denizleri

Savurmak kendini sevdanın rüzgarına

Hayat bugün sevmek insanları karşılıksız

Hayat bugün düşünmek yaşanmamış en güzel günlerimizi...

18 Temmuz 2002

23: 02', 'Bu sıcaklarda Hüzünlenmek bile zor be güzelim Yemek, içmek, düşünmek Yaşamak yalnızlığı zor be güzelim İsyan kokar bu havalar Eriyen kaldırı...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bu-sicaklarda-huzunlenmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Unut', 'sen-unut-soner-demirez-a8rst', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zaten becermişsin sen *****

Zaten çıkarıp atmışsın beni yüreğinden

Yaşadıklarımızı hiçe saymışsın..

Şimdi neden bu sevkat

Bitirdiysen bitir ve git dönüp arkana bile bakmadan

Ben neymişim ne olmuşum sanane

Sen git mutluluğunu yaşa 

Ben artık istemiyorum mutluluğu

İstemiyorum....

Br kere and içmişim sevdama

İhanet bekleme benden sevdama

İhanet edemem bunca yaşananlara

Sevmek oyun değil gülüm 

Bir gün varolup bir gün bitemez

Bende sevgin asla bitmeyecek 

Güllerim solsada  yol kenarına atılsada

Asla bitmeyecek bir sevgi büyüttüm yüreğimde 

Suladım besledim büyüttüm

Şimdi bana kaldır çöpe at diyorsun herşeyi

Atmayacağım ***** atmayacağım

Masal dünyasındaydım seninle

Hem öyle bir masal ki; 

Sevdiğimi sevildiğimi görüyordum bu masalda

Uyanmak istemiyorum bu rüyadan

Uyanmayacağım bırakın beni

Karşılık bulmasamda seveceğim

Delikanlıca erkekçe seveceğim yinede

Yok öylepilavdan dönmek 

Söz verdinmi söz olacak bu

Yalamayacaksın tükürdüklerini

Hayatta hiç bir şeye boyun eğmedim ben

Ama şimdi sevdama boyuneğiyorum

Aylarca sana boyun eğdim 

Yoluna halı oldum kilim oldum ilmek ilmek

Yandım yolunda yanmayada razıyım

Var olanları inkar etmek yakışmaz insana beeeee

Yakışmaz gülüm bunu böyle bilesin

İçimde mıh gibi kazılı sevdan

Değil başkalrı sen bile sökemezsin

Ben burdayım yaşıyorum

Dimdik değilse bile ayaktayım gülüm

Yaşamaksa bu yaşıyorum elbet 

Evsiz barksız çocuksuz sevgisiz ve mutsuz

Yaşamın bana reva gördükleriyle

Derbederliğimle yaşıyorum artık

Sen mutluluğu yakaladınya hadiş hayırlı olsun

Ben, sevindim senin adına

Kurtuldun benden

Sonunda başından atabildin beni

Şimdi seni mutluluk bekliyor

Git mutluluğun kollarında yaşa 

Arkana bile bakma

Seni mutluluğundan döndürmeme izin verme

Evet git ardında bıraktığın viraneye aldırma

Köhne bir yapı kaldı senden bana

Anatomi denilen bir köhne yapı

Şimdi ben o köhneyi taşıyorum bedenimde

Köhne bir beden köhne bir insan

Allah yolunu açık etsin

Bende yakalayamadığın mutluluğu yakala

Güldüremediğim yüzün gülsün

Gecelerin kasvet değil neşeyle dolsun

Ben verememişim bunları sana 

Olurya benden çok sevenini bulursun', 'Zaten becermişsin sen ***** Zaten çıkarıp atmışsın beni yüreğinden Yaşadıklarımızı hiçe saymışsın.. Şimdi neden bu sevkat Bitirdiysen bitir ...', ARRAY['Türk Edebiyatı','Şiir','Soner Demirez']::text[], 8.5, '{"poet":"Soner Demirez","poet_slug":"soner-demirez","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/sen-unut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Uzak', 'senden-uzak-soner-demirez-84nx1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senden uzaklarda yapayanlızım, 

Ne bir tutanacak dalım nede ümidim kalmış...

Özlemin dağlıyor yüreğimi, ben sevgine aç...

Bir kuş bir kelebek gibi yapa yanlız uçuyorum semada.

Yıllar boyu seveceğim seni, aşkıma ihanet etmeden...

Şimdi sen düşünmektesin acaba seviyormuyum diye...

Belkide sevmiyorsun...

Canın sağ olsun ciğerparem, aşk karşılık beklemezki, 

Seven yürek karşılık beklemezki; 

Sever  ölürcesine, taparcasına sever, 

Kavuşma ümidi hiç olmasada sever gülünü...

Suya hasret toprak gibi hasret yüreğim sevgine, 

Ulaşılmaz yıldızlar gibi uzaksın bana içimdeyken bile...

Oysa varlığın ısıtırdı yüreğimi, 

Ben ben olurdum...

Hayata direnen, hayaller kuran geleceğimize dair, 

Planlar yapardım mutluluğumuza dair, 

Şimdi şu halime bak sersefil kalakalmışım bir başıma, 

Ne bir ümidim kalmış, ne bir bekklentim dünyadan...

Sevgi denen illete lanetler okuyor olmuşum...

Oysa seni hala çok seviyorum...

Ellerim titriyor sensizliğimde, 

Gözlerim kararıyor, bişey göremiyorum senden başka, 

Elimden düşmeyen resimlerin mektupların var şimdi, 

Avutamıyorlar beni...

Her okuyuşumda gözümden binlerce damla birden boşalıyor, 

Perişanlık dedikleri bu olsa gerek...

Bir farkım vardı seninleyken, 

Seviyor seviliyordum gözbebeğim...

Beni hayata bağlamıştı sevgin...

Yılların verdiği acıları kahırları unutmuştum seninle..

Sana inanıp sana güvenmiştim yavrum...

Şimdi sende çekilmek istiyorsun hayatımdan..

Sende bir darbe daha vuracaksın bana...

Vur be gülüm vur elbet bununlada yaşarım..

Az acılar çekmedi bu yürek...

Ahdım kaldı yeminim kaldı bana yadigar...

Aşkımıza sevgimize verdiğim sözler yeminler..

Dönemem verdiğim sözlerden geriye...

Dönemem dönemem be canım dönemem...

Sabaha varmayan geceler yaşıyorum...

Gören binlerce düşüncem var sanıyor...

Yok beeee bir tek düşüncem var, birtek sevdiğim olduğu gibi, 

Tek düşüncem tek sevdiğimsin bitanem...

Sen beni sevmesende ben seni hala çok seviyorum, 

Nedir beni senden uzaklaştıran? 

Sendeki sevgimi yok eden nedir? 

Yokmu bir çaresi gözbebeğim yok mu? 

Bulamazmıyız bir ortak yön? 

Arayalım bulalım bitanem...

Bir gece vakti ansızın gel öp dudaklarımı..

Yeniden seni seviyorum de...

Sar beni sımsıkı özledim özledim seni bitanem...

Candan gülüşünü seviyorum deyişini özledim.

Bir gün apansız gel yeniden...

Bir daha gitmemek üzere  gel...

Ne kendinmi nede beni üzme bitanem...

Kötü anları silelim anılardan.

Güzel günlere yelken açalım...

Seviyorum diyerek gel bana, 

Bitmeyecek bir sevgiyle gel..

Tut ellerimden çıkar düştüğüm karanlıktan...

Zifir karanlık günlerime güneşi getir....', 'Senden uzaklarda yapayanlızım,  Ne bir tutanacak dalım nede ümidim kalmış... Özlemin dağlıyor yüreğimi, ben sevgine aç... Bir kuş bir kelebe...', ARRAY['Türk Edebiyatı','Şiir','Soner Demirez']::text[], 8.5, '{"poet":"Soner Demirez","poet_slug":"soner-demirez","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/senden-uzak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çabuk Gel Çocuk', 'cabuk-gel-cocuk-melih-coskun-lwgwb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çabuk gel çocuk

Gel ki aydınlansın karanlık gecelerim

Gel ki ışısın gözlerim

Sol yumruğunun namusu için gel

İki damla gözyaşı için gel

Düşüşün bir depremdir senin çocuk

Yıkarsın bütün dünyayı

Yeniden kurarsın aydınlık yarını

Gel ki doğsun yine güneş

Ay yine aydınlatsın gecemi

Gel ki bitsin bu hasret

Gülmeyi unutan çocukların gülsün 

Karlar kalksın dağlarından 

Sen giderken bir ayazdı

Gel ki ısınsın yüreğim

Emeğimin namusu için gel

Sol yumruğumun namusu için gel...

18 Eylül 2002

21: 49', 'Çabuk gel çocuk Gel ki aydınlansın karanlık gecelerim Gel ki ışısın gözlerim Sol yumruğunun namusu için gel İki damla gözyaşı için gel Düşüş...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/cabuk-gel-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin', 'gittin-soner-demirez-jy02r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ardına bir ben biçare yapayanlız....

Bir virane bırakıp çektin ve gittin...

Yazdığın son satırları okudum defalarca..

Her harfinde binlerce kez ağladım...

Şimdi gidiyorum *****...

Gidiyorum bilinmeze doğru...

Senin kabul etmediğin yüreği taşımak zor gelir...

Dayanamam buna...

Beni arama sorma....

Ben artık senin için yokum.

Evet gerçekler acıdır *****...

Bunca çektiğim yeter

Taşımaz bunda fazlasını bu beden.

Mutluluklar senin olsun yavrum....

Benim mutluluğum sende kaldı bitanem.

Sende kaldı, sende kaldı, sende, sende...', 'Ardına bir ben biçare yapayanlız.... Bir virane bırakıp çektin ve gittin... Yazdığın son satırları okudum defalarca.. Her harfinde binlerce ...', ARRAY['Türk Edebiyatı','Şiir','Soner Demirez']::text[], 8.5, '{"poet":"Soner Demirez","poet_slug":"soner-demirez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gittin-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Gidiş Bir Ölümdür', 'her-gidis-bir-olumdur-melih-coskun-a3sxn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her gidiş bir ölümdür

Bir film karesinde bir çocuk ağlar

Hiç kimseler görmeden

Küçük bir andır zamanın sonsuzluğunda

Ancak ömürdür bir yürekte

Her gidiş buğulu bir otobüs camı

Camın arkasında anlaşılmayan

Çılgınca merak edilen son cümleler

Bir bakışa sığdırılışı 

Bir ömre sığdırılamayacak kadar çok kelimenin

Yitirilen çocukluk hayalleri gibidir şimdi

Her giden otobüs, 

Her gidiş bir ölümdür

Ve buğulu bir otobüs camında 

Gizlice ağlayan bir çocuktur hasret...', 'Her gidiş bir ölümdür Bir film karesinde bir çocuk ağlar Hiç kimseler görmeden Küçük bir andır zamanın sonsuzluğunda Ancak ömürdür bir yürek...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/her-gidis-bir-olumdur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Kadin Var Ne Gozyasi', 'ne-kadin-var-ne-gozyasi-huseyin-poyraz-ox37s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Garip gonlum susma soyle

Kimdi bizi uzen boyle! 

Aramizda bundan boyle

Ne kadin var ne gozyasi...

Her nefeste ozlenecek

Ardi sira gozlenecek

Nisanlanip sozlenecek

ne kadin var ne gozyasi...

Bir bir dustuler gozumdan

Caymam artik ben sozumden

Billur olsa gozu kasi

Ne kadin var ne gozyasi...', 'Garip gonlum susma soyle Kimdi bizi uzen boyle!  Aramizda bundan boyle Ne kadin var ne gozyasi... Her nefeste ozlenecek Ardi sira gozlenecek...', ARRAY['Türk Edebiyatı','Şiir','Huseyin Poyraz']::text[], 8.5, '{"poet":"Huseyin Poyraz","poet_slug":"huseyin-poyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ne-kadin-var-ne-gozyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Batarken', 'gun-batarken-soner-demirez-xzcom', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir çizik daha attim kalbime...

Senden uzak geçen hergün yaptigim gibi, 

Kavusacagimiz güne safak sayiyorum...

Gün bitmeden ben bitiyorum hergün, Gün Batarken

Içimde firtinalar kopuyor, özlemin büyüyor içimde, 

Tusunamiler kapliyor yüregimi...

Karadenizin hoyrat dalgalarini tasiyorum içimde.

Gün batarken sahile vuran dalgalarda ariyorum seni...

Yoklugunda denizler çiziyorum kendime...

Siirler yaziyorum kendimce sana dair

Ama yoklugunun yerini doldurmuyor hiçbiri...

Gün batiminda kollarim sarsin istiyorum tenini...

Suskun kalmis dillerim konusamam lal olurum, 

Yüregim yüce daglar misali kabarir...

Gözlerindeki tebessüme isiga hasret kalirim, 

Isyan ederim senden uzak gün batiminda...

Ne güzel günler yasadik bebegim...

Simdi onlar beynimin en güzel yerindeler..

Resmini çiziyorum senden uzaklarda tüm hatlarinla...

Yutkunamiyorum senden uzak olmuyor gün batiminda...

Gözlerim dalar uludaga, seni görürüm orda, 

Sonra çikar dolasirim yollarda her yanda sen, 

Bankta oturan pencereden bakan hep sen...

Uzanip tutmak isterim ellerini gün batiminda...

Karanliklara ilk adim gün batimlari...

Oysa gözlerin gelir gözlerimin önüne sonra, 

Öpücügün konar dudaklarima atesleriz geceyi..

Ah ah kör olasi gün batimi özlemimi deprestirir...', 'Bir çizik daha attim kalbime... Senden uzak geçen hergün yaptigim gibi,  Kavusacagimiz güne safak sayiyorum... Gün bitmeden ben bitiyorum he...', ARRAY['Türk Edebiyatı','Şiir','Soner Demirez']::text[], 8.5, '{"poet":"Soner Demirez","poet_slug":"soner-demirez","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gun-batarken-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mum Yaktim Geceye', 'mum-yaktim-geceye-soner-demirez-014ia', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir mum yaktim geceye ikimize dair...

Elma kokulu yeşil mum''da buldum seni, 

O kadar yakindin ki bana, bir o kadar uzak, 

Uzattim ellerimi sana ellerim yandi sicakliginda..

Özledim seni bebegim, canimdan çok candan öte, 

Canim hasretinle bi çareyim, dudagimda hala izin...

Yanan tenim kül olmakta hasretinle...

Ben yogrulmaktayim mum isiginda...

Ey gözleri kahve yüregi altin güzel, 

Sen misin beni dertlere salan derbeder eden_? 

Varligin vardi daha düne kadar yanimda, 

Oysa simdi yoklugunda varsin ebediyen...

Son bulmayacak bir ask bu, sonu olmayacak bir sevgi, 

Bir hayalle basladi sevdamiz tohumken gonca oldu, 

Goncadan güle döndü dikenleri batti ellerimize....

Biz var olduk sevgimizde oda batti be gülüm...

Gittigin gün gezdigimiz yerlerde dolastim...

Hatirladin bakirköy sahilini dalgalar hoyrat, 

Seni sordular cevap bile veremedim onlara.

Kiyisinda oturup saçlarini oksardim....

Bak yenimahallede kayalarin üstündeyim, 

Neler neler konusmustuk hatirlarmisin_? 

Tabanlarimiza kara sular inmisti yürümekten

Seni özledim be gülüm seni özledim...', 'Bir mum yaktim geceye ikimize dair... Elma kokulu yeşil mum''da buldum seni,  O kadar yakindin ki bana, bir o kadar uzak,  Uzattim ellerimi s...', ARRAY['Türk Edebiyatı','Şiir','Soner Demirez']::text[], 8.5, '{"poet":"Soner Demirez","poet_slug":"soner-demirez","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/mum-yaktim-geceye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kentin Öyküsü', 'bir-kentin-oykusu-tahir-yuksel-5zotu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1-mumyalanmış bir kente ilk ziyaret

bir seher vakti geldim bu beton kente

kara bulutların ağdığı sokaklar bomboştu

gökyüzü anlamını kaybetmişti birkaç asır önceden

bütün yıldızlar sis olmuştu birer birer insanların zihninde

güneş de

çok uzaklara gitmişti bir garip büyülenerek

ve bu kent

ve öbür kentler

ve tüm ülke ölümlere eş bir sükûta boğulmuştu

insanlar karanlıkta doğmuştu da herkes gülmüştü 

                                                            ağız dolusunca yıllar yılı

günler bambaşka geçiyordu  bu beton kentte

düğmeye basınca akşam oluyor

düğmeye basınca gene akşam oluyordu sabah niyetine

bütün hareketleri trafik lambalarına bağlıydı insanların

kalpleri ise ithal malıydı made in bilmem ne marka

ve herkes mutluydu

öyle yazıyordu gazeteler çarşaf çarşaf

kadınlar vardı bu beton kentte

çinko klişelere yapışmış her biri bin mühür

durmadan basılıyorlardı afişlere şan için

dağılıyorlardı tüm ülkede insanlık yararına

bir kadeh içki fiyatına

elden ele dolaşıyorlardı sıkılmış limonlar

pörsümüş çiçekler gibi çöp sepetlerinde

çocukları boşuna aradım uzun süre bu beton kentte

belki mumyalarını çözerim diye

büyülerini bozarım diye

kaldırımlar eridi ılgıt ılgıt ayaklarımın altında

çağın enerjisi tükendi ama çocuklar yoktu ortalıkta

topuğunu çöle vurup su fışkırtacak

şeytanın gözünü tek taşla çıkartacak

ve gittiği yere nur götürecek sütun sütun

milat vardı her yudum suda ve her nefeste 

ciğerlere dolan zehir gibi

insanları büyüleyen cadı kazanı

milat milat milat

ve beni de eritmek için doku doku kezzap kuyusu kan denizi

şarkılar vardı

mutluluk şarkıları azap gibi

kulaklar sağır olmuştu taştan da beter

gözlere perde inmişti duman duman afyoncasına

sokaklar kalleş havası

evler ise leş yuvasıydı beton çağın beton kentinde', '1-mumyalanmış bir kente ilk ziyaret bir seher vakti geldim bu beton kente kara bulutların ağdığı sokaklar bomboştu gökyüzü anlamını kaybetmi...', ARRAY['Türk Edebiyatı','Şiir','Tahir Yüksel']::text[], 8.5, '{"poet":"Tahir Yüksel","poet_slug":"tahir-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/bir-kentin-oykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayattan Öğrendiklerim Var', 'hayattan-ogrendiklerim-var-soner-demirez-w8q5t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayattan öğrendiklerim var ey dostlar...

Yıllarca yaşadım, bence sanki asırlar! ! 

Kitaplardan okumadım hayatı yaşadım...

Yaşayarak öğrendim kitaplarda yazılmayanları...

Dost bildiklerinin arkandan dolaplar çevireceğini...

Değer verdiklerinin sana değer vermeyeceğini...

Bildiklerinin bir işe yaramadığını gördüm...

Sen severken ihanetleri yaşayacağını gördüm...

Şimdilerde biliyorum artık hak edene vereceksin değeri, 

Yeni tanıdığına değer vermeyeceksin asla...

Çıkarmayacaksın tepene...

O sana ne kadar değer verirse, sende ona vereceksin, 

Ne bir eksik ne bir fazla...

Dost bilip güvenmeyeceksin kimseye...

Güvendiğin dalları elinde kalmış görmek istemiyorsan...

Güvenmeyeceksin arkadaş, 

Buna layık olanın olmadığınıda gördüm...

Gördümde yüreğim cız etti derinlerden...

Hayattan öğrendiğim şeyler var, 

Evet hayattan öğrendiğim şeyler varda....

Öğrendiklerimi uygulama özürlüyüm ben...

Bazen içimden desemde yapamam, 

Uygulayamam hayattan öğrendiklerimi...

Kendime insanlığıma yediremem bunları...

Bende biliyorum kısasa kısasla yaklaşmayı...

Biliyorum da bildiklerim beş para etmiyor...

Uygulayamıyorum bildiklerimi...

Aşamıyorum insanlığımı eziliyorum hayatta..', 'Hayattan öğrendiklerim var ey dostlar... Yıllarca yaşadım, bence sanki asırlar! !  Kitaplardan okumadım hayatı yaşadım... Yaşayarak öğrendim...', ARRAY['Türk Edebiyatı','Şiir','Soner Demirez']::text[], 8.5, '{"poet":"Soner Demirez","poet_slug":"soner-demirez","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/hayattan-ogrendiklerim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günlerdir Haber Yok', 'gunlerdir-haber-yok-soner-demirez-s6ljv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nerelerdesin ey sevgili...

Özlemin yüreğimi dağlar bilmezmisin...

Bir sesin vardı beni avutan şimdi o da kalmadı..

Günlerdir haber yok senden...

Bu nasıl bir kabus, biz neresindeyiz _? 

Çözülmez denklemlerin eşiğinde bir hayat..

Ve biz de bu hayatın tam göbeğindeyiz....

Meraktayım günlerdir haber yok senden...

Özlem bulutları yağmurlarını döküyor yüreğime...

Her dem içimde büyütüyorum aşkı sevdayı...

Gülen yıldız gözlerin gözlerimin önünde...

Günlerdir haber alamadım senden...

Ahhh bitanem bilemesin ne hallerdeyim...

Anlayamazsın bendeki seni bilemezsin..

Suskun dilimin ardındaki yüreği bilemezsin..

Günlerdir haber yok senden özlemindeyim...

Şimdi şiir yazıyorum şiirde kendimi içimdekileri..

Oysa yazmadığım daha neler var bebeğim bilemezsin...

Yangın yeri yüreğim, sana muhtacım bilemezsin...

Günlerdir yanıyorum hasretinle senden haber yok...

Sana açtığım telefonlara çıkmıyorsun..

Bir haber yollamıyorsun bana...

Bilmiyorum ne haldesin...

Aklımda soru işaretleri var senden haber yok günlerdir...

İlkbaharda ektiğim gül hala gonca veriyor...

Oysa ben hazanı yaşıyorum yaprak dökümündeyim..

Geceler üstüme çöküyor karabasan misali..

Günlerim geceden farksız senden haber yok günlerdir..

Ne çalışmak iistiyorum nede bişey yapmak..

İçimden hiç bişey gelmiyor...

Nerdesin yaşama sevincim nerdesin yıldız gözlüm...

Günlerdir haber yok senden...', 'Nerelerdesin ey sevgili... Özlemin yüreğimi dağlar bilmezmisin... Bir sesin vardı beni avutan şimdi o da kalmadı.. Günlerdir haber yok sende...', ARRAY['Türk Edebiyatı','Şiir','Soner Demirez']::text[], 8.5, '{"poet":"Soner Demirez","poet_slug":"soner-demirez","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gunlerdir-haber-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kenti İkinci Ziyaret', 'kenti-i-kinci-ziyaret-tahir-yuksel-87kn9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gene bir seher vaktiydi bu beton kente gelişim ikinci kez

sokaklar sisli

toprak küskün

insanlar sarhoş değildi eskisi gibi

gökyüzü berraktı kevser''le yıkanmış gönüllere eş

ve ufuklarda mesaj vardı güneşe dair

betonlar çökmüştü uzza gibi

kadınlar

kadındı artık ziynet gibi korunan

ve çocuklar çocuktu artık umut bağlanan', 'gene bir seher vaktiydi bu beton kente gelişim ikinci kez sokaklar sisli toprak küskün insanlar sarhoş değildi eskisi gibi gökyüzü berraktı ...', ARRAY['Türk Edebiyatı','Şiir','Tahir Yüksel']::text[], 8.5, '{"poet":"Tahir Yüksel","poet_slug":"tahir-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kenti-ikinci-ziyaret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Be Sende', 'hadi-be-sende-soner-demirez-xu88x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seviyordun beni öylemi_? 

Şimdi sevgine bile inanamıyorum canım...

Evet beni gerçekten sevdiğini düşünüyordum, 

Yazıklar olsun bu beynime yüreğime nasılda aldandı...

Seni o kadar çok sevdim ki; 

Buna inanamazsın...

Zaten inanmakta istemiyorsun..

Kırdığım kalbini onarabildi mi bir başkası_? 

Ya senin kırdığın bu kalbi kim onaracak...

Bende başkasındamı arayayım mutluluğu huzuru...

Yooo ben bunu yapmayacağım....

İhanet etmeyeceğim sevgime...

Sen inanmasanda  seni senden çok sevdim bebeğim...

Ama sen bilemeyeceksin asla...

Sen sildin beni...

Şimdi üzülme, üzülmesi yas tutması gereken benim...

Tabiyaa ben güçlüydüm değil mi_? 

Evet bitanem ben güçlüyüm...

Hem öyle güçlüyüm ki ölümün kucağına atlaycak kadar...

Gidiyorum bitanem gidiyorum...

Yüreğindende gidiyorum dünyadanda..

Bilinmezlere açıldı artık sana açık kollarım..

Sen kollarını üçüncü şahsa aça dur ben bennnn.......

Yıkılmaz bir dağ sanırdım kendimi...

Ama yıkıldım perişan oldum derbeder oldum...

Çok acılara göğüs gerdi bu yürek...

Böyle acı yaşamadım hiç...

Bana reva gördüklerine  teşekkürler..

Ben bana verdiklerinle gidiyorum..

İçimde yalan sevginin gerçeğiyle..

Dilimde isminle gidiyorum..

Aslında söyleyeceğim o kadar çok şey varki; 

Kelimeler kifayesiz kalıyor anlatmaya...

Yutkunamıyorum birşey boğazıma çörekleniyor..

Nefesimi kesiyor bu his...

Beni seviyordun haaa :))

Hadi be sende....

Hadi ordan, insan böylemi sever_? 

Sevipte sevdiği kalbini kırdı diye, 

Başkasındamı arar mutluluğu huzuru saadeti...

Sevdin öylemi_? 

Evet beni sevdiğine inandım...

İnandımda lanet ediyorum yüreğime...', 'Seviyordun beni öylemi_?  Şimdi sevgine bile inanamıyorum canım... Evet beni gerçekten sevdiğini düşünüyordum,  Yazıklar olsun bu beynime yü...', ARRAY['Türk Edebiyatı','Şiir','Soner Demirez']::text[], 8.5, '{"poet":"Soner Demirez","poet_slug":"soner-demirez","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/hadi-be-sende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Adam', 'bir-adam-soner-demirez-6cfna', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uzak diyarlarda sürgün bir sevda 

Kaybolan gecelerde sessiz bir çığlık

Susmus dillerde sessiz bir hece

Bilinmeyen bir halde yanlız bir adam

Sahte bir dünya içinde papatyalar

Güllerin dikenleri batar eline

Bi çare kalır kör düğüm gecelerde

Ömrün her durağına  geç kalınmış adımlar

Ve duraklarda eli başında bekleyişler

Ahlarla vahlarla dolu bir hayat

Daha bebekken başlayan kahır

Ölümden sonra yeni diriliş

Çekilecek çilenin habercisi olaylar

Baskılarla büyüyen bir bebek

Hayatında gülmemiş bir yüz

Sevgiye hasret bir çocuk

Saygıya hasret bir genç

Varoluş savaşında ezilen delikanlı

Yargılanan idam  edilen gençlik

Çatık kaşların arkasındaki gerçek

Boğulan yıllar

Yılların ardından gelen mutluluk

Ve mutluluğa bir adım geç kalınmışlık

Tekrar başlayan umutsuzluk mutsuzluk

Yıkık dökün viran bir neden

Kendinde herşeyden geçmiş bir adam', 'Uzak diyarlarda sürgün bir sevda  Kaybolan gecelerde sessiz bir çığlık Susmus dillerde sessiz bir hece Bilinmeyen bir halde yanlız bir adam ...', ARRAY['Türk Edebiyatı','Şiir','Soner Demirez']::text[], 8.5, '{"poet":"Soner Demirez","poet_slug":"soner-demirez","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bir-adam-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Bir Resim', 'guzel-bir-resim-soner-demirez-7hx1x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yanlızım yine bu akşamda

Kalabalığın içinde bir başımayım...

Yalan yalan  yıldız gözlüm inanma buna..

Sen her an olduğu gibi benimlesin..

Yüreğimde dolaşan kanımsın...

Beynimde dolaşan düşünce...

Sen uzaklarda olsan da benden 

Bendesin benim içimdesin benden öte....

Elimde bir kaç resim kalmış eskiden kalan 

Birde yeni verdiğin resim...

Hani varya sen ve ben yan yana...

Bakıyorum, baktıkça ağlamak istiyorum.

Gözlerimden akan damlalar sel olsun..

Sel olup aksın yüreğine 

Yüreğinde hayat bulsun yeşersin sevdam.

Yüreğimde fırtınalar koparıyor resimler..

Bakıyorum.

Başka diyarlara götürüyorlar beni..

Yaşadığımız güzelliklere götürüyor...

Bir buluşma anına gidiyorum...

Ve sonrasında yaptığımız münakaşa...

Sen ve ben yan yana..

Görüyormusun bak resim bile söylüyor...

Siz birbirinizinsiniz diye...

-Birbirinize yakışıyorsunuz...-

-Siz eş ruhlarsınız diyor bu resim...-', 'Yanlızım yine bu akşamda Kalabalığın içinde bir başımayım... Yalan yalan  yıldız gözlüm inanma buna.. Sen her an olduğu gibi benimlesin.. Yü...', ARRAY['Türk Edebiyatı','Şiir','Soner Demirez']::text[], 8.5, '{"poet":"Soner Demirez","poet_slug":"soner-demirez","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/guzel-bir-resim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cemaziyel Evvelimiz', 'cemaziyel-evvelimiz-tahir-yuksel-ngm2q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '''kâinatla düğümlenmiş savaşı

 çözmeye yetmiyor artık gözyaşı''

yıllar yılı sükûn içre ağladık ta ne oldu

gözyaşlarında bir çocuk masumluğu

buğulu baharlarda

evler şöyle dursun sokaklardan kovuldu

ve kaskatı ihanetin betonarme kelimeleri

tırmaladı kuduz kediler gibi

en kutsal duygularımızı

her yıldızsız gecede karanlığa küserek

gün be gün depreşti de yaralar

gene çâre aramadık isyana', '''kâinatla düğümlenmiş savaşı  çözmeye yetmiyor artık gözyaşı'' yıllar yılı sükûn içre ağladık ta ne oldu gözyaşlarında bir çocuk masumluğu bu...', ARRAY['Türk Edebiyatı','Şiir','Tahir Yüksel']::text[], 8.5, '{"poet":"Tahir Yüksel","poet_slug":"tahir-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cemaziyel-evvelimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşün ki,', 'dusun-ki-soner-demirez-8pnvm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kulaklarım adını hiç duymamış 

Ve hiç tekrar etmemiş, isminin ilk hecesini, 

Yalçın kayalarda akislenen seda gibi 

Düşün ki, 

Düşüncelerimde hiç olmamışsın sen 

Uğultusu avuçlarımda kalan rüzgar gibi geçmişsin. 

Ay ışığına hasret yakamozlarının vuslatıymış, 

Tam yerine ve tan yerine vuran o umutlarının gölgesi... 

Düşün ki, 

Bir sigara içimlik vakitmişsin, 

Ciğerime ecza diye dolan 

Ya da uğrak bir, giderlemeyen efkâr kahvehanesi... 

Düşün ki, 

Bardakta eriyen; ebediyen beklemekmiş, şeker sanılan 

Kırık bir sandalyeymiş umutlarımı yasladığım... 

Düşün ki, 

Bir uçurum dibiymiş, bakışlarındaki o mana 

Oyuncaksız kalmasıymış bir çoçuğun 

Ya da bir annenin yavrusuna hasreti... 

Düşün ki, 

Yanık bir Anadolu türküsüymüşsün, 

Çeşme başındaki güzel kızlara inat 

Ve inat, gurbetin tüm güzelliklerine... 

Düşün ki, 

Gam yüklü duvarda asi, kırık bir aynaymışsın 

Hep yarım, hep eksik, hep mahçup.. 

Ayna karşısında kırık bir bakış, 

Kaybolan diğer yarısındaki tılsım.. 

Bir yağmur olmuşsun 

Ve tanelerin düşermiş pembe düşlerimin düştüğü yere.. 

Düşün ki, bir orada bir burada 

Bir gurbette bir sılada 

İsminin yalın, yanlızlığımın çoğul halinde.. 

Ve arkasına saklanmış binlerce yürek 

O binlerce yürekten düşen..Tek bir düş 

Ve ılık bir nefesinde üşümüş... 

Düşün ki, 

Uzak hatıralarım kalmış sende 

Tek kişilik bir oyun 

Gurbete bir tren bileti 

Ya da yarası, 

Yarısından büyük olan yırtık bir resim... 

Düşün ki, 

Hiç olmamış

Hiç çalınmamış bir beste 

Hiç tadılmamış bir zehir, 

Düşün ki, 

Hiç yazılmamış bir şiir...', 'Kulaklarım adını hiç duymamış  Ve hiç tekrar etmemiş, isminin ilk hecesini,  Yalçın kayalarda akislenen seda gibi  Düşün ki,  Düşüncelerimde...', ARRAY['Türk Edebiyatı','Şiir','Soner Demirez']::text[], 8.5, '{"poet":"Soner Demirez","poet_slug":"soner-demirez","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/dusun-ki-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan -Ya da- Uyanış', 'i-syan-ya-da-uyanis-tahir-yuksel-pyt6o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'susmayı mahkûm ettim dünkü celsede

ve bir bir parçaladım incilleri-tevratları-manifestoları

el yazması

taş basması bütün izm''leri lazım olan arasın çöp kutularından

bundan böyle

kalbimi prangaya vuruyorum işte

yufkadır diye

bedenimse kuyudadır yusuf''la

çağlar ötesinde

ibrahim''in düşleriyle yan yana

yok artık deneme-yanılma

ay''ı görünce ay / güneşi görünce güneş

yok yok yok 

yok artık kitabımızda yeri promete''nin', 'susmayı mahkûm ettim dünkü celsede ve bir bir parçaladım incilleri-tevratları-manifestoları el yazması taş basması bütün izm''leri lazım olan...', ARRAY['Türk Edebiyatı','Şiir','Tahir Yüksel']::text[], 8.5, '{"poet":"Tahir Yüksel","poet_slug":"tahir-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/isyan-ya-da-uyanis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şeytan Niyetine Büyütülen Çocuklar', 'seytan-niyetine-buyutulen-cocuklar-tahir-yuksel-i4f32', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'çağ tutsak etti  melekleri en acil zamanda

ve çocuklar meleksiz büyüdüler

zakkum ağaçları gibi acı ve süs yerine

en özgür bulutları bile kirletti eksoz dumanları

çiçekler bal olmadı şifa niyetine

arılar çocuk

çocuklar arı oldular şeytan niyetine

ve ağlayan çocuklara şeker verdiler umut yerine

ninnilerin uyutuculuğuna caz katıp

taşıyıp durdular posta arabalarıyla -kentten kente-

her yargıç önünde binlerce mahkûm

çocuklarına birşeyler götüremeyen babaların hüznü içinde

gözlerini kaybedip hiçbirşey görmediler bu curcuna içinde

eridiler

toz oldular

yok oldular zaman içinde

çağ içinde

devir kendini inkâr etti hapishaneleriyle

çağ evlâtlarını yedi evlâtları çağı

ve canevinden vurdular vicdanları', 'çağ tutsak etti  melekleri en acil zamanda ve çocuklar meleksiz büyüdüler zakkum ağaçları gibi acı ve süs yerine en özgür bulutları bile kir...', ARRAY['Türk Edebiyatı','Şiir','Tahir Yüksel']::text[], 8.5, '{"poet":"Tahir Yüksel","poet_slug":"tahir-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seytan-niyetine-buyutulen-cocuklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Çağın Yeni Çocukları', 'yeni-cagin-yeni-cocuklari-tahir-yuksel-9iaxg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'artık gelsin güvercin kanadında kutsal buyruklar

dua dua yoğrulmuş çocuklar

isyan etti çağa ve zamana rıza-yı hak için

yepyeni bir nesil bayrak bayrak

en yüce imanın doruğundan kopan çığ

ve açılan amentü gibi rahmet yüklü

şeksiz-şüphesiz

yepyeni bir çağ

ağaçlar çiçeğe dursun özgürlük gibi ap-ak

çağın kelepçelerini kırarak

meleklerden mesaj var

yeni çağın çiçeklerine

yeni çağın çocuklarına', 'artık gelsin güvercin kanadında kutsal buyruklar dua dua yoğrulmuş çocuklar isyan etti çağa ve zamana rıza-yı hak için yepyeni bir nesil bay...', ARRAY['Türk Edebiyatı','Şiir','Tahir Yüksel']::text[], 8.5, '{"poet":"Tahir Yüksel","poet_slug":"tahir-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yeni-cagin-yeni-cocuklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hapishane Çiçekleri', 'hapishane-cicekleri-tahir-yuksel-hgca0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'zehir çanağı kalplerden verilen iksir

tutsak eylemiştir bizi şarkıların raksına

yıkılan eyfel''lerin karşısında

promete''den miras malta kentlerinde

tüy kadar hafif prangaların hafifliği

yüreklerdeki yangını söndüremez elbet', 'zehir çanağı kalplerden verilen iksir tutsak eylemiştir bizi şarkıların raksına yıkılan eyfel''lerin karşısında promete''den miras malta kentl...', ARRAY['Türk Edebiyatı','Şiir','Tahir Yüksel']::text[], 8.5, '{"poet":"Tahir Yüksel","poet_slug":"tahir-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hapishane-cicekleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanıktır Tanrı', 'taniktir-tanri-tahir-yuksel-mrqky', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'vermişiz özgürlüğümüzü

hasretine çiçek çağlarının da

ah etmemişiz tanıktır zindanlar

tanıktır yer ve gök

tanıktır kaadir tanrı

çözülmemişiz karanlığın karşısında

ve pişman da olmamışız adanmışlığımıza

yüce buyruk uğruna', 'vermişiz özgürlüğümüzü hasretine çiçek çağlarının da ah etmemişiz tanıktır zindanlar tanıktır yer ve gök tanıktır kaadir tanrı çözülmemişiz ...', ARRAY['Türk Edebiyatı','Şiir','Tahir Yüksel']::text[], 8.5, '{"poet":"Tahir Yüksel","poet_slug":"tahir-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/taniktir-tanri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkunun Gözbebekleri', 'korkunun-gozbebekleri-tahir-yuksel-cbyyh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'korkunun gözbebekleri

puslu aynalarda sarhoştur

teneşirde sırtüstü yatan ceset

kanlı karanlıklardan hatıra

long-playlarda uluyan sesler

karlı hülyaları yırtar tren çığlıklarınca

gelmiyorsa güvercin kanadında kutsal buyruklar

hûnkârlık neye yarar

ve enerjinin yokoluş sırrı

erimeli ki kâfir düşünceler lav lav 

biline

biline bir defadan sonra ölümün olmadığı', 'korkunun gözbebekleri puslu aynalarda sarhoştur teneşirde sırtüstü yatan ceset kanlı karanlıklardan hatıra long-playlarda uluyan sesler karl...', ARRAY['Türk Edebiyatı','Şiir','Tahir Yüksel']::text[], 8.5, '{"poet":"Tahir Yüksel","poet_slug":"tahir-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/korkunun-gozbebekleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eksik Gazel', 'eksik-gazel-mahmut-okur-n35jz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Görmez artık gözlerim bir başka hayal ile

İçilecek bu sukut, bunca derd vebal ile...

Ne mehtabı isterim, ne güneşi görürüm

Bir ömür hep susarım ah ben o cemal ile! 

Her nefeste ümidim parçalansa göğsümde

Yıllar yılı bu ömür geçse de melal ile, 

Mecnun olurum sessiz, tüm çöllere dolarım, 

Her zerreden fşkırıp taşarım bu hal ile...', 'Görmez artık gözlerim bir başka hayal ile İçilecek bu sukut, bunca derd vebal ile... Ne mehtabı isterim, ne güneşi görürüm Bir ömür hep susa...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Okur']::text[], 8.5, '{"poet":"Mahmut Okur","poet_slug":"mahmut-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/eksik-gazel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Perdeler II', 'perdeler-ii-mahmut-okur-ox4ce', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu perde, bu perde, bu titrek deniz

Şu gamlı göğsümde oynaşıyor mu? 

Ey mazi! Istırap yüklü geminiz

Ruhumda bir yere yanaşıyor mu?

Bu perde, bu perde geçmişe şahit

Bu yıldız, şu güneş hep ona ait.

Fısıldar; o eski arzularda yit! 

Orada mutluluk bak yaşıyor mu?', 'Bu perde, bu perde, bu titrek deniz Şu gamlı göğsümde oynaşıyor mu?  Ey mazi! Istırap yüklü geminiz Ruhumda bir yere yanaşıyor mu? Bu perde,...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Okur']::text[], 8.5, '{"poet":"Mahmut Okur","poet_slug":"mahmut-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/perdeler-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Perdeler I', 'perdeler-i-mahmut-okur-y8qzq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalnızlık bürür de sorarım eski

Aşina gölgeler şimdi nerdeler? 

Kim bilir sırrımın mahremindeki

Bir garip alemde, başka yerdeler.

Bir eski resimde bir mahzun anı

Yılların içime dolar hicranı

Perdeden izleyip giden zamanı

Sanırım dostlarım ''Hep içerdeler.''

Gün olur ve gece erir şafakta

Ben sessiz ağlarım soğuk yatakta

Haykırır, ''Dostların kaldı uzakta...! ''

Sarışın perdeler, esmer perdeler...', 'Yalnızlık bürür de sorarım eski Aşina gölgeler şimdi nerdeler?  Kim bilir sırrımın mahremindeki Bir garip alemde, başka yerdeler. Bir eski r...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Okur']::text[], 8.5, '{"poet":"Mahmut Okur","poet_slug":"mahmut-okur","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/perdeler-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürüyelim Biraz Daha', 'yuruyelim-biraz-daha-i-smail-aykanat-c0r6s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'geç geç bitmiyorsun

söyle nigârım

neresindeyim ismailî

köprülerin

ısrarımdır bir sen dökül kuytularıma 

billursu bir kederle içiyorsun ayrılığı

öylece sun bana sâgarını âhım

yalvaç gülüşleriyle geçiyorsun yoksulluğumdan 

ateşine karşı prometheus’un

yüreğinin keşfine izin veren

ben o okyanus kıblesi

şairlerin yalnızlığı emanet ettiği yegâne zat

bunca yankı içinde başka söze ne hacet

duymak istediğimiz

ölümü haberleştirmesi değil midir

lotus çiçeklerinin

ağlamıyor gibi ağlayan

selâma muhtaç cümle çiçeğin

yalnızlığına katılmadan varolmak nedir öyleyse

birlikte aranacak şeyler adına 

haydi arayalım üçünü de

akasya yeşilini / altındaki toprağı ve insanı

yoksa bahtımız mı bilmeliydik

bu kentte ağaç ya da şair olmayı', 'geç geç bitmiyorsun söyle nigârım neresindeyim ismailî köprülerin ısrarımdır bir sen dökül kuytularıma  billursu bir kederle içiyorsun ayrıl...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aykanat']::text[], 8.5, '{"poet":"İsmail Aykanat","poet_slug":"i-smail-aykanat","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yuruyelim-biraz-daha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Gazeli', 'gecenin-gazeli-i-smail-aykanat-hno4j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ötelerden örtülerden geçerek gelenekten güz

elim düşle gelirim

susmalar susmalar susmalar cehennemi

çiçeklenir boğumun gider gider gelirim

şairim kuru sıkı cesetle ruhuma kan ekerler

gecelerin havarisi suhûletle giderim

geceleri titreten yoksa kızıl bir düş mü

cenneti sende bilip döner döner gelirim

durup yol çatımında onurlu ölümler ustasının

gök rengi kadehinden baldıranlar içerim

şahidim olur toprağın darçiçeği

en gizil ölümlerle ben bedelim öderim', 'ötelerden örtülerden geçerek gelenekten güz elim düşle gelirim susmalar susmalar susmalar cehennemi çiçeklenir boğumun gider gider gelirim ş...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aykanat']::text[], 8.5, '{"poet":"İsmail Aykanat","poet_slug":"i-smail-aykanat","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gecenin-gazeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gazel', 'gazel-i-smail-aykanat-4iye0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'arılar mesnevisi bahar çiçekleri

yüreğimin binbir renkli leylasından geçtiler

aşıklar doğmak için yeniden aşkın seherine

içimin gök betiği gecesinden geçtiler

kuyularda sahipsizdim beni kardeşlerim yaktı

ve yakub’un gözlerinden semenderler geçtiler

demirciler çarşısında geçilmez celalillerden

denenmişin denendiği çarşılardan celaliler geçtiler

kervanbaşı ölçü alır ölçü satar hanlarda 

can kırıldı meyden neşveyi züleyha’dan içtiler

o diyarın kurbanı ibrahim berzahın mesihi 

evlileri söğüt altı ve dahi rindleri seçtiler

bütün derman ustalar bir elden terk ettiler

nev truva atının terkisinde sürçtüler

 

İsmail Aykanat', 'arılar mesnevisi bahar çiçekleri yüreğimin binbir renkli leylasından geçtiler aşıklar doğmak için yeniden aşkın seherine içimin gök betiği g...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aykanat']::text[], 8.5, '{"poet":"İsmail Aykanat","poet_slug":"i-smail-aykanat","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gazel-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mısra-ı Âzade', 'misra-i-zade-i-smail-aykanat-k806i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'işe yarar ne kaldı aşık olmadıktan başka

 

İsmail Aykanat', 'işe yarar ne kaldı aşık olmadıktan başka   İsmail Aykanat...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aykanat']::text[], 8.5, '{"poet":"İsmail Aykanat","poet_slug":"i-smail-aykanat","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/misra-i-azade-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tenasüp', 'tenasup-i-smail-aykanat-yl7at', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'neden sen gurbetlerde bu kadar mükemmelsin

niçin hoş-sılada ben nankörüm körüm onca

 

İsmail Aykanat', 'neden sen gurbetlerde bu kadar mükemmelsin niçin hoş-sılada ben nankörüm körüm onca   İsmail Aykanat...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aykanat']::text[], 8.5, '{"poet":"İsmail Aykanat","poet_slug":"i-smail-aykanat","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/tenasup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sayhadra', 'sayhadra-i-smail-aykanat-jlz3j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gece olur gün doğar

güne atılınca derler biter gibi olur

sesler iter gibidir sayhadra

                 anlamak zor

                         çekiyor

                               uzaklara

öyle uzak ufku bile göremiyor

gözlerim suskusunu öremiyor

sözlerim öyle yakın uyanıyorum derindir

hangi kızın sorusudur gözlerindeki uyku

birazdan buradaydı dönüyor biraz önce

                                ...biraz

                           -dan

                      buradaydı

                  dön! 

               -üyor

           bir: 

         -az

önce...

          dökül sayhadra

                    d

                      ö

                     k

                       ü

                     l

böyle yağar rüyasında şairin endülüsü

alt yazılı ve siyah beyaz

senin rüyalarında hep pazarlar kurulur

bir ramazan davulu say ki harran

benimse ermişliğim ellerimden sorulur

melâl uzatmalı sevgilim

gözler çeker / sesler iter

               “zafer

biraz da hasar ister” sayhadra

güne atılınca dertler biter gibi: dur', 'gece olur gün doğar güne atılınca derler biter gibi olur sesler iter gibidir sayhadra                  anlamak zor                          ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aykanat']::text[], 8.5, '{"poet":"İsmail Aykanat","poet_slug":"i-smail-aykanat","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sayhadra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taygalarda Yetim Bir Gül Büyüdü', 'taygalarda-yetim-bir-gul-buyudu-i-smail-aykanat-7p54o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '-nurullah genç’e- perde aralanırken yumru yumru düğümlenir kıyısına hüznün sahra

 

1./

seranat öldü

kahrımı çiziyorum buz kesmiş dünyaya

her çatlağa mevsimlerden ses vererek

bitkinim

bu kez senin kollarınlayım asmalarda

kar

yağdı arzularıma

hengâme - -

sonra firak ve ukdesi suskunluğun

bir tren ölümün kapısını aralar

ipek şallar  artık ne anlar beni

günbegün yinelenen derya / sancılar

sonlara açılan kucak kaybolur

susturulan gülüşlerimi toplarım kıyılarda

sahraya dökülmüş susamışlığım

düşlerimde morötesi acılarım gizlidir

bekleyişim bir gül / üşür yüreğim

2./

bir ihtilal türküsüdür yaşamak

bir ihtilal türküsüdür yaşamak

taun günlerinden kalma hüznü eriten

kahrımı çiziyorum buz kesmiş dünyaya

taygalarda 

yetim bir gül büyüdü

ağrıyan yerleri kangren oluyor 

cellatların

gezinir dilleri yerenliğimiz

bir molla tevekkülü yüreğimde sel olur

parmaklarım parçalar ihanet kalkanını

ağıt gönüllüm elveda', '-nurullah genç’e- perde aralanırken yumru yumru düğümlenir kıyısına hüznün sahra   1./ seranat öldü kahrımı çiziyorum buz kesmiş dünyaya her...', ARRAY['Türk Edebiyatı','Şiir','İsmail Aykanat']::text[], 8.5, '{"poet":"İsmail Aykanat","poet_slug":"i-smail-aykanat","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/taygalarda-yetim-bir-gul-buyudu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş''e', 'gunes-e-yavuz-sevinc-h9ccz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana şiirler yazdım, 

Sitemler yolladım..

Geri çağırdım kuşları üzülme diye..

Türküleri senin için dinledim, 

Sen herşeydin, herşey sendi..

Güzeldin, inanılmaz

Bozulmasın diye büyü..

Dokunamadım.

Özlemler büyüttüm sonra, 

Sıcak gecelerde sarhoş oldum, 

Buğunu kokladım..

Biryıl oldu birtanem

Sana doymadım..', 'Sana şiirler yazdım,  Sitemler yolladım.. Geri çağırdım kuşları üzülme diye.. Türküleri senin için dinledim,  Sen herşeydin, herşey sendi.. ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Sevinç']::text[], 8.5, '{"poet":"Yavuz Sevinç","poet_slug":"yavuz-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gunes-e-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bal Arısı', 'bal-arisi-cem-mizrak-vwv59', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hani sana söylemiştim ya

İlk defa, ilk kez

Seni seviyorum diye

Herkesin içinde haykırarak

Kimseye aldırmadan

Yalandı güzelim, inandın mı yoksa

Bende sonradan anladım 

Yanlış kızı sevdiğimi yanlış çiçeğe konduğumu

Çaresiz bir bal arısı gibi

Karşıdan kandırdın beni 

Güzel rengin ve kokunla

Fakat yaklaşmadan anlayamadım senin

İçinin boş olduğunu

Bana bir şey olmaz güzelim

Başka çiçekte bulurum konacak

Ama bütün arılar biliyor senden yar olmayacağını

Sana asalak sineklerden başkası konmayacak', 'Hani sana söylemiştim ya İlk defa, ilk kez Seni seviyorum diye Herkesin içinde haykırarak Kimseye aldırmadan Yalandı güzelim, inandın mı yok...', ARRAY['Türk Edebiyatı','Şiir','Cem Mızrak']::text[], 8.5, '{"poet":"Cem Mızrak","poet_slug":"cem-mizrak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bal-arisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-cem-mizrak-nga6r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biliyorsunuz değil mi ey insanlık, 

Yaşamak hayatı

Doya doya, veda günü gelene kadar

Sadece amacına yönelerek 

Etrafındaki engelleri görmeden aşarak

Yaşamak mıdır ki sadece nefes almak

Ve sadece oyalanmak hayatta, akışına bırakarak

Siz tutun kendinizi hayatın akışına kapılmayın

Ve hatta daha fazlasını yapın hayat sizin akışınııza kapılsın

Çünkü yaşam koskoca bir nehir gibidir

Akar çılgıncasına ve katar önüne geleni acımadan

Mühim olan hayatın önüne katılmamaktır

Hayatı önüne katarak kovalamaktır sonuna kadar

Zaten çıkacaktır önüne o, son denilen şelale

Herkes son bilir orasını fakat son değildir, bilenler bilir

Her nehrin bitişi bir nehrin başlangıcıdır, bilenlere

Bilmeyenlere ise sondur tabiki 

Başlangıcını bilmedikleri, kapkara bir son

Sonunu onlarında bilmedikleri.', 'Biliyorsunuz değil mi ey insanlık,  Yaşamak hayatı Doya doya, veda günü gelene kadar Sadece amacına yönelerek  Etrafındaki engelleri görmede...', ARRAY['Türk Edebiyatı','Şiir','Cem Mızrak']::text[], 8.5, '{"poet":"Cem Mızrak","poet_slug":"cem-mizrak","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hayat-68-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni seviyorum', 'seni-seviyorum-cem-mizrak-a75sa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hani o gün, hatırlıyor musun? 

Parktaydık, sadece ikimiz

Zaten o yağmurda başka kim oturabilir ki orada

Hani sen açık bir çay istemiştin

Soğuk getirdi diye tartışmıştık garsonla

Sonra, hani ellerin ellerime değmişti o soğukta, sıcacık

Gözgöze gelmiştik, koca bir günde ilk defa

Ve seni sevdiğimi söylemiştim sana, utanmama rağmen

Sen, yanlızca susmuştun ve başını önüne eğmiştin

O an kalbim yerinden çıkacaktı sanki

Başını kaldırdın ve bana dedin ya hani, ”bende”

Sevincimden koşmak geldi içimden 

Islak sokaklarda hiç durmadan

Hala inanmıyordum, o güzel kız beni seviyordu

Bende onu

‘sevmek’ basit kalır yanında, onun için ölüyordum

Hiç böyle hissetmedim kendimi inan

Artık gözlerinin içinde kaybolabilirdim

Yanlış anlar mı diye düşünmeden 

Her gece dua ediyorum bitmesin diye

Sonsuza kadar sürsün diye

Ben ebedi olduğuna inanıyorum

Ve utanmadan söylüyorum

Seni seviyorum.', 'Hani o gün, hatırlıyor musun?  Parktaydık, sadece ikimiz Zaten o yağmurda başka kim oturabilir ki orada Hani sen açık bir çay istemiştin Soğ...', ARRAY['Türk Edebiyatı','Şiir','Cem Mızrak']::text[], 8.5, '{"poet":"Cem Mızrak","poet_slug":"cem-mizrak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/seni-seviyorum-100-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dön Gel Artık', 'don-gel-artik-yuksel-aytug-nble4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hasretin alevinde 

Tütsülendi ayrılık

Yetmedi mi özleyişler? 

Ne olur dön gel artık

Gittiğin günden beri

Kalbim kırık, yaralı

Gönül defterimde sayfan

Baştan sona karalı

Un-ufak oldu sevgimiz

Enginlere dağıldık

Bıraktığın yerdeyim

Ne olur dön gel artık

Yağmura dua ederken

Tufana teslim olduk

Kök salmadan toprağa

Sürüklenip mahvolduk.

Sevginin kör tuzağında

Düğüm olduk, dolandık

Çözecek dermanım yok

Ne olur dön gel artık

Acımasız bir sürgün bu

Umutsuzluğun çölüne

Hiçbir şey  koyamadım

Hasretinin önüne

Kendimizden uzaklaşıp

Yolun sonuna geldik

Ben çoktan geri döndüm

Ne olur dön gel artık', 'Hasretin alevinde  Tütsülendi ayrılık Yetmedi mi özleyişler?  Ne olur dön gel artık Gittiğin günden beri Kalbim kırık, yaralı Gönül defterim...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Aytuğ']::text[], 8.5, '{"poet":"Yüksel Aytuğ","poet_slug":"yuksel-aytug","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/don-gel-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Protesto', 'protesto-ali-kalayci-rv54k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kar yağmalı

şehir terkedilsin mi  kirlerin egemenliğine

ölülerin yavan sırlarıyla çeşnilenen

bütün söylenceler kahrolsun..

çingenelerin ve neonların

bir türlü kabullenmediği

şubat bulutları vardı aramızda.

meyhane semtlerinin

kedileri gibi yaltak

siyasi parti ilanları

umurunda değildi fahişelerin.

özlenen omuz omuza bir hayat

omuz omuza aşka ve hükümete karşı: 

tek yol.. deniz.. intikam..

çaresi yok kar yağmalı

iri gümüş gözleri vardı sevgilimin

sevişebilirdik pazar akşamları

sarı şarkılara şartlanmış buz dudakları 

dudaklarımda ılımazdı

huylanıp gerilla edasıyla yakardım

siyah beyaz yarın fotoğraflarını

sevgilim ağlardı.

kıvrak caz ritimleri ve esrar satıcıları

daha keşfetmemişti kolej kapılarını

kışa vakit vardı ve

parmaklarımdaki manyeto izinden

habersizdi sevgilim.

ben korsan mitinglerin heveslisi

herşeyi hiç sayarak

kurtarılmış caddelerde koyuverdim sesimi: 

kana kan.. kurtuluş.. kavgaya devam..

evet kar yağmalı.

kar yağmalı

aşklar da terk edilsin mi kirlerin egemenliğine 

sloganlar, yıldönümleri

ve naylon sarmaşıklar kahrolsun..', 'kar yağmalı şehir terkedilsin mi  kirlerin egemenliğine ölülerin yavan sırlarıyla çeşnilenen bütün söylenceler kahrolsun.. çingenelerin ve n...', ARRAY['Türk Edebiyatı','Şiir','Ali Kalaycı']::text[], 8.5, '{"poet":"Ali Kalaycı","poet_slug":"ali-kalayci","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/protesto-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kum Tanesi', 'kum-tanesi-yuksel-aytug-4ke9y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bilmiyorum, 

daha ne kadar beklemeliyim

yüreğinin ıssız, solgun derinliklerinde...

Sen bir istiridye, 

ben bir kum taneciği...

Ne dermanım var inci olmayı bekleyecek, 

ne de onca zamanım.

Farket! 

Beni farket ne olur, 

okyanusta bir kum tanesi olarak 

kalmayayım...', 'Bilmiyorum,  daha ne kadar beklemeliyim yüreğinin ıssız, solgun derinliklerinde... Sen bir istiridye,  ben bir kum taneciği... Ne dermanım v...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Aytuğ']::text[], 8.5, '{"poet":"Yüksel Aytuğ","poet_slug":"yuksel-aytug","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kum-tanesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölü Evi', 'olu-evi-ali-kalayci-886ti', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 've

destursuz

bir

poyraz

dağların

yıkıldığı

akşam

gözlerimde

çapraz

yaşlar

ağlasam

ağlamasam

gece

döner

ay

heceler

karlı

kavaklar

yüreğime

yüreğime

dallanır

savuşamam

durduk

yerde

ak 

bakışım

allanır

ığıl

ığıl

kana

yonca

çiçeği

gayrı

ölesiye

uykular

haram..', 've destursuz bir poyraz dağların yıkıldığı akşam gözlerimde çapraz yaşlar ağlasam ağlamasam gece döner ay heceler karlı kavaklar yüreğime yü...', ARRAY['Türk Edebiyatı','Şiir','Ali Kalaycı']::text[], 8.5, '{"poet":"Ali Kalaycı","poet_slug":"ali-kalayci","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/olu-evi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Şehidi', 'sevda-sehidi-yuksel-aytug-k8nst', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben bir meçhul askerim

Toprağın derinliklerinde

Aşkının şehidiyim

Bir meydan muharebesinde

Kim çekti aşkın pimini? 

Kim tutuşturdu elime? 

Sinsi bir şarapnel gibi

Saplandı yüreğime

Göğsümde madalya değil

Aşkının kurşunları var

Bil ki kalbinin altında

Bir sevda şehidi yatar', 'Ben bir meçhul askerim Toprağın derinliklerinde Aşkının şehidiyim Bir meydan muharebesinde Kim çekti aşkın pimini?  Kim tutuşturdu elime?  S...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Aytuğ']::text[], 8.5, '{"poet":"Yüksel Aytuğ","poet_slug":"yuksel-aytug","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevda-sehidi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Layiha', 'layiha-ali-kalayci-244lf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'puştluğum kendime

ayrılığın ırzına dokunmadım

dilim çözülebilirdi rakı komalarında

yağmurlar altında becerdiğim kadar aylak

elinin değdiği yerlerimi sulardan sakınarak

ısrarlardan toy cevaplar kaçırdım

gücüme gitse de

telefonları yüzüme kapattığın

h i ç b i r ş e y i

h i ç k i m s e y e

en başından anlatmadım', 'puştluğum kendime ayrılığın ırzına dokunmadım dilim çözülebilirdi rakı komalarında yağmurlar altında becerdiğim kadar aylak elinin değdiği y...', ARRAY['Türk Edebiyatı','Şiir','Ali Kalaycı']::text[], 8.5, '{"poet":"Ali Kalaycı","poet_slug":"ali-kalayci","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/layiha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'While justice was just ice in your eyes', 'while-justice-was-just-ice-in-your-eyes-ali-kalayci-m8nzd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'fırtınalardayız bak, 

bahar bizi neylesin

dört duvar arasında

harami ve tutsak

aç, üryan kaldıysak

suç senin..

zaman 

buyrukçularda rehin

zapta geçmeden son turu

yelkovanla akrebin

sevişelim

sokul bana

kirpiğimden yakın olsun bedenin

korkma

yetkileri yetmez

seni benden koparmaya

devriyelerin', 'fırtınalardayız bak,  bahar bizi neylesin dört duvar arasında harami ve tutsak aç, üryan kaldıysak suç senin.. zaman  buyrukçularda rehin za...', ARRAY['Türk Edebiyatı','Şiir','Ali Kalaycı']::text[], 8.5, '{"poet":"Ali Kalaycı","poet_slug":"ali-kalayci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/while-justice-was-just-ice-in-your-eyes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gafil', 'gafil-ahmet-agdere-8e9by', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçinde bulunur ne bir kin, ne de nefret, 

Sana olan duygular sevgiden ibaret! 

Ateşlerin içinde yanan ben olayım, 

Yeter ki sen her daim gönlünü mesut et! 

Aşk dediğin nedir ki canım bu alemde, 

Senin ki tek gerçek, gerisi hep bahane! 

Bekçiyim senle nesli tükenen kutsalın, 

Düşmüştür yalnız yaşamak bana, kime ne! 

Sana ait duygularını bir bir katlet, 

Bük boynunu, ez, lime lime doğra, mahvet.. 

Bir hata edip benimkine el uzatma; 

Yoksa ne kemik kalır alemde ne de et! ...', 'İçinde bulunur ne bir kin, ne de nefret,  Sana olan duygular sevgiden ibaret!  Ateşlerin içinde yanan ben olayım,  Yeter ki sen her daim gön...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gafil-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baranta', 'baranta-ali-kalayci-zvvk1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'küfür gibi gözlerinle 

kuytularımdasın

ana avrat bu gece

kirpik kirpik selamsız

kan revan hısım

ille de kargaşam olacaksın.

ovada diz boyu kar

kar sırtında yıldız izi

gölgemi bir mermi yoklar

bir ses seker çakal sürülerinden

koynumda bir gül kımıldar

bela mı bela..

bir hançer kürt nakışlarını

etime işler

öncesiz ve sonrasız

sevgilim benim

yangınlardan kaçırdığım

ay görmemiş şoselerden

sayrılarımdan

sevdiysem iftiradır

ya sevmediysem?', 'küfür gibi gözlerinle  kuytularımdasın ana avrat bu gece kirpik kirpik selamsız kan revan hısım ille de kargaşam olacaksın. ovada diz boyu k...', ARRAY['Türk Edebiyatı','Şiir','Ali Kalaycı']::text[], 8.5, '{"poet":"Ali Kalaycı","poet_slug":"ali-kalayci","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/baranta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurca', 'yagmurca-ali-kalayci-bzazk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'dağlara güvenme

dağlar benim dağlarım

bildiğin yurtlara git

ki kan dökmesem

yüksünecek

tüfengim

acılıyım

anla

şehir işi sulhlar

getirme bana 

   

muhacir bir nişana

yatar mı bu eşkıya

babayiğit bir ölüm

yoksa menzil ucunda

bana kancık tuzağın

sökmez yağmurca', 'dağlara güvenme dağlar benim dağlarım bildiğin yurtlara git ki kan dökmesem yüksünecek tüfengim acılıyım anla şehir işi sulhlar getirme bana...', ARRAY['Türk Edebiyatı','Şiir','Ali Kalaycı']::text[], 8.5, '{"poet":"Ali Kalaycı","poet_slug":"ali-kalayci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yagmurca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Av ile Avcı', 'av-ile-avci-ahmet-agdere-pmwug', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tilki av olmuş, girmiş ormana, 

Ukalaca dolaşmış uzun uzadıya.

Bakmış aslan olacak gibi değil; 

Avlamış tilkiyi aydınlık anında! ..

''''Aslan kral! '''' demişler yıllarca; 

Pençe atmadık bırakmamış ormanda...

İtirazda bulunmuş buna Ademoğlu; 

Silahsız aslanı avlamış silahla! ...

Ne tür silah ararsan hep insanda; 

Hangi avın canı dayanır daha buna! 

Lakin doğanın kanunu; bir av, bir avcı; 

Melekler almış insanı pusuya! ...

Bilinçsiz dolasıp durur dünyada, 

Bilmez ne zaman kalır tuzakta! 

Gönül bırakmak istemez dünyayı fakat; 

Elbette avlanmak haktır ona da! ...', 'Tilki av olmuş, girmiş ormana,  Ukalaca dolaşmış uzun uzadıya. Bakmış aslan olacak gibi değil;  Avlamış tilkiyi aydınlık anında! .. ''''Aslan ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/av-ile-avci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklı Sevdamsın', 'sakli-sevdamsin-ahmet-agdere-gl9ec', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saklı sevdamsın iki yıldız arasında, 

Eski ve yeni yıllar sayfasında...

Lavanta kokusu yayılır etrafa; 

İz bırakılan koca dünya darasında!', 'Saklı sevdamsın iki yıldız arasında,  Eski ve yeni yıllar sayfasında... Lavanta kokusu yayılır etrafa;  İz bırakılan koca dünya darasında!...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sakli-sevdamsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karabasan', 'karabasan-ali-kalayci-kwqmd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'esas aşklar

bakara

ondokuz yaşım

doymadığım 

dudaklarından

bütün kitapsızlığım

inkar etmek için seviştik

şifre miydi

aramızda

usturuplu

şavkıyla

yaz 

ovalarında 

ay

gidemezdin

er vakitte

sana

çok 

geç

kalmasaydım 

vay

uykulardan

uykulara

uyandım', 'esas aşklar bakara ondokuz yaşım doymadığım  dudaklarından bütün kitapsızlığım inkar etmek için seviştik şifre miydi aramızda usturuplu şavk...', ARRAY['Türk Edebiyatı','Şiir','Ali Kalaycı']::text[], 8.5, '{"poet":"Ali Kalaycı","poet_slug":"ali-kalayci","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/karabasan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farkında mısın Gönül?', 'farkinda-misin-gonul-ahmet-agdere-mk3di', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bilmiyorum farkında mısın ne kadar küçüldüğünü gönül? 

Anlamsız ifadeler hayatında pişman olacaksın bir gün.

Değiştirmek isteyeceksin kaderini, işte o an dövül! 

Ezik duygularla dolu yaşam olarak anılacak hep dün...', 'Bilmiyorum farkında mısın ne kadar küçüldüğünü gönül?  Anlamsız ifadeler hayatında pişman olacaksın bir gün. Değiştirmek isteyeceksin kaderi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/farkinda-misin-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku Ve Ümit!', 'korku-ve-umit-abdulkadir-karaman-w2wyj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beklemediğin bir ân, çok korktuğun olacak...

Kalktığında bir sabah, bakacaksın ben yokum.

Gözlerin yaş, yüreğin pişmanlıkla dolacak...

Deliye çevirecek her yana sinmiş kokum. 

Soracaksın: ne için, nereye gitti, niye? 

Sebepler arayarak kendine kızacaksın! 

Korkacaksın; ebedî, gelmez terk etti diye

Usanmadan adımı her yere yazacaksın! 

Susuzluğun doruğa çıkacak, ya hasretin! ? 

Vermeyecek hiç rahat, bozacak huzurunu...

Arama canındadır; usandığın gurbetin…

Kurtuluş yok, kırmadan kibrini, gururunu..

İçinde, umutların başlayacak yangını...

Gözyaşın söndürmekte kifâyetsiz kalacak! 

Lânetle anacaksın düştüğün yanılgını…

Güvenle dayandığın ümitler yıkılacak! 

Bir yaslı kâlp sonsuza ilencini sıralar…

Hiç rahat vermeyecek, hatıralar kaçsan da...

Depreşecek, kapandı zannettiğin yaralar 

Bulunmayacak çâre, dermana el açsan da...

Yollara perçinleyip gözlerini, bıkmadan 

Bekleyeceksin...belki, geriye döner diye! 

Canını özlemlerin alevinde yakmadan...

Kavuşmak mümkün değil terk ettiğin sevgiye! 

18 – 07 – 2001', 'Beklemediğin bir ân, çok korktuğun olacak... Kalktığında bir sabah, bakacaksın ben yokum. Gözlerin yaş, yüreğin pişmanlıkla dolacak... Deliy...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/korku-ve-umit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlar', 'umutlar-mikdat-acikkapi-bww4c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Umutlar, kağıtlardan yaptığımız uçaklardı

rüzğarın kanatlarına bırakır

süzülünüşlerini

dalgalanmalarını izlerdik

ve birden atardı rüzğar kanatlarından

çaresiz

düşüşlerine bakardık

ya tekrar rüzğarın kanatlarına bırakır

ya da sıkılır uçurmazdık  kağıt uçaklarımızı

bir kenara birakır

belki de yırtardık

umutlar, kağıtlardan yaptığımız uçaklardı', 'Umutlar, kağıtlardan yaptığımız uçaklardı rüzğarın kanatlarına bırakır süzülünüşlerini dalgalanmalarını izlerdik ve birden atardı rüzğar kan...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Açıkkapı']::text[], 8.5, '{"poet":"Mikdat Açıkkapı","poet_slug":"mikdat-acikkapi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/umutlar-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorsun', 'biliyorsun-ali-safak-bali-xpck2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gecelerim de gündüzlerim gibi, karanlık.

Ne aya bakabiliyorum, ne de yıldıza artık.

Şikayet etmemeliyim, biliyorsun, bir zamanlar 

en çok sevdiğimdi benim, zifiri karanlık...

Yalnızlığım da kalabalıklarım gibi, kimsesiz

Ne seninle olabiliyorum, şimdi, ne de sensiz

Bir girdaba kaptırdım, biliyorsun, ruhumu, 

en az benim kadar, artık tüm çabalar kifayetsiz...', 'Gecelerim de gündüzlerim gibi, karanlık. Ne aya bakabiliyorum, ne de yıldıza artık. Şikayet etmemeliyim, biliyorsun, bir zamanlar  en çok se...', ARRAY['Türk Edebiyatı','Şiir','Ali Şafak Balı']::text[], 8.5, '{"poet":"Ali Şafak Balı","poet_slug":"ali-safak-bali","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/biliyorsun-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bembeyaz', 'bembeyaz-emine-cevirgen-ug62k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gün

Geleceksin belkide özleyeceksin beni

Bir kız vardı diyeceksin

Yakın çevrelerde

İsmini hatırlayamayacaksın belkide

Ama vardı...diyeceksin vardı işte

Gelip görmek isteyeceksin belkide

Bakacaksın bomboş bir sokak ve sessiz bir ev

O kızı soracaksın hekese

Kimi tanımayacak bile

Bazılarıda yüzüne bakacak sadece

Ama bilemeyeceksin o kız nerede 

İŞTE SEVGİLİM...

Mutlu ve neşeli diye tanıdığın o kızı

Baş ucunda selvi ağacı olan 

Üzerinde yeşil çimleri biten

Kenarlarında kırmızı güller açan

Kapkara bir dikdörtgen çukurunun içinde

BEMBEYAZ  bulacaksın.', 'Bir gün Geleceksin belkide özleyeceksin beni Bir kız vardı diyeceksin Yakın çevrelerde İsmini hatırlayamayacaksın belkide Ama vardı...diyece...', ARRAY['Türk Edebiyatı','Şiir','Emine Çevirgen']::text[], 8.5, '{"poet":"Emine Çevirgen","poet_slug":"emine-cevirgen","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bembeyaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ressam Haklı', 'ressam-hakli-mehmet-akif-ersoy-z74h5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir zaman vardı ya tarih-i mukaddes modası...

Yeni yaptırdığı köşkün büyücek bir odası

Mutfakta eski resimler ile hep süslensin

Diye ressam aratır hayli zaman bir zengin.

Biri peyda olarak ''Ben yaparım'' der, kolunu

Sıvayıp akşama varmaz, sekiz arşın salonu

Sıvar ama ne sıvar...Sahibi der: 

                                -Usta bu ne? 

Kıpkızıl bir boya çektin odanın her yerine! ..

-Bu resim, askeri basmakta iken Firavun'' un 

Kızıl Deniz yarılıp geçmesidir Musa'' nın

-Hani Musa, be adam? 

                               -Çıkmış efendim karaya

-Firavun nerde? 

                               -Boğulmuş.

                               -Ya bu kan rengi boya? 

-Kızıl Deniz, a efendim yeşil olmaz ya bu da! 

-Çok güzel levha imiş, doğrusu şenlendi oda! ..', 'Bir zaman vardı ya tarih-i mukaddes modası... Yeni yaptırdığı köşkün büyücek bir odası Mutfakta eski resimler ile hep süslensin Diye ressam ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Ersoy']::text[], 8.5, '{"poet":"Mehmet Akif Ersoy","poet_slug":"mehmet-akif-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ressam-hakli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akça Kızlar Göç Eyledi Yurdundan', 'akca-kizlar-goc-eyledi-yurdundan-karacaoglan-bd8b2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akça kızlar göç eyledi yurdundan 

Koç yiğitler deli oldu derdinden 

Gün öğle sonu da belin ardından

Saydım altı güzel indi pınara

Üçü uzun boylu, kaşların süzer

Üçü orta boylu, zülfünü dizer

Sanki akça ceylan bir çölde gezer

Sarı kınalı keklik indi pınara

El atıp dericek Hatce'' nin gülü

Can için sarıcak Ayşe'' nin beli

İkisi hampalı biri döndeli 

Eminem çok içti kandı pınara

Karac''oğlan bunu böyle söyledi

İndi aşkın deryasını boyladı

Kızlar gitti diye pınar ağladı

Acıştım yüreğim yandı pınara', 'Akça kızlar göç eyledi yurdundan  Koç yiğitler deli oldu derdinden  Gün öğle sonu da belin ardından Saydım altı güzel indi pınara Üçü uzun b...', ARRAY['Türk Edebiyatı','Şiir','Karacaoğlan']::text[], 8.5, '{"poet":"Karacaoğlan","poet_slug":"karacaoglan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/akca-kizlar-goc-eyledi-yurdundan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Kızım', 'canim-kizim-i-clal-aydin-cjk08', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Canım  Kızım; 

Meğer sanaymış yolculuğum. Burgun kendime neden yasadığımı sordum; bir anlamı  olmalıydı basımdan gecen onca şeyin; bir karşılığım olmalıydı hayatta.bu soruyu sorduğumda kendime  yirmi üç yasındaydım. Ellerim yaslanmamıştı  henüz ama soluk soluğa kalmış yorgun bir çocuktum, bildiğim her şeyden, herkesten uzaktaydım..

Yalnızlık, yabancılık, haksızlık dünya kederleri  bir olup yüklenmişlerdi bir gece kalbime. Balkona çıktım, dördüncü kattaydım.soğuk bir kıs gecesiydi. Demirleri tuttum caddeyi seyrettim ağlayarak. Göreceksin insan nasıl acır kendine böyle anlarda...  Yüz yirmi dokuz numaralı otobüs geçiyordu ve bir kız köşedeki benzinciden çıkmış; elinde bira şişesi ağlıyordu, uzundu sacları.kaldırıma oturdu elindeki bira şişesini karşısındaki saat kulesine fırlattı. Saat oniki''ye on vardı  ve belli ki  ikimizinde canı çok yanmaktaydı...

Annem geldi aklıma bir Pazar dönüşü  elimi avucunun içinde kavrayışı ve bana doğumumu anlatısı. Yalnızmış sancıları geldiğinde; çok korkmuş ya başaramazsa diye. Balkona çıkmış insanları seyretmiş  başka kadınlarda çekti  bu sancıyı diyerek  ve  başka insanların acılarından güç alarak doğuma girmiş. Doğduğumda  yaptığı ilk şey saate bakmak olmuş. Saat öğlen oniki''ye on varmış. İşte böyle demiştim kendi kendime; buraya kadarmış. Sonra çilekli pastayı, çaldığım vişneleri, limonlu dondurmayı ne çok sevdiğimi düşündüm. Saclarımı uzatacaktım, para biriktirip yollara çıkacaktım ve bir daha hiç yirmi üç yaşında olmayacaktım. Büyük kararlardan önce mutlaka bir gece beklemeli eğer sabah  aynıysa her şey o zaman düşünmeli  bitirmeyi  bir hikayeyi.. Ertesi gün güneşli bir sabahtı; çoktan düşmüştü ruhumun ve kederimin ateşi...

O günden sonra neler oldu bir bilsen...sana anlatacak o kadar çok şeyim var ki. Çok korkuyorum severmisin acaba beni? İyi  bir  anne olabilecek miyim? Koruyabilecek miyim seni? Kalbimde ve zihnimde biriktirdiklerimi  eksiksiz  iletebilecek miyim sana? 

Takvimler bir sonbahar çocuğu olacağını söylüyor. Annende sonbaharda doğmuş bir bebekti. Bu mevsim hüzünlüdür kızım  ve çok sever güneşi.şuanda minicik tekmelerinle ben burdayım diyorsun. Gelişine az kaldı. Seni sevinçle beklerken odanı hazırlıyoruz hevesle.ama ne yazık ki odan kadar sessiz ve özenli bir ülkeye gelmiyorsun. İsterdim ki benim gördüklerime sen şahit olma ama onlar sana bile yetişti. Geleceği  zamanı kendi seçen biri olarak güçlü ve bendende önde olacağını biliyorum umarım sende seversin  karıncaları, kedileri ve kelebekleri. Ben babasını çok özleyen bir çocuktum  dilerim sen ayrı kalmazsın seni sevinçle bekleyen  babandan....

Anneler ve babalar tanıyacaksın bizden başka. Oğluna söz verdiği bisikleti alamadığında notalarla oğlunun adını yazan bıyıklı yorgun babaları, ya da kendi giyemediği mavi yirmi üç nisan elbisesini sabaha dek uyumadan kızına diken anneleri, sonra kendinden başkasını düşünmeyenleri, kendi öfkesinde boğulanları  ve yalancıları tanıyacaksın. AŞk''ı tanıyacaksın bir gün, kalbim kırılacak ve belki kıracaksın birilerini... İyi bir tamirci ol kızım, çabuk onar kırdığın kalplere ve çaresiz kalma kendi kırık kalbine. Sen şimdi kendi öykünü yazmaya geliyorsun.

Hayat iki seçenek sunuyor: ya payına düşen kederi parlatacaksın; ya da  ömrünle iyi geçinmeye bakacaksın. İkincisini  tercih edersin umarım...

Bana öğretildiği gibi kızım; öğrendiğin çiçek adlarını unutma, kelebekleri kitap arasında kurutma, kin büyütme  kalbinde  ve  incitme  kimseyi...

Dilerim  dünyaya geliş  nedenini sen  çabuk bulursun.yolun acık  olsun....

Annen', 'Canım  Kızım;  Meğer sanaymış yolculuğum. Burgun kendime neden yasadığımı sordum; bir anlamı  olmalıydı basımdan gecen onca şeyin; bir karşı...', ARRAY['Türk Edebiyatı','Şiir','İclal Aydın']::text[], 8.5, '{"poet":"İclal Aydın","poet_slug":"i-clal-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/canim-kizim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suya Giden Allı Gelin', 'suya-giden-alli-gelin-karacaoglan-6ciov', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '-Suya giden allı gelin 

Niçin böyle salınırsın? 

Gelin bir su ver içeyim

Gelin kimin gelinisin

-Su değildir derdin

Görmek ise yeter gördün

Oğlan burda çokça durdun

Ağam gelir döğülürsün

-Döğülürsem döğüleyim

Söğülürsem söğüleyim

Gelin sana kul olayım

Ölürüm kanlım olursun

-Yaylaya göçmedin mi? 

Soğuk sular içmedin mi? 

Güzel görüp geçmedin mi? 

Beni görüp delirirsin! 

-Türlü yaylayı aşınca

Soğuk suları içince

Kocayıp vaktin geçince

Taşlar alıp döğünürsün

-Evlerinin önü solgan 

Ağam görürsen korkan

Telli perçemlisin oğlan

Ne dedim ki darılırsın

Karac''oğlan sana vurgun

Döşlerin elmadan dolgun

Sevindirdin beni bugün

İnşallah cennet görürsün', '-Suya giden allı gelin  Niçin böyle salınırsın?  Gelin bir su ver içeyim Gelin kimin gelinisin -Su değildir derdin Görmek ise yeter gördün O...', ARRAY['Türk Edebiyatı','Şiir','Karacaoğlan']::text[], 8.5, '{"poet":"Karacaoğlan","poet_slug":"karacaoglan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/suya-giden-alli-gelin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hilâl Gazeli', 'hil-l-gazeli-i-lyas-altuner-ywkco', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tûfân olur ol dem bana bir seyr-i melâlin

Kim açmada gamzende tebessüm-i hilâlin

Âşufte salınır iki yandan iki mercân

Âfâk-ı muhabbetde yüzer kevn-i hayâlin

Endâm-ı nihân hâle olur görse gönül ki

Âlemde cüdâdır bana hep rû-yı cemâlin

Encâma kadeh tutsa elim şeb-i çerâğdan

Üstümde belâdan nicedir aşk-ı mecâlin

Bir parça kelâm eyle safâdan şu gedâya 

Ger çarmıha Îsâ gibi al cân-ı helâlin

Esrâr-ı beyân kû-yı melâmetde nihân mı

Sardın çekemem kahrını bu derd-i mihâlin

Sorsam ki ne âfet ü ne dil-dâr-ı güzînsin

Âsûde olam ''RÂZI'' ise kalb-i visâlin', 'Tûfân olur ol dem bana bir seyr-i melâlin Kim açmada gamzende tebessüm-i hilâlin Âşufte salınır iki yandan iki mercân Âfâk-ı muhabbetde yüze...', ARRAY['Türk Edebiyatı','Şiir','İlyas Altuner']::text[], 8.5, '{"poet":"İlyas Altuner","poet_slug":"i-lyas-altuner","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hilal-gazeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostum', 'dostum-yasar-donmez-rekeb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dost yüzüne hasret kaldım

Yüzün nurlu imiş dostum

Dertli sazım sensiz çaldım

Türkün tatlı imiş dostum

Kapım sessiz kimse çalmaz

Çalan da bir daha gelmez

Kara bahtım bir gün gülmez

Neşem senle imiş dostum

Vermiyor tat, tatlı aşım

Her dem dumanlıdır başım

Neredesin can yoldaşım

Sözün kutlu imiş dostum

Kalem tutan elim yorgun

Yokluğun dert değil vurgun

Sana bütün güller kırgın

Suyun şifa imiş dostum

Mecnuniyim ömrüm boşa

İsyan etmiyorum haşa

Bakma gözümdeki yaşa

Derdin beter imiş dostum

Amma, 

Hasret biter imiş dostum', 'Dost yüzüne hasret kaldım Yüzün nurlu imiş dostum Dertli sazım sensiz çaldım Türkün tatlı imiş dostum Kapım sessiz kimse çalmaz Çalan da bir...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Dönmez']::text[], 8.5, '{"poet":"Yaşar Dönmez","poet_slug":"yasar-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dostum-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emperyalizm', 'emperyalizm-nizar-kabbani-nlpmd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sözüm saçlarına, yetki elde eden

Sömürgeci olmuş da saçların

Deli gibi devamlı koşuyor yalınayak

Ardım sıra koşuyor

Ve dans ediyor etrafımda

Çekiyor üstüme perdelerini

Ben farkında olmadan

Öyle bir gündüz olsa ki

Zalim, kudretli ve etkili

Özür kabul etmeyen bir gündüz

Bu güzel bir hakimiyet terk ettiğim

Lanet ettiğim ve kabullendiğim isteyerek

Sözüm saçlarına, kendini hortumlayan

Yıldızlar görüyorum haber getiren 

Çeviren: İlyas Altuner', 'Sözüm saçlarına, yetki elde eden Sömürgeci olmuş da saçların Deli gibi devamlı koşuyor yalınayak Ardım sıra koşuyor Ve dans ediyor etrafımda...', ARRAY['Türk Edebiyatı','Şiir','Nizar Kabbani']::text[], 8.5, '{"poet":"Nizar Kabbani","poet_slug":"nizar-kabbani","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/emperyalizm-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Postadaki Aşk', 'postadaki-ask-nizar-kabbani-r2hkd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey kadın

Büyük sevgisini postayla gönderen

Sesini

Rimelini

Ve kışkırtıcı kokusunu

Ey kadın

Ey kendisini tanıdığım ve tanımadığım

Durdur, durdur şu yazma işini

Gönderdiklerin hep çocukça

Yazdıkların saçma hep

Yok bunlarda bir kadın

Postayla aşk yapılmaz erkekle

Postayla ancak çocuklar baba olur

Çeviren: İlyas Altuner', 'Ey kadın Büyük sevgisini postayla gönderen Sesini Rimelini Ve kışkırtıcı kokusunu Ey kadın Ey kendisini tanıdığım ve tanımadığım Durdur, dur...', ARRAY['Türk Edebiyatı','Şiir','Nizar Kabbani']::text[], 8.5, '{"poet":"Nizar Kabbani","poet_slug":"nizar-kabbani","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/postadaki-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Oldu', 'ne-oldu-muzaffer-taskirmaz-s7hui', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerinde tüten, sevgi ne oldu

Yaşanan günlerim, kederle doldu

Bu zamanın aşkı, çok basit oldu

İçimde acılar, hiç dinmez oldu

	

Verdiğin o sözler, nereye gitti

Mutluluk hevesim, kayboldu gitti

Ümit dolu gönlüm, birden karardı

Sensizlik canıma, kanıma yetti

Bir gün gelir elbet, beni ararsın

Kalbinde yaşatıp, beni anarsın

Göz yaşını siler, siler ağlarsın

Çektiğim çileyi, o an anlarsın

 “Biliyormusun? Dinmeyen gözyaşım, mercan oldu

Sevda dolu gönlüm, ömrüne mezar oldu

Sonsuza kalan aşkım, sevgi ile doldu

Bak şu gözlerime, seni arar oldu.”', 'Gözlerinde tüten, sevgi ne oldu Yaşanan günlerim, kederle doldu Bu zamanın aşkı, çok basit oldu İçimde acılar, hiç dinmez oldu 	 Verdiğin o ...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-oldu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılmalıyız', 'ayrilmaliyiz-muzaffer-taskirmaz-l0z4e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben doğarken tanrım, yaşama küstüm

Göz yaşım dinmiyor, gözü yaşlıyım

Çektiğim çileler, yetmez mi artık

Gözümde canlandı,  en son ayrılık

Dünyanın derdini, çeken ben miyim

Bir kara sevdalı, olan ben miyim

Bunca sevenler, sevilenler

Alnımıza yazılı, bu son ayrılık

Boş yere yazılmış, alın yazımız

Dertlerle kederle, dolu aşkımız

Mecnun Leyla gibi, çölde dolaşıp

Dua etsek de boş, ayrılmalıyız

 “Ağlasan ne fark eder? şu fani dünyada

Gülmeyi unutma, sevgi ile yaşa

Bir vefasız uğruna, sakın aldanma

Kaderinse neyleyim, çaresizliğini.”', 'Ben doğarken tanrım, yaşama küstüm Göz yaşım dinmiyor, gözü yaşlıyım Çektiğim çileler, yetmez mi artık Gözümde canlandı,  en son ayrılık Dün...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ayrilmaliyiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahtı Karalı', 'bahti-karali-muzaffer-taskirmaz-hiubq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karanlık sokakları, gezip durdum

Bitmeyen yolların, ahını kurdum

Bahtıma yazılan, kara yazgıyı

Yıllarca çektim, çekip durdum

Ben miyim dünyada, çaresiz biri

Ben mi geceleri, uykusuz biri

Ben miyim dünyada, bahtı karalı

Düşünmeden, edemiyorum sabahı

				

Muhabbetle böyle, doyum olmaz ki

Seveni unutma, unutulmaz ki

Yaşamla mücadele, böyle olmaz ki

Yıllarca denedim, unutulmadın', 'Karanlık sokakları, gezip durdum Bitmeyen yolların, ahını kurdum Bahtıma yazılan, kara yazgıyı Yıllarca çektim, çekip durdum Ben miyim dünya...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bahti-karali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmayan Benle Olan Hayalin', 'olmayan-benle-olan-hayalin-zeynel-abidin-toprak-m8w0r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rüzgar, üstüne estiğinde duyarsın belki, 

Fırtınaya savurduğum sözcüklerimi, 

Bir gölün kenarında görürsün belki, 

Suda çözülmüş hayat resmimi.....

Güneşten ruhuma sinen gölgeler, 

Konuşuyor yerlere benim yerime, 

Yokluğun varlığımda ve neyleyim

Varlığım yokluğunda yaşıyorum öylesine, 

Öylesine dalıp dalıp gidiyorum ki

Ben bile tanımakta zorlanıyorum kendimi

Seni ezberlemekten kendimden az hatırlıyorum

Sen de unutmuşsan beni eğer, 

Bilki sen dolusu bir ben batacak, 

Hüzün dağlarının arkasından.

Seni beraber götürmüş olacağım.

Artık olmayan benle olan hayalin; 

Artık yalnız “böyle” ikimiz, 

Artık bu türden bir benle sen kalırız, 

Sonsuzluğun ulu orta yerinde, 

Bir benle sen kalırız; 

Bir ben

Bir sen

Unutuluşta unutma o halde

Bir sen hatırlasa yeter ben için......', 'Rüzgar, üstüne estiğinde duyarsın belki,  Fırtınaya savurduğum sözcüklerimi,  Bir gölün kenarında görürsün belki,  Suda çözülmüş hayat resmi...', ARRAY['Türk Edebiyatı','Şiir','Zeynel Abidin Toprak']::text[], 8.5, '{"poet":"Zeynel Abidin Toprak","poet_slug":"zeynel-abidin-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/olmayan-benle-olan-hayalin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmeyen Aşk', 'bitmeyen-ask-muzaffer-taskirmaz-nnzv1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ah, Ah yıllar geçiyor

Bilinmez dertteyim, inanılmaz ki

Ah, Ah ömrüm bitiyor

Nedir çektiğim, çileler benim

Yaşadım yıllarca, bitmeyen aşkı

Gönülden bağlandım, sevdiğime

Sonunda takıldım, sevgi ağına

Nasılda aldandım, yalan dünya ya

Kalbimde açılan, bir yara gibi

Bu  sevgi uğrunda, yok olmuş biri

Göz yaşım dinmiyor, akan sel gibi

Bir aşk çölünde, esen yel gibi

Şimdi sen uzakta, gurbet ellerde

Yalnızlık çektiren, vefasız yarim

Boynu bükük kalan, yalnızca benim

Bir gönül uğruna, yok olan benim', 'Ah, Ah yıllar geçiyor Bilinmez dertteyim, inanılmaz ki Ah, Ah ömrüm bitiyor Nedir çektiğim, çileler benim Yaşadım yıllarca, bitmeyen aşkı Gö...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bitmeyen-ask-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim İstanbullum', 'benim-i-stanbullum-muzaffer-taskirmaz-kgx0a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hani beni tanımazdın, hatırlar mısın

Telefonda konuştuk, çıkaramadın

Sen beni unutsan da, unutamam seni

O gülüşünü, benim İstanbullum

Hep sen söylerdin, bende dinlerdim

Mazimizde kaldı işte, o mutluluklar

Yıllar geçse bile, unutamam seni

O bakışını, benim İstanbullum

Belki bir gün,  beni hatırlarsın

Maziye geri dönüp de, bir bakarsın

Geçmişi hatırlar, sende unutmazsın

O hüzünlü bakışımı, benim İstanbullum', 'Hani beni tanımazdın, hatırlar mısın Telefonda konuştuk, çıkaramadın Sen beni unutsan da, unutamam seni O gülüşünü, benim İstanbullum Hep se...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/benim-istanbullum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzinsiz Yürüyorum Senin Şehrine', 'i-zinsiz-yuruyorum-senin-sehrine-zeynel-abidin-toprak-004em', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Belki bir gün... başlıklı, nice umutlar; 

Bekleyiş tünelinden, meçhule akar, 

Bütün mutluluğumu toplayan sırlar; 

Bırakır seni bende, bırakıp kaçar.

İsimsiz bir mevsime yol dayamışım, 

İzinsiz yürüyorum senin şehrine, 

İçim der ki orda ben, tanımlanmışım, 

İçtikçe susuyorum senin zehrine.

Renklerin dilindeki geceler yitik, 

Rüyamda kar yağar hep, üşütür beni, 

Resminin uzağına ismim bitişik, 

Renksiz gecelerime düşürür seni.

Anlamakmış anlamı acı çekmenin, 

Ağlamakmış anlamı, son sözcüklerin, 

Alın yazılarında, silgi biter de; 

Aynı kalır silinmez, kadim defterde.

Beklerken seni bil ki, şol sular durur, 

Bekler, bir tek saatte, bütün bir zaman.                                                                  

Bileklerimde nabız; gel! diye vurur, 

Boşalır nesnelerden bütün bir mekan.

İnsana dayanılır gibi gelmez de, 

İçimden dışıma bir senlik sızar.

İçten içe derinden; kan demlese de; 

İliklere bu kandan, bir umut damlar.

Dua dua açılan, bir çift avuçta, 

Dilekler sıra sıra, dudakta bekler.

Düşümde ektiğim bir gül yamaçta, 

Dermek için ellerim, bir izin ister.

İsimsiz bir mevsime yol dayamışım, 

İzinsiz yürüyorum senin şehrine.

İçim derki orda ben, tanımlanmışım, 

İçtikçe susuyorum senin zehrine.

Ne geçmiş, hayatımı, geriye sarar, 

Ne gelecek, konar, seçtiklerime, 

Ne zaman ötesine gitmeye yol var, 

Ne de zamanı yenmek; mümkün gücüme.

Seni hep yürümekle, yollara çizsem, 

Sabırla sabrıma bir, sabır eklesem, 

Sonsuzluktan bir gün, benim olsa da

Sana gelseydim o gün, bir seni seçsem.

Ellerimde bütün bir arz, buharlaştı, 

Elendi varlık; sana, henüz bakmadan, 

Erek dolusu gemim sana yanaştı, 

En güzel aslında bir, seni Yaradan.

Nerdesin yüreğimin, seçtiği dilek? 

Nerde, kabul bekleyen, sımsıcak duam? 

Nerde o bir bakımlık, isimsiz çiçek? 

Nerde gecelerimin gurbeti şuam? ........', 'Belki bir gün... başlıklı, nice umutlar;  Bekleyiş tünelinden, meçhule akar,  Bütün mutluluğumu toplayan sırlar;  Bırakır seni bende, bırakı...', ARRAY['Türk Edebiyatı','Şiir','Zeynel Abidin Toprak']::text[], 8.5, '{"poet":"Zeynel Abidin Toprak","poet_slug":"zeynel-abidin-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/izinsiz-yuruyorum-senin-sehrine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emre Can', 'emre-can-muzaffer-taskirmaz-4zy6z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her gece düşündüm, kalbimde heyecan

Duygumun esiri, sen oldun Emre Can

Bir zaman gelecek, bu şarkı okunacak

Her an seninleyim, üzülme Emre Can

O güzel sesini, duyarım uzaktan

Her gülüşünle, güneşe benzersin

Bir damla göz yaşı, çok bile sana

Her ağlayışında, maniler söylersin

Bir bahar rüzgarı, eser başından

Bir gönül hasreti, geçer bir zaman

Başından geçmeyen, ne anlar aşktan

Kalbimin sevinci, sen oldun Emre Can', 'Her gece düşündüm, kalbimde heyecan Duygumun esiri, sen oldun Emre Can Bir zaman gelecek, bu şarkı okunacak Her an seninleyim, üzülme Emre C...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/emre-can-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kenarsız Yüzeyler', 'kenarsiz-yuzeyler-zeynel-abidin-toprak-gb932', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sesim sensizliğin nehrinde akar, 

En bilmediğim duygular, tanışık şimdi.

Vakit ya hiç geçmemiş yada hiç gelmedi üstümden/üstüme

Geçmişle geleceğin arasına teğetlenmişim. 

İlkin kirpiklerinin gölgesinde serinlendim; 

Lavlı bir kraterden sana akarken, 

İçim bakışlarınla ısındı sonra, merkezine düşerken...

Bir geçmiş düştü sol elimden bilmediğim bir yere, 

İzinsiz duygular hecelendi gelmemiş günlerin anılarında, 

Resmin çiziliverdi birden gönül duvarlarıma...

Suların aktığı yönedir yönelişim, 

Eski günler koşuyor önümde dolu dizgin, 

Ve tersine esiyorum şimdi, 

Güllerin açıldığı ıslak gözlerine ben.

İlişikte sevgim var hiç tadılmamış, 

Leyleklerin gökyüzü özgürlüğünden alınmış; 

İlk uçuşum var sana....

Sana rüyalarımın karelerini getirdim.

Elimin diğerinde de gündüzlerimdeki dalışlarım var sana.

Ne anlatılmazmış bu, baksana saatlerimin tanımlarına...

Sokaklar hep bir adres mi taşır uzaklara? 

Elenir mi gökler gri bulutlardan? 

Verir mi bana seni, mavi sevdalar? 

Giyer miyim senli günleri bu kış? 

İğneler hangi soruları olumlu işleyecek çeyizlerine? 

Levhalar hep bir yöne işaretlidir; 

İsmine remzeden yollardayım ben...', 'Sesim sensizliğin nehrinde akar,  En bilmediğim duygular, tanışık şimdi. Vakit ya hiç geçmemiş yada hiç gelmedi üstümden/üstüme Geçmişle gel...', ARRAY['Türk Edebiyatı','Şiir','Zeynel Abidin Toprak']::text[], 8.5, '{"poet":"Zeynel Abidin Toprak","poet_slug":"zeynel-abidin-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kenarsiz-yuzeyler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluk Aşkım', 'cocukluk-askim-muzaffer-taskirmaz-qews5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayaller kurardım, gençlik çağımda 

Ümitle yaşadım, çocukluk günlerimi

Mazide kalan, en güzel duygularımdın

Çocukluk arkadaşım, ilk aşkımdın

Tebessümlerinle, hep naz ederdin

Güzel bakışınla, beni yakardın

Yıllar gelip geçti, seni bekledim

Sevmeyi ben değil, sen bilmedin

Düşündüğüm tek şey, seninle olmak

Her geçen günümde, beraber olmak

Yalnızlık ruhumun, sevinci değil

Acılar içimde, gömülü değil

Yabancı biriyim, diyorsun bana

Sitemli diyorsun, sen bu hayata

Üzülme diyorsun, tövbekar yaşa

Hayatın tadı yok, gel de sen yaşa', 'Hayaller kurardım, gençlik çağımda  Ümitle yaşadım, çocukluk günlerimi Mazide kalan, en güzel duygularımdın Çocukluk arkadaşım, ilk aşkımdın...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cocukluk-askim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşeyin Sonu Bu', 'herseyin-sonu-bu-muzaffer-taskirmaz-vkfoz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen yoksun inan, gözlerim görmez oldu

Sen yoksun, kulağım duymaz oldu

Sanki bu şehir bana, karanlık oldu

Yıkılmış virane olmuş, her şeyin sonu bu

Başımda dönüyor, aşk heyecanı

O da bak yorulmuş, halinden belli

Neye yarar artık, çaresi yok şimdi

Sanki sonu gelmiş, hiç umudu yok

Bulutlara sen de bak, rengi solmuş

Gözlerimden yine, yaşlar dökülmüş

Benim bu ömrüme, nazar mı değmiş

Dünyanın sonu bu, artık belli olmuş', 'Sen yoksun inan, gözlerim görmez oldu Sen yoksun, kulağım duymaz oldu Sanki bu şehir bana, karanlık oldu Yıkılmış virane olmuş, her şeyin so...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/herseyin-sonu-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gonca Gülsün', 'gonca-gulsun-muzaffer-taskirmaz-236ic', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen kalbimde açan, gonca gülsün

Yıllardır gizledim, senden aşkımı

Yüreğimde coşan, sevda bülbülüsün

İçimde kanayan, sen aşk fırtınasısın

Baharda yeni açan, gonca gülümsün

En büyük aşkımsın, kır çiçeğimsin

Rüyalarımı süsleyen, hayal gücümsün

Bitmek tükenmek bilmeyen, şarkılarımsın 

                

Sevda dolu gönlüm, bir kuşa benzer

Ümit dolu yüreğim, güneşe benzer 

Sevgi dolu günlerim, geçiyor sensiz

Mutluluk sevincimi, yaşarım sensiz', 'Sen kalbimde açan, gonca gülsün Yıllardır gizledim, senden aşkımı Yüreğimde coşan, sevda bülbülüsün İçimde kanayan, sen aşk fırtınasısın Bah...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gonca-gulsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Karanlığı', 'gecenin-karanligi-muzaffer-taskirmaz-1z3x4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir şiir istiyorum sevdiğimden 

Gecenin karanlığı olsun sözün başı 

Bir mektup istiyorum sevdiğimden 

Gece diye başlayan sözcükler olsun 

Çok güzel rüya gördüm 

Sessiz gecelerin karanlığında 

Beyaz gelinlik içinde 

Gecenin karanlığını aydınlattın 

Hep Özlemişimdir seni hayalimdesin 

Sanki yanımdasın bir gölge gibi 

Sabahın olmasını hiç istemem ki 

Keşke bitmeseydi rüya gerçek olsa', 'Bir şiir istiyorum sevdiğimden  Gecenin karanlığı olsun sözün başı  Bir mektup istiyorum sevdiğimden  Gece diye başlayan sözcükler olsun  Ço...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gecenin-karanligi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamıyorum Seni', 'unutamiyorum-seni-muzaffer-taskirmaz-t5muf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Unutamıyorum seni, seni unutamıyorum 

Yıllar gelip geçse bile, unutamam seni 

Gündüz hayalimde, gece rüyamda 

İnan ki bu kalbim, yalan söylemez 

Her geçen gün seni, seni arıyorum 

Bilmiyorum neredesin, sen kiminlesin 

Yıllara geri dön de bak, nasıl yorulmuş 

Geçmişin hatırasını, bağrına gömmüş

Sesini duydum, çok uzaklardan 

Sanki bana yakınsın, yanımdasın 

Yanı başımda bir gölge, dolaşıp durur 

Senin hatıranı, bana anlatır 

''Gözler uzağı görmez derler, sence doğrumu? 

Ama kalp dersen, bunda yanılırsın sen 

Hayatta en güzel şey, sevip sevilmek değil mi? 

Aşk uğruna ihanete uğramak, bence doğru değil 

Kader derler işte buna, kaderine yazılmışsa çekersin 

Bu bilmeceyi ancak sen çözersin.''', 'Unutamıyorum seni, seni unutamıyorum  Yıllar gelip geçse bile, unutamam seni  Gündüz hayalimde, gece rüyamda  İnan ki bu kalbim, yalan söyle...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/unutamiyorum-seni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiçbir Zaman', 'hicbir-zaman-zeynel-abidin-toprak-kmzew', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerim kilitlendiğinde Gözlerine, 

Bir köz alevlenmişti usul usul, 

Gözlerinin tutuşturup yüreğimin körüklediği...

Seddi çatırdamıştı aşk barajının.

Ve dumanlar yükselmişti, 

Sönmüş bir yanardağın kraterinden.

Bir yol uzamıştı önümde; 

Sonu belirsiz...

Sonra ilk izi düşmüştü o yola; 

Alıkoyamadığım ilk adımımdan.

Fırtına günlerinden önce, 

Seni ilk gördüğüm an...

Gördüm etrafımda, 

Eşyanın belirsizleşip yokoluşunu, 

Zeminin kaydığını, 

Ayaklarımın altından.

Bir tek sen kaldın gözlerimin gördüğü, 

Ve bir tek sen kaldın bu sonsuz boşlukta, 

Yörüngesinde döndüğüm, 

Bana yeten tek dünya...

Artık kimsecikler yaşamıyordu bu şehirde.

Sokaklar bomboş.

Artık bendim sokakların serveti bir tek, 

Aşk delisi, sevda sarhoşu bir hoş...

Enleminde uzanıp boylamında yürüdüm senin.

Bulmaya adadım gün aydınlığımı, 

Gecelerimse anmakla geçti seni.

Sonuçsuz arayışlarım sırtımda dağ, 

Odama girdim. 

Varlığının bağıyla bileklerim tutuk, 

Ve dizlerimin bağı, yokluğuna çözülmüş ki; 

Yokluğunun merceğinde sabitlenmişim.

Yüzünün ışığı tam yüreğimin üstünde odak, 

Bense uçmak istemiştim bana acı...

Pencereye baktım, 

Gün batmadan umudumu yitirmemeliyim dedim

Ama umudum, ufuklarında battı sevdiğim! 

Karanlığın çöküşü son defa yüzüme vuracak artık.

Son defa seyretmişim gün doğuşunu meğer.

Meğer o belirsiz yolun sonuna gelmişim sensiz...

Yine de seni düşündüm. 

İlk anı, ilk heyecanı yudumladım yeniden, 

Olmasa da takatim, tebessüm etmeye, 

Yetmese de gücüm, ismini söylemeye...

Göz kapaklarım ağırlaşıyordu son akşamüstü, 

Son defa hayal ettim seni bu akşamüstü sensiz: 

Başucumda saçlarımı okşadın ve ağladın.

Beni anlamıştın artık, bulup yitirmek kadar.

Sıkıca ellerimden tutup bırakma! dedinse de

Düşüverdi ellerim, sıcacık ellerinden.

Ve yarım kalmıştı bu aşk.

Hayali bile.Kimse bilmeyecekti bunu, 

Bunu, sen bile.

Şansımız olmayacak bir daha asla: 

Seni seviyorum.

Demeye benim, 

Duymaya senin.

Hala bilmeyeceğim nerdesin.

Ve bilmeyeceğim ben, 

Aslında hiçbir zaman...', 'Gözlerim kilitlendiğinde Gözlerine,  Bir köz alevlenmişti usul usul,  Gözlerinin tutuşturup yüreğimin körüklediği... Seddi çatırdamıştı aşk ...', ARRAY['Türk Edebiyatı','Şiir','Zeynel Abidin Toprak']::text[], 8.5, '{"poet":"Zeynel Abidin Toprak","poet_slug":"zeynel-abidin-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/hicbir-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlama Acısı', 'anlama-acisi-zeynel-abidin-toprak-8ih12', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anlama acısı bu cana ölüm mayası, 

Gözlerimdeki hüznün cansız yurduna bir bak! 

Çevremde yeşil öksüz bahar ölü kopyası, 

Sensizliğin özümde çarpan nabzıma bir bak! 

Ne nisyana imkan var ne anmaya takatim, 

Hayalindir beynimde çakan bu yıldırımlar, 

Yolların çıkmazında, halimden tek özetim; 

Yokluğunun öldüren bedeli bu sancılar.

Ne ölmeyi bilirim, ne yaşamayı burda, 

Ateşten bir temasla yakıyor bu yalnızlık, 

İnsanlar öldü sanki yeryüzü boşaldı da; 

Bir benim arza kalan en büyük kalabalık.

Ellerin o ellerin kalbimi okşar gibi, 

Duyularımda hâla nefesin sevgi sesin, 

Sanki birazdan yine çıkar gelirsin gibi, 

Hayalimin sılası, özümün gurbetisin.

Merhametine verdim seni Rahim Allah’ın, 

Doğman için yeniden, Muhammed’in yurduna, 

Teslim olmak ne güzel emrine Yaradan’ın

Sana Cennet umarı yalvaran ellerimden..

Ensemin örsünde arz; yontulurken bilinse, 

Bilseydi de insalar, anlamazlık çekilse, 

Ve müjdeyi be anam kor bağrımda gizlesem, 

Vuslat gününe kadar, günlerimi beklesem....', 'Anlama acısı bu cana ölüm mayası,  Gözlerimdeki hüznün cansız yurduna bir bak!  Çevremde yeşil öksüz bahar ölü kopyası,  Sensizliğin özümde ...', ARRAY['Türk Edebiyatı','Şiir','Zeynel Abidin Toprak']::text[], 8.5, '{"poet":"Zeynel Abidin Toprak","poet_slug":"zeynel-abidin-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/anlama-acisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eriyen Zamana', 'eriyen-zamana-ufuk-nazim-gikg9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İpleri kalın ve sıkı sıkıya bağlı.

Beynindeki damarlar kılcallara ayrıldıkça, 

Büyüyordu sorun yumağı.

Sorunlar yumağını koyuyor yastığa, 

Ve başlıyor örmeye hayellerle kazağını.

Onu umutsuz gecelerde, 

Karanlıktan koruyacak, 

Onu yaşatacak.

Ona sarınıp umutla tutunacak, 

Yaşamın en sekter dalınada olsa.

Kaldırımlar ah ayaklarımızın altından, 

Geçip giden zamanın eridiği kaldırımlar.

Yürürken kaldırımların düzenine bakarken

Ve kaldırımların altına akarken zaman, 

Boşunamıydı adımların çabası.

Seni seviyorum, 

Ey hayat.

Tırnaklarım sarardıkça

Ve ufkun kızıllığı tenimden yansırken, 

Gözlerimin altındaki morluklar kadar seviyorum.

Yaşamak, 

Hiç bir zaman tamamlanmamış bir ilişkiye, 

Eksik bir sevişmeye benzeyen yaşamak.

Hangi ressam bitirebilmişki tablosunu, 

Hangi şair bitirmiştirki şiirini.

İşte ne zamanki kara nefesiyle, 

Simsiyah bir yansı gibi kaplansa, 

Ozaman biter tablolar şiirler.

Ve şimdi siyah beyaz bir resmin önündeyim, 

Dolaşık bir sorun gibi renklerin oyunu.', 'İpleri kalın ve sıkı sıkıya bağlı. Beynindeki damarlar kılcallara ayrıldıkça,  Büyüyordu sorun yumağı. Sorunlar yumağını koyuyor yastığa,  V...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/eriyen-zamana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başa Almak Bu Aşkı', 'basa-almak-bu-aski-zeynel-abidin-toprak-309zc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Parçalanmış, yarım aşklarla dolu 

Bir sonsuzluk bu nehirden akıyor

Acı acı akıp giden dalgalar, 

Koskoyu bir bilinmeze çarpıyor.

Her aşkın bir hikayesi yüzümde

Çizgi çizgi gözü alıp gelir de

Anlatılmaz, dayanılmaz, yaşanmaz...

Sabredilmez, alışılmaz, son bulmaz.

Gel bu sevgi böyle olmasın için, 

Gel yapalım her yapılası şeyi.

İlk defa bir aşkın sonu görünsün, 

Mutluluğun son durağı görünsün.', 'Parçalanmış, yarım aşklarla dolu  Bir sonsuzluk bu nehirden akıyor Acı acı akıp giden dalgalar,  Koskoyu bir bilinmeze çarpıyor. Her aşkın b...', ARRAY['Türk Edebiyatı','Şiir','Zeynel Abidin Toprak']::text[], 8.5, '{"poet":"Zeynel Abidin Toprak","poet_slug":"zeynel-abidin-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/basa-almak-bu-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ela Ağlayışlar', 'ela-aglayislar-zeynel-abidin-toprak-yl3jw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayalinle tanışarak başardım ayrılmayı 

Senden.

İstediğin kadar izini kaybet ve arama istediğin kadar.

Ben bir sen edindimki sen bile kıskanırsın. 

Öteki senle çok özgürüm artık.

Bütün engeller hava gibi aşılıyor aramızda, 

Hep istediğimiz gibiyiz özgürlüğün sonsuz kucağında.

Artık seni çekiştiriyoruz öteki senle.

Bir dünya feda etmiştim oysaki sana: 

Bilemediğin kadar bildik

Göremediğin kadar görünen

Kavrayamadığın kadar anlamlı

Senin kadar güzel ve zulmün kadar mahsumdu.

Ayrılığın acısı kadar da sevgi dolu bir dünya.

Senin için bir hayat paketlemiştim ki: 

Ademden son doğan bebeğin arasındaki hayatlar kadar, 

Neyi kaybettiğini anlayamadığın kadar, 

Acımın büyüklüğüyle iftihar ettiğin, 

Yalvarışıma dudak büktüğün kadar.

Bütün sorunları çözdük öteki senle

Seninle çözemediğimiz.

Şimdi bir verandada çayımızı yudumluyoruz beraber.

Hep gülümsüyor. İyiki... dedirtiyor bana, senin, ah keşke... Demen gerektiği kadar.

Ne çıkardı oysa herşeyi feda etseydin bu isimsiz sevgiye, 

Benim herkesin herşeyini feda ettiğim gibi.

Ve bu yüzdendir herkesin toplam acıları kadar çekmişim.

Dayanılmazlığın acımasızlığına terkedilmişim savunmasız Dirençsiz.

Bu yüzdendir bitişlerim başladı; 

İnsan sayısı kadar sonu gelmeyen, 

Bu yüzdendir yüreğim bakılamamacasına parça.

Bir daha görmeyeceksin böylesi bir sevilmeyi 

Yada hiçbir zaman çağına kalacaksın sevilmek için

İlk aramayı neden yaptın beni böyle aratacaksan? 

İşte sonsuz bir sevgide küçülen senlik

Ve işte bu acıyla büyüyen benlik.

En ilgisiz yerlerde bile heyecanla aradım.

Her sözcük ve her eylemde sıra sıra ilgiler uydurdum.

Bir ulaşı olsun için, 

Senden bir çağrışım uyandırtmaya kendimde.

İtirafa direnmeye gücüm yetmiyor: 

Gezdiğimiz her yerde ölüm yaşıyorum peşpeşe.

His yoğunluğundan yokolma noktasında varlığım. 

Duymak istediklerim var, duymanı istediklerim.

Bedene hapsolmuş bir ruhun isyanıyla başedemiyorum artık.

Seni yaşamaya gücümün bittiği yerdeyim

Hayaline razı olmaya başladığım yer...', 'Hayalinle tanışarak başardım ayrılmayı  Senden. İstediğin kadar izini kaybet ve arama istediğin kadar. Ben bir sen edindimki sen bile kıskan...', ARRAY['Türk Edebiyatı','Şiir','Zeynel Abidin Toprak']::text[], 8.5, '{"poet":"Zeynel Abidin Toprak","poet_slug":"zeynel-abidin-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/ela-aglayislar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serseri Sevda', 'serseri-sevda-salih-ozalasan-01d3d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey benim deli gönlüm

Nedir benim senden çektiğim

Yetmedimi? umutsuz aşklara bağlandığın

Serseri bir sevda senin seçtiğin

Ulaşamadın; Ulaşamassın; Ulaşamayacaksın

Asla senin olmaz delicesine sevdiğin

Karanlık Dünya''ma ışık dediğin

Serseri bir yıldız senin seçtiğin

Yağamayacağın dağlara kar olmak senin neyine

Alplerin zirvesi ulaşmak istediğin

Bulutlara hükmetsen ne olacak

Serseri bir bulut senin dolmak istediğin

Çiçekleri seversin; en çok da kardeleni

Ama o dağların zirvesi asla eremediğin

O zirveye ersen ne olacak

Serseri bir Cennet yolunu bile bilmediğin

Yanmışsın; Ey deli gönlüm

Yanmışsınki; alevlerin delip geçmiş arş''ı

Karşıdan bakan ne bilsin, tütüp tütmediğin

Serseri bir itfaiye güzeli senin beklediğin

(Y.Tar.18-12-2002 Saat 12.10)', 'Ey benim deli gönlüm Nedir benim senden çektiğim Yetmedimi? umutsuz aşklara bağlandığın Serseri bir sevda senin seçtiğin Ulaşamadın; Ulaşama...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/serseri-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamadığım Sen', 'anlatamadigim-sen-zeynel-abidin-toprak-kibeh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vaktim olmadı 

Yorulduğumu anlamaya, 

Umudumu yitirmeye

Küresel çırpınışımla ancak, 

Adresinin adresini bulamayacağımı anladım.

Ama ne acı ulaşılmazlık ki, 

Seni bulmak benim hayatımdı.

Çünkü sen, 

Ulaşılmazlığın kadar gereklisin bana.

Biliyorum, 

Adresin, Dünyanın hiçbir yerinde yok.

Sadece sensizlik ikamet ediyor

Bütün dünya evlerinde.

Cadde ve sokaklar çok kalabalık: 

Sensizlik dolu.

Bendeki tek ipucu varolduğundur.

Aslında ben uydurmuşum bu adresi de, 

Benden başka inanan yok buna.

Seni niçin aradığımı biliyorum.

Ama hiç kimse, 

Seni niçin aradığımı bildiğimi bilmiyor.

Kimseye bir şey söyliyemiyorum.

Dünyada olmayan bir dil öğrendi yüreğim ve

Başkaca da dil bilmiyor anlatacak.

Kimse anlayamaz beni, 

Kimsenin ben olmadığı gibi, 

Sözcüklerin kahrolduğu gibi içimde.

Sen, varlık haini bir yok

Ve varlıkta yokluk arayan bir ben.

Çünkü seviyorum olmayan seni

Çünkü aşığım ben, olmayan sana...', 'Vaktim olmadı  Yorulduğumu anlamaya,  Umudumu yitirmeye Küresel çırpınışımla ancak,  Adresinin adresini bulamayacağımı anladım. Ama ne acı u...', ARRAY['Türk Edebiyatı','Şiir','Zeynel Abidin Toprak']::text[], 8.5, '{"poet":"Zeynel Abidin Toprak","poet_slug":"zeynel-abidin-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/anlatamadigim-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Bakan''a Kutlama', 'yeni-bakan-a-kutlama-cazim-gurbuz-lr0wk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İş arayanlar

                  iş bağlayanlar

                                        parti örgütüne bel bağlayanlar

Ricacılar

              çıkarcılar

                            kar uşakları

                                               ilkokuldan arkadaşları

Köy ağaları

                  para babaları

                                        delegeler

                                                      heyetler

                                                             orman kibarları

Bir atımlık merhabası olanlar

                                   dedikoducular

                                          yalan yayanlar

Yerinden atılanlar

                             ipinden kurtulanlar

                                                          partiye katılanlar

Kaşarlanmış bürokratlar

                                      yalancı demokratlar

                                                           binbir suratlar

Ellerinde çiçek cümle kavatlar

                 koltuklamaya

                                      yaltaklanmaya

                                                           otlamaya

                                                                          kutlamaya

gelmişler

               yeni bakan''a', 'İş arayanlar                   iş bağlayanlar                                         parti örgütüne bel bağlayanlar Ricacılar              ...', ARRAY['Türk Edebiyatı','Şiir','Cazim Gürbüz']::text[], 8.5, '{"poet":"Cazim Gürbüz","poet_slug":"cazim-gurbuz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yeni-bakan-a-kutlama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gün Benim Doğum Günüm', 'bu-gun-benim-dogum-gunum-ozgul-ozyilmaz-vwyqn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bugün benim doğum günüm

Bugün şımardığım, 

Şımartılmak istediğim bir gün..

Yeni başlangıçlara, 

Yeni ufuklara hazırlandığım bir gün bugün..

Aslında farklı değil diğerlerinden

Ama dedim ya doğduğum gün işte! 

Ve bugünü başlangıç seçtim kendime

Tıpkı yıllar önce doğarken yaptığım gibi..

Renkler aynı ama ayrı güzel

Dostlar aynı ama ayrı özel

Güneş hep bildik güneş işte..

Ama benim hissedişim başka bugün

Çünkü bugün benim doğum günüm.

Herkesin beni mutlu etmek için çaba sarfettiği bir gün

Herkesin her şeyimi hoş gördüğü bir gün bugün..

Ne güzel! Tüm sevenlerim bir telaşta

Kimi çiçek göndermenin, kimi mesaj çekmenin

Kimi aramanın, kimi de varlığıyla özel günümü paylaşmanın..

Tanrım ne güzel böylesi sevildiğini hissetmek

Ne güzel, beni seven insanların varoluşu

Sevginin sıcaklığı, 

Yüreğime, ta derinlere o sevgilerin dokunuşu..

Gözlerim doluyor, içim titriyor ama acıdan değil, 

Sevinçten, sevgiden..

Yüreğimdeki o en derin köşelere ulaşmayı başaran 

Sevginin başdöndürücü sıcaklığından..

İşte bu! 

Hep istediğim, her daim dilediğim tek şey bu: SEVGİ

Yok başkasında gözüm, 

Yok başka gerçek dileğim

Minicik bir sevgi, 

Minicik bir sıcaklık, 

Ki onlar içimde alev alır, yüreğimi, bedenimi ısıtır

Görünmesede ayaklarım kesilir yerden

Ruhum bir bir başka havalanır..

Tüm evren, tüm dostlar ve canım ailem

Size sonsuz teşekkürler, 

Böylesi güzel bir gün için

Böylesine beni sevdiğiniz, 

Sıcaklığınızı uzak-yakın hissettirdiğiniz, 

Sevgi arsızı yüreğimi böylesine beslediğiniz için..

Evet, bugün benim doğum günüm 

Hepinizi çok seviyorum ve işte dileğim: 

Sonsuza kadar sevgiyle yaşamamızı diliyorum.

7.6.2000', 'Bugün benim doğum günüm Bugün şımardığım,  Şımartılmak istediğim bir gün.. Yeni başlangıçlara,  Yeni ufuklara hazırlandığım bir gün bugün.. ...', ARRAY['Türk Edebiyatı','Şiir','Özgül Özyılmaz']::text[], 8.5, '{"poet":"Özgül Özyılmaz","poet_slug":"ozgul-ozyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/bu-gun-benim-dogum-gunum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi ki Yaşandılar', 'i-yi-ki-yasandilar-ozgul-ozyilmaz-kox5n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İyiki yaşandılar, iyiki vardılar

Ya olmasalardı, ya hiç yaşanmasaydılar

Derinlere inemeseydim

Nasıl bilirdim kanat takıp uçmayı

Yıldızlara uzanmayı? 

Yollarım hep düz olsaydı

Nasıl hissederdim yokuş aşağı yürürken

Rüzgarın beni okşayışını, baştan çıkarışını

Düz bir çizgi olurdu hayat, sıkıcı ve monoton

Zikzaklar çizdim yollarımda

Ormanların derinliklerine daldım

Dikenlerin içinden geçtim, kanadım

Ama yıkılmadım yine kalktım, havalandım.

Yeşil çimenlere uzandım, güneşin batışındaki kızıllığı, 

ağaçların renk cümbüşünü, 

denizin sakinliğini, bazende azmışlığını  yaşadım.

Uçurumlardan yuvarlandım, dağıldım, parçalandım

İçim eridi, yandım ama yılmadım.

Yüreğimdeki bir damla ışığa “imdat” diye sarıldım

Kimi zamansa  yanlızlığımla huzurun tadına  vardım.

İzledim, gözlemledim, dinledim ve yürekten paylaştım, 

Her biriyle ayrı ağladım, ayrı bir sevdayı yakaladım

Her birini ayrı ayrı özümledim

Hep bir dersti aldığım

Evet, iyiki vardılar, iyiki yaşandılar 

Yoksa nasıl anlardım hayatı, yaşamı ve aşkı.

Ne muhteşem, iyiki vardılar, iyiki benimle yaşadılar

Varolduğum sürece de hep benimle olacaklar.

Seni seviyorum hayat, 

Seni seviyorum dünya, 

Ve sizi seviyorum dostlar ve de düşmanlar! 

İyiki varsınız 

Dünya var oldukça da hep var olacaksınız! 

Asla, ama asla ne beni benden, 

Ne de dostları ve  aşkları yüreğimden çalamayacaksınız! 

21 Kasım 1997', 'İyiki yaşandılar, iyiki vardılar Ya olmasalardı, ya hiç yaşanmasaydılar Derinlere inemeseydim Nasıl bilirdim kanat takıp uçmayı Yıldızlara u...', ARRAY['Türk Edebiyatı','Şiir','Özgül Özyılmaz']::text[], 8.5, '{"poet":"Özgül Özyılmaz","poet_slug":"ozgul-ozyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/iyi-ki-yasandilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümit', 'umit-ozgul-ozyilmaz-3y417', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ümit, adı üstünde 

yeşermemiş bir tomurcuk 

suyu-güneşi eksik.

Minik bir kıvılcım, 

rüzgarı-ateşi eksik.

İnançla, 

yıkılmadan ve 

asla teslim olmadan

Tomurcuk çiçeğe, 

kıvılcım ateşe 

ve en son nefese 

ulaşıncaya dek sürecek.

10.04.1996', 'Ümit, adı üstünde  yeşermemiş bir tomurcuk  suyu-güneşi eksik. Minik bir kıvılcım,  rüzgarı-ateşi eksik. İnançla,  yıkılmadan ve  asla tesli...', ARRAY['Türk Edebiyatı','Şiir','Özgül Özyılmaz']::text[], 8.5, '{"poet":"Özgül Özyılmaz","poet_slug":"ozgul-ozyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/umit-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben''den', 'ben-den-ozgul-ozyilmaz-48hy8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben hiç utanmadımki sevgimden, kendimden

Sıkılmadım hiç seni sevdiğimi söylemekten

Korkmadım reddedilmekten! 

Ben sadece sevdim, 

Bıraktım kendimi sevgimin seline 

Dolu dolu, yüreğimce

Bata çıka, güle oynaya dalgalandım.

Hiç saklamadımki sana olan tutkumu

Taptım sana içimden geldiğince

Sevdim seni yüreğim istediğince

Bu Ben’dim ve 

Bendeki Ben olarak seviştim hissettiğimce.

Yoktu kaprisle harcayabilecek zamanım

Anlamsızca gurura feda edebileceğim tek bir An’ım

Kavgayla, hırla gürle çöpe atacak kelâmım! 

Sen varsan bende vardım 

Ve işte o andı en değerli kazancım, kârım..

Kime neydi ne yaptığım? 

Kimin umrundaydı enayi sayıldığım? 

Kim bilelir benden başka gerçek Ben’i? 

Kim tutabilir o manyak, o çılgın içimdeki gizli Ben’i? 

Yok canımıniçi..! Yok! 

Olamaz böyle bir şey! 

Hiç kimse! .. Hiç bir şey bana engel olamaz! 

Bir Sen! Bir Tanrı’dan başka 

Hiç bir şey kalp atışımı sonlandıramaz..! 

Hesap vermem sevdamı kendimden başkasına, 

Sana bile hatta! 

İnanmam, kabullenmem, dinlemem hiç kimseyi

Bir yüreğimden ötesini..

Çünkü en iyi ben bilirim bendekini..

Hayat benim! 

Acılarımda, sevinçlerimde, 

Gün olup göz göz kanayan yaralarımda, 

Kanatlandırıp uçuran aşklarımda, dostlarımda.! 

Her şeyim bana, 

İyisiyle, eğrisiyle bana..! 

Hesabımda bana, sevdam da..

Seni bilemem AMA

Ben memnumum benden 

Yolumu gönlümce çizmekten

Ve seni.. Böylesi sevmekten..!', 'Ben hiç utanmadımki sevgimden, kendimden Sıkılmadım hiç seni sevdiğimi söylemekten Korkmadım reddedilmekten!  Ben sadece sevdim,  Bıraktım k...', ARRAY['Türk Edebiyatı','Şiir','Özgül Özyılmaz']::text[], 8.5, '{"poet":"Özgül Özyılmaz","poet_slug":"ozgul-ozyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/ben-den-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kır Çiçeği', 'kir-cicegi-ozgul-ozyilmaz-60uo7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Başıboş bir kır çiçeği

Diğerlerinden yok bir farkı.

Kendi başına anlamsız, belirsiz

Bazen bir rüzgar alır götürür

Bırakır bir dağın tepesine…

Bazen güneş vurur yüzüne

Bazen de yağmurdan bükülür boynu

Salamaz köklerini derinlere

Çünkü..

O zayıf ve güçsüz

Yetmez gücü kimseye..

Bazen yanlız kalır kendiyle

Farketmez kimse onu

Yetmez ki sesi varlığını hissettirmeye..

Bir an gelir fark eder birisi, ilgilenir

Sevinir, nihayet der..

Sürmez çok uzun bu seviniş

Çünkü

Bir anlıktır bu ilgileniş.. 

Yine yalnız kalır herkesin içinde

Rüzgarın bıraktığı yerde..

Kuşlar, bulutlar, rüzgar, güneş 

Ve yağmurdur onun dostu

Hiç biri unutmaz hep hatırlar onu

Bir de çocuklar

İncitselerde onu bazen, aldırmaz

Çünkü bilir içtendir çocuklar

Kirlenmemiş, saf ve temiz.

Bekler kırçiçeği

Olabildiğince güçlü ve mutlu olarak

Bir gün sıranın kendine gelmesini..', 'Başıboş bir kır çiçeği Diğerlerinden yok bir farkı. Kendi başına anlamsız, belirsiz Bazen bir rüzgar alır götürür Bırakır bir dağın tepesine...', ARRAY['Türk Edebiyatı','Şiir','Özgül Özyılmaz']::text[], 8.5, '{"poet":"Özgül Özyılmaz","poet_slug":"ozgul-ozyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/kir-cicegi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vasiyetim Olsun-1-*', 'vasiyetim-olsun-1-bayram-tunca-qkuny', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mezarımın başında, bir çınar olsun

Bu çınarın, dallarına kuşlar konsun

Gölgesindekiler de konuğum olsun

Gözyaşlarım bu çınara pınar olsun

Çınarın meyvesi küpelerim olsun

Dökülen yaprağı yorganım olsun

Ulu çınarın hışıltıları ninnim olsun

Kökleri emziğim/biberonum olsun

Bu ulu çınar, oksijen çadırım olsun

Kökleriyle yüreğime oksijen dolsun

Bu dünyadaki gözüm/kulağım olsun

Benim de her şeyim ona helal olsun

Soğuğa/sıcağa karşı şemsiyem olsun

Gecelerde, koruyup/kollayanım olsun

Yıldırımlara karşı da paratonerim olsun

Acıktığımda anam gibi emzirenim olsun 

18.08.2002-18.18

Öneli Not: 

Besteye namzet tüm şiirlerim noter tasdiklidir.

İzinsiz yazılı veya görsel basında kullanılamaz.

Beste yapmak isteyeni, çok kolaylık gösterilir.

İrtibat Tel: 0212-639 34 90-', 'Mezarımın başında, bir çınar olsun Bu çınarın, dallarına kuşlar konsun Gölgesindekiler de konuğum olsun Gözyaşlarım bu çınara pınar olsun Çı...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/vasiyetim-olsun-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demek ki+', 'demek-ki-bayram-tunca-qoi78', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Demek ki senin gibisine benim gibisi lazımmış

Demek ki benim gibisine senin gibisi lazımmış

Demek ki kaderimiz böyle yazılmış ta ezelden

Sen beni/ben seni anlamazsak, ne gelir elden

04.09.2002-10:54

''Aşk Ateşten Gömlek''', 'Demek ki senin gibisine benim gibisi lazımmış Demek ki benim gibisine senin gibisi lazımmış Demek ki kaderimiz böyle yazılmış ta ezelden Sen...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/demek-ki-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Güzel Gerçek', 'en-guzel-gercek-ahmet-nadir-caner-9w80r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalnızlık bile çekip gitmiş

Belki de uğramamış bu yerlere

Yorulmuyor taşımaktan geceler

Aydınlıkları doğan her güne

Ve sana özgürlüğüne leke düşmemiş

Dağ başlarındaki yerlerden sesleniyorum

Bu dünya yalan değil...', 'Yalnızlık bile çekip gitmiş Belki de uğramamış bu yerlere Yorulmuyor taşımaktan geceler Aydınlıkları doğan her güne Ve sana özgürlüğüne leke...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Nadir Caner']::text[], 8.5, '{"poet":"Ahmet Nadir Caner","poet_slug":"ahmet-nadir-caner","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/en-guzel-gercek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hey Leylâ*', 'hey-leyl-bayram-tunca-psrth', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aramıyorsam sakın unuttu sanma

Hakkımda kim ne söylerse kanma

Yüreğim senin için atıyor şu anda

Sevgin aynen durmakta bu canda

Sıcaklığın dolaşıyor damarlarımda

Siluetin peyda oldu tam karşımda

Bir gün çıka gelirsem, hiç şaşırma

Geldiğimde sen de fırsatı kaçırma

07.12.2002-12.07', 'Aramıyorsam sakın unuttu sanma Hakkımda kim ne söylerse kanma Yüreğim senin için atıyor şu anda Sevgin aynen durmakta bu canda Sıcaklığın do...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hey-leyla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bil ki*', 'bil-ki-bayram-tunca-bukfn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kalemim ile kağıdımın öpüştüğü her an

Kanımın damarda magma gibi aktığı an

Aşkın yüreğime ak kor misali yaktığı an

Bil ki; o vakit sana aşk şiiri yazdığım an

12.10.2000-12.12', 'Kalemim ile kağıdımın öpüştüğü her an Kanımın damarda magma gibi aktığı an Aşkın yüreğime ak kor misali yaktığı an Bil ki; o vakit sana aşk ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bil-ki-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Türk Milletiyiz', 'biz-turk-milletiyiz-bayram-tunca-54htw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biz anamızın gözyaşlarıyla sulanmışız

Babamızın nasırlı elleriyle okşanmışız

Ninemizin o masallarıyla büyütülmüşüz

Siyasilerimizin vaatleriyle uyutulmuşuz

B. Tunca/06.12.2002-12.06', 'Biz anamızın gözyaşlarıyla sulanmışız Babamızın nasırlı elleriyle okşanmışız Ninemizin o masallarıyla büyütülmüşüz Siyasilerimizin vaatleriy...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/biz-turk-milletiyiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçlarının Lodosunda', 'saclarinin-lodosunda-alaattin-soykan-bwedk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beklenmedik bir rüzgarın

Beklenen mahmuzu değdi

Kişnemeye durdu sular

Bol köpük hasret kişnemeye

Şaha kalkan bir gemiyle 

Ve bir yolcu yola durdu

Sana doğru senden uzak

Saçlarının lodosunda

Dalgalar hoyrat dişidir

Ve uskur belalım erkek

Koyunu rüzgarlı kıl ey yâr

Canciğer kuytu kerempeni

Ve kıyın kavuşmak köpürsün 

Bir gemiyle yaklaşan bu

Sana doğru senden uzak 

Saçlarının lodosunda...', 'Beklenmedik bir rüzgarın Beklenen mahmuzu değdi Kişnemeye durdu sular Bol köpük hasret kişnemeye Şaha kalkan bir gemiyle  Ve bir yolcu yola ...', ARRAY['Türk Edebiyatı','Şiir','Alaattin Soykan']::text[], 8.5, '{"poet":"Alaattin Soykan","poet_slug":"alaattin-soykan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/saclarinin-lodosunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Ne Sevdalar İstedi', 'seni-ne-sevdalar-i-stedi-ahmet-kerem-kaban-sxgb2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geldiğin gibi 

Gittin sevdiğim

Ne güzel yakışmış

Akdeniz güneşi tenine

Ne güzel değmiş

Denizin suyu

Gözlerinde Olympus''tan 

Kalma sevda ateşi

Ne güzel yakışmış

Saçlarına 

Fenike aryaları

Geldiğin gibi gittin

Sevdiğim

Yüzyıllık bir yalnızlık

Oldu bende

Geldiğine sevineyim derken

Gittin

İskenderiye’ye sevdalı gönüllerdi

Her deniz savaşından sonra

Sana gelen

Bir tel saçın 

Senden yastığımmda duran

Gel-gitler yaşarken ben

Antik çağdan kalan

Bir rüya idi benimkisi

Geldiğin gibi gittin

Aklında bildik bir türkü

Yüzünde tanrıçalara yakışan

Bir tebessümle.

		

(26.08.2002)', 'Geldiğin gibi  Gittin sevdiğim Ne güzel yakışmış Akdeniz güneşi tenine Ne güzel değmiş Denizin suyu Gözlerinde Olympus''tan  Kalma sevda ateş...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kerem Kaban']::text[], 8.5, '{"poet":"Ahmet Kerem Kaban","poet_slug":"ahmet-kerem-kaban","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/seni-ne-sevdalar-istedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Temptations', 'temptations-ali-kalayci-48jz3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'I.

ne yeryüzüm oldu seccadelerden

ne kutsandım sihirli sularla ırmak ırmak 

medet beklemedim mucizelerden

mutlanmama yetmedi Tevrat

zani putlar ortasında

inkarlardayım heyhat

II.

baş aşağı bir kuyuya salındım

beni sur kurtaracak

seni sevmek kadar alçak

tövbesi olmayacak

ne varsa geçmişimde

hatta ısrarlarla kamaşan

kızıl bir gül ayrılığın çeperlerinde

bir şiir, 

ölülerden bir im bile

bırakmayacağım

saçım dibe değdiğinde

suları yandıracak

ömrüm kundaklara alışkın bir pankart

beni sur kurtaracak

III.

muteber ölümlerin

tellalıyken her konak

herkesin harcı değil

hem de kanun zoruyla

dirliğe secde durmak

hu ile tekmilde dağlar

meğer vahiy muştulanmış

aynı kıblede umman

''febi eyyi ala-i rabbiküma tükezziban'' 

IV. 

her şirk nöbetinde 

suçüstü

yakalandığım Ahad, 

nicedir nefsime bağışladığın hayat

yüreğimde çirkef aşklar domurtarak

sindirirse sevincimi

beni İbrahim gibi

mihrabınla baştan çıkar

beni adınla aldat..', 'I. ne yeryüzüm oldu seccadelerden ne kutsandım sihirli sularla ırmak ırmak  medet beklemedim mucizelerden mutlanmama yetmedi Tevrat zani put...', ARRAY['Türk Edebiyatı','Şiir','Ali Kalaycı']::text[], 8.5, '{"poet":"Ali Kalaycı","poet_slug":"ali-kalayci","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/temptations-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal', 'hayal-yakub-kavruker-39vn2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zaman olur aklıma hayalin  düşer 

Anlatılmaz bir an olur saniyeler

Kaybedilmiş sevgili üzerine 

Birkaç mısra dökülür ağzımdan, 

Nefesimi duyarım yalnızca 

Kaybetmemek için gölgeni...

Her akşam karanlık hüzne dönüştüğünde

Yıldızlar gözlerimde hırçınlaşır

Ay, deli dolu gülümser gözlerine

Bir bulut sarar ayrılık şehrini, 

Bir kaç damla süzülen yaş

Hayatım oluverir...

Özlem  budur derim kendi kendime 

Kaybedilmiş aşk

Ve namlunun ucundaki umut

İki yamalı kardeş olur, 

Sevgili olur biri birine...

Susuyorum artık...

Kirpiklerim birbirine kenetlenmiş

Yanımdan geçip gidişini izliyorum.

(13.12.2002    23: 30   istanbul)', 'Zaman olur aklıma hayalin  düşer  Anlatılmaz bir an olur saniyeler Kaybedilmiş sevgili üzerine  Birkaç mısra dökülür ağzımdan,  Nefesimi duy...', ARRAY['Türk Edebiyatı','Şiir','Yakub Kavruker']::text[], 8.5, '{"poet":"Yakub Kavruker","poet_slug":"yakub-kavruker","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hayal-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamadıklarım', 'anlatamadiklarim-ali-fuat-futsi-hsmux', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kuşlarda göç etti mevsimsiz bir günde

Ve bir günde bir çok mevsimin olduğu 

Günsüz mevsimler yaşanmaya başlandı

Kuşlar geri dönünde mevsimler günlere değil

Günler mevsimlere karışsın

Bitsin bitmeyen hasretim

Hasretim bitsin diye bilinmezliğe gitsin

Ve bitmek bilinmezlik diye

Hasretimde bitsin', 'Kuşlarda göç etti mevsimsiz bir günde Ve bir günde bir çok mevsimin olduğu  Günsüz mevsimler yaşanmaya başlandı Kuşlar geri dönünde mevsimle...', ARRAY['Türk Edebiyatı','Şiir','Ali Fuat Futsi']::text[], 8.5, '{"poet":"Ali Fuat Futsi","poet_slug":"ali-fuat-futsi","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/anlatamadiklarim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dudağım Kor Yangını', 'dudagim-kor-yangini-mahmut-ucakcan-tb7cy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıllar oldu kapatalı kapıları

Aşk bir uçurumdu

Yüksekliği göz karartıcı

Bu yüksekliğin en güzel yerinde buldum seni

Açtım gözlerimi

Güzel bir gerçekteyim şimdi

Uyumak istemiyorum

Eline dokunmak; 

Öyle bir dokunmak ki

Irmakların coşkusu sanki

Sarılmak; 

Öyle bir sarılmak ki

Tanrıya yaklaşmak gibi...

Şimdi bahar geldi dağlarıma

Bak

Kuşlar cıvıldaşıyor duyuyormusun

Çiçekler en güzel renginde

Ve çocuklar dans etmeyi bekliyorlar

Dudaklarım kor oldu

Dudaklarınla buluşunca

Bir ateş düştü, yangın başladı

Bıraktım kendim yanmaya

İçimi ısıtıyor ateşin

Ve güneş doğuyor ufuklarıma

Ne iyi ettin geldin

Hoşgeldin

Al bu kalp senin

Bu ten, bu dokunuş senin

Ben senin oldum

Ben sen oldum...', 'Yıllar oldu kapatalı kapıları Aşk bir uçurumdu Yüksekliği göz karartıcı Bu yüksekliğin en güzel yerinde buldum seni Açtım gözlerimi Güzel bi...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Uçakcan']::text[], 8.5, '{"poet":"Mahmut Uçakcan","poet_slug":"mahmut-ucakcan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/dudagim-kor-yangini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haykırsam', 'haykirsam-yalvac-ural-2-35yzc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu sensiz ilk akşamım

İçimde bir kavga var

İnan gönlüm acıyor

Bana dargın anılar

Bu akşam sabah olmaz

Tüm saatler duracak

Sensiz zaten ölmüşüm

Gel vur oldu olacak

Alışamam yokluğuna 

Yüreğimi susturamam

Çığlık olur yanar dilim 

Haykırsamda duruyamam', 'Bu sensiz ilk akşamım İçimde bir kavga var İnan gönlüm acıyor Bana dargın anılar Bu akşam sabah olmaz Tüm saatler duracak Sensiz zaten ölmüş...', ARRAY['Türk Edebiyatı','Şiir','Yalvaç Ural 2']::text[], 8.5, '{"poet":"Yalvaç Ural 2","poet_slug":"yalvac-ural-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/haykirsam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-soner-demirez-60kax', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sordum; ey nazlı gül nedir aşk? 

Bana sorma dedi, bülbül bilr aşkı..

Bülbül söyle bana nedir aşk..

Sevdiğin uzaklarda olsada onu sevmektir dedi.

Acı değil mi bu dedim..

Aşk acı çekmektir dedi..

Aşk acı verecekse nerde kaldı mutluluk dedim..

Aşk acıdan haz duymaktır dedi..

Bazen özlemle yanan yüreğine bir damla yağmur...

Bazen çölde esen ılık meltemdir dedi..aşk..

Vuslat varken, hicran neden dedim? 

Hicrandır aşkı sıcvak tutan dedi...

Uzaktan duyulanm bir sesatir dedi..

O duyduğun sesin içine işlemesidir dedi...aşk..

Kardelen''e sordum nedir aşk diye..

Aşk karanlıkların aydılığa kavuşması...

Yüreklerin karanlıktan kurtulmasu dedi...

Çiğ damlası nedir aşk söyle bana...

Gecenin ayazında yağmaktır sevgiliye..

Donacağını bile bile yağmaktır...

Sabah doğan güneşle buhar olacağını bilerek sevmek dedi..

Bir kadın gördüm nedir aşk dedim..

Uzaktaki sevgiliye duyulan özlem dedi...

Onu özlemek onun için yanıp tutuşmak dedi..

Bazen başımmda dolaşan parmakları..

Bazen gözümün içi bir bakışı...

Beni benden alışı belkide beni ben yapışı...

Aşk onu canımdan çok sevebilmek dedi...

Hey ihtiyar derbeder adam aşk nedir? 

Aşk herşeye rağmen sevebilmek delikanlı..

Aklından bir an bile çıkarmamacasına sevmek..

Uğruna ölümü bile göze almaktır aşk...

Sonsuzluğa açılan bir  pencere, 

Duyguların bir öpücükle aldığı alev, 

Tenlerin tenlerde erimesi...

Gözlerden kalplere inan o kaynayan şey..

Fokurdayan kalplerde o heyecan..

Sevdanın alev almasıdır aşk...

Ya delikanlım işte aşk denen güzellik..', 'Sordum; ey nazlı gül nedir aşk?  Bana sorma dedi, bülbül bilr aşkı.. Bülbül söyle bana nedir aşk.. Sevdiğin uzaklarda olsada onu sevmektir d...', ARRAY['Türk Edebiyatı','Şiir','Soner Demirez']::text[], 8.5, '{"poet":"Soner Demirez","poet_slug":"soner-demirez","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/ask-118-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep O Türkü', 'hep-o-turku-ahmet-murad-0aj1u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bakışların hasret yüklü

Dudagında hep o türkü

Bunlar dökülen son yapraklar hayat ağacından

Bir volkan fışkıracak yarın, beyin bakracından

Hep seni söyleyecek şarkılar, 

Hep seni anlatacak masallar, 

Hep seninle yoğrulacak insanlar.

Birgün gönlüne düşeceksin o zalim dağların, 

Belki taht kuracaksın kalbinde yaldızlı çagların, 

Seslenecek vatana senin özleminle martılar, 

Kükreyecek seninle, ses olacak mırıltılar, 

Unutulacaksın belki zamanla uzak beldelerde

Ancak yaşayacaksın burada hep kalplerde

Senin hasretin bizim hasretimiz olacak

Sana bakan kem gözler bakışımızla donacak

Gidince sen ağlayacagız çığlık çığlığa

Gömülecek etrafımız kör karanlığa

Üzerine sardığımız şu son bayramlığa

Sevdanı yazacağız, o bitmez aşkını kazacağız

Seni yaşadıkça anlatacak, anlattıkça yaşayacağız

Bakışların sevda yüklü 

Dudağında hep o türkü', 'Bakışların hasret yüklü Dudagında hep o türkü Bunlar dökülen son yapraklar hayat ağacından Bir volkan fışkıracak yarın, beyin bakracından He...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Murad']::text[], 8.5, '{"poet":"Ahmet Murad","poet_slug":"ahmet-murad","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hep-o-turku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yelken', 'yelken-mehmet-ali-kadakal-ck3yr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevdanın kıyısında durmuştum

Yelkenler hazırdı gerilmeye

Her şey seni beklerken yolculuklara

Sen kumdan kuleler yaptın çocuklara

Sahilde çekirdek çıtlatmayı

Tercih ettin nedensizce

Dolu yelkenlerle dümen tutmaya

Sorumluluk ağır dedin

Hem yelken açmak da zor iş

Oysa çok iyi bilirdin

Dümende hep benim olduğumu fırtınalarda

Ve hep benim yelken bastığımı

Lodoslarda bir başıma

Sen sadece durgun sularda 

Ve güneşli havalarda çıkardın güverteye

Seni çocuklara bırakıp 

Demir aldım martılarla

Madem ki sevemedin denizleri

Tüm karalar sana kalsın 

Elbet bir denizci bulunur

Varılan limanlarda', 'Sevdanın kıyısında durmuştum Yelkenler hazırdı gerilmeye Her şey seni beklerken yolculuklara Sen kumdan kuleler yaptın çocuklara Sahilde çek...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kadakal']::text[], 8.5, '{"poet":"Mehmet Ali Kadakal","poet_slug":"mehmet-ali-kadakal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yelken-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Fayda', 'ne-fayda-ozan-rari-l7xuf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sanki o sihir gitmiş gibi üzerimden

Kaldım yine bir başıma eskilerde olduğu gibi! 

Anladım sandım hayat böyle gidiyormuş demek

Ama ne fayda! 

Sanıyordum ki artık hep başarı gelecekti, hiç umudumu kaybetmeyecektim

Arınmıştım sanki uğursuzluktan, talihsizlikten keşke olsaydı öyle ama ne fayda! 

Halim ortada perişanım 

Kafam yine doldu lüzumsuzluklarla

Elimde olan ipler çektiler kendilerini benden birer birer

Bir yandan ölüm yok sonunda diyorum 

Hayat öyle yada böyle geçer ama? 

İşte belirsizlik çıktı karşıma yine yeniden! 

Pişman olmak ne kadar kötü bir şey olsa gerek

kurulu düzeni terk etmek, bırakmak 

Her taraf sisli göremiyorum önümü tanrım...

Herşey güzel olsaydı bende mutlu olabilseydim keşke

Gönlüme göre insanlara arkadaşım, aşkım hatta dostum diyebilseydim

Basamakları tek tek çıkabilseydim keşke!', 'Sanki o sihir gitmiş gibi üzerimden Kaldım yine bir başıma eskilerde olduğu gibi!  Anladım sandım hayat böyle gidiyormuş demek Ama ne fayda!...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ne-fayda-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmiyorum', 'sevmiyorum-yavuz-turhan-x1jsm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevmiyorum; 

Sensizliği.

sensizliğin, bir karabasan gibi, 

üzerime yüklediği geceleri...

      Sevmiyorum; 

Rakı sonrası sarhoşluğum da, 

senin uzaklarda oluşundan, 

doğan öfkemi...

       Sevmiyorum; 

hasret kokan türkülerin sessizliğin de, 

sensizliği....

        Sevmiyorum; 

Saçlarının kokusunun, 

güllere sinmesini...

         Sevmiyorum; 

Ayrılık dakikaların da, 

yeniden özlemi düşünmeyi...

          Sevmiyorum, 

Her an gelecekmişsin gibi, 

köşe başlarında beklerken, 

it gibi titremeyi...', 'Sevmiyorum;  Sensizliği. sensizliğin, bir karabasan gibi,  üzerime yüklediği geceleri...       Sevmiyorum;  Rakı sonrası sarhoşluğum da,  se...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Turhan']::text[], 8.5, '{"poet":"Yavuz Turhan","poet_slug":"yavuz-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevmiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durmuşum Bir Yol Kenarında', 'durmusum-bir-yol-kenarinda-melih-coskun-iz0gk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Durmuşum bir yol kenarında

Kendimi arıyorum gecenin içinde

Bulamıyorum

Gece uzun 

Gece karanlık

Hüzün nöbetim gelmiş

Bir şarkı söylemek istiyorum

Gecenin en karanlık yerinde

Sabahın en çok yaklaştığı an.

Ve güneşi ilk ben karşılamak istiyorum

Güneşle birlikte doğmalı umutlarım

Dostum, her ne olursa olsun sana da doğmalı güneş

Bilmelisin ki yarın sen olamasan da 

Ülkenin üzerine yine doğacak güneş

Işık saçacak aşsız evlere

Girecek karanlık bir hapishanenin daracık penceresinden

Sevinecek bir gün, çıplak ayaklarıyla kaldırımları aşındıran 

Şu yoksul çocuk, 

Birileri yine çılgınca sevecek birbirini

          

Ve kardeşim sen ki taşımalısın bu ışığı yanında 

En karanlık zindanda bile

Işık senin içindedir.

Yüreğinde...

31 Mayıs 2002

23: 22', 'Durmuşum bir yol kenarında Kendimi arıyorum gecenin içinde Bulamıyorum Gece uzun  Gece karanlık Hüzün nöbetim gelmiş Bir şarkı söylemek isti...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/durmusum-bir-yol-kenarinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey İstanbul', 'ey-i-stanbul-melih-coskun-gbvh4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey İstanbul

Çocukluğum, gençliğim

İlk heyecanım

İlk deniz kokusu

İlk martılar 

Ve ilk fark edişim yeryüzünü

İlk düşünüşüm 

İlk kez duyuşum ayrılığın hüznünü

İlk ezilişim, 

İlk baş kaldırışım, 

Sende sevdim hasretleri

Sevdim kederlenmeyi

Ölümü de sende gördüm, hayatı da

Ve karanlığı gördüm sende 

Karanlık sokaklarının yutuşunu insanları

Ve çocukları gördüm sen de

Gözleri güneş gibi parlayan çocukları

O güzel gözleri gördüm

Ve sefaleti gördüm 

Halkımın açlıktan kokuşmuş nefesinde

Ben sende kendimi gördüm

Bir sabah belki yine

Şiirler okuruz bu denize karşı

O martılar duruyorsa yine aynı yerde 

26.06.2002

00: 40', 'Ey İstanbul Çocukluğum, gençliğim İlk heyecanım İlk deniz kokusu İlk martılar  Ve ilk fark edişim yeryüzünü İlk düşünüşüm  İlk kez duyuşum a...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ey-istanbul-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soldu Bugün', 'soldu-bugun-melih-coskun-2rr1s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Soldu bugün 

Döktü bütün yapraklarını

Yurdumun meyve vermeyen tek ağacı

Niye dikmişlerdi ki zaten onu oraya

Gözü pek çocuklarının çıkıp ta 

İnmeyi başaramadıkları tek ağacı

Neden dikmişlerdi zaten

En güzel şiirler yazılsın diye mi son akşamlarda

Yok etmek için mi bir dost gülüşü? 

Peki nasıl susar haykırışı 17’sinde asılanın

Son sigara kahrolmaz mı şimdi

Keşke hemen tükenmeseydim diye

O çingene bulabilecek mi artık 

Kaybettiği şahsiyetini

Artık çiçek açar mı o darağacı

Ve söyleyin 

Kim geri getirebilir 

Kaybedilen dostların gülüşlerini...

01 Eylül 02

00: 17', 'Soldu bugün  Döktü bütün yapraklarını Yurdumun meyve vermeyen tek ağacı Niye dikmişlerdi ki zaten onu oraya Gözü pek çocuklarının çıkıp ta  ...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/soldu-bugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha Genciz', 'daha-genciz-melih-coskun-49075', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Daha genciz 

Daha çok türkü söyleriz

Daha çok şiir yazarız hayata dair

Daha çok gecelerimiz olur

Ve yine severiz 

Yine ağlarız 

Ve yine umut ederiz inadına

Yine şükrederiz yaşadığımıza

Hayaller kurarız kafamızda

Bir mutluluk fikri tasarlarız beynimizde

Bir sabah bir yürek ihtilaliyle uyanır bir yürek

Daha bir anlam kazanır renkleri bütün doğanın

Deniz daha bir mavi

Ağaç daha bir yeşil

Yüreğine ateş düşer bir şairin

Kurtuluş günlerinin sevinci gelir aklına

Birdenbire bir tebessüm belirir bir çocuğun gözlerinde

Sözcükler daha bir güzelleşir.

Mutlu günlere inanan çocuklar

Çıkıp gelirler bir akşamüzeri ansızın

Türküler söylerler...

Ve türküler söyleriz

Çünkü daha genciz 

Yaşıyoruz 

Ve daha çok türkü söyleriz....

31 Ağustos 2002

00: 52', 'Daha genciz  Daha çok türkü söyleriz Daha çok şiir yazarız hayata dair Daha çok gecelerimiz olur Ve yine severiz  Yine ağlarız  Ve yine umut...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/daha-genciz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tut ki Hücredesin', 'tut-ki-hucredesin-melih-coskun-l4xo7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tut ki birinci şubenin en iğrenç hücresindesin

Ve bekliyorsun işkencecini

Derin bir karanlık içindesin

Yalnızsın ıssız bir ada gibi

Yine de kaybetmeyeceksin umudunu

Işığını saklayacaksın yüreğinde

Senin ışığını çalmak isteyecekler

Ve başarırlarsa bunu

Yarın güneş bile aydınlatamayacaktır seni.

Sen ki gecenin en karanlık anında bile 

Bir yerlerde sabah olduğunu düşünmelisin

Ölürken, düşüneceksin yine birilerinin doğduğunu

Ayrılırken sevdiğinden, kavuşanları düşüneceksin

Esirsen, hürriyeti düşüneceksin

Seveceksin yarınını, 

Seveceksin umudu...

26 Mayıs 2002

15: 40', 'Tut ki birinci şubenin en iğrenç hücresindesin Ve bekliyorsun işkencecini Derin bir karanlık içindesin Yalnızsın ıssız bir ada gibi Yine de ...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/tut-ki-hucredesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suskunluğum Haykırışımdır', 'suskunlugum-haykirisimdir-melih-coskun-9fk0p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Suskunluğum haykırışımdır.

Sessiz görünsem de

Bağırıyorum 

Hem de avazım çıktığı kadar

Mümkün müdür? 

Gözlerinle 

Gözlerinle “kahrolsun” diye bağırabilmek

Gözlerinle 

Seni seviyorum diyebilmek

Öyle yüksek bir sesle bağırıyorum ki

Siz bile duyamazsınız beni

Siz ancak küçük haykırışları işitebilirsiniz

En büyük isyandır kimi zaman sessizlik

Bir muhtıra veriyor eşsiz derin gözlerimiz

Sorgula kendini 

Bunu görebilecek kadar temiz midir yüreğin? 

Sen de haykırabilir misin benim gibi

Kimseler duymadan...

1 Ekim 2002

20: 52', 'Suskunluğum haykırışımdır. Sessiz görünsem de Bağırıyorum  Hem de avazım çıktığı kadar Mümkün müdür?  Gözlerinle  Gözlerinle “kahrolsun” diy...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/suskunlugum-haykirisimdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-ali-niku-c1t77', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hava puslu, nem de var üstelik

kış mevsimi kasvetiyle ünlüdür

içiniz daralır, ruhlar firar eder

ağızdaki lezzet eskisinden de beter

aşkların bile tadı yoksa eğer

sen özlemi yaşıyorsun birader...', 'hava puslu, nem de var üstelik kış mevsimi kasvetiyle ünlüdür içiniz daralır, ruhlar firar eder ağızdaki lezzet eskisinden de beter aşkların...', ARRAY['Türk Edebiyatı','Şiir','Ali Niku']::text[], 8.5, '{"poet":"Ali Niku","poet_slug":"ali-niku","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ozlem-87-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'şehre yeni bir adam geldi', 'sehre-yeni-bir-adam-geldi-rabia-can-ulas-jyi5z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hüzün böyle derbeder yağmasaydı, 

belki olmazdı böyle

içimde tek bir taş oynamazken

kabuğum böyle değişmezdi

bu şehre yeni bir adam gelmezdi

savaş açmazdı kimse tüm kovboylara

dekman oynamazdık hayatla

ve yalan bir oyunda

olmayan bir silahla

vurulmazdım

şimdi ölüyüm

bu oyunu oynamazdım..

seni bunca sevdiğimi bilseydim

yada başka birini

bu kadar sevebileceğimi hissetseydim

vurulmazdım böyle

ölmezdim bunca genç

ama yitirdim tüm gerçegimi

ve kendi nemimle oluşan bulutla doldurdum

ömrümün namlusunu

kararsız bir anevrizma kıldım beynime 

sakladım sonsuz girintilerinde, 

istesemde bulamam

o saatli bir bomba

patlar ve giderim

kente gelen yeni adam gibi.', 'hüzün böyle derbeder yağmasaydı,  belki olmazdı böyle içimde tek bir taş oynamazken kabuğum böyle değişmezdi bu şehre yeni bir adam gelmezdi...', ARRAY['Türk Edebiyatı','Şiir','Rabia Can Ulaş']::text[], 8.5, '{"poet":"Rabia Can Ulaş","poet_slug":"rabia-can-ulas","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sehre-yeni-bir-adam-geldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bir Uyusam Bir Uyansam', 'ben-bir-uyusam-bir-uyansam-reha-basogul-6rn2i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben bir uyusam

gözlerim kapansa

yalnızlık sussa

insanlar ağlamasa

dünya dursa

kimseler konuşmasa

Ben bir uyansam

gözlerim kapansa

yalnızlık sussa

insanlar ağlamasa

dünya dursa

kimseler konuşmasa', 'Ben bir uyusam gözlerim kapansa yalnızlık sussa insanlar ağlamasa dünya dursa kimseler konuşmasa Ben bir uyansam gözlerim kapansa yalnızlık ...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-bir-uyusam-bir-uyansam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostum Stelio', 'dostum-stelio-zerrin-oktay-utp3r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen ölürken ben...

konforlu bir trenin içinde

akıp giden anıları izliyor

ve özlüyordum sadece...

Sen ölürken ben...

odamın bir köşesinde

sana mektup yazıyor

ve yaşıyordum sadece...

Sen ölürken ben...

o sevimli sokaklarda

ve korudaki patikamızda

yürüyordum sadece...

Sen ölürken ben...

kocaman bir sincaba bakıp

''muhteşemsin! '' diye haykırıp

gülüyordum sadece...

Sen ölürken Stelio, 

karşıki taraftaydın...

ve ben... giden can dostuma

ağlıyordum sadece...', 'Sen ölürken ben... konforlu bir trenin içinde akıp giden anıları izliyor ve özlüyordum sadece... Sen ölürken ben... odamın bir köşesinde san...', ARRAY['Türk Edebiyatı','Şiir','Zerrin Oktay']::text[], 8.5, '{"poet":"Zerrin Oktay","poet_slug":"zerrin-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dostum-stelio-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yangınlarda Yüreğim', 'yanginlarda-yuregim-mehmet-caner-sumengen-exiw7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İki parmağımın arasında bir sigara

Aklımda ise sen varsın.

Gittin gideli bil ki geceler hep kapkara

Işığımı çalan yarsın.

Yar...Yar...Yar...

Yangınlarda yüreğim

Yar...Yar...Yar...

Ölmek üzereyim...

Vurulmuş bu kalbim, gözlerin benim katilim

Sevgisizlik tüm nedeni.

Andıkça maziyi yaşarım yüksek gerilim

Ruhum terketti bedeni.

Yar...Yar...Yar...

Yangınlarda yüreğim

Yar...Yar...Yar...

Ölmek üzereyim...', 'İki parmağımın arasında bir sigara Aklımda ise sen varsın. Gittin gideli bil ki geceler hep kapkara Işığımı çalan yarsın. Yar...Yar...Yar......', ARRAY['Türk Edebiyatı','Şiir','Mehmet Caner Sümengen']::text[], 8.5, '{"poet":"Mehmet Caner Sümengen","poet_slug":"mehmet-caner-sumengen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yanginlarda-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuslat', 'vuslat-guney-dirimi-xxbta', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nicedir bu bayrak sallamalar

Alı, sarısı, beyazı

Ve ne gemiler geçer bu yürekten hasbelkader

Kah yelkenleri fora, kah gönülleri alabora

Divit yazısı zerafetinde, kalbi sütliman

Ve ruh sessizliğinde 

Gözleri diline muktedir kadınlar ararken biz

Hala vuslatı mı bekleriz? 

Onu bile kestiremeyiz.', 'Nicedir bu bayrak sallamalar Alı, sarısı, beyazı Ve ne gemiler geçer bu yürekten hasbelkader Kah yelkenleri fora, kah gönülleri alabora Divi...', ARRAY['Türk Edebiyatı','Şiir','Güney Dirimi']::text[], 8.5, '{"poet":"Güney Dirimi","poet_slug":"guney-dirimi","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/vuslat-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtiraf', 'i-tiraf-ozgur-arslan-n794k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gece ve uykusuzluğun dostluğu, 

Sen gece ve karanlık, 

Ben uzaklardaki yanlızlık.

Senden öncesi ve sonrası, 

Eskisi aydınlık, 

Şimdi ise karanlıkta umuda bir bakış.

Eskiyi özlüyorum, 

Artık senden kaçıyorum, 

Kurtulamıyor, yeniden gece ve karanlık.

Eskinin bıçak yaraları, kurşun izleri, 

Şimdi senin için kanayan yaralar, 

Kalbime zehir saçan kurşunlar.

Seninle başlayan gece, 

Ay ışığı, yıldızlar, soğuk esen rüzgar, 

Yaralarını saran ben, 

Dönmenden umutsuzluğa düşmüş, zehirlenmiş bir kalp.

Git artık gece perisi, 

Eski sevginin yerinde nefret var, 

Artık geceyi aydınlatacak, 

Gündüzünü arayan bir ben var.', 'Gece ve uykusuzluğun dostluğu,  Sen gece ve karanlık,  Ben uzaklardaki yanlızlık. Senden öncesi ve sonrası,  Eskisi aydınlık,  Şimdi ise kar...', ARRAY['Türk Edebiyatı','Şiir','Özgür Arslan']::text[], 8.5, '{"poet":"Özgür Arslan","poet_slug":"ozgur-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/itiraf-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok Olan Benim', 'yok-olan-benim-muzaffer-taskirmaz-ruzym', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şimdi sen uzakta, gurbet ellerde

Yalnızlık çektiren, vefasız yarim

Boynu bükük kalan, yalnızca benim

Bir sevda uğruna, yok olan benim

Göz yaşım dinmiyor, akan sel gibi

Bir aşk çölünde, esen rüzgar gibi

Kalbime açtığın, bir yara gibi

Bir sevda uğruna, yok olan benim

Üzerimde kara bulutlar, gitmek bilmiyor

Benim bu dertlerim, bitmek bilmiyor

Kalbim karardı, aydınlık bilmiyor

Dertli yüreğim uğruna, yok olan benim', 'Şimdi sen uzakta, gurbet ellerde Yalnızlık çektiren, vefasız yarim Boynu bükük kalan, yalnızca benim Bir sevda uğruna, yok olan benim Göz ya...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yok-olan-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Hasrete', 'bu-hasrete-muzaffer-taskirmaz-10ngg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yürek mi dayanır bu hasrete

Çektiğimi bir ben bilirim

Yıllar aldı seni benden kopardı

Artık dayanamam yalnızlığa

Ümitlerim yok olup gitti

Sevdiklerim terkedip gitti

Şimdi çıkmaz sokağa girdim

Geçmişi kalbime gömdüm

Daha böylesini hiç görmedim

Kara bulutlar var üzerimde

Sen şimdi neredesin bilemem ki

İçimi bir korku sardı şimdi', 'Yürek mi dayanır bu hasrete Çektiğimi bir ben bilirim Yıllar aldı seni benden kopardı Artık dayanamam yalnızlığa Ümitlerim yok olup gitti Se...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bu-hasrete-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selam Var Sana', 'selam-var-sana-muzaffer-taskirmaz-9iv6h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çok uzaklardan esti rüzgar   

Rüzgarın sesi öyle etkiledi ki

Yaklaştı uzaktan,  bir sevgi ile

Söyledi sevgiliden, selam var sana

     

Sanki sesini duydum, esen rüzgardan

Bir umut bekliyorum, ben yarimden

Bir anda kayboldu, o güzel sesin

Şaşkın aşıklar gibi, kahroldum sevgilim

Ömrümde bu kadar, olmadım telaşlı

Neden böyle kaderli, huzurlu değil

Sana olan özlemimdir, belki budur telaşı

Seni çok özledim, anla beni bir tanem', 'Çok uzaklardan esti rüzgar    Rüzgarın sesi öyle etkiledi ki Yaklaştı uzaktan,  bir sevgi ile Söyledi sevgiliden, selam var sana       Sanki...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/selam-var-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Sevgilim', 'canim-sevgilim-muzaffer-taskirmaz-7r932', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilemezdim bu kadar, zor olacağını 

Anladım hayat, bu kadar kolay değil

Kimi hüzünlü, kimi sevinçli hayatta

Dönüyor dünya, bilmiyorum niçin

Kalbime doğdu, bir hüzün şimdi

Ne aşkın tadı var, ne de heyecanı

Fakat düşündükçe, o eski anıları

Seni hala seviyorum, canım sevgilim

Bir umut bekliyorum, gelecek günlerden

Sanki dünyanın sonu bu, bilemiyorum

Dertliler diyarından, sana haber var

Seni çok seviyorum, canım sevgilim', 'Bilemezdim bu kadar, zor olacağını  Anladım hayat, bu kadar kolay değil Kimi hüzünlü, kimi sevinçli hayatta Dönüyor dünya, bilmiyorum niçin ...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/canim-sevgilim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabret Sevgilim', 'sabret-sevgilim-muzaffer-taskirmaz-o8f5m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O güzel sesini, duyduğum an

İçime düştü, hasretliğin senin

Sanki yıllardır, hasretim sana

Bir günüm sanki, yüz yıl gibi

Konuşmakla olmuyor, hasret gidermek

Anlatmakla bitmez ki, güzel muhabbet

Sabretmek gerek, sana kavuşmak için

Seni çok özledim, hasretim sana

Ayrı bir dünya da, yaşıyoruz sanki

Sevgiden aşktan, yoksunuz şimdi

Bende biliyorum, gurbetlik bu

Sabret sevgilim, bu da biter biliyorum', 'O güzel sesini, duyduğum an İçime düştü, hasretliğin senin Sanki yıllardır, hasretim sana Bir günüm sanki, yüz yıl gibi Konuşmakla olmuyor, ...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sabret-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Çok Özledim', 'seni-cok-ozledim-muzaffer-taskirmaz-vh1zo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İşte böyle geçti, bu gençlik çağım

Hüzün kederler dolu, her anım

Bu düşünceler, boynumu büktü

Hayalimden gitmiyor, eski günlerin

Dudaklarım sana, bir şeyler söyler

Bunu ben çözemedim, çok uğraştım

Sordum kendi kendime, kim bilir cevabını

Söyledi sevgili yar bilir, bir başkası bilemez

Sonun da anladım, çözdüm bilmeceyi

Sana ben kapıldım, yok ki bir başkası

Cevabını sana şimdi söylüyorum

Seni çok seviyorum, seni çok özledim', 'İşte böyle geçti, bu gençlik çağım Hüzün kederler dolu, her anım Bu düşünceler, boynumu büktü Hayalimden gitmiyor, eski günlerin Dudaklarım ...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-cok-ozledim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garibin Çilesi', 'garibin-cilesi-muzaffer-taskirmaz-6u0qv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beni kahrından, sen öldüreceksin

Sevgilim ne olur, bırakma beni

Ayrılırsak zor gelir, terk etme beni

Sevgilim ne olur, üzme sen beni

Garibin çilesi bu, hep böyle olur

Sevenler ayrılır, kader kahrolur

Sevmişte terkedilmiş, sonu ne olur

Olanlarsa gariplere, kime ne olur

Geçmişi bir hatırla, bir an sevgilim

O eski duygular, kaybolmuş gitmiş

Hayal kurardık, biz o günlerde

Şimdi ise ne oldu, mazisi kaldı sevgilim', 'Beni kahrından, sen öldüreceksin Sevgilim ne olur, bırakma beni Ayrılırsak zor gelir, terk etme beni Sevgilim ne olur, üzme sen beni Garibin...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/garibin-cilesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Zalimin Eseri', 'bir-zalimin-eseri-muzaffer-taskirmaz-tuq0z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Manasızca bir haykırış koptu dudaklarımdan

Gözlerimden dökülen bir kaç damla yaş

Büyük bir ayrılığın ağlayışı, bedenim yığıldı bir köşeye

Beynimse, senden başkasını düşünmez oldu

Kalbimde dev alev yanan gençlik ateşi

Ardından bakarken yavaş yavaş söndü

Birden sensizliğimle irkildim 

Artık ayakta bir enkaz yığını kaldı

Tel tel ağaran saçlarım dökülmüş

Yaşlar süzülen gözlerim buruşmuş

Dimdik duran o canlı insan çökmüş

Ellerim titremekli, şimdi saltanatı yıkılmış kral gibi

Yavaş yavaş yürüyorum boş sokaklarda

Kararan bulutlar sanki bana acımış gibi

Salıyor yağmur zerreciklerini üzerime

Bir ben ağlıyorum, birde bulutlar

''Ve ıslanmış bedenim, düşüyor yol ortasına

Şimdi yağmur ortasında yatan kişi

Senin gibi bir zalimin eseri

Dudaklarımdan son iki kelime çıkıyor

Mutluluklar sevgilim, sana mutluluklar''', 'Manasızca bir haykırış koptu dudaklarımdan Gözlerimden dökülen bir kaç damla yaş Büyük bir ayrılığın ağlayışı, bedenim yığıldı bir köşeye Be...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-zalimin-eseri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünüyorum', 'seni-dusunuyorum-muzaffer-taskirmaz-6zh5y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geçenlerde bir haberini aldım 

Acılardan acı, beterlerden beter 

Unutmazsın derken, unutulmuşum

Hatırlayamamışsın, güzelim beni

Bir kerecik düşün ve, gözlerinin önüne getir

Gecenin mateminde, herkes tatlı bir uykudayken

Gecenin sessizliğinde sabahın olmasını beklerken

Ben yaşlı gözlerimle, seni düşünüyorum

Şimdi sen belki de, bir başkasıyla birlikte

Eski hatıralarını, maziye gömmüş birisin

Sıcak bedenini, kim bilir kimler sarıyor

Seni seviyorum, dediğim kulaklarına kim bilir', 'Geçenlerde bir haberini aldım  Acılardan acı, beterlerden beter  Unutmazsın derken, unutulmuşum Hatırlayamamışsın, güzelim beni Bir kerecik ...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-dusunuyorum-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağma Yağmur', 'yagma-yagmur-muzaffer-taskirmaz-4618p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine yağmur yağıyor, benden intikam alırcasına

Sanki bilmezden geliyor, yaşadığımız aşkı

Bir yağmurlu günde ayrıldığımızı o da biliyor

Yağma yağmur artık dur, gözlerimden akan yaşlar

Nice topraklar ıslatır, hep onu hatırlatıyorsun bana

Onun karşısında ıslatmıştın beni hatırlarmısın

O benden ayrılıp gittiğinde, sen hala yağıyordun

O gideli yıllar oldu, gözlerimde halen yaş

           

Ve sen hala yağıyorsun, hiç dinmeyecek gibi

Güneş doğmayacak sanki, her yer karanlık

Kara bulutlar var üzerim de, gitmeyecekmiş gibi

İçimde bir korku, hiç dönmeyeceksin geri', 'Yine yağmur yağıyor, benden intikam alırcasına Sanki bilmezden geliyor, yaşadığımız aşkı Bir yağmurlu günde ayrıldığımızı o da biliyor Yağma...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yagma-yagmur-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seveceğim', 'seni-sevecegim-muzaffer-taskirmaz-g4ubp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gün maziye bak, gerçekleri görmek için

Belki buruk bir tebessüm, edeceğim sana

Hata olduğunu bile bile, sana döneceğim 

Belki yanlışını anlarsın, yine seni seveceğim

Kırılan kalbi düzelmek, çok zor olur

Hiç düşünmedin mi, kararını verirken

Yıllardır birlikte olduğumuz, o şen günleri

Sen nasıl unuttun, bir anda kayboldun

Seni her yerde aradım, mecnun gibi

Elimde resmin bile yok, kime sorayım

Koskoca bu şehirde, seni kimden sorayım

Belki geri dönersin, yine seni seveceğim', 'Bir gün maziye bak, gerçekleri görmek için Belki buruk bir tebessüm, edeceğim sana Hata olduğunu bile bile, sana döneceğim  Belki yanlışını ...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-sevecegim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Kelimede Bir Ömür', 'i-ki-kelimede-bir-omur-abdullah-karaduman-1m82z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ağlayarak doğdum ve yaşadım

Yaşam ağırdı, beni ezemedi.

Küçük balık olmak yoktu, olmadım.

Sokaklar acımasızdır, sessiz ve de soğuk

Özlersin sıcak bir yuva, bir kucak.

Sana sevda olur gülümseyen bir dudak, 

Ve ölürsün uğrunda, ol dese olursun uşak.', 'Ağlayarak doğdum ve yaşadım Yaşam ağırdı, beni ezemedi. Küçük balık olmak yoktu, olmadım. Sokaklar acımasızdır, sessiz ve de soğuk Özlersin ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karaduman']::text[], 8.5, '{"poet":"Abdullah Karaduman","poet_slug":"abdullah-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/iki-kelimede-bir-omur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerim Islak', 'gozlerim-islak-hasan-ozemek-pmeb2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Odamın serin karanlığında, 

Senin hayalin, 

Dudağıma götürdüğüm kadehte sen varsın, 

Bir nisan yağmuru gibi

Gözümde yaşlarla..

İşte yalnızım, 

Sensiz olmanın yalnızlığı içinde..

Ne gözlerime gülen, 

Ne ellerimi okşayan biri var..

Düşüncelerimiz aramızdaki mesafeler kadar uzak, 

Gözlerim ıslak, 

Durup durup ta seni düşlüyorum, 

Ve....

Doyasıya ağlıyorum hiç utanmadan.....', 'Odamın serin karanlığında,  Senin hayalin,  Dudağıma götürdüğüm kadehte sen varsın,  Bir nisan yağmuru gibi Gözümde yaşlarla.. İşte yalnızım...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özemek']::text[], 8.5, '{"poet":"Hasan Özemek","poet_slug":"hasan-ozemek","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gozlerim-islak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutuldum', 'unutuldum-hasan-ozemek-jhrgm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir damla gözyaşında unutuldum, 

Gittikçe daralan bu yaşantımda..

Kurşunlarca ağırlık yüklenmiş omuzlarıma, 

Kapımı bir el çalmadı.....

Bir damla gözyaşında unutuldum, 

Nedenlerini  soran olmadı...

Bitmemiş bir şarkı misali, 

Borçlandı tüm sevgiler bana...

Kapanmamış bir defterde unutuldum, 

Sarılmamış bir yara yüreğim, 

Yaban gözlerle yalvardım hep..

Bir damla gözyaşında unutuldum..', 'Bir damla gözyaşında unutuldum,  Gittikçe daralan bu yaşantımda.. Kurşunlarca ağırlık yüklenmiş omuzlarıma,  Kapımı bir el çalmadı..... Bir ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özemek']::text[], 8.5, '{"poet":"Hasan Özemek","poet_slug":"hasan-ozemek","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/unutuldum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geleceğim Yine', 'gelecegim-yine-hasan-ozemek-wwi8e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kılıç bakışlarla geleceğim sana tekrar, 

Yağmur gibi dolacağım çevrene, 

Şemsiyen geri çeviremiyecek beni..

Dudaklarımdan alamayacaksın bir tek söz..

Kilit gerisinde kalacak özlemin, 

Öfkem kasırgalar getirecek, 

Gölgem gözlerine düşecek..

Sonra; 

Seni yalnızlıklarınla bırakıp, 

Kapını örteceğim sessizce..

Ve geri döneceğim....', 'Kılıç bakışlarla geleceğim sana tekrar,  Yağmur gibi dolacağım çevrene,  Şemsiyen geri çeviremiyecek beni.. Dudaklarımdan alamayacaksın bir ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özemek']::text[], 8.5, '{"poet":"Hasan Özemek","poet_slug":"hasan-ozemek","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gelecegim-yine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıcağı Ararım', 'sicagi-ararim-omer-bayhan-7pc2n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kanat çırparak ulaşmaya çalışırlar, 

Sıcağı bulmaktır amaçları..

Benimde yüreğimde esen, 

Kırlangıç fırtınasıdır..

Sıcağı ararım seninle, 

Bu yüzden çırpınırım.', 'Kanat çırparak ulaşmaya çalışırlar,  Sıcağı bulmaktır amaçları.. Benimde yüreğimde esen,  Kırlangıç fırtınasıdır.. Sıcağı ararım seninle,  B...', ARRAY['Türk Edebiyatı','Şiir','Ömer Bayhan']::text[], 8.5, '{"poet":"Ömer Bayhan","poet_slug":"omer-bayhan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sicagi-ararim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah İstanbul', 'ah-i-stanbul-ergun-yildirim-2h6gp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ah İsatanbul, 

Kimi zaman yalnızsın, kimi zamanda kalabalık

Anlaşılmaz bir türlü halin

Ne yazın belli nede kışın, İstanbul

Ah İstanbul, geceleri sessiz sakin

Gündüzleri deli rüzgar gibisin

Her yerde esmektesin

Ah istanbul, sen hep böylemisin

Ah istanbul, anlatmakla bitmezsin

Gezmeklede görünmezsin

yokmu seni ucun, bucağın

Ne taşın nede toprağın, istanbul

Ah istanbul, ne şairler ne yazarlar yedin

Bir bir anlatılar yazdılar seni

Yinede dinletemedin kendini

Nedir senin bu halin, İstanbul', 'Ah İsatanbul,  Kimi zaman yalnızsın, kimi zamanda kalabalık Anlaşılmaz bir türlü halin Ne yazın belli nede kışın, İstanbul Ah İstanbul, gece...', ARRAY['Türk Edebiyatı','Şiir','Ergün Yıldırım']::text[], 8.5, '{"poet":"Ergün Yıldırım","poet_slug":"ergun-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ah-istanbul-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamadın', 'anlamadin-ahmet-kerem-kaban-gjwli', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Serüvene koşmak için

Trenler beklemene gerek yok

Kaçmak için nedenlere

Güneşi yakalayıp

Gözlerine yerleştirmek için

Beyaz yelkenlerin seni almalarına

Yarına gitmek için günbatımına

İyi Gözükmek için

Bana

Güçlü görünmek için

Öfkeye

İhtiyacın varsa

Demek ki

Beni anlamadin', 'Serüvene koşmak için Trenler beklemene gerek yok Kaçmak için nedenlere Güneşi yakalayıp Gözlerine yerleştirmek için Beyaz yelkenlerin seni a...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kerem Kaban']::text[], 8.5, '{"poet":"Ahmet Kerem Kaban","poet_slug":"ahmet-kerem-kaban","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/anlamadin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıyısında Dolanıyoruz Sevdanın', 'kiyisinda-dolaniyoruz-sevdanin-mikdat-acikkapi-brejy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yeniden yeşertin ümitleri

sevgilin olmasam da

yüreğim serçe pencerende

ellerine konmak isteyen

huzur var gözlerimde yeni yeni

ne sen ne ben sevdadan bahsetmesek de

kıyısında dolanıyoruz sevdanın

Acı versede dost kalmalıyız belki

yalnızlıklarda birbirimize sığınmak için

Yaşadığım aşklardan yücedir

ılık nefesinde sarhoş olmak

paylaşımlarımız az olsada

düşüncelerimizde gizli özlem olsun

geceleri ansızın uyku bölen

içimden içine telepati ile dolan

yangınımla uyanmalısın

dokun yangınıma yüreğin ısıtsın

kıyısında dolanıyoruz sevdanın', 'Yeniden yeşertin ümitleri sevgilin olmasam da yüreğim serçe pencerende ellerine konmak isteyen huzur var gözlerimde yeni yeni ne sen ne ben ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Açıkkapı']::text[], 8.5, '{"poet":"Mikdat Açıkkapı","poet_slug":"mikdat-acikkapi","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kiyisinda-dolaniyoruz-sevdanin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nice Yıllara', 'nice-yillara-hakan-cabuk-fb0ch', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevdin mi sen, yüreğinle dolduracaksın boşluğunu

Adını dostluk yazmışsan eğer, özleyeceksin yokluğunu

Dara düştüğünde yoksa hala sırtında

Ellerin yüzüne bakamayacak, hissedemeyeceksin açken tokluğunu

Tükenmediyse nefesin ve hala dalıyorsa yaşlı gözlerin

Tut ellerini bir kez daha, vuslatı görmeden yorgun bedenin

İki cihan fatihi sen bile bize dostlukla hükmettin

Nice yıllara dostum, seni seviyorum Sadettin', 'Sevdin mi sen, yüreğinle dolduracaksın boşluğunu Adını dostluk yazmışsan eğer, özleyeceksin yokluğunu Dara düştüğünde yoksa hala sırtında El...', ARRAY['Türk Edebiyatı','Şiir','Hakan Çabuk']::text[], 8.5, '{"poet":"Hakan Çabuk","poet_slug":"hakan-cabuk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/nice-yillara-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-ufuk-nazim-m7487', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hasretmi dedin, 

Uçan kuşlara nasıl baktın.

Karınca yuvasına giderken, 

Kıskandınmı onuda.

Aktın işte bir sonbahar akşamında, 

Gözlerimden içeri.

Şişede şaraptın seni yıllarca yudumladım.

Rolünü ezberlemiş bir figürandın.

Aynı olmak yada olmamak, 

Neyi anlatırki.

Aşarken aynılık içinde sedir ağaçları, 

Binlerce yılı değişimi rüzgardan beklediler.

Biz şu kısacık ömrümüzde, 

Değişmek için ateşe dokunduk.

En hızlılarımız yananlarımızdır.

Ve ben ateşe kanatlarını sunanlardanım.

Bir yazar yalnızlığında, 

Zamanın yarısında yazmaktayım.

Geçen sağnağı hatırlamaktayım, 

Çağrışımlarla çözülüp, 

İçselliğimi çeperlerime vurmaktayım.', 'Hasretmi dedin,  Uçan kuşlara nasıl baktın. Karınca yuvasına giderken,  Kıskandınmı onuda. Aktın işte bir sonbahar akşamında,  Gözlerimden i...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hasret-80-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar', 'bahar-esma-ozdemir-xc0e4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İşte, yine geldi bahar mevsimi! 

Giyindi tabiat yeşil bir giysi

Berrak mavileri, parlak güneşi

Yağmurlu günleri getirdi bize.

Yumuşak toprağı, çimenlerini

Tomurcuk, kokulu çiçeklerini

Dallarda ötüşen kuş seslerini

Ne çok özlemişim bahar ben seni! 

Kalkmış uykusundan bütün canlılar

Her tarafta bir yiyecek ararlar

Tarlalarda, bahçelerde insanlar

Neşe ve istekle hep çalışırlar.

Gelincikler, papatyalar kırlarda

Nevruzlar, çiğdemler sarp kayalarda

Sümbüller, menekşeler dağlarda

Renk katarlar her tarafa baharda.

Güzelliğin destan olur dillere

İlham gelir ressamlara, şaire

Aşıklar anar seni hep sözlerinde

Sihirli bir tablo gönlümde bahar.', 'İşte, yine geldi bahar mevsimi!  Giyindi tabiat yeşil bir giysi Berrak mavileri, parlak güneşi Yağmurlu günleri getirdi bize. Yumuşak toprağ...', ARRAY['Türk Edebiyatı','Şiir','Esma Özdemir']::text[], 8.5, '{"poet":"Esma Özdemir","poet_slug":"esma-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bahar-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hangimiz', 'hangimiz-seyit-ahmet-duzen-7jzj0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşamak istedim seninle

Yanında olmak

Tek dileğim

Ya şimdi...

Hangimiz terketti bizi

Ve kim yalnız bıraktı

Hangimiz öldürdü aşkı

Nefretle suçluyoruz 

Birbirimizi.

Neler yapıyor, 

Ne haldeydik.

Hangimizin umrunda

Var olan sevgi yok

Hangimiz katil

Kimbilir?', 'Yaşamak istedim seninle Yanında olmak Tek dileğim Ya şimdi... Hangimiz terketti bizi Ve kim yalnız bıraktı Hangimiz öldürdü aşkı Nefretle su...', ARRAY['Türk Edebiyatı','Şiir','Seyit Ahmet Düzen']::text[], 8.5, '{"poet":"Seyit Ahmet Düzen","poet_slug":"seyit-ahmet-duzen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hangimiz-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkarım', 'korkarim-seyit-ahmet-duzen-z0sz6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu geceler farklı dost

Ayazı kızıl aleve çalar

Sisli sabah sonu yollarda

Vazgeçer, dönersin

Bu geceler acımasız olur

Kavuşmak yarına kalır

Korkarım, yarın olmazsa

Kimse halini sormaz dost

Sokaklar ıssız ve çıkmaz

Artık dostlar nankör

Tanıyamayacağın kadar yabancı

Yalnızsındır

Yalnızlık kurtuluşum

Sen yarına kalırsın

Korkarım, yarın hiç olmazsa

Seni beklerim 

Çok uzaklarda

Onların olmadığı

Dostluğun ve kardeşliğin

Yaşandığı o yerde...

Yarın, 

Şimdi bugündür

Korkarım ya gelmezsen', 'Bu geceler farklı dost Ayazı kızıl aleve çalar Sisli sabah sonu yollarda Vazgeçer, dönersin Bu geceler acımasız olur Kavuşmak yarına kalır K...', ARRAY['Türk Edebiyatı','Şiir','Seyit Ahmet Düzen']::text[], 8.5, '{"poet":"Seyit Ahmet Düzen","poet_slug":"seyit-ahmet-duzen","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/korkarim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günün Adamı', 'gunun-adami-i-rfan-topcu-m612d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ben bu günün adamıyım.

ne dünden küskün, 

ne yarından umutsuzum.

ama bu gün mutsuzum.', 'ben bu günün adamıyım. ne dünden küskün,  ne yarından umutsuzum. ama bu gün mutsuzum....', ARRAY['Türk Edebiyatı','Şiir','İrfan Topçu']::text[], 8.5, '{"poet":"İrfan Topçu","poet_slug":"i-rfan-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gunun-adami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalakamçı Sesleri', 'dalakamci-sesleri-i-rfan-topcu-q53gs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey eli kanlı yüzyıl.

ne karsın çocuklarını

dalakamçı sesleriyle büyütüyorsun.

nede geceleri rahat uyutuyorsun.

seni özlemle bekleyen bendim, 

banada yazıklar olsun.

sözde uğur doluydun.', 'Ey eli kanlı yüzyıl. ne karsın çocuklarını dalakamçı sesleriyle büyütüyorsun. nede geceleri rahat uyutuyorsun. seni özlemle bekleyen bendim,...', ARRAY['Türk Edebiyatı','Şiir','İrfan Topçu']::text[], 8.5, '{"poet":"İrfan Topçu","poet_slug":"i-rfan-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dalakamci-sesleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurşunlum Sen Varsın', 'kursunlum-sen-varsin-muammer-mermer-mmj24', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugün masamda şiir yazdım

İplik iplik nakışında KURŞUNLUM sen varsın

Aşkın kanununu okudum

Madde madde KURŞUNLUM sen varsın..

Devrez vadisinden bir ırmak geçer

Eğilir hayvanlar suyundan içer

Bağrında ay doğar zambaklar açar

Sessiz sessiz akışında KURŞUNLUM sen varsın..

Öz suyunun hayat denen şişenin

Nedenisin keder ile neşenin

Sevda cephesinde şehit düşenin

Donuk donuk bakışında KURŞUNLUM sen varsın...

Hep senin renginde görünür bahar

Yaprakta yeşilin, gülde kokun var

Yama yama kalbimdeki yaralar

Sıra sıra dikişinde KURŞUNLUM sen varsın...', 'Bugün masamda şiir yazdım İplik iplik nakışında KURŞUNLUM sen varsın Aşkın kanununu okudum Madde madde KURŞUNLUM sen varsın.. Devrez vadisin...', ARRAY['Türk Edebiyatı','Şiir','Muammer Mermer']::text[], 8.5, '{"poet":"Muammer Mermer","poet_slug":"muammer-mermer","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kursunlum-sen-varsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavgaya Devam', 'kavgaya-devam-ali-kalayci-9xijn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'alnıma bir silah çevriliyor ne yana baksam

bir ceset doğruluyor gözlerimi kapattığımda

cebimde uzak şehirlere günü geçmiş biletler

tutuşuyor azıcık hayıflansam.

her gece ayin sessizliğinde

bir kadın geçiyor uykularımdan

bir kadın iskambil fallarıyla kirletilmemiş

bir kadın cinayetler çağrıştıran

bir yaz bahçesi, 

bir daha...

bir gölge kımıldıyor bir adım atsam.

devasa bir mermere dönüşüyor bedenim.

put put aşklar göveriyor her yanımdan

kahredilmiş kavimlerin

her yanımda Nuh’tan sonra süregelen şenliği

her yanım Nuh’tan kalma 

Nuh gibi.

fakat ben yaktım gemilerimi..

evet gitmiyorum, 

yağmalara alışkınım ilk suhuftan beri. 

bu davetçi tevazusu

bu kulluk haşmeti

ne varsa aramızda 

bezirganlar,  işporta işi felek evleri

bitsin  ne varsa hemen şimdi

ey karşı koydukça büyüyen uğursuzluğun rahmi

kavgaya devam

ancak haşr’e kadar baki kalır bu vahiy

1992', 'alnıma bir silah çevriliyor ne yana baksam bir ceset doğruluyor gözlerimi kapattığımda cebimde uzak şehirlere günü geçmiş biletler tutuşuyor...', ARRAY['Türk Edebiyatı','Şiir','Ali Kalaycı']::text[], 8.5, '{"poet":"Ali Kalaycı","poet_slug":"ali-kalayci","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kavgaya-devam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vur Neşterini', 'vur-nesterini-emre-gumusdogan-3y0er', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '-''kadavraya neşter''

neyler ki deme  -

zinalardan geldim / temiz değilim

isa musa tanımam

yağmursuz toprakla konuştum

suyu çekikti yıkandığım ırmakların

düşler mezarlığında kaldı

memesini emdiğim şiir

ölümün öncesinden geldim

-ölümün öncesi - çığlığı parçalayan

tavana asılı bakıştı

ve martı sesleri...

geceler dinlerdi 

bir de dört duvar

bir ömrü ırattım kendimden

seyreldim

sonra seni sevdim

bir masalın uzun soluğunda

sevende bilirsin

suya değen söğüt dalı kesilirim

zinalardan geldim / kirliyim

bu aşkı sen çekip çevireceksin

sensin kıraç toprağımda harman yapacak

sevginle arındır / bekleme 

vur neşterini', '-''kadavraya neşter'' neyler ki deme  - zinalardan geldim / temiz değilim isa musa tanımam yağmursuz toprakla konuştum suyu çekikti yıkandığım...', ARRAY['Türk Edebiyatı','Şiir','Emre Gümüşdoğan']::text[], 8.5, '{"poet":"Emre Gümüşdoğan","poet_slug":"emre-gumusdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/vur-nesterini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni AÇ Bıraktın', 'beni-ac-biraktin-cahit-i-pekoglu-e8183', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yandım, yandım

Ben aşkınla hep yanar oldum.

Kokladım, kokladım

kokunla hep sarhoş oldum.

Sarhoşluğum bitmiyor

seni hala içimden atamadım.

Yaktın beni, beni yaktın

doyamadım sana, beni aç bıraktın.

Anladımki

senin için hayatından geçiyordum.

Benden ne istedin

beni can evimden, yaraladın.

Şimdi yaramı saracak canda yok

sonsuzluğa uğurlayacak bir canda yok.

Yaktın beni, beni yaktın

doyamadım sana, beni aç bıraktın...', 'Yandım, yandım Ben aşkınla hep yanar oldum. Kokladım, kokladım kokunla hep sarhoş oldum. Sarhoşluğum bitmiyor seni hala içimden atamadım. Ya...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beni-ac-biraktin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alabalık', 'alabalik-esma-ozdemir-h3r9o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bu gece, doldum; taştım 

yeniden

mavi denizlere uzandım.

bir bardak suda 

kıyametlerde yandım.

gaddarlara, insafsızlara

acımasız

sert dalgalarda uyandım.

tatlı sularda oynaşan 

bir alabalığa kandım.

derinliklerde yüzerken

zümrüt, yosun ağlarına takıldım.

alabalık, kurtar beni

kalbimden yakalandım! 

terkedeceğim bu bedeni

bu anlamsız cesetten kurtulacağım! 

canımı canına katacağım

bu  mundar hayat 

gayrı, yetmez mi! 

ve 

hayata şöyle bir bakacağım yeniden

gayesiz, bayat kokan insanlara

kahkahalarla güleceğim! 

okyanuslar kadar mavi

sular gibi serin

gökyüzü kadar berrak

denizler kadar coşkun

balıklar kadar canlı

yosunlar kadar tutkun

hayallerde 

ölümsüz yaşayacak ruhum!', 'bu gece, doldum; taştım  yeniden mavi denizlere uzandım. bir bardak suda  kıyametlerde yandım. gaddarlara, insafsızlara acımasız sert dalgal...', ARRAY['Türk Edebiyatı','Şiir','Esma Özdemir']::text[], 8.5, '{"poet":"Esma Özdemir","poet_slug":"esma-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/alabalik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görmiyeceğim', 'gormiyecegim-muammer-mermer-xoi6c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Görmüştüm ben seni internette

Ölünceye kadar bekliyeceğim

Kaderime kızıp bir gün sonunda

Hayalin gözümle görmüyeceğim

Ah çeker dururrum içimde sevdan

Nasıl olsa bir gün döneceksin

Şaşırıp kalmışım herşey Allahtan

İnanki herşeyim ben sensiz ölmiyeceğim

Melekse güzeller sen huri oldun

Şahidim Allahtır bıkmıyacağım

Artık bende birini buldum

Kalbimin içinde saklıyacağım...', 'Görmüştüm ben seni internette Ölünceye kadar bekliyeceğim Kaderime kızıp bir gün sonunda Hayalin gözümle görmüyeceğim Ah çeker dururrum içim...', ARRAY['Türk Edebiyatı','Şiir','Muammer Mermer']::text[], 8.5, '{"poet":"Muammer Mermer","poet_slug":"muammer-mermer","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gormiyecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çeker Giderim', 'ceker-giderim-omer-cam-6sk4l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çekilir mi derdi fânî dünyânın, 

Hayatın encâmı hiçlik olunca.

Zevkinden ne çıkar geçen zamanın, 

Bahçemizde bir gün güller solunca? 

*

Biz öldükten geri ne gelir elden? ..

Ukbâya hazırlık gerek tezelden.

Istırap yüklüdür herkes ezelden; 

Üzülür dururum yıllar boyunca...

*

Ekinimi bugün eker giderim, 

Arabamı yarın çeker giderim, 

Malı da, mülkü de bilmem niderim, 

Gözlerim benim toprak olunca...”', 'Çekilir mi derdi fânî dünyânın,  Hayatın encâmı hiçlik olunca. Zevkinden ne çıkar geçen zamanın,  Bahçemizde bir gün güller solunca?  * Biz ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Çam']::text[], 8.5, '{"poet":"Ömer Çam","poet_slug":"omer-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ceker-giderim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ünye Özlemi', 'unye-ozlemi-omer-cam-12pm5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir parıltı yükselir tutuşurken yıldızlar

Bu serin bahçelerin uyuyan baharında, 

Ve gülüşür uzaktan şafak çehreli kızlar 

Süzülürken ışıklar zümrüt dalgalarında. 

Ve mavi mavi kuşlar uçurur rüyamızı

Pembe pembe uçuşlar kucaklar dünyamızı, 

Çakır Tepe''nin yamaçlarında menekşe renginde Yesil, yemyeşil gölgeler görülür çam ağaçlarında...

Damla damla, altın peykeler görülür. 

Ünye''de güneş; cennetin binbir renkli kızıdır, 

Gün doğarken güneş sarı, batarken kırmızıdır. 

Ünye, canım Ünye, canım ciğerim Ünye, 

Derelerine kaynak olayım Ünye, 

Bahçelerinde toprak olayım Ünye, 

Ağaçlarında yaprak olayım Ünye', 'Bir parıltı yükselir tutuşurken yıldızlar Bu serin bahçelerin uyuyan baharında,  Ve gülüşür uzaktan şafak çehreli kızlar  Süzülürken ışıklar...', ARRAY['Türk Edebiyatı','Şiir','Ömer Çam']::text[], 8.5, '{"poet":"Ömer Çam","poet_slug":"omer-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/unye-ozlemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-muammer-mermer-yvyl1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'S eviyorum seni kimsenin sevemiyeceği kadar

E min  ol herşeyim gözümden akıyor yaşlar

M aksat seni sevmek ömrümün sonuna kadar hep beraber

A rtık resmin önümde ama konuşmaya dakikalar saatler yetmiyor

S atırlarımda yazı yok yazılan ve yazan 

E llerimde elin yok istediğim zaman

N efesinde kaybolmak adım adım

İ çimden çıkartmıyacağım herşeyim hiç bir an

S aadetli yaşam hayatıma can bazen mutsuzluğum  aynasında heyecan

E fsane sanki tarihte yaşatılangözlerin umarsız

V e senle herşeyim ölümsüz sevgimiz ve aşkımız

İ lgine tapınanşevkatine sığınan muammer vurgun yemiş

Y akışan ellerime en güzel ellerin en sadık gözlerin

O an geldiğinde sözlerinle bütünleşen hislerim

Rüzgar bulutları toplanıp yağmur yağdığında sana sarılıyorum

U fukta güneş batıp yok olunca seni yanımda istiyorum

M avi gökyüzünde fırtına oluşunca herşeyim seni merak ediyorum.....', 'S eviyorum seni kimsenin sevemiyeceği kadar E min  ol herşeyim gözümden akıyor yaşlar M aksat seni sevmek ömrümün sonuna kadar hep beraber A...', ARRAY['Türk Edebiyatı','Şiir','Muammer Mermer']::text[], 8.5, '{"poet":"Muammer Mermer","poet_slug":"muammer-mermer","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/seni-seviyorum-102-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Ne Yapardım; Ben', 'sensiz-ne-yapardim-ben-ozgul-ozyilmaz-mgu7k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''Sensiz ne yapardım ben'' deriz bazen..

İnsan tatmadığı bir yemeğin

Koklamadığı bir çiçeğin

Duymadığı bir melodinin

Görmediği bir güzelliğin özlemini duyar mı hiç? 

İşte asıl ikilem de burda başlar ya insanoğlunda..

Ve işte bunun için hep derim ya 

''keşme bir köylü kızı olsaydım'' diye.

Çok bilmek, çok istemektir

Çok görmek, çok özlemektir

Çok sevmek, çok acı çekmektir.

Çoğaldıkça parçalanır, parçalandıkça mutsuz olur insan.

Bir arada tutmak ister her parçayı, ama yoktur ki olanak, imkan.

Hal böyle olunca da başlar yürekte bir isyan..

Dostlar harika, ayrılması zor, 

Yaşam harika, ayakta kalması zor, 

Sevmek kolay, vazgeçmek ise çok zor.

Dostlara vakit ayırmalı

Ayakta kalmak için çok çalışmalı

Sevdiklerini kaybetmemek için ise çok fazla özveride bulunmalı..

Zaten bütün meselede hepsini aynı anda nasıl yapmalı? 

En iyisi herşeyi olduğunca kabullenip yürekte yaşatmalı..

13.09.2002', '''Sensiz ne yapardım ben'' deriz bazen.. İnsan tatmadığı bir yemeğin Koklamadığı bir çiçeğin Duymadığı bir melodinin Görmediği bir güzelliğin ...', ARRAY['Türk Edebiyatı','Şiir','Özgül Özyılmaz']::text[], 8.5, '{"poet":"Özgül Özyılmaz","poet_slug":"ozgul-ozyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sensiz-ne-yapardim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buğu', 'bugu-ali-kalayci-2p4en', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'mavi bendim

yollarında 

gök hükmünde

ilahi..

bakma ela rüzgarıma

öyle dingin bekledim

mavi bendim 

yollarında

çığ tohumu 

kamaşan..

dilsiz, yörük cümlelerle

geçip gittin kitabımdan', 'mavi bendim yollarında  gök hükmünde ilahi.. bakma ela rüzgarıma öyle dingin bekledim mavi bendim  yollarında çığ tohumu  kamaşan.. dilsiz, ...', ARRAY['Türk Edebiyatı','Şiir','Ali Kalaycı']::text[], 8.5, '{"poet":"Ali Kalaycı","poet_slug":"ali-kalayci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bugu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Yıl Bizi Kavuştursun', 'bu-yil-bizi-kavustursun-soner-demirez-etbxy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Saçlarına kar yağamasın...

Gözlerin hep parıldasın...

Yıldızlar yoldaş olsun..

Bu yıl bizi kavuştursun..

Sürme çekme gözlerine..

Hüzün sürme yüreğine..

Aşkın ecel olsa bile...

Bu yıl bizi kavuştursun...

Dalda çiçek açtığında...

Ihlamurlar koktuğunda..

Yaz güneşi doğduğunda...

Bu yıl bizi kavuştursun...

Ayrılık ateşine yanma sakın..

Hicran''a teslim olma sakın...

Seni sevdiğimi unutma sakın...

Bu yıl bizi kavuştursun...', 'Saçlarına kar yağamasın... Gözlerin hep parıldasın... Yıldızlar yoldaş olsun.. Bu yıl bizi kavuştursun.. Sürme çekme gözlerine.. Hüzün sürme...', ARRAY['Türk Edebiyatı','Şiir','Soner Demirez']::text[], 8.5, '{"poet":"Soner Demirez","poet_slug":"soner-demirez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-yil-bizi-kavustursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahretsin Seni Seviyorum', 'kahretsin-seni-seviyorum-salih-ozalasan-t6bla', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaç kez söylemek istedim, kaç kez yazmak

Bazen noktalarla, bazen imalarla

Kızdığımda dokuz sûtuna manşet puntolarla

Bazen çareyi aradım aşkı anlatan kartlarda

Diyemedim seni seviyorum; çok ama çok

Kâlbimde sen varsın yüreğim yangınlarda

Sevgi sözlerini bekledim; dudaklarından, çok ama çok

Çok geceler teselliyi aradım aşk''ı anlatan şarkılarda

Gözlerinin içine baktım hep, gözümü kırpmadan

Söylermi acaba diye benim söyleyemediğimi

Bende seni seviyorum; çok ama çok

Anla artık benimde sana diyemediğimi

Yüzüme vurmanı bekledim hep

Aptal; ! Bende seni seviyorum seni

Anladım yüreğinden geçeni

Dilinin söyleyemediğini

Bari sorsaydın sevebilirmiyim seni? 

Dersin şimdi yapma be sevgili

Sevmek için sevgiliden izin istenirmi; 

Sen söyleyemedin; şimdi dinle

Seni seviyorum; seni seviyorum

Kahretsin; hemde çok seviyorum seni', 'Kaç kez söylemek istedim, kaç kez yazmak Bazen noktalarla, bazen imalarla Kızdığımda dokuz sûtuna manşet puntolarla Bazen çareyi aradım aşkı...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kahretsin-seni-seviyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haticem''e', 'haticem-e-ozgul-ozyilmaz-7vxx1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayat hiç bir zaman düz bir yol olmadı bize, 

Aştık nice engelleri biz beraberce.

Tutunduk yüreklerimizle, kenetlendik kalbimizle, 

İnandık, sevgiyle, cesaretle ve birlikte her zorluğu aşabileceğimize.

Coşkuyla, acıyla, zamanı, mekanı, duaları paylaştık içten içe, 

El ele, gönül gönüle, sırt sırta, asla pes etmedik direndik geldik bu günlere, 

Mutlu olacağız Haticem, aşacağız bunları da Allah’ın izniyle, sevdiklerimizle..', 'Hayat hiç bir zaman düz bir yol olmadı bize,  Aştık nice engelleri biz beraberce. Tutunduk yüreklerimizle, kenetlendik kalbimizle,  İnandık,...', ARRAY['Türk Edebiyatı','Şiir','Özgül Özyılmaz']::text[], 8.5, '{"poet":"Özgül Özyılmaz","poet_slug":"ozgul-ozyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/haticem-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayrampaşa', 'bayrampasa-soner-demirez-z1ayw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Demir kapılar ardında..

Dört duvarın arasında..

Tesbihimi çekiyorum.. 

Bayrampaşa mahpusunda..

Üç çocuklu bir anadan..

Doğmakmış benim suçum..

Üçte birlik bir sevgiyle, 

Ağlar anam''Aah çocuğum''..

Görüş günü gelsede, 

Arayanım olmaz benim..

Unutulmuş olsam da, ben..

Bu hasretim bitmez benim..', 'Demir kapılar ardında.. Dört duvarın arasında.. Tesbihimi çekiyorum..  Bayrampaşa mahpusunda.. Üç çocuklu bir anadan.. Doğmakmış benim suçum...', ARRAY['Türk Edebiyatı','Şiir','Soner Demirez']::text[], 8.5, '{"poet":"Soner Demirez","poet_slug":"soner-demirez","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bayrampasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Hatirlayanlara Selam Ederim!', 'beni-hatirlayanlara-selam-ederim-sessiz-adam-gesob', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gün gelir ben giderim, 

bu dünayda yoktur yerim, 

toprak altina girerim, 

beni hatirlayanlara selam ederim...

giden günler geri gelmez, 

kimse sanmasin kendi ölmez, 

kötü yoldan cogu geri dönmez, 

beni hatirlayanlara selam ederim...

benim hayatim bitti bitecek, 

herkes bu ana gelecek, 

ölmeden kelimeye saadet getirecek, 

beni hatirlayanlara selam ederim...

benim gözlerim görmez olur, 

Annemin gözleri dolu olur, 

yarin hersey gecmis olur, 

beni hatirlayanlara selam ederim...

Namazimi kilar Allaha dua ederim, 

herkese bunu tafsiye ederim, 

Siirin ötesini getiremedim, 

beni hatirlayanlara selam ederim...', 'Bir gün gelir ben giderim,  bu dünayda yoktur yerim,  toprak altina girerim,  beni hatirlayanlara selam ederim... giden günler geri gelmez, ...', ARRAY['Türk Edebiyatı','Şiir','Sessiz Adam']::text[], 8.5, '{"poet":"Sessiz Adam","poet_slug":"sessiz-adam","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/beni-hatirlayanlara-selam-ederim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paylaşıyorum', 'paylasiyorum-soner-demirez-u9l8c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Huzursuz bir gece, gökte yıldızlar.

Hepsi parlak, dünya''ya inat edercesine..

Sana inat biz, hala ayaktayız der gibi...

Ben onlarla yanlızlığımı paylaşıyorum..

Kulağımda seçme şarkılar..

Beynimde düşünceler...

Depremzedeleri düşünüyorum..

Ve acılarını paylaşıyorum..

Yolllara bakıyorum, yollar yolar bomboş..

Sabah dolacak, yeniden canlanacak..

İnsanları bir telaş saracak..

Heyecanlarını, hayatı paylaşıyorum..

İnsanları düşünüyorum..! ! ! 

Kimi aç, kimi tok, kiminin bir işi yok...

Kimi sağcı kimi solcu, 

Düşüncelerini paylaşıyorum...

Ağlayanlar, üzülenler, sevinenler..

Yaşananları, hayalleri düşünüyorum..

Yaşananlardan alıyorum hissemi, 

Ve bu dünya''da yaşamaya çalışıyorum, 

''Bir mikrop gibi''...', 'Huzursuz bir gece, gökte yıldızlar. Hepsi parlak, dünya''ya inat edercesine.. Sana inat biz, hala ayaktayız der gibi... Ben onlarla yanlızlığ...', ARRAY['Türk Edebiyatı','Şiir','Soner Demirez']::text[], 8.5, '{"poet":"Soner Demirez","poet_slug":"soner-demirez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/paylasiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm!', 'olum-sessiz-adam-g1mni', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Derin bir uykuya daliyorum

diyerek gözlerimi kapiyorum 

hayattan ümidi kesiyorum

yoksa yinemi yinemi ölüyorum? 

Bir yok yere

ölmüstüm ben bir kere

veda etmeden ellere

birakmistim kendimi sellere

Bu gidisle ben daha cok ölürüm, 

ölür ölür gömülürüm, 

bir ümit annemi görürüm, 

Ölürüm ulan ölürüm...', 'Derin bir uykuya daliyorum diyerek gözlerimi kapiyorum  hayattan ümidi kesiyorum yoksa yinemi yinemi ölüyorum?  Bir yok yere ölmüstüm ben bi...', ARRAY['Türk Edebiyatı','Şiir','Sessiz Adam']::text[], 8.5, '{"poet":"Sessiz Adam","poet_slug":"sessiz-adam","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olum-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dedim Kendime', 'dedim-kendime-soner-demirez-pt0h6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eveeet, yine akşamlardan bir akşam, 

Yine benim saatlerim geldi çattı...

Ortalıktan el ayak çekildi, 

Ve gece yine bendeniz''e kaldı..

Geceyi beklemeye başladım yine, 

Yıldıları sayarak, hayallwer kurarak...

Bir yıldız kaydı gök''te...

Biri daha öldü, dedim içimden...

Üzüldüm, belki daha çok gençti, 

Belki henüz hayatı tadamamıştı, 

Ya çok sevdiği biri vardıysa..

Yazık oldu, dedim kendime..

Belki''de orta yaşlıydı, kim bilir; 

Ömrün en güzel çağları, 

Belkide evliydi ardında, çocukları..

Ölmenin zamanımıydı, dedim kendime...

İhtiyar olsa üzülmeszdim belki''de, 

Ya, acı içinde yavaş yavaş öldüyse, 

Peki ya imansızca öldüyse...! ! ! 

Allah rahmet eylesin, dedim kendime...', 'Eveeet, yine akşamlardan bir akşam,  Yine benim saatlerim geldi çattı... Ortalıktan el ayak çekildi,  Ve gece yine bendeniz''e kaldı.. Geceyi...', ARRAY['Türk Edebiyatı','Şiir','Soner Demirez']::text[], 8.5, '{"poet":"Soner Demirez","poet_slug":"soner-demirez","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dedim-kendime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ondan Başka', 'ondan-baska-soner-demirez-no86l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gün dünya duracak gülüm, 

Hayat bitecek, herşey yalan gülüm..

Yaradanı tanı gülüm, 

Ondan başka dostun mu var_! ! ! 

Dil üzmenin, kalp kırmanın, 

İnsana eza vermenin, 

Anlamı yok çile, derdin...

Ondan başka dostun mu var_! ! ! 

Bir garibim Allah kul''u...

İki gözüm fer''i, nur''u, 

Aksın bu gözlerin nur''u...

Ondan başka dostun mu var_! ! ! 

Gel sende katıl kervan''a..

İnsanlığım çıkarına..

İnsana hizmetten yana...

Ondan başka dostun mu var_! ! ! 

Soner söyler doğru sözü...

Allah yolu işin özü...

Din dediğin, yaşam özü..

Ondan başka dostun mu var_! ! !', 'Bir gün dünya duracak gülüm,  Hayat bitecek, herşey yalan gülüm.. Yaradanı tanı gülüm,  Ondan başka dostun mu var_! ! !  Dil üzmenin, kalp k...', ARRAY['Türk Edebiyatı','Şiir','Soner Demirez']::text[], 8.5, '{"poet":"Soner Demirez","poet_slug":"soner-demirez","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ondan-baska-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerde', 'nerde-soner-demirez-rklwh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gece karanlığın büyüsünde..

Gündüzün telaşesinde, 

Yüreğin her köşesinde, 

Söyleyin sevgi nerde_? 

Denizlerde, sahillerde, 

Dağlarda, tepelerde, 

Bilinmeyen gizlerde, 

Söyleyin sevgi nerde_? 

Bazen bir kuş kanadında, 

Bazen yolun sonunda, 

Bazen yanı başında, 

Söyleyin sevgi nerde_? 

Karanlığın koynundamı? 

Dehlizlerin sonunda mı? 

Aşıkların bağrındamı? 

Söyleyin sevgi nerde_? 

Hakk''a doğru giden yolda..

İnsanların arasında..

Dürüstlükte, doğrulukta..

İşte dostlar sevgi burda...', 'Gece karanlığın büyüsünde.. Gündüzün telaşesinde,  Yüreğin her köşesinde,  Söyleyin sevgi nerde_?  Denizlerde, sahillerde,  Dağlarda, tepele...', ARRAY['Türk Edebiyatı','Şiir','Soner Demirez']::text[], 8.5, '{"poet":"Soner Demirez","poet_slug":"soner-demirez","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nerde-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arıyorum', 'ariyorum-soner-demirez-a2d0w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsanların içinde, 

Düşüncede beyinde, 

Dünyanın her yerinde...

Arıyorum sevgi''yi..

Denizin mavisinde..

Martıların sesinde, 

kaderin cilvesinde...

Arıyorum sevgi''yi...

Bir gül''ün kokusunda, 

Bulutların ötesinde, 

Kardelen''in yas''ında..

Arıyorum sevgi''yi...

Dağların heybetinde, 

Güneşin ateşinde, 

Ay''ın görüntüsünde..

Arıyorum sevgi''yi...

Kainatta karanlıkta, 

İslamın ışığında, 

Allah''ın huzurunda..

Arıyorum sevgiyi...', 'İnsanların içinde,  Düşüncede beyinde,  Dünyanın her yerinde... Arıyorum sevgi''yi.. Denizin mavisinde.. Martıların sesinde,  kaderin cilvesi...', ARRAY['Türk Edebiyatı','Şiir','Soner Demirez']::text[], 8.5, '{"poet":"Soner Demirez","poet_slug":"soner-demirez","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ariyorum-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlüyorum', 'ozluyorum-soner-demirez-fekt1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güneşin battığı sahilde, 

Kumsalın, mavi dinginliğinde, 

Özlemlerin en yücesiyle, 

Özlüyor özlüyorum seni..

Beklettiğin çay bahçesinde, 

Gelmediğin o günlerde, 

Hasretimin son deminde, 

Özlüyor özlüyorum seni..

Neden gelmedin bilmiyorum, 

Alo dersin umuyordum, 

Aramadınya inan sana kırıldım, 

Deliler gibi özledim seni...

Güneş ufukla bir olduğunda, 

O daldığım seraplarda, 

İçimdeki sıcaklıkla, 

Özlüyor özlüyorum seni..

Sesini duymadığım bir haftada, 

Karışık şu beynimde, 

Özlüyor özlüyorum seni..

İster aşk de, ister tutku, 

İster feryap de, ister korku, 

Gelmediğin hergün, bu ömrün sonu, 

Ölümüne Aşkım Özledim seni....', 'Güneşin battığı sahilde,  Kumsalın, mavi dinginliğinde,  Özlemlerin en yücesiyle,  Özlüyor özlüyorum seni.. Beklettiğin çay bahçesinde,  Gel...', ARRAY['Türk Edebiyatı','Şiir','Soner Demirez']::text[], 8.5, '{"poet":"Soner Demirez","poet_slug":"soner-demirez","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ozluyorum-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyormusun', 'biliyormusun-soner-demirez-vucm0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şimdi şarkılar bile çok farklı! ! ! 

Her annenin çocukları misali özel..

Her biri ayrı bir güzel..

Ama en güzeli şarlırda seni bulmak biliyormusun_? 

Bir taze bahar dalı bu sevi..

Sanki yıllardır yüreğimdeymiş gibi..

Gayb''dan gelen bir sesmi bilmiyorum, 

Ama kaderim sensin biliyormusun_? 

Yetermi kelimeler aşkımı anlatmaya? 

Hiç sanmıyor yinede yazıyorum...

nakış nakış seni işliyorum dizede..

En güzelide seni yüreğime işliyorum biliyormusun_?', 'Şimdi şarkılar bile çok farklı! ! !  Her annenin çocukları misali özel.. Her biri ayrı bir güzel.. Ama en güzeli şarlırda seni bulmak biliyo...', ARRAY['Türk Edebiyatı','Şiir','Soner Demirez']::text[], 8.5, '{"poet":"Soner Demirez","poet_slug":"soner-demirez","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/biliyormusun-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda', 'elveda-soner-demirez-gzu0x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ve artık herşey bitti diyorsun..

Herşey bitti sen artı yoksun diyorsun..

Evet ben artık yokum, yokum..

Yüreğinde vardım seninle anlamlıydım..

Ben artık yokum bweynimdeki düşünceler de..

Bir hayal''dim cisim oldum...

Cisimden Hayal''e döndüm...

Önceleri sesim bile yetiyordu..

Şimdilerde sana sesimde çok gelir oldu..

Önce bedenimden, sonra sesimden geçtin..

Bana ait ne varsa hepsini elnn tersiyle ittin..

Yakaladığın güveni yıkmak değil, bana artık gitmek düşer..

Evet  yıldız gözlüm bana artık gitmek düşer...

Göçebe bir kuş ruhum, bu gün bende yarın, kim bilir nerde...

Bunlar sana veda sözlerim bebeğim..

Sevgine o kadar inanmışi o kadar güvenmiştim ki; 

Ama görüyorum ki; herşey boş herşey yalan bu dünyada..

Evet bitanem son defada olsa sesini duydum..

Şimdi gönül rahatlığıyla veririm bu canımı..

Oysa ne güzel planlarım vardı..

Biraz para biriktirecek yanına gelecektim..

Beraber el ele omuz omuza savaşacaktık hayatla..

Bütün gün beni özleyen bir olduğunu bilecektim..

İş çıkışı sana kavuşmak için acele edecektim..

Ve görüyorum ki; ***** seninde dediğin gibi, 

Evet ben hayata pembe gözlüklerle bakmışım..

İşte bir fırtına dağıttı o pembe bulutları..

Ben sana ne mutluluk nede güven verememişim..

Oysa sen inamasdanda yüreimn en güzel yerinde taht''ın...

Ve şimdi o taht''ı da yıkıp gidiyorsun..

Bende gidiyorum canım daha önce gitmediğim, 

Bilmediğim diyarlara yolcuyum..

Kim bilir_? 

Belki bir gün yeniden kavuşuruz..

Elveda gözbebeğim elveda...', 'Ve artık herşey bitti diyorsun.. Herşey bitti sen artı yoksun diyorsun.. Evet ben artık yokum, yokum.. Yüreğinde vardım seninle anlamlıydım....', ARRAY['Türk Edebiyatı','Şiir','Soner Demirez']::text[], 8.5, '{"poet":"Soner Demirez","poet_slug":"soner-demirez","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/elveda-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Feryat', 'feryat-soner-demirez-i9qnu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Fermanım elinden olsun be odun gözlüm..

Ellerini tutmak gözlerine bakmak nasibim olsun, 

Rahat yüzü görsün ayrı bedenlerdeki tek yürek..

Andımız olsun, bir daha ayrılmamak..

Yadeller de sürgün olmasın sevdamız..

Lal olmuş dilim, kelimeler suskun..

Ey gözleri sürmelim yüreği gamlım..

Fallara kalmasın yaşadığımız sevda..

Kahreden bir kader bu yaşadığımız zulüm..

O kadar ki; özlşemle yanan yüreklerimiz çöl olmakta..

Neden böyle olduk, diyemem odun gözlüm..

Unutamam yaptığım sahtekarlığı..

Kendim ettim, kendim buldum dünyası bu..

Lif lif parçalansa dağılsa bedenim..

Unutmadım..

Unutamam seni be odun gözlüm..', 'Fermanım elinden olsun be odun gözlüm.. Ellerini tutmak gözlerine bakmak nasibim olsun,  Rahat yüzü görsün ayrı bedenlerdeki tek yürek.. And...', ARRAY['Türk Edebiyatı','Şiir','Soner Demirez']::text[], 8.5, '{"poet":"Soner Demirez","poet_slug":"soner-demirez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/feryat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesin', 'sesin-gokcen-duran-kp4xg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Can  oldu   sesin, 

           Neyin nefesine  düştü.

                      Şad  oldu  bütün  alem

  Bülbül  oldu  sesin, 

                Gönlümün kafesine düştü.

                                   Yad  oldu  bütün  alem.

Çiy  oldu  sesin, 

         Gülün  handesine  düştü.

                       Zad  oldu  bütün alem.

                                              

                                               Çığ oldu sesin, 

        Aklıma düştü.

                      Mevat  oldu bütün alem', 'Can  oldu   sesin,             Neyin nefesine  düştü.                       Şad  oldu  bütün  alem   Bülbül  oldu  sesin,                  G...', ARRAY['Türk Edebiyatı','Şiir','Gökçen Duran']::text[], 8.5, '{"poet":"Gökçen Duran","poet_slug":"gokcen-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sesin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Ve Ses', 'i-nsan-ve-ses-gokcen-duran-p0350', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Farkında   olmadan   yitiririz  sevdiklerimizi

Bir   yıldızın  gökyüzünden  kayması   gibi

Önce  yıldız  kaybolur,  arkasından  izi 

Sevdiğimizin  yokluğu  acıtsa  da  içimizi

Yokluğunda  sesinin  gölgesi  serinletir  bizi

                   

                                                                        

                  ''''Sesler,  seslerde  kaybolur.

                                 Bir  insan,  kaybettiklerini

                                        Bir  insanın   sesinde  bulur....’’', 'Farkında   olmadan   yitiririz  sevdiklerimizi Bir   yıldızın  gökyüzünden  kayması   gibi Önce  yıldız  kaybolur,  arkasından  izi  Sevdiği...', ARRAY['Türk Edebiyatı','Şiir','Gökçen Duran']::text[], 8.5, '{"poet":"Gökçen Duran","poet_slug":"gokcen-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/insan-ve-ses-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevincim', 'sevincim-gokcen-duran-s937h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir nehir suyunun, 

Denize, 

Bir annenin 

Çocuğuna, 

Kavuşma sevinci ne ise.

Sesimi, sesine, 

Gözlerimi, gözlerine

Ellerimi, ellerine

Kavuşturma sevincim odur...', 'Bir nehir suyunun,  Denize,  Bir annenin  Çocuğuna,  Kavuşma sevinci ne ise. Sesimi, sesine,  Gözlerimi, gözlerine Ellerimi, ellerine Kavuşt...', ARRAY['Türk Edebiyatı','Şiir','Gökçen Duran']::text[], 8.5, '{"poet":"Gökçen Duran","poet_slug":"gokcen-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevincim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Buluşma', 'i-lk-bulusma-soner-demirez-d4pel', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu gün seninle ilk buluşmamız, günlerden cumartesi..

Sabahtan beri bekliyorum, nerde kaldın hayal perisi_? 

Gece çıkmışım yola sabaha karşı yanındaydım..

Artık seninle aynı şehrin havasını soluyorum..

Bursa-İstanbul arası dört saat yol gelmişim..

Gözlerimde uyku yok, inede sadece sen varsın bebeğim..

Harem otogarına adım attım, artık bir  adım daha yakınım sana..

Bir adım daha yaklaştım hep düşlerimde gördüğüm hayalime..

Yüreğim arı kanadı hızında çarpmakta..

Yolum Kadıköy''e bitanemin olduğu semt''e, bitaneme..

Çantasmı vurdum sırtıma koyuldum yola..

Yettim bitanem yettim, artık seninle aynı semtteyim..

Eminönü iskelesi önündeki postanedeyim..

Yüeğimin sesiyle sana telefon açıyorum..

Duy bitanem duy sana olan özlemimi hasretimi duy, 

Heyecanımı sesimin titreyişinde duy..

Geleceğim, öğlene yanındayım diyorsun..

heyecanım katlanıyor bir kat daha, bekliyorum..

Söylediğin gibi bebeğim Adalar iskelesi önünde.

Zaman geçmek bilmiyor, sanki saatler bana düşman..

Volta atıyorum iskele önünde, denizdeki gemi gibi yalpalayarak..

Oturuyorum banklardan birine..

Çok  bekletmeden geçiyorsunömümden....

Allah''ım nerde o heyecan ben seni yıllardır tanıyorum..', 'Bu gün seninle ilk buluşmamız, günlerden cumartesi.. Sabahtan beri bekliyorum, nerde kaldın hayal perisi_?  Gece çıkmışım yola sabaha karşı ...', ARRAY['Türk Edebiyatı','Şiir','Soner Demirez']::text[], 8.5, '{"poet":"Soner Demirez","poet_slug":"soner-demirez","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ilk-bulusma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-soner-demirez-94b1n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hani bir yıldız kayar''ya gökyüzünde, 

İnsan düşünürya kimim ben, neyim, yolum nereye_? 

Çıkmaz sokaklara düşer ya yolun..

Yürürsün yeniden sokağın başına..

Ben bir yıldızdım canım, canözüm, 

Gözlerinden kaydım gittim bilinmezlere apansiz...

Öyle hızlı, o kadar sert düştüm ki; 

Kırdığım kalbini onarmaya güç bulamadım....

Neydim ben, kimdim, kendimi ne sanmışım_? 

Seni üzmek hakkını bana kim vermiş_? 

Heleki başkasına kızmışken seni üzmek neden_? 

Anlamsız yere kırdığım kalbin benden hesap soruyor...

Çıkmaz sokaklara ittim seni...

Oysa sokağın sonuna gitmeni istememiştim..

Sokağın başında kollarından tutup seni, 

Göğüs kafesimden içeri sokmak istedim

Gitme gitme be odun gözlümbenden uzağa...

Çektirmeyelim bu cefayı yüreklerimize..

Gel gitme, yeniden başlayalım..

Tek bedende tek ruh olalım..', 'Hani bir yıldız kayar''ya gökyüzünde,  İnsan düşünürya kimim ben, neyim, yolum nereye_?  Çıkmaz sokaklara düşer ya yolun.. Yürürsün yeniden s...', ARRAY['Türk Edebiyatı','Şiir','Soner Demirez']::text[], 8.5, '{"poet":"Soner Demirez","poet_slug":"soner-demirez","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gitme-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Santa-Maria', 'santa-maria-tahir-yuksel-hdlwj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hırçın denizle boğuşan sen değildin dostluk için

sen değildin yepyeni ufuklara umut götüren

martı çığlıkları ve fırtına ıslıkları arasında

kıpırdanan palmiye dallarına uygarlık sunan

ve timsahların bulanık sudaki fokurtularından

apartmanların delik deşik ettiği

dupduru gökleri kurtaran

vahşî savaşın enkazından

yaraları sarmaya giden

sen değildin

sen değildin santa-maria

kemik veremine tutulmuş bir hastanın

eklemlerindeki sızıyı taşıdın denizaşırı

bilsinle diye

varsın bilmesinlerdi

kızılderililer

ve karaderililer

katranlara eş -uygar-lığını

ve de

kölesi olduğun ve silah ve afyon ve seni

günahların zirvesine tak kurdun

ve kurban ettin en taze çocukları

kusmuk kusmuk tüm dünyaya taşıyıp

hınçlı duyguları bir hamlede

güçsüz forsaların kürek darbeleriyle

ve tepeleme kin yüküyle

yırttığın deniz gibi

karanlıklardan

karanlık taşıyarak kara sahillere

vebâl oldun

vebâl oldun santa-maria', 'hırçın denizle boğuşan sen değildin dostluk için sen değildin yepyeni ufuklara umut götüren martı çığlıkları ve fırtına ıslıkları arasında k...', ARRAY['Türk Edebiyatı','Şiir','Tahir Yüksel']::text[], 8.5, '{"poet":"Tahir Yüksel","poet_slug":"tahir-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/santa-maria-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buhara Geceleri', 'buhara-geceleri-tahir-yuksel-8t20u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '-üç zamanlı bir şiir-

a)   şimdiki zaman

buhara gecelerinden çaldığımız

yıldızları katranlara bulayıp 

şimşekleri çamurla mühürleyerek

gökyüzünü

can sıkıntısı mağrur müsvetteler gibi

perişan dalgaların süksesine fedâ edip

sisleri içerek baygın dudaklarımızla 

güneşin mânâsını dahi düşünmeye

dondurup bir kenara fırlattığımız zamanı

binbir hile ile bahane ederek

fırsat bulamadığımız o güneşleri

övünerek ihmal edip

sonra da kör pişman

gecelere mi sığınacaktık

b)   geçmiş zaman

yorumlarımız aldattı ilkönceleri bizi

saltanatın cakasına tutulduk da

özendik teker teker romenos diegenos püskülüne

bir yıldız kaydı buhara semalarından

bir alparslan vakarına

gözlerimizi kapadık bilmem kaç asır önceden

duygulara heykel dikmek için

aşkları transatlantiklere yükledik

taşınmak

kaçıp gitmek için gündüzlerden

usanmadan

ve de utanmadan geride bıraktığımız işaretsiz mezarlardan

duman duman âh eden 

kılıç arslan erlerindenparfüm kokan bizans entrikalarına

kara osman bir masaldı bize lüzumsuz

geceye boyun eğmeyen

ayakta sabahı bekleyen

gül desenli sevdâlarına övülmüş kumandanlığı tercih eden

mehemmed hân''ın

tarihe sarrafcasına şekil verişini

umursamadık da bizans gibi

isli gecelere demir attık övünçle

ve kıvrandık durduk kültür sancılarında bunca zamandır

bizans ile koyun koyuna

c)   gelecek zaman

bulutsuz yaz gecelerinde bir ışık yanıp söner 

                                                                  /buhara  semalarından

kafa tutan sihir vardır karanlıklara

elektrik ampulleri buz tutmuştur

bizans iptal edilmiştir kırmızı kalemle çaprazlama

göğsümüze kadar saplandığımız senfoniden geriye

patlayan flaşların tesbit ettiği acı kahkahaları

teker teker yakacağız buhara gecelerinde

yanlış seçilmiş sevgilinin ihaneti diye de

osman gazi gibi ayakta bekleyeceğiz

müjdelenen sabahı

buhara gecelerini yırtarak', '-üç zamanlı bir şiir- a)   şimdiki zaman buhara gecelerinden çaldığımız yıldızları katranlara bulayıp  şimşekleri çamurla mühürleyerek gökyü...', ARRAY['Türk Edebiyatı','Şiir','Tahir Yüksel']::text[], 8.5, '{"poet":"Tahir Yüksel","poet_slug":"tahir-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/buhara-geceleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemin Soluğumdu', 'ozlemin-solugumdu-ozgun-enver-bulut-5giz5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sanıyorum özlediğim gündü.dündü. 

elveda kadar bir boşluktu ayrılık 

geceydi.sana değiyordu. 

saçlarım gözlerin diyordu. 

ötelerde dağılan yürekler gibi efkarlıyken sular 

düşen yıldızlar kadar eksilir gökyüzü 

gündüz hükmü olmayan gölge 

hüzündür.düşer geceye. 

iz sürer bir baba 

gölge yanar. 

sanıyorum özlediğim gündü.dündü. 

gitarın eskiyen tellerinde eriyordu sözlerim 

kimsenin merak ettiği de yoktu 

ölüm sadece öleni yakıyordu 

ötekiler yangından çok uzaktı. 

nasıl düşerim ardına şimdi 

dudakların böyle giz doluyken 

hançeri suluyor gözyaşlarım intihar öncesi 

uzaksın. hangi mefsimde öleceğimi düşünüyorum 

babam da uzak 

anneme benziyor acılı kadınlar 

kırık tırnaklarıyla geziyorlar 

sanıyorum özlediğim gündü. dündü. 

gözlerim kördü. kötülük vurmuştu 

günahlarımı temizliyordu kalbin 

düşündüğüm son barınaktı istanbul 

sarsıyordu. özlemin soluğumdu. soğuktu. 

ellerin kayıyordu.', 'sanıyorum özlediğim gündü.dündü.  elveda kadar bir boşluktu ayrılık  geceydi.sana değiyordu.  saçlarım gözlerin diyordu.  ötelerde dağılan y...', ARRAY['Türk Edebiyatı','Şiir','Özgün Enver Bulut']::text[], 8.5, '{"poet":"Özgün Enver Bulut","poet_slug":"ozgun-enver-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ozlemin-solugumdu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seher İçin Türkü-1', 'seher-i-cin-turku-1-tahir-yuksel-jpu2w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'o seherler söktü yosunlu kemiklerin ördüğü surları

kaskatı bakışların çivilediği

çöl susuzluğunu yudum yudum

kaybolmuşlar çağının alın yazısını

o seherlerdi elbet çarmıhları parçalayan

meleklerin kanadıyla

alan kara yazgıyı

nur yüzlü anaların kalbinden

tereddütü silen zerre zerre imanlardan

ve inananlardan ölüm korkusunu

şarap sarhoşluğu ile

buzağıya secde eyleyen israil oğullarını 

lânetlerin lânetiyle lânetleyen

ve o havarileri 

o''nun yerine çarmıha çivileyen seherler

kıpkızıl çöl kumlarını

yavrularını

canlarını

dizüstü kahkahalarla ağlayarak gömen babaların

küstah günahlarını elinden alıp

sıvı demir potasınca yanmış yüreklere

bir topuk darbesiyle billur suyu

karşılıksız sunan seherler

atlar deryâya da sürülür

bunalmışların umudu tanrı adını

fırtınaların ulaşamadığı ıssız diyarlara götürmek için

o kutlu seherlerde', 'o seherler söktü yosunlu kemiklerin ördüğü surları kaskatı bakışların çivilediği çöl susuzluğunu yudum yudum kaybolmuşlar çağının alın yazıs...', ARRAY['Türk Edebiyatı','Şiir','Tahir Yüksel']::text[], 8.5, '{"poet":"Tahir Yüksel","poet_slug":"tahir-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/seher-icin-turku-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seher İçin Türkü-2', 'seher-i-cin-turku-2-tahir-yuksel-z9xdc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'tarih takvimde kaybolmuşken

ben de ulu bir çınarın doruklarından öte

bilmem hangi ayın hangi gününde

yürüdüm atom çekirdeğini patlatarak

ak bulutların üstünden kürre-i arzı aşarak

bütün sırlarımı sizlere hediye ettim ey insanlar

göklerin kahkahası bana vız gelir

vız gelir yıldırımlar zelzeleler

siz arayın kendinizi yerkürede ve habbede ve kubbede

benimse kaldırımları eze eze gittiğim

çakmak çakmak çıngıların içinden

aradığım o seherler kutludur', 'tarih takvimde kaybolmuşken ben de ulu bir çınarın doruklarından öte bilmem hangi ayın hangi gününde yürüdüm atom çekirdeğini patlatarak ak ...', ARRAY['Türk Edebiyatı','Şiir','Tahir Yüksel']::text[], 8.5, '{"poet":"Tahir Yüksel","poet_slug":"tahir-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seher-icin-turku-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük Aşk''lar Bitermi', 'buyuk-ask-lar-bitermi-salih-ozalasan-e6anj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Buraya kadardı sevda, unut artık ismimi

Yırt at gitsin, sana bakan sararmış resmimi

Girmesin rüyalarına, çıkar gitsin cismimi

Geçmiş zamanlı anlatırsın artık sevgimi

Deme sakın, ben Aslı oda Kerem''di

Ağladığımı söyleme, artık gözyaşım tükendi

Elimdeki dağları delen ne kazma ne kürekti

Yüreğimde sevda, elimdeki kara kalemdi

Söyleme bilmesinler, ümitsizdi ama severdi

Serseri değildi ama, bana sonserserim derdi

Çoğu kez hüzünlüydü, arada bir gülerdi

O ne bir Mecnun, ne Kerem, ağlamak kaderim derdi

Kimbilir belkide ağlamak için beni severdi

Hüzünlerin şairiyim, gülmek bana haram derdi

Yüreği ağlardı, oysa yazdıkları gülümserdi

Adımı ne zaman ansa, yüreği tir tir titrerdi

Bilmesinler büyük aşk''lar kavuşmadan biterdi

Aslı Kerem derken sıra bize geldi

Belki onlar dağlar deldi; terini tüketti

Benimse sevdamı yazmaktan yüreğim tükendi

Kalmadı artık dayanacak gücüm sabrım

Sevdam yüreğimde, ama umudum tükendi

Sanmaki sana darıldı, kırıldı, gücendi; 

Yüreğinde sevdan, sonserseri''nin ömrü tükendi

(Y.Tar.19-12-2002 Saat 21.45)', 'Buraya kadardı sevda, unut artık ismimi Yırt at gitsin, sana bakan sararmış resmimi Girmesin rüyalarına, çıkar gitsin cismimi Geçmiş zamanlı...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/buyuk-ask-lar-bitermi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşi Yuyan Gözyaşları', 'gunesi-yuyan-gozyaslari-tahir-yuksel-d9x4j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kalem elimde değil pençemde artık

bulutsuz gökyüzünde şimşek misâli

kaçakçı kamyonlarının titrek farları

zekâ gibi

kör bıçakla kesilmeye çalışılan kurbanlar

zımparalıyor kelimeleri

kızgın saca dökülen kelimeler

buharlaşıyor hayâllerim

mendebur şehrin firavun asfaltında

kıyamete muştu taşıyor

saman sayfalara yazılmış şiirler

yedi kat yerin altından

mitos canavarları diş biliyor

gümbet-i devvârdaki nemli düşüncelere

üşüşüyor ebâbil kuşları

bombaları ki her biri bir evren

en soylu kureyş''in hali

ve çöl kuzgunları şimdi

ceset sömürüyor pırlanta dükkanında

balıklar sudan tiksiniyor

eğreltilerin boynu bükük

küfürler fethetti ay''ı güneş sırada gibi

delip geçiyor dünyayı ekvatora ters 

ve bir zamandan beri

sükûtun en anlamsızı abanmıştı yüreğimin üstüne

bezm-i elesti bilmediğimden', 'kalem elimde değil pençemde artık bulutsuz gökyüzünde şimşek misâli kaçakçı kamyonlarının titrek farları zekâ gibi kör bıçakla kesilmeye çal...', ARRAY['Türk Edebiyatı','Şiir','Tahir Yüksel']::text[], 8.5, '{"poet":"Tahir Yüksel","poet_slug":"tahir-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gunesi-yuyan-gozyaslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sus', 'sus-ufuk-nazim-ben94', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kırılgan bir kurulukta, 

Beni beklemen niye.

Bilirsinki ben sevince, 

Hoyrat severim.

Sorular uzaklaşsın benden, 

Kırdım acımadım.

Tutunduğum dalı kırdım 

Ve kırıldım.

İçimden yıkmak geldi köhneyeni, 

Eskiyen herşeyi.

Ve ilkin beynimde yıktım duvarları, 

Sonra çıktım sokaklara.', 'Kırılgan bir kurulukta,  Beni beklemen niye. Bilirsinki ben sevince,  Hoyrat severim. Sorular uzaklaşsın benden,  Kırdım acımadım. Tutunduğu...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sus-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Aleme Bir Gurbet', 'her-aleme-bir-gurbet-tahir-yuksel-q0yni', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'geceleri bekçi düdükleriyle ıslanan yıldızlar

buhar buhar ağıp

havuzlanan iblis''lerin damıtıldığı loş sokaklara

jale titrekliğinde ve kalp duyarlılığında apayrı bir âlem

her dem

kurban kurban solukları keserek

vücudu zelzeleye tutulmuş serserisinden

ve homurdayarak geceyi biçen üçotuzbeş ekspresinden

milyon üstü milyon kerre vatikan

pazarlanan kadının gözyaşındaki itirafın 

tek hecesi bile durdurur dünyamızı zıngadak

     ''sılanın acısı hançer olur da

      garibin dem be dem bağrına işler

      ağır ağır çöken her akşam vakti

      zamanı insanın beyninde dişler''

kimileri kaçar da fersah fersah adından

inkâr eder titrek mendilleri/gözyaşını

dökülen yaprakların her hazan vakti

ananın/kardeşin/yârin kalbinden

dua dua hasret 

küller de üstünü hüzzamlı yaranın

bakışları donuk cânânın çeyizinde işlidir

her türlü yorumdan ârî mısralar

     ''çocukça atılmış sapan taşının

      mendili ıslatan her gözyaşının

      devamlı kaynayan hasret aşının

      lügatte adına gurbet demişler''', 'geceleri bekçi düdükleriyle ıslanan yıldızlar buhar buhar ağıp havuzlanan iblis''lerin damıtıldığı loş sokaklara jale titrekliğinde ve kalp d...', ARRAY['Türk Edebiyatı','Şiir','Tahir Yüksel']::text[], 8.5, '{"poet":"Tahir Yüksel","poet_slug":"tahir-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/her-aleme-bir-gurbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leylâ vü Mecnûn', 'leyl-vu-mecn-n-tahir-yuksel-ebm5e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''Zaman, geçmiş ya da gelecek zamandır. Çöl... Sapsarı kumlar güneşin yakıcı ışıkları altında parıl parıl...  Göz alır ha bire.  Gökyüzü renksizdir.  Yeşilin bütün tonları hafızalardan silinmiştir.     Boğucu bir yel eser uzaktan uzağa...   Kuzgun sesleri..     Çöl,  Fuzûlî olmuştur; sessiz bir gazel okumakta. 

Taa ufukta  nokta gibi bir karartı vardır. Habire samyeli eser

dörtbir yandan. Burada yön de yoktur tıpkı yeşil gibi...''

modern çağın kadını mı ördü bu ağı aşkın adına

-ki iliklerde mızrak mızrak ışıkların çelengi-dir

gökyüzünde gömülü ölünün ayak ucundaki yıldızar

yıldızlar mı

yok yok sevinç gözyaşlarıdır yaşanmış aşklardan artakalan

esir çiçeklerin alınyazısıdır bu

gözlere mil çekilmişse

kumlar da kördür bundan ötürü -ve bundan böyle-

çiçeklerin suskunluğuna denk

çölü kaynatan aşkın mahiyeti

leylâ''yı görür mü hiç

leylâ bir hiçtir görebilen gözlerde

bir kadınsa -ki aranan-

serapların maviliğinde

esrarlı dumanların kıvrımı yok

mecnûn''un bıraktığı ayak izinde

okunabilir aşkın imzası

şol sahrâ vü deryâ içre

     ''Ve karartı ı yakalar. Çöl kükremektedir geçmiş ya da gelecek zamana doğru...''', '''Zaman, geçmiş ya da gelecek zamandır. Çöl... Sapsarı kumlar güneşin yakıcı ışıkları altında parıl parıl...  Göz alır ha bire.  Gökyüzü renk...', ARRAY['Türk Edebiyatı','Şiir','Tahir Yüksel']::text[], 8.5, '{"poet":"Tahir Yüksel","poet_slug":"tahir-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/leyla-vu-mecnun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seherle Gelen Muştu', 'seherle-gelen-mustu-tahir-yuksel-3dmsq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kutlu seherler kutlu muştu getirdi

bahar saflığında ve gül tazeliğinde

bir çocuk gülümsemesinde

şarka ve garba ve cenuba ve şimale

ve münkir''e ve nekir''e

nuh''a ve ibrahim''e ve mesih''e

ve mustafa''ya çoban yıldızı ve samanyoluyla

geceler miraç

sular zemzem

dünya irem olmasa da artık

sahibine sevdâlı bir gönül

dirilen süleymaniye'' de

ve aksa''da ve o''nun beytinde

kalbe verilen fermandır aşk için

salât-ü selâm vaktinde', 'kutlu seherler kutlu muştu getirdi bahar saflığında ve gül tazeliğinde bir çocuk gülümsemesinde şarka ve garba ve cenuba ve şimale ve münkir...', ARRAY['Türk Edebiyatı','Şiir','Tahir Yüksel']::text[], 8.5, '{"poet":"Tahir Yüksel","poet_slug":"tahir-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/seherle-gelen-mustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buğulu Camlar', 'bugulu-camlar-akin-kir-f15i8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ayaz vurmuşken geceye

Hayallerdi içimi ısıtan

Yüreğimi okşar bir çift göz

Bir ses çağırır beni

Bir of çekerim derinlerden

Buğulanır bütün camlar

Ve senin adındır

Buğuya kazınan', 'Ayaz vurmuşken geceye Hayallerdi içimi ısıtan Yüreğimi okşar bir çift göz Bir ses çağırır beni Bir of çekerim derinlerden Buğulanır bütün ca...', ARRAY['Türk Edebiyatı','Şiir','Akın Kır']::text[], 8.5, '{"poet":"Akın Kır","poet_slug":"akin-kir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bugulu-camlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatmak İstediğim', 'anlatmak-i-stedigim-akin-kir-xu7oz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Birşeyler var anlatmak istediğim

Ne olduğunu bildiğim halde

Bir türlü söyleyemediğim

Bakma bana öyle

Benim suçum değil

Daha bulunmadı kelimesi

Sana olan sevgimin', 'Birşeyler var anlatmak istediğim Ne olduğunu bildiğim halde Bir türlü söyleyemediğim Bakma bana öyle Benim suçum değil Daha bulunmadı kelime...', ARRAY['Türk Edebiyatı','Şiir','Akın Kır']::text[], 8.5, '{"poet":"Akın Kır","poet_slug":"akin-kir","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/anlatmak-istedigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sokak Çocuğuyum', 'ben-sokak-cocuguyum-servet-yuksel-ryd43', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben sokak çocuğuyum adımı bilmezsiniz.

Benimde bir dünyam var çağırsam gelmezsiniz.

Bir köprü altı bile bulamadım sürtecek.

Gece yarılarında üstümü kim örtecek? 

Vebali boynunuza toplumun günahıyım.

Sevgiden mahrum kalmış yüreklerin ahıyım.

Annesizlik zemheri iliklerim üşüyor.

Kolum kanadım kırık, gönlüm yorgun düşüyor.

Ne olur sanki bende baba eli tutsaydım.

İçimde dönüp duran acıyı unutsaydım.

Bir bardak çayda yeter yanında simit olsun.

Yalnız hayata dair azıcık ümit olsun.

Bir düşünün nelerdi zevkle tattıklarınız.! 

Helal edxn, mxdemde çöpe attiklariniz..! 

Gelin görün çaldığım bütün kapılar duvar.

Hüzünlü rüyalarım, yetim hayallerim var.

Sırtımda garibliğin, yoksulluğun hırkası.

Bakmaktan çekinmeyin yüzüm ibret aynası.

İyileri ararken, kötüler beni bulur.

Masum duygularıma ne tuzaklar kurulur.

Bakışlarınız bıçak, sözünüz var ki kırbaç! 

Merhamet dilendiğim benden daha çok muhtaç.

Özlediğim şeylerden bahsederler duyarım.

Herkes güzel giyinir, ''bayram'' derler duyarım...

Bahtıma küstüm işte evim, oyuncağım yok.

Koşup atılacağım bir şefkât kucağım yok…

Siz keyfinize bakın, size tantana düşer.

Dokuz kere  yutkunmak, ağlamak bana düşer.', 'Ben sokak çocuğuyum adımı bilmezsiniz. Benimde bir dünyam var çağırsam gelmezsiniz. Bir köprü altı bile bulamadım sürtecek. Gece yarılarında...', ARRAY['Türk Edebiyatı','Şiir','Servet Yüksel']::text[], 8.5, '{"poet":"Servet Yüksel","poet_slug":"servet-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ben-sokak-cocuguyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tac-Mahal''den Gökdelene Gelende', 'tac-mahal-den-gokdelene-gelende-tahir-yuksel-bvs5d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yıldızlar benimdi bir zamanlar avuç avuç

çocuklara dağıtırdım hep bayramlarda

büsbüyük mutluluklar vardı küçücük tebessümlerde

ve bir zamanlar

ben vardım bizlerden mürekkep

bizleri bilen adım gibi

yoktan icat ettim lüks olsun diye

kafdağı''ndaki gûlyabanileri

bülbülleri baykuş yaptım caka satmakla

zümrüd-ü ankalardan öç aldım phantom kanatlarıyla

kudretimle avunmak /övünmek deriz ya/ için

velîliğin imtiyazını ipotek ettirdim deliliğe

başıboşluğun serabına demir attım zamanı sıfırlayarak

gülüp geçtim titrek gözyaşlarına

ki soluk bir asker mektubu gibi

hasretin mahzunluğu vardı işiltısında

ama

yalvarmanın acizliğini görmedim

dönüp bakmadım bile tereddütlü dudaklara

acı bir çizgi buruk bir vicdan

sürdüren varlığın kavgasını bir çift dudaktır iki gözle birlikte

biri altta

biri üstte öylece ya da yanyana

sadakati heceleyen kıpır kıpır saadeti kaybederken

gene de istemeyen tükenmemi bu yağmada

ah ne çare ki

görmedim göstermediler bu sükutu inadına

şimdi mi

gördüğünüz gibi dotlar

bildiğiniz gibi işte', 'yıldızlar benimdi bir zamanlar avuç avuç çocuklara dağıtırdım hep bayramlarda büsbüyük mutluluklar vardı küçücük tebessümlerde ve bir zamanl...', ARRAY['Türk Edebiyatı','Şiir','Tahir Yüksel']::text[], 8.5, '{"poet":"Tahir Yüksel","poet_slug":"tahir-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/tac-mahal-den-gokdelene-gelende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet', 'gurbet-tahir-yuksel-dtxi8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gurbet beni benden alıp

çilelere yâr eyledi

zaman yedi güllerimi

sevgimi de nâr eyledi... 

sürükledi suyunda

yer vermedi koyunda

ölüm denen oyunda

tabutumu zar eyledi... 

akşam hüzün gelince

hasret dokur ince ince

gün sonunda ölünce

mezarımı dar eyledi', 'gurbet beni benden alıp çilelere yâr eyledi zaman yedi güllerimi sevgimi de nâr eyledi...  sürükledi suyunda yer vermedi koyunda ölüm denen ...', ARRAY['Türk Edebiyatı','Şiir','Tahir Yüksel']::text[], 8.5, '{"poet":"Tahir Yüksel","poet_slug":"tahir-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gurbet-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlük ya da Sonsöz', 'dortluk-ya-da-sonsoz-tahir-yuksel-kg56d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaçışım kurtarmadı beni bataktan, 

Nurlu bir bekleyiş; yeniden doğum.

Ya Rabbî bu olmayacaksa bari

Ne olur geri gelsin çocukluğum...', 'Kaçışım kurtarmadı beni bataktan,  Nurlu bir bekleyiş; yeniden doğum. Ya Rabbî bu olmayacaksa bari Ne olur geri gelsin çocukluğum......', ARRAY['Türk Edebiyatı','Şiir','Tahir Yüksel']::text[], 8.5, '{"poet":"Tahir Yüksel","poet_slug":"tahir-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dortluk-ya-da-sonsoz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai-97-465-', 'rubai-97-465-mevlana-celaleddin-rumi-2vca1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '465

Göğsünün  içindekini gerçek gönül sanan kimse, 

Hak yolunda iki üç adım attı daherşey oldu bitti sandı

Aslında tesbih, seccade, tövbe, sofuluk, günahdan sakınma  bunların hepsi yolun başıdır.Hak yolcusu aldandı da, bunları varacağı yer sandı.

97

O eşsiz, parlak incinin hayali, gözümün önüne geldi.

O anda kendimi tutamadım, ağlamaya başladım.

Gözyaşlarım akarken  içim yanıyordu.

Heyecandan şaşırmıştım.Gizlice  gözümün kulağına dedim ki; 

biliyormusun? ''Gelen konuk, çok değerlidir, çok azizdir''

Ona bol bol aşk şarabı sun.', '465 Göğsünün  içindekini gerçek gönül sanan kimse,  Hak yolunda iki üç adım attı daherşey oldu bitti sandı Aslında tesbih, seccade, tövbe, s...', ARRAY['Türk Edebiyatı','Şiir','Mevlana Celaleddin Rumi']::text[], 8.5, '{"poet":"Mevlana Celaleddin Rumi","poet_slug":"mevlana-celaleddin-rumi","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/rubai-97-465-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatan Ettik Bu Yurdu', 'vatan-ettik-bu-yurdu-cevat-karabacak-6m11o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Selam ve dua ile

Dilde tevhid Lâ ilâhe illallah, 

Bile, bile vatan ettik bu yurdu.

Yardık Kayaları hep evvel Allah, 

Dele, dele vatan ettik bu yurdu.

Yetmedi meydan dar oldu dar bize, 

Ne ateş yanaştı ne kızıl kor bize...

El oldu dost, yaran, ana ve yar bize

Öle, öle vatan ettik bu yurdu.

Savaş ettik düğüne çıkar gibi, 

Mermi tuttuk gelini çeker gibi.

Aslanın ağzından hep söker gibi, 

Ala, ala vatan ettik bu yurdu.

Büründük Yaratanı zikirlere, 

Bağlandık sarsılmayan fikirlere.

Tanklar geçmeyince tüm çukurlara, 

Dola, dola vatan ettik bu yurdu.

Bilevledi bizi çekilen çile, 

Bismillah deyince yıkıldı kale.

Kahırlar gırtlaktan yapışsa bile, 

Güle, güle vatan ettik bu yurdu.

Edirne de neysek aynıyız Van’da, 

Kenetlendik bir, bir şerefte şanda.

Gelinlik içinde Fatma mı kanda, 

Bula, bula vatan ettik bu yurdu.

Kolay mı sanırsın sözü dilime? 

Mermiyi beledik kışta kilime.

Bebeği unuttuk, kar da ölüme, 

Sala, sala vatan ettik bu yurdu.

Kaptırma, kaptırma sakın çapsıza! 

Oyuncak eyleme üç hesapsıza.

Çektik de süngüyü bunca sapsıza, 

Çala, çala vatan ettik bu yurdu.

Dondurdu cephede bizi ayazlar, 

Neleri anlatsam söze sığmazlar...

Karların üstünde Hakka Namazlar, 

Kıla, kıla vatan ettik bu yurdu.

Boşa mı sanırsın bunca çabalar? 

Analar ağladı, öldü babalar

Tifolar, Sirozlar, salgın vebalar, 

Sola, sola vatan ettik bu yurdu.

Kalsak açlıktan bir kemik bir deri, 

Şerefle yürüdük koştuk ileri.

Hakkettik, Vallahi alından  teri, 

Sile, sile vatan ettik bu yurdu.

Gelmesin bir daha o gün geriye, 

Uyanık ol Cevat bak ileriye! 

Bizler kuru bir ekmeği yarıya, 

Böle, böle vatan ettik bu yurdu.', 'Selam ve dua ile Dilde tevhid Lâ ilâhe illallah,  Bile, bile vatan ettik bu yurdu. Yardık Kayaları hep evvel Allah,  Dele, dele vatan ettik ...', ARRAY['Türk Edebiyatı','Şiir','Cevat Karabacak']::text[], 8.5, '{"poet":"Cevat Karabacak","poet_slug":"cevat-karabacak","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/vatan-ettik-bu-yurdu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neler Unutulmaz', 'neler-unutulmaz-muammer-tukenmez-ikn9j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yağmulu bir havada şemsiyemi

Soğuk bir havada paltomu

Her sabah çay içmeyi

Yaşadığım şehrin sokaklarını

Sabahları gazete almayı ve işe gitmeyi.

Dün yağmulu soğuk bir havada

Sabahın köründe çayımı bile içmeden

Nereye gitdiğimi bilmeden

Şemsiyesiz ve paltosuz

Bu adını bile unutduğum sokaklarda  dolaşıp durdurken

Boş boş bakan gözlerimden akan iki damla yaşla

Bir anda unutmuşken herşeyi

Bir tek seni hatırladım.', 'Yağmulu bir havada şemsiyemi Soğuk bir havada paltomu Her sabah çay içmeyi Yaşadığım şehrin sokaklarını Sabahları gazete almayı ve işe gitme...', ARRAY['Türk Edebiyatı','Şiir','Muammer Tükenmez']::text[], 8.5, '{"poet":"Muammer Tükenmez","poet_slug":"muammer-tukenmez","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/neler-unutulmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tablo', 'tablo-muammer-tukenmez-1dlg8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Odamda güzel bir tablo var

İçinde üç beş yelkenli olan güzel bir liman

Bazen canım sıkıldığı zaman

Geçip karşısına dalıp gidiyorum.

İnip limana, atlıyorum bir kotraya

Rüzğarın estiği yana

Dalıp gidiyorum ta uzaklara.', 'Odamda güzel bir tablo var İçinde üç beş yelkenli olan güzel bir liman Bazen canım sıkıldığı zaman Geçip karşısına dalıp gidiyorum. İnip lim...', ARRAY['Türk Edebiyatı','Şiir','Muammer Tükenmez']::text[], 8.5, '{"poet":"Muammer Tükenmez","poet_slug":"muammer-tukenmez","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/tablo-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alçak Duvarlar', 'alcak-duvarlar-zerrin-oktay-4ilo7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben zaman zaman

buharlaşıyorum galiba

tıpkı şimdi olduğu gibi...

bir anda çevremi, içimi

bir yabancılıktır sarıyor

acaba burası dünyada bir yer mi? 

Ne kadar hızlı uçuyor şu duvarlar

yoksa, uçan ben miyim? 

hayır! ben bir minibüsün içindeyim

minibüs bir araçtı, değil mi? 

Dışarıya bakıyorum oturduğum yerden 

duvarların sonu gelmek bilmiyor 

pencereli duvarlar, 

kapılı duvarlar, 

boyalı, 

yazılı duvarlar... 

ve duvardan duvara 

koşuşturan insanlar.. 

Sesler duyuyorum etrafımda 

bildiğim bir dil bu, 

ama anlayamıyorum 

gördüklerim mi, 

yoksa ben miyim çözümleyemediğim? 

delirmek mi beni korkutan, 

yoksa zaten deli miyim? 

Son durak... kara toprak demişler 

benimkisi son duraktan bir öncesi 

bakırköy akıl hastanesi 

hastanenin duvarları kalındır, 

kolay olmaz delmesi 

Evdeki duvarlar delik delik 

hep yara... 

yıllardır acılarımı aktardım onlara 

seyrettim, konuştum doya doya 

evimin duvarları, 

şimdi sizde sıra 

Biraz da siz bana yaklaşın 

göndermeyin beni tımarhaneye, 

eğilin, 

biraz daha eğilin 

bunu gerçekten istiyorum, 

ben kararlıyım 

yıkılın duvarlar, 

başıma yıkılın! 

Yıkılın ve beni kurtarın 

buharlaşmaktan kurtarın 

sevgisizlikten kurtarın 

anılardan kurtarın... 

bu dünyadan kurtarın 

haydi! 

ne duruyorsunuz, yıkılsanıza 

alçak duvarlar!', 'Ben zaman zaman buharlaşıyorum galiba tıpkı şimdi olduğu gibi... bir anda çevremi, içimi bir yabancılıktır sarıyor acaba burası dünyada bir ...', ARRAY['Türk Edebiyatı','Şiir','Zerrin Oktay']::text[], 8.5, '{"poet":"Zerrin Oktay","poet_slug":"zerrin-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/alcak-duvarlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farkımız', 'farkimiz-mikdat-acikkapi-h0bg3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sen

yaşama sevincinle

dalga dalga gelen deniz

ben

durgun halimle 

sadece ve sadece dalga kıran

sen

mutluluk yolundaki

yelkenli gemi

ben

yaşam yolundaki

fakir balıkçı teknesi', 'sen yaşama sevincinle dalga dalga gelen deniz ben durgun halimle  sadece ve sadece dalga kıran sen mutluluk yolundaki yelkenli gemi ben yaşa...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Açıkkapı']::text[], 8.5, '{"poet":"Mikdat Açıkkapı","poet_slug":"mikdat-acikkapi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/farkimiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Kendim İçin Sevdim', 'seni-kendim-i-cin-sevdim-mikdat-acikkapi-g29up', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüreğimde besledim sevdanı

kanımla canımla

benliğime yerleştirdim

yokluğunun yalnızlığını acını bilirim

yanımda olmanın yok imkanı

ama

seni kendim için sevdim

Dağların oğluyum 

yalın çıplak geçitsiz

anlamazsın dilimizden 

ağıtlarımızdan

uyutmaz seni ninnilerimiz

lorilori de lorilori bebeğim lorilori

ezğisinde

yüreğin burkulmaz için ezilmez 

yanımda olmanın yok imkanı

ama 

seni kendim için sevdim', 'Yüreğimde besledim sevdanı kanımla canımla benliğime yerleştirdim yokluğunun yalnızlığını acını bilirim yanımda olmanın yok imkanı ama seni ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Açıkkapı']::text[], 8.5, '{"poet":"Mikdat Açıkkapı","poet_slug":"mikdat-acikkapi","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/seni-kendim-icin-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tombul Rüzgar', 'tombul-ruzgar-yalvac-ural-2-kt791', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tombul rüzgar esince, 

El sallar çamaşırlar.

Saçılır her bir yana

İnce dallar, yapraklar.

küçük maviş şaşırır

Bakınır çevresine, 

Kızar tombul rüzgara

Bağırır ''Git evine! ''', 'Tombul rüzgar esince,  El sallar çamaşırlar. Saçılır her bir yana İnce dallar, yapraklar. küçük maviş şaşırır Bakınır çevresine,  Kızar tomb...', ARRAY['Türk Edebiyatı','Şiir','Yalvaç Ural 2']::text[], 8.5, '{"poet":"Yalvaç Ural 2","poet_slug":"yalvac-ural-2","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tombul-ruzgar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Kenti', 'dus-kenti-salman-celik-5mewm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaybolmuş vs.lerimi ararken

uyuyup kalmışım yollarda

bir gün yollar bitecek diye düşündüm hep

birine rastladım umudun bittiği yerde 

yüreği benim gibi kocaman

sevgisi rüzgar gibi coşkulu 

kimsin dedi bana nerden geldin? 

cevap verdim ona

eski bir gaziantepli 

şimdi geziyorum düş gezginiyim

düş kentimi arıyorum 

ansızın kayboldu 

sonra merakımı susturdu 

-''Düş gezgini'' dedi bana; hitap et 

denizlere, okyanuslara, dağlara

sıradan bir anı olma, ansızın kaybol 

hoşgeldin 

doğru yerdesin 

burası DüŞ KENTi...', 'Kaybolmuş vs.lerimi ararken uyuyup kalmışım yollarda bir gün yollar bitecek diye düşündüm hep birine rastladım umudun bittiği yerde  yüreği ...', ARRAY['Türk Edebiyatı','Şiir','Salman Çelik']::text[], 8.5, '{"poet":"Salman Çelik","poet_slug":"salman-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/dus-kenti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dost Tanıdım', 'bir-dost-tanidim-salman-celik-9ntl7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Günlerden çarşamba 

bir dost tanıdım bugün 

belliki pek delidolu 

hani; 

kıpır kıpır derlerya 

zamanında kalbi yarılmamış değil onunda 

kara sisler yaşamış besbelli 

onu da yaralayanlar omuş olmalı 

o neşeli biriymiş aslında 

bazen ise kükrermi aslan gibi 

kafası küp gibi olsa da; 

iyi biriymiş aslında, çok pamuk kalpli 

bunu anlamak hiç zor değil

dostlarıyla uzun konumalar yaparmış

bir gün yorgun bir kuş misali gibi kanatlarını bırakmış

uzun uzun dinlemiş kalbinden gelen sesleri

kara sislere aldırış vermemiş zamanla

umursamamış boşlukları UMARSIZ olmuş 

o sadece yüreginden gelenleri dogrularmış 

kötülüklere bile deger vermiş zamanla 

fakat onlar umursanmayacak bir figüranmış ona göre

o, 

aşklarını, yakınlarını, hayatını

güzel bir şarkıya benzetirmiş 

ama çok güzel olmalıymış

yüreğinin içinden gelen ses bunu istiyormuş 

bu şarkı hiç bitmeyecekmiş ona göre

bazen hızlanır, bazense sönük bir ateşe dönermiş 

evet bugün yeni bir dost tanıdım 

adı...', 'Günlerden çarşamba  bir dost tanıdım bugün  belliki pek delidolu  hani;  kıpır kıpır derlerya  zamanında kalbi yarılmamış değil onunda  kara...', ARRAY['Türk Edebiyatı','Şiir','Salman Çelik']::text[], 8.5, '{"poet":"Salman Çelik","poet_slug":"salman-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bir-dost-tanidim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Heyecanı', 'ask-heyecani-salman-celik-q8i4k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Soğuk bir hava

bulutlar gökyüzünü kapamış

güneş dünyaya küsmüş sanki 

pencerenin önünde uçan kuşlara imrendim bir an 

nasılda özgürler, üşümüyorlar, korkuları yok 

işte sevgimizde böyle olsun ayışığı

aşk bize, 

denizde mavi bir dalga 

doğada bir yeşil

yağmurda rengarenk bir gökkuşağı kadar renkli 

kaybolan bir çocuğun annesini buluşu 

bir özlemin son buluşu kadar mutluluk dolu olsun 

hüzün denizin karşı kıyısında 

sevdamız bize yakın olsun 

sıcak bir havada alevlenen bu aşkı 

yağmurlar dalgalar topraklar  söndüremesin

aşk bize; 

sevginin mutluluk dağlarınn

aşk etekleri olsun...', 'Soğuk bir hava bulutlar gökyüzünü kapamış güneş dünyaya küsmüş sanki  pencerenin önünde uçan kuşlara imrendim bir an  nasılda özgürler, üşüm...', ARRAY['Türk Edebiyatı','Şiir','Salman Çelik']::text[], 8.5, '{"poet":"Salman Çelik","poet_slug":"salman-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ask-heyecani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak Tatlı', 'yasamak-tatli-salman-celik-yk8uy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Denizler, 

eskisi gibi gülmüyor

Sevgi, 

buzları eriten tek şey

İnanç, 

çok dertli yakınıyor

Güven, 

o kimseye güvenmiyor

Bahar, 

insanlar artık onu beklemiyor

Karlar, 

artık yağmak bile istemiyor

Dünya, 

tersine dönmekten bıkmış

Züürtler, 

onların derdi bambaşka

Kalemler, 

yalan yazmaktan usanmış

Yakamoz, 

deniz gülmüyorki düşsün 

Savaş, 

o hiç bitmez 

İnsanlar, 

hem uçlu hem güçlü 

''Yaşamak Tatlı'' diyelim de

söz yerini bulsun...', 'Denizler,  eskisi gibi gülmüyor Sevgi,  buzları eriten tek şey İnanç,  çok dertli yakınıyor Güven,  o kimseye güvenmiyor Bahar,  insanlar ar...', ARRAY['Türk Edebiyatı','Şiir','Salman Çelik']::text[], 8.5, '{"poet":"Salman Çelik","poet_slug":"salman-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yasamak-tatli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıplak Duygular', 'ciplak-duygular-ahmet-gumustekin-5zy5c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Neden saklıyoruz 

kalbimizi, 

neden saklıyoruz 

sevgimizi, 

Bunun ayıbı günahı 

nerede? 

Adeti, töresi, anenesi

nerede? 

Düşüncelerimizi duygularımızı 

saçmada olsa 

bütün saflığı ve çıplaklığıyla

ortaya serersek

kaybedeceğimiz ne? 

Kazanacağımız ne?', 'Neden saklıyoruz  kalbimizi,  neden saklıyoruz  sevgimizi,  Bunun ayıbı günahı  nerede?  Adeti, töresi, anenesi nerede?  Düşüncelerimizi duy...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Gümüştekin']::text[], 8.5, '{"poet":"Ahmet Gümüştekin","poet_slug":"ahmet-gumustekin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ciplak-duygular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sev Beni, Hadi Gel', 'sev-beni-hadi-gel-ahmet-gumustekin-lei0p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni sevmemi istiyorsun 

oysa bilmiyorsun ki 

ben zaten seni seviyorum. 

Farkında değilsin sevgimin ve aşkımın.

Sana gelmemi istiyorsun 

ama aslında yanında olduğumu görmüyorsun. 

Uzaklarda beni arıyorsun, 

benim seni zamanında aradığım gibi.

Fakat eminim bir gün sende beni bulacaksın 

benim seni bulduğum gibi.

Yalnız geçen gecelerde seni düşünüyorum, yapabileceklerimizi, yaşayabileceklerimizi hayal ediyorum. Senli bir geleceğin aslında 

hiç uzak olmadığını görüp seviniyor, 

fakat senin bana ne kadar 

uzak olduğunu görüp üzülüyorum. 

Bu da hayallerimin üzerine bir 

karabulut gibi çöküyor. 

İkimizin de ortak buluşma noktası şiirler.

İkimizde duygularımızı düşüncelerimizi, 

birbirimize söylemek isteyip de 

söyleyemediklerimizi şiirlerle

söylüyoruz ve rahatlıyoruz. 

İkimizde birbirimizi aynı yerde

arıyoruz fakat bulamıyoruz. 

Dörtlüklerin arasında benim

sana senin bana seslenişlerin 

yitip gidiyor.

İşte buradayım ve sana tekrar sesleniyorum, 

SENİ SEVİYORUM', 'Seni sevmemi istiyorsun  oysa bilmiyorsun ki  ben zaten seni seviyorum.  Farkında değilsin sevgimin ve aşkımın. Sana gelmemi istiyorsun  ama...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Gümüştekin']::text[], 8.5, '{"poet":"Ahmet Gümüştekin","poet_slug":"ahmet-gumustekin","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sev-beni-hadi-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-ahmet-gumustekin-vszcp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sabahın ilk saatlerinde 

Gökyüzünde o kızıl saçlarının 

serpilmesini izleyeceğim. 

Ilık bir rüzgar esecek, 

Tıpkı nefesin gibi, 

İç gıcıklayan ve huzur dolu. 

Her geçen dakika sıcaklık artacak.. 

Günün ilerleyen saatlerinde, 

Kavrulacağım nefesinle, teninle', 'Sabahın ilk saatlerinde  Gökyüzünde o kızıl saçlarının  serpilmesini izleyeceğim.  Ilık bir rüzgar esecek,  Tıpkı nefesin gibi,  İç gıcıklay...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Gümüştekin']::text[], 8.5, '{"poet":"Ahmet Gümüştekin","poet_slug":"ahmet-gumustekin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sen-200-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybetmek', 'kaybetmek-ahmet-gumustekin-uhc64', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni kaybetmekten korktukça 

seni kaybettiğimi farkettim. 

Seni sevdikçe de 

kendimi kaybettiğimi.

Ne yapacağımı düşünemiyorum 

sanırım aklımı kaybettim.', 'Seni kaybetmekten korktukça  seni kaybettiğimi farkettim.  Seni sevdikçe de  kendimi kaybettiğimi. Ne yapacağımı düşünemiyorum  sanırım aklı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Gümüştekin']::text[], 8.5, '{"poet":"Ahmet Gümüştekin","poet_slug":"ahmet-gumustekin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kaybetmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtlar Ağlasın', 'kurtlar-aglasin-hanifi-celebioglu-3zj4m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Parçalansın yürekler, kar’a kan damladı, 

Yırtılsın bağırlar, Necip uçmağa vardı, 

Kar’lar sussun, Gökler ağlasın

Dağlar yıkılsın, Kurtlar Ağlasın, 

Necip bir milletin evladıydı Necip, 

Kah Ötüken’de, kah Kırım’daydı Necip, 

Türküler sussun, sazlar ağlasın, 

Köpekler sevinsin, Kurtlar Ağlasın.

Atsız’ın kalemi, Kür’şad’ın kılıcıydı, 

Her nefesi düşmana kini, hıncıydı, 

Berlin sussun, Turan ağlasın, 

Vatikan sevinsin, Kurtlar ağlasın.

Tetiği çeken namert eller kurusun, 

Emri veren  el’in soyu kurusun, 

Zaman sussun,  çağlar ağlasın, 

Çakallar sevinsin, Kurtlar ağlasın.

Halis Türk idi Necip, katıksız halis Türk, 

Milleti necipti, kendisi halis Türk, 

Kansızlar sussun, Türkoğlu ağlasın, 

Domuzlar sevinsin, Kurtlar ağlasın.

Gözler sussun, yürekler ağlasın.

Pınarlar sussun, seller ağlasın, 

Sussun kahpe Dünya, Acun ağlasın, 

Sussun sahtekarlar, Kurtlar ağlasın.

Sussun artık albızlar, Rahmet ağlasın, 

Bütün Rahmetler Necip’e yağsın

İnciller sussun, Fatihalar ağlasın, 

Fatiha ağlayan,  Bozkurtlar ağlasın.', 'Parçalansın yürekler, kar’a kan damladı,  Yırtılsın bağırlar, Necip uçmağa vardı,  Kar’lar sussun, Gökler ağlasın Dağlar yıkılsın, Kurtlar A...', ARRAY['Türk Edebiyatı','Şiir','Hanifi Çelebioğlu']::text[], 8.5, '{"poet":"Hanifi Çelebioğlu","poet_slug":"hanifi-celebioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kurtlar-aglasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mızıkçı Sevgili', 'mizikci-sevgili-barbaros-kilicgedik-0ttaj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerimi kapayıp oyunlar oynarım

Açtığımda sen olursun diye

Kapıyorum VARSIN

Açıyorum YOKSUN

Seni oyunbozan, MIZIKÇI sevgili...', 'Gözlerimi kapayıp oyunlar oynarım Açtığımda sen olursun diye Kapıyorum VARSIN Açıyorum YOKSUN Seni oyunbozan, MIZIKÇI sevgili......', ARRAY['Türk Edebiyatı','Şiir','Barbaros Kılıçgedik']::text[], 8.5, '{"poet":"Barbaros Kılıçgedik","poet_slug":"barbaros-kilicgedik","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/mizikci-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Tanrının Armağanısın', 'sen-tanrinin-armaganisin-cahit-i-pekoglu-3icsh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gerçeği

yannız seninle yaşamışım ben. 

Şaşkınlık içindeyim şimdi

ruhuma hakim olan, bir melekle.

Onca sevgililer içinde

sadece gerçek aşkı yaşar olmuşum bebeğimle... 

Tam zamanında

girmişti ruhu, ruhuma.

Sanki gülüm''le 

beraber gelmiştim dünyaya.

Yaşamak buysa

onca yaşanmışlıklar, yaşam değilmiş

Onca sevgiler 

değerini yitirirken, bana bebeğimi getirmiş..

Bak bebeğim

sen böyle, doğmuştun benim dünyamda.

Yaşam seninle yaşanırmış

zaman içindeki senin titreyişlerinde.

Yoksa senin ismin

bebeğim değil, yaşam''mıdır meleğim.

Benim için yeni değilsin

ruhuma ben doğarken, sen hediye edilmişin..', 'Gerçeği yannız seninle yaşamışım ben.  Şaşkınlık içindeyim şimdi ruhuma hakim olan, bir melekle. Onca sevgililer içinde sadece gerçek aşkı y...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sen-tanrinin-armaganisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mekansız', 'mekansiz-ufuk-nazim-pwy81', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mekansızdı: 

Bir bulut gibi, 

Oradan oraya akardı.

Baktımı ap ak bakardı.

Yargısız yaşadı.

Sorgularda dilsiz, 

Meydanlarda hatipti.

Işık bahçelerine çevirdi meydanları.

Yollarda geçti ömrü, 

Göçtü düşün bozkırlarına.

Kavak misali sallandı, 

Hırçın fırtınalarla sarsıldı.

Aşklar yaşadı, 

Her biri birer destan.

Şekilden şekile girdi sevdikleri, 

En sonunda takıldı güneşe.

Onu görenler, 

Parça parça bölüştüler onu.

Aynılık cehenneminde, 

Ömrünü çalanlardan korkmadı hiç.

Korkusuz yaşadı.

Bir bulut gibi, 

Yağamadan asılı kaldı, 

Önünde güneşin.', 'Mekansızdı:  Bir bulut gibi,  Oradan oraya akardı. Baktımı ap ak bakardı. Yargısız yaşadı. Sorgularda dilsiz,  Meydanlarda hatipti. Işık bah...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/mekansiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günü Sevdim Seninle Her GeLşimde', 'gunu-sevdim-seninle-her-gelsimde-cahit-i-pekoglu-6fwd3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gülü sevdim

beni sarhoş eden kokusuyla.

Günü sevdim

gülle beraber gelişiyle.

Her ikisini karıştırdım''da sevdim

GÜLÜM oluşuyla.

Neyini sevmedimki gülüm senin

alahım elimde alma diyen haykırışlarında.. 

Sevgiyi öğretti bana

sevilirken, her titreyişinde.

Bebeği sevdirdi bana

her aklına gelişinde, ağlayışlarında.

GÜLÜM''ü çok sevdim ama

alışamadım bir türlü, kayboluşuna...

Gülü sevdim

beni sarhoş eden kokusuyla.

Günü sevdim

gülle beraber gelişiyle.

Her ikisini karıştırdım''da sevdim

GÜLÜM oluşuyla.

Neyini sevmedimki gülüm senin

alahım elimde alma diyen haykırışlarında..', 'Gülü sevdim beni sarhoş eden kokusuyla. Günü sevdim gülle beraber gelişiyle. Her ikisini karıştırdım''da sevdim GÜLÜM oluşuyla. Neyini sevmed...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gunu-sevdim-seninle-her-gelsimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Olmalıyız', 'dost-olmaliyiz-ufuk-nazim-n51gx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşanması gereken bir hayat, 

Ellerimizde dostum.

Biz bütünün parçalarıyız, 

Dost olmalıyız.

Yalnızlığın çeperlerine, 

Takılmak değil senin istediğin.

Öznelliğin türevleri, 

Gene sensin.

Yüreğinin kuytusundan, 

Beyninin tümseğine, 

Yollar açmak, 

Senin ellerinde.

Umutların rüzgarına, 

Açıp bembeyez yelkenleri, 

Özgür limanlara yol almak, 

Bizim elimizde.

Yolculukların sonu yok güzelliklerinde.

Çakılmak bir kalbe, 

Acıtıp yürekleri çekip gitmek, 

Değilki sevmek.

Dostum yoğrulduğumuz umut hamurundan, 

İnsanlığın ekmeğini yapmanın zamanıdır.

Karışıp sokakların akışına, 

Umudun ekmeğini dağıtmanın zamanıdır.

An eskiyeni kılıçtan geçirip, 

Şimdiyi yaratmanın zamanıdır.

Haydi kuşan umudunu, 

Umudu köhnelerden kurtarmanın zamanıdır.', 'Yaşanması gereken bir hayat,  Ellerimizde dostum. Biz bütünün parçalarıyız,  Dost olmalıyız. Yalnızlığın çeperlerine,  Takılmak değil senin ...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/dost-olmaliyiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Drama Köprüsü', 'drama-koprusu-ruhi-su-43cea', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Drama köprüsü Hasan, dardır geçilmez,

Soğuktur suları da Hasan, bir tas içilmez

Anadan geçilir Hasan, yardan geçilmez

At martini de bre Hasan, dağlar inlesin

Drama mahpusunda Hasan, dostlar dinlesin

Mezar taşlarını Hasan, koyun mu sandın

Adam öldürmeyi de Hasan, oyun mu sandın

Drama mapusunu Hasan, evin mi sandın

At martini de bre Hasan, dağlar inlesin

Drama mahpusunda Hasan, dostlar dinlesin', 'Drama köprüsü Hasan, dardır geçilmez, Soğuktur suları da Hasan, bir tas içilmez Anadan geçilir Hasan, yardan geçilmez At martini de bre Hasa...', ARRAY['Türk Edebiyatı','Şiir','Ruhi Su']::text[], 8.5, '{"poet":"Ruhi Su","poet_slug":"ruhi-su","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/drama-koprusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Radyo', 'radyo-ali-niku-zisow', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'arkası yarınlar, 

ne güzeldiler...

eğri büğrü yatılırdı bir köşeye

pür dikkat..

kulaklarda idi yaşam

gözler yavuklunun gözünde

elleri ellerimdeydi çoğu zaman

kulaktaki efekt sesi, 

yaşamın aşkını yaşatırdı

konu yarına aksetse de

umutlar kalırdı zihinde

ertesi güne kadardı, 

aşka vakit henüz vardı, 

yaşamak isteyen için...', 'arkası yarınlar,  ne güzeldiler... eğri büğrü yatılırdı bir köşeye pür dikkat.. kulaklarda idi yaşam gözler yavuklunun gözünde elleri elleri...', ARRAY['Türk Edebiyatı','Şiir','Ali Niku']::text[], 8.5, '{"poet":"Ali Niku","poet_slug":"ali-niku","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/radyo-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Üstüne;', 'ayrilik-ustune-dafne-avril-livorced-ay-bviv2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tam göğsünüzün ortasında bir yeriniz acıyacak...

Evinizin sizi içine sığdıramayacak kadar dar olduğunu farkedeceksiniz...

Sokağa fırlayaksınız...Sokaklar da dar gelecek...

Tıpkı vücudunuzun yüreğinize dar geldiği gibi...

Ne denizin mavisi açacak içinizi, ne de pırıl pırıl gökyüzü...

Kendinizi taşıyamayacak kadar çok büyüyecek, bir yandana da kaybolacak kadar küçüleceksiniz...

Birileri size bir şeyler anlatacak durmadan...

''Önemli olan sağlık.''

''Yaşamak güzel.''

''Boşver, her şey unutulur...''

Siz hiçbirini duymayacaksınız...

Gözyaşlarınızdan etrafı göremez hale geleceksiniz...

Ondan ölmesini isteyecek kadar çok nefret edecek, az sonra kollarında ölmek isteyecek kadar çok seveceksiniz...

Hep ondan bahsetmek isteyeceksiniz...

''Ölüme çare bulundu.'' ya da ''Yarın kıyamet kopacakmış.'' deseler, başınızı kaldırıp ''Ne dedin? '' diye sormayacaksınız...

Yalnız kalmak isteyeceksiniz...

Hem de kalabalıkların ortasında kaybolmak... İkisi de yetmeyecek...

Geçmişi düşüneceksiniz... Neredeyse dakika dakika, ama kötüleri atlayarak! 

Onunla geçtiğiniz yerlerden geçmek isteyeceksiniz, gittiğiniz yerlere gitmek...

Bu size iyi gelmeyecek... Ama bile bile yapacaksınız...

Biri size içinizdeki acıyı söküp atabileceğini söylese, kaçacaksınız...

Aslında kurtulmak istediğiniz halde, o acıyı yaşamak için direneceksiniz...

Hayatınızın geri kalanını onu düşünerek geçirmek isteyeceksiniz...

Aksini iddia edenlerden nefret edeceksiniz...

Herkesi ona benzetip, kimseyi onun yerine koyamayacaksınız...

Hiçbir şey oyalayamayacak sizi, ilaçlara sığınacaksınız...

Birkaç saat kafanızı bulandıran ama asla unutturmayan...

Sadece bir müddet buzlu camın arkasından seyrettiren...

Bütün şarkılar sizin için yazılmış gibi gelecek...

Boğazınız düğümlenecek, dinleyemeyeceksiniz...

Ne geceler rahatlatacak sizi ne gündüzler...

Ölmeyi isteyip, ölemeyeceksiniz...

Belki çivi çiviyi söker diye can havliyle önünüze çıkana sarılmak isteyeceksiniz, nafile...

Düşüncesi bile tahammül edilmez gelecek...

Rüyalar göreceksiniz, gerçek olmasını istediğiniz...

Her sıçrayarak uyandığınızda onun adını söylediğinizi farkedeceksiniz...

Telefonun çalmasını bekleyeceksiniz...

Aramayacağını bile bile...

Her çaldığında yüreğiniz ağzınıza gelecek...

Ağlamaklı konuşacaksınız arayanlarla...

Yüreğiniz burkulacak...

Canınız yanacak...

Bir daha sevmemeye yemin edeceksiniz...

Hayat dair hiçbir şey yapmak gelmeyecek içinizden...

Onun sesini bir kes daha duymak için yanıp tutuşacaksınız...

Defalarca aradığı günlerin kıymetini bilmediğiniz için belki de kendinizden nefret edeceksiniz...

Yaşadığınız şehri terketmek isteyeceksiniz...

Onunla hiçbir anınızın olmadığı bir yerlere gidip yerleşmek...

Ama bir umut... Onunla bir gün karşılaşma umudu...

Bu umut sizi gitmekten alıkoyacak...

Gelgitler içinde yaşayacaksınız... 

Buna yaşamak denirse...', 'Tam göğsünüzün ortasında bir yeriniz acıyacak... Evinizin sizi içine sığdıramayacak kadar dar olduğunu farkedeceksiniz... Sokağa fırlayaksın...', ARRAY['Türk Edebiyatı','Şiir','Dafne Avril Livorced Ay']::text[], 8.5, '{"poet":"Dafne Avril Livorced Ay","poet_slug":"dafne-avril-livorced-ay","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/ayrilik-ustune-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Aşkım', 'son-askim-ecem-uranbey-7eu6d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'şimdi geceleri beklemiyorum

sen varsın, 

bir ara yıldızlara bakıyorum sadece

biliyorum çünkü ordasın

zor bulunan en güzel sevgili', 'şimdi geceleri beklemiyorum sen varsın,  bir ara yıldızlara bakıyorum sadece biliyorum çünkü ordasın zor bulunan en güzel sevgili...', ARRAY['Türk Edebiyatı','Şiir','Ecem Uranbey']::text[], 8.5, '{"poet":"Ecem Uranbey","poet_slug":"ecem-uranbey","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/son-askim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlkler', 'i-lkler-ecem-uranbey-qvqpj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İlklerde bir gün sona erermiş 

tıpkı bizim gibi

soğuk ve sakin

ıslak, 

seni unutmak mı, saçma

senin gözlerin, o yeşil gözler

hep kalbimde, aklımda, tüm bedenimde

sen kimmisin

yok olan ama unutulmayan...', 'İlklerde bir gün sona erermiş  tıpkı bizim gibi soğuk ve sakin ıslak,  seni unutmak mı, saçma senin gözlerin, o yeşil gözler hep kalbimde, a...', ARRAY['Türk Edebiyatı','Şiir','Ecem Uranbey']::text[], 8.5, '{"poet":"Ecem Uranbey","poet_slug":"ecem-uranbey","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ilkler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çukurovada Yaz', 'cukurovada-yaz-mehmet-akif-sahin-p22cf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çukurovada Yaz

Şimdi Çukurovada

Güneş adamı pek tutar

Yarılıp kavrulmuş tarlada

Gün uzar ha uzar

İnsan kurur

Çöreklenir tükrük boğaza

Yağmurlar serap olur

Sıcak yakar ha yakar

Dudaklar sabretmez

Kaç yerinden çatlar

Bir yel bile esmez

Çukurova yanar ha yanar', 'Çukurovada Yaz Şimdi Çukurovada Güneş adamı pek tutar Yarılıp kavrulmuş tarlada Gün uzar ha uzar İnsan kurur Çöreklenir tükrük boğaza Yağmur...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Şahin']::text[], 8.5, '{"poet":"Mehmet Akif Şahin","poet_slug":"mehmet-akif-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cukurovada-yaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dut Ağacı', 'dut-agaci-zeren-cangert-qrewi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hani bir dut ağacı vardı ya evin bahçesinde

Fatma teyzenin, çocukluk aklımızla

hikayelerini dinlediğimiz.

Dallarına salıncaklar kurduğumuz, 

Gölgesinde şarkılar söylediğimiz

Hatırlıyor musun Hasan amcanın minik ipek böceklerine

Yaprak toplarken o ağaçtan düşmüştüm

Başım kan revan içindeyken bile gülüyordun halime.

Yıllar geçti aradan hala izi başımda saçımı tararken

Tarağın ucu takıldıkça o ize, hep gülerim o eski halimize.

İşte o çevresinde oynadığımız. 

Güneşin ışığını yaprakları ile süzen ağacı kestiler. 

Yazık ettiler.

Hatıralarımız o ağaçla beraberdi.

Sanki kalbimden bir şeyler söküldü.

Boşuna mı geçirdik o güzelim yılları, 

Ne vardı yok edecek beton yığını için

Unutulmaz anıları.', 'Hani bir dut ağacı vardı ya evin bahçesinde Fatma teyzenin, çocukluk aklımızla hikayelerini dinlediğimiz. Dallarına salıncaklar kurduğumuz, ...', ARRAY['Türk Edebiyatı','Şiir','Zeren Cangert']::text[], 8.5, '{"poet":"Zeren Cangert","poet_slug":"zeren-cangert","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dut-agaci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba Yalancı Dünya', 'merhaba-yalanci-dunya-mehmet-akif-sahin-j4d0k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bitmeyen gecenin ortasında

Anam çığlık çığlığa

At üstünde doğmuşum

Toros Dağlarında

Ateş böceği şavkında

Göbeğimi kesmiş taşla

Aç kurt gibi saldırmışım

Anamın bağrına

Bulamamış fistanından başka

Belek olacak urba

Baykuş sesiyle dalmışım

İlk uykuma

Yamaçtaki çorak tarlada

Mehmet demiş adıma

Böyle merhaba demişim 

Yalancı dünyaya', 'Bitmeyen gecenin ortasında Anam çığlık çığlığa At üstünde doğmuşum Toros Dağlarında Ateş böceği şavkında Göbeğimi kesmiş taşla Aç kurt gibi ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Şahin']::text[], 8.5, '{"poet":"Mehmet Akif Şahin","poet_slug":"mehmet-akif-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/merhaba-yalanci-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözüm Açık', 'gozum-acik-sadi-salim-y02k0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Cümlelerim kanıyor herbiri noktasız

Kelimelerim ruhsuz faili meçhul herbirinin

Ciğerim yanıyor öznesi yok hiçbirinin

Faili belli bir cinayet benimkisi

Hiçbir tanığı olmadı cesedimin

Şahitleri sustu ecelimin

Gözüm açık 

Onu bile örtmedin.', 'Cümlelerim kanıyor herbiri noktasız Kelimelerim ruhsuz faili meçhul herbirinin Ciğerim yanıyor öznesi yok hiçbirinin Faili belli bir cinayet...', ARRAY['Türk Edebiyatı','Şiir','Sadi Salim']::text[], 8.5, '{"poet":"Sadi Salim","poet_slug":"sadi-salim","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gozum-acik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soytari', 'soytari-ahmet-i-plikci-a05jh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Elit komisyoncuyum ben, 

Disim hos, icim bos, 

Etliye sutluye dokunmam

Korkarim kaybetmekten 

Ne oldugunu bilmeden. 

Kralin, diktatorun, kuresel kraliyetcinin, 

Yahudinin, Bushun degil, 

Nefsimin soytarisiyim ben.

Bile bile duzene ayak uydururum

Basimi sallar, keyfime bakarim.', 'Elit komisyoncuyum ben,  Disim hos, icim bos,  Etliye sutluye dokunmam Korkarim kaybetmekten  Ne oldugunu bilmeden.  Kralin, diktatorun, kur...', ARRAY['Türk Edebiyatı','Şiir','Ahmet İplikci']::text[], 8.5, '{"poet":"Ahmet İplikci","poet_slug":"ahmet-i-plikci","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/soytari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtına ve Rüzgar', 'firtina-ve-ruzgar-seyfettin-bilal-ozluk-b0jat', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rüzgar birazdan son hızıyla başlayacak yaprakları koparmaya

Ne fırtına denir buna ne de başka bir şey

Olsa olsa çaresizliğin son demleri...

Kopar benliğimden o arta kalan kırıntıları

İstemem ben tek başıma ağaç da kalmayı götür beni de

Giderken kalmasın ne bir yaprak ne de bir kuru dal...

Acımasın kimse beni neydi ne oldu diye

Ben kendimi bilirim bir de yaptıklarımı

Başladıysam hazan mevsimine bir kendim kalmalıyım...

Düşsün bırak o son yaprakta dalından

Sen gel yeter ki çarem

Unutmadım unutamadım hep içimdesin ve içimdeydin...

Dedim ya bu ne bir fırtına ne de rüzgar

Sadece senin yokluğunun bir adıydı bu yalnızlık

Hadi gel isim koy benliğime...

Lütfen bu son olsun koparma artık dalımdan

Bir ben kalayım bu ağaçta bir de sen

Sonsuza dek direnelim rüzgara ve fırtınaya inat...

Var mısın yeniden başlamaya

Hazır mısın benliğimizde afetler  yaratmaya...

Biliyorum be küçüğüm hep sevdin

Tek başına ve acılarla

Hadi uyan bak ben yanındayım ve ne diyorum dinle; 

             SENİ SEVİYORUM...', 'Rüzgar birazdan son hızıyla başlayacak yaprakları koparmaya Ne fırtına denir buna ne de başka bir şey Olsa olsa çaresizliğin son demleri... ...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/firtina-ve-ruzgar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağlay''ya', 'caglay-ya-erdem-ozsoysal-1ux5t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'dün gene kırılan kalbimi onarmaya çalıştım.

kırık penceremden girerken havanın ayazı.

sen kokulu bir battaniye''ye sarıldım

 koskoca oflar çekiyordum, bitişik zamanlara inat.

gözlerim hep kapı zillerindeydi

 yada çalacak bir telefonda.

sonradan anladım çoktan beri terk edilmişliğimi 

ve yoklukların ortasında koca bir yokluk olduğumu umutsuz.', 'dün gene kırılan kalbimi onarmaya çalıştım. kırık penceremden girerken havanın ayazı. sen kokulu bir battaniye''ye sarıldım  koskoca oflar çe...', ARRAY['Türk Edebiyatı','Şiir','Erdem Özsoysal']::text[], 8.5, '{"poet":"Erdem Özsoysal","poet_slug":"erdem-ozsoysal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/caglay-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Eylül Akşamı', 'bir-eylul-aksami-umut-gul-nf0gm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir eylül akşamında

Rüzgar fısıldarken yapraklara

Sen fırtınalar koydun yüreğime

Bir eylül akşamında

Ay ışığı dolarken odama

Sen yüreğini koydun avcuma

Bir eylül akşamında

Yağmur vururken pencereme

Sen ateşler koydun yüreğime

Bir eylül akşamında

Yıldızlara kayarken tuttuğum dileği

Sen koydun başucuma', 'Bir eylül akşamında Rüzgar fısıldarken yapraklara Sen fırtınalar koydun yüreğime Bir eylül akşamında Ay ışığı dolarken odama Sen yüreğini ko...', ARRAY['Türk Edebiyatı','Şiir','Umut Gül']::text[], 8.5, '{"poet":"Umut Gül","poet_slug":"umut-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-eylul-aksami-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balıkçıyla Pazarlık', 'balikciyla-pazarlik-reha-basogul-ch685', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'vuslata yaka silktim kaptan

acele kalk yetiş yanıma

gidelim buralardan

daraldım diyorum

anlasana

haydi bitir şu tekneni beni bunaltmadan

oyalanma çivi çakmayla falan

fazla da kıçını zımparalamadan

yakalım diyorum kısmetse

senle denizci fenerlerimizi

açalım istiyorum şöyle

denize pupa yelkenlerimizi

bütün dubaları aşıp

sen de en uzaklara kırarsan dümeni

inan olsun

yeter bana...

Vuslata yaka silktim kaptan

acele kalk yetiş yanıma

gidelim buralardan

daraldım diyorum

anlasana

rica minnet olmadan

götür istiyorum beni çok uzaklara

inanmıyorsun ama

hemen görmem gerek 

yüreğimdeki balık sürülerini

ah yok mu o bıcırık deniz bigudileri 

mübarekler gözümde tüttü şimdi

azmışım da

bunlar da kadınım olmuş sanki

anlamıyorsun ama

nasıl da özledim bi bilsen canım denizimi

bir kere olsun 

sürsem yüzümü onun hoyrat lodosuna

off var ya 

başım üstüne yeminle

yeter bana! 

vuslata yaka silktim kaptan

acele kalk yetiş yanıma

gidelim buralardan

daraldım diyorum

anlasana

sen rasgele demeyi ağzıma bir alıştırsan

ben kızdırsam  güzelim dalgalarımızı 

karanlığın Ay yüzüne kadar bağırsam 

heryanım velet donu kadar ıslansa

gelse içime zaten bir kere bunaltı

bak şuraya yazıyorum

yeter bana! 

vuslata yaka silktim kaptan

acele kalk yetiş yanıma

gidelim buralardan

daraldım diyorum

anlasana

çilingir soframıza ne koyarsan

öyle hiç mızmızlanmadan öte boka

derim çok şükür amenna! 

söz veriyorum 

istesen de 

duyamazsın artık benden

başka bir terane

ağzımdan çıktı bir kere 

demedik mi ne çıkarsa bahtımıza

zaten ne diyorum ben sana

sarı çizmelerimi taksam ayağıma

yağmurluğumu da geçirdim mi üstüme

adımımı atsam güvertenin başına

elimi de kanattım mı bir kere misinayla

versen de istemem daha

palamutunmuş lüferinmiş

sanma sakın gözüm var onlarda

öylece teknenin köşesinde oturayım

daha ne olsun ki

ciğerimi ye

yeter bana! 

vuslata yaka silktim kaptan

acele kalk yetiş yanıma

gidelim buralardan

daraldım diyorum

anlasana

bakma bana öyle uzaktan 

hiç deli görmemiş gibi

sen de söz vereceksin 

çoluk çoluk ayaklarına yatmadan

ne bırakacaksın beni buzhaneye

ne sen de kaçacaksın tersaneye

geçen seferki gibi kandırmazsan

itmezsen beni elinin tersiyle

ölümü gör

yeter bana! 

vuslata yaka silktim kaptan

acele kalk yetiş yanıma

gidelim buralardan

daraldım diyorum

anlasana

adamı günaha sokmadan

beni daha fazla daraltmazsan 

kimseyle kanlı bıçaklı olmadan

lafımı bir anlarsan

sen de yeter ulan diyip

verdiğin sözü bi tutarsan

birkereliğine dönmeyiz diyorum işte 

ruhuma ağını atmış

şu mendireği kayıp namussuz bedene', 'vuslata yaka silktim kaptan acele kalk yetiş yanıma gidelim buralardan daraldım diyorum anlasana haydi bitir şu tekneni beni bunaltmadan oya...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":104,"source_url":"https://www.antoloji.com/balikciyla-pazarlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leyla', 'leyla-yusuf-kaya-asunq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Leyleklerin göç zamanında rastladım sana 

En güzel günlerimdi o günlerim benim

Yaralarımın sarıldığı, kalbimin  bir başka heyecanla attığı günler

Lalezarların bizim mekanımız olduğu günler

Aşk dolu günlerdi o günler beni mesut ettiğin için sana teşekkür ediyorum.', 'Leyleklerin göç zamanında rastladım sana  En güzel günlerimdi o günlerim benim Yaralarımın sarıldığı, kalbimin  bir başka heyecanla attığı g...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Kaya']::text[], 8.5, '{"poet":"Yusuf Kaya","poet_slug":"yusuf-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/leyla-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlamayacağım...', 'aglamayacagim-hayat-uyar-eql82', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'AĞLAMAYACAĞIM

Biten sevginin ardından, 

Ben ağlamayacağım

Giden sevginin ardından

Ben bakmayacağım

Doğan güneşin önünde

Ben parlayacağım

Yağan yağmurun altında

Ben ıslanmayacağım

07.10.1998', 'AĞLAMAYACAĞIM Biten sevginin ardından,  Ben ağlamayacağım Giden sevginin ardından Ben bakmayacağım Doğan güneşin önünde Ben parlayacağım Yağ...', ARRAY['Türk Edebiyatı','Şiir','Hayat Uyar']::text[], 8.5, '{"poet":"Hayat Uyar","poet_slug":"hayat-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/aglamayacagim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlıyordum', 'agliyordum-hayat-uyar-xhbee', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yağmur yağarken

Şimşekler çakıyordu

Islanınca gözlerim

Hafiften ağlıyordum

Ayaz dışarda eserken

Elim cebimde geziyordum

Ben seni özlerken

Hafiften ağlıyordum', 'Yağmur yağarken Şimşekler çakıyordu Islanınca gözlerim Hafiften ağlıyordum Ayaz dışarda eserken Elim cebimde geziyordum Ben seni özlerken Ha...', ARRAY['Türk Edebiyatı','Şiir','Hayat Uyar']::text[], 8.5, '{"poet":"Hayat Uyar","poet_slug":"hayat-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/agliyordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahududum', 'ahududum-hayat-uyar-pd9dd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine gözlerim İstanbul ufuklarında birtanem, 

Dizimin üstünde defter elimde kalem

Durmadan yazıyorum aşkımı ve seni

Ne olur gecikme, bekletme beni

Saat gecenin ikisi birtanem ahududum, 

Sağımda solumda seni arıyorum

Uzatıyorum elimi, elini tutamıyorum

Yine sarhoşum, Biramı yudumluyorum

Bekleyeceğim mutlaka yine bana geleceksin, 

Fakat çok geç kalıp acı gerçeği öğreneceksin.

Sensizliğe tahammül edemeyen kelebeğini, 

Kara toprakla sonsuz uykuda bulacaksın

16.05.1979', 'Yine gözlerim İstanbul ufuklarında birtanem,  Dizimin üstünde defter elimde kalem Durmadan yazıyorum aşkımı ve seni Ne olur gecikme, bekletm...', ARRAY['Türk Edebiyatı','Şiir','Hayat Uyar']::text[], 8.5, '{"poet":"Hayat Uyar","poet_slug":"hayat-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ahududum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ama neye?', 'ama-neye-hayat-uyar-8jjd7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevdalıyım ben bir şeye 

Ama neye? 

Özlüyorum buram buram

Ama kimi? 

Söylüyorum yanık türkü

Ama kime? 

Ağlıyorum durmadan

Ama neden? 

Düşünüyorum yorulmadan

Ama niçin? 

Fala bakıyorum durmadan

Ama nasıl? 

Severek ölesiye tapıyorum

Ama kime? 

Her gecem binbir sitem

Ama neye?', 'Sevdalıyım ben bir şeye  Ama neye?  Özlüyorum buram buram Ama kimi?  Söylüyorum yanık türkü Ama kime?  Ağlıyorum durmadan Ama neden?  Düşünü...', ARRAY['Türk Edebiyatı','Şiir','Hayat Uyar']::text[], 8.5, '{"poet":"Hayat Uyar","poet_slug":"hayat-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ama-neye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem Beni severdi...', 'annem-beni-severdi-hayat-uyar-9qjyk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Annem beni severdi.

                           

Annem beni severdi

Minik kuşum, güvercinim derdi

Ekmeğin dışını kendi                          

İçini bana yedirirdi

Annem beni severdi

Karagözlüm, ceylanım derdi

Şilteyi kendi üstüne

Yorganı bana örterdi

Annem beni severdi.

Şehit yadigârı Mehmet''im derdi

Çorbayı kendi içer

Yemeği bana yedirirdi.

  11.07.1998', 'Annem beni severdi.                             Annem beni severdi Minik kuşum, güvercinim derdi Ekmeğin dışını kendi                       ...', ARRAY['Türk Edebiyatı','Şiir','Hayat Uyar']::text[], 8.5, '{"poet":"Hayat Uyar","poet_slug":"hayat-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/annem-beni-severdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmak', 'unutmak-ender-guncelik-644zu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilir misin? 

Bu sana yazdığım otuzuncu şiirim.

Otuz şiirin hepsinde aşkım vardı

Sana yalvarışlarım, tarif edilmez aşkım.

Şimdi başka bir şiir yazıyorum

Adı unutmak.... Unutanları unutmak...

Bu şiirde konu sen değilsin, konunun kendisi benim

Nasıl başlayacağım söze, nasıl anlatacağım? 

Ya da uzatmadan söyleyeyim 

Bugün seni unutacağım.

Zor olacak tabi ki, 

Hatta belki bu şiirle birlikte ağlayacağım

Tek taraftı benim aşkım, bazılarının tabiriyle en güzeliydi aşkın

Karşılık beklemeden sevmek, sevilmeden her şeye evet diyebilmek

Ama doğrusunu söylemek gerekirse, karşılık bekledim ben senden

Gözlerinde, sözlerinde, sende beni bulmayı aradım.

Oysa ben senin için kan emici bir sülük gibiydim

İstenmeyen, fakat yapıştığında çok zor giden bir haşere gibi tıpkı.

Ama benim tek farkım zararsız olmaktı

Tabi rahatsız oluşlarını katmazsak içine, 

Her neyse, ben anladım artık hayatın ne demek olduğunu

Ölümdü bazen görünen  tek kurtuluş yolu

Ya da senin geri dönmendi bana.

Ama ne işe yarardı dönüşün

Kalbinde başkasına yer varken, bana gelmen ne yazardı.

Bir şey diliyorum senden

Belki on dakikalık bir iş bu

Düşün şimdi geçmişi...

Çok geriye gitmene gerek yok, 

Yaklaşık altı ay öncesi

Hani senin için değişik bir erkek vardı

Tüm erkeklerden farklıydı

O sadıktı, güvenilirdi

Bu sözleri sen söylerken, hep kendi üzerime alındım

Nedendir bilmiyorum, belki yanıldım

Belki bu sözler benim için değildi.

Ama olur ya o zaman sevmiştin beni

Belki inkar edersin ama, sende sevmiştin.

Yoksa göz yaşların niye aksınki? 

İşte o değişik dediğin insan bensem eğer

Gerçekten ben sana değişik davranmaya çalıştım

Severken hep söyledim sana 

Seviyorum dedim, hem de çok seni

Bir gün unutamadığım, sevdiğimi sandığım biri

Duygularımı geri çaldı

Ve o gün cesaretle çıkıp karşına, söyledim sana

Ben onu unutmadım dedim, eminim hatırlarsın

Bir tatilin başlangıcıydı bu, iki ay boyunca ayrı kalacaktık

Seviyorum diye geçiştirebilirdim seni

Tıpkı şu an sana erkeğinin yaptığı gibi

Ne dedim, ben sana farklı olmaya çalıştım

Gerçekçiydim hep, sana karşı oynadığım ufak bir oyun bile olmadı

Ama duygularım beni yanıltmıştı, benim asıl sevdiğim sendin

Zaten hemen geri geldim, ama sen çoktan oltanı başka yere atmıştın

Şimdi geçmişi dönüp kurcalamak anlamsız

Ama içim rahat, sana hep doğruları söyledim

Ben ne isem o oldum karşında

Seni kaybetmek pahasına bile olsa

Bir gerçeği daha söyleyeyim

Şu an çok seviyorum seni

Ama en büyük aşklar bile, bilirsin ki unutulur

Ben de unutmak için bu günü seçtim

Unutmaya başlamak için. 

Gözlerim nöbet tutmaz mı? Gözlerinde

Kalbim sende olmaz mı? Bundan böyle.

Elbet gözlerim ve kalbim sende olacaktır belli bir süre

Yavaş yavaş bitmeli, dev gibi sevgim bile.

Bu sevginin bitirdiği bazı aşklar vardı eski günlerde 

Onlar kalbin en dibinde saklıydı

Önlerinde çelik bir kapı asla kırılamayan, çıkışı olmayan

Senin yerin ise bu küçük kısımdan kalan yerdi kalpte

Yerin ayrıydı, sen ne dersen de.

Oysa sen beğenmedin asla yerini

Dedim ya unutuyorum, şimdi senide kilitliyorum çıkışı olmayan bölüme

Bu haberim sevindirecektir seni

Niye sevindirmesin ki? 

Yüz kişi koşmuyor muydu? Arkandan

İşte kaldı doksan dokuz kişi.

Al hayat senin, özgürsün artık

Ne de olsa benden kurtuldun

Tıpkı hapishaneden çıkmış mahkumlar gibi sevinmelisin şimdi

Büyük bir aşkı bitirdim diye

Savaşı kazanmış askerler gibi sevinmelisin.

Gülmelisin, oynamalısın

Bilmelisin artık, kimse yanlış anlamaz bizi.

Ama unutma ki! ! ! 

O sülük gibi derine yapışan ben

Küçük bir yara açmışımdır teninde

Artık ayrılmış olsam da 

O yarayı hemen kapatamazsın 

Belki hiç acı vermez o yara sana

Ama bir iz kalır orada

Bir gün kabuk tutar ve düşer

İşte o zaman sende tamamı ile

Unutmuş olursun beni

Sakın inkar etmeye kalkışma

Hiçbir şey hissetmemiş olamazsın aşkım karşısında

Dedim ya bu yazmış olduğum otuzuncu ve son şiirim sana.

Belki hayatta sevemem senden çok kimseyi ama

Sende gizli kalacaksın bundan böyle kalbimin bir köşesinde...', 'Bilir misin?  Bu sana yazdığım otuzuncu şiirim. Otuz şiirin hepsinde aşkım vardı Sana yalvarışlarım, tarif edilmez aşkım. Şimdi başka bir şi...', ARRAY['Türk Edebiyatı','Şiir','Ender Günçelik']::text[], 8.5, '{"poet":"Ender Günçelik","poet_slug":"ender-guncelik","theme":"Türk Şiiri","is_hero":false,"total_lines":100,"source_url":"https://www.antoloji.com/unutmak-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkların gazabı', 'asklarin-gazabi-hayat-uyar-uokji', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün seni terk edersem

Gülen gözlerim ağlasın

Bir gün seni kaybedersem

Nazlı güller solsun

Tanrının kızgın güneşi

Şu yanık bağrıma doğsun

Sana kötü yazarsam

Narin parmaklarım kırılsın

Seni pişman edersem

“Aşkların gazabı” beni bulsun.', 'Bir gün seni terk edersem Gülen gözlerim ağlasın Bir gün seni kaybedersem Nazlı güller solsun Tanrının kızgın güneşi Şu yanık bağrıma doğsun...', ARRAY['Türk Edebiyatı','Şiir','Hayat Uyar']::text[], 8.5, '{"poet":"Hayat Uyar","poet_slug":"hayat-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/asklarin-gazabi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram akşamı', 'bayram-aksami-hayat-uyar-bibey', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gurbette bir bayram akşamı

Ezanlar okunuyor yanık mı yanık

Koca caddede bir ben yalnız

Işıklar parlamıyor sönükmü sönük

Eski bayramlar eski neşeler

Yok olmuş zamanın akışında

Yeni bayramlar yeni neşeler

Yok olmuş bendeki sevinçler', 'Gurbette bir bayram akşamı Ezanlar okunuyor yanık mı yanık Koca caddede bir ben yalnız Işıklar parlamıyor sönükmü sönük Eski bayramlar eski ...', ARRAY['Türk Edebiyatı','Şiir','Hayat Uyar']::text[], 8.5, '{"poet":"Hayat Uyar","poet_slug":"hayat-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bayram-aksami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle bir gün...', 'bekle-bir-gun-hayat-uyar-pua82', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bekle bir gün, 

Ümitlerin bittiği zaman

Gözyaşın kuruduğu zaman

Saçların ağardığı zaman

Ben sana geleceğim.

Bekle bir gün, 

Anılarla avunduğun zaman

Gözlerinin feri bittiği zaman

Hıçkırıktan tıkandığın zaman

Ben sana geleceğim

Bekle bir gün, 

Elimde bir tahta asa, 

Sırtımda bir yırtık hırka

Karışmış saçım sakala

Ben sana geleceğim', 'Bekle bir gün,  Ümitlerin bittiği zaman Gözyaşın kuruduğu zaman Saçların ağardığı zaman Ben sana geleceğim. Bekle bir gün,  Anılarla avunduğ...', ARRAY['Türk Edebiyatı','Şiir','Hayat Uyar']::text[], 8.5, '{"poet":"Hayat Uyar","poet_slug":"hayat-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bekle-bir-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben seni ararım', 'ben-seni-ararim-hayat-uyar-u9643', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir hüzün çöktü doldu gözlerim

Dizlerimin üstünde kenetlendi ellerim

Yana yana seni anar, ağlarım

Anılar buruk, ben seni ararım

Ağlayan gözlerimin yaşını silmeye gel

Deliler gibiyim ruhumu sevmeye gel

Dertlerim kadehlerde, içmeye sen gel

Öldüm sevdandan, gömmeye sen gel', 'Bir hüzün çöktü doldu gözlerim Dizlerimin üstünde kenetlendi ellerim Yana yana seni anar, ağlarım Anılar buruk, ben seni ararım Ağlayan gözl...', ARRAY['Türk Edebiyatı','Şiir','Hayat Uyar']::text[], 8.5, '{"poet":"Hayat Uyar","poet_slug":"hayat-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ben-seni-ararim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben seni bekliyorum', 'ben-seni-bekliyorum-hayat-uyar-nxpkq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Etrafımı sonbahar sardı, 

Tüm yapraklar sarardı, 

Gündüzüm bile karardı

Ben seni bekliyorum

Gönlümün neşesi, aşkımın ateşi

Kanımın baharı kalbimin nefesi

Bitti kadehler, kırıldı şişesi

Ben seni bekliyorum

Yüreğime karlar yağacak

Kanım çekiliyor donacak

Son nefesimde ancak

Ben seni bekliyorum', 'Etrafımı sonbahar sardı,  Tüm yapraklar sarardı,  Gündüzüm bile karardı Ben seni bekliyorum Gönlümün neşesi, aşkımın ateşi Kanımın baharı ka...', ARRAY['Türk Edebiyatı','Şiir','Hayat Uyar']::text[], 8.5, '{"poet":"Hayat Uyar","poet_slug":"hayat-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-seni-bekliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir gözüm bir de içim...', 'bir-gozum-bir-de-icim-hayat-uyar-mjj8t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir geceki karanlığın karası

Bir ayaz ki dışarının havası

Birde cebimde olsa ekmek parası

Bir gözüm bir de içim ağlar

Bir gece ki yıldızı ayı yok

Bir fırtına ki yağmuru yok

Bir sokaktayım hiç sonu yok

Bir gözüm bir de içim ağlar

Bir Feryat ki sesim duyulmaz

Bir dert ki bu çare bulunmaz

Biçareyim ben halim sorulmaz

Bir gözüm bir de içim ağlar', 'Bir geceki karanlığın karası Bir ayaz ki dışarının havası Birde cebimde olsa ekmek parası Bir gözüm bir de içim ağlar Bir gece ki yıldızı ay...', ARRAY['Türk Edebiyatı','Şiir','Hayat Uyar']::text[], 8.5, '{"poet":"Hayat Uyar","poet_slug":"hayat-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-gozum-bir-de-icim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir mektup', 'bir-mektup-hayat-uyar-s9ua5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir mektup yazdım sana

Okudukça ağlayacaksın

Bir mektup yazdım sana

Okudukça haykıracaksın

Gözlerin bakacak uzaklara

Hıçkırığın düğümlenecek boğazında

Yutkunamayacaksın gözlerin dolacak

Ağlayacaksın okudukça

Dallardaki çiçekleri koparacaksın

Göklerden yıldız koparacaksın

Çöllerde Mecnun arayacaksın

Okudukça ağlayacaksın...', 'Bir mektup yazdım sana Okudukça ağlayacaksın Bir mektup yazdım sana Okudukça haykıracaksın Gözlerin bakacak uzaklara Hıçkırığın düğümlenecek...', ARRAY['Türk Edebiyatı','Şiir','Hayat Uyar']::text[], 8.5, '{"poet":"Hayat Uyar","poet_slug":"hayat-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-mektup-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir seni sevdim', 'bir-seni-sevdim-hayat-uyar-l8bt8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir seni sevdim bir de defterimi

Bir kirpiklerini sevdim bir de kalemimi

Sen olmasanda olur, defterim var ya! 

Kirpiklerin kırpmasa da olur, kalemim var ya! 

Anılarımı yazıyorum bu yapraklara

Kahrediyorum inan ayrılıklara

Belki dönüp, tekrar seversin diye

Hep defterimi açık bırakıyorum', 'Bir seni sevdim bir de defterimi Bir kirpiklerini sevdim bir de kalemimi Sen olmasanda olur, defterim var ya!  Kirpiklerin kırpmasa da olur,...', ARRAY['Türk Edebiyatı','Şiir','Hayat Uyar']::text[], 8.5, '{"poet":"Hayat Uyar","poet_slug":"hayat-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-seni-sevdim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir gün...', 'bir-gun-hayat-uyar-rrkmf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gün: 

Uzaklara bakarsa gözlerin

Açılırsa gökyüzüne ellerin

Haber sal bana turnalardan

Haber sal bana bulutlardan

Göz yaşını sal yağmurlardan, 

Kokunu sal bana rüzgarlardan

Bir gün, 

Duyarsa kara haberimi kulakların

Cennete salar beni duaların

Ne selam gelir turnalardan

Ne haber gelir bulutlardan

Ne gözyaşı gelir yağmurlardan

Ne kokun gelir rüzgârdan', 'Bir gün:  Uzaklara bakarsa gözlerin Açılırsa gökyüzüne ellerin Haber sal bana turnalardan Haber sal bana bulutlardan Göz yaşını sal yağmurla...', ARRAY['Türk Edebiyatı','Şiir','Hayat Uyar']::text[], 8.5, '{"poet":"Hayat Uyar","poet_slug":"hayat-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-gun-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bittiği yerde', 'bittigi-yerde-hayat-uyar-3wkjb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Umutların bittiği yerde

Acılar başlarmış

Sevginin bittiği yerde

Nefret başlarmış

Umut yok, sevgi yok

Yaşa nasıl yaşarsan

Aşk yok özlem yok

Yaşa nasıl yaşarsan

Hüznün geldiği yerde

Yürekler daralırmış

Sevginin bittiği yerde 

Nefret başlarmış...', 'Umutların bittiği yerde Acılar başlarmış Sevginin bittiği yerde Nefret başlarmış Umut yok, sevgi yok Yaşa nasıl yaşarsan Aşk yok özlem yok Y...', ARRAY['Türk Edebiyatı','Şiir','Hayat Uyar']::text[], 8.5, '{"poet":"Hayat Uyar","poet_slug":"hayat-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bittigi-yerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş kaldı', 'bos-kaldi-hayat-uyar-mcova', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerim pencerene bakamaz oldu

Sen gittin bu sokak boş kaldı

Dizlerim parklara yürümez oldu

Sen gittin masamız boş kaldı

Sahilde yürüdüm elim cebimde

Sessiz bir çığlık var kalbimde

Duymadım hoşçakal desende

Sen gittin kalbim boş kaldı', 'Gözlerim pencerene bakamaz oldu Sen gittin bu sokak boş kaldı Dizlerim parklara yürümez oldu Sen gittin masamız boş kaldı Sahilde yürüdüm el...', ARRAY['Türk Edebiyatı','Şiir','Hayat Uyar']::text[], 8.5, '{"poet":"Hayat Uyar","poet_slug":"hayat-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bos-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çimkent', 'cimkent-hayat-uyar-v102m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalanların çok olduğu

Aşkların bol olduğu

Votkanın dere olduğu

Bir yer adı çimkent

Devuşka''nın hangisini istersen

Şaşlık etin neresini istersen

Alemlerin en güzelini istersen

Bir yer adı Çimkent

(Çimkent/Kazakistan Şubat 1998)

Şair bu şiiri,1998 de Türk cumhuriyetlerine yaptığı bir gezi de yazmıştır.', 'Yalanların çok olduğu Aşkların bol olduğu Votkanın dere olduğu Bir yer adı çimkent Devuşka''nın hangisini istersen Şaşlık etin neresini ister...', ARRAY['Türk Edebiyatı','Şiir','Hayat Uyar']::text[], 8.5, '{"poet":"Hayat Uyar","poet_slug":"hayat-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/cimkent-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuktum', 'cocuktum-hayat-uyar-4moqb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çocuktum şendim, Dünya''yı bilmezdim

Koşardım ağlardım

Annemin elini tutardım sımsıkı

Kaybolma derdi bir fısıltı

İşte kayboldum anneciğim

Terkedilmiş bir şehirdeyim

Yalnızım şevkâtini arıyorum

Hastayım alnımda titreyen ellerini arıyorum

Unutmadım geceleri baş ucumda oturduğunu

Boncuk boncuk terlerimi sildiğini

Bana gece sütü içirdiğini

Arıyorum anam seni arıyorum

Bu karanlık şehir de bulamıyorum

Bir fısıltı geliyor kulağıma

Bu cehennem karanlığında

Sen cennetten sesleniyorsun

Yavrum geçmiş olsun diyorsun', 'Çocuktum şendim, Dünya''yı bilmezdim Koşardım ağlardım Annemin elini tutardım sımsıkı Kaybolma derdi bir fısıltı İşte kayboldum anneciğim Ter...', ARRAY['Türk Edebiyatı','Şiir','Hayat Uyar']::text[], 8.5, '{"poet":"Hayat Uyar","poet_slug":"hayat-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cocuktum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlara, taşlara', 'daglara-taslara-hayat-uyar-cnppn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dağlara, taşlara, ovalara

Yeşil yeşil yaylalara

Yaprağına çamlarına

Haykırdım sevdiğimi.

Irmağına, deresine

Soğanına, teresine

Koyununa tekesine

Haykırdım sevdiğimi', 'Dağlara, taşlara, ovalara Yeşil yeşil yaylalara Yaprağına çamlarına Haykırdım sevdiğimi. Irmağına, deresine Soğanına, teresine Koyununa teke...', ARRAY['Türk Edebiyatı','Şiir','Hayat Uyar']::text[], 8.5, '{"poet":"Hayat Uyar","poet_slug":"hayat-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/daglara-taslara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derbeder', 'derbeder-hayat-uyar-7azyh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevmem dedim yine sevdim

İçmem dedim yine içtim

Dertsiz idim dertlendim

Derbederim derbeder

Beklemem dedim bekledim

Yine baktım yollara

Gelirse gelsin dedim

Gitmem ben uzaklara

Bakarsan maziye

Muhtaç ol sevgiye

Hasret kal gülmeye

Derbederim derbeder', 'Sevmem dedim yine sevdim İçmem dedim yine içtim Dertsiz idim dertlendim Derbederim derbeder Beklemem dedim bekledim Yine baktım yollara Geli...', ARRAY['Türk Edebiyatı','Şiir','Hayat Uyar']::text[], 8.5, '{"poet":"Hayat Uyar","poet_slug":"hayat-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/derbeder-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deyin ki', 'deyin-ki-hayat-uyar-plmbq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gün soracak size aramaklıca

Deyin ki o şimdi asker

Bir gün bakacak gurbete özlemlice

Deyin ki o şimdi derbeder.

Bir gün bakacak kadeh diplerine

Deyin ki sevileri kadeh diplerindeydi

Bir gün soracak nasıl seviyordu

Deyin ki sevgisi sonsuz ölesiyeydi

Bir gün soracak size kimdi sevdiği

Deyin ki anlamadın mı sendin istediği', 'Bir gün soracak size aramaklıca Deyin ki o şimdi asker Bir gün bakacak gurbete özlemlice Deyin ki o şimdi derbeder. Bir gün bakacak kadeh di...', ARRAY['Türk Edebiyatı','Şiir','Hayat Uyar']::text[], 8.5, '{"poet":"Hayat Uyar","poet_slug":"hayat-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/deyin-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlar', 'dostlar-hayat-uyar-npesw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Unutacaklar elbet birgün

Dost bilip bağrımıza çektiklerimiz

Beddua ederler belki bize

Dost bilip dua ettiklerimiz

Selam verip arkadaş olduğumuz

Dünü yarını konuştuğumuz

Dertlerine ortak olduğumuz

Unuturlar elbet dost sandıklarımız', 'Unutacaklar elbet birgün Dost bilip bağrımıza çektiklerimiz Beddua ederler belki bize Dost bilip dua ettiklerimiz Selam verip arkadaş olduğu...', ARRAY['Türk Edebiyatı','Şiir','Hayat Uyar']::text[], 8.5, '{"poet":"Hayat Uyar","poet_slug":"hayat-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dostlar-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerim seni', 'duslerim-seni-hayat-uyar-pnt4w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ceylan gibi çağlayanda düşlerim seni

Nilüfer gibi göllerde düşlerim seni

Serap gibi çöllerde düşlerim seni

Gül gibi bahçemde düşlerim seni

Sevda gibi gönlümde düşlerim seni

Esas gibi rüyamda düşlerim seni

Deli gibi çılgınca severim seni

Özlerim seni düşlerim seni

Güneş gibi ufukta düşlerim seni

Çam gibi ormanda düşlerim seni

Yanımda gibi karşımda düşlerim seni

Dün gibi yarında düşlerim seni

Yıldız gibi göklerde düşlerim seni

Nefes gibi ömrümde düşlerim seni

Tel gibi sazımda düşlerim seni

Gönül istiyor özlerim seni', 'Ceylan gibi çağlayanda düşlerim seni Nilüfer gibi göllerde düşlerim seni Serap gibi çöllerde düşlerim seni Gül gibi bahçemde düşlerim seni S...', ARRAY['Türk Edebiyatı','Şiir','Hayat Uyar']::text[], 8.5, '{"poet":"Hayat Uyar","poet_slug":"hayat-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/duslerim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emirdağında', 'emirdaginda-hayat-uyar-skypm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Emirdağında, 

Hüzün dolu gecelerin birisi

Düşüncelerim yosun tuttu rıhtımlarda

Sevilerim yine kadeh diplerinde

Gözlerim kan çanağına dönmüş

Dünya da en acı şey zulümmüş, 

Bir şeyler yazıyorum, şu balkonda

Ama neyi, kimi bilemiyorum.

Neyi anlatmak istiyorum bu gece

Neden, niçin, nasıl, nerde? 

Dalıyor gözlerim göklere, yıldızlara

Benziyor herşey dünkü akşamlara

Hasretim belki sevgi ile bakan gözlere

İsyanım belki yazamadığım şiirlere

Dalıyor gözlerim yıldızlı gecelere

Emirdağında, hüzün dolu göklere.', 'Emirdağında,  Hüzün dolu gecelerin birisi Düşüncelerim yosun tuttu rıhtımlarda Sevilerim yine kadeh diplerinde Gözlerim kan çanağına dönmüş ...', ARRAY['Türk Edebiyatı','Şiir','Hayat Uyar']::text[], 8.5, '{"poet":"Hayat Uyar","poet_slug":"hayat-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/emirdaginda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Es deli rüzgar', 'es-deli-ruzgar-hayat-uyar-1i02t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Es deli rüzgâr toz duman

Yağsın yağmur, Her yer çar çamur

Seller götürsün bütün anıları

Ömrüm yaşıyor şimdi son baharını

Es deli rüzgâr toz duman

Dök yaprakları kır dalları

Salla delice ulu çınarları

Ömrüm yaşıyor şimdi son baharını', 'Es deli rüzgâr toz duman Yağsın yağmur, Her yer çar çamur Seller götürsün bütün anıları Ömrüm yaşıyor şimdi son baharını Es deli rüzgâr toz ...', ARRAY['Türk Edebiyatı','Şiir','Hayat Uyar']::text[], 8.5, '{"poet":"Hayat Uyar","poet_slug":"hayat-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/es-deli-ruzgar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evde kalmışız', 'evde-kalmisiz-hayat-uyar-olusy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İkimizde evde kalmışız

Bulamadık aradığımızı

Gel beraber bağlayalım

Şu gönül bağımızı

Dün bugün yarın 

Hep boşuna geçecek

Bu boş gönüller

Kimbilir kimi sevecek

İstermisin beraber olalım

El ele göz göze gönüllerle

İstermisin mutlu olalım

Sevgiyle, aşkla, özlemle', 'İkimizde evde kalmışız Bulamadık aradığımızı Gel beraber bağlayalım Şu gönül bağımızı Dün bugün yarın  Hep boşuna geçecek Bu boş gönüller Ki...', ARRAY['Türk Edebiyatı','Şiir','Hayat Uyar']::text[], 8.5, '{"poet":"Hayat Uyar","poet_slug":"hayat-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/evde-kalmisiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Suskun Tutsak', 'suskun-tutsak-mustafa-engin-karatay-ufnp9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beni bende arama, gittiğin günden beri! .. 

Senle birlikte gittim, dönmedim daha geri 

Rotasız gemi gibi, kayboldum sularında; 

Bir liman bulamadan, dolaşırım serseri... 

Setler çekip kapattın, döneceğim yolumu 

Yanında zindânlara, zincirledin kolumu 

Ne kurtuluşum mümkün, ne kaçış yönüm belli; 

Hayâlin bir gardiyân, tutmuş sağım-solumu... 

Şimdi perişân hâlim, kim kaç dilde pelesenk? 

Adım: mecnûn, âvâre; farketmez! İkisi denk! 

Kendini kaybetmiş''in, ölüden farkı var mı? 

Sana esîr oluşum; boynuma geçmiş çelenk... 

Rûh gibiyim sorarsan; suskun, tutsak ve bitik; 

Gönlü kelepçelenmiş, bütün umûdu yitik 

Ve, hayâta küsmüş''ün; son arzusu, son satır: 

-Hazırım infâzına, çekiver bitsin tetik! 

13.12.2002  Münih   05:05', 'Beni bende arama, gittiğin günden beri! ..  Senle birlikte gittim, dönmedim daha geri  Rotasız gemi gibi, kayboldum sularında;  Bir liman bu...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/suskun-tutsak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir resim gibi, Bir masal gibi...', 'bir-resim-gibi-bir-masal-gibi-cem-bektas-4zodw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kendi ışığını güneş sanan bir yıldızböceğinin gündüz gözüyle gördüğü ilk ağaçta şirin kırmızı kirazlar olsun. Ayva, nar, elma da olsun biraz. Ama en çok kiraz olsun.

Birazcık tatil olsun okullar. Birazcık beyazlaşsın dünya. Birazcık kar tanesi düşsün yere...

Umutlarımız bir çiçek olup delsinler karla kaplı kişisel gökyüzlerini...

Bir resim gibi olsun her şey... “Bir renk gibi hür, bir gökkuşağı gibi kardeşçe”.

İğne kadar bir balık mide rahatsızlığı yaşamadan yiyebilsin balina balığını.

Sinek gösterişli hortumuyla ormanlarda gezinsin filler ise iskambil kağıtlarında azıcık dinlensin.

Kuşların elleri olsun, erkek kuşların eli ekmekle dolsun, kadın kuşların eli çamaşırları ovsun. Kuşların yıkadıkları çamaşırları asabilecekleri çamaşır telleri olsun. Kuşların tellerine telgraflar konsun.

Güneş yerine vekaleten bir partikülünü bırakıp uçsuz bucaksız bir kumsalda şezlonguna uzanıp güneşlensin birazcık. Gözünde güneş gözlüğü, elinde güneş yağı, teninde güneş yanığı... Orada kalsın birkaç bin güneş yılı.

Yağmurlardan bulut yağsın, bulutlar toprağı ıslatsın. Toprağın derinliklerindeki kör solucanlar yollarını her şaşırdıklarında bir bitki kökü onları Tanrı misafiri saysın. Misafirperver bitkilere Tanrı daha çok bulut yağdırsın.

Dünyanın üçte üçünde, ıssız adaları koynunda gerdanlık gibi taşıyan bir deniz olsun, kalan kısmında ise hiçbir şey kalmasın.

Deniz kızlarının gözleri mavi olsun, deniz adamlarının ise yeşil. Aşklarının azıcığı küçük olsun, azıcığı ölümcül. Kalpleri ise kıpkırmızı olsun, kanları da, bayrakları da. Ve bir beyaz yıldız da olsun bayraklarında.

Dünyada devler yaşasın. Dev anneler, ağlayan dev bebeklerine, dev tavuklardan ürettikleri dev yumurtaları, yanardağların orta hararetteki ateşlerinin üstünde pişirsinler. Dev annelerin dev tavaları da olsun, dev mutfak robotları da olsun, develeri de olsun.

Devlerin dışında dünyada Robot panterler, Kaba Sakal, Safinaz, ve Temel Reis yaşasın. Temel reis Safinaz’ dan şiddetli geçimsizlik nedeniyle boşansın, Safinaz bohçasını kapıp Kabasakal’ a kaçsın. Robot panterler birleşip Voltran’ ı oluştursun... Voltranlar birleşip “Birleştirme Derneği” kursun... Bu dernek kaçan Safinaz ile depresyondaki Temel’ i yeniden birleştirmenin hayalini kursun.

Bir masal gibi olsun her şey...

Pamuk cüce yedi prensesin arasına düşsün.

Uyuyan güzel, yakışıklı kurbağa tarafından öpülsün.

Külkedisi rüyasında balkabağından arabasıyla çizmeli kediyi görsün.

              Gökten üç elma düşsün, elmaların düştüğü yelerde elma ağaçları büyüsün.', 'Kendi ışığını güneş sanan bir yıldızböceğinin gündüz gözüyle gördüğü ilk ağaçta şirin kırmızı kirazlar olsun. Ayva, nar, elma da olsun biraz...', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-resim-gibi-bir-masal-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimizdeki Sonsuzluk Mesafeleri', 'i-cimizdeki-sonsuzluk-mesafeleri-reha-basogul-djlhg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İnsan 

içimizdeki yüzünden

öyle bir varlıktır ki

sonsuzluktaki en küçük noktada

ve noktadaki  en büyük  sonsuzluktadır

insan 

sonsuzluk yüzünden

öyle bir çelişkidir ki 

noktasının uçları birbirine en yakın uzaklıkta

ve en uzak yakınlıktadır

İnsan 

mesafeleri yüzünden

öyle bir ironidir ki

uçlarının içerisi kadar hiç

ve dışarısı kadar heptir', 'İnsan  içimizdeki yüzünden öyle bir varlıktır ki sonsuzluktaki en küçük noktada ve noktadaki  en büyük  sonsuzluktadır insan  sonsuzluk yüzü...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/icimizdeki-sonsuzluk-mesafeleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalpten Sözümüz', 'kalpten-sozumuz-halil-gulel-apx04', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mazlumun sesiyim, zalime belâ; 

Gerçektir sözümüz kalpten sözümüz.

Yaradan’a aşık aşka müptela

Hakk’tandır özümüz kalpten sözümüz.

Insan olmak insan çilede pişip, 

Varmalı menzile dağları aşıp, 

Vuslat arzularım gönülden coşup

Aydındır yüzümüz kalpten sözümüz.

Dosttan gelen cefa toydur, düğündür, 

Mazlumu güldürmek ne güzel gündür, 

Dertliye bir çare mutlu bir andır

Böyledir yazımız kalpten sözümüz.

Namerdin zehirden acıdır aşı, 

Geçince yıl, karlar boyuyor başı, 

Yoksulla, öksüzden silince yaşı 

Bitmekte sızımız kalpten sözümüz.

Güzellik işimiz birliktir dilek, 

Hakk aşkıyla atar cümlede yürek, 

Ressam Halil için edersen merak

Dünyada gözümüz kalpten sözümüz.

		Ressam Halil GÜLEL

		Düsseldorf / 16.09.2001

