INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Desem Boşuna', 'ne-desem-bosuna-halil-gulel-2askg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seher vakti vardım yâr kapısına; 

Açmaz ki ne desem boşuna güzel...

Gül toplayıp şerbet döktüm tasına

Içmez ki ne desem boşuna güzel...

Ilahi buyruğa uydukça özüm, 

Şen olur yüreğim gülümser gözüm, 

Herkese geçerken bir sana sözüm

Geçmez ki ne desem boşuna güzel...

Kafdağı’nda saray kurdum o yâre, 

Gel gidelim dilber düşmeden zare, 

Gül, karanfil kokan bizim diyara

Göçmez ki ne desem boşuna güzel...

Huzur gerek huzur en evvel başta, 

Anmalı verilen sözü her yaşta, 

Bencil duyguları gerçekte düşte

Biçmez ki ne desem boşuna güzel...

Perilerden şirin eşsiz sultana, 

Bir güzellik geldi aşkla cihana, 

Yıldırım hızıyla zol aldım sana

Uçmaz ki ne desem boşuna güzel...

Kafdağı’nda gördüm ilk önce günü, 

Arzular bu gönül arzular seni, 

Vefalı yâr diye alemde beni

Seçmez ki ne desem boşuna güzel...

		Ressam Halil GÜLEL

		Düsseldorf / 06.07.2002

