INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Çizgi', 'i-ki-cizgi-nevzat-celik-3d7oq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'avucumdan düşüyor iki çizgi

biri ak kara biri

ak sizin olsun

bahar açan dağlara düşer yolu

kara bende kalsın

yaftalı ölümle biter sonu', 'avucumdan düşüyor iki çizgi biri ak kara biri ak sizin olsun bahar açan dağlara düşer yolu kara bende kalsın yaftalı ölümle biter sonu...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Çelik']::text[], 8.5, '{"poet":"Nevzat Çelik","poet_slug":"nevzat-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/iki-cizgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Yılkı Aşkı', 'yilki-aski-mehme-arslan-q1zd3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir sevdam var bu kışı çıkarmaz dediğim, 

Bir aşkım

Zemheri sert geçer buralarda

İkimizi birden doyurmaz bu ekin

Yapılacak tek şey

Bırakmalıyım sevdamı mor dağ eteklerine

Kışı çıkarması için

Çıkarırsa ne ala

Tekrar alıp beslerim

Ama çıkarmazsa...

Üzülmemeliyim

Malum ikimizi de çıkarmaz bu ekin.

01.08.2002, İstanbul', 'Bir sevdam var bu kışı çıkarmaz dediğim,  Bir aşkım Zemheri sert geçer buralarda İkimizi birden doyurmaz bu ekin Yapılacak tek şey Bırakmalı...', ARRAY['Türk Edebiyatı','Şiir','Mehme Arslan']::text[], 8.5, '{"poet":"Mehme Arslan","poet_slug":"mehme-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yilki-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Yerinde', 'senin-yerinde-emir-yurtoglu-9f8eu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kırık bir kalbim var, 

Senin yerine bu bedende...

Her şey bitti sen varsın, 

Harabe olmuş sevgimde.

Bitmeyen gecelerimde 

Senin yerine

Yıpranmış bir deste mektup, 

Bir ömür verilmiş sevda benimle.', 'Kırık bir kalbim var,  Senin yerine bu bedende... Her şey bitti sen varsın,  Harabe olmuş sevgimde. Bitmeyen gecelerimde  Senin yerine Yıpra...', ARRAY['Türk Edebiyatı','Şiir','Emir Yurtoğlu']::text[], 8.5, '{"poet":"Emir Yurtoğlu","poet_slug":"emir-yurtoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/senin-yerinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Yıllar', 'ey-yillar-emir-yurtoglu-2321w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevmekten korkuttunuz beni 

Ey kahpelik dolu yıllar.

Gönlümde kabuk tutacak yer, 

Aklımda sığınacak bir liman bırakmadınız, 

Ey gençliğimi yitiren yıllar.

Çiçek koklarken arı, 

Birini severken keder, 

Sevdiklerimin yanında hüzün, 

Reva gördünüz bana, 

Ey cefa dolu sevgisiz yıllar.

Sevgi içimde bir ırmak misali, 

Akarken benliğimden, 

Irmaktan su içecek bir ceylan, 

Bulmuşken ezelden, 

Onu da benden çalan, 

Ey kahpelik simsarı acımasız yıllar.

Bıktırdınız beni kendimden, 

Yaşam denen bu çileden, 

Tek kaldığım gecelerde, 

Yaşlı gözlerimi gömerken, 

Beni deliye döndüren, 

Ey yalnızlığa boyun eydirmiş arsız yıllar.', 'Sevmekten korkuttunuz beni  Ey kahpelik dolu yıllar. Gönlümde kabuk tutacak yer,  Aklımda sığınacak bir liman bırakmadınız,  Ey gençliğimi y...', ARRAY['Türk Edebiyatı','Şiir','Emir Yurtoğlu']::text[], 8.5, '{"poet":"Emir Yurtoğlu","poet_slug":"emir-yurtoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ey-yillar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Put', 'put-funda-ozdemir-zi30j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dualar nasıl ulaşır Tanrı''ya

Hayret ederim

Kuşkularımız kesmez mi önlerini

Sözler daha inmeden dudaklara

Dudaklar ezile büzüle 

Nasıl yaranır Tanrı''ya? 

Kıvrımlarında şüphe, 

Utanır ağlamaya.

Gecenin bir yarısı

Tüm saflığı, inancıyla

Nasıl kızar gerçek Tanrı

Önünde korkuyla dizilip

Dua ettiğimiz puta.', 'Dualar nasıl ulaşır Tanrı''ya Hayret ederim Kuşkularımız kesmez mi önlerini Sözler daha inmeden dudaklara Dudaklar ezile büzüle  Nasıl yaranı...', ARRAY['Türk Edebiyatı','Şiir','Funda Özdemir']::text[], 8.5, '{"poet":"Funda Özdemir","poet_slug":"funda-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/put-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör', 'kor-funda-ozdemir-ix9qx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Görmeyen bir insanın elinden tuttum

Eli yüreğime soktum, bir çocuk buldum.

Hafif hafif söyledi ninnisini

Gözümü kapadım, ben de kör oldum.

Kör oldum, bir bulut ruhuma girdi, 

Bir yağmurdur aldı başını gitti.

Dudağında taze toprak kokusu

Sevdiğim geldi, alnımdan öptü.

Alnımdan öptü, yanar hala ten.

Cehennem azabında ölünmez iken

Güneşe bakan gözler nasılsa

Kör oluyor, öldüğünü bilmeden.

Öldüğünü bilmeden bir dilek tutmuş, 

Saçları dağılmış, bir şiir yazmış, 

Tutmuş yüreğini, çekmiş çıkarmış

Cenneti bulmuş küçük elinde

Başka şey görmezmiş o günden beri.', 'Görmeyen bir insanın elinden tuttum Eli yüreğime soktum, bir çocuk buldum. Hafif hafif söyledi ninnisini Gözümü kapadım, ben de kör oldum. K...', ARRAY['Türk Edebiyatı','Şiir','Funda Özdemir']::text[], 8.5, '{"poet":"Funda Özdemir","poet_slug":"funda-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karda Yürümek', 'karda-yurumek-sevinc-keles-psgri', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dağların beyazını seyrediyorum bu sabah penceremde

Hiç bu kadar beyaz görmemiştim onları.

Toprağı, kurumuş ağaçları karla örtüşen dallarını seyrediyorum 

Küçükken yaptığımız burnuna havuç, gözlerine kömür

Eline süpürge, boynuna atkı bağladığımız o güzelim kardan adamı yapmak istiyorum 

Ellerim donarak.

İnsanları seyrediyorum bu sabah penceremde karda yürümek zor olmalı 

Adımlarını atarken daha sağlam, başları daha dik, vücutlar daha dengede olmalı düşmemek için.

Keşke onların yerinde olsaydım ve ben hep düşseydim 

Ben karda yürümeyi çok severdim.

Adım atarken hani çıkan ses varya ”gırç, gırç” diye o sesi ben çok severdim.

O kadar özledim ki karda yürümeyi hem de çok bilir misiniz, hayır bilemezsiniz.

Çünkü siz çok şanslısınız, elinizden alınmadı hiçbirşeyiniz.

Kalbim ve ruhum bu kadar isterken ayaklarım buna mani, 

Bedenimse, çaresiz mecbur itaatkar.

Benim özlediklerimi azcık sizlerde özleyin olur mu? 

Ben yaşayamazken siz yaşayın ve öyle yaşayın ki

Bir daha hiç yaşayamayacakmış gibi...', 'Dağların beyazını seyrediyorum bu sabah penceremde Hiç bu kadar beyaz görmemiştim onları. Toprağı, kurumuş ağaçları karla örtüşen dallarını ...', ARRAY['Türk Edebiyatı','Şiir','Sevinç Keleş']::text[], 8.5, '{"poet":"Sevinç Keleş","poet_slug":"sevinc-keles","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/karda-yurumek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bölücü Yeşil', 'bolucu-yesil-i-kbal-yasin-ncbi8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'En acı veren çehrelerin, 

En utangaç bakışların, 

Gözetimindeki kürek mahkumu! 

Yeşil deryanın en uzun müebbeti.

Hey ben! 

Ön bahçedeki güller koklanmayı bekliyor, 

Dikenler kanatmadan batmayı, 

Çimenler beyaz gömleğinde hoş bir iz bırakmayı.

Ne zaman bitiyor müebbet? 

- Derya mai renkli olunca, 

  Fırat gibi yırtılıp akınca.

  Bizim yasada ölene af çıkmaz, 

  Secdeye baş koymadıkça!', 'En acı veren çehrelerin,  En utangaç bakışların,  Gözetimindeki kürek mahkumu!  Yeşil deryanın en uzun müebbeti. Hey ben!  Ön bahçedeki güll...', ARRAY['Türk Edebiyatı','Şiir','İkbal Yasin']::text[], 8.5, '{"poet":"İkbal Yasin","poet_slug":"i-kbal-yasin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bolucu-yesil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tık Makina Gacır Mutluluk', 'tik-makina-gacir-mutluluk-i-kbal-yasin-unsve', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tık tık tık ritimli şu topraklarda hayat, 

Ve bu makinada gıcırdayan bir çark.

Her çarkın ritmi aynı, 

Anlatsam derdimi, tesellim Tık tık tık! 

Hangi kuvvet döndürüyor bu çarkları? 

Ara bunun cevabını insanlarda, 

Tek cevapları Tık tık tık! 

Gacır Gucur hayat geçmez.

Sökün atın beni bu makineden, 

kendi kutumda daha rahat paslanırım.

anladım ki: 

Düzensiliğin en basit, 

en düzenli ritmi Tık tık tık! 

Yaşam taze girer, 

bayat ölüm, ürün çıkar.

Şeytanın parmağı düğmede

Hadi Kırın şu parmağı, 

Bakarlar bana Tık tık tık! 

Eğer bu çarklarda kırılırsa şeytanın parmağı, 

işte o an anlarız 

yaşamdan daha tazeymiş ölüm.

Allah sorduğu zaman, 

Eyvahki sana! 

Hala diyorsan Tık tık tık...', 'Tık tık tık ritimli şu topraklarda hayat,  Ve bu makinada gıcırdayan bir çark. Her çarkın ritmi aynı,  Anlatsam derdimi, tesellim Tık tık tı...', ARRAY['Türk Edebiyatı','Şiir','İkbal Yasin']::text[], 8.5, '{"poet":"İkbal Yasin","poet_slug":"i-kbal-yasin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/tik-makina-gacir-mutluluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Özledim', 'cok-ozledim-mehmet-kemal-tumac-6taw8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir bahar yorgunu yüreğimde

dudaklarındaki gülümseyişi özledim.

ölüme yaklaşırken adım adım.

sevdanı yüreğinde bir kin gibi tutmanı, 

dışa vurumlarda ağlayışını özledim.

deli gibi sevdanı gösteripte

titrek adımlarında korkularını gizlemeni

ve sevi yalnızlığında

yaşamanı özledim.', 'bir bahar yorgunu yüreğimde dudaklarındaki gülümseyişi özledim. ölüme yaklaşırken adım adım. sevdanı yüreğinde bir kin gibi tutmanı,  dışa v...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kemal Tumaç']::text[], 8.5, '{"poet":"Mehmet Kemal Tumaç","poet_slug":"mehmet-kemal-tumac","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/cok-ozledim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizken', 'sensizken-ufuk-nazim-n0oec', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ayazdayım, 

Sensizliğin uykusunda

Yokluğunun gamındayım.

Yok senden öncesi hayatın, 

Nede sensiz sonrası.

Güneş doğmuyor sensiz, 

Işıksız ve umutsuzum 

Yeter bu ayrılık!              

Ufuklardaki kızıllığınla

Ve denizlerdeki parıltınla, 

DÖN GERİ!', 'Ayazdayım,  Sensizliğin uykusunda Yokluğunun gamındayım. Yok senden öncesi hayatın,  Nede sensiz sonrası. Güneş doğmuyor sensiz,  Işıksız ve...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sensizken-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dava Yolunda', 'dava-yolunda-namik-kemal-sucin-xz9kr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir bayrağı bayrak yapan üstündeki kandır.

Vatan uğrunda ölen varsa vatandır.

Sen sahip çıkarsan bu vatan batmayacaktır.

Sahip çıkılmayan vatanların batması haktır.

Atalarımız dökmüş bu vatan için kan.

Hangi kalp burdan gitmek ister can.

Sen beni bırak kendi haline yan.

Türkiye bizim sen nasıl sanarsan san.', 'Bir bayrağı bayrak yapan üstündeki kandır. Vatan uğrunda ölen varsa vatandır. Sen sahip çıkarsan bu vatan batmayacaktır. Sahip çıkılmayan va...', ARRAY['Türk Edebiyatı','Şiir','Namık Kemal Suçin']::text[], 8.5, '{"poet":"Namık Kemal Suçin","poet_slug":"namik-kemal-sucin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dava-yolunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamadın', 'anlamadin-ceyhun-yilmaz-n6n1l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hiç anlamadın beni 

bir geminin limandan ayrılmasına 

ağladığımı görmedin 

sen bilmezsin 

liman olurum ben giden her vapurun ardından 

bazen deniz.... 

ve bir geminin pervanesi değidir 

betona çarpıp üstünü ıslatan o damlalar! 

el sallamalar arasında 

göz yaşlarımı dalga sanır herkes', 'hiç anlamadın beni  bir geminin limandan ayrılmasına  ağladığımı görmedin  sen bilmezsin  liman olurum ben giden her vapurun ardından  bazen...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/anlamadin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçış', 'kacis-ufuk-nazim-hjodd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugün, 

Kendimiz için bir şeyler yapalım, 

Yabancılaştığımız, uzaklaştığımız.

Kendimize bakalım bugün.

Hüzünden kemiklerim sızlıyor, 

Ellerim bomboş, 

Yüreğimde yıkılmışlık.

Vazgeçmişiz, 

Bu güzel dünyadan. 

Beynimdeki sokaklar, 

Karatılmış, 

Umudun aydınlık bombardımanına karşı.

Saatler, 

Ölümü çağrıştırıyor. 

Zaman, 

Hayat denen ulu ve yalnız dağın, 

Üzerinde birikip.

Aykırı haykırışlarla, 

Bizi boğmaya hazırlanan, 

Büyük bir çığa gebe her an, 

Ve her saniye; 

Üzerimize örülen duvarın taşlarıdır.

Ölümün çığlığı kulaklarımızda, 

Kaçıyoruz, her şeyden kaçıyoruz, 

Hovarda rüzgarlar gibiyiz; 

Her yönden her yöne esen.

Beyin çöllerinin, 

Güneşsiz karanlığını görmüyoruz.

Kör olduğumuzu bile, 

BİLMİYORUZ.', 'Bugün,  Kendimiz için bir şeyler yapalım,  Yabancılaştığımız, uzaklaştığımız. Kendimize bakalım bugün. Hüzünden kemiklerim sızlıyor,  Elleri...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kacis-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-ufuk-nazim-fxm77', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Son kez bak dünyaya, 

Gidişin ne kadar acı.

Son kez bak dünyaya, 

Ağaçlar, kuşlar nasıl üzgün.

Gidişine dayanamayıp, 

Gökyüzünden çekilmiş güneş.

Bir ben gülümsüyorum sana.

Seni tayininin çıktığı yere, 

Uğurlar gibi.

Bir ben gülümsüyorum ardından.

Seni, umudumuza kavuşacakmışsın gibi, 

Korkmadan gülerek uğurluyorum.

Ölürken dirilenlerin bahçesinde, 

Kızıl güllerin hiç solmasın.', 'Son kez bak dünyaya,  Gidişin ne kadar acı. Son kez bak dünyaya,  Ağaçlar, kuşlar nasıl üzgün. Gidişine dayanamayıp,  Gökyüzünden çekilmiş g...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ayrilik-88-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Postaci', 'postaci-huseyin-poyraz-699t4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gurbet kapisindan sila yoluna

Bakmaktan gozlerim doldu postaci.

Verecegin bir mektubun ugruna

Ellerim koynumda kaldi postaci...

Su gordugun resim yesil gozlumun

Gonlumun sultani melek yuzlumun

Buralara gelirken ben, sozlumun; 

Gulusleri lale, guldu postaci...

Gun olur comelir bir koseye ben, 

Dalarim maziye; gecip kendimden! 

Elimde sigaram, onumde sisem

Umutlarim mezem oldu postaci! ..

Hancerdende beter hasret acisi! 

Beller buker kivrandirir sancisi! 

Yaban elin asik yuzlu hancisi

Benim bu halime guldu postaci...', 'Gurbet kapisindan sila yoluna Bakmaktan gozlerim doldu postaci. Verecegin bir mektubun ugruna Ellerim koynumda kaldi postaci... Su gordugun ...', ARRAY['Türk Edebiyatı','Şiir','Huseyin Poyraz']::text[], 8.5, '{"poet":"Huseyin Poyraz","poet_slug":"huseyin-poyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/postaci-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Tanem', 'yagmur-tanem-tamer-dankarli-kjwfp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kavrulmaktayım  suya hasret gülgibi

artık geceler bir farklı 

yıldızlar seni anlatmıyorki

yağmur tanem dön geri

bana bıraktığın o kuruyaprak

iyice kurudu birtanem

bakamıyorum 

yağmur tanem dön geri', 'kavrulmaktayım  suya hasret gülgibi artık geceler bir farklı  yıldızlar seni anlatmıyorki yağmur tanem dön geri bana bıraktığın o kuruyaprak...', ARRAY['Türk Edebiyatı','Şiir','Tamer Dankarlı']::text[], 8.5, '{"poet":"Tamer Dankarlı","poet_slug":"tamer-dankarli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yagmur-tanem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geberiyorum', 'geberiyorum-seval-kemertas-ewfww', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kanar içimde bitmeyen aşklar 

Yanarım dağlarda ateşler gibi 

Hangi gün açıldı ki gonca güllerim 

Solgunum hazan yaprakları gibi 

Dört yanımı sarmış çıldırtan hazan 

Yaşanmadan kurumuş baharın bahçeleri 

Su misali geçiyor içimden zaman 

Alabildiğine coşkun, azgın bir nehir sanki... 

Özleminle yanıp tutuşunca göz bebeklerim 

Öylesine çözülür, öylesine dağılırım ki; 

Bunu ne ben anlatabilirim 

Ne de sen anlayabilirsin beni... 

Ortasındayım bitmeyen gecelerin 

Düşlerim korku dolu... 

İçimde her dakika tepinir durur 

Ayıpları, günahları yok sayan arzu 

Sensiz geceler simsiyah, karanlık 

Korkuyorum; yolunu şaşırmış martı gibi 

Acı bir tebessüm oldu dudağımda ayrılık 

İçimdeki melekler ağlıyor şimdi... 

Zamansız acılarla çöktüm, yıkıldım 

Kök saldı içimde aşkın matemi 

Öyle kahırlı, öyle kederliyim ki; 

Sorma; yokluğundan geberiyorum gibi...', 'Kanar içimde bitmeyen aşklar  Yanarım dağlarda ateşler gibi  Hangi gün açıldı ki gonca güllerim  Solgunum hazan yaprakları gibi  Dört yanımı...', ARRAY['Türk Edebiyatı','Şiir','Seval Kemertaş']::text[], 8.5, '{"poet":"Seval Kemertaş","poet_slug":"seval-kemertas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/geberiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Anka şiiri', 'bir-anka-siiri-erdal-tuter-6fpbn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Adını hatırlamak

Dört duvar arası cümle kalabalıklarında, 

Gözlerini düşünüp rahatlamak

Yitirilmiş bir zamanın

Akşamüstü yorgunluklarında.

Daha yeni çıktım 

Bir aşk meydan savaşından, 

Mağlup mu oldum, 

Yoksa galip mi? 

Ya da berabere mi bitti bütün aşklar benim yüreğimde.

Umutsuz sevgisiz sonuçlar mı yazıldı 

Benim skor tabelama.

Oysa hep onlar ev sahibi oluyorlardı, 

Ve ben deplasmana gidiyordum

Aşık olmak için.

Her deplasman dönüşü

Kendi şehrimin, 

O çıldırtan kalabalığında

Yapayalnız yürüyordum.

Kimseye çarpmıyordu omzum, 

Kimse basmıyordu ayağıma.

Binlerce kişinin yürüdüğü, öpüştüğü, 

Bir yere yetişmek için hızlı adımlar attığı

O sisli caddede, 

Sanki bir hayalettim.

Ve yine bir deplasmandan yenik dönmüştüm.

Yitirilmiş duygularımı apartman girişine bırakarak

Kendi evime girdim.

Annemi ve liliyi gördüm; 

Bana bakıyorlardı

Sanki hiç yaşanmamış bir gecenin 

Karanlığına bakıyorlardı..

Televizyon açıktı

Bütün kanallar altyazı geçiyordu

Benim aşkımın mağlubiyetini, 

Ve az sonra diyorlardı

Her saniyesi yiyen, tırmalayan

Kanatan  aşkım için, 

Az sonra diyorlardı

Umut etmesini unutan 

Yüreğimin hıçkırıklarını canlı yayınlayabilmek için.

Daha ne kadar dayanır kalbim

Bu ayrılıklara, 

Bu mağlubiyetlere

Ve ne zaman istifaya davet eder beni 

Aklım, fikrim, yüreğim diye düşünürken, 

Yeşil gözlü bir adam çok uzaktan

Kalbini gönderdi bana.

O yitirilesi kalbim güç buldu bir anda.

Ne kadar uzaktada olsa; 

Artık bütün odamı onunla ısıtıyorum, 

Bütün yemekleri onunla yapıyorum, 

Beraber televizyon izliyor, 

Sonra liliyle oynuyoruz, 

Ne kadar uzaktada olsa

Onun sözleri alıyor bütün üzüntümü

Ve yaşama olan bütün kırgınlığımı.

İlk defa ev sahibiydim

Ve ilk defa bir maçın 

İki galibi vardı yüreğimde.

Biri ben

Biri o! ! ! 

Artık umudum var, 

Yitirilmeyecek bir yüreğim, 

Dokunulası saçlarım

Ve o kalabalık caddede omzuna çarptığım, 

Ayağına bastığım insanlar var artık.

Yaşama belirtisi gösteren gözlerim 

Ve soğukta üşüsede ısıtılacak ellerim var artık.



Çünkü ben soğuk ve puslu bir Ankara akşamından

Bütün dünyaya onun yeşil gözleriyle bakıyorum

Ve gelen bütün mavileri yüreğime saklıyorum..................................', 'Adını hatırlamak Dört duvar arası cümle kalabalıklarında,  Gözlerini düşünüp rahatlamak Yitirilmiş bir zamanın Akşamüstü yorgunluklarında. D...', ARRAY['Türk Edebiyatı','Şiir','Erdal Tüter']::text[], 8.5, '{"poet":"Erdal Tüter","poet_slug":"erdal-tuter","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/bir-anka-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugünsüzlük', 'bugunsuzluk-kucuk-i-skender-z36ck', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'çizgi film dudaklarımızda bir süre rumi sürgün

bir sürü coşkusuz, bir sürü bugünsüz, bir sürü tanıdık

hüzün vardı

herkes herkesin dul annesi 

herkes herkesin şefkatli adres defteri, makyaj çantası 

herkes herkesin üvey sevgilisiydi ortalıkta

herkes herkesin ironisi, istanbul hatırası! 

telaştan olacak ağızsız bir kadınla öpüşürken korkmak

gibi bir geceydi, gündüzdü, öğleydi, vakitsizlikti ya da 

o kadardı.

hüzün var mıydı? 

                         sonra bir acı 

                                             bir tutku veya 

bir mavi gençlikli iliklere değin evliya /yağmur! 

katlanarak büyüyordu tümörlü çocukluklarımız.

ardından 

              bir hırs 

                        kıpkırmızı oluveriyordu içimizde 

                        hissederdidiz, belki hissizlik derdiniz 

içimiz dışımız öncelikle altyazısız! 

sığacak mıyız bu sahte tiyatro salonlarına

bu kremasız sinemalara-galerilere hepimiz 

hepimiz binebilecek miyiz bir anda 

bizi bekleyen örme asansörlere! 

kaçımızı alacak bu kabartma otobüsler, trenler eskaza

ve yine kaçımız sıkış sıkış yatabiliriz ki

bizler için açmış bahar çiçeği mezarlarda! 

kırk buçuk santigrad derece gözlerimizde

küçücük su damlacıkları koşuşuyor sağa sola

evet! hüzün vardı. anımsadım.

sürç-ü insan ettikse affola!', 'çizgi film dudaklarımızda bir süre rumi sürgün bir sürü coşkusuz, bir sürü bugünsüz, bir sürü tanıdık hüzün vardı herkes herkesin dul annesi...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bugunsuzluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kral Kızı', 'kral-kizi-cabukoglu-ahmet-s9z71', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Alevi, Sünni ayrımı yapanlara ithaf olunur.

Yıldızları topladım. Yoluna sermek için

Ebemkuşağını dürdüm. Beline sarmak için

Baharı kıştan ayırdım. Avucuna koymak için

Şarkı oldum. Şiir oldum. Duygu oldum. Gönlüne aktım.

Dağları geçtim. Tepeleri düz ettim. Yar nedir bilmedim.

Mavi okyanusları aştım da, Kızıl bir çizgiyi aşamadım.

Kızıl çizgi dediğim, beyinlere gerilmiş bir perdeymiş...

Yırtarım sandım, yırtamadım. Anladım.

Anladım, anladım ve Ağladım.

Kirpiklerimin arasından bir damla umut düştü

Karşılıksız sevenlere mabed oldu, kalbimin hüzün takı...

Ey dalları altında saatlerce düşündüğüm ulu çınar, 

Ey üzerinde onlarca sigara söndürdüğüm çakıl taşı, 

Söyleyin, unutmaya çalışmadım mı? 

Unutmadım, unutamadım, unutamadım.

Şimdi ise aşkının nöbetini tutuyorum.

Bu emri hangi kudretli komutan verdi, 

Hangi mühür bu kadar güçlü idi, 

Bu nöbetin bir tezkeresi var mı? 

BİLMİYORUM........', 'Alevi, Sünni ayrımı yapanlara ithaf olunur. Yıldızları topladım. Yoluna sermek için Ebemkuşağını dürdüm. Beline sarmak için Baharı kıştan ay...', ARRAY['Türk Edebiyatı','Şiir','Çabukoğlu Ahmet']::text[], 8.5, '{"poet":"Çabukoğlu Ahmet","poet_slug":"cabukoglu-ahmet","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kral-kizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otomobil Kullanma Kılavuzu', 'otomobil-kullanma-kilavuzu-turgay-kaygi-zsxjm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'size ait olup

olmaması

hiç de mühim değil; 

direksiyon simidini

kavrayan el; 

kime aitse

ona aittir

otomobil...

az sonra uzaya fırlatılacak

bir uzay mekiğine

binmeye gidiyormuş gibi

ilerleyin üstüne

ve

güzel bir kadını

dansa kaldırmak için

elinden tutup çeker gibi

açın kapısını

ölen babasının tahtına kurulan bir

prensmişsinizcesine 

yayılıp koltuğa, 

ilkin

daha önce görmeyi hayal ettiğiniz

en uzak ülkeyi, 

sonra da 

mevcut benzinin sizi

en fazla nereye kadar götürebileceğini

düşünün...

anahtarı çevirirken 

kontakta; 

o andan itibaren

başınıza gelebilecek

her şeyin, 

başınıza hiçbir şeyin

gelmemesinden

yeğ olacağını kabullenin evvela! 

marşa basmanızla

birlikte

gürül gürül

hayatı duyacaksınız, 

çok yakınınızda, 

bir adım

ilerinizde duran

hayatı...

birinci vitese takıp

vites kolunu, 

ayağınızı 

bastığınız debriyajdan

yavaş yavaş

kaldırdıkça; 

yetiştiğinizi, 

karıştığınızı hissedeceksiniz

hayata...

fakat; 

marşa bastığınız anda

ve

gazı; 

uyuyan bir dostunuzu

dürtercesine

ufak ufak

yoklamanıza karşın

ve

başınıza gelebilecek

her şeyin

başınıza hiçbir şeyin

gelmemesinden

yeğ olacağını kabullenmenize rağmen; 

motor

kuyruğuna basılmış 

bir kaplan gibi

kükreyip, 

içinizi ferahlatan

güzel ve tempolu bir

gürültü çıkaramıyorsa bir türlü, 

bu; 

‘akünüzün  boşaldığı’ 

manasına gelir...

ve

işte o anda

trafik denen

kıpır kıpır, 

anlamsız

ama aynı zamanda da

heyecan verici akıntıya doğru

itmesi için 

sizi

ve

otomobilinizi, 

vurdurmaya çağırabileceğiniz

bir-iki dostunuz bile yoksa; 

‘Cehennemin dibine kadar yolunuz var! ’

(inegöl,21.12.2002)', 'size ait olup olmaması hiç de mühim değil;  direksiyon simidini kavrayan el;  kime aitse ona aittir otomobil... az sonra uzaya fırlatılacak ...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kaygı']::text[], 8.5, '{"poet":"Turgay Kaygı","poet_slug":"turgay-kaygi","theme":"Türk Şiiri","is_hero":false,"total_lines":91,"source_url":"https://www.antoloji.com/otomobil-kullanma-kilavuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Seni Değil', 'senden-seni-degil-fuat-kaplan-evt2n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Senden seni değil

Kara gözlü güzel, 

Seni ilk gördüğüm an, 

Üzerinde kalan, 

Gözlerimi isterim.', 'Senden seni değil Kara gözlü güzel,  Seni ilk gördüğüm an,  Üzerinde kalan,  Gözlerimi isterim....', ARRAY['Türk Edebiyatı','Şiir','Fuat Kaplan']::text[], 8.5, '{"poet":"Fuat Kaplan","poet_slug":"fuat-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/senden-seni-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aptal! ...', 'aptal-tahir-yuksel-49vox', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beni bırakıp da gittiğin zaman

Keşke artık sana  ''el'' diyebilsem...

Şarkımız bitince sazımı atıp, 

''Neyleyim kırıldı tel'' diyebilsem...

Araya upuzun yıllar girince, 

Yüreğin sızlar mı inceden ince, 

Rüzgârın ıslığı ne diyor sence? 

''Aldırma güzelim yel'' diyebilsem...

Hasretle sevdânın acısı başlar

Bal diye yediğin zehrolur aşlar

Hüzünle gözüne dolunca yaşlar

Eğilip usulca ''gel'' diyebilsem...

Aranıp durulur çâre zamanda

Yürek ezikliği kalır bir yanda...

Artık umudumun bittiği anda; 

''Seni sevdiğimi bil! '' diyebilsem...', 'Beni bırakıp da gittiğin zaman Keşke artık sana  ''el'' diyebilsem... Şarkımız bitince sazımı atıp,  ''Neyleyim kırıldı tel'' diyebilsem... Aray...', ARRAY['Türk Edebiyatı','Şiir','Tahir Yüksel']::text[], 8.5, '{"poet":"Tahir Yüksel","poet_slug":"tahir-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aptal-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Yine Bana Kaldı', 'ah-yine-bana-kaldi-yasar-aslan-fx8ex', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'boğazımda düğümlenmiş kelimenin sancısı kaldı

dudağımda yarım kalan aşkın izi kaldı

kor''a dönmüş yüreğin hazin ezgisi kaldı

ahh uykusuz geceler, yıkılan hayaller 

gözlerde göz yaşı yine bana kaldı

yıldızsız geceler, dalgasız denizler

yapraksız çiçekler, kanatsız melekler

haykırışlar, çileler, sessiz ölümler

ahh yürekte gözyaşı yine bana kaldı

çıldırtan feryatlar, sahipsiz ağıtlar

ahh kefensiz ölümler yine bana kaldı', 'boğazımda düğümlenmiş kelimenin sancısı kaldı dudağımda yarım kalan aşkın izi kaldı kor''a dönmüş yüreğin hazin ezgisi kaldı ahh uykusuz gece...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Aslan']::text[], 8.5, '{"poet":"Yaşar Aslan","poet_slug":"yasar-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ah-yine-bana-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ol', 'sen-ol-salih-ozalasan-21249', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgiler seninle

Sen sevgilerle iç içe ol

Yürekler seninle

Sen hep yüreklerde ol

Ağlamasın hiç gözlerin

Sen akan gözyaşımda ol

Korkulu rüya görme hiç

Sen hep güzel rüyalarda ol

Kalbini verme benden başkasına

Sen her sevenin kalbinde ol

Karanlığı tanıma ışık sensin

Sen doğan güne Güneş ol

Yüreğini yakmasın aşk ateşi

Sen her yürekte kor ol

Her gören sana aşık, seni sevsin

Sen yalnız, ebedi benim ol

Y.Tar.21-12-2002 saat 16.32', 'Sevgiler seninle Sen sevgilerle iç içe ol Yürekler seninle Sen hep yüreklerde ol Ağlamasın hiç gözlerin Sen akan gözyaşımda ol Korkulu rüya ...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-ol-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Veda Etmek', 'veda-etmek-tolgahan-bostan-idl29', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'son sahne: 

yüzünde ılık bir rüzgar. 

saçında son bir kıpırtı. 

sarı bir gök... 

gözlerde yaş yok. 

sana veda etmek 

bir atın yelelerini okşayıp günbatımına gitmek gibi. 

ellerinde büyüyen bir özlem denemez 

kalbinde küçülen bir benek 

sana veda etmek 

üşüdükçe giydiğin bir hırkayı sökmek gibi 

sana veda etmek 

bir ülkeden çıkmak gibi 

her şey yavaşlıyor 

bir şarkı boyunca yüzünün yere baktığı oluyor 

bir susmak boyunca konuşmak istediğin 

gözlerini üstüne sermek üşümüş bir bedenin 

sana veda etmek 

tutulmamışlığını hatırlamak gibi bir elin 

kurumuş bir yaprağı kırıyorken sonunda 

ellerinin duruşundan söz açmak yersiz artık 

yüzünde bir rüyadan arta kalan güzellik 

duruşunda güzelliğin gördüğü rüya 

gülüşünün o bende yer etmişliği 

ağır bir göz kırpışı gibi 

giriyor konuşulmayacaklar arasına 

sana veda etmek 

umudun ölüsünü bırakmak gibi durgun bir suya 

kopan herşeyin resmi bize benziyor şimdi 

harften bölünmüş bir kelime, kırık bir dal 

parçalanmaya hazır gül kurusu 

ikiye ayrılan kitap 

-ki bir yarısını anlatır hep diğer yarısı- 

sana veda etmek 

bir yaprağın düşerkenki türküsü 

anlatmakla tükenmez bir sen vardı bende.. 

bir damlanın koptuğu buluttan aldıkları gibi 

bir cümleye sığabilirse herşey yine de 

içimde birikenleri al şimdi 

bildiğim en güzel şiir gözlerindi 

sana veda etmek bir şiiri unutmak gibi', 'son sahne:  yüzünde ılık bir rüzgar.  saçında son bir kıpırtı.  sarı bir gök...  gözlerde yaş yok.  sana veda etmek  bir atın yelelerini okş...', ARRAY['Türk Edebiyatı','Şiir','Tolgahan Bostan']::text[], 8.5, '{"poet":"Tolgahan Bostan","poet_slug":"tolgahan-bostan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/veda-etmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben miydim', 'ben-miydim-ugur-hasanoglu-fo73v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben miydim bu alemde sarhoş dolaşan? 

ben miydim görmeyen? 

ben miydim? 

Şimdi bildiğimi sandıklarımla bildiklerim

Ben ve evren

Şimdi bir bütünün parçası olan ben

varmak için bütüne

uzatıyorum elimi, düşümü, düşüncemi

kadim zamanların ve bilge insanların

en uyanık kavimlerin

ve adem''in

Adem olmazdan önceki şeklinin

Ve gerçeğin tüm çıplaklığını

bir mağara çıkışı gören Platon''un

ve İsa''nın, Musa''nın

ve Muhammet''in zamanına

usulca uzanan usum

gördü görmek zorunda olduğu herşeyi.', 'Ben miydim bu alemde sarhoş dolaşan?  ben miydim görmeyen?  ben miydim?  Şimdi bildiğimi sandıklarımla bildiklerim Ben ve evren Şimdi bir bü...', ARRAY['Türk Edebiyatı','Şiir','Uğur Hasanoğlu']::text[], 8.5, '{"poet":"Uğur Hasanoğlu","poet_slug":"ugur-hasanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ben-miydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha', 'daha-esin-levent-r6kv9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Daha Şehidlik''e okunmazken Fatiha; bir taze ruh''a

Alem-i Ervah''ta künyelenmiş miydik cümle Cüruh''a? 

Daha? 

Dahası yok! 

Dikildi gözleri Havariler''in, Beyt-i Makdis''de çarmıka

Son vuruş, o son vuruş da

Balyozumdan olacak mı?', 'Daha Şehidlik''e okunmazken Fatiha; bir taze ruh''a Alem-i Ervah''ta künyelenmiş miydik cümle Cüruh''a?  Daha?  Dahası yok!  Dikildi gözleri Hav...', ARRAY['Türk Edebiyatı','Şiir','Esin Levent']::text[], 8.5, '{"poet":"Esin Levent","poet_slug":"esin-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/daha-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçını', 'sacini-esin-levent-aq5p1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Daha divaneye döndürmemişken aşıkların kim kaçını, 

Daha rahipler kırmamışken senin için Haç''ını, 

Parmaklarım kavramamış mıydı, altın tozlu saçını?', 'Daha divaneye döndürmemişken aşıkların kim kaçını,  Daha rahipler kırmamışken senin için Haç''ını,  Parmaklarım kavramamış mıydı, altın tozlu...', ARRAY['Türk Edebiyatı','Şiir','Esin Levent']::text[], 8.5, '{"poet":"Esin Levent","poet_slug":"esin-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/sacini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşadıkça', 'yasadikca-birol-ozkan-rf1g1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gördükçe, 

elini tutan bir eli, 

yüzümde tebessümle geçtim, 

mutluydum, seninle mutluluğu paylaşmak için.

mahçuptum da gözlerine bakarken.

Gecedeki ben

ben değildim sanki, 

sanki sen değildin 

mutlu olan 

gözler yalan söylüyordu ikimize de

doğru olan da yoktu 

sen de görmüyordun ben de.

Okudukça seni, 

ondan, 

yazdıkça kalemden 

kıskanıyordum

gece oluyordu vakti gelince

ellerim titriyordu, 

yazamıyordum, 

yakıyordum şimdiki beni 

ve eskiyen seni.

Ağladıkça, 

gözlerindeki yaşı kurutmak istiyordum, 

üzülüyordum seni üzgün görmeye.

gecede ben ağlıyordum bu sefer, 

gözlerindeki yaş oluyordum

hiç kurutmamak için.

Yaşadıkça, 

görüyordum seni

ve yaşadıkça

ölmek istiyordum gecede.', 'Gördükçe,  elini tutan bir eli,  yüzümde tebessümle geçtim,  mutluydum, seninle mutluluğu paylaşmak için. mahçuptum da gözlerine bakarken. G...', ARRAY['Türk Edebiyatı','Şiir','Birol Özkan']::text[], 8.5, '{"poet":"Birol Özkan","poet_slug":"birol-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yasadikca-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir garip Orhan Veli', 'bir-garip-orhan-veli-gok-tengri-niqw5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir garip Orhan Veli''yim 

Urumeli Hisarında

Veya Nazım Hikmet''im, soğukta yakasını kaldırıp paltomun

''Seviyorum Seni'' diyerek şiir okuyorum...

Ben bir garip Orhan Veli''yim

Urumeli Hisarında; tarifsiz kederler içinde

Veya Nazım Hikmet''im dünyanın en güzel sesinden

Dinliyorum en güzel şarkısını dünyanın

Ve Istanbul''u dinler gibi gözlerim kapalı; 

Bir kız dinliyorum; Orhan Veli misali

Veya Nazım Hikmet gibi diyorum: 

''Istanbul''da yumuşacık kararırken ortalık

İçimde kımıldanan bir şeyler gibi seviyorum seni''

Tıpkı.. tıpkı ''yaşıyoruz çok şükür der gibi! ....''', 'Bir garip Orhan Veli''yim  Urumeli Hisarında Veya Nazım Hikmet''im, soğukta yakasını kaldırıp paltomun ''Seviyorum Seni'' diyerek şiir okuyorum....', ARRAY['Türk Edebiyatı','Şiir','Gök Tengri']::text[], 8.5, '{"poet":"Gök Tengri","poet_slug":"gok-tengri","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-garip-orhan-veli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım', 'yalnizligim-ali-niku-2wk3x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'oyuncaktı çocukluğumdan istenen

el emeğiyle kıvrılmış tel tekerlek

yürüttükce hüzünleri çiğneyen...

patlak toplarım vardı tamir ettiğim

onları isteyenlere seve seve verdim

benide aralarına alsınlar diye...

resim sayfaları toplardım büyüklerden

ilaveler yapardım içimi kavuranlara

çok güzeldiler bende kaldıklarında

okul oldum bilgiler yüklenesiye

isteyenlere kopya oldum biteviye

yakalan hep ben olsam da...

aşık olmak ne haddime, 

yeşil gözlere uzaklardan bakardım

ışıltıyı farketmeden çekilmez

kırpışması yüreğime değmedi

hızlı atan kalb misali heyecan

uzaklardan fısıltı gibi gelen

hayalleri kurmaksa bana düşen

isteyene onları bile verdim...

yapayalnız geçti onca yıllarım

kendim için nefes bile almadım

şimdi koskoca bir yalnızlık

istemeden hep kucağımda olan

onu paylaşacak bir dost ararım', 'oyuncaktı çocukluğumdan istenen el emeğiyle kıvrılmış tel tekerlek yürüttükce hüzünleri çiğneyen... patlak toplarım vardı tamir ettiğim onla...', ARRAY['Türk Edebiyatı','Şiir','Ali Niku']::text[], 8.5, '{"poet":"Ali Niku","poet_slug":"ali-niku","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yalnizligim-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyiş', 'bekleyis-tunc-asker-fplix', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sarıyor bileklerimi

Sıçrıyor dizlerime

Tuzunu bırakmış üzerimde

Vermiş birde hayatını, yeşil

Benmi gelmişim o''na, 

O''mu gelmiş beni almaya

Bir ayağım ilerde, 

Sıradan bir gidiş gibi

Takılı kalmış olduğu yerde

Birde o, yüzüme vuran arkadaşın...', 'Sarıyor bileklerimi Sıçrıyor dizlerime Tuzunu bırakmış üzerimde Vermiş birde hayatını, yeşil Benmi gelmişim o''na,  O''mu gelmiş beni almaya B...', ARRAY['Türk Edebiyatı','Şiir','Tunç Asker']::text[], 8.5, '{"poet":"Tunç Asker","poet_slug":"tunc-asker","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bekleyis-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Benim İşte', 'o-benim-i-ste-salih-ozalasan-day7q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kurumuş bir yaprak görürsen yerlerde savrulan

Tutunacak dalı kalmamış, ağacı kuruyan

Her geçen basıp geçmiş üzerine durmadan

Bilki o benim, mevsimsiz yerlere dökülen

Bir köşede görürsen, gözü yaşlı ağlayan

Gözyaşını silecek bir mendili bile olmayan

Sorma sakın; ? Neden ağlıyorsun; ? Kim seni ağlatan

Bir vefasız yârdir yüreğimi kor ateşlerle dağlayan

Kanadı kırık bir kuş görürsen yerlerde uçamayan

Pusmuşsa bir köşeye etrafı yılan çiyan

Kanadımı sarma sakın; Artık asla uçamam

Bir vefasız yârdir, benim iki kanadım kıran

Bir duman görürsen, ortalarda yangın olmadan

Kara bir bulut olup göklerde öylesine savrulan

Kurumuşsa yağmurlarım, bir tek damla yağmadan

Bir vefasız yârdir, benim yağmurlarımı kurutan

Y.Tar 20-12.2002 Saat 14.00', 'Kurumuş bir yaprak görürsen yerlerde savrulan Tutunacak dalı kalmamış, ağacı kuruyan Her geçen basıp geçmiş üzerine durmadan Bilki o benim, ...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/o-benim-iste-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhtiyacım Var', 'i-htiyacim-var-melih-coskun-cds3o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sonsuz kederine değil, 

Gözlerinin içi gülen çocuklarına ihtiyacım var.

Ağlayışların değil, 

Duvarlarından kahkahaların yankılandığı bir şehre ihtiyacım var

Ağlama duvarları olmamalı şehrimde

Olmamalı dünyada.

İnsanlar öğrenmeli duvarlara ağlamamayı

Birisi anlatmalı onlara gülmeyi

Gülmeyi duvarlara

Gülmeyi bir ağaca

Gülmeyi bir buluta

En mühimi gülmeyi bir insana

Ama yine de unutmamalı hüzünlenmeyi

Sevinci değerli kılan hüzünlerdir elbette.

Susuzluğun yağmuru

Hasretlerin kavuşmayı değerli kıldığı gibi

Sana ihtiyacım var 

Ve senin gözlerinin içi gülen çocuklarına ihtiyacım var.

26 Ağustos 2002

23: 08', 'Sonsuz kederine değil,  Gözlerinin içi gülen çocuklarına ihtiyacım var. Ağlayışların değil,  Duvarlarından kahkahaların yankılandığı bir şeh...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ihtiyacim-var-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değiştim Ben de Yeryüzü Gibi', 'degistim-ben-de-yeryuzu-gibi-melih-coskun-s9kok', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Değiştim bende yeryüzü gibi

Cüzdanımda para yerine şiir taşıyorum artık

İnsanların şiirlerini 

Ağlayan insanların şiirlerini

Bir gün insanlar gülebilsin diye ağlayan insanların şiirlerini

Sevdalanmak yok benim şiirlerimde

Çünkü kanatılmış bir eylül akşamıdır

Artık bende sevdalanmak hürriyeti

Başkalarının şiirleri yetmiyor artık bana

Bana  kendi yüreğimden taşan nehirler gerek artık

Bir çocuk resmi kimi zaman

Kimi zaman ağlayan bir ana

İnsanlar ağlıyorlarsa da  bugün şiirlerimde 

Ama elbette gülecekler bir gün 

Doğuracak büyük acılar büyük mutlulukları

Her giden otobüs bir gün dönecek mutlaka

Her hasta bir gün iyileşecek

Bir şairin yüreğine bir gün aşk düşecek

Dünya daha güzel olacak yarınlarda... 

26 Eylül 2002

23: 13', 'Değiştim bende yeryüzü gibi Cüzdanımda para yerine şiir taşıyorum artık İnsanların şiirlerini  Ağlayan insanların şiirlerini Bir gün insanla...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/degistim-ben-de-yeryuzu-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şiir Okumalısın', 'bir-siir-okumalisin-melih-coskun-4tui2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir şiir okumalısın içinde umut olmalı

Bir söz söylemelisin içinde sevda olmalı 

Ve yürümelisin yolun sonunu göremesen bile

Yolun bir sonu olduğunu düşünerek

Yaşamalısın direnerek hayata 

Hayatın bir sonu olduğunu bilsen bile

Bir türkü okumalısın 

Son türkün olduğunu bilsen bile...

20 Mayıs 2002

00: 12', 'Bir şiir okumalısın içinde umut olmalı Bir söz söylemelisin içinde sevda olmalı  Ve yürümelisin yolun sonunu göremesen bile Yolun bir sonu o...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bir-siir-okumalisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Bir Yürek', 'nasil-bir-yurek-melih-coskun-1r3yf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nasıl bir yürektir bu 

Kimi zaman 

Yüzüne tükürülecek kadar korkak

Kimi zaman

Karanlığı yırtarcasına cesur

Kimi zaman bir gül dalı gibi ürkek 

İki günlük çocuk gibi acemi bazen

Neden herkesi yaşamana rağmen içinde

Herkes olamıyorsun

Neden bir çocuğun küçücük elleri ağlatıyor seni

Neden gülüyorsun yüreğin kan ağlarken

Bunca yıl devirdin 

Hala öğrenemedin yaşamayı

Ne olmalısın sen? 

Kendisi için ağlayan herkes mi

Yoksa herkes için ağlayan kendin mi? 

Dostun anlamadı seni 

Bir sazın teliyle 

Gökyüzüne değerken yüreğin

Bilemedi herkes olmadığını

Göremedi gözlerinin içini

Çünkü o da herkes den biriydi sadece

Varsın bilmesinler

Bilebilselerdi zaten

Onlarda kendileri olabilirler di belki... 

2 Ekim 2002

19: 37', 'Nasıl bir yürektir bu  Kimi zaman  Yüzüne tükürülecek kadar korkak Kimi zaman Karanlığı yırtarcasına cesur Kimi zaman bir gül dalı gibi ürke...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/nasil-bir-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahu Bakışlı Yare', 'ahu-bakisli-yare-kamil-kaya-tmn2j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir tatlı bakış 

Bir sıcak söz

Alır götürür pembe hülyalara

Gülüşünde ısınır 

Bakışlarında eririm

Saat 3.00’e ve sonrasına düşman oldum artık

Ayrılık vaktidir çünkü

Akşamları bitmez bir türlü

Ne oyun, ne de dostlar tutar yerini

Yalnız sen

Bir cümlelik mesajın 

Bir tadımlık nefesin

Yeter akşamlarıma

Yeter akşamlarımın karanlığına 

Yeter yalnızlığımın hüznüne

Yeter bütün sıkıntılarımın ızdırabına...', 'Bir tatlı bakış  Bir sıcak söz Alır götürür pembe hülyalara Gülüşünde ısınır  Bakışlarında eririm Saat 3.00’e ve sonrasına düşman oldum artı...', ARRAY['Türk Edebiyatı','Şiir','Kamil Kaya']::text[], 8.5, '{"poet":"Kamil Kaya","poet_slug":"kamil-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ahu-bakisli-yare-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eyvah', 'eyvah-kamil-kaya-jsvpi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Siyah bulutlar kapladı umutlarımı

Yarınımı ve sonrasını karartan bulutlar

Karanlık düşler yeni yoldaşlarım artık

Ümit, uzak diyarların cılız çocuğu

Aşk, soğuk iklimlerin yenilmez pehlivanı

Bir kırıntı kalmadı kereminden

Hep yanımda; 

Fakat hiç yetişemediğim gölgemsin adeta

Bir an dur 

Ve duy can-hıraş feryatlarımı

Bütün intizarım sana ey bilinmezim

Bütün isyanlarım, gözyaşlarım...

Duy ve cevap ver sesime

Gözlerimde seyret beni

Sesimde dinle türkümü

Kervanın yerleşsin gönül sarayıma

Bitir bu yolculuğu ve konakla artık

Tut elimden narin gülşenim

Anla artık 

Aşkına çizer kalemim her an gözlerini

Gülüşüne hayrandır her bir hücrem

Zaman şahidimdir ey sevgili

Varlığında huzur buldum

Tut elimden bırakma

Ey sevgili! 

En sevgili! ...', 'Siyah bulutlar kapladı umutlarımı Yarınımı ve sonrasını karartan bulutlar Karanlık düşler yeni yoldaşlarım artık Ümit, uzak diyarların cılız...', ARRAY['Türk Edebiyatı','Şiir','Kamil Kaya']::text[], 8.5, '{"poet":"Kamil Kaya","poet_slug":"kamil-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/eyvah-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Sevgili', 'ey-sevgili-kamil-kaya-a1d01', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nerdesin ey sevgili? 

Dön artık...

Ankalar yere ayak bastı

Sen dönmedin

Dön ve gör ızdırabımı

Ayrılığın Kaf Dağı’ndan büyük

Hasretin yürekte kezzap

Özlemin bir kıymık sancısı

Dön ve dindir sancımı

Bil artık ey sevgili

Seninle açmışım dünyaya gözlerimi

İlk kelimem sen oldun

İlk nefesim

İlk kalp atışım sen

Bekletme beni

Bütün rüyalarda sen varsın

Yeşilliğine açarım her sabah gözlerimi

Gözlerinin

Sesinde söylerim yanık türkülerimi

Nefesinde soluklanırım her daim

Ana rahminde ilk kıpırdayışım sanadır

Sanadır ilk pişmanlığım

İlk tevbem...

Gönlüm işgalinle şenlendi

Şenlendi dünyam

Söndü İran’ın sönmez ateşi

Ay ikiye bölündü hasretinden

Hayata merhaba dedi kardelenler

Gülüşünle can verdiğin bu miskini

Öldürme

Ve kulak ver sesime: 

Dön artık 

Nerdesin ey sevgili?', 'Nerdesin ey sevgili?  Dön artık... Ankalar yere ayak bastı Sen dönmedin Dön ve gör ızdırabımı Ayrılığın Kaf Dağı’ndan büyük Hasretin yürekte...', ARRAY['Türk Edebiyatı','Şiir','Kamil Kaya']::text[], 8.5, '{"poet":"Kamil Kaya","poet_slug":"kamil-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ey-sevgili-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Manitu''nun bakire kızı', 'manitu-nun-bakire-kizi-gok-tengri-834qy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kızıl toprağa boyanmış sarı-siyah deri karşıladı onu; 

Çıplaklığından rahatsız olmayan kadınlar...

Manitu''nun bakire kızı: Kızılderili toprağı

Kirletti onu Avroamerikan

Manitu dayanamadı bu pisliğe; öldü kahırdan...

Ve şimdi günah mı çıkarmakta zavallı Avroamerikan

Hangi kilise rahibi çıkaracak o kadar günahı

İsa bile çıkaramaz; zavallı Hıristiyan

Zaten tarih itibarıyla dindar olamaz ki o

Affetmeyecek hiç bir zaman torunlarına cips sevdireni ihtiyar ESKİMO! ..', 'Kızıl toprağa boyanmış sarı-siyah deri karşıladı onu;  Çıplaklığından rahatsız olmayan kadınlar... Manitu''nun bakire kızı: Kızılderili topra...', ARRAY['Türk Edebiyatı','Şiir','Gök Tengri']::text[], 8.5, '{"poet":"Gök Tengri","poet_slug":"gok-tengri","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/manitu-nun-bakire-kizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kirli kanlılar', 'kirli-kanlilar-gok-tengri-m91t3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İyi kızılderili Tosawi''ye...

En iyi zenci ölü zencidir diyip

Onu öldüren soluk benizliyle

Aynı kirli kanı taşır

Kızılderili''nin uzattığı ele küstahça cevap veren general: 

''En iyi Kızılderili ölü kızılderilidir.''', 'İyi kızılderili Tosawi''ye... En iyi zenci ölü zencidir diyip Onu öldüren soluk benizliyle Aynı kirli kanı taşır Kızılderili''nin uzattığı ele...', ARRAY['Türk Edebiyatı','Şiir','Gök Tengri']::text[], 8.5, '{"poet":"Gök Tengri","poet_slug":"gok-tengri","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kirli-kanlilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savaş çubuğu', 'savas-cubugu-gok-tengri-luvhu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Doğayı ana belleyen

Avladığı hayvanı son zerresine kadar kullanıp; 

Hayvandan özür dileyen kızılderili

Barış çubuğundan sonra 

Savaş çubuğunu da öğrendi

Ne zaman ki Avroamerikalı yanı başında bitiverdi! ...', 'Doğayı ana belleyen Avladığı hayvanı son zerresine kadar kullanıp;  Hayvandan özür dileyen kızılderili Barış çubuğundan sonra  Savaş çubuğun...', ARRAY['Türk Edebiyatı','Şiir','Gök Tengri']::text[], 8.5, '{"poet":"Gök Tengri","poet_slug":"gok-tengri","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/savas-cubugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Olur', 'gun-olur-habip-ata-giresunlu-pzhck', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gün olur ömrümün biter baharı, 

     Sevgi badesini yudumlamadan.

     Gün olur rüzgarda yaprak misali, 

     Bir hayal engine koşar durmadan.

     Gün olur beklerken dönecek diye, 

     Aşina yüzleri düşte bulurum.

     Gün olur gözümde biriken yaşla, 

      Herkes gibi ben de toprak olurum.

                               (Ankara-Mamak 03.04.1968)', 'Gün olur ömrümün biter baharı,       Sevgi badesini yudumlamadan.      Gün olur rüzgarda yaprak misali,       Bir hayal engine koşar durmada...', ARRAY['Türk Edebiyatı','Şiir','Habip Ata Giresunlu']::text[], 8.5, '{"poet":"Habip Ata Giresunlu","poet_slug":"habip-ata-giresunlu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gun-olur-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geri Dönmemeliyim', 'geri-donmemeliyim-habip-ata-giresunlu-ynbwm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu gece

     Tüm anılar kırık dökük

     Tüm seviler meze yapılıyor kadehlere

      Kadehlerle oyuluyor gözleri gecenin, 

      Masalarda kızıl renkler, 

      Ümitsiz şarkılar raksediyor gök yüzünde.

      Ümitsis kalpler aşk arıyor

      Yaşamak, yaşatmak için

      Meyhane köşelerinde...

     

       Niçin susuyorsun, 

       Niçin bakıyorsun gözlerime öyle? 

       Hadi bir daha çek ellerini ellerimden, 

       Sıcaklığı yalnız güneşte hissetmeliyim, 

       Yalnız arzularda bulmalıyım  mutluluğu

       Sensiz...

       Seninle.

       Ve

       Yalnız ben bu gara

       Geri dönmemeliyim.

                               (Ankara-Mamak- 1968)', 'Bu gece      Tüm anılar kırık dökük      Tüm seviler meze yapılıyor kadehlere       Kadehlerle oyuluyor gözleri gecenin,        Masalarda kı...', ARRAY['Türk Edebiyatı','Şiir','Habip Ata Giresunlu']::text[], 8.5, '{"poet":"Habip Ata Giresunlu","poet_slug":"habip-ata-giresunlu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/geri-donmemeliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-sait-ferhat-ozmen-cknho', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Özlem aslında beş harf, 

Yazması da söylemesi kadar kısa, 

Oysa Özlemek zor, 

Yaşaması da, anlatması  da, 

Söylemesinden uzun.

Özlem aslında özlemenin, 

Acısız anlatımı, 

Acıdan kaçanın, korkanın, 

Kolay anlatımı özlem.

Ben onu o kadar kolay yaşamıyorum, 

Ben özlem çekmiyorum, 

Ben seni özlüyorum.

Ben seni en az özlediğim kadar seviyorum, 

Sevdiğim kadar özlüyorum.

Seni sevmek değil belki ama seni özlemek, 

Bana acı veriyor, 

Ve ben acıyı, 

Özleminle göğüslüyorum.', 'Özlem aslında beş harf,  Yazması da söylemesi kadar kısa,  Oysa Özlemek zor,  Yaşaması da, anlatması  da,  Söylemesinden uzun. Özlem aslında...', ARRAY['Türk Edebiyatı','Şiir','Sait Ferhat Özmen']::text[], 8.5, '{"poet":"Sait Ferhat Özmen","poet_slug":"sait-ferhat-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ozlem-89-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Risalesi', 'olum-risalesi-erdem-bayazit-8ms0z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Damla damla oluşuyor hayat

Ölüm kımıl kımıl

Duymak kolay

Anlatmak değil

Her an

Farkındayım

Az az öldüğümün

Bilincindeyim doğan ayın

Eriyen karın akan suyun

Ve usul usul tükenen zamanın

Tekrarlayıp duruyor saat

Vakit te mahluktur

Vakit te mahluktur

İşliyor kalbim

Eskiyor saçlarım

Ve gözlerimin en ince hücreleri

Okuyorum hayatı

Toprağın üstünden çok

Altındakilerle var olduğunu

Toprak

Ölüme aç

Ölüme muhtaç

Hayat

Ölüm muhakkak

Ve ölüm mutlak

Tek kapısıdır ölümsüzlüğün

Ölümle tanıştıktan sonra anladım

Sadece bir kimlik belgesi olduğunu yaşamanın

Kesitler

Mahlukta devinen

Gürül gürül bir ırmaktır ölüm

Babalar ölür

Dolaşır eli ölümün

Saçlarında anaların oğulların

Analar ölür

Kök salar hasret yüreklere

''Bir evlat pir olsa da''

O zaman anlar ancak neymiş öksüzlük

Oğullar ölür

Bir kafes olur ölüm

Ana kalbi bir kuştur

Azad kabul etmez

Sevgililer ölür

Bir hicret olur ölüm

Bir sıla

Mesela arkadaşlar

Arkadaşlıklar vardır okullarda

Bakarsın biri gelmez bir gün

Ve artık hiç gelmeyecektir

Simsiyah bir gölge düşmüştür adeta

Bahçeye koridorlara sınıflara

Bir fısıltı dolaşır dudaklarda

Kimi kirpikleri ıslak

Çökmüş bahçenin tenha bir yerine

Elinde bir çöp resmini çizer toprağa

Anıların

Kimileri öbek öbek toplanıp

Çaresizliği dile getirirler anlamsız sözcüklerle

-Nasıl olur daha dün beraberdik

-Salıncakta İki Kişi''yi izlemiştik daha dün nasıl olur

-Geçen pazar kırlarda dolaşmıştık

''''Göçmen kuşlar yerli kuşlardan daha mutlu olmalılar 

Hayatı dolu dolu yaşıyorlar'''' demişti unutamıyorum

Sonra bir mezarlıkta Bir çukurun başında

Bir kapının ağzında

Herkez susar

Konuşur ölüm

Ve sürer hayat.

Bazan bir tekerlek altında

Ansızın gelir ölüm

Apansız biter sınav

Bir elektrik kesilmesi gibi

Kesilir tulu emel

Bazan ölüm vardır

Ölümden önce gelir

Mesela bir hapishanede bir hücrede yaşanır

Sorular hep yanıtsız kalır orada

Sadece konuşan rüyalardır

Yahut hayaller suskun duvarlarda

Gözler kabul eder parmaklar kabul eder

Ama beyin hep umuttan yanadır

Bazan akan bir film şeridinin

Tek kare donan bir fotoğrafı gibidir

Ölüm

Karşıda bir manga asker

Gözler namluların karanlık ağızlarını görmez de

Takılıp kalır masmavi gökyüzünde

Asılıp kalmış bembeyaz bir buluta

Ölümden uzak ölümler vardır

Gazete ilanlarında rastlanılan

Dünyaya bağlılığın zavallı

Ve muannit

Bir belgesidir

Daha çok kalanlara ait.

Bir de bir örümcek ağının ortasına düşmüş

Bir sineğin titrek bacaklarında seyretmiştim ölümü

Ölümler vardır: 

Can kuş gibi uçar gider

Bir martının süzülüp

Kaybolması gibi maviliklerde

Bir Portre

Engin sakin berrak bir denize 

Uçsuz bir kumsaldan ağır ağır

Nasıl yürürse insan

Sokrates öyle yürüdü ölüme

Tilmizleri ağlaşırken

O vasiyet ediyordu: 

-Asklepyos''a bir horoz borçluyuz

Unutmayınız.

Ne tuhafsınız dostlar

Güçsüz kadınlar gibi ağlaşmak niye

Yükselmek varken ölümsüzlüğe

İnancına sahip olmak

İnsan olmanın şartı

Kölelikler içinde en onulmaz kölelik

Hayatın ölümcül yanına

Takılıp kalmak değil mi? 

İlkin ayaklarında duydu Sokrates

Zehirin soğukluğunu

Ve yavaş yavaş ölüm

Yükseldi göğsüne çenesine

Dudaklarında donan son bir tebessümle

Bir işaret taşı da böylece

Sokrates dikmiş oldu ölüme

Ölümün Sesi

Ölümden bir işaret var her şeyde

Ölümün sesini duyuyorum şarkılarda türkülerde: 

-Kışlanın önünde redif sesi var

Namluların ucunda ölümün sesi! 

-Bir ay doğdu geceden oy oy

Karanlığın ağzında ölümün sesi! 

-Erzurum dağları kan ile boran

Vadilerin koynunda ölümün sesi

-Ezo gelin durmuş bakar yollara

Umudun ardında ölümün sesi! 

-Bir ihtimal daha var

Umuddan da öte ölümün sesi! 

Kendi Ölümüme Ait Bir Deneme

Bir gün öleceğim biliyorum

Bunu her an ölür gibi biliyorum

Anamın yüreğinde bir kor

Ölene dek sönmeyecek bir ateş

Kımıldanıp duracak hep

Karım bomboş bulacak dünyayı

-N''olurdu birlikte ölseydik, deyip duracak

Oysa insan yalnız ölür

Ama o olmayacak dualarla teselli arayacak

Kızlarımın gırtlaklarında bir düğüm

Bir süre kaçacaklar insanlardan

Boşluğa düşmüş gibi bir duygu içlerinde

Sonunda onlar da kabullenecekler öylesine

Ölümüme en çabuk dostlarım alışacaklar

-Yaşayıp gidiyorduk yahu

Ne vardı acele edecek! 

Diyecekler

Biliyorum yaklaşıyoruz her an

Biliyorum oruçlu doğar insan

Ölümün iftar sofrasına

Son Söz

Ve zaman döne döne

Gelmişti başlangıç noktasına

İlk yaratılış düğümüne

Mahlukatın var olduğu

Yüzüsuyu hürmetine

Evrenin Efendisinin

Kavuşmak vakti gelmişti sevgilisine.

Hayatın menbaı

Merhametin son durağı

Madeni, muhabbet ocağının

Ateşler içindeydi

Yatağında.

İltica etmişti sanki Kainat

Kutsal tenine

Hayata şafak olan alnında

Ter taneleri

Her biri insanlık çilesinden

Bir haberdi sanki

Bir an oldu

Aralandı gözleri

Sonsuzu kuşatan bakışları

Süzdü ciğerparesi Fatıma''yı

Süzdü tek tek çevresindeki

Can dostlarını

Kıpırdadı dudakları, dedi: 

-Ebu Bekir kıldırsın namazı

Sonra daldı daldı uyandı

Son defa aralandı

Bakışları

Yöneldi bir noktaya

Karar kıldı bir noktada

Ve dedi: 

-Merhaba ey refik-i ala! 

Olacak oldu

Akıllar kamaştı

Kalpler tutuştu

Feryat ve figan gökleri tuttu

Çekti kılıcını Faruk olan

Sıçradı orta yere: 

-Kim derse ''''O öldü'''', öldürürüm! 

Ayrılık ateşinden

Ateşin şiddetinden

Sanki bendler çözülmüş

Felekler çökmüştü

Şuur tutuşmuş

Akıl iflas etmişti.

Sonra Sıddıyk olan

Yetişti geldi

Baktı baktı yatağında hareketsiz yatan sevgiliye

Mağarada arkadaşına Hicrette yoldaşına

Sonra baktı çevresine

Mahşerden önce mahşer hali yaşayan

Ashabına

Aline

Ebu Bekir dedi: 

-Ey nas, susun! 

Kim ki Resulullaha tapmaktadır

Bilsin ki Resul ölmüştür

Kim ki Allaha tapmaktadır

Bilsin ki Allah ölmez

Hayy ve Layemuttur

Ey nas, susun! 

''''İnna Lillah ve inna ileyhi raciun''''

Sonra eğildi sevgilinin yüzüne

Sürdü bulutlanmış gözlerini

O güzellikler ülkesine

Baktı baktı ve dedi: 

-Hayatında güzeldin

Ölümünde güzelsin

Öldün

Bir daha ölmeyeceksin', 'Damla damla oluşuyor hayat Ölüm kımıl kımıl Duymak kolay Anlatmak değil Her an Farkındayım Az az öldüğümün Bilincindeyim doğan ayın Eriyen k...', ARRAY['Türk Edebiyatı','Şiir','Erdem Bayazıt']::text[], 8.5, '{"poet":"Erdem Bayazıt","poet_slug":"erdem-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":230,"source_url":"https://www.antoloji.com/olum-risalesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Miniciğim', 'minicigim-ugur-oguz-sahin-65vbz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne kadar güzel bir meleksin

Ne kadar tatlı bir bebeksin

Yumuk yumuk gözlerin o tatlı burnun

Minicik dudakların o yenesi ellerin

Sensin benim bebek yüzlü meleğim

Seni seyretmeye doymuyor gözlerim

Dalıp gidiyorum seninle yarınlara

İşte mutluluk bu diyorum hadi yaşasana

O sihirli kelimeyi duymak istiyorum

O minnacık dudakların arasından

Bana baba diyeceğin günü bekliyorum

O gün ömrümün en mutlu günü olacak biliyorum', 'Ne kadar güzel bir meleksin Ne kadar tatlı bir bebeksin Yumuk yumuk gözlerin o tatlı burnun Minicik dudakların o yenesi ellerin Sensin benim...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/minicigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tarih Yorumu', 'bir-tarih-yorumu-ozdemir-i-nce-994uf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Başkaları karar veriyor senin yerine

seni bildiğini tanıdığını sananlar

seni değil sadece kendilerini savunanlar

ama ne su içmişler seninle, ne yola gitmişler, 

o, diyorlar, şunu yapar bunu yapmaz

o, diyorlar şunu sever bunu sevmez

o, diyorlar, kışın hiç güneye gitmez

sıcak bölgelere göçmen kuşlar gibi; 

senin ceviz ve çınara hasret göçmenliğini, 

senin eller yakan hasretini anlayamayanlar.', 'Başkaları karar veriyor senin yerine seni bildiğini tanıdığını sananlar seni değil sadece kendilerini savunanlar ama ne su içmişler seninle,...', ARRAY['Türk Edebiyatı','Şiir','Özdemir İnce']::text[], 8.5, '{"poet":"Özdemir İnce","poet_slug":"ozdemir-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bir-tarih-yorumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'On Sekiz Yaştaki Gibi', 'on-sekiz-yastaki-gibi-ugur-oguz-sahin-h4sgl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben seni sevdim

Tertemiz duygularımla

Sadece seni sevdi yüreğim

Yalanını dolanını değil

Ben seni sevdim

Yağan yağmurla

Söken şafaklarda

Sevgimi satasın diye değil

Ben seni sevdim

Gerçekten sevdim seni

Yenemedim içimdeki korkuyu

Demek ki güven dediğin boşaymış

Sevdim seni on sekiz yaştaki gibi

Güven dedin güven vermedin

Benimleyken sattın sevgimi

Bir de yüzüme bakarak yalan söyledin

Söz dedim kendime

Artık seni sevmeye tövbe

Gömdüm içime gömdüm seni

Artık kendi kendimle hesaptayım', 'Ben seni sevdim Tertemiz duygularımla Sadece seni sevdi yüreğim Yalanını dolanını değil Ben seni sevdim Yağan yağmurla Söken şafaklarda Sevg...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/on-sekiz-yastaki-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yagmur', 'yagmur-senay-erdogan-b9wk7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Neden sen böyle serin serin yağıyorsun 

Oysaki sen 

Güneşle birlikte 

Daha güzel oluyorsun', 'Neden sen böyle serin serin yağıyorsun  Oysaki sen  Güneşle birlikte  Daha güzel oluyorsun...', ARRAY['Türk Edebiyatı','Şiir','Şenay Erdoğan']::text[], 8.5, '{"poet":"Şenay Erdoğan","poet_slug":"senay-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yagmur-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyuncaktan', 'oyuncaktan-deniz-aydin-p5mha', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Küçücük ağzıyla

Büyük büyük esneyen bu çocuk

Ben diyeyim üç yaşında

Sen de üç buçuk

Elinde tabanca oyuncaktan

Küçücük gözleriyle

Ikarusun penceresinden

Öylece bakan bu çocuk

Ben diyeyim üç yaşında

Sen de üç buçuk

Namlusunun ucunda

Kendince hedefi oyuncaktan

Küçücük parmaklarıyla

Seni beni işaret eden bu çocuk                                             Ben diyeyim üç yaşında

Sen de üç buçuk

Eli tetikte oyuncaktan

Küçücük düşüncesiyle

Kocaman hayallere sahip bu çocuk

Ben diyeyim üç yaşında

Sen de üç buçuk

Öldürdü beni oyuncaktan.', 'Küçücük ağzıyla Büyük büyük esneyen bu çocuk Ben diyeyim üç yaşında Sen de üç buçuk Elinde tabanca oyuncaktan Küçücük gözleriyle Ikarusun pe...', ARRAY['Türk Edebiyatı','Şiir','Deniz Aydın']::text[], 8.5, '{"poet":"Deniz Aydın","poet_slug":"deniz-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/oyuncaktan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak Lambaları', 'sokak-lambalari-cesare-pavese-szr5b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sokak lambalarının sessiz ışıkları süslüyor

geceyi tepeleri ve caddeleri

Yüksek yapılar arasında bitkin günün

uzayıp giden sancılanan yalnızlığı

yeniden yanıyor tüm kanımda

gözlerimde gökyüzüne dek yükselerek.

Başdöndürücü yolların beyaz ışıkları evrenin ortasında

Yollarda her yanan mavimsi tozlar açılıyor

bana doğru. Susuyor bitkin anılar bir an için.

Ve gökyüzü kararıp yitiyor gözden.

Yarın güneşin isi altında

yeniden yanlızlığa sarılacak yaşam', 'Sokak lambalarının sessiz ışıkları süslüyor geceyi tepeleri ve caddeleri Yüksek yapılar arasında bitkin günün uzayıp giden sancılanan yalnız...', ARRAY['Türk Edebiyatı','Şiir','Cesare Pavese']::text[], 8.5, '{"poet":"Cesare Pavese","poet_slug":"cesare-pavese","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sokak-lambalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kokun', 'kokun-seyit-ahmet-duzen-83q7h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kentin bütün ışıkları söndüğünde

Düşünmeden sokağını tanıyabilmek

Hala o evde oturduğuna

Ümüt etmek, inanmaktır.

Aşk

Cesaretimi zorlayıp

Senin tırmandığın basamakları

Tırmanıp

Kapı tokmağında parmak izlerimi

Bırakıp kaçmaktır bazen...

Bir kokun vardır merdiven boşluğunda

Birde kimsesiz korkak yureğim

Kokunu nefes nefes içime çekerim

Yüreğimin en efkarlı nefesidir bu

Yüregimin en korkak....

                        ‘Unutma sevgilim herkes yüregi kadar korkar’’', 'Kentin bütün ışıkları söndüğünde Düşünmeden sokağını tanıyabilmek Hala o evde oturduğuna Ümüt etmek, inanmaktır. Aşk Cesaretimi zorlayıp Sen...', ARRAY['Türk Edebiyatı','Şiir','Seyit Ahmet Düzen']::text[], 8.5, '{"poet":"Seyit Ahmet Düzen","poet_slug":"seyit-ahmet-duzen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kokun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlığa', 'karanliga-cesare-pavese-mfvg6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karanlığa ve diri serinliğe gömülü alandaki bahçe.

Gecenin karanlığında devliğini yitiriyor

yüzlerinin arasından ışıklar sızan evler.

Geçmiş göklerin derinliğinde, yıldızlar arasında

ürkünç çöl. Büyük ve parıltılı ateş sağırlaşıyor

ulaşarak bu karanlığa. Sessizliktir burası, 

bir gömütlüğün koca kımıltısızlığı

Gürültüler ve ışıklar

ağaçların ötesindeki uzaklığa ulaşıyor.

Capcanlı ışıklar fışkırıyor karanlığın içinden, 

uluyor kendinden geçmiş sevinçli sesler

o üzünçlü ayrılışta.

Boğuk ulaşıyorlar dipsiz karanlıkta ölmeye

yine delicesine yaşama aşkıyla

solgun intiharlar gibi.

Dinlemek geçmiş tutkuları, 

yürekte ve gecede tırmanışlarını

toprağın ıpıslakkokusu üzerinde.

İsteğintanınmadık bir bitkisi

sessizliğin ve karanlığın göğünde kapalı.

Karanlıkta ateşin göverişi

ağaçların arasında kanayan o kızıl ışık gibi', 'Karanlığa ve diri serinliğe gömülü alandaki bahçe. Gecenin karanlığında devliğini yitiriyor yüzlerinin arasından ışıklar sızan evler. Geçmiş...', ARRAY['Türk Edebiyatı','Şiir','Cesare Pavese']::text[], 8.5, '{"poet":"Cesare Pavese","poet_slug":"cesare-pavese","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/karanliga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güney Denizleri', 'guney-denizleri-cesare-pavese-a1d1l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sessizce yürüyoruz tepenin yamacında bir akşam.

Alacakaranlığın yoğunlaşan loşluğunda amcamın oğlu

suskun, yanık yüzlü, dingin davranışlı, beyaz giysili

bir dev sanki. Suskunluk bizim erdemimiz.

Atalarımızdan biri iyice yanlız kalmış olmalı

- aptalların arasında bir büyük adam ya da

zavallı bir deli - bize bunca sessizliği öğretebilmek için.

Amcamın oğlu konuştu bu akşam. Kendisi ile çıkıp 

çıkmayacağımı sordu. Torinonun uzak fenerinin

yanması seçiliyor duru gecelerde tepeden.

Sen ki Torinoda oturuyorsun dedi bana

''.....Ama haklısın. Yaşam doğduğun yerden

uzakta sürüp geçer. Yayarlanıp tadını çıkardıktan

sonra benim gibi kırk yaşında döndüğünde

herşeyi yepyeni bulursun. Langhe ise yitip gitmiyor''

Bütün bunları bana İtalyanca söylemiyordu. Ağır

konuştuğu yerel ağız şu tepenin taşları gibi kupkuru.

Yirmi yılın başka dilleri ve denizleri de

etkileyememiş onu. Yürüyor, yorgun köylülerde gördüğüm

yoğun bakışlarıyla yokuşa doğru.', 'Sessizce yürüyoruz tepenin yamacında bir akşam. Alacakaranlığın yoğunlaşan loşluğunda amcamın oğlu suskun, yanık yüzlü, dingin davranışlı, b...', ARRAY['Türk Edebiyatı','Şiir','Cesare Pavese']::text[], 8.5, '{"poet":"Cesare Pavese","poet_slug":"cesare-pavese","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/guney-denizleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deola''nın Düşleri', 'deola-nin-dusleri-cesare-pavese-p6dbr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kahvede oturarak geçiriyor sabahı Deola, 

kimse bakmıyor ona. Koşuşuyor kentte herkes

şimdi, yeni günün diri güneşinde. Kimseyi aramıyor

Deola da, dinginlikle içiyor sigarasını, sabahı soluyup.

Pansiyonda kaldığı süre boyunca uyumak zorundaydı

şimdilerde, gücünü toplayabilmek için. Yatağın

üzerindeki hasırı kirletirdi kaba ayakkabılarıyla

asker ve işçiler, yorn argındı müşterilerinden.

Ama bambaşkadır güneş: daha az yorularak

daha iyi bir iş yapabilir. Dünkü adam erkenden

uyandırıp öptü onu.(Sevgilim, elimde olsa

seninle Torinoda kalırım)  kendisi ile birlikte

istasyona götürdü ona iyi yolculuklar diyip

uğurlaması için

                            Bu kez şaşkın ama diri, 

hoşuna gidiyor özgür olmak Deola''nın, çöreğini

yiyip sütünü içmek  Yarı bir hanımefendibu sabah, 

gelip gidene baksa da sadece sıkılmamak için.

Bu saatlerde pansiyonda kapalı yer kokusu

içinde uyunur - Patroniçe gezip dolaşıyordur-

orada kalmak budala eder insanı. Akşamları

lokalleri dolaşmak için güzel görünmek gerekir.

Pansiyonda otuz yaşında kalan azıcık güzelliği de

yitip gider insanın.

Aynaya yan dönmüş oturuyor Deola

camın diri serinliğinde kendisiyle bakışarak.', 'Kahvede oturarak geçiriyor sabahı Deola,  kimse bakmıyor ona. Koşuşuyor kentte herkes şimdi, yeni günün diri güneşinde. Kimseyi aramıyor Deo...', ARRAY['Türk Edebiyatı','Şiir','Cesare Pavese']::text[], 8.5, '{"poet":"Cesare Pavese","poet_slug":"cesare-pavese","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/deola-nin-dusleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşün Sonu', 'dusun-sonu-cesare-pavese-jam38', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yeniden başlayamaz artık bu gövde.

Gözlerine dokunulduğunda, bir yığın toprağın

canlılığını duyar biri. Tan ağırtısında da 

kendisini susturamıyan topraktır o.

Olü bir gövdedir, o bir çok uyanıştan

kalan ama.

Hergün yaşama başlayacak gücümüz yok

- Toprağın önünde, suskun bir gök altında-

bir yeniden uyanışı bekliyerek. Şaşırtıyor biri

bunca yoruculuğuna tan ağırtısının. Bir iş

yerine getiriliyor bu yeniden uyanışlar içinde.

Ama sadece ilerki bir işe heyecan yüklemek

ve yoprağı bir kez uyandırmak için yaşıyoruz.

Ve kimi kez oraya erişip, sonra bizle birlikte

suskunluğa dönüyor.

Kımıldanmazdı yüz hafifçe dokunsaydı el

- yaşayan el duyuyor dokunulan yaşamı -

Bu soğut, tan ağartısında donan toprağın

soğuğu değilse gerçekten belkide yeniden uyanıştır.

ve tan ağartısında susan varlıklar

sözcükler söylerler yine. Ama elim titriyor.

Ve tüm varlıklar kımıltısız ele benziyor.

                            Bir zamanlar kuru bir acı

ve ışığın kasılmasıydı tan ağırtısında uyanmak.

Ama yine de bir özgürlüğe kavuşmaydı.

Toprağın verimsiz sözcüğü kısa bir an sevinçliydi.

Ve yine orada dönmekti ölüm. Şimdi toprağa

dönmeyen gövde bir çok yeniden uyanışı bekliyor.

Ondan sözetmiyor kaskatı dudaklar da.', 'Yeniden başlayamaz artık bu gövde. Gözlerine dokunulduğunda, bir yığın toprağın canlılığını duyar biri. Tan ağırtısında da  kendisini sustur...', ARRAY['Türk Edebiyatı','Şiir','Cesare Pavese']::text[], 8.5, '{"poet":"Cesare Pavese","poet_slug":"cesare-pavese","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/dusun-sonu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığa Düşkünlük', 'yalnizliga-duskunluk-cesare-pavese-t95al', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Akşam yemeği yiyorum biraz, aydınlık pencerede.

Oda kararmış gökyüzü görünüyor. Dışarı çıkınca

geniş kırlığa götürürdingin yollar az sonra.

Göğe bakıyor ve yiyorum - kimbilir şimdi

kaç kadın yemek yiyordur - gövdem dingin; 

sersemleştiriyor gövdemi iş ve her kadın.

Dışarıda akşam yemeğinden sonra, yıldızlar gelip

geniş ovanın toprağına dokuncaklar. Yıldızlar

canlı, değersiz ama bu bir başına yediğim kirazlar.

Göğü görüyorum. Biliyorum ama paslı çatıların

arasında parıldayan ışıkları ve altında yapılan

gürültüleri. Koca bir yudumla bitkilerin ve ırmakların

tadını alıyor kendini her şeyden ayrı duyan gövdem.

Biraz sessizlik yetiyor, her varlık kendi gerçek

yerinde duruyor, gövdemin duruşu gibi.

Sessizliğin uğultusunu dağıtmaksızın benimseyen

duygularımın önünde her varlık yalıtılmış.

Damarlardan geçen kanımı bildiğim gibi

her varlığı karanlıkta bilebilirim.

Tüm varlıkların akşam yemeği, koca bir suyun

otların arasında aktığı yerdir ova.

Kımıltısız yaşıyor her bitki ve her taş.

Bu ova üzerinde yaşayan her varlığın damarlarını, 

beni beslyan besinleri dinliyorum.', 'Akşam yemeği yiyorum biraz, aydınlık pencerede. Oda kararmış gökyüzü görünüyor. Dışarı çıkınca geniş kırlığa götürürdingin yollar az sonra. ...', ARRAY['Türk Edebiyatı','Şiir','Cesare Pavese']::text[], 8.5, '{"poet":"Cesare Pavese","poet_slug":"cesare-pavese","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yalnizliga-duskunluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Tatları', 'gece-tatlari-cesare-pavese-igtgc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geceyi duymaya duyuyoruz biz de

Çırılçıplak anında yelin

Kokuların döküldüğü, yelin dondurduğu yollarda

Burun deliklerimiz kaldırıyoruz / Ötelerde slınan ışıklara.

Karanlıkta bekleyen bir ev var hapimizi

Döndüğümüzde düşlerine uzanmış bir kadının

Sıcak kokular içinde, karanlık bir odada

Uyurken esen yelden habersiz, 

İçimizde mırıldayan kan gibi

Ilık tenini soluduğunu', 'Geceyi duymaya duyuyoruz biz de Çırılçıplak anında yelin Kokuların döküldüğü, yelin dondurduğu yollarda Burun deliklerimiz kaldırıyoruz / Öt...', ARRAY['Türk Edebiyatı','Şiir','Cesare Pavese']::text[], 8.5, '{"poet":"Cesare Pavese","poet_slug":"cesare-pavese","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gece-tatlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaldırım Çiçeği', 'kaldirim-cicegi-cesare-pavese-utqu1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nasılsa kaldırımda bitmiş bir çiçeğim, 

Nasılsa kaldırımda bitmiş bir çiçek o

Tozları, sesten, ilgisizlikten bunaldığım bir gün 

Tuttum aşık oluverdim

Ben kaldırımın bir ucunda, 

Tâ öteki ucunda o', 'Nasılsa kaldırımda bitmiş bir çiçeğim,  Nasılsa kaldırımda bitmiş bir çiçek o Tozları, sesten, ilgisizlikten bunaldığım bir gün  Tuttum aşık...', ARRAY['Türk Edebiyatı','Şiir','Cesare Pavese']::text[], 8.5, '{"poet":"Cesare Pavese","poet_slug":"cesare-pavese","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kaldirim-cicegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soğukluk', 'sogukluk-cesare-pavese-pe47z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ateşli bir sevi gibi yeşeriverdi acılanarak

ateşini seyre dalan bir kin. Bir yüz, 

bir ten sevişmişcesine.

Öluverdi teni çinlayan sesleri dünyanın.

Bir titreyiş kapladı varlıkları. Tümüyle

bir sese asılı kaldı yaşam.

Acı bir esrime içinde geçiyor günler

yüzümü soldurarak geri gelen sesin

üzünçlü okşayışında. Yeniden çınlayan

ve bizim için bir kez daha acımasız

anıda tatsız değil bu ses.

Ten titremiyor ama. Onu sadece bir

sevi tutuşturabilirve bu kin arar.

Tümüyle varlıklar, sesler ve dünyanın

teni yerinde tutmuyor o gövdenin ve gözlerin

yanıp tutuşan okşayışının. Kendini yıkan

acılı esrimede her gün yeniden bir bakış

ve kırık bir sözcük buluyor bu kin.

Ve yakalıyor orada, doyumsuzca, 

bir seviymişcesine', 'Ateşli bir sevi gibi yeşeriverdi acılanarak ateşini seyre dalan bir kin. Bir yüz,  bir ten sevişmişcesine. Öluverdi teni çinlayan sesleri dü...', ARRAY['Türk Edebiyatı','Şiir','Cesare Pavese']::text[], 8.5, '{"poet":"Cesare Pavese","poet_slug":"cesare-pavese","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sogukluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyuyan Dost', 'uyuyan-dost-cesare-pavese-71wxm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uyuyan dosta ne diyeceğiz bu gece? 

O tüyler ürpertici acının en dirençsiz

sözcüğü geliyor dudaklarımıza.

Uysalca konuşacağız onun sözetmeyen

yararsız dudaklarına bakıp

Her akşam aldırışsız ve capcanlı beliren

o eski ağrının yüzü olacak gece.

Acı çekecek bir can gibi, karanlıkta suskun

o eski sessizlik. Uysalca soluyan

geceye konuşacağız.

Varlıkları ölü sessizliğe karşı belirleyerek

apansız gelen tan ağırtısının tedirginliğinde

ve varlıkların ötesinde karanlıkta

anların ardınca damladığını duyacağız.

Yararsız ışık ortaya çıkaracak günün

sancılanan yüzünü. Susacak anlar ve

varlıklar konuşacak uysalca.', 'Uyuyan dosta ne diyeceğiz bu gece?  O tüyler ürpertici acının en dirençsiz sözcüğü geliyor dudaklarımıza. Uysalca konuşacağız onun sözetmeye...', ARRAY['Türk Edebiyatı','Şiir','Cesare Pavese']::text[], 8.5, '{"poet":"Cesare Pavese","poet_slug":"cesare-pavese","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/uyuyan-dost-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UZAK ADA/M -II-', 'uzak-ada-m-ii-faize-ozdemirciler-c2zps', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '-II-

                                                           

                                            Direndiler ve abarttılar

                                    bizim dünyamızdan değildi onlar

                                                           Paul Eluard

Direnmedik! abarttık! 

rengimiz belli olmasın diye 

salkımsöğüt''ü  kağıtla kapladık 

otuz kişilik odalarda 

gözümün kaydığı yer nere''ydi 

hangi tarih''e, hangi şiir''e gebe? 

sen baskıya bile direnmedin 

aşka direndiğin kadar 

ve kanıt kalmasın diye bugüne 

fazla da  konuşmadın sevda üstüne

aşk karanfil kadar anlamdışıydı! 

Kırılırdı bakışların gözlerin gülünce

fizik kuralları örterdi sözlerini

keskin bıçağa dönüşürdü dilinde aşk

gidişin şarttı, üstelik yağmur yağıyordu

ıslanmak çekmişti canın, kimbilir! 

politika konuşurken bizi yakalayacak bir kedi

doğrulayabilirdi sevdamızı ve yoktu öyle bir kedi!', '-II-                                                                                                         Direndiler ve abarttılar       ...', ARRAY['Türk Edebiyatı','Şiir','Faize Özdemirciler']::text[], 8.5, '{"poet":"Faize Özdemirciler","poet_slug":"faize-ozdemirciler","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/uzak-ada-m-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UZAK ADA/M -III-', 'uzak-ada-m-iii-faize-ozdemirciler-jl8kg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '-III-

Minerva kuşu uğursuzluğuna yanar

çocukluğumun bisikletten düştüğü yollarda

kıtasıyla anlaşamayan haritadır saçlarım

bir yarım ada, bir yarı(m)  yarim ada

Bir horoz öter aziz sergios''un* köyünde

uyanır istanbul''un sabahları

bir çilek çıtırtısı, bir diş izi, bir dudak çınlaması

rüya tabirleri kitabı''na hiç bakmadım

annem bilir o kitaplardaki yorumları

Ak saçlı ada/m umutlarını yüklenir çıkar balkona

aşılanmaya hazır fidancıktır manşetler

kuşluğa veda ederken silahtan arınır coğrafya

sonrası; tombul bir çocuğun aşı filizini koparması

bir tokat patlaması...bir çocuk ağlaması...

bir pişmanlık...bin pişmanlık...bir kucaklaşma! 

       

Büyük düşler gören babam

sardunya koklar gibi bakmasını öğretti bana

babamın gözlerinden kopardığım

bir adacıktan başka birşey değildir sevda! 

      

* 1974''ten sonra Aytotoroluların yerleştirildiği Aysergi köyü.', '-III- Minerva kuşu uğursuzluğuna yanar çocukluğumun bisikletten düştüğü yollarda kıtasıyla anlaşamayan haritadır saçlarım bir yarım ada, bir...', ARRAY['Türk Edebiyatı','Şiir','Faize Özdemirciler']::text[], 8.5, '{"poet":"Faize Özdemirciler","poet_slug":"faize-ozdemirciler","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/uzak-ada-m-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklemek -I-', 'beklemek-i-faize-ozdemirciler-y0azu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '-I-

Kar beklentisi dağıttı gecenin seslerini

           hüzzam bozuldu! 

natürel sol, ipsiz sapsız  ''sol''a bıraktı yerini

sol anahtarı''yla açılan kapıların ardında 

üç divane göç, üç pasaport; ödünç...aslanlı

şarkılarda yer yok 

bekleyen pencerelerin makamına

gözleriyle ağlardı annem 

ve hiçbir nota yok gözsesini anlatmaya

Niyet var ama dönmek yok

''buralarda hayat kalmadı'' dediler ve gittiler

saat yok, zaman yok bu uzaklığı anlatmaya

kırışık fotoğraflardan başka kanıt yok 

hüzzam''ın mutluluğuna

(Beklemek, düş aralarındaki kavşaktan 

eski köy''e* sapmak, hiç varamamaktır!)



* Doğduğum ve on yaşımdan sonra hiç göremediğim yer.', '-I- Kar beklentisi dağıttı gecenin seslerini            hüzzam bozuldu!  natürel sol, ipsiz sapsız  ''sol''a bıraktı yerini sol anahtarı''yla a...', ARRAY['Türk Edebiyatı','Şiir','Faize Özdemirciler']::text[], 8.5, '{"poet":"Faize Özdemirciler","poet_slug":"faize-ozdemirciler","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/beklemek-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklemek-II-', 'beklemek-ii-faize-ozdemirciler-5oms6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '-II-

Kar beklentisi soğuttu gecenin ellerini

hüzzam bozulunca sazlar durur mu...

kendi kendimle sohbetlerim olmasa

kime anlatırdım içimdeki martıcığın

kocaman kanatlarını

ki o kanatlar birer yolculukturlar

birer ''alıp başını gitme'' dirler aslında

bavulyüreğim kendini sığmaz oldu

her an gidecekmiş gibi duruşum bundan

mumu ateşe tercih ettin! sen ve ben başkalarıyız 

hep yanacakmış gibi duruşum bundan

(Bu sevdanın altına imzanı atamasan da

seni beklemek özgürlüktür!)', '-II- Kar beklentisi soğuttu gecenin ellerini hüzzam bozulunca sazlar durur mu... kendi kendimle sohbetlerim olmasa kime anlatırdım içimdeki ...', ARRAY['Türk Edebiyatı','Şiir','Faize Özdemirciler']::text[], 8.5, '{"poet":"Faize Özdemirciler","poet_slug":"faize-ozdemirciler","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/beklemek-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklemek-III-', 'beklemek-iii-faize-ozdemirciler-300e8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kar beklentisi soğuttu gecenin rüzgarını, hadi uç! 

ütopyaları tüketmeyecek kadar çirkindir yaşam

kız kulesi''ne sarıl, salamis''teki sütunlara, kime ne! 

güvercin cesetleri biriktiren milli şiir''e inat, sen uç! 

gelmiş geçmiş ne varsa, pütür pütür olsun poyrazla

devletsiz bir şiir yazdım, at imzamı altına

senin de italikti yazın mektuplarından 

anımsadığım  kadarıyla

 -o mektuplar ki, yaktığım günden beri

bir devrimcinin işkencede çözülen dili

nasıl acıtırsa yüreğini, öyle acı verirler bana-', 'Kar beklentisi soğuttu gecenin rüzgarını, hadi uç!  ütopyaları tüketmeyecek kadar çirkindir yaşam kız kulesi''ne sarıl, salamis''teki sütunlar...', ARRAY['Türk Edebiyatı','Şiir','Faize Özdemirciler']::text[], 8.5, '{"poet":"Faize Özdemirciler","poet_slug":"faize-ozdemirciler","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/beklemek-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklemek-IV-', 'beklemek-iv-faize-ozdemirciler-x4r11', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '-IV-

Kar beklentisi soğuttu bekleyişlerimi

şehir bozuldu...köy bozuldu...

ikisi ortası bir köyşehir düştü payıma

tokluğumu sakladım da oturdum iftar sofralarına

dualar boyunca  erguvanları kokladım

yaseminler dizdim çam iğnelerine

endülüs desenli şalımı doladım boynuma

ölü ozan sevicileri yalan söylüyordu

adalı şairler aradım tarihin kuytularında...

                       yoktu! 

bilmiyorum...bilemiyorum...(nasıl bilebilirim)

hilmi bey''ler, yahya bey''ler ve diğerleri

ortak olurlar mı günahlarıma? 

           (Seni beklemek istanbul demektir

                gel gör ki, biz başkalarıyız

               ve bize ait bir şehir değil bu!)', '-IV- Kar beklentisi soğuttu bekleyişlerimi şehir bozuldu...köy bozuldu... ikisi ortası bir köyşehir düştü payıma tokluğumu sakladım da oturd...', ARRAY['Türk Edebiyatı','Şiir','Faize Özdemirciler']::text[], 8.5, '{"poet":"Faize Özdemirciler","poet_slug":"faize-ozdemirciler","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/beklemek-iv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızma İşte Şairim', 'kizma-i-ste-sairim-hasan-yasar-u4a6c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sen 

sevgilimsin

         değerlim

                  biriciğim

şiir ise metresim

ara sıra 

      seni aldatıp 

    koynuna girdiğim.

bursa da 

            bi başka yarim

            yaşama sevincim 

                          cennetim.

bursa 

      sakın duymasın 

bi yarim de ege’de

                    üzümünü 

         zeytinini 

      ayrı severim

kızma işte

           şairim

duramaz edemez 

     gönül gönül gezerim...', 'sen  sevgilimsin          değerlim                   biriciğim şiir ise metresim ara sıra        seni aldatıp      koynuna girdiğim. bursa d...', ARRAY['Türk Edebiyatı','Şiir','Hasan Yaşar']::text[], 8.5, '{"poet":"Hasan Yaşar","poet_slug":"hasan-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kizma-iste-sairim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahpusta Zaman', 'mahpusta-zaman-hasan-yasar-3kyqc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'takar koluma 

          bir köylü güzelini

birgün 

        altıparmak’tan çekirge’ye

birgün 

        alsancak’tan montrö’ye 

 yürürüm.

duramam 

edemem 

alır kalbimi avucuma

maçka’dan taksim’e 

oradan da taa istinye’ye

                                     götürürüm...

yeni yetme 

              bir ege kızıyla

döndüğüm yer 

                   hep kadıköy’dür.

bana 

     öyle 

          deliymişim gibi 

                                 bakma! 

tutkulu 

bir tutukluyum 

ve 

bilirim 

böyle diner 

           kalp ağrısı 

ve 

mahpusta zaman 

ancak

                     böyle öldürülür...', 'takar koluma            bir köylü güzelini birgün          altıparmak’tan çekirge’ye birgün          alsancak’tan montrö’ye   yürürüm. duram...', ARRAY['Türk Edebiyatı','Şiir','Hasan Yaşar']::text[], 8.5, '{"poet":"Hasan Yaşar","poet_slug":"hasan-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/mahpusta-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürek Evimin Sahibi', 'yurek-evimin-sahibi-murat-oz-251fy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Selam olsun! 

Selam olsun zifiri karanlığımdan 

nur aydınlığıma, , 

bakire gecelerimin sessiz ve yağmalanmamış 

hırçın ama bir o kadar garip çocuğuna 

Selam olsun! ! ! 

......... 

Doğum kadar masum ama ölüm kadar 

kaçınılmaz olan vuslatıma Selam olsun, 

gönül sahibime AŞK efendime, 

varlığıyla en renkli bahçelerime güneş olan 

yokluğuyla bir hançer yarası açan 

yakan kavuran... 

''''derin yanlızlık denizimin'''' huzur girdabına 

sıcak yuvam tadım tuzuma 

Selam olsun! ! .. Selam olsunnn........ 

...................... 

Neydin sen 

bir düşmü? içimi yakan 

bir gülüşmü? ruhumu candan, canı canandan ayıran 

Neydin sen? 

bazen berrakmı berrak bir gözyaşı 

bazen derinmi derin bir gayya 

bir heyula, , 

hiç uyanamayan gönlümden 

aldın savurdun kuşlarımı yürek evimden 

haydi söyle artıkkkk! 

Neydin Sen? 

Bir şarkı dilimde yazanı yok söyleyeni yok 

bir ömür yolu dizilmiş notaları 

sıra sıra... 

her nağme hüzün ve ağıt 

her türlü kirden arınmış 

sırat köprüsü misali ince.. hayallerle sarılmış 

sinesi temizlenmiş bir derviş 

ya da tapınanı kalmamış bir put 

bir şarkı dilimin ucunda 

ve arkanda bıraktığın gencecik bir TABUT! .... 

........ 

karanlık sokaklar, yüksek binalar ve 

acımasız insan yığınları 

ne yana baksam küstah bakışlar 

bende ise.. 

varlığının yıldızlar kadar uzağında 

yetim bıraktığıN düşlerimin med-cezirleri 

ne yana baksam sensizliğimin sessizliği 

ve hasretimin ayak sesleri.. 

oysa, , , 

oysa böyle olmayacaktık 

yenilmeyecektik kahpe yüzlere 

yüzümüzden güneşin rengi silinmeyecekti 

deyyusun ''''yüz'' ü ''''bin'' olsa 

biz ''birbirimiz'' olmaktan vazgeçmeyecektik... 

.... 

Duy beni varlığında yittiğim yokluğum 

Duy beni üşüyorum yokluğunda.. 

VARlığıMın ''varlığı'' VARlığıNda gizli 

Duy beni yürek evimin SAHİBİ! ! .........', 'Selam olsun!  Selam olsun zifiri karanlığımdan  nur aydınlığıma, ,  bakire gecelerimin sessiz ve yağmalanmamış  hırçın ama bir o kadar garip...', ARRAY['Türk Edebiyatı','Şiir','Murat Öz']::text[], 8.5, '{"poet":"Murat Öz","poet_slug":"murat-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/yurek-evimin-sahibi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bilgenin Kadim Yolculuğu', 'bir-bilgenin-kadim-yolculugu-murat-oz-gocet', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilgeysem; 

dilimde kaygısız bir bakirenin terennüm ettiği 

cılız bir şarkı varsa, 

hayatımın en zifiri yerinde acılarıma yataklık eden 

zamanda ilerliyorsa pervasızca, 

bir türlü teskeresini alamıyorsa yüreğimden 

acılarım

lügatıma habersiz eklediğin Aşk da, 

kifayetsiz kalıyorsa intiharlarıma

hep boş bırakmışsam tuvalimi 

karşısında çirkefliğin, bir fiske dahi atamamışsam 

okunaksız yüzüne hayatın, 

en çok da korku ''savaşçıların ağzındaysa artık''

balkır saçlarıma bile sığınmadan

ürkütmeden gecenin flu çocukluğunu, 

ayazına bile aldırmadan zemheri akşamlarının

geride bırakarak muskalarımı ve cüzzamlı dostlarımı hafiyelerine bir aldırmadan terketmeliyim bu kenti

terkime ıssızlığımı bile almadan...

Bilgelik

yakupçasına biriktirmekse

yüreğindeki acıları

bilgeyim

kadim bir yolculuk içre

hiç durmadan 

                incinir belleğim...', 'Bilgeysem;  dilimde kaygısız bir bakirenin terennüm ettiği  cılız bir şarkı varsa,  hayatımın en zifiri yerinde acılarıma yataklık eden  zam...', ARRAY['Türk Edebiyatı','Şiir','Murat Öz']::text[], 8.5, '{"poet":"Murat Öz","poet_slug":"murat-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-bilgenin-kadim-yolculugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimsin Sen -1-', 'kimsin-sen-1-murat-oz-yy5z7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kimsin sen 

saçların neden toprağa bu kadar 

yakın gözlerin neden ölüm kokuyor 

kimsin sen? 

Tren yollarında unuttuğum ümitlerimmi 

varoşların kaldırımlarında kaybettiğim gençliğimmi 

sokak ortasında ayyaşların kimsesiz çocukların düşlerimi 

yağmurmusun ıssız ıssız yağan 

ağıtmısın ağır ağır akan 

gözlerimden yüreğime kimsin sen? 

Kapkaranlık gecenin sahrasında 

kapkaranlık ''Deniz''in ortasındayım 

bir elimde gül yanığı bir elimde

paramparça yürek

bir mavzer gibi sıkıyorum gençliğimi kapkaranlık geceye

ve salıyorum binlerce çığlık binlerce feryat 

binlerce ağıt yüreğimi ''Deniz'' in tam ortasına 

hüznümü yorgan yapıyorum gözyaşlarımla ıslattığım 

''Deniz'' e

üşümesin diye

sonra isyanımın kıvılcımından bir ateş yakıyorum 

karanlık geceye 

aydınlansın ''Denizim'' diye...', 'Kimsin sen  saçların neden toprağa bu kadar  yakın gözlerin neden ölüm kokuyor  kimsin sen?  Tren yollarında unuttuğum ümitlerimmi  varoşlar...', ARRAY['Türk Edebiyatı','Şiir','Murat Öz']::text[], 8.5, '{"poet":"Murat Öz","poet_slug":"murat-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kimsin-sen-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimsin Sen -2-', 'kimsin-sen-2-murat-oz-0s4it', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu ne acımasız darbe

içerim yanıyor

yanlızlığım buram buram hasret 

gözlerinde öfke, kin, sevinç ne istersen mevcut 

bu ne ani ölüm 

bu ne zamanında diriliş 

Kimsin sen? 

Öfkeliyim öfkeli 

öfkem dağları yıkar 

gururum ise seni 

melekmisin yoksa cinmi 

söyle kimsin sen? 

Hüzünlü akşamlarda 

yağan yağmurmusun sen 

yoksa yağmurlar arasında

gülücükler dağıtan güneşmi 

ben zindanlarda  mahkum 

sense kapıları açıp kapatan 

gardiyanmısın? 

ben uçurum kenarında bir ayyaş 

sense çocuksu hayallerimmisin? 

bilmemki nesin? 

ben darağacına giden 

bir idam mahkumu 

sense ipimi çeken bir celladımmısın? 

Bu ne yanlış anlama 

yıllarım yanlış anlaşılan bir adam

zaman olur sessizdir ölümüm 

zaman olur çığlık çığlık feryatlar 

bu ne yanlış anlama bu ne yanlış ve yalancı yorum 

sen Brındar 

bense duygularınla oynayan bir acemi 

Figüran...', 'Bu ne acımasız darbe içerim yanıyor yanlızlığım buram buram hasret  gözlerinde öfke, kin, sevinç ne istersen mevcut  bu ne ani ölüm  bu ne z...', ARRAY['Türk Edebiyatı','Şiir','Murat Öz']::text[], 8.5, '{"poet":"Murat Öz","poet_slug":"murat-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/kimsin-sen-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimsin Sen -3-', 'kimsin-sen-3-murat-oz-4bu7z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu ne ansız ne amansız vurgun 

yüreğim delik deşik 

tenhalarında çığlık çığlık hasret 

gözlerinde yumak yumak nefret 

ne ansız çelişki 

ne amansız korku 

ne zamansız sevda 

Kimsin sen? 

Bu ne sessiz ne kimsesiz vurgun 

düşlerim un ufak gönlüm darmadağın 

kahkahasında hançer hançer kan 

ağlamasında boncuk bocuk tebessüm 

ne ansız akrep 

ne amansız yelkovan 

ne zamansız tesadüf 

Kimsin sen? 

Bu ne ıssız ne kararsız vurgun 

yıllarım perişan gençliğim paramparça 

gün olur sessiz sessiz feryat 

gün olur yumruk yumruk isyan 

ne ansız bakış 

ne amansız haykırış 

Hey haat! ! ! bu ne zamansız kaçış

Kimsin sen?', 'Bu ne ansız ne amansız vurgun  yüreğim delik deşik  tenhalarında çığlık çığlık hasret  gözlerinde yumak yumak nefret  ne ansız çelişki  ne a...', ARRAY['Türk Edebiyatı','Şiir','Murat Öz']::text[], 8.5, '{"poet":"Murat Öz","poet_slug":"murat-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kimsin-sen-3-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük', 'ozgurluk-murat-oz-w7s0h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Özgürlük gülebilmektir dileğince 

ağlamaktır sorgulanmadan 

ögürlük sevebilmektir gönlünce 

aşık olmaktır utanmadan 

hesap vermemektir özgürlük 

hislerinden ve düşüncelerinden ötürü 

pranga vurmadan kalbinden geçenlere 

haykırabilmektir elalemden korkmadan 

baskıya zulme boyun eğmek değildir 

kadere körü körüne bağlanmak değildir 

duygulara kölelik isteklere efendiliktir 

baş eğmemektir asiliktir yılmadan 

arzulara esaret yasaklara çobanlıktır 

medeniyete hizmetkarlık taassuba isyankarlıktır 

ve bir ihtiyaçtır özgürlük 

şerefli bir cesaret demektir 

canının istediği zaman kazanıp 

canının istediği zaman kaybetmektir...', 'Özgürlük gülebilmektir dileğince  ağlamaktır sorgulanmadan  ögürlük sevebilmektir gönlünce  aşık olmaktır utanmadan  hesap vermemektir özgür...', ARRAY['Türk Edebiyatı','Şiir','Murat Öz']::text[], 8.5, '{"poet":"Murat Öz","poet_slug":"murat-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ozgurluk-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hesap', 'hesap-murat-oz-wtkt5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Biz ki 

inancın ve sevdanın 

bakır yüzlü çocuklarıyız 

toprak testilerden içince temiz suları 

gül bahçesinde ellerimiz 

hergün 

herkeze gül biçecek 

Sevda bir ince fikir derdi üstadım 

bu ince fikir üzere tutukluyum 

mahpusundayım 

alnımda bir damla kurban kanı 

ve sağlıklı bir nefret, bir sağlam öfke 

Yüreğim şimdi bir dağ şafağındadır 

el değmeye kıyamam gün uykudadır 

uyanır elbet görürsün 

ruhuma ruhun girince 

acılarımız birleşince 

alışırız bizde 

ince hesap sormaya 

derin hesap vermeye 

geniş hesap almaya...', 'Biz ki  inancın ve sevdanın  bakır yüzlü çocuklarıyız  toprak testilerden içince temiz suları  gül bahçesinde ellerimiz  hergün  herkeze gül...', ARRAY['Türk Edebiyatı','Şiir','Murat Öz']::text[], 8.5, '{"poet":"Murat Öz","poet_slug":"murat-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hesap-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke...', 'keske-ender-guncelik-tw2fa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir bulut olabilseydin keşke

Her yağmurda seni tenimde hissetseydim

Sel sularının içine 

Seni bulmak ümidiyle girebilseydim.

Bir rüzgar olabilseydin keşke

Nefes bile almayı zorlaştıran, poyraz rüzgarı

Ve ben o zorlukta solusaydım havayı

Seni içimde saklayabilseydim

Güneşin içinde rehin olsaydın keşke

O alev alev yanan ateş topunun orta yerinde, 

Ben gelip söndürseydim o ateşi

Kurtarıp, kahramanın olabilseydim.

Ayrılık olmasaydın keşke

Beni eritip bitiren o ayrılık

Dünyada her türlü zorluğu aşmak yerine

Ayrılığı yok edebilseydim.

Keşke...Keşke...Keşke...', 'Bir bulut olabilseydin keşke Her yağmurda seni tenimde hissetseydim Sel sularının içine  Seni bulmak ümidiyle girebilseydim. Bir rüzgar olab...', ARRAY['Türk Edebiyatı','Şiir','Ender Günçelik']::text[], 8.5, '{"poet":"Ender Günçelik","poet_slug":"ender-guncelik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/keske-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanberin Sevdası', 'kanberin-sevdasi-cahit-i-pekoglu-ouhf0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Boşuna arama meleğim

aşk senin yüreğinde barınamazmış.

Aşkı sadece ben yaşamışım

yüreğimde aşk hep son durakmış...

Sen sadece geçerken 

uğramışın benim dünyama.

Yüreğim seninle yıkandı

yıkanmaz olsaydı keşke ruhundan...

Ancak bu kadar dayanabildin

yeniden eski sevgisizliğine döndün.

Boşuna arama meleğim

aşk senin yüreğinde barınamazmış.

Bu güne kadarki tüm çabaların

sadece sevilmeyi yaşamakmış...

Biliyorsun değilmi

sevilmenin tüm hazzını hissettirdim sana.

Senin''de aradığın

sadece bu değilmiydi.

Artık 

gözün arkada kalmasın kadınım.

Gerçekte seni seven 

bir deli kanber yarattın dünyanda.

Köyüm kınalı kar olsun

yaşayayım seninle, sevgi ormanlarında...', 'Boşuna arama meleğim aşk senin yüreğinde barınamazmış. Aşkı sadece ben yaşamışım yüreğimde aşk hep son durakmış... Sen sadece geçerken  uğra...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kanberin-sevdasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Gibi Aklımdasın', 'gun-gibi-aklimdasin-ender-guncelik-i9ylj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nisanın ikinci haftası

Yağmuru sevdim ben

Ağzından duymuştum ilk defa

Kalbinden geldiğini sandığım, sevmek lafını

Sıcak bir mayısın ortası

Iğıl ığıl esen rüzgarı sevdim

Camdan giren rüzgar

Güzel saçındaki mis kokuyu taşımıştı burnuma

Haziranın o ilk haftası

Tozu dumana katan fırtınayı sevdim

İlk kavgamdı seninle, belki kendini naza çekmiştin

Ama kavgan bile güzeldi senin.

Oysa ben güneşi hiç sevmedim

İçimi ısıtacağına, seni aldı yanımdan

O gün bu gün nefret ettim.

14’den sonra hazirandan.

Şimdi kar var her yerde

Üşüyorum, belki de donacağım

Son defa yalvarıyorum sana gel diye.

2002’nin son günlerinde.

Hiçbir şeyi sevmiyorum artık ben, seni bile

Çünkü topraktayım sevdiğim

Duymuş muydun? öldüğümü 

Evlendiğinin günün ertesinde...

(bu son satırı da farz etki kara topraktan yazdım sana, YILLAR sonra) ...', 'Nisanın ikinci haftası Yağmuru sevdim ben Ağzından duymuştum ilk defa Kalbinden geldiğini sandığım, sevmek lafını Sıcak bir mayısın ortası I...', ARRAY['Türk Edebiyatı','Şiir','Ender Günçelik']::text[], 8.5, '{"poet":"Ender Günçelik","poet_slug":"ender-guncelik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gun-gibi-aklimdasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamın Anlamı', 'yasamin-anlami-cahit-i-pekoglu-lky9f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seveni gül ağlatır

öyle bir gam çekerki, öldürür.

Bin tane yürekte olsa içinde

seveni ancak sevdiği güldürür.

Aşk inletir derle

dert söyletir.

Yarin ruhuna ihtiyacı olan

onun yüreğiyle ancak beslenir...

Neylesem, ne yapsam

unutmak için, başka bir sevdayada dalsam.

Bulunmaz yüreğime derman

onsuz yaşanamaz, ölürüm her an.

Gezmeyle elde edilmiyor sevda

sevdiğim gibisi, dünyada çok az''ya.

Severken onu kaybetmek varya

yaşamın anlamını kaybettiriyor bu dünyada..', 'Seveni gül ağlatır öyle bir gam çekerki, öldürür. Bin tane yürekte olsa içinde seveni ancak sevdiği güldürür. Aşk inletir derle dert söyleti...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yasamin-anlami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı İnkar Zordur', 'aski-i-nkar-zordur-ender-guncelik-3i97r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşkı inkar etmek zordur bir tanem

İnsana gözlerinle baktığında 

Bazı duyguları rahatça anlattıysan, 

Seviyorum dediysen, hem de senin beni sevdiğinden çok

Elini tuttuğunda yaktıysan onun ellerini

Karşına aldığında titretebildiysen ona ait dizleri

Ayrılığınla ağlattıysan o yeşil gözleri

Mutluluğunu elinden aldıysan eğer sevdiğinin

Giderken dönüp bakmadıysan 

Ve aylar sonra karşısına geçip, o adama karşı

Yine gözlerini konuşturduysan, yine gülüşünle yaktıysan eğer

İstediğin kadar sevmiyorum de

Kendi kalbine inandırdıysan bile

Ümit vermedim hiçbir zaman diyebilsen de

İnandırmak mümkün olmaz yanan o kalbe

Hele benim ki gibi delicisine, ölürcesine bir sevgiye

Aşkı inkar etmek zordur bir tanem...', 'Aşkı inkar etmek zordur bir tanem İnsana gözlerinle baktığında  Bazı duyguları rahatça anlattıysan,  Seviyorum dediysen, hem de senin beni s...', ARRAY['Türk Edebiyatı','Şiir','Ender Günçelik']::text[], 8.5, '{"poet":"Ender Günçelik","poet_slug":"ender-guncelik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aski-inkar-zordur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Defa', 'son-defa-ender-guncelik-vu25w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sensizliği bu gece, kaldırım taşlarıyla paylaştım

Derdimi anlattım onlara, göz yaşlarımı damlattım

Onlar bana, ben de onlara baktım

Tıpkı onlar gibi bende bu gece yalnızdım

Yol boyu eşlik ettiler bana

Senin ayak izlerini taşlarda yaşattım

Geçeceğin yerdeki kaldırımlara 

Yanan kalbimin ateşiyle ismini kazıttım

Ayrılırken söz verdiler bana 

Damarlarımda hissettiğim büyük aşkı, yarın anlatacaklar sana 

Bu akşam rahat uyu, sabaha ne olur aç gözünü

Bak son defa kaldırım taşlarındaki aşkıma...', 'Sensizliği bu gece, kaldırım taşlarıyla paylaştım Derdimi anlattım onlara, göz yaşlarımı damlattım Onlar bana, ben de onlara baktım Tıpkı on...', ARRAY['Türk Edebiyatı','Şiir','Ender Günçelik']::text[], 8.5, '{"poet":"Ender Günçelik","poet_slug":"ender-guncelik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/son-defa-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '17 Yaş', '17-yas-ender-guncelik-5jaog', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nüfus kağıdına on yedi yaşında yazmışlar

Oysa ben iki aylığım

Şu koca hayatı 

İki ay yaşadım ve ölüme kucak açtım

Sevdiğini söylediğin günden yedi ay geçti

Ayrılışımızdan da tam beş ay

Arada kalan iki ay varya 

O benim yaşamım, yaşayamadığım yıllarım

Ruhum öldü senin gitmenle

Ama umudum yok değil

Umudum olmazsa zaten

Ey kara toprak! al beni en iç yerine

O umudun biteceği gün 

Senin başkasıyla yüzük taktığın gün olacak

İşte o gün 

Benim ruhen ve fiziken ölümüm olacak...

Eğer haber alırsan gel

Gel nikahının ertesi benim bedenimin

Toprakla buluşacağı ana

Ve at içine mezarımın 

Mis kokulu saçlarından bir tutam

Baktığı an yakan gözlerinden son bir bakış daha

Bir kağıda da “Sevişmiştim Seni” yaz. 

Bu dünyada inanamadım sevdiğine 

Belki inanırım cehennem ateşinde...', 'Nüfus kağıdına on yedi yaşında yazmışlar Oysa ben iki aylığım Şu koca hayatı  İki ay yaşadım ve ölüme kucak açtım Sevdiğini söylediğin günde...', ARRAY['Türk Edebiyatı','Şiir','Ender Günçelik']::text[], 8.5, '{"poet":"Ender Günçelik","poet_slug":"ender-guncelik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/17-yas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonunda', 'sonunda-salman-celik-abtjo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yalnız kalmıştım geçen gün

ansızın içimde bir kıpırtı oluştu

sessizce kendimi dinledim 

evirdim, çevirdim yine bulamadım o coşkunun nedenini

mor yeller esti içimde, sebepsiz umutlar

inanın ürkmedim aklıma o geldiğinde

nedense umutlu oldum niye olduğunu anlamadan 

yollara çıktım, gözlerim arar oldu onu

aslında onu neden aradığımı bile bilmiyordum 

sokuldum, sessiz ılık esen rüzgara

eskilere baktım, hayatımın eskittiklerine

mantık değişmiyordu hiç

insanlar ürkekliğinden arınamıyordu

nasıl olduysa o geldi aklıma birdenbire

yorulmuştum aramaktan gözlerini

and içtim bulacağım artık sebebimi

sonsuz yolculuk bu olsa gerek

en sonunda anladım galiba

martılara sordum bilemediler 

insalar anlayamadılar bile

nasıl olduysa ben bile anlayamadan 

SEVMiŞTiM ONU...', 'yalnız kalmıştım geçen gün ansızın içimde bir kıpırtı oluştu sessizce kendimi dinledim  evirdim, çevirdim yine bulamadım o coşkunun nedenini...', ARRAY['Türk Edebiyatı','Şiir','Salman Çelik']::text[], 8.5, '{"poet":"Salman Çelik","poet_slug":"salman-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sonunda-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beniöm Sevgim', 'beniom-sevgim-halil-gulel-fdxdh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey elleri kınalım kaşları sürmelim; 

Karakışı bahara döndüren sevgilim.

Yanakları al olan gerdanı tek bendim

Sinesine bir beni konduran sevgilim.

Tel tel ipek saçları örülür elimde, 

Işık verir gözleri aydınlık yolumda, 

Sabah akşam her zaman mevcuttur dilimde

Aşkıyla yüreğimi yandıran sevgilim.

Gökleri tuttu duman yandıkça bu yürek, 

Menzile varmak çok zor o yâr benden ırak, 

Bir ömrü verdim ona bilmem ki dur durak

Baharda gül dalına konduran sevgilim.

Cilvesi verir çile kopartır velvele, 

Nazı etti müptela tebessümü alâ, 

Çekse de yaban yola yağsa ondan belâ

Bir tatlı sözle beni kandıran sevgilim.

Kor mudur ateş midir bu dudaklar sende, 

Aşığın bir ben, çoktur hayranın çevrende, 

Ressam Halil’in ömrü son ana gelende 

Yürekte her derdimi dindiren sevgilim...

                  		Düsseldorf / 22.12.2002', 'Ey elleri kınalım kaşları sürmelim;  Karakışı bahara döndüren sevgilim. Yanakları al olan gerdanı tek bendim Sinesine bir beni konduran sevg...', ARRAY['Türk Edebiyatı','Şiir','Halil Gülel']::text[], 8.5, '{"poet":"Halil Gülel","poet_slug":"halil-gulel","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/beniom-sevgim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebepsiz Gezinti', 'sebepsiz-gezinti-salman-celik-o4f9p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gece iyice ilerlemiş, sabaha zaman gitgide yaklaşırken 

sebepsizce bir gezintiye çıktık

gündüzleri insan seli olan sokaklar bomboş 

belki kafalarını dinliyorlar bilemem

ama bir dilleri olsa neler anlatacaklar neler

sonra, 

insanlar şehirle beraber çekilmişler evlerine 

binalar sanki şehri korurcasına siperle duruyorlar 

o sokaktan çıktık bu sokağa

derken eski evimizin sokağına bir manevra

bizimkilerin anıları...

daha sonra, 

bir üst sokağa hayatımı eskittiklerinden birinin sokağına 

sokakların bu kadar anlam taşıması çok ilginç 

ama diyorumya ah bir dilleri olsa

herkes anılarını anlatırken ben 

eski bir dostumun penceresine bakıyordum

gece ilerlerken, 

bizimkiler fakültedeki eski manastırı anlatıyor 

bir anda ay ışığını hissettim içimde

benim ne umrumda fakülte benim gözüm ayışığında

sonra, 

kenar bir semte giriyoruz, usulca

ev ışıklarının çoğu olmasada birazı yanıyor

malum ya, vakit geç 

bir köşede gençler sigara tüttürüyor

ama sokakların tümü boş 

radyodan bir şarkı değiyor kulaklarıma 

öyle seveimki, Yavuz Bingöl''den ''Üşüdüm Biraz'' ı 

sokaklar geceleri, ıssız ve dilleri yok 

gündüz, 

bir karınca yuvası gibi olam Maarif kavşağı bile 

bomboş, sessiz

bir de soğuk havada boşalan parklar, 

yalnızlığa oynuyorlar 

saat 23: oo 

ve bir sonbahar geceside elimden kaymak üzere

yavaş yavaş eve gidiyoruz artık

resim ödevim var yarına

çizgi çalışması mı neymiş, 

benim kalemim öyle şeyleri yazmıyor artık

neden bilemem 

aman, ne umrumda demekte olmuyor ki

neyse, 

artık son satırlarım 

eve de geldik zaten 

inşaatlara daha halen beton dökülüyor

sıcak bir çay içeçeğim şimdi

umutlarım için...', 'gece iyice ilerlemiş, sabaha zaman gitgide yaklaşırken  sebepsizce bir gezintiye çıktık gündüzleri insan seli olan sokaklar bomboş  belki ka...', ARRAY['Türk Edebiyatı','Şiir','Salman Çelik']::text[], 8.5, '{"poet":"Salman Çelik","poet_slug":"salman-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/sebepsiz-gezinti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Horoz Ötende Gel', 'i-lk-horoz-otende-gel-halil-gulel-0zhi8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çok uzak diyarlarda muhteşem köşkünde; 

Sefa sürsen de güzel ömrün yetende gel...

Bir benden iz bulursun bir benden aşkında

Seviyorsan eğer ilk horoz ötende gel...

Kardan aktı mehtapta kardan aktı yüzün, 

Yansımış güzelliğin ne şirindir özün, 

Bıktırsa da razıyım bu aşığı nazın 

Senin sevdanla hâlâ yürek atanda gel...

Ruha haz verir kaşlar haz verir dudağın, 

Gül yaprağı gibi al olmuştur yanağın, 

Ey sevgili geçmeden zamanın ve çağın

Bir bahar akşamında güneş batanda gel...

Bakışın şefkat dolu nur saçar her yana, 

Bir senin için geldim aşk ile cihana, 

Vazgeçmem boyansa da bu yüreğim kana

İstersen bu çileler bir gün bitende gel...

Geçilmez ulu dağlar kesmiştir yolumu, 

Kırsa da zalim felek kırsa da kolumu, 

Bir sana sunmaktayım bir sana gülümü

Ressam Halil, yürekte duman tütende gel...

                                		Düsseldorf / 16.12.2002', 'Çok uzak diyarlarda muhteşem köşkünde;  Sefa sürsen de güzel ömrün yetende gel... Bir benden iz bulursun bir benden aşkında Seviyorsan eğer ...', ARRAY['Türk Edebiyatı','Şiir','Halil Gülel']::text[], 8.5, '{"poet":"Halil Gülel","poet_slug":"halil-gulel","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ilk-horoz-otende-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başangıç Şarkısı', 'basangic-sarkisi-salman-celik-2rspm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yine sensiz bir gün

içimden defol demek geliyor 

dün gece sanki beni çağırıyor

dünkü yağmurlar senin tenine düşüyor 

yıldızlara yansıyan yüzün 

gecemi aydınlatıyor 

dünkü ışıklar hala gözlerimin içinde

ışıldıyor

yarında sen olmayacaksın belki

ama dün gece beni çağırıyor 

yıldızlara yansıyan yüzün 

gözümün önünden gitmiyor

bitmesin bu gece

doğmasın güneş 

diyemedim işte

yıldızlar gidince sende gideceksin işte

git...', 'yine sensiz bir gün içimden defol demek geliyor  dün gece sanki beni çağırıyor dünkü yağmurlar senin tenine düşüyor  yıldızlara yansıyan yüz...', ARRAY['Türk Edebiyatı','Şiir','Salman Çelik']::text[], 8.5, '{"poet":"Salman Çelik","poet_slug":"salman-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/basangic-sarkisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-salman-celik-rnnpq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yağmur neden yağarsın bilmem 

yağ içime serpil yüreğime

sevdalarım filizlensin

aşklarım ıslansın 

ama her zaman böyle olmuyor ki

neden yağmur neden? 

neden bazen kir pas olursun 

neden dostları tüketirsin bilmem 

seni anlayamam yağmur 

yalnızken bana arkadaşsın 

ay ışığında düşmansın 

ama sevdalaraımın karanlık mimarısın 

sana küsüm be yağmur

kalbimin bir parçası senin elinde

o parçamı bana vermeden

yağma buralara...', 'yağmur neden yağarsın bilmem  yağ içime serpil yüreğime sevdalarım filizlensin aşklarım ıslansın  ama her zaman böyle olmuyor ki neden yağmu...', ARRAY['Türk Edebiyatı','Şiir','Salman Çelik']::text[], 8.5, '{"poet":"Salman Çelik","poet_slug":"salman-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sitem-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmuşum', 'unutmusum-salman-celik-jbbgn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bana sevmesini öğretmelisin 

yaprakları dökmeliyiz sonbaharda seninle 

kaçmamalıyız düş yaralarından

yağmurlardan birer anlam çıkarmalıyız 

sonra sessiz kalıp dinlemeliyim yağmurları

bu mecburiyet nereden takıldı aklıma 

sıcak bir çay içerken denize bakmak 

yada en yorgun umutları yaşarken kurduğum düşler 

bu mecburyetin birer gerekçesiydiler bence

söylenmeyen sözler 

bakan gözlerle 

birere anlamla gelmeliler aklıma

karşımdaki sevgi derin bir of ile başlıyorsa

arkamdan yaşanmışlıklarım beni kovalıyorsa

öğrenememişimki ben sevmesini 

korkmuşum belki sevgiden 

birine bağlanmak zor gelmiş bana

nasıl yuvaya döneceğim derken

bir gün, 

sen, 

öğretmenim 

yasemin çiçekleriyle iç içe, 

yasemin kokulu bir yerde 

sevgiyi anlattın bana 

unutulmuş sevgi kıpırdamalarını hatırlattın bana

sevgiyi sen yeniden, 

daha büyük bir umutla

evet, 

sen yaşattın bana...', 'bana sevmesini öğretmelisin  yaprakları dökmeliyiz sonbaharda seninle  kaçmamalıyız düş yaralarından yağmurlardan birer anlam çıkarmalıyız  ...', ARRAY['Türk Edebiyatı','Şiir','Salman Çelik']::text[], 8.5, '{"poet":"Salman Çelik","poet_slug":"salman-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/unutmusum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rengarenk', 'rengarenk-salman-celik-zptdu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'uyuya kalmışım yine, 

rengarenk umutlara kapılmışım

belki aldatmışım kendimi 

belki umutlarım yok ediyor beni

ya da sevgim terk ediyor yüreğimi

olsun düşler bırakmasın peşimi

aşık oluyorum rengarenk umutlarla

yasemin çiçekleri görüyorum rüyamda

her gece aynı uykuya dalıp 

aynı düşleri hissedip

yine onunla uyanıyorum 

umut yolculuğu başlamaya hazırlanıyor

ve rengarenk umutlar geliyor aklıma

umutlanıyorum her sabah

nedendir bilmem gerçekleri umursamıyorum 

düşler yorgunluğumdan arındıryor beni

uzaktan bir ses geliyor sonra

bir yankılanma, bir sevgi sesi bence

yüreğimde yankılanıyor sanki

bir dalga sesi umutlandırıyor beni

sonra bir anda yasemin kokusuyla hayale dalıp 

mavi denize açılıyorum sessizce

çok yakında, dokunabiliyorum ona

sen hiç düşlerine dokundunmu? 

dertleştinmi düşlerinle? 

umut bencillik değildir

rengarenk umutlar ise asla...', 'uyuya kalmışım yine,  rengarenk umutlara kapılmışım belki aldatmışım kendimi  belki umutlarım yok ediyor beni ya da sevgim terk ediyor yüreğ...', ARRAY['Türk Edebiyatı','Şiir','Salman Çelik']::text[], 8.5, '{"poet":"Salman Çelik","poet_slug":"salman-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/rengarenk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai', 'rubai-neyzen-tevfik-9qod1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sanma ciddiyet ile sarf ederim sanatımı 

Ney elimde  suyu durmuş kuru musluk gibidir

Bezm i meyde sufehanın saza meftun oluşu

Nazarımda su içen eşşeğe ıslık gibidir', 'Sanma ciddiyet ile sarf ederim sanatımı  Ney elimde  suyu durmuş kuru musluk gibidir Bezm i meyde sufehanın saza meftun oluşu Nazarımda su i...', ARRAY['Türk Edebiyatı','Şiir','Neyzen Tevfik']::text[], 8.5, '{"poet":"Neyzen Tevfik","poet_slug":"neyzen-tevfik","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/rubai-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz', 'deniz-salman-celik-nr6f9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ay birkaç geceden sonra

tekrar penceremin önünde 

camlar buğlanmış

aklıma sen geldin işte

evet, 

bir denizsin sen 

coşkulu, bazense durgun 

bir ışık doğar tam kalbinden 

yakamozlar oluşur yüzünde

coşkulu denizin şarkıları söylenir heryerde

umursamazsın kimseyi

heey! dersin varmı benden mutlusu 

bazen durgunlaşırsın, 

yakamozlar yerini 

kızıl gecelere bırakır

bir gece yakamozunu beklerken 

ansızın, bir güneş doğacak bekle 

başına onlarca afet çıkacak belki 

yıpranacaksın, dalgalaraın hırçınlaşacak 

kayaları vurup geçirecek 

vuracağın kayaları iyi seçeceksin unutma

direncin kalmayacak belkide

belkide suların çekilecek 

ve yine yakamozunu beklerken 

bir güneş doğacak ansızın 

ancak bir deniz tanımlayabilirdi 

ancak bir deniz 

evet, sen bir deniz gibisin ''DOSTLARIM''

bir deniz gibi...', 'ay birkaç geceden sonra tekrar penceremin önünde  camlar buğlanmış aklıma sen geldin işte evet,  bir denizsin sen  coşkulu, bazense durgun  ...', ARRAY['Türk Edebiyatı','Şiir','Salman Çelik']::text[], 8.5, '{"poet":"Salman Çelik","poet_slug":"salman-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/deniz-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin', 'neredesin-ozcan-nevres-0nact', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çok sevdiğin çay bahçesinde oturdum

Soğuğa aldırmadan saatlerce

Ne denizin eski güzelliği

Ne de içtiğim çayların tadı vardı

Kalkıp kumsala gittim

Yürüdüm uzun uzun

Karanlık çökünce kentin üstüne

Oturup bir kayanın üstüne

Hayalini aradım serin suların içinde

Üşüdüm aldırmadım üşümeme

Şimdi yanıyorum ateşler içinde

Ölümü düşlüyorum gönlümce

Baş ucumda sen varsın

Gözlerin yaşlar içinde', 'Çok sevdiğin çay bahçesinde oturdum Soğuğa aldırmadan saatlerce Ne denizin eski güzelliği Ne de içtiğim çayların tadı vardı Kalkıp kumsala g...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/neredesin-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş Üstünde İki Kuş', 'ates-ustunde-i-ki-kus-kucuk-i-skender-v4y9m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '-kimseye...

1.

onulmaz gecelerin epe parmakları olurdu

telgraflar alınırdı o saat

ince uçurumlarına ölü dolan plak ülkelerin

güzel yalnızlıklarından

dire straits''in hüküm sürdüğü bir pub''da

tekbaşınıza otururdunuz sen ve o

timsah parçası kadın

                                     -geceyle ölüm arasında

                                      bir bağlaç gibiydim-

adamlar sahile iner hıçkıra hıçkıra kanun çalarlardı

içlerinden ikisi menekşe körü

diğer üçü ölüm virtiözü     ben

ben gitgide kararan vücudumu suda tutardım

su bizi sayıklardı ben hüznü sayıklardım 

gözlerimi yumardım seni

özlediğimi fısıldardım laci sineklere, yüz binlerce.

bir baygın yılan sokulurdu ağzından  ağzıma kimi

kimi kere, yatağımda bulurdum kopuk bacaklarını

kopuk hatıralarını bir yerlerinden kan sızlayan

öylesine bir özlemdi ki sözünü ettiğim

bütün kuşların aklı durur! 

                                -kasıklarımda bulduğum ilk tüyü 

                                senin burnununucuna sürdüydüm-

kirpiklerinde bir karanfil kayması 

külden bir elbise dikip çocukluğuma

papuçlarını çaldım camii kapısı önünden

kapımın altından sızan sıvı kafatası

                                 sen gök çetesinin reisi

                                 ben yağmurun üvey oğlu.

-piyanonun sesini biraz kısar mısınız? 

vücudundaki udu indirirdim tenimden

söylemine mahlas burakılmış bir aşk tragedyası

2.

jimmy hendrix, peter gabriel, lois armstrong

birdy, angel heart, outsiders, la luna, rumble fish

hepsini birbiri ardınca dinler

birbiri ardınca seyrederdim sürekliyüzünde

sen enjektörü sokarken damarına

''sabahattin ali''ye benziyorsun derdin

keserken jiletlerle bileklerini -ayak- 

ben bir omzundan bir omzuna lir telleri gererdim

ipek böcekleri salardım gülerken süzülen gözyaşlarına

içki şişesinin kapağını seninle açar

seninle kapatırdım çıkarken perili konağın kapısını

puslu bahçeden geçerken topuklarıma

                            müge dikenleri batardı

batardın sayrı dolu geçmişinle yavaşça

birbirimize vidalanırdık geceler boyu 

uyku, 

bir çocuğun nefesini çalan cin gibi gelirdi ayakucumuza

sonra bir kadın çığlık çığlığa ağıt tutuştururdu.

-annem!            -benim de! 

-sen bir elementsin keşfedilmemiş           -sen de! 

seksle oksitlenirdik

dokunulmaz gecelerin tan parmakları olurdu

o parmaklar sessizce sokulur, hislenir

en kuvvetli unutuluşlarımıza dokunurdu

marlyn: devekuşunun banyo yaptığı küvet

james dean: çükümün soluk borusu

                         birarada düşünme alışkanlığı, birarada

                         duygulanım mekanizması, birarada ayrımsama

                         yetisi olan ve birarada yaptırımcı olma

                         tehlikesi taşıyan ve birarada 

                         özgünleşme bilincine erişmiş bir 

                         gettonun mütevazı ama sıradışı bireylerinin

                         tepisine ne zaman maruz kalacağız

dehliz ve ter. örtüşüyor ıslaklığın

kampanalar çalarken

taşocağında bulduğun 

giyotin

eski bir eşarpla mavi.

ayrnıtlarını devşirip varlığının

eski bir okyanus macerasında

masal kitabımın en harbi korsanı

bıyıkları yeni bilenen şehzadem

süzdün ışığı.hole geçti uşak.

mumları iğnedanlığa batırdı

sen tanıdığım 

en kadın 

en erkek

kirpiklerinde bir karanfil kayması          

1.

