INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl da', 'nasil-da-asuman-uzunyolcu-7efxc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nasılda sürükleniverdik biz

Sisli bir kaynaktan, 

Coşkun selli bir ırmağa

yalan! 

yıllar aldığını vermiyor geri

elimde kala kala

bir kopuk sevda

(Edirne yılları)', 'Nasılda sürükleniverdik biz Sisli bir kaynaktan,  Coşkun selli bir ırmağa yalan!  yıllar aldığını vermiyor geri elimde kala kala bir kopuk s...', ARRAY['Türk Edebiyatı','Şiir','Asuman Uzunyolcu']::text[], 8.5, '{"poet":"Asuman Uzunyolcu","poet_slug":"asuman-uzunyolcu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/nasil-da-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelişin Tsunamiydi', 'gelisin-tsunamiydi-gokcen-duran-ahs0y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nice   depremler   yaşadı   ruhum

Yıkıldı  bir  bir  tahammül  kaleleri

Geride  her  şeyinden  soyunmuş

Çıplak  bir  benlik  kaldı

Her  şeyini  yitirmiş  bende

Yaralı  bir  ben, arta   kaldı

Yaşadığım  her  depremde

Bir  sonrakinin  yıkıcılığı

Çok  daha  fazlaydı  öncekilerden

Korumasızdım,  üryandım

Bir  bütünden arta  kalan

Bir  bulmacanın  binlerce

Parçasıydım   artık

Acılar  nöbet   tutuyordu

Tahammülümün   sınırında

Ben  hala  direniyordum

 Hayata  inat   kendi  enkazımda 

Ta ki   seninle  karşılaşıncaya   kadar

Sen, 

Çektiğim  onca  acıya  rağmen

En  son  sığındığım  limanı, 

Depremlerden  arta  kalan  benliğimi, 

Tarumar  eden  bir  tsunamiydin

Direnemedim sana, 

Ve benliğimin yitirilmesine

Aşk tanrıçası ve deniz tanrısı

El ele tutuşmuş, öpüşüyorlardı

En yüksek dalganın gölgesinde

Beni onlara kurban ettiğin

Onlara adanmış o, kutsal törende

Neptün’ün  ve senin 

İki dudağı arasında

Mahkum yaşıyorum şimdi sana', 'Nice   depremler   yaşadı   ruhum Yıkıldı  bir  bir  tahammül  kaleleri Geride  her  şeyinden  soyunmuş Çıplak  bir  benlik  kaldı Her  şeyi...', ARRAY['Türk Edebiyatı','Şiir','Gökçen Duran']::text[], 8.5, '{"poet":"Gökçen Duran","poet_slug":"gokcen-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/gelisin-tsunamiydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acıktın mı Gardaş?', 'aciktin-mi-gardas-muharrem-karaoglan-lkyio', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Havası sert, insanı serttir Sivas''ın

Yiğdolar çokta misafirperver, 

Büyük küçük eve kim gelirse gelsin, 

Açmısın, sofra serek mi derler.

Misafir odasına kurulursun, 

Kesme çorbası, Katuklu, Borani, 

Yanında dal turşusuna bayılırsın, 

Yersin belki parmağını elini.

Çorba faslı biter, geçersin böreğe, 

Kete, Velibah, Çökelek, Kullama, 

Doyamazsın sıcak etli ekmeğe, 

Hıngel mantısına, yaprak sarmaya.

Acıkırsanız gezerken çarşıyı, 

Sorar size Sivaslı gardaşınız, 

Kelle yermisin, yoksa sebzelimi, 

Bidaha istersin varsa şansınız.

Vakit erken ise Çedar, Kelecoş, 

Öğlene doğru paça çorba iste, 

Ardından mumbar dolması gelir hoş, 

Madımak, Evelik, Yemlik; uzar liste.

Daha içli köftesini saymadık, 

Size bad yermisin diye sormadık, 

Avluda şöyle sac katmer yapmadık, 

Kalbura bastıyı sona bıraktık.

Umduğunu değil, bulduğunu yer, 

Herzaman her eve gelen misfir, 

Sivas''ın insanı sanki canciğer, 

Hergün misfir olsasın gelir.', 'Havası sert, insanı serttir Sivas''ın Yiğdolar çokta misafirperver,  Büyük küçük eve kim gelirse gelsin,  Açmısın, sofra serek mi derler. Mis...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Karaoğlan']::text[], 8.5, '{"poet":"Muharrem Karaoğlan","poet_slug":"muharrem-karaoglan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/aciktin-mi-gardas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamaya Dair', 'yasamaya-dair-ufuk-nazim-odtfm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bilirmisin, 

Suratlardaki, 

Taşa kesilmiş hüznü.

Yazıp yazıpta, 

Unutulan düşünü.Yarını beklerken, 

Kahrolan bugünü.

Ben hepsini bilirim; 

Yaşlanmadan ölmeyi, 

Bilirim bilirim dost, 

Taştan ekmek çıkarmayı, 

Nasırlı ellerle avrat okşamayı, 

Gülerken ağlamayı, 

Bilirim de; 

Ellerimi açıp yanlara, 

Korkuluk bile olamam.', 'Bilirmisin,  Suratlardaki,  Taşa kesilmiş hüznü. Yazıp yazıpta,  Unutulan düşünü.Yarını beklerken,  Kahrolan bugünü. Ben hepsini bilirim;  Y...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yasamaya-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubailer-1', 'rubailer-1-mevlana-celaleddin-rumi-epd5n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Askin beni sarmis, nasihatlar bosuna

Ictim o zehiri ben, bu seker bosuna

Gönlümdür olan divane bilmez kimse

''Zincir ayagindan vurunuz''der bosuna!', 'Askin beni sarmis, nasihatlar bosuna Ictim o zehiri ben, bu seker bosuna Gönlümdür olan divane bilmez kimse ''Zincir ayagindan vurunuz''der bo...', ARRAY['Türk Edebiyatı','Şiir','Mevlana Celaleddin Rumi']::text[], 8.5, '{"poet":"Mevlana Celaleddin Rumi","poet_slug":"mevlana-celaleddin-rumi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/rubailer-1-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varlık', 'varlik-derin-oger-1v9dh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rengârenk batan günü al karşına

Bir renk de kendinden kat

Bu gün dünyaya istediğin bir renkle bak

Çocuklar gibi saf, temiz ve berrak

Ve kapat gözlerini bir hikâye yarat

Vazgeçme hisset biraz,da sıcağını kat

Kalbinde,ki elleri bırakma sıkıca tut

Çünkü varlıktır sevgiye en güzel kanıt.

Yalnızlığın saltanatını sür, sür ama.

Birikmiş sevginden herkese bir parça dağıt

Bir tebrik bir arama bir okşama

Bin umuttur her canlı varlığa................', 'Rengârenk batan günü al karşına Bir renk de kendinden kat Bu gün dünyaya istediğin bir renkle bak Çocuklar gibi saf, temiz ve berrak Ve kapa...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/varlik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık Kalp', 'kirik-kalp-oguz-celik-agqqj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kırılmış bir vazoyu tamir eder gibi, 

Tek tek ve özenle topladım; 

Kalbimin parçalarını.

Biri defterin  arasından çıktı, 

Diğeri bana göderdiğin mektupta, 

Bir diğeri son busende, dudağımda.

Ve ardından diğerleri seninle ilgili heryerde.

Aldım sevgi tomurcuklarını, 

Aşkımla besledim, öğüttüm.

İtina ile sürdüm kırık kalbimin parçalarına.

Tek tek yapıştırdım yerlerine.

Fakat toplarken saydığım gibi, 

Bir parça eksik kaldı; 

Sanıyorum sende...

25/12/2002', 'Kırılmış bir vazoyu tamir eder gibi,  Tek tek ve özenle topladım;  Kalbimin parçalarını. Biri defterin  arasından çıktı,  Diğeri bana göderd...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Çelik']::text[], 8.5, '{"poet":"Oğuz Çelik","poet_slug":"oguz-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kirik-kalp-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim', 'kalbim-oguz-celik-vu7ar', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senin yanında; 

Saatin tiktakları gibi atıyordu kalbim

Hatta bazen daha hızlı.

Zamanla yarışıyordu adeta sevgim.

Biradım önden gidip, 

Az sonra olacakları tahmin etmeye çalışıyordu.

Ayrıldığımız günü bilemedi.

Bilseydi durdururdum.

24/05/2000', 'Senin yanında;  Saatin tiktakları gibi atıyordu kalbim Hatta bazen daha hızlı. Zamanla yarışıyordu adeta sevgim. Biradım önden gidip,  Az so...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Çelik']::text[], 8.5, '{"poet":"Oğuz Çelik","poet_slug":"oguz-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kalbim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapı aralığı', 'kapi-araligi-mustafa-ozke-xdglg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey kapı aralığında kalan yüreğim

acını benden öte kim duyar

kimin nefesi ciğerine sığar

bilir misin

Ey kapı aralığında kalan yüreğim

aşkını benden öte kim yaşar

kimin sevdası ummanları aşar

duyar mısın

Ey kapı aralığında kalan yüreğim

gökyüzünü benden öte kim özler

kimin şafağı gecesini gizler

söyler misin

Ey kapı aralığında kalan yüreğim

nefesini benden öte kim verir

kimin bedeni için için erir

anlar mısın

Ey kapı aralığında kalan yüreğim

toprağını benden öte kim sarar

kimin leylası mecnununu arar

sorar mısın

Ey kapı aralığında kalan yüreğim

sen benim ömrüme zarar mısın', 'Ey kapı aralığında kalan yüreğim acını benden öte kim duyar kimin nefesi ciğerine sığar bilir misin Ey kapı aralığında kalan yüreğim aşkını ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Özke']::text[], 8.5, '{"poet":"Mustafa Özke","poet_slug":"mustafa-ozke","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kapi-araligi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-sair-khan-fbihu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gidişin ansızın güneşin önünü kapatan bulutların bir anda

 dünyayı karanlığa mahkum ettiği gibiydi o gün

doğanın tüm güzelliği bile tesellisi olmazdı gözden süzelenlerin

ne boğaz ne ağaçlar ne de kuşlar.....

yunus söyler ya “bana seni gerek seni”..

yunus benim yerime yüzyıllar önce söylemiş bu gfünümü

dağların üstüne çökmüş sis dalgası nasıl o muhteşem görüntüyü siliyorsa

gidişin de dünyanın tüm güzelliğini de ardına taktı götürdü

var olup olmamak arasında giden beynim senin varlığınla yuaşadığının farkına vardı

yokluğunda ise ölüme..ama yokluğunu asla kabullenemedi kabullenemez

gözlerimin gözlerinde eridiği.gözlerimin gözlerinin işıltısın da kamaştığı anlar aklıma gelir

gülümsediğin andaki yüzünde açan çiçekler gamzeler gelir, hep gelir gelir

ama sen gelmezsin akıl baştan gider o gelmez gülümseme gider gözyaşı gelir

dünya da ki cennet gider cehennem gelir azrail gelir

sen de bir meleksin benim gözümde azrail de bir melek ama 

aranızda tek bir fark var o ölüm sen ise hem ölüm hem de yaşam meleğisin', 'Gidişin ansızın güneşin önünü kapatan bulutların bir anda  dünyayı karanlığa mahkum ettiği gibiydi o gün doğanın tüm güzelliği bile tesellis...', ARRAY['Türk Edebiyatı','Şiir','Şair Khan']::text[], 8.5, '{"poet":"Şair Khan","poet_slug":"sair-khan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gitme-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek İçin Ölelim', 'sevmek-i-cin-olelim-sait-selman-arik-y82nu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgilim, 

Şimdi ölelim

Tam sevebilmişken

birbirimizi

Sevilmişken ölelim.

Doruğa çıkmış ihtiraslarımızı yolda bırakalım

Ölmek zamanıdır gün batımı 

Veya seher vakti...

Ayrılık kanatmadan yüreğimizi

Hasret donatmadan bedenimizi

Yaşayanlara inat, 

Güllere inat ölelim.

Daracık bir odada 

şiir yazarken

kitap okurken

dua ederken

göz göze gelmişken ölelim

bir kez 

ve son kez...

Kimse bilmesin öleceğimizi

Güller için ölelim..

Aşkı anlatırken

Yaşatırken ölelim

ki güller utansın

Hasret satırları kağıda dökülmeden

Ufuklarımız kapanmadan

Birbirimize sarılamadan ölelim.

Sevgilim artık kavuşma zamanıdır 

Hadi artık ne duruyorsun? 

Ölelim...', 'Sevgilim,  Şimdi ölelim Tam sevebilmişken birbirimizi Sevilmişken ölelim. Doruğa çıkmış ihtiraslarımızı yolda bırakalım Ölmek zamanıdır gün ...', ARRAY['Türk Edebiyatı','Şiir','Sait Selman Arık']::text[], 8.5, '{"poet":"Sait Selman Arık","poet_slug":"sait-selman-arik","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sevmek-icin-olelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'dur-gitme', 'dur-gitme-elif-sebnem-akal-hw352', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dur, gitme...

Henüz bitmedi hikayesi, 

Her sabah gökyüzüne, 

Sevgi ile ''günaydın''

Diyen gözlerimin.....

Dur, 

Anlatmadım ki daha, 

Hangi tonunu severim, 

Gökkubbenin, denizin

Havasına, gününe

Göre değişen renginin...? 

Nerde görmüştüm bir de, 

Aynısını değil de, 

Benzerini gözlerinin...

Kal, 

Gitmek için çok erken, 

Daha vaktimiz varken

Ve sürüyorken, 

Bende ki geçici eşsizliğin...

19.1.1998', 'Dur, gitme... Henüz bitmedi hikayesi,  Her sabah gökyüzüne,  Sevgi ile ''günaydın'' Diyen gözlerimin..... Dur,  Anlatmadım ki daha,  Hangi ton...', ARRAY['Türk Edebiyatı','Şiir','Elif Şebnem Akal']::text[], 8.5, '{"poet":"Elif Şebnem Akal","poet_slug":"elif-sebnem-akal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dur-gitme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağlama', 'baglama-i-brahim-kilinc-71m3g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bazen alev olur, bazen har olur, 

Sevenlerin yüreğinde kor olur, 

Şiir olan yerde elbet var olur, 

Dilimizdir, bizi söyler bağlama.

Ağıt olur, felaketler sonunda, 

Yiğit olur, o toplumun önünde, 

Neler söyler, bak ehlinin elinde, 

Bir tanıdık yüzü söyler bağlama.

Türkü yapar şairlerin sözünü, 

O güldürür aşıkların yüzünü, 

Neşeyi anlatır, bazen hüzünü, 

Kalpten kalbe izi söyler bağlama.

Telinden geçmeden öze varılmaz, 

Aşk ile yanmadan köze varılmaz, 

Gönülden dinleyen çalan yorulmaz, 

Eli değil bizi söyler bağlama.

Ustası çalarken seni anlatır, 

Elime alınca beni anlatır, 

Belki yarın, belki dünü anlatır, 

Bir tınıda bini söyler bağlama', 'Bazen alev olur, bazen har olur,  Sevenlerin yüreğinde kor olur,  Şiir olan yerde elbet var olur,  Dilimizdir, bizi söyler bağlama. Ağıt olu...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/baglama-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşlar', 'yaslar-i-brahim-kilinc-318l5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnletirse usta mızrap telleri, 

Sormadan dökülür gözünden yaşlar, 

Sevdanın ikinci yarısındaysan, 

Yormadan dökülür gözünden yaşlar, 

Gönüle dikilen bir gülün olur, 

Kanınla sulanır al gülün olur, 

Çorak bağrındaki son gülün olur, 

Durmadan dökülür gözünden yaşlar.

Gökte şimşek kalpte yıldırım olur, 

Çözmek istedikçe kördüğüm olur, 

İçinden çıkılmaz bir durum olur, 

Yılmadan dökülür gözünden yaşlar

Gözleri gözünden ayrılmaz ki hiç, 

Sert kabuk altında kaynayan o iç, 

Titretir aşktaki o kudret o güç, 

Sonradan dökülür gözünden yaşlar

.

Gelir geçer dersin yerleşir kalır, 

Her şeyin tükenir hatıran olur, 

Can sanarsın bakarsın ki el olur, 

Kalmadan dökülür gözünden yaşlar.', 'İnletirse usta mızrap telleri,  Sormadan dökülür gözünden yaşlar,  Sevdanın ikinci yarısındaysan,  Yormadan dökülür gözünden yaşlar,  Gönüle...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yaslar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nur', 'nur-i-brahim-kilinc-kmn4h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nur doğmuş diyorlar o gün bir güzden, 

Uyananlar haberdar olmuş bu kızdan, 

Renk vermiş Yaradan güneş, ay ve denizden

                                                 18.11.1999', 'Nur doğmuş diyorlar o gün bir güzden,  Uyananlar haberdar olmuş bu kızdan,  Renk vermiş Yaradan güneş, ay ve denizden                       ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/nur-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen gülünce II.', 'sen-gulunce-ii-yusufcan-koksal-apcd8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'rüyama girdin dün gece

belki bir nefes kadar yakın

belki yıldızlar kadar uzaktın

belki kafiyelerde saklısın 

belki de bestelerde bi hece, 

soluk kesecek kadar güzeldin dün gece

annem bile uyandıramadı beni, 

sen gülünce..

eski takvimleri mi karıştırıyorum yine

tarihi tekerrür mü ettiriyorum

yine mi seviyorum da yanıyorum

''aşk değil'' desen de buna

''aşk değil'' de sen bozma

belki uzamış olur o gün sakalım

o gün tövbe dersin

o gün sen gülünce... 

Aralık 2002', 'rüyama girdin dün gece belki bir nefes kadar yakın belki yıldızlar kadar uzaktın belki kafiyelerde saklısın  belki de bestelerde bi hece,  s...', ARRAY['Türk Edebiyatı','Şiir','Yusufcan Köksal']::text[], 8.5, '{"poet":"Yusufcan Köksal","poet_slug":"yusufcan-koksal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-gulunce-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen gülünce III.', 'sen-gulunce-iii-yusufcan-koksal-fhda9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'anlamını bilmeden, 

dinlemeden söylediğim şarkılar gibisin, 

bestecisi, söz yazarı hepsi belirsiz

anlayacağın, anlatılmaz bir melodisin.

ne sesim güzel ne ezberim kuvvetli

ama tutamıyorum şakıyorum işte

sen gülünce, 

son yürüyüşüm bu Ankara sokaklarında

son üşüyüşüm kışının soğuğunda

elini tutup da ısınmak vardı ama

korkarım yaklaşamamki yanına

sen gülünce, 

titrer mi nefesim çeksem seni bir nefeste, 

bilmem geçer mi hevesim o anın salisesinde, 

ama takılma ihtimalin yok mu içimde

sen gülünce...

Aralık 2002', 'anlamını bilmeden,  dinlemeden söylediğim şarkılar gibisin,  bestecisi, söz yazarı hepsi belirsiz anlayacağın, anlatılmaz bir melodisin. ne ...', ARRAY['Türk Edebiyatı','Şiir','Yusufcan Köksal']::text[], 8.5, '{"poet":"Yusufcan Köksal","poet_slug":"yusufcan-koksal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-gulunce-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bende Değilim Artık', 'ben-bende-degilim-artik-bektas-oncu-286ku', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ben hep yalnızlığımla sensiz, sensizliğimle kimsesizim. o, neşe dolu insandan bir eser kalmadı artık, beni benden alan yokluğun temelli tüketiyor beni. derin düşünceler kemirirken beynimi, hala sönmeyen küllenmek bilmeyen sevda ateşin yakarken içimi, paket paket içtiğim sigaralar ve yudumladığım buz gibi bir bira, efkarımı dağıtmaya yetmiyor. yüreğimin ateşi dinmiyor, tükeniyorum kendi karanlığımda, boğuyor beni sensiz hayat.seni arıyorum. gençliğimi arıyorum.boşa geçmiş yıllara isyan ederken.içimde saklıyorum öfkemi, ve hep susuyorum.giderken bıraktığın o neşe dolu insandan bir eser kalmadı artık.binlerce defa özür diliyorum ömrümden.boşa ziya olmuş günlerden.o tükenen gençliğimden.doğacak her güne merhaba demeye korkarken.hiçbir şeyin farkına varmadan öylesine amansız ve çaresiz geçen yıllar, nede çabuk harcadı ve yıprattı beni.bir albümün arasına sıkışmış o tevessümler gülen gözler.o neşe dolu insandan bir eser kalmadı artık.tütünüme meze yaptım yalnızlığımı, sigaramda duman oldun.anlam veremediğim hayatın uğultusu içimi çizip geçerken, buralrda herşey bıraktığın gibi bir sen vefasız çıktın birde, ben bende değilim artık o neşe dolu insandan bir eser kalmadı ararken seni kendi karnlığımda, yıldızı kayıp gecelerde, ay geceye küsmüş bende sana  o neşe dolu insandan bir eser kalmadı artık', 'ben hep yalnızlığımla sensiz, sensizliğimle kimsesizim. o, neşe dolu insandan bir eser kalmadı artık, beni benden alan yokluğun temelli tüke...', ARRAY['Türk Edebiyatı','Şiir','Bektaş Öncü']::text[], 8.5, '{"poet":"Bektaş Öncü","poet_slug":"bektas-oncu","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/ben-bende-degilim-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayamadım', 'aglayamadim-arzu-dincer-8if4z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen giderken, 

Buğulu gözler bırakmıştın bana, 

 Ve demiştin ki, 

   “Beni anarsın, her gözyaşında”

      “Bencilsin” demiştim, bencilliğimi örterek, 

           Gözyaşları değil, seni istiyorum yanımda...

           .....

                Nasıl anlatabilirim, insanlara kızgınlığımı, 

                   Ya da hiçbitmeyen sakarlığımı, 

                      Söyle..buğulu gözlerin dile gelirmi uzaklardan..

Sen giderken buğulu gözler bırakmıştın bana, 

  Ve demiştin ki, 

  “Özlediğinde bakarsın...yanında oluveririm hemen, söz”

     Daha sıcaklığın geçmeden ellerimden, 

       Baktım buğulu gözlerine, 

          Sen gelmedin, 

         ...

             Ağlayamadım gidişine....

Arzu ÖZTÜRK

25/12/2002', 'Sen giderken,  Buğulu gözler bırakmıştın bana,   Ve demiştin ki,     “Beni anarsın, her gözyaşında”       “Bencilsin” demiştim, bencilliğimi...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aglayamadim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık Ölüm', 'karanlik-olum-ufuk-nazim-jgzv0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sırıklar dikmişler, 

Çadırların orta yerine.

Bir sırık taşır, 

Üzerlerindeki gökyüzünü.

Anadolumun göçebe halkı, 

Tekrar çadırlarında; 

Ama korkudan, zorunluluktan.

Depremi bekliyorlar, 

Ölümü bekler gibi.

Uykular haram, 

Karanlık ortağı olmuş depremin

Ve uykuda geliyor ölüm, 

Uykudan korkuyor Anadolu’m.', 'Sırıklar dikmişler,  Çadırların orta yerine. Bir sırık taşır,  Üzerlerindeki gökyüzünü. Anadolumun göçebe halkı,  Tekrar çadırlarında;  Ama ...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/karanlik-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Dediğin Fani...', 'hayat-dedigin-fani-arzu-dincer-e19nq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen ağlarsın fani şeylere, 

Fani şeyler seni bilmez...görmez.

Sen dert edinirsin, 

Dert seni tanımaz, kim bu demez.

E be arkadaş ne uğraşırsın 

Böyle şeylerle, 

Seni tanımayanı, 

Sen de tanıma gitsin...', 'Sen ağlarsın fani şeylere,  Fani şeyler seni bilmez...görmez. Sen dert edinirsin,  Dert seni tanımaz, kim bu demez. E be arkadaş ne uğraşırs...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hayat-dedigin-fani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kımıldanış', 'kimildanis-ozgur-mavi-dg51f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölümle bağlandık zincirlere, 

yaşamla öldük özgürlüklerde

ve yaşadık...

ve öldük...

seni yaşadık

ölümle yaşam arasındaki parlak tılsım

ölümle olsada.', 'Ölümle bağlandık zincirlere,  yaşamla öldük özgürlüklerde ve yaşadık... ve öldük... seni yaşadık ölümle yaşam arasındaki parlak tılsım ölüml...', ARRAY['Türk Edebiyatı','Şiir','Özgür Mavi']::text[], 8.5, '{"poet":"Özgür Mavi","poet_slug":"ozgur-mavi","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kimildanis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanda Ufalanan', 'zamanda-ufalanan-ufuk-nazim-p2zpf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nedir ölümün sebebi? 

Kohrolası zülüm mü? 

Yoksa ömürlerini, 

Mahkümiyet gibi geçirip, 

Cenneti ölümde arayan bizler mi? 

Bozkırlarımızda su yerine, 

Akarken kan.

Çelişkilerde yoğrulurken insan.

İnsan kardeşine kurşun sıkan, 

Senin sevgiyi yaratan ellerin.

Düşün kapkara postallar, 

Senin ayaklarında insan.

Neden üzerimizde kapkara postalların? 

El uzatıyorum karanlığa, 

Ne olur tutun elimden.', 'Nedir ölümün sebebi?  Kohrolası zülüm mü?  Yoksa ömürlerini,  Mahkümiyet gibi geçirip,  Cenneti ölümde arayan bizler mi?  Bozkırlarımızda su...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/zamanda-ufalanan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-arzu-dincer-xhlyv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Baktıkça gülümsüyor hayat, 

Söz alıyor, yaşamak üstüne.

Sahip çıkıyor kendine, 

Takvimden bir yaprak daha yitiyor..', 'Baktıkça gülümsüyor hayat,  Söz alıyor, yaşamak üstüne. Sahip çıkıyor kendine,  Takvimden bir yaprak daha yitiyor.....', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hayat-69-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karartma Geceleri', 'karartma-geceleri-ufuk-nazim-4is0f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kurşunlar, 

Nakışlarını çizerken bedenlere; 

Umudun desenlerini, 

Mutluluğun mısralarını yaratırdı, 

Bombardıman altında, 

Hiç karartılamayan yüreğinde.

Karartılamadı odası, 

Evine kurşunlar yağdı, 

O yinede yazdı.

Nazım'' dan öğrendi 

İnsanı sevmeyi, 

Ölümü satırlara gömmeyi.

Her satırla daha da sağlam bastı yere.

Karartma gecelerinde                                   

Öğrendi ağlamayı, 

Sonraları savaşla hep savaştı

Ve hiç ağlamadı.', 'Kurşunlar,  Nakışlarını çizerken bedenlere;  Umudun desenlerini,  Mutluluğun mısralarını yaratırdı,  Bombardıman altında,  Hiç karartılamaya...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/karartma-geceleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşe Gömülenlere', 'gunese-gomulenlere-ufuk-nazim-uxonp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaybolup gidiyor gene bir umut, 

Tek tek yok olan günler

Ve sönen yıldızlar gibi.

Her nefeste dahada yaklaşıyor ölüm.

Birde sen olmasan ya gülüm, 

Her saniye bana zulüm.

Bak bir yıldız daha sönüyor, 

Dar ağacının mat rengine bürünüp.

Ayakları daha yeni çıkmış prangadan

Elleri hala bağlı.

Gözlerinde hala kavgasının ışığı saklı.

Ve sloganları yankılanıyor, 

Korku dağlarından.

Sahte bir matem dökülen suretlerden.

Yıldızlar kayboluyor.

Güneşe gömülecek, 

Sönen bir yıldız daha.

Pencerelerinizden girecek evlerinize, 

Kapılarınız kapalı kalsada.', 'Kaybolup gidiyor gene bir umut,  Tek tek yok olan günler Ve sönen yıldızlar gibi. Her nefeste dahada yaklaşıyor ölüm. Birde sen olmasan ya g...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gunese-gomulenlere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Kişilik Ülke', 'tek-kisilik-ulke-ufuk-nazim-26e46', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senin adın neydi? 

Rengin neydi? 

Bilmiyorum.

Sana dair herşeyi unuttum.

Yüreğime ağan çelikçubuklarla, 

Ölüme yaklaşırken, 

Yıllardırgurbette, 

Ciğerlerim şarabı damıtırken, 

Yalnızlığında bir içki olduğunu

Ve karanlığında meze olabileceğini anladım.

Yalnızlık ayyaşıyım artık.

Karanlığa olan tutkum artıyor.

Aranıza dönemem.

Siz gurbettesiniz artık, 

Bense ufuk yalnızlığında, 

Yalnızlıklar ülkesinde.', 'Senin adın neydi?  Rengin neydi?  Bilmiyorum. Sana dair herşeyi unuttum. Yüreğime ağan çelikçubuklarla,  Ölüme yaklaşırken,  Yıllardırgurbet...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tek-kisilik-ulke-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayâlin İzdüşümü...', 'hay-lin-i-zdusumu-nihan-demirel-c0cfh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'uçuk kaçık bir öyküydü bu

gülünesi bir öykü...

başladığı gibi; hâyâl...

bitti...

hazandan hep korktum ben.

ayrılığın acınası sesini

haykırdı senelerce...

kimi vakit: 

ezberlerim sarardı; 

teker teker cansız döküldü...

kimi zaman: 

ölümün tatlı kokusu; 

nefesimde...

kimi kayboluş: 

tek hece; 

''SEN''...

bir hayaldi, 

esinti belki; 

yarı açık, yarı kapalı

gibi, 

yarı sevgi, yarı nefret; 

hepsi aynı....

beyazın karaya, 

hüznün yalnızlığa

vurduğu akşam kapıları, 

açılmadan, kapalı...

son bu; 

ertesi yok.

ne iklim, 

ne şehir, 

ne kelime kelime...

hazan gibi dökülmüyor kolay...

konuşamazsın...! 

''hataların harflerini sen döktün teker teker''

diyorsun; içimdeki ben.

''sen de hislerini bastırdın hep kendi nefesine''

diyorum; 

ve o da beni terk ediyor...

tek ruh parça parça

kalakalıyorum...

içimde, 

kimsesiz çığlıklarını özlüyorum

hüznümün...

ve acı dolu haykırışlarını

çaresizliğin...

yok......

ben, 

yarı var, yarı yok

misali; 

Hep Aynı Yol; 

YAĞMUR...

YAĞAR YA KİMSEYE SORGUSUZ....

25.10.97', 'uçuk kaçık bir öyküydü bu gülünesi bir öykü... başladığı gibi; hâyâl... bitti... hazandan hep korktum ben. ayrılığın acınası sesini haykırdı...', ARRAY['Türk Edebiyatı','Şiir','Nihan Demirel']::text[], 8.5, '{"poet":"Nihan Demirel","poet_slug":"nihan-demirel","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/hayalin-izdusumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SevgiKıran', 'sevgikiran-ufuk-nazim-gmpfz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni sevdim.

Ama korkaklığım; 

Sevgimi, 

Dalga kıran gibi; 

Parçalara ayırdı.

Ve sevgim okyanusa yayıldı.', 'Seni sevdim. Ama korkaklığım;  Sevgimi,  Dalga kıran gibi;  Parçalara ayırdı. Ve sevgim okyanusa yayıldı....', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sevgikiran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiyi Yayabilmek', 'sevgiyi-yayabilmek-ufuk-nazim-v33wf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sıra dağlar gibi sevdim seni, 

Dağlar isyandır zulme, 

Zulme direnenlerin yuvasıdır dağlar.

Sevginin esareti altında, 

Yıllarımı sana adayamam.

Küçük bir evde, 

Sahte mutluluklarla yaşayamam.

Umut dağlardadır, 

Dağlar yuvadır umuda.

Ey heybetine alıcı kuşların konamadığı, 

Suretini iklimlerin bozamadığı dağ.

Ve bir dağ, 

Ancak bir dağı sevebilir, 

Ve dağlar dağları sevdiğinde, 

Yayılır sevgi ovalara.', 'Sıra dağlar gibi sevdim seni,  Dağlar isyandır zulme,  Zulme direnenlerin yuvasıdır dağlar. Sevginin esareti altında,  Yıllarımı sana adayam...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevgiyi-yayabilmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuzluğun Güneşle Gülümseyen Tezahürü', 'sonsuzlugun-gunesle-gulumseyen-tezahuru-ufuk-nazim-0lvq4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Rakı içiyordun, 

Türkü söylüyordun, 

Sonra susuyordun susuyordun.

Kaçtın bir ömür boyu

Arkandan gelen geçmişinden.

Kafandaki tutsak sevginin acısıyla

Ağıtlar yaktın zaman zaman.

Yalnızlığınla kaldın gene

Gene yalnızlığın güvertesindesin.

Üzülme ufuk okyanus sınırsız, 

Güneşin vefalı

Ve sen küçük değilsin bedenin kadar, 

Beynin sonsuz.

Ve ufkunda gülümseyen

Bir güneşin var.', 'Rakı içiyordun,  Türkü söylüyordun,  Sonra susuyordun susuyordun. Kaçtın bir ömür boyu Arkandan gelen geçmişinden. Kafandaki tutsak sevginin...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sonsuzlugun-gunesle-gulumseyen-tezahuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğun Neler Anımsatıyor Bana', 'yoklugun-neler-animsatiyor-bana-ahmet-kerem-kaban-jgeag', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dün

Üzdüm seni

Kırmak istemedim

Dün

Yorgun gözüküyordun

Yormak istemedim

Dün

Geçiyordun önümden yılgın

Dün

Hastaydın

Dün

Sebebi Yoktu kendimin

Dün

Aramadıysam seni

Bu unuttuğum anlamına gelmez

Dün

Dün dü

Ve bu gün

Düne benzemeden tamamlayacağım

Ve yarın yollara düşeceğim

Senin için

Yollar seninle anlam kazanacak

Ben de seni

Yarın dan

Önce gelmeliydim yanına

Sonumu(z)  t.....', 'Dün Üzdüm seni Kırmak istemedim Dün Yorgun gözüküyordun Yormak istemedim Dün Geçiyordun önümden yılgın Dün Hastaydın Dün Sebebi Yoktu kendim...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kerem Kaban']::text[], 8.5, '{"poet":"Ahmet Kerem Kaban","poet_slug":"ahmet-kerem-kaban","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yoklugun-neler-animsatiyor-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Günü', 'dogum-gunu-sair-karatas-9sfab', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Doğum Günü

Ölümün, doğumdan daha kutsal sayıldığı

                                bir yerde doğduysan, 

bir mezar taşına bakmadan bilemezsin, 

                                doğduğun günü, 

ölenler eksiksiz yazılır mezar taşlarına; 

doganlar bu milatla hatırlanır.', 'Doğum Günü Ölümün, doğumdan daha kutsal sayıldığı                                 bir yerde doğduysan,  bir mezar taşına bakmadan bilemezsin...', ARRAY['Türk Edebiyatı','Şiir','Şair Karataş']::text[], 8.5, '{"poet":"Şair Karataş","poet_slug":"sair-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dogum-gunu-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '8: 40 ve sonrası', '8-40-ve-sonrasi-ahmet-kerem-kaban-w3b8s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Küller seriyorum dağ yamaçlarına

Saçlarında papatyalar

Rüyalarıma giriyorsun

Bitmemesi için

Fazla mesaiye kalıyorum

Senin içinde yaşıyorum

Gövdene yaslanıyorum

Kıvrımlı nehirleri anımsatıyor

Söylencelerim

Kızma bana

Pırlantalar gözümü kama? tırıyor

Sen pırlantalardan

Daha fazla...', 'Küller seriyorum dağ yamaçlarına Saçlarında papatyalar Rüyalarıma giriyorsun Bitmemesi için Fazla mesaiye kalıyorum Senin içinde yaşıyorum G...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kerem Kaban']::text[], 8.5, '{"poet":"Ahmet Kerem Kaban","poet_slug":"ahmet-kerem-kaban","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/8-40-ve-sonrasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorgulama', 'sorgulama-sair-karatas-xql01', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sorgulama

Öğrendiklerimi yaşayamadım.

Benim yaşadıklarımı, 

hiç bir öğretmenim kara tahtaya

                                       yazamadı', 'Sorgulama Öğrendiklerimi yaşayamadım. Benim yaşadıklarımı,  hiç bir öğretmenim kara tahtaya                                        yazamadı...', ARRAY['Türk Edebiyatı','Şiir','Şair Karataş']::text[], 8.5, '{"poet":"Şair Karataş","poet_slug":"sair-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sorgulama-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir perdelik aşk', 'bir-perdelik-ask-sair-karatas-3k2x1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir Perdelik Aşk

Yeni dağılmış bir ilkokul gibiydi 

                                   gözlerin.

Saçının kenarına bir ırmak iliştirdim.

İlk perdeydi, 

antik tiyatroda öpüşmemiz.

Bir perde daha sürse, 

aşkımızın cumhuriyeti alkışlanacaktı.', 'Bir Perdelik Aşk Yeni dağılmış bir ilkokul gibiydi                                     gözlerin. Saçının kenarına bir ırmak iliştirdim. İlk ...', ARRAY['Türk Edebiyatı','Şiir','Şair Karataş']::text[], 8.5, '{"poet":"Şair Karataş","poet_slug":"sair-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-perdelik-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda', 'elveda-sair-karatas-hkl8d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nihayet geldi çattı.

Eşe dosta bir elveda diyemeden...

Neden toplandı bu kalabalık, avluya? 

Neden kulakları sağır etmekte, 

bu sessizliğin gürültüsü? 

Börtü böceği bile almış bir sessiz

                                            telaş.

İnce minareden ıslak musalla taşına inen 

                                                   essalat.

Zehir zıkkım gibi düşmüş, 

solmuş yapraklara çiğ.

Son

bahara karışıyoruz yine.', 'Nihayet geldi çattı. Eşe dosta bir elveda diyemeden... Neden toplandı bu kalabalık, avluya?  Neden kulakları sağır etmekte,  bu sessizliğin ...', ARRAY['Türk Edebiyatı','Şiir','Şair Karataş']::text[], 8.5, '{"poet":"Şair Karataş","poet_slug":"sair-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/elveda-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-sair-karatas-zvthl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Korkuyorum senden istanbul.

Bu korku; 

ne

bin hükümdar kocadan 

dul kalmış bakireliğinden, 

ne

bin dudağa susuzluğunu gidermiş

öpülmemiş genç kızlığından, 

ne

altı köşeli yıldızı

haçı

ve hilali

bağrına basıp

dinsiz kalmış günahsızlığından.

sende sevgisiz

sende sevgilisiz kalmaktan.', 'Korkuyorum senden istanbul. Bu korku;  ne bin hükümdar kocadan  dul kalmış bakireliğinden,  ne bin dudağa susuzluğunu gidermiş öpülmemiş gen...', ARRAY['Türk Edebiyatı','Şiir','Şair Karataş']::text[], 8.5, '{"poet":"Şair Karataş","poet_slug":"sair-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/istanbul-66-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldatma', 'aldatma-mehmet-kemal-tumac-gw72e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ne güzeldi o sarışın kız.

göğüsleri dudakları ne güzeldi

sanki başka diyarlara götürdü beni

minicik elleri sardı bedenimi

sabaha kadar.

ertesi gün karşımda duruyordun

hiçbir şey söylemeden.

yüzümün kızardığını hissettim.

söyleyecek bir şey bulamıyordum sana.

suskundum 

yutkundum durdum

konuşacak kelime bulamıyordum.

bir ara kısık bir sesle

HERKES YÜREĞİ KADAR SEVER

dediğinde

yıkıldım.', 'ne güzeldi o sarışın kız. göğüsleri dudakları ne güzeldi sanki başka diyarlara götürdü beni minicik elleri sardı bedenimi sabaha kadar. erte...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kemal Tumaç']::text[], 8.5, '{"poet":"Mehmet Kemal Tumaç","poet_slug":"mehmet-kemal-tumac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aldatma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemim Sevgiye', 'ozlemim-sevgiye-soner-demirez-fs1ab', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben hiç sevilmedim..

Sahte sevgilerin açtığı yarlarda yandım

Ciğerime saplanan yağlı kurşunlarda

Bilmedim sevginin ne olduğunu

Hep özledim hep aradım..

Nafile günlerde zamansız düşlere daldım

Özlemim sevgiye..

 Candan bir gülşe hasretim...

 Okşanmamış başım hasret şevkate..

 Berceste bir çocuk büyüyor içimde

 Peşmürde bir gençlik...

 Sevgisiz diyarlada yeşeriyor yüreğim

Bir gün sevgi gülü doğarmı topraklarımda..

Aaahh ahh öyle açım ki sevgiye..

Yemek istemem aş istemem iş istemem..

Başımı dizine yaslayacağımbişr sevgi...

Omuzlarında ağlayabileceğim bir sevgi..

 Gözyaşlarımı silecek bir sevgi dilediğim..

 Özlemim sevgiye..', 'Ben hiç sevilmedim.. Sahte sevgilerin açtığı yarlarda yandım Ciğerime saplanan yağlı kurşunlarda Bilmedim sevginin ne olduğunu Hep özledim h...', ARRAY['Türk Edebiyatı','Şiir','Soner Demirez']::text[], 8.5, '{"poet":"Soner Demirez","poet_slug":"soner-demirez","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ozlemim-sevgiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Telaşla Tüketiliyor', 'hayat-telasla-tuketiliyor-gokcen-duran-flw60', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Pencereden  bakacağız  dışarıya   üşümeyeceğiz

Bir  fikrin  kıyısından,  tam  ortasına   düşeceğiz

Farkında  olmadan  koşturacağız  sağa  sola

Anlayacağız  ki,  ölmeden verilemeyecek mola

Gördüğümüz  her  şey  gölgelerde   yaşayacak

Gölgeler  doyacak  güneşe,  güneş   solacak

İşleyecek   zaman,  buz  gibi  eriyecek   hayat

Bir  gün  bakacağız  ki,  gelivermiş    o   saat

Nereye   bu  gidiş,   bize   neler   olacak

Akan  göz  yaşlarımızın  yerine  ne  dolacak

Biz  olmasak  da  bu  manzara  hep  sürecek

Bu  dünya  böyle  gelmiş,   böyle   gidecek', 'Pencereden  bakacağız  dışarıya   üşümeyeceğiz Bir  fikrin  kıyısından,  tam  ortasına   düşeceğiz Farkında  olmadan  koşturacağız  sağa  so...', ARRAY['Türk Edebiyatı','Şiir','Gökçen Duran']::text[], 8.5, '{"poet":"Gökçen Duran","poet_slug":"gokcen-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayat-telasla-tuketiliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat; Çocukları Sever Sardunya''yı da', 'hayat-cocuklari-sever-sardunya-yi-da-hakki-cinar-zpjch', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayat; Çocukları Sever 

Sardunya''yı da

aslında çok uzun yollar kat etmedim

yani erken yoruldum aynı sokakları geçerken

gözlerim incitti pencereleri bildik adresleri de

balkonlar evin yalnızlıklarıydı ellerim bi kışa el sürerken

bi çok insan gördüm bi okul çıkışı bi ev yorgunu

hangi enleme düşerse iç cebim ordan vuruldum 

şu an bu sis şehrin siyah beyaz resmine belki de bi mağraydı

kimsesiz kızımı özlüyorum böyle durumlarda sardunyayı 

bi köpek yavrusu salınıyor ayaklarıma hep aynı dizelerden geçiyorum

başka şairlerle sonra yüzlerimiz  suyu çekilen bi dere

aslımız bu oysa suları çoğaltmaktan geliyorum

ne kadar çok yol var; dehlizler ve karanlıklar bi an herkes

kendi karanlığına ip sarkıtıyor sonsuz çarpışıyoruz

ne haklı çıkarır bizi kelimeleri kullanır mıyız bilmiyorum

çocuklar kartopu oynuyor bu vakitlerde

kimseler içimden geçenleri okuyamıyor birileri diyorum

yanlış olmalı her şeyi kırarken ne varsa 

birileri kırılmış olmalı kim haklı çıktı derken hayat dikiliyor 

karşımda biraz evlerin balkonu biraz mağra biraz ben

herkese bi soru veriyorum silik geçen adımlarıma dair

hayat sana bi kız çocuğu sundum bilirim 

sen de seversin çocukları', 'Hayat; Çocukları Sever  Sardunya''yı da aslında çok uzun yollar kat etmedim yani erken yoruldum aynı sokakları geçerken gözlerim incitti penc...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Çınar']::text[], 8.5, '{"poet":"Hakkı Çınar","poet_slug":"hakki-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hayat-cocuklari-sever-sardunya-yi-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başlasın Yine Kırkında Sevdamız', 'baslasin-yine-kirkinda-sevdamiz-kelkitli-summani-39y1i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni alırken, sen civan ben civan

Geçti ömrümüz, kalmadı sürmemiz

Kırkına kadar, bende olan sevdan

Başlasın yine kırkında sevdamız

Mecnun gezerim yar seni seveli

Kırkından sonra gördüğüm güzeli

Baştacı yaptım ben seni ezeli

Başlasın yine kırkında sevdamız

Hayat kırkında başlarmış güzelim

Birbirimizi daha çok sevelim

Sevgimizi biz, elekten süzelim

Başlasın yine kırkında sevdamız

İyi ki doğdun, sen maşuk, ben aşık

Kırkından sonra sevdamız sarmaşık

Doğum gününü kutlarım barışık

Başlasın yine kırkında sevdamız', 'Seni alırken, sen civan ben civan Geçti ömrümüz, kalmadı sürmemiz Kırkına kadar, bende olan sevdan Başlasın yine kırkında sevdamız Mecnun ge...', ARRAY['Türk Edebiyatı','Şiir','Kelkitli Summani']::text[], 8.5, '{"poet":"Kelkitli Summani","poet_slug":"kelkitli-summani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/baslasin-yine-kirkinda-sevdamiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazen ölmek yaşamaktan daha iyidir', 'bazen-olmek-yasamaktan-daha-iyidir-sahin-yenilmez-abycf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bazen ölmek yaşamaktan daha iyidir

Yaşadın da ne oldu? 

Kaç kere güldün? 

Kaç kere ölümüne sevdin? 

Yaşadığına değdi mi? 

Akıp giden göz yaşlarımı toplasaydım

İçinde boğulurdum

Çektiğim acıları toplasaydım

Çıkış yolu bulamazdım

Yaşamak...

Evet ben yaşıyorum diyeceksin

Diyeceksin ama

Gerçekten yaşıyor musun? 

Gerçekten hayata başkaldırabiliyor musun? 

Yanıtlamazsın çünkü sen yaşamadın

Yada hayatı ikinci yüzüyle yaşadın

Yaşıyorum deyip hep kendini kandırsın

İyisi mi sen böyle devam et

Eğer hayatı anlamak isteseydin belki şimdi burada olamazdın

Eğer hayatı anlamak isteseydin kendini bile tanıyamazdın

Bence çare susmak değildir

Bence çare yaşamak değildir

Bazen ölmek yaşamaktan daha iyidir.', 'Bazen ölmek yaşamaktan daha iyidir Yaşadın da ne oldu?  Kaç kere güldün?  Kaç kere ölümüne sevdin?  Yaşadığına değdi mi?  Akıp giden göz yaş...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yenilmez']::text[], 8.5, '{"poet":"Şahin Yenilmez","poet_slug":"sahin-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bazen-olmek-yasamaktan-daha-iyidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırlar mısın?', 'hatirlar-misin-sahin-yenilmez-dfchx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hatırlar mısın çok sevdiğimiz bir şarkı vardı? 

Beraberken hep dinlediğimiz

Ve dinlemekten hiç sıkılmadığımız

Hatırlar mısın yürüdüğümüz bir yol vardı? 

Beraberken hep gezdiğimiz

Adresini hiç unutmadığımız o yol.

Şimdi yoksun ya yanlızlık çok vuruyor

Şimdi yoksun ya sensizlik kanıma dokunuyor

Sanki acılarım bir halka oluşturmuş

Bana tuzak kuruyor

Sen olmasan da ben hep aynı şarkıyı dinliyorum

Dinledikçe birikiyor göz yaşlarım

Dinledikçe hıçkıra-hıçkıra ağlıyorum

Sen olmasan da ben hep aynı yoldan geçiyorum

Yürüdükçe mazi aklıma geliyor

Yürüdükçe gözlerim hep seni arıyor.

Hatırlar mısın eskiden seni seven birisi vardı? 

Yanından hiç ayrılmak istemeyen

Seni bir an bile görmeden duramayan.

Eğer beni bir gün hatırlamak istersen o şarkımızı dinle beni içinde bulacaksın

Eğer beni bir gün hatırlamak istersen yürüdüğümüz o yolda yürü

Yapraklarla dolan bomboş sokaklarda benim sesimi duyacaksın.', 'Hatırlar mısın çok sevdiğimiz bir şarkı vardı?  Beraberken hep dinlediğimiz Ve dinlemekten hiç sıkılmadığımız Hatırlar mısın yürüdüğümüz bir...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yenilmez']::text[], 8.5, '{"poet":"Şahin Yenilmez","poet_slug":"sahin-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hatirlar-misin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fedakarlık', 'fedakarlik-sahin-yenilmez-4c3hd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayatta her zaman istediğin bir şeyler için fedakarlık yapmalısın

Bir şeyi kaybetmeden yenisini kazanamıyorsun

Ama düşündüğümde her anımız böyle geçiyor

Yani ağlamadan gülemiyoruz mesela

Yada yağmur yağmadan güneş açmıyor

Birisi ölmeden yenisi doğmuyor

Hayatta her zaman istediğin şey için fedakarlık yapmalısın

Yani sevmeden sevilmenin ne anlama geldiğini bilemezsin

Yada korkmadan korkuyu yenemezsin

Fedakarlıklarla doludur hayatımız

Yaşamadan ölümün ne demek olduğunu bilemezsin

Yürümeden koşamazsın

Acıyı yaşamadan acıyı anlayamazsın

Karanlık olmadan aydınlığın farkına varmazsın

Bazen düşünüyorumda ikisininde olması gerekiyor

Yani karanlık olmadan gündüzün kıymetini bilemiyoruz

Yada ağlamadan gülerek geçen zamanımızın değerini

Sevilmeden sevmenin ne demek olduğunu

Hayatta her zaman istediğin bir şey için bir diğerini feda etmelisin

Yaşamak istiyorsan önce ölümün ne demek olduğunu bileceksin

Sevmek istiyorsan sevilmenin ne demek olduğnu bileceksin

Eğer ölmek istiyorsan feda edeceğin şey hayatın olacak

Feda edeceksin.', 'Hayatta her zaman istediğin bir şeyler için fedakarlık yapmalısın Bir şeyi kaybetmeden yenisini kazanamıyorsun Ama düşündüğümde her anımız b...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yenilmez']::text[], 8.5, '{"poet":"Şahin Yenilmez","poet_slug":"sahin-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/fedakarlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak Sadece Nefes Almak Değildir', 'yasamak-sadece-nefes-almak-degildir-sahin-yenilmez-87uyd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaşamak sadece nefes almak değildir

Her yaşadığın anın değerini bileceksin

Ya çok sevecek yada çekip gideceksin

Hatayı bir tek kendinde arayacaksın.

Aslında en büyük düşman sensin

Her zaman duygularının esirisin

Belki darmadağın bir serserisin

Severek yaşamayı bileceksin.

Yaşamak sadece nefes almak değildir

Belki her yolun sonunda engel karşına çıkar

Karşı koyacak bir iraden yoksa eğer

Yenilirsin, hayata yeniksindir.

Yaşamak sadece gülüp geçmek değildir

Her tebessümde bir çığlık arayacaksın

Amacın sadece yaşamaksa eğer

Hiç gülmeden de yaşayacaksın.

Yaşamak istiyorsan eğer

Sevilmeden de sevmeyi bileceksin

Kuru bir ot gibi yaşayacaksan eğer

Herkes gibi o an sende öleceksin.', 'Yaşamak sadece nefes almak değildir Her yaşadığın anın değerini bileceksin Ya çok sevecek yada çekip gideceksin Hatayı bir tek kendinde aray...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yenilmez']::text[], 8.5, '{"poet":"Şahin Yenilmez","poet_slug":"sahin-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yasamak-sadece-nefes-almak-degildir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör Misali', 'kor-misali-sahin-yenilmez-8abbo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anılarım kayboluyor

Sanki fotoğrafların üzerindeki

Kişilerde birer birer yok oluyor

Kör misali

Hatıralarda alay edercesine bize inat yapıyor

Mazimi hatırlayamıyorum

Hiç sevmedim mi ben? 

Yada hiç ağlamadım mı? 

Neden böyle

Neden her geçen gün

Hepimizden birer parça alıyor

Ve bir daha geri vermiyor

Yaşlanıyoruz işte

Belki saçlarımız ağarmadı

Gözlerimiz bozulmadı

Belkide daha dede, nine olamadık ama

Yüreğimizin yaşlandığı kesin

Kaç sevda gördü kimbilir

Kimbilir ne türlü acılara dayandı

Sanırım artık tükendi

Fotoğrafların üzerindeki kilşiler birer birer kayboluyor

Ve ben kör misali hergün o fotoğrafa bakıyorum 

Ama hiç bir şey görmüyorum.', 'Anılarım kayboluyor Sanki fotoğrafların üzerindeki Kişilerde birer birer yok oluyor Kör misali Hatıralarda alay edercesine bize inat yapıyor...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yenilmez']::text[], 8.5, '{"poet":"Şahin Yenilmez","poet_slug":"sahin-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kor-misali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Ağlıyordu Ben Dinliyordum', 'i-stanbul-agliyordu-ben-dinliyordum-sahin-yenilmez-6m7b0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Simsiyah gecenin esintisinde

Bomboş sokakların bir köşesinde

Hiç bilinmeyen yaşamın kıyısında

İstanbul ağlıyordu ben dinliyordum.

Kimsesiz sokaklar geceyle dolu

Otobüs duraklarında sokak çocukları

Kuru bir ağacın yeşil kalan dalı misali

İstanbul ağlıyordu ben dinliyordum.

Kendi sokaklarında kayboluyordu

O gece rengi yollarında

Güneşin yolunu arıyordu

Evet İstanbul ağlıyordu.

İstanbul ağlıyordu ben dinliyordum

Belki onun haline acıyordum

Gecenin bir yarısı onu arıyorken

İstanbul''un hıçkırıklarını duyuyordum.', 'Simsiyah gecenin esintisinde Bomboş sokakların bir köşesinde Hiç bilinmeyen yaşamın kıyısında İstanbul ağlıyordu ben dinliyordum. Kimsesiz s...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yenilmez']::text[], 8.5, '{"poet":"Şahin Yenilmez","poet_slug":"sahin-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/istanbul-agliyordu-ben-dinliyordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Görmeseydim', 'seni-gormeseydim-mustafa-kartal-qw57h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Acı keder bilmezdim, seni görmeseydim

Ağlamaz inlemezdim, seni görmeseydim

Gözlerini görmezdim, saçlarını örmezdim

Muradıma ermezdim, seni görmeseydim

  

Ayağımla gelmezdim, sana gönül vermezdim

Sevda nedir bilmezdim, seni görmeseydim

Bedduanı almazdım, yarı yolda kalmazdım

Böyle aşık olmazdım, seni görmeseydim

  

Gece gündüz anmazdım, uykudan uyanmazdım

Mecnun gibi yanmazdım, seni görmeseydim

Uçan kuşa sormazdım, rüyaları yormazdım

Böyle hayal kurmazdım, seni görmeseydim', 'Acı keder bilmezdim, seni görmeseydim Ağlamaz inlemezdim, seni görmeseydim Gözlerini görmezdim, saçlarını örmezdim Muradıma ermezdim, seni g...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kartal']::text[], 8.5, '{"poet":"Mustafa Kartal","poet_slug":"mustafa-kartal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-gormeseydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizlice Seviyorum Seni', 'gizlice-seviyorum-seni-sahin-yenilmez-mf987', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gizlice seviyorum seni

Kimse bilmesin, duymasın

Yüreğimde saklıyorum seni

Sen bile bilmiyorsun.

Yüreğim yansada alevler içinde

Ağlasamda seni her düşündüğümde

Kaybolsam bile kadehler içinde

Ben seni gizlice seviyorum.

Açıklarda bir gemiye benziyorum

Binlerce balığın benden haberi yok

Denizlerin içinde kayboluyorum

Denizin bile benden haberi yok.

Gizlice seviyorum seni

Tarifi imkansız duygular içinde

Sen gözlerimin içinde, her baktığım yerde

Ben gizlice seviyorum seni.

Yolum hep çıkmazlarda

Hikayem yalan kitaplarda

Sürgün gibi diyarlarda

Hep gizli kalacaksın

yüreğimin köşesinde

Ve bir gün gelip ben ölürsem

Kendini bulacaksın benim kalbimde.', 'Gizlice seviyorum seni Kimse bilmesin, duymasın Yüreğimde saklıyorum seni Sen bile bilmiyorsun. Yüreğim yansada alevler içinde Ağlasamda sen...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yenilmez']::text[], 8.5, '{"poet":"Şahin Yenilmez","poet_slug":"sahin-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gizlice-seviyorum-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlarım Var', 'umutlarim-var-sahin-yenilmez-sj6sn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geleceğe dair umutlarım var

Mutsuz insanlar, yaşanan acılar

Hergün ağlayan çocuklar

Hepsi geçecek bir gün umudum var.

Geleceğe dair umutlarım avar

Bu çıkar kavgaları

Para uğruna verilen savaşları

Hepimiz unutacağız bir gün umudum var.

Geleceğe dair umutlarım var

Sevilmeyen insanlar

Hep gözü yaşlı olanlar

Gülecekler bir gün umudum var.

Geleceğe dair umutlarım var

Yaşamaktan bıkanlar

Güneşin doğmasını beklemeyenler

Yaşayacaklar bir gün umudum var.

Geleceğe dair umutlarım var

Bir gün herkes sevecek, sevilecek

Hiç kimse ağlamayacak

Ayrılık nedir hiç bilmeyecek

Her günü ümitle bekleyecek

Umutlarım var bir gün bunların hepsi olacak.', 'Geleceğe dair umutlarım var Mutsuz insanlar, yaşanan acılar Hergün ağlayan çocuklar Hepsi geçecek bir gün umudum var. Geleceğe dair umutları...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yenilmez']::text[], 8.5, '{"poet":"Şahin Yenilmez","poet_slug":"sahin-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/umutlarim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Bağı', 'sevgi-bagi-mustafa-kartal-gy6ud', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Açmayan çiçeklere, kelebekler konmazmış

Seven bütün kalplerin, dertleri onulmazmış

  

Muhabbet kuşlarının, kur yapması bitmezmiş

Bu kadar nazdan sonra, bülbül güle gitmezmiş

  

Kanayan gönüllerin, yarası dikilmezmiş

Candan seven yiğidin, bileği bükülmezmiş

  

Sevmenin sevilmenin, belli yaşı olmazmış

Olmazsa sevgi bağı, bu ömürler dolmazmış', 'Açmayan çiçeklere, kelebekler konmazmış Seven bütün kalplerin, dertleri onulmazmış    Muhabbet kuşlarının, kur yapması bitmezmiş Bu kadar na...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kartal']::text[], 8.5, '{"poet":"Mustafa Kartal","poet_slug":"mustafa-kartal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevgi-bagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkagelsen', 'cikagelsen-mustafa-kartal-ddl9j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaybolma hemen öyle

İnsaf et biraz acı

İnleyen şu kalbimin

Sensin bir tek ilacı

  

Ayrılma hemen öyle

Biz bize yakışırken

Yakaladık mutluluğu

Göz göze bakışırken

Birgün bile yok olsan

Neler çekerim bir bilsen

Ruhum hemen canlanır

Ansızın çıkagelsen', 'Kaybolma hemen öyle İnsaf et biraz acı İnleyen şu kalbimin Sensin bir tek ilacı    Ayrılma hemen öyle Biz bize yakışırken Yakaladık mutluluğ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kartal']::text[], 8.5, '{"poet":"Mustafa Kartal","poet_slug":"mustafa-kartal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cikagelsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenim', 'ogretmenim-mustafa-kartal-1v269', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen kara tahtanın önünde

Pamuk gibi ellerin

Bembeyaz olurken tebeşirden

Ve keçe silginin çıkardığı

Tozları solurken ciğerine öğretmenim, 

Ben kız arkadaşımın saçını

Çekerek yaramazlık yapardım da

Seni üzerdim

Sonra sokakta karşılaştığımda, 

Kaçardım utancımdan, senden öğretmenim..

Bir gün cezalandırmıştın beni

Sınıfta tek ayak üstünde durdurarak

Ben, utangaç ve mahcup, başım önümde

Beklemiştim kapının yanında

Yarım saatten fazla

Sonra sen farkederek yorulduğumu

Ve bana acıyıp, 

Dürüst ve terbiyeli davrandığımı

Söyleyip, affetmiştin gönlümü

Alarak öğretmenim.

Yine de beni çok severdin de

Yerli malı haftasında, sınıfımı temsilen

Öğretmenler sofrasına, beni seçerdin, 

Beni layık görürdün, öğretmenim...

Beni mezun ettikten sonra

Çok çile çektim hayatta

Hiç el etek öpmedim, bu yüzden

Çok ceza yedim, ama ben

Senin öğütlerini tuttum hep

Seni çok özlüyorum öğretmenim, çok...

Senin cezanı ve şefkatini özlüyorum

Ve affını diliyorum, ellerini öperek

Öğretmenim...', 'Sen kara tahtanın önünde Pamuk gibi ellerin Bembeyaz olurken tebeşirden Ve keçe silginin çıkardığı Tozları solurken ciğerine öğretmenim,  Be...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kartal']::text[], 8.5, '{"poet":"Mustafa Kartal","poet_slug":"mustafa-kartal","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ogretmenim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Çiçek', 'hayal-cicek-mustafa-kartal-hwbbg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dermanımı arar oldum

Derin ve renkli rüyalarda

Ne masmavi deniz çare

Ne de vücudumu saran kum

Bir nefis ki hayalperest

Hala sende bulmaya mahkum...

Binbir çiçek içinde

Seçmiştim tek birini

Sundu kase içinde

Şifadır diye zehrini

Bir hayal çiçek ki

O, güle benzeyen zakkum...', 'Dermanımı arar oldum Derin ve renkli rüyalarda Ne masmavi deniz çare Ne de vücudumu saran kum Bir nefis ki hayalperest Hala sende bulmaya ma...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kartal']::text[], 8.5, '{"poet":"Mustafa Kartal","poet_slug":"mustafa-kartal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayal-cicek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizli Sevda', 'gizli-sevda-mustafa-kartal-5lzz4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gizli sevda çekmeyen, çektiğimi bilir mi

Halimi sormak için, hiç yanıma gelir mi

Nerededir kimbilir şimdi o bir vefasız

Umarım yaşıyordur,gamsız ve cefasız 

Bülbül gülü sever de, çilesi hiç biter mi

Bir gülücük bir kere hiç sevene yeter mi

Nerededir kimbilir şimdi o bir vefasız

Umarım yaşıyordur,gamsız ve cefasız 

Sevmeyenin kalbinde, hiç heyecan olur mu

Şu kalbim onun artık, hiç yerinde durur mu 

Nerededir kimbilir şimdi o bir vefasız

Umarım yaşıyordur,gamsız ve cefasız', 'Gizli sevda çekmeyen, çektiğimi bilir mi Halimi sormak için, hiç yanıma gelir mi Nerededir kimbilir şimdi o bir vefasız Umarım yaşıyordur,ga...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kartal']::text[], 8.5, '{"poet":"Mustafa Kartal","poet_slug":"mustafa-kartal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gizli-sevda-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen BU Şehre Küsemezsin', 'sen-bu-sehre-kusemezsin-yavuz-turhan-gjjxd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen bu şehre küsemezsin... 

Yüreğinde taşıdığın bu aşk, yaralı bedenine kazındı. 

Onurluydun, mağrur, gururlu. 

Giderken yanına aldığın, yalnızca acılarındı. 

Gözyaşlarını bile burada bıraktın. 

Sen bu şehre küsemezsin... 

Çocukça işlediğimiz bir suçtu bu aşk. 

Gözlerimizde yalansız bakışlar. 

Tek tanığımız; 

Ellerimiz titremeden yürüdüğümüz, karanlığa bulaşmış yollar. 

Sen bu şehre küsemezsin... 

Çalıyorken hala sazlarda bizim türkülerimiz, 

Dilimiz söylüyorsa en güzel aşk şiirlerini, 

Hala halaydaysak omuz omuza. 

Sen bu şehre küsemezsin... 

Giderken dokunduğun bedenim saydamlaştı. 

Yüreğimdeki seni herkes görüyor. 

Bir korna sesi ''Hoşçakal ''diyor. 

Hıçkırıkların gözlerini dolduruyor... 

Sen bu şehre küsemezsin... 

Otobüs camına koyduğun yastığın, 

Başına küçük geliyor. 

Klimanın düğmesini çeviriyorsun, 

Saçların yüzünü hafif hafif okşuyor. 

Ellerimi arıyorsun. 

Başın boşluğa düşüyor. 

Sen bu şehre küsemezsin... 

Okuduğun kitapta, 

Gözlerin gözlerime değiyor. 

Her sayfada boğazına düğümleniyorum. 

Kelimeler bu aşkın mevsimlerini anlatıyor. 

Sen bu şehre küsemezsin... 

Sevişmelerden sonra, sessizliğini paylaştığımız, 

Perdesi örtük odaları, 

Dışarda, simitçi bağırışlarının böldüğü düşleri, 

Alnına konulmuş öpüşleri unutamazsın... 

Sen bu şehre küsemezsin...', 'Sen bu şehre küsemezsin...  Yüreğinde taşıdığın bu aşk, yaralı bedenine kazındı.  Onurluydun, mağrur, gururlu.  Giderken yanına aldığın, yal...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Turhan']::text[], 8.5, '{"poet":"Yavuz Turhan","poet_slug":"yavuz-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sen-bu-sehre-kusemezsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geç kalan sevgi', 'gec-kalan-sevgi-i-lyas-nevsehirli-l5eo4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen benim hayatımın anlamısın

Ne careki  sensiz yaşam  okadar zor

tarifi imkansız

Duydumki hiç müteessir değilmişin

Ben seni çok sevmiştim

sen ise kendini', 'Sen benim hayatımın anlamısın Ne careki  sensiz yaşam  okadar zor tarifi imkansız Duydumki hiç müteessir değilmişin Ben seni çok sevmiştim s...', ARRAY['Türk Edebiyatı','Şiir','İlyas Nevşehirli']::text[], 8.5, '{"poet":"İlyas Nevşehirli","poet_slug":"i-lyas-nevsehirli","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gec-kalan-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Sevdam', 'benim-sevdam-salih-ozalasan-ea9g7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senin için yıktım, sel olup gözyaşımla dağları

Yeniden yazdım, satır satır kalemimle sevdaları

Senin için yok saydım, ağaları beyleri paşaları

Yüreğime kazdım, iğne ile keremlik aşkları

Ferhat oldum, yaktım Şirin''ime ağıtları

Köroğlu oldum, eğildi önümde Bolu dağları

Kalem oldum, sil baştan yazdım çağları

Ben yaşadım, yaşanmaz denen büyük aşk''ları

Geceleri çevirdim, hasretimle gündüze

Yıldızları şiirlerime yaptım birer, birer dize

Güneş''i yok saydım, Sevgili Güneş oldu bize

Samanyolu az geldi, koybolup gitti seven yüreğimizde

Çok geceler ağladık, ağlatmadık hiç seveni

Yüreğimde bir özlem, hasretim Alp''lerin kardeleni

Hep derler ya, yoktur sevdanın kadir kıymet bileni

Oysa ben.Sonserseri, ağlarken mutlu olabileni

Sevda denizinde bir sandal, rotasız yol alabileni

Seviyormusun diye sormadan, sadece sevebileni

Sevdasına tutulup yandığım, gönlümün kardeleni

Ben küçücük yüreğime sığdırdım, koskocaman Alp''leri

Y.Tar.26,12,2002 Saat 23', 'Senin için yıktım, sel olup gözyaşımla dağları Yeniden yazdım, satır satır kalemimle sevdaları Senin için yok saydım, ağaları beyleri paşala...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/benim-sevdam-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağır Geldin Aşk Bana', 'agir-geldin-ask-bana-derin-oger-pui0l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sitemim var selamsız yıllara

Çok değil daha dün gibi

Göğsümde uyurdu aşkın ateşi 

Ah benim deli fikirli şu kalbim varya

Öyle derin ki anlamadım geçen günleri 

Cennet ile cinnet arasında

Adını yazmışım gönül duvarlarına

Yıksam diyorum şu içimdeki seni

Ellerin var buzdan  yüreğimi tutan

Geceler var hüznümü dudağından öpen 

Bir ayrılık ki öldürür  öldürecek zehirden

Anladım ki taşa bastım kalbimi

Yılgınım  tükendim  yoruldum bu yolda 

Ağır geldin  ağır geldin...Aşk bana..........', 'Sitemim var selamsız yıllara Çok değil daha dün gibi Göğsümde uyurdu aşkın ateşi  Ah benim deli fikirli şu kalbim varya Öyle derin ki anlama...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/agir-geldin-ask-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BU YÜZDEN', 'bu-yuzden-kadir-polat-0mhk1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen aşka aşıksın belli

endişelerle eksiltiyorsun ruhunu

Beni aşk emzirip büyüttü, 

unuttum oyunu! 

Bu yüzden ateşle su arasında yüreğim

Bu yüzden düşlerim olmaz olanı...

Tapılacak kadar güzel

Tutulamayacak kadar narin yüreğin

Bense tapınacak kadar kararlı

Dönüp arkama bakamayacak kadar korkağım! 

Bu yüzden bir bebek kadar beceriksiz dillerim

Bu yüzden elimde eğreti duruyor ellerin...

Seni rutin rüzgarlar savurmuş

dünyanın diğer yanına

Benim üzerime yıkılmış asırlık dünya

doğrulmam gerekiyor kırık bacaklarla

Bu yüzden aşk tutmalı ellerimden

Bu yüzden tutunmalıyım aşka yeniden

Bu yüzden bir yanım bahara durmuş al al

Bu yüzden yana yana kül olmuş diğer yanım

Bu yüzden dururkenki mağrurluğum, 

konuşurken ağlamaklı oluşum, 

gülerken

cam kırıkları gibi gülüşüm

bu yüzden!', 'Sen aşka aşıksın belli endişelerle eksiltiyorsun ruhunu Beni aşk emzirip büyüttü,  unuttum oyunu!  Bu yüzden ateşle su arasında yüreğim Bu y...', ARRAY['Türk Edebiyatı','Şiir','Kadir Polat']::text[], 8.5, '{"poet":"Kadir Polat","poet_slug":"kadir-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bu-yuzden-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son', 'son-atakan-arslan-otvo7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Belki sana son bakışım olacak, 

Uslanır bir yalvarış bu, erken solacak.

Yollar çoktan belirdi gözlerinde, 

Belliki benden son kaçışın olacak.', 'Belki sana son bakışım olacak,  Uslanır bir yalvarış bu, erken solacak. Yollar çoktan belirdi gözlerinde,  Belliki benden son kaçışın olacak...', ARRAY['Türk Edebiyatı','Şiir','Atakan Arslan']::text[], 8.5, '{"poet":"Atakan Arslan","poet_slug":"atakan-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/son-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paketli Ayrılık', 'paketli-ayrilik-atakan-arslan-gu575', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Paketle birlikte azalıyorsun sende, 

solan kibrit alevleri gidişine haberdar sanki.

Kapı koluna uzanıyorlar habersizce, 

seni izleyen boğulası dumanlar.

Dibinde gidişin görülüyor, 

düşerken sayısı, tütün ölüsü kağıtların.

Bir daha kimbilir ne vakit, 

dudaklarımız aynı filtrede buluşacak, 

aynı halkalardan geçireceğiz, solgun yüzlerimizi.

Dönüşün yeni bir paketle ezbeledim, biliyorum

Sonuncuda seni içiyorum...', 'Paketle birlikte azalıyorsun sende,  solan kibrit alevleri gidişine haberdar sanki. Kapı koluna uzanıyorlar habersizce,  seni izleyen boğula...', ARRAY['Türk Edebiyatı','Şiir','Atakan Arslan']::text[], 8.5, '{"poet":"Atakan Arslan","poet_slug":"atakan-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/paketli-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cevapsız', 'cevapsiz-atakan-arslan-ly4ig', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Birkaç uzun ''la''sesiydim senin için, 

Kulak çeperinde düğümlenen 

Cevapsız aramalar satırında, serice hapsedilmiş.

Kendi desiseliyle inleyen.

Eksik taşların duvarı oldum hep, 

Tamamlanamamış çeyrek gidişlerin durağı.

Hep aynı yüzümü dinlemek isterdin benim, 

Geriye sarılmış anlarda, 

Bu nedenle geçemedik ''b''yüzüme, 

Faturasız yalanlarda.', 'Birkaç uzun ''la''sesiydim senin için,  Kulak çeperinde düğümlenen  Cevapsız aramalar satırında, serice hapsedilmiş. Kendi desiseliyle inleyen...', ARRAY['Türk Edebiyatı','Şiir','Atakan Arslan']::text[], 8.5, '{"poet":"Atakan Arslan","poet_slug":"atakan-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/cevapsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçma', 'kacma-atakan-arslan-zbk1v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüzün nefesimle dargın, şu sıralarda.

Cepheni özlüyorum, kaçırdın onu benden.

Sorular gizlidir hep bir yerlerde ama; 

Anlamsızca matlaşıyorum gözlerinde, 

Belli belirsiz sözlerinde.

Dudaklarının altında açan güller, 

Zamanından önce soluyorlar, 

Salıyorlar kendilerini.

Metinlerim üzerine devriliyor, 

Koyu bir gölgeyle birlikte, 

Çekiyorsun kendini, ezilmeden gölgesinden...', 'Yüzün nefesimle dargın, şu sıralarda. Cepheni özlüyorum, kaçırdın onu benden. Sorular gizlidir hep bir yerlerde ama;  Anlamsızca matlaşıyoru...', ARRAY['Türk Edebiyatı','Şiir','Atakan Arslan']::text[], 8.5, '{"poet":"Atakan Arslan","poet_slug":"atakan-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kacma-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylece Git', 'oylece-git-atakan-arslan-rni3h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Git ama kalan birşeyle olsun senden geride, 

Yalnızlığıma açılan kırık bir pencere belkide

Hiçli anlarımda yüzüme uğrayacak sıcak bir gülüş, 

Kendine kalan bir sen olsun, 

ama içinde yine ben...

''öylece git''demeyi ne çok isterdim, 

Sen hepsini kendinde götür demeyi...', 'Git ama kalan birşeyle olsun senden geride,  Yalnızlığıma açılan kırık bir pencere belkide Hiçli anlarımda yüzüme uğrayacak sıcak bir gülüş,...', ARRAY['Türk Edebiyatı','Şiir','Atakan Arslan']::text[], 8.5, '{"poet":"Atakan Arslan","poet_slug":"atakan-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/oylece-git-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-atakan-arslan-vjs8d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gece mürekkebini dökmüş üzerine, 

Hem de her gece.

Daralan yanlızlıklara ittiği, 

Kendinden geçen yüzlercesine.', 'Gece mürekkebini dökmüş üzerine,  Hem de her gece. Daralan yanlızlıklara ittiği,  Kendinden geçen yüzlercesine....', ARRAY['Türk Edebiyatı','Şiir','Atakan Arslan']::text[], 8.5, '{"poet":"Atakan Arslan","poet_slug":"atakan-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gece-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adamdan Saymadığın', 'adamdan-saymadigin-salih-ozalasan-g2swb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen yürekten sevmek nedir bilir misin

Sadece sevmek, olmasa da bir ümidin

Sen almadan vermek nedir bilir misin

Sadece vermek olmasa da hiç bir gelirin

Sen hiç görmediğin birini sevebilir misin

Sadece sesinden ve yüreğinden tanıdığın

Sen tüm duaları unutup, tek bir ismi söyleyebilir misin

Kâlbindeki sevgili olur mu? Tanrı diye taptığın

Sen dağların ardını aşmadan görebilir misin

Gönül gözüyle oldu mu hiç uzaklara baktığın

Sen gözyaşıyla denizler yaratabilir misin

Sen bir gün ben olabilir misin, adamdan saymadığın

Y.Tarihi 27,12,2002 Saat 01,36', 'Sen yürekten sevmek nedir bilir misin Sadece sevmek, olmasa da bir ümidin Sen almadan vermek nedir bilir misin Sadece vermek olmasa da hiç b...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/adamdan-saymadigin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-caglayanin-sesi-9s3w1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kimdi o, 

kapımı çalan..? 

yapraklarımın sararmaya başladığı, 

son bahara hazırlandığım zaman...

neydi o, 

ılık ılık esen..? 

kapımı penceremi kapatıp, 

soğuğa ve yalnızlığa alıştığım, 

gökyüzüne, bulutlara, 

pencereden bakacağım an...

bunca yıldan sonra, 

Kim O..? 

26.12.2002-12: 50', 'kimdi o,  kapımı çalan..?  yapraklarımın sararmaya başladığı,  son bahara hazırlandığım zaman... neydi o,  ılık ılık esen..?  kapımı pencere...', ARRAY['Türk Edebiyatı','Şiir','Çağlayanın Sesi']::text[], 8.5, '{"poet":"Çağlayanın Sesi","poet_slug":"caglayanin-sesi","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/umut-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara Soğuk', 'ankara-soguk-hafize-zuluflu-pt8n7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bildiğin gibi değil bu mevsim buralar

Ankara soğuk,  kar

Sokaklar kaldırımlar buz

Kristale dönmüş bütün ağaçlar

Ama bu kış bu ayaz işlemiyor içime

yokluğun kadar

Sorma

Ankara’da trafik hızlı

AB’ye giriş, Kıbrıs sorunu

Amerika, Irak

Saddam, operasyon

Gündemde olası bir savaş var

Fakat hiçbiri vahim değil onbeş dakikalık

Bir görüşmeden sonra gidişin kadar

Şimdi ruhum hapislerde

Dünya zindan, her yer bana dar...

Ne olursa olsun

Yıldırmaz yüreğimi bu azap, bu sensizlik

Çünkü seni severken ayrılıkları göze aldım yar

Rüyama girdiğin gecelerin ardından

Her yeni günde sensizliğe uyanmak zor

Sol gözüm seğiriyor

Belki de senden bir haber var....', 'Bildiğin gibi değil bu mevsim buralar Ankara soğuk,  kar Sokaklar kaldırımlar buz Kristale dönmüş bütün ağaçlar Ama bu kış bu ayaz işlemiyor...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ankara-soguk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor', 'zor-hasan-sami-emiroglu-t8y3y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sair olmakta zor, arif olmakta

Zaman coktan gecti, vadem dolmakta

Zor olani sectim nedense bende

Gönlüm sevda ile oyalanmakta...

Düsseldorf.2002', 'Sair olmakta zor, arif olmakta Zaman coktan gecti, vadem dolmakta Zor olani sectim nedense bende Gönlüm sevda ile oyalanmakta... Düsseldorf....', ARRAY['Türk Edebiyatı','Şiir','Hasan Sami Emiroğlu']::text[], 8.5, '{"poet":"Hasan Sami Emiroğlu","poet_slug":"hasan-sami-emiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/zor-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimyasal Aşk', 'kimyasal-ask-huseyin-i-sbasar-d1h7o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yanıyor kalbim hızla 

belkide kükürtlü gazla

seviyorum seni ben 

sülfürik asitten fazla

kızıl bakır renginde 

o dudakların senin

ne olur bir öpücük 

karbonat kokan sevgilim

sana olan aşkımda 

reaksiyon var benim

gerekirse uğrunda 

elektron veririm

seni görmeden eğer ben

ölürsem sevgilim 

ufacık bir denklem yaz

mezar taşıma benim', 'yanıyor kalbim hızla  belkide kükürtlü gazla seviyorum seni ben  sülfürik asitten fazla kızıl bakır renginde  o dudakların senin ne olur bir...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin İşbaşar']::text[], 8.5, '{"poet":"Hüseyin İşbaşar","poet_slug":"huseyin-i-sbasar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kimyasal-ask-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebeğim', 'bebegim-aslihan-erdal-watrt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Büyüyorsun bebeğim, 

Hem de öyle güzel büyüyorsun ki sana baktıkça şükrediyorum Tanrıya, 

Böyle bir güzelliği bana bahşettiği için...

Gözlerinde geleceği görüyorum.

Zeytin karası olsa da mavi mavi parlıyorlar çünkü mavi umudu anlatıyor.

Ve ben senin gözlerinde o bitmeyen, tertemiz ve en saf haliyle sevgiyi görüyorum.

Büyüyorsun bebeğim, önünde upuzun bir hayat var.

Hüznü de, sevinci de doya doya yaşayacağın, ağlayıp güleceğin, seveceğin, sevileceğin bir hayat.

Sürprizin, binlerce seçeneğin olduğu bir hayat...

Biliyorum yüreğinle yaşayacaksın hayatı, çünkü bana benziyorsun.

Duygularının gösterdiği yoldan ayrılmayacaksın biliyorum.

Asla zayıflık değildir duygularla yaşamak; aksine duygularını bilen, onların sesine kulak verebilen ayakta kalır hayatın acımasızlığında.

Zaman zaman tökezlesen de, yine sarılacaksın duygularına ve onlara tutunup kalkacaksın ayağa, 

Duygularına sahip çıktıkça yüzündeki o eşsiz gülümseme hiç terk etmeyecek seni...

Yarını unutmayacaksın ama yarına bağlı kalmayacaksın.

Söylemek istediğin her şey, söylemek istediğin an dökülecek dilinden.

Yapmak istediğin her şey, yapmak istediğin an gerçekleşecek.

Sen ''keşke'' diyenlerden de olmayacaksın.

Unutma bebeğim, en büyük pişmanlık isteyip da yapamadığın şeyler için duyulan pişmanlıktır.

Büyüyorsun bebeğim, yüreğin de büyüyor.

Kimler girecek o yüreğine sen seçeceksin.

Sevgini sadece hak edenlere vereceksin.

Duygularını hor kullanmak isteyenlere ''DUR'' diyeceksin.

Sen ''AŞK'' çocuğusun.Aşkla doğdun, aşkla büyüyorsun.

Bu yüzden her zaman sahip çıkacaksın aşka.

Senin kadar değer vermiyorlarsa eğer, uzak tutacaksın onları.

Senin dünyan öylesine büyük ki, küçük düşünceli insanlar algılayamayacak o büyüklüğü.

Kaçacaklar.Kovalama sakın! Korkaklar sana göre değil...

Büyüyorsun bebeğim, ben de seninle büyüyorum.

Bak 12 yıl geçti bile...

Çocukluktan çıkacaksın yakında ama kaybetme içinde ki çocuğu.

Bırak seninle birlikte yaşasın o da ömrünün sonuna dek.

Senin meleğindir o, en sıkıntılı anında bir tek içindeki o çocuk yardım edecektir sana...

Büyüyorsun bebeğim ve ben her yıl olduğu gibi bu yıl da 

içimdeki sevgiyi hediye ediyorum sana....

Kızım, canım, doğum günün kutlu olsun ve ''aşk'' hep seninle olsun...', 'Büyüyorsun bebeğim,  Hem de öyle güzel büyüyorsun ki sana baktıkça şükrediyorum Tanrıya,  Böyle bir güzelliği bana bahşettiği için... Gözler...', ARRAY['Türk Edebiyatı','Şiir','Aslıhan Erdal']::text[], 8.5, '{"poet":"Aslıhan Erdal","poet_slug":"aslihan-erdal","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bebegim-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitik Hayat', 'yitik-hayat-mustafa-sahiner-edajb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerini kaparken serin akşamlarda

Hasreti kovalarken şehrin yollarında

Geride bıraktıklarını hep hatırladığında

Ben gelmeliyim aklına, gözlerim gelmeli

Unuturken dertlerini yorgun dünyanın

Söylerken şarkısını yitik hayatın

Dinlerken sesini koyu karanlığın

Ben gelmeliyim aklına, gözlerim gelmeli

Gün kızıla dönerken mavi okyanusta

Güller solarken sevginin çıkmazlarında

Beklerken gemiler dostluğu kayıp limanlarda

Ben gelmeliyim aklına, gözlerim gelmeli', 'Gözlerini kaparken serin akşamlarda Hasreti kovalarken şehrin yollarında Geride bıraktıklarını hep hatırladığında Ben gelmeliyim aklına, göz...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Şahiner']::text[], 8.5, '{"poet":"Mustafa Şahiner","poet_slug":"mustafa-sahiner","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yitik-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünmek', 'dusunmek-i-hsan-topcu-dii1p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir ülke düşün / düşün ki

içerdekiler dışardakilerden namuslu

bir ülke düşün

düşün ki al başına belayı', 'bir ülke düşün / düşün ki içerdekiler dışardakilerden namuslu bir ülke düşün düşün ki al başına belayı...', ARRAY['Türk Edebiyatı','Şiir','İhsan Topçu']::text[], 8.5, '{"poet":"İhsan Topçu","poet_slug":"i-hsan-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dusunmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Çıkar', 'ne-cikar-fazil-husnu-cakiroglu-22sb4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Savur dur yapragi rüzgar

Dalindan düstükten sonra

Ne cikar! 

Tastan tasa vur

Yada bir kuytuya biraki ver.

Ok! geri cagir attigini

Saat tut saniyeni.

Icine ne koyarsan testinin

O dökülür bardagina

Bilmezmisin? 

Hadi cal kasigini bulanik bir suya 

Belki bu defe

Farkli birsey cikar sana.

Karamasanin yazgisi hep atesse

Eller ne yapsin? 

Ve bir küp testine bekleyenler gibi

Eksimis cikacaksa sözler

Habire yutkunmalimi dersin

Durmadan doguran harfleri.

Isigi söndür….

Bütün kuslari kafese koy

Hatta kanatlarini yol.

Eger becerebilirsen 

Rüzgarada kilit vur.

                            11.11.1997

                                 sali', 'Savur dur yapragi rüzgar Dalindan düstükten sonra Ne cikar!  Tastan tasa vur Yada bir kuytuya biraki ver. Ok! geri cagir attigini Saat tut s...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Çakıroğlu']::text[], 8.5, '{"poet":"Fazıl Hüsnü Çakıroğlu","poet_slug":"fazil-husnu-cakiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ne-cikar-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzerim Akıntıya Karşı', 'yuzerim-akintiya-karsi-fazil-husnu-cakiroglu-wla1q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tas devrine götürüp

Yeniden sekillendirmelimi? 

Bir tas gibi duran gövdemi

Yoksa tunc caginda

Eritip bastan kalibami dökmeli? 

Bunlari bilmiyorum ama

Bildigim bir sey var

Bir ömrün bir ölüme az geldigi.

Öyleyse kac kera yikayip asmali

Lekesi cikmayan gövdeyi

Bilmedigim ne cok sey var

Kimselerin söylemedigi.

Yüzerim akintiyi karsi

Ama bilmem 

Ben bir alabalik degilim.

Oysa ne cok sey varmis bildigim

Kimselere söylemedigim

Olmasamda bir alabalik

Yüzerim iste akintiya karsi

Ama düsünürüm, 

Alabaligi alabalik yapan

Akintiya karsi yüzüsümüdür? 

Yoksa akintiyi akinti yapan 

Baligin yüzüsümüdür.', 'Tas devrine götürüp Yeniden sekillendirmelimi?  Bir tas gibi duran gövdemi Yoksa tunc caginda Eritip bastan kalibami dökmeli?  Bunlari bilmi...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Çakıroğlu']::text[], 8.5, '{"poet":"Fazıl Hüsnü Çakıroğlu","poet_slug":"fazil-husnu-cakiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yuzerim-akintiya-karsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkularim', 'korkularim-fazil-husnu-cakiroglu-dczk7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gecenin icinde cirkin

Gecenin icinde kuvetli

Tarafsiz uzayan parmaklardan

Tenime dokunan ürperti

Bir düsten arta kalan zamanda

Avuclarimda kalan yok

O yokun icinde de cok

Korkularim.', 'Gecenin icinde cirkin Gecenin icinde kuvetli Tarafsiz uzayan parmaklardan Tenime dokunan ürperti Bir düsten arta kalan zamanda Avuclarimda k...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Çakıroğlu']::text[], 8.5, '{"poet":"Fazıl Hüsnü Çakıroğlu","poet_slug":"fazil-husnu-cakiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/korkularim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmaya Çalışın', 'unutmaya-calisin-fazil-husnu-cakiroglu-ifq7m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Unutmaya calisin

Yada yerini degistirin Bazi seylerin

Anlamak icin babanizi

Yerine koyun kendinizi

Yada oglunuz olun

Icine kapanan bir masa gibi

Icinize kapanin

Yada bir kitabin teli gibi

Sayfadan sayfaya gezin yasadiklarinizin

Karanlikta nekadar kendidir hersey

Kalabalikta odur insan

Eskir maskelerimiz

Degistikce rollerimiz

Ve gözlerimiz, ellerimiz

Kanina girdigimiz

Nice günlerimiz, 

Vaktini bekler

Acilip kapanan bir sandikta

El degmemis saatlerimiz

Sikilir zamanda

Bu yüzden 

Bir kisalir bir uzar.', 'Unutmaya calisin Yada yerini degistirin Bazi seylerin Anlamak icin babanizi Yerine koyun kendinizi Yada oglunuz olun Icine kapanan bir masa ...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Çakıroğlu']::text[], 8.5, '{"poet":"Fazıl Hüsnü Çakıroğlu","poet_slug":"fazil-husnu-cakiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/unutmaya-calisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamdan Bir Kesit', 'yasamdan-bir-kesit-fazil-husnu-cakiroglu-i5mga', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben filimleri hayal zannederdim

Oysaki hayatin bir kesiti.

Acilar sevincler hep sarkilarda türkülerde olurdu

Yanilmisim hayatin takendisi imis aci ve sevgi.

Yol aldikca mesafeler de büyüyor

Öylesine ki ¡

Bazan ardimizi göremiyoruz

Ne bir ses ne bir görüntü.

Beklenmedik bir anda calan telefonun ucunda

Bugulu bir ses ve hersey bundan ibaret.

Kayip giden yildizlar gibi devrilir sayfalar

Ve arasinda birikir bir yasammisligin özeti

Okudukca yasartir gözleri

Bazen hancer gibi sözleri.

Silik yazilar soluk resimler

Sesini yüzünü animsamadigin dostlardan izler.

Beraberce yasanan onca güzellikler

Devrilen sayfalar arasinda kaybolup gider.', 'Ben filimleri hayal zannederdim Oysaki hayatin bir kesiti. Acilar sevincler hep sarkilarda türkülerde olurdu Yanilmisim hayatin takendisi im...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Çakıroğlu']::text[], 8.5, '{"poet":"Fazıl Hüsnü Çakıroğlu","poet_slug":"fazil-husnu-cakiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yasamdan-bir-kesit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duruluş', 'durulus-fazil-husnu-cakiroglu-slksb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Boslugun ötesinde bir yerdesin

Zaman kavramini kaybetmis

Saatlerin durdugu

Canlarin calmadigi bir yerde

Düsünceler donuk ve mat

Kaygilandirmiyor insani gelecegin endisesi

Bilinmez nerde biter insanin nesesi

Koyver zamana karsi koy ver

Sana verdigini yüzüne calarcasina

Bak gelip geciyor iste insafsizca', 'Boslugun ötesinde bir yerdesin Zaman kavramini kaybetmis Saatlerin durdugu Canlarin calmadigi bir yerde Düsünceler donuk ve mat Kaygilandirm...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Çakıroğlu']::text[], 8.5, '{"poet":"Fazıl Hüsnü Çakıroğlu","poet_slug":"fazil-husnu-cakiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/durulus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Aradım', 'seni-aradim-hakki-hakan-kaya-rz7zz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ansızın çekip gittiğinden beri, 

Günlerde günlerce seni aradım.

Sevdiğimi bir kez söyleyemeden, 

Seslerde sessizce seni aradım.

Anası vurulmuş elik gibi, 

Yeni doğmuş bebek gibi, 

Sanki birden gelecek gibi, 

Yüzlerde yüzsüzce seni aradım.

Gönül bağlarımı bağladığımda, 

Hasretine sarılıp ağladığımda, 

Dönüşşüz gittiğini anladığımda, 

Anılarda umutsuzca seni aradım.

Şimdi hiçbir yaram kabuk bağlamaz, 

Geceme gündüz ışık sağlamaz, 

En kor alevler etimi dağlamaz, 

Ölmeden ölümü sende tanıdım.', 'Ansızın çekip gittiğinden beri,  Günlerde günlerce seni aradım. Sevdiğimi bir kez söyleyemeden,  Seslerde sessizce seni aradım. Anası vurulm...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seni-aradim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yumuk gözlüm', 'yumuk-gozlum-seyit-ahmet-duzen-mirb8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Endişeli, tedirgin durma n’olur.

Bir daha terketmek yok

Severek ayrılmak yok

Kar yağıdığında mevsime

Üşüdüğünde yanında olacağım

Geçmişi unut 

Yumuk gözlerinle gül yine...

Senin için dönüyorum bu kez...

Yağmurlardan uzak şehre

Kar yağıyorum.

Bir bavul dolusu hasretinle

Düştüm yollara

Arıtlımış saf sevgi getiriyorum.

Uzunca zaman burdayım.

Ağlama kar beyaz yüreğin

Esmer güzeli....

Yumuk gözlerinde ceylan besleyen

Sevgilim üzülme...', 'Endişeli, tedirgin durma n’olur. Bir daha terketmek yok Severek ayrılmak yok Kar yağıdığında mevsime Üşüdüğünde yanında olacağım Geçmişi unu...', ARRAY['Türk Edebiyatı','Şiir','Seyit Ahmet Düzen']::text[], 8.5, '{"poet":"Seyit Ahmet Düzen","poet_slug":"seyit-ahmet-duzen","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yumuk-gozlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lodoslomalar', 'lodoslomalar-kemal-aslan-978uf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1

kusar  sevgisini

arzusu hırçın 

2

bırakmaz 

sarhoş edinceye kadar 

3

yorulunca dudakları

gözü yaşlanır

4

gidince izi

kıyıda kalır', '1 kusar  sevgisini arzusu hırçın  2 bırakmaz  sarhoş edinceye kadar  3 yorulunca dudakları gözü yaşlanır 4 gidince izi kıyıda kalır...', ARRAY['Türk Edebiyatı','Şiir','Kemal Aslan']::text[], 8.5, '{"poet":"Kemal Aslan","poet_slug":"kemal-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/lodoslomalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşçakal Perisu', 'hoscakal-perisu-ozlem-ertas-ey2lf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey yerlerin ve göklerin en zalim sevgilisi, 

Buraya kadarmış biliyorum

Bütün ordularım senin için çalıştılar, artık 

Bütün şiirler, şarkılar biraraya gelse getiremez seni.

Dudağını bükme Perisu beni gördüğünde, 

Gidiyorum artık Perisu, bundan sonrası yok, 

Bunlar son kurşunum sana özlemim.

Zamanında tüm ümitlerin tükenmişti, 

Acımasız oldun şimdi bukadar.

Böylesi güzel bir aşkı yaşattığın için teşekkürler.

Üzgünüm gerçek aşkın olamadığım için, 

Üzgünüm olanlar için, 

Unutmayacağım seni hiç, 

Hatırla beni eskiden olduğum halimi, 

Teşekkürler aslan yürekli Perisu.

Büyülü bulutlar salsamda senin adına hergün, 

Üç binyılın özlemi var saçlarının neminde, 

Artık kurşun değmezmi sana başka sevgilin var diye, 

Artık hiçbir yağmur ıslatmazmı seni, 

Bu rüzgarlar üşütmezmi seni.

Şiirlerinden fal tutuyorum her özlediğimde seni, 

Birgün 44 çıkıyor birgün Sönmeyecek umut, 

Mavi gözlerinden Ankara akar, Ankara''da özlemim, 

Radyoda Yaşar çalıyor gönlümde sen, 

Hatırla beni eskiden olduğum halimi.

Gidiyorum artık Perisu bundan sonrası yok, 

Yüzsüzlüğü bırakmanın zamanı geldi, 

Dönsende istemiyorum artık seni, 

Ne sen Leyla''sın nede ben Mecnun amma, 

Yeniden başlamak zor bundan sonra.

Hoşçakal Perisu, hoşçakal mavi gözlü sevgisu, 

Şimdi anılarıda ver mahkemeye, 

Hayret ettiğin şeyler gibi bulutsu.', 'Ey yerlerin ve göklerin en zalim sevgilisi,  Buraya kadarmış biliyorum Bütün ordularım senin için çalıştılar, artık  Bütün şiirler, şarkılar...', ARRAY['Türk Edebiyatı','Şiir','Özlem Ertaş']::text[], 8.5, '{"poet":"Özlem Ertaş","poet_slug":"ozlem-ertas","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/hoscakal-perisu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meşhur Dünya', 'meshur-dunya-louis-aragon-ek8nk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu mevsim insanlar

Taş gözlü korku ayaklılar

Gözbebeklerindeki rüyalar

Kafeste vahşi hayvanlar

Manzaranın tozu

Ateş ve demir

Günün büyük oyunu

Eski talanlara direnir

Kuruntusuz ormanda

Gidiyor kurtlar kadife adımlarla

Her günün Vebasıdır

Güneşin canavarlığında

Ayıp ve zafer arasında tutku

Ve inkarcılık arasında umut

Adaletin terazisi

Yanlışların lanetli kitabında

Nehrin güvensiz geçidindeyiz

Yaşayanlardan ölülere giden

Pişmanlıkların asma köprüsünden

Ölülerden yaşayanlara giden

Kalp ve gömlek arasında

Yer var sadece bıçağa

Tez mi geç mi

Her şey ihanetin tadında

Züllümün gizli rüzgarı

Acayip döndürdü başları 

Ne dileniyor bu kişiler

Sözlerin ayrılığında', 'Bu mevsim insanlar Taş gözlü korku ayaklılar Gözbebeklerindeki rüyalar Kafeste vahşi hayvanlar Manzaranın tozu Ateş ve demir Günün büyük oyu...', ARRAY['Türk Edebiyatı','Şiir','Louis Aragon']::text[], 8.5, '{"poet":"Louis Aragon","poet_slug":"louis-aragon","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/meshur-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökyüzünde Salınırken', 'gokyuzunde-salinirken-mustafa-dillioglu-m9i1a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gökyüzünde salınırken tellere takılan uçurtmamdın sen

Elimden kaçırdığım balonum

En sevdiğim misketimdin çaldırdığım

Az ağlamadım ardından

Sen, yitirdiklerimin en güzeliydin', 'Gökyüzünde salınırken tellere takılan uçurtmamdın sen Elimden kaçırdığım balonum En sevdiğim misketimdin çaldırdığım Az ağlamadım ardından S...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Dillioğlu']::text[], 8.5, '{"poet":"Mustafa Dillioğlu","poet_slug":"mustafa-dillioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gokyuzunde-salinirken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Oyun Burada Biter', 'bu-oyun-burada-biter-mustafa-dillioglu-4h311', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu oyun burada biter

Sen soldan çıkarsın

Ben kalakalırım ortasında sahnenin

Perde kapanır kalakalırım 

açılana dek...', 'Bu oyun burada biter Sen soldan çıkarsın Ben kalakalırım ortasında sahnenin Perde kapanır kalakalırım  açılana dek......', ARRAY['Türk Edebiyatı','Şiir','Mustafa Dillioğlu']::text[], 8.5, '{"poet":"Mustafa Dillioğlu","poet_slug":"mustafa-dillioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bu-oyun-burada-biter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnce Bir Islık', 'i-nce-bir-islik-mustafa-dillioglu-qaa79', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnce bir ıslık sesi kulaklarımda

Bir martı selamlıyor balıkçı teknesini

Geceyi kovalarken güneş

Uzaklıklar belirginleşiyor

Dinginliği haykırıyor deniz

Ellerimde kum taneleri

İnce bir ıslık sesi kulaklarımda

Ben vardım sahilde

Semniydin

Güneşi bekleyen gözlerimde

Bizde oradamıydık

Sürüklernirken kumlarda kayık

Denizi anımsar gibiyim

ya martılar

ya çığlık

Seraplar yalnız çöllerin malıdır kitaplarda

Ya benim olanlar

dalgalarda varmıydı

Hani güneş doğuyordu demin

Karanlığın hükmü hala gözlerimde

Hani  ellerim

Hani kum

Hani sen

Parça parça ellerimden yıldızlar gizi kayarken sen

Sahi kumsalda mıydın', 'İnce bir ıslık sesi kulaklarımda Bir martı selamlıyor balıkçı teknesini Geceyi kovalarken güneş Uzaklıklar belirginleşiyor Dinginliği haykır...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Dillioğlu']::text[], 8.5, '{"poet":"Mustafa Dillioğlu","poet_slug":"mustafa-dillioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ince-bir-islik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Beni Bul', 'bugun-beni-bul-mustafa-dillioglu-hpzzj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bugün beni bul

bir telefon

istersen güvercin kullan

Bugün beni bul

yemek yiyelim

birlikte

çay içelim

Bugün beni bul

ki bulasın diye 

en yakınlarındayım

gözlerinin içinde

yüreğinde

Bugün beni bul

bak aynaya

kapa gözlerini

ben bul

Bu şehirden gitmiyorsam

beni bulabilesin diyedir', 'Bugün beni bul bir telefon istersen güvercin kullan Bugün beni bul yemek yiyelim birlikte çay içelim Bugün beni bul ki bulasın diye  en yakı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Dillioğlu']::text[], 8.5, '{"poet":"Mustafa Dillioğlu","poet_slug":"mustafa-dillioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bugun-beni-bul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Etkileşim', 'etkilesim-fikret-esmerok-j3aqh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İşte doğa, 

İşte ben, 

İşte biz, 

İşte ellerimiz...

Birbirinden ayrılmayan

Bir bütünüz hepimiz.

İç içe, 

Dış dışa, 

Etkiliye, 

Etkilene, 

Başlangıçsızlıktan, 

Sonsuzluğa akıyoruz.

Bir büyük usta

Bitimsiz bir duvar örüyor.

Ördükçe öğreniyor, 

Öğrendikçe, 

Daha güzel örüyor.', 'İşte doğa,  İşte ben,  İşte biz,  İşte ellerimiz... Birbirinden ayrılmayan Bir bütünüz hepimiz. İç içe,  Dış dışa,  Etkiliye,  Etkilene,  Ba...', ARRAY['Türk Edebiyatı','Şiir','Fikret Esmerok']::text[], 8.5, '{"poet":"Fikret Esmerok","poet_slug":"fikret-esmerok","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/etkilesim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Kimi İçmiş', 'kim-kimi-i-cmis-oguz-alniacik-1g6j9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Lodos yemiş balık gibi masada

Şişede koç yumurtası sanki

Dili fırın küreği

Küllükte yanan üç sigara

Kravatı beline bağlamış

Ehliyeti var araba sürecek

Karısı yanında iki gözü iki çeşme

Adam adam değil ki 

Langa hıyarı

Kat yoğurda cacık yap

Rakı adamı içmiş', 'Lodos yemiş balık gibi masada Şişede koç yumurtası sanki Dili fırın küreği Küllükte yanan üç sigara Kravatı beline bağlamış Ehliyeti var ara...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Alnıaçık']::text[], 8.5, '{"poet":"Oğuz Alnıaçık","poet_slug":"oguz-alniacik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kim-kimi-icmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esrarlı Bir Zamandan Kalan Dostluk', 'esrarli-bir-zamandan-kalan-dostluk-huseyin-cayikli-8bqp3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ESRA icin

seni dusundugumde

elinde lolipop sekeri olan

yaramaz bir kiz cocugu aklima gelir

oysa ben cocukluktan beri o kadar 

yorgunum ki

simdi koca koca evler cizsemde

buyuk laflar etsemde 

o kiz cocugunu goremem 

o zamanlara bir daha gidemem

ne kadar zamani tuketsekte 

senle ben... 

aklima  eski bir tiyatro oyunu 

cok eski bir zamanlarda paylasilan 

beraber duslerin ulkesine acildigimiz

bir ulkenin pencersinden baktigimizda

geride kalanlar 

olmayan fotograflarda kalan siyah beyaz anilar

adinin ne kadar esrarli birsey oldugu hatirlatir

hayat boyu gul tamam mi cocuk gozlerinle Esra...

bir dost.', 'ESRA icin seni dusundugumde elinde lolipop sekeri olan yaramaz bir kiz cocugu aklima gelir oysa ben cocukluktan beri o kadar  yorgunum ki si...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/esrarli-bir-zamandan-kalan-dostluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalemim Bitmek Üzere', 'kalemim-bitmek-uzere-turgay-kaygi-qrui7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kalemim bitmek üzere! 

ve sanırım az sonra

ağlayacağım

biteceği yere kadar yazıp

ardından

tükenen kalemimin 

yasını tutacağım

siyahı severim ben

çok hem de

bir ara

bir daha

hiç sevemeyeceğim sandım

siyahı

bir çift

kahve

rengi gözde

gördüğümü

geleceğim 

sandım

ve

öleceğim sandım

çözene kadar

bu kördüğümü

şimdi

kadehimi 

‘sokakta bas bas bağıran

serserinin şerefine’

kaldırıyorum...

ve

artık

ne yaşaran gözlerime

ne de aynadaki

mütecaviz bakışlara

aldırıyorum...

kalemim bitmek üzere! 

bir yerlerde kaynayan

kazanımın fokurtusu

geliyor kulağıma; 

duyabiliyorum...

elimden ne gelir? ; 

maymundan türemiş olma fikrine

katılmasam bile

“şu anda çağırıyor olsalar; 

Nuh’un gemisine, 

‘ben gelmiyorum! ’ 

derdim! ”

diyebiliyorum...

kalemim bitmek üzere! 

boşaldıkça

göz yaşlarımla doluyor kadehim; 

bu kadeh de 

‘fırtınalı gecelerde

kahır yüklü gemilerime

koynunu açan

müşfik limanların’ şerefine! 

dostlardan bahsederken

hiç gelmeyecekmiş gibi

ne kadehin

ne şişenin dibi

ve

hiç bitmeyecekmiş gibi

mürekkebi 

kalemimin...

kalemim bitmek üzere! 

derken! 

 “sigara dumanı çıksın! ”

diye

açtığım pencereden

‘umut’; 

hastasının ayağına gelen

doktor misali

bir anda

süzülüp

girebiliyor...

ve

kafiye denen

uğursuz rüzgar

silebiliyor

yaşını

gözlerimin...

izin verirseniz

‘gittiği yerde

dönmeyi düşünmeyenlere’

kaldıracağım kadehimi; 

‘bittiği yerde

yeniden başlayanların’

şerefine! ..

kalemim bitmek......

(inegöl,  26.12.2002)', 'kalemim bitmek üzere!  ve sanırım az sonra ağlayacağım biteceği yere kadar yazıp ardından tükenen kalemimin  yasını tutacağım siyahı severim...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kaygı']::text[], 8.5, '{"poet":"Turgay Kaygı","poet_slug":"turgay-kaygi","theme":"Türk Şiiri","is_hero":false,"total_lines":89,"source_url":"https://www.antoloji.com/kalemim-bitmek-uzere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müstear', 'mustear-suna-edip-5qzca', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Suna Edip, 

kağıda düştüğüm

(g) izim.', 'Suna Edip,  kağıda düştüğüm (g) izim....', ARRAY['Türk Edebiyatı','Şiir','Suna Edip']::text[], 8.5, '{"poet":"Suna Edip","poet_slug":"suna-edip","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/mustear-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Her Gece', 'ben-her-gece-nihan-yuzel-pxiar', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şehrin tüm ışıklarını söndürüp

Yüreğimin derinliklerine gömerim kendimi

Sessiz çığlıklar atarım

Duyulmaz

Tüm günahlarımı haykırırım 

Hiç bilen olmaz

Ve sonra ayrılık şarkıları söylerim geceye

Ağlamam ama 

Ağlamışçasına yanar gözlerim

Ben her gece

Hatıralarımla birlikte ayrılık şarkıları söylerim

Kimse duymaz çığlıklarımı

Uykuları yasaklarım kendime

Sonra isyan ederim herşeye

Yıldızlara her baktığımda uzakları hatırlarım

Sonra dolar gözlerim

Ağlamam

Uykusuz düşler görürüm hep

Kaldırımlara sererim yalan günahlarımı

Sonra

Şehrin tüm ışıklarını söndürüp

Yüreğimin derinliklerine gömerim kendimi

Sessiz çığlıklar atarım

Geceye ait ne varsa kalemimde

Yokluğuna yazarım bir bir

Üşümekli olur sesim

Karanlığa yüklerim hasretimi

Güneşleri beklemem sabahlarıma

Gecelere yazarım içimde ne varsa

Kayıp cümlelerimi ararım gecenin koyusunda

Düşünmek olur tek bildiğim

Sen olmaktan korkarım uzaklarda

Nefes almak zor gelir

Seni koklarım hayalinde

Hasret kokarsın buram buram

Gecenin rengi değişir sana kayıp zamanlarda

Şehrin tüm ışıklarını söndürüp

Yüreğimin derinliklerine gömerim kendimi

Kayıplığını ararım bendeki

Yokluğun sarar bedenimin dört yanını

Korkutur yalnızlığım 

Ağlayamam

Yakar yüreğimi eski sızılar

Yeni hasretler eklenir ardından yokluğuna

Dolar gözlerim

Hatıralarımla birlikte geceye ayrılık şarkıları söylerim...', 'Şehrin tüm ışıklarını söndürüp Yüreğimin derinliklerine gömerim kendimi Sessiz çığlıklar atarım Duyulmaz Tüm günahlarımı haykırırım  Hiç bil...', ARRAY['Türk Edebiyatı','Şiir','Nihan Yüzel']::text[], 8.5, '{"poet":"Nihan Yüzel","poet_slug":"nihan-yuzel","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/ben-her-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-nihan-yuzel-vbqca', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Susmak acı verir insana

Ama bazen susmalıdır bakışlar

Terk edilmeye alışmalıdır insan

Yada aldatılmaya

Bayat bir hayattır yaşadığımız

Ağladığımızsa 

Birkaç damla gözyaşı

Kim bilir kimlerin ahları vardır bu hayatta

Kimler gömülmüştür bembeyaz hatıralarla

Değer mi

Yada değer miydi bu yalana? 

Terk edilmeli midir her seven

Öyleyse bile

Hiç insan değil midir sevilen

Sızlamaz mı hiç vicdanı

Korkmaz mı

...

Bu kadar kolay olmamalı ölüm

Yıkmamalı bir tek kurşun hayalleri

Ağlamamalı geride kalanlar

Yada ağlatmamalı giden

...

Öyleyse sevme beni

Hem de hiç sevme

Ardından ıslak kalacaksa gözlerim

Ve üşütecekse rutubetli geceler bakışlarımı

Yalnızlık vuracaksa gecenin bir yarısı beynime

Hiç gelme uzaklardan

Bırak da hayalimde yaşasın sıcak akşamlar

Öldürme ölümsüz sevdamı

Yıkıp da gitme hayallerimi

...

Yada sev 

Sımsıkı sarıl gecelerime

Şarkılar söyle gözlerinle ıslanmış akşamlara

Unuttur acı olan ne varsa

Sonra

Sonra eskileri hatırlat

Ama ölüm olmasın

Zira bir defa ölüyor insan

Bin kere öldürme

...

Uzaklardan yağmur sesleri geliyor kulağıma

Hadi sırılsıklam ıslanmalıyız

Göz göze gelmeliyiz arada bir

Buluşmalı bakışlarımız

Ve tutmalısın ellerimi

Ve haykırmalıyım

Uçsuz bucaksız uçurumlardan

SENİ SEVİYORUM...', 'Susmak acı verir insana Ama bazen susmalıdır bakışlar Terk edilmeye alışmalıdır insan Yada aldatılmaya Bayat bir hayattır yaşadığımız Ağladı...', ARRAY['Türk Edebiyatı','Şiir','Nihan Yüzel']::text[], 8.5, '{"poet":"Nihan Yüzel","poet_slug":"nihan-yuzel","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/seni-seviyorum-104-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu İlk Olmayışın Değil Yanımda', 'bu-i-lk-olmayisin-degil-yanimda-nihan-yuzel-8aglc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaç iklim geçti sen gideli 

Saymadım.

Alışamadım yanlızlıklara

Uzatıyorum üşümekli ellerimi gökyüzüne

Ve ağlıyorum karanlık sabahlara

Sen benden gideli gecelere attım gündüzlerimi

Saçlarımı rüzgara verdim

Gözlerimse çaresizliğe mühürlendi

Kurabildiğim tek cümle

‘Beklemek’

Gelmezliğe uğurladıklarımı

Yada hiç gitmeyenlerimi

Sen gideli ne çok mevsim değişti seni özlemelerimde

Her gece çıldırta yalnızlığı alıp koynuma, 

Gelmelerine dair hayaller kurdum; hayallerde kaldık.

Temiz duygularımız kaldı mühürlü gözlerimizde.

Gelmezliğe uğurladım seni

Tek aldanışım; geleceğini beklemek.

Bıkmadım.

Bıkmamda.

Alışamadım ama, alışmış gibi yapıyorum

Sen benden gideli

Gecelere attım gündüzlerimi

Seni, beni ve yalnızlığımı alıp yanıma

Gelmezliğe uğurladıklarımı

Yada 

Hiç gitmeyenlerimi bekliyorum...', 'Kaç iklim geçti sen gideli  Saymadım. Alışamadım yanlızlıklara Uzatıyorum üşümekli ellerimi gökyüzüne Ve ağlıyorum karanlık sabahlara Sen be...', ARRAY['Türk Edebiyatı','Şiir','Nihan Yüzel']::text[], 8.5, '{"poet":"Nihan Yüzel","poet_slug":"nihan-yuzel","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bu-ilk-olmayisin-degil-yanimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoruldum', 'yoruldum-nihan-yuzel-2714p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bugün bir sayfayı daha yırtıp attım hayatımdan

Ve gülümsediğim tüm fotoğraf karelerindeki bakışlarını

Ve seni erkek yüreklim

Ve seni

...

Öyle uzak kokar ki yokluğun umutlarıma

O kadar asidir ki bakışlarım

Ve sen o kadar yalnızsındır ki

Anlatma yaşadıklarını

...

Bu hüznüm gidişine mi? 

Yoksa yalnız kalışım mı? 

İnan ki bilmiyorum

Bilmiyorum artık

...

Bir iki damla ağlıyorum arada bir

Nerde olduğunu bilmiyorum düşlerimin

Ve kiminle

...

Bakışlarını topladım dün gece hayatımdan

Ve sevişini

Karanlıksın

Kopkoyu bir yalnızlığın var yüreğimde

Tüm kapılarını kapattım seni sevmelerimin

Hiçbir ışık yanmaz artık yüreğimde

...

Sonbahar düştü gidişinle gözlerime

Kuru yapraklar gibi sararıp soldu hayallerim

Birkaç gülümseme sığdırdım hayatımın eski karelerine

Senide geçmişe karaladım artık

Hiçbir umudum kalmadı geleceğine

Yaşlandı tüm duygularım

Yoruldum

...

Nerelere gittin yüreğimden habersiz? 

Ve gözlerimden

Uzaklara mı yar oldun

Ondan mıdır yıkılışım, 

Ondan mıdır kahroluşum

...

Dönme erkek yüreklim

Hiç dönme

Yitik bir sevda artık bendeki

Her gece sızlatan yüreğimi

Ve ağlatan

...

Yalnızım

En çokta sensiz

Yoruldum...', 'Bugün bir sayfayı daha yırtıp attım hayatımdan Ve gülümsediğim tüm fotoğraf karelerindeki bakışlarını Ve seni erkek yüreklim Ve seni ... Öyl...', ARRAY['Türk Edebiyatı','Şiir','Nihan Yüzel']::text[], 8.5, '{"poet":"Nihan Yüzel","poet_slug":"nihan-yuzel","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/yoruldum-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüler Sevişmez Yangınım', 'oluler-sevismez-yanginim-nihan-yuzel-kyfzi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevişen ümitlerdir boş sokaklarda

Hayallerdir yıkılan yitiklikte

Yaşanmışlıklara dalar sevdalar

Bir gerçek arar içlerinde yalan dünyalar

Ayrılık şarkıları söyler gece sevenlere

Ve kanlı yüzler sahte aynalar arar gerçeklerine

Bende mühürledim gecelerimi yalnızlığına

Hayalini kurdum yaşanmışlıklara dair

Bakışlarını aradım karanlık gecelerime

Kim bilir kaç gece geçti hasretinle

Sayamadım seni özlemelerimi

Zamanım yetmedi yokluğuna

Haykıramadım 

Kimselere diyemedim çaresizliğimi

Söyleyemedim

Dinleyen olmadı derdimi

Anlayan olmadı

Anılarımı düşündüm mazide kalan

Yaşanmışlığını düşündüm sevdamın

Seni düşündüm sensizliğin içinde

Kırılıp önüme düştü hatıralarım

Yalnızlığıma yazdım sana ait ne varsa içimde

Kimsesiz kaldım

Kimsesiz bırakıldım derin sessizliğinde 

Düşündüm

Ve sustum 

Sana sustum her defasında

İçim acıdı

Çok canımı yaktım

Çok canım yandı sensizliğimde

Bedenim tükense de

Ben sana konuşmam yangınım, ben sana susarım

Susmalarım sanadır benim 

Yanmalarım kendime

Yangınımsın

Cümlesi yok sensizliğin

Zamanı yok 

Kayıplığa uğurladım varlığını

Yokluğuna yazıyorum hayallerimi

 “Taşın kalbi yok ama taşı bile yosun sarar demiştin”ayrılırken

Gece geldi aklıma sözlerin

 “Başka sıcaklıklar hissedersin” demiştin “kuralsızca”

Susmuş, düşünmüştüm uzunca bir süre

Sende hatırlarsan 

Sonunda cevap verebilmiştim

Yıkılarak 

Ve ağlayan bir yürekle sana: 

“ölüler sevişmez yangınım”demiştim.

Sevişen ümitlerdir boş sokaklarda...', 'Sevişen ümitlerdir boş sokaklarda Hayallerdir yıkılan yitiklikte Yaşanmışlıklara dalar sevdalar Bir gerçek arar içlerinde yalan dünyalar Ayr...', ARRAY['Türk Edebiyatı','Şiir','Nihan Yüzel']::text[], 8.5, '{"poet":"Nihan Yüzel","poet_slug":"nihan-yuzel","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/oluler-sevismez-yanginim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırılmış Aynalardan Baktım Eskimiş Yüzüme', 'kirilmis-aynalardan-baktim-eskimis-yuzume-nihan-yuzel-dbxfh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kırılmış aynalardan baktım eskimiş yüzüme

Firarlara vurdum yüreğimi

Bu gece yalnızlığımı hatırladım her gece olduğu gibi

Yine sana mühürledim yeminleri

Gelmelerine dair hayaller kurdum, gitmediğin halde

Öyle bir inandırdım ki kendimi

En sonunda bende inandım yokluğuna

Uzak diyarlarımı yar edindin kendine

Ondan mıdır bendeki bu boşluğun

Ondan mıdır bilinmezlere yokluğum

Gecelerimi yazdım gözlerine

Hayallerime yandım yokluğunda

Yakılmış şiirlerde kaldı yangınlarım

Oysa ellerim senin sıcaklığında

Gözlerim sen diye bakar her sevdaya

Bir yıldız daha kaydı ömrümden bu gece

Bu kaçıncı dileyimdir

Sayamadım 

Saymalara gücüm yetmedi sevdiğim

Seni sevmeye ömrüm...

Ayrılığım yardan değil; candan oldu sen gidince

Yabancı kaldırımlar çiğnedim seni ararken içimde

Seni sevmelere yandım

Dönmelerine yandım

Yollarına serdim günahlarımı

Ayrılık şarkılarında aradım ismini

Bilmediğim yerlerde aradım seni

Kendim kayboldum boşluğunda

Bitmedi

Bitiremedim içimdeki seni

Gelme artık

Hiçbir kıymeti kalmadı varlığının

Yabancılaştı gözlerim sana.

Nasılda tutkundum oysa; 

Nasılda vurgundum, 

Nasılda yanmıştım yokluğunda.

Yoktun, 

Olamazdın yakınlığımda.

Ölümün soğukluğuna kattım yokluğunun ateşini

Diri diri gömdüm hayata kendimi

Ölemedim

Onu bile beceremedim

Öldürmeye kıyamadım içimdeki sevgini

Yenildim

Harcandım ayrılığınla

Ama benliğimdeki anlamını unutmadım adının

Gelme artık

Hiçbir kıymeti kalmadı varlığının...', 'Kırılmış aynalardan baktım eskimiş yüzüme Firarlara vurdum yüreğimi Bu gece yalnızlığımı hatırladım her gece olduğu gibi Yine sana mühürledi...', ARRAY['Türk Edebiyatı','Şiir','Nihan Yüzel']::text[], 8.5, '{"poet":"Nihan Yüzel","poet_slug":"nihan-yuzel","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/kirilmis-aynalardan-baktim-eskimis-yuzume-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Geldim', 'sana-geldim-nihan-yuzel-ranxs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana ait ne varsa alıp götürdü rüzgar avuçlarımdan, tutamadım varlığını, gittin.

Seni, beni, bizi bıraktın ardında

Hasreti bıraktın sensiz gece yarılarıma.

Seni bıraktın yaralı yüzünle rüyalarıma.

Bir ümit bekledim seni umutsuz yarınlarıma.

Yoruldum

Yıprandım sevdiğim

Beni yıprattım içimdeki senle

Gülüşüne baktım her gece ağlayan gözlerle

Ve sesini arzuladım

Suskunluğumda.

Sustum.

Sana sustum her defasında.

Zamansız gittin hayatımdan, 

Sana ihtiyacım vardı

Ama gittin.

Kapadın gözlerini varlığıma.

Uzaksın şimdi.

Ve ben her gece kokunu çektim buram buram içime.

Yokluğuna yazdım şarkıları.

Saçlarımı okşadım saçların diye, 

Gecelerce bekledim gelmeni

Belki yarın dedim her defasında

Ama yok

Bittik artık

Bozguna uğradı yaşadığımız ne varsa

Ağlatan hatıralara karıştı gözlerim

Ümitsiz yarınlar biriktirdim sana dair

Uykusuz gözlerimde aradım yokluğunu

Çoğu gece seni diledim kayan yıldızlardan

Yokluğuna yazdım geceleri

Papatyalar koparttım ellerine

Ve güneşe baktım gözlerin için

Her defasında daha çok yoktun

Şimdilerde hasretine yanıyor her sigaram

Kim bilir hangi mevsimlerdesin şimdi aşkın iklimlerinde her mevsim kış bana

Gittiğin günde kaldı zamanlarım

Dönülmeyen zamanlara uğurladım seni

Aşk yalnız yaşanırmış, sende anladım

Delirmeye yüz tutmuş ümitlerimde

Ve hep belkilerimdesin

Dağları, denizleri herşeyi aştı yüreğim

Sen bana gelmedin ama

Elini yüreğine koy; 

Ben sana geldim...', 'Sana ait ne varsa alıp götürdü rüzgar avuçlarımdan, tutamadım varlığını, gittin. Seni, beni, bizi bıraktın ardında Hasreti bıraktın sensiz g...', ARRAY['Türk Edebiyatı','Şiir','Nihan Yüzel']::text[], 8.5, '{"poet":"Nihan Yüzel","poet_slug":"nihan-yuzel","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/sana-geldim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağladım...', 'agladim-nihan-yuzel-8hnbh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güneşin doğuşunu seyrettim bu gece hayat penceremden

Bulutları hissettim kayan yıldızlarda

Gülüşünü düşündüm

Güldüm.

Senin yerine güldüm içim kan ağlarken

Mektuplarını okudum sonra

Hayallerine daldım

Gözlerin geldi aklıma

Ağladım

Sana ağladım

Birazda yokluğuna isyanım

Olmayışına

Ve sonra yaşamayı düşündüm sana dair

Yaktım tüm mektuplarımızı

Bu kadar zor olmamalıydı ama

Zorlandım.

Güneşin doğuşunu seyrettim bu gece hayat penceremden

Yağmurlar yağdırdım ağlayan yüreğime

Yeni düşlerimi vurdum sırtıma

Eski sokaklarımda yürüdüm

Sana yürüdüm

Hiç kimseye selam vermedim

Yollar uğurladı eski sokaklardan

Hiç bakmadım ardıma

Hiç duymadım

Hiç konuşmadım

Sana sustum yine 

Yokluğuna sustum bensiz zamanlarda

Unuttum

Hepsini unuttum 

Her şeyi unuttum

Gördüğüm ne varsa...	

“Hayat” dedi yaşlı bir adam ardımdan

yüzümü çevirdim bilmediğim duygulara

Seni aradım olmadığın her yerde

Sana seslendim

Gülüşünü düşündüm

Güldüm

Bu kadar zor olmamalıydı ama 

Zorlandım.

Yokluğuna zorlandım

Bakışlarınla ısındım soğuk gecelerde

Eskidi yeni düşlerim

Yalnızlığıma eskidi

Kimsesizliğime...

Güneşin doğuşunu seyrettim bu gece hayat penceremden

Toprağa sardım bedenimi

Gözlerin geldi aklıma; 

AĞLADIM...', 'Güneşin doğuşunu seyrettim bu gece hayat penceremden Bulutları hissettim kayan yıldızlarda Gülüşünü düşündüm Güldüm. Senin yerine güldüm içi...', ARRAY['Türk Edebiyatı','Şiir','Nihan Yüzel']::text[], 8.5, '{"poet":"Nihan Yüzel","poet_slug":"nihan-yuzel","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/agladim-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutunacak Hiçbir Dalım Kalmadı Artık', 'tutunacak-hicbir-dalim-kalmadi-artik-nihan-yuzel-ll0s9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tek ümidim sendin

Sende ansızın çekip gittin

Şimdi derin bir boşluk yokluğundan arta kalan

Hatıralar keskin birer hançer sırtıma saplanan

Oturmuşum karanlığa

Acılarımı dinliyorum

Kulaklarımda keskin bir uğultuyla seni seyrediyorum

Sen görmesende

Göz göze geliyoruz arada bir seninle

Ağlıyorsun yine

Duygusallık senin en vazgeçilmez yanındır

Küçük çekik gözlerin şafak rengi olmuş

Benzinse; sararıp solmuş

Karşında yine ben varım 

Birşeyler anlatıyorsun bağırarak

“olmuyor”diyorsun, ”olmuyor”

Oysa olumsuzluklar hiç olmazdı bizde

Hiç ağlayamayan ben 

Hıçkıra hıçkıra ağlıyorum karşında

Sonra çekip kapıyı gidiyorsun

Arkanda seni ve beni bırakarak gidiyorsun bu eski şiirden

Maziye ait ne varsa bir bir siliyorsun

Yıkılıyorum ardından

Ağlamalara vuruyorum kendimi

Kalbim uçmayı yeni öğrenmiş kuşlar gibi kanat çırpıyor ayrılığa

İçim acıyor gidişine

Anlatamıyorum sensizliği kimselere

Gittin

Yıktında gittin

Vurdunda gittin en can alıcı yerimden

Bittim ardından

Gittiğin yerlere serdim zamanlarımı

Kahırlar doldu ağlayan gözlerime

Sensizlik kaldı özlenen günahlarla

Her gece yokluğuna erimek kaldı

Bozgunluk kaldı ağladığım zamanlarda

Sen kaldın olmayışınla yanımda

Şimdi vakit gece yarısı

Ve derin bir boşluk yokluğundan arta kalan

Kulaklarımda keskin bir uğultu

Oturmuşum karanlığa

Seni özlemelerime yanıyorum

Kulaklarımda keskin bir uğultu

Açmışım yüreğimi hatıralara

Seni seyrediyorum', 'Tek ümidim sendin Sende ansızın çekip gittin Şimdi derin bir boşluk yokluğundan arta kalan Hatıralar keskin birer hançer sırtıma saplanan Ot...', ARRAY['Türk Edebiyatı','Şiir','Nihan Yüzel']::text[], 8.5, '{"poet":"Nihan Yüzel","poet_slug":"nihan-yuzel","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/tutunacak-hicbir-dalim-kalmadi-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sone 87', 'sone-87-william-shakespeare-yjbr9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hoşça kal! Değerin çok yüksek, tutamam seni,

Biliyorum kendine ne paha biçtiğini; 

Özgürlüğe kavuştun alıp değer belgeni,

İptal ettik sendeki hakkımın senedini

Nasıl tutarım seni, sağlamadan iznini,

Neyim var hak edecek senin zenginliğini,

Bu eşsiz armağana kim layık görür beni? 

Bana verilmiş berat, donup buldu vereni.

Sen vermiştin kendini, bilmeden değerini

Ya da bana vermekle hata işlediğini,

Bir yanlış anlamanın sonucu hediyeni; 

Ama, o yine buldu hatayı düzelteni

Sen benimdin: rüyanın görkemleriyle doldum.

Ben uykuda sultandım, uyanınca hiç oldum', 'Hoşça kal! Değerin çok yüksek, tutamam seni, Biliyorum kendine ne paha biçtiğini;  Özgürlüğe kavuştun alıp değer belgeni, İptal ettik sendek...', ARRAY['Türk Edebiyatı','Şiir','William Shakespeare']::text[], 8.5, '{"poet":"William Shakespeare","poet_slug":"william-shakespeare","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sone-87-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son', 'son-ceyhun-kuburlu-b2oxl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ve neresinden başlarsak başlayalım 

Yeni aşkların, 

İster göz ucu bakışmalarıyla başlasın tüm sevdalar

İster bir merhabayla

Ya da düşen kitaplarda

O ilk yaz cemresinin toprakta bıraktığı kokuyu bulamıyor insan

O ipe sapa gelmez bahanelerin

Tadıda yok hiçbir yalanda

Hiçbir mevsim dönüşü; yağmurlarını kaldıramıyor yürek

Bir gül, bir güneş sızıntısı kalıyor 

Geçmişin yansımalarında

Sessiz ve derinden

Soğuk bir mevsim daha yaklaşıyor hayata dair

Hepsi bu...

Hepsi bu... 

Ve giderken küçük bir tebessümle selamlamak miş’li geçmiş mevsimleri, 

Tüm yankıların anıldığı gün batımı semesına dönüyor dingin suların gövdesinde.

Ve alışıyor insan sessiz, dingin

Ama yorgun yalnızlığına...

Alışıyor 

Koskoca bir mevsim daha...

Ve koca bir çınar nasıl ömür tüketiyorsa toprağın kuytusunda, 

Aşklarda önce yapraklarını sonra dallarını bırakıyor

Bilinsiz bir gururun ortasına...

Ozetlemek gerekirse “o günler” diye başladığımız anıları

Gözlerimizden düşen pırıltılarda aramalıyız güzelliğini, 

Ve yarası bizde kalan tüm mektupların

Sonunu bir kez daha okumalıyız, 

Bir mutluluk sisinde...

İstanbul (Üsküdar)

Aralık 2002', 'Ve neresinden başlarsak başlayalım  Yeni aşkların,  İster göz ucu bakışmalarıyla başlasın tüm sevdalar İster bir merhabayla Ya da düşen kita...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Kuburlu']::text[], 8.5, '{"poet":"Ceyhun Kuburlu","poet_slug":"ceyhun-kuburlu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/son-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varoluş', 'varolus-eren-serbest-fko8p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çanlar çalıyor dışarıda yada ben öyle zannediyorum, 

Kathedraller bir bir yok oluyor sanki, 

İsrafil geliyor karanlıktan, yaşanmamış hayatlara son vermeye, 

Melaikeler seni arıyor neredesin sen? ? ? 

İstedim ki seni fani tarafta yaşıyayım, 

Bilir misin bana seni sordular ahiret sorusu diye! 

Şimdi yükseliyorum herkesle beraber; 

Ama yine tek düşüncem hasretimsin sen...

Bir bir yok oluyor katedraller, 

Sur üfleniyor, 

Dünya yok oluyor birtanem; 

Ama ben yine seni düşünüyorum 

Savurma hasret ateşini gayrı beni gönlünde yaşat! 

Eğer buraya gelirsen melaikelere sorma beni, 

Ben defterin solundaydaydım hep, 

Çünkü bu aşk kocaman bir yalan! ! ! !', 'Çanlar çalıyor dışarıda yada ben öyle zannediyorum,  Kathedraller bir bir yok oluyor sanki,  İsrafil geliyor karanlıktan, yaşanmamış hayatla...', ARRAY['Türk Edebiyatı','Şiir','Eren Serbest']::text[], 8.5, '{"poet":"Eren Serbest","poet_slug":"eren-serbest","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/varolus-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sone 126', 'sone-126-william-shakespeare-51rfo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hey oğul, güzel oğul, avucunda kıskıvrak: 

Vaktin dönek aynası, bir de saatli orak.

Sen ay gibi büyürken, serpilip gelişirken

Hepten çokmuş görünür kim varsa seni seven.

Yıkımlara egemen olan Doğa tanrıça

Seni geri çekiyor sen hızla yol aldıkça: 

Amacı, hünerini sende kanıtlayarak

Zamanı rezil etmek, sefil anlara kıymak.

Şimdi gözbebeğisin, ama kork ondan, çünkü

Tuttuğu hazinesi sonsuz onun olmaz ki.

Ertelese de er geç hesabı kapanacak: 

Yapacağı ödeme sen olacaksın ancak.', 'Hey oğul, güzel oğul, avucunda kıskıvrak:  Vaktin dönek aynası, bir de saatli orak. Sen ay gibi büyürken, serpilip gelişirken Hepten çokmuş ...', ARRAY['Türk Edebiyatı','Şiir','William Shakespeare']::text[], 8.5, '{"poet":"William Shakespeare","poet_slug":"william-shakespeare","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sone-126-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışkanlık', 'aliskanlik-hakki-cinar-vnt3f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bu kadar yalnız kalacağımı bilseydim 

hani böylece oturacağımı bilseydim 

seçer miydim kelimeleri işte oturmuşum 

karanlığa yakın insanlara uzak ah...! sen 

olduğunu bilmeden bi anneye sığınan onca çocuk 

herkes kendi evine giderken bu saatlerde ölümleri 

görüyorum uzaklardan yanınızdan 

içimden iyi şeyler geçmiyor çoğalmıyor bi türlü 

kendimiz ellerimiz gözlerimiz yarım kalan bi türkü 

gibi gıdıklıyor aklımızı dışardaki kar da eriyecek 

biliyorum gelişlerimiz kapıları yoklayışlarımız 

aynı kelimeler söylene söylene yıpranmıyor 

oturmuşum aslında soyum yalnızlıktan gelmiyor da 

be...! kardeşim göre göre de yaşanmıyor 

ayakkabımın altı delindi su geçiriyor 

olsun bir insan geçiyor daha henüz 

içimden değil mi ki Nazım da 

böylece geçmişti', 'bu kadar yalnız kalacağımı bilseydim  hani böylece oturacağımı bilseydim  seçer miydim kelimeleri işte oturmuşum  karanlığa yakın insanlara ...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Çınar']::text[], 8.5, '{"poet":"Hakkı Çınar","poet_slug":"hakki-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/aliskanlik-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farklılık', 'farklilik-ozcan-gunergok-ib5ur', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Düşün ki

Bir sabah uyanmışsın

hemfikir seninle tüm dünya 

doğru, yanlış, güzel, çirkin

Gördüğün her şey aynı, 

''Farklılık'' lügatlarda tozlanmış

nostaljik kavram

Düşün ki herkes aynı

Kimsenin diğerinden bir farkı yok

Fikirler aynı, bakışlar aynı

Ne tez, antitez, ne sentez

Solunum bile artık fotosentez...

Baksana güller bile çeşit çeşit 

Sarı, kırmızı, beyaz

hepsi de gül, neden, düşün biraz.

Hem neden türlü türlü ağaçlar

Yetmez miydi ağaç niyetine bir tek çam, 

Ne hoş huzur veriyor değil mi çınar...

Bir de söğüdün gölgesinde 

Cennetten ödünç saatler yaşamak var

Unutma

Tonlar çeşit çeşit gökkuşağında 

Cümlesine beyaz diyorlar

Ben, sen, o, biz, siz onlar, 

Cümlemize insan diyorlar...

(26.09.1999 İstanbul 20: 39)', 'Düşün ki Bir sabah uyanmışsın hemfikir seninle tüm dünya  doğru, yanlış, güzel, çirkin Gördüğün her şey aynı,  ''Farklılık'' lügatlarda tozlan...', ARRAY['Türk Edebiyatı','Şiir','Özcan Günergök']::text[], 8.5, '{"poet":"Özcan Günergök","poet_slug":"ozcan-gunergok","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/farklilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Barış Olacak', 'adi-baris-olacak-ozcan-gunergok-kxq9c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yakında bir oğlum olacak

adını ''Barış'' koyacağım

Savaşın ortasındayken bile

yüzü hep gülecek yavrumun

Gülen fotoğraflarına bakacağım

Hasbelkader cephedeysem

Yaşama umudum olacak

benim gül yüzlü ciğerparem

Ya kızım mı olursa? 

Ne fark eder ki? 

Öğütledim hayat arkadaşıma

Adı yine ''Barış'' olacak

(31.03.1999 İstanbul 02: 59)', 'Yakında bir oğlum olacak adını ''Barış'' koyacağım Savaşın ortasındayken bile yüzü hep gülecek yavrumun Gülen fotoğraflarına bakacağım Hasbelk...', ARRAY['Türk Edebiyatı','Şiir','Özcan Günergök']::text[], 8.5, '{"poet":"Özcan Günergök","poet_slug":"ozcan-gunergok","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/adi-baris-olacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşı', 'gozyasi-ozcan-gunergok-qoz8m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözyaşlarında mutluluk saklı 

Azad edebiliyorsan inci tanelerini 

Şükretmelisin tanrıya 

Nerde, ne zaman, nasıl 

İnan farketmez 

Hürriyet ertelenemez 

Kim demiş ağlayan zayıf diye 

Ben ki bir ulu çınarım 

Arza gömülü candamarımı 

Gözyaşımla sularım', 'Gözyaşlarında mutluluk saklı  Azad edebiliyorsan inci tanelerini  Şükretmelisin tanrıya  Nerde, ne zaman, nasıl  İnan farketmez  Hürriyet er...', ARRAY['Türk Edebiyatı','Şiir','Özcan Günergök']::text[], 8.5, '{"poet":"Özcan Günergök","poet_slug":"ozcan-gunergok","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gozyasi-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Papatyalar Açtığında', 'papatyalar-actiginda-ozcan-gunergok-hz2kw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Papatyalar açtığında 

Hep kırlarda buluşur 

Seninle aynı oyunu oynardık 

çocukluğumuzdan beri 

Ben gözlerimi kapar

Bir ağaca yaslayıp başımı

İçimden sayardım

Bir, iki, üç...

Sonra gözlerimi açar 

Pes diyene kadar arardım

Seni bulamazdım 

Saklanmakta ustaydın

Kazanmanın sevinciyle koşup

Bana sarılman vardı ya 

Sarhoş ederdi beni sevgilim

Bir kadeh bile içmeden 

Söylediler inanmadım gittiğine

Görmez misin papatyalar açtı

Yine kırlardayım

Başımı yasladım o ağaca

Bak kapıyorum gözlerimi

Sayıyorum içimden

Bir, iki, üç...

Duymuyor musun sevdiceğim

Hadi artık pes dedim...', 'Papatyalar açtığında  Hep kırlarda buluşur  Seninle aynı oyunu oynardık  çocukluğumuzdan beri  Ben gözlerimi kapar Bir ağaca yaslayıp başımı...', ARRAY['Türk Edebiyatı','Şiir','Özcan Günergök']::text[], 8.5, '{"poet":"Özcan Günergök","poet_slug":"ozcan-gunergok","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/papatyalar-actiginda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gaz', 'gaz-ali-erkin-kutlu-1lvwr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgiyi bulmak sabırsa, 

Güzel olanı yaşamaksa amaç, 

Aşksa seni gülümseten, 

Ve huzursa seni canlandıran, 

Kaldır başını, koş doğruca..

Kimse sana bunları yaşatan.', 'Sevgiyi bulmak sabırsa,  Güzel olanı yaşamaksa amaç,  Aşksa seni gülümseten,  Ve huzursa seni canlandıran,  Kaldır başını, koş doğruca.. Kim...', ARRAY['Türk Edebiyatı','Şiir','Ali Erkin Kutlu']::text[], 8.5, '{"poet":"Ali Erkin Kutlu","poet_slug":"ali-erkin-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim', 'yuregim-soner-demirez-fjo83', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ahhhhh ah be gülüm bilemesin içimi

Bilemezsin kaç yangından çıkmışım...

Bilemezsin kaç vurgun yedim..

Kaç yağlşı kurşun saplandı bu yüreğime..

Bir yalanla başlayan kaç ilişki gömüldü bu kalbe..

Her biri bir diğerini arattı..

Son vurgunda yandım kül oldum...

Bitmeyen hasretlere gömüldüm..

Çaresizliğimde boğuldum...

Tutamadım ellerini göremedim yüzünü...

Kapısınına dayanamadım yarin...

İrkiliyorum gecelerde

Karabasan düşler giriyor rüyalarıma..

Rüyalar bile izin vermedi Onu görmeme...

Derbeder viran yarattı şu koca zaman...

Varlığımdaki...

Varlığımdaki yokluğumu gördüm..

Hiçliğimi gördüm koca dünyada...

Yaşananlar bir masal... 

Özlemlerim, yüreğim acı dolu..', 'Ahhhhh ah be gülüm bilemesin içimi Bilemezsin kaç yangından çıkmışım... Bilemezsin kaç vurgun yedim.. Kaç yağlşı kurşun saplandı bu yüreğime...', ARRAY['Türk Edebiyatı','Şiir','Soner Demirez']::text[], 8.5, '{"poet":"Soner Demirez","poet_slug":"soner-demirez","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yuregim-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Pişmanlık Fayda Etmez', 'son-pismanlik-fayda-etmez-ozan-rari-ktr0b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalnızlığın kucağında, 

Düşüncelerin karmaşasında, 

Hayatın karasında, 

Pişmanlığın tam ortasındasın...

Geçmişinin esaretinde, 

Aşklarının lekesinde, 

Özünün bilinmezliğindesin...

Gecelerin ayazında, 

Hatalarının yumağında, 

Kin ve nefret kıyısında tek başınasın...

Mutluluk dilemek isterdim ama 

Değerlerin yok ki senin, 

Boşuna bu küskünlük, 

Geçmişte kaybettiklerini şimdi geri alamazsın, 

Geleceğe umut bağlama, 

Geçmişin kara, geleceğinse kapkara! ! !', 'Yalnızlığın kucağında,  Düşüncelerin karmaşasında,  Hayatın karasında,  Pişmanlığın tam ortasındasın... Geçmişinin esaretinde,  Aşklarının l...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/son-pismanlik-fayda-etmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Damlaları', 'yagmur-damlalari-ozan-rari-y28q1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yağmur damlaları kadar seviyorum seni işte

Sevdim işte...

Elimde değil, elimde olsa geri almazmıyım

Sevgimi, aşkımı, anılarımı, umutlarımı...

Vermezmiydim geri, bana bıraktıklarını! 

Hüzünlerimi, gözyaşlarımı, hayal kırıklıklarımı...

İstemezmiyim şimdi o eski kızı

Hani gözlerinin içi gülen, 

Dünyaya binbir umutla bakan, 

Aşkından ayakları yerden kesilen.

Ama alacağım verdiğim herşeyi senden geri

Sen istemesende, izin vermesende

Ve birgün gelecek....

Bende göreceğim gözyaşlarını...', 'Yağmur damlaları kadar seviyorum seni işte Sevdim işte... Elimde değil, elimde olsa geri almazmıyım Sevgimi, aşkımı, anılarımı, umutlarımı.....', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yagmur-damlalari-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişman', 'pisman-ozan-rari-tdt36', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Son pişmanlık fayda etmez! 

Geri dönmeye gücün yetmez! 

Bu nefret burada bitmez! 

Yalvarsanda, ağlasanda, 

Ayaklarıma kapansanda, 

Rüyalarında görsende, 

Ölüp ölüp dirilsende! 

Artık boş laflarına karnım yok

İnim inim inlesende! ! !', 'Son pişmanlık fayda etmez!  Geri dönmeye gücün yetmez!  Bu nefret burada bitmez!  Yalvarsanda, ağlasanda,  Ayaklarıma kapansanda,  Rüyaların...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/pisman-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Film Bitti', 'film-bitti-seyfettin-bilal-ozluk-1srwp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sol yanıma bir yıldırım düştü

Söktü gitti kalbimi yine acı gerçekler

Şimdi yüzleşme zamanı

Aç müziğin sesini söyle Sezen sen söyle

''Sarı odalarda evli barklı...''

Bir arama moduna girdim yine

Kaybettim benliğimi yok olmama az kaldı

Yetişen ne elimi tutacak ne de kolumu

Çekilin karşımdan, çıkmayın yoluma...

Bir küçük yadigar şimdi resimler

Ve bir kaç satır yazı

Umudum hep yarınlardaydı

Artık yarınlarda yok...

Birkaç saniyelik kısa metrajlı film değil mi? 

Şu yalan ve sahte hayat.

Ey acı gerçekler

Hep yüzüme mi vurmanız gerekiyor

Bir kerecikte yalan olsanız

Ne çıkar ya ne çıkar! ...

Kaybeden hep ben

Kazanan hep acı gerçekler...

 Birazdan altyazı geçecek

“Seni sevmiştim ve seviyorum''

Ve film bitiyor

Az sonra perde de inecek

Ve ışıklar kapanacak

Ben ise yine koltuğuma yapışmış vaziyette

Yeni bir filmi bekleyeceğim...', 'Sol yanıma bir yıldırım düştü Söktü gitti kalbimi yine acı gerçekler Şimdi yüzleşme zamanı Aç müziğin sesini söyle Sezen sen söyle ''Sarı oda...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/film-bitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben ve Yine Ben', 'ben-ve-yine-ben-seyfettin-bilal-ozluk-oy1is', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yürüyorum sahil boyunca

Tek başıma yapayalnız

Vuruyor dalgalar sahile

Deniz kabuğu topluyorum kendimce

Martılar uçuşuyor denize

Bir dalıp bir çıkıyor

Ben ise yine kendimle

Hayaller kuruyorum sanki martılarla...

Uzaktan bir gemi görünüyor

Ve başlıyor

Hafif yağmur çiselemeye

Neden neden? 

Daha yeni başlamıştım

Martılarla ve deniz kabuklarıyla dertleşmeye...

Hiç aldırmıyorum yağan yağmura

Ben hala oturmuş sahile

Yağan yağmura ve soğuğa inat

Kendimle dertleşiyorum, hatalarımla

Bir martı kanat çırpıyor üzerimde

Sanki beni anlarcasına

Veya alay edercesine bu yağmurda

''Ne yapıyorsun'' der gibi

O da haklı

Ne bilsin ki benim ne yaşadığımı

Veya yaşarken neler çektiğimi...

Yağmura aldırmıyorum

Gök yarıldı

Bütün bulutlar ağıtla doldu ağlıyor

Ama dedim ya aldırmıyorum

Islanmadık yer kalmadı elbisemde

Yine oralı değilim ben hala

Ve 

Başlıyor tam hayallerimin arasında 

Telefonun sesi

Arayan yine o nerdesin diyor

Ben ise kandırıyorum

Oturuyorum kafede diyorum

Ama nerden bilsin ki

Sahilde yağmurun altında oturduğumu

Bir köpek benimle inatlaşırcasına

O yağmurda bana yaklaşıyor

Ben 

Evet ben, 

Köpekten nefret eden o insan

Korktuğum halde usulca yaklaşıyorum

Okşuyorum köpeği

O da yanıma uzanıyor

Sanki beni anlarcasına o yağmurda

Ben ise hep denizin maviliklerini seyrediyorum

O masum köpek ise

Her martı uçuşunda koşuşuyor

Yakalayacakmışçasına arkasından

Yoruluyor ve tekrar yanıma geliyor...

Evet koca sahilde

Ben, köpek, martılar

Ve birde

Hayallerim...

Ve tekrar telefon çalıyor

''Aman Allah''ım''

Sahile oturalı 3 saat olmuş

Ama bana 5 dakika gibi geldi

Artık vakit gitme zamanı

Kalkıyorum her tarafım yamyaş

Ve hayallerimi bırakıyorum

O sahile ve martılara

Köpek ise benden akıllı

O çoktan gitti kulübesine...

Evet

İşte ben yine kendimle

Kaderimle tek başıma kalıyorum

Dertlerimle ve hatalarımla

Ama

İçimde hep bir umut

Geleceğe ve yarınlara

Ancak

Bu nereye kadar 

Nasıl gider

Ne ben bilirim ne de sen

Bilme bilmekte istemiyorum...

Çünkü ben hep yalnızdım

Ve hala yalnızım...', 'Yürüyorum sahil boyunca Tek başıma yapayalnız Vuruyor dalgalar sahile Deniz kabuğu topluyorum kendimce Martılar uçuşuyor denize Bir dalıp bi...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":81,"source_url":"https://www.antoloji.com/ben-ve-yine-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müjgan''ın Ardından', 'mujgan-in-ardindan-turgut-erdogan-6axpf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen orada değildin Müjgan, 

Bilemezsin…

Sen yıkık değildin, değildin viran, 

Göremezdin…

Sen çekip gidendin, 

Oysa ben, geride kalan.

Geride kalıp da, kirpiklerin devşirip

Ardın sıra ağıtlar yakan.

Sen orada değildin Müjgan! ! ! 

Sen değildin vurulan, 

Sen değildin vurulup da yıkılan.

Bendin o bendim, 

Yokluğunun kan gölünde upuzun yatan.

Sen hiç yoktun ki Müjgan! ! ! 

Seni havadan, 

Seni sudan, 

Seni çamurdan ben yarattım, 

Tuttum bir de ölürcesine taptım.

Sen hiç yoktun ki Müjgan.

Ya ben! ! ! 

Ben var mıyım?', 'Sen orada değildin Müjgan,  Bilemezsin… Sen yıkık değildin, değildin viran,  Göremezdin… Sen çekip gidendin,  Oysa ben, geride kalan. Geride...', ARRAY['Türk Edebiyatı','Şiir','Turgut Erdoğan']::text[], 8.5, '{"poet":"Turgut Erdoğan","poet_slug":"turgut-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mujgan-in-ardindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup -23- (Uzaklığın)', 'mektup-23-uzakligin-turgut-erdogan-daije', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her sabah böyle uyanırım, kuş gibi.Yeni doğmuş bir bebeğin günahsızlığındayımdır her sabah, her gecenin bitimindeki tüm günahlarıma inat. İlk seninle başlarım güne, aklıma ilk düşen yüzünde çağıldayan akarsulardır. Berrak, temiz, saf ve günahsız. Ve bir o kadar da ayrılığın, uzaklığın buruk tadı vardır o sularda. Dudaklarımın kıyısında beliren tebessüm, önce yüzüme ardından tüm bedenime yayıldığında kahkahaya dönüşmüştür artık. Gayrı hiçbir avcı izini süremez bir maralın, apansız sıkıştırıp bir kaynak başında  umutlarına, hayallerine son veremez gözbebeğimdeki engin çayırlarda, gayrı tek damla yağmur yağmaz kirpiklerimdeki yağmur ormanlarında.

	Her sabah seninle ilk kez buluşacakmış, ilk kez gözlerimiz birbirine değecekmiş, ilk kez ellerimiz birleşecekmiş ve ilk kez o ipek saçlarını okşayacakmışçasına dolu dolu bir umut ve sevinçle hazırlanırım.07.15 Trenine yetişmek için kapıyı yalnızlığımın suratına çarpıp koşar adım tutarım istasyonun yolunu. Bindiğim vagondaki insanların yüzü ilgimi çekmez hiç. Ama bilirim ne şartlarda yaşadıklarını, ne zorlukları aşmaya çalıştıklarını ve her birinin yüreklerinde ulaşılması imkansız bir aşka son sürat koştuklarını. Benim de tek derdim sana olan uzaklıkları aşmaktır 07.15 treninde.	

	Raylar üzerinde salına salına giden trenin son vagonunda otururken rayların kıyısındaki telefon direklerinden fallar tutarım sevdaya dair, “seviyor-sevmiyor” diye. Hep “seviyor” çıkar ama uzaksın, niye? Durup duruken bir şiirin mısraları gelir çakılır düşüncelerime; 

“Şimdi! ! ! 

Ne saz dayanır yokluğunun türküsüne, 

Ne mızrap dayanır bu sevdanın öyküsüne.

Dön sevdalım, dön umudum, 

Yüreğim hasret yüreğinin gölgesine…”

	İstasyonda iner inmez koşar adım giderim fabrikaya. Masamın çaprazındadır masan. Gözlerim hasretle seni arar ama yine yoksun, bugün de yoksun. Akşama kadar beklesem de seni, gelmezliğini bildiğim halde belki gelirsin umuduyla bitiririm günü.

	Evin hemen köşesindeki Vahdet Efendiden alırım akşam nevalemi. Bir küçük rakı ve biraz da beyaz peynir. Akşam oturduğum balkonumun boğaz esintisinde geç saatlerde bitiririm ancak küçük rakı, beyaz peynir ve geleceğine dair umutlarımı.

	Sen şimdi yüreğimin kıyısında ama çok uzak, sen şimdi çok uzak ama canım kadar yakınsın.', 'Her sabah böyle uyanırım, kuş gibi.Yeni doğmuş bir bebeğin günahsızlığındayımdır her sabah, her gecenin bitimindeki tüm günahlarıma inat. İl...', ARRAY['Türk Edebiyatı','Şiir','Turgut Erdoğan']::text[], 8.5, '{"poet":"Turgut Erdoğan","poet_slug":"turgut-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/mektup-23-uzakligin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ardına Bakma', 'ardina-bakma-seyfettin-bilal-ozluk-pnpxz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dolu dizgin yaşarken seni içimde

Seyyah olup kapına çalarsam birgün zamansızca 

Sırtına dönme bana 

Yine bir başıma kalırım

Eğer çıkmak istersen içimden

Giderken arkana hiç ama hiç bakma...

Çünki dönüpte arkana bakarsan

Dizlerimin üzerine kapanışımı

Ve gözümden akan yaşları görme! 

İçinde olmayan hislerin beni acımasın...

Giderken ardına bakma

O son bakışın beni kahretmesin, 

Kararlıysan gitmeye sonsuzluğa

İstemem sensizliğe iç çekişimi görme

Ve benim dudağımda bu şarkı dökülecek; 

''Bu ilk gecem

Sensiz savunmasız

Bu ilk gecem

Zamansız yalnızım

Tek hece aşk

Yakar kavurur beni

Sensiz geçen ilk gecemde, 

Unutmadım sensiz geceyi unutamam seni.

Sana söz verdim aşkım

Bu gece ağlamayacağım

Sana söz verdim aşkım

Uyumaya çalışacağım

Sana söz verdim aşkım

Sözümü tutacağım.

Gitti artık deseler bile senin kalacağım.

Sana söz verdim aşkım

Bu gece içmeyeceğim

Sana söz verdim aşkım

Canımdan vazgeçmeyeceğim

Unut artık deseler bile

Ben senin kalacağım, 

Sana söz verdim aşkım SÖZ! ...''

Evet alır götürür bu şarkı beni

Ne ben kalırım ne de hasret biter.

Söyledim ya giderken arkana bakma

Benim yıkılmışlığımı 

Yok olmuşluğumu görme...

Kendime lanet okuyorum

Her zaman ki gibi alışmış olduğum kaybetmişliği...

Ağlamaktan kanlanmış gözlerimi

Görme istemem ne olur...

Herşeyin bir sonu olduğunu hep inanırım

Ancak senin sonsuz olduğunu hep inandım ve inanacağım

Çünki sen hep içimdesin

Ve hep öyle kalacaksın

Bugün yaşıyorsan yarınlarımda da yaşayacaksın

Ve eğer gideceksen arkana bakma ne olur 

Sessizce çek

Ve 

Git! ...', 'Dolu dizgin yaşarken seni içimde Seyyah olup kapına çalarsam birgün zamansızca  Sırtına dönme bana  Yine bir başıma kalırım Eğer çıkmak iste...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/ardina-bakma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al Beni', 'al-beni-ozan-rari-1qd4j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tüm çıplaklığımla herşeyimle karşındayım

İstediğin benim hey sen ne duruyorsun? 

İçindeki kabarmış sonsuz nefret

Yaşanmamış anılar, günler, duygular...

Ölümüne sevdan hayatının buruk kalmış gerçeği

Neredesin ben karşındayım al işte ne duruyorsun öyle! 

Seninde istediğin bu değil mi son darbeyi indirmek şu garip, zavallı yüreğime! 

Ne varsa al senin olsun bende işe yaramıyorlar zaten

Olsada olur olmasada farketmez 

Sapla kara saplıyı ki içindeki şeytan huzura ersin

Al veriyorum sana kendimi

Dilediğin gibi kullan

Canın ne çekiyorsa onu yap

Ama yeterki bitir işimi

Kaybedecek hiçbir şeyim kalmadı zaten

Umrumda değil gerçekten

Ne olacaksa olsun bir an! 

Bekliyorum gelip beni almanı, sabırsızım inan

Sakın bekletme beni fazla...', 'Tüm çıplaklığımla herşeyimle karşındayım İstediğin benim hey sen ne duruyorsun?  İçindeki kabarmış sonsuz nefret Yaşanmamış anılar, günler, ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/al-beni-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Bu Ya', 'hayal-bu-ya-nursema-gurul-qe8z0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu akşam dönerdönmez eve

Bir kadeh rakı hazırlayacağım kendime

Bir bardak da vicdan koyup masama

Sana içireceğim ellerimle...

Başımın belası duvarların hiç yokmuş gibi 

Hoş köşene bağdaş kuracağım bir çırpıda

Sana yüzlerce şiir yazacağım bütün içtenliğimle

Ve hepsini okuyacağım bir nefeste

Sonra bir vakitte pişman olduğun gelecek aklına

Benden özür dileyeceksin bu gece...

İnadın kırılmış, yüzün güleç olacak

Elini elime uzatacaksın yine

Sanki hiç gitmemiş gibi olacaksın

Sanki hiç terketmemiş gibi

Sanki hiç değişmemiş gibi bütün umutlarımı

Uykularımı bölen o kahrolası zilliye! 

Eskisi gibi yalanların olmayacak bu defa 

Güzel sözler söyleyeceksin bana

Seni soranların selamlarını ileteceğim tek tek

Yüzünde özlem dolu  güller açacak bu gece!', 'Bu akşam dönerdönmez eve Bir kadeh rakı hazırlayacağım kendime Bir bardak da vicdan koyup masama Sana içireceğim ellerimle... Başımın belası...', ARRAY['Türk Edebiyatı','Şiir','Nursema Gürül']::text[], 8.5, '{"poet":"Nursema Gürül","poet_slug":"nursema-gurul","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hayal-bu-ya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Sen Öldürdün', 'beni-sen-oldurdun-knight-errant-tsnrt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Lise hayatı öldürdü beni

Kaloriferin başında içtiğimiz çaylar

Arka bahçede attığımız turlar öldürdü

Bir de kız pansiyonun merdivenleriyle

Kantindeki masalar öldürdü beni

Bursa''nın havası öldürdü beni

Rüzgarda dalgalanan kıpkızıl saçların

Soğuktan kızaran burnun öldürdü

Bir de üşüyünce koluma girmenle

Kazağımı verişim öldürdü beni

Çarşı esnafı öldürdü beni

Salep içtiğimiz köşedeki kafe

Klasik dondurmacımız Geye öldürdü

Bir de Burç sinemalarıyla

Tostçu Hüseyin öldürdü beni

Bursa''nın doğası öldürdü beni

Setbaşı Köprüsü''nden dereyi seyretmemiz

Sonra aşağı inip taş atmamız öldürdü

Bir de teleferik keyfimizle

Uludağ''ın suları öldürdü beni

Aşk acısı öldürdü beni

Deli gibi durmadan çarpan kalbim

Seni düşünmekten kaybolan aklım öldürdü

Bir de sabaha kadar sönmeyen dolunayla

Yarım yamamalak parlayan yıldızlar öldürdü beni

Aslında beni sen öldürdün

Sana her baktığımda ışıldayan mavi gözlerin

Üşüdüğünde yanağıma dayadığın ellerin öldürdü

Her gün taktığın o püsküllü sarı şapkayla

Üzerinde bir kez gördüğüm o beyaz kazak öldürdü

O yumuşscık, dağınık kızıl şaçlarınla

Bir ömür kadar uzak olan dudakların öldürdü

Evet, evet aslında beni sen öldürdün', 'Lise hayatı öldürdü beni Kaloriferin başında içtiğimiz çaylar Arka bahçede attığımız turlar öldürdü Bir de kız pansiyonun merdivenleriyle Ka...', ARRAY['Türk Edebiyatı','Şiir','Knight Errant']::text[], 8.5, '{"poet":"Knight Errant","poet_slug":"knight-errant","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/beni-sen-oldurdun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardanölüm', 'kardanolum-ali-tasmaz-nlze5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dışarıda kar yağıyor

İçime ölüm yağıyor

Bir mezar kazılıyor yüreğimde

Bütün umutlarım gömülüyor

Dışarda kar yağıyor

Elektirik gidiyor geliyor

Bir serçe konmuş taşın üstüne

Mezar taşına benziyor

Toprak gelinlik giyiyor diyor Arif hoca

Bana göre kefen giyiyor

Dışarda kar yağıyor

İçimde mezarlar üşüyor

Ürperiyor bütün benliğim

Beynimde düşünceler donuyor

Bir uçurumun kenarında yürüyorum

Herşey üzerime geliyor

İmkansız bir aşk pusuya yatmış

Acılar kollarını sonuna kadar açmış

Hepsi uçuruma düşmemi bekliyor

Bu defa düşüremiyeceksiniz diyorum

Büyük konuşmamak gerekiyor biliyorum

Dışarıda kar yağıyor

Mezarlıkta ölüler üşüyor

Gözleri doluyor bir serçenin

Bir romantiğin gözyaşı toprağa düşüyor

Dışarda kar yağıyor

Yaşayan bir ölü şiir yazıyor', 'Dışarıda kar yağıyor İçime ölüm yağıyor Bir mezar kazılıyor yüreğimde Bütün umutlarım gömülüyor Dışarda kar yağıyor Elektirik gidiyor geliyo...', ARRAY['Türk Edebiyatı','Şiir','Ali Taşmaz']::text[], 8.5, '{"poet":"Ali Taşmaz","poet_slug":"ali-tasmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kardanolum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başkaldırıyorum', 'baskaldiriyorum-sahin-yenilmez-2gud6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Alıp başımım gidemiyorum

Gitsem arkamda kalacaklara acıyorum

Çok acılar yaşadım

Gözyaşlarım bir şarap misali

Hergün şişelerce aktı döküldü yerlere

Yaşamak hep böyledir çoğu zaman

Yaşamak istersin 

Önüne çıkan engellere boyun eğersin

Ben başkaldırıyorum

Hiç acı yaşamadım değil ama hepsini bir anda siliyorum

Boyun eğmiyorum

Hiçbir acı yüzünden kendimi aldattığım olmadı

İnsanlar aldatılmaz aslında

Aldatılan o an için yaşanan anılar olur

Eğer yaşadığım anılar beni aldatıyorsa

Ve bana sevgi yerine hüzün veriyorsa hayatımı onlara adamam

Ben başkaldırıyorum

Kim duyar bilmem ama

Ben alıp başımı gitmiyorum.', 'Alıp başımım gidemiyorum Gitsem arkamda kalacaklara acıyorum Çok acılar yaşadım Gözyaşlarım bir şarap misali Hergün şişelerce aktı döküldü y...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yenilmez']::text[], 8.5, '{"poet":"Şahin Yenilmez","poet_slug":"sahin-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/baskaldiriyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sevda Denizi', 'bir-sevda-denizi-sahin-yenilmez-xp9ty', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sevda denizinin tam ortasındayım sanki

Aynı bir acemi balık gibi

Karaya çıkarsam ölürüm

Denizde ise yapayalnızım.

Bir sevda denizinin tam ortasındayım sanki

Sanki yüzme bilmiyorum

Yada gidecek bir yerim yok

Oradan oraya yüzüyorum.

Her yağmur yağışında dua ediyorum

Kurtar beni bu denizden diye

Yağmur dinince ise

Benim gözyaşlarım yağmaya başlıyor.

Bir sevda denizinin tam ortasındayım sanki

Sanki kurtulmak için uzatılan eller Azrail''in eli

Her fırtınada ya seni düşünüyorum

Bekliyorum ölmeyi.', 'Bir sevda denizinin tam ortasındayım sanki Aynı bir acemi balık gibi Karaya çıkarsam ölürüm Denizde ise yapayalnızım. Bir sevda denizinin ta...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yenilmez']::text[], 8.5, '{"poet":"Şahin Yenilmez","poet_slug":"sahin-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-sevda-denizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mechul', 'mechul-selami-ozturk-hdei9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dün umutla geleceğe sarılan

Bugün hüznün gözyaşlarıyla kavrulan

Yarın bilinmeze doğru yol alacak olan

bu meçhul

Yıllar sonra kim bilir nerde ve nasıl bulunacak', 'Dün umutla geleceğe sarılan Bugün hüznün gözyaşlarıyla kavrulan Yarın bilinmeze doğru yol alacak olan bu meçhul Yıllar sonra kim bilir nerde...', ARRAY['Türk Edebiyatı','Şiir','Selami Öztürk']::text[], 8.5, '{"poet":"Selami Öztürk","poet_slug":"selami-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/mechul-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melek', 'melek-selami-ozturk-ifi12', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Neşeli uçuk bir halin vardı seni ilk gördüğüm an

İlk aşk kıvılcımlarını attın kalbime

Hayallerime girdin ansızın

Aşık olmuşum ben kendimden habersiz

Tek düşüncem artık yalnız sen ve ben

Vuruldum sana delicesine

Ellere yar etmem seni sonunda ölüm olsa bile

Melekmiş adın inan melekler kadar güzelsin

En güzel gecemi sana ayırsam gelir misin

Loş ışıklar altında yalnız sen ve ben

En tatlı heyecanları yaşamak için

Kalbimin en güzel yerine konar mısın…. 

Sonunda ölüm olsa bile…', 'Neşeli uçuk bir halin vardı seni ilk gördüğüm an İlk aşk kıvılcımlarını attın kalbime Hayallerime girdin ansızın Aşık olmuşum ben kendimden ...', ARRAY['Türk Edebiyatı','Şiir','Selami Öztürk']::text[], 8.5, '{"poet":"Selami Öztürk","poet_slug":"selami-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/melek-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Sevgilim', 'canim-sevgilim-selami-ozturk-00idx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eskiden kalan ne varsa senden

Hepsi değerli şu sensiz bedenimden

Yaşadığım bir gün bile senle

Benim için değerli bütün ömrümden

Canım sevgilim', 'Eskiden kalan ne varsa senden Hepsi değerli şu sensiz bedenimden Yaşadığım bir gün bile senle Benim için değerli bütün ömrümden Canım sevgil...', ARRAY['Türk Edebiyatı','Şiir','Selami Öztürk']::text[], 8.5, '{"poet":"Selami Öztürk","poet_slug":"selami-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/canim-sevgilim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlıkta Üşümek', 'karanlikta-usumek-selami-ozturk-jc4x6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ruhum karanlığın koynunda, 

soğuk ve alacakaranlık.

İçim sıkılıyor

daralıyor

ve çığlıklarla gelen üzüntüler 

Bedenimi parçalıyor', 'Ruhum karanlığın koynunda,  soğuk ve alacakaranlık. İçim sıkılıyor daralıyor ve çığlıklarla gelen üzüntüler  Bedenimi parçalıyor...', ARRAY['Türk Edebiyatı','Şiir','Selami Öztürk']::text[], 8.5, '{"poet":"Selami Öztürk","poet_slug":"selami-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/karanlikta-usumek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askerin Şiiri', 'askerin-siiri-selami-ozturk-rfow7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her sabah saat 6 da kalkmakla

Soğuk suyla traş olmakla

Mercimek çorba ile doymakla

Bu askerlik biter mi söyle  arkadaş

Her saat içtimaya çıkmakla

Nasırlı ellerle ot yolmakla

Sekiz saat çaprazda nöbet tutmakla

Bu askerlik biter mi söyle arkadaş

Anamı babamı özledim şafağım çok

İzne gitmek istesem 20 gün yeter mi

Kışlamdan sılaya giden yollar

Beni anama geri verir mi söyle arkadaş

Batmandan Uzunköprü’ye 1 ayda mektup gelmez

Telefon açsam param yetmez

Garip askerin çilesi bitmez

Bu askerlik biter mi söyle arkadaş

Ben yunan sınırında nöbet tutarken

Soğuktan ellerim ayağım titrerken

Gözümde yarimin hayali varken

Gözüme uyku girer mi söyle arkadaş

Siyah saçlarıma aklar düşmeden

Şu zalim ellerden firar etmeden

İçimdeki sevgimi daha yitirmeden

Bu askerlik biter mi söyle arkadaş

550 gün saymakla biter mi 

ben ölmeden bu gurbetlik sona erer mi

garip askerin çilesi bunla biter mi 

söyle söyle be arkadaş', 'Her sabah saat 6 da kalkmakla Soğuk suyla traş olmakla Mercimek çorba ile doymakla Bu askerlik biter mi söyle  arkadaş Her saat içtimaya çık...', ARRAY['Türk Edebiyatı','Şiir','Selami Öztürk']::text[], 8.5, '{"poet":"Selami Öztürk","poet_slug":"selami-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/askerin-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-sair-seyyah121-7z7uq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Herşeyin anlamsızlaştığı

Hiçbirşeyin duvarlara yansıdığı

Kireç suyunun suyla karıştığı

Aşkın dalga dalga yansıdığı

Karnlık bir dağevindeyim

Sessizlik, sensizlik ve aşkın

Bana arkadaşlık ettiği

Ve kederimi sigara dumanıyla

Beslediğim zamandayım

Buğulu camlarda hayalini kurduğum

Ağlamaklı yüzüm ile

İçimdeki berhavalıkla 

Geliyorum sana

Ve demirleniyor gemiler

Gelecek zamanın 

Bilinmez limanlarına

Ve aşklar haykırıyor dalga dalga

Ve aşklar haykırıyor sözcük sözcük

Geliyor sana doğru 

Seni seviyorum diye.', 'Herşeyin anlamsızlaştığı Hiçbirşeyin duvarlara yansıdığı Kireç suyunun suyla karıştığı Aşkın dalga dalga yansıdığı Karnlık bir dağevindeyim ...', ARRAY['Türk Edebiyatı','Şiir','Şair Seyyah121']::text[], 8.5, '{"poet":"Şair Seyyah121","poet_slug":"sair-seyyah121","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ask-119-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya...', 'dunya-nilgun-akcay-lybw4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ruhumdaki dünya umut çiçekleriyle süslü.

Mutluluk şelalem sevgi yüklü...

Keşkelerimi gömdüm hayallerime.

Ömrümün şu son demlerinde..

Sararan hayat tuvalimde..

Son rötujlarımı iki renkle yaptım.

Anılarımı siyaha...

Ruhumu da beyaza boyadım.

Geleceğim ise..........

Rengarenk bir gökkuşağıydı.....

Altından geçtim....

Heyhat..

Değişen ne BEN.. ne kaderim oldu....

Nil............2002', 'Ruhumdaki dünya umut çiçekleriyle süslü. Mutluluk şelalem sevgi yüklü... Keşkelerimi gömdüm hayallerime. Ömrümün şu son demlerinde.. Sararan...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Akçay']::text[], 8.5, '{"poet":"Nilgün Akçay","poet_slug":"nilgun-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dunya-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimi...', 'kendimi-nilgun-akcay-o6xuh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karanlıklara dalıyorum..

Her adımda daha..daha derinlere..

Peşimde..

Her dakikası pişmanlık dolu anılar.

İçimdeki mevsimler hep Sonbahar.

Ve...Gözlerim aramakta geçmişimi.

Sonunda......

Kum saatim kırıldığında....

Her şeyin yok olduğu noktada.....

İnci tanesi bulan dalgıç gibi...

Bulacağım kendimi...', 'Karanlıklara dalıyorum.. Her adımda daha..daha derinlere.. Peşimde.. Her dakikası pişmanlık dolu anılar. İçimdeki mevsimler hep Sonbahar. Ve...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Akçay']::text[], 8.5, '{"poet":"Nilgün Akçay","poet_slug":"nilgun-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kendimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şey...', 'her-sey-nilgun-akcay-tbr80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yalnızım...

Hergün gibi bugün de yapayalnız...

Duvarlarla yıllardır arkadaşız.

Onlar dinler derdimi, kederimi.

Onlar kucaklar avutur beni...

Öylesine kırgınımki 

Haykırmak istiyorum artık...

Haykırmak........

Yok etmek istiyorum....

Beni hayata bağlayan duygularımı.

Savurmak istiyorum.

Sonsuzluğun ta derinliklerine...

Geçmişimi, anılarımı.....

Gömmek istiyorum.

Hayatı yalansız, riyasız...

Yaşamak istiyorum.....

Ama.....Herşey hayal biliyorum....

Gerçekler yüreğimde saklı....

Orda duygularım, anılarım, tüm hayatım...

Mermerin soğukluğu....toprağın kucağında....

Herşey...Evet...Herşey..ÖLÜM''e bağlı......', 'Yalnızım... Hergün gibi bugün de yapayalnız... Duvarlarla yıllardır arkadaşız. Onlar dinler derdimi, kederimi. Onlar kucaklar avutur beni......', ARRAY['Türk Edebiyatı','Şiir','Nilgün Akçay']::text[], 8.5, '{"poet":"Nilgün Akçay","poet_slug":"nilgun-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/her-sey-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Yakın....', 'bana-yakin-nilgun-akcay-ax0pb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kiminiz soğuk bulursunuz... Kiminiz korkunç....

Bense kavuşmayı beklerim sessiz sessiz....

Kiminiz yaşamdan neşe, mutluluk beklersiniz...

Bense ölümün kucağında simsiyah bir sevinç...

Sakın sanmayın beni DELİ....

Ben de yıllarca düşledim en güzel şeyleri..

İnsanların bana vermek istemediklerini.

Herşeyi... Ama herşeyi karşılıksız vermeyi...

Yanlızlığın sonsuzluğunda ızdırabı sevmeyi...

Bana dost..Bana yakın ÖLÜM öğretti...', 'Kiminiz soğuk bulursunuz... Kiminiz korkunç.... Bense kavuşmayı beklerim sessiz sessiz.... Kiminiz yaşamdan neşe, mutluluk beklersiniz... Be...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Akçay']::text[], 8.5, '{"poet":"Nilgün Akçay","poet_slug":"nilgun-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bana-yakin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip', 'garip-levent-umit-temiz-56nbk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şu garibin 

Gülüşü kime benzer 

Ağlayışı kime 

Kim anlar kavgasını 

Sevdasını kim 

Hangimizi tutar korkuları 

Umutları hangimizi 

Hangi yüreğe 

Yakın düşer selamı 

Uzaktır hangisine 

Söyleyin 

Kime benzer sesi 

Sessizliği kime', 'Şu garibin  Gülüşü kime benzer  Ağlayışı kime  Kim anlar kavgasını  Sevdasını kim  Hangimizi tutar korkuları  Umutları hangimizi  Hangi yüre...', ARRAY['Türk Edebiyatı','Şiir','Levent Ümit Temiz']::text[], 8.5, '{"poet":"Levent Ümit Temiz","poet_slug":"levent-umit-temiz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/garip-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçsam Göklere..', 'ucsam-goklere-nilgun-akcay-khjs3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'a target=''_blank'' href=''http://www.slide.com/s/YOTHY6Iyuz9Y1YyrBF02mx-aifqyV4K4? referrer=hlnk''>

Bir kuş olsam uçsam göklere.

Süzülsem sonsuzluğa.

Bulutların arasında

Ne geçmişi düşünsem,

Ne de geleceği düşlesem.

........Uçup..

..........Uçup..! 

...........Uçup da..

Kaybolsam.

Yorulsam.

Kırılsa kanadım.

Yerlere çakılsam.

Leş kargaları başıma üşüşse

............Eğer,

Mutlu olacaklarsa

Beni parçalara ayırsınlar.

Varsın olsun.

Özümden anlamayanlar.

Hiç değilse sözümden anlasınlar.

                                ADSIZ ÇOCUK..', 'a target=''_blank'' href=''http://www.slide.com/s/YOTHY6Iyuz9Y1YyrBF02mx-aifqyV4K4? referrer=hlnk''> Bir kuş olsam uçsam göklere. Süzülsem sonsu...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Akçay']::text[], 8.5, '{"poet":"Nilgün Akçay","poet_slug":"nilgun-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ucsam-goklere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acaba...', 'acaba-nilgun-akcay-niggp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her gün yeni bir seyler görüyorum....

Dönüyor dünya, dönüyor biliyorum...

Iste ben de mecburen yasiyorum...

Dar geliyor bu sokaklar...Özgür olamiyorum...

Bir seyler tutuyor beni....

Duygularim engel...Gidemiyorum.

Hep soruyorum kendi kendime....

Dünya nasil olurdu ben olmadan...diye

Ya insanlar....

Kim olurdu..Benim yerime aglayan...

Ölmek istiyorum diye hergün haykiran..

Ya ugruna yasadigim umutlarim...

Kurtarabilir miydim onlari...

Yok olan her zerremi....

Yeniden diriltebilir miydim..? 

Acaba..?', 'Her gün yeni bir seyler görüyorum.... Dönüyor dünya, dönüyor biliyorum... Iste ben de mecburen yasiyorum... Dar geliyor bu sokaklar...Özgür ...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Akçay']::text[], 8.5, '{"poet":"Nilgün Akçay","poet_slug":"nilgun-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/acaba-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttum...', 'unuttum-nilgun-akcay-uuk3b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir anda kendimi unuttum..

Unuttum ki... Ben lanetli biriydim..

Nasıl.... nasıl mutlu olabilirdim..

Unuttum... dünyada yerim olmadığını

Renklerimin hep siyah...

Duygularımın hep hüzün ve nefret olduğunu...

Ne zaman ki...uzattığım elim boş kaldı...

Hatırladım o zaman...

Ben yanlız ölümle dans eder...

Ve ölümle yaşayabilirdim.....', 'Bir anda kendimi unuttum.. Unuttum ki... Ben lanetli biriydim.. Nasıl.... nasıl mutlu olabilirdim.. Unuttum... dünyada yerim olmadığını Renk...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Akçay']::text[], 8.5, '{"poet":"Nilgün Akçay","poet_slug":"nilgun-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/unuttum-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurşunlanan Sokaklarda', 'kursunlanan-sokaklarda-caglar-varol-qsh1c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sıradan bir eylül akşamı solgun bir yüzdün aklımda

içinde kötü bir his vardı mutsuz değildin aslında

kime sorsan bu mevsimi çok uzaktı güzel şeyler

kurumak için delirsen de dinemezdi yağmurlar

el sallayan çocuklardık arabaların camlarında

herkes sustu bir biz kaldık kurşunlanan sokaklarda

susma n''olur ben gidince kendine bir şarkı söyle

oralarda bir yerlerde benim içinde mutluluk var', 'sıradan bir eylül akşamı solgun bir yüzdün aklımda içinde kötü bir his vardı mutsuz değildin aslında kime sorsan bu mevsimi çok uzaktı güzel...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Varol']::text[], 8.5, '{"poet":"Çağlar Varol","poet_slug":"caglar-varol","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kursunlanan-sokaklarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evet', 'evet-knight-errant-gz1bl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Neydi hayatında aldığın en güzel hediye? 

Vesikalık fotoğraftan bakılarak çizilmiş karakalem bir portre? 

Yoksa bir ayıcık mı yumuşak tüylü ve şişman? 

Peluş bir terlik? Yada bir kedi, bir hayvan? 

Yada en basitinden bir parfüm, 

Olmadı bir biblo, kupa yada mum...

Değildi hiçbiri benim en güzel hediyem

Çünkü ben asıl hakettiğim hediyeyi almadım

Çok bişey istemiyorum aslında senden

Bırak diğerlerini, şaşalı hediyeleri onların olsun

Ama sende bırak artık ağzında düğümlenmiş o sözcüğü

Dört harf istiyorum senden sadece dört harf

Çok mu? değil, gerçekten değil

Ben burda senin için şiirler yazarken eğer sen

Eğer zaten o dört harfi söylemiyorsan

İstemiyorum bırak o da senin olsun

Tüm masumluğuyla. hüznüyle, yalnızlığıyla...

Ama şunu da bil ki, 

O dört harf için ben en büyük yüklerin altına girdim...

Ve onların altında kalmadım...

Ama sen...sen sadece o dört harfin altında ezilip kaldın....', 'Neydi hayatında aldığın en güzel hediye?  Vesikalık fotoğraftan bakılarak çizilmiş karakalem bir portre?  Yoksa bir ayıcık mı yumuşak tüylü ...', ARRAY['Türk Edebiyatı','Şiir','Knight Errant']::text[], 8.5, '{"poet":"Knight Errant","poet_slug":"knight-errant","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/evet-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenim', 'ogretmenim-oktay-avci-b1k9f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ÖGRETMENİM Öğretiyorsun bana bilmem gerekeni veriyorsun bana almam gerekeni seviyorsun beni sevmesemde seni sana çok şey borçluyuz Öğretmenim.bir an düşünmek istesem seni dalırım tatlı güzel hayallere düşünüp anlayabilsem bana yaptıklarını.kulun kölen olurdum.Öğretmenim.sen senin olan herşeyi sevgini şevkatini bilgini, hiç çekinmeden veriyorsun herşeyini.öğretmenim.herkesin memleketi mekanı var senin buda yok öğretmenim ilden ile dolaşırsın hep birşeyler vermek için canım Öğretmenim', 'ÖGRETMENİM Öğretiyorsun bana bilmem gerekeni veriyorsun bana almam gerekeni seviyorsun beni sevmesemde seni sana çok şey borçluyuz Öğretmeni...', ARRAY['Türk Edebiyatı','Şiir','Oktay Avcı']::text[], 8.5, '{"poet":"Oktay Avcı","poet_slug":"oktay-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/ogretmenim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Saati 2', 'siir-saati-2-ozhan-arioglu-917du', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölümün soğuk nefesi vardı bugün gök yüzünde, 

Bedenim rüzgarla birdi ama kalbim meçhullerde.

Fırtınalar kopardı sensiz yüreğimde, 

Gözlerim gözlerinde ama ruhum hayallerde...', 'Ölümün soğuk nefesi vardı bugün gök yüzünde,  Bedenim rüzgarla birdi ama kalbim meçhullerde. Fırtınalar kopardı sensiz yüreğimde,  Gözlerim ...', ARRAY['Türk Edebiyatı','Şiir','Özhan Arıoğlu']::text[], 8.5, '{"poet":"Özhan Arıoğlu","poet_slug":"ozhan-arioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/siir-saati-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm', 'gulum-vedat-koparan-yfbo5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mavi hülyalarda

Sevdayı yudum yudum içtiğim

Halden bilirim  halden geçtiğim

Yollar var aşılır yollar var ulaşılır 

Dost yüreklerle 

Elbet bir gün gelir buluşulur..

Aç müziğinin kutusunu 

Nota nota gireyim

Aç yüreğini geleyim 

Sen Gül ol

Dikenini  batır 

Yeter ki razıyım aksın kanım 

Karanlıklarım aydınlansın..

Vedat.K  28-12-2002', 'Mavi hülyalarda Sevdayı yudum yudum içtiğim Halden bilirim  halden geçtiğim Yollar var aşılır yollar var ulaşılır  Dost yüreklerle  Elbet bi...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gulum-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Nasıl Hatırlasam', 'seni-nasil-hatirlasam-vedat-koparan-2obw5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni Nasıl Hatırlasam 

Seni bana neler hatırlatmaz ki 

İnce bir tül gibi çekerken

Gök yüzünden bulutları 

Hafiften esen yellerde 

İnceden yağan yağmur tanelerinde 

Gözlerin..! ! 

Gözlerimle nasılda harelenir 

Mevsim dönüşür hava üşür 

Ben senle ısınırım 

Bahar açımları olur 

Renk renk çiçeklerde gelirsin 

Yaz olur güneş sıcaklığında 

Başaklar salınır meltem esinleriyle 

Ben senle sımsıcak olurum 

Sen nesin 

Seni bana neler getirsin

Hatırıma öylece yer edesin 

Ay düşümü

Gecelerden denize 

Deniz otobüsü yanaşır sahile 

Seni hatırlarım 

Telaşlı yolcular gelir gözümün önüne 

Biride senmisin diye 

Bir çocuk ağlaması duyarım 

Gözleri yaşlar içinde 

Akarım kendimce o yaşlar da 

Deniz gibi çeker beni.. 

Vedat.K 2002', 'Seni Nasıl Hatırlasam  Seni bana neler hatırlatmaz ki  İnce bir tül gibi çekerken Gök yüzünden bulutları  Hafiften esen yellerde  İnceden ya...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/seni-nasil-hatirlasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tiyatro', 'tiyatro-zeliha-oztepe-3mw4b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu tiyatranın ilk sahnesi haksızlık dolu

 Güvendiğin aktör can dediğin, 

 Can evinden vuruyor.

 Neye benzer bu bilirmisin? 

 Bilemezsin; daha yaşamadın ki kızım! ..

 Öyle bir sahneki bu

 Döven değil, dövülen suçlu

 İki yüzlü değil, düsrst suçlu

 Haramı işleyen değil, işlemeyen suçlu

 Alkışlar, sevgiler, övgüler ona

 Buna dayanmak zor, dayanamazsın

 Ayakta kal yıkılma kızım! ..

 Bu sahnede rol arkadaşın, kardeşinede güvenme! 

 Sen aciz kül kedisi, nötrdamın kamburu

 Polyana gibi mutluluk oyna

 Fadime anam gibi, tevekkürde ol

 Bu rolü başar, başar ki; 

 Dayana bilesin kızım''..

 Unutma, bu oyun iki perdelik

 İlk sahnede rolün acılarla dolu

 Dürüst olursan, kazanan da sen olursun

 İkinci perdede sen kralsın, şahsın

 Her acının, direhem direhem, bedelini alacaksın

 Sabırlı ol, ol ki  ikinci perdede

 Adın NeoN''da kalsın kızım! ..', 'Bu tiyatranın ilk sahnesi haksızlık dolu  Güvendiğin aktör can dediğin,   Can evinden vuruyor.  Neye benzer bu bilirmisin?   Bilemezsin; dah...', ARRAY['Türk Edebiyatı','Şiir','Zeliha Öztepe']::text[], 8.5, '{"poet":"Zeliha Öztepe","poet_slug":"zeliha-oztepe","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/tiyatro-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serseri', 'serseri-umit-kurtulus-saepz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sence  biz neyiz serseri

Sanmaki gülüm serseri ağlamaz

Serseri ağladımı kimse susturamaz..

Serseri konuştumu kimse susturamaz...

Unutma güzel kız herkes SERSERİ olamaz...', 'Sence  biz neyiz serseri Sanmaki gülüm serseri ağlamaz Serseri ağladımı kimse susturamaz.. Serseri konuştumu kimse susturamaz... Unutma güze...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kurtuluş']::text[], 8.5, '{"poet":"Ümit Kurtuluş","poet_slug":"umit-kurtulus","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/serseri-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşey biterken', 'hersey-biterken-umit-kurtulus-cgjgc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her şeyin sonu ölümse 

Ölümden korkmak niye

Ecel gelip alsın canımı diye

Bunca sene beklemek niye

Ama şu berbat dünyaya geldik birkere 

Ne yapalım yaşam böyle

Aslında ölmek için ecele ne gerek 

Zaten içinde yoksa yaşamak için bir istek

Ama dünyada böyle güzel be dostum 

Acısıyla tatlısıyla katlanmak gerek.', 'Her şeyin sonu ölümse  Ölümden korkmak niye Ecel gelip alsın canımı diye Bunca sene beklemek niye Ama şu berbat dünyaya geldik birkere  Ne y...', ARRAY['Türk Edebiyatı','Şiir','Ümit Kurtuluş']::text[], 8.5, '{"poet":"Ümit Kurtuluş","poet_slug":"umit-kurtulus","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hersey-biterken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-serdar-ada-vw5os', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yağmur Gibi Nemli Olsada Gözlerim 

Aşıkınla Yanar Bedenim Buğlanır Yüreğim

Süzülür Kalbim Gecenden Güneşine 

Gök Kuşağı Olur Sana Dair Düşlerim...', 'Yağmur Gibi Nemli Olsada Gözlerim  Aşıkınla Yanar Bedenim Buğlanır Yüreğim Süzülür Kalbim Gecenden Güneşine  Gök Kuşağı Olur Sana Dair Düşle...', ARRAY['Türk Edebiyatı','Şiir','Serdar Ada']::text[], 8.5, '{"poet":"Serdar Ada","poet_slug":"serdar-ada","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ask-121-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmece', 'bilmece-hasan-kagan-yayla-zc8yj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kara gözlerinde yanar bir ışık, 

Altından mı, billurdan mı, nurdan mı? 

Tel tel olmuş siyah zülfün dolaşık; 

Atlastan mı, ipekten mi, sırdan mı? 

Kirpikler bir perde gözünü saklar.

Kapanır parmaklık görünmez aklar.

Ya ak tenindeki kızıl dudaklar? 

Alevden mi, ateşten mi, kordan mı? 

Yanağında gamzen o kadar derin; 

Kaybolur içinde gül kokan terin.

Ey güzel o senin beyaz ellerin, 

Pamuktan mı, sedeften mi, kardan mı? 

Gülünce yüzünde güller açılır; 

Bu dilim lal olur, aklım şaşırır.

Ne zaman bir baksam gözün kaçırır, 

Korkudan mı, edepten mi, ardan mı?', 'Kara gözlerinde yanar bir ışık,  Altından mı, billurdan mı, nurdan mı?  Tel tel olmuş siyah zülfün dolaşık;  Atlastan mı, ipekten mi, sırdan...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kağan Yayla']::text[], 8.5, '{"poet":"Hasan Kağan Yayla","poet_slug":"hasan-kagan-yayla","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bilmece-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayaller', 'hayaller-levent-ongun-e237g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beden zindandayken gönül kuş olsa

Fikir kanatlanır ve hayal olur

Gerçekler gerilip hep yokuş olsa

Aldırmaz ufuklar ona yol olur

Her zafer önce bir hayalle başlar

Hayal şekillenir bir murat olur

İdeal ve hedef derken savaşlar

Sonunda hayaller hakikat olur

Hayalin zamanı gençlik çağıdır

Toz pembe hayaller alır götürür

Gerçekler genç için ayak bağıdır

Kaf dağı da neymiş gökte oturur

Rüyada asası tacı da olsa

Gece boyu kişi sultandır beydir

Gerçeğin zaferi acı da olsa

Yine de hayaller çok güzel şeydir', 'Beden zindandayken gönül kuş olsa Fikir kanatlanır ve hayal olur Gerçekler gerilip hep yokuş olsa Aldırmaz ufuklar ona yol olur Her zafer ön...', ARRAY['Türk Edebiyatı','Şiir','Levent Ongun']::text[], 8.5, '{"poet":"Levent Ongun","poet_slug":"levent-ongun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hayaller-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Plaj', 'plaj-levent-ongun-3e6ni', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Denizin dalgaları kıyılara çarpmakta

Sahilin pisliğini kumsala fırlatmakta

Nerde asude ufuk nerde et pazarı kum

Kadın erkek karışmış birbirine bakmakta

Gözlerim denizlerde hep maziyi arıyor

Umutsuz bakışlarla ufukları tarıyor

Güneş cehennem gibi plajdaki insanlar

Ahirete kalmadan bu dünyada yanıyor

Saçının tellerini saklayan ninem nerde

O günleri andıkça insan düşüyor derde

Torunlar çok değişti gün başka bir gün oldu

O nineler kayboldu bilinmeyen bir yerde', 'Denizin dalgaları kıyılara çarpmakta Sahilin pisliğini kumsala fırlatmakta Nerde asude ufuk nerde et pazarı kum Kadın erkek karışmış birbiri...', ARRAY['Türk Edebiyatı','Şiir','Levent Ongun']::text[], 8.5, '{"poet":"Levent Ongun","poet_slug":"levent-ongun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/plaj-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-mecdan-mahackale-wlbne', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hasret, Gözyaşı Olupta Aktı

O Güzelim Yanaklardan

Son Bir Kez Daha Baktı

Yarini Beklermişçesine 

Uzaklardan....

Gençliğim, Su Olup Aktı

Bir Bedevinin Su Kabından

Hala Bir Umudun Kaldı

Gittikçe Hayasızlaşan

Yarınlardan...

                                                  Erzurum-2000', 'Hasret, Gözyaşı Olupta Aktı O Güzelim Yanaklardan Son Bir Kez Daha Baktı Yarini Beklermişçesine  Uzaklardan.... Gençliğim, Su Olup Aktı Bir ...', ARRAY['Türk Edebiyatı','Şiir','Mecdan Mahaçkale']::text[], 8.5, '{"poet":"Mecdan Mahaçkale","poet_slug":"mecdan-mahackale","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hasret-83-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişim', 'degisim-oktay-avci-9ryg0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Degişim Türktüm Dogruydum Çalışkandım Eskidendim Onurluydum Gururluydum insandım Oda eskidendim', 'Degişim Türktüm Dogruydum Çalışkandım Eskidendim Onurluydum Gururluydum insandım Oda eskidendim...', ARRAY['Türk Edebiyatı','Şiir','Oktay Avcı']::text[], 8.5, '{"poet":"Oktay Avcı","poet_slug":"oktay-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/degisim-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Varız', 'hep-variz-oktay-avci-49dvy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hep varız Güneşin parçasıyız biz Karanlığada atsanız aydınlatırız soguğada atsanız ısıtırız biz Denize atsanız bogulurmuyuz yelken açarız kanatlanırız martı oluruz uçarız özgürlüğe', 'Hep varız Güneşin parçasıyız biz Karanlığada atsanız aydınlatırız soguğada atsanız ısıtırız biz Denize atsanız bogulurmuyuz yelken açarız ka...', ARRAY['Türk Edebiyatı','Şiir','Oktay Avcı']::text[], 8.5, '{"poet":"Oktay Avcı","poet_slug":"oktay-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/hep-variz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söz Yok İçinde', 'soz-yok-i-cinde-senay-erdogan-as25u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bunca zaman bir çok resme baktım ben.

Sanabenzeyen yüz yok içnde.

O kadar çok isimler var ama, 

Sana benzeyen yüz yok içinde.

Karşıdan gelişin manken misali, 

Sana söylenecek söz yok içnde.

Rakamlar puanlar yetmiyor canım, 

Sana verecek not yok içnde.

Oturman kalkman bir başka güzel, 

Sözün sohbetin herkesten özel, 

Sözlükler lügatlar yetmiyor canım, 

Seni anlatacak söz yok içnde.', 'Bunca zaman bir çok resme baktım ben. Sanabenzeyen yüz yok içnde. O kadar çok isimler var ama,  Sana benzeyen yüz yok içinde. Karşıdan geliş...', ARRAY['Türk Edebiyatı','Şiir','Şenay Erdoğan']::text[], 8.5, '{"poet":"Şenay Erdoğan","poet_slug":"senay-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/soz-yok-icinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Umut', 'bir-umut-sahin-yenilmez-iq201', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tek bir umuda bağlı bir insan hayatı

Eğer karamsarlığa düştüyse

Ve olmaz dediğinde

Önüne küçücük bir umut bile çıksa

O zaman sarılır hayata iki elle

Ve artık ondan mutlusu yoktur

Ama olurda hiç bir umudu kalmazsa

O zaman onun için hayatın bir anlamı yoktur

İnsan hayatı umutlarla doludur

Kimi yeni umutlar bulur kiminin umutları yok olur

Eğer tutunacak bir dalı da yoksa eğer

O insanın zaten ölmeden kalbi durur.', 'Tek bir umuda bağlı bir insan hayatı Eğer karamsarlığa düştüyse Ve olmaz dediğinde Önüne küçücük bir umut bile çıksa O zaman sarılır hayata ...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yenilmez']::text[], 8.5, '{"poet":"Şahin Yenilmez","poet_slug":"sahin-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-umut-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Parça', 'bir-parca-sahin-yenilmez-9ox9x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne zaman bir parça aklıma gelsen gözlerim doluyor

Ağladığımda oluyor bazen 

Yanlızlık çok kötü vurdu beni

Sanki hatıralarım benimle dalga geçiyor.

Bir parça rüzgar vursa yüzüme

Eski günleri esiyor

Bir damla gözyaşı aksa gözlerimden 

Yanaklarımdan süzülüp yüreğime akıyor.

Bir parça sevgi vardı yüreğimde

Halada aynı yerinde duruyor

Sen olmasan bile yanımda

Bana sensizliği haykırıyor.

Çığlık çığlığa şarkılar söylüyorum

Kimbilir belkide içimi döküyorum

Beni dinleyen ise

Benden başkası olmuyor.

Dediğim gibi bir parça canım var

Hep acıları yaşayan

Benim bedenimde senin canında var

Al artık onu kurtulayım.

Yanlızlığı taşıyamıyorum artık

Çok ağır geliyor

Bir parça tebessüm varken yüzümde

Oda yıllara yeniliyor.', 'Ne zaman bir parça aklıma gelsen gözlerim doluyor Ağladığımda oluyor bazen  Yanlızlık çok kötü vurdu beni Sanki hatıralarım benimle dalga ge...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yenilmez']::text[], 8.5, '{"poet":"Şahin Yenilmez","poet_slug":"sahin-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-parca-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Ağası', 'gul-agasi-ahmet-ozdemir-yu0fg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kimine toprak ağası diyorlar, 

Kimine sendika ağası; 

Kimini de benzetiyorlar hıyar ağasına! 

Gönül dostları sanıyordu, 

Çoğu günün dostuymuş.

Daha dün; 

Yüzüyordu sevgi denizinde kulaç kulaç, 

Okşayanlar sırtını her gün, 

Anladı ki içini oymuş.

''Her güleni dost sanma'' dediği ataların

Demek buymuş.

Uğradığı her ihanete olsun diye andaç, 

Aldırmadan alına, akına, karasına; 

Bir gül fidanı dikti yüreğinin ortasına.

Kim söylemiş, bilmem ki, kim kimden duymuş; 

Şimdi de adını çıkarmışlar fakirin

Gül ağasına! ...

Ahmet ÖZDEMİR', 'Kimine toprak ağası diyorlar,  Kimine sendika ağası;  Kimini de benzetiyorlar hıyar ağasına!  Gönül dostları sanıyordu,  Çoğu günün dostuymu...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özdemir']::text[], 8.5, '{"poet":"Ahmet Özdemir","poet_slug":"ahmet-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gul-agasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevinç', 'sevinc-cem-bektas-3g5r8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevinç derler tüm ideallerin özü, 

Derler ki bir de sevilmekmiş çocukça

Sevilmekmiş yaşamak denen giz.

Her yer gül kokuyor, 

Her yer nergiz.

Bir hayalsin ama gerçekleşebilirsin, 

Bir dua veya bir damla gözyaşı.

İçinde gizlenirken kuşlar mağaraların

Bir şarkı söylerler hep sen bilmezsin...

Çok severler neyi sevseler, 

İnanılmaz çok severler hem de.

Ve dinlesen gurbetten bahsederler hep, 

Yeşil ovalarından bahsederler memleketlerinin.

Mağaralar karanlıktır şarkıları ak, 

Nasıl çok seviyorum, nasıl çok

Git merak edersen kuşlara bak...

Ne vakit kalbinden gelen bir elem

Karartırsa gün ışığını, o dem

Bir güvercin yükselt gökyüzüne

Elim uzansın

Gökyüzünden yüzüne.

Bir hayal ama gerçekleştirebiliriz, 

Her yer gül kokuyor, 

Her yer nergiz.', 'Sevinç derler tüm ideallerin özü,  Derler ki bir de sevilmekmiş çocukça Sevilmekmiş yaşamak denen giz. Her yer gül kokuyor,  Her yer nergiz....', ARRAY['Türk Edebiyatı','Şiir','Cem Bektaş']::text[], 8.5, '{"poet":"Cem Bektaş","poet_slug":"cem-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevinc-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sana Aşıktım Nüveylâ', 'ben-sana-asiktim-nuveyl-ethem-vayvayli-wven0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yapraklarda

gece alevinin dolaştığı

topraklarda ılıman

hürriyetin

pencerelerde kaçak

yaşamın

toplandığı sürgünlerde

ben sana aşıktım nüveylâ! ...

kırmızının revnaklara

sarıldığı

kırağının

örttüğü pınarlar başında

suskun manolyalar gibi

ben sana aşıktım nüveylâ! ...

titrek kirpiklerinde

yüreğin buğu buğu

geldin içime

alevin ve ayazınla

ağlaştık oysa

göğsümüzü gezen 

güz melteminin altında

ağlaştık gözgöze

ağlaştık nüveyla! ...

18.10.2000', 'yapraklarda gece alevinin dolaştığı topraklarda ılıman hürriyetin pencerelerde kaçak yaşamın toplandığı sürgünlerde ben sana aşıktım nüveylâ...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ben-sana-asiktim-nuveyla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su', 'su-edip-koroglu-k9qhj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uykusunda gördüm onu

                                 >

Korkuyorum! ! ! 

Yağmalanmış, sahiplenilmiş bir evden sadece küçük bir köşe istediğim çocuk odasında varya hani, -

yeşil örtülü, demirden, buzz gibi demirden divanın altıdır orası.Karanlıktır.En çok karanlıktır bilemezsiniz

Dilerseniz hiç çıkmam. Varlığımı anlamazsınız ben ordayken.Yalvarıyorum bırakın beni! ! ! 

Kendi evinde sığıntı olmaktır bu, varsın olsun sığanabileceğim bir avuç yere razıyım ben.

Ne olur istemeyin, istemeyin onu benden > işte bakın ne kadar sefilim.Koca-

bir yürekten kala kala bir divan altı, karanlık, melun bir köşe kalmış elimde(tek mabedim)

Alamut kalesi kadar ele geçilmez, Kabe kadar kutsal sıcak sımsıcak bir dize kadar anlamlı.Ve bir okadarda korunaksız.

              Ve şimdi, daha sonra ama hep

Korkuyorum! ! ! 

Uykusunda gördüm onu

                                    >

Kim isterdi, neden isterdi. Dedim ya lanet melun bir yerdir orası...

   Bir tarafında içki masaları kuruldu yüreğimin

   Bir tarafında ihanetin en unutulmazı

   ve birer birer zaptedildide

   kimsecikler çalmadı, çalamadı belkide

   yeşil örtülü, demirden buzz gibi demirden

   divan altı, bir avuç kadar dünyamın kapısını...

Uykusunda gördüm onu

                                  >

Korkuyorum! ! ! 

Yürek narindir, yürek ince 

yürek kimsenin bilmediği gibidir

duvarlar yükseldiğince...

>

Ve sen şimdi, 

o kan damlayan gözlerimi

seslenilensiz, seslenilensiz olan sözlerimi istiyorsun benden

Korkuyorum anla beni

-Rüyalardan mı uyandım Tanrım! Her yerde benim ellerim

Karanlık; ürperiyorum karanlığımdan

Anlamsız bütün bunlar, Anlamsızlıklardanmı korkuyorum

Yoksa karanlıklardanmı

Gel diye çağırıyor ellerden biri

diğeri kolumdan tutmakta

bir başkası sensin > diyor

duvardan duvara çarpıyorlar beni

Kan sıçrıyor etrafa.Hıçkırık doluyor bedenim

Dehşetle kendime bakıyorum

            YOK! ! ! 

>

    Bitsin artık sabah olsun istiyorum

    güneşi görmek istiyorum

    duvardan duvara çarparken umut

    yarın olsun istiyorum

    duvardan duvara çarparken bedenim

    bilirim sabahı vardır her gecenin 

                 duvarda senin izin

Uykusunda gördüm onu

                            > 

                                                                                         SU 

                                                                     12.05.1999 

                                                          Kahta/Adıyaman', 'Uykusunda gördüm onu                                  > Korkuyorum! ! !  Yağmalanmış, sahiplenilmiş bir evden sadece küçük bir köşe istediği...', ARRAY['Türk Edebiyatı','Şiir','Edip Köroğlu']::text[], 8.5, '{"poet":"Edip Köroğlu","poet_slug":"edip-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/su-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayaz', 'ayaz-ali-ayyildiz-zso7l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ayaza kesti dünya, sevdam buz tuttu

Unutmam diyen gönül ne tez unuttu

       Yansa da uzaktan uzağa bir yürek

       Tükendi adım adım sükut ederek

Varılmadı farkına gerçek ile yalanın

Uğruna bir ömür köle olanın

       Hasretinden yanıp da hiç söylememek

       Tüketti adım adım sükut ederek

Değerler hep değişmiş; güzellik elem

Hayale hasret kalmak, gerçeğe sitem

       Mutluluğa üzülmek, sayrılığa sevinmek

       Tüketir adım adım sükut ederek

Gerçeğine yabancı olmak hayalin

 Kıramamak kilidini aşk sözlerinin

       Yürek kan ağlarken gülmek ne demek

       Tükenmek adım adım sükut ederek

Yokluğuna gülümsemek, unutuldu zannetmek

Kanayan bir yaranın üzerini küllemek

       Tükenmek, tükendiğini bilemeden tükenmek

       Tükenmek adım adım sükut ederek', 'Ayaza kesti dünya, sevdam buz tuttu Unutmam diyen gönül ne tez unuttu        Yansa da uzaktan uzağa bir yürek        Tükendi adım adım sükut...', ARRAY['Türk Edebiyatı','Şiir','Ali Ayyıldız']::text[], 8.5, '{"poet":"Ali Ayyıldız","poet_slug":"ali-ayyildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ayaz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlaşılmak', 'anlasilmak-mustafa-sureyya-sezgin-prm43', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Söyle nasıl bir duygudur

Anlaşılmak, 

Ya da anlaşılmamak? 

Bu iki duygu

Arasında yalpalamak? 

Geldik gidiyoruz be güzelim

Ve sen hala

Bozuk bir plak gibi

Anlaşılamadığından dem vuruyorsun! ..

Anlaşamayınca da

Güzellikleri öldürüyorsun! ..

Kim kimi anlamış ki bu dünyada? 

Sokrat da anlaşılamamış

Hallac-ı Mansur da! ..

Birine zehir sunmuşlar, 

Diğerini dara çekmişler...

İster anla, ister anlama

Ben sana kendimi sunuyorum

Bütün anlaşılmazlığımla! ..

Hadi ilmek ilmek çöz beni...

Her ilmekte

Kendini anlat bana

Sonsuz bir evren gibi

Esrarengiz ve çözümsüz

Ve anlaşılmaz olsun! ..

Mustafa Süreyya Sezgin

İstanbul,22.07.1997', 'Söyle nasıl bir duygudur Anlaşılmak,  Ya da anlaşılmamak?  Bu iki duygu Arasında yalpalamak?  Geldik gidiyoruz be güzelim Ve sen hala Bozuk ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Süreyya Sezgin']::text[], 8.5, '{"poet":"Mustafa Süreyya Sezgin","poet_slug":"mustafa-sureyya-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/anlasilmak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen efsanelerin kadınısın.', 'sen-efsanelerin-kadinisin-abacan-ahmet-nazim-424f2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ey potemkin zırhlısının duvarlarına sırnaşan kadın

menopolisin harabelerine kazınmış senin adın...

sen ki, narcissusun ayranını içtin

gözlerinde deliorman türküleri ve zeusun sihri

belindeki kuşağa dolanmış pegasusun mührü..

şututgartta zangırdayan pelegreni katedrali

destanını senin için yazmış keşanlı ali

bundan ne ikitelli haberdar ne bab-ı ali

fakirlikten geberiyor zavallı somali...

kutsal süleymanın hazinelerine saklanan güneş

senin varlığınla alevlenecek bu ateş

zümrütler ve yakutlarla donandı marakeş

senin yüzünden bütün yiğitler oldu serkeş...

ey bahtımı karartan simden yapılma güneş

kaf dağını uzattım dört elif miktarı

senin ellerinden içtim ölümsüz nektarı

zümrüd-ü anka kuşunun bıraktığı...

izleri takip ederek buldum seni yaşatan varı...

machu pichu''daki inka harabelerinde sen

bin yıllık iran halılarında sen

gökkuşağında, ebemkuşağındaki ölümsüz desen

ölürüm yoluna, ah bir gel desen...

kutsal ganj nehrinde yıkanan sendin

mataşi-nehru''nun sutrasındaki ben''din

işvandana ve keralanın nirvasına erdin

sen, yüzyılların alıp getirdiği seherdin....

isfehanda semerkantta yürüyen kervan

hipokratının ölümsüz reçetesindeki derman

olimpos dağında tanrıların yazdığı ferman

senin yoluna kurban olayım ben aman...

senin için savaştı epimetus ve promete

senin için fethetti avrupayı imparator mete

senin için ölüyorum ah bir ''he'' de...

yoksa sadist olurum, üstadım marki de sade

biliyorum, diyorsun artık gel sadede...', 'ey potemkin zırhlısının duvarlarına sırnaşan kadın menopolisin harabelerine kazınmış senin adın... sen ki, narcissusun ayranını içtin gözler...', ARRAY['Türk Edebiyatı','Şiir','Abacan Ahmet Nazım']::text[], 8.5, '{"poet":"Abacan Ahmet Nazım","poet_slug":"abacan-ahmet-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sen-efsanelerin-kadinisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Kişilik Dans', 'tek-kisilik-dans-seyfettin-bilal-ozluk-h1zg8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dans eder mi insan kendisiyle

Sokak ortasında pervasızca

Gökte ay bulutların arasında

Trafik lambası devamlı yanıp sönüyor

Yeşil, sarı, kırmızı

Dakikalarca ve saatlerce

Hiç tıklamadan...

Hava da hafiften bir kömür kokusu

Uzakta iki çift

Yürüyor sarmaş dolaş

Dans ediyorum yine kendimle

Gülüyorum kendime...

Uğultu başlıyor kulağımda 

En sevdiğim şarkı çalıyor

Karşı ki kasteçide

Diyor ki; 

''Sen aldırma''

Yine gülüyorum kendime...

Kaldırım taşlarını sayıyorum

Bir noktada duruyorum

İşte ben bu kadarlığım...

Bir o yana bir bu yana yalpalıyorum

Alkol de almadım kullanmıyorum 

Ama niye yalpalıyorum? 

Evet

Hayatın yükünü kaldıramıyorum

Bu ağırlıkla yürünmez ki

Yoruldum, oturuyorum kaldırıma

Süratle bir araba geçiyorum hemen önümden

Ve ileride kayboluyor karanlıkta...

Sonra dudağımda bir şarkı sözü

''Sen burdan gittin gideli''

Evet! 

Sen benden gittin gideli böyleyim

Nereye gittin niye gittin 

Bilmiyorum? 

Neden gittin, neden? 

Saat gece yarısını çoktan geçmiş

Göz kapaklarım hafiften sızlıyor

Gitmek istemiyorum buralaradan

Çünki yine başlayacak sorular

Zamansız ve tek cevap vereceğim

''Bilmiyorum''

İşte bu cevap deli edecek

Ama anla beni ne olur anla, 

İstemiyorum seni 

Çık ne olur sevme beni

Uğraşma boşuna yalancı sevgili

Sevmiyorum seni sevemiyorum...

İnat uğruna başladık

Şimdi inat bitti

Gerçekleri görmelisin

Olmuyor olamıyorum eskisi gibi

İhanet etmedim edemedim

Ama yine de seni sevemedim...

Ne diyorum ben kendi kendime

Kiminle konuşuyorum ben

Gülüyorum

Kendime gülüyorum

Evet

Kendime gülüyorum 

İnsan tek başına 

Sokak ortasında dans edermi? 

Demek ki edermiş...', 'Dans eder mi insan kendisiyle Sokak ortasında pervasızca Gökte ay bulutların arasında Trafik lambası devamlı yanıp sönüyor Yeşil, sarı, kırm...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/tek-kisilik-dans-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-seyfettin-bilal-ozluk-g09z6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hani rahipler vardır

Kapalı bir oda da tek başlarına

Ve günahkarlarıyla günah çıkartırlar ya

Ben de tek başıma çaresiz

Seni yaşıyorum ve yaşatıyorum

Şimdi günahlarımı çıkardım

İçimde bir tek ruh kaldı

O da sevgi...

Geçmişte ne yaşananlar umrumda

Ne de yaptığım hatalar

Hepsini teker teker afaroz ettirdim

Yalnızım, savunmasız biçare

İçimdeki senle...

Ne içimde kendimi aldatma duygusu

Ne de kahrolası o polyannacılık...

Şimdi beni günahkar kılacak bir aşk arıyorum

Bütün günahım sevgi olsun

Ancak içinde ihanet olmasın

Kalbimde ki sevginle...

Ben yaşadım seni

Ve günahlarımı

Bırak bütün suçum aşka özlem olsun

Ne günah çıkarayım ne de rahipe ihtiyaç duyayım

Kimse dokunmasın bedenimi

Kimse okşamasın kalbimi

Ben yaşıyorum sonsuz ufkun güzelliğini

Rahibe sen git kilisene

Günahkar olmak istemiyorum.

Seni ve seninle yaşamayacağım güzelliklere

Seni seviyorum aşkım ve günahlarım...', 'Hani rahipler vardır Kapalı bir oda da tek başlarına Ve günahkarlarıyla günah çıkartırlar ya Ben de tek başıma çaresiz Seni yaşıyorum ve yaş...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/seni-seviyorum-105-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Aşkım', 'son-askim-mehmet-ali-cibikli-mrx3m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Son aşkımsın sen benim, son göz ağrım, 

Son sevgilim olarak kalacaksın.

Bu sana son sözüm, sana son çağrım, 

Yalnız benimsin, benim olacaksın.

Çaresizlik diz boyu bende şimdi, 

Güllerini soldurma aşk bahçemin.

Sevginle yaşadım, aşkın çareydi, 

Bırak tekrar yeşersin, bende sevgin.

Karanlık gecemin, tek yıldızısın, 

En koyu gecemde, beni aydınlat.

Bende bitmez ağrı, dinmez sızısın, 

Suskun yüreğime, sevgileri kat.

Seni sevmeye sanki yemin ettim, 

Unutmadım seni, bir kere bile.

Bir an bile bitmez, sana hasretim, 

İnan ki mecburum, seni sevmeye.

Doktorum ol, sar şu aşk yarasını, 

Acılarım dinsin, üzüntüm bitsin.

Seni seviyorum, anlamadın mı? 

Dermanım sensin, ilacım sensin.

Ümidimsin, ışığım, aşığımsın, 

Sen, benim gönlümde, yanan fenerim.

Aşk çorbamda en güzel kaşığımsın, 

Hep seni sevdim ben, seni severim.', 'Son aşkımsın sen benim, son göz ağrım,  Son sevgilim olarak kalacaksın. Bu sana son sözüm, sana son çağrım,  Yalnız benimsin, benim olacaksı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/son-askim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yâr', 'y-r-muhammed-gozubuyuk-78u5n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaylalara geldi bak yine bahar 

Otlağında koyun kuzular meler

Gözlerimde yaşlar yürek kan ağlar 

Yar deyip gözyaşım silermisin yâr.

Yaylalarda kar var sert boran olur 

Derede ak köpüklü sularda çağlar.

Bu acı hasretlik yüreğim dağlar 

Acıyıp lütfedip dönermisin yâr,

Yaylalarda lale sümbül gül açar, 

Göçmen kuşlar gayri sılaya göçer

Sensizlik yaktı âh eyledi naçâr

Yar deyip sinene sararmısın yâr

.

Yüreğimde ateş volkanlar kaynar

Acıyıp lütfedip sularmısın yâr

Gülünce yüzünde yar güller açar

Gül gibi gönlüme açarmısın yâr.', 'Yaylalara geldi bak yine bahar  Otlağında koyun kuzular meler Gözlerimde yaşlar yürek kan ağlar  Yar deyip gözyaşım silermisin yâr. Yaylalar...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Gözübüyük']::text[], 8.5, '{"poet":"Muhammed Gözübüyük","poet_slug":"muhammed-gozubuyuk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yar-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kerrat Cetveli', 'kerrat-cetveli-kucuk-i-skender-epb33', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Benim suçum yok! 

Bir çocuktan bir çocuğa geçen 

su çiçeği gibi bulaştın bana! 

Kalbimi kucağıma aldım, 

kalbim, kapanmayan bir ahşap çekmece sanki

yarısı içerde, yarısı dışarda 

boşlukta asılı kaldı dudaklarına! 

Bir marangoz ustasıydım adeta

bir ayağı mutlaka kısa masa yapan! 

Bir elimde çekiç, bir elimde çivi

kendimi bir resim gibi çakacağım insanı aradım yıllarca! 

Kim bilir, belki de

denize indirilen gemiye çarpacak şampanya şişesiydim hayatında! 

Gemi indirildi, şampanya şişesi çarptı

Sadece gözyaşlarının köpükleri bulaştı ağır ağır dalgalara! 

Hadi diyelim ki, ilkokul üç talebesinin zorlandığı matematik işlemiydim

yedi kere sekiz''in hiç bir boka yaramadığı bir hesap gibi hatırlandım aslında!', 'Benim suçum yok!  Bir çocuktan bir çocuğa geçen  su çiçeği gibi bulaştın bana!  Kalbimi kucağıma aldım,  kalbim, kapanmayan bir ahşap çekmec...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kerrat-cetveli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bülbülüm', 'bulbulum-salih-ozalasan-l21m0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Unutmak çok kolay, unutulmaksa acı

Hele etmişseniz onu başınızın tacı

Kanayan yaranıza bulunmaz merhem

Yaratılmadı daha bu yaranın bir ilacı

Yüreğinizde sevda çağlayıp sel olsa bile

Akan gözyaşınız dönsede umman bir göle

Sultanlar şevk ile olsada size birer köle

Unutulmuşsanız; Söyleyeceğiniz çile bülbülüm çile

Etmez fayda, yanmışsınız aşk''ın narına

Desde desde güller konsada bağrına

Tüm güzeller yansa tutuşsada aşkınızla

Ununutulmuşsanız; Bekleyeceksiniz gele bülbülüm gele

Aşkınızla olsada herkes bir pervane

Sevgiler anlatılsa dizelerde şairane

Serenâtlar edilse karşınızda nacizane

Unutulmuşsanız; Söyleyeceğiniz kime bülbülüm kime

Unutulmuşsunuzdur; Ama siz unutamassınız

Gözleriniz görmez baktığın; Görsede bakamassınız

Eliniz erecek gibidir; Ama asla tutamassınız

Unutulmuşsanız; Diyemessiniz öle bülbülüm öle

Y.Tar 29-12-2002 Saat 12,10', 'Unutmak çok kolay, unutulmaksa acı Hele etmişseniz onu başınızın tacı Kanayan yaranıza bulunmaz merhem Yaratılmadı daha bu yaranın bir ilacı...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bulbulum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-mehmet-ali-kalkan-ovf0p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Taşları sırdaş tutan deli çay oluyordun, 

Yalnızlık soluyordu içindeki ay balam, 

Sonra sonsuzluklara dalıp kayboluyordun, 

Şu gönlümün yanında deniz ne ki ay balam.

Bir damla ümid ile Mecnun yürürken aşka, 

Gölgeyi mekan tutup beklemeseydin keşke, 

Saklanacak nere var yerin altından başka, 

Hep seninle gidecek alnındaki ay balam.

Ben bu kara dedikçe hayır dedin akladın, 

Ne sevgimde eridin ne sırrımı sakladın, 

İki yok arasını var diye kucakladın, 

Tuttuğun senin olsun peki peki ay balam.

Ancak şunu unutma veren alandan üstün, 

Zirvede üşümeyen yerde kalandan üstün, 

Şükrederek yaşayan zevke dalandan üstün, 

Gün gelip yürüyecek kundaktaki ay balam.

 Orta Asya nakışlı soylu, mağrur tay benim, 

Menzilde hedef döven, toz koparan yay benim, 

Zeybekçe diz vurulan çekilen halay benim, 

Ne lir çalıp oynadım, ne sirtaki ay balam.

Zannetme güneş denen, gecelerden öç almış, 

Kozayı mekan tutan ipek sevmeye dalmış

Bak yüz sene öncesi yaşayandan kim kalmış, 

Can taşıyan gidici aşktır baki ay balam.', 'Taşları sırdaş tutan deli çay oluyordun,  Yalnızlık soluyordu içindeki ay balam,  Sonra sonsuzluklara dalıp kayboluyordun,  Şu gönlümün yanı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kalkan']::text[], 8.5, '{"poet":"Mehmet Ali Kalkan","poet_slug":"mehmet-ali-kalkan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sitem-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Çarşamba', 'kara-carsamba-mehmet-ali-kalkan-bix66', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uykuyu çok severdim bir türlü uyanmazdım		

Bekleyenim var diye düşman vurur sanmazdım		

Rüyamda görsem bile katiyyen inanmazdım			

Üç kılıç birden indi başımı düşürdüler			

Sevdamı, ümidimi, yaşımı düşürdüler.				

Bir acayip girdiler milenyum denen çağa		

Zevkle incir diktiler tütüp duran ocağa		

Dünkü siyahla beyaz, şimdi kucak kucağa			

				

Halayı unuttular, oynadıkları samba			

Temizlenmez leke bu, leke kara Çarşamba		

Azaltmaya uğraşmaz derde dert eklersiniz		

Baş olmaya çalışmaz, ayak eteklersiniz		

Haç’ını bileyenden medet mi beklersiniz? 

Kimlere inandınız, acep kime kandınız? 

Dünkü artıklarıma muhtaç mıyım sandınız? 			 

								 

Bu zelil duygu neden, bu nasıl bir düşüştü? 			

Leş bekleyen kargalar birer birer üşüştü							

Sayenizde açılan yaralara kurt düştü 

Bu yara iyi olmaz, kabuk tutmaz bu yara 			 	

Sizden medet uman yok, sesimi duy Ankara! 			

Dost bilinen ellerden heybemize gam doldu

Hayatın baharında nice umutlar soldu

İnsan hakkı bilmeyen it, hakkı korur oldu

Bastığın şehit kanı, pörsümüş halı değil

Kırılan Türk gururu, kuru çam dalı değil

Tarihini bilenler hatalı yolu tutmaz

Yalan söyleyerek milletini avutmaz

Lades oynayan bile “aklımda” der unutmaz

Ki bu vatan sevdası, oyun değil ki beyim

Yaşayan Türk Milleti, koyun değil ki beyim.

Vaktini geçirince elbette çürür maya

Geçmişten alıştınız, bir atıp üç tutmaya

Soysuz yemin ederken soyumu kurutmaya

Yaptığınız işlerden huzur mu bulursunuz

Düşman ayakta iken siz nasıl uyursunuz? 

Ne ağlayan unutur, ne ölen geri gelir

Anma günü gelende dizimin feri gelir

Zulüm payidar olmaz, elbette yeri gelir

Bu dert temizlenmezse benim yüz karam olsun

Düşmanımın güldüğü gün bana haram olsun.

Zamanlar boşta gezer, ya geç derler ya erken

Kanıma dokunuyor şerefsizler gülerken

Bak şu şehit çocuğu, öpmeye el ararken

Diyecek neyiniz var şu yetime öksüze; 

Susmaksa cevabınız yazıklar olsun size.

Ülkü denen gelini bir kutlu yar bilirdim

Dağ dağ olmuş dertleri eriyen kar bilirdim

Ötekiler zaten yok, ben sizi var bilirdiml

 Milyon kere haklıyken nerdeyse haksız kaldım

Baba olan devletti, yitirdim öksüz kaldım

Dövünmek vakti değil, boşa şimdi eyvahım

Zalimlerin şerrinden gökleri vurur ahım

Dileğimi kavi tut, baş indirtme Allah’ım! 

Göğsümdeki imanla titresin ruy-i zemin; 

Bayrak yere düşmesin, ezan susmasın..Amin!', 'Uykuyu çok severdim bir türlü uyanmazdım		 Bekleyenim var diye düşman vurur sanmazdım		 Rüyamda görsem bile katiyyen inanmazdım			 Üç kılıç ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Kalkan']::text[], 8.5, '{"poet":"Mehmet Ali Kalkan","poet_slug":"mehmet-ali-kalkan","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/kara-carsamba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Karanlık Yansıması', 'askin-karanlik-yansimasi-umut-ulbegi-6rpyf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sonsuzdan beri

ufkumdan uzakları seçiyorum

neden bu tutukluluk

perspektifi var mıdır zihnime boylu boyunca uzanan kelepçelerin

Cepheden yeni döndüm

üstüm başım aşk

boşlukları saymazsak

Boşluklar

boşluklarım kanıyor

ısınıyor alizelerim

Cepheden yeni döndüm

işim yok cirit atıyorum dörtyol ağızlarında

Çiçek tutuyorum

balık dikiyorum deniz bahçelerine

Ah o dikiş tutmayan dalgalar yok mu

yarısı orkide yarısı papatya

zengin fakir bahçelerim

Dilek tutuyorum

yıldızlar ölmeden

nefesime düğümlenmiş kelimeleri çözemeden

buzlar çözülüyor

Her ilkbahar yapılıp her sonbahar yakılan kağıttan kalpler arasından

sana tutuluyorum

Sen bu gece hiç anlatılamadan gelen

morötesi karanlığım

Yarın gece de

binbir gece de 

o yıldızda 

varlığım.

28.12.2002', 'Sonsuzdan beri ufkumdan uzakları seçiyorum neden bu tutukluluk perspektifi var mıdır zihnime boylu boyunca uzanan kelepçelerin Cepheden yeni...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/askin-karanlik-yansimasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bu Şehri Bir Gün Sana Anlatacaktım', 'ben-bu-sehri-bir-gun-sana-anlatacaktim-kucuk-i-skender-0t80e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kel kadınlar tanıdım insafsızca

Her sokak başında bir ekip otosu vardı

Kaç paraya öpüştük durduk asitli homojen

Ne çok insandılar öyle yıkılası acılı

öyle kırkayak kimlikli. Sahi, 

bana ait bir sürü sevgiliyle dolaşırlardı! 

Dolaşırdı ayaklarım - babam kimdi, belki

birikimler yalnızca, yalnızca itilişler! 

Annem: O, yalnızlığım olacak! 

Sarhoş çocuklar gibiydim, dirilen bir ceset

gibiydim - yüzümde bir gri saten bıçak! Saat bozuk

gibiydim, imdat polis gibi! Saçmalayacak gibiydim

beni bir  bıraksanız, ah bir bıraksanız, 

ödünç bir tutku, özürlü bir rüzgar misali

dağılıp gidecek gibiydim! 

Oğlum eşkalim İstanbul, yine katildi. Kızım

son vitrinin son beyaz gelinliğinde! 

Yaşları, toplasan en fazla on üç, on dört

en azından milattan önce yirmi! Bir zaman

efkarla makyajını tazeledi içimdeki ölü helvası

Ölü helvası ve kör çiçekler satan çok kalibre çingene! 

Ve horgörülen aşklar bazen sahte.. abazan..

Biraz daha öpüşebilsek, ah bir de

öpüşmeleri, sevişmeleri, logaritmayı bilsek

alkol komalarımıza hafif inceden 

profesör bir zencefil kokusu inecekti! 

Kel kedımlar tanıdım insafsızca

Her sokak başında bir ekip otosu vardı

Hatırlar mısın, yazmıştım sana, her otel odasında

filtresi bekaret kanıyla lekeli

yanan bir orospu sigarası. Ah, göğsüm, 

sen, kurşuna dönmüş zalim gözlerle

delik deşik edilmiş bir  erkek fanilası! 

Delikanlılığım         aşka aç

                               aşka muhtaç

                               aşka mecburdu! 

Ve yüreğim! 

Yaşlandıkça memeleri sarkar oldu! 

Bana bir haller oldu / bana filmler bir tuhaf olur! 

Sarkaçlar bana pek bir dar oldu / kuyular pek bir sığ olur

Bakın! Kızkardeşim gitti gecenin dul eşi oldu

Abim miyop dudaklarıyla kendi yılanında küçülür küçülür mahfolur! 

Ah! Çıtır hüznüm, asil acılarım, dikkat edin! 

İstanbul bu! Genç bedenlere aç

                     dinç cesetlere muhtaç

                     hürriyete mecburdur!', 'Kel kadınlar tanıdım insafsızca Her sokak başında bir ekip otosu vardı Kaç paraya öpüştük durduk asitli homojen Ne çok insandılar öyle yıkıl...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/ben-bu-sehri-bir-gun-sana-anlatacaktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözler', 'gozler-abdullah-karaduman-3pa19', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bakma yaş akmadığına gözlerimden

İçimdeki seni kurutmamak için

Yine içime akıttığımdandır kuru gözlerim', 'Bakma yaş akmadığına gözlerimden İçimdeki seni kurutmamak için Yine içime akıttığımdandır kuru gözlerim...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Karaduman']::text[], 8.5, '{"poet":"Abdullah Karaduman","poet_slug":"abdullah-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/gozler-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Okul Arkadaşı', 'okul-arkadasi-kucuk-i-skender-qksqw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aynı ranzada uyumuştuk seninle

yatılı okula benzeyen bir sevdada, 

üstte kim yatabilirdi ki: Elbette yeryüzü! 

altta kim yatabilirdi ki: Elbette gözlerimizdeki intihar süsü! 

birbirimizi düşündüğümüz gizli saklı rüyalarla

kim mutlu olabilirdi ki: Elbette günah dürtüsü! 

Nasıl tabir edilir ki artık veda kabusları..

şimdi çift kişilik yataklardayız başka 

başka insanlarla! Başka başka hayatlarda! 

ama hiçbir iyi geceler! ağlatmıyor beni 

ağlatmıyor senin karanlığın içinden duyulan

küçük hıçkırıkların kadar hala! 

23 nisan 2000', 'Aynı ranzada uyumuştuk seninle yatılı okula benzeyen bir sevdada,  üstte kim yatabilirdi ki: Elbette yeryüzü!  altta kim yatabilirdi ki: Elb...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/okul-arkadasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vay le le...', 'vay-le-le-sah-ali-yasar-tvmvr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Asil kanın sararır mı hiç

Nurlu yüzün kararır mı hiç

Kör kurşuna yandın gittin sen

Buna yürek dayanır mı hiç...

Vay le le le, vay le le le, vay le le le, hey

Yandı yürek, viran oldu, talan oldu, hey...

Toprağın derine dalsın da

Dört bir yana kökler salsın da

Yavrum sana sözüm olsun da

Kavgan yerde kalır mı ki hiç...

Gardaş sana sözüm olsun da

Kanın yerde kalır mı ki hiç...

Vay le le le, vay le le le, vay le le le, hey

Yandı yürek, viran oldu, talan oldu, hey...', 'Asil kanın sararır mı hiç Nurlu yüzün kararır mı hiç Kör kurşuna yandın gittin sen Buna yürek dayanır mı hiç... Vay le le le, vay le le le, ...', ARRAY['Türk Edebiyatı','Şiir','Şah Ali Yaşar']::text[], 8.5, '{"poet":"Şah Ali Yaşar","poet_slug":"sah-ali-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/vay-le-le-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık -I-', 'yalnizlik-i-faize-ozdemirciler-biswz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yağmurun pis asfalta düşerken söylediği şarkı

kirli ellerdeki sesidir nergisin

inançların cenaze töreninden dönüyorum

hiçbirşey ağlamaktan vazgeçiremez beni

canım ya çıkmak, ya sulamak ister

karanfil fidancığını 

Gün geldi işte; bir gemi dayandı iskeleme

soydaşlarımdan biri indi sularıma

aynı yolun yolcusu olduğumuzu geç anladım

neden bu denli uçarı ve hırçın olduğunu

saçlarını neden at kuyruğu yaptığını

ve neden sürekli göçler biriktirdiğini yüreğinde

yollar kapalı, köyler boş, çocuklar kan içinde

yalanını yakaladım ey beyaz güvercin

                kimbilir kaç kere...', 'Yağmurun pis asfalta düşerken söylediği şarkı kirli ellerdeki sesidir nergisin inançların cenaze töreninden dönüyorum hiçbirşey ağlamaktan v...', ARRAY['Türk Edebiyatı','Şiir','Faize Özdemirciler']::text[], 8.5, '{"poet":"Faize Özdemirciler","poet_slug":"faize-ozdemirciler","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yalnizlik-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık -II-', 'yalnizlik-ii-faize-ozdemirciler-ib8wn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tek isteğim arzularımı geçmişe kaydetmek

sinsice imza çalmak zaman''dan 

uyumak değil şarkı söylemek doğduğum evde

dudaklarından göçen kuşlar, ah o kuşlar! 

başkalarına söylettiğin hüzzamlarım

peşini hiç bırakmayacaklar! hadi ağla! 

ağlayan gözlerde 

daha belirgindir aşkın ayak izleri

ve barış daha iyi yakışır ıslak bir yüze

kuzey''e aldırma, güney''e boşver

doğu''da, batı''da dur, düşün ve ağla! 

kendi yurdunda eskittiğin yüreğine

eskitemediğin ayakkabılarına', 'Tek isteğim arzularımı geçmişe kaydetmek sinsice imza çalmak zaman''dan  uyumak değil şarkı söylemek doğduğum evde dudaklarından göçen kuşlar...', ARRAY['Türk Edebiyatı','Şiir','Faize Özdemirciler']::text[], 8.5, '{"poet":"Faize Özdemirciler","poet_slug":"faize-ozdemirciler","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yalnizlik-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zafiyet İksiri', 'zafiyet-i-ksiri-kucuk-i-skender-19wfg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Heykelde rol alan bir ağaç 

gibi havada asılı durur sarkaç! 

kalp ile mermerin mesafesi daralmış

kusur, hükme mühim bir mühür

ölüm, aşka dair ihtiyaç! 

Hayatta bir yer edinmek lazım

eğer, ıstıraba doğru esiyorsa sahte

hüzünlerden kalkan zahiri kainat! 

Ah bu simsiyah sirayetin saldırısına

dur demek lazım tabip! Dur demek lazım 

etteki meleğe, kayıptaki tedavüle! 

Çünkü, 

laf, keder israfı

veda, insana dair ihtiyaç! 

Kanda biriktim! 

Kanda soğudum! 

Artık cehenneme el lezım

artık cehenneme el lazım tabip! 

Çünkü

ateş, söndüğü geceye mahsus

ruh, maddede bir yantesir

ihanet, korkunç sevdalara mahlas!', 'Heykelde rol alan bir ağaç  gibi havada asılı durur sarkaç!  kalp ile mermerin mesafesi daralmış kusur, hükme mühim bir mühür ölüm, aşka dai...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/zafiyet-iksiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serzeniş', 'serzenis-faize-ozdemirciler-k44fv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İkiye bölünmüş bir adacık

tarihi yabancılar tarafından yazılan

savaşları çeviri olan insanlar

şiirin kolay yol olduğunu söyleyenler

o yola hiç sapamayanlar

hep soru soranlar

hiçbir soruyu yanıtlayamayanlar

sizler; 

dönecek memleketim olmadığı halde

''neden memleketine dönmüyorsun''ları 

 yaratanlar

sizler yalnızlığımdınız

aynı tabaktan kiraz yediklerim 

aynı içkiyi içtiklerim

sevişmediklerim, sevdiklerim

sizler başkalarıydınız, ben başkası

görmek istediğimi görürdüm aynalarınızda

loş ışıklarda katlanabilirdik birbirimize

aydınlığa da dayanamazdık

karanlığa da!', 'İkiye bölünmüş bir adacık tarihi yabancılar tarafından yazılan savaşları çeviri olan insanlar şiirin kolay yol olduğunu söyleyenler o yola h...', ARRAY['Türk Edebiyatı','Şiir','Faize Özdemirciler']::text[], 8.5, '{"poet":"Faize Özdemirciler","poet_slug":"faize-ozdemirciler","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/serzenis-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz Buluşçusu-I-', 'yaz-buluscusu-i-faize-ozdemirciler-zpyq0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hiçbir düşe sığdıramazdım ben onu

yaz gelirdi yüzüne, uzardı uyanıklığı

yarısı gözkapaklarımla kirpiklerimin 

oynaştığı noktada bir arpacık kadar ağrılı

öylece kalırdı...haftalarca...aylarca

ağlarken gözleri kahkaha atardı

ve dondurması çalınmış bir çocuğu 

andırırdı gülüşü

Kısa boylu sevgiler ekerlerdi bahçelerime

uzadı mı, limon sıkar gibi ekşitirlerdi yüzlerini

tarlalarımı dümdüz yaparlardı, gerçeklerimi düş

limon ağacına çamaşır asarken kanardı elleri

aşka dokunduklarını anlamazlardı', 'Hiçbir düşe sığdıramazdım ben onu yaz gelirdi yüzüne, uzardı uyanıklığı yarısı gözkapaklarımla kirpiklerimin  oynaştığı noktada bir arpacık ...', ARRAY['Türk Edebiyatı','Şiir','Faize Özdemirciler']::text[], 8.5, '{"poet":"Faize Özdemirciler","poet_slug":"faize-ozdemirciler","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yaz-buluscusu-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz Buluşçusu-II-', 'yaz-buluscusu-ii-faize-ozdemirciler-8vti5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiçbir mevsimde dokunamazdım ona, yanardı! 

elini uzatışı zorunluluktu

sevmiş bulunduk ya birbirimizi, öyleydi! 

ne zaman doğmuştu

hangi tarihli sevişmenin eseriydi

beni bu ilgilendirirdi 

ve kanıtı kırışık yüz

soru sorulamayacak kadar 

ötesindeydi denizlerin

bilinmeyenleriydi sevgili kılan onu

bir de dudağından hiç eksiltmediği

çiğdem çiçeğinin tarihçesi', 'Hiçbir mevsimde dokunamazdım ona, yanardı!  elini uzatışı zorunluluktu sevmiş bulunduk ya birbirimizi, öyleydi!  ne zaman doğmuştu hangi tar...', ARRAY['Türk Edebiyatı','Şiir','Faize Özdemirciler']::text[], 8.5, '{"poet":"Faize Özdemirciler","poet_slug":"faize-ozdemirciler","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yaz-buluscusu-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz Buluşçusu-III-', 'yaz-buluscusu-iii-faize-ozdemirciler-qm3td', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hiçbir eylül''e sığdıramazdım onu

hep yaz gelirdi yüzüne, uzardı uyanıklığı

sabah güneşiyle örterim şimdi

yaşamaya ait tembelliğimi

kaçışımın şarkısını söylerler ağlarım

sana gelişimin şarkısını söylerler ağlarım

şarkısı yok memleketimin, sessizliği bundan

                       ağlarım! 

Yüzünde keşfettiğim uzun yaz''ı 

unuttuğun günden beri

yalnızlık senin unutkanlığın, benim şiirim

çocuk elinden çıkma bir yaz günü bu

ayaklarımın altında bir mavi ağaç, bir yeşil su

yaz geldi gülüm gözlerinin rengine 

       hadi! kucakla yazbuluşçusunu!', 'Hiçbir eylül''e sığdıramazdım onu hep yaz gelirdi yüzüne, uzardı uyanıklığı sabah güneşiyle örterim şimdi yaşamaya ait tembelliğimi kaçışımın...', ARRAY['Türk Edebiyatı','Şiir','Faize Özdemirciler']::text[], 8.5, '{"poet":"Faize Özdemirciler","poet_slug":"faize-ozdemirciler","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yaz-buluscusu-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Yer', 'o-yer-faize-ozdemirciler-h1uev', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yabancı haritalara yaranmak için yarım kalan

silah sesleri arasında doğmuş bebeklerine

savaş ismini verenlerin çocuğuydum

Öyle buyurmuştu reis

uzun burunlu kuş anasını uzaklarda arayacak

ağlayacak...ağlayacak...hiç gülmeyecekti

mavilerim acı acı kıvranarak can çekişiyor 

adalı kadınlar güneşle tanıştıramıyor göğüs uçlarını

kim kapattı aphrodite''nin bedenini 

öpülesi ada/m/ın yüzünde bu sakal neyin nesi? 







Hayalkırıklığımı sığdıracak bir bavul verin bana

aşkın tükürülmediği bir yer vardı, yolculuğum oraya

o yer ki, bir bisiklet uğruna terkedilendi

öteki çocuklar''ın gözyaşları üzerinde 

kurduğumuz düşler gecikmiş yağmurlarla 

ıslatıyor yüreklerimizi

ve pişmanlık renginde bir utanç 

etkisi altına alıyor yüzlerimizi 

yeni yeni anlıyoruz; 

                 kırmızı bisiklet

                yolculuklarımızı 

              kısa kesmek içindi!', 'Yabancı haritalara yaranmak için yarım kalan silah sesleri arasında doğmuş bebeklerine savaş ismini verenlerin çocuğuydum Öyle buyurmuştu re...', ARRAY['Türk Edebiyatı','Şiir','Faize Özdemirciler']::text[], 8.5, '{"poet":"Faize Özdemirciler","poet_slug":"faize-ozdemirciler","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/o-yer-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durup dururken', 'durup-dururken-aziz-pinar-3njii', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ayrılmamaya yemine gücün yetmiyoır

Sevip istiyorken...

Ayrılmanın yollarını arıyor

Boşluklara yeminler ediyorsun

Durup dururken...', 'Ayrılmamaya yemine gücün yetmiyoır Sevip istiyorken... Ayrılmanın yollarını arıyor Boşluklara yeminler ediyorsun Durup dururken......', ARRAY['Türk Edebiyatı','Şiir','Aziz Pınar']::text[], 8.5, '{"poet":"Aziz Pınar","poet_slug":"aziz-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/durup-dururken-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtiraf', 'i-tiraf-bora-zihni-ib1mm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Deli bir Bora gibi hayatına girip, 

Örtülmüş bir yalnızlığın içinde

Tozlanan seni bulup, 

Gün ışığına çıkarmak.

Ve

Belki bir ömür boyu ölüme sunmak.

Hayır, 

Yanan bir ömürde seni ateşe  sunmamak.

Ağlama yağmur  gözlüm, 

Sen üzülme, sen üzülme.

                            TAYFA', 'Deli bir Bora gibi hayatına girip,  Örtülmüş bir yalnızlığın içinde Tozlanan seni bulup,  Gün ışığına çıkarmak. Ve Belki bir ömür boyu ölüme...', ARRAY['Türk Edebiyatı','Şiir','Bora Zihni']::text[], 8.5, '{"poet":"Bora Zihni","poet_slug":"bora-zihni","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/itiraf-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sızı', 'sizi-aziz-pinar-pralh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçimde sızlayıp duran yarasın

Gittin gönül seni nerde arasın

Çöl ortasındayım aşkına susuz

Yağmur ol ömrüme yağ ne olursun...', 'İçimde sızlayıp duran yarasın Gittin gönül seni nerde arasın Çöl ortasındayım aşkına susuz Yağmur ol ömrüme yağ ne olursun......', ARRAY['Türk Edebiyatı','Şiir','Aziz Pınar']::text[], 8.5, '{"poet":"Aziz Pınar","poet_slug":"aziz-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sizi-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle', 'seninle-aziz-pinar-pa604', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seninle tertemiz bir hava dolar içime

Seninle sımsıcak iklimlerde olurum

İçim içime sığmaz, uçarım şahlanırım

Seninle karanlıkta aydınlığı bulurum...

Açılması imkansız kapıları açarım

Seninle yakınlaşır yaşantıma mutluluk

Bir tatlı rüya olur seninle uykularım

Seninle sabahları aydınlığı bulurum..', 'Seninle tertemiz bir hava dolar içime Seninle sımsıcak iklimlerde olurum İçim içime sığmaz, uçarım şahlanırım Seninle karanlıkta aydınlığı b...', ARRAY['Türk Edebiyatı','Şiir','Aziz Pınar']::text[], 8.5, '{"poet":"Aziz Pınar","poet_slug":"aziz-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/seninle-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliğin Ertesinde', 'sensizligin-ertesinde-laci-gece-24usj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sensizlikle flört etmeyi, sen yokken sana aşık olmayı ve bunu yüreğimin en sevdalı köşesinde saklamayı ancak ve ancak sensizlik bilir! ! sensiz yaşamayı sensizlik bilebilir ancak..ne sen nede ben...

 içinde bir sen var! sana bu zamana kadar dilediğin aşkı yaşatmamış, aşk nedir öğrenmene fırsat vememiş, meyvesini yedirmemiş bir sen var içinde...şimdi sen o içindeki senin ellerinden tut.bu güne kadar ne kadar üzdü o sen seni! kaç gecen baş ağrısıyla gecti o senle? hayatına bi renk katmadı o sen! siyah ve beyazın o dayanılmaz çekiciliğinin buzlarında kayboldu o sen..şimsi sen içindeki senin ellerinden tut! düşlerini içinde hep avuttun.kimi yarım kaldı, yaşanmadan bitti, kimiyse sadece bir düş olarak kaldı..şimdi sen içindeki senin ellerinden tut ve BENİM İÇİN ona bir gül ver..çünki ben seni o senle sevdim! ! ! 

  sen o senin ellerinden tutunca içimden öyle nehirler akıyorki kendime.çünki o içindeki sen benim! ! en başında da bendim..şimdi de benim.sesini ilk duyduğum, sana ilk dokunduğum, hüznünle ilk tanıştığım gün anladım içindeki senin ben olduğunu! ! .içimde bu güne kadar başıboş nehirlerimin pusulası oldun sen.şimdi sen içindeki senin ellerinden tut ve ona bir gül ver! 

   yollara cıkıp umarsızca dolaşırdım, insanları aradım gözlerdeki anlamsız bakışlarda.olmam gereken yerlere gitmezdim inadına! diğer dünyalarda yaşayanlar ilgimi çekerdi hep.saçları belinde bir erkeğe sokaktaki insanlar küfür ederken ben onu takip ederdim, nerde yaşar, neyle ilgilenir? yönü ne diye.oysa olmam gereken yer türk toplumunun kabul edeceği yerlerdi.gözlerdeki anlamsız bakışların peşinde, olmam gerekenleri, yapmam gerekenleri unuttum.sıradışı kafelerde onlar gibi olmadan bulundum.pantolonum yırtık değildi, saçım darmadağın değildi..ruhum bunu yaşıyor ama bulunduğum mevki buna tersti! benim için pusulasız bir geminin kaptanı olmaktı, hep fırtınayla didişmekti bu masal.ne başlangıcı, ne gidişatı, nede sonu belli olmayan bi yolculuktu, yolculuğa neden cımıştım, ne zaman bu gemini kaptanı olmuştum kimse bilmiyor! ben bile...

  sonraları salaş meyhanelere dadandım.yaşama umudunu at yarışlarına, sayısal lotolara bağlamış insanların arasında cok ayrıydım kendimce.çünki onlardan dadeğildim ben.ve bulunduğum yer onlardan üstündü! onlara akıl verebiliyordum.sarhoşken kurduğum bi kaç dostlukta onlara bazı öneriler, tavsiyeler veriyor, ertesi gün tavsiyemin ne kadar yerinde olduğunu öğrenince ortamdaki yerim daha da sağlamlaşıyor, mekan sahibine daha bi güven veriyordum.geberene kadar içiyordum artık..ceketimi salaş meyhanelerde bırakıp kendimi yollara vurduğum zamanlar gençliğimi de o ceket gibi o meyhanelerde bıraktığımın farkında bile değildim oysaki.ertesi gün işyerinde dünün gecesini hatırlamaz, uyuşuk, baygın baygın bakan bi devlet memuru olmanın haklı gururyla hayat yeniden başlıyordu amaçsızca, acımasızca...halen bulunduğum yere yakışır yaşamıyordum ama pusulasız bir gemiyle yolculuk yapmanın ve o gemnin kaptanı olduğuma inanmanın verdiği rahatlıkla ayaklar artık gideceği yeri kesinlikle biliyor.gene uçsuz bucaksız deryalarda, masmavi gökyüzüne açılacaktım aklında sadece oynadığı at olan bi kaç alkolik, esrarkeş muhabbetinde! 

  kendim hep bi şeyler arıyor! yeni bi gün yeni bi umut...aşk meşk yoktu gözümde.çünki rotam ne zaman ona sapsa zaten pusulası olmayan gemim batıyordu! acıkcası yokluğunu da aramıyordum.taaaaki bu geminin bu salaş meyhane köhneliğinde çürüdüğüne inanana dek! ! ! bi umut olmalıydı bi yerlerde! benimde topragın bağrını delip bi fidan ekebilecek bir avuç umudum olmalıydı! onu sulayıp yeşertmeliydim...bu fikir iyiden iyiye yatmaya başlıyordu kafama! ! kendimin elleri meğerse ne kadar sevgi dolu ve sıcakmış.ne kadar da sevmeye sevilmeye açmış.bi anne kucağına, baba ocağına, kardeş selamına açmış meğer kendi ellerim! ! ! kendimin ellerinden tuttuğumda cok geç kalmadım dedim içimdeki bana! yaşlı ve şefkatli bi azize korumalıydı beni hayattan, dertten, tasadan hatta hatta aşktan bile.sabaha kadar onun koynunda uyumalı, hiç kıpırtı yapmadan, başımda dönen melekleri rahatsız etmeden ruhumu ona teslim etmeliydim.içime yüklenen derdin adını bulmalıydım.aşksız yaşamak mı? her sevilme umudumun aşağılanark yerin yedi kat dibine gömülmesimi? uzun zamandır ana sıcağına hasret olmakmı? doğuştan beri gelen yoksulluğun beni ezmesimi? işte azizem ve melekler bana bi cevap vereceklerdi.belki hepsi diyeceklerdi, belkide yenilerini katarak bana sunacaklardı, fırından yeni cıkmış bi yemek buharında...

  yine gidersen sığınağım kalmayacak..ezilecek hayat yolum..farmuarın dişlileri yerine oturmayacak..sevgilim....sen tutunca ellerimden ömrünün içinden akmak geliyor taa derinlerine! ! ! 

  içimde dinmez yaralar azdı kanıyor, kanamıyor aslında sel oldu yakıyor, dağıtıyor gectiği yeri, seni! ! ! ! ama bir gün doğacakki...o günün yumuşacık tenine dokununca bütün yaralar derman bulacak kabuk bağlayacak.cook uzun boylu bi umutsun sen bana...bu umudun tadında her şeyi unuttur bana..kışın soğuk sularını, yazın derin uykularını, binlerce kere düşüp tekrar cıktığım uçurumları unuttur bana! ! bir kaleyi esir almak için surlarına tırmanırken üzerimize kızgın yağlar dökülse bile uslanmayalım...sevelim..sevelim..sevelim...cok sevelim birbirimizi! ! sen cok uzun boylu bi umutsun bana...senin için benmiş meğersem, sen benmişsin..tut içindeki senini ellerinden! ! ! 

    doğayı sarmış, adam boyunu aşmış kar yığınları gibi seviyorum seni..bu kar yağdığında eriyor sellerim sana akıyor..ömrünün taaa içine akıyor tüm geçmişim, sevilmemişliğim...senin yangınınla üşüyor şimdi titrek ellerim..

  külle karılmış günlerin tortususun yanan ömrümde.o kadar ağırbaşlı bi sevda olmuş, üflesen yenidenalevlenecek bi tortu! ! kötü dünlerimizi gerillalar vurdu, yatıyor yol ortasında! birazdan çöpçüler gelip leşleri toplayacak yüreğimden.mutlu yarınlarımızı menekşeler, lalelerle büyüteceğiz.uzaklardan odam kireç tutmuyoru söyleyecek anneler ninnilerinde bebeklerine! ve biz koyun koyuna mühür gözlüm seni elden sakınırım kıskanırım diyeceğiz sıcak yatağımızda geceyarısı sessizliğinde..

  kendini bıçak gibi ışıyan yeni güne bağışla sevdalım.yeni gün benim! ! yeni gün biz olma umudu.uzzuuun boylu umutsun bana! ! arkana bakma sakın! ! unut gerillaların vurduğu leşleri, lalelere basma o leşlere bakarken! ! ! o kötü anılara yakışan en güzel elbiseyi biz cok giydirdik onlara..sel gibi akan gözyaşımızla! ! ve onlara kefen oldu bu elbise! 

seni hiç bi zaman sadece gözlerimle görmedim! ! hep içindeki senle gördüm seni..içindeki seni daha iyi tanıdıkçada geceleri sen uyurken daha cok bağlandı yüreğim sana.her gece saçlarını okşayarak uyuttum seni.yüreğim görüyordu seni! ! ! seniseverken içime yaşama umudu doldu, bi amaç oldu yaşamak.dünyayı sevdim seni severken.içten bir gülüşün ne demek olduğun anladım, tadının ne kadar dayanılmaz olduğunu tattım senle! ellerimi tuttuğunda patlamaya hazır bi volkan oldu hep yüreğim.içim yüreğime dar geldi.her an senin için bi şey yapma çabası doldu yüreğime.cümlelere sözlere sığdıramadım seni ve sevgimi.yetmedi bildiğim hiç bi şey bunu tarif etmeye.damarlarımda akan kana karıştın bir tatlı gülüşünle, içten bir sözünle.yüreğimin en derin yerlerini sana açtım, , oraları doldurdun ve sığmıyorsun içime..seni her yere koydum, gözlerimin içine aldım seni, sesime nefesime...

  mevlana ''ne arıyorsan o sundur''demiş.demekki ikimizde sevgiyi aşkı arıyormuşuz..bunun uçar kaçar yanı yok.her an içimizi yakan bu sevgi yüreklere nasıl dolduysa! demekki biz sevmeye ve sevilmeye açmışız onu arıyormuşuz.pusulamız buyüzden şaşırmış hep...yanlış yerlerde yanlış zamanlarda yaşamışız her şeyi birbirimizi bulana kadar! 

  gel aşkım.bir nergis çiçeği getirdim sana.mevsim nerde baharsa oraya cevirelim rotamızı..SANA BAHAR GETİRDİM YÜREĞİMİN AVUÇLARINDA...bahar kokuluı bir çiçek olacağız seninle, doğa bile kıskanacak bizi! ! ! 

  haritanın yırtılan yerinden kopalım hayattan senle.keşfedilmemiş diyarlara gidelim.havagazını ve pencereleri açıp kaybolmuşluğumuzun inandına sevşelim geceler boyu, hiç durmadan..nereye istersek oraya gidelim.mevsim bahar olsun, bizde bahar kokulu bi çiçek! 

 çoğu zaman beni ne kadar derin duygularla sevdiğini haykırdın bana.ama ben bunların bazısında ruhsuz biri gibi davrandım konuşmanın gidişatında.sebebi belliydi...bu güne kadar aşk serüvenleri ve hayat yüzünden hep kabuğuna gizlenen, korkak, sevgi yeteneksizi biri olarak yaşadım..yoksulluğum bunda en başlı neden di.sinemayı bile liseyi bitirdikten sonra tanıyan biri olarak hayata sosyal yönden ne kadar bağlanabilirdimki? ? senin normlarında hayata bağlanmadım hiç bi zaman.karnım toksa, yatacak yerim varsa mutlu bi insandım.şiir yazmak bi eksiklik olmadı yalnızlığımı tamamlayana kadar.sosyal bi insan olmadım diye bi boşluğa düşmedim hayat boyu.taaki istanbul macerasına kadar.demekki ankarada kendimce sosyalliğim kendime yetiyormuş, arkadaşlarım, ailem, hatta kendim kendime yetiyormuşum.şiir benim için sadece aşık olduğumda vardı..şiirler yazardım okul defterimin arkasına.ya öğretmen görüp yırtar atardı yada sadece ben okur bi gecenin karanlığına boğar giderdim..bunun dışında aramazdım hayatımda şiir yada resim müzik! ! kafama uygun bi kaç arkadaş benim için sosyal hayattı işte.yoksulların mahkum edildiği sosyal hayat bu olsa gerek! ! 

  ve istanbuldaki 5 senem! ! ! tek kelime...YALNIZIM! ! ! ! ! 

bunca acı tek bi söze nasıl sığıyordu? bu sözü dudaklarımdan alıp kalbimi onunla parcalamıştım..rengi cok zarifti bu sözün.yarım kalmış aşkların tarifsiz esmerliğiydi bu! ! içime dolan binşlerce yüzdü bu tek kelime..

  bu ilişkide ben o kadar suçluyumki bir bilsen: (((ne kadar acı cekiyorum bi bilsen? ben seni taaa senden önceki ıssız sessizlikte dinlemiştim.seni tanıyordum aslında seni yüreğim bilmeden önce.ve senin için ölecek tek insan yine bendim seni tanımadan önce! ! bilsen ne kadar çaresizim ben sana çare olamadığım için: (((((((sen soluk alıyorsun diye seviyorum hayatı şimdi..hayatına kendi eklediğin şeyleri keşfettikçe ıssızlığın sesi daha bi derinleşti, içimdeki sevgin daha bioturdu yüreğime! ! dokundukça çoğalttın, sevdikçe çoğaltıın içimdeki sevgini.konyadan her dönüşte otobüs beni senden uzaklaştırdıkça ben...senin ben için döktüğün gözyaşlarını topladım tekerleğin her dönüşünde..gece boyu gözyaşınla yıkadım hep yüreğimi o şehirden giderken seni orda bırakıp! ! ! oturduğumuz cay bahçelerinden, yürüdüğümüz sokaklardan, ıslandığımız yağmurlardan, seviştiğimiz her kuytu köşeden topladım seni otobüsün gittiği her kilometrede. 

   oğlumuza kızımıza yazacağın şiirlerle seviyorum seni..kitapçı vitrinlerinde kalan gözlerinle daldım uykularına..birde bana seviyorum derken içinde açan binlerce büyülü çiçeğe sarılıp uyuyabildim gecelerce, düşlerime dar gelen yatagımda...

 Asla çözemediğim kurallarıyla beni hep dışına sürükleyen hayata yeniden tutunmaya çalıştığım tek yerin sana duyduğum  bu derin aşk olduğunu biliyormusun? ... Kendimi değil, seni seçtiğimi biliyormusun? ...şimdi yağmurunda ıslanan çıplak bedenimi aldım ve kapında dileniyorum...yanıma usulca sokulup bana sarılmanı istiyorum bir daha ayrılmamacasına söz vererek...Ölüm o ısrarcı soğukluyla hemen arkamda duruyor. Korkuyorum seni saramamaktan ölüpte! ! neolur sıkı tut ellerimden.beni o soğuk rüzgarın kollarına bırakma sakın diye bütün suskunluğumla haykırırken gözyaşlarım kanımda seni topluyor yine! ! ! 

  seni seviyorum'' demek yetmiyor bana. sanki hiç sevmiyormuşum gibi geliyor. senin için yeterli olup olmadığını da bilmiyorum; ama beni tatmin etmediği kesin. Bu da beni çok yıpratıyor. seni sevmemeyi düşünmek, aklımdan bir saniye olsun geçmesi bile onulmaz bir yara açıyor yüreğimde. kendimi hasta, ya da oldukça sağlıksız ve güçsüz hissediyorum bu anlarda. Seni o kadar çok seviyorum ki, ''seni seviyorum'' sözcüğü bunu ifade etmekte yeterli gelmiyor.Seni sadece sevmemeliyim. bunun yetmediğini bir şeylerin eksik olduğunu hissediyorum içimde. Sadece seni sevdiğimi biliyorum. Bunda en küçük bir şüphe oluşmuyor içimde. Bir rahatsızlık duymuyorum. Rahatsız eden, sanırım sözcüklerin yetersizliği, sana bunu hissettirememem rahatsızlık veren! ! haklısın, bunu bugüne kadar başarabilmiş değilim. ama bu beni yılgınlığa itmiyor; tam tersine azmimi arttırıp bu zorlu işi başarabilmek için güç veriyor.seni sevmenin girdabına kendimi teslim edip, kalbine doğru giden bu yolda bir yolcu olmak beni mutlu kılıyor. ben seni seviyorum. Sadece ve yalnız  seni seviyorum.

   acısıyla, yarasıyla, kapanmayanıyla bi aşk yaşıyoruz.istediğimiz oluyor yani...idam mahkumu bi suçlunun bin yıllık kelepçeleri gibi bağlandı yüreğimize bu sevgi.sanki perdeyi araladığımda karşmda senle dolu bi dünya olacak! ! ama bizi ne kısıtlıyor, neden böyle sorunlar yaşıyoruz, bunlar neden yaşanıyor? bunları aşalım artık..ben sadece seni istiyorum.içindeki beni seviyorum.içimde yaşayan yaralı seni seviyorum.içimizde birbirimizden önce karaya oturan aşk gemisini yeniden açık denizlere salalım ve umarsızca aşka doğru kürek çekelim istiyorum.mevsimin bahar olduğu yere gidelim, haritanın yırtılan köşesinden sıyrılalım artık! ! ! 

 seni cok seviyorum sen sevenim........

28/12/2002

ayrılık öncesi! !', 'sensizlikle flört etmeyi, sen yokken sana aşık olmayı ve bunu yüreğimin en sevdalı köşesinde saklamayı ancak ve ancak sensizlik bilir! ! sen...', ARRAY['Türk Edebiyatı','Şiir','Laci Gece']::text[], 8.5, '{"poet":"Laci Gece","poet_slug":"laci-gece","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sensizligin-ertesinde-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ilgaz''da', 'ilgaz-da-husrev-hatemi-wa6xa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uğultu, dağ başına kadar izlesin beni, 

İzlesin beni uğultu doruğa kadar, 

Her biri bir ses perdesiydi, çevremdeki insanlar...

Saz semaisi sussun şimdi; 

Öyküler ilginçliklerini yitirdiler, 

Ümit ise, geçerliğini...

Uğultu, dağ başına kadar izlesin beni, 

Dallar, çiçekler ve sarp kayalar

Beni devralmalılar uğultudan, 

Beni devralmalılar, orada, dorukta.

Duyduğumda hep yogun bir derde

Dönüşen besteyi istemiyorum..

Fakat orada, ilerde, dorukta

Uçurum aşağı, kısa yolculukta

Duyulsun isterim saz semaisi

Bulutun akı ve göğün mavisi

İçinde dağılıp yokolsun o da...

Tükenip de sona erince ömür, 

Kişinin bestesi O''nunla ölür.', 'Uğultu, dağ başına kadar izlesin beni,  İzlesin beni uğultu doruğa kadar,  Her biri bir ses perdesiydi, çevremdeki insanlar... Saz semaisi s...', ARRAY['Türk Edebiyatı','Şiir','Hüsrev Hatemi']::text[], 8.5, '{"poet":"Hüsrev Hatemi","poet_slug":"husrev-hatemi","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ilgaz-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serseri Sevdalar', 'serseri-sevdalar-salih-ozalasan-3s33b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevmek; Kimini mecnun eder, yürekten sevince

Sevmek; Kimini deli eder, sevdiğini kaybedince

Sevmek; Kimini sarhoş eder, içmeden alabildiğince

Sevmek; Serseri sevdaya döner, bizim gibi sevince

Sevmek; Yüreği bir atmaktır ömrünce

Sevmek; Bir oh diyememektir gönlünce

Sevmek; Kızıl bir volkandır, ayrı düşünce

Sevmek; Serseri bir yıldız gibidir, tanımaz yörünge

Sevmek; Bazen ateş olur yanar gönülde

Sevmek; Bazen buz olur, Sina çölünde

Sevmek; Bazen bir balık, okyanusun dibinde

Sevmek; Serseri bir mayın gibidir seven gönülde

Sevmek; Vardır bedeni olan her yürekde

Sevmek; Çağlayıp taşar bazen seven gönüllerde

Sevmek; Kavuşmayı hayal etmek Dünya ve ahirette

Sevmek; Serseri sevda olur birleşince iki yürek bir yürekde

Sevmek; Gece yıldızları saymak sevgiliyi özleyince

Sevmek; Kayan yıldızlardan fal tutmak ümitsizce

Sevmek; Baktığını görmemek araya ayrılık girince

Sevmek; Serseri bir Güneş, doğmadan batar sevgili küsünce

Sevmek; Şimdi herkesin dilinde bizi görünce

Sevmek; Yüreklerde oldu şimdi ince bir düşünce

Sevmek; Serseri sevda hikayeleri olacak biz ölünce

Sevmek; Serseri sevdalar yaşanır oldu sen hayatıma girince

Y.Tar.26+28-12-2002', 'Sevmek; Kimini mecnun eder, yürekten sevince Sevmek; Kimini deli eder, sevdiğini kaybedince Sevmek; Kimini sarhoş eder, içmeden alabildiğinc...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/serseri-sevdalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kayıp, Bir Anne ve Bir Ders', 'bir-kayip-bir-anne-ve-bir-ders-gokcen-duran-tonhp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '(Acı  çeken  annelerimize  en  içten  duygularımla. 

       Dilerim ki  acıları  sonsuza  kadar  sürmez)

En acı veren şeylerden biridir kaybetmek

Kaybettiklerimiz, kendi acılarıyla ders verir

Hayatta kalanlara, yavaş yavaş

Kaybettiklerimizin kendileriyle örtüşen

Karşılıkları vardır hayatta

Onları yaşadıkça, onlara rastladıkça

Acı çekeriz.

Ama hiçbir acı sonsuza kadar sürmez.

Birileri hep durak yapar hayatımızda

Önce gelir. Geliş güzeldir, mutlu eder bizi

Zamanla alışırız ona, hayatımızda bir yer edinir

Sonra gider. Gerisinde bir boşluk bırakarak

Bizde uzaklaşan her şey

Bizden bir parça da olsa

Hayat, kaybettiklerimizle ders verir bize

Hem de yüzümüze tokat atarak

Kanayan yüreğimizi iki misli kanatarak.

“Hayat böyle bir şey olsa gerek”

Kaybetmiştik 

Bizden bir parçaydı o

Umutlarımız ona asılıydı, 

Varlığı sevinç getirmişti bize

Ölümü hüzün ve gözyaşı

Umutlarımız, yarınlarımız, onunla gömüldü

Ölüm sessizliğine...

Geri de onun hayata yansımaları kalmıştı.

Her ölümün geride bıraktığı 

Derin bir sessizlik ve boşluk kalmıştı.

Bir şeyin kaybının anlamının derinliğini, 

Hayatın ta kendisi sunar insana

Birilerini kaybetmenin anlamı, 

Yaşarken çarpar yüzümüze

Tanrı insana acılar verir önce, 

Sonra acıları yatıştırıcı dersler, 

Bir Pazar günüydü, 

Yürüyordum sokakta

Çevremdekilerin gölgeleri, 

Sokağa düşüyordu.

Kalabalık içinde yapayalnızdım.

Bir ses beni derin düşüncelerimden uyandırdı: 

“ Bana yardım edebilir misin? Evladım! ”

diyordu, 

Elinde iki süt bidonu, sırtında 

Yılların ağırlığından daha ağır bir çuval, 

Beli iki büklüm, dili lal

Sırtından aldım çuvalını, 

Gideceği yere kadar, taşımak için.

Ağırlığını görünce şaşırdım.

Bu yaşta ve bu bedenle, 

Nasıl taşıyabiliyor bu yükü! 

Anladım ki! En ağır yük hayatın ta kendisidir.

Yoksul insanlar için. 

Yanından arabalar geçiyordu.

Onun görüntüsü her gün gidilen 

Resim sergilerindeki tablolardan, 

Çok daha anlamlı bir tabloydu.

Arabalarının camlarına, kartondan bir yaşam

Koymuştu herkes! 

Anlamlandıramıyorlardı, yanı başlarındaki

Bu tabloyu! 

Hep bir şeyler yitirdik

Bu yitirdiklerimiz içinde en çok yitirdiğimiz, 

Bu insanları fark etmeyen, 

Görme duyusudur, sanırım.

İçi sıcacık arabalar, içinde kadınlar, erkekler, çocuklar...

Eşyaları bagajlarında, 

Yük olmadan sırtlıyorlar hayatı! 

Hayat onlar için “ Kendim” merkezli.

Yürüdük bir süre, 

Yüzünü kaldıramadı, 

Bakamadı bile yüzüme, 

İki büklüm beli engelliyordu onu

Biri iki soru sordu.

Arkasından derin bir sessizlik.

Duygulandı

Buğulandı, gözleri

Ağlıyordu yanımda sessizce

Sırtındaki yük ağırlığıncaydı.

Yere düşen her damla yaşı, 

Hem ağlıyordu, hem de anlatıyordu.

Süt satmaktan utanan evlatları varmış.

Kendisine yardım etmiyorlarmış.

Onun deyimiyle birer hayırsız evlat

Bizim dün yitirdiğimizi! 

O, çoktan yitirmişti, yüreğinde

Hayatta olanları yüreklerde yitirmek

Bu olmalıydı.

Titreyen dudaklarından, dualar yükseldi

Sonsuz boşluğa

Durağa gelmiştik, döndü ve baktı yüzüme

“ Tanrı hayırlı bir evlat nasip etsin sana.”

Dilerim ki yaşlanınca, talihin benzemez, bana! 

Ayrıldım yanından

Yüreğimiz yarısı onda kaldı, 

Yarısı yitirdiklerimde

Anladım ki, 

Hayat, kaybettiklerimizle yine hayatta ders veriyor bize

                       Tanrı insana acılar verir önce, 

                       Sonra acıları yatıştırıcı dersler.', '(Acı  çeken  annelerimize  en  içten  duygularımla.         Dilerim ki  acıları  sonsuza  kadar  sürmez) En acı veren şeylerden biridir kayb...', ARRAY['Türk Edebiyatı','Şiir','Gökçen Duran']::text[], 8.5, '{"poet":"Gökçen Duran","poet_slug":"gokcen-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":101,"source_url":"https://www.antoloji.com/bir-kayip-bir-anne-ve-bir-ders-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarz', 'tarz-kucuk-i-skender-jyojk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gece ile haplandık 

zarara gidiyoruz topyekun

çile koyduk dudaklarımızın adını

fırsat bildik vücuda gelişimizi

ne fısıldasak kardı

meleklerin tebessümü imiş feza

sınıflanmadık

teşekküre geçerken tüm serseri aşklarımız

omurgalarımıza döşenmiş elektrik kablolarıyla, 

biraz hayata sinirlendik

hayli öfkelendik tarihe hayırlısıyla, 

ölmemek için mücadele dersinde

şeytani ruhtan kopya çektik

meleklerin göğüs uçlarıymış ay''la dünya

bilemezdik

yeryüzündeki acılardan utanıyorduk

henüz göğe bakmadık!', 'gece ile haplandık  zarara gidiyoruz topyekun çile koyduk dudaklarımızın adını fırsat bildik vücuda gelişimizi ne fısıldasak kardı melekleri...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/tarz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamaz Oldum', 'anlatamaz-oldum-emre-orkun-zmgbb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kalem kağıda değmeden anlatamaz oldum kendimi, 

Kayıkta ki kürek, kürekte ki su damlalarıyım şimdi.

Ters koşan bir adamın ilerleyişinde, 

Yalnız duran çınarın çokluğundayım şimdi.

Bitti sandığımın yeni başladığı günlerde, 

Uyanışlardayım şimdi.

Dostlar yalan konuştu demişler, 

İsyanlardayım şimdi.

Nişanım bozuk, namludaki küfüm 

Ve de tilkideki hinim şimdi.

Kaçmak ister aklım, 

Lambada ki cinim şimdi.

Yani tüketmişim beyazı, 

Siyahtaki huşum şimdi.', 'Kalem kağıda değmeden anlatamaz oldum kendimi,  Kayıkta ki kürek, kürekte ki su damlalarıyım şimdi. Ters koşan bir adamın ilerleyişinde,  Ya...', ARRAY['Türk Edebiyatı','Şiir','Emre Orkun']::text[], 8.5, '{"poet":"Emre Orkun","poet_slug":"emre-orkun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/anlatamaz-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönerim Sanırım', 'donerim-sanirim-emre-orkun-066yc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sebebimi bilir de, 

Kokum yok, dikenlerimi saldım sanırsın.

Korkmak hakkı değil mi ellerimin? 

Unuttuklarımı hatırlamam sanırsın.

Çoktandır yürümedim sevdiğim kentin sokaklarında, 

Evinin yolunu unutmam sanırsın.

Küçüklüğüme bile verdim fermanı, 

Sana kalemi kırmam sanırsın.

Yüzler, yerler kalırda aklımda, 

Seni sana vurmam sanırsın.

Doğruyu bilsem de yanlıştan çok, 

Suçları cezasız bıraktım sanırsın.

Halefi selefe değişmem, 

Yine sana dönerim sanırsın.', 'Sebebimi bilir de,  Kokum yok, dikenlerimi saldım sanırsın. Korkmak hakkı değil mi ellerimin?  Unuttuklarımı hatırlamam sanırsın. Çoktandır ...', ARRAY['Türk Edebiyatı','Şiir','Emre Orkun']::text[], 8.5, '{"poet":"Emre Orkun","poet_slug":"emre-orkun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/donerim-sanirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Korku Saldım İçime', 'bir-korku-saldim-i-cime-emre-orkun-00ys7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir korku saldım içime, 

Yapacak o kadar çok şey varken, 

Ve Yapacak gücü kendinde bulmuşken, 

Bir korku saldım içime...

Etimi kanıma böldüren, 

Deli divaneye döndüren, 

Hayatın değerini bildiren, 

Bir korku saldım içime. 

Etimi kanıma böldüren, 

Deli divaneye döndüren, 

Hayatın değerini bildiren, 

Bir korku saldım içime.', 'Bir korku saldım içime,  Yapacak o kadar çok şey varken,  Ve Yapacak gücü kendinde bulmuşken,  Bir korku saldım içime... Etimi kanıma böldür...', ARRAY['Türk Edebiyatı','Şiir','Emre Orkun']::text[], 8.5, '{"poet":"Emre Orkun","poet_slug":"emre-orkun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-korku-saldim-icime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Örtüşen Sevdalara Koştular', 'ortusen-sevdalara-kostular-selahattin-demiraco-1gqz4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Örtüşen sevinçlere koştular

Eski sevdalar ayrılıktı

Herşey mazide kaldı

Birdaha yolları kesişmedi

Örtüşen sevdalara koştular

Eski sevdalar ayrılıktı

Mutluluklar yakındı

Şarkılara şiirlere konu oldular

Örtüşen sevinçlere koştular

Herşey mazide kaldı

Mutluluklar yakındı

Sevda rüzgarlarına koştular.', 'Örtüşen sevinçlere koştular Eski sevdalar ayrılıktı Herşey mazide kaldı Birdaha yolları kesişmedi Örtüşen sevdalara koştular Eski sevdalar a...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Demiraco']::text[], 8.5, '{"poet":"Selahattin Demiraco","poet_slug":"selahattin-demiraco","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ortusen-sevdalara-kostular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanar Tozlu Patika Yollar', 'yanar-tozlu-patika-yollar-selahattin-demiraco-hopvs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saçları nar çiçeği bir kadın

İplik eğirir ağırşakla

Kır menekşeleri gelincikler

Böğürtlenler kara kara

Bir ağıt yakmışlar 6000 yıllık

Kanlı geçitte Aşağıpınarda

Kelebeklerin düğünü vardı

Yolları kesti haydutlar

Genç bir kız sekti

Omuzunda testisi

Peşinde sevdalısı

Yanar tozlu patika yollar

Ağustosun onbeşi

Yolları kesti haydutlar

Ortalık kül rengi', 'Saçları nar çiçeği bir kadın İplik eğirir ağırşakla Kır menekşeleri gelincikler Böğürtlenler kara kara Bir ağıt yakmışlar 6000 yıllık Kanlı ...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Demiraco']::text[], 8.5, '{"poet":"Selahattin Demiraco","poet_slug":"selahattin-demiraco","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yanar-tozlu-patika-yollar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Diye Bir Duygu', 'ask-diye-bir-duygu-salih-ozalasan-ok1ez', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşk diye bir duygu olmasa yüreğimde

Geceler boyu yıldızları saymak niye

Aşk diye bir dua olmasa dilimde

Geceler boyu şiirler yazmak niye

Sevdalara dalıp gitmese gözlerim

Hıçkırıklara boğulup ağlamak niye

Özleminle yanmasa ciğerlerim

Saçlarımdaki bu zamansız aklar niye

Seni sevmesem umutsuz çaresiz

Kılacak aradaki dağlar önümde secde

Ölümsüz şarkılar söylenir hep sensiz

Dilimde dua sana yazdığım son beste

Aşk''ımı kattım mısralara 

Sen varsın notalardan çıkan her seste

Bülbülün muradı sensin sal dağlara

Sensiz ölürüm ben altın kafeste

Adını yazdım aya yıldıza karlı dağlara

Aşk onlarıda eyledi pare pare

Bir ümitsiz aşk''mı sebep şimdi bunlara

Aşk''ına tutulalı olmuşum ben bi''çare

Y.Tar 29-12-2002 Saat 22 25', 'Aşk diye bir duygu olmasa yüreğimde Geceler boyu yıldızları saymak niye Aşk diye bir dua olmasa dilimde Geceler boyu şiirler yazmak niye Sev...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ask-diye-bir-duygu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Medcezir Duygular', 'medcezir-duygular-sebahattin-abi-brsts', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tebessümü gördüm yüzünde, yüreğine dokundum,

Sessizce senden habersiz...

Ve seni sevdim yüreğimde gizlice.

Gözbebeklerine dokundum,

Yüreğini hissettim tebessümünde...

Gözyaşlarımı gördüm kanayan yüreğimde,

Koptu icimden bir şeyler yüreğim acıdı

İlk defa sensizlik bu kadar koydu bana...

Tebessümünde gördüm yüreğini,

Ve dokundum yüreğine sessizce...

Güneşi avuçladınmı yüreğin buz tutmuşken,

Dolu dizgin sevdalarında okyanusları koydunmu cebine,

Fırtınaları kucakladınmı hiç..

Sen bir bebeğin yüreğini gördünmü mavi sabahlarda,

Dokunabildinmi bir kuşun göz yaşlarına

Ölümü öptünmü gözbebeklerinden.

Parmaklarının ucunda hissettinmi soğukluğunu,

Sonra yüreğinin çırpınışlarını duydunmu gürleyen gökyüzünde

Boşaldımı gözyaşların yeryüzüne,

Islattımı kaldırımları,

Sen geceyi duydunmu hissettinmi titreyen ellerıinde,

Hadi uzat geceye ellerini.

Haykır sesin kısılıncaya kadar yırtılıncaya kadar gökyüzü.

Unut dünde ne varsa,

Yarınlar senin inandır kendini

İnandır yüreğini...

Yalnız değilsin, çaresiz değilsin

Gözlerinin derinliğine yelken aç.

Pupa yelken doldur yureğini,

Kılavuzun ruhun kaptanın sevgin...

Haydi durma açıl aydınlık yarınlara....', 'Tebessümü gördüm yüzünde, yüreğine dokundum, Sessizce senden habersiz... Ve seni sevdim yüreğimde gizlice. Gözbebeklerine dokundum, Yüreğini...', ARRAY['Türk Edebiyatı','Şiir','Sebahattin Abi']::text[], 8.5, '{"poet":"Sebahattin Abi","poet_slug":"sebahattin-abi","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/center-medcezir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geniş Aşk Konsepti', 'genis-ask-konsepti-kucuk-i-skender-qs4x5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kurtarılmış bir bölgeyim, gölgemde hurma ağaçları.

Üzerimde sonsuz küstahlığın tırnak izleri var.

Kurtarılmış bir de gövdeyim aslında yekpare taştan, 

Başucuma slogan yazıyor çok sevdalı çocuklar.

''Biz gecenin emrine girdik, 

Gözümüz keder görmez artık! '' diye

hayıflanıyor kimi elementler, oysa ben

atomunu yeşile kaptırmış alelade bir ot gibi

bitmek taraftarıyım bir cenk sahilinde.

Dudakları polis ruju bir kadınla da seviştim

yüzünde bir yama gibi duran bakışlarıyla

beton bir kadın.

Tabelası sökülmüş kasabalardan gelen bir kadın

Aşkta tedbirli, serserilikte acımasız

hayata kuvvetli bir şamarla inen

yedi ceddi yetmiş yedi bela kuşanmış 

başka erkeklere kurnaz

bana bir gangster kadın.

Adı dilimde tespih

Adı göğümde vahşi dolunay

göğsünden şerbet fışkıran kadın. 

Her yıl derisini değiştirirdi onsuz bunaldığım şehir

anarşistler ırmakları ateşe verir, dağları zorlardı

büyük harflerle yazılmış bir yalnızlıkla düşünüyorum da şimdi

kaç hücresi hayata bağlıdır artık ve

benim susturduğum kainatta o hangi gezegendedir.

Kurtarılmış bir bölgeyim, gölgemde hurma ağaçları

hatıramda öyle uzun, öyle sıcak, simsiyah bir sedir

oturmuş yaşlılar, topraktan pirinç ve gençlik ayıklar

söyle bana ömrüm, bu saadet değilse nedir', 'Kurtarılmış bir bölgeyim, gölgemde hurma ağaçları. Üzerimde sonsuz küstahlığın tırnak izleri var. Kurtarılmış bir de gövdeyim aslında yekpar...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/genis-ask-konsepti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Giyip Gülgûn Demâdem Azm-i Cevlân Eyleyen', 'ey-giyip-gulg-n-dem-dem-azm-i-cevl-n-eyleyen-fuzuli-94saq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey giyip gülgûn demâdem azm-i cevlân eyleyen

Her taraf cevlân edip döndükçe yüz kan eyleyen

Ey beni mahrum edip bezm-i visâlinden müdâm

Gayri, hân-ı iltifatı üzre mihmân eyleyen! 

Ey demadem reşk tiğiyle benim kanım döküp

Mey içip ağyâr ile seyr-i gülistân eyleyen.

Bunca kim efgaanımı ey mâh, işittin giceler

Dimedin bir gice; ''''Kimdir bunca efgaan eyleyen.''''

Aşk derdiyle olur aşık mizâcı müstakîm

Düşmenimdir dostlar, bu derde derman eyleyen.

Derd-i hicrân, natüvan etmiş Fuzûlî hasteyi,

Yok mudur Yâ Rabb devâ-yı derd-i hicrân eyleyen!', 'Ey giyip gülgûn demâdem azm-i cevlân eyleyen Her taraf cevlân edip döndükçe yüz kan eyleyen Ey beni mahrum edip bezm-i visâlinden müdâm Gayr...', ARRAY['Türk Edebiyatı','Şiir','Fuzuli']::text[], 8.5, '{"poet":"Fuzuli","poet_slug":"fuzuli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ey-giyip-gulgun-demadem-azm-i-cevlan-eyleyen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gayr İle Her Dem Nedür Seyr-i Gülistân Etdüğün', 'gayr-i-le-her-dem-nedur-seyr-i-gulist-n-etdugun-fuzuli-4nyho', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gayr ile her dem nedür seyr-i gülistân etdüğün

Bezm edüp halvet kılup yüz lutf u ihsân etdüğün

Ahd bünyadın mürüvvetdür mi vîrân etdüğün

Hanı ey zâlim bizümle ahd ü peymân etdüğün

Lahza lahza müddeî pendin dür-i gûş eyledün

Kana kana gayr câm-ı şevkini nûş eyledün

Vara vara ahd ü peymânı ferâmûş eyledün

Hanı ey zâlim bizümle ahd ü peymân etdüğüm

Gayre salup mihrüni bizden savutdun âkıbet

Terk-i mihr etdün tarîk-i zulm dutdun âkıbet

Ahdler peymânlar etmişdün unuttun âkıbet

Hanı ey zâlim bizümle ahd ü peymân etdüğüm

Cürmümüz n’oldı ki bizden eyledün bîzârlığ

Biz gamun çekdük sen etdün özgeye gam-hârlığ

Sizde âdet bu mıdur beyle olur mı yârlığ

Hanı ey zâlim bizümle ahd ü peymân etdügün

Çerh tek bed-mihrliğ resmini bünyâd eyledün

Yahşi adun var iken döndün yaman ad eyledün

Döne döne bizi gam-nâk özgeni şâd eyledün

Hanı ey zâlim bizümle ahd ü peymân etdüğün

Gönlümüz min-ba‘d zülfünçün perîşân olmasun

Bağrumuz la‘lün hevâsiyle dahi kan olmasun

Bî-vefâsen çeşmümüz yâdunla giryân olmasun

Hanı ey zâlim bizümle ahd ü peymân etdüğün

Va‘de-i vasl ile aldun sabrumuz ârâmumuz

Olmadı her gün visâlünden müyesser kâmumuz

Geçdi hecr ile Fuzûlîden beter eyyâmumuz

Hanı ey zâlim bizümle ahd ü peymân etdüğün', 'Gayr ile her dem nedür seyr-i gülistân etdüğün Bezm edüp halvet kılup yüz lutf u ihsân etdüğün Ahd bünyadın mürüvvetdür mi vîrân etdüğün Han...', ARRAY['Türk Edebiyatı','Şiir','Fuzuli']::text[], 8.5, '{"poet":"Fuzuli","poet_slug":"fuzuli","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gayr-ile-her-dem-nedur-seyr-i-gulistan-etdugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sade Döküm', 'sade-dokum-kucuk-i-skender-7486s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-Yaramazlık yapanları tahtaya yaz 

dedi öğretmenim.

Dağların ve sevdanın, 

mücadelenin ve yalnızlığın

şiirini yazdım bembeyaz sayfalara! 

Tarih derse girene kadar da silmedim! 

15 ağustos 1998', '-Yaramazlık yapanları tahtaya yaz  dedi öğretmenim. Dağların ve sevdanın,  mücadelenin ve yalnızlığın şiirini yazdım bembeyaz sayfalara!  Ta...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sade-dokum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük Acılar', 'buyuk-acilar-atilgan-alemdar-4qkys', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yüzümden firar etti gözlerim 

şimdi bir denize bakıyorlar 

dört duvar arasında kalmışım 

yanımdakiler öyle diyorlar 

kafamı çarptığım ranzanın demiri 

ciğerlerimi emen soğuk duvar 

saçımdaki karları çoğaltmışım 

yanımdakiler öyle diyorlar 

görüş günüm olmadı henüz 

daha yeni başlıyor büyük acılar 

ve daha epey ağrıyacakmışım 

yanımdakiler öyle diyorlar 

seni görmeyeceğim artık 

zaten tamamlanmıştı anılar 

ihtimal sabah alınırmışım 

yanımdakiler öyle diyorlar 

gözlerime iyi bakarsın umarım 

günde milyonlarca kez seni ararlar 

diğer tüm hisleri bırakmamışım 

yanımdakiler öyle diyorlar 

yanımdakiler öyle diyorlar', 'yüzümden firar etti gözlerim  şimdi bir denize bakıyorlar  dört duvar arasında kalmışım  yanımdakiler öyle diyorlar  kafamı çarptığım ranzan...', ARRAY['Türk Edebiyatı','Şiir','Atılgan Alemdar']::text[], 8.5, '{"poet":"Atılgan Alemdar","poet_slug":"atilgan-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/buyuk-acilar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birr Hhissim', 'birr-hhissim-kucuk-i-skender-tglq9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bbu yyıl nne kkadar ççok ssevdim kkaçtım: : ttehdit aaltındayım

aaşk ççırağıyım, , bbiliyorum, , ööldürülürüm: : iişgal aaltındayım

iinan ddoğrudur bbazı hhayvanların rruhlarının oolduğu

yyazmayı ööğrenip ookumayı ssökememiş bbir yyavru ttanrı

ggibi

ddağlarındayımmm

aalkol, , uuyuşturucu vve sseks vve ssosyalizm vve aanarşizm vve

iiçimde ssağ kkalmış bbir yyaradılış

iiçimde ssağ kkoyulmayacak bbir hhis

ggünü ggecenin ssırtında ggeçeceksek eğer

eellerimi ttemizle

ggözlerimi ttemizle yyalvarırım           ddayanamam

kkırk hhasretlik öömrüm vvar             bbir hhissim

vvar zzindanlarında ssaklanan ggöndermeli ttutkular oo

hher yyere aalışkanlıklarıyla ggiden bbirileri ggibi, , 

nneredeysen ooraya ggömsünler kkoparttığım aağzımı

ddudaksızım aahlaksızım ssensizim bbiraz aanla ssev

kkabul kkabul

kkabul kkabuk

                  bbağlayarak aatan kkalbimin eefendisisin

bbir hhissim

vvar eefkarlarında ssaklanan göndermeli aavuntular oo

hher yyere kkendi bbalıklarıyla ggiden ookyanuslar ggibi, , 

                                                                      228.ttemmuz.11992', 'bbu yyıl nne kkadar ççok ssevdim kkaçtım: : ttehdit aaltındayım aaşk ççırağıyım, , bbiliyorum, , ööldürülürüm: : iişgal aaltındayım iinan dd...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/birr-hhissim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Etheromanie', 'etheromanie-kucuk-i-skender-fhgtl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bana...

ayna dönerken içine bakamam

kanapede uyuyor çıplak delikanlı

aşk memnun

Cuk Paşa''nın fermanı sarılmış 

ütüler arasında yatıyorum, buruşmuşum

el peşrev, ölü gözleri ve şehvet, 

zamanın arifesinde bir çift 

                                 siyah deri eldiven 

kapı aralığı bir sevgilim var 

dudakları: intihar fragmanı

gözleri: filmin devamı

türkçenin ilk büyük Yalnızlığı  bu

komşu bahçede öldürülüyorum

yangın uyandırıyor beni sesimden

akışta sürekli yenilenen bir renk, 

rakı içmeye ve sevişilmeye gidilen

o kenar ev, bahçıvanın beni seyrettiği

boynumdaki mor atkıyı örtüyorum

delikanlının ateş kasıklarına, bir denizatı

çıkmak istiyor aralayıp gözkapaklarını

mazgala yuvarlanmış bakışlarda ara

anı hapishanesinin gaddar gardiyanını

bir jilete bütün hayatımı anlatıyorum

kız bir memesini yatağın altına düşürmüş

öbür memesi apartman boşluğunda, 

dışarsı? 

dışarsı sahte bir dua sarhoşluğunda! 

snop ve kedi, kalorifer dairesinde

gizle cehennem sarıyorlar

yeşil horoz geceyatısı öter

künyemi ve seksimi ders diye okutuyorlar

otomobilimin arkası yarın ve dışkı kırıntıları

bir lise tuvaletinde, camda, korkma! 

buğuya yazdığım son destan: 

-yürüyemeyeceğin caddede

kaldırıma çıkman fayda etmez

pazar günleri sokakta sevişelim

raconumu bozarak doğuyor gün ve

ve gün raconumu ortadan çizerek, 

dlyrk bir dark side of the moon

ayışığının ayışığı bir yılgının sanrıları 

bir sebeplenişle, ilelebet saks eşliğinde, 

kes sakallarını! 

bazı sözcüklerin tozunu alma sırası geldi

sırtının demiryolu omurgana deydirdiğim makas

senin denizfenerinde yakıldım ben

özür dilerim

tamamı siyah! timsah siyah! 

ayna dönerken içine bakamam

ve asansörün çelik halatlarını kesiyor 

annem', 'Bana... ayna dönerken içine bakamam kanapede uyuyor çıplak delikanlı aşk memnun Cuk Paşa''nın fermanı sarılmış  ütüler arasında yatıyorum, bu...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/etheromanie-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgim Sermayem Yolunuza', 'sevgim-sermayem-yolunuza-ugur-oguz-sahin-n0xpw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hep gözlerim üzerinde hapis

Duygularım gardiyan olmuş sanki

Parmaklıklara kilitlenip kalmış gibi

Hasretliğim yanıyor içimde şimdi

Sana hiç bir şey vadetmedim bilirsin

Ne bir dünya malı ne de bir servet

Pembe rüyalara da uzak kaldım hep

Gecen ve gündüzün için iki çiçek sundum sana

Beni onlarda kokla bizi bulursun onlarda

Sonsuz şükürler olsun yaradana

Aşkımızın ve sevgimizin eseridir bu

Ölene dek en sonsuz armağanlarım sana

Gönlüm ev değil saraydır sana

Göz bebeklerim en renkli giyisilerdir sana

Sofralar doldurur taşırır sevgi sepetim size

Ne üşür ne ıslanırsınız çatıdır kollarım kanatlarım

Tek hedefim var o da mutlu kılmak sizi

Dahası var mı bu dünyanın var mı başka gayesi

Hiç olmazsa gayem yarına borçlu bırakmamak sizi

Sevgim sermayem yolunuza hep onu harcıyorum', 'Hep gözlerim üzerinde hapis Duygularım gardiyan olmuş sanki Parmaklıklara kilitlenip kalmış gibi Hasretliğim yanıyor içimde şimdi Sana hiç b...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevgim-sermayem-yolunuza-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım Ve Şile', 'yalnizligim-ve-sile-ugur-oguz-sahin-3z570', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şimdi güneş batıyor vakit akşam

Karşımda daha yanmamış Şile feneri

Koyda bir sessizlik deniz çarşaf gibi

Sana yazıyorum maşatlık parkında arabamda

Seni ilk gördüğüm heyecanımdaki gibi Şile

İnsanlar rengârenk cıvıl cıvıl giyinmişler

Kiminin yolu bir bara bir restorana ya da çay bahçesine

Şile''de akşam Şile''de sessizlik o fener karşısında

Şile''de festival var tiyatro konser

Sadece bir eksik olan sensin

Şile''de herkes birlikte bir ben yalnız bir de fener altı

Acaba sen nerdesin

Doğruymuş çok güzelmiş Şile

Zaten üstat Atılay getiriyor dile

Bir kere sevmek yetmez bir kere gelmek yetmez

Sana olduğum gibi tiryaki olmaktan korkuyorum

Şile akşamında Şile''de olmaktan çok mutluyum

Şimdi yandı fener o da sanki selamlıyor beni

Aşağıdan gümbür gümbür müzik sesi geliyor

Ama senden hâlâ bir ses yok

Güzelim Şile diyorum sana dediğim gibi

Bir sözüm vardı bir borcum vardı geldim işte Şile

Çok şirinmişsin çok güzel o da senin gibi

Sen tüm güzelliğinle karşımdasın can özüm nerede şimdi', 'Şimdi güneş batıyor vakit akşam Karşımda daha yanmamış Şile feneri Koyda bir sessizlik deniz çarşaf gibi Sana yazıyorum maşatlık parkında ar...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yalnizligim-ve-sile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Kadar Güldü Gül de', 'o-kadar-guldu-gul-de-kucuk-i-skender-7umc7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kadınım benden kaldı şuaya, bir ölü basil gibi, 

zencefil kokan butlarında bulut dadanmış esrar

epriyen salgıları artık benden daha dün

ve benden daha uzak, adalardık, tadına kaçtık, 

siyah ellerin kimi nereye koyduğu efsanesi

gözümün tekiyle tutuşturdum delikanlının yüzünü

yürüdük sonra, çok unutulmuş bir haykırışa doğru

caddeler sokaklara çocuk muamelesi yaparken

ve istanbul dönüşmemişken henüz

erkeğim benden kaldı efsuna, bir ölü virüs gibi, 

tepemizde kamikaze ışıkları

yeniden kanadı vücudumun o an bir tarafı

yeniden kanadı vcudumun kopuk, bensiz ay, 

kenti ezberlemeyi hatırlatan çok şey oldu

ve ağaç yapan adamın intiharını yazan şair

ne kadar yaşlanmışsak, o kadar güldü gül de

üstü örtük maceraperest tülden yürüdük

uykunun memebaşlarında valsli bir veda

ne düttürüambos şarkıları ne de emelimde

bir şeytan yumurtası

                                   gibi

ateş ateş eriyerek geldi içime

kenti ezberlemeyi hatırlatan çok şey oldu

ve biz ne kadar sevişmişsek, o kadar güldü gül de

                                                                               18.mayıs.1990', 'kadınım benden kaldı şuaya, bir ölü basil gibi,  zencefil kokan butlarında bulut dadanmış esrar epriyen salgıları artık benden daha dün ve b...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/o-kadar-guldu-gul-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Hedefimsin', 'tek-hedefimsin-ugur-oguz-sahin-x6gtj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Damarlarımda dolaşanımsın

Tenimdeki dürtü sen yaşatanımsın

Düşlerimde kaynayan kızıl volkan

İsteyip de yaşayamadığımsın

Rüzgârınla saçlarımı okşayanımsın

Ruhumu kasıp kavuran tozutanımsın

Tekleyen kalp atışlarımdaki

Korkumsun öldüren heyecanımsın

Gözlerimdeki göz bebeğimsin

Düşlerimin ürettiği emeğimsin

Penceremdeki dertleştiğim mavi menekşem

İçimdeki deprem yaşamımın tek hedefisin', 'Damarlarımda dolaşanımsın Tenimdeki dürtü sen yaşatanımsın Düşlerimde kaynayan kızıl volkan İsteyip de yaşayamadığımsın Rüzgârınla saçlarımı...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tek-hedefimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahlaksızlık', 'ahlaksizlik-kucuk-i-skender-2jl6f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'artık zamanın da üstünde şık bir şehirde

mazgallara kapatılmış, büyüyemeyen çocuklar için

kafatasları çelikten adamların şarkılarını

ya da rahibe pelerini altına gizlenmiş, 

gözleri irin torbalarıyla kanlı şeytanları

bir ruhun turuncu mihrabına getirip 

ordan aşağı atmalı..

sisle örtülü bir tanrı yüzünde ortalık

henüz

güpegündüz bir şalla sarıldıysa dörtnala

karanlık bir an

çirkin bir vincin organik çengelinde

çağdışı bir cadı gibi kusarken kanlı

asılı kaldıysa

delikanlılarla yatıp kalkan ivedi bir caddenin

dedeleri, dişsiz oratoryolar gibi embriyo ise

rahmine sıçarım böyle anaların diye

küfrederek dua adına açılıyorsa engerek yuvası avuçları

peygamber develerinin

artık zamanın da üstünde şahsiyetsiz bir şık şehirde

mazgallara kapatılmış, büyüyemeyen çocuklar için 

kutsal kabahatleri ve mecazi kerhaneleri

bir ruhun turuncu mihrabına getirip

ordan aşağı atmalı..

ve bu sülalenin bütün arsız, ağızsız ağıtlı kapılarını

o sisli yüzlerin yüzüne kapatmalı..', 'artık zamanın da üstünde şık bir şehirde mazgallara kapatılmış, büyüyemeyen çocuklar için kafatasları çelikten adamların şarkılarını ya da r...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ahlaksizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Undermost', 'undermost-kucuk-i-skender-tnu7i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kafir melaikesi.....

duanın soğuğa sürtündüğü kesik bilekleri bileyle! 

kim  yaban gecenin tozuna bulanmış çocuk: ben, 

aşkın duvarlarına gölünü biriktiren.

bizi tipi takip etti, biz orda seksek oynadık

annelerimiz yoktu, hep haylaz kalacağız sandık

kemiklerimi gömdüğüm buzul dudaklar

nasıl buruştuysa bir öpüşün ardındaki valste

ve yontunun yalnızlığına bırakılan bir sesi 

üfleyen karı kancığı spontan eller

nasıl dolaştıysa vücudumuzun en atölye kulesinde

     sizin gözleriniz akşamüstü dinlenen yaz tangolarına benzerdi. hatırlayın, ''arkadaşımın aşkısın''da birlikte ağlayışlarımızı. ve birbirimizden kaçırırken bakışlarımızı, kayboluşumuzu çiçek pasajında. sonra size o adada uzatıp verdiğim papatyaya ''şarlo'' adını takışımızdaki derin mana ve ısrar. biz umutsuzluğu iyi biliyorduk, bize hep tokat da attılar. bunlara iyi üzülürdünüz. şimdi bunlara üzülemeyecek kadar öldünüz. bana biraz chopin çalın, sarılın bana. bakın, bu sabah, buğu yağacak şehrimize ve ben, her zaman yaptığınızı yapıp, 

bir yılgınlığı okşamak için uzanan yazı

unutup gittik biz, biz hep haylaz kalacağız sandık

birbirlerine omuz vermiş insanların sararmış fotoğrafları

biz onlardan sonraları uçurtmalar yaptık.

sorguluyor tarih ve ipek bugün suçlarımızı

ve gözyaşı kanallarınızı iltihaplıyor o hisler

kanatıyor kıpkırmızı.

hırsızlar, hey hırsızlar! 

lütfen çalmayın yoksul çocukların bisikletlerini

ve onlar uzak ada vapurlarına binerken

siz satın alın bir kerecik olsun

taze, sıcak, akşam simitciklerini..

                                                                   21.eylül.1989', 'kafir melaikesi..... duanın soğuğa sürtündüğü kesik bilekleri bileyle!  kim  yaban gecenin tozuna bulanmış çocuk: ben,  aşkın duvarlarına gö...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/undermost-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eftelya', 'eftelya-monad-balkan-njsyx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'iner gibi denizlerin diplerine

dalmış gitmişim birden gizemlere

iner gibi denizlerin diplerine

dalmış gitmişim birden gizemlere

çıkıp geliyor usulca yanıma

nihaventli bir soprano

giysisi yosunun mu yeşili

biliyorum şakıyor şarkıların en güzelini

duyamasam da dibindeyiz denizin 

bakakalıyorum ardlarından

suda başını alıp gidiyor ezgiler

kuyruğundan yakalıyorum eftelya’mı

o ise ayaklarımdan

daire olup dönüyoruz

belirsizlik güneşinin ışıklarında

(10.7.1998 budapeşte

monad balkan)', 'iner gibi denizlerin diplerine dalmış gitmişim birden gizemlere iner gibi denizlerin diplerine dalmış gitmişim birden gizemlere çıkıp geliyo...', ARRAY['Türk Edebiyatı','Şiir','Monad Balkan']::text[], 8.5, '{"poet":"Monad Balkan","poet_slug":"monad-balkan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/eftelya-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Hayat Verdin', 'bana-hayat-verdin-sair-khan-hd8uj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Serin sonbahar günlerinden biriydi.Yaprakların sararıp yuvalarını terk ettiği, 

Yorgun savaşçıların cephelerde tek tek düşüp hayattan koptuğu gibi bir sonbahar, 

Yaprakların rüzgarın verdiği yöne doğru savrulmaktan kurtulamadığı, 

Kendini o rüzgarın kollarına teslim ettiği bir sonbahar, 

Dışarıda olağan günlerden tek farklı olan, O rüzgarlarla savrulmuş

Yollarda bilinçsizce dolaşan bir adam ve sen; güzün güzelliğine güzellik katan güz gülü. Hatırladın mı o Pazar sabahını, o dağların o ormanların o çimlerin asla ama asla

Bir daha şahit olamayacağı güzelliği o bedenin altında gizli güzel  küçük kızı? 

İşte o an kalbimdeki tüm kasvetin koptuğu, ümitsizliğin yerini ümide terk ettiği, 

Boş vermişliğin ve acılarının yerini sevgi ile dolduğu hatta taştığı gündür o, 

Hep savunduğum”insan sevdiğine baktı mı burnu sızlayacak gözü dolacak”tezinin

Ama inanmadığım imkansız dediğim tezimin doğruluğunun gözlerimdeki tasdiki, 

O an ve o anın gerçek sahibi canım sevgilim biricik aşkım, her şeyim

Senin anlamayacağın anlayamayacağın o kadar güzel değişikliklere, 

O kadar mutluluğa hükmettiniz  ki güz ve sen.......

Sararmış yüzle dünyaya fersiz bakan yüz ve onu isteksizce taşıyan beden hayat buldu

Mühürlenmiş kalp ve gözler birleşti çağladı coştu aşkınla rahmet oldu yağdı

Gönül kanatlandı denizle gökyüzünün birleştiği ufukta seninle birleşti 

Sonsuz diye adlandırılan çizgiye kanat çırptı, 

Kalp çarpıntıları ile hızlandı damarlardan akan kan

Beden canlandı gözler parladı, dudaklar yanlara doğru açıldı

Gün yüzünün göremediği dişler ortaya çıktı ve gülümsedi

Her ne kadar ölüm gibi görünse de güz seninle ortak bana hayat verdi....', 'Serin sonbahar günlerinden biriydi.Yaprakların sararıp yuvalarını terk ettiği,  Yorgun savaşçıların cephelerde tek tek düşüp hayattan koptuğ...', ARRAY['Türk Edebiyatı','Şiir','Şair Khan']::text[], 8.5, '{"poet":"Şair Khan","poet_slug":"sair-khan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bana-hayat-verdin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda', 'veda-baran-ozbey-4nix9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bunca yıl sonra hangi kahrolası ütopya

Kopardı benden seni, hangi kitap yazar, 

Hangi şarkı söyler, böylesi yalnızlığı

Bitkinliğin son perdesindeyim.

Boş şarap şişeleri gibi dibe vurdum.

Titanic bile hiç kalır yanımda.

Hangi okyanus hangi ırmak hangi deniz paklar

Beni, ya seni...

Senin ayak seslerin hiç usulca tırmandımı

Merdivenlerden, kazınmış loto kuponları gibi

Nasıl bıraktın beni öksüz bir başıma.

Nasıl bir intihar beni oldürür söylesene

Sensiz nasıl yasanır böyle söylesene...

Ağır vedaların adamı sen, 

Titrek masum sevdalarin alevi ben, 

Kimbilir belki bir bün bir yerde kesişir yollarımız.

Aralık 2002/ İstanbul', 'Bunca yıl sonra hangi kahrolası ütopya Kopardı benden seni, hangi kitap yazar,  Hangi şarkı söyler, böylesi yalnızlığı Bitkinliğin son perde...', ARRAY['Türk Edebiyatı','Şiir','Baran Özbey']::text[], 8.5, '{"poet":"Baran Özbey","poet_slug":"baran-ozbey","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/veda-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Günlerden', 'bugun-gunlerden-seyfettin-bilal-ozluk-pp3cf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bugün günlerden beyaz; 

İlk umut gibi içimdesin yeniden

Tüm güzelliğinle

Kalbimin en derin kuytusunda yerin...

Bugün günlerden gri; 

Git gide daha çok özlüyorum gibi

Hasret dolu, çığlık çığlık sevgi dolu yürek

Doyamıyorum seni sevmeye

Isıtmıyor hiçbirşey sıcaklığın gibi...

Bugün günlerden mavi; 

Denizlere dolarken gözlerim

Hayaller kuruyorum yeniden ilk aşk gibi

Heyecenlanıyorum

Binbir umut içimde

Binbir renk sevgi...

Bugün günlerden sarı; 

Sonbahar, 

Umutsuzluk mevsimi

Yapraklar dökülürken birbir dalından

İçimdeki rüzgar üşütüyor benliğimi

Umutlar son damlasında

Tükeniyor galiba

Tutunmaya çalışıyor varolan son gücüyle

Kaybetmemek için sevgiyi, güzelliği...

Bugün günlerden kırmızı; 

Yüzüm kızarıyor seni her düşünüşümde

Neden aşık oldum sana diyorum

Neden güçsüzüm böyle? 

Hiç kimseye yenilmedim bu hayatta

Bu denli sevmedim

Peki sen

Söyle bana

Sen niye? ...

Bugün günlerden siyah; 

Acı, matem sarmış etrafımı

Yas tutuyorum gidenlere

Dilimde bir dua, güzel günlerin anısına

Gözlerim takılı kalmış bir noktaya

Eski aşk kayboluyor

Gidiyor uzaklara...

Git sevgili, 

Doyamadığım, saramadığım, yaşayamadığım sevgili

Git ve son kez gülümse

İnanmasam da son kez

''SEVİYORUM'' de...', 'Bugün günlerden beyaz;  İlk umut gibi içimdesin yeniden Tüm güzelliğinle Kalbimin en derin kuytusunda yerin... Bugün günlerden gri;  Git gid...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/bugun-gunlerden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir can verdim cansız hayalinde...', 'bir-can-verdim-cansiz-hayalinde-baran-ozbey-1fhdr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aklıma gelir, isminin keşkelerinde...

Giden gitmişliğiyle övünürse, kalan

Kalmıslığıyla gurur mu duymalıdır...

Kim yetim kim şanslı, kim mağdur

Bilinmezki.

Sevgi o kadar yüceleşirki, 

Dünyanın merkezinde bir sen bir o.

Halbuki yürek sevgiyi bir o kadar çabuk eskitir

Parçalar, unufak eder.

Katran karası gecelerin zift kıvamı ağırlığında 

Boğulmak istersinde beceremezsin

Kahretsinler başlar iççekislerle

Üç beş nobetleriyle biter çoğu gece

Pencerende günesi doğduramaz, ayı

Batıramazsınki.

Ne tuhaf duygudur ölmek ey sevgili

Yanağımdan süzülen iki damla yaş gibi

Yığıldım kaldım, gölgenin üstüne.', 'Aklıma gelir, isminin keşkelerinde... Giden gitmişliğiyle övünürse, kalan Kalmıslığıyla gurur mu duymalıdır... Kim yetim kim şanslı, kim mağ...', ARRAY['Türk Edebiyatı','Şiir','Baran Özbey']::text[], 8.5, '{"poet":"Baran Özbey","poet_slug":"baran-ozbey","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-can-verdim-cansiz-hayalinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmen İçin', 'gitmen-i-cin-seyfettin-bilal-ozluk-hftl1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni bende arama, 

Yokum.

Gittim, gidiyorum ve gideceğim de daha...

Bu ne bir başlangıçtı, 

Ne de bir son olacak...

Ben beni kaybettim artık

Sen de arama ben de beni

Kayboldum, 

Kurtarnaya çalışma.

Işık olma karanlığıma

Hayal olma gözlerim kapandığında, 

Ne sevincim ol ne acım ne de pişmalığım...

Git, 

Beni bende bırakmadan

Kaybettiğim yarımı buldurmadan git

Hiçbir umut da kalmasın ardından

Şiirler bile yazamayayım artık sana dair, 

''Unuttum'' bile dedirtmeden git, 

Yeniden bakmadan o yalancı gözlerle

Sarılmadan boynuma, 

Uzanmadan omzuma, 

Dokunmadan...

Git, 

Beni bende bırakmadan

Kaybettiğim yarımı buldurmadan...

Git, 

Ne umudum ol, ne hayalim

Beni sensiz bırak sevdiğim

Git...', 'Beni bende arama,  Yokum. Gittim, gidiyorum ve gideceğim de daha... Bu ne bir başlangıçtı,  Ne de bir son olacak... Ben beni kaybettim artık...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gitmen-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim', 'ozledim-seyfettin-bilal-ozluk-h50yc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Oysa ki gecelerdi seni bana anlatan

Şimdi onlarda anlamsız ben de

Sen yoksan karanlıklar mutluluk olmuyor eskisi gibi...

Özledim, 

O kokunu boş sohbetlerimizi olmadık zamanlarımızdaki

Oysa ki şimdi sen yoksun

Geceler de yalnız, ben de

Eksik yaşamak vardır ya

Nefes aldığını hissedemezsin, 

İşte öyleyim, nefes alamıyorum...

Özledim, 

O kokunu, sarılışlarımızı olmadık zamanlarımızdaki

Oysa ki şimdi acılarlayım, 

Geceler de geçmek bimiyor, acılarım da

Boğulmak var ya hayal denizinde

İşte öyleyim, 

Yavaş yavaş ölüyorum galiba...

Özledim, 

O kokunu, bakışlarımızı olmadık zamanlarımızdaki

Oysa ki türkülerdi hasretleri bağlayan

Şimdi geceler de suskun türküler de

Her türkümüzü dinleyişimde çıldırıyorum, 

Yalnızlığım bir kat daha koyuyor, 

''Neden'' diye sormak var ya, 

Susuyorum; 

Ama cevabını bulamıyorum...

Özledim, 

O kokunu, suskunluklarımızı olmadık zamanlarımızdaki

Oysa ki inatlarımız vardı bizi bize bağlayan

Şimdi geceler de kaygısız ben de

Tek kaygı var ya hayatda

Sadece onun için yaşarsın

İşte öylesin

Tapınağımsın...

Özledim, 

O kokunu, sevişmeyi özledim olmadık zamanlarımızdaki....', 'Oysa ki gecelerdi seni bana anlatan Şimdi onlarda anlamsız ben de Sen yoksan karanlıklar mutluluk olmuyor eskisi gibi... Özledim,  O kokunu ...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Bilal Özlük']::text[], 8.5, '{"poet":"Seyfettin Bilal Özlük","poet_slug":"seyfettin-bilal-ozluk","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ozledim-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetim Gün''ün Mavi Umudu', 'yetim-gun-un-mavi-umudu-erol-sen-12ql0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Günsüz doğan güneşe bakarken

Yetim kalmış güneş günsüz ve gecesiz

Rengi bile bir başka soluk yaşama

Ay bile etkilenmiş bu yetimlikten

Bulutlar abuk subuk serpilmiş

Birazda şaşkınlar doğmamış güne

Yaşama sevinci kimlere kaçmış izinsiz

Yada aldatılar yaşama dair

Sevdalar kağıda dökülmeyen ama yaşanan

Umudun bekleyişi doğacak güne

Kışın soğuk bedeninden doğan

Baharı umut eden kır çiçekleri gibi

Bitmez gönlümün seven ateşleri

Kimi zaman küllenen çığlık ateşi olsa da

Umudun mavileri seven insanlara

Yaşamdaki renkli mavilerle....

30.12.02', 'Günsüz doğan güneşe bakarken Yetim kalmış güneş günsüz ve gecesiz Rengi bile bir başka soluk yaşama Ay bile etkilenmiş bu yetimlikten Bulutl...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yetim-gun-un-mavi-umudu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Yıl Mesajı-1+', 'yeni-yil-mesaji-1-bayram-tunca-elc74', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bak dünkü hayallerimiz, bugün mazi oldu

Acı-tatlı anılarımız belleğimizde arşiv oldu

Bak dünkü hülyalarımız bugün gerçek oldu

Seni sevmiş olmam, beni mutluluğa boğdu

30.12.2002-11:30

Aşk Ateşten Gömlek', 'Bak dünkü hayallerimiz, bugün mazi oldu Acı-tatlı anılarımız belleğimizde arşiv oldu Bak dünkü hülyalarımız bugün gerçek oldu Seni sevmiş ol...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yeni-yil-mesaji-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye', 'sevgiliye-hasan-azkiran-5bihe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Titrer o hatıralar  dumanlı gözlerimde.

O vefasız diyardan ne zaman sorsam seni

Hasret ateşi yanar şahlanan hislerimde

Aşkına bel bağlayan gönlümde ansam seni', 'Titrer o hatıralar  dumanlı gözlerimde. O vefasız diyardan ne zaman sorsam seni Hasret ateşi yanar şahlanan hislerimde Aşkına bel bağlayan g...', ARRAY['Türk Edebiyatı','Şiir','Hasan Azkıran']::text[], 8.5, '{"poet":"Hasan Azkıran","poet_slug":"hasan-azkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevgiliye-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenmeyen', 'beklenmeyen-guner-kurt-jhdfr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir şehir gömülürken 

Geçenin içine

Karanlık ve yorgunlukla dolu

Ben ayaktaydım

Issız ve sessiz sokaklarında

Uykusuz

Bir gün başlayacak

Sabahın ilk ışıklarıyla

Durgun ve solgun

Hep aynı hikaye tekrarlanacak

Umutsuz

Yaşanacak yine bir şeyler

Saatler dolacak boşalacak

Takip edecek akrep yelkovanı

Amansız

Yarı belli, yarı belirsiz

Gececek mevsimler

Apansız

Çalacak kapımızı

Beklenmedik bir anda

Beklenmeyen

Zamansız', 'Bir şehir gömülürken  Geçenin içine Karanlık ve yorgunlukla dolu Ben ayaktaydım Issız ve sessiz sokaklarında Uykusuz Bir gün başlayacak Saba...', ARRAY['Türk Edebiyatı','Şiir','Güner Kurt']::text[], 8.5, '{"poet":"Güner Kurt","poet_slug":"guner-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/beklenmeyen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Yeni Bir Yıla', 'umut-yeni-bir-yila-halil-gulel-tdk9r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne kadar kar yağdı ne kadar başa; 

Dizlerim çözüldü iş kola kaldı...

Bin hasret yüklendi, kor döktü düşe

Yorum çok karanlık bir fala kaldı...

Yüreğim doludur aşk ile yine, 

Muhabbet saçarım cümle her yana, 

Dilerim mutluk – barış cihana

Bu iş bizim gibi bülbüle kaldı...

Düşünceler derin deryadan derin, 

Molla Kasım çıkar yırtar eserin, 

Mutlaka bir güneş doğacak yarın

Sabrettik yürekte bir güle kaldı.

Sevmektir hayatta en hoş meziyet, 

Seven insan etmez asla eziyet, 

Güzelliğe olsa herkeste niyet

Anlaşmamız mümkün bir dile kaldı...

Dağların üstünden aştım da geldim, 

Sevdikçe sevgiyle taştım da geldimi

Ressam Halil oldum, piştim de geldim

Bütün umut YENİ BİR YILA kaldı...

                                Ressam Halil GÜLEL

		Düsseldorf / 28.12.2002', 'Ne kadar kar yağdı ne kadar başa;  Dizlerim çözüldü iş kola kaldı... Bin hasret yüklendi, kor döktü düşe Yorum çok karanlık bir fala kaldı.....', ARRAY['Türk Edebiyatı','Şiir','Halil Gülel']::text[], 8.5, '{"poet":"Halil Gülel","poet_slug":"halil-gulel","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/umut-yeni-bir-yila-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokaklar...', 'sokaklar-mehmet-bor-61bv5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şaşar kalırlardı

adres soran yabancılar.

Saf, saf bakarlardı

nereden bildiğimize.

Nerden bilebilirlerdi ki

günümüzün sokaklarda geçtiğini.

Yalan da değildi hani, 

O dönemler gençliğiydi.

Bugünlerdekilere tamamen zıt.

Soran, sorgulayan.

Karşı çıkan, 

Kötü giden herşeye

tepkisini koyan.

Olmadı mı? 

Dökülürdük sokağa, 

kovulunca oradan..

Geçilirdi öbür sokağa.

Sokakları caddeleri bilmek

Belliki önemliymiş o zaman.

O dönemler, 

Sokaklar, caddeler

bizimdi; gençlik olarak.

Cafelerin, barların..

Bugünler de, sizlerin olduğu gibi.', 'Şaşar kalırlardı adres soran yabancılar. Saf, saf bakarlardı nereden bildiğimize. Nerden bilebilirlerdi ki günümüzün sokaklarda geçtiğini. Y...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bor']::text[], 8.5, '{"poet":"Mehmet Bor","poet_slug":"mehmet-bor","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sokaklar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakıp', 'bakip-guner-kurt-9q298', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Üstüme yağsa

Sağınak yağmurlar

Damla damla

Sevinemem çöle bakıp

Aşk bahçesinde

Gezsemde doya doya

Güle dokunamam

Bülbüle bakıp

Gözlerim gözlerinde kalsa

Vakitli, vakitsiz

Tutuldum diyemem

Güneşe bakıp

Sanma ki sevmedim

Sanma ki yanmadım

Tutuştuğumu söyleyemem

Ateşe bakıp', 'Üstüme yağsa Sağınak yağmurlar Damla damla Sevinemem çöle bakıp Aşk bahçesinde Gezsemde doya doya Güle dokunamam Bülbüle bakıp Gözlerim gözl...', ARRAY['Türk Edebiyatı','Şiir','Güner Kurt']::text[], 8.5, '{"poet":"Güner Kurt","poet_slug":"guner-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bakip-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenim', 'ogretmenim-hasan-azkiran-m396f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerine baktım, yüreğine kadar gülüyordu.

O cok zarif ellerin, binlerce nakış işliyordu.

Dudaklarından, tane tane dökülen her hece, 

Bana öğüt veriyor, hedefimi gösteriyordu.

Ben senin eserinim, şükran borcluyum öğretmenim.

Bu günlerimi ben değil, bana sen hazırladın.

Sade, ham bir maddeydim, beni hamur gibi yoğurdun.

Seni çok üzdüm öğretmenim, sen bana darılmadın.

Tam aksine... öptün beni, yanaklarımı okşadın.

Ben senin eserinim, şükran borcluyum öğretmenim.

Kalem tutuyorsa elim, öz türkce ise dilim, 

İlimdir, irfandır, kadirdir senden öğrendiklerim.

Bu gün öğretmenler günü, senin günün öğretmenim! 

Bakmam yaşıma, huzurunda saygıyla eğilirim.

Ben senin eserinim, şükran borcluyum öğretmenim.

Sen var oldun, başöğretmenin devrimlerinden sonra.

Ulus için yılmadın, yorulmadın, düştün yollara.

Kar, Kış, Fırtına demedin, vurdun kendini dağlara.

Yöntemi ve yönetimi öğrettin biz Cumhurlara.

Ben senin eserinim, şükran borcluyum öğretmenim.

Bir tarih, bir corafya yaşıyor o bakışlarında...

Kar düşmüş kara dağlarına, siyah yok saclarında...

Buna ramen, bülbüller şakıyor senin gönlünde.

Solmasın senin yüzün, hep gülsün, bu günde, yarında...

Ben senin eserinim, şükran borcluyum öğretmenim.', 'Gözlerine baktım, yüreğine kadar gülüyordu. O cok zarif ellerin, binlerce nakış işliyordu. Dudaklarından, tane tane dökülen her hece,  Bana ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Azkıran']::text[], 8.5, '{"poet":"Hasan Azkıran","poet_slug":"hasan-azkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ogretmenim-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostu Ağlar Gördüm', 'dostu-aglar-gordum-hasan-azkiran-6fqsx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dostuma yüregimi actım, 

O dinledi, ben de anlattım.

Ol gülen gözlerine baktım, 

Dostumu ağlar iken gördüm.

Ne kavgam oldu, ne dövüşüm, 

Yeminimdir onu övüşüm.

Cesaretim, kalbinde görüşüm.

Dostumu ağlar iken gördüm.

Zaman geldi, ufkumu açtı.

Gün geldi, fikirler cakıştı, 

Gün geldi, bana kucak actı.

Fakat, bu gün onu aglar gördüm.

Bilsem ki bu gün doğum günü

Dostumu bayramı-düğünü, 

Ağlamı, beni çok üzdü, 

Bu gün artık gülme günü.', 'Dostuma yüregimi actım,  O dinledi, ben de anlattım. Ol gülen gözlerine baktım,  Dostumu ağlar iken gördüm. Ne kavgam oldu, ne dövüşüm,  Yem...', ARRAY['Türk Edebiyatı','Şiir','Hasan Azkıran']::text[], 8.5, '{"poet":"Hasan Azkıran","poet_slug":"hasan-azkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dostu-aglar-gordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtiraf', 'i-tiraf-guner-kurt-2gs4i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bana ne saçlarından desem

Gözlerim inkar eder

Bana ne kulak asmıyorum sana desem

Sesine odaklanır

Beni ben bile dinlemem

Sen söylediklerime bakma

Sen sakın onlara takma

Ben böyleyim bazen

Canım arkadaşım

İtiraf bu

Takıntılarda takılı kalıyoruz

Zaman zaman

Ne güzel şey oysa

Seviyorum demek

Sevdiğini göstermek

Beni bana bırak

Canım arkadaşım

Ben bunları da aşarım', 'Bana ne saçlarından desem Gözlerim inkar eder Bana ne kulak asmıyorum sana desem Sesine odaklanır Beni ben bile dinlemem Sen söylediklerime ...', ARRAY['Türk Edebiyatı','Şiir','Güner Kurt']::text[], 8.5, '{"poet":"Güner Kurt","poet_slug":"guner-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/itiraf-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal', 'hayal-erhan-balaman-mr6rj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Duvarlara Bakıp Saatlerce Oynaşan Gölgeleri Seyrettinmi hiç? 

Ve Geceyle Dost Oldunmu? 

Göz Kapakların Kıpır Kıpır! 

Yureğinse Yorgun! 

Yanlızlığa Sarılıp Uyumaya Çalıştınmı Hiç?', 'Duvarlara Bakıp Saatlerce Oynaşan Gölgeleri Seyrettinmi hiç?  Ve Geceyle Dost Oldunmu?  Göz Kapakların Kıpır Kıpır!  Yureğinse Yorgun!  Yanl...', ARRAY['Türk Edebiyatı','Şiir','Erhan Balaman']::text[], 8.5, '{"poet":"Erhan Balaman","poet_slug":"erhan-balaman","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hayal-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bak Gözlerime', 'bak-gozlerime-hasan-ozemek-porkd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerim seni anlatıyor, 

Tükenmeyen heyecanlarım dans ediyor, 

Dudaklarım titriyor adını anarken, 

Dört mevsimi yaşıyor yüreğim..

Başka bir dünyadayım sanki, 

Gözümü açıyorum sen varsın, 

Sen varsın gözümü kapattığımda  da, 

Öncesini hatırlamıyorum, 

Senden önce nasıldı yaşam, 

Nasıl dile gelirdi sevgi sözcükleri..

Bilirmiydim acaba özlemenin ne olduğunu, 

Saklamıyorum hasretliğimi, 

Bakışlarımla okşayacağım yüzünü, dokunmasam bile..

Adını hep söyleyeceğim karşımda olmasan bile, 

Bensiz gecelerinde yoldaşın olacağım, 

Bir rüzgar olacağım içini ürperten, 

Kadehe değdiğinde dudakların, 

Tadını alacaksın dudaklarımın, 

Bana susayacaksın, yudum yudum beni içeceksin, 

Tenimde alev alev yandığını hissedeceksin, 

Durma bak gözlerime...

Orada sadece kendini göreceksin....', 'Gözlerim seni anlatıyor,  Tükenmeyen heyecanlarım dans ediyor,  Dudaklarım titriyor adını anarken,  Dört mevsimi yaşıyor yüreğim.. Başka bir...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özemek']::text[], 8.5, '{"poet":"Hasan Özemek","poet_slug":"hasan-ozemek","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bak-gozlerime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostum', 'dostum-seyit-ahmet-duzen-2ukix', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bana yalnız sen dostum de! 

Ağladığımda gözyaşımı sil.

İnadına gül, gülmemi iste

Sonra...

Giderken beni öldür

Terk ederken...

Kalleşçe değil, dostça öldür.

Acımaz yüreğim, aglamam.

Kimseye dostum demem

Bir daha....', 'Bana yalnız sen dostum de!  Ağladığımda gözyaşımı sil. İnadına gül, gülmemi iste Sonra... Giderken beni öldür Terk ederken... Kalleşçe değil...', ARRAY['Türk Edebiyatı','Şiir','Seyit Ahmet Düzen']::text[], 8.5, '{"poet":"Seyit Ahmet Düzen","poet_slug":"seyit-ahmet-duzen","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dostum-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört İşlem ve Bir Türkü', 'dort-i-slem-ve-bir-turku-edip-cangonul-3j0tt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aklım kaldı yüreğinde

Nasıl gitti

Nere gider

           Bu gece vakti

                          Bensiz

Sevdamın aklı yok.

Kalmadı, 

Yüreğim de.

Kim yürek

Sevda kim

Sevmek zor böyle 

garip

sarhoş

Ve utanmaz

Ağlamaklı

Sen yine de bu yürek malın bil

İster tep

        tepiştir

İster böl odacıklarına

        Kulakcık bölü karıncık eşittir bir

Çarp duvarlara

        Bir o yana bir bu yana

Topla kirli çamaşır torbasında

Çıkar aklından

Kulun bil beni

“ben bu derde  hande derman bulayım

meğer dost elinden ola çaresi

efendim, efendim benim efendim

benim bu derdime derman efendim”', 'Aklım kaldı yüreğinde Nasıl gitti Nere gider            Bu gece vakti                           Bensiz Sevdamın aklı yok. Kalmadı,  Yüreğim ...', ARRAY['Türk Edebiyatı','Şiir','Edip Cangönül']::text[], 8.5, '{"poet":"Edip Cangönül","poet_slug":"edip-cangonul","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/dort-islem-ve-bir-turku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çökertme', 'cokertme-i-hsan-uncuoglu-ii59f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uğurlu böceler

Bacadan kimler

Kimlere gülümser, 

İnsan ağırdır kantarlanır

Mecliste Erdemlisi aranır

Aylık parasını sonuna dek

Hesapsız harca yaz bir çek

Sonu kalsın köye düğün dernek, 

***

Aklınca altı üstü altı okka çeker 

Ey karındaş diyene ver nane şeker

Bilir bilmez nedendir bir şaşı evet

Nutuklarda yayıldı şimdi gelir bereket, 

***

Taştan vergiler servet velinimet

Para bol pul oldu dön ya tekerlek

Değirmen taşın altında yoksa elek

Yetersiz keramette bulunur bin cennet, 

***

Maşallah kadın erkek çoktur altın istek

Kalb üstün el koy gönül dolsun dört Melek 

İnancımız göstermelik saçımızda başımızda

Bir dirhem bir çekirdek benzeriz muşmulaya, 

***

Kafa''da saplantı bir akıl sanki kütük kazık 

Anlayan çıkar karışamaz hoop! var ya dokunmazlık,', 'Uğurlu böceler Bacadan kimler Kimlere gülümser,  İnsan ağırdır kantarlanır Mecliste Erdemlisi aranır Aylık parasını sonuna dek Hesapsız harc...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/cokertme-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müebbet Türküsü', 'muebbet-turkusu-nevzat-celik-tmbpj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Müebbet Türküsü 

1

önce kol sonra sürgü sonra anahtar açılır kapı 

itilirim sırtımdan ben ebedi kiracı kesilmiş hükmüm 

önce sürgü sonra kol sonra anahtar kapanır kapı 

bir ömür boyu diri diri içmek için gövdemi 

dolanır bacaklarıma balçık gibi ağır bir karanlık 

çırpınsam küçücük pencerede çifte çapraz parmaklık 

üstünde yüzüme örtülür binlerce kare demirörgü 

her karesinde oyulmuş bir göz gibi kanar gökyüzü 

batan güneşim kapının önünde kıpkızıl asılırım biran 

ranzam tavana ranzam yere ranzam göğsüme çakılı 

kımıldasam göğsüm boydan boya yırtılacak sanki 

duvarlarını üstüme yıkacak hücrem adım atsam 

adım atsam apansız kurşun değdi kanadına kuşun 

tutun beni önüm berbat uçurum bu kimin sesi 

bırak torbanı atlas''a ödüldür gökkubbeyi taşımak 

düş kırıklığına salan salsın gözlerini bırak 

ranzanda yatak yatakta düşlerin dağınık kalsın 

yürü delikanlım beton altında toprak uyansın 

duvarı duvara vur ateş gibi bir ıslık tuttur 

yürü a benim deli gönlüm yürü kesilmiş hükmün 

2 

şarkılar türküler skeçler camdan cama gülücükler 

-olur böyle şeyler takma kafanı yatarız be- 

gecede ay mı var alttan alta katılaşan bir şey 

olur böyle şeyler takmıyorum kafamı yatarız be.. 

biter havalandırma eğlentisi de gecenin bir yerinde 

son sigaranın ateşi kararır dostlar uykuya varır 

gece sefası bu mevsim açar mı gecede ay mı vardı 

idamdan müebbete düştüm müebbetten hücreme 

belki sıcaktı şubat gece karla başladı fakat 

en güzel yüzünü resminin yüreğime ters kapadım 

kırdım belleğimin bütün sırrı dökük aynalarını 

ranzam soğuk ranzam ayaz ranzam kar 

altımda demir üstümde ışık yanımda duvar 

üşür ellerim sensiz ellerim öksüz ellerim 

nerde portakal bahçesi kadar sıcak memelerin 

dönerim gene duvar gene soğuk gene ayaz 

düşlerim seni almaz düşlerime müebbetim sığmaz 

bir dal fesleğen taksan da saçlarına yorulursun 

güneşi yatırsalar koynuma ısınamam 

bir yerine vardım ki gecenin sen yoksun 

3

bir yerine vardım ki gecenin sen yoksun 

sen yüreğimin dağlarında sakladığım kaçak kız 

seni sunuyor kar yüklü dallarıyla çam ağaçları 

kimliğin bende saklı uzanıp alsam alnın apak 

gece balçık gibi yapışıyor ellerime saat kaç 

tende yaşanmayacak aşkımız anladım tenimde isyan 

yorgunum ranzama uzansam gözlerimi kapatsam 

bir daha açmasam beni bu kapkara suskunluk 

beni öldürecek diyorum avaz avaz düşüyorum 

asama dikse anam kapımızdan balkona tırmansa 

akçamların kokusunu sen saçlarından savursan 

üç yanı sırılsıklam ülkem gibi hep acı dalgalara dirensen 

yanağından mutlu bir damlanın yuvarlandığını görsem 

kar da eridi çamur sonra yağmur sokaklar çıplak 

asfalt makadam bulvar ayaklarda o bildik bıçak acısı 

haki gömleğinden bir düğme aç ellerimden üşüyorum 

şafakları yunus çıkarsa ağlarından balıkçılar beter ağlar 

dudaklarında uzayan sigara külü martı kanatları ve türkü: 

bir dal fesleğen taksan da saçlarına yorulursun 

bulaşıyor dilime beni ağzınla sustur susturacaksan 

4

sabah oldu beni ağzınla sustur susturacaksan 

gazeteyle uzatıldı mazgaldan dürülmüş bir yangın gibi 

korkunç acılarıyla ellerime on üç yıl öncesinin vietnam''ı 

pirinç tarlaları bambu evleri insanları yani kavgaları 

1972 trag bang köyü ve temmuz güneşi 

ve yankee ve napalm yani ölüm bulutları 

yapışıyor sırtlarına çocukların çocukların bacakları tutuk 

çığlıkları var fakat ağızlarında boylarından büyük 

ilkokul çağında saçı kara çığlığı yangın küçücük kızın 

bant çekmişler göbeğinin altına ne ayıp ne yasak 

kaçıyor o güzelim çocuk bütün insanlığıyla çıplak 

elinden tutmalı göğsüme basmalı göğsümde soluklandırmalıyım 

benim de gözlerim yanaklarıma doğru çekilmeli acıdan 

ağzımı kulaklarıma dek yırtarcasına haykırmalıyım 

payıma düşeni almalıyım yedi milyon ton bombadan 

işte ben her acıda böyle sırılsıklam şaşkınım 

haykırılmış her çığlık burda benim ağzımı yakıyor 

durma kanıyor acılarım gövdemin neresine dokunsam 

kaldırmadan demir parmaklığı insanla insan arasından 

canım sevgilim ben bu yaraları kabuk bağlatmam 

5

alnım parmaklığa gömülü alnımda tarifsiz hasret 

dörtbir yanım idam dörtbir yanımda türküleşen müebbet 

ne bir yıldız kayar üstünden ne bir çiçek açar 

hücreler burada susuz kör kuyulara benzer 

her bahar duvara koşar da sarmaşıklar yaz biter 

yorulur sonunda salkım saçak dal budak ağaçlar 

gözlerimi içime çevirmesem gözlerim duvarda kurur 

bir an büyüse suskunluk kulaklarıma kurşun akar 

belki bu yüzden yüreğimde tepesi karlı dağlar 

boydan boya karadeniz boydan boya toros 

akdağ karadağ altındağ cudi ağrı canik aras 

vurulup öldüğüm kalkıp çocuklar gibi güldüğüm dağlar 

yakındır eteklerinde dudaklarına özenir kiraz 

ellerin tüfeğinden çözülür göğsüne ılık ılık kan yürür 

dişlerinin arasında apak ilkbahar kardeleni uyanırsın 

tenin buğulanır bilirim dudakların mahmur uykudadır 

kollarını açıp gerinirsin ormanın bütün ağaçlarınca yeşil 

dokunabilsem sana çoğalırdım saçlarınca tel tel 

yüreğimin ırmaklarını aykırı akıtıyorum dağlara doğru 

süzülüp gelsen suda bir papatya kadar güzel 

6

saçlarını yastık yapıp yatıyorsun öyle düşünüyorum 

yorgan diye geceyi dört mevsim üstüne çekiyorsun 

yaprak düşer ay düşer yıldız düşer kar düşer 

kurşun düşer üstüne bomba ölüm ayrılık düşer 

apansız sena düşer aklıma beni ağzınla sustur 

göğsü isyan göğsü ateş göğsü tomur tomur 

sena onaltı yaşının heyecanını tarar aynada 

çıplacık boynu... el-boruk dağlarında israil konvoyu 

kıvrılır yılan gibi... nazi fırınlarından sarı yıldız uyanır 

aynada gözlerini bırakır gözleri iki yüz kilo bomba 

içine 504 peugeot''nun büsbütün bir kinle oturur 

kanatlanır avına sena mehdillah şii müslüman kız 

sedir ağaçları değil yanan köyleri geçer iki yanından 

hükmünü okur benim ülkemde filizkıran fırtınası 

dalların acısı gelir hücremde beni bulur 

konvoy patır cizze arasında durur.. sena atmaca 

sena nisan dalları gibisin sena sena 

fünye fitil ateş... sena dur ama durma... 

gövdesinin dört katı ağır bombayla patlar güzelim kız 

beni ağzınla sustur susturacaksan 

7

bu türkü hiç bitmeyecek karanlık sular akıyor içime 

her dizesi bir fırtına belki soluğum yetmeyecek 

korkarım teninden avuçladığım buğu uçup gidecek 

yastığım sımsıkı yastıkta aralanmıyor dudakların 

kış üşümesiyle durma sırtını dönüyor yatağım 

bir yangından çıkmışım tepeden tırnağa yanık 

çekip almışım bir çocuğu çığlığı bende kalmış 

yana yana dost kapılardan yüzgeri olmuşum 

su dökenimi aramışım inatla beni ağzınla sustur 

beni suskunluk kapkara suskunluk öldürecek beni 

sesi türkümün sesi sağanak yağmurları isterim 

dur altına sen de sağalır belki ateşi gövdemin 

duvarla başladı duvarla mı bitecek türküm 

şu dağlar eteği kuşatma tepesi karlı dağlar 

şu okul şu sokak şu ev şu ağaç şu bulvar 

düşünüyorum da sanki bir varmış bir yokmuş 

benim türküm yangın yeri sevgilim sesli konuş 

sesli konuş dışarda kalmasın çiçek yüklü dallarıyla bahar 

balçık gecelerden balçık gecelere çıkıyorum 

ayaydınlık sabahlara bir de sana inanıyorum 

8

benim türküm yangın yeri sevgilim sesli konuş 

söyle ben türkü söylerken sıkı bassınlar yere 

yağmurlu bulutları tepelerinde taşısınlar söyle 

benim gecelerim tepeleme ısırganotu sevgilim 

dur durak yok bana bu bahar akşamlarından 

toprak deniz ve kadın kokularıyla dövüyor da kapımı 

bir karası aşıyor duvarı kahrolası karanlık 

kibriti çakılmış sigarayım nerede dudakların 

barut dumanıyla islenmiş belki kararmış saçların 

çekincesiz yıkanırsın deli çılgın akan sularda 

sular hırçın sular arsız ben ellerimle yapayalnız 

kovalanmışım çocukça düşlerimden taşa tutulmuşum 

balıkları oltada bir deniz gibi ayağa kalkmışım 

delikanlıyım yıldızsız gecelerde düşlerine kıran girmiş 

sensiz kupkuru bir dalım güneşin gözüne batan 

grevsiz işçiyim de ocağı tütmeyen evim 

öğretmenim diline sözcük sözcük yasak vurulmuş 

çocuğum elinde bir balon bulut bir dolu umut 

benekli balonlarım sonra bir varmış bir yokmuş 

benim türküm yangın yeri sevgilim sesli konuş 

9

türkü söylüyoruz tahliyecinin ardından nedense yanık 

yanık birşeyler kokuyor havada ağlamak istiyorum 

ateş hattından çıkmışım beni ağzınla sustur 

tam bir hafta aralıksız dövmüşler barikatı 

kanlı upuzun bırakmışım üç arkadaşımı yorgunum 

yürürken şarapnel parçası düşüyor göğsümden 

çekilen ilk dişimmiş gibi alıp cebime koyuyorum 

daha otuzbir dişim var katıla katıla gülüyorum 

yaranı avuçlarıma ver ateş hattından çıkmışım 

yitiyor nöbetçi kulesi ellerim kopuyor parmaklıktan 

nerede susuzluğun bir yudum su kaldı mataramda 

ağzımda senin dudakların bir varmış bir yokmuş 

duvarın dibinde kurt köpekleri ve bolivyalı çavuş 

guevera''nın sırt çantasında neruda kahkahası 

ve ezbere okuduğun bizim şairlerimiz geliyor aklıma 

salt bizim işimizmiş gibi şaşıp kalmışım 

felâket yakışırmış meğer onlara da ölmek 

çınar dediğin de gün gelir devrilirmiş usulca 

anımsa ne derdik aramızda ona hadi anımsa 

a. kadir amca a. kadir amca a. kadir amca 

10

benim türküm yangın yeri sevgilim sesli konuş 

söyle ben türkü söylerken sıkı bassınlar yere 

yağmurlu bulutları tepelerinde taşısınlar söyle 

ben yokum okulda fabrikada sokakta sen yoksun 

her adımda bir pusu her pusuda bir sevinç asılı 

kapılar kapalı pencerelerin perdeleri aralanmaz 

çocukların oyuntaşı parçalanır camlarda gülmeler açmaz 

ardına kapının süpürgeyle kurum yığar bir kadın 

öğrenciler başka işçiler başka bir başka ülkem 

sen neredesin insan kardeşim nerede neredeyim ben 

hücremin değil evinin duvarında bitiyor voltam 

buz gibi titriyor sırtıyla duvara sırtımı dayasam 

adımlarımı sayıyor bir iki üç... aklı karışıyor 

gün biter mi ay biter mi mevsim yıl biter mi 

duvardan duvara ömür biter mi şaşıp kalıyor 

kapısını açsa kapıma çıkacak ödü kopuyor 

işte bu insan kardeşimin ölümcül korkusu bu işte 

ağır mahkumum düşüyorum bütün uçurumları 

yüreğinin kayalıklarında yeşertemedi henüz bana bir dal 

paramparça parmaklarım korkusunu sıçrıyor uykusunda 

11

insan yaralarım kanadı beni ağzınla sustur 

yaralarım kanamasa gözlerim duvarda kurur 

kör sağır suskunlukları dipsiz düşüyorum 

ayırdına varmadan dibini çekiyorlar uçurumun 

beni dipsizlik kapkara dipsizlik öldürecek beni 

sözüm kurşun hasretim kurşun kurtuluşum 

açsana gülün yaprağını uçsana kanadını kuşun 

sevmesi sevişmek değil gülmesi gülüşmek 

çocuğunun saçlarını okşuyor elleri dalgın elleri uzak 

yasaklarca çalışıp konuşup yaşıyor yasaklarca 

hah desem unutup büyük ellerini kaçacak 

kaçacak ardında madeni sesler bırakarak 

keşif kolları çıkar inadına yasak ateşler yak 

kuşatmalar da kuşatılır bir yerde haber uçur 

alınıp satılabilen bir ülkenin müebbetiyim ben 

türküm duvarla türküm yangınla sürüp gidecek 

gencim delifişek gözlerim bir çift kara tüfek 

bütün umutlar menzilimde belki kızıyorlar sözlerime 

henüz bir avuç insan kardeşimi gördüm fakat 

şaşırmadan ellerini dimdik bakabilirken gözlerime 

12

benim türküm yangın yeri sevgilim sesli konuş 

çoğalmasın yangın sesli konuş güzelim insan 

adın bende gizli gölgen takibinde helikopterin 

her gece koşar gelirsin düşlerimin çekimine kapılıp 

kent dağa kavuşur ellerim ellerini bulunca 

ellerimiz buluşunca düşlerim gece baskınında 

çam ve ardıç kokularını göğsüme bırakıp 

kopar yürürsün ellerimin şehvetine sarınıp 

yürürsün canımın içi kanatlan çarçabuk 

serçe tedirgini adımların ele vermeden seni... 

kaç mahpus yılı düşlerime girip çıktın 

hep bir umudun allığı düşler ki sınırsız 

düşler ki yazdan kışa uçsuz bucaksız 

düşler ki yaşanan yıllara aykırı... 

kurumasın istemem rüzgârda salınmadık hiçbir dal 

minik ellerin yine kabzasında büyüsün silahın 

devrederken nöbeti fakat bir el değmeli eline 

acı bir bulut gibi taşıma saçlarını seni ülkem bildim 

yorulursun arama arama ellerimi ellerimi unut 

katmer güllerin açtığı dağlardadır aşk ve umut 

13

umudum dağlarca yapraklarca umudum halklarca 

fabrikalar gecekondular... duyuyorum tıpırtısını varoşların 

daha fazla dayanamaz bu beton bu demir bu plastik 

kolumu uzatınca elini buluyorum yan hücredeki arkadaşın 

eli sıcak elim sıcak sımsıcak umut yaşamak bu 

yaşamak bu diyorum kesip atıyorum karamsar yerlerimi 

ve gülüyorum gül sen de yüzünde güller açsın 

güney afrikalı zencilerin kavgaları erik çiçekleri kadar ak 

biliyorum nice kavgalar verilmekte bana yakın bana uzak 

hücre hücre direniyorum kuşatılsam da sayrılıklarla 

gün gelecek saçlarımın güz savrulması durmuş olacak 

duvarla boğuşmayacak hiçbir düş hiçbir adım hiçbir ayrılık 

ve hiçbir sözcük şiirde bir silah gibi patlamayacak 

ne müthiş bir duygu içerde umudu kıyasıya yaşamak 

çürütülmek ve öldürülmek olasılığı ağır basarken 

mutlu şarkıları ve zafer tarakalarını beklemek 

evet canım gün gelecek nasıl atılmışsam içeri 

öyle diri ve genç aşacağım yıkılan ilk duvarı 

oğlu kızı yitik bütün kadınları anam bileceğim 

sen diye öpeceğim ağzından karşıma çıkan ilk kızı 

14

karşıma ilk çıkan kızı sen diye öpeceğim ağzından 

boynuna doladığım kollarıma ayaz vuracak belki 

soracağım nerde belinin çukuruna dolan saçların 

susturacaksa o kız da ağzıyla sustursun beni... 

direnmenin güzelliği yüzümüzde kış bahar yaz 

çok değişmedik fakat ellerimiz büyüdü azbiraz 

gökyüzünden çalıp yolla uçurtmaları salkım saçak 

ellerimizde çocuk merakı ellerimiz güzel haberlere aç... 

bana ince uçurumlara bakan kar bahar yüklü patikaları anlat 

ki iz sürücüler tıkanıp kalsın sonlarına bakınca o saat 

köylere inişlerinizi bir de bir de kentlere kaçamak 

yün çorapları önemse dağlarda korkarım ayakların donacak... 

ağlamaklı oluyorum ne güzel düşlerken kuşanmış günleri 

kırılacakmış gibi bütün kapalı kapılar bugün yarın 

bayramlık giysilerimle buluyorum kendimi aynada tıraş olurken 

ranzamda uyur uyanık düş denizi geçiyor üzerimden 

alıp getiriyor kovasını küreğini kumdan kale yapan çocukların 

bulutları yıkıyorum saçlarından gözleri nasıl da umut... 

hep umut edeceğiz sevgilim kopacak her yenilgi sonrası 

sustu sanılan yüreğimizde korkunç bir yaşam fırtınası 

(Ocak-Mayıs 1985)', 'Müebbet Türküsü  1 önce kol sonra sürgü sonra anahtar açılır kapı  itilirim sırtımdan ben ebedi kiracı kesilmiş hükmüm  önce sürgü sonra kol...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Çelik']::text[], 8.5, '{"poet":"Nevzat Çelik","poet_slug":"nevzat-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":296,"source_url":"https://www.antoloji.com/muebbet-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Ümitsiz Aşkım', 'sen-ve-umitsiz-askim-fuat-polat-b8a8d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir bilsen içimdeki ateşi

Bir görebilsen yüreğimin işkencesini

Dokunmak varken uzak kalmak 

Gözlerinin yanında yalnız yaşamak

Sen hep böylesin işte

Ne bana yakın ne bana uzak', 'Bir bilsen içimdeki ateşi Bir görebilsen yüreğimin işkencesini Dokunmak varken uzak kalmak  Gözlerinin yanında yalnız yaşamak Sen hep böyles...', ARRAY['Türk Edebiyatı','Şiir','Fuat Polat']::text[], 8.5, '{"poet":"Fuat Polat","poet_slug":"fuat-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sen-ve-umitsiz-askim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül', 'gonul-birol-ozkan-bz5dd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gel diyor gönül bilmediğim bir yerlere, ama kal diyen bir gönül var içimde.Peki gideceksem neden, 

gideceksem kime? ...diye soruyorum ben de.Biliyorum ki kalacağım ama hep bilinmeyene gitti gönlüm, hep imkansızı 

aradı.Peki şimdi........şimdi kır çiçeklerini hatırlattı.Yanındakini gösterdi, uzağı düşünürken.Peki güller neden hep uzaktaydı ve 

neden onlar seviliyordu? ..Çünkü onlar seviyordu sadece.Ama gördüğünde ömrü kısalıyordu hemen...

Artık seviyorum hemde uzak değil en yakınımdaki kır çiçeğini ama ömrü ne kadar onu bilmiyorum bir de beni......

Evet kalıyorum, gitmek yok diyor gönlüm ve kazanıyor da.......

Kusura bakma gül, artık gülleri de sevmiyorum..çünkü imkansız, çünkü sahte, yalan ve uzaktaki kısa yol.

Benim yolum uzun, ama engelsiz çünkü mavi yol bu.

Kaçamam da artık buralardan, artık ağlayamam da seni düşünürken ve sana birşey veremem, uzaklara da tek başıma 

gidemem artık....

Yemin de edemem çünkü tutamıyorum ve eskisi gibi de sevemiyorum, sana yürekten sevgi de veremem.

Belki yıllar sonra, ama o zaman o kadar çiçeği ve mavileri bırakamam yani bitsin ve zaman geçsin artık.......

Zamanı durdur ve eğer istersen sen gel.........', 'Gel diyor gönül bilmediğim bir yerlere, ama kal diyen bir gönül var içimde.Peki gideceksem neden,  gideceksem kime? ...diye soruyorum ben de...', ARRAY['Türk Edebiyatı','Şiir','Birol Özkan']::text[], 8.5, '{"poet":"Birol Özkan","poet_slug":"birol-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gonul-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efsane', 'efsane-fuat-polat-uu0ga', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıldızlar uzaktan bakarlar, 

Hayatın akış tarzına, 

Güneş ise dinlemekle yetinir, 

Yüreklere fısıldanan şarkılara..

Efsanelere inanır mısın bilmem! 

İnanmak önemli değil aslında, 

Mühim olan efsaneyi yaşamak, 

Az da olsa birşeyler yakalamak. 

Efsanaye göre, 

Yıldızlar sevenleri anlarmış, 

Her zaman yanlarındaymış.

Güneş ise sevgileri yanına alırmış, 

Onların arası soğumasın diye..

Peki Sen Ne Dersin? 

Güneşin yanına varmaya

Yıldızların yanında olmaya! ! !', 'Yıldızlar uzaktan bakarlar,  Hayatın akış tarzına,  Güneş ise dinlemekle yetinir,  Yüreklere fısıldanan şarkılara.. Efsanelere inanır mısın ...', ARRAY['Türk Edebiyatı','Şiir','Fuat Polat']::text[], 8.5, '{"poet":"Fuat Polat","poet_slug":"fuat-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/efsane-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum', 'gidiyorum-fuat-polat-9mu2j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gidiyorum o lanetli gözlerinden,

Kaçıyorum yüreğinde ki sahte sevgiden,

Düşüyorum bir yaprak gibi bedeninden,

Terk ediyorum seni duyuyor musun? 

Bir daha görmemek üzere gidiyorum, 

Bir daha dönmemek için gidiyorum.

Beynimden sileceğim seni bu yüzden,

Yüreğimde de dursan, sileceğim beynimden.

Sana korkular kadar yakınım her an! 

Ulaşamayacağın sevgilerdeyim artık uyan! 

Gidiyorum, yalnız kalacaksın benden sonra,

Sanma ki bulacaksın benim gibisini bir daha! 

Bu son olacak, gidiyorum, ölmekte olsa sonunda! 

Dönmek olmayacak aklımın herhangi bir ucunda,

Sırf sana inat ölecegim bu uğurda..

Gün değmemiş yerler de görsem sensiz,

Kutsal toprak deyip saracağım kollarıma,

Su nedir bilmemiş çöllerde de olsam sensiz,

Dua edip eğleneceğim bulunduğum ortama.

Gülüşün, dönüşüm olamaz hiçbir zaman,

Haykırışın, acıyışım olamaz hiçbir zaman,

Seni gözlerimle sildim, ellerimle dağıttım,

Dudaklarımla ağlattım, yüreğimle kurşun sıktım.

Bir nefeste geçti senle olan anlarım,

Seninle geçen günlerime ağlarım,

Bu anlamsız yokuşta, neden ben vardım? 

Ya da yanında ben nasıl yaşamışım,

Şaşırıp kalırım..

Uyan! Yüreğim, uyan! Oldu artık sabah,

Bu çektigin acılar bitti sona erdi bu sabah,

Yeniden gül hayata, gelecek güzel bahara,

Seni seveni düşün, şimdi sevgiye ağla!', 'Gidiyorum o lanetli gözlerinden, Kaçıyorum yüreğinde ki sahte sevgiden, Düşüyorum bir yaprak gibi bedeninden, Terk ediyorum seni duyuyor mus...', ARRAY['Türk Edebiyatı','Şiir','Fuat Polat']::text[], 8.5, '{"poet":"Fuat Polat","poet_slug":"fuat-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gidiyorum-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal', 'masal-serhan-i-seri-uwkqq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geçmiş bir zamanda, 

Bir ülke varmış düş ülkesi adında.

Dört kişi yaşarmış burada, 

Gözyaşı, neşe, kibir ve para.

Bir de kral ve kraliçeleri varmış, 

Kral  zaman ve kraliçe aşk adında.

Kraliçe aşk zaten ilk görüşte vuruluvermiş, 

Sevgili eşi Kral Zaman` a.

Bir çocukları olmuş, 

Bir kaç sene sonra.

Aşk ona şefkatinden vermiş, 

Zamanda bilgeliğinden.

Ama çocuğun güzelliği, 

Bunlardan değil masumiyetinden.

Prenses büyüyüvermiş, 

Evlenme çağı gelmiş.

Zaman demiş ki Aşk`a; 

Ne dersin karıcığım, 

Yapalım bir yarışma, 

Soralım herkese; 

Ne verebilirsin prensesimize? 

En güzel cevap verene, 

Verelim kızımızı, 

Mutlu olsun o da artık, 

Üzmeyelim yavrumuzu.

Tamam demiş aşk hanım, 

Ama bir şartım var sana, 

Kızımıza da soralım, 

Gitmek ister mi ona? 

Peki demiş zaman bey, 

Anlaştık o zaman, 

Beraberce çıkalım, 

Bu işinde altından.

Ve gün gelivermiş, 

Sınav yapılacak ana, 

Adaylar çıkıvermiş, 

Kralın huzuruna.

Kral zaman soruvermiş, 

Ne verebilirsin kızıma? 

Neşe cevap vermiş, 

Yüzünü güldürürüm ben kızının, 

Daima, daima...

Zaman biraz düşünmüş, 

Neşeye şöyle demiş; 

Buysa tüm vereceğin, 

Bu fıkralarla da olur, 

Fedakarlık olmazsa, 

Aşkın hali ne olur? 

Sıra gelmiş ikinci adaya, 

Kral aslında sıkılmış, 

Ama Kral Zaman bu, 

Sabrın değerini bilmekteymiş.

Kral zaman soruvermiş, 

Ne verebilirsin kızıma? 

Para cevap vermiş; 

Zenginlik adına ne varsa, 

Onun olur benle olursa.

Zaman biraz düşünmüş, 

Paraya şöyle demiş; 

Zenginlik paraylaysa, 

Ferhatlar fakir midir? 

Sen onlara fakir dersen, 

Senin neren zengindir? 

Sıra gelmiş üçüncü adaya, 

Kral kızmış aslında paraya, 

Ama dert etmemiş, 

Yarışmaya devam etmiş.

Kral Zaman soruvermiş; 

Ne verebilirsin kızıma? 

Kibir cevap vermiş; 

Yok benim gibi bir tane daha bu dünya da, 

Kalmadım ben senin kızına.

Kral zaman düşünmüş, 

Kibire şöyle demiş, 

Tarihte çok gördüm ben, 

Senin gibi ukala, 

Yıkıl karşımdan şimdi, 

Kızımı bir daha anma.

Sıra gelmiş son adaya, 

Kral umudunu yitirmek üzereymiş, 

Ama bilgeliği düşüncelerini yenmiş, 

Bunu da deneyelim bari demiş.

Kral Zaman soruvermiş; 

Ne verebilirsin kızıma? 

Gözyaşı cevap vermiş; 

Kralım ben gözyaşıyım, 

Yok fazla şeyim elimde avucumda, 

İnancım ve saflığımdan başka.

Eğer lütfederseniz sonsuza dek  bağlanayım ona, 

Tüm inancım ve saflığımla.

O anda Zamanın gözleri gülüvermiş, 

Gözyaşına seni sevdim delikanlı demiş.

Eğer kızımda beğenirse seni, 

Evlenin en güzeli.

Prensese göstermişler, 

Talibini şatodan, 

Prenses vurulmuş, 

Kalbinin ortasından.

Gözyaşı soruvermiş, 

Eşimin ismi nedir öğrensem? 

Zaman cevap vermiş; 

Prenses sadakat artık senin zevcen.

Prenses gelivermiş, 

Gözyaşının yanına, 

Şu sözleri fısıldamış, 

Gözyaşının kulağına; 

''Zenginlik başkadır ama, 

Sevebilmek bambaşka, 

Aşka düşmek başkadır ama, 

Sadık kalmak bambaşka.''

Gözyaşı bunları duyunca, 

İlk kez gülümsemiş, 

Değerinin anlaşıldığını düşünüp, 

Artık akmayıvermiş.

O an zaman hanımı aşkın gözlerine bakmış, 

Bilgece gülümsemiş, 

Ve şu sözleri söylemiş; 

Başından beri bilirdim ben, 

Bunların bağlılığını, 

Gözyaşsız sadakat, 

Sadakatsiz aşk, 

Aşksız zaman olmayacağını.

Sitemimde bundandır bazen kızınca sana.

Sitemim sana değil, 

Gözünden yaş akmayan şimdiki aşıklara.', 'Geçmiş bir zamanda,  Bir ülke varmış düş ülkesi adında. Dört kişi yaşarmış burada,  Gözyaşı, neşe, kibir ve para. Bir de kral ve kraliçeleri...', ARRAY['Türk Edebiyatı','Şiir','Serhan İşeri']::text[], 8.5, '{"poet":"Serhan İşeri","poet_slug":"serhan-i-seri","theme":"Türk Şiiri","is_hero":false,"total_lines":125,"source_url":"https://www.antoloji.com/masal-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul-2', 'i-stanbul-2-sair-revolver-eg8p1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'beynime doğrultulmuş bir silah buşehir, 

korkardım bir ara patlar diye, 

korkardım yakışıklı birceset olamamaktan

beyni dağilmış bulunmaktan bir buhulu sabah kıyısında

beynime doğrultulmuş bir silah bu şehir, 

onunla yaşamaya alışmaya başladım artık

korkmuyorum artık cesedim yakışıklı olmaz diye

tek korkum kimsenin beni bulmaması sadece...

beynime dayadığım bir silah artık bu şehir, 

kabzasından tutan benim 

gücü tükenen benim

damarlarımdan akan kan değil artık, irinden bir nehir...', 'beynime doğrultulmuş bir silah buşehir,  korkardım bir ara patlar diye,  korkardım yakışıklı birceset olamamaktan beyni dağilmış bulunmaktan...', ARRAY['Türk Edebiyatı','Şiir','Şair Revolver']::text[], 8.5, '{"poet":"Şair Revolver","poet_slug":"sair-revolver","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/istanbul-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Kavuşacakmıyım', 'sana-kavusacakmiyim-salih-ozalasan-81xii', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yıl daha geçti ben yine sensiz

Hasretinle kahroluyorum akşamları

Yine özlemle kapanacak çaresiz

Yeni yıla sitemle başlayacak gönül sayfaları

Ha bugün ha yarın derken geçiverdi

Bu kadar kısamıydı bu ikibiniki

Sana kavuşacağım gün gelmeden bitiverdi

Ömrümden bir sayfa sensiz kapanıverdi

Şimdi ben yenisinde de ağlayacakmıyım

Sensizliğe kahrolup ağıtlar yakacakmıyım

Yine hasretinle buram buram yüreğim

Gözyaşımla şiirler yazacakmıyım 

Yine yıldızlardan fal tutacakmıyım

Yoksa kırdığım kadehleri elime alıp

Bıraktığım yerden yine başlayacakmıyım

Allah''ım ben sevdiğime kavuşacakmıyım

(Y.Tar 30-12-2002 Saat 23,17)', 'Bir yıl daha geçti ben yine sensiz Hasretinle kahroluyorum akşamları Yine özlemle kapanacak çaresiz Yeni yıla sitemle başlayacak gönül sayfa...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sana-kavusacakmiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudum Var', 'umudum-var-melih-coskun-xnprj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Umudum var yarına dair

Çünkü biliyorum ki güneş yarında doğacak, 

Bir çocuk doğacak yarın, 

Yine insanlar işe gidecekler yarınları için, 

Umutları için, 

Ve yine birileri ölecek umutlarıyla...

4 Mayıs 2002

00: 12', 'Umudum var yarına dair Çünkü biliyorum ki güneş yarında doğacak,  Bir çocuk doğacak yarın,  Yine insanlar işe gidecekler yarınları için,  Um...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/umudum-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyümek', 'buyumek-melih-coskun-135is', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Büyümek ne zor şeymiş

Her duyguyu iki kez yaşamakmış büyümek

Öfkeyi iki kez 

Sevinci iki kez

Sevgiyi iki kez yaşamakmış büyümek.

Fark etmek olanı biteni dünyada

Atmak kendini kirletilmiş sokaklarına şehrinin

Yürümek, yürümek, yürümekmiş... 

Kurtlar sofrasına düşmekmiş büyümek.

Büyümek; 

Kirletilmesi en temiz çocuksu duygularının

Ve anlamakmış kısaldığını sevgiye ayrılan zamanının

Ve büyümek; kanına dokunması artık yapılan kalleşliklerin

Bir insanın gözlerinin içine bakarak ağlayabilmek

Gülebilmekmiş insanlar gülebildiklerinde.

Ve fark etmek yüzüne her gülenin dostun olmadığını

Büyümek; 

Boşver gitsin diyememekmiş olan bitene.

Büyümek; 

Kaybetmek teker teker değer verdiğin ne varsa 

Daha iyi anlayabilmek ölümün kalleşliğini

Şaşırmak ne kadar çabuk geçtiğine yılların

Ve pişman olmakmış büyümek 

Boşa geçirilmiş günler için...

(Büyüdük bugün

Ancak hala yaşıyoruz

Boşa geçirdiğimiz günlerde olsa

Daha yol var gidilecek

Zaman var hala sevdalanmak için)

18 Eylül 2002

 21: 45', 'Büyümek ne zor şeymiş Her duyguyu iki kez yaşamakmış büyümek Öfkeyi iki kez  Sevinci iki kez Sevgiyi iki kez yaşamakmış büyümek. Fark etmek ...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/buyumek-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi Koru Yüreğini', 'i-yi-koru-yuregini-melih-coskun-uxgw8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dostum iyi koru yüreğini

Nesli tükenmekte olan bir kuştur yüreğin

Bir çocuk saflığındadır.

İyiye, doğruya, güzele hazır kendini fedaya.

Bir volkandır patlamaya hazır

Zulme, haksızlığa karşı 

Bir tarafı coşkun bir nehir

Akar insanlığa doğru

Bir tarafı durgun bir deniz

Ve onurludur yalnız kalacak kadar

Kendini yalnız bırakanlar için çarpar 

Bir ırgatın alın teridir

Bir bebeğin ağlayışıdır.

Bir kar tanesidir temiz ve yumuşak

Parçalara böler kendini insanlık adına

Dağlara verir bir parçasını

Denizdedir bir parçası

Bir parçası özgürce dolaşan bir bulut

Yağmur olur bulutla yağar yeryüzüne

Yağar sokaktaki insanların üzerine

Güzelliğini yaymak adına dünyaya...   

16 Haziran 2002

23: 41', 'Dostum iyi koru yüreğini Nesli tükenmekte olan bir kuştur yüreğin Bir çocuk saflığındadır. İyiye, doğruya, güzele hazır kendini fedaya. Bir ...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/iyi-koru-yuregini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saf Yüreğim', 'saf-yuregim-melih-coskun-2kjp1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saf yüreğim

Kaldıramıyorsun artık şu yalancı dünyanın yükünü

Ağır geliyor sana 

Bu kemirici kurtlar arasında

Bir elma kadar saf ve temiz olmak, 

Şuranda bir sızı içten kemirmekteyse seni

Dostun sıcacık gülücüğü yerine 

Hançerini göstermişse sana

Kederden gebermekteysen 

Ve yine de inadına gülebiliyorsan 

İnsanlara dostça, 

Bu yaşadığımız dünya senin değil demektir

Tertemiz yüreğin daha ne kadar kaldırır bu yükü

Ve sen bu yürekle iflah olmazsın kardeşim...

28 Haziran 2002

00: 02', 'Saf yüreğim Kaldıramıyorsun artık şu yalancı dünyanın yükünü Ağır geliyor sana  Bu kemirici kurtlar arasında Bir elma kadar saf ve temiz olm...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/saf-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanı Onları', 'tani-onlari-melih-coskun-8hxss', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şu havada kafanın üzerinde 

Sürekli durmadan dönüp duran 

Leş kuşlarını gördün mü

İşte onlar, ta kendileri

Senin bir an önce düşmeni bekleyen kuşlar

İyi bak onlara 

İşte onlar dost sandıkların bir zamanlar

İşte onlar paylaştığın her şeyini bir zamanlar

Ve şimdi onlardır

Ellerinde bir bıçakla 

Arkandan yaklaşmakta olan senin

Ve şunu anla ki bugün

Senin en iyi dostun 

Türküler, şiirler ve sensin... 

08 Eylül 2002

13: 52', 'Şu havada kafanın üzerinde  Sürekli durmadan dönüp duran  Leş kuşlarını gördün mü İşte onlar, ta kendileri Senin bir an önce düşmeni bekleye...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tani-onlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkü Söyleyin Bana', 'turku-soyleyin-bana-melih-coskun-nhy3z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bugün türkü söyleyin bana

En güzel türkülerinizi söyleyin

Sabahlara kadar türkü dinlemek istiyorum

Bir gece 

Uykudayken  şehir 

En umulmaz bir vakitte

Başımı koyup bir omuza

İki damla gözyaşı dökmek istiyorum

Bugün şiir okuyun bana

En güzel şiirlerinizi okuyun

Bu gece beynime 

Kirletilmemiş bir dünya sığdırmak istiyorum

Geceyi doldurmak istiyorum odama

En güzel şiirlerinizi okuyun bana

Ben bugün yaşamak istiyorum...

6 Eylül 2002

23: 20', 'Bugün türkü söyleyin bana En güzel türkülerinizi söyleyin Sabahlara kadar türkü dinlemek istiyorum Bir gece  Uykudayken  şehir  En umulmaz b...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/turku-soyleyin-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görmüyor musun', 'gormuyor-musun-melih-coskun-8apvp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Görmüyor musun

Daha tükenmemiş paylaşabileceklerimiz

Hepimize yetecek bir gökyüzü var tepemizde

En büyük tesellidir bel ki de insana

Sevdiğiyle aynı havayı soluduğunu düşünmek  bazen 

Günaydın derken

Hissetmek aydınlık bir günü paylaştığını

Aynı yıldızları saymak

Aynı yolları yürümek

Yemek, içmek, gülmek, ağlamak

Aynı otobüse binmek

Maaş günlerini beklemek

Geleceği düşünmek 

Ve ölümü 

Ürpermek kimi zaman

Kimi zaman korkmak karanlıktan

Kimi zaman ağlamak yitirilenin ardından

Ve en büyük mutluluktur anlayabilene

En büyük ortak noktamızı: 

Hayatı...

30 Eylül 2002

23: 50', 'Görmüyor musun Daha tükenmemiş paylaşabileceklerimiz Hepimize yetecek bir gökyüzü var tepemizde En büyük tesellidir bel ki de insana Sevdiği...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gormuyor-musun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Hep Sekiz Yaşında Olacağım', 'ben-hep-sekiz-yasinda-olacagim-melih-coskun-szpq3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bana ölümü anlat anne

Daha çok küçüğüm 

Beceremem ki ölmeyi

Daha sekiz yaşında bir kız çocuğuyum ben                 

Bilmiyorum ölümü

Hayatı bilmediğim gibi henüz

Bana göremeyeceğim mutlu günlerimi anlat

İlk aşkımı anlat bana

İlk öpücüğü yanağımdaki.

Nasıl olacaktı gelinliğim

Çocuklarımı anlat bana

Hiçbir zaman göremeyeceğim 

En kıymetli varlıklarımı anlat.

Söyle bana anne

Hangi çocuklar oynayacak artık

O en çok sevdiğim bebeğimle

Artık kimse kutlamayacak mı doğum günlerimi

İyi ki doğdun yazmayacak mı artık 

O çok sevdiğim çikolatalı pastanın üzerinde

Bana, bensiz günlerini anlat anne

Nasıl kaldırır bu yükü bir ana yüreği

Üzülme anne

Göz yaşların acıtır yüreğimi

Ben her akşam sen uyurken rüyalarında

Sana sarılıyor olacağım...

Sende sıkıca sarıl bana 

Senin sıcaklığına ihtiyacım var...

7 Eylül 2002

00: 02', 'Bana ölümü anlat anne Daha çok küçüğüm  Beceremem ki ölmeyi Daha sekiz yaşında bir kız çocuğuyum ben                  Bilmiyorum ölümü Hayat...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ben-hep-sekiz-yasinda-olacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Her Akşam', 'ben-her-aksam-melih-coskun-36vf3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben her akşam 

Hayal kırıklıkları biriktiririm 

Odamdaki o kara kaplı defterde

Her hüzün bir mutluluğu götürür

Benim test kitaplarımda

Ama kızmam hayata

Memnun olurum yaşadığıma

Çünkü bilirim ki birazda hüzünlerdir

Adam eden adamı

Ve kansız bir düşünce inkılabıdır 

Şair eden adamı...

31.08.02', 'Ben her akşam  Hayal kırıklıkları biriktiririm  Odamdaki o kara kaplı defterde Her hüzün bir mutluluğu götürür Benim test kitaplarımda Ama k...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-her-aksam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Bir Otogar Gecesi', 'yine-bir-otogar-gecesi-melih-coskun-b1jl0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine bir otogar gecesi

Herkes içindeki hiç kimseler

Bir an büyük bir kalabalık

Sonrası sessizlik

Göçtü sanırsın bütün insanlar

Sanki boşaldı bir anda yeryüzü

Nerede gitti bunca insan

Yoksa hiç kimseler yok muydu zaten orada

Sınıflara ayrılır bir anda insanoğlu

Siyah, beyaz, sarı değil, 

Burjuva, işçi değil, 

Ezilenler ve ezenler değil, 

Sadece

Gidenler ve kalanlar.

Bekliyorum 

Bir gün otobüs camında gizlice ağlayan çocuk

Büyür diye bir gün

Hey çocuk, söyle bana

Hasret miydi adın senin

Döner misin bir daha geriye

Gittiğin yerden

Böyle mi sürüp gidecek hayatımız

Hep gidenler, gelenler, kalanlar...

Sonrası hiç...

6 Ekim 2002

22: 52', 'Yine bir otogar gecesi Herkes içindeki hiç kimseler Bir an büyük bir kalabalık Sonrası sessizlik Göçtü sanırsın bütün insanlar Sanki boşaldı...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yine-bir-otogar-gecesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ertelenir mi Ölüm', 'ertelenir-mi-olum-melih-coskun-y0od2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayat hep böyle mi akıp gidecek

Erteleyerek sürekli güzellikleri

Yarını yaşamaktan 

Kahrettik günümüzü

Son çeyreğe sığar mı yaşamadıklarımız

Dostlar söyleyin bana 

Ertelenir mi ölüm? 

Dün acı çekiyordun bugünün için

Bugün yine acı çekiyorsun 

Yaşanmamış günlerin için

Yarın da acı çekeceksin 

Boşa geçirdiğin günlerin için

Şunu bil ki

Hayat uzun değil 

Tüm ertelediklerini yaşayacak kadar

Hayat kısa 

Günlerini kahredemeyeceğin kadar...

10 Ekim 2002

22: 43', 'Hayat hep böyle mi akıp gidecek Erteleyerek sürekli güzellikleri Yarını yaşamaktan  Kahrettik günümüzü Son çeyreğe sığar mı yaşamadıklarımız...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ertelenir-mi-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hangisi Sıla', 'hangisi-sila-melih-coskun-anjyn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hangisi sıla 

Söyle bana 

Ey doğduğum koca şehir

Doğduğum yer midir sıla 

Yoksa  seveceğim yer mi olacak

Bir şehir nasıl güzelleşir bir günde

Bir şehrin dağları nasıl yeşerir 

Gurbet nasıl sıla olur

Bir adam nasıl bırakıp gider

Herkesi ve her şeyi arkasında

Uzun bir yolculuk romanıdır artık hayatımız

Kim bilir hangi meçhul şehirde bitecek bu roman...

14 Ekim 2002

23: 12', 'Hangisi sıla  Söyle bana  Ey doğduğum koca şehir Doğduğum yer midir sıla  Yoksa  seveceğim yer mi olacak Bir şehir nasıl güzelleşir bir günd...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hangisi-sila-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birtanem', 'birtanem-i-brahim-cagri-saglik-ne8rc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzun süren aramamda

Aradığımı buldum, seni

Evet seni buldum ve bil ki

Seni çok seviyorum birtanem

Yıllar boyunca beklediğim

Hayalimsin gerçek olan

Ve sonsuza kadar bekleyip

Seveceğimsin birtanem

Terkedip uzaklara gitsen

Dönmeyeceğini dahi bilsem

Göz açıp gördüğüm, sen

Gönül verdiğimsin birtanem

	

30 Aralık 2002', 'Uzun süren aramamda Aradığımı buldum, seni Evet seni buldum ve bil ki Seni çok seviyorum birtanem Yıllar boyunca beklediğim Hayalimsin gerçe...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Çağrı Sağlık']::text[], 8.5, '{"poet":"İbrahim Çağrı Sağlık","poet_slug":"i-brahim-cagri-saglik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/birtanem-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canıma', 'canima-i-brahim-cagri-saglik-rst3x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karanlık gökyüzünde ışık gibisin

Aşık olan bülbülün gülü gibisin

Kalbimin içinde taht kurmuş gibisin

Uğruna gönül verdiğim sevgilimsin

Sevgi bende bir hayalken ümit oldu

Toprağım çorak iken güllerle doldu

Mutluluk dallarıma bülbüller kondu

Yoluna yürek koyduğum sevgilimsin

Dünyamın varlığı, anlamı sensin

Bu kıraç toprak sensiz nasıl yeşersin

Gülüşün essin baharım neşelensin

Yanında sevda olduğum sevgilimsin

 19 – ARALIK - 2002', 'Karanlık gökyüzünde ışık gibisin Aşık olan bülbülün gülü gibisin Kalbimin içinde taht kurmuş gibisin Uğruna gönül verdiğim sevgilimsin Sevgi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Çağrı Sağlık']::text[], 8.5, '{"poet":"İbrahim Çağrı Sağlık","poet_slug":"i-brahim-cagri-saglik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/canima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Gönül', 'deli-gonul-i-brahim-cagri-saglik-paexx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hava soğuk, elimde sigara

Oturdum yine, yazmaktayım

Deli demeye dilim varmıyor ama

Uslanmadı gitti, şu benim gönlüm

Savaşta barışı ister dururum

Barışı bulunca kavga sorarım

Sevgiden yana bir dost ararım

Uslanmadı gitti, şu benim gönlüm

Keramet ne bende ne başkasında

İki cümle birlikte söz tartısında

Dilim dolanmakta, kafam karışmakda 

Uslanmadı gitti, şu benim gönlüm

Bir hata eyledim cevabı buldum

Kulaktan kulağa çok laflar duydum

Bin kez yemin ettim binbir kez bozdum

Uslanmadı gitti, şu benim gönlüm

Eloğlu çok yaman bakmaz halime

Karabasan misali çöker üstüme

Ben laf geçiremedim kendi gönlüme

Uslanmadı gitti, şu benim gönlüm

Özüm sözüm birdi bu hale düştüm

Sözümden dönünce özüme küstüm

Herdem isyan ettim kendimi üzdüm

Uslanmadı gitti, şu benim gönlüm

Çağrı bak gördün mü halin harap

Senin derdin yüzünden yıllandı şarap

Uygun değilki sana edilen hitap

Uslanmadı gitti, şu benim gönlüm

10-11-1995', 'Hava soğuk, elimde sigara Oturdum yine, yazmaktayım Deli demeye dilim varmıyor ama Uslanmadı gitti, şu benim gönlüm Savaşta barışı ister dur...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Çağrı Sağlık']::text[], 8.5, '{"poet":"İbrahim Çağrı Sağlık","poet_slug":"i-brahim-cagri-saglik","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/deli-gonul-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer', 'eger-i-brahim-cagri-saglik-109tp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir kor olup yapışsaydım eline

Beni bu kadar kolay bırakır mıydın? 

Kumsalda dolaşırken yalnız başıma

Sinirden ruhuma dolabilir miydin? 

Taş atıp sektirseydim aşk denizine

Bana bu kadar çok kızabilir miydin? 

Aşkımı kazısaydım göktaşlarına 

Benden bu kadar çabuk kopar mıydın? 

Veyahut dilenseydim merhamet senden 

Bana bu kadar kolay kıyar mıydın? 

Mayıs 2002', 'Bir kor olup yapışsaydım eline Beni bu kadar kolay bırakır mıydın?  Kumsalda dolaşırken yalnız başıma Sinirden ruhuma dolabilir miydin?  Taş...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Çağrı Sağlık']::text[], 8.5, '{"poet":"İbrahim Çağrı Sağlık","poet_slug":"i-brahim-cagri-saglik","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/eger-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fotoğraf', 'fotograf-i-brahim-cagri-saglik-cwkqv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Odamda yalnızım yine bu gece

Hüzünlü bir müzik kulaklarımda

Eski albümleri karıştırıyorum

Derin bir nostaljideyim fotoğraflarda

Uzun süreden sonra elimde bir resim

Gözlerim takılıyor gözlerine

Mutluluk okunuyor içlerinde

Gülücük saçıyor dudakları

Düşünüyorum acaba kim bu

Bu kadar mutulu bu dünyada

Habersiz bunca acıdan, nefretten

Saf kalmış kalbi bu tuzaklarda

Ve birden yıkılıyorum resme karşı

Kim diye düşündüğümün 

Kendim olduğunu anlayınca 

Farkediyorum yılların götürdüklerini

Giden dostlar, arkadaşlar

Biten umutlar, sevgiler

Ve bütün bu nostaljilerle

Odamda yalnızım yine bu gece

9-Ocak-1993', 'Odamda yalnızım yine bu gece Hüzünlü bir müzik kulaklarımda Eski albümleri karıştırıyorum Derin bir nostaljideyim fotoğraflarda Uzun süreden...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Çağrı Sağlık']::text[], 8.5, '{"poet":"İbrahim Çağrı Sağlık","poet_slug":"i-brahim-cagri-saglik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/fotograf-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Sevgiliye', 'kayip-sevgiliye-i-brahim-cagri-saglik-fvwcs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hata bende mi bilemiyorum.

Ama hala bulamadım seni güzelim

Boynum öne eğik bomboş sokaklarda

Kimselere soramadım seni güzelim

Hayallerimi süslüyorsun her akşam

Seni görüyorum her bardağın sonunda

Başımı ne yana çevirip baksam 

Başka birisi var senin yanında

Birgün gelecek, bulacağım seni elbet

İşte o zaman sımsıkı sarılacağım

Deli gönlüm sende biraz daha sabret

Sevdiğim seni mutlak bulacağım

Aralık 1992', 'Hata bende mi bilemiyorum. Ama hala bulamadım seni güzelim Boynum öne eğik bomboş sokaklarda Kimselere soramadım seni güzelim Hayallerimi sü...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Çağrı Sağlık']::text[], 8.5, '{"poet":"İbrahim Çağrı Sağlık","poet_slug":"i-brahim-cagri-saglik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kayip-sevgiliye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyimize Karanlık', 'neyimize-karanlik-i-brahim-cagri-saglik-4xf9c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne karanlık, göz kapatmaya gerek yok

Yalanlar bile apaçık ortada

Heyhat belki ilk defa böyleyken

Karanlıkta onları sezen bile yok

Alemin her kesmine ayrı bir telaş 

Benimse içime korku peydahladı

Sebepsiz yere zaman harcayıp

Bakma göremezsin zaten arkadaş

Ne halim var ne de takatim kaldı 

Dostumu düşmanımı ayırt etmeye

Bakma yalandandır ayakta oluşum

Bize ölmezden evvel ağlamak kaldı

Kalbimiz durdu, durmak üzere

Sevgimiz tabutta, gömülmek üzere

Geride yaşlı gözler, kurumak üzere

Çağrı’ya son duayı okumak kaldı.

29 Haziran 1999', 'Ne karanlık, göz kapatmaya gerek yok Yalanlar bile apaçık ortada Heyhat belki ilk defa böyleyken Karanlıkta onları sezen bile yok Alemin her...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Çağrı Sağlık']::text[], 8.5, '{"poet":"İbrahim Çağrı Sağlık","poet_slug":"i-brahim-cagri-saglik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/neyimize-karanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Ağıt', 'sevgiliye-agit-i-brahim-cagri-saglik-kc8y3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Maziyi aradım içimde bu gece

Gönül dehlizimin karanlıklarında

Adın dilimden hiç eksilmeyen hece

Bir ışık bakındım hüzün tufanında

Acaba kimlerin unutulmuş ismi

Gözlerimden akan hep acılı günler

Masamda o en mesut anların resmi

Geçmişten bugüne yorgun düşünceler

Bir ağıt kopuyor hergün derinlerden

Veda eder yaşlarım göz pınarına

En güzeli bu olmalı sevgilerden 

Sessizce giderken yarin diyarına

Her esen rüzgarda seni hatırlarım

Sensiz bomboş kalan küçücük dünyamda

Hala gülüşünü duyar kulaklarım

Aşkımız akan kanım damarlarımda

17 - Mayıs - 2002', 'Maziyi aradım içimde bu gece Gönül dehlizimin karanlıklarında Adın dilimden hiç eksilmeyen hece Bir ışık bakındım hüzün tufanında Acaba kiml...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Çağrı Sağlık']::text[], 8.5, '{"poet":"İbrahim Çağrı Sağlık","poet_slug":"i-brahim-cagri-saglik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevgiliye-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Getirdim', 'sana-getirdim-i-brahim-cagri-saglik-fmj7n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ölümün başedilmez pençesinden

Dağların ötesinden yer dibinden

Karanlık korkunç gölgelerin içinden

Bir tutam çiçek getirdim sana

Gökyüzü mavisi gözlerinde

Okyanus esintisi sözlerinde

Aldın götürdün kalbimi ellerinde

Sen dolu bir kalp getirdim sana

Yürünmez yolların ötesinden

Varılmaz noktaların gerisinden

Denizin derinliklerinden her yerden

Yeşeren tomurcuk getirdim sana

1997', 'Ölümün başedilmez pençesinden Dağların ötesinden yer dibinden Karanlık korkunç gölgelerin içinden Bir tutam çiçek getirdim sana Gökyüzü mavi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Çağrı Sağlık']::text[], 8.5, '{"poet":"İbrahim Çağrı Sağlık","poet_slug":"i-brahim-cagri-saglik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sana-getirdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Metin''e Dair Şiir Şiire Dair Metin', 'metin-e-dair-siir-siire-dair-metin-emre-citlak-je71g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'acım benim ilacım

ilacım sensin hacım

gidiyoz denizlere amcam

gidiyoz her yan kürek

dayanmaz amcam yürek

dayanmayı bilmek gerek

yürüyoz hacım

yürüyoz da nerelere gidiyoz sanki

kalıyoz hacım

kalıyoz bok gibi

yaşıyoz da hacım

artıyor acım

artıyor acılardaki hacim 

yoğunluk artıyor

kütle artmayacak mı sanıyosun

yanılıyorsun hacım

çok yakın değil ölüm

top yekün değil

azalıyor mu acın daha az sevince

ya da kabarıyor mu sevmeyi bilince

biliyoz hacım biliyoz

yaşamasını da ölmesini de

adımız gibi

adımızı sınıyoz yangın yerlerinde

ölümlere gidiyoz

sevmelerle geliyoz

geliyoz da hacım

nereye kadar

ne kadar daha genciz

ve daha

nasıl yaşlanmasın yürek

samatya''da sahildeyiz

boyatacak ayakkabımız yok

paylaşmayı biliyoruz sunduğumuz kadar

ya sonrası hacım

sonrası nereye kadar? ...

hiç bir şey bilmemek marifet mi

yaşıyoz yaşıyoz da hacım

büyüyor acılardaki hacim

gidip top oynuyoruz dostlarla

gidip hiç bir şey olmamış gibi

sevmeyi sınıyoruz paylaşırken

bir gol geliyor peşine

daha da mutluyuz şimdi

maçı da aldık ama

kaç maç verdik? ...

allahının aşkına

kaç maç acılara...', 'acım benim ilacım ilacım sensin hacım gidiyoz denizlere amcam gidiyoz her yan kürek dayanmaz amcam yürek dayanmayı bilmek gerek yürüyoz hacı...', ARRAY['Türk Edebiyatı','Şiir','Emre Çıtlak']::text[], 8.5, '{"poet":"Emre Çıtlak","poet_slug":"emre-citlak","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/metin-e-dair-siir-siire-dair-metin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Masalı Bir Laz Yazdı Diye Vazgeçecek Kurbağa Değilim Ben', 'bir-masali-bir-laz-yazdi-diye-vazgececek-kurbaga-degilim-ben-emre-citlak-qjxfk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'saat dört olmuş

kurbağa hala bekliyor prens olmayı

oysa herkes bilir

arabalar onikiye kadar

sonrası balkabağı

prensesler hizmetçi...

bu gerçek her zaman gerçekten uzun', 'saat dört olmuş kurbağa hala bekliyor prens olmayı oysa herkes bilir arabalar onikiye kadar sonrası balkabağı prensesler hizmetçi... bu gerç...', ARRAY['Türk Edebiyatı','Şiir','Emre Çıtlak']::text[], 8.5, '{"poet":"Emre Çıtlak","poet_slug":"emre-citlak","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bir-masali-bir-laz-yazdi-diye-vazgececek-kurbaga-degilim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yenı Yıl Kırmızısı', 'yeni-yil-kirmizisi-erol-sen-3ae93', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevdanın yıldönümü bugün

Biten bir kırmızı sevdaya yenisi geliyor

365 gün sevdalanacak gönül

Belki bir çiçeğe, belki bir güzel güne

Belki de baharın aldatısına

Belki de yazın kısa aşklarına

Yeni şarkılar yazılacak umutla

Sevdanın kolları hep açık olacak

Belki bir arabaya sevdalanacak şaşkın gönüller

Belki su perisi güzelliğinde bir kadına

Belki de denizin mavi yeşiline

Belki de küçük bir derenin kahve pembesine

Sevmeyi bilen gönüllere sevdalar akarken

Çıkarsız aşkın büyüsüyle

Kör eden kırmızı güllere

Bülbül şakıyacak umarsızca....

31.12.2002', 'Sevdanın yıldönümü bugün Biten bir kırmızı sevdaya yenisi geliyor 365 gün sevdalanacak gönül Belki bir çiçeğe, belki bir güzel güne Belki de...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yeni-yil-kirmizisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Yıl', 'yeni-yil-hakki-hakan-kaya-38xwa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşanan tüm acıları bi yana, 

Bırakıp koyan yeni yıl.

Geçmiş günahları bi anda, 

Arıtıp soyan yeni yıl.

Yılboyu kalmışın aç, 

Üç kuruşa olmuşun muhtaç, 

Takmazsın artık kafana hiç, 

Çünkü gelen yeniyıl.

Bu yıl senin yılın olacaktı, 

İş esirin, para kölen olacaktı, 

Bilemezdin hayallerin solacaktı, 

Umutları sömüren yeniyıl.', 'Yaşanan tüm acıları bi yana,  Bırakıp koyan yeni yıl. Geçmiş günahları bi anda,  Arıtıp soyan yeni yıl. Yılboyu kalmışın aç,  Üç kuruşa olmu...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yeni-yil-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Yıla Girerken', 'yeni-yila-girerken-i-brahim-cagri-saglik-jochx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İstanbul''da bugün bir bahar havası

Kulaklarımda eski hüzün şarkısı

Sokaklarda yeni yıl koşturmacası

Bunca varlar içinde birtek sen yoksun

Yüreğim kayıplarda hissiz ve donuk

Yılların hediyesidir bu yorgunluk

Sensizlik, varlık içinde ki yokluk

Bunca zorluk içinde sen tek coşkusun

Aklım, hanesinden çok çok uzaklarda

Gereksiz, günlük, fani hesaplarda

Yaşam savaşı denen bu pusularda

İçime dolabilen sen tek duygusun

Bu gece bedenen ayrı olsak bile

Eski yıla buruk nokta koysak bile

Yaşanacak günlerin aşkıyla, dile

Yeni yıllar bizim aşkımızla dolsun

31-12-2002', 'İstanbul''da bugün bir bahar havası Kulaklarımda eski hüzün şarkısı Sokaklarda yeni yıl koşturmacası Bunca varlar içinde birtek sen yoksun Yü...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Çağrı Sağlık']::text[], 8.5, '{"poet":"İbrahim Çağrı Sağlık","poet_slug":"i-brahim-cagri-saglik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yeni-yila-girerken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Coşan Gül', 'cosan-gul-cahit-i-pekoglu-1p3bt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gül kokulum

bana senin sevdan yeter, yeter''ya.

Kokun yüreğime sinmiş

kokunu hissedemediği  zaman ölüyor, ölüyor''ya.

Zannetme gül kokulum

elli dal dolaşır yüreğim.

Seni arar yaban, dalarda bulamaz

başka hiçbir gülle, ruhu doymaz...

Nereden seçtim

mesleğim olmasada gönül yazmacılığını bilemem.

Seninle kazandığım deneyimim olsaydı

koku uzmanı olurdum, gül kokulum.

Kokun ve sevdanı, harç eder

COŞAN GÜL, parfümünü imal ederdim.

Gül kokulum

bana senin sevdan yeter, yeter''ya.

Kokun yüreğime sinmiş, sakın silme''yaaaa...

Gül kokulum

bak yine burnumdasın, buram buram.

Benimle olanlar,  üzerime sinmiş kokunu

hissediyorlar.

Gül kokulum

bana senin sevdan yeter, yeter''ya.

Kokun yüreğime sinmiş, sakın silme''yaaaa...



Son derece alımlı bir kadın, her zaman kendi ayakları üzerinde durmayı başarmış başarılı bir iş kadını, kimseye boyun eğmeyen güçlü bir karakter olan Suna Hanım’ın bir hastalığa yenik düşmesi ve günden güne vücudunun eriyerek ölüme doğru ilerleyişi beni en çok etkileyen bölüm oldu.. 

Kitabın başından beri son derece güçlü bir karakter olan Suna’nın da zayıf yönlerinin olduğunun ve ölüme doğru giderken hayatını sorgulaması, şimdiye kadar hayatında yer vermediği duyguları, korkuları yaşamaya başlaması, özellikle de ölüm korkusu çok güzel', 'Gül kokulum bana senin sevdan yeter, yeter''ya. Kokun yüreğime sinmiş kokunu hissedemediği  zaman ölüyor, ölüyor''ya. Zannetme gül kokulum ell...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/cosan-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadakat', 'sadakat-cahit-i-pekoglu-wab9v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sadakat nedir bilmeyen yüreğim

bak seninle nasılda değişti.

Sadakata boyun eyersem eğer

sevdiğimi anlar, sevdiğimi haykırırım.

Ben seni seviyorum gülüm...

Nasıl bir aştır bu

yüreğim tutmuyor ayar.

Ruhumu terkeden ruhun olsada

yüreğime söz geçmiyor gülüm.

İçimdeki sevgin, öylesine büyük''ki

ruhun beni sadakata sürüklüyor.

Sadakata boyun eydim

sadece seni, seninle aldatırım gülüm...', 'Sadakat nedir bilmeyen yüreğim bak seninle nasılda değişti. Sadakata boyun eyersem eğer sevdiğimi anlar, sevdiğimi haykırırım. Ben seni sevi...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sadakat-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Neyinim', 'senin-neyinim-cahit-i-pekoglu-9507u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben, senin hangi yarınım 

eksik olan yarın''mı. 

Fazla gelen yanin''mı 

ya da karanlık yarının''mı. 

Ben, senin günah yanınmıyım 

yoksa senin günahkârın mı... 

Senin olmayanın mıyım 

senin kalmayacak olanın''mı... 

Ben, senin ağlayanınmıyım 

senin göz yaşların''mı. 

Senin hayallerin miyim 

senin gerçekleşmeyecek düşlerin''mi. 

Ben, senin düşüşlerin miyim 

senin tuzağa düşen yanın''mı... 

Senin uzağında mıyım 

senin uzaklaşan yanında''mı... 

Ben, senin unutacağınmıyım 

senin yalan rüyan''mı. 

Senin tutsağınmıyım 

senin esir olan yanin''mı. 

Ben, senin neyinim 

senin neyim, neyim... 

Senin sevdanmıyım 

senin sevda masalın''mı...', 'Ben, senin hangi yarınım  eksik olan yarın''mı.  Fazla gelen yanin''mı  ya da karanlık yarının''mı.  Ben, senin günah yanınmıyım  yoksa senin g...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/senin-neyinim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme Gitme', 'gitme-gitme-cahit-i-pekoglu-nlpx9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Fırtınalı, bir gece gibi esme 

bu son kez, mi bakışınn gözlerime. 

Bu son sözlerin''mi 

yüreğimde yol alırken, silemem izlerini yıllarca. 

Gitme seni özlerim gitme

gitme, gitme... 

İliklerime işliyerek eserken 

keskinliğin çaresizliğim oluyor. 

Gitme sabahlarım güneşsiz kalırken 

acılar bedenimi ezer yoğurur. 

Dayanmaz yüreğim korkuları büyütür 

uğruna ölecek kadar sevdiğimsin gitme. 

Gitme seni özlerim gitme

gitme, gitme... 

Ayrılık girdi, girecek kanıma 

nasil anlatırım yüreğimdeki yangınlara. 

Gitme seni özlerim gitme

gitme, gitme... 

Ne derim sonra 

düşen takvim yapraklarına. 

Gitme seni şimdiden özledim 

gitme, gitme. 

Bittimi vadem doldumu 

gülermisin şimdi gözümdeki yaşlara. 

Gitme ugrunda verdigim can hatrina 

gitme seni özlerim gitme

gitme, gitme...', 'Fırtınalı, bir gece gibi esme  bu son kez, mi bakışınn gözlerime.  Bu son sözlerin''mi  yüreğimde yol alırken, silemem izlerini yıllarca.  Gi...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gitme-gitme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilinmezken Yaşanan Oldun', 'bilinmezken-yasanan-oldun-cahit-i-pekoglu-qfyus', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen garip bir yolculuktun

iş olsun diye yola çıkılan.

Yüreğin sanki bir tuzaktı

gezinirdim teninde doymadan. 

Sevgin yoklarken yüreğimi

seni mutlu kılmak için verirdim tenimi.

Sen garip bir yolculuktun

iş olsun diye yola çıkılan...

Seni seviyorum, diye haykıramazdım

gerçeğini yaşamadan sevemezdim. 

Seni hissetmeden, tenine sarıldım

her titreyişinde, özümdeki gerçeği yaşadım. 

Seni öyle çok sevmişim''ki

ruhunu bana, seni sana bıraktım...

Hadi de''bana de''bana

benden hayır yok de bana.

Beni istemesende bunu söyleme

gözlerinle bak bana.

Bilirmisin artık, kadınım oldun

canım oldun, vazgeçilmezim oldun.

Seni öyle çok sevmişim''ki

ruhuna aşık, teninle sarhoş oldum...

Gezinirdim teninde

yaşanmamış seni, bulmak için.

Renk değiştirirdi tenin

beni sarhoş edip, bırakmamak için. 

Okşanmamışlıklar

sanki bent olmuştu yüreğinde.

Ne zaman, okşasam tenini ellerimle

görülmeyen gözler ağlardı, sev, sev diye.

Seni öyle çok sevmişim''ki

ruhuna aşık, teninle sarhoş oldum...', 'Sen garip bir yolculuktun iş olsun diye yola çıkılan. Yüreğin sanki bir tuzaktı gezinirdim teninde doymadan.  Sevgin yoklarken yüreğimi seni...', ARRAY['Türk Edebiyatı','Şiir','Cahit İpekoğlu']::text[], 8.5, '{"poet":"Cahit İpekoğlu","poet_slug":"cahit-i-pekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bilinmezken-yasanan-oldun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-hakan-akgun-4s50v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Son görüstügümüz günden beri seni yasiyorum, 

Senden uzak görünüp, hep seninle ugrasiyorum, ama sasirdim, 

Çaresiz kalakaldim, hayattan uzaklasip sende yogunlastim, 

Her gece, dipsiz bir okyanusta, dalip çikiyorum zamana, 

Bak iste gün agariyor, yagmur ve yalnizlik yagiyor, 

Dalgalarin oynastigi kayaya, göz kirpistirarak, gök yüzünde unuttugum uçurtmalara, 

Hayiflaniyorum, ve özlüyorum, savrulan saçlarinin fisiltisini, inan öyle bir izdirapki, 

Acidan bile mahrum, gözlerim dost gözlemekte, hala, 

Gözlerim seni gözlemekte ve simdi rüyalarimdan bile uçup gidecegine daldim, 

Anla sevgili bu gece yine seni hasretle andim, seni ciddiye aldim.

Nefret etmek ya da sevmek, anladim ki, ciddiye almak demek, 

Zit kutuplar arasi bir berzahta gezinmek; ya sondur ya da baslangiç, 

Zamanin ucunda tüttürürken sigarami, ne son kaldi ne de ilk, anla ki sevgili, 

Zaman ve mekan her sey bir hiç, sensiz, tüm renkler siyah, resimler çizgisiz, 

Leylaklar ve hatta bülbüller bile hissiz, sensiz tüm çocuklar kimsesiz, 

Kimsesiz koskoca dünya, sensiz, bütün isiklar eriyor, dönüyor her sey, 

Suskunlugunda, yazamiyorum ki, anladigimi, anla artik sevgili seni ciddiye aldigimi.

Ve önce, ve sen bile, adim adim yaklastin, 

Gördün ilgimi, uzaklastin, güçler dengesi dünya, kedi fare oyunu, 

Ürkek bir ceylan gibi nerede gördünse kaçtin, 

Zannetme ki aramizdaki mesafeyi açtin, 

Ben sana uzanan yolda tüm mesafeleri astim, 

Sevgili, ne dünüm kaldi ne de yarinim, varliginda yoklugunu yasiyorum, 

Yoklugunda, isyan bayragini açtim, dalgalaniyor isyankar ruhum, titretiyor her seyi, 

Yoklugunda hep kendimi kandirdim, hep ben bana aldandim, 

Iyilik melegi, güzellik kraliçesi, dogruluk abidesi sevgilim, 

Gel artik, gel, benim kadar, diger ademler de isyankar, onlara da lütfet, 

Mayandan, çöllerde güller açsin, yine seni hasretle andim, seni ciddiye aldim sevgili.

Senden uzak durdugum senden kaçtigim, yalan, ilgisiz göründügüm, ciddiye aldigimdan, 

Ve hep kulaklarimda, ayni ses yankilanan, ''neredesin sevgili, neredesin sevgili''

Bir denizin ufkunda nagmelerinle, yok olup tükendim, ben bende kayboldum, 

Seni benden kiskaniyor, seni bedende aramiyorum, tarihin derinliklerinde, 

Kültürlerin küflenmis dehlizlerinde, Her zaman baska isim, yoklugunda

Kuruttular okyanusu, sen her zaman baska sekil, Ne bir kiz, ne bir yildiz, 

Eflatun bir hayal gibi, sen içimde atessin, ama, yildizlarin bir bir söndü, 

Hepsinde umutlarim, göz yaslarim gizliydi, puslu kaldirim kenarinda, 

Minik gölcüklerde, atesinle yandim, bir avuç fisilti ile, dün gece seni andim, 

Seni ciddiye aldim, sevgili.

Sensiz caddeler bos, sensiz dünya kimsesiz, yalnizligim zirvede, sensiz, 

Gönlüm nesesiz, sen topragin üzerine dogan günessin, benligimi tüm topraga serdim, sadece beni isit, sadece beni aydinlat, sensiz kayboluyorum, karanliklarda, 

Ariyorum yolumu günessiz, ne olur sevgili bir sabah yeniden dog, 

Karmakarisik duygularima bir günes gibi, kirik da olsa tebessüm et, 

Hüznün tomurcuklandigi ülkeme, hüznün tomurcuklandigi ülkelere, 

Elin degiverse, ellerime, bir demet papatya birakiversen, biraktigim hayata bakiversen, 

Zamanin ucunda yasiyorum, görsen, ölümün güzelligine nispet, yine de seni hasretle andim, 

Seni ciddiye aldim, sevgili.

Bu gece ne çigliklar kurtuldu yine hançeremden, ne kabuslar yasadim, 

İzmarit dolu masa basinda, ne çileler çektim ben, 

Günesin ilk isigi sizarken penceremden, anladim ki, 

Seni ciddiye almak kadar sana baglanmakta var, ama korkma, 

Suskun kalacak bu asktan yana dilim, gözlerimin içinde itirafim sevgilim, 

Etrafinda gördügün hiçbir sey ben degilim, hiç bir yerde arama, 

Ben ruhuna saklandim, ne bir sekilim, ne bir suret, sensizlikte zaten ''yokluk'' adim, 

Belli ki ey sevgili seni yoklukta aradim, bir kapali Hisarcik gecesinde, 

Sular yuttu seslerimi, sanki ölen biri var, kargalarda bir heyecan, 

Yokluga dogmakta tüm bebekler, sanki yokluk yagmakta, sanki çökmekte gök-tavan, 

Simsekler sönüp yanar, yine sen yagarsin zihnime, ne yagmur tükenir ne de gece, 

Gecelerde Hisarcikta, uzaktan bir melodi oynasir, bestesi hiçlik olan, 

Su görünen ferleri sönmüs evlerde, gözleri yasla dolan, 

Anneler geldi aklima, evladiyla yok olan, 

Yine Hisarcigin karanlik dehlizlerine daldim, 

Ve yine seni hasretle andim, anla artik sevgili, seni ciddiye aldim...

Korktum seni sevmekten ve sana baglanmaktan, korktukça sevdim, 

Sevdikçe korktum inan, gel ne olur, gel artik, benim atesimde yan, 

Gel böyle bir aska sen dayan, bak ve gör, her sey sana ayan, 

Sonsuz tünellere gömülen sirlar, çocuklugumun zayif omuzlarinda, 

Büyük hüzünler tasidim minicik yüregimde, patlayan yanar daglari, 

Siire dönüstürüp bosluga saldim, seytanca gülümseyen alkolün pençesinde, 

Ariyordum gözlerini, yanip sönen kadehlerde, karanliga yuvarlandi bir bir umutlarim, 

Simdi, hesaplasmayi birakip, hesapsiz bir ask yasamaktayim, 

Bu gece seni yasiyorum, bu gece seni andim, belli ki sevgili seni ciddiye aldim.

Sensizlik bir sukut, dil tutuk, gönül buruk, seni uzaktan görmek bile büyük mutluluk, 

Kelimeler dilimde peltelesen yorgunluk, bak, itirafim bu satirlarda mecalsiz, 

Sevgimi sana itirafim, gerçekten imkansiz, biliyorum sana kavusamam, ama ararim seni, 

Hep ararim, benim ki, yoklukta varligi aramak, sen de yoksun bensiz sevgili, 

Seni ''ben'' kesfettim, benim ki, sende ''ben'' i aramak, bu yüzdendir sana inandim, 

Sevgili, hayir, sensiz bir sonu hak etmedim ben, herkes duysun, sen de bil, 

Böyle ölmek istemem, bari sen beni bul, sen beni teshis et hemen, 

Kimse edemez bana yardim, seni yine hasretle andim, 

Anla ki sevgili seni ciddiye aldim.

Biliyorum zor, bir zor kelimesidir dolasiyor dilime, öyle bir zor ki, 

Zor çok kolay kelime, askimi itirafim ikinci anlamda zor, 

Simdi düsün ve bunu hayra yor, düsün, kim bu zor olan, ne, niçin söylenemez, belki sen Anlarsin, yoksa kimse bilemez, lütfen erken anla, sonuma yaklasmaktayim, adim adim, 

Boslukta dolasmaktayim, yokluktur sensiz adim, inan ki sevgili, 

Seni hasretle andim, seni ciddiye aldim, yalnizlik yagmura benzer

Yükselir aksamlara denizlerden

Uzak issiz ovalardan eser agir gider göklere her zaman göklerdedir.

Ve kentin üstüne göklerden düser...', 'Son görüstügümüz günden beri seni yasiyorum,  Senden uzak görünüp, hep seninle ugrasiyorum, ama sasirdim,  Çaresiz kalakaldim, hayattan uzak...', ARRAY['Türk Edebiyatı','Şiir','Hakan Akgün']::text[], 8.5, '{"poet":"Hakan Akgün","poet_slug":"hakan-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":88,"source_url":"https://www.antoloji.com/seni-seviyorum-106-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üstüpü', 'ustupu-mehmed-sahin-kacar-0k0m6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu aralar hayli şairim haydar

Mağazada indirim var

Cebimde infilak

Dünya çırılçıplak

Sinemaya gideceğim ihaleden sonra

İki tek atarım borç bulursam

Laflarız şerefle ordan burdan

Ne olacak ismetin bu hâli kimbilir

Dünya yerle bir

Neşenin tayini çıkmış duydun mu

Kerem hacere aşıkmış

Bazen diyorum ulan

Boşuna mı vurdular onuru

Dünya tanrının defterinden çıkmış

Bekârlık zor be haydar

Hoş sen de aynısın ya

Cepken delik foça o biçim

Nerede sahi şimdi o çocuklar

Dünyayı takan kim...', 'Bu aralar hayli şairim haydar Mağazada indirim var Cebimde infilak Dünya çırılçıplak Sinemaya gideceğim ihaleden sonra İki tek atarım borç b...', ARRAY['Türk Edebiyatı','Şiir','Mehmed Şahin Kaçar']::text[], 8.5, '{"poet":"Mehmed Şahin Kaçar","poet_slug":"mehmed-sahin-kacar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ustupu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Edalı Kardelen', 'edali-kardelen-salih-ozalasan-sqv8h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen; Adını andığımda yüreğimi titreten

Sen; Aşkına düşmüş yüreğimi inleten

Sen; Gözyaşını tanımayan gözlerime ağlamayı öğreten

Sen; Sevdasıyla yandığım beyaz kardelen

Sen; Tanıdığımda beni hayata döndüren

Sen; Sevdalandığımda içmeden başımı döndüren

Sen; Susmuş yüreğimi şaire döndüren

Sen; Hasretiyle tüttüğüm mahsun kardelen

Sen; Biten ömrümün başlangıcı

Sen; Kuruyan sevda çeşmesinin pınarı

Sen; Bana yakın eden baktığımda uzağı

Sen; Bana tanrının lûtfusun edalı kardelen

(Y.Tar.31-12-2002 Saat 16.50)', 'Sen; Adını andığımda yüreğimi titreten Sen; Aşkına düşmüş yüreğimi inleten Sen; Gözyaşını tanımayan gözlerime ağlamayı öğreten Sen; Sevdasıy...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/edali-kardelen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acaba', 'acaba-sertac-kendirci-vbnf4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yazıyorum...

Yazıyorum ama

Hüznüm belli mi bu satırlarda

Ya da kırık kalbim görünür mü

Anlaşılır mı çektiğim hasret

Zihnimi meşgul eden

Beni yavaş yavaş eriten şey

Kavuşur mu açıklığa

Bilmem ki döktüğüm gözyaşı

Isladığı satırlara

Can verir mi

Peki anlatır mı bu satırlar

Seni ne çok sevdiğimi', 'Yazıyorum... Yazıyorum ama Hüznüm belli mi bu satırlarda Ya da kırık kalbim görünür mü Anlaşılır mı çektiğim hasret Zihnimi meşgul eden Beni...', ARRAY['Türk Edebiyatı','Şiir','Sertaç Kendirci']::text[], 8.5, '{"poet":"Sertaç Kendirci","poet_slug":"sertac-kendirci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/acaba-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Nefesimdin Sen', 'son-nefesimdin-sen-sertac-kendirci-o8rpp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevmiştim seni

İlk ve son kez

Ama gerçekten sevmiştim

Anlamanı beklerdim

Anlayamadın...

Anlatamadım belki de

Ve sen gittin

Çok uzaklarda

Dağlar ardındasın şimdi

Yine sessiz, 

Yine sensiz bir gün

Yine hüzünlü bitti

Önceleri

Her geçen gün ümitleniyordum

Geleceğin günün yaklaştığını düşünerek

Şimdi ise...

Her geçen gün

Ümitlerim yok oluyor

Aylar geçti ve sen

Hâlâ gelmedin diye

Belki de...

Göremeyeceğim seni bir daha

Göremesem de sonsuza dek

Ben hep seni seviyorum

Benim için herşey sensin

Bu dünya, bu ülke, bu şehir

Eğer sen yoksan bu şehirde

Bil ki artık ben de yokum

İkinci bir hayata adım atıyorum

Artık seni hep görüyorum

Burada gelmeni bekliyorum', 'Sevmiştim seni İlk ve son kez Ama gerçekten sevmiştim Anlamanı beklerdim Anlayamadın... Anlatamadım belki de Ve sen gittin Çok uzaklarda Dağ...', ARRAY['Türk Edebiyatı','Şiir','Sertaç Kendirci']::text[], 8.5, '{"poet":"Sertaç Kendirci","poet_slug":"sertac-kendirci","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/son-nefesimdin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulmayacaksın', 'unutulmayacaksin-sertac-kendirci-72vbs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen yüreğimdesin, yanıbaşımda sensizlik

Ayrılık yine karşımda, yine her yerde sessizlik

Layıkıyla sevemedim seni belki de ama

İmkansızdı bu aşk; zordu zordan da fazla

Hayat bu; bazen üzülecek, bazen mutlu olacaksın

Ama bil sonsuza dek unutulmayacaksın...', 'Sen yüreğimdesin, yanıbaşımda sensizlik Ayrılık yine karşımda, yine her yerde sessizlik Layıkıyla sevemedim seni belki de ama İmkansızdı bu ...', ARRAY['Türk Edebiyatı','Şiir','Sertaç Kendirci']::text[], 8.5, '{"poet":"Sertaç Kendirci","poet_slug":"sertac-kendirci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/unutulmayacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışamadım Yokluğuna', 'alisamadim-yokluguna-sertac-kendirci-ql2uf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sessiz çekip gittin

Gittin bir elveda demeden

Kırık bir kalp

Islak bir çift göze aldırmadan

Şimdi çok uzaklardasın

Uzaklarda...Dağlar ardında

Hayalinle başbaşayım, 

Hayalinle yan yana 

Yüreklere sığmayan sevgin

Sevgin her zerremde hâlâ

Yüzün, gözlerin, gülümseyişin

Beynime kazılı, unutamadım seni

Hâlâ gözlerimi yaşlar

Yüreğimi hasretin zorlamakta

Aradan yıllar geçti ama ben...

Ben seni unutamıyorum

Sen de gün gelir hatırlarsan beni

Gözlerimde yaş, sevgin kalbimde

Hâlâ bekliyorum seni burada

Bekliyorum seni çünkü

Çünkü hâlâ çok seviyorum

Hâlâ hasretin yüreğimi dağlıyor

Yokluğuna alışamadım daha

Sensizlik ağırıma gidiyor ve ben...

Ben  henüz sensiz  yapamıyorum...', 'Sessiz çekip gittin Gittin bir elveda demeden Kırık bir kalp Islak bir çift göze aldırmadan Şimdi çok uzaklardasın Uzaklarda...Dağlar ardınd...', ARRAY['Türk Edebiyatı','Şiir','Sertaç Kendirci']::text[], 8.5, '{"poet":"Sertaç Kendirci","poet_slug":"sertac-kendirci","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/alisamadim-yokluguna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dua', 'dua-ahmet-i-ldeniz-r6ulh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben; 

O

Siyah gözlerine

Bir çift gözle bakmadım

Allah takdir eder gözlerimi alırsa

İşte

İlk gün gömdüm seni kalbime

Artık; 

Ölüm ayıramaz, 

Görmeyen göz unutturamaz.

BEBEĞİMM! ...

O

Soğuk kara toprağa

Bir çift kör gözle girersem

Senin ateşin kandil, 

Kokun amber, 

Sevdan mezarımda 

Cennet olur BİTANEMMMM! ...

EY! ...

ALLAHIM! ...

Sen büyüksün.

Şu seherinde DUAM; 

Bir huri yeter.

Gurbet olsada aramızda', 'Ben;  O Siyah gözlerine Bir çift gözle bakmadım Allah takdir eder gözlerimi alırsa İşte İlk gün gömdüm seni kalbime Artık;  Ölüm ayıramaz,  ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet İldeniz']::text[], 8.5, '{"poet":"Ahmet İldeniz","poet_slug":"ahmet-i-ldeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dua-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '2002', '2002-ugur-uludag-q2lmq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yalan dolan

kabus gibi bi sene

yıllar sonra pişman olacağım halde

mutluyum- yalnızım

elim sigara

önüm şarap

sırf kafiye olsun diye

ömrüm harbiden harap

güzel sözler

nefis gözler

dileyesim var tanrıdan

bilirim olmaz ki

böyle bahtsızlık olmaz ki? 

ama yine de

ezberledim bir yerinden hayatı

yapışmışım yakasına bırakmam

yeni sene yalan da olsa inanmam

32. sayfasından kıvrılıp okunmamış bi kitap gibiyim

kötü yazılmış- yazılamamış

üstünde uğraşılmamış

iğrenç, tukaka bi kitap

ama yine de

tutunmuşum bir yerinden hayata

ölürüm de bırakmam

yeni sene dolan da olsa dolanmam

ölürüm de inanmam', 'yalan dolan kabus gibi bi sene yıllar sonra pişman olacağım halde mutluyum- yalnızım elim sigara önüm şarap sırf kafiye olsun diye ömrüm har...', ARRAY['Türk Edebiyatı','Şiir','Uğur Uludağ']::text[], 8.5, '{"poet":"Uğur Uludağ","poet_slug":"ugur-uludag","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/2002-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm', 'gulum-ahmet-i-ldeniz-aba7y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir canki, vursan ölmüyor.

Bir bedenki, ateşe atsan yanmıyor.

Ben ölümsüzüm demiyorum.

Orada bir sen, bir ben var GÜLÜM! ...

Öllüm hak desem, 

Sevdan öyle bir aşk ki, 

Sensiz sönmüyor bee... GÜLÜM! ...', 'Bir canki, vursan ölmüyor. Bir bedenki, ateşe atsan yanmıyor. Ben ölümsüzüm demiyorum. Orada bir sen, bir ben var GÜLÜM! ... Öllüm hak desem...', ARRAY['Türk Edebiyatı','Şiir','Ahmet İldeniz']::text[], 8.5, '{"poet":"Ahmet İldeniz","poet_slug":"ahmet-i-ldeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gulum-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarifsiz', 'tarifsiz-ali-serttas-lsa0a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dudaklarıma takılan iki kelime

Tarifi mümkün

Anlatması zor', 'Dudaklarıma takılan iki kelime Tarifi mümkün Anlatması zor...', ARRAY['Türk Edebiyatı','Şiir','Ali Serttaş']::text[], 8.5, '{"poet":"Ali Serttaş","poet_slug":"ali-serttas","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/tarifsiz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canlar Merhaba', 'canlar-merhaba-halil-gulel-3kqd4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uzaktan yakından aşkla gelerek; 

Gönülden gül deren canlar merhaba...

Hakk’tan aldığını halka vererek

Gözlerde sel gören canlar merhaba...

Yüreği yaralı sinesi oyuk, 

Bir damla gözyaşı deryadan büyük, 

Sırtında insanlık adına bir yük

Mazluma kol geren canlar merhaba...

Okyanus içinde inciyi bulan, 

Yoksula, garibe bir derman olan, 

Aşk derdiyle yanan hasretle solan

Gurbette yol soran canlar merhaba...

Yanmış yüreklere can veren bir su, 

Alemin gerçeği – işin doğrusu, 

Gönülden süzülen aşkın duygusu

Eserde bal veren canlar merhaba...

Ressam Halil, sanat gönül işidir, 

Çileyle yoğrulan temel taşıdır, 

Kültürün başıdır – halkın yaşıdır

Millete dil kuran canlar merhaba...

                                Ressam Halil GÜLEL

		Düsseldorf / 14.12.2002', 'Uzaktan yakından aşkla gelerek;  Gönülden gül deren canlar merhaba... Hakk’tan aldığını halka vererek Gözlerde sel gören canlar merhaba... Y...', ARRAY['Türk Edebiyatı','Şiir','Halil Gülel']::text[], 8.5, '{"poet":"Halil Gülel","poet_slug":"halil-gulel","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/canlar-merhaba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derbederin Dünyası', 'derbederin-dunyasi-ugur-akdogan-1pv4q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'BENI SEVMEK YÜREK ISTER

Bilsen içim neler gizler

K@nimd@ki çilgin hisler

Seversem dûny@yi y@k@r geçer

Bilmeceyim gel çôzersen

@d@m gibi seveceksen

Gôlge gibi pe§inden

Gelirim k@lbime bir girersen

Benzeyemem b@§k@sin@

Meyd@n okurum bir b@§im@

Cilginim Deliyim

Severken Div@neyim

Y@l@n sôze hiç gelemem

Ih@neti ben çekemem

Beni birgûn @gl@tirs@n

Hirçinim y@k@rim @ffedemem

@ci t@tli her gûnûmde

Ol@c@ks@n sen benimle

Dû§ûnmeden bir @n olsun

Giderim seninle ôlûme

Çok Seviyorum 

Seviyorum seni yalan diyemem 

Ağlarım artık sensiz gülemem 

Senden başkasını inan sevemem 

Çok seviyorum seni yalan diyemem 

Azıcık anlamaya çalış zalim olma 

O ufak kalbine yabancı olma 

Korkma seni aldatır sanma 

Çok seviyorum seni şaka sanma 

.', 'BENI SEVMEK YÜREK ISTER Bilsen içim neler gizler K@nimd@ki çilgin hisler Seversem dûny@yi y@k@r geçer Bilmeceyim gel çôzersen @d@m gibi seve...', ARRAY['Türk Edebiyatı','Şiir','Ugur Akdogan']::text[], 8.5, '{"poet":"Ugur Akdogan","poet_slug":"ugur-akdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/derbederin-dunyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Anerka*', 'anerka-ozhan-hakan-70qhu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'I 

Hüznüm; süngülü yalnızlıklara itilmiş bir Dersim gecesi, 

açlığım; bir deri bir kemik, 

sabrım; altı aylık unutulmuşluğuyla bir Bahçesaray''lı 

ve korkum; yollarına sinmiş bir çakal 

ya gidenler evin yolunu bir daha bulamazsa Anerka! 

geçitlerinde yasaklanmış mevsim hatıralarıyla 

sana nereden geleyim? 

Artık her ses içimdeki bir sözün katili 

oysa, bir seni bildim Anerka 

bir de kaçmaya hazır gözlerindeki, yarı uykuyu 

ki henüz bir kaç asırlık olsa da sensiz kalmışlığım 

bir seni bildim, 

bir de sensizliği... 

dilimde, kavimler göçünden kalma bir yol türküsü, 

aklımda, söze dönüşmeyen sesler, 

yüzümde gülücük diye taşıdığım hüzün, 

boynumda, mor hamaylı gözlerin 

ve yüreğimde 

aşkın kehanet korkularıyla 

sabrımı yoklayan esmer geceyi 

ayın öbür yüzündeki ihaneti 

tanrıyı 

ve 

seni, 

hakimin hükmüne kırılan kalemi, 

ve 

çekilen bıçağın 

aşkın kirli tarihinden akıttığı kanları 

soluk ve soğuk yüzlerin sinsi pusularını 

celladın cüzzamlı, kanlı avuçlarını 

ve her an tetikte, aklı firarda sevgilileri... 

bir seni bildim Anerka 

bir de sol göğsünde kızıl alev güllerini 

yüzünün yaşama dönüşüp, 

gözlerinin felsefe ile anlaştığını 

ve bir ben bildim 

Platon''un gözlerine ne denli yakıştığını... 

bir seni bildim Anerka 

bir de yirmi dört saatin gece olduğunu 

geçmiş zaman kipinde bütün umutları 

gelecek zamana bağlayan 

bağlantısız bir bağlaç 

ve 

güneşe devrilmeyen 

devrik bir cümle gibi 

her şeyin anlamından koptuğumu 

II 

Aşkınla, 

ateşinde yanan şaşkın bir pervaneydim Anerka! 

yaşamın başlangıç noktası 

ve ölümle başlayan başlangıçların son noktası... 

görünmez bir kazaydım kendi seyrimde 

gece; zarf 

ölüm; fiil 

ışık; fail 

ben ise bütün intiharların öznesiydim 

Pusuda iken bütün Firavunlar 

kimseler sevmedi benim kadar gözlerindeki yarı uykuyu 

bir intihar pervanesiydim, bir ışığa aşık 

bir şaşkın düş kanadıydım 

gözlerinde kırık, 

gözlerine aşık... 

oysa şimdi Anerka, 

oysa şimdi, kum saatinin ince belinden tek saniye süzülmezken 

Bruki göçü gibi diyar diyar sürülen yüreğimde(n)                                         vuruyor zaman 

Babil''im, Ninova''yım. 

yitik ve mistik bir zaman tüneliyim 

bir çığın ağır çığlığı 

ve ağır bir sevda enkazıyım Anerka! 

III 

Hislerimi bir dervişe satıp 

tanımsız hiçliğimle duaların ürpertisine gizledim umudumu 

boynumda bilmece gibi ismin 

bir sevda türküsünün son notası özetinde 

ve 

her kulacımda dibe çekildiğim 

anasından ayrı Van Gölü hüznündeyim 

özü bilinmeyen dinler adına 

Xecé û Siyabend aşkına Anerka! 

yut dudaklarımı 

yut ki öpeyim yüreğinden 

yoksa, 

sol yanımda ağır bir kanamayla cebimde cerahatımı taşıyarak 

kötücül varlıklar 

ve kaybolmuş yüzlerin arkasında yatan hiçlikle 

kendime yamanarak 

ve yanarak 

ve yalınayak Tamara çaresizliğinde 

kokunun sindiği kaleden bozma şatomun dehlizlerinde yitip 

talihim gibi kör çıyanların 

bedenini oyduğu Akdamar olurum Anerka! 

kıvranan narin çaresizlik, 

titreyen özüme bulaşmış acemilik, 

ve 

günah desenleriyle 

ruhumun ölüsünde dirilen beden neye yarar? 

yokluğun ölüm olur Anerka! 

yokluğun, Başkale''de sırrı aşikar bir cinayet 

ve Zilan Deresinde ölen çocuk ürpertisiyle 

asi, direngen yüreğimdeki isyanı bastıran zulüm olur... 

bir seni bildim  Anerka

bir de senden olanı 

kendimi ve yokluğumu 

ve 

uyruğumun aşk, 

tabiyetiminse hiç olmadığını...

ey göğsüne yaslanıp çırılçıplak ağladığım! 

kaşlarını ağıtlarıma, 

gözlerini çaresizliğime, 

yalnızlığım kadar prüzsüz bir ten 

ve ışığı boğan gölgem kadar yoksul çizgileriyle 

yüzünü yüzüme benzettiğim siluetsiz sevgili 

bilirsin ''''aşk bir sığınma talebidir'''' 

anadilim gibi dilimin ucunda ve yasak olsan da 

iri gözlerine beni de al Anerka! 

İri gözlerine beni de al...', 'I  Hüznüm; süngülü yalnızlıklara itilmiş bir Dersim gecesi,  açlığım; bir deri bir kemik,  sabrım; altı aylık unutulmuşluğuyla bir Bahçesara...', ARRAY['Türk Edebiyatı','Şiir','Özhan Hakan']::text[], 8.5, '{"poet":"Özhan Hakan","poet_slug":"ozhan-hakan","theme":"Türk Şiiri","is_hero":false,"total_lines":117,"source_url":"https://www.antoloji.com/anerka-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubailer', 'rubailer-cevat-akkanat-c67y1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1.

gün eğilir girer gölgeler yere

boşalır bulutlar içime dolar

hazindir iniler bahtımsın diye

alevden söylediğim şarkılar solar

2.

benim sevdiğim bir kırılgan kalp kızı

aldı götürdü beni sanki şehri ağrı’ydı 

tatlı bir acı sızı de ki yedi bitirdi 

yani oldum onunla elbet kalbim göynüdü

3.

ibrahim gözümde bir ince umut

hayata sımsıkı bağlayan alev

belkıs zöhre züleyha ayrı alem herbirin

adın çıkmış güzelim ben yıkarım nice put', '1. gün eğilir girer gölgeler yere boşalır bulutlar içime dolar hazindir iniler bahtımsın diye alevden söylediğim şarkılar solar 2. benim sev...', ARRAY['Türk Edebiyatı','Şiir','Cevat Akkanat']::text[], 8.5, '{"poet":"Cevat Akkanat","poet_slug":"cevat-akkanat","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/rubailer-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aralık 2002 İdi Bu Şiiri Yazarken, Ocak 2003 Oldu', 'aralik-2002-i-di-bu-siiri-yazarken-ocak-2003-oldu-edip-cangonul-e9g44', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '42. si devrildi bugün

gece yarısıydı

havai fişekler 

fişek fişekdi 

uzun bir kavaktı

ormancı nöbette

ben türküler eşliğinde

koca kavak

buruşuk kavak

dalları yanası kavak

kuru bir kavak gibi devrildi gitti

önlem aldı ağaççılar

kırmasın diye

dalını

kayısının

kuruydu dalı 

kaysının

yine de

baktı korku ile

üstüme düşer diye

kuru kavağa

kavak düştü

kayısı baktı

beni türküler ısıtıyordu 

hala

bu yaz sıcağında

yeni bir yıl oldu

yeni bir bahar

kayısı çiçeğe durdu

kavak kökünde piç fidanlar

yeşil

....................

bir yılbaşıydı canlar

siz üşümeyin

eliniz elde ola

elde ola eliniz', '42. si devrildi bugün gece yarısıydı havai fişekler  fişek fişekdi  uzun bir kavaktı ormancı nöbette ben türküler eşliğinde koca kavak buruş...', ARRAY['Türk Edebiyatı','Şiir','Edip Cangönül']::text[], 8.5, '{"poet":"Edip Cangönül","poet_slug":"edip-cangonul","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/aralik-2002-idi-bu-siiri-yazarken-ocak-2003-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Simsiyahım', 'simsiyahim-ahmet-ozturk-8gls2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Siyahı giyinmek bir misyon ister

Bir de yürek

Karşı duracak kollar lazım

Parçalayacak eller

İsyana fışkaracak gözler

Okyanusun dibinde boğulmayacak bir beyin

Siyaha bakmak hüküm ister

Bir de bilek

Ezberleyecek dudaklar

Soluk soluğa bir göğüs

Dostlarının içinde oynamayacak bir adam

Siyaha bakıyorum

Hüküm yüreğimde

Yürekliyim bileğine kuvvet

Kollarımla saracak dudaklarım

Ellerim göğsümde isyana fışkırıyorum

Simsiyahım siyaha bakarken

17 Aralık 2002 Salı

02: 49', 'Siyahı giyinmek bir misyon ister Bir de yürek Karşı duracak kollar lazım Parçalayacak eller İsyana fışkaracak gözler Okyanusun dibinde boğul...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Öztürk']::text[], 8.5, '{"poet":"Ahmet Öztürk","poet_slug":"ahmet-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/simsiyahim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar', 'sonbahar-sevi-tuncel-b9sx6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kasım yağmurları başladı artık, 

Hüzünlü sevdaların son demleridir yaşanan...

Ve şairlere gün doğdu yine.

Yağmura karışan gözyaşlarıyla, 

Hasret kokuyor ıslak topraklar..

Düşen yaprak misali solan sevgiler, 

Geceyarısı boş kaldırımlarla boy ölçüşen yalnızlığımız

Ve ürpermek minik kuş yüreğiyle hırçın rüzgarlarda...

Titreyen dudaklarda yanmış bir sigara, 

Duman duman dağılan düşüncelerimiz...

Her nfeste ciğerimize dolan unutulmanın verdiği acı.

Sinsice işler içimize ve bir yaradır kanar durmadan, 

Sarar tüm benliğimizi yorgan misali..

Oysa kaçıncı sonbahardır unutamadığımız, 

Yağmurların silemediği anılarda yaşamak sonbaharı..

ve sevmek seni zehir zıkkım....', 'Kasım yağmurları başladı artık,  Hüzünlü sevdaların son demleridir yaşanan... Ve şairlere gün doğdu yine. Yağmura karışan gözyaşlarıyla,  Ha...', ARRAY['Türk Edebiyatı','Şiir','Sevi Tuncel']::text[], 8.5, '{"poet":"Sevi Tuncel","poet_slug":"sevi-tuncel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sonbahar-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-mehmet-i-mal-p8ont', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dikkatlice bakıyorum yerlere 

Altın olan ne tek bir taş var 

Ne de bir avuç toprak

Çaresizlik buluyorum sadece ayak izlerinde

Kimileri sosyetik gölgeler saçarken etrafa

Kimileri o gölgelerde simit satıyor

Kimileri olanları hesaplıyor

Kimileri olmayanları var etmeye çalışıyor

Bir tas çorba için bin tas ter döküyor

Ve 

anlıyor en sonunda

İstanbul dediklerinin

boş bir çorba tenceresi olduğunu', 'Dikkatlice bakıyorum yerlere  Altın olan ne tek bir taş var  Ne de bir avuç toprak Çaresizlik buluyorum sadece ayak izlerinde Kimileri sosye...', ARRAY['Türk Edebiyatı','Şiir','Mehmet İmal']::text[], 8.5, '{"poet":"Mehmet İmal","poet_slug":"mehmet-i-mal","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/istanbul-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük Gagalı Kuşlar', 'buyuk-gagali-kuslar-tuncay-emrem-q81hl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Büyük gagalı kuşlar dolaşır durur

Yüce ağaçların tepelerinde

Uzak bir yıldızın insanları mıdır

Gölgeleri bir tuhaf akşam içinde

Bilgiç bir tavırla gelip konacaklar

Birgün hasta yatağımın karyola demirine

O zaman anlarım gitmek zamanı

Büyük gagalı kuşların memleketine

İstanbul 1958', 'Büyük gagalı kuşlar dolaşır durur Yüce ağaçların tepelerinde Uzak bir yıldızın insanları mıdır Gölgeleri bir tuhaf akşam içinde Bilgiç bir t...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Emrem']::text[], 8.5, '{"poet":"Tuncay Emrem","poet_slug":"tuncay-emrem","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/buyuk-gagali-kuslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece', 'bu-gece-tuncay-emrem-awwdr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu gece üşüyorum

Bu gece yağmur içime yağıyor

Damları erimiş bir şatoyum bu gece

Kapılarım gıcırdıyor

Ay ışığı dolmuş harabelerde

Çıplak ayakla koşuyorum

Bu gece üşüyorum', 'Bu gece üşüyorum Bu gece yağmur içime yağıyor Damları erimiş bir şatoyum bu gece Kapılarım gıcırdıyor Ay ışığı dolmuş harabelerde Çıplak aya...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Emrem']::text[], 8.5, '{"poet":"Tuncay Emrem","poet_slug":"tuncay-emrem","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bu-gece-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulmak', 'unutulmak-tuncay-emrem-205wa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Olsa tüyleri parlak

Beyaz bir kanadımız

Yıldızlı ağaçların

Mavi yapraklarının

Göllerin üzerinden, 

Kanat çırparak, 

                 süzülsek uzak, 

                              başka ellere..

Zaman geçse de, 

                 dönmesek geri

                              ve unutulsak...', 'Olsa tüyleri parlak Beyaz bir kanadımız Yıldızlı ağaçların Mavi yapraklarının Göllerin üzerinden,  Kanat çırparak,                   süzülse...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Emrem']::text[], 8.5, '{"poet":"Tuncay Emrem","poet_slug":"tuncay-emrem","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/unutulmak-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayata Meydan Okuyacağım', 'hayata-meydan-okuyacagim-gokcen-duran-utnhx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu akşam

Ay   doğarken   üzerime

Kıracağım  zincirlerimi.

Yılların  esaretini, 

Mahzenlerde  bırakacağım.

Tam  on  ikiden  vurup  talihi

Şanssızlık  kalelerini  yıkacağım

Kanat  takıp  ruhuma, 

Sonsuz  boşluğa  uçacağım

                           Geçmiş  ve  gelecekten  yakınmadan

                           Ayları,  günlerle  dokuyacağım

                           Gözümü  budaktan  sakınmadan

                           Hayata  meydan  okuyacağım', 'Bu akşam Ay   doğarken   üzerime Kıracağım  zincirlerimi. Yılların  esaretini,  Mahzenlerde  bırakacağım. Tam  on  ikiden  vurup  talihi Şan...', ARRAY['Türk Edebiyatı','Şiir','Gökçen Duran']::text[], 8.5, '{"poet":"Gökçen Duran","poet_slug":"gokcen-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hayata-meydan-okuyacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabret Geleceğim Aşkım', 'sabret-gelecegim-askim-ugur-erbil-bvttg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sabret sevdiğim geleceğim bir gün

Hasretine dayanamıyorum artık

Berabersizliğimizin son anları artık

Bekle sevdiğim bu hasretlik bitiyor artık, 

Sabret sevdiğim geleceğim bir gün

Askerliğimde bitecek bir gün

O zaman beraber uzun yıllar beraberiz aşkım

Yıllar yetmeyecek bizi ayırmaya yollar yetmeyecek, 

Sabret sevdiğim geleceğim bir gün

O göz yaşların kurusun artık

Bende dayanamıyorum hasretin koydu artık

Sensiz geçti on sekiz ayım bundan sonra hep yanındayım, 

Sabret Sevdiğim İşte Geliyorum Artık...', 'Sabret sevdiğim geleceğim bir gün Hasretine dayanamıyorum artık Berabersizliğimizin son anları artık Bekle sevdiğim bu hasretlik bitiyor art...', ARRAY['Türk Edebiyatı','Şiir','Uğur Erbil']::text[], 8.5, '{"poet":"Uğur Erbil","poet_slug":"ugur-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sabret-gelecegim-askim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Dersin', 'ne-dersin-yusuf-unsal-ukcma', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gecelik beni yaşatırmısın sende

Olmasada

Benim seni yaşattığım 

Sarıp sarmaladığım gibi

Konuk eder ağırlarmısın

Rüyalarının bir ucuna

O zifiri karanlıklarda

Bir gecelik beni yaşatırmısın sende

Birilerinin uykuya daldığı saatlerde

El ayak çekilip 

Bedenim yenik düştüğünde

Sarıp sarmalamasanda

Bir gecelik beni yaşatırmısın sende

Benim her geceme karşılık bir gece

Ne dersin', 'Bir gecelik beni yaşatırmısın sende Olmasada Benim seni yaşattığım  Sarıp sarmaladığım gibi Konuk eder ağırlarmısın Rüyalarının bir ucuna O ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ünsal']::text[], 8.5, '{"poet":"Yusuf Ünsal","poet_slug":"yusuf-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ne-dersin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurura Yenildik', 'gurura-yenildik-yusuf-unsal-3vpzj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Arkamızda sıra, sıra dağlar bıraktık zirvelerinde kar

Kırık kalpler bıraktık o dağların arkasında

Mahsun duygular bıraktık titrek dudaklar bıraktık

Zirvesine ulaşamayacağımızı bilebile aptalca kahramanlıklar

O kahramanlıkların yanında bir sürü abukluklar

Oysa biz

İpsiz sapsız bir gururun arkasına sığındık

O gururki bizi bize bile uzak bırakmış

Bizi bize düşman etmiş

Alamadığımız dostluk

Alamadığımız insanlık

Anlayamadığımızsa karmakarışıklık

Kıymetini bilmediğimiz kalplerimizdeki tomurcuklar

O tomurcuklarki belki bir daha açmayacak

Elbette utancımızı gururumuza satacak yenikliğini saklayacağız

Elbette gururumuzu yüceltecek, aklayacağız

Kimse anlamayacak kimse ne oluyorlarla ağrıtmayacak başımızı

Ve biz

Gururumuzla ikimiz

Gül gibi geçinip gideceğiz

Kimin umrunda

Arkamızda sırasıra dağlar bırakmışız zirvelerinde kar

Kimin umrunda

Kırık kalpler bırakmışız o dağların arkasındaymış yar', 'Arkamızda sıra, sıra dağlar bıraktık zirvelerinde kar Kırık kalpler bıraktık o dağların arkasında Mahsun duygular bıraktık titrek dudaklar b...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ünsal']::text[], 8.5, '{"poet":"Yusuf Ünsal","poet_slug":"yusuf-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gurura-yenildik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey aşk...', 'ey-ask-dinc-coban-wl5a9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey aşk, 

Ey yüzgeçleri kesik

yalnız balina.

Sarkık bıyıklarımı batırıp içtiğim sarı su, 

küfrettiğim yalnızlık; 

Kırmızı başlıklı ortanca, 

tut, 

bırakma ellerimi, 

ne sırt ağrısı çekeceksin bundan böyle

ne gün ışığına hasretlik.

Kışlara yatıp, 

baharlara uyanacaksın 

tut, 

bırakma ellerimi...

...

Ey aşk, 

ceplerinde hüzün taşıyan küçük kız, 

ne zaman yakacağımı bilmediğim ateşler getirdim

ve

ne zaman topladığımı bilmediğim

kestaneler.

Onlara anlat derdini, 

patladıkları zaman anlayacaklar seni...

...

Ey aşk, 

sevdası doyumsuz göçebe kız, 

salınıp yürü kaldırımlar boyu, 

aklına getir sevişmelerimizi, 

diren, 

kesme saçlarını...

1 Ocak 2003', 'Ey aşk,  Ey yüzgeçleri kesik yalnız balina. Sarkık bıyıklarımı batırıp içtiğim sarı su,  küfrettiğim yalnızlık;  Kırmızı başlıklı ortanca,  ...', ARRAY['Türk Edebiyatı','Şiir','Dinç Çoban']::text[], 8.5, '{"poet":"Dinç Çoban","poet_slug":"dinc-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ey-ask-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim KIRÇİÇEĞİM', 'sevdim-kirci-cegi-m-murat-hakki-yasar-vfmbq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Evet sevmemiştim seni

Çünkü sevdimmi kendimi kaybediyorum

Gözüm hep şişelere takılıyor

Saatlerce, günlerce içiyorum durmadan

Sevdimmi hep böyle olurum.

Senden ayrıldıktan sonra 

Karşıdaki meyhaneye gittim

Saatlerce içtim durmadan duraksamadan

Evet senide sevmişim

Bunu bende geç anladım

Yine şişelerle dertleşiyorum

Masamdaki sigara ve bardaktaki alkol

Bana bakıyor durmadan

İçiyorum, içiyorum, içiyorum ama seni hala unutamıyorum

Artık hiçbirşey fayda etmiyor bana 

Seni çok sevmişim meğer

Bunu bende geç anladım

Şuanda yanımda olmanı 

Ve seninle bizim şarkımızı beraber söylemek vardı! 

Ama geç! ! ! ! ! ! ! ! ! ! ! ! ! ! ! 

Sende sevmedin tıpkı ötekiler gibi

Ben alıştım, şişelerde alıştı 

Hep sevip sevip ayrılmaya 

Neyse seni fazla rahatsız etmeyeyim

Ama telefonu kapattığında 

Sakın üzülme bana 

Dedim ya ben alıştım

(01.01.2003

konya /ılgın)', 'Evet sevmemiştim seni Çünkü sevdimmi kendimi kaybediyorum Gözüm hep şişelere takılıyor Saatlerce, günlerce içiyorum durmadan Sevdimmi hep bö...', ARRAY['Türk Edebiyatı','Şiir','Murat Hakkı Yaşar']::text[], 8.5, '{"poet":"Murat Hakkı Yaşar","poet_slug":"murat-hakki-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sevdim-kircicegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu sen misin?', 'bu-sen-misin-i-smail-karakus-yl55m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu sen misin? 

Yani şu ağlamaklı

Titrek,

Bedbin sima! 

Neydin sen,

Ağlamak bir yana,

Üzülmüş müydün hiç,

Bir ağlayana? 

...

Zaman be,

Ah zaman var ya; 

Ağlamayanı ağlatır.

Hatta,

Anlamayanı da.

...

Sensin evet,

Bu senmişsin de; 

Sakladığın hüzünlerde, 

Buldum izini.

Senmişsin.

...

Bir daha,

Kendini saklamak istediğinde; 

Benim gözyaşlarıma gel.

Kimse bulamaz orada seni,

Benden başka! 

...', 'Bu sen misin?  Yani şu ağlamaklı Titrek, Bedbin sima!  Neydin sen, Ağlamak bir yana, Üzülmüş müydün hiç, Bir ağlayana?  ... Zaman be, Ah zam...', ARRAY['Türk Edebiyatı','Şiir','İsmail Karakuş']::text[], 8.5, '{"poet":"İsmail Karakuş","poet_slug":"i-smail-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bu-sen-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Türküsü', 'gecenin-turkusu-ahmet-cagri-ozsema-fp1ke', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güneş yavaş yavaş göz kırpıyor

Ben hâlâ kendi karanlığımdayım.

Sabah ezânı, kuş sesleri, rüzgar hışırtısı

Hepsi var.

Bir sen yoksun, 

Sen yoksan ben de yokum.

Sen yoksun, 

Şimdi sensizlik vaktidir.

Bir türküdür sensizlik, 

Sensizlik, gecenin türküsüdür.

Gecenin türküsü sabaha sesleniyor.

Ve sabah yeni acılar için bileniyor...', 'Güneş yavaş yavaş göz kırpıyor Ben hâlâ kendi karanlığımdayım. Sabah ezânı, kuş sesleri, rüzgar hışırtısı Hepsi var. Bir sen yoksun,  Sen yo...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Çağrı Özsema']::text[], 8.5, '{"poet":"Ahmet Çağrı Özsema","poet_slug":"ahmet-cagri-ozsema","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gecenin-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Yaranamadım', 'yaranamadim-i-smail-karakus-mfi3y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İllegal haykırışlarla serinlettim,

Çöl yılgını gönlümü.

Su tabancalı çocuklardık,

Gerillası olmadan önce sevgi cephesinin.

Üzgünsü bir boyun büküştü kalan,

Titrek görüntülü mazilerde.

İhtiyacı yokken su verdim hep

Kaktüs ruhlu gönlüme.

Töreye kurban bir ruh gibiydim,

Sıkılgan, kırılgan, sonunu bilen.

Ve sona yaklaşmışken,

Hayalinde başa dönen.

Dert sarhoşuyken meze oldum,

Maymun iştahlı gönlüme.

Aynı fikirlerdi hep paylaşılan,

Ve aynı filmlerdi seyredilen hep,

Pembe matinelerde.

İtirafçı militandım onun gözünde,

Aşk karakolu nezarethanesinde.

Şifacı bir bülbül oldum,

Gülü yanan gönlüme.

Banadır dönüşün hey,

Gel acziyetimi dinle.

Kudurgan göller gibiydin, 

Denizlere kafa tutan

Söyle içimin gangsteri,

Var mı elinden tutan?', 'İllegal haykırışlarla serinlettim, Çöl yılgını gönlümü. Su tabancalı çocuklardık, Gerillası olmadan önce sevgi cephesinin. Üzgünsü bir boyun...', ARRAY['Türk Edebiyatı','Şiir','İsmail Karakuş']::text[], 8.5, '{"poet":"İsmail Karakuş","poet_slug":"i-smail-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yaranamadim-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımsın', 'askimsin-sukru-mehmet-bayrak-ehpwq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her bahar gözlerimin yeşilinde yeşerdin, 

Kumrular gibi, oynaştın kipriklerimin dallarında.

Sen benim dile getiripte konuşamadığım, 

Şöyle bir uzanıpta alamadığım aşkımsın...

Dualarımla nurda perde olur, pencereme inerdin...

Sesini duyardım odama sızan ay ışığında...

Sen benim geceyi aşıpta kavuşamadığım, 

Yıldızların en ötesindeki, erişemediğim aşkımsın...

Bazen bir yağmur damlası olup, Yüreğime düşerdin...

Bazende ılık ılık eserdin tenimde, sonbaharlarda.

Sen benim yollarını bilip de, ulaşamadığım...

Şöyle bir dokunup da, sarılamadığım aşkımsın....', 'Her bahar gözlerimin yeşilinde yeşerdin,  Kumrular gibi, oynaştın kipriklerimin dallarında. Sen benim dile getiripte konuşamadığım,  Şöyle b...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Mehmet Bayrak']::text[], 8.5, '{"poet":"Şükrü Mehmet Bayrak","poet_slug":"sukru-mehmet-bayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/askimsin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünmek', 'seni-dusunmek-i-smail-ozabaci-otypl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'seni düşünmek; 

kabullenmekti bir güzelliği koşulsuz, 

seni düşünmek; 

biraz ellerine dokunmaktı, 

    biraz saçına, 

          ve hayallerde sarılmaktı sana, 

seni düşünmek, 

olası bir önseziyle aramaktı seni, 

hissetmekti yüreğinden geçenleri bir bir, 

seni düşünmek, 

uzak bir şehirde bilmediğim bir evde, 

olmaktı yanıbaşında, 

izlenesi bir rüyadayken sen, 

seni düşünmek sevgili, 

korku, yalnızlık ve özlemdi biraz, 

ve çelişkiydi, 

beni görmekle görmemek arası gidip gelirdi duyguların, 

seni düşünmek

SENİ SEVMEKTİ...', 'seni düşünmek;  kabullenmekti bir güzelliği koşulsuz,  seni düşünmek;  biraz ellerine dokunmaktı,      biraz saçına,            ve hayallerd...', ARRAY['Türk Edebiyatı','Şiir','İsmail Özabacı']::text[], 8.5, '{"poet":"İsmail Özabacı","poet_slug":"i-smail-ozabaci","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seni-dusunmek-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanayan Yaram', 'kanayan-yaram-mustafa-engin-karatay-hn6de', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir cerahat misali, fışkırıyor deştikçe

Her vuruşta neşteri; azar, kanayan yaram

Anılardan süzülüp, kan damlası düştükçe; 

Yüreğimin özüne, sızar kanayan yaram...

İnler, duydukça gökler; feryad ü figanımı

Kızıllaşan kirpiğim, gösterir hicranımı

Tellerine nakşedip, resmeder her ânımı

Esrarlı pıhtıları, bozar kanayan yaram...

Sonra eğilir başım, sessiz boynum bükülür

Ciğerlerimden kopup, parça parça sökülür

Buğulu gözlerimden, kalemime dökülür

Ruhumun Kitabı''na, yazar kanayan yaram...

01.01.2003 - 04.25, Münih', 'Bir cerahat misali, fışkırıyor deştikçe Her vuruşta neşteri; azar, kanayan yaram Anılardan süzülüp, kan damlası düştükçe;  Yüreğimin özüne, ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kanayan-yaram-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun', 'yorgun-i-smail-karakus-ahau0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geçip gitti en son nehir

Bir garip arya gürültüsü

Evrendeki

İç bunaltan sessizlik.

Takatinin kıyamete kurulu

Saatli bombaları.

Bitkinliğinde,

Devlerin izi var

Sevdalarını çalan cüceler de

Cabası...', 'Geçip gitti en son nehir Bir garip arya gürültüsü Evrendeki İç bunaltan sessizlik. Takatinin kıyamete kurulu Saatli bombaları. Bitkinliğinde...', ARRAY['Türk Edebiyatı','Şiir','İsmail Karakuş']::text[], 8.5, '{"poet":"İsmail Karakuş","poet_slug":"i-smail-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yorgun-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidersen Ağlamam', 'gidersen-aglamam-ayhan-erdem-bqwh1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüzümdeki hüzün değil

Yılların yorgunluğu sadece

Gözlerimdeki korku değil

Tedirginlik sadece

Üzülme ben ağlamam

Yeterki sen mesut ol.

Gözlerimdeki yaşlar

Yağmur damlası sadece

Saçlarımdaki aklar

Yağan karlar sadece

Üzülme ben ağlamam

Yeterki sen mesut ol.

Kaybetmenin korkusu

Bir dakika sadece

Giderken arkandan

Bakarım ben sadece

Üzülme ben ağlamam

Yeterki sen mesut ol.

(Ankara-01.01.2003)', 'Yüzümdeki hüzün değil Yılların yorgunluğu sadece Gözlerimdeki korku değil Tedirginlik sadece Üzülme ben ağlamam Yeterki sen mesut ol. Gözler...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Erdem']::text[], 8.5, '{"poet":"Ayhan Erdem","poet_slug":"ayhan-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gidersen-aglamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Dâveti Ve Bir Soru', 'dost-d-veti-ve-bir-soru-emine-senlikoglu-x5490', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gel kardesim diyorum, Rabbini dinle, 

Dünya gitmeyecek inan seninle.

Sulara darginmisın ki, guslün yok, 

o kadar nankör müsünki, sükrün yok.

Kör kütükte kayitin Islâm''dir ama

Islâm''in kütügünde belki kayitin yok.

Anamiz (Hz.)    Havva''dir, babamiz(Hz.)   Adem

Kimimiz nicin cevher, kimimiz neden maden? 

Bir fincan kahveye tesekkür eden sen, 

Yaratan''a nankörlük acaba neden? ? ?', 'Gel kardesim diyorum, Rabbini dinle,  Dünya gitmeyecek inan seninle. Sulara darginmisın ki, guslün yok,  o kadar nankör müsünki, sükrün yok....', ARRAY['Türk Edebiyatı','Şiir','Emine Şenlikoğlu']::text[], 8.5, '{"poet":"Emine Şenlikoğlu","poet_slug":"emine-senlikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dost-daveti-ve-bir-soru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Albümde Bir Fotograf', 'albumde-bir-fotograf-fatih-cinar-xg6pu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'eskiden daha güzelmişsin

gençliğim gibi

ki seninde gençliğin

ve geriye kalan bugün yüzünde çizgiler

belli sende geçmişsin o yollardan

ki benimde zamanında geçtiğim

ve çekmişsin fikir yolunda

benimde çektiğim pembe çileler', 'eskiden daha güzelmişsin gençliğim gibi ki seninde gençliğin ve geriye kalan bugün yüzünde çizgiler belli sende geçmişsin o yollardan ki ben...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/albumde-bir-fotograf-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Name-i Gurbet', 'name-i-gurbet-fatih-cinar-5hh3j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'vereyim önce hak selamını

öpeyim sonra al yanağını

görünce kağıda damlayan kanı

mektubumu alınca ağlama yarim

bilmek istersen birtek yarinden

gurbete uçtu güzel memleketinden

parelendi gönül ayrılığın derdinden

bir tatlı gülüşüne hasretim yarim

hayal oldu artık eski yıllarım

gurbet yollarında gezer ağlarım

hasretin dilinden iyi anlarım

doldurup çilemi birgün gelirim yarim

mertsin namusumu namusunda taşıdın

gündüz tokum dedin geceleri aç yattın

gülüşünü merhem edip yarelerim kapattın

kalemlerle yazılamazsın benim güzel yarim

uzatma garip ankaralı acı mektubu

bitmez hiç sevgilinin vuslat umudu

başımızda dolanadursun acı keder bulutu

güneş doğacak bir gün ufkumuza yarim', 'vereyim önce hak selamını öpeyim sonra al yanağını görünce kağıda damlayan kanı mektubumu alınca ağlama yarim bilmek istersen birtek yarinde...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/name-i-gurbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk Ağacı', 'mutluluk-agaci-salih-ozalasan-t652e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yeni yılıda bilme tanıma acıyı

Günlerin öyle mutlu geçsinki

Çatlasın tüm düşmanların

Dostlarının ebedi sen ol baş tacı

Hayatından kopmasın asla

Sevgili, anne, baba, evlat, bacı

Yüreğin olsun mutluluk ağacı

Asla yıkmasın kaderin kıskacı', 'Yeni yılıda bilme tanıma acıyı Günlerin öyle mutlu geçsinki Çatlasın tüm düşmanların Dostlarının ebedi sen ol baş tacı Hayatından kopmasın a...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mutluluk-agaci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmişime Dair...', 'gecmisime-dair-alper-altug-hpy2t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ayrı yollardaydık aslında

Senin yokluğunda ben ölümü kokladım buram buram...

Karanlığa açılan bir cennet perdesindeyim, 

yarın var mı yok mu bilmyorum

Uyuşturucu bütüm bedenime yayılıyor.

Yeşil bir dağdan aşağı düşüyorum

Rüzgar var hafif sarsılıp düşüyorum

Dünyam bir müzik seti kabininin üstünde dönüyor.

Düşünmek istiyorum düşünmemeyi nasıl sağlamak adına.

Çektiğim acılar artık yetmiyor kanıyan vücuduma

Boşluktayım belki de..

Boşluğunda boşluğunda....

Duyduklarım hissetiklerim değil

Hissetmek istediklerim

Duyduklarım değil

Belki''lerin üstüne kurulu bir yaşam....

Acı hissedebildiğim tek şey

Sen korkak azrail

Dediklerimi yaz ve oku

Oku kıyamet günü bütün insanlığa

Sebepsiz fırtına öncesi sessizlikte

Kulaklarım tıkalı

Tek seni dinliyorum

Sadece sen

Sen...

sen...

sen...', 'Ayrı yollardaydık aslında Senin yokluğunda ben ölümü kokladım buram buram... Karanlığa açılan bir cennet perdesindeyim,  yarın var mı yok mu...', ARRAY['Türk Edebiyatı','Şiir','Alper Altuğ']::text[], 8.5, '{"poet":"Alper Altuğ","poet_slug":"alper-altug","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gecmisime-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Megolaman', 'megolaman-alper-altug-t06n0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ve bu sefer her şey yolunda

Geçmişin karanlığından korkmuyoruz

Onlar ve olanlar

Yaptıkları bize zarar veremez

Birbirimize hiç bu kadar yaklaşmadık

Belki cesaretimiz yoktu

Belki sen yoktun

Ama şimdi burdasın....

Alper Altuğ öldü diyenlere

En güzel cevap 

...Varoluş

Bir evrim bir inkar

Kalemin gücü

Beynimin eseri

İnsanlığa bir tokat

Şimdi herşeyi inkar eden birisi

Şimdi korkak bir çocuk

Şimdi ölü bir beden....

Ondan korkmuyorum

Üstüne gidebilirim

Onu yenebilirim

Ama yinede tek bir kaybım olacak

Korkmamaktan korkmayı

Kaybedecem 

Ve bu beni sizden sıyıracak

Gezgin yıldızların altında büyüdüm

Tek başımaydım fakat yalnız değildim

Kimseden bir şey istemem

Kendi kendime yeterim

Ben hepsinden üstünüm 

Çünkü benim

Benim saat gibi işleyen bir

Sistemim ve Hücrelerine kan giden

Bir beynim var! ! !', 'Ve bu sefer her şey yolunda Geçmişin karanlığından korkmuyoruz Onlar ve olanlar Yaptıkları bize zarar veremez Birbirimize hiç bu kadar yakla...', ARRAY['Türk Edebiyatı','Şiir','Alper Altuğ']::text[], 8.5, '{"poet":"Alper Altuğ","poet_slug":"alper-altug","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/megolaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahu Gözlüm..', 'ahu-gozlum-cemal-safi-atwfq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ahu gözlüm böyle oyun

Duydum desem yalan olur.

Senden gayrı yare boyun

Eğdim desem yalan olur.

Erdim aşkın değerine, 

Yandım derinden derine, 

Seni bin leyla yerine, 

Koydum desem yalan olur.

Akışlarda bu coşkuyu, 

Nakışlarda bu dokuyu, 

Çiçeklerde bu kokuyu, 

Duydum desem yalan olur.

Vazgeç artık şu kuşkundan, 

Ne umarsın bu şaşkından, 

Ecel gelse yar aşkından, 

Caydım desem yalan olur.

Aciz olmak ne beter şey, 

Gene yoksun geldi hey hey, 

Her bakışın bir kadeh mey, 

Aydım desem yalan olur.

Dile kolay yedi sene, 

Son diyorsun öl desene, 

Yedi veren gül busene, 

Doydum desem yalan olur.', 'Ahu gözlüm böyle oyun Duydum desem yalan olur. Senden gayrı yare boyun Eğdim desem yalan olur. Erdim aşkın değerine,  Yandım derinden derine...', ARRAY['Türk Edebiyatı','Şiir','Cemal Safi']::text[], 8.5, '{"poet":"Cemal Safi","poet_slug":"cemal-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ahu-gozlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaktan Sevmek', 'uzaktan-sevmek-volkan-saban-jwbtw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana ulaşmak belki bir yıldıza ulaşmak kadar zordu

Seni sevmek bir gülün dikenine katlanmak gibi birşey belki

Seni beklemek ölümü beklemek gibi birşey

Ama ben; 

Ben hiç yılmadım seni sevmekten..

Ben hiç düşünmedim ayrılığı..

Ben hiç vazgeçmedim senden...

Sana ulaşmak bütün bu engelleri aşmakmıydı? 

Hayır...Hayır...

Sana ulaşmamı engelleyen sadece kahrolası yollar...

Ve sadece yıkılası dağlardı...

İkimizi birbirimizden koparan...

Oysa ben hep herşeye ümitle bakıyordum...

Her doğan günden sana kavuşmak gibi yeni umutlarım vardı...

Ama sen; 

Umutlarımı yıkmakla benide yıktın...

Hayatta en çok gücüne giden şeyi; 

Bir kalemde silmek gibi...

Beni silmek gibi..

Hayatından koparıp attın beni...', 'Sana ulaşmak belki bir yıldıza ulaşmak kadar zordu Seni sevmek bir gülün dikenine katlanmak gibi birşey belki Seni beklemek ölümü beklemek g...', ARRAY['Türk Edebiyatı','Şiir','Volkan Şaban']::text[], 8.5, '{"poet":"Volkan Şaban","poet_slug":"volkan-saban","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/uzaktan-sevmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağır Hasta', 'agir-hasta-fazil-husnu-daglarca-p5tlj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Üfleme bana anneciğim korkuyorum

Dua edip edip, geceleri.

Hastayım ama ne kadar güzel

Gidiyor yüzer gibi, vücudumun bir yeri.

Niçin böyle örtmüşler üstümü

Çok muntazam, ki bana hüzün verir.

Ağarırken uzak rüzgarlar içinde

Oyuncaklar gibi şehir.

Gözlerim örtük fakat yüzümle görüyorum

Ağlıyorsun, nur gibi.

Beraber duyuyoruz yavaş ve tenha

Duvardaki resimlerle, nasibi.

Anneciğim, büyüyorum ben şimdi,

Büyüyor göllerde kamış.

Fakat değnekten atım nerde

Kardeşim su versin ona, susamış.', 'Üfleme bana anneciğim korkuyorum Dua edip edip, geceleri. Hastayım ama ne kadar güzel Gidiyor yüzer gibi, vücudumun bir yeri. Niçin böyle ör...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 8.5, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/agir-hasta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adsız III', 'adsiz-iii-sertan-sarioglu-kryqg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen yoksun ya, kanıma işledi yoksulluk

sanki ben şimdi karanlıklarda ışıksız kalmışım, 

bir başıma başsız kalmışım sanki

sanki körmüşüm, görmüyormuşum da; 

uzatırken ellerimi yoluna

dudaklarına değmişim

ellerimden yüreğime giden yol, bir başıma

soluğun kadar uzak, dudakların kadar ıslak, 

sesin kadar yalın

ve yalnızdı....

keşke gitme diyebilseydim sana....

şimdi beni böyle çaresiz ve sürgün kılan

bedeninin bedenime açtığı yara.

ayağını sürüdüğün her yolda, 

bekliyorsam eğer, 

bu yürümek ötesi yorgunluk

bu nefessiz kalışlar bitsin diye değil

bu hasrettir, bu özlemek, bu acı; 

bu yoksulluğun kanıma işleyen yanı....', 'Sen yoksun ya, kanıma işledi yoksulluk sanki ben şimdi karanlıklarda ışıksız kalmışım,  bir başıma başsız kalmışım sanki sanki körmüşüm, gör...', ARRAY['Türk Edebiyatı','Şiir','Sertan Sarıoğlu']::text[], 8.5, '{"poet":"Sertan Sarıoğlu","poet_slug":"sertan-sarioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/adsiz-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son', 'son-sertan-sarioglu-86jrr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne yakınındayım, ne uzağında

öyle bir yer ki bulunduğum, burası

ne denizin kıyısında

ne ateşin ortasında

bana en yakın olan da

en uzak olan da sen, 

ne çıkar sen benim ellerimi sevmesen....', 'Ne yakınındayım, ne uzağında öyle bir yer ki bulunduğum, burası ne denizin kıyısında ne ateşin ortasında bana en yakın olan da en uzak olan ...', ARRAY['Türk Edebiyatı','Şiir','Sertan Sarıoğlu']::text[], 8.5, '{"poet":"Sertan Sarıoğlu","poet_slug":"sertan-sarioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/son-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Kangrenleri', 'dus-kangrenleri-sertan-sarioglu-0m4pa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölüm bir melodidir şimdi

kapı gıcırtısı, saatin tik-takları

silah sesleri, bir de ölü ıslıkları 

hiç dinmiyor: yaşam ve ölüm arasındaki ince iniltide

anılarsa, soluğu ensemizde bir akordur hayatın ezgisinde 

ne zaman geçmiş bir zaman kipi düşse dilime 

yakamda karanfiller, anmaya geliyorum 

seni ve kangrenleşen aşklarını ömrümün 

(yüreğimde platonik deprem kuşları 

pıhtılaşmış iklimlere göç ediyorken güz yağmurlarıyla; 

yağmurlar, 

bir hüzün serinliğinde yağmurlar...) 

bütün mezarlarda sen varsın, geleceğin var, bir de umudum

ölümün, ölümümdür yavrum, sevdamsım. 

(masallarımın mavi saçlı kızıydı, her gece yanımda yatar 

soluğumdan öperdi 

anılarını ve aşklarını sürüklerken ardından 

gözleri bağlı ve ıslaktı yanakları, 

masallardan geriye kâbuslar kaldı...)

her ayak sesinde sen varsın, yalnızlığım var 

karanlığın ortasından geliyor sesin 

sesini görmüyorum 

adımı soruyorlar bağcıksız gecelerde 

(duvarların neden sağır olduğunu bilmiyorum 

üşüyorum, kan kokuyor, bir de gözyaşı...) 

söylemiyorsun, 

soluğunu duyuyorum, ordasın hâlâ 

çıplaksın ve utanmıyorsun, 

(ne güzel hiç utanmıyorsun) 

sen yalnızlığımsın benim 

sessizliğimsin 

azıcık tutuversem elinden, 

çocuğum olursun, sevdiğim olursun, aşk olursun...

(masallarda kaldı oynadığımız oyunlar, 

artık sende benim gibi göç kokuyorsun)   

şimdi yalnız anılar kaldı senden bana 

bir ihtilal gibi zamansız gel-gitler 

ve armağan ettiğin kızıl düşgelimler kaldı 

sel gider, kum kalırdı ya 

kangrenleşen düşler kaldı bize yalnızca 

adına aşk dediğimiz o derin uykudan...', 'Ölüm bir melodidir şimdi kapı gıcırtısı, saatin tik-takları silah sesleri, bir de ölü ıslıkları  hiç dinmiyor: yaşam ve ölüm arasındaki ince...', ARRAY['Türk Edebiyatı','Şiir','Sertan Sarıoğlu']::text[], 8.5, '{"poet":"Sertan Sarıoğlu","poet_slug":"sertan-sarioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/dus-kangrenleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tokmak', 'tokmak-i-hsan-uncuoglu-xkp55', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'BUDUNUMUN  TOKMAĞIYIM



Sivri akıl sahibi yalan koşar hep sivride        

Her yerde oturur önden hak ister bir tepede      

Doğru ölçüyü bilmez ayağı eğrilere dönerde    

Aydınlıklar para etmez minareden elif yapar

Açık alına kara çalar bakmaz gözündeki merteğe, 

***

Keyiften kime şak şak alkış kime ağır taşlar 

Elden düşme yetersiz akıllarla hafif kıl kadar 

Çoğ yakadan kendin bilmez duyarsız nanem molla

Sakala bıyık katanlara arka çıkarsa meydanlarda

Analar ocağında sessiz ağlamaz bağrına taş basar 

Çizmeden yukarı çıkanın sakalını yunar yular yaparlar! ,', 'BUDUNUMUN  TOKMAĞIYIM Sivri akıl sahibi yalan koşar hep sivride         Her yerde oturur önden hak ister bir tepede       Doğru ölçüyü bilme...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tokmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığın Busesi', 'yalnizligin-busesi-erdogan-ciray-4c1b2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sus

Bir şey söyleme

Beyhude yorma kendini

Sen bu dünyanın kadını değilsin

Sen

Hayallerin ötesisin

Sessizliğin sesi

Yalnızlığın busesisin

Sen

Gerçeğin kendisisin

Şu gönlümün hevesi

Karanlığın gölgesisin

Velhasıl güzelim

Sen bu dünyanın kadını değilsin

Bak 

Gör eserini

İbreti alem içinde

Sen bu dünyanın kadını değilsin

Sen 

Hayallerin ötesisin

Sessizliğin sesi

Yalnızlığın busesisin

Sen

Gerçeğin kendisisin

Şu gönlümün hevesi

Karanlığın gölgesisin

Velhasıl güzelim

Sen bu dünyanın kadını değilsin

SEN TEK KİŞİLİK DÜNYANIN KADINISIN! ...', 'Sus Bir şey söyleme Beyhude yorma kendini Sen bu dünyanın kadını değilsin Sen Hayallerin ötesisin Sessizliğin sesi Yalnızlığın busesisin Sen...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çıray']::text[], 8.5, '{"poet":"Erdoğan Çıray","poet_slug":"erdogan-ciray","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yalnizligin-busesi-serbest-calisma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başım Dünyaya Yıkıldı', 'basim-dunyaya-yikildi-cemal-yaman-82wps', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni gördüğüm gün 

Ürkek bakışlı ceylanlar koşuşmaya başladı

Su başlarından

Seni sevdiğim gün

Kuru dallar çiçeklendi 

Binbir sürgün verdi dal uçlarından

Ve mutluluk döküldü 

Billur billur

Çocukların avuçlarından

Seni yitirdiğim gün 

Bir yiğit vuruldu 

Geçit vermez dağının eteklerinde 

Kapkara sevda okuyla

Ve bir türkü yakıldı 

Sevda üstüne 

Anadolunun bilmem hangi köyünde

Söylenir ha söylenir

Seni yitirdiğim gün 

Hanım Sultan, başım dünyaya yıkıldı

Başım dünyaya yıkıldı.', 'Seni gördüğüm gün  Ürkek bakışlı ceylanlar koşuşmaya başladı Su başlarından Seni sevdiğim gün Kuru dallar çiçeklendi  Binbir sürgün verdi da...', ARRAY['Türk Edebiyatı','Şiir','Cemal Yaman']::text[], 8.5, '{"poet":"Cemal Yaman","poet_slug":"cemal-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/basim-dunyaya-yikildi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Yıl Mesajı-2-', 'yeni-yil-mesaji-2-bayram-tunca-pwemu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dünkü hayallerini kurduğumuz yıllar bugün mazi oldu

Acı/tatlı hatıralarımızın hepsi, belleğimizde arşiv oldu

Hey dost bak güneş bu sabah bir başka gizemli doğdu

Seninle yeni bir yıla girmiş olmam beni sevince boğdu

B. Tunca/01.01.2003.10.01', 'Dünkü hayallerini kurduğumuz yıllar bugün mazi oldu Acı/tatlı hatıralarımızın hepsi, belleğimizde arşiv oldu Hey dost bak güneş bu sabah bir...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yeni-yil-mesaji-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Hâl Olmuş İnsanlara', 'bir-h-l-olmus-i-nsanlara-erdogan-ciray-jisah', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dost hatırı sorulmuyor

Parmak tetik yorulmuyor

Dalgalanmış durulmuyor

Bir hâl olmuş insanlara

Kin bürümüş gözlerini

Tutmuyorlar sözlerini

Unutmuşlar özlerini

Bir hâl olmuş insanlara

Sermayesi yalan riya 

Mutluluklar olmuş rüya

Amaçları dostluk güya

Bir hâl olmuş insanlara

****************************************

Yazmış olduğum bu şarkı sözü değerli sanatçımız Hüseyin ALTIN tarafından bestelenmiştir. Ancak stüdyo kaydı almak maalesef nasip olmamıştır.

Kendisine allahtan rahmet kederli ailesine başsağlığı diliyorum.

Şarkıyı youtube''dan paylaşarak halkımıza armağan eden kardeşimize de sonsuz teşekkürlerimi ve sevgilerimi sunuyorum.

ŞARKININ YOUTUBE LİNKİ: https://www.youtube.com/watch?v=joIAr5teTtw', 'Dost hatırı sorulmuyor Parmak tetik yorulmuyor Dalgalanmış durulmuyor Bir hâl olmuş insanlara Kin bürümüş gözlerini Tutmuyorlar sözlerini Un...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çıray']::text[], 8.5, '{"poet":"Erdoğan Çıray","poet_slug":"erdogan-ciray","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-hal-olmus-insanlara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağırma Beni', 'cagirma-beni-cumhur-turan-gka2u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'çağırma beni

gelemem ormanlarına

çağırma beni

içemem kaynaklarında su

çağırma beni

toplayamam ağacında meyvanı

çağırma beni

ben zaten ölmüşüm bir yerlerde

                        bir garip biçimde

                                          hem var

                                          hem yok olmuşum

çağırma beni

        çağırma

geceleri özellikle

       yalnızlığımda

       ısırırım ellerimi

              kan gelir oturur gözlerime

çağırma beni

          ne olur

                 çağırma', 'çağırma beni gelemem ormanlarına çağırma beni içemem kaynaklarında su çağırma beni toplayamam ağacında meyvanı çağırma beni ben zaten ölmüşü...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Turan']::text[], 8.5, '{"poet":"Cumhur Turan","poet_slug":"cumhur-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cagirma-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ecel Teri+', 'ecel-teri-bayram-tunca-7zuyx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yelkovan akreple öpüşüyordu

Yağmur toprakla öpüşüyordu

İkide bir de şimşek çakıyordu

Vefasız derin/derin uyuyordu

Hiç mi hiç böyle ıslanmamıştım

Hiç de böyle hastalanmamıştım

Sanki tenim sema/terim yağmur

Vücudum olmuştu, sanki hamur

Tir tir titremekteydi elim/ayağım

Tutmadı el/ayak eklem bağlarım

Yağmur gibi aktı tenimden terim

Her biri pınar oldu gözeneklerim

Sıkılsaydı çamaşırım ıslatırdı orayı

Çıksaydı avazım, çınlatırdı ortalığı

Kısılmıştı sesim/solmuştu benzim

Film şeridi gibi gelip geçti mazim

Dün gece, yine ecelle pençeleştim

Nefsim ve Azrail ”as”la cedelleştim

Ben zaten dünden razıydım ölmeyi 

Bekliyordum derin bir oof çekmeyi

Yaşamaktan ziyade ölmekti isteğim

Ölseydim, bir kere ölmüş olacaktım

Oysa, ben kaç defa ölüp ölüp dirildim

Nefsim dahil, ekseriyete çok yenildim

Bıktım artık ben şu âlemin eracifinden

Baksanız ya dört bir yanımızda katliam

Güçlüler güçsüze karşı olmuş yamyam

Var mı, arşa yükselen feryatları duyan

Olanlara ne tanık ne de sanık olmak isterdim

Asrımızda savaş değil, barış görmek isterdim

İhtimal ben de acele edip kışta gelenlerdenim

Vaatedilen yılları yeni neslimiz görsün dilerim

29.12.2002-02:29

NOT:

 Dün geceki rahatsızlığımın öyküsüdür.

''Aşk Ateşten Gömlek''', 'Yelkovan akreple öpüşüyordu Yağmur toprakla öpüşüyordu İkide bir de şimşek çakıyordu Vefasız derin/derin uyuyordu Hiç mi hiç böyle ıslanmamı...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ecel-teri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşümdeki Prenses', 'dusumdeki-prenses-erdogan-ciray-v2o5p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu gece de rüyamdasın

İnan bana harikasın

Bir yalanım varsa eğer

Allah şu canımı alsın

Yine seni seviyorum

Sana güller veriyorum

Alıp seni kollarıma

Dudağından öpüyorum

Yaprak gibi titriyorsun

Al kalbimi git diyorsun

Öyle candan sevmişsin ki

Herşeyini veriyorsun

Sevincimden uçuyorum

Neşe huzur saçıyorum

Unutup derdi tasayı

Aşka kucak açıyorum

Gün doğmadan gidiyorsun

Bana veda ediyorsun

Ayrılmadan son bir defa 

Sarıl bana öp diyorsun

Gözlerimi kapıyorum

Dediğini yapıyorum

Öyle güzel bir duygu bu

Yarim sana tapıyorum', 'Bu gece de rüyamdasın İnan bana harikasın Bir yalanım varsa eğer Allah şu canımı alsın Yine seni seviyorum Sana güller veriyorum Alıp seni k...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çıray']::text[], 8.5, '{"poet":"Erdoğan Çıray","poet_slug":"erdogan-ciray","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dusumdeki-prenses-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Davetsiz Misafir', 'davetsiz-misafir-erdogan-ciray-0efd2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Davetsiz misafir gibi zamansız

Sevdan öyle zor ki öyle amansız

Sensiz yaşayamam artık imkansız

Çekip gittiğin gün bittiğim gündür

Söküp yüreğimden nasıl atarım

Sen diye resmini öper yatarım

Her gün senle doğar senle batarım

Çekip gittiğin gün bittiğim gündür

Sonumuz ne olur bilemiyorum

Sensiz bir an bile gülemiyorum

Bir adım sonramı göremiyorum

Çekip gittiğin gün bittiğim gündür', 'Davetsiz misafir gibi zamansız Sevdan öyle zor ki öyle amansız Sensiz yaşayamam artık imkansız Çekip gittiğin gün bittiğim gündür Söküp yüre...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çıray']::text[], 8.5, '{"poet":"Erdoğan Çıray","poet_slug":"erdogan-ciray","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/davetsiz-misafir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çizgi', 'cizgi-nurten-ceranoglu-fcsvs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'B ir çizgi daha çizilmiş, 

Ömrümün üstüne.

Biliyorum asla dönmeyecek geriye, 

Günler nankör, saatler düşman sanki.

Geçmeyin, gitmeyin ne olur dedim.

Daha yapacak çok işim var benim.

Niye hızlandınız birden? 

Neden bu telaş bu çizgiler? 

Daha dün gibiydi sanki, 

Halamın anlattığı hikayeler, 

Piknikte yediğim pamuk şeker, 

Tepeyi çıkarken yorulduğum okul yolları.

Meğer onlarda çizilmiş birer birer, 

Farkına varmadan nasılda geçmiş günler.

İster sitem et, ister dövün nafile, 

Bir çizgi daha çizilmiş ömrümün üstüne.', 'B ir çizgi daha çizilmiş,  Ömrümün üstüne. Biliyorum asla dönmeyecek geriye,  Günler nankör, saatler düşman sanki. Geçmeyin, gitmeyin ne olu...', ARRAY['Türk Edebiyatı','Şiir','Nurten Ceranoğlu']::text[], 8.5, '{"poet":"Nurten Ceranoğlu","poet_slug":"nurten-ceranoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cizgi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kumda Oyna', 'kumda-oyna-erdogan-ciray-d0sgh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aklın fikrin hep oyun

Değişmedi hiç huyun

Neden eyeyim boyun

Sen gitte kumda oyna

Boşa dönsün çarkımız 

Ağıt olsun şarkımız

Yeter bitsin aşkımız

Sen gitte kumda oyna

Unutturdun gülmeyi

Arattırdın ölmeyi

Bırak umut vermeyi

Sen gitte kumda oyna', 'Aklın fikrin hep oyun Değişmedi hiç huyun Neden eyeyim boyun Sen gitte kumda oyna Boşa dönsün çarkımız  Ağıt olsun şarkımız Yeter bitsin aşk...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çıray']::text[], 8.5, '{"poet":"Erdoğan Çıray","poet_slug":"erdogan-ciray","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kumda-oyna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Dostları', 'gonul-dostlari-nurten-ceranoglu-aifsv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gece mehtap bir bambaşka, 

Oturduk dostlarla başbaşa.

Çimlerin üstünde ılık yaz akşamı, 

Neredesiniz ey gönül dostları? 

Gönüller tek bir nağme olmuştu, 

Seslerimiz gecede huzur bulmuştu, 

Tanıdık tanımadık arkadaş olmuştu, 

Neredesiniz ey gönül dostları? 

Yaz akşamları bir başka orada, 

Fenerbahçe parkında şarkılar burada, 

Şahitti deniz ve dalgalarda, 

Neredesiniz ey gönül dostları? 

Hatırladınızmı şimdi o günleri? 

Zaman dursada dönsek yine geri, 

Şarkılar nağmeler hep bekler bizi, 

Neredesiniz ey gönül dostları?', 'Gece mehtap bir bambaşka,  Oturduk dostlarla başbaşa. Çimlerin üstünde ılık yaz akşamı,  Neredesiniz ey gönül dostları?  Gönüller tek bir na...', ARRAY['Türk Edebiyatı','Şiir','Nurten Ceranoğlu']::text[], 8.5, '{"poet":"Nurten Ceranoğlu","poet_slug":"nurten-ceranoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gonul-dostlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlüm Varmıyor', 'gonlum-varmiyor-erdogan-ciray-rnl6u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kilitlendi ağzım tutuldu dilim

Bomboş kaldı kalbim bomboş bak elim

Gittiğin o günden beri sevgilim

Gülüp eğlenmeye gönlüm varmıyor

Aydınlık dünyamız karardı birden

Bir selam göndersen gittiğin yerden

Sevdan eksilmiyor dumanlı serden

Başka yar sevmeye gönlüm varmıyor

Gözümde hayalin elimde resmin

Dudağımda içli bir şarkı ismin

Kulağımda çınlar dururken sesin

Gülüp eğlenmeye gönlüm varmıyor', 'Kilitlendi ağzım tutuldu dilim Bomboş kaldı kalbim bomboş bak elim Gittiğin o günden beri sevgilim Gülüp eğlenmeye gönlüm varmıyor Aydınlık ...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çıray']::text[], 8.5, '{"poet":"Erdoğan Çıray","poet_slug":"erdogan-ciray","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gonlum-varmiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim Nigar', 'sevgilim-nigar-muzaffer-taskirmaz-s3a2h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gelirsin diye, yolunu bekledim

O bakışını, gülüşünü özledim

Yaz mevsimi boyunca, seni bekledim

Resmine bakıp bakıp, seni özledim

Yine bahar geldi, açtı çiçekler

Tahammülüm kalmadı, uzadı geceler

Aylar yıllar geçti, bitsin ayrılıklar

Seni çok özledim, sevgilim Nigar

Ne zaman bitecek, ayrılık Nigar

Ömrümde kalmadım, böyle yadigar

Bir bahar yeli gibi, esti rüzgar

Sanki nisan yağmuru, eridi kar', 'Gelirsin diye, yolunu bekledim O bakışını, gülüşünü özledim Yaz mevsimi boyunca, seni bekledim Resmine bakıp bakıp, seni özledim Yine bahar ...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgilim-nigar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Ayrılıklar', 'bu-ayriliklar-muzaffer-taskirmaz-u0j5e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzaklardan bir gelen, gelen mi var? 

Söyleyin yarimden, haber mi var? 

Kalbimde titreyen, ellerin mi var? 

Göz yaşımı silen, mendilin mi var? 

Ümitle doluydu, yaşanan günler

Mazimizde kalan, en güzel günler

Bak yine ağlıyor, o mutlu yıllar

Derbeder ediyor, bu ayrılıklar

Kaderimle baş başa, kaldım şimdi

Sırdaş oldu  bana, yalnızlık şimdi

Mechule dönderdin, aşkımı şimdi

Gönlümde yaşıyor, acılar şimdi', 'Uzaklardan bir gelen, gelen mi var?  Söyleyin yarimden, haber mi var?  Kalbimde titreyen, ellerin mi var?  Göz yaşımı silen, mendilin mi var...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bu-ayriliklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim', 'kalbim-muzaffer-taskirmaz-1r2ut', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine hüzünlü esti rüzgar, çok dertli

Yine kalbimde, ayrılığın hissi var

Niçin hüzünlü, düşünür dersen bana

Yarim beni bekler, sayılı günler var 

Gözlerimden süzülen, yaşa baksana

Ağlıyorsun deme, dayanamam yoksa

Hasretlik zor geldi, inan sen bana

Bak şu gözlerime, anla beni sevgilim

İçimde kor alev yanar, arşa püskürür 

Sanki volkan seli, alev gibi yanar

Ayrılığa dayanamam, çok zor gelir

Kalbim dayanamaz buna, anla sevgilim', 'Yine hüzünlü esti rüzgar, çok dertli Yine kalbimde, ayrılığın hissi var Niçin hüzünlü, düşünür dersen bana Yarim beni bekler, sayılı günler ...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kalbim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne zaman Bitecek', 'ne-zaman-bitecek-muzaffer-taskirmaz-a26hj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu günleri sensiz, ben nasıl yaşadım

Hasretine dayanmak, zulüm oldu bana

Bak yine neler söylüyor, bu günler

Uzadı günlerin, birkaç gün daha bekle

Bu düşüncelerden, nasıl kurtulurum ben

Sanki saatler durdu, çalışmıyor zaman

Uzadı geceler, güneş batmak bilmiyor

Bekliyorum son günleri, ne zaman bitecek

Sanki buraları, mesken tutmuşum

Bırakmıyor yakamı, gitme diyor

Özlem dolu günler, gözümde tütüyor

Nasıl gitmem ki, sevgili yarim bekler', 'Bu günleri sensiz, ben nasıl yaşadım Hasretine dayanmak, zulüm oldu bana Bak yine neler söylüyor, bu günler Uzadı günlerin, birkaç gün daha ...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ne-zaman-bitecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garib Asker', 'garib-asker-muzaffer-taskirmaz-tyyov', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sessiz adalarda, sensiz neyler bu garib

Yavru vatan KIBRIS''ta askerdir garib

Çok sevdiği ailesinden uzak bu garib

Her gece düşünür, yine hüzünlü garib

Anası, babası, kardeşlerin hep yolunu beklerler

Sevgili eşini unuttu sanma, iple çeker gününü

Bir tek yavrusu var, babam asker der

Mektubunuzu okudukça, yüreğim sızlar

Bazı günler rüyadayım, biliniz ki yanınızdayım

Sabah olur, kalk denilir, yanılmışım KIBRIS''tayım

İçime düşer bir sızı, umutsuz yine bu garib asker

Daha çok bekler, gelmez ki bu altı ay

Geçmiyor günler, geçmek bilmiyor

İki seven aşığın, ümidi olmuyor

Sen orada garib, ben burada garib

Garibim çilemmiş, günlerim hiç geçmiyor', 'Sessiz adalarda, sensiz neyler bu garib Yavru vatan KIBRIS''ta askerdir garib Çok sevdiği ailesinden uzak bu garib Her gece düşünür, yine hüz...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/garib-asker-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askerim', 'askerim-muzaffer-taskirmaz-2ll6a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senden ayrı yaşamak, hiç gelmezdi aklıma

Bir umutsuzluğa kapıldım, çaresizim dertliyim

Çok düşünceli oldum, günlerim çok daha

Sensiz bu geçen günlerim, zehir oldu bana

Bu gurbetlik zor geldi, dayanamam buna

İçimde bir his, kavuşmamıza çok daha

Bu günler geçer mi, umutsuzum sevgilim

Geri kalan yetmiş gün, sanki yetmiş yıl

Bir şiir oldu aşkımız, hiç tadı kalmadı

Sayfalara sorsan da, anlatamaz ki derdimi

Leyla olsan, aslı olsan anlayamazsın derdimi

Bana bir yol göster, mecnun değil askerim

Eski günlerin hayali ile yaşıyorum KIBRIS''ta

Yoksa ne gezerim, Ercan''da, Kırklar''da

Bir gün gelir hayal olur, umutsuzluk sona erer

O günü sabırsızlıkla bekler, sevgilini unutma', 'Senden ayrı yaşamak, hiç gelmezdi aklıma Bir umutsuzluğa kapıldım, çaresizim dertliyim Çok düşünceli oldum, günlerim çok daha Sensiz bu geçe...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/askerim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Mektup', 'sevgiliye-mektup-muzaffer-taskirmaz-yeg8b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir bahtiyar gencim, şu dillerde

Gurbette ayrılık varmış, yaban illerde

Söyle sevgilim, özlemiş isen beni

Kuşlar gibi uçarak, geliyorum sana

Karadır bahtım karalı

Gönlüm hüzünlü ve yaralı

Yardan uzak olalı bir hal oldum

Sevgilim ağlıyor nazlı nazlı

Bu sözlerimle üzdümse beni

Mektuplarımın sözleriyle eylemi

Seni güldürüyorsa muhabbetim emi

Mazide kaldı artık sevgilim anla beni', 'Bir bahtiyar gencim, şu dillerde Gurbette ayrılık varmış, yaban illerde Söyle sevgilim, özlemiş isen beni Kuşlar gibi uçarak, geliyorum sana...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgiliye-mektup-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle Beni»', 'bekle-beni-konstantin-simanov-b6wen', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karlar tozarken bekle 

Ortalık ağarırken bekle 

Kimseler beklemezken bekle beni 

-K.Simonov', 'Karlar tozarken bekle  Ortalık ağarırken bekle  Kimseler beklemezken bekle beni  -K.Simonov...', ARRAY['Türk Edebiyatı','Şiir','Konstantin Simanov']::text[], 8.5, '{"poet":"Konstantin Simanov","poet_slug":"konstantin-simanov","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bekle-beni-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimbilir', 'kimbilir-muzaffer-taskirmaz-6p6m9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kim bilir gözlerin nasıl doluyor

Dönüp de maziye baktığın anlar

Kim bilir ellerin nasıl titriyor

Eski resimlere baktığın anlar

                

Unuttum deme hiç, unutmaz yaşayan

Bir aşkı bir ömre, değişmez insan

Anarsın maziyi, kalpsizde olsan

Başını yastığa koyduğun anlar

Kim bilir, belki de şu an ağlıyorsundur

Durup ta, maziye daldığın anlar kim bilir 

Sen nasıl yanılıyorsundur, kim bilir

El ele gezeni gördüğün anlar, kim bilir', 'Kim bilir gözlerin nasıl doluyor Dönüp de maziye baktığın anlar Kim bilir ellerin nasıl titriyor Eski resimlere baktığın anlar              ...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kimbilir-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Özlermisin', 'beni-ozlermisin-muzaffer-taskirmaz-nml42', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Duydukça rüzgarda, tatlı sesini

İçimde açılan, yaram kanıyor

Hayal kaldırınca tül perdesini

Gözüm gözlerini, şimdi arıyor

Ruhumda gurbetin, zehri taşarken

Rüzgarla sevincim, her an koşarken

Senden uzaklarda, sensiz yaşarken

Dudağım her zaman, ismini anıyor

Düşünür müsün sen, seni düşündüğüm kadar 

Beni yaşar mısın, seni yaşadığım kadar

Hatırlar mısın beni, gece ve gündüzünde 

Beni özler misin, seni özlediğim kadar', 'Duydukça rüzgarda, tatlı sesini İçimde açılan, yaram kanıyor Hayal kaldırınca tül perdesini Gözüm gözlerini, şimdi arıyor Ruhumda gurbetin, ...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/beni-ozlermisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Hayal Gelir', 'sana-hayal-gelir-muzaffer-taskirmaz-iikuc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bak yine soldu güneş, yine akşam oluyor

Ömrümün kadehine, sensiz bir gün doluyor

Sen yoksun diye inan, dertliyim kederliyim

Gelmezsen kahrolurum, yıkılırım sevgilim

Gündüzleri seni, düşünmekten usandım 

Geceleri rüya, görmekten kahroldum

Sana yalan gelir, ağlamaktan yoruldum

Sense bilmem ki, sana hayal gelir

Çok mu uzaklardasın, söyle ben geleyim

Derdine dermanına, ben de ortak olayım 

Gözlerden uzak olan, yardan ırak olur derler

Bırak artık dargınlığı, yeniden başlayalım', 'Bak yine soldu güneş, yine akşam oluyor Ömrümün kadehine, sensiz bir gün doluyor Sen yoksun diye inan, dertliyim kederliyim Gelmezsen kahrol...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sana-hayal-gelir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hez Zaman', 'hez-zaman-muzaffer-taskirmaz-o2ksl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bak ayrılık çanları çalıyor, bize yine 

Sus ağlama sil gözyaşlarını, darılırım

Mazide kalan, garip dostların seninle

Seni her zaman anıyor, unutmuyor

Yarabbi ne zor olurmuş, yardan ayrılmak

Uykusuz geçen geceler, zehir oldu bana

Yalnız ve boş saatler, geçmek bilmiyor

Bunu yalnız kalınca anladım, çok zormuş

Gurbet derlerdi de, bana kolay gelirdi             

Bunu yaşayan bilir, ancak bir de ben

Çekilmiyor artık, sensiz geçen günler

Tuttuğum her dal, kırılıyor birer birer', 'Bak ayrılık çanları çalıyor, bize yine  Sus ağlama sil gözyaşlarını, darılırım Mazide kalan, garip dostların seninle Seni her zaman anıyor, ...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hez-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidemem', 'gidemem-muzaffer-taskirmaz-nmmi2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''Bir sel gibi akıp giden, insan yaşantısında

 Geriye kalan yalnız tatlı hatıralardır, gülümseme

 Şayet bu tatlı hatırayı yaşayabildiysek ne mutlu bize''

Hatıra yaşadım dedim sana, anlamak istenmedin 

Kalemim yazmadı dertlerimi, sen dinlemedin

Bırakıp gideyim dedim seni, ayaklarım bağlandı

Ellerin bırakmadı ellerimi, yapıştı kaldı çözemedim

Bakmak istedim gözlerine, büyüledin beni

Perçinledin gözlerimi, ayıramadım bir türlü

Seni gelinlikle görmek istemedim, başkasıyla 

Bırakıp gitmek istedim, kapılar kapalı gidemedim 

Sensiz olmazmış hayat, bunu yeni anladım

Gurbetin kahrını çekmek, daha da zor olur

Seni kaybetmek mi asla, ben o an yıkılırdım

Sanki bağlanmıştım sana, kalkıp gidemedim', '''Bir sel gibi akıp giden, insan yaşantısında  Geriye kalan yalnız tatlı hatıralardır, gülümseme  Şayet bu tatlı hatırayı yaşayabildiysek ne ...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gidemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim Seni', 'ozledim-seni-muzaffer-taskirmaz-mbgik', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir mektup istiyorum, beni sevenimden

Seviyorum diye başlayan, sevgisi bitmeyen

Sensiz olmam diye, devam eden kelimelerle 

Çok özledim seni, dön diye biten günlerden

Dün gelecek diye beklenen, yarini özleyen

Bir türlü gelmeyi bilmeyen, sevgili yardan

Cevabını bekliyorum, hasret gidermek için

Beni kollarına alıp, bedenimi sarsın diye

Gözlerim doluyor, mektubunu okudukça

Yüreğim kan ağlıyor, hasretliğin çok zor

Sensiz olmak da, yaban gülü dikeni gibi

Hayalle yaşadığım, bu günler ölüm bana', 'Bir mektup istiyorum, beni sevenimden Seviyorum diye başlayan, sevgisi bitmeyen Sensiz olmam diye, devam eden kelimelerle  Çok özledim seni,...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ozledim-seni-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoksun', 'sen-yoksun-muzaffer-taskirmaz-xtlk5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ay ışığı vurmuş sen yoksun, nerelerdesin

Cümle dağlar selam durmuş, yine sen yoksun

Mor salkımlı leylaklar altında, beklerken seni 

Garip gönlüm bağdaş kurmuş, yine sen yoksun

Kimse bilmez derlerimi, perişan oldum

Gülen yüzüm hiç gülmüyor, seni arıyor

Dertlerimle baş başa kaldım, ben yalnızım 

Dünya umurumda değil, ben sensizim

Hayal ediyorum, bir gün döneceksin

Ümit ediyorum, sen bana geleceksin

Ben sensiz, hiç olamamam diyeceksin

Gözlerime bakıp, aşkım sonsuz diyeceksin', 'Ay ışığı vurmuş sen yoksun, nerelerdesin Cümle dağlar selam durmuş, yine sen yoksun Mor salkımlı leylaklar altında, beklerken seni  Garip gö...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-yoksun-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiklerimizi Arar', 'sevdiklerimizi-arar-muzaffer-taskirmaz-6y2f0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Denizin enginlerine, çekilirken dalgalar

Tüm sahili kaplar, atılan şen kahkahalar

Çılgın bir sevinçle, eğlenirken dalgalar

Kalbimiz özlem dolu, sevdiklerimizi arar

Güneş doğarken, birden kalabalık

Sahilde ses çıkaran martılar, kuşlar

Onlar da kendi aleminde, dertlenir   

İçi sevinç dolu, sevdiklerini ararlar

Gök yüzündeki yıldızlar, güneş ve ay

Kurulu bir düzeni var, ayrılmaz ki onlar

Ayrılık ancak, aşkı yaşayan mecnunda mı 

İçimiz hüzün dolu, sevdiklerimizi arar', 'Denizin enginlerine, çekilirken dalgalar Tüm sahili kaplar, atılan şen kahkahalar Çılgın bir sevinçle, eğlenirken dalgalar Kalbimiz özlem do...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevdiklerimizi-arar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bana Gel', 'sen-bana-gel-muzaffer-taskirmaz-jaolh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İster esen rüzgarla gel, sen bilirsin

İster gökyüzündeki, yıldızlarla birlikte

İster denizin mavileşen, dehşetiyle 

Derinliğinde kuduran, dalgalarla gel

İster yağmurlu bir havada, sen bana gel 

İstersen göçmen kuşlarla, birlikte gel

İstersen eriyen buzullarla, dön bana gel

Şimşekler çakarken, rüzgarlar eserken

Mutlaka seni bekliyorum, dönersin diye

Yoluna kır çiçeklerini serdim, gelirsin diye

Kapıma aşk zilini taktım, çalarsın diye

Seviyorsan beni eğer, koşarak gelirsin bana', 'İster esen rüzgarla gel, sen bilirsin İster gökyüzündeki, yıldızlarla birlikte İster denizin mavileşen, dehşetiyle  Derinliğinde kuduran, da...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-bana-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Ömrüm', 'benim-omrum-muzaffer-taskirmaz-5uqnc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Batan her güneş, bana hüzün verir

Biten her an, bende bir başka acıdır

Çünkü sensiz her günüm, ayrı çile

Hep aynı gurbet acısıdır, benim ömrüm

İşte böyle geçer, hayal ederek

Senden çok uzakta, yalnız günlerim 

Bazen hüzün, bazen sevinç dolu

Sensiz geçip gidiyor, benim ömrüm

Dertliler diyarından, söyle haber mi var

Sevgililer gününden, bana mesaj mı var

Geçmişte kalan hatıralardan, özlem mi var

Hep aynı gurbet acısıdır, benim ömrüm', 'Batan her güneş, bana hüzün verir Biten her an, bende bir başka acıdır Çünkü sensiz her günüm, ayrı çile Hep aynı gurbet acısıdır, benim ömr...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/benim-omrum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabul Edermisin', 'kabul-edermisin-muzaffer-taskirmaz-wl2x6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düşsem yollarına, ağlasam ardından

Geri dönüp de, ağlama der misin sen

Senin için sakladım, bir tek kelime

Sevgilim ol desem, kabul eder misin

Benim için, bir tek sen varsın

Kalbim de açan, gonca gülsün

Deniz de coşan, dalgalar gibisin

Havada uçuşan, martılar gibisin

Düşünmeni istemem, cevabı ver bana

Ben de biliyorum, seviyorsun sen beni

Bu aşkı gizlemediğin, halinden belli

Bir başkası olamaz, seviyorum seni', 'Düşsem yollarına, ağlasam ardından Geri dönüp de, ağlama der misin sen Senin için sakladım, bir tek kelime Sevgilim ol desem, kabul eder mis...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kabul-edermisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretin Ne Kadar zor', 'hasretin-ne-kadar-zor-muzaffer-taskirmaz-pbci1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kalbim seni, unutacak kadar adi ise

Ellerim onu, parçalayacak kadar asil

Gözlerim, görmeyecek kadar nankör ise

Gönlüm onu, kör edecek kadar sefil

Nereden bilirdim, yalnız kalacağımı

Aklımdan geçmezdi, senin gideceğin

Beni hatıralarımla, yalnız bırakacağın

Ben de terk eder, giderim bu şehir'' i 

Hasret ne kadar zor, yalnız bırakılmak

Yardan ayrı düşmek, daha da zor

Sensiz buralarda yaşamak, ölümden zor

Bunu ancak yaşayan bilir, sen bilemezsin', 'Kalbim seni, unutacak kadar adi ise Ellerim onu, parçalayacak kadar asil Gözlerim, görmeyecek kadar nankör ise Gönlüm onu, kör edecek kadar ...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hasretin-ne-kadar-zor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Mutlu Günüm', 'en-mutlu-gunum-muzaffer-taskirmaz-kuzia', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senin için varım ben, gönlümde yok başkası

Dünyayı verseler bana, ben sensiz olamam

Sensizlik matemi içinde, yaşadım bu günleri

Yoksa dünya bana, zehir olurdu sen olmasan

Her zaman hayal içinde yaşadım, seni düşündüm

Bir gün olsun dinmedi, kalbimdeki sevincim

Hep özlemekle geçti, sensiz geçen günlerim

Sana kavuşacağım o an, benim en mutlu günüm

Belki sana hayal gelir, düşünürsen zor gelir

Bu yaşamın çarkında, dönmek kolay mı gelir

Attığım her adım da, sana yaklaşırım ben

Uzayan gecelerin, sabahını beklerim ben', 'Senin için varım ben, gönlümde yok başkası Dünyayı verseler bana, ben sensiz olamam Sensizlik matemi içinde, yaşadım bu günleri Yoksa dünya ...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/en-mutlu-gunum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Işığı Vurmuş', 'ay-isigi-vurmus-muzaffer-taskirmaz-lq56m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ay ışığı vurmuş, sen yoksun nerelerdesin

Cümle dağlar selam durmuş, sen yoksun

Mor salkımlı leylaklar altında, seni beklerken

Garib gönlüm bağdaş kurmuş yine sen yoksun

Gökyüzüne baktım, yıldızlar kaybolmuş

Meğer üzerini, kara bulutlar bürümüş

Yalnızlık ne kadar zor, bunu şimdi anladım

Yarimin hasret kokusu, burnuma tütüyor

Sen beni kahrımdan, öldürecek misin 

El aleme beni, rezil edecek misin 

Hiç sesin çıkmıyor, nerelerdesin 

Sen beni yaşamadan, öldürecek misin', 'Ay ışığı vurmuş, sen yoksun nerelerdesin Cümle dağlar selam durmuş, sen yoksun Mor salkımlı leylaklar altında, seni beklerken Garib gönlüm b...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ay-isigi-vurmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-muzaffer-taskirmaz-ubpp5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O eski mutlu günleri, hatırladıkça

Mehtaplı gecelerin, tatlı anını

İçimde bir korku var, şu an sevgilim

Yalnızlıktan başka nedir, söyle sevgilim

Yüzüm güler ama, içim kan ağlar 

Derdime çare bul, sensizliğime

Gücüm yok dermanım, sana geleyim

Perişan haldeyim, ben derbederim

          

Seni benden aldılar, yalnız bıraktılar

Öyle sarhoşum ki, kendime gelemedim

Korku içindeyim, kaybolmuş biriyim 

Yalnız bu sokaklarda, sensiz yürüyorum', 'O eski mutlu günleri, hatırladıkça Mehtaplı gecelerin, tatlı anını İçimde bir korku var, şu an sevgilim Yalnızlıktan başka nedir, söyle sevg...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensizlik-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Bana Dar Gelir', 'dunya-bana-dar-gelir-muzaffer-taskirmaz-da32u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir masal oldu aşkımız, bunu herkes biliyor 

Bak şiir oldu şarkımız, dillerde söyleniyor

Bu beklenen hasretlik, artık kahrı çekilmiyor

Özlemi doldu sevgilim, dünya bana dar gelir

Sanki bana hayal gelir, dün ayrıldık rüya gelir

Geriye dönüp bir bakarsan, yıllar sayılı gelir

Gerçek olan sevgiye, dayanmaz vız gelir

İki seven arasına girmek, lüzumsuz gelir

Uzaklardan bir rüzgar esti, sen geldin sandın

Uyandım rüya imiş, yine kalbim de hüzünlü

Bitsin artık ayrılık, dayanamaz haldeyim ben

Bunca çektiğimiz çile, bu bize çok bile', 'Bir masal oldu aşkımız, bunu herkes biliyor  Bak şiir oldu şarkımız, dillerde söyleniyor Bu beklenen hasretlik, artık kahrı çekilmiyor Özlem...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dunya-bana-dar-gelir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anla Beni', 'anla-beni-muzaffer-taskirmaz-9ylf4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bahçeden gül koparıp, sana verdiğimde

Kalbimin bir parçasını, sana verdim bebeğim

Hep yolunu bekledim, aradım her zaman 

Unutmadım seni, ne olur anla beni bebeğim

Sen benim yanımda, dalda duran çiçeksin

Bir dalını kopartsalar, üzülürüm bebeğim

Sana bir söz söyleseler, kıskanırım bebeğim

Senin kalbini çalsalar, yıkılırım bebeğim

Gözlerim senden başkasını, görmek istemez

Kulağım senden başkasını, duymak istemez

Ayaklarım senden başkasına, gitmek istemez

Unutamadım seni güzelim, anla beni bebeğim', 'Bahçeden gül koparıp, sana verdiğimde Kalbimin bir parçasını, sana verdim bebeğim Hep yolunu bekledim, aradım her zaman  Unutmadım seni, ne ...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anla-beni-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdemi Yaşamak İsterdim', 'nerdemi-yasamak-i-sterdim-muzaffer-taskirmaz-fer16', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Neredemi yaşamak isterdim? Söylesem mi

Yemyeşil bir ova da, kimselerin olmadığı yerde 

Kavak ve söğüt ağaçlarının, bulunduğu yerde

Billur gibi bir dere kenarında, kalmak isterdim

O yemyeşil dağların, eteklerinden sana gelmek için

Ovaya doğru özgürcesine, koşmak isterdim

İnsanlar yaşamlarında, küçük bir aydınlık isterler 

Bulduklarında ya çok geçtir, yada çok erken

Gözlerimde canlandı bir an, senin eski hatıraların

Yağmurlu günü hatırlar mısın, nasıl ıslanmıştık

Cadde de yürürken, kaldırım kenarında 

Sırılsıklam olmuştuk, gülüyordu herkes bize', 'Neredemi yaşamak isterdim? Söylesem mi Yemyeşil bir ova da, kimselerin olmadığı yerde  Kavak ve söğüt ağaçlarının, bulunduğu yerde Billur gi...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nerdemi-yasamak-isterdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemek Güzeldir', 'ozlemek-guzeldir-muzaffer-taskirmaz-6mjlw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Özlemek güzeldir, Özlüyorsa özlenen

Sevmek güzeldir, seviyorsa sevilen

Beklemek güzeldir, gelecekse beklenen

Yaşamak güzeldir, yaşıyorsa yaşayan

Sanki sesini duydum, esen rüzgardan

Bir umut bekliyorum, ben yarimden

Bir anda kayboldu, o güzel sesin

Şaşkın aşıklar gibi, kahroldum sevgilim

Bir gün düşünce, sararsa kalbimi

Bil ki sevgilim, seni düşünüyorum

Hayalimde bile, seni yaşıyorum

Kalbimde her an seni yaşatıyorum', 'Özlemek güzeldir, Özlüyorsa özlenen Sevmek güzeldir, seviyorsa sevilen Beklemek güzeldir, gelecekse beklenen Yaşamak güzeldir, yaşıyorsa yaş...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ozlemek-guzeldir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorulmuşum', 'yorulmusum-muzaffer-taskirmaz-qjzfd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir hatıra hayaldir, bu son resim senden bana

Tanrım neden ayırdın, bizim gibi sevenleri

Bir köşesi ıslanmış, üstelik de yırtılmış

Sanki o da ağlamış, bitmeyen aşkımız

Unutmadım o günleri, unutmadım o yılları

Kalbimde damla damla, birikti ızdıraplar

Yoruldu gözlerim, akar sel gibi yaşlar

Yavrusunu bekleyen, kanadı kırık kuşlar

Yılları beklemekten, bıktım yorulmuşum

Yıllara küstüm şimdi, ne olacak hayatta

Ben sensiz yaşamaktan, bıktım usandım 

Yıllara küstü gönlüm, ne olacak hayatta

Yolunu beklemekten, bıktım yorulmuşum

Hayalinle yaşamaktan da, artık usanmışım

Dönüyorsan dön artık, bıktım usanmışım

Kaderime küstü gönlüm, artık yorulmuşum', 'Bir hatıra hayaldir, bu son resim senden bana Tanrım neden ayırdın, bizim gibi sevenleri Bir köşesi ıslanmış, üstelik de yırtılmış Sanki o d...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yorulmusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıkılırım', 'yikilirim-muzaffer-taskirmaz-kagex', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bak yine soldu güneş, yine akşam oluyor

Ömrümün kaderine, sensiz bir günüm doğuyor

Sen yoksun inan, dertliyim kederliyim

Gelmezsen kahrolurum, yıkılırım sevgilim

Dünyada sanki biziz, umutsuz yaşayan

Bir başkası yok ki, yalnızca ikimiz

Sevgi üzerine söylenmiş, şarkılar mı?

Sanki bize yazılmış, kaderimiz bu mu? 

Derelerin suyu, durmadan çağlar

Yüreğimde yanan alev, sönmez yanar

Volkanın lavları püskürür, kor alev yakar

Benim yarimin kalbi, bilmem ne yapar', 'Bak yine soldu güneş, yine akşam oluyor Ömrümün kaderine, sensiz bir günüm doğuyor Sen yoksun inan, dertliyim kederliyim Gelmezsen kahroluru...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yikilirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut yok Yarınımdan', 'umut-yok-yarinimdan-muzaffer-taskirmaz-vfe4k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gün elbet, güneş doğacak göreceksin

Bilir misin, yarın ne olacak düşünsene

Belki aydınlık, yada karanlık olacak

Anladım şimdi, umut yok yarınımdan

Düşümceler sardı, bırakmıyor beni

Kalbim karardı, sanki bunalımdayım

Düşüncelerden, artık sabrım kalmadı

Anladım şimdi, umut yok yarınımdan

Tanıdığım herkes, düşman oldu bana

Yarabbi ne zormuş, böyle yaşamak

Herkes kendi aleminde, kendi kendine

Dünyanın çarkı bu, böyle dönüyor', 'Bir gün elbet, güneş doğacak göreceksin Bilir misin, yarın ne olacak düşünsene Belki aydınlık, yada karanlık olacak Anladım şimdi, umut yok ...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/umut-yok-yarinimdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekliyorum', 'bekliyorum-muzaffer-taskirmaz-sazbd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gurbet çekmiş sılada, özlem dolu gözlerin 

Sabır kalmadı canda, seni çok beklemekten

Yeter artık ızdırabım, çekilmiyor dertlerim 

Bekliyorum gelsene, biraz çabuk olsana

Bir kalbim var alsana, sana veriyorum

Bekliyorum gelsene, biraz çabuk olsana

Koşsana koş gel, dertlerime ortak olsana

Bekliyorum gelsene, biraz çabuk olsana

Sen olmazsan, bu hayatın tadı olmaz

Sen olmazsan, kırda çiçekler açmaz

Sevgi dolu yüreğimde, pas olmaz

Bekliyorum gelsene, biraz çabuk olsana', 'Gurbet çekmiş sılada, özlem dolu gözlerin  Sabır kalmadı canda, seni çok beklemekten Yeter artık ızdırabım, çekilmiyor dertlerim  Bekliyorum...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bekliyorum-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güldürme Beni', 'guldurme-beni-muzaffer-taskirmaz-a76as', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O güzel sevgiyi, o büyük aşkı

Biliyorum deyip, güldürme beni

Senin aşkım dediğin, eski bir şarkın

Seviyorum deyip, güldürme beni

Bu zaman da aşkın, adımı kaldı

Sevip sevilmenin, tadımı kaldı

Yoksa tüm dünya, sana mı kaldı

Seviyorum deyip, güldürme beni

Sevgiler ne yazık, sözlerde şimdi

Söylüyor yalanı, sözlerde şimdi

Bir Leyla, bir Mecnun nerede şimdi

Seviyorum deyip, güldürme beni', 'O güzel sevgiyi, o büyük aşkı Biliyorum deyip, güldürme beni Senin aşkım dediğin, eski bir şarkın Seviyorum deyip, güldürme beni Bu zaman da...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/guldurme-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Olan Hasretimi', 'sana-olan-hasretimi-muzaffer-taskirmaz-1oe1s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dertli rüzgar estikçe eser, durmak bilmez ki

Sana olan bu aşkım, coştukça coşar

Deli gibi seviyorum, sana aşığım 

Sana olan hasretimi, bilemezsin sen

Gökyüzünde yıldızları, sayan benim

Yıldızlara baktıkça, coşan benim

Sanki gökyüzünde, koşan sensin

Sana olan hasretimi, bilemezsin sen

Dert rüzgarı derler buna, bilemezsin

Bu dünya da başkasını, sevemezsin

Alın yazın bana yazılmış, bunu bilesin

Sana olan hasretimi, bilemezsin sen', 'Dertli rüzgar estikçe eser, durmak bilmez ki Sana olan bu aşkım, coştukça coşar Deli gibi seviyorum, sana aşığım  Sana olan hasretimi, bilem...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sana-olan-hasretimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiye Doğru', 'sevgiye-dogru-alper-ceylan-zfh6c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sanki bir kuş misali, 

Uçup giden bir sevgi, 

uzaklara, sıcaklığı hissettiği

sevgiyi duyduğu yerlere göç eden bir kuş olmak, 

En umutsuz gecelerde bile, 

Hiç bir şey olmamışcasına uçabilen, 

Dertleri, kederi anlamaksızın

Delicesine, özgürce uçabilen, 

O mavi rengin sonsuluğuna kapılıp

ve o sonsuzlukta uçabilen 

bir kuş olmak isterdim.

Kara kalemi her aldığı zaman, 

umutsuzluktan, yalnızlıktan

başka bir şey yazmayan bu eller, 

bir kanat olup uçabilseydi, 

inanki, seni de alır 

uçardım, 

huzura doğru, 

sevgiye doğru!', 'Sanki bir kuş misali,  Uçup giden bir sevgi,  uzaklara, sıcaklığı hissettiği sevgiyi duyduğu yerlere göç eden bir kuş olmak,  En umutsuz gec...', ARRAY['Türk Edebiyatı','Şiir','Alper Ceylan']::text[], 8.5, '{"poet":"Alper Ceylan","poet_slug":"alper-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sevgiye-dogru-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırladıkça', 'hatirladikca-muzaffer-taskirmaz-zdf60', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aklımdan gitmiyor, ne yapsam bilmiyorum

Belki de bir çılgınlık, seviyorum seni sevgilim

Ne yapsam bilmiyorum, ne söylesem

Olmayacak dua, dilime doğuyor bir an

Seni hatırladıkça, maziye dönüp baktıkça

Çaresizlik olmazsa, bir başka oluyorum

Ellerimden bir tutsan, bana kendinden anlatsan

Söyle kalbim durursa, dünya bana zindan olursa

      

Birlikte olduğumuz, mehtaplı gecelerin karanlığı

Sana bir şeyi hatırlatır mı, çam ağacının altında

Dudaklarımdan ilk çıkan kelime, seni seviyorum 

Bil ki seni seviyorum, o eski günleri hatırladıkça', 'Aklımdan gitmiyor, ne yapsam bilmiyorum Belki de bir çılgınlık, seviyorum seni sevgilim Ne yapsam bilmiyorum, ne söylesem Olmayacak dua, dil...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hatirladikca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Feryat', 'feryat-muzaffer-taskirmaz-crz2t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Maraş''dan gideli aylar, yıllar geçti

Uzadı geceler, günler sanki ömür geçti

Zaman sanki durdu, günlerim ağlayarak geçti

Ağlıyorum, sızlıyorum günlerden beri

Bu fani dünyada hasretlik nereden çıktı

Feryatlarım yükseldi, arşa çıktı

Yarim döner mi diye, beklemekten yıllar geçti

Halimi sorarsan sen, yerlerden dikenler çıktı

Yıldızlara soruyorum, döner mi geri

Beklemeye sabrım kalmadı, dermanım bitti

Gözlerim ağlamaktan, toz bulutu gibi

Artık yürek dayanmaz, bu hasrete yıkılmışım', 'Maraş''dan gideli aylar, yıllar geçti Uzadı geceler, günler sanki ömür geçti Zaman sanki durdu, günlerim ağlayarak geçti Ağlıyorum, sızlıyoru...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/feryat-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başladı', 'basladi-muzaffer-taskirmaz-xpsnw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her şeyi bana göz süzüp, baktığın an başladı

Yüreğimi kor gibi, yaktığın an başladı

Faydası yok külleme, yaktığın bu ateşi

Aşk denilen fırtına, bende çoktan başladı

Sen ne anlarsın, hiç yaşadın mı? 

Gönlümde sakladım, sana sevgimi

Anlatmak istedim, kalbim heyecanlı

Sana bir türlü, aşkımı söyleyemedim

Bana fırsat mı verdin, aşkı anlatacak

Aşkımla alay ettin, el aleme rezil ettin 

Sen sözünde durmadın, dinlemedin beni

Sana son sözüm, mutluluklar sevgilim', 'Her şeyi bana göz süzüp, baktığın an başladı Yüreğimi kor gibi, yaktığın an başladı Faydası yok külleme, yaktığın bu ateşi Aşk denilen fırtı...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/basladi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek', 'sevmek-muzaffer-taskirmaz-mppbh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kaderde senden, ayrı düşmekte varmış

Doğrusu bunu, hiç düşünmemiştim ben

Gökyüzündeki yıldızlara, benim içinde bak

Susadım diyorsan, aşkın şarabından içmelisin

Ben seni beklemekten yoruldumsa, sen uyumalısın

Gözlerim gözlerine, bakmak istiyor

Ellerim ellerinden, tutmak istiyor

Dudaklarım, dudaklarından öpmek istiyor

Al beni, beni de sev demedim mi

Sar beni, kollarına al yar demedim mi

Ömrüm senin olsun, sar beni bağrına

Gel demedim mi, sev demedim mi

Kollarımı açtım sana, sende bana sarılsana

Yüreğimi verdim sana, sende beni anlasana

Beni biraz olsun anlasana, canım sevgilim

Tahammülüm kalmadı, sar beni bağrına', 'Kaderde senden, ayrı düşmekte varmış Doğrusu bunu, hiç düşünmemiştim ben Gökyüzündeki yıldızlara, benim içinde bak Susadım diyorsan, aşkın ş...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevmek-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmezsin', 'gelmezsin-muzaffer-taskirmaz-t7qdu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben seni bekliyorum, gelmezsin

Umutlarımı yıktın, neredesin

Aşıklar kırda gezer, kol kola

Sevgililer eğlenir, barda

Bizim burada yaz, gazinoda saz

Ellerinde şişeleri, hiç düşürmezler

Gece barda, dans ederler 

Güzel kızlar da, hep naz ederler

Sanki kalbim, tutuklu kalır

Sevgi dolu yüreğim, bomboş kalır

Zaman tünelinde, yürüyorum

Dermanım kalmamış, yorulmuşum', 'Ben seni bekliyorum, gelmezsin Umutlarımı yıktın, neredesin Aşıklar kırda gezer, kol kola Sevgililer eğlenir, barda Bizim burada yaz, gazino...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gelmezsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-alper-ceylan-80dcd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayat, bazen ilkbahar, 

yeniden yeşeren umutlar, 

sıcak dostlukların getirdiği hatıralar, 

bir mevsimlikte olsa, yaşanmaya değer! 

Hayat, bazen acımasız, 

alıp gider sevdiklerini

uzaklara çok uzaklara.

Ardından gözyaşı bırakır.

Yas dolar insan yüreği, 

Yaşamın kanunuda olsa, ağlamaya değer! 

Hayat, bazen karanlık bir kış gecesi.

Her tarafında korkunç rüyaların pençesi.

Yüreğinde soğuk bir ayaz, 

bendinde acılardan kalan tutsaklık.

Bir anlıkta olsa, korkmaya değer! 

Hayat bu bazen bir kuş, 

bazende bir papatya.

Ya uçar gider, 

ya da seviyor, sevmiyor.

Gelip geçiçi de olsa bu dünya, 

güzellikleri görmeye değer!', 'Hayat, bazen ilkbahar,  yeniden yeşeren umutlar,  sıcak dostlukların getirdiği hatıralar,  bir mevsimlikte olsa, yaşanmaya değer!  Hayat, ba...', ARRAY['Türk Edebiyatı','Şiir','Alper Ceylan']::text[], 8.5, '{"poet":"Alper Ceylan","poet_slug":"alper-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hayat-72-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefasız Sevgili', 'vefasiz-sevgili-muzaffer-taskirmaz-mt1wt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Adını sayfalara, yazıp durdum

Üstelik resmini, çizip durdum

Titreyen ellerini, tutup durdum

En güzel duyguyu, sende buldum

Canımsın demiştin, ne oldu sana

Eğlenip gülmek, yakışır sana

Kalbime açtığın, aşk yarasını

Sen kendin sarıver, mutlu olayım

Elveda demeden, yok olup gitme

İnanmak zor olur, hele bu devirde

Resmini vermeden, terkedip gitme

Ayrılık daha zor, bunu sen isteme

Ne yapsam olmuyor, şaşkınım artık

Yalnızlık duygusu, başladı artık

Üzgün bakışların, söyler duygunu

Ayrılığı ben değil, sen düşündün

Şaşkın bakışınla, beni yakarsın

İnci mercan gibi, kalbimde parlarsın

Gözlerime bakıp, kalbimi yakarsın

Umutlarımı yıktın, sende yıkılasın

Hani o söylenen, şarkı senindi

Aşk denilen duygu, sonsuzdu

Bu dünya yalnız, ikimizindi

Bak sana  ne oldu, yalnızım şimdi', 'Adını sayfalara, yazıp durdum Üstelik resmini, çizip durdum Titreyen ellerini, tutup durdum En güzel duyguyu, sende buldum Canımsın demiştin...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/vefasiz-sevgili-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Bulutları', 'sevda-bulutlari-muzaffer-taskirmaz-8ei6k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevda bulutları, geçti üzerimden

Bu yollar kapalı, dertli kaderimden

Haberini alamıyorum, sesini duymuyorum

Çok uzaklardasın, dayanamıyorum ben

Rüzgar alsın götürsün, beni sana

Yüreğimi koparsın, versin sana

Zaman tünelinde, belki buluşuruz

Belki hayal olur, belki de gerçek olur

Sen unutma beni, belki bir gün buluşuruz

Aklından geçer mi hiç, kavuşmamız

Yıllar sonrasını, hayal ederek

Ömrümün baharını, solmuş görürsün.', 'Sevda bulutları, geçti üzerimden Bu yollar kapalı, dertli kaderimden Haberini alamıyorum, sesini duymuyorum Çok uzaklardasın, dayanamıyorum ...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevda-bulutlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Hiç Olmadım!', 'sensiz-hic-olmadim-abdulkadir-karaman-o6pcb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben sensiz hiç kalmadım

her ân benimle oldun her yerde.

Ne gözlerden, ne ikramlar sunuldu, 

ne gülüşlerden ne ilhamlar; 

hiç birini almadım; 

bağlandığımdan beri

dermanı sen olan derde…

Nereye baktıysam sen vardın

seni gördüm hep gözlerde…

senin gülüşlerindi içime çöken

gülüşlerde.

Uzaklarda olsan bile

varlığın hep yanımdaydı…

hayalin gözlerimde, 

hasretin canımdaydı…

ben sensiz hiç kalmadım

sen yanımdayken de

yanımda yokken de

sensiz olmadım! 

Nefes aldım

ve verdim hep seninle…

17.12.02', 'Ben sensiz hiç kalmadım her ân benimle oldun her yerde. Ne gözlerden, ne ikramlar sunuldu,  ne gülüşlerden ne ilhamlar;  hiç birini almadım;...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sensiz-hic-olmadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdamın Ardından', 'sevdamin-ardindan-alper-ceylan-v0hz2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karanlık çöker ansızın dizlerinin dibine, 

ağlar olmuşsun farkında olmadan.

Nedensiz bir hasret kaplamış, dört bir tarafını.

Hüznün en doruğuna ulaşmışsın, 

gözyaşların arkadaşın olmuş, 

karanlık yoldaşın.

Sevdirmiş kendini sana, 

en mahsum, en boşvermiş yanıyla..

Bir de bakmışsın, hançer gibi kalbine saplanan sevdan, 

karanlıkta kayboluvermiş, 

aramaz olmuşsun..

Yalnızlık çökmüş sonrasında yüreğine, 

karanlığın aydınlığa vurduğu anda.

Yüreğin heyecanını kaybedivermiş, 

karanlık kendiyle beraber almış götürmüş.

Aramaz dediğim yüreğim, 

sevdamı dört gözle bekler olmuş.

Vurulmuş bir çocuk gibi, en taze en güzek yaşında...', 'Karanlık çöker ansızın dizlerinin dibine,  ağlar olmuşsun farkında olmadan. Nedensiz bir hasret kaplamış, dört bir tarafını. Hüznün en doruğ...', ARRAY['Türk Edebiyatı','Şiir','Alper Ceylan']::text[], 8.5, '{"poet":"Alper Ceylan","poet_slug":"alper-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sevdamin-ardindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Derdin Adı!', 'ayrilik-derdin-adi-abdulkadir-karaman-m2fft', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hasret geçit vermeyen

Tetikte çığlar ardı.

Gönlüm imdât dileyen

Bakışlara susadı! ..

Eskimez acıların

Oyuncağı yüreğim.

Derdi ne? çilelerin

Dolmaz neden miâdı? 

Eskidi gözyaşlarım

acılar eskimedi. 

Kâr etmedi yalvarmak

Derdim hep tâze kaldı! .

Göz göz oyuk her yanı

Girdaplarda benliğim…

Umut kesti ufuktan

Hüznün içine daldı! ..

Canım niye kıskaçta? 

Ruhum bunaltı neden? 

Tütmez, içerden canım

Ne diye, niçin yandı? 

Kâlbim paslanmış diyar

Sevgimse yosun bağlar.

Çözülmez küf duygular

Ayrılık, derdin adı! ..

01.01.03', 'Hasret geçit vermeyen Tetikte çığlar ardı. Gönlüm imdât dileyen Bakışlara susadı! .. Eskimez acıların Oyuncağı yüreğim. Derdi ne? çilelerin ...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ayrilik-derdin-adi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günce', 'gunce-nev-bilginer-w6uy9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gül güncesi 

tutulur hergün

kendini sonsuzluğa bıraktığında gün

kırmızıyla yazılır

herşey insana dair

ve bir daha hiç silinmeyecekler

bazı yapraklar dikene dolanır

kurtaramazsın

güncene hikayesini almazsın

istemezsin

o sayfalar yere düşer

aldırmazsın

gürültüye dönersin

bir gül düşer başına 

o günü hiçbiryere sığdıramazsın

bazen süzersin saat saat günü

o sayfada tek satır dolduramazsın

gün olur, gün yine solur

günlerin bitmez ama

defterin dolar

satırlardan düşürdüğün tek şey kendine

hafif bir başağrısı olur

düşen gülü özlersin

çünkü bir tek o 

kırmızıyla yazılıdır', 'Gül güncesi  tutulur hergün kendini sonsuzluğa bıraktığında gün kırmızıyla yazılır herşey insana dair ve bir daha hiç silinmeyecekler bazı y...', ARRAY['Türk Edebiyatı','Şiir','Nev Bilginer']::text[], 8.5, '{"poet":"Nev Bilginer","poet_slug":"nev-bilginer","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gunce-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durduramazsın', 'durduramazsin-alper-ceylan-p221p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kıymeti bilinmez gençliğin, 

öylece geçip gider.

Gözünü bir açıp kapatmışsınki, 

yolu yarılamışsın bile.

Sonra da ararsın o günleri, 

anlatırsın maceralarını, 

lise aşklarını.

Böylece sürüp gider, 

durduramazsın.

Gençken insan daha iyi duyar, 

kuşların cıvıltılarını, 

yağmurun sesini, 

karanlığın hüznünü..

Yaş ilerleyip gider ya, 

bu seslerde yavaşlar.

Yavaşlar, durduramazsın.

Tâ ki ömrün son durağına kadar.

Sonra gelirsin ya son durağa, 

öylece dokunmak istersin gözyaşlarına, 

öylece ölmek.

Kıymeti bilinmez hayatın, 

gider, gider de durduramazsın.', 'Kıymeti bilinmez gençliğin,  öylece geçip gider. Gözünü bir açıp kapatmışsınki,  yolu yarılamışsın bile. Sonra da ararsın o günleri,  anlatı...', ARRAY['Türk Edebiyatı','Şiir','Alper Ceylan']::text[], 8.5, '{"poet":"Alper Ceylan","poet_slug":"alper-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/durduramazsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'N''olur', 'n-olur-bilal-yilmaz-2-oe44y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Korkarak, haydi git, dese de dilim

Yalvarıyor gönlüm, gitmesin n''olur.

Varsın aylarca boş kalsın da elim, 

Bu sevda böylece bitmesin n''olur.

Gitme kal, kollarım açık kalmasın.

Gözlerim hayale sensiz dalmasın.

Yıllar yüreğimde tuttuğum yasın

Kucağına beni atmasın n''olur.

Ömrümün sensiz baharı uykuda.

Gönlüm dolu, yoğu varı uykuda.

Yarı açık gözler yarı uykuda, 

Öksüzce bir acı tatmasın n''olur.', 'Korkarak, haydi git, dese de dilim Yalvarıyor gönlüm, gitmesin n''olur. Varsın aylarca boş kalsın da elim,  Bu sevda böylece bitmesin n''olur....', ARRAY['Türk Edebiyatı','Şiir','Bilal Yılmaz 2']::text[], 8.5, '{"poet":"Bilal Yılmaz 2","poet_slug":"bilal-yilmaz-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/n-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda', 'veda-bilal-yilmaz-2-4v2oy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geçilmiyor tuzaklardan

Varın ona hayat deyin.

El ediyor uzaklardan

Musalla taşı mabedin.

Beklerdim böyle bir davet

Çökmüşken içime kasvet.

Bir ses, edersen icabet

Kalmaz diyor hiçbir derdin.

Demir atılmadan suya

Dalayım derin uykuya.

Tek tek göremem olur ya

Hakkınızı helal edin.', 'Geçilmiyor tuzaklardan Varın ona hayat deyin. El ediyor uzaklardan Musalla taşı mabedin. Beklerdim böyle bir davet Çökmüşken içime kasvet. B...', ARRAY['Türk Edebiyatı','Şiir','Bilal Yılmaz 2']::text[], 8.5, '{"poet":"Bilal Yılmaz 2","poet_slug":"bilal-yilmaz-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/veda-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Önsöz', 'onsoz-muzaffer-taskirmaz-gd6w8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1979 yılından itibaren, gerek gençlik yıllarımda gerek vatani görevimi yaparken kaleme aldığım, özel yaşantımdan da esinlenerek şu zamana kadar, eşime, beni seven arkadaşlarıma ve sevdiklerime karşı hissettiğim duygularımı yazmış olduğum şiirlerimle sizlere anlatmaya çalıştım.

              Siz sevenlerime karşı hissettiğim duygularımı kağıda dökmemi sağlayan yardımlarını benden esirgemeyen sevgili eşime teşekkürlerimi arz ediyorum.

                              Sevgi ve saygılarımla, 

                                              Muzaffer TAŞKIRMAZ', '1979 yılından itibaren, gerek gençlik yıllarımda gerek vatani görevimi yaparken kaleme aldığım, özel yaşantımdan da esinlenerek şu zamana ka...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/onsoz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgeçmiş', 'ozgecmis-muzaffer-taskirmaz-ouxlx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kahramanmaraş İli Merkez Kayabaşı Mahallesi 10.04.1963 doğumlu İlkokul öğrenimimi 1970 - 1975 tarihlerinde Kahramanmaraş Dumlupınar İlkokul''un da tamamladım. Orta ve Lise öğrenimimi 1976-1984 tarihleri  arasında Kahramanmaraş İmam-Hatip Lisesi''nde tamamladım.1987 - 1988 yılları arasında askerlik eğitimimi Amasya ve Kıbrıs''ta yaptım.

               20.10.1989 yılında Kahramanmaraş Merkez Fatmalı Belediyesinde Muhasebeci olarak memurluk görevime başladım.30.01.1997 yılında Kahramanmaraş Sütçü İmam Üniversitesi Ziraat Fakültesi''ne tayinim yapılmış olup, Tahakkuk Servisi''nde halen memur olarak görev yapmaktayım. Bundan sonraki hayatımda da duygularımı sevenlerimle paylaşmaya devam edeceğim.  

             En içten dileklerimle...

Muzaffer TAŞKIRMAZ', 'Kahramanmaraş İli Merkez Kayabaşı Mahallesi 10.04.1963 doğumlu İlkokul öğrenimimi 1970 - 1975 tarihlerinde Kahramanmaraş Dumlupınar İlkokul''...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Taşkırmaz']::text[], 8.5, '{"poet":"Muzaffer Taşkırmaz","poet_slug":"muzaffer-taskirmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ozgecmis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnadına', 'i-nadina-alper-ceylan-j8w8a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüreğimde bir sonbahar, 

fırtınalı ve karanlık.

Tüm ağaçların güzelliklerini bıraktığı, 

kupkuru bir odun parçasına döndüğü, 

bir sonbahar yaşıyor yüreğimde.

ve ben yine sensiz, 

inanki, üşüyorum! 

Yalnızlığımı ağaçlarla paylaşıyorum, 

onlar yaprak döktükçe, 

ben de gözyaşı, 

ama sen yine yoksun.

Yüreğimde bir kış, 

soğuk ve hüzünlü.

Dışarıda lapa lapa bir kar, 

şehrin elektrikleri kesik.

Ben, yalnız bir odada

bir mum aydınlığı var, 

o eriyip giderken, 

bakar bakar ağlarım.

Daha fazla dayanmaz yüreğim, 

ilk gözyaşım damladığı vakit

mumda söner, 

yine her yer karanlık

ve ben yine yalnız, 

yine sensiz.

Yapamıyorum artık! 

anla, 

yüreğim sıcağı özledi, 

yüreğim coşkuyu, 

yüreğim gülmeyi özledi.

Her ne kadar, 

uyuduğum vakit rüyalarıma gelmemekte

inat etsen bile, 

her ne kadar, 

elini tutmama izin vermesen bile, 

seveceğim inadına, 

inadına seveceğim..', 'Yüreğimde bir sonbahar,  fırtınalı ve karanlık. Tüm ağaçların güzelliklerini bıraktığı,  kupkuru bir odun parçasına döndüğü,  bir sonbahar y...', ARRAY['Türk Edebiyatı','Şiir','Alper Ceylan']::text[], 8.5, '{"poet":"Alper Ceylan","poet_slug":"alper-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/inadina-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız kalmak istiyorum!', 'yalniz-kalmak-istiyorum-serhan-i-seri-20vrd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalnız kalmak istiyorum bugünlerde, 

Ama inadına herkes tepemde.

Ne kadar çok kişi var bugün yine çevremde, 

Koskoca bir hiçkimse! 

Ne kalabalık şey şu hiçkimse, 

Doğrular, yanlışlar, pişmanlıklar, 

Mutluluklar, acılar, heyecanlar, 

Kaybolmamak elde değil bu kadar insanın içinde.

Sevgiler, sevgililer, sevdiklerim, sevenlerim, 

Hepsi inadıma geliyorlar üzerime.

Susmuyorlar anılar, dönüyorlar çevremde, 

Ne kadar çok sevmişiz meğer, şu kısacık ömürde.

Ayrılıklar geliyor, ölümlerden de önce, 

Daha çok acıtıyor, sevgilerin ölünce.

Ne acı şey yaşamak, 

Ölümü düşününce.

Yalnız kalmak istiyorum bugünlerde, 

Ama inadına herkes tepemde! 

Birileri gelsede kalabalıktan çıksam, 

Kalabalıktan çıkıp insanlara karışsam.', 'Yalnız kalmak istiyorum bugünlerde,  Ama inadına herkes tepemde. Ne kadar çok kişi var bugün yine çevremde,  Koskoca bir hiçkimse!  Ne kalab...', ARRAY['Türk Edebiyatı','Şiir','Serhan İşeri']::text[], 8.5, '{"poet":"Serhan İşeri","poet_slug":"serhan-i-seri","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yalniz-kalmak-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybolan şehir', 'kaybolan-sehir-mehmet-sisli-z7lps', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bütün şehirler uyuyor

Ben hariç

Düşünmek varolmakmış

Sonsuza kadar

Rüzgar bir şeyler fısıldıyor

Bir sigara daha iç

Sonu görünmeyen bir rüyaya dalıyorum

Ama kimsesiz

Yagmur gibi yağıyor hüzün

Yüreğim ıslanıyor

Ellerim üşüyor

Bir sigara aralığında

Gözlerim mavilikte beyazı arıyor

Ve kapanıyor

Hüzün yağıyor odama', 'Bütün şehirler uyuyor Ben hariç Düşünmek varolmakmış Sonsuza kadar Rüzgar bir şeyler fısıldıyor Bir sigara daha iç Sonu görünmeyen bir rüyay...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şişli']::text[], 8.5, '{"poet":"Mehmet Şişli","poet_slug":"mehmet-sisli","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kaybolan-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Timsahın Gözyaşları', 'timsahin-gozyaslari-mehmet-sisli-eo9nb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zaman bir bir alıyor günleri

Açarken kışın ortasında kar gülleri

Bir satırı bir kelimeye

Bir harfikoca bir şiire sığdırıyorum

Giden günler bir şeyler götürüyor benden

Taki bir timsahın göz yaşları akana kadar

Sonu bulmak güneşin daglar ardına saklanması gibi

Hala bir şans var göz yaşları durmalı timsahın

Yıldızlardan sızan o ince ışığı görmeli

Önce biri göz yaşlarımı silmeli', 'Zaman bir bir alıyor günleri Açarken kışın ortasında kar gülleri Bir satırı bir kelimeye Bir harfikoca bir şiire sığdırıyorum Giden günler b...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şişli']::text[], 8.5, '{"poet":"Mehmet Şişli","poet_slug":"mehmet-sisli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/timsahin-gozyaslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esmer Yüzlü Gül Gülüşlüm', 'esmer-yuzlu-gul-guluslum-sair-khan-bk0tn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her gece seni düşünen beyin ellerine emir verdi

Bu gece senin esmer yüzüne bir şiir yazmaya karar verdim, 

Seni vücudumun bütün damarlarında hissedişimi, 

Kan, su  gibi bana hayat verişini yazmak istedim, 

Özleminle, hasretinle, yokluğunla dayanmanın zorluğunu yaşarken, 

Bu gece senin esmer yüzüne gül gülüşüne bir şiir yazmaya karar verdim, 

Sensizliğin ateşi buram buram kokarken burnumda, 

Köz olan kalp yangınına çözüm bulmaya çalışırken karanlık gecelerde

Yaşarken bir şeylerin tersliğini eksikliğini hissettiğimi  özlemimi yazdım, 

Güneşin beni yakışını, çiçeklerin kokmayışını, yağmurun yağmayışını, 

Sensiz geçen, seni tanımadan geçen saatlerimi yazdım, 

Yani ben seni yazamadım! Yazamadım 

Ben sensizliğin acısını burnumun sızısını gözümün yaşını yazdım! 

Senin gülüşünü yazdım, o güzel tebessüm ile tanışmamı yazdım, 

Yemyeşil ormanların çiçekle bezenmiş çimlerin 

Güzelliğini takla atışlarınla şenlendirdiğini yazdım

O gülüş ile aşka küsmüş olan kalbimin parıldayışını, 

İçimde açan gülü, baharı ve sana duyduğum temiz aşkımı, 

Hayata yeniden merhaba deyişimi yazdım, Sana yazdım bu gece, 

Ben senin esmer yüzünde biten gülü; o yıldızlı gülüşü yazdım, o gülüşe ölüşümü yazdım, 

Bu yaşa kadar kuruyan pınarların  ilk ağlayışını yazdım, 

Biliyor musun en çokta bunda zorlandım, 

Göz yaşlarımın her satırı ıslatışını seyrettim hayret ve neşe ile karışık 

Sadece senin için yazdım bu gece, sadece senin için ilk şiirimi

Kalbimden kopup doruğa ulaşan senin esmer yüzüne gül gülüşüne yazdım

Ben senin esmer  yüzüne beş yıldızlı gülüşüne bir şiir yazdım işte, 

Ben ve gece, yalnız ıssız yollar karanlıklar içerisinde tek odasında yanan lamba ile bir oda, 

Gökte esmer yüzündeki gülüşe düşen yıldızlar, ona eşlik eden yakamoz tutmuş deniz

Belirsizce öten gece kuşları ve aracımın içini aydınlatan zayıf ışık

Sana bu satırları adadık, esmer yüzlü ey gül yüzlü şahikam', 'Her gece seni düşünen beyin ellerine emir verdi Bu gece senin esmer yüzüne bir şiir yazmaya karar verdim,  Seni vücudumun bütün damarlarında...', ARRAY['Türk Edebiyatı','Şiir','Şair Khan']::text[], 8.5, '{"poet":"Şair Khan","poet_slug":"sair-khan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/esmer-yuzlu-gul-guluslum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aziz yare elveda', 'aziz-yare-elveda-huseyin-hilmi-isik-4mio8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Muzdarib bir gönülle, kâbûslu hayâllerle, 

Vuslât-ı cânâna ve gülistâna elvedâ! 

Gizli âh çekmelerle, içli iniltilerle, 

Zevkine doymadığım nevbahâra elvedâ''! 

Son bir def''a bakayım, o hüsn-i cemâline, 

Bir nazarın değişmem, bütün dünyâ mâline, 

İster gülsün gâfiller, bu âşıkın hâline, 

Bundan böyle neş''e ve sürûrlara elvedâ''! 

Gönlüm nûru, feyz kaynağım, oldu bizden ırak, 

Zulmet-i hicrânda kaldı rûhum pür iftirâk.

Hasret kaldım, hep karardım, oldum nûrundan cüdâ, 

Feyz kaynağım, elvedâ'', âh elvedâ'', elvedâ''.

Güzellerin güzeli, rûhların tek matlûbu, 

Değil mahlûkun yalnız, Hâlıkın da mahbûbu

Cihânı tenvîr eden en son Nûra elvedâ''! 

En derin sevgilerle, azîz yâra elvedâ''!', 'Muzdarib bir gönülle, kâbûslu hayâllerle,  Vuslât-ı cânâna ve gülistâna elvedâ!  Gizli âh çekmelerle, içli iniltilerle,  Zevkine doymadığım ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Hilmi Işık']::text[], 8.5, '{"poet":"Hüseyin Hilmi Işık","poet_slug":"huseyin-hilmi-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aziz-yare-elveda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nisgiller', 'nisgiller-ahmet-hani-bx318', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Deniz sakit gemi düm ağ

Yaşıl yarpaq hasilli bağ

Qızıl torpaq qızıllı dağ

Ne çox nisgil ki var mende.

-

Gece aylı, işıq günler

Sazın çala aşıq günler

Deniz, men, yar, qayıq, günler

Ne çox nisgil ki var mende.

-

Büşqu mişar yox olsunlar

Ağaclıqlar çox olsunlar

Ac qarınlar tox olsunlar

Ne çox nisgil ki var mende.

-

Sövüd, kölge, barış, istek

Qara qansız temiz ürek

Alov, tendir, fetir, çörek

Ne çox nisgil ki var mende.

18 december  1995', 'Deniz sakit gemi düm ağ Yaşıl yarpaq hasilli bağ Qızıl torpaq qızıllı dağ Ne çox nisgil ki var mende. - Gece aylı, işıq günler Sazın çala aş...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nisgiller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamın Garipsiliği', 'yasamin-garipsiligi-elif-kerenciler-95a5k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sessizliğin en çok hissedildiği vakit

yankım dağılır aslında her yana

nefesim yetmez olur

umduklarımı hayal edip

gelmeni beklerim...

17.03

02.01.2003

perşembe

ESKİŞEHİR', 'sessizliğin en çok hissedildiği vakit yankım dağılır aslında her yana nefesim yetmez olur umduklarımı hayal edip gelmeni beklerim... 17.03 0...', ARRAY['Türk Edebiyatı','Şiir','Elif Kerenciler']::text[], 8.5, '{"poet":"Elif Kerenciler","poet_slug":"elif-kerenciler","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yasamin-garipsiligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgelenmis Özgürlükler', 'golgelenmis-ozgurlukler-sair-met-yf5v3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sende kalsin gölgelenmis özgürlükler

Yüregimi koyduugum misralarimi ver bana, 

Degmez çünkü çogu güzellikler sana

Birakirim hiç arkama bakmadan

Sanma ki vefaliyim aglatanlara.

Kimsenin yanina kalmadi ki ettigi, 

Bu kadar zulme ne hacet var? 

Belli ki kincisin, çatmissin kaslarini

Söyle sana göz agrtan mi var? 

Küçük masumluklar da özlenesi degil artik, 

Gölgelenmis özgürlükler arkasinda.

Siyrilma zamani geldi-çatti sicakligindan

Son defa düsünmek bile, düsünülesi degil.', 'Sende kalsin gölgelenmis özgürlükler Yüregimi koyduugum misralarimi ver bana,  Degmez çünkü çogu güzellikler sana Birakirim hiç arkama bakma...', ARRAY['Türk Edebiyatı','Şiir','Şair MET']::text[], 8.5, '{"poet":"Şair MET","poet_slug":"sair-met","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/golgelenmis-ozgurlukler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsterdim', 'i-sterdim-metin-yalti-31gib', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni bir gün batımı kızıllığında tanımak isterdim.

Elini tuttuğumda gölge bile düşmesin üzerine isterdim.

Verdiğin sevinç soycul bir sevdaya dökülsün isterdim

içimde hiç tatmadığım  hazlarla çırpınırken isterdim.

Ne zaman düşsen usuma kim, nasıl biri diye sormak yerine

Çok sevdiğim, hep sevdiğim gene benimle demek isterdim.

Sen bana geldiğinde sevinçli ve şaşkın kalmak isterdim

Elini, bir kelebeğin çiçeğine konuşu gibi tutmak isterdim.

Verdiğimi çiçek özü toplayan arı gibi almanı isterdim.

isterdim, benim duyduklarımı sende duyasın isterdim.

Ne zaman ve nasıl geleceksin? Bunu hep bilmek isterdim.

Çılgınca sevinçlerimin her anını seninle paylaşmak isterdim.

 Sevda Türküleri/ 26,11,2002', 'Seni bir gün batımı kızıllığında tanımak isterdim. Elini tuttuğumda gölge bile düşmesin üzerine isterdim. Verdiğin sevinç soycul bir sevdaya...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/isterdim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilsen', 'bilsen-ayse-ant-95lyq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Benim cektigim acilari bilsen, 

Yine de sevmek ister misin? 

Toz pembe hayallerin kaybolabilecegini bilsen, 

Yine de birisin ellerini tutar misin? 

Döktügüm yaslarin acisini bir bilsen, 

Yine de sevip bile bile aglar misin? 

Bütün sevgilerin yalan oldugunu bilsen, 

Yine de seve seve atese gider misin? 

Sevgilinin seni sevmedigini bilsen, 

Yine de yillar yili bekler misin? 

Bütün söylenen sözlerin yalan oldugunu bilsen, 

Yine de her zaman dinler misin? 

Geceler boyunca cilelerimin cogaldigini bilsen, 

Yine de sevip aci ceker misin? 

Ciceklerin yalan sevgi ile solduklarini bilsen, 

Yine de sevip kendini soldurur musun? 

Söyle cocugum, söyle: sever misin? 

Bile bile atese gider misin? 

Rüzgar Gülü sorar sana: 

sevmeyi becerebilecek misin? 

(28.12.2002)', 'Benim cektigim acilari bilsen,  Yine de sevmek ister misin?  Toz pembe hayallerin kaybolabilecegini bilsen,  Yine de birisin ellerini tutar ...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Ant']::text[], 8.5, '{"poet":"Ayşe Ant","poet_slug":"ayse-ant","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bilsen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerelerdesin Deniz Gözlüm', 'nerelerdesin-deniz-gozlum-serkan-tontus-i9ofp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben ben değilim artık 

Beni ben yapan benliğimden bensiz ayrılmışım

Yüreğimde bir ben vardım, 

birde...

Birde beni ben yapan sen

Ben beni unuttum

Benliğimden atamadım benliğini

Beni ben yapan sen, seni sen yapan bendim

Ben ben değilim artık 

Beni ben yapan benliğimden bensiz ayrılmışım

Yüreğimde bir ben vardım, 

Ben beni kaybettim

Sen nerelerdesin DENİZ GÖZLÜM', 'Ben ben değilim artık  Beni ben yapan benliğimden bensiz ayrılmışım Yüreğimde bir ben vardım,  birde... Birde beni ben yapan sen Ben beni un...', ARRAY['Türk Edebiyatı','Şiir','Serkan Tontuş']::text[], 8.5, '{"poet":"Serkan Tontuş","poet_slug":"serkan-tontus","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/nerelerdesin-deniz-gozlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaşım', 'arkadasim-umit-besen-9pep1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uykuları kaçıyor düşündüğümde 

Güvenim kalmadı hiç aşka sevgiye 

Gözlerim inanmadı gördüklerine 

Ben utandım kendimden onun yerine 

Sitemim sana değil yeni aşkına 

Uğrunda öleceğim arkadaşıma

Değişmezdim ben onu hiçbir kadına 

Aşka değil gözyaşım arkadaşıma

Neden neden dünya yalanlarla dönüyor 

İnandığım dostlarım hep sırtımdan vuruyor 

Arkadaşım kardaşım yıllar yılı sırdaşım

Elbet bulursun kadın yok artık arkadaşım

Gezerken gördüm onu bir başkasıyla

Gördüğüm o başkası yabancı olsa

Beynimden vurulmuşum sanki o anda

Aldatıldım en yakın arkadaşımla', 'Uykuları kaçıyor düşündüğümde  Güvenim kalmadı hiç aşka sevgiye  Gözlerim inanmadı gördüklerine  Ben utandım kendimden onun yerine  Sitemim ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Besen']::text[], 8.5, '{"poet":"Ümit Besen","poet_slug":"umit-besen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/arkadasim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan', 'i-nsan-orkun-basaran-53lec', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'şair  1980 bursa doğumlu şu ana kadar 2 kitabı  ve birçok dergide şiirleri yayınlandı bu şiir de okuduğum kadarıyla 

insan ların düştükleri durumu ve kaybolan maneviyatı  anlatmak için yazdı şair bursa lisesi mezunu fakat başarılı olmasına rağmen maddi durumdan dolayı okuluna devam edemedi bir çok zorluklar yaşadı şair daha çok konferanslarla kendini anlatmaya çalışıyor', 'şair  1980 bursa doğumlu şu ana kadar 2 kitabı  ve birçok dergide şiirleri yayınlandı bu şiir de okuduğum kadarıyla  insan ların düştükleri ...', ARRAY['Türk Edebiyatı','Şiir','Orkun Başaran']::text[], 8.5, '{"poet":"Orkun Başaran","poet_slug":"orkun-basaran","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/insan-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet Elde', 'gurbet-elde-pir-sultan-abdal-pr6l9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gurbet elde bir hal geldi basima, 

Aglama gözlerim Mevlâ kerimdir.

Derman arar iken derde düs oldum, 

Aglama gözlerim Mevlâ kerimdir.

Hüma kusu suya düstü ölmedi, 

Dünya Sultan Süleyman''a kalmadi.

Dedim yâre gidem nasip olmadi, 

Aglama gözlerim Mevlâ kerimdir.

Kagida yazarlar ufak yazilar, 

Anasiz olur mu körpe kuzular.

Yürek yaralidir, ciger sizilar, 

Aglama gözlerim Mevlâ kerimdir.

Pir Sultan Abdal''im böyle buyurdu, 

Ayrilik donlari biçti giydirdi.

Ben ayrilmaz idim felek ayirdi

Aglama gözlerim Mevlâ kerimdir.', 'Gurbet elde bir hal geldi basima,  Aglama gözlerim Mevlâ kerimdir. Derman arar iken derde düs oldum,  Aglama gözlerim Mevlâ kerimdir. Hüma k...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gurbet-elde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söylesene', 'soylesene-gokcen-duran-dfkg7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çalan

Bu

Türkü, 

Hangi

Zincire

Vurulmaz

Dalganın

Dokunuşudur? 

Yavaşlayan

Bu 

Yağmur, 

Hangi

Gözyaşının

Kaçıncı

Kuruyuşudur? 

Söylesene, 

Ben

Öperken

Hazanı

Dudaklarından, 

Ellerimi

Verirken

Ellerine

Açan

Bu

Çiçekler

Hangi

Baharın

Habercisidir....? 

Söylesene, 

...', 'Çalan Bu Türkü,  Hangi Zincire Vurulmaz Dalganın Dokunuşudur?  Yavaşlayan Bu  Yağmur,  Hangi Gözyaşının Kaçıncı Kuruyuşudur?  Söylesene,  Be...', ARRAY['Türk Edebiyatı','Şiir','Gökçen Duran']::text[], 8.5, '{"poet":"Gökçen Duran","poet_slug":"gokcen-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/soylesene-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Doğuyor Denizden', 'ay-doguyor-denizden-hasan-akarsu-1kfv2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ay doğuyor denizden

Tekirdağ’da denizi gören

Racoczi’nin evinden uzakta

Deli Muzaffer durgun

Servis otobüsleri gürültülü

Kuşlar çığlık çığlığa

Yürüyor akşam

Denize açılan balıkçılarla

Ay doğuyor denizden.

                              Ekim 2001', 'Ay doğuyor denizden Tekirdağ’da denizi gören Racoczi’nin evinden uzakta Deli Muzaffer durgun Servis otobüsleri gürültülü Kuşlar çığlık çığlı...', ARRAY['Türk Edebiyatı','Şiir','Hasan Akarsu']::text[], 8.5, '{"poet":"Hasan Akarsu","poet_slug":"hasan-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ay-doguyor-denizden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinde Işıklarla', 'gozlerinde-isiklarla-hasan-akarsu-blfq6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerinde ışıklarla

Umut vererek gittin

Aydınlık bakışlarla

Bir yaşamı paylaşırcasına

Sevinçler içinde gittin

Yeşeren sevdalarla

Çocuk ellerinle

Kız gülüşlerinle gittin

Gülen anılarla

Sesin kaldı bende

                     Temmuz 2000

                      Hasan AKARSU', 'Gözlerinde ışıklarla Umut vererek gittin Aydınlık bakışlarla Bir yaşamı paylaşırcasına Sevinçler içinde gittin Yeşeren sevdalarla Çocuk elle...', ARRAY['Türk Edebiyatı','Şiir','Hasan Akarsu']::text[], 8.5, '{"poet":"Hasan Akarsu","poet_slug":"hasan-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozlerinde-isiklarla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkinci Cumhuriyetçi', 'i-kinci-cumhuriyetci-hasan-akarsu-bje60', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tarihi tersten okuduğu belli

Tecimen gözüyle baktığından

Lozan’la bir alıp veremediği var

Sevr’e delicesine taptığından.

                                 Ekim 2001', 'Tarihi tersten okuduğu belli Tecimen gözüyle baktığından Lozan’la bir alıp veremediği var Sevr’e delicesine taptığından.                    ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Akarsu']::text[], 8.5, '{"poet":"Hasan Akarsu","poet_slug":"hasan-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ikinci-cumhuriyetci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimlik', 'kimlik-hasan-akarsu-jya78', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '‘’Ahbap düşman oldu

ben buna şaştım...’’

Yemeğinizi yersiniz

Suyunuzu içersiniz

Her şey yerinde

Yanlış yapınca üzülürsünüz 

Ezilirsiniz baş kaldırınca

Sorun derinde

Zorda kalsanız da

Baş eğmezsiniz

Kimliğiniz, onurunuz-

Ölürsünüz çiğnendiğinde.

Eylül 2001', '‘’Ahbap düşman oldu ben buna şaştım...’’ Yemeğinizi yersiniz Suyunuzu içersiniz Her şey yerinde Yanlış yapınca üzülürsünüz  Ezilirsiniz baş ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Akarsu']::text[], 8.5, '{"poet":"Hasan Akarsu","poet_slug":"hasan-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kimlik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köy Enstitüleri', 'koy-enstituleri-hasan-akarsu-wgi32', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '‘’Komadı karanlığın ağaları

Halk uyansın ülke çiçeğe dursun’’

İş içinde eğitim 

Eğitim içinde üretim

Sürekli eğitim, sürekli üretim

Sonra yurdum çiçek

Köy kahvesinde

Eğitim mücadelesi’nde

Mehmet Başaran’ın şiiri

‘’Tonguç Baba için yazdığı

Kahvede gençler, emekliler

Taş- kağıt oyunları

Televizyonda defile

Gözlerin hiç ayrılmadığı

Ertelendi yurdumun çiçeğe durması

Bir kış gecesi yollar çamur

Kahve duman, köylü duman

Kimselerin umursamadığı.

Ocak 2002', '‘’Komadı karanlığın ağaları Halk uyansın ülke çiçeğe dursun’’ İş içinde eğitim  Eğitim içinde üretim Sürekli eğitim, sürekli üretim Sonra yu...', ARRAY['Türk Edebiyatı','Şiir','Hasan Akarsu']::text[], 8.5, '{"poet":"Hasan Akarsu","poet_slug":"hasan-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/koy-enstituleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tan Ağartısı', 'tan-agartisi-hasan-akarsu-mfzkn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tan ağartısıda

Yıldızlı gecelerde

Şiir değiyor gözlerinize

Açlıktan ölenlerin acıları

Geçim intiharları

Ölüm yazgı değil

Her şey kirleniyor

Gösterişli çekimlerde

Dudaktan söyleniyor türküler

Yürek/ten değil

Tan ağartısında 

Yıldızlı gecelerede

Şiir tatlı geçilmiyor

Denizi, gökyüzünü öpüyorsunuz

Martı kanatlarında

Güneş uzak değil.

                        Aralık 2001', 'Tan ağartısıda Yıldızlı gecelerde Şiir değiyor gözlerinize Açlıktan ölenlerin acıları Geçim intiharları Ölüm yazgı değil Her şey kirleniyor ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Akarsu']::text[], 8.5, '{"poet":"Hasan Akarsu","poet_slug":"hasan-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/tan-agartisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vurgunlar', 'vurgunlar-hasan-akarsu-8cpkl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağustos sıcağında

‘’Babam öldü’’ diyerek

Koşan genç, 

Yaşayan bilir acılarını

Aşk mevsim tanır mı

Yaşayan bilir zamansız aşkları

Genç aşıkların sancılarını

Dalgalı denizde 

Balıkçılar, gemiler...

Asfalt yollarda kuş ölüleri

Can dostlar bilir vurgunlarını

Şu geçici dünyada

Ozanın dediğince

Çiçekler bezer topraklarını.

                                 20.08.2001', 'Ağustos sıcağında ‘’Babam öldü’’ diyerek Koşan genç,  Yaşayan bilir acılarını Aşk mevsim tanır mı Yaşayan bilir zamansız aşkları Genç aşıkla...', ARRAY['Türk Edebiyatı','Şiir','Hasan Akarsu']::text[], 8.5, '{"poet":"Hasan Akarsu","poet_slug":"hasan-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/vurgunlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam Sonsuz Değil', 'yasam-sonsuz-degil-hasan-akarsu-dyxxx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gökyüzü sonsuz

Yüksel yükselebildiğince

Aşk sonsuz

Sev sevebildiğince

Yaşam kısa

Değerini bil! 

Deniz, doğa

Ne çok güzellikler...

Yaşam sonsuz değil! 

                      Ekim 2000', 'Gökyüzü sonsuz Yüksel yükselebildiğince Aşk sonsuz Sev sevebildiğince Yaşam kısa Değerini bil!  Deniz, doğa Ne çok güzellikler... Yaşam sons...', ARRAY['Türk Edebiyatı','Şiir','Hasan Akarsu']::text[], 8.5, '{"poet":"Hasan Akarsu","poet_slug":"hasan-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yasam-sonsuz-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba Dost', 'merhaba-dost-kul-aptal-kazim-huzur-okutan-y9oi8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İnsan yükü ağırdır, 

Öyle bilirdim.

Hele yanında ki yerimi de

İyi bilirdim.

Ama insanız ya! 

Hata etmişiz.

Sakalımız var diye, 

Haddimizi aşmışız.

Şimdi özür zamanı, 

Borç ödemenin tavı.

Eksiğim varsa dost, 

Sen tamamla kalanı.

Yaradana bir can, 

Sana bir SELAM, 

Ötesini ödemeye

Yok ki takattan.

Kısa kelam.

Halt etmişsek Hakkını, 

İster helal et.

Dost; 

Gördüm ki kalmamış ya! 

İster dua, 

İster kına et.

(gaziemir. Ocak.2003)

 Kul Aptal (Kazım Huzur Okutan)', 'İnsan yükü ağırdır,  Öyle bilirdim. Hele yanında ki yerimi de İyi bilirdim. Ama insanız ya!  Hata etmişiz. Sakalımız var diye,  Haddimizi aş...', ARRAY['Türk Edebiyatı','Şiir','Kul Aptal (Kazım Huzur Okutan)']::text[], 8.5, '{"poet":"Kul Aptal (Kazım Huzur Okutan)","poet_slug":"kul-aptal-kazim-huzur-okutan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/merhaba-dost-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Davet', 'davet-cevat-akkanat-zistx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'şehrimize bir müslüman gelmiş 

kalkın ona gidelim 

bir müslüman gelmiş bugün bize 

biz de ona gidelim 

haydi haydi silkinelim gidelim 

hoşgeldin ey müslüman diyelim 

basıp kara basıp kâbusa basıp 

ay müslüman vay müslüman hay müslüman diyelim 

eğlenelim el birlik gülelim

verelim şehrimizi müslümana verelim', 'şehrimize bir müslüman gelmiş  kalkın ona gidelim  bir müslüman gelmiş bugün bize  biz de ona gidelim  haydi haydi silkinelim gidelim  hoşge...', ARRAY['Türk Edebiyatı','Şiir','Cevat Akkanat']::text[], 8.5, '{"poet":"Cevat Akkanat","poet_slug":"cevat-akkanat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/davet-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Teslisi (Kutsal Dörtleme)', 'askin-teslisi-kutsal-dortleme-ozan-durmaz-sp9da', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'I

Varsıllar otel odalarında sevişir, 

Papazlar rüyalarında.

Günahla vaftiz olur herkes 

İlk aşkı bulduğunda, 

Dirileceğim, 

Aşkların içi boşaldığında.

Yükledim çarmıhımı sırtıma...

Dağda yörük çadırıdır, 

Çölde deve hörgücünde gizli.

Yıllık çınar kesersen acımaz bu kadar.

Günahla kutsandı herkes

Dirileceğim, 

Aşkların içi boşaldığında.

Yükledim çarmıhımı sırtıma...

Paçalarıma sıçrayacak kadar

Yolsuzsa aşk

Lağımdan geleceğim

Parmak uçlarınıza kadar, karanfil yağı.

Dirileceğim, 

Aşkların içi boşaldığında.

Yükledim çarmıhımı sırtıma...

Nasır iltihabı akar gibi sıcak

Metal sesi gibi aşk

Günahkar bütün aşıklar

Kurtaracağım Tanrıyı! 

Dirileceğim, 

Aşkların içi boşaldığında.

Yükledim çarmıhımı sırtıma...

Oyuklara kadar saplıdır kan

Mavi akar sürüngende.

Haydi kes kulağını durma! 

Gör! Mavi değilki aşk! 

Dirileceğim, 

Aşkların içi boşaldığında.

Yükledim çarmıhımı sırtıma...

II

Yol, satranç tahtası

Piyonum, bir hamle daha! 

Dama olacağım büyüyünce

Ölüm, sağlıktır, aşk boşandığında.

Dirileceğim, 

Aşkların içi boşaldığında.

Yükledim çarmıhımı sırıtıma...

Kes sesleri bir bıçakla

Sivridir diller yalamada usta

Yalanmak hükmüdür günahın

Kes dilini çarmıhımla.

Dirileceğim, 

Aşkların içi boşaldığında.

Yükledim çarmıhımı sırtıma...

Pigmentlerini sök derinden

Renksizliğin imanındır.

İman et, tek aşka.

Git, iç, öl; doğ sonra benle.

Dirileceğim, 

Aşkların içi boşaldığında.

Yükledim çarmıhımı sırtıma...

III

Geldik deliliğin tapınağına

Şimdi eğil ve tapın

Dua et, körlüğüne, sağırlığına, 

Felç tutmuş batıllıklarına.

Dirileceğim, 

Aşkların içi boşaldığında.

Yükledim çarmıhımı sırtıma...

Koro başlar çalmaya

Öyküsünü imanlı dervişin, 

Çerçevelerini kır manifestonun

Manifesto içinde, büyüttün ya saksıda

Dirileceğim, 

Aşkların içi boşaldığında.

Yükledim çarmıhımı sırtıma...

İtildin, kakıldın, boyandın 

Döndün bahçe çitine

Köhne bir krallığı korumak adına

Sefiller''i okudun kana kana..

Dirileceğim, 

Aşkların içi boşaldığında.

Yükledim çarmıhımı sırtıma...

Toprak sadece Kudüs''te kutsal değil 

Kutsallık çeyiz sandığında.

Sandık kutsal toprakta

Toprakları AŞKIN KRALLIĞI'' nın dört bir yanda! 

Dirileceğim, 

Aşkların içi boşaldığında.

Yükledim çarmıhımı sırtıma...

IV

Son nefeste iner çarmıh

Sırtımdan toprağa.

Şişer toprak, patlar; 

Açılır sandık.

Ölürüm ben bir kere.

Dirilirim ben bir kere- daha, 

Aşkların içi dolar.

Çünkü; 

KRALLIĞI AŞKIN; 

HERYERDEDİR! !', 'I Varsıllar otel odalarında sevişir,  Papazlar rüyalarında. Günahla vaftiz olur herkes  İlk aşkı bulduğunda,  Dirileceğim,  Aşkların içi boş...', ARRAY['Türk Edebiyatı','Şiir','Ozan Durmaz']::text[], 8.5, '{"poet":"Ozan Durmaz","poet_slug":"ozan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":98,"source_url":"https://www.antoloji.com/askin-teslisi-kutsal-dortleme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akide Şekeri', 'akide-sekeri-ozan-durmaz-0dlpi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kavuşmak ikliminin, 

Özlemek mevsiminde, 

Soğuk alıp, aşık olmuştum ben.

Ve buhulu penceremde

Gözyaşların çiğ olmuştu.

Güneşi bekleyen gözlerinde

Gözbebeklerine doğuyordu güneş

Ve karanlıkta ruhumu titreten soluğu

Vermek isterdim göğüslerine doğru, 

Ilgıt ılgıt dudaklarımdan...

İşte böyle bir mevsimin namlusunda

Sarhoştum ve  menzil içinde

Koynuna odaklanıyordu dudaklarım.

Akide şekeri kokuyorduk, 

Ben, dudaklarımda kaybettiğimde seni...

İşte o an, saplandı mevsimin mermisi

Kalbimin  surlarına

İlkin gulyabaniler koştu 

Surlardan kaynadılar kanıma

Tatlı bir su yürüdü, 

Hüzünü süpüremediler yanaklarımdan.

Yüzünü süpüremediler gözlerimden.

Dindi ölüm, 

Bir sokakta nemlicene...

Rutubetli dudaklarımdan, 

Akide şekeri aktı köpük köpük...

Kaldırımlar sen koktu bir anda, 

O kadar ki geçemedi ruhum gökyüzüne...

Kaldı bir Arnavut kaldırımında, 

Paspas niyetine...

Sildiğin ayaklarını.', 'Kavuşmak ikliminin,  Özlemek mevsiminde,  Soğuk alıp, aşık olmuştum ben. Ve buhulu penceremde Gözyaşların çiğ olmuştu. Güneşi bekleyen gözle...', ARRAY['Türk Edebiyatı','Şiir','Ozan Durmaz']::text[], 8.5, '{"poet":"Ozan Durmaz","poet_slug":"ozan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/akide-sekeri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldanma', 'aldanma-ozan-durmaz-uccpq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Taş, kağıt, makas...

Kan oturmuş bilekler

Afrodit hariç...

Kestik bileklerini onun

Hileci bir piç

Ne cıvıltı, ne neşe

Bilirsiniz Venüs'' ü

Kestik sol kulağını onun

Avluda meşeler dizi dizi

Sadece kerpiç var.

Ferhat ütüldü Şirin'' e

Şirin, şimdi, yirmiye açıyor viziteyi

Bir yosmadır Juliet, 

İngiltere'' de bir pavyon karısı.

Romeo, şimdi, kapitalist sermaye

Sonsuz aldattı böylece Juliet'' i

Hepsi de aldattı! 

Hepsi de aldandı! 

İlk hırsız oldular hepsi, 

Aşkın içi boşaldığından beri...', 'Taş, kağıt, makas... Kan oturmuş bilekler Afrodit hariç... Kestik bileklerini onun Hileci bir piç Ne cıvıltı, ne neşe Bilirsiniz Venüs'' ü Ke...', ARRAY['Türk Edebiyatı','Şiir','Ozan Durmaz']::text[], 8.5, '{"poet":"Ozan Durmaz","poet_slug":"ozan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aldanma-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün', 'bir-gun-ozan-durmaz-jwnyn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün karşına çıkarsam

Okul sokağından çıkarken, 

Ki elim pis olur mutlak.

Büyür gözlerin, şaşkın

Bilirim, gözlerinde büyürüm

Bir gün karşına çıkarsam

Ve iki top topuzsa saçın

Yıkılırım, içerim haksızlığına

İçersem eğer, gözlerin büyür.

Bilmediğim bir yerde, 

Çapaklanır gözün.

Çıkmam gözünden

Gözlerinde büyürüm

Bir gün karşına çıkarsam

Ve yine ellerim kutup olur ihtimal

Ve yine; 

Kırmızıdır alnın kutuplarda, 

Dağ gelinciği özleminde.

Gözlerinde eğer, gelincik açıyorsa hala.

Ve isyanı görürsem gözünde

Gözlerinde büyürüm

Bir gün karşına çıkarsam

Ve kan istersen canına canımdan

Cananıma dayanamam

Çıkarır kalbimi veriririm eline

Korkarsan eğer, 

Büyür gözlerin, ilkel

Gözlerinde büyürüm.

Ölürüm; 

Mezar olur gözbebeklerin, 

Bulunamam.', 'Bir gün karşına çıkarsam Okul sokağından çıkarken,  Ki elim pis olur mutlak. Büyür gözlerin, şaşkın Bilirim, gözlerinde büyürüm Bir gün karş...', ARRAY['Türk Edebiyatı','Şiir','Ozan Durmaz']::text[], 8.5, '{"poet":"Ozan Durmaz","poet_slug":"ozan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bir-gun-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Di''li Geçmiş', 'di-li-gecmis-ozan-durmaz-wwpw9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşkın tretuvarında

Yoksul serserilerdik.

Zamanın yokluğundandı 

Şarapların dinginliği.

Çünkü sevmek, 

Dört mevsim, 

''-Di'' li geçmişin, 

Birinci tekiliydi.', 'Aşkın tretuvarında Yoksul serserilerdik. Zamanın yokluğundandı  Şarapların dinginliği. Çünkü sevmek,  Dört mevsim,  ''-Di'' li geçmişin,  Biri...', ARRAY['Türk Edebiyatı','Şiir','Ozan Durmaz']::text[], 8.5, '{"poet":"Ozan Durmaz","poet_slug":"ozan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/di-li-gecmis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Ara', 'o-ara-ozan-durmaz-c5gsh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kadın sesi

Eğer kırmızıysa

Beşik gibidir

Tüm dar sokaklar

Suya yalınayak basmak

Çok gürültülüdür

Kordonboyu

Eğer ağustos böcekliyse

Sımsıkı gürültü

Kurşun sıksan geçmez

Saatler yağ

Kayar gider kafam

Maya tutar ağzım

Şişeler bekçidir

Fenerler uykucu

Ve hırsızdır kadınlar

Kapkaç meşrudur

Yaşasın meşrutiyet! 

Karayollarına mıcır dökmüş hırsızlar

Ben hariç

Zira; 

Hatırlayamıyorum 

Ben o arayı', 'Kadın sesi Eğer kırmızıysa Beşik gibidir Tüm dar sokaklar Suya yalınayak basmak Çok gürültülüdür Kordonboyu Eğer ağustos böcekliyse Sımsıkı ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Durmaz']::text[], 8.5, '{"poet":"Ozan Durmaz","poet_slug":"ozan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/o-ara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek Bakkaliyesi', 'sevmek-bakkaliyesi-ozan-durmaz-bqsvl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Adım var

Tam üzerinde

Kara kaplı defterin

Sevmek Bakkaliyesinde.

Sevmek bakkaliyesi 

Yirmidört saat açık, 

Bakkal Amca sızmazsa, 

Şarabın kırmızılığında.

Şarap, hele ucuzsa

Ve bozuksa bir de

Çok güzel

Sevmek

Diğer türlü

Sevmek

Ne kadar rakı olurdu

Sevmek Bakkaliyesinde

Çünkü tüm rakılar

Daha sarhoş

Aşkı kırmızı şaraplardan

Sevmek Bakkaliyesinde

Sek olsun; 

Nefret

Sarıdır

Sevmek Bakkaliyesinde

Ve tüm anarşistliğiyle

Hayata

Bir o kadarda

Smith''çidir 

Sevmek Bakkaliyesi.', 'Adım var Tam üzerinde Kara kaplı defterin Sevmek Bakkaliyesinde. Sevmek bakkaliyesi  Yirmidört saat açık,  Bakkal Amca sızmazsa,  Şarabın kı...', ARRAY['Türk Edebiyatı','Şiir','Ozan Durmaz']::text[], 8.5, '{"poet":"Ozan Durmaz","poet_slug":"ozan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sevmek-bakkaliyesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Kızlar', 'kucuk-kizlar-ozan-durmaz-b7otj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Küçük kızlar öpüşmez! 

Hele varsıllarsa hiç.

Baharın hariç

Nefesleri ferah, temiz dişler

Ama yakmış parmakları cigar...

Küçük kızlar sevinmez! 

Hele varsıllarsa hiç.

Cuma hariç

Narindir bacaklar, el değmemiş

Haftasonu sığmaz aralarına...

Küçük kızlar sevişmez! 

Hele varsıllarsa hiç.

Barlar hariç

Cepler ağırdır, eller brüttür.

Neti söyleme usta! Boştur! 

Küçük kızlar özgürdür! 

Hele varsıllarsa hep.

Okullar dahil, 

Dışarısı hariç

Kısmi felçtir, ansızın.

Rasyonellik imkanı fakir...', 'Küçük kızlar öpüşmez!  Hele varsıllarsa hiç. Baharın hariç Nefesleri ferah, temiz dişler Ama yakmış parmakları cigar... Küçük kızlar sevinme...', ARRAY['Türk Edebiyatı','Şiir','Ozan Durmaz']::text[], 8.5, '{"poet":"Ozan Durmaz","poet_slug":"ozan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kucuk-kizlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaderin Antı', 'kaderin-anti-ozan-durmaz-0w4cd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilmez miyim nasılda hasret içindesin? 

Görmez miyim sanırsın gözlerinin kıvılcımını? 

Nasılda heves heves kokar sesin! 

Daha ölüm sızmamaış nefesine; 

Ciğerin kara değil! 

Ak, açık bir alnın var! 

Cesaret yazıyor beyninde; bilirim! 

Dinginliğin deprem, 

Haykırışın devrim! 

Bin atlı geçer yüreğinden, 

Nallarını vura vura.

Bini bir tane sen etmez! 

Bin tilki dolanır zihninde, 

Bini bir fikir içinde.

Bininin fikri; senin bir fikrin etmez! 

Bilirim; tam içindesin ateş çemberinin.

Nasılda eser kavga rüzgarı göğsüne! 

Hissederim sıcaklığını hırsının.

Toprağı bereketlendiren sen, 

Başağı büyüten sen, 

Emeği yücelten sen! 

Bilirim bahar bekler canın.

Eyleme! 

Senle bir kış, bin bir bahara bedel! 

Hadi! 

Şimdi esmenin zamanıdır! 

Kışın başlarda tufanın, 

Bahara çiçek açtırır; inanırım.

Gün bugündür ve ilk ışığıyla sabahın, 

Kükremektir ahtı kaderinin!', 'Bilmez miyim nasılda hasret içindesin?  Görmez miyim sanırsın gözlerinin kıvılcımını?  Nasılda heves heves kokar sesin!  Daha ölüm sızmamaış...', ARRAY['Türk Edebiyatı','Şiir','Ozan Durmaz']::text[], 8.5, '{"poet":"Ozan Durmaz","poet_slug":"ozan-durmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kaderin-anti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Benim Beş Duyumsun...', 'sen-benim-bes-duyumsun-ediz-karaoglu-8ky3a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen benim beş duyumsun bitanem, 

Seninle tadını almaya başladım bu dünyanın, 

Geceleri sensizsem eğer, 

Buğulu gözlerle aktığımda anladım görebildiğimi…

Her telefon sesinde kalkışlarım yoktu eskiden, 

Belki duymuyordum, ya da duymak istemediğimdendi, 

Yeni yeni anladım küçük kız seslerin güzelliğini, 

Yeni yen fark ettim şarkıların o en güzel motiflerini…

Ellerini her tuttuğumda heyecanı hissettim, 

Senden her ayrı kaldığımda ise ateşi, 

Denizin kokusunu, kuşların cıvıltısıyla sevmeye başladım…

Şimdi eğer kendime şair diyebiliyorsam, 

İnan ki bu bile sendendir bitanem…

							      02.Ocak.200

Saat: 23: 35

İstanbul', 'Sen benim beş duyumsun bitanem,  Seninle tadını almaya başladım bu dünyanın,  Geceleri sensizsem eğer,  Buğulu gözlerle aktığımda anladım gö...', ARRAY['Türk Edebiyatı','Şiir','Ediz Karaoğlu']::text[], 8.5, '{"poet":"Ediz Karaoğlu","poet_slug":"ediz-karaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-benim-bes-duyumsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaklardan', 'uzaklardan-baris-akm-26sst', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İşte bir ilk gecesi daha

Memleketten uzağa gurbet denen yerin birinde

Otel odası değil de sanki hücre

Duvarlar ayrı, köşeler ayrı geliyor üstüme

Saksıda bir yaprağı sararmış menekşe

Küllükte biraz önceden iki sigara

Solumda bir yatak yalnızlığa gebe

Çarşafında buraların ayazı halay çekmede

Daha ilk, ilk günde

Hiç zaman kaybetmeden gece başında

Mahkemeler kuruluyor gri soluğumda

Tüm sorular cevapsız kalacak olmanın altında

İlk gecesi bu gökyüzünün bu gece

Ay giyinmiş kara çarşafı yok yerinde

Mehtap bilmeyen ay dan geceye

Gece gülmeyen tenden sabaha ne fayda', 'İşte bir ilk gecesi daha Memleketten uzağa gurbet denen yerin birinde Otel odası değil de sanki hücre Duvarlar ayrı, köşeler ayrı geliyor üs...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/uzaklardan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seyirlik Trenler', 'seyirlik-trenler-baris-akm-2j01g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerim doğusunda gün batımının

Biraz burukta olsa kıyıları bakışlarımın

Gönül verdiğim renklerin kanatlarında

Geceyi biraz başka yudumluyorum

Her geçen gün treninin vagonlarına

Yeni yeni adlar takıyorum

Bir gün, iki gün, üç gün

Trenler geçiyor seyretmekle avunuyorum

Boş gitseler akmayacak yaşları gözlerin

Koltukları dolu dolu sevinçlerim

Birine ilişemiyor ardından bakakalıyorum

Küf kokulu istasyonda üşümek mutluluğum', 'Gözlerim doğusunda gün batımının Biraz burukta olsa kıyıları bakışlarımın Gönül verdiğim renklerin kanatlarında Geceyi biraz başka yudumluyo...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seyirlik-trenler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balgözlüm', 'balgozlum-baris-akm-wnmr1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biliyor musun? 

Sana hiç balgözlüm dememiştim

Sen, seni anlamadığımdan şikayetçiydin

Ben, beni anlamadığından

İçimdeki ben-i bilemedin

Yüzümdeki ben gerçeğin

Oysa buzdağıydı o gördüğün

Bakışlarımın köklerindeki zehri anlayamadın

Zordu bal gözlüm

Her gece lacivert denizlerle boğuşmak

Üstüne bir de suçlusu oluşum kaderin

Taş olsa çatlardı, ben un ufak oldum

Düşündümki balgözlüm

Biliyorsun, aşk ölmüştü de sevgi kalsın

Üstünü sade bir toprak örtsün nişanlarımızın

O gün kalbimi hatıralarla ateşe verdin

Aşkı kahve fincanlarında sordun

Göremedin soluyordu rengi çiçeklerin

Çok yakındı çatırtısı dağın

İşte bak şimdi altındayım karların

Tüm acısına rağmen dikenlerin

Çok denedim balgözlüm

Kalbimin tümünü bir araya getiremedim

Değişik zamanların tuzunu bir başıma içtim

Dayanmayı çok denedim, olmadı bal gözlüm

Evet balgözlüm

Biliyorum ya da umuyorum

Gelmediyse eğer, o gün gelecek bana hak vereceksin

O güne kadar aşkınla lanetli kalmaya razıyım

Tek dileğim senin için o gün geç kalmasın', 'Biliyor musun?  Sana hiç balgözlüm dememiştim Sen, seni anlamadığımdan şikayetçiydin Ben, beni anlamadığından İçimdeki ben-i bilemedin Yüzüm...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/balgozlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Kalpler', 'kayip-kalpler-baris-akm-4jj9m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çocukluğumdan hala hatırımda

Bir el uzanırken bir arkadaşa

Ya da ilk kez birine

Kalplerimiz olurdu avuçlarımızda

Ne oldu da biz büyüdükçe günden güne

Dikenler boy verdi 

Pençeye dönüştükçe avuçlarımızda', 'Çocukluğumdan hala hatırımda Bir el uzanırken bir arkadaşa Ya da ilk kez birine Kalplerimiz olurdu avuçlarımızda Ne oldu da biz büyüdükçe gü...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kayip-kalpler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Gelir', 'gun-gelir-baris-akm-9zwul', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gün gelir gri kelebekler bile dönmez etrafında

Hasret kalırsın bir sivrisinek vızıltısına

Unutursun uğur böceğini günün birinde

Sende inanırsın mum ışığı olduğuna

Dayanamazsın geçen bir gölgenin bile rüzgarına

Yoksa seni kuşatan bir cam kavanozun etrafında

Yumuşak bir el nazikçe tenini sarmıyorsa

Titreyen ışığına bir çift göz sevgiyle bakmıyorsa

Güneşten yahut yıldızlardan farkın olmasa da

Ömrün bir mum sönümü olsa da

Yaşamak için var olduğunu düşündüğünde

Bir pervane böceği bile bulamazsın etrafında

Çok değil dündü daha

İç geçiren kalpler etrafında

Gözlerini dikenler gözlerinin derinlerine

Şimdi pişman mı olmalısın kalp taşıdığına?', 'Gün gelir gri kelebekler bile dönmez etrafında Hasret kalırsın bir sivrisinek vızıltısına Unutursun uğur böceğini günün birinde Sende inanır...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gun-gelir-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğrenmenin Faturası', 'ogrenmenin-faturasi-baris-akm-qfyso', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eskiden tutturulurdu her bakılan gözde

Hiç evlenmemiş ne kelime illede bakir olacak diye

Evlenmezdi armudun sapında, üzümün çöpünde

Yanağında yahut kalçasında gamzesi yok dedikçe

Göğüsleri küçük emziremez düşüncesinde

Kalçaları dar çocuğu olmaz belkileri ile

Sakalı çıkmamış, bıyığı yok dudak üstünde

Saçları seyrelmiş yirmibeşinde daha

Gün gelir hah işte, buldun tam sana göre

Eldeğmemiş eline, ten tenine

Söz nişan derken girdin gerdek evine

Başın göğe erdi mi? evlendinde

Üç gün beş gün maskeler düşer halıların yüzüne

Her şey istediğin gibiydi ama

Meğer ne çok yanlış varmış perdelerin desenlerinde

El değmemişti, izi yoktu yabanın tende ya

Hadi düşün şimdi al başını ellerinin arasınada

Nerede yanlış yaptım savaşları kalbinde

Razı olurdun değil mi, hiç bir şey aramaydın da

Bir tek aklı uysaydı aklına', 'Eskiden tutturulurdu her bakılan gözde Hiç evlenmemiş ne kelime illede bakir olacak diye Evlenmezdi armudun sapında, üzümün çöpünde Yanağınd...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ogrenmenin-faturasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapı Tokmağı', 'kapi-tokmagi-baris-akm-f0uw3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kapı tokmağı deyipte geçme

Bilir misin ne sırlar gizlidir orada? 

Bir senin el kokun yığılmamışsa üst üste

Arkadaşların yahut dostların varsa

Yahut çoluk çocuk keyifle hep birlikte

Ya kimsen yoksa in cin top peşinde

Bir başınaysan kalabalık meydanlarda

Ne fark eder ha bir iz, ha binlerce

Orada özlediğin elin sıcaklığı yoksa

Kokusu odadan odalara ya

Anlarsın gün gelip kapın tahta olunca tabuta

Bilsen nasıl özlenir bir satıcının sesi bile

Hani o kızıp kovaladığın bir zamanlarda

Boynunu büküp kandilini kutlayan çocuklar nerede

Kapıcı Rüstem Efendi, komşunun minik bebeği birde

Hepsini herkesi özlersin gurbette 

En çok da kendini memleketin kaldırımlarında', 'Kapı tokmağı deyipte geçme Bilir misin ne sırlar gizlidir orada?  Bir senin el kokun yığılmamışsa üst üste Arkadaşların yahut dostların vars...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kapi-tokmagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Padişahım Sen Çok Yaşa', 'padisahim-sen-cok-yasa-baris-akm-o5zzl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Padişahım sen çok yaşa

Etrafında dört başı mamur dalkavukların

Ardında yemediğin, önünde yediğin

Şan-şöhret nam senin

Gam kasavet sokakları dolduranların

Padişahım sen çok yaşa

Yüksekten bak o kalabalık kölen

Üç kuruş ver kapı kulun emirerin

Kadını koparırsın kocasından, ocağından

Bir şıklasın iki parmağın

Padişahım sen çok yaşa

Ziyafetler çek şarlatanlar efradın

Köpeğini biftekle beklemek hakkın

Sokaktakiler soysuz sen soylusun

Çok gelir onlara artıkların

Padişahım sen çok yaşa

Ki memleket bağları üzüm versin

Mahzenler senin için dolup taşsın

Şeriatı göster kapındaki dilenci sussun

Elini savur kellesi duvarını süslesin

Padişahım sen çok yaşa

Tebdil-i kıyafet etmeyesin sakın

Çığlıklar kimin için bilmeyesin

Olurda içinde çiçek açarsın

Maazaallah işte o zaman yandın

Padişahım sen çok yaşa

Bu Dünya senin dünyan

Cuma''ya gitmekle sanmaki ahrette senin

Hacca gitmekle silinir günahın

Kefenini yumaya yetmez zemzemin

Padişahım sen çok yaşa

Astığın astık, kestiğin kestik senin

Yollar boyu sürüler senin

Mühür sende Süleyman sensin

Ben karnından bağladığın kulun', 'Padişahım sen çok yaşa Etrafında dört başı mamur dalkavukların Ardında yemediğin, önünde yediğin Şan-şöhret nam senin Gam kasavet sokakları ...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/padisahim-sen-cok-yasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sendeyim Ben', 'sendeyim-ben-murat-cimen-2-njven', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne saçmalıklar var,

Ne de kötü anılar.

Seni üç dört saat önce

Bıraktığım yerdeyim ben 

Seni seviyorum derken 

Kalbimin atışındayım ben 

Şimdi sana hoşçakal iki gözüm

İlk göz ağrım derken

Gözümden akan bir damla yaştayım ben

seNi seviyoruM 

Giderken beni de götür yanında 

Burda kalsam neye yarar 

Ben şimdi nerdeyim kimbilir

En son hatırladığım 

Bir yudum sendeyim ben 

(03 Ocak 2003 / Sefaköy)', 'Ne saçmalıklar var, Ne de kötü anılar. Seni üç dört saat önce Bıraktığım yerdeyim ben  Seni seviyorum derken  Kalbimin atışındayım ben  Şimd...', ARRAY['Türk Edebiyatı','Şiir','Murat Çimen 2']::text[], 8.5, '{"poet":"Murat Çimen 2","poet_slug":"murat-cimen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sendeyim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüşün', 'gulusun-abdusselam-bugur-iifvo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gün biter gülüşün onda kalır belki de

Görmeme engel bu dağlar, çöksünler dibe.

Kayıp giderken bulutlar, tutunurum belki de

Ilık bir yağmur gibi, damla damla yağarım şehrine.

***

Gün biter gülüşün onda kalır belki de

Hep seni düşünürüm yıldızlar sevişirken gökyüzünde.

Yaşanan o güzel dünler canlanırken gözümde

Gönlümü hasretin sarar, fırtınalar kopar içimde.

***

Gün biter gülüşün onda kalır belki de

İçimde bir yalnızlık başlar sensiz gecem de. 

Sana kavuşamadan bir gün ölsem de

Dilimin ucunda sen olacaksın en son nefesim de.

***', 'Gün biter gülüşün onda kalır belki de Görmeme engel bu dağlar, çöksünler dibe. Kayıp giderken bulutlar, tutunurum belki de Ilık bir yağmur g...', ARRAY['Türk Edebiyatı','Şiir','Abdüsselam Bügür']::text[], 8.5, '{"poet":"Abdüsselam Bügür","poet_slug":"abdusselam-bugur","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gulusun-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Namın Yürüsün', 'namin-yurusun-ugur-arslan-byqbp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hüzünlü bir kış günü başladı yolculuğum

çocukluğum yıkık kentlerde

ve kesme kaya caddeli ahşap evlerde geçti

okuma yazmayı öğrendiğim gazetelerdeki terör sayfaları

ve haliç tersanelerinde korsanlar

evden çıkarken vedalaşırdı babalarla evlatlar

her sokağın başında anaların isyanı dururdu

ve günler kısa

ama geceler uzun olurdu

bir kurşun bir liraya

ve bir hayat bir kurşuna malolur

benim doğduğum yerlerde insanlar can evinden vurulurdu

sen sarayburnunun dimdik delikanlısı

yavuz zurhlısında deniz piyade eri

yetmişikiye dört çakı gibi asker

arkadaşının kaza kurşunu izini sırtında taşıyan

ve giderken bıraktığı sevdiğini

döndüğünde bulamıyan

yakar mı bizi bu sevda? 

bir aşk delikanlıyı bozar mı? 

hadi kalk

eski günlerde olduğu gibi

karanlığa yine ışık yak

arka bahçedeki mahalle kavgalarında

kaşına sapan taşı geldiğinden beri

hani kanına kanımı sürdüğüm o günden beri

can dostum ve kan dostum

ister kalbine gömdüğün sevdanın aşkın

ister Allahın aşkına kalk

bir ışık yak

bir kor küşür yüreğimize

savaşmak ne güzel bir şey uğrunda

ve yeniden

yeniden aşık olmak

unutmadık o günleri

sevdamız yüreğimizde gizli kalır

ve mahallemizin kızına aşık olmak ayıp sayılırdı

bir kıza aşık olmak bir de parkayı çıkarmak haramdı

ve dünya dedikleri şey yalandı

paranın geçmediği günler vardı gençliğimizde

ve namerdin yıkamadığı mertliğimiz

silah çekmek ve tesbih sallamak değildi delikanlılık

tesbihi çekmek ve silahı saklamaktı

yazık

gün geldi nasıl da azaldık

sonra üç kuruşa satılan arkadaşlıklar ve ucuz aşklar

artık bizim işimiz değildi

ah sarayburnunun dik ve yitik delikanlısı

ne geçmişten yükselen ağıtlar anlıyor seni

ne de geleceğe satılan aşklar

gidiyorsun belki

sana kal diyemem giderken

sevmek kadar ölmek de kader

ama giderken bile ışığın yol göstersin kayıp gemilere

gözlerin gökyüzünü aydınlığa bürüsün

ve sen ölsen bile bir gün

namın yürüsün...', 'hüzünlü bir kış günü başladı yolculuğum çocukluğum yıkık kentlerde ve kesme kaya caddeli ahşap evlerde geçti okuma yazmayı öğrendiğim gazete...', ARRAY['Türk Edebiyatı','Şiir','Uğur Arslan']::text[], 8.5, '{"poet":"Uğur Arslan","poet_slug":"ugur-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/namin-yurusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Denizi', 'sevgi-denizi-tahsin-kavak-b97h0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yepyeni bir denizi yüz yıl eskileştirsek 

İşte bu kadar yıldır seviyordum ben seni, 

Bir sahilin kumlarını tek tek okşamak gibi

Deniz minaresini bir ömre dizmek gibi

Denizlerimdeki yeşili sen çaldın

Rahat mısın bari? 

Yapılır mı? 

Korsan töresine aykırı 

Sana o yeşil bize çok gerekli demedik miydi, 

Hiç mi düşünmedin istiridyelerin yüreklerini? 

Tut ki alaca karanlıkta bir şangırtı koptu şimdi, 

Bir adam denize bıraktı kendini usulca, 

Usulca ayaklarına bağlayarak sevgisini, 

İki damla göz yaşı istesek, yollar mısın ki? 

Deniz ölülerine mezar taşı dikilmez bilirsin, 

Kaç yıl sonra da olsa bir deniz görsen, 

Yanında kocan da olsa bir deniz görsen

Hala duruyorsa gözlerindeki o yeşil sevgi, 

Ve denize bakınca buğulanırsa yeşil gözlerin

Kocandan sakla, kıskanır belki.

Şimdi kaç bin metre derindeyim bilmiyorum, 

İndiğimde bir perişandı deniz dipleri, 

Yosunlar yeşillerini unutmuşlardı

Tuz buz olmuştu istiridyelerin yürekleri, 

Önce gözlerinin yeşilini anlattım yosunlara, 

Verdim yanımda ne getirdiysem hepsini

Sonra, bir bir topladım istiridyelerin yüreklerini 

Şimdi bir yeryüzü öyküsü ile ben onları avutuyorum, 

Bütün denizaltı güzellikleri ile onlar da beni.', 'Yepyeni bir denizi yüz yıl eskileştirsek  İşte bu kadar yıldır seviyordum ben seni,  Bir sahilin kumlarını tek tek okşamak gibi Deniz minare...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Kavak']::text[], 8.5, '{"poet":"Tahsin Kavak","poet_slug":"tahsin-kavak","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sevgi-denizi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanetin Tadına Baktın Sen', 'i-hanetin-tadina-baktin-sen-ozan-rari-j3zy6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anlıyorum şimdi artık seni, alışmışsın bir kere vazgeçemiyorsun

Hep yeni bir sevgi, başka hayaller ve ardında bir enkaz! 

Oysa ne kadar güzel oynuyordun benimleyken

Bir gün ümit verirdin, başka gün hayaller kurmamı sağlıyordun

Hep sen vardın herşey sen demekti

Sensizlik en büyük korkuydu

Ayrılık kabusların sebebiydi

Sadece bir gecelik aşk idim senin nazarında

Tıpkı diğerleri gibi geçmişimde...

Basit idi herşey, kolaydı senin gözünde

Yönetmen sen oyuncu ben idim! 

Derken sıra bana gelmişti artık kovulmuştum sürem dolmuştu senin yaşamında

Hayallerim, sevgim, güvenim  herşeyim hepsi yok olmuştu

Aşkım artık başka sevdaların peşine koştu

Yeni bir kurban onun istediği şeydi! ! ! 

Ben şimdilerde pek fenayım sensizim

İlk aşkımdın sen, en çok sevdiğimdin bugüne kadar

Sıcaklıktın, bendin, herşeydin sen...

Kaldım işte burda yalnız başıma erdin muradına! 

Herşey olabilir kabul ediyorum ama niye ben? 

Keşke aramasaydın beni

Keşke seni görmeseydim

Keşke seni hiç sevmeseydim

Keşke bu kadar saf olmasaydım

Diyorum ama ne çare! ! ! 

Sen ihanetin diğer adısın artık benim için

Hayatın çirkin yüzüsün sen, 

Olmaması, yaşanmaması gereken tarafısın

En güzel duyguların celadısın

İttin kendi ellerinle altımdaki tabureyi, 

Kırıldı boynum, sallanıyorum boşlukta

Ölüm sen mişsin meğer...

(Tüm acı çeken ruhlara ithafen)', 'Anlıyorum şimdi artık seni, alışmışsın bir kere vazgeçemiyorsun Hep yeni bir sevgi, başka hayaller ve ardında bir enkaz!  Oysa ne kadar güze...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ihanetin-tadina-baktin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Geceler', 'kara-geceler-ozan-rari-eyj9q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geceler benim gündüzüm, 

Geceler yalnız kaldığım zamanım, 

Geceler vicdanım, 

Geceler hatıralarımı yaşatanım, 

Gecelerim benim tek aşkım...

(Geceleri sevenlere ithafen)', 'Geceler benim gündüzüm,  Geceler yalnız kaldığım zamanım,  Geceler vicdanım,  Geceler hatıralarımı yaşatanım,  Gecelerim benim tek aşkım... ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kara-geceler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredeyse Eksiksiz', 'neredeyse-eksiksiz-yannis-ritsos-nron8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biliyorsun, ölüm diye bir şey yok, diyor adam kadına.

Biliyorum, evet, artık öldüğüme göre, diyor kadın.

İki gömleğin de ütülendi, çekmecede, 

sadece küçük bir gül benim özlediğim.

Çev. Cevat Çapan', 'Biliyorsun, ölüm diye bir şey yok, diyor adam kadına. Biliyorum, evet, artık öldüğüme göre, diyor kadın. İki gömleğin de ütülendi, çekmecede...', ARRAY['Türk Edebiyatı','Şiir','Yannis Ritsos']::text[], 8.5, '{"poet":"Yannis Ritsos","poet_slug":"yannis-ritsos","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/neredeyse-eksiksiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin', 'gittin-yusuf-kenan-caglar-441xs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gittin bir sabah yağan yağmurla, 

benden bir şeyler alarak.

böyle olmayacaktı ayrılığımız, 

beni böyle bir başıma...

kimbilir hangi nehirlere karıştın, 

ordan hangi denize.? 

seni hep bekleyeceğim.

belki bir gün yağmur olup, 

yağacaksın üzerime....

                               29.12.2002', 'gittin bir sabah yağan yağmurla,  benden bir şeyler alarak. böyle olmayacaktı ayrılığımız,  beni böyle bir başıma... kimbilir hangi nehirler...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Kenan Çağlar']::text[], 8.5, '{"poet":"Yusuf Kenan Çağlar","poet_slug":"yusuf-kenan-caglar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gittin-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Yüzünden', 'senin-yuzunden-abdulkadir-karaman-bbww8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senin yüzünden…

terk edersem bu diyarı…

geri gelmezsem; 

senin yüzünden, 

yüreğimdeki sızılar, 

döktüğüm gözyaşları.

İçimde sönmeyen yangın

saklandığım sır

olduğum; her şeye, herkese kırgın

ve sürekli dalgın…

senin yüzünden

yapmışsa sevdâ canımda salgın.

Söylemişsem hüzünlü şarkılar 

ve yazmışsam hasret şiirleri

senin yüzünden

suçlu değil birileri.

Dile düştüğüm

tanınamaz hâle düştüğüm

senin yüzünden

kul olduğum, köle düştüğüm.

Değişmez hayat rotamı,

değiştirmem; 

tepeden tırnağa giyimimi, kuşamımı 

yürüyüşümü, gülüşümü, düşünüşümü 

yeniden şekillendirmem; 

 ve terk etmem bütün güzel alışkanlıkları…

senin yüzünden; 

yapmaya başlamam,

yapmayı hiç düşünmediğim yanlışları. 

Nefret etmişsem sevdiklerimden,

sevmeye başlamışsam nefret ettiklerimi

kimsiz, kimsesiz kalmışsam, 

senin yüzünden 

çekiyorum 

bütün çektiklerimi.

Bir çırpıda unutmam, 

silip atmam gerekirse, 

geçmiş unutulmaz ânları, 

senin yüzünden; 

binlerce kez tepelemem, 

ayaklarımı kanatan, 

içimi acıtan,

ayrılığa götüren kahırlı yolları.

meğer ne kadar yanlış tanımışım

ve ne kadar hatâ etmişim 

sana inanmakta, 

hakkında ne denli yanılmışım, 

zorlansam da kabullenmekte ve anlamakta, 

eğer yüksünüyorsam canı taşımakta…

bil ki sensin tek sebebi

ve senin yüzünden 

ölmekte…

yaşamakta…

02.01.03', 'Senin yüzünden… terk edersem bu diyarı… geri gelmezsem;  senin yüzünden,  yüreğimdeki sızılar,  döktüğüm gözyaşları. İçimde sönmeyen yangın ...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/senin-yuzunden-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine', 'yine-umit-turan-2h9f5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yine akşamlara demirleyecekse sabahlar

hüzne gidecekse dalga boyu düşünceler

için için bir sızı saplanacaksa yüreğime

doğmasın güneş

sabahlar soğuk ellerim ayaz

yine üşüyeceksem loş odalarda

mevsimler bir beni solduracaksa

gelmesin bahar

yine gözlerim yollarda kalacaksa

sevda bestelerinin en acısını kuracaksam

ellerin ellerimden yavaşça kayacaksa

olmasın aşk

yine bakışlar öfke dolu olacaksa

keder dolu saatler her aradığında beni bulacaksa

dudaklar paslı kilitlere inat susacaksa

dursun saatler

yine rüzgarlar esecekse deli deli

yağmurlar yağacaksa sicim sicim

toprak içecekse bir mazlumun ahını yavaşça

yağmasın yağmurlar', 'yine akşamlara demirleyecekse sabahlar hüzne gidecekse dalga boyu düşünceler için için bir sızı saplanacaksa yüreğime doğmasın güneş sabahla...', ARRAY['Türk Edebiyatı','Şiir','Ümit Turan']::text[], 8.5, '{"poet":"Ümit Turan","poet_slug":"umit-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yine-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meşhur Laleli!', 'meshur-laleli-abdullah-golbasi-lq5ky', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geçen akşam Laleli’deydim, 

Dostlar…

İçki, sigara bol muhabbet…

Güzel bir geceydi, 

Seni aradım, oralarda 

Hatta sordum, 

Dedim ki; 

Herkes buralarda mı? 

Dediler ki, 

Olur mu öyle hiç? 

Biz bedenimizi satıyoruz, 

Ruhunu satanlar giremez…', 'Geçen akşam Laleli’deydim,  Dostlar… İçki, sigara bol muhabbet… Güzel bir geceydi,  Seni aradım, oralarda  Hatta sordum,  Dedim ki;  Herkes ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Gölbaşı']::text[], 8.5, '{"poet":"Abdullah Gölbaşı","poet_slug":"abdullah-golbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/meshur-laleli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kireçli Kuyu!', 'kirecli-kuyu-abdullah-golbasi-3dm3g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Vakit geldi, yazılacak elbet

Vakit geldi, sorulacak elbet

Vakit geldi, hasret öldü ve gömülecek

Kimsem tutmasın dört bir yanından.

Ben doğurdum kasıklarımı yırta yırta 

Ben büyüttüm binbir yoklukla

Ciğerlerimi söktüm o’na verdim

Gözlerimi oydum o’na verdim

Ellerimi kopardım o’na verdim

Dünyamı verdim oynaşsın diye

Ama öldü…

Hasret öldü! 

Bilinen bir marazdan öldü.

Cümle alem duymasın, 

Kimse dokunmasın kaldırım gülüne, 

Kimse tutmasın ucundan.

Hasret öldü! 

Ve hatta! 

Kireçlenerek gömüldü!', 'Vakit geldi, yazılacak elbet Vakit geldi, sorulacak elbet Vakit geldi, hasret öldü ve gömülecek Kimsem tutmasın dört bir yanından. Ben doğur...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Gölbaşı']::text[], 8.5, '{"poet":"Abdullah Gölbaşı","poet_slug":"abdullah-golbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kirecli-kuyu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alacağım var!', 'alacagim-var-abdullah-golbasi-jqxj7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hakkım var soracağım, 

Hakkım var helal etmiyorum, 

Lanet olsun yok! 

Allah’ından bul da yok! 

Nedensiz, 

Niçinsiz, 

Nasılsız da yok! 

Kanayan yaram, 

Acıyan canım, 

Susmayan yüreğim, 

Isırdığım dilim, 

Kinim! 

İntikam yeminim de var! 

Değersin, değersin, değersin! 

Ve sen, 

Yazıyla yüz dolarsın!', 'Hakkım var soracağım,  Hakkım var helal etmiyorum,  Lanet olsun yok!  Allah’ından bul da yok!  Nedensiz,  Niçinsiz,  Nasılsız da yok!  Kanay...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Gölbaşı']::text[], 8.5, '{"poet":"Abdullah Gölbaşı","poet_slug":"abdullah-golbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/alacagim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ela do Turco Ela do', 'ela-do-turco-ela-do-i-hsan-uncuoglu-kr7i0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ela do Turco Ela do

/Kuzey Kıbrıs''ta Sayın Rauf Denktaşa''a karşı olanlara, , , / 

Aklımızı 

peynir ekmekle 

yemedik daha burada! , 

Kim oluyor şimdi 

Kuzey Kıbrısta

Kimlerdir onlar

Ardında yırtınanlar

Çözüm lafı numarası 

Elin kolun sallayarak

Türkleri öldürenler 

Dozerle mezarlara gömenler 

Avrupalı uygarlar

Uygar Albay Grivası 

Para-van-lis''i 

Fır-lama-pulos''u 

Nikos sampsonu 

Yıldız Papaz Makariosu

İngiliz Yunan Dostu

Haklıyı haksız çıkaran 

Asaletine toz kondurmayan 

Birleşmiş Milletlerden çıkan

Anlaşmış Milletleri 

Güya Başkanlarını 

Şimdilerde Annan''ı 

Alavere Dalavere

Kel başlı de soto''su

Oyun içinde oyunu

Taktikleri göremeyen

Aklından yoksunu 

Anadoluyu

Anmayarak! 

Papandreu Simitisi 

Kleridesi

Selamlayarak! 

Sorumluluk almadan 

Beş para etmeyenler 

Arkada saklanana saklanan 

Her bakımdan değersizler! 

Dilin çıkarır Denktaş''a

Bindikleri dalı keserler 

Lefkoşa meydanında! ,', 'Ela do Turco Ela do /Kuzey Kıbrıs''ta Sayın Rauf Denktaşa''a karşı olanlara, , , /  Aklımızı  peynir ekmekle  yemedik daha burada! ,  Kim oluy...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/ela-do-turco-ela-do-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnanamadım', 'i-nanamadim-mehmet-bor-zvwus', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gece yarısıydı 

hatta sabaha yakın

Ahizeyi kaldırdığımda

titrek bir ses

Benimle görüşmek istiyordu

Benim diyordum konuşamıyordu.

Toparlandı sanırım

çıkardı ağzındakini

yaralı demişti senin için

yüreğim ince, ince

yırtılıyordu sanki

inanmamış gerçeği söylemesini

istemiştim.

Metanetliyimdir demiştim.

itiraf etti sonunda

senin öldüğünü..

Kapatamadım telefonu 

başımı ellerimin arasına alıp

yıkıldım, çöktüm oracığa.

soramamıştım bile

nasıl olduğunu.

öyle ne kadar kaldığımı

hatırlamıyorum.

Toparlandım.

yanına gitmek için.

Yola çıktığımda

Kan çanağıydı gözlerim

yollar da uzuyordu sanki

sonun da sana vardım.

Morgtaydın.

Bayrağa sarmışlardı.

Dayanamadım.

Açın, açın lütfen..

görmek istiyorum 

yalvardım, yalvardım..

açtılar sonunda.

Öyle güzeldi ki yüzün

biran yaşadığını sandım

yaşıyor, yaşıyor

ölmemiş diyerek

bağırdım, bağırdım, bağırdım..

hıçkırıklara boğuldum

tutamıyordum kendimi 

gerçekten ölmüştün

Duyuramadım, duyuramadım

sana kendimi.

03.01.2003

(İsmail Bor''un anısına)', 'Gece yarısıydı  hatta sabaha yakın Ahizeyi kaldırdığımda titrek bir ses Benimle görüşmek istiyordu Benim diyordum konuşamıyordu. Toparlandı ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bor']::text[], 8.5, '{"poet":"Mehmet Bor","poet_slug":"mehmet-bor","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/inanamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birsen', 'birsen-eymen-ozcelik-erupf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Umudumun doruk noktasında anlatıyorum seni

Çiğdem çiçeklerinin mitolojik havasında

Tales’in  yok oluşunun savunuculuğunda 

Musa’nın ikiye ayırdığı denizin tam ortasında, 

Anlatıyorum seni ilk gördüğüm günün yarısında. 

Sanki; 

Gözlerin dalgasız bir deniz umudu yansıtan

Güneşten kopup gelen bir ışık bakışların

Çığlıklarda unutulan sessizlik gibi

Ağıtlarda söylenen bir ölüm yakarışların.

Anlatılması güç bir bütünlüğün

Paydasına bölünemeyenlerindensin

Matematik kurallarının dışında kalan

Beni bölebilen tek etkili eleman

1-sen’sin...', 'Umudumun doruk noktasında anlatıyorum seni Çiğdem çiçeklerinin mitolojik havasında Tales’in  yok oluşunun savunuculuğunda  Musa’nın ikiye ay...', ARRAY['Türk Edebiyatı','Şiir','Eymen Özçelik']::text[], 8.5, '{"poet":"Eymen Özçelik","poet_slug":"eymen-ozcelik","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/birsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müslümanlık Nerde', 'muslumanlik-nerde-mehmet-akif-ersoy-snmz8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Müslümanlık nerde! Bizden geçmiş insanlık bile... 

Adem aldatmaksa maksad, aldanan yok, nafile! 

Kaç hakiki müslüman gördümse, hep makberdedir; 

Müslümanlık, bilmem amma, galiba göklerdedir; 

İstemem, dursun o payansız mefahir bir yana... 

Gösterin ecdada az çok benziyen kan bana! 

İsterim sizlerde görmek ırkınızdan yadigar, 

Çok değil, ancak Necip evlada layık tek şiar. 

Varsa şayet, söyleyin, bir parçacık insafınız: 

Böyle kansız mıydı -haşa- kahraman ecdadınız? 

Böyle düşmüş müydü herkes ayrılık sevdasına? 

Benzeyip şirazesiz bir mushafın eczasına, 

Hiç görülmüş müydü olsun kayd-i vahdet tarumar? 

Böyle olmuş muydu millet canevinden rahnedar? 

Böyle açlıktan boğazlar mıydı kardeş kardeşi? 

Böyle adet miydi bi-perva, yemek insan leşi? 

Irzımızdır çiğnenen, evladımızdır doğranan... 

Hey sıkılmaz, ağlamazsan, bari gülmekten utan! ... 

"His" denen devletliden olsaydı halkın behresi: 

Payitahtından bugün taşmazdı sarhoş naresi! 

Kurd uzaklardan bakar, dalgın görürmüş merkebi. 

Saldırırmış ansızın yaydan boşanmış ok gibi. 

Lakin, aşk olsun ki, aldırmaz otlarmış eşek, 

Sanki tavşanmış gelen, yahut kılıksız köstebek! 

Kâr sayarmış bir tutam ot fazla olsun yutmayı... 

Hasmı, derken, çullanırmış yutmadan son lokmayı! ... 

Bu hakikattir bu, şaşmaz, bildiğin usluba sok: 

Halimiz merkeple kurdun aynı, asla farkı yok. 

Burnumuzdan tuttu düşman; biz boğaz kaydındayız; 

Bir bakın: hala mı hala ihtiras ardındayız! 

Saygısızlık elverir... Bir parça olsun arlanın: 

Vakti çoktan geldi, hem geçmektedir arlanmanın! 

Davranın haykırmadan nakus-u izmihaliniz... 

Öyle bir buhrana sapmıştır ki, zira, halimiz: 

Zevke dalmak söyle dursun, vaktiniz yok mateme! 

Davranın zira gülünç olduk bütün bir aleme, 

Bekleşirken gökte yüz binlerce ervah, intikam; 

Yerde kalmış, naşa benzer kavm için durmak haram! ... 

Kahraman ecdadınızdan sizde bir kan yok mudur? 

Yoksa, istikbalinizden korkulur, pek korkulur.', 'Müslümanlık nerde! Bizden geçmiş insanlık bile...  Adem aldatmaksa maksad, aldanan yok, nafile!  Kaç hakiki müslüman gördümse, hep makberded...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Ersoy']::text[], 8.5, '{"poet":"Mehmet Akif Ersoy","poet_slug":"mehmet-akif-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/muslumanlik-nerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Fanusun Islak Sessizliği', 'bir-fanusun-islak-sessizligi-siar-yilmaz-x7kg9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir Fanusun Islak Sessizliğinde

GözlerinleOturmuş

Eski Bir Masal Kuşunu Konuşuyoruz

Ama Gözlerin Yok...

Bir Fanusun Islak Sessizliğinde

Karanlığı Dinliyorum...

Sokaklar, 

Duyulmayan Bir Çığlık

Sessizliğin Gibi

Ama Suretin Yok...

Bir Fanusun Islak Sessizliğinde

Vatansızlığım Kalmıştı

Aşk...Gözlerin..

Ve Yüreğim

Bir Palyaçonun

Yıkılmış Kalelerine Dökülen

Gözyaşları Gibi

Bir Fanusun Islak Sessizliği...

                     (Ankara, Ocak,2003)', 'Bir Fanusun Islak Sessizliğinde GözlerinleOturmuş Eski Bir Masal Kuşunu Konuşuyoruz Ama Gözlerin Yok... Bir Fanusun Islak Sessizliğinde Kara...', ARRAY['Türk Edebiyatı','Şiir','Şiar Yılmaz']::text[], 8.5, '{"poet":"Şiar Yılmaz","poet_slug":"siar-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-fanusun-islak-sessizligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aylin''e', 'aylin-e-ozan-rari-ya0ld', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yeni bir insan var karşımda

Bana gülüşü, kendi neşesi o kadar sıcak ki

Benziyor duygulaı, düşünceleri hatta çektiği acıları bana

Korkuları sarıyor benliğini küsmüşcesine bazı değerlere! 

Bir garip arayış içinde tanıştık onunla

Olurya hani iki yabancı tanışıri kanları çeker birbirini

İşte buna benzer Aylin''le halim kısa zaman sürecimizde

Sabahlara kadar akan gözyaşları, edilen nasihat ve çıkarılan dersler sonunda

Süre mühim değil derdi bana, önemli olan güvendi! 

Onun brucuda terazi kimi zaman karamsar

Aksine bazen insanları imrendiren, niye ben böyle değilim dedirten! 

Çok sadık kesinlikle sözünün arkasında harbi bi kız o

Birde onun en yakını var yakınlarında 

Sırdaşı, herşeyi paylaştığı dostu Nahide

Gönül isterdiki onunla daha nice günlere beraber başlamak

Ama bu kadarıyla bitecek olsada tanıştığımıza çok memnun oldum minik kız...

TÜm güzeliğini koruman ve kaybetmemen dileğiyle

Sana yakın olan adam! 

(Güzel insan''a ithafen)', 'Yeni bir insan var karşımda Bana gülüşü, kendi neşesi o kadar sıcak ki Benziyor duygulaı, düşünceleri hatta çektiği acıları bana Korkuları s...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/aylin-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Çok Seni Özledim', 'en-cok-seni-ozledim-ozan-rari-ndy1u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tek bir kez olsun sana sarılmayı, 

Göğsümde seni hissetmeyi özledim

Varsın olsun yansın dünya tek biz kalalım! 

Olmaz mı ha aşkım söyle? 

Nefes alıp vermeni, 

Yanı başımda uyumanı, 

Uyurken sana bakmayı  o büyük sonsuzluğu, 

Sabah uyandığımda senin varlığını, 

Bana yaptığın yemekleri, 

O güzel sesinle sevgi sözcükleri söylemeni, 

Vücudunun estetiğini, 

O mis gibi kokan saçını bebeğim, 

Evet o tenini arıyorum gül çiçeğim

Bana alo deyişini, 

Kahkahalarını hatta gözyaşlarını be aşkım

Özlemediğin tek bir şeyin yok! 

Ama hepsi sen yokken olmaz, olmuyor işte yoksun...

Seni çok özledim bebişim...

(İçimdeki umuda ithafen-belki bir gün)', 'Tek bir kez olsun sana sarılmayı,  Göğsümde seni hissetmeyi özledim Varsın olsun yansın dünya tek biz kalalım!  Olmaz mı ha aşkım söyle?  Ne...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/en-cok-seni-ozledim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Sevgi ve Nefretsin', 'sen-sevgi-ve-nefretsin-ozan-rari-vzxpk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgim sonsuz biliyorsun; yaşadın, hissettin Allahın''a kadar

İnkar edemezsin bunu, 

Herşey yalan desende bunlar olamaz gülüm! 

Aslını inkar edebilirsin, 

Nereden geldiğini, 

Kim olduğunu ama sevgimi asla inkar edemezsin canım...

Tek şahidim yüce rabbim aşkım! 

O biliyor, o istedi, o ayırdı bizi bunuda ben biliyorum

Sen sevgiyi ittin elinle bir kenara

Aradın başka birisini her zaman

İstedin hayalindeki erkeği! 

Ama yok öyle birisi be güzelim bunu anla artık

Hayat bize sonsuz hayal dünyası sunmuş, 

Hep isteriz o büyük aşk''ı, bizi anlayan yegane insanı

Nafile o insan bize en yakın, en uygun insanmış meğer

Bu gerçekle yüzleş bir gün...

Başkasının yanındasın mutluyum diyorsun

Belki gerçekten öylesin ya o sana sırırlsıklam aşık olan genç delikanlı o ne halde? 

Umrunda değil biliyorum çünkü inadından ödün vermiyorsun! 

Beni her zaman pasif bilirdin ya, 

Korkak erkek zanederdin beni ya, 

Ben karşılaşabileceğin en büyük yüreğe sahip adamdım oysa! 

Susmak, efendi olamak, saygı göstermek, çekingen, mahçup olmak korkaklıksa ben dünya''daki en korkak adamım o zaman! 

Böyle bilinsin böyle duyulsun varsın...

Sen benim en büyük sevgilimsin, 

Aynı zamanda beni bir başına bırakan yegane kadınsın! 

Sen kavuşamadığım hasretimsin gül cemalim...

(Hayatta isyan edenlere ithafen_Bilkent 2003)', 'Sevgim sonsuz biliyorsun; yaşadın, hissettin Allahın''a kadar İnkar edemezsin bunu,  Herşey yalan desende bunlar olamaz gülüm!  Aslını inkar ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sen-sevgi-ve-nefretsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili', 'sevgili-ahmet-agdere-wx8uu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bilmiyorum ne kadar zaman oldu görüşmeyeli; 

Akşamları sabahları birbirine kattım sevgili! 

Dünya malını bir hiçe sayar oldum iyice, 

Eller rızkıma ortak oldu sessizce sevgili! 

Tarumar oldum gezerim sokak aralarında, 

Uğruldayan kurt eşlik eder sessizlikte bana...

Bulamadım ne seni ne de onu karşımda; 

Ahır zaman gelmiş haberim yok sevgili!', 'Bilmiyorum ne kadar zaman oldu görüşmeyeli;  Akşamları sabahları birbirine kattım sevgili!  Dünya malını bir hiçe sayar oldum iyice,  Eller ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevgili-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Günün Kutlu Olsun', 'dogum-gunun-kutlu-olsun-refik-recep-pelit-44vom', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Umutla beklenir işte o an

Seni de güldürür geldiği zaman 

Dost dediğin sevdiklerinle heran

Doğum günün kutlu olsun 

Bu dünyada çilesizdir sana sözüm

Mutlu ol sende ağlama iki gözüm 

Bir gün dersin bu oğlum buda kızım

Doğum günün kutlu olsun 

Bitsin hasretlerin, hemen kavuşasın

Darıldıysan eğer acil barışalım 

Sevdiğim değer verdiğim arkadaşım

Doğum günün kutlu olsun 

ikigözüm sakın olaki hüzünlenme 

Bu gün sevinç sana, kıvanç ve neşe 

Mavi bulutların götürdüğü o köşkte

Doğum günün kutlu olsun.', 'Umutla beklenir işte o an Seni de güldürür geldiği zaman  Dost dediğin sevdiklerinle heran Doğum günün kutlu olsun  Bu dünyada çilesizdir sa...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dogum-gunun-kutlu-olsun-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Minik Aşk', 'minik-ask-i-hsan-uncuoglu-kqnw3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Minik Aşk

Nerden bileceksin sevdiğim bilmiyorsun

Görmedik birbirimizi ne ben nede sen

Coşturan kaynağım sen içime doluyorsun

Gönlüm kalbimin derininde seni yaşıyorum, 

***

Duyduğum bütün aşkların üstünde

Zaman zaman olalı başın göğsümde 

Heranım hayalini gönlüme gömüyorum 

Biricik yıldızımsın seni özlüyorum,', 'Minik Aşk Nerden bileceksin sevdiğim bilmiyorsun Görmedik birbirimizi ne ben nede sen Coşturan kaynağım sen içime doluyorsun Gönlüm kalbimin...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/minik-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Okyanusta Bir Gemi', 'okyanusta-bir-gemi-erdogan-ciray-j93fq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne zaman maziye dalsa gözlerim, 

Siz beliriyorsunuz karşımda; Sen ve O...

Önce tatlı tatlı gülümsüyorsunuz bana.

Çözemediğim bir gizemle, ısrarla bakıyorsunuz.

Sanki için için birşeyler anlatıyorsunuz.

Ama sizleri duyamıyorum...

Anlıyamıyorum.

Donup kalıyorum.

Sonra yavaş yavaş rüzgardan uçuşan saçlarınız, 

İçli sıcak bakışlarınız ve nemli titrek dudaklarınız

Taş-toprak misali birbirine karışıyor; 

Senin gözlerin Onda, Onun dudakları sende.

Şaşırıyorum...

Arkasından, kulakları çınlatan, çılgın bir kahkaha...

Sanki benle alay ediyorsunuz.

Lanetliyorum sizi...

Birden derin bir uykudan uyanır gibi oluyorum.

Gecenin ve gördüğüm düşün mahmurluğuyla, 

Gözlerimi ovuşturuyorum.

Farkında olmadan bir sigara yakıyorum.

Şimdi biraz daha iyiyim...

Bizi düşünüyorum; Üçümüzü...

İçim kararıyor.

Neş''em kaçıyor.

Büyük bir huzursuzluk duyuyorum ki

Bazen hayatı, 

Omuzlarımda taşınması güç, bir yük olarak görüyorum.

Bu yükten kurtulmak için, birşeyler yapmak istiyorum.

Olmuyor...

Sonra herşeyden vazgeçiyorum.

Kendimi hayatın akışına bırakıyorum.

Derken! 

Yalnızlık korkusuyla birden irkiliyorum.

Ve...

Son bir çırpınışla, kuru bir dala tutunuyorum...

Ama...

Az sonra o da kırılıyor.

Hayat sellerinde sürüklenip gidiyorum.

Ta ki karşıma yeni biri çıkana kadar.

Bir umuttur içimde bitmek, tükenmek bilmiyor.

Beni rüzgara karşı kürek çekmeye zorluyor.

Çaresiz kabulleniyorum.

Bu yüzdendir ki gözümün önünü göremez oldum.

Belki Onu Senden fazla düşünüyorum...

Ama...

Seni Ondan fazla arıyorum.

O okyanusta bir gemi; Ben kazazedeyim.

Sense can simidim, son ümidim...

Ancak...

Uzanıp tutamadım ellerini.

Kalmadı mecalim.

Enginlere savruldum.

Yıllarca bir sahil aradım; bulamadım.

Pusulam yoktu; kimseye; güvenip, soramadım.

Boğuştum durdum deli dalgalarla; 

Muradıma eremedim.

Gerçek aşkı bulupta, 

Mutluluğa varamadım.

Seviyorum diyeni reddedip, 

Kalbini kıramadım.

Ne yaptımsa olmadı; 

Yakamı yalnızlıktan kurtaramadım.

Çaresiz yine kendime döndüm.

Bir iç geçirdim derinden.

Kül olmuş sigaramdan, 

Son bir nefes daha çektim.

Efkarım Kaf Dağında bu gece! 

Belki de ölürüm kederimden.

Yalnızlık acı...

Birşey gelmiyor elimden.

Daha da anlatmak isterdim ya! 

Adeta kelimeler düğümlendi dilimde...

                 KASIM 1987', 'Ne zaman maziye dalsa gözlerim,  Siz beliriyorsunuz karşımda; Sen ve O... Önce tatlı tatlı gülümsüyorsunuz bana. Çözemediğim bir gizemle, ıs...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çıray']::text[], 8.5, '{"poet":"Erdoğan Çıray","poet_slug":"erdogan-ciray","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/okyanusta-bir-gemi-serbest-calisma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklemek', 'beklemek-sair-karatas-vv3kq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Işığın karanlığı kemirmesiydi, 

Güneşin doğuşu.

Dağların kasıklarından

Kan sızıntısı gibi

Bir kızıllık bırakmasıyla, 

Ortaya çıkışı.

Bahçedeki dut ağacının altında

Tek başına bir yontu gibi, 

Bakır rengi alnıyla 

Bekleyen dedeme görünmesi.

Ve dedemin; 

Bahçedeki yeşilin

Sarıdan korkması gibi

Bakmasıydı bu doğuşa

Bir yıldızın yıldızı yakması gibiydi

Bas bas bağırmak istedim

İnsanı geren bu sabaha...', 'Işığın karanlığı kemirmesiydi,  Güneşin doğuşu. Dağların kasıklarından Kan sızıntısı gibi Bir kızıllık bırakmasıyla,  Ortaya çıkışı. Bahçede...', ARRAY['Türk Edebiyatı','Şiir','Şair Karataş']::text[], 8.5, '{"poet":"Şair Karataş","poet_slug":"sair-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/beklemek-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelimeler', 'kelimeler-murat-tali-xq0uo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 've son bir hafta..

ve son bir gun..

ve son bir saat..

ve.....

yitip derinliğinde 

bir off çekmenin

bir dize daha döküyorum satırların arasına

bir hüzün afallaması yaşıyor tarihin o ifade edilemeyen 

tarifsizliği

yine 

yalnızlaşıyor

kelimeler

yine terkediyor 

kendini

yalnızlığım

zamanın o en kuytu 

yerinde

bir kuru dala sarınarak', 've son bir hafta.. ve son bir gun.. ve son bir saat.. ve..... yitip derinliğinde  bir off çekmenin bir dize daha döküyorum satırların arasın...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kelimeler-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sana Sevdam', 'bir-sana-sevdam-salih-ozalasan-dstia', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüreğimde bir sevda yakar bitirir beni

Ölmeden giymişim ben aşk denen kefeni

Görmüyor gözüm ruhum dinlemez beni

Bir deryada sal olmuşum, yok yelkeni

Geceler benim, olmuşum gecenin sultanı

Gün ağarsada, solmuşum tanımam Güneşi

Yıldızlar dost olmuş paylaşır derdimi

Çoban yıldızı gün ağarsada bırakmaz beni

Bir seni düşünür bir seni bilirim seni

Bilmez tanımaz yüreğim başka birini

Verselerde Dünya güzeli bir gelini

Değişmem sana saçının bir telini

Demesinler bana bu delimi divanemi

Sevmiş birini o  bu Dünya''da bir tanemi

Etmez iyi Lokman hekim bile benim yaremi

Çaresiz bir derde düşmüş sonserseri

Çare sensin seven yüreğimde

Bilmez uyku sensiz gözlerimde

Bir sana sevda, bir sana hasret sözlerimde

Her gece özlemle bekliyor seni bu sonserseri

Y.Tar.03-01-2003 Saat 17.23', 'Yüreğimde bir sevda yakar bitirir beni Ölmeden giymişim ben aşk denen kefeni Görmüyor gözüm ruhum dinlemez beni Bir deryada sal olmuşum, yok...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-sana-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Günün Kutlu Olsun', 'dogum-gunun-kutlu-olsun-sabri-eylikeder-rjj9t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ay onbeş günde bir doğar 

Geceyle güzeldir.

Güneş her gün doğar

Dünya ile güzeldir.

İnsan bir gün doğar

İnsanla güzeldir.

Ben seninle güzelim.

Mutlu yıllar KARDELEN çiçeğim.', 'Ay onbeş günde bir doğar  Geceyle güzeldir. Güneş her gün doğar Dünya ile güzeldir. İnsan bir gün doğar İnsanla güzeldir. Ben seninle güzeli...', ARRAY['Türk Edebiyatı','Şiir','Sabri Eylikeder']::text[], 8.5, '{"poet":"Sabri Eylikeder","poet_slug":"sabri-eylikeder","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dogum-gunun-kutlu-olsun-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fal', 'fal-firat-utkan-dzrip', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben bu şiiri ancak yolda yazarım

Yengeçler hep Ekim''de ölürmüş ve

O masada üç kız oturmuş

Sen sağlam bir gülüşte bulurken aşkı

Beni yalan mevsiminde yitik inançların öldürmüş

Yengeçler hep Ekim''de ölürmüş

Temmuzlar sende

Kalbimi çoktan söküp atmışım diyorsun

İncittiğin kalp şimdi atıyor bende

Ürkekliğimde

Korkarak baktığım gözlerinde Dianysos''u gördüm

Hani yeni gelmiş ya İstanbul''a

Zaten tanıyınca pişman olmuş seni

Tanrı olduğuna, Şaraba

O masada üç kız oturmuş

Hoş hiçbirini benzetemedim sana

Sanki vefa borçluydular

Aşklarına

Belki de pişman değillerdir yalnızlıklarına

Gerçekten Ekim''de ayrılmak zormuş

Ve gerçekten doğruymuş Yengeçlerin öldüğü

Ekim ayında

Ben çoktan öğrenmiştim

Falını okuduğumda

..........

Yalnız kaldığımda

Yengeç ayında...', 'Ben bu şiiri ancak yolda yazarım Yengeçler hep Ekim''de ölürmüş ve O masada üç kız oturmuş Sen sağlam bir gülüşte bulurken aşkı Beni yalan me...', ARRAY['Türk Edebiyatı','Şiir','Fırat Utkan']::text[], 8.5, '{"poet":"Fırat Utkan","poet_slug":"firat-utkan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/fal-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıskançlığın bu Kadarı', 'kiskancligin-bu-kadari-knight-errant-1ocqr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kısaknıyorum şu saati

Akrep bile sokuluyor yelkovana

Belki çok kalmıyor yanında, belki ağır ağır gidip geliyor

Ama en azından yanyanalar, değiller bizim gibi ayrı

Bıktım şu vedalardan gayrı

Kıskanırım oldum üzerindeki montu

Benden daha yakın sana şu alçak mont bile

Sarıyor ya seni, hele bi de kavramıyor mu belini

Sırtı sırtında, değiyor sana elleri, kolları

Bıktım şu soğuklardan gayrı

Kıskanıyorum artık terini

Süzülüyor yanaklarında, ellerimden daha çok

Tüm vücudunda değil mi şimdi o insafsız

Özledim seni, özledim soğukları, karı

Bıktım şu sıcaklardan gayrı

Artık psikloğunu bile kıskanıyorum

Saatlerce konuşuyor senle, gözlüklerinin altından bakarak

İstediğinde yatırıyor mu seni o şekilli koltuğa

Elinde defter, elinde kalem, boynunda fuları

Bıktım şu kederlerden gayrı

Seni kendimden bile kıskanıyorum

Her saniye düşünüyor şu ya beynim seni

Ellerim okşuyor yüzünü fotoğraflarda olsa bile

Arasıra diyorum kendime kıskançlığın bu kadarı

Bıktım aşktan, sevmekten, sevip üzülmekten

Bıktım artık hüznümü şu kağıtlara dökmekten

Bıktım beynimi kemirmenden, saatlerimi çalmandan

Fazla değil mi kıskançlığın bu kadarı

Bıktım şu ayrılıklardan gayrı', 'Kısaknıyorum şu saati Akrep bile sokuluyor yelkovana Belki çok kalmıyor yanında, belki ağır ağır gidip geliyor Ama en azından yanyanalar, de...', ARRAY['Türk Edebiyatı','Şiir','Knight Errant']::text[], 8.5, '{"poet":"Knight Errant","poet_slug":"knight-errant","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kiskancligin-bu-kadari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmadı', 'olmadi-knight-errant-iaitk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Olmayacak

Bu şiir güzel olmayacak, içime doğdu

Pek havam yok zaten bugün

Sabah mutluydum, kalktığımda

Olmasan bile yanımda, vardı

Fotoğrafın yine başucumda

Dedim ya güzel olmayacak bu şiir

İçinde sen varsın çünkü

Ne nesin böyle ki yıkıyorsun girdiğin yerleri

Kalbimi, beynimi hatta bu şiiri

Olmadı

Bu şiir de güzel olmadı senin kadar

Sen yoksun çünkü içimde

Unuttum seni hatırlamıyor musun? 

Sevmiyorum artık seni

Niye anlamak istemiyorsun

Mahvettin bir şiirimi daha, mutlu musun şimdi? 

Hadi git yat

Ve de girme rüyalarıma, bırak onlar güzel kalsın.....', 'Olmayacak Bu şiir güzel olmayacak, içime doğdu Pek havam yok zaten bugün Sabah mutluydum, kalktığımda Olmasan bile yanımda, vardı Fotoğrafın...', ARRAY['Türk Edebiyatı','Şiir','Knight Errant']::text[], 8.5, '{"poet":"Knight Errant","poet_slug":"knight-errant","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/olmadi-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Ben', 'i-ki-ben-knight-errant-9yh9r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölüyorum, 

Çekinmene gerek yok artık

Her dakika, her saniye ölüyorum

Büyük bir güç bastırıyor beni

Konuşmamam, ortalıklarda dolanmamam için

Şiir bile yazamıyorum artık

Ben yazmıyorum bu şiiri, ''O'' yazıyor aslında

Evet, ben yazıyorum bu şiiri

Ve büyüyorum sen öldükçe

Her dakika, her saniye

İnanılmaz bir güç besliyor beni

Kontrolü ele aldım, şiir bile yazıyorum bak

Ama sana değil ilk defa

Sana değil bu sefer bu şiirim

Kendime yazıyorum, ben ve içimdeki iki ben

İki ben var içimde

Ölürken birisi, diğeri büyüyor aynı kudretle

Çekinmeli misin? Bilmiyorum, 

Ve bilmiyorum kontrol kimde

Ölüyorum, 

Göremeyeceksin artık beni, kimse göremeyecek

Kontrol da sende, izin ister oldum

Artık konuşmak için bile

Sevinmen lazım, 

Artık yokum, sevinmen lazım

Kararsız değilsin artık, biliyorsun kim olduğunu

Sevinmen lazım, kalktı üzerinden büyük bir yük

Ve bu yüzden bana teşekkür etmen lazım

Mutluyum, 

Sağol beni benle bıraktığın için

Sağol kararsızlıktan kurtardığın için

Teşekkür ederim sana.

Ama, 

Senin de var bir teşekkür borcun

Yok ettim seni, çekmeyeceksin artık acı

Kemirmeyeceksin kendi aklını, yitirmeyeceksin

Ve hatırlamayacaksın yazdığın şiirleri

Güzel olsada bu günleri.

Haklısın, 

En iyisi bu ikimize ve de ''O''na

Yok artık acı hayatımda, yok artık hayatım

Ve son kez söylemek istiyorum

''HAYATIM''

İki ben var içimde Ölürken birisi, diğeri büyüyor kudretle

Çekinmene gerek yok artık

Ve biliyorum, kontrol artık ''BEN''de...

Ve mutlu son, 

Ben varım artık sadece

Saat 8''e geliyor ve ben uyku sersemi

Fakat doğdu içime, herşeye rağman

Güzel geçecek bugün...', 'Ölüyorum,  Çekinmene gerek yok artık Her dakika, her saniye ölüyorum Büyük bir güç bastırıyor beni Konuşmamam, ortalıklarda dolanmamam için ...', ARRAY['Türk Edebiyatı','Şiir','Knight Errant']::text[], 8.5, '{"poet":"Knight Errant","poet_slug":"knight-errant","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/iki-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayaklarım Ve Ben', 'ayaklarim-ve-ben-knight-errant-e42hs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düştüm yola, çıkıyorum şimdi

Ve haberin olsun dostum, 

Giymeyeceğim ayakkabılarımı.

Hissetmedim bir kez olsun toprağı

Toprak Ana''yı çıplak ayaklarla

Hissetmedim o ıslaklığı, o kokuyu

Kendi ayaklarımda.

İstemiyorum artık arabalar gibi

Tekerlek misali bu ayaklarla, 

Bu ayakkabılarla.

Düştüm yola yürüyorum şimdi

Yok ayağımda o ıslaklık, o koku

Sadece betonun soğukluğu

Yürüyorum, yürüyorum saatlerdir

Yoruldum, artık yenik düştüm betona.

Ve senden özür diliyorum ayaklarım, 

Mahkumsun kabında dolaşmaya...', 'Düştüm yola, çıkıyorum şimdi Ve haberin olsun dostum,  Giymeyeceğim ayakkabılarımı. Hissetmedim bir kez olsun toprağı Toprak Ana''yı çıplak a...', ARRAY['Türk Edebiyatı','Şiir','Knight Errant']::text[], 8.5, '{"poet":"Knight Errant","poet_slug":"knight-errant","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ayaklarim-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgedeki Hayallerim', 'golgedeki-hayallerim-knight-errant-rg8hp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir yere bakıyorum bir göğe, 

İkiside beton, farkı yok.

Görünmüyor bulutlar, yıldızlar

Görünmüyor kafdağının arkası.

Hayallerim, ümitlerim görünmez oldu

Kafesteler sanki, kilitli.

Açsam kafesi, salsam onları 

Ne olur? Ne olur bari

Onlar erişsinler gökyüzüne

Bulutlara gömülsünler, umarsızca, 

Dertsiz, tasasız, değil benim gibi...

Bir yere bakıyorum bir göğe

İkiside beton, farkı yok.

Karışmak istiyorum doğaya, ümitlerime

Buluşmak onlarla, görüşmek.

Görmek istiyorum en azından

Nasıl olur ümit dediğin? Hayaller? 

Var mı onlarında kaşı, gözü? 

Olular mı aşık? Yanarlar mı? 

Kahrolurlar mı benim gibi? 

Olmasınlar, bari onlar kalsınlar mutlu.

Bari onlar erişsinler gökyüzüne.', 'Bir yere bakıyorum bir göğe,  İkiside beton, farkı yok. Görünmüyor bulutlar, yıldızlar Görünmüyor kafdağının arkası. Hayallerim, ümitlerim g...', ARRAY['Türk Edebiyatı','Şiir','Knight Errant']::text[], 8.5, '{"poet":"Knight Errant","poet_slug":"knight-errant","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/golgedeki-hayallerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çatışma', 'catisma-knight-errant-8uapl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çatışmadayım kendi içimde

Tutmuyor yaptıklarım düşündüklerimi

Ya da söylediklerim yansıtmıyor beni

Değişiyorum körükörüne, körce

Körelmişcesine bileniyorum hayatta

Büyüyorum galiba, adam oluyorum

Ama benden adam olmaz, bu şarkılar susmadıkça

Deli gönlüm durmadıkça

Bir başka yorumluyorum herşeyi

Seni bile başka görüyorum her baktığımda

Göremiyorum bile, gözlerim kaçıyor

Dedim tutmuyor yaptıklarım

Oysa istemez miyim saatlerce kaybolmak o mavi gözlerinde

Yola çıkmak engin denizlerde, 

Mavi  ve engin denizlerde yol almak bir ömür boyu

Bir ömür boyu olmak seninle, gözlerinle

Olmamak içli dışlı hayatla, kitlemek kendimi sana

Olmak yanında her nefeste, nefes almak hep yanında

Yanında ölmek, ölmek seninle, ölmek denizlerde boğularak

Ama can çekişmeden, maruz kalmak kesin ölüme', 'Çatışmadayım kendi içimde Tutmuyor yaptıklarım düşündüklerimi Ya da söylediklerim yansıtmıyor beni Değişiyorum körükörüne, körce Körelmişces...', ARRAY['Türk Edebiyatı','Şiir','Knight Errant']::text[], 8.5, '{"poet":"Knight Errant","poet_slug":"knight-errant","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/catisma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-knight-errant-nowkd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '***Bu sözler ilk olarak Zülfü Livaneli''nin seslendirdiği Gözlerin adlı parçaya devam niteliğinde yazılmıştır***

Umudun alçalıp, çıktığı yerde

Kalbinde atıyor hiç sekmeksizin

Bitmemiş bir hayat, ellerinde onu yaşatmak

Bir yer var kalbimde, kalbimde değişmeksizin

Gözlerin  bir alev, amansız bir dalga

Gözlerin heryeri yıkıp kavuran bir yangın

Bir masa, bir şarap ve uykuluyken

Delice, çılgınca  içmek  seninle

Kadehi elime alıp bitirmek, bitirmek

Kapanmak ellerine, kapanmak bir şafak vakti

Ellerin bir şarkı, alımlı ve küskün

Ellerin piyanoda hayat bulan bir yarım beste

Bir insan sahile doğru yürürken

Elinde bir çiçek, bir şişe konyak

Son bulan bir hayat, dalgalara atılan bir taş

Bembeyaz bir tablo, sonsuzluğa atılan demir

Gözlerin  bir alev, amansız bir dalga

Gözlerin heryeri yıkıp kavuran bir yangın

Ellerin bir şarkı, alımlı ve küskün

Ellerin piyanoda hayat bulan bir yarım beste', '***Bu sözler ilk olarak Zülfü Livaneli''nin seslendirdiği Gözlerin adlı parçaya devam niteliğinde yazılmıştır*** Umudun alçalıp, çıktığı yerd...', ARRAY['Türk Edebiyatı','Şiir','Knight Errant']::text[], 8.5, '{"poet":"Knight Errant","poet_slug":"knight-errant","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gozlerin-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-i-lkay-aydogdu-1l3lz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tek başıma bir odada, 

Oturmuş seni düşünüyorum.

Bir şarkı geliyor uzaklardan.

Seni, duman duman hayalinle; 

Çatık kaşların, kara gözlerinle

Yanımda hissediyorum.

Şarkı, seni getiriyor bana.

Aramızda, 

Sıradağların olduğunu söyleyerek.

Gözlerim doluyor...

Yanaklarımdan yaşlar süzülürken, 

''İbibikler öter ötmez ordayım'' diyorum.

Ellerimi uzatıyorum.

Ellerim boş, kalbim seninle dolu...

Hayalin kayboluyor.

Sen yoksun yanımda…

Ah! Diyorum, yalnızlığım bir bitse, 

Sen olsan yanımda…

Gözümde yaş, kalbimde sen.

Sabahlar oluyor, günler geçiyor, 

Gelmiyorsun, bekliyorum…

Senden bana hatıra resmin karşımda, 

İçimde yine umut, yine sana olan sevgim…

Hasretin içimi yakıyor.

Sen yoksun, 

Bekliyorum.

Baharın, yazın gelmesini.

Gözlerim uzaklarda, 

Sen gelesin diye.

Ama gelmiyorsun…

Gelmeyeceksin...', 'Tek başıma bir odada,  Oturmuş seni düşünüyorum. Bir şarkı geliyor uzaklardan. Seni, duman duman hayalinle;  Çatık kaşların, kara gözlerinle...', ARRAY['Türk Edebiyatı','Şiir','İlkay Aydoğdu']::text[], 8.5, '{"poet":"İlkay Aydoğdu","poet_slug":"i-lkay-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/hasret-84-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meşrep Taassubu', 'mesrep-taassubu-levent-ongun-nfly4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Müslüman kardeşine bu öfke niye

Kınarsın düşüncesi farklıdır diye

Allahın peygamberin birdir yetmezmi

Bu millet ne zamandır hasret sevgiye

Ağaçlar büyüyünce dallar ayrılır

Ne kadar ayrılsa da kardeş sayılır

Kardeşlik şuurunu kaybeden dallar

Gün gelir fırtınada toptan kırılır

Müslüman kardeşini sevmek zorunda

Hoşgörü göstermeli birlik uğrunda

Meşrepler taassubu terkeder ise

Başarı garantidir Allah yolunda

Aslında farklılıklar ayrıntılarda

Dostluk yok müslümanlar sıkıntılarda

Tefrika körüklenip fitne çıkıyor

Bu yüzden islamiyet sarsıntılarda

Haydi müslümanlar kardeş olalım

Kavgayı unutalım dostça kalalım

Sevelim sevilelim buna mecburuz

Hepimiz birlik olup sevap alalım', 'Müslüman kardeşine bu öfke niye Kınarsın düşüncesi farklıdır diye Allahın peygamberin birdir yetmezmi Bu millet ne zamandır hasret sevgiye A...', ARRAY['Türk Edebiyatı','Şiir','Levent Ongun']::text[], 8.5, '{"poet":"Levent Ongun","poet_slug":"levent-ongun","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mesrep-taassubu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Geç...', 'cok-gec-i-lkay-aydogdu-yuxf1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağzında mırıldandığı, 

Bir sevda türküsüydü.

Dalmıştı gözleri, 

Erkekler ağlamazdı! ...

Ağlıyordu...

Yediremiyordu kendine, 

Hata yaptım demeyi.

Cesareti yoktu.

Yaşlı gözleri: 

''Anla beni'' der gibiydi.

Ne yazık ki; 

İhanetler unutulmuyor, 

Yaşanan acılar silinmiyor, 

Geçen ömür, giden yıllar

Geri gelmiyordu...', 'Ağzında mırıldandığı,  Bir sevda türküsüydü. Dalmıştı gözleri,  Erkekler ağlamazdı! ... Ağlıyordu... Yediremiyordu kendine,  Hata yaptım dem...', ARRAY['Türk Edebiyatı','Şiir','İlkay Aydoğdu']::text[], 8.5, '{"poet":"İlkay Aydoğdu","poet_slug":"i-lkay-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/cok-gec-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine De', 'yine-de-oktay-avci-twdpa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Birimiz sustukça

Birimiz konuştuk

hep vardık

Hiç sıfıra düşmedi sayımız

hiç bitmedik

Yalnızlıkpaylaşılmayınca olur

ve paylaşılır', 'Birimiz sustukça Birimiz konuştuk hep vardık Hiç sıfıra düşmedi sayımız hiç bitmedik Yalnızlıkpaylaşılmayınca olur ve paylaşılır...', ARRAY['Türk Edebiyatı','Şiir','Oktay Avcı']::text[], 8.5, '{"poet":"Oktay Avcı","poet_slug":"oktay-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yine-de-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğrencilerime', 'ogrencilerime-i-lkay-aydogdu-gfytr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben, Anadolu köşelerinde; 

Sizin için yaşayacak bir öğretmen.

Amacım ayrı, yolum ayrı...

Sizin için şiirler yazacağım.

Güzel günlerimiz, anılarımız olacak.

Sizin gözleriniz gibi…

Kara gözlü bir öğrencim olursa; 

Hep, onun gözlerine anlatacağım dersleri.

Siz, belki unutacaksınız; 

Yeni öğrencilerimle bırakacaksınız beni.

Ama ben, asla unutmayacağım sizi...

Üzüldüğüme bakmayın, aldırmayın siz.

Geçmişim aydınlık; geleceğimde, 

Anadolu''yu aydınlatacağım...

Bir köy öğretmeni olacağım, 

İsli lambalarda aydınlanacak gecelerim.

Siz ise; bu günün, 

Geleceği parlak öğrencilerisiniz.

Yarın ya doktor, ya mimar olacaksınız.

Ben; boş ve rutubetli odamda, 

Yarınki vereceğim dersin planını hazırlarken; 

Bazılarınız belki, bir gece kulübünde

Çılgınca eğleneceksiniz.

Görüyorsunuz ya, yollarımız ayrı...

Beni ve kendinizi boşa aldatmayın.', 'Ben, Anadolu köşelerinde;  Sizin için yaşayacak bir öğretmen. Amacım ayrı, yolum ayrı... Sizin için şiirler yazacağım. Güzel günlerimiz, anı...', ARRAY['Türk Edebiyatı','Şiir','İlkay Aydoğdu']::text[], 8.5, '{"poet":"İlkay Aydoğdu","poet_slug":"i-lkay-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ogrencilerime-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Derdiniz', 'ne-derdiniz-oktay-avci-b0zov', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kim asar insanı boynundan

Asılırken de seyreder gaddarca 

Biliyorum insansa asmaz

astırmazda

Düşünün ki bir oyun bu

Ne dersiniz oyunda asılana

Ne derdiniz  astırana

Birde sussa baştan sona

Konuşturulmasa

Ve seyretse bir yabancı gibi ölümü

Sessizce

Sonra agzını açıp koparsa dişlerini suratınıza

Söyleyin aglamaz mıydınız

Katlanabilir miydi yüreğiniz böylesine çaresiz bir acıya

Dayanabilir miydi gözleriniz

Güzelliğiniz ve insanlıgınız

Dayanmaz, başkaldırırdınız korkusuzca

Böylece sizi de bir başka gün

Bir başka darağacına bağlarlardı

Siz de boğulurken ne derdiniz

Bırakın bir insanı

Bir köpeği assalar karşınızda

Sessizce susar ve seyredermiydiniz', 'Kim asar insanı boynundan Asılırken de seyreder gaddarca  Biliyorum insansa asmaz astırmazda Düşünün ki bir oyun bu Ne dersiniz oyunda asıla...', ARRAY['Türk Edebiyatı','Şiir','Oktay Avcı']::text[], 8.5, '{"poet":"Oktay Avcı","poet_slug":"oktay-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ne-derdiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin Çocukları', 'sevginin-cocuklari-oktay-avci-d32a1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Öp beni gülüm

Sen öptükçe ben çogalırım

Okşadıkça büyürüm

Sayım artar sevildikçe

Boyum uzar kilolanırım

Öpbeni güzelim

Sempatin güzelleştirir beni

Bunu bilenler bilir esir

Esirgerler sevgini benden

Gerillalar savunulmaz biliyorum

Yine de koru beni güzelim

Benim silahlarım senin bana bakışından doğar

Kurşun bile işlemesin bedenime öyle bak ki

Kendi kurşunum da patlamasın şakağıma

Tepmesin geri

Öp beni güzelim 

Kanatlanıp uçayım', 'Öp beni gülüm Sen öptükçe ben çogalırım Okşadıkça büyürüm Sayım artar sevildikçe Boyum uzar kilolanırım Öpbeni güzelim Sempatin güzelleştiri...', ARRAY['Türk Edebiyatı','Şiir','Oktay Avcı']::text[], 8.5, '{"poet":"Oktay Avcı","poet_slug":"oktay-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevginin-cocuklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Volta Atılırken', 'volta-atilirken-tahir-karlidag-1jcfx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'volta atılırken denizin yalnızlığına

yıldızlar seyre dalıyordu

sevgililerin kucaklaşmasına

martılar özgürlük naraları atarken

ben

 uzak diyarların köşebaşlarında

 yalnızlığıma aşklar sığdırıyorum', 'volta atılırken denizin yalnızlığına yıldızlar seyre dalıyordu sevgililerin kucaklaşmasına martılar özgürlük naraları atarken ben  uzak diya...', ARRAY['Türk Edebiyatı','Şiir','Tahir Karlıdağ']::text[], 8.5, '{"poet":"Tahir Karlıdağ","poet_slug":"tahir-karlidag","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/volta-atilirken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben De Seni', 'ben-de-seni-oktay-avci-g9t8b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Morsümbüllü dağlarında memleketimin

İlkbahar sandım

Bende seni

Kapkaranlık siyahında renklerin

Beyazım sandım

Bende seni

Aysız gecelerimin

Güneşi sandım

Bende seni

Boğulurken son nefesimde

Umudum sandım

Bende seni

Bırakıp ta giderken

Dönecek sandım

Bende seni', 'Morsümbüllü dağlarında memleketimin İlkbahar sandım Bende seni Kapkaranlık siyahında renklerin Beyazım sandım Bende seni Aysız gecelerimin G...', ARRAY['Türk Edebiyatı','Şiir','Oktay Avcı']::text[], 8.5, '{"poet":"Oktay Avcı","poet_slug":"oktay-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ben-de-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Madem', 'madem-sessiz-adam-25kmv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Demek bir gün gidecektin

gidip bana hayir diyecektin

beni böyle dünyamdan edecektin

neden bu izdirabi bana cektirecektin? 

Artik dünyaya küsmüs bir vaziyetteyim

bilmem kime icimi dökeyim

kolay degilki kalbimden sökeyim

ne edeyim gülüm, ne edeyim? 

öylesine sevip, alismistimki sana

kalbim atmiyacakti artik baskasina

böylemi yapacaktin be gülüm bana

Delikanliyim dedim ama yenildim sana! 

Yürek yarasi en beteriymis demek

peki bunu kim telafi edecek? 

ama sen düsünme, senden gecti artik bu erkek

hayat nasil olsa devam edecek...', 'Demek bir gün gidecektin gidip bana hayir diyecektin beni böyle dünyamdan edecektin neden bu izdirabi bana cektirecektin?  Artik dünyaya küs...', ARRAY['Türk Edebiyatı','Şiir','Sessiz Adam']::text[], 8.5, '{"poet":"Sessiz Adam","poet_slug":"sessiz-adam","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/madem-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben De Seni 2', 'ben-de-seni-2-oktay-avci-h40s2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Salkım saçak dağlarımda ülkemin

Kelebek sandım, uçan kuş sandım

Bende seni

Kaymakam bahçesinde 

Açacak sandım, 

Bende seni

Ebabilin cennetinde

Ötecek sandım, 

Bende seni

Azrailin pençesinden 

Kaçacak sandım, 

Bende seni

Öpüp giderken beni

Gelecek sandım, 

Bende seni

Kış aylarında kar altında

Açan gül sandım, açacak sandım', 'Salkım saçak dağlarımda ülkemin Kelebek sandım, uçan kuş sandım Bende seni Kaymakam bahçesinde  Açacak sandım,  Bende seni Ebabilin cennetin...', ARRAY['Türk Edebiyatı','Şiir','Oktay Avcı']::text[], 8.5, '{"poet":"Oktay Avcı","poet_slug":"oktay-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-de-seni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımın Gözyaşları', 'askimin-gozyaslari-abdulkadir-teker-tjr48', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tahmin edemiyeceğin kadar uzak

Ummadığın kadar yakındır sevgi

Geleceği belirsiz bir yoldur ki 

Bir bakmışsın

Artık yalnızsın, bu aşk yolunda 

Bir yanda melek yüzün 

Diğer yanda şeytani gülüşün

Bir yanda masum bakışlar

Diğer yanda aşka küsmüş bir kalp var

Serseri gibi, sarhoş gibi

Düştüm bu karanlık aşk yoluna

İntiharı düşündüğüm şu anda

Senin resmin geliyor geliyor aklıma 

Unutmak istediğim bir kişi var hayatımda

Artık umrumda değil ne aşk nede dünya

Gelde bir bak gözlerimin içine

Sanki sana bir şey söylemek istiyor

Gelde bir dokun kalp atışlarıma

Kalbim aşkını anlatmak istiyor

Gelde bir dinle beni, seni sevmediğimi

Haykırmak istiyorum nefretimi

Ama yapamıyorum

Çünkü seni çok seviyorum.', 'Tahmin edemiyeceğin kadar uzak Ummadığın kadar yakındır sevgi Geleceği belirsiz bir yoldur ki  Bir bakmışsın Artık yalnızsın, bu aşk yolunda...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Teker']::text[], 8.5, '{"poet":"Abdülkadir Teker","poet_slug":"abdulkadir-teker","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/askimin-gozyaslari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Atma Dünyandan', 'beni-atma-dunyandan-oktay-avci-awmt3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şair baba

Benişiir yaz

De ki çaresiz 

De ki aç

De ki öfkeli

De ki kızgın

Deki odun

Hırsız deme

Arsız deme

İt deme

Beni kovma şiirlerinden

Ressam olda

Resim yap beni

De ki yorgun

De ki sürgün

De ki yılmayan

Gözümü yap

Başımı yap

Dudağımı yap

Beni yap

Bana benzesin

Beni silme çirkinimya

Tanrı baba

Beni gül yap açayım

De ki kurumayan

De ki solmayan

De ki koparılmayan

Beni insan yap

İnsan yap tanrı baba

Çalmayan

Zülmetmeyen

Sövmeyen

Sövdürtmeyen

Deki sevmesini bilen

De ki insan gibi bir insan

De ki konuşan

Deki gülen

De ki gülünce güller açan

Deki beni atma dünyandan', 'Şair baba Benişiir yaz De ki çaresiz  De ki aç De ki öfkeli De ki kızgın Deki odun Hırsız deme Arsız deme İt deme Beni kovma şiirlerinden Re...', ARRAY['Türk Edebiyatı','Şiir','Oktay Avcı']::text[], 8.5, '{"poet":"Oktay Avcı","poet_slug":"oktay-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/beni-atma-dunyandan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Değilmiydin?', 'sen-degilmiydin-serkan-arslanargun-bs750', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Turuncu geminin ardından koşarken düştüm.

Sönük hayallerimi gerçekleştirebilmek için koşuyordum

Niçin sevdiğimi bile bilmediğim

Aslında kendisi bir düşmanım olan

Fakat sevdiğim kadının ardından

Düştüğüm için

Bazen bana acıdığını düşünüyordum da

Fakat beni düşürüp

bu yarayı açan zaten sen değimliydin? 

16/11/2002 -vangölü', 'Turuncu geminin ardından koşarken düştüm. Sönük hayallerimi gerçekleştirebilmek için koşuyordum Niçin sevdiğimi bile bilmediğim Aslında kend...', ARRAY['Türk Edebiyatı','Şiir','Serkan Arslanargun']::text[], 8.5, '{"poet":"Serkan Arslanargun","poet_slug":"serkan-arslanargun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-degilmiydin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Anlatıyorum', 'seni-anlatiyorum-sahin-yenilmez-572lw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sorunlarım var

Sorunlar deyince aklıma tek sen geliyorsun

Bütün hayatım boyunca benim tek sorunum oldun

Bütün hayatım boyunca bana hayata karşı koyma isteğini verdin

Umutlarım var

Umutlar deyince aklıma hep sen geliyorsun

Yaşadığım sürece benim hep umudum oldun

Seni tanıdıktan sonra hayata hep umutla baktım.

Yaşamak 

Yaşamak deyince de aklıma sen geliyorsun

Bir insana yaşama isteği vermek ne büyük şey

Seninle yaşıyor benim gözümde her şey.

Aşk deyince aklıma bir tek sen geliyorsun

Zaten aklımdan hiç çıkmıyorsun

Ne zaman bir gülü koklasam

Sanki sana dokunuyorum

Ne zaman yağmur yağsa

Deliler gibi çılgınca koşmaya başlıyorum

Çünkü sonunda seni hatırlıyorum.

Ölüm

Ölüm deyince aklıma sen geliyorsun

Ölürsem eğer ağladığını duyabilirim

Göz yaşların toprağa aksa seni hissedebilirim

Avuçlarınla toprağımı okşasan sana sevgimi haykırabilirim

Yeter ki sen ölme

Ben seni ölünce de severim.', 'Sorunlarım var Sorunlar deyince aklıma tek sen geliyorsun Bütün hayatım boyunca benim tek sorunum oldun Bütün hayatım boyunca bana hayata ka...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yenilmez']::text[], 8.5, '{"poet":"Şahin Yenilmez","poet_slug":"sahin-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/seni-anlatiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnziva', 'i-nziva-baris-akm-f41bg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İyiki içki kokusu sinmiyor mektuplara

Kelimeler bazen salınıyor olsada

İnceden külhan ağzıyla 

Çakır keyif gönle yasak mı var? 

Bu ağızla yazılmaz diye

Kim ne der içmesini bilene? 

Her neden içerse

Yok yok, bakma sözümün perde arkasına

Yüz görümlüğü istemem ama

Kağıdın dostluğuna bile anlatamadığım

Bir ömrün seceresi yatıyor orada

Kaldırıp örtüyü ne olur büyüsünü bozma 

İnzivaya çekildi artık umutların denizi

Bir bu kelime kalmıştı sanki 

Beklediğim ama öğrenmediğim anlamını

Şimdi biliyorumki bu kelime karanlığın prensi

Hayattan umudu kesenlerin sığınağı

Mevsimleri içinde yaşamak zorunda olanların kıblesi', 'İyiki içki kokusu sinmiyor mektuplara Kelimeler bazen salınıyor olsada İnceden külhan ağzıyla  Çakır keyif gönle yasak mı var?  Bu ağızla ya...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/inziva-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşklarda Terkedilir', 'asklarda-terkedilir-baris-akm-8e2wg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir kış günüydü

Aşkımızın poşlet içine konup

Sanki bir köşebaşında peydahlanmış gibi

Cami avlusuna terk edilişi

Kurt yavrusu değildiki korusun onu postu

Ev bark olamazdı ona kışın karı

Bir kaç gün yazılmış demek ömrü

Her gün yerine, son kez ağlayıp sustu', 'Bir kış günüydü Aşkımızın poşlet içine konup Sanki bir köşebaşında peydahlanmış gibi Cami avlusuna terk edilişi Kurt yavrusu değildiki korus...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/asklarda-terkedilir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızkulesi''nin Gözyaşları', 'kizkulesi-nin-gozyaslari-baris-akm-sjgvl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben seni bu gün kaybetmedim sevgili

Bulduğumda Üsküdar öyle uzaktıki

Sisin dağladığı boğazın hırçın sularında

Boşuna ağlıyordu Kızkulesi

O zamanlar boğaz köprüyle nişanlıydı

Sen bir evin deli kızı

Ben bir başkasının ağır başlı çocuğu

Seni kaybedişim işte o zamandı

Hani yıllar önce bir güneş tutulmuştu

Her yer kararmış sokak lambaları yanmıştı

İşte o gündü kına ertesi

Bir baltanın taştan sekişi', 'Ben seni bu gün kaybetmedim sevgili Bulduğumda Üsküdar öyle uzaktıki Sisin dağladığı boğazın hırçın sularında Boşuna ağlıyordu Kızkulesi O z...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kizkulesi-nin-gozyaslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönüş', 'donus-baris-akm-3lyhc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu rüya değil

Uçuyorum sahidende

Eminim bulutlar el sallıyordur

Karanlık içinde

Güle güle, güle güle diye

Alıştığım bir uğultu

Elimde plastik şarap bardağı

Bekliyorum 

Çökecek bir kaç saat sonra

Gurbetin taş duvarları

Kükreyecek İstanbul''un ışıkları

Hoş geldin gerdanı

Dedilerki orada hava bir derece

Deli mi bunlar ne? 

Artı ya da eksi yüz olsada

Nasıl kalırım buralarda? 

Boşuna mı nöbet tuttum ben o sınırlarda?', 'Bu rüya değil Uçuyorum sahidende Eminim bulutlar el sallıyordur Karanlık içinde Güle güle, güle güle diye Alıştığım bir uğultu Elimde plasti...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/donus-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok Arkadaş', 'yok-arkadas-baris-akm-f19di', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yok arkadaş olmaz böyle

Kalp dediğin ölmeli otuzunda

Kurumalı başakları ilk hüsranda

En fazla otuzbeşe geldiğinde

Ne o öyle kırk demiş hala ahlarda

Ne demeli yetmişinde vahlara? 

Paslı çivi battıysa bir kere

Burulup dağlanmalı kalpler üçüncü günde

Yok arkadaş intizar etmiyorum sana

Aklını devşir düşün sende

Nedir bu çektiğin gönülden yana? 

Kurumuş damarlar kurtuluş olmaz mı insana? 

Bak şu ağaçlara

Ne kalp gövdesinde ne hüzün dalında

Bahar gelmiş neyine, kış neyine

Ağaç gibi olmalı umutsuz kalbin bedenide', 'Yok arkadaş olmaz böyle Kalp dediğin ölmeli otuzunda Kurumalı başakları ilk hüsranda En fazla otuzbeşe geldiğinde Ne o öyle kırk demiş hala ...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yok-arkadas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşığım', 'asigim-baris-akm-rvgob', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Evet aşığım, kimse şaşmasın buna

Aşksız yaşanmıyor kaçsa kaç yaşın başın

Canına can, kalbine kalp gerek insanın

Gözlerinde uyuyup gözlerinde uyandığın

Sevip okşamaya doyamadığın

Hangi sürgü kilit olur kalbe? 

Kim çizer sınırları yasak diye? 

İdamlık olsanda kalp uçar sevdiğine

Darağacı bile çöker sevda denince

Anlını karışlarım eğilmeyen suyun aşk önünde

Aşığım dedim, şaşacak ne var bunda? 

Ben sevmeyeceğimde onu delice

Kurtlar mı kapsın subaşında? 

Kalp hali bu söz dinlemiyor ne dersen de

Hor görmeyin bir hayale aşığım diye

Aşık olmak güzel be

Varsın hayal kalacak olsun ömrümce

Eli elime değmesin hayalden öte

Kalbim çarpar ya hayalin gözlerinde

Satiim anasını o da yeter be', 'Evet aşığım, kimse şaşmasın buna Aşksız yaşanmıyor kaçsa kaç yaşın başın Canına can, kalbine kalp gerek insanın Gözlerinde uyuyup gözlerinde...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/asigim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kağıttan Dost', 'kagittan-dost-baris-akm-1wi5u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yazıyor, yazıyor yazıyorum biteviye

Ne bir nebze rahatlama göğsümde

Ne de anlatmaya yetiyor

Dost bildiğim kalem

Kalbimi bir kağıt tomarına bile

Neden? Bir an geldiğinde

Anlatamıyorsun içinin sırlarını bir kağıda bile

Her şeye rağmen bir şeyler kalıyor gizlerinde

Korkun kimden ya da neden? 

Boğazında bir düğüm yutkunamadığın

Dilin dönmüyor işte bak anlatmaya

Alıştın mı yoksa içindeki zehire? 

Onun için mi gizleniyorsun göğsünün içine

Dost olamıyorsan bir kağıt parçasına bile

Tak yağlı urganı boynuna, hadi durma', 'Yazıyor, yazıyor yazıyorum biteviye Ne bir nebze rahatlama göğsümde Ne de anlatmaya yetiyor Dost bildiğim kalem Kalbimi bir kağıt tomarına b...', ARRAY['Türk Edebiyatı','Şiir','Barış Akm']::text[], 8.5, '{"poet":"Barış Akm","poet_slug":"baris-akm","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kagittan-dost-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek', 'sevmek-selale-uygun-20nl5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güzel bir sesten, 

Güzel bir şiiri dinlemek gibi

Yaşamak istiyorum aşkı.

Yağmur damlasının 

Dudağıma düşüşü gibi

Hissetmek seni.

Dünden fazla, yarından az

Sevmek, sevmek, sevmek.', 'Güzel bir sesten,  Güzel bir şiiri dinlemek gibi Yaşamak istiyorum aşkı. Yağmur damlasının  Dudağıma düşüşü gibi Hissetmek seni. Dünden fazl...', ARRAY['Türk Edebiyatı','Şiir','Şelale Uygun']::text[], 8.5, '{"poet":"Şelale Uygun","poet_slug":"selale-uygun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevmek-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yılkı Atı', 'yilki-ati-selale-uygun-1n67p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Duru, sessiz gece.

Yılkı atının esir oluş sessizliği.

Çırpındım ve duruldum yine.

Ruhum bedenimden taştı.

Ağladım...', 'Duru, sessiz gece. Yılkı atının esir oluş sessizliği. Çırpındım ve duruldum yine. Ruhum bedenimden taştı. Ağladım......', ARRAY['Türk Edebiyatı','Şiir','Şelale Uygun']::text[], 8.5, '{"poet":"Şelale Uygun","poet_slug":"selale-uygun","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yilki-ati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bul', 'sen-bul-selale-uygun-al8fq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne yırtık çorap giymekten

Utanırım.

Ne eski elbiseler.

Ne yüzüne bakmaktan 

Utanırım.

Ne konuşmaktan.

Bir tek şeyden 

Utanırım 

Sana dair.

Sen bul.', 'Ne yırtık çorap giymekten Utanırım. Ne eski elbiseler. Ne yüzüne bakmaktan  Utanırım. Ne konuşmaktan. Bir tek şeyden  Utanırım  Sana dair. S...', ARRAY['Türk Edebiyatı','Şiir','Şelale Uygun']::text[], 8.5, '{"poet":"Şelale Uygun","poet_slug":"selale-uygun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-bul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmayan', 'olmayan-selale-uygun-tj3m2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tehlikeli olmayan insanlardan

Tehlikeler yaratırım.

Aşık olunmayacak insanlara

Aşık olurum.

Gülünmeyecek zamanlarda

Gülerim.

Ama tam zamanında

Ağlarım.', 'Tehlikeli olmayan insanlardan Tehlikeler yaratırım. Aşık olunmayacak insanlara Aşık olurum. Gülünmeyecek zamanlarda Gülerim. Ama tam zamanın...', ARRAY['Türk Edebiyatı','Şiir','Şelale Uygun']::text[], 8.5, '{"poet":"Şelale Uygun","poet_slug":"selale-uygun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/olmayan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine', 'yine-selale-uygun-l0350', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bugün efkardayım yine.

Dost bildiklerim

Dost değilmiş yine.

Özümde var acı, 

Söküp atamadım yine.

Oysa severim bulutları, 

Kuşları ve çocukları.

Onlar ihanet etmez insana.

Uğraştım uğraştım da yine.

Gerçek huzura varamadım niye?', 'Bugün efkardayım yine. Dost bildiklerim Dost değilmiş yine. Özümde var acı,  Söküp atamadım yine. Oysa severim bulutları,  Kuşları ve çocukl...', ARRAY['Türk Edebiyatı','Şiir','Şelale Uygun']::text[], 8.5, '{"poet":"Şelale Uygun","poet_slug":"selale-uygun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yine-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zeynep''e', 'zeynep-e-selale-uygun-vwbo2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kocaman gözlerinle doğdun evimize.

Kocaman yüreğini sonra anladık.

Sen bizim ilkimizsin.

Değerini şimdi anladık.

Zekan yüreğini örtmesin sakın.

Hep böyle sevecen, cana can

Kalasın.', 'Kocaman gözlerinle doğdun evimize. Kocaman yüreğini sonra anladık. Sen bizim ilkimizsin. Değerini şimdi anladık. Zekan yüreğini örtmesin sak...', ARRAY['Türk Edebiyatı','Şiir','Şelale Uygun']::text[], 8.5, '{"poet":"Şelale Uygun","poet_slug":"selale-uygun","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/zeynep-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buradayım', 'buradayim-selale-uygun-m47em', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsanların acısını

Dindirmek için buradayım.

Acı nedir bilirim.

Çareler bulmak için buradayım.

Çaresiz dertleri bilirim.

İleri gitmek için buradayım.

Umut var bilirim.', 'İnsanların acısını Dindirmek için buradayım. Acı nedir bilirim. Çareler bulmak için buradayım. Çaresiz dertleri bilirim. İleri gitmek için b...', ARRAY['Türk Edebiyatı','Şiir','Şelale Uygun']::text[], 8.5, '{"poet":"Şelale Uygun","poet_slug":"selale-uygun","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/buradayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıkamaz', 'yikamaz-selale-uygun-mzaug', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Öyle çok acı çektim ki, 

Hiç bir acı beni

Yıkamaz.

Öyle çok hayal kırıklığı yaşadım ki, 

Hiç bir hayal kırıklığı beni

Yıkamaz.

Öyle çok üzüldüm ki, 

Hiç bir üzüntü beni

Yıkamaz.

Öyle çok ihanete uğradım ki, 

Hiç bir ihanet beni

Yıkamaz.

Ve öyle çok sevdim ki seni, 

Hiç kimse bunu

Yıkamaz.', 'Öyle çok acı çektim ki,  Hiç bir acı beni Yıkamaz. Öyle çok hayal kırıklığı yaşadım ki,  Hiç bir hayal kırıklığı beni Yıkamaz. Öyle çok üzül...', ARRAY['Türk Edebiyatı','Şiir','Şelale Uygun']::text[], 8.5, '{"poet":"Şelale Uygun","poet_slug":"selale-uygun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yikamaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatcam', 'hatcam-sair-geleneksel-5pwcs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Denizin dibinde Hatcam

Demirden evler

Ak gerdan ustunde anam

Ciftedir benler

O kinali parmaklar parmaklarda

O beyaz eller

Yolcuyu yolundan eden

Eyleyen dilber

Dalga dalga dalgalaniyor

Hatcami gorenler anam sevdalaniyor.

Yuce ag basinda Hatcam

Ekin ekilmez

Yagmur yagmayinca anam

Koku sokulmez

Ellerin koyunde Hatcam

Kahir cekilmez

Doldur agulari

Icelim Hatcam

Dalga dalga dalgalaniyor

Hatcami gorenler anam sevdalaniyor.', 'Denizin dibinde Hatcam Demirden evler Ak gerdan ustunde anam Ciftedir benler O kinali parmaklar parmaklarda O beyaz eller Yolcuyu yolundan e...', ARRAY['Türk Edebiyatı','Şiir','Şair Geleneksel']::text[], 8.5, '{"poet":"Şair Geleneksel","poet_slug":"sair-geleneksel","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hatcam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışkın Değilim', 'aliskin-degilim-pervin-adalioglu-9hrzc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'seni çok sevdiğimi haykırarak sarılmak istiyorum.

ben alışkın değilim bitanem bu kadar ayrı kalmaya.

her gün sarılmalıyım sana

her gün okşamalı her gün beni benden alan gözlerine bakmalıyım.

her gün parmaklarımı saçlarına dolayıp dudaklarını almalıyım içime.

ve her gün seni sevmeli aşık olmalı özlemeliyim.

ben alışkın değilim bitanem senden yanındayken uzak kalmaya

her gün kendimi okşatmalı her gün ellerimi avuçlatmalıyım.

her gün bana baktırmalı her gün dudaklarına güzel sözler söyletmeliyim.

ve her gün gözlerinle sevdirmeli her gün bakışlarınla kendimi soydurtmalıyım.

ve beni çok sevdiğini söyletmeli bende seni seviyorum demeliyim....

11: 10

16 Aralık''02-Denizli

Pazartesi', 'seni çok sevdiğimi haykırarak sarılmak istiyorum. ben alışkın değilim bitanem bu kadar ayrı kalmaya. her gün sarılmalıyım sana her gün okşam...', ARRAY['Türk Edebiyatı','Şiir','Pervin Adalıoğlu']::text[], 8.5, '{"poet":"Pervin Adalıoğlu","poet_slug":"pervin-adalioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/aliskin-degilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiçbişeyin', 'hicbiseyin-nev-bilginer-cqpyr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kurudu güneşte yas

küçüldü

en yakındaki hani

daha çok acır içi

duyuldu sözlerin

den beri

her yerde bu yas

bi yas

ve sen 

ve titrek gözlerin

gazap tütüyor büyüyen gözlerin

hiçbişeyin olasım gelmiyor', 'Kurudu güneşte yas küçüldü en yakındaki hani daha çok acır içi duyuldu sözlerin den beri her yerde bu yas bi yas ve sen  ve titrek gözlerin ...', ARRAY['Türk Edebiyatı','Şiir','Nev Bilginer']::text[], 8.5, '{"poet":"Nev Bilginer","poet_slug":"nev-bilginer","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hicbiseyin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kız', 'kiz-sessiz-adam-4hrjv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir kiza gönül verdim

illede o kiz derdim

onu icime ekerdim

Babamdan cok dayak yerdim

Sevdim o kizi bir kere

birakmam onu ellere

alip getiririm eve

yok deve! 

Ah diye sineme vurdum

ben ne hayeller kurdum

döndüm baktim durdum

ben sana vuruldum

eger beni görmek geliyorsa icinden

sen zahmet etme yerinden

bir gün cikar gelirim evimden

tabi bunu istersen...', 'Bir kiza gönül verdim illede o kiz derdim onu icime ekerdim Babamdan cok dayak yerdim Sevdim o kizi bir kere birakmam onu ellere alip getiri...', ARRAY['Türk Edebiyatı','Şiir','Sessiz Adam']::text[], 8.5, '{"poet":"Sessiz Adam","poet_slug":"sessiz-adam","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizken Gozlerim', 'sensizken-gozlerim-kaan-demir-7fn5b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sensizlik coktu yıne uzerime 

Hasret bekliyor yine penceremde

Gozlerim kose basını bekliyor

Belki sen gelirsin diye

Sensizligi bir ben bilirim 

Birde gozlerim hani

Hep seni bekleyen hep seni arayan o gozler

Bu askın gunahını hep onlar cekti

Aglayarak saatlerce yollarına bakarak

Vede seni bekleyerek

Yasamını bır sana kurmus gozlerim

Yazık degilmi bana beni bırak gozlerime', 'Sensizlik coktu yıne uzerime  Hasret bekliyor yine penceremde Gozlerim kose basını bekliyor Belki sen gelirsin diye Sensizligi bir ben bilir...', ARRAY['Türk Edebiyatı','Şiir','Kaan Demir']::text[], 8.5, '{"poet":"Kaan Demir","poet_slug":"kaan-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensizken-gozlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niye Susayım', 'niye-susayim-mehmet-yucel-mteqs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsan hayvan gibi olmak peşinde, 

Bunu görüyorsam niye susayım.

Yiğidin kellesi kalleş dişinde, 

Eğer görüyorsam niye susayım.

Beni anlamıyor konuşan canlı, 

Cehaleti vurdum ellerim kanlı, 

Yobaz masum, oldu ben de bir zanlı, 

Bedel ödüyorsam niye susayım.

Konuşmk adına mecliste tektim, 

Ben bu yolda nice çileler çektim, 

Toplum tarlasına tohumlar ektim, 

Yeşertemiyorsam niye susayım.', 'İnsan hayvan gibi olmak peşinde,  Bunu görüyorsam niye susayım. Yiğidin kellesi kalleş dişinde,  Eğer görüyorsam niye susayım. Beni anlamıyo...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yücel']::text[], 8.5, '{"poet":"Mehmet Yücel","poet_slug":"mehmet-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/niye-susayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benimsin diye', 'benimsin-diye-magic-world-fch8k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'o güzel aşkımıza nazarmı değdi

Bilmem neden ayrıldık suçumuz neydi

sevenler ayrılmaz derdin bana 

yalvarırım dön gel artık muhtacım sana..

+

sen bir yana dünya bir yana sevgilim

yalvarırım dön artık muhtacım sana...

+

Gül yüzünü görünce mesut olurdum 

Senin gibi birini nerede bulurdum 

sevenler ayrılırmı diyordun bana

yalvarırım dön artık mhtacım sana.

+

Güneşi sevdim saçların diye

denizi sevdim Gözlerin diye

SeNi SeVDim BeNiMSiN DiYe...', 'o güzel aşkımıza nazarmı değdi Bilmem neden ayrıldık suçumuz neydi sevenler ayrılmaz derdin bana  yalvarırım dön gel artık muhtacım sana.. +...', ARRAY['Türk Edebiyatı','Şiir','Magic World']::text[], 8.5, '{"poet":"Magic World","poet_slug":"magic-world","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/benimsin-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benden Başkasını Seversen Eğer', 'benden-baskasini-seversen-eger-batuhan-toplu-22hbn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Masumlar gibi boynun bükülsün

Tırnakların dibinden sökülsün

Tek istediğim o güzel yüzün hiç gülmesin

Benden başkasını seversen eğer

anan baban nedir diye bilmesin halini 

tüm doktorlar derdine derman bulamasın 

benden başkasını seversen eğer

yılan akrep yuvasına mezarın kazılsın

mezarının başına nankör diye yazılsın

benden başkasını seversen eğer

kara bulutlar sarsın evin etrafını 

azrail beklesin almak için canını

ben değil aşkım emsin acımasızca kanını

benden başkasını seversen eğer', 'Masumlar gibi boynun bükülsün Tırnakların dibinden sökülsün Tek istediğim o güzel yüzün hiç gülmesin Benden başkasını seversen eğer anan bab...', ARRAY['Türk Edebiyatı','Şiir','Batuhan Toplu']::text[], 8.5, '{"poet":"Batuhan Toplu","poet_slug":"batuhan-toplu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/benden-baskasini-seversen-eger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-musvette-sair-pt615', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevdiceğim, sayrı mısın sağ mısın? 

Bir düş gördüm aklım hep sende kaldı.

Diyeceğim: Kara mısın ağmı sın? 

Bir düş gördüm aklım hep sende kaldı

Karlı dağlar yasta gibi tülü var, 

Yeşil bağlar hasta gibi gülü var.

Sanırsın ki her  evde bir ölü var, 

Bir düş gördüm aklın hep sende kaldı.

Garip aşık inler senin adını, 

Unutmadım o günlerin tadını, 

Hayatımın kara güllü kadını, 

Bir düş gördüm aklım hep sende kaldı.', 'Sevdiceğim, sayrı mısın sağ mısın?  Bir düş gördüm aklım hep sende kaldı. Diyeceğim: Kara mısın ağmı sın?  Bir düş gördüm aklım hep sende ka...', ARRAY['Türk Edebiyatı','Şiir','Müsvette Şair']::text[], 8.5, '{"poet":"Müsvette Şair","poet_slug":"musvette-sair","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dus-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kılavuz (I)', 'kilavuz-i-ahmet-kurt-fsqga', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hoca Ahmet Yesevi’nin ocağı, 

Yüreğimde yanan bir ateş olmuş, 

Hünkar Hacı Bayram almış bıçağı, 

Hayal dünyasında boynum vurulmuş. 

Mecalim yeterse saymak dilerim, 

Nefesiyle gözlerimi silmek isterim, 

Çağrısına uyup hemen giderim, 

Mevlana bir güzel yürekli kulmuş, 

Öyle çetin, öyle çetin ki bu yol, 

Mihnete dayanmaz, katlanamaz kul, 

Onun deryasında ayrı bir okul, 

Gönül dergahıma Pir Sultan konmuş. 

Fuzuli bir alem, divan denince, 

Nedim’in yolları sırattan ince, 

Nefi’nin sözleri cana değince, 

Tenimden geçerek hedefi bulmuş. 

Güzele denecek sözü komadım, 

Gülek konağımdı Toros durağım, 

Çeşme başlarında güzel sorardım, 

Karacaoğlan renkli ürünler sunmuş. 

Erzurum yaylası ayrı bir dünya, 

Emrah’ı görmeden olur mu rüya, 

Hele kırmızı gül tarifi var ya, 

Güzellik tahtına saltanat kurmuş. 

Yiğitlik denince, Bolu dağında, 

Çamlıbel yaylası Ayvaz yanında, 

Rüzgar gibi eser kırat koynunda, 

Koç yiğit Köroğlu, zulme set olmuş. 

Azığı sırtında Türkmen kocası, 

Herkese malumdur Tapduk hocası, 

Yurdunda amansız doğum sancısı, 

Yürekler içinde Yunus vururmuş. 

Bu tarih özümü yakar kavurur, 

Kül eder cismimi yele savurur, 

Deli gönlüm bu ateşle avunur, 

Sümmani de gelip tahta kurulmuş. 

Yönüm nere dönsem bir ulu çınar, 

Baktıkça gözümde çıngılar çakar, 

Dadaloğlu denen bir yiğit bakar, 

Dağın doruğunda heybetle durmuş. 

Cumhuriyet devri ayrı bir zengin, 

Orhan Veli, Ziya Osman, Cahit Külebi’n, 

Beyatlı, Dağlarca biter mi sandın, 

Atamın yurdunda Güllere vurmuş. 

O bir daha nasip olmasın diye, 

İstiklal Marşını verdin hediye, 

Asım’dan başlayıp Çanakkale’ye 

Mehmet Akif Ersoy içinden doğmuş. 

Gölgesinde şimdi huzurluyum ben, 

Al bayrağım sana azdır söylenen, 

Yıldızı var Arif Arif diye dillenen, 

Asya’nın aslanı, bayrağa konmuş. 

Seni unutur mu anlayan dostlar, 

Gönül gözlerinden süzüldü yaşlar, 

Yürekten toprağa akımlar başlar, 

Veysel sadık yari öze kavuşmuş. 

Yıldızı söner mi güzel ülkemin, 

Dumanlı dağların tutar matemin, 

Sözleri cihanda Türkmen erinin, 

Mahzuni Şerifim bir selam vermiş. 

Yurt vermem düşmana diyen benliği, 

Cepheden cepheye koşan Şenliği, 

Aramızda dolaşıyor kimliği, 

Çobanoğlu, aşık Reyhani doğmuş. 

Aşıklık Türkün özünden başlar, 

Kimi koşma söyler, kimisi taşlar, 

Cihana bir gelir Neşet Ertaşlar, 

Sazıyla sözleri ne güzel uymuş. 

Kurdoğlu ve Bayram minnet borcunu, 

Yazarak karmayı ister harcını, 

Oku sen de biraz doldur hurcunu, 

Her satır, her hece yürekten gelmiş. 

“Bir sohbet esnasında gelişti fikir. Yakında aramızda olacak Bayram Erdoğan adlı dostumla ortaklaşa, tarihten süzülerek gelen gönül sultanlarının aziz hatıralarına ithaf edilmek üzere bu şiir yazmak. ”', 'Hoca Ahmet Yesevi’nin ocağı,  Yüreğimde yanan bir ateş olmuş,  Hünkar Hacı Bayram almış bıçağı,  Hayal dünyasında boynum vurulmuş.  Mecalim ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/kilavuz-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdası Bende Sevdam', 'sevdasi-bende-sevdam-mahmut-dogan-dgg1g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben Bir Sevdaya Tutuldum.

Adı Sevda Olan.

Ben İlk Günden Abayı Yaktım.

Sevdayı Hiç Tanımadan.

Uyku Tutmadı, Geceler Bitmedi.

Sevda Beni Tanımadan.

Sevdama şiir yazdım.

Sevdamın haberi Olmadan.

Sevda kimmidir dedin.

Sevda benim ilk ve son aşkımdır.

Adı Sevdadır Sevdası Bende Olan.

Saçları Tel Tel Belinde.

Değdimi Elim Eline.

Fırtınalar Kopuyor İçimde.

O Kadar Sıcak Kanlı Ki, 

Her Gördüğümde Eriyorum.

Gözlerine Baktığım Zaman

Gözlerimde Bir Işıltı Seziyorum.

Sevdayı Tanıdıkça Hissediyorum.

İsmi Gibi Sevdasını Yüreğimde.

Sevdayı Bilmem Ama 

Ben Çok Seviyorum...', 'Ben Bir Sevdaya Tutuldum. Adı Sevda Olan. Ben İlk Günden Abayı Yaktım. Sevdayı Hiç Tanımadan. Uyku Tutmadı, Geceler Bitmedi. Sevda Beni Tanı...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Doğan']::text[], 8.5, '{"poet":"Mahmut Doğan","poet_slug":"mahmut-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevdasi-bende-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Martılar', 'martilar-i-srafil-yildizkan-ud1lq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '-Seher vakti, 

-Deniz kıyısın da 

-Takalar arkasından 

Balıklara pike yapan, 

-Mehtap ile 

Sevgililere seranat ceken 

-Martılar; 

Görüyorum ki artık 

Mekân değiştirmişsiniz. 

-Denizleri bırakıp 

Kara da uçuşur olmuşsunuz. 

Sizi anınca, 

-Deniz gelirdi, 

-Istanbul gelirdi aklıma. 

-Şimdiler de 

- Deniz yerine 

Çöplükler de geliyor aklıma! 

-Ne dersiniz bu işe? 

-Denizler mi çöplük, 

-Çöplükler mi deniz oldu? 

-Balıklar mı tükeniverdi 

İstanbul da ne?', '-Seher vakti,  -Deniz kıyısın da  -Takalar arkasından  Balıklara pike yapan,  -Mehtap ile  Sevgililere seranat ceken  -Martılar;  Görüyorum ...', ARRAY['Türk Edebiyatı','Şiir','İsrafil Yıldızkan']::text[], 8.5, '{"poet":"İsrafil Yıldızkan","poet_slug":"i-srafil-yildizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/martilar-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben, de Unutmadım', 'ben-de-unutmadim-derin-oger-m9b8x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biliyordum gideceğini..

Gelişinde kesif bir gidiş kokusu vardı..

Kapı açıldı, sen girdin..

Adımların gitmeye yeminli, 

Ne kadar yaklaşsan, o kadar sokuluyordu gidişin..

Gidişini de sineye çekerdim gözlerini görmeseydim..

Ama olmadı..

İlk narin bakışın perçinledi gözlerini yüreğime.

Bir çift buğulu göze tutulmuştum, eriyordum..

Nafile, gitmek için gelmiştin belliydi..

Yüreğim gözlerine kenetli..

Topladın bütün bakışlarını kalkarken, 

Gözlerin bende kalsın diyemedim, 

Gittin..

Karalar bağladım gözlerinin karasına..

Gözlerinde çok ağladı kalbim, 

Gözyaşların gönlümün yaralı figanıydı, bilmedin..

Çok kanadı içim, 

Resmini bastım herseferinde, 

En çok gözlerindeki tebessümü aradım, 

Gözlerinden güzel güleni görmedim...

Unutmadım....

Gözlerinde çok ağladı kalbim

Ben, de unutmadım..........', 'Biliyordum gideceğini.. Gelişinde kesif bir gidiş kokusu vardı.. Kapı açıldı, sen girdin.. Adımların gitmeye yeminli,  Ne kadar yaklaşsan, o...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ben-de-unutmadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlıyor Musun', 'anliyor-musun-sukru-erbas-jsgrl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zaman buldukça uğra

Tek neşem bu benim

Beklemek ve bulmakla yaşadığım

Dili tutulmuş bu şaşkın sevinç.



Eşyalar geri çekiliyor sen gelince

Bir ayrıntı gibi içinde kaybolduğum

Sığ ilişkileri günlerin

Geri çekiliyor, dudaklarıma kadar

Yükselen 
..........
..........', 'Zaman buldukça uğra Tek neşem bu benim Beklemek ve bulmakla yaşadığım Dili tutulmuş bu şaşkın sevinç. Eşyalar geri çekiliyor sen gelince Bir...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Erbaş']::text[], 8.5, '{"poet":"Şükrü Erbaş","poet_slug":"sukru-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/anliyor-musun-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzü Yağmura Gömülü Düşüm', 'yuzu-yagmura-gomulu-dusum-sukru-erbas-jru8f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Duruşun bir ayrılık resmi çiziyor

Akşamın incelen sularına

Susuşun yıkıyor beni en zayıf yerimden

Bilmez miyim içindeki kederi

Yüzü yağmura 
..........
..........', 'Duruşun bir ayrılık resmi çiziyor Akşamın incelen sularına Susuşun yıkıyor beni en zayıf yerimden Bilmez miyim içindeki kederi Yüzü yağmura ...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Erbaş']::text[], 8.5, '{"poet":"Şükrü Erbaş","poet_slug":"sukru-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yuzu-yagmura-gomulu-dusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avlu Genişliği', 'avlu-genisligi-sukru-erbas-rmp64', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sizin evleriniz var, büyük. 

Sıkıntı diye soyunduğunuz dünya, eşiklerde. 

Çocuğunuz odalarda bir gün kapalı kalmadı. 

Habersiz girmedi kapınızdan kimse. 

 o masal hâlâ uyumanız için. 

Gittiğiniz hiçbir toplantı suç sayılmadı. 

Başkası için itiraz etmediniz kimseye. 

Üniforma son sözünüz, içinizden giydiğiniz. 

Emekten, yalnız kendinizi anladınız. 

Susup kaldığınız olmadı hiç. 

Arkanızı döndüğünüz, yoktu. 

..........
..........', 'Sizin evleriniz var, büyük.  Sıkıntı diye soyunduğunuz dünya, eşiklerde.  Çocuğunuz odalarda bir gün kapalı kalmadı.  Habersiz girmedi kapın...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Erbaş']::text[], 8.5, '{"poet":"Şükrü Erbaş","poet_slug":"sukru-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/avlu-genisligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutuşmak Üzere Yeniden', 'tutusmak-uzere-yeniden-sukru-erbas-4ev33', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sızıyor sessizce kendi derinine

Çıkışını bulamayan sular.

İnsan aynı türküyü aynı içtenlikle

Söyleyemiyor ki uzun zaman

Böyle karşılıksız yankısız', 'Sızıyor sessizce kendi derinine Çıkışını bulamayan sular. İnsan aynı türküyü aynı içtenlikle Söyleyemiyor ki uzun zaman Böyle karşılıksız ya...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Erbaş']::text[], 8.5, '{"poet":"Şükrü Erbaş","poet_slug":"sukru-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/tutusmak-uzere-yeniden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eksilmesin İmgen', 'eksilmesin-i-mgen-sukru-erbas-sq67w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bana verdiğin mutluluğu

Paylaşacak kimsem yok

Sevincimi içime 

Ve yalnız taşıyorum

             (Biliyorsun ya

Su
..........
..........', 'Bana verdiğin mutluluğu Paylaşacak kimsem yok Sevincimi içime  Ve yalnız taşıyorum              (Biliyorsun ya Su .......... .............', ARRAY['Türk Edebiyatı','Şiir','Şükrü Erbaş']::text[], 8.5, '{"poet":"Şükrü Erbaş","poet_slug":"sukru-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/eksilmesin-imgen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynı Yürek Lekesi', 'ayni-yurek-lekesi-sukru-erbas-7qxep', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Babam gelirdi ve akşam olurdu. 

Bahçedeki akasya ağacı günboyu biriktirdiği kuşları 

birer hayal topu olarak uzatırdı yatağımıza. 

Siyah-beyaz bir fotoğraf gibi gelirdi babam. 

Kamyonlar hep geceleri, hep uzaklara giderdi. 

Ben o zamanlar bütün babaları susar sanırdım. 

Yalnızca gaz lambasıyla ko
..........
..........', 'Babam gelirdi ve akşam olurdu.  Bahçedeki akasya ağacı günboyu biriktirdiği kuşları  birer hayal topu olarak uzatırdı yatağımıza.  Siyah-bey...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Erbaş']::text[], 8.5, '{"poet":"Şükrü Erbaş","poet_slug":"sukru-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ayni-yurek-lekesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Özlemin İzdüşümü', 'bir-ozlemin-i-zdusumu-sukru-erbas-n5h46', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eğri çizgiler dalgın

İki kaşım üzerinde

İki kaşım üzerinde bir ağrı

Gözlerim yanıyor günlerdir

Gözlerimde bir yangın.



Bi
..........
..........', 'Eğri çizgiler dalgın İki kaşım üzerinde İki kaşım üzerinde bir ağrı Gözlerim yanıyor günlerdir Gözlerimde bir yangın. Bi .......... ...........', ARRAY['Türk Edebiyatı','Şiir','Şükrü Erbaş']::text[], 8.5, '{"poet":"Şükrü Erbaş","poet_slug":"sukru-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-ozlemin-izdusumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Neden Başkalarını Sevemiyoruz', 'biz-neden-baskalarini-sevemiyoruz-sukru-erbas-427ou', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gümüşün ustalarını bitirdik 

Ahşap konakların oymalı dolapların 

Üzümün camın kesme taşın ustalarını... 

Akik kehribar yakut ve lal 

İşleyip incecik dünyayı parmaklarıyla 

Hantal düzlüğümüze köpük köpük 

Pencereler açan 
..........
..........', 'Gümüşün ustalarını bitirdik  Ahşap konakların oymalı dolapların  Üzümün camın kesme taşın ustalarını...  Akik kehribar yakut ve lal  İşleyip...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Erbaş']::text[], 8.5, '{"poet":"Şükrü Erbaş","poet_slug":"sukru-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/biz-neden-baskalarini-sevemiyoruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ek de....', 'ek-de-ali-riza-erdem-chyfa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'şiir yarım kalmış aşkları tamamlar 

senle başlayıp şiirle biten bir aşkın ardından 

ek de yüreğimden parçalar gönderdim 

doğan güneşe......', 'şiir yarım kalmış aşkları tamamlar  senle başlayıp şiirle biten bir aşkın ardından  ek de yüreğimden parçalar gönderdim  doğan güneşe.........', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Erdem']::text[], 8.5, '{"poet":"Ali Rıza Erdem","poet_slug":"ali-riza-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ek-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cehennem Bekçisi', 'cehennem-bekcisi-huseyin-osmanoglu-ilpx3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Cehennem bekçisi kalktı yerinden

Ölülerin tuttu tek tek elinden

Azrail sordu.

Bunlar ne yapmış? 

-Bu vurmuş.

-Bu çalmış.

-Bu aldatmış.

-Peki bu (      )  ne yapmış? 

-O aşkı aramış, bulmuş ve kaybetmiş

-''Peki.Onu affediyorum'' demiş azrail.

-Çünkü O ezelden beri cehennem ateşinde yanmış...', 'Cehennem bekçisi kalktı yerinden Ölülerin tuttu tek tek elinden Azrail sordu. Bunlar ne yapmış?  -Bu vurmuş. -Bu çalmış. -Bu aldatmış. -Peki...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Osmanoğlu']::text[], 8.5, '{"poet":"Hüseyin Osmanoğlu","poet_slug":"huseyin-osmanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/cehennem-bekcisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan Ter İçinde', 'kan-ter-i-cinde-sukru-erbas-psy25', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağzın ömrüm. Ağzın öptükçe derin

Konuşuyorsun, kanatlı bir karanfil dudakların.

Gözlerin iki dağ suyu güldükçe köpüklenen

İndiriyorsun kirpiğini upuzun bir güz.

Bir kapı 
..........
..........', 'Ağzın ömrüm. Ağzın öptükçe derin Konuşuyorsun, kanatlı bir karanfil dudakların. Gözlerin iki dağ suyu güldükçe köpüklenen İndiriyorsun kirpi...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Erbaş']::text[], 8.5, '{"poet":"Şükrü Erbaş","poet_slug":"sukru-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kan-ter-icinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yenilgi', 'yenilgi-sukru-erbas-6kkbt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir kadın iki çocukla 

Çiviliyim odalara 

Söylesem de söylemesem de bu böyle 

Çıksam çıksam 

Zincirim kadar özgürlüğüm 

Yaşamak hep ötelerde 

Dili kopmuş bir hayal çanı yüreğim 

Sesini yalnız benim duyduğum 

Vurur durur çığlık çığlık içimde 

Dönüşü olmayan biricik şeymiş zaman 
..........
..........', 'Bir kadın iki çocukla  Çiviliyim odalara  Söylesem de söylemesem de bu böyle  Çıksam çıksam  Zincirim kadar özgürlüğüm  Yaşamak hep ötelerde...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Erbaş']::text[], 8.5, '{"poet":"Şükrü Erbaş","poet_slug":"sukru-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yenilgi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kum ile Su', 'kum-ile-su-sukru-erbas-ej4wh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben, duvar diplerini giyineceğim 

Kimseye kapısından yakın olmayacağım 

Ağzımı kuyulara vereceğim 

Beni kim beklemiyorsa ona gideceğim 

Otların ıssız mevsimini seveceğim 

Bir yağmur hükmü olacağım 

Mutluluğu pişmanlığı bir bileceğim 

Sitemlerinizden eksileceğim 

Kum sahiplerine suları göstereceğim 

..........
..........', 'Ben, duvar diplerini giyineceğim  Kimseye kapısından yakın olmayacağım  Ağzımı kuyulara vereceğim  Beni kim beklemiyorsa ona gideceğim  Otla...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Erbaş']::text[], 8.5, '{"poet":"Şükrü Erbaş","poet_slug":"sukru-erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kum-ile-su-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkına Mecnun', 'askina-mecnun-serkan-pisgen-3x3pb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Susuz çöller gibi sana susadım; 

Gecesi olmayan güne ağladım; 

Leyla''yı arayan mecnun misali, 

Gözümdeki yaşlar sel oldu aktı...

Yalnızlık bahtımın kara yazısı; 

Sensizlik ömrümün enzor acısı; 

Ne olur dön bana bitsin bu sancı, 

Sana yemin edip af diliyorum...

Kuşlar bile yalnız uçmaz diyorlar; 

Ölümde sebebsiz olmaz diyorlar; 

Bu canımda sensiz yaşamaz ama, 

Gel görki bu can seni bekliyor...', 'Susuz çöller gibi sana susadım;  Gecesi olmayan güne ağladım;  Leyla''yı arayan mecnun misali,  Gözümdeki yaşlar sel oldu aktı... Yalnızlık b...', ARRAY['Türk Edebiyatı','Şiir','Serkan Pişgen']::text[], 8.5, '{"poet":"Serkan Pişgen","poet_slug":"serkan-pisgen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/askina-mecnun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudumsun', 'umudumsun-serkan-pisgen-zuin3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uzaklardayım bu akşam yine sensiz; 

Mehtabı seyrediyorum yalnız ve kimsesiz; 

Ufukta ince bir çizgi, belkide sevgimiz; 

Dalgalar yükseliyor etrafında, kaybolacak belkide hayallerimiz

Umudumu yitirmedim, istemeselerde kavuşacağız ikimiz; 

Masmavi göklerde yeşeriyor sonsuz sevgimiz; 

Solmayacak aşkımız, gün geçtikçe büyüyor fendimiz; 

Umudumsun, bekleyeceğim senei mehtabı olan gecelerde; 

Nasıl olsa, her gecenin bir mehtabı var, bekleyeceğim seni senelerce', 'Uzaklardayım bu akşam yine sensiz;  Mehtabı seyrediyorum yalnız ve kimsesiz;  Ufukta ince bir çizgi, belkide sevgimiz;  Dalgalar yükseliyor ...', ARRAY['Türk Edebiyatı','Şiir','Serkan Pişgen']::text[], 8.5, '{"poet":"Serkan Pişgen","poet_slug":"serkan-pisgen","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/umudumsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeyeceğim', 'sevmeyecegim-serkan-pisgen-dww62', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gök yüzü karanlık ben ağlıyorum; 

Doğmuyor güneşim hep içiyorum; 

Bileklerimde kelepçe, zindana gidiyorum, 

Değermiydi senin için mahkum olmaya...

Birdaha böyle sevmeyeceğim; 

Birdaha bu acıyı çekmeyeceğim; 

Yıkıldı hayalim mahkum olunca; 

Birdaha seni sevmeyeceğim; 

Karanlık günlerim hep acı dolu; 

Kırılan kalbimde isyanlar dolu; 

Allah''ım sen affet isyankar kulunu; 

Birdaha kimseyi sevmeyeceğim...', 'Gök yüzü karanlık ben ağlıyorum;  Doğmuyor güneşim hep içiyorum;  Bileklerimde kelepçe, zindana gidiyorum,  Değermiydi senin için mahkum olm...', ARRAY['Türk Edebiyatı','Şiir','Serkan Pişgen']::text[], 8.5, '{"poet":"Serkan Pişgen","poet_slug":"serkan-pisgen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevmeyecegim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-sair-orantula-ffy88', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ela gözlerinde bir masal ülkesi görüyorum

İçinde sevdadan başka birşey olmayan

Aşk renginde milyonlarca gül var orada 

Hiçbir zaman solmayan

Bir de kalp görüyorum gökyüzünde

Hani şu aşk meleğinin okuyla vurulmuş

Bir tarafında senin

Diğer tarafında benim adım yazıyor

Çok büyük harflerle

Görüyorsun ya yıldızlar bile duymuş aşkımızı

Ölümsüzleştirmek için çizmişler

Seni ve beni sonsuz gökyüzüne', 'Ela gözlerinde bir masal ülkesi görüyorum İçinde sevdadan başka birşey olmayan Aşk renginde milyonlarca gül var orada  Hiçbir zaman solmayan...', ARRAY['Türk Edebiyatı','Şiir','Şair Orantula']::text[], 8.5, '{"poet":"Şair Orantula","poet_slug":"sair-orantula","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozlerin-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Sen', 'hep-sen-i-rfan-donmez-kjxti', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yağan karda, esen rüzgarda

Hep sen varsın.

Yağmur damlalarında, bülbül sesinde

Sümbülün kokusunda, kelebek kanadında

Yine sen varsın



Güneşimsin ısıtan

Ayımsın aydınlatan

Kor bir alevsin ruhumu yakan

Çölde buzlu su gibisin

Kutupta bir kadeh sıcak şarap

Cennetteki hurisin



Sağa dönsem sen

Arkamda gölgen

Sola dönsem yine sen

Yerde, gökte, her yerde

Hep sen varsın

Sen nesin sen...', 'Yağan karda, esen rüzgarda Hep sen varsın. Yağmur damlalarında, bülbül sesinde Sümbülün kokusunda, kelebek kanadında Yine sen varsın Güneşim...', ARRAY['Türk Edebiyatı','Şiir','İrfan Dönmez']::text[], 8.5, '{"poet":"İrfan Dönmez","poet_slug":"i-rfan-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hep-sen-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçilmezimsin', 'vazgecilmezimsin-i-rfan-donmez-hgs30', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bak rüzgar nasıl okşuyor tenimi

Tıpkı o beyaz ellerin gibi

Akan soğuk su nasıl titretiyor içimi

Tıpkı bana bakan gözlerin gibi

Parlak güneş nasıl ısıtıyor bedenimi

Tıpkı bana yönelen benliğin gibi

Sen içtiğim su, soluduğum nefessin

Ellerimin aradığı, yüreğimin susadığı sevgisin

Sen bir başyapıt, gönlümün sultanı

Hayat iksirim, vazgeçilmezimsin...', 'Bak rüzgar nasıl okşuyor tenimi Tıpkı o beyaz ellerin gibi Akan soğuk su nasıl titretiyor içimi Tıpkı bana bakan gözlerin gibi Parlak güneş ...', ARRAY['Türk Edebiyatı','Şiir','İrfan Dönmez']::text[], 8.5, '{"poet":"İrfan Dönmez","poet_slug":"i-rfan-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/vazgecilmezimsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakamamak', 'bakamamak-firat-utkan-mq7ng', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sebepsiz bir zenginlikmiş benimkisi

Çoktan söküp attığın kalbinde umut aramak

Gelmeyecek yeşili beklemek gibi...

İki sokak arkada buluşmak, ertesi ayrılmak

Ve birdaha buluşamamak

Dahası içten değil dalga geçer gibi

Saat yarım olduğunda diğer yarımı bekler gibi

Uçurum kenarında yıldızı tutmak

Fırat''ı tersine akıtıp pınarları toplamak 

Ama toprağı küstürmeden özlemek 

......................

Özlemek gibi

Miller gibi henüz yirmibirinde ölmek

Göğü yedi kat bilip dördüncü katta ağlamak 

Aldırmamak gibi umursamazlığına nispet

Bilmem kaç milyon yıl uzaktaki güneşle yaşamak

Ve hergün görüp ve hergün bakmamak gibi

.................................

Bakamamak gibi...', 'Sebepsiz bir zenginlikmiş benimkisi Çoktan söküp attığın kalbinde umut aramak Gelmeyecek yeşili beklemek gibi... İki sokak arkada buluşmak, ...', ARRAY['Türk Edebiyatı','Şiir','Fırat Utkan']::text[], 8.5, '{"poet":"Fırat Utkan","poet_slug":"firat-utkan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bakamamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrümüzün Hikayesi', 'omrumuzun-hikayesi-aziz-akgun-otf1f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 've doğdu insanoğlu

açtı gözlerini dünyaya 

nedense korktu birden

başladı ağlamaya

kimse bilemedi

bu gözyaşları neden

''bebektir ağlar'' dediler

unuttular

doğarken yürekleri dağladığını

zaten ona da unutturdu hayat

doğarken ağladığını

koynuna verip annesinin 

emzikler tıkıştırdılar ağzına

ve çaresiz insanoğlu

başladı yaşamaya

.............................

önce emekledi insanoğlu

iki kol, iki bacak

ne zaman düşse yere 

bekledi bir el kaldıracak

ve hep geldi beklediği el

ve özlediği o kucak

minik kafasında bir garip düşünce 

ansızın dudaklarından döküldü iki hece

''anne'' dedi 

sustu...

ilk kelime ilk arkadaş

insanoğlu konuştu...

...............

aylar ayları kovalarken

yürüdü insanoğlu

iki ayağa durdu güneşe karşı

şaşırdı yağmurlara 

sevdi rüzgarları

ne zaman rüzgar çıksa

süzüldü gökte uçurtmaları

hep korktu gecelerden

ve zor bilmecelerden

aklı karışıp çoğu zaman 

anlamsız sorular sordu

tatlı rüyalar görüp boyuna 

yelken açtı 

masallar koyuna

hayat döktü önüne oyuncaklarını

ve insanoğlu 

kapıldı gitti bu oyuna...

..........................

derken genç bir fidan

adı bende saklı insanoğlu

bıyıkları başlarken terlemeye

baharla çiçeklere kondu arı

ve kaçınılmaz son

aşka düştü yolları...

kocaman sevdasını 

sımsıkı tutup ellerinde

harmanladı yüreğini

bahar yellerinde

''güzel şeymiş sevmek'' dedi birden

ve gariptir 

ağladı sevdiğinden...

.....................

birer birer düşen takvimler 

zamanın geldi dediler

ve resmileşen sevgiler

insanoğlunda belirdiler

hayat tozpembe değildi artık

eş, çocuk, sorumluluk

geçim derdi

varlık ve yokluk...

ve nereden çıktıysa 

her akşam o garip yorgunluk

birşeyler seziyordu insanoğlu

tükeniyor muydu acaba 

upuzun yolu

saçlarına yavaş yavaş yağan 

kar mıydı

yoksa ansızın yakalayan bir dolu

hem hülyasını da yitirmişti geceler

geceler sabaha zor çıkıyordu

geceler baştan başa korkulu

...............

artık anladı ki insanoğlu 

ardında kalan sadece güzel hatıralar 

bıraktığı masal koyunda

hayat son perdeyi

çoktan açmış bu oyunda...

ıslandı boşluğa takılan gözleri 

sordular yaşlı adama derdini

söylemedi...

ve sustu öylece

dindi bir fırtına 

tükendi bir ömür böylece,,,,,,,,', 've doğdu insanoğlu açtı gözlerini dünyaya  nedense korktu birden başladı ağlamaya kimse bilemedi bu gözyaşları neden ''bebektir ağlar'' dedile...', ARRAY['Türk Edebiyatı','Şiir','Aziz Akgün']::text[], 8.5, '{"poet":"Aziz Akgün","poet_slug":"aziz-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":92,"source_url":"https://www.antoloji.com/omrumuzun-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Resmi', 'askin-resmi-i-rfan-donmez-6umvx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşkın resmini yapsam

Bu senin resmin olurdu

Üç renk bulunurdu tam

Beyaz, sarı ve kahve

Beyaz tenindir

Sarı saçlarındır

Kahve ise gözlerin

Üç renk birlikte ruhunun rengidir

Çizgiler aşkımızın çizgisi

Çizgi iki nokta arasındaki

En kısa yol değil ki

Noktaları sen ve ben olan iki komşu

Noktadır tarifi belirleyen

Bu nokta çok mühim ki

Orası aşkımızın geometrik yeri', 'Aşkın resmini yapsam Bu senin resmin olurdu Üç renk bulunurdu tam Beyaz, sarı ve kahve Beyaz tenindir Sarı saçlarındır Kahve ise gözlerin Üç...', ARRAY['Türk Edebiyatı','Şiir','İrfan Dönmez']::text[], 8.5, '{"poet":"İrfan Dönmez","poet_slug":"i-rfan-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/askin-resmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinde Unutuldum', 'gozlerinde-unutuldum-tuncer-onal-l85e7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aklıma gelmiyor değilsin hani, 

Rüzgarların renk verdiği gecelerimde, 

Umutsuzluğu yitirdiğim garipsi duygularla, 

Mısralar diziliyor gözlerimde, 

Senin için yazdıklarım.

Ne olur

Bakma gözlerime öyle ağlamaklı...

Ben çökmüşüm bir kez

Sevgiden, saadetten yana

Bir damla yaş gibiyim gözlerinde unutulmuş.

Unut yine hatırlama', 'Aklıma gelmiyor değilsin hani,  Rüzgarların renk verdiği gecelerimde,  Umutsuzluğu yitirdiğim garipsi duygularla,  Mısralar diziliyor gözler...', ARRAY['Türk Edebiyatı','Şiir','Tunçer Önal']::text[], 8.5, '{"poet":"Tunçer Önal","poet_slug":"tuncer-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gozlerinde-unutuldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlar', 'yalnizlar-tuncer-onal-bdfgv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gün gelecek, 

Bir tek ben kalacağım bu rıhtımda

Seni bekleyen, 

Sarhoş martıları seyredeceğim

Ve denizin derinliklerine dalıp, 

Yosun yeşili gözlerinden öpeceğim', 'Bir gün gelecek,  Bir tek ben kalacağım bu rıhtımda Seni bekleyen,  Sarhoş martıları seyredeceğim Ve denizin derinliklerine dalıp,  Yosun ye...', ARRAY['Türk Edebiyatı','Şiir','Tunçer Önal']::text[], 8.5, '{"poet":"Tunçer Önal","poet_slug":"tuncer-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yalnizlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitenler', 'bitenler-ciler-goksel-7jmvn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsanda bitenler

Mektuplarla

Fotoğraflarla

Sözlerle bitmiyor.

Yutkunduğun an bitiyor. 

Yutkunduğun, 

Nefes alamadığın   

Ve ağlayamadığın an...', 'İnsanda bitenler Mektuplarla Fotoğraflarla Sözlerle bitmiyor. Yutkunduğun an bitiyor.  Yutkunduğun,  Nefes alamadığın    Ve ağlayamadığın an...', ARRAY['Türk Edebiyatı','Şiir','Çiler Göksel']::text[], 8.5, '{"poet":"Çiler Göksel","poet_slug":"ciler-goksel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bitenler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağır Zehrim', 'agir-zehrim-nihal-tezcan-w0vwi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ağır ağır içmeliydim zehrini 

Tüm uzuvlarımla hissetmeliydim 

Önce bir uyuşukluk hali almalıydı 

Ama en son beynim ve gözlerim 

Kapanmalıydı. 

En son sen geçmeliydin 

Uyuşmuş beynimle gözlerimden 

Gözlerimde senin hayalin 

Beynimde düşüncelerin 

Tam her yerim uyuştuğunda, 

Gözlerimden sen kaybolduğunda 

Bilincimi de kaybettiğimde 

Beni soğuk balkon duvarına yaslı bulmalıydın 

Önce anlamsızca izlemeli 

Halime bir neden bulamamalıydın. 

Sonra zehrini aldığım şırıngayı görüp 

Gözlerime bakmalıydın. 

Belki bir son hamleyle bende gözlerine dikmeliydim gözlerimi. 

Ve zehrini ağır ağır içtiğim gibi, 

Seni de ağır ağır bitirmeliydim... 

15 nisan 2002 23: 55', 'Ağır ağır içmeliydim zehrini  Tüm uzuvlarımla hissetmeliydim  Önce bir uyuşukluk hali almalıydı  Ama en son beynim ve gözlerim  Kapanmalıydı...', ARRAY['Türk Edebiyatı','Şiir','Nihal Tezcan']::text[], 8.5, '{"poet":"Nihal Tezcan","poet_slug":"nihal-tezcan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/agir-zehrim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Öyle Baktım', 'hep-oyle-baktim-nihal-tezcan-lhqe8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Korku varken gözlerimde 

Korkmadığımı söylemek garip geldi yüreğime 

Benim korkum düşüncelerindi 

Senden değildi korkularım 

Bendendi 

Anlatamıyor olmaktan kaynaklanan korkulardı. 

Merkezinde sen vardın. 

Ama oluşma nedeni bendim. 

Gözlerini anlayamamaktı beni korkutan 

Seni sana tasvir ettikten sonra 

Önce kendine sonra bana takılan gözlerindi. 

… 

Sen herkes değilsin, 

Herkes de sen değil biliyorum. 

Ama herkes gibi konuştun o gece... 

“bana öyle bakma” dedin. 

Neydi, nasıldı ve neden bakmamalıydım öyle..? 

Kimse yapmamıştı bunun açıklamasını 

Yapamamıştı belki de… 

Ben öyle baktım. 

Ve ben

Hep öyle baktım…

19 kasım 2002 20: 40', 'Korku varken gözlerimde  Korkmadığımı söylemek garip geldi yüreğime  Benim korkum düşüncelerindi  Senden değildi korkularım  Bendendi  Anlat...', ARRAY['Türk Edebiyatı','Şiir','Nihal Tezcan']::text[], 8.5, '{"poet":"Nihal Tezcan","poet_slug":"nihal-tezcan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hep-oyle-baktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Hece', 'i-ki-hece-bahri-sohtorik-4gvgt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sultanlık, krallık, çarlık

Ben kurarım ben yıkarım, 

Bana kahramanlık yapma

Zindana kor, ben salarım

Tacın, tahtınla övünme

Taht devirir, baş keserim

Güçlüyüm diye gerinme

Köle yapar, azl ederim

Dosta değil bana güven

Şan ile şöhret veririm

Eğer kıymet bilmeyensen

Yok olur, rezil ederim

Benle bütün hayat güzel

Benle bütün ömür hoştur

Şimdi diğer kavramlar

Pek manasız ve de boştur

Kuvvet benim, kudret benim

Kanun benim, nizam benim

Tek değil, iki heceyim

Şimdi, Para, adım benim.', 'Sultanlık, krallık, çarlık Ben kurarım ben yıkarım,  Bana kahramanlık yapma Zindana kor, ben salarım Tacın, tahtınla övünme Taht devirir, ba...', ARRAY['Türk Edebiyatı','Şiir','Bahri Sohtorik']::text[], 8.5, '{"poet":"Bahri Sohtorik","poet_slug":"bahri-sohtorik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/iki-hece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklıma Takılı Kaldın', 'aklima-takili-kaldin-aziz-pinar-taem4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen o ilkbaharda açtığın yerde

Sen orada kaldın.

Yazlar, kışlar geçti

Sıcak, soğuklar

Sarı sonbaharlar.

Sen orada açtın öylece kaldın...

Ne yağmurlar yağdı, rüzgarlar esti

O büyük aşkımın ilk baharında

Kokladığım yerde

Öylece kaldın...

Zaman gelip, geçti, ne çiçekler açtı

Soldu, uçtu bahar dalından

Fakat sen, solmayan, sararmayansın

Sana dokunduğum zamanda kaldın...

Koparıp almayı beceremedim

Seni o bahardan.

Hala oradamısın bilemiyorum

Şimdi nasılsın? 

Ne rüya, ne hayal göremiyorum

Aklıma takılı kaldın...', 'Sen o ilkbaharda açtığın yerde Sen orada kaldın. Yazlar, kışlar geçti Sıcak, soğuklar Sarı sonbaharlar. Sen orada açtın öylece kaldın... Ne ...', ARRAY['Türk Edebiyatı','Şiir','Aziz Pınar']::text[], 8.5, '{"poet":"Aziz Pınar","poet_slug":"aziz-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aklima-takili-kaldin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Tren', 'son-tren-bahri-sohtorik-5ssrl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her maziye dalışında

Bir buruk, bir ezik oluyorsa için

Gülmüyorsa güzel yüzün

Bil ki, bensizliktendir

Hep dert, hep keder kaplamışsa içini

Hep mutsuzsan, 

Bulamamışsan aradığını, alamamışsan

Bil ki, bensizliktendir

Duymuyor, hissetmiyorsan

Kalabalık içinde yalnızsan

Dünya, bir yabancı ise sana

Bil ki, bensizliktendir

Anladınmı bilmem

Bensizliğin, ne demek olduğunu

Sevgisizliğin, 

Ve bensiz olamayacağını, anladınmı

Artık bensizliği istemiyorsan

Anlamı yoksa yaşamın, sevgisiz

Son tren bu, haydi

Koşmalı, yetişmelisin', 'Her maziye dalışında Bir buruk, bir ezik oluyorsa için Gülmüyorsa güzel yüzün Bil ki, bensizliktendir Hep dert, hep keder kaplamışsa içini H...', ARRAY['Türk Edebiyatı','Şiir','Bahri Sohtorik']::text[], 8.5, '{"poet":"Bahri Sohtorik","poet_slug":"bahri-sohtorik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/son-tren-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evet Aşk', 'evet-ask-aziz-pinar-c9myw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Artık ellerimize hükmümüz geçmiyor

Gözlerimiz habersiz oluyor birbirinin

Bahar dalında aşkımız tomurcuklanıyor

Dudaklarda açıyor gonca gülü sevginin...', 'Artık ellerimize hükmümüz geçmiyor Gözlerimiz habersiz oluyor birbirinin Bahar dalında aşkımız tomurcuklanıyor Dudaklarda açıyor gonca gülü ...', ARRAY['Türk Edebiyatı','Şiir','Aziz Pınar']::text[], 8.5, '{"poet":"Aziz Pınar","poet_slug":"aziz-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/evet-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konuşma Bak', 'konusma-bak-aziz-pinar-581fc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sus konuşma, bir şey söyleme bana

Bulutlarla konuş, dalgalara bak

Konuşmak istersen eğer benimle

Başını göğsümün üstüne bırak

Gözlerime bak ve dudaklarını uzat...', 'Sus konuşma, bir şey söyleme bana Bulutlarla konuş, dalgalara bak Konuşmak istersen eğer benimle Başını göğsümün üstüne bırak Gözlerime bak ...', ARRAY['Türk Edebiyatı','Şiir','Aziz Pınar']::text[], 8.5, '{"poet":"Aziz Pınar","poet_slug":"aziz-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/konusma-bak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değişmeden', 'degismeden-oktay-avci-eftc8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben geldim

Sag geldim sevinin çocuklar

Ben geldim

Size kendimi getirdim

sarılın çocuklar

Yarın geleceğimi bilemezsiniz

Kolum var

Bacagım var

Size bir bayram daha çocuklar

Ben geldim yaşayarak

Ben geldim direnerek

Küserek

Korkarak

Kaçarak

Ayyaş değil

Delice değil

Oynayalım çocuklar

Bu akşamda kendim geldim

Size beni  getirdim', 'Ben geldim Sag geldim sevinin çocuklar Ben geldim Size kendimi getirdim sarılın çocuklar Yarın geleceğimi bilemezsiniz Kolum var Bacagım var...', ARRAY['Türk Edebiyatı','Şiir','Oktay Avcı']::text[], 8.5, '{"poet":"Oktay Avcı","poet_slug":"oktay-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/degismeden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Yarında', 'umut-yarinda-oktay-avci-3pktx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bekliyorum

Bu günde açmadı karanfiller

Dünde beklemiştim

Bekleyeceğim

Umut yarında

Karanlık günler yaşıyorum

Aydınlıklar senelerce önümde

Çaresi yok açacak', 'Bekliyorum Bu günde açmadı karanfiller Dünde beklemiştim Bekleyeceğim Umut yarında Karanlık günler yaşıyorum Aydınlıklar senelerce önümde Ça...', ARRAY['Türk Edebiyatı','Şiir','Oktay Avcı']::text[], 8.5, '{"poet":"Oktay Avcı","poet_slug":"oktay-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/umut-yarinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herkese Ve Her Şeye', 'herkese-ve-her-seye-oktay-avci-9q4sn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kavgaysa varım

Savaşsa yine varım

Kaçışsa yokum

Hınca hınçdoldurmuşuz meydanları

Nasıl olmam

Meydanlardan  bize merhaba

Meydanlardan size merhaba

Merhaba çılgınlıgım

Asiliğim ve teröristligim

Aşkım, sevdam merhaba

Gözlerim, gözbebeğim

Çirkinliğimden göremiyorum

Göremediyim herkese merhaba', 'Kavgaysa varım Savaşsa yine varım Kaçışsa yokum Hınca hınçdoldurmuşuz meydanları Nasıl olmam Meydanlardan  bize merhaba Meydanlardan size me...', ARRAY['Türk Edebiyatı','Şiir','Oktay Avcı']::text[], 8.5, '{"poet":"Oktay Avcı","poet_slug":"oktay-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/herkese-ve-her-seye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüznüme Failim Şimdi', 'huznume-failim-simdi-i-smail-ozabaci-rd3vh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kalp atışlarımı gözlerinde hissettiğim sevgili; 

Soğuk bir gecenin, zamansız bir saatinde, sana zaman ayırmak olsa gerek aşk, hayattan artırabildiğim umudumla, sana yazmak

Hesapsız, tutarsız, öylece, 

kalemi elime alıp düşünmeden yazmak, ve gezinmesi gözlerinin bu satırlar üstünde, aydınlatması kimbilir hangi ağaçtan yapılan bu teksir kağıdının üstünü, 

Sonra saçlarının bir sicim gibi sarması yüreğimi, 

koklamak gibi bir çiçeği, düşmesi başının omzuma sessizce, 

ve üşümen sıcak bir 4 mayıs gecesi, 

Başka bir şehirde, aynı yerde senle olmak, 

tarifsiz bir sevinç, anlamsız bir duygu, bir yanı tanımsız ama bir o kadar da anlamlı bişey bu...

Bir dua nasıl gidip yerini buluyorsa, bir gözyaşı bir sevince filizleniyorsa tutarsız, 

ve yazım bu kadar kötüyse gecenin üçünde, 

ve soruyorsam kendi kendime, 

doğallık nedir diye? 

Seni buluyorum her sorunun sonunda, her cevap bu kadar mı yakın olmalı sana, ve her anlamlı düşünce neden çağrıştırır, 

bu dengesiz halimde seni bana, 

biliyor musun? 

HÜZNÜME FAİLİM ŞİMDİ...

öylesine bir akşamda..', 'Kalp atışlarımı gözlerinde hissettiğim sevgili;  Soğuk bir gecenin, zamansız bir saatinde, sana zaman ayırmak olsa gerek aşk, hayattan artır...', ARRAY['Türk Edebiyatı','Şiir','İsmail Özabacı']::text[], 8.5, '{"poet":"İsmail Özabacı","poet_slug":"i-smail-ozabaci","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/huznume-failim-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerim Arkada Kalmayacak', 'gozlerim-arkada-kalmayacak-oktay-avci-fn7df', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben daglara çıkayımda

Sen aglama

Canım benim

Sevdam

Canmı dayanır buna

Yürekmi

Bırak sevdayı

Üstüme bombayı atsınlar

Ben parçalanayım

Sen sus

İnanmam olmaz böyle yalan

Açıkta kalayım

Zemheride buz tutsun ayagım

Aldırma 

Kim inanır

Hıçkırıklarını yutacagına

Ben ölümü yaşayayım gecelerde

Sen bekle evinde dönüşümü

Duvarları yırtarsın

Bulutları deler isyanın biliyorum

Kim inanır bu sensin

Senin susacagına

Ve kaygısızca bakacağına

Daglar senide bekler

Başkalarını da

Haydi canım

Elimi tut

Elime tutun', 'Ben daglara çıkayımda Sen aglama Canım benim Sevdam Canmı dayanır buna Yürekmi Bırak sevdayı Üstüme bombayı atsınlar Ben parçalanayım Sen su...', ARRAY['Türk Edebiyatı','Şiir','Oktay Avcı']::text[], 8.5, '{"poet":"Oktay Avcı","poet_slug":"oktay-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gozlerim-arkada-kalmayacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Vazgeçilmez Kılan', 'seni-vazgecilmez-kilan-ozcan-gunergok-8aghs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne sineme döktüğün 

Seni kokan saçların, 

Ne bakışlarında kaybolduğum 

Eşsiz gözlerindi 

Seni vazgeçilmez kılan, 

Varlığına sebep 

Sonsuz sevgi, 

Ve sevgiye barınak 

Sıcacık yüreğindi. 

(05.02.1999 İstanbul 01: 10)', 'Ne sineme döktüğün  Seni kokan saçların,  Ne bakışlarında kaybolduğum  Eşsiz gözlerindi  Seni vazgeçilmez kılan,  Varlığına sebep  Sonsuz se...', ARRAY['Türk Edebiyatı','Şiir','Özcan Günergök']::text[], 8.5, '{"poet":"Özcan Günergök","poet_slug":"ozcan-gunergok","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/seni-vazgecilmez-kilan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
