INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Hikayem Var', 'bir-hikayem-var-oguzkan-bolukbasi-ot3ns', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir hikayem var

tam dinlemelik

ağaçta bir keklik

cepte bir teklik

dur dediler dünyaya

dursa

önce ben

sonra sen inecektik

ne dünya duruyor

ne sevda susuyor yürekte

denizsiz bir kayık içindeyim

sensizlik kürekte

hikaye bu ya

yağmur basmış çölleri

almış rüzgar

getirmiş gemileri

korsan gemiler

içinde dünya malı var

ve sen uzaktan göründün

hayal meyal

içim titredi

kıpırdadı suda dalgalar

sen vardın ya

korsan gemilerde olsan bile

sen vardın ya

/dolaşacağım limanları

sıra sıra ben/', 'bir hikayem var tam dinlemelik ağaçta bir keklik cepte bir teklik dur dediler dünyaya dursa önce ben sonra sen inecektik ne dünya duruyor ne...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bir-hikayem-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onbir Milyon Liralık Hayat Hikayesi', 'onbir-milyon-liralik-hayat-hikayesi-gok-tengri-f5c4y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kovaladığı için dellenmiş atları

Çılgın At adını alan Kızılderilinin

Acaba hiç aklına gelir miydi

Okyanuslar ötede adını bile bilmediği bir ülkede

Onbir milyon liraya hayat hikayesinin satılacağını', 'Kovaladığı için dellenmiş atları Çılgın At adını alan Kızılderilinin Acaba hiç aklına gelir miydi Okyanuslar ötede adını bile bilmediği bir ...', ARRAY['Türk Edebiyatı','Şiir','Gök Tengri']::text[], 8.5, '{"poet":"Gök Tengri","poet_slug":"gok-tengri","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/onbir-milyon-liralik-hayat-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
