INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '4''5 dan beş', '4-5-dan-bes-candan-aydogan-sl2k5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne bilirim ben; 

Okumayı yazmayı, 

Edebiyatı kimyayı...

Bir bildiğim seni sevmek., 

Onda da aldığım not dörtbuçuktan beş.', 'Ne bilirim ben;  Okumayı yazmayı,  Edebiyatı kimyayı... Bir bildiğim seni sevmek.,  Onda da aldığım not dörtbuçuktan beş....', ARRAY['Türk Edebiyatı','Şiir','Candan Aydoğan']::text[], 8.5, '{"poet":"Candan Aydoğan","poet_slug":"candan-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/4-5-dan-bes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esitiler Senfonisi', 'esitiler-senfonisi-akin-onen-umy07', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güneşin yeryüzüne diklendiği, 

Çakılların ışığa boğulduğu öğle sıcağında

Meltemle poyrazın, kimi hırçın, kimi sessiz kavgası,

Doğanın sahilde buluşmasıdır.

Buluşmanın bir yanı sevinçtir, 

Bir yanı da, sonraki güne  özlem.

Yeni yaşamlar, yeni sevgiler, yeni düşler için

Kimi meltem kazanır esintiler savaşını, 

Kıyıdan karayı bir serinliğe boğar.

Kimi poyraz,  sürdürür beyliğini, 

Kayaların, taşların sıcaklığını sarar, kavurur, yakar.

Esintilerin gökyüzündeki savaşı birinin egemenliği ile biter. 

Meltemin geceden beri süren özlemi, 

Sıcak  tenleri okşarken bir sevgili gibi, .

Poyraz hırçın  bir duyguyla dokunur tenlere, 

Sahile ulaşıp çakılları bir aştı mı, 

Denizin üzerinden öyle bir akıp gider ki, 

Alıp götürür ne bulursa  önünde, 

Ufuklara,  Akdeniz’in bilinmeyenlerine.

Akdeniz önce ürker bu sertlikten, 

Birden dinginleşir, uslanır, sahilden uzaklaşır.

Oysa meltemi alıp arkasına sahille buluşmaktır özlemi.

Hep  kıyıya doğru atılmak gelir içinden, 

Çarpıp çakıllara uysalca çekilmek sonra geriye, 

Dalgalarıyla sahildeki sıcak çakılları serinletmek, 

Bir başkadır Antalya’da dalgaların çakıllarla aşk senfonisi.

Arada akşam üstleri “Manavgat*”, 

Tatlı sert karışır bu senfoniye.

Gündoğumundan esintiler getiren bir seranattır, 

Ebabil kuşlarının boşlukta kanat çırpışlarıdır, 

Meltem ile poyrazın arasında, 

Gün doğumunun aşkını, gün batımına fısıldar.

Güz oldu mu, ak  bulutlarda eşlik eder bu  senfoniye.

Esintiler arasında, 

Karadan denize, denizden karaya, sürüklenir dururlar.

Önceleri denizden karayadır yolculukları, 

Çizgi çizgidirler kimi zaman, 

Aralarına denizin turkuazını da  alırlar.

Sonra bir toplanır, bir dağılırlar

Birleşir, parçalanır, karada toplanırlar.

Bir ara  iki mavi arasındadırlar, 

Denizle söyleşirken, gökyüzüne göz kırparlar.

Akdeniz senfonisi eşliğinde bir bulut balesidir, 

Gökyüzünde sahnelenen.

Arada Torosların doruklarına takılırlar, 

Yükseklerde  bir süre asılıp kalırlar.

Dorukların yüceliği  onlara da bulaşır, 

Akdeniz’e yukardan bakarlar.

Sonra sıra dağları arkalarında bırakıp, 

Hızla akarlar Antalya’nın üzerine, 

Gökyüzünün  toprağa özlem kokan gözyaşları olup, 

Düşerler poyrazın kuruttuğu toprak üstüne.

Arada davulların sesi duyulur

Yağmur küçük vuruşlarına karışır.

Akdenizden bulutlara, 

Bulutlarla Toroslara 

Doruklardan Antalya’ya ulaşan, 

Bir özlem senfonisidir, 

Dinmeyen  sevgidir, 

Yeniden, yeniden bestelenir.

			Akın Önen 29.07.2000 Antalya

*Manavgat: Gündoğumu esintisinin Antalya’daki adı', 'Güneşin yeryüzüne diklendiği,  Çakılların ışığa boğulduğu öğle sıcağında Meltemle poyrazın, kimi hırçın, kimi sessiz kavgası, Doğanın sahild...', ARRAY['Türk Edebiyatı','Şiir','Akın Önen']::text[], 8.5, '{"poet":"Akın Önen","poet_slug":"akin-onen","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/esitiler-senfonisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taş Nokta', 'tas-nokta-i-hsan-uncuoglu-ykz4z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Unuttum, Unutulsam da ben

Akıla sonsuz gizli açık hayal fikir gelir 

kimi akla takılır kimi durmaz rüya silinir      

Baştan sona yaşanmayan yalan yanlış hikayedir

Taş üstünde kalan izler silinmezse bir tarihtir,', 'Unuttum, Unutulsam da ben Akıla sonsuz gizli açık hayal fikir gelir  kimi akla takılır kimi durmaz rüya silinir       Baştan sona yaşanmayan...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/tas-nokta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çalmaca', 'calmaca-i-hsan-uncuoglu-acsu0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her seven sevdiğine kolay söyler 

Anlar anlamaz alışılmış çalmaca sözler

Kendine iyi bak benzeri gibi eldeymiş sanki

Yaşamayana anladım demek çok kolay 

Konuyu yaşamayan yaşayan gibi anlamaz 

Havaya başını sallar pekde tanımış sayılmaz 

Kelama önem vermeyen bildiğinden hiç şaşmaz,', 'Her seven sevdiğine kolay söyler  Anlar anlamaz alışılmış çalmaca sözler Kendine iyi bak benzeri gibi eldeymiş sanki Yaşamayana anladım deme...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/calmaca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle olmak İsteği*', 'seninle-olmak-i-stegi-bayram-tunca-437w4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bazen sabahlar olmasın isterim

Bazen akşamlar olmasın isterim

Seninle olunca, dopdoludur hislerim

Çünkü, her an seninle olmak isterim

Bazen de sabahın erken olmasını isterim

Bazen de akşamın erken olmasını isterim

Yanımda olmadığında, yine seni düşlerim

Sensiz başka türlü bastırılmaz ki düşlerim

İki gönül bir olunca, samanlık seyran olur

Birlikte olunca da, bu prensip gerçek olur

Ne aş, ne ekmek, ne su gelir benim aklıma

Her şeyi unuturum o gözlerine baktığımda

Ne kadar çok isterdim şu an seninle olmak

Seninle aynı değer ve duyguları paylaşmak

Hayattaki tek istek ve arzum seninle olmak

İsterdim ki toprak misali hep seninle olmak

Ne aş, ne ekmek, ne su gelir benim aklıma

Her zaman ve her yerde sen gelirsin aklıma

Her şeyi unuturdum, o gözlerini baktığımda 

Her daim seni düşünürüm yatıp kalktığımda

23.12.2002-12.23', 'Bazen sabahlar olmasın isterim Bazen akşamlar olmasın isterim Seninle olunca, dopdoludur hislerim Çünkü, her an seninle olmak isterim Bazen ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/seninle-olmak-istegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğumun Yağmuru', 'cocuklugumun-yagmuru-yuksel-unal-olgr3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben bu yağmurları çocukluğumdan bilirim, 

Saatsiz, takvimsiz, 

geç kalması bile olmayan zamanlardı sene 84

Kurşun kalem kokmasa sevmezdim okulu

Siyah önlüğümde beyaz kolalı yaka

Çamurlu yollarda ite-kaka

Önümde bir ömür tekmelerdim

     bir de gazoz kapağı düşe-kalka

Ben bu yağmurları çocukluğumdan bilirim, 

Ne zaman su birikse evmizin yanındaki arsaya

Kağıt gemilerden yapılmış bir yolculuğa çıkardım

bütün okyanusları dolaşırdım

annem çağımasa...', 'Ben bu yağmurları çocukluğumdan bilirim,  Saatsiz, takvimsiz,  geç kalması bile olmayan zamanlardı sene 84 Kurşun kalem kokmasa sevmezdim ok...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Ünal']::text[], 8.5, '{"poet":"Yüksel Ünal","poet_slug":"yuksel-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cocuklugumun-yagmuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Bir Bakış', 'kucuk-bir-bakis-abdulkadir-teker-oqqw1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Küçük bir kıvılcımla başladı herşey

Ne bilirdim ki

Kıvılcımın yangın olacağını

Nerbilirdim ki

Yangının bu kadar büyük olacağını

Yanıyor yüreğim

Cayır cayır yanıyor

Bilinmez bu yangın nasıl büyüyor

İçimdeki bu günah artık acı veriyor 

Kimse bilmez bu kıvılcımın sahibini

Kimse düşünmezki bu garibanın kalbini

Kimse bilmez yangının nasıl biteceğini

Kimse düşünmez bunun kine sebep olabileceğini

Sönmüyor, söndürülemiyor

Hiçbir uğraş fayda etmiyor

Sanki sönmek istemiyor

Kalbimde başladı bu yangın 

Sönmek istemiyor...', 'Küçük bir kıvılcımla başladı herşey Ne bilirdim ki Kıvılcımın yangın olacağını Nerbilirdim ki Yangının bu kadar büyük olacağını Yanıyor yüre...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Teker']::text[], 8.5, '{"poet":"Abdülkadir Teker","poet_slug":"abdulkadir-teker","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kucuk-bir-bakis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek', 'gercek-selale-uygun-2t85s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çok acı çektim çok

Bitmez gibiydi.

Sonu gelmez gibiydi.

Geldi.

Mutluluklarım da oldu.

Sonsuz gibiydi.

İnanılmaz gibiydi.

Gerçekti.

Hayat bu

Acı ve mutluluk 

Bir arada olmaz gibiydi.

Oldu.', 'Çok acı çektim çok Bitmez gibiydi. Sonu gelmez gibiydi. Geldi. Mutluluklarım da oldu. Sonsuz gibiydi. İnanılmaz gibiydi. Gerçekti. Hayat bu ...', ARRAY['Türk Edebiyatı','Şiir','Şelale Uygun']::text[], 8.5, '{"poet":"Şelale Uygun","poet_slug":"selale-uygun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gercek-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Aşk', 'kayip-ask-abdulkadir-teker-e8jqr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne bir şans, ne bir umut veriyor

Kalbim artık unutmak istiyor

Hiç ummuyor onu istemiyor

Dizginlenmiş yüreğim yollarda çürüyor

Bilmeden düştüğüm bu aşk labirentinde

Düşünüyorum hiç sebep var mı diye

Bulamıyorum kendimi bilmiyorum niye

Yıkılmış kalbim labirentin içinde

Dolanıyorum aşksızca 

Tek bir yolum var umuda

Yolumu aydınlatan bir aşk var ama

Yavaş yavaş yürüyorum özgürlüğün kucağına

Fırtına sonrası deniz gibi şimdi kalbim

Sakin ve durgun

En sonunda bitti

Bu uzun ve çileli oyun', 'Ne bir şans, ne bir umut veriyor Kalbim artık unutmak istiyor Hiç ummuyor onu istemiyor Dizginlenmiş yüreğim yollarda çürüyor Bilmeden düştü...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Teker']::text[], 8.5, '{"poet":"Abdülkadir Teker","poet_slug":"abdulkadir-teker","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kayip-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-oropa-seni-dchzl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senden bana ellerin kaldı sade

başkalarının karası, benimse ak ellerin

beyaz, yumuşak pamuk pamuk..tan da

Benden sana gözlerim kaldı sade

''''olmasaydı''''ya bakıp hala dolan gözlerim

kısık, nemli bulut bulut..tan da

Bizden geriye bir düş kaldı sade

olası mucizenin ölesi mutluluğu

aşktan da üstün, ayrılıktan da....', 'Senden bana ellerin kaldı sade başkalarının karası, benimse ak ellerin beyaz, yumuşak pamuk pamuk..tan da Benden sana gözlerim kaldı sade ''''...', ARRAY['Türk Edebiyatı','Şiir','Oropa Seni']::text[], 8.5, '{"poet":"Oropa Seni","poet_slug":"oropa-seni","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dus-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'karşıla beni', 'karsila-beni-engin-namli-p2grv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sabahın seherinde güneşin doğuşuyla 

Kalbinde yanan ışıklarla karşıla beni

Ufukların koynundan usulca ay çıkarken

Akşam kapıda çiçeklerle karşıla beni

Her zaman aynı saatlerde yollarıma bak

Aşk kolyeni gerdanına değil gönlüne tak

Evin önünden ben geçerken lambaları yak

Pencerede gülücüklerle karşıla beni

Gönlümde sevdası hiç kurumayan pınar ol

Yağışı bitmeyen tutku yağmurlarıyla dol

Gümbür gümbür yağ da, ıslansın sana giden yol

Kalbinden çakan şimşeklerle karşıla beni

Herkesin dilinde sanki yer etmiş bu sevda

Aşk ötesinde sonsuz hazla biter bu rüya

Tak duvağı, giy gelinliği geliyorum sana

Parmaklarında yüzüklerle karşıla beni

ENGİN NAMLI      22: 06 09.01.2003', 'Sabahın seherinde güneşin doğuşuyla  Kalbinde yanan ışıklarla karşıla beni Ufukların koynundan usulca ay çıkarken Akşam kapıda çiçeklerle ka...', ARRAY['Türk Edebiyatı','Şiir','Engin Namlı']::text[], 8.5, '{"poet":"Engin Namlı","poet_slug":"engin-namli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/karsila-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül Gelmiş Memleketime', 'eylul-gelmis-memleketime-melih-coskun-0b7ey', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eylül gelmiş memleketime

Darbe vurulmuş sevdalara

Yok edilmiş aşklar

Ezilmiş ayaklar altında insana dair ne varsa

Unutturmuşlar halkıma

Onuru, hürriyeti, eşitliği, insanlığı

Unutturmuşlar koca bir halka aramayı hakkını

Eylüller olmayacak artık ülkemde

Duracağız karşısında dimdik bütün Eylüllerin

İnsanlık adına, hürriyet adına

Daha yaşanası bir dünya adına

Güneş ışığı yerine 

Atmış mumluk bir ampulün 

Titrek ışığına muhtaç kalmasın diye gençliğimiz....

2 Haziran 2002

02: 05', 'Eylül gelmiş memleketime Darbe vurulmuş sevdalara Yok edilmiş aşklar Ezilmiş ayaklar altında insana dair ne varsa Unutturmuşlar halkıma Onur...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/eylul-gelmis-memleketime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gençliğim', 'gencligim-melih-coskun-4v9gi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '80 sonrasının çocuklarındanım ben

Yaşamadım o günlerin acısını

Tamamen özgürüm diyemesem de

Yatmadım hiç zindanda

Hiç dayak yemedim öldüresiye

Sabahlamadım sorgularda

Dayanmadı alnıma bir on dörtlü

Kurşunlanmadım Beyazıt Meydanında

Ama tanıdım hayatımın baharında, 

Ben dünyaya gelirken tükenen çocukları

Hüznünü saldılar  yüreğime o günlerin

Onlar öğretti bana fedakarlığı

Dimdik durmayı ayakta haksızlığa karşı

Onlar öğretti bana  şiir okurken ağlamayı

Ve onlardan kaldı yüreğimdeki derin uçurum duygusu

Her kalleşlikte biraz daha sıktım dişlerimi

Her susuşumda utandım varlığımdan

Sevdim imkansızın peşine düşmeyi

Sevdim yüreğim kan ağlasa da

Yine de yaşamayı

İnadına yaşamayı...

28.06.2002

00.29', '80 sonrasının çocuklarındanım ben Yaşamadım o günlerin acısını Tamamen özgürüm diyemesem de Yatmadım hiç zindanda Hiç dayak yemedim öldüresi...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gencligim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz', 'biz-i-smail-korkmaz-ts47x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biz! 

Seninle ikimiz 

Birde gece 

Söylenmemiş türkülerin bestecisiyiz. 

Unutulmuş romanlarda, 

İstanbul''un dar bir sokağında 

Yankılanır seslerimiz. 

Öptüğümde seni 

Yanan ateş küllenirdi. 

Silkinirdi gürgenler, meşeler, çamlar 

Balıklıova Şelalesi bir başka gürlerdi. 

Sen benim anlatılmaz duygularım 

Çocuksu yanımdın. 

Senin için bütün çılgınlıkları yapmaya 

Sürüklüyordu yüreğim beni. 

Biz 

Seninle ikimiz 

Canikler''in koynunda 

Sevda şerbetine bulandık. 

Seni güldürebilmek 

Hayatı senin gülen gözlerinden görmek 

Seni seviyorum diyebilmek 

Yetiyordu bu dünyanın cennet olmasına. 

Zamanı durduramadık. 

Lale Sokak''da 

Aç kediler dolaşıyordu. 

Perden hiç kıpırdamıyordu. 

Bulutsuz soğuk bir gecede 

Sarhoş olmak istiyordu canım. 

15 Aralık 2002-Münih', 'Biz!  Seninle ikimiz  Birde gece  Söylenmemiş türkülerin bestecisiyiz.  Unutulmuş romanlarda,  İstanbul''un dar bir sokağında  Yankılanır ses...', ARRAY['Türk Edebiyatı','Şiir','İsmail Korkmaz']::text[], 8.5, '{"poet":"İsmail Korkmaz","poet_slug":"i-smail-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/biz-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gri', 'gri-yusuf-kaya-kkkvs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tozdan ve kirden önce

Güzellikler vardı bu şehirde

O zamanlar ıslık çalardım yollarda yürürken

Geceleri, yıldızları sayardım

Bir efkarlı türkü dolardım dilime

Gözlerimde, gözlerinin hayali

Ufuklara dolardım

Tüm şehirde sokak sokak

Seni arardım

Gri bir gölge gibi uzaktan

Ellerimi açar sana koşardım

Gece gözlerimde tüllenirken

Bedenin bir ruh gibi

Kayıverdi kollarımdan

Yine bir gri gölge kalırdın uzakta

Ağlardım

Sarı saçların geceme hiç ışık katmadı

Ve bir çift zümrüt yeşili göz

Rüyalarıma hiç girmedi.

Aramızda, 

Neden görünmez duvarlar vardı, 

Ve neden gece hep seni

Gri’ye boyardı.

Bir bakışına hasretti gözlerim

Ve kulaklarım bir gülüşünü duyma azminde

Bir gri gölge idin

Gülmedin

Ve hiç görmedim gözlerini 

Sana, doyasıya bakamadım

Koştum durdum peşin sıra 

Sana bir kez olsun ulaşamadım

Bir Gri gölge idin kaçtın 

Bir ruh gibi

Pembeden hayallerimde dolaştın.

Sen yeşilden ve sarıdan öte

Gri renkli sevgilim; 

Yine sislerin ardından gül bana

Efsunluca, 

Ve ta ötelerden sev beni

Dokunma, gülme istersen 

Ne olur ağlama, 

İnan ben ağlıyorum.

Seni düşünerek

Geceleri, sabahlara bağlıyorum.

Gözlerine bakamazsam da

Görüyorum seni

Ve şarkılar söylemesen de sen

Ben dinliyorum.

Gecenin al yalazında, yapayalnız üşüyorum

Sığındığım tek bir şey var 

Seni Seviyorum!', 'Tozdan ve kirden önce Güzellikler vardı bu şehirde O zamanlar ıslık çalardım yollarda yürürken Geceleri, yıldızları sayardım Bir efkarlı tür...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Kaya']::text[], 8.5, '{"poet":"Yusuf Kaya","poet_slug":"yusuf-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/gri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PARKE TAŞLARI', 'parke-taslari-ahmet-kurt-hpznf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sokaklar sahipsiz yolumu gözler.

Korkuyor silinir yaşayan izler.

Günün her doğuşu bir başka elem, 

Bir başka ahenkte durgun denizler.

Vuslatsız sevda sonu gibidir, 

Aşina olduğum solgun benizler.

Gönül alev alev yanar da sessiz, 

O büyüyü bozmaya mecalsiz dizler.

Her gün dayak yiyen parke taşları

Kim bilir kaç aşığın yolunu gözler.', 'Sokaklar sahipsiz yolumu gözler. Korkuyor silinir yaşayan izler. Günün her doğuşu bir başka elem,  Bir başka ahenkte durgun denizler. Vuslat...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/parke-taslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haykırış', 'haykiris-sair-i-lkay-flkfk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dalgalara yenik düşmüş

Bir gemi gibiyim

Tamamen batmadım ama

Kendimi kurtarabilme ümidim

Mucizelere kalmış

Son bir nefes alıyorum

Herkese veda edercesine

Ve tükeninceye kadar bağırıyorum

''Seni Seviyorum'' diye...', 'Dalgalara yenik düşmüş Bir gemi gibiyim Tamamen batmadım ama Kendimi kurtarabilme ümidim Mucizelere kalmış Son bir nefes alıyorum Herkese ve...', ARRAY['Türk Edebiyatı','Şiir','Şair İlkay']::text[], 8.5, '{"poet":"Şair İlkay","poet_slug":"sair-i-lkay","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/haykiris-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitanem', 'bitanem-gunes-kara-iak15', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aniden birgün çıktınya karşıma

İşte o gündenberi deli gibi

Kalbim adını sayıklarken

Sevdim seni BİTANEM

Sen kalbimin hızlı atışı 

Gözümdeki parıltıydın ya

Ben sana sırılsıklam

Aşık olmuştum  BİTANEM

Birgece kayboldunya 

Karanlığın siyahında

Sıcak nefesini düşledim, 

Çok özledim BİTANEM

Sen gideli hergece 

Yatmadım ya bakmadan resmine

Hep bekledim, 

Konuşup bir kelime diyesin diye BİTANEM

Kan kırmızı bu gecelerde, 

Öptüm ya resmini doyasıya

Yükledim sensizliği beynime, 

Bedenime BİTANEM

Özleminle sensiz gecelerde, 

Hep ağladımya

Yüreğimden vurdun beni, 

Yıktın BİTANEM', 'Aniden birgün çıktınya karşıma İşte o gündenberi deli gibi Kalbim adını sayıklarken Sevdim seni BİTANEM Sen kalbimin hızlı atışı  Gözümdeki ...', ARRAY['Türk Edebiyatı','Şiir','Güneş Kara']::text[], 8.5, '{"poet":"Güneş Kara","poet_slug":"gunes-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bitanem-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçtim', 'vazgectim-i-smail-doruk-kpdyn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'can gibi gidecekti bu mektup sana

yüzünü çizdim üç ayrı sayfaya

en güzeli benimle olanıydı suretinin

kaç gece geçirdim gözlerinde

beyaz bir kağıda düştüm seni

bitmeden sarardı yapraklar

sonsuz gibiydin sözcüklerde

gerçeğe dönüşme hep böyle kal', 'can gibi gidecekti bu mektup sana yüzünü çizdim üç ayrı sayfaya en güzeli benimle olanıydı suretinin kaç gece geçirdim gözlerinde beyaz bir ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Doruk']::text[], 8.5, '{"poet":"İsmail Doruk","poet_slug":"i-smail-doruk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/vazgectim-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çünkü', 'cunku-i-smail-korkmaz-koi4y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben sende çok şey bulmustum 

Çocukluğumun ve ilk gençliğimin 

Yitip giden hesapsız günlerini 

Sınırsızlığı, kuralsızlığı bulmuştum sende 

Hayrandım sana, imreniyordum 

Çünkü sen 

Yaşamak istediğim yitik günleri 

Yaşıyordun özgürce 

Ben büyümek istemiyordum 

Sen küçük olduğunu kabul etmiyordun 

Zamanı öylece durdurmak istiyorduk ikimizde. 

26 Ocak 1998-Niksar', 'Ben sende çok şey bulmustum  Çocukluğumun ve ilk gençliğimin  Yitip giden hesapsız günlerini  Sınırsızlığı, kuralsızlığı bulmuştum sende  Ha...', ARRAY['Türk Edebiyatı','Şiir','İsmail Korkmaz']::text[], 8.5, '{"poet":"İsmail Korkmaz","poet_slug":"i-smail-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cunku-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım...', 'canim-ruya-deniz-demir-p0x88', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gel otur şöyle yanıma

Hoşgeldin...

Yine gözlerinin içi gülüyor

Otur anlat çok sevinçlisin

Mutlusun belli...

Kapatayım mı pencereleri

Üşümüşsündür belki

Tut ellerimi

Üşümüştür ellerin

Yüreğin üşümüştür belki...

Isıtsın ellerim ellerini

Sıcaktır ellerim

Öyle söyler dostlarım

Sana şarkı da söylerim belki

Güzeldir sesim

Gözlerim gibi...

Bir tek sana bakarken gülüyor içi gözlerimin

Bir seni dinlerken titriyor yüreğim

Annemden sonra hiç titremedi belki...

Tut yüreğimi

Al avuçlarına, senin için atıyor

Sana birşey söylemek ister belki...

Dinle onu; 

Güzel gözlünün

Gözlerine bakarak dinle madem seviyorsun

Doya doya, bağıra bağıra; 

Seni Seviyorum der belki! ! !', 'Gel otur şöyle yanıma Hoşgeldin... Yine gözlerinin içi gülüyor Otur anlat çok sevinçlisin Mutlusun belli... Kapatayım mı pencereleri Üşümüşs...', ARRAY['Türk Edebiyatı','Şiir','Rüya Deniz Demir']::text[], 8.5, '{"poet":"Rüya Deniz Demir","poet_slug":"ruya-deniz-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/canim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin Yalanci Figuranligi', 'sevginin-yalanci-figuranligi-turabi-gultekin-mhuo4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ah ah sevdiğim

senden son bir şans istemiştim

hayal kırıklığım 

hiç sans tanımayacak kadar bencil olmandı

bu senin kendine olan düşmanlığın

esaretin, kurtulamamışlığın

inan ki ben öldürmedim

senin açlığın

doyuramadığın

ama ufak bir zerrede kustugundu

kaçmak çözüm olsaydı

aşk olmazdı, direnç olmazdı

sen olmazdın

şayet çözüm olsaydı..

kayıp siğaraların korkak aydınlığı gibi olmazdın

kurtulduğunu sanma

bitmiş olsada yüreginin haylazlığı

gözlerin yine firari

en ufak ışık hüzmesinde

karanlığı avucuna öksürerek

içine kaçmak isteyeceksin

biliyorum benden konusuyor o turku

kapatsanda sesini

beyininde kemirecek seni

zaman zalim olur 

zaman anarşist

gunler gine tutup getirecek seni

dışımızda en küstah yanlışlıklar

içimizde ise bambaşka türlü bir ayıp

ıslıksız dudaklarda çıkan

sesler bir parça dumanlı

acı bir tütün gibi yakacak genzimizi

gülümsemeler açık bir yara gibi

kanamalı, acı ve utandırıcı olacak

dehşetini birden kaybedecek gelişin

esaretin duygusunda güneş olmak isteyeceksin

oysa ki zehirini sağıyor olacaksın gecenin

gercek sandıgın bir cok sey

degerinden eksige bozulmus oldugunu goreceksin

en uzak içlerimize bir rüzgar dagılacak

günlerin önemi kalmayacak

gün ortasında akşam olacak

sonra....

hoş geldin diyecegim

hoş bulduk diyeceksin

tıpkı iki yabancı insan gibi..........', 'ah ah sevdiğim senden son bir şans istemiştim hayal kırıklığım  hiç sans tanımayacak kadar bencil olmandı bu senin kendine olan düşmanlığın ...', ARRAY['Türk Edebiyatı','Şiir','Turabi Gültekin']::text[], 8.5, '{"poet":"Turabi Gültekin","poet_slug":"turabi-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/sevginin-yalanci-figuranligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarıl Bana - Lila''ya Mektuplar I', 'saril-bana-lila-ya-mektuplar-i-mehmet-akif-ardic-wx7s0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir rüzgâr anımsatır kokusunu, 

bir rüzgâr; 

ellerime Lila''nın nefesi değer. 

hissizce seyreder yok oluşumu; 

Lila, o soğuk kayalara benzer... 

bûsesi kanar soğuk ışıkla, 

saflığı bir kız çocuğunun yüreğinde esmer.. 

ne olur pencereni aç Lila! 

bakarsın kanatsız bir martı, 

o bembeyaz yatağına düşer. 

yahut ataletli bir yürek atışı; 

gözlerini gözlerimden kaçırıp korkuyla, 

bu mumdan bebek, 

bu camdan patikler, 

ellerin gibi kırılgan bu çini vazo... 

hissizliğin gözlerine incecik 

damla damla düştüğü vakitler... 

dudaklarını Lila, dudaklarım ısıtacak. 

mürekkeple yazdığını, 

kalbim bûsenle unutacak.. 

sarı odalarda bu dar adımlar Lila, 

ve siyah korkular; 

yüreğinde, tüm çığlıklarıyla... 

örtün Lila, pencerenden bahâr giriyor.. 

sevdâya karşı, 

yüreğin bitiyor, bitiyor... 

Lila, yüreğin rehin korkulara. 

umutlar da bir köşede can veriyor.

hayır, pencereni açma! 

hayır, lambaları yakma! 

anlamıyorsan yüreğimi, 

boşver, kalsın, anlama! 

bu limanda kağıttan kayıklar 

ve suya batan ellerin Lila, 

kağıttan kayıklar, yüzmez sularda.. 

örtün Lila, odan gittikça aydınlanıyor.. 

yüreğinde kargaşa artıyor, artıyor... 

kayıklar batacak Lila, 

bak, bu deniz''in sesi: 

''atla, atla, atla...'' 

deniz''in senden başka 

yok hiç kimsesi; 

anla, anla, anla... 

kabukların var ya Lila, 

sığınağını göğsünde taşıyısın var ya.. 

gezişin sevdâyı parmak uçlarınla.. 

içimdeki sessiz bu öfke, 

öpmezsem beni yakacak.. 

sen korkuyla ufuklara bakarken.. 

gözlerin, kahverengi bir tül gibi uzanırken boşluğa, 

son kez çaresizce yalvararak 

teslim olacağım aşk celladına.. 

seninse dudaklarında o aynı kelime: 

''seviyorum; ama, ama, ama...'' 

anlatsam mı? 

hiç konuşmasam mı? 

sussam mı? 

ya da dudaklarını öpmesem? 

yaşamak bir cehennemse koynunda 

Lila, yanmak...

küllerime savurdun be boşluğa, 

sevdim sanarak! ! ! 

Lila, ağlasam mı? 

mehtâba küskün bu sarı yüz, 

en keskin bıçakların kanattığı.. 

hani sevdâdan çarpılma. 

bir ölünün kalbinden alıntı 

mehtâba küskün bu sarı yüz.. 

affet! ... 

bu incecik gönül taşımıyor sevdâyı.. 

kurşun, köpüğe işlemiyor. 

dokunma ne olur yaralarıma! 

merhem olma acılarıma! 

ne ben boynu bükük bir dervişim, 

ne dudakların dudaklarıma bir sadaka... 

... 

hayır, Lila, anlama beni; 

ve boşver, anlamaya da çalışma! 

hayır, söndür tüm ışıkları, 

Lila, sakın lambaları yakma! 

umarsız, çaresiz.. 

yastığına gizlediğin sırlar gibi sessiz... 

haydi bana haykır şimdi, 

yastığının yastık olmadığını.. 

siyahın hiç siyah olmadığını.. 

sevdânın günâh olmadığını.. 

haydi bana şimdi haykır; 

seni hiç anlayamadığımı... 

haydi bana sarıl şimdi! 

ne olur asıl şimdi! 

gönlümüz, gönlümüze esir şimdi.. 

birbirimizden uzak hergün asır şimdi.. 

sevdâ başucumuzda dolaşır şimdi.. 

seni seviyorum de bana, 

al koynuna asıl şimdi! 

yüreğimdeki hüzün dağlara bedel; 

gözümden yaşları sil şimdi! 

gönlüm, ben hiç sevmem derken, 

bir ceylan bakışlıya esir şimdi! 

bir çiğ tanesi gibi her sabah erken, 

bas beni bağrına, kalbim senindir şimdi! 

seni seviyorum de bana, 

öp dudaklarımı asıl şimdi! ... 

...... 

yıldızlar da bitiyor... 

ay, dökülüyor parmakuçlarıma.. 

ay, bir sahra çölüne düşüyor; 

ay, İstanbul''a... 

uzaklardan bir at sesi geliyor. 

sevdânın ölümcül yamaçlarında, 

kalbim eriyor, eriyor.. 

Lila, kalbime birşeyler oluyor! 

rûhum delice şeyler istiyor! 

aklım imkansızı istiyor! 

günâh dolu beyazı istiyor! 

Lila, kalbime birşeyler oluyor... 

mâsûm ve utangaç... 

küçük bir kızın sevdâ oyunu. 

o sevilmeye muhtaç; 

bense sevmeye onu... 

ahhh Lila.. gönlümün maralı! .. 

ve ceylan bakışlım.. 

ve dostum, yârânım, yârım 

benim kalbi yaralı; 

gazalım, sebeb-i varım. 

mâsûm ve utangaç... 

bilse o zalım, bilse o zalım.. 

ne rujlu bir dudak; 

ne de boyalı saç.. 

güzellik hep Lila''nın.. 

mâsûm ve utangaç... 

bir gül dalı mı yoksa selvi mi; 

yahut çöle düşen bir yağmur mu adın? 

Leyla mı, Aslı mı, Zühre mi, Şirin mi? 

Züleyhâ''sı mı Yusuf''un, 

Sara''sı mı Musa''nın? 

yoksa bir sevdâ seli mi; 

gökyüzünü boyadığın? 

gecelerin kızı, ey mâh-ı didârım.. 

bir efsürde-dil.. 

can yakan gönül.. 

afet-i devran! 

ey katre-i aşk.. 

ey bunalan gökyüzü.. 

ey siyah perçemli cihân! 

ey günaha çağıran masum, 

ey can veren ölüm, 

ey hüsn ve iffet, 

ey sevda hırsızı, 

ey yaşam pınarı, 

ey gecenin matemi, 

sevda bakışlım, 

derdim, sevincim, hüznüm.. 

sebeb eyyyyy! ... 

bir sükut ki anla bin âh''a bedel.. 

bir sevdâ ki, 

hiç karşılıksız, umarsız.. 

değişmem hiç birşeye gülümsemeni; 

ne olur gel, gel! .. 

bakarsın bulamazsın gün gelir beni; 

bu çiçek de karlara düşer.. 

gün gelir sevdiğinin bedeni, 

ıssız bir mezara düşer.. 

yarın belki de geçtir ne olur şimdi! .. 

sarıl bana ne olur asıl şimdi! ..

2003', 'bir rüzgâr anımsatır kokusunu,  bir rüzgâr;  ellerime Lila''nın nefesi değer.  hissizce seyreder yok oluşumu;  Lila, o soğuk kayalara benzer....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Ardıç']::text[], 8.5, '{"poet":"Mehmet Akif Ardıç","poet_slug":"mehmet-akif-ardic","theme":"Türk Şiiri","is_hero":false,"total_lines":166,"source_url":"https://www.antoloji.com/saril-bana-lila-ya-mektuplar-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Davet', 'davet-i-smail-korkmaz-fojbt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Koş sevinci paylaşmaya 

Birlikte ağlamaya 

Sev insani 

Ve tüm doğayi 

Korkuyu yen 

Yarinlar için 

Gülmeyi öğren 

9 Ağustos 1994-Niksar', 'Koş sevinci paylaşmaya  Birlikte ağlamaya  Sev insani  Ve tüm doğayi  Korkuyu yen  Yarinlar için  Gülmeyi öğren  9 Ağustos 1994-Niksar...', ARRAY['Türk Edebiyatı','Şiir','İsmail Korkmaz']::text[], 8.5, '{"poet":"İsmail Korkmaz","poet_slug":"i-smail-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/davet-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağladım', 'agladim-seval-kemertas-97duy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gecelerin şalına sakladım 

alacakaranlığını son akşamların 

herşey usul usul bitti 

ne sen kaldın ne de ben 

bütün renkler bir bir silindi 

''gidiyorum elveda'' 

hep aynı sözler kulağımda 

lanetler yağdırdım... 

zamansız ayrılıklara 

ama hiç birşey yapamadım 

ben sadece düşündüm... 

ağladım... 

ne kadar inanılmaz geldi önceleri 

sonra; acı vurdu kalbimi 

en derin yerinden 

bir kez daha yıkıldım 

lanetler yağdırdım.. 

zamansız ayrılıklara.. 

ama hiç birşey yapamadım. 

ben sadece düşündüm 

ağladım.', 'gecelerin şalına sakladım  alacakaranlığını son akşamların  herşey usul usul bitti  ne sen kaldın ne de ben  bütün renkler bir bir silindi  ...', ARRAY['Türk Edebiyatı','Şiir','Seval Kemertaş']::text[], 8.5, '{"poet":"Seval Kemertaş","poet_slug":"seval-kemertas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/agladim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler Ağlar', 'geceler-aglar-seval-kemertas-vzfkf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güneş hep böyle mi batar 

Öperek maviyi dudaklarından 

Sonra hüzünlü bir akşam 

Kapkara bir gece başlar 

Ağlar akşamlar ağlar 

Denizin karanlığında 

Ağlar yakamozlar ağlar 

Martıların çığlığında 

Ay hep böyle mi doğar 

Öperek geceyi dudaklarından 

Sonra hüzünlü bir şarkı; 

Rüzgarın ıslığıyla başlar 

Ağlar geceler ağlar 

Yıldızların arasında 

Ağlar gökyüzü ağlar 

Her yağmur damlasında

30.08.2001', 'Güneş hep böyle mi batar  Öperek maviyi dudaklarından  Sonra hüzünlü bir akşam  Kapkara bir gece başlar  Ağlar akşamlar ağlar  Denizin karan...', ARRAY['Türk Edebiyatı','Şiir','Seval Kemertaş']::text[], 8.5, '{"poet":"Seval Kemertaş","poet_slug":"seval-kemertas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/geceler-aglar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söylenmeyen-1', 'soylenmeyen-1-seval-kemertas-p78s5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gitme... kal.. 

İki kelime aslında 

Sanki bir çırpıda söylenivercek gibi 

Ama; söylemek zor gelir kimi zaman 

Bilmediğin bir dili konuşur gibi 

Söyleyemezsin,

Dilin tutulur 

Sanki dudaklarına kilit vurulur 

Söyleyemezsin,

İçin yırtılır 

Bir hatıra defterinin; 

Artık istenmeyen sayfası gibi... 

Yırtılır, acıyarak... 

O çok sevdiğin giderken; 

Gitme kal diyemezsin susarsın.. 

Şaşkın, çaresiz...bakarsın ardından 

Korkarsın pişman olacağından 

Oysa pişmalığın en büyüğü 

Asıl o gittikten sonra başlar.. 

Söyleyemediğin sözlerle yıkılır dünyan 

İki kelimeyle kayar mutluluk avuçlarından 

Ve o gider...

Şimdi yalnızlıktır seni saran... 

19/09/2002', 'Gitme... kal..  İki kelime aslında  Sanki bir çırpıda söylenivercek gibi  Ama; söylemek zor gelir kimi zaman  Bilmediğin bir dili konuşur gi...', ARRAY['Türk Edebiyatı','Şiir','Seval Kemertaş']::text[], 8.5, '{"poet":"Seval Kemertaş","poet_slug":"seval-kemertas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/soylenmeyen-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söylenmeyen-2', 'soylenmeyen-2-seval-kemertas-kjqtg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sorma bende bilmiyorum 

Hangi fırtınayla savruldum 

Hangi sevda vurdu gurbet yollarına 

Kırgınlıkmı, kaçışmı 

Hangi duygularla geldim buralara 

Söylenmeyen sözler mi savurdu, 

Gurur mu attı uzak diyarlara 

Bende bilmiyorum... 

Gurbet neresindedir hayatın 

Gittiğin yerdemidir yoksa; 

Yüreğini bıraktığın yerdemidir uzaklıklar... 

Sorma bilmiyorum... 

Kalbime batan hasretinmidir yoksa; 

Kendim miyim bıraktığım senin yanında... 

Bildiğim bir şey var... 

Gurbet canını acıtıyor daha ilk anda 

Sanki dünya başına yıkılmış; 

Sen kalmışsın gibi altında

Korkuyorsun...

Yabancı bir kentin

Seni tanımayan ıssız sokaklarında 

Adressiz, telefonsuz kaybolmuşcasına 

Gurbet canını yakıyor daha ilk anda.. 

Hele yüreğin geldiğin yerde kalmışsa... 

24/09/2002', 'Sorma bende bilmiyorum  Hangi fırtınayla savruldum  Hangi sevda vurdu gurbet yollarına  Kırgınlıkmı, kaçışmı  Hangi duygularla geldim burala...', ARRAY['Türk Edebiyatı','Şiir','Seval Kemertaş']::text[], 8.5, '{"poet":"Seval Kemertaş","poet_slug":"seval-kemertas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/soylenmeyen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Öyle', 'i-ste-oyle-seval-kemertas-9w9qn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gemi... 

Hoyratça yararak denizin bağrını 

nasıl ilerliyorsa yolunda; 

Yokluğunda... 

Öyle ilerleliyor yüreğimde 

Dalgalar... 

Acımasızca nasıl vuruyorsa 

geminin bordasına; 

Hasretinde... 

Öyle vuruyor, 

Acıtıyor yüreğimi...

03.06.2001 

Karşıyaka vapuru 19.50', 'Bir gemi...  Hoyratça yararak denizin bağrını  nasıl ilerliyorsa yolunda;  Yokluğunda...  Öyle ilerleliyor yüreğimde  Dalgalar...  Acımasızc...', ARRAY['Türk Edebiyatı','Şiir','Seval Kemertaş']::text[], 8.5, '{"poet":"Seval Kemertaş","poet_slug":"seval-kemertas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/iste-oyle-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yap-Boz', 'yap-boz-ahmet-gumustekin-a460m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düşüncelerime sakladım, 

Adım adım arıyorum seni.

Bir yapbozun parçaları gibi, 

Dağınıksın düşüncelerimde.

Parçaları birleştirip 

Seni oluşturmaya çalışıyorum.', 'Düşüncelerime sakladım,  Adım adım arıyorum seni. Bir yapbozun parçaları gibi,  Dağınıksın düşüncelerimde. Parçaları birleştirip  Seni oluşt...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Gümüştekin']::text[], 8.5, '{"poet":"Ahmet Gümüştekin","poet_slug":"ahmet-gumustekin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yap-boz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fark', 'fark-ahmet-gumustekin-wkle6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Farklı olmak isterken, 

Bilemedim! 

Diğer insanlardan

farkım kalmadığını.

Bilmeliydim! 

Esas farklılığın, 

kendim olmamı

gerektirdiğini.', 'Farklı olmak isterken,  Bilemedim!  Diğer insanlardan farkım kalmadığını. Bilmeliydim!  Esas farklılığın,  kendim olmamı gerektirdiğini....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Gümüştekin']::text[], 8.5, '{"poet":"Ahmet Gümüştekin","poet_slug":"ahmet-gumustekin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/fark-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adem Oğlu', 'adem-oglu-ahmet-gumustekin-r3uub', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben bir garip Adem Oğlu''yum.

Ne çok doluyum, 

Ne çok boş.

Ne ilerideyim, 

Ne geride.

Bu kocaman alemde, 

Ortalarda bir yerde, 

Ufacık bir toz zerreciğiyim.', 'Ben bir garip Adem Oğlu''yum. Ne çok doluyum,  Ne çok boş. Ne ilerideyim,  Ne geride. Bu kocaman alemde,  Ortalarda bir yerde,  Ufacık bir to...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Gümüştekin']::text[], 8.5, '{"poet":"Ahmet Gümüştekin","poet_slug":"ahmet-gumustekin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/adem-oglu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakın Ama Uzak', 'yakin-ama-uzak-ahmet-gumustekin-1lcjg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Varlığına doyamamak, 

Yokluğunu hissedememek.

Bir olmak yada olamamak.

Yakın ama uzak olmak.

Çelişkili gibi fakat gerçek! 

Sevmeye çalışmak

Fakat bilinmeyeni, 

Görünmeyeni.', 'Varlığına doyamamak,  Yokluğunu hissedememek. Bir olmak yada olamamak. Yakın ama uzak olmak. Çelişkili gibi fakat gerçek!  Sevmeye çalışmak ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Gümüştekin']::text[], 8.5, '{"poet":"Ahmet Gümüştekin","poet_slug":"ahmet-gumustekin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yakin-ama-uzak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hastalığımsın', 'hastaligimsin-ahmet-gumustekin-o6qdn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yavaş yavaş 

Damarlarımdan vücuduma 

Nüfuz ediyorsun.

Önce kalbimi, 

Daha sonra beynimi

Kaplıyor

Kısa bir zaman sonrada 

Tüm benliğimi sarıyorsun.

Artık yalnızca seninim

Ve seni hissediyorum.

Bütün bağışıklık sistemimi 

Etkisiz hale getiriyorsun.

Sana karşı savunmasız 

Ve dirençsizleşiyorum.

Artık sana aşık olabilir, 

Seni sevebilirim.', 'Yavaş yavaş  Damarlarımdan vücuduma  Nüfuz ediyorsun. Önce kalbimi,  Daha sonra beynimi Kaplıyor Kısa bir zaman sonrada  Tüm benliğimi sarıy...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Gümüştekin']::text[], 8.5, '{"poet":"Ahmet Gümüştekin","poet_slug":"ahmet-gumustekin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hastaligimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükenen', 'tukenen-elif-kerenciler-zoah5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'vakitler ucuzlamış gibi

insan denen neydi ki

acizliğe yenilmeyen

güçlüyüm diye direnen

karşımda

ve solarken içimde bir çiçek daha

dökülecek yaprağım kalmadı...

19 Ocak 2003

17: 59

Pazar

BİGA', 'vakitler ucuzlamış gibi insan denen neydi ki acizliğe yenilmeyen güçlüyüm diye direnen karşımda ve solarken içimde bir çiçek daha dökülecek ...', ARRAY['Türk Edebiyatı','Şiir','Elif Kerenciler']::text[], 8.5, '{"poet":"Elif Kerenciler","poet_slug":"elif-kerenciler","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tukenen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-dara-jine-tz95h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her seni yazmak istediğimde 

Kaç kağıt buruşturdum

Bendeki senin kelimlerden ayrıklığını

Her zaman hiç seni yazamadıklarımı 

BİLİYORMUSUN

Her seni anlatmak istediğimde

Ne kadar kekemeleştiğimi

''O'' diyip sustuğumu

Hep sonra ''O''''nu seviyorum dediğimi

BİLİYORMUSUN', 'Her seni yazmak istediğimde  Kaç kağıt buruşturdum Bendeki senin kelimlerden ayrıklığını Her zaman hiç seni yazamadıklarımı  BİLİYORMUSUN He...', ARRAY['Türk Edebiyatı','Şiir','Dara Jine']::text[], 8.5, '{"poet":"Dara Jine","poet_slug":"dara-jine","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-210-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapılar Ardında', 'kapilar-ardinda-umut-ulbegi-346u1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Rüzgarla gelen sendin

kapıyı çaldın küçük ellerinle

yavaş yavaş

Hemen içeriye aldım seni

Üşümüştün

susamıştın

yüzünde sonsuz gizemler taşıyordun

soğuktan titreyen dudakların açılıp kapandıkça

içim gidiyordu

Gözümün önünde hıçkıra hıçkıra ağladın

Damlalar ellerimdeydi

dudakların dudaklarımda

Anlamıştım seni

Aynadaki aksim gibiydin

Gerçek sevgiye, aynada göreceğin mutlu yüze muhtaçtın

Rüzgarla gelen sendin

Gökyüzü masmaviydi

Bilinmeyen özleminin rüzgarları uçurmuştu bacaklarını kapıma dek

Seni saracak bir vücut

üstünde ağlayabileceğin bir omuz

gerçek bir sevgiliydi özlemin

Bu yüzden üşüyordun

Sana sımsıkı sarıldım

Daha sıkı

Tüm vücudunu hissettiğim an bıraktım seni

gecenin karanlığında sonsuzluğa yuvarlandık

Sen ve ben

yapayalnız

herkesle

Gökyüzünde iki ay vardı bizim için

on yıldız

tören vardı bulutlarda

Açıldı tüm kapılar

Kapılar dalgakıran, rüzgarkesen

Kapılar ardında sen, ben

Sen ve ben

Aşk ve gece

Ben ve sen

Sevişmeler rüzgarkesen

10.05.1997', 'Rüzgarla gelen sendin kapıyı çaldın küçük ellerinle yavaş yavaş Hemen içeriye aldım seni Üşümüştün susamıştın yüzünde sonsuz gizemler taşıyo...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/kapilar-ardinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşayabilme Yetisi', 'yasayabilme-yetisi-altug-can-aldanmaz-qpekm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '...............................................................-Teşekkürler Hazel Angel-

Ne kadar zorsa vazgeçmeyi başarmak bir anda 

İşte o kadar kolay vazgeçtiğine inandırmak

Ne kadar zorsa avutmak yüreğini kanadığında

İşte o kadar kolay kaybolmak avuntunun doğasında

Kaybolmak zor gibi görünse de kimi zaman insana

Bazen olabildiğince lüzumlu, bazen öylesine saçma

Aslında suyunda var hayatın canına  kattığımız

Aslında kayboluşun ta kendisi, yıllarca avunmak sandığımız

Ve kimi zaman da olabildiğince kolaydır kaybolmak

Göz yapımı, kaf misali dağlar dizersiniz hayatla aranıza

Belki inanırsınız artık, kalmadığına aranızda hiçbir bağın

Belki de kalırsınız altında, bu göz yapımı, ecel misali dağın

Ne kadar desek de zincirdir dünyaya bağlandığımız

İşte böylesine pamuk ipliğinin ucunda tüm hayatımız

Biz insanlar yarın olacağı bilmeden, fütursuzca yaşarız

Ve biz korkaklar, ömür boyu neden bilmem, yaşıyor numarası yaparız

Hayır ölüm değildir adı korktuğumuz sahnenin

O kadar kolay ki ölebilmek bir anda

Asıl ürküten beni, sonunda bu perdenin

Avunamamak, o göz yapımı dağın, ak toprağında...', '...............................................................-Teşekkürler Hazel Angel- Ne kadar zorsa vazgeçmeyi başarmak bir anda  İşte o...', ARRAY['Türk Edebiyatı','Şiir','Altuğ Can Aldanmaz']::text[], 8.5, '{"poet":"Altuğ Can Aldanmaz","poet_slug":"altug-can-aldanmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yasayabilme-yetisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-umut-ulbegi-p4icd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güneşin doğuşunu seyretmeyi seviyorum

İlk ışıklarla ve dünyanın parlak renkleriyle tanışmayı

Aklıma sen geldiğinde 

sevgimi güneşle paylaşmayı

ona seni anlatmayı seviyorum

Gün batımlarını seviyorum

Mor dağlar ardında kaybolan

kuşları yanında götüren karanlığı

Dünyanın sonunu hatırlatan kızıllığı

Dudaklarında ölümü anımsatan kızıllığı

Dudaklarında her akşam yeniden ölmeyi seviyorum

Yıldızları seviyorum

ve dolunayı

geceleri yıldızlara dokunmaya çalışan soğuk rüzgarların

seni fısıldamasını

saçlarım gözlerimi örttüğünde bile şu en parlak yıldızda

seni görmeyi

sesini özlediğim ve sana ulaşamayacağım zamanlarda

tüm gücümle ismini gökyüzüne haykırmayı seviyorum

Seviyorum

her geçen gün seni bana yaklaştıran gökyüzünü 

Seni seviyorum

11.06.1997', 'Güneşin doğuşunu seyretmeyi seviyorum İlk ışıklarla ve dünyanın parlak renkleriyle tanışmayı Aklıma sen geldiğinde  sevgimi güneşle paylaşma...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/seni-seviyorum-110-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimsesiz Karanlıklar', 'kimsesiz-karanliklar-umut-ulbegi-7lz4i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Neden bu kadar karanlığım

ve neden uçuyorum gökyüzünde

güneş kadar yalnız

kimsesiz

isimsiz

Söyle bana 

neden ağlıyorum kendi kendime

elimde sonsuz bir deniz ve tanıdık bir yıldızın üstünde

Bir o elimde deniz 

bir bu elimde

ve neden her seferinde aklımda sen varsın

bir elimde hayalin

bir elimde deniz

ama sen çok uzak

ben kimsesiz.

21.01.1997', 'Neden bu kadar karanlığım ve neden uçuyorum gökyüzünde güneş kadar yalnız kimsesiz isimsiz Söyle bana  neden ağlıyorum kendi kendime elimde ...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kimsesiz-karanliklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçaklar Sensiz Kalabilir', 'ucaklar-sensiz-kalabilir-umut-ulbegi-9je8p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uçaklar geçiyor kapımın önünden

kanatları değiyor dudaklarıma

getiriyor uzak ülkelerin soğuk sabahlarını

Arıyorum sıcaklığını

Özlemişim diyorum

özlemişim dudaklarını

Uçaklar geçiyor kapımın önünden

Ne olurdu diyorum

bir de sen geçsen.

26.01.1997', 'Uçaklar geçiyor kapımın önünden kanatları değiyor dudaklarıma getiriyor uzak ülkelerin soğuk sabahlarını Arıyorum sıcaklığını Özlemişim diyo...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ucaklar-sensiz-kalabilir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin', 'senin-i-cin-umut-ulbegi-5b4zu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Senin için 

titredikçe ellerim

yazdığım her şeyi

bil ki senin için

Senin için

çarptıkça kalbim

bil ki

düşündüğüm tek güzel şey

sensin.

30.10.1996', 'Senin için  titredikçe ellerim yazdığım her şeyi bil ki senin için Senin için çarptıkça kalbim bil ki düşündüğüm tek güzel şey sensin. 30.10...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/senin-icin-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tahta Sandalyem, Gölgem ve Ben', 'tahta-sandalyem-golgem-ve-ben-umut-ulbegi-20otq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir tahta sandalye

masabaşında gölgem

ellerim bulutlarda

gökyüzü yağmura uzak

ve 

damlalara teslim yeryüzü

Bir tahta sandalye

Deniz kıyısında gölgem

Taşlar tutmuş ayaklarımı

istesem de yürüyemem

Yakamoz vurmuş gözlerime

sabaha dek seyredemem

Bir tahta sandalye

sana uzak bir şehrin

yabancı sokaklarında gölgem

Acı çeken insanlar var

acılar var beni çeken

ve 

sensizlik var burada

Tahta sandalyem, gölgem ve ben

Sensizlik çekiyoruz.

11.01.1997', 'Bir tahta sandalye masabaşında gölgem ellerim bulutlarda gökyüzü yağmura uzak ve  damlalara teslim yeryüzü Bir tahta sandalye Deniz kıyısınd...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/tahta-sandalyem-golgem-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pembe Bir Aşk Yarası', 'pembe-bir-ask-yarasi-orhan-altan-q91da', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir balıkmışım ben, 

mavi bir fon ve üzerinde beyaz martılar...

Kocaman gri bir kalabalık

ve ortasında hiçsizlik...

Bir çok balıkadam tanıdım ben

mavi bir tonda yeşil kıvamında...

Yani aslında kırmızı bir balığım ben, 

mavi bir fonda beyaz kıvamında...

Yani aslında pembe bir aşk yarası...', 'Bir balıkmışım ben,  mavi bir fon ve üzerinde beyaz martılar... Kocaman gri bir kalabalık ve ortasında hiçsizlik... Bir çok balıkadam tanıdı...', ARRAY['Türk Edebiyatı','Şiir','Orhan Altan']::text[], 8.5, '{"poet":"Orhan Altan","poet_slug":"orhan-altan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/pembe-bir-ask-yarasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş Zaptedildi', 'gunes-zaptedildi-mirkan-acar-v9h10', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'alabildiğince upuzun ovalar boyunca oturmuş, 

etekleri dağların yamacına kadar serilmiş, 

papatya, yaban gülleri, nergisler... 

v dört mevsimin bütün çiçekleriyle süslenmişti... 

saçları; 

selviler, buzullar gibi yerlere serilmiş 

uçları yeşil, 

yukarılara gidildikçe sarı, 

sonra kırmızı, eflatun, mor... 

tepesi güneş rengiydi.., saçları gökkuşağıydı 

gözleri; 

gökyüzünün hüzün tabakasıydı, 

gözleri nehir gibi akıyordu mavi mavi. 

bütün yüreklerin o asi, sıcak ve yaralı derinliklerine... 

gözleri elaydı, maviydi, yeşildi... gözleri rengarenkti. 

kirpikleri, dağlara ağlar örmüştü.. 

kirpikleri, kökleri olmayan uçuşan ormanlar gibiydi.. 

ve bana eteklerine basacak kadar yakın, 

ulaşılması güç, bitmek tükenmek bilmeyen bir yol gibiydi.. 

koştum.., koştum, nefesim rüzgar olmuş, 

bedenim sular içinde kalmıştı.. 

gözlerinden akan mavi nehire katılan terim, 

ulaşılmadıkça fırtına, 

ulaşılmadıkçaasi, 

ulaşılmadıkça okyanus oluvermişti.... 

koştum..., yüzdüm..., haykırdım..., ağladım... 

ıslak, bitkin.., 

yüreği cehennem sıcağı bedenim, 

dizlerinin üstüne yığılıp kaldı.. 

ellerini gökyüzüne uzattı! 

tuttuğu gibi güneşi sırtıma dayadı! ! 

içimdeki yangının yanında, güneş; ..! ilkbaharın yalancı sıcaklığı gibiydi! ! ! 

sonra, serçeler kırlangıçlar, pepuklar, güvercinler, 

ve hiçbir zaman, yurdu olmamış yurtlarından! göçen kuşlar, 

kirpiklerine kondular... 

kirpiklerini kırpmıyordu.! 

gözlerinden akan mavi nehirdensu içen kuşlar, ürkmesin, düşmesin diye..! 

sonra elleriyle kuşlara dokundu...bütün kuşlar güvercin oldu! 

sonra eteklerindeki çiçeklere dokundu..., bütünçiçekler karanfil oldu...! 

her güvercine bir karanfil verip, 

dünyanın dört bir yanına uçurdu... 

umutla gökyüzüne açılan ellere, 

kanayan yaralara, 

nazım hikmetin mezarına, 

hatta ^^kaf dağının ardına^^ 

dünyanın semaları, güvercinler ve karanfillerle donanmıştı! 

^^güneş zaptedilmişti^^ 

bense; mavi nehirde özgür bir kuğu, 

enginliğinde bir bulut kuşuydum artık.... 

yüzünde yüzen...! 

teninde beslenen...! 

............................mirkan', 'alabildiğince upuzun ovalar boyunca oturmuş,  etekleri dağların yamacına kadar serilmiş,  papatya, yaban gülleri, nergisler...  v dört mevsi...', ARRAY['Türk Edebiyatı','Şiir','Mirkan Acar']::text[], 8.5, '{"poet":"Mirkan Acar","poet_slug":"mirkan-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/gunes-zaptedildi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim Yetim Kaldı..!', 'yuregim-yetim-kaldi-mirkan-acar-g0tjy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir yanım engin deniz, 

bir yanım dağ.. 

heybetli ve asi.. 

her yanım sen, 

Çılgın ve deli..! 

ve piru pak yüreğim 

hiç tükenmeyecek denizlerin sevdasıyla, 

gül tadında, 

sen tadında 

şarkılar haykırıyor, , .. 

dağ dağ, deniz deniz, 

yanımdaydın.., 

canımdaydın.., 

avuçlarından yüreğime coşkun nehirler taşıdın, 

odamdaydın..; 

duvarda ki tablolar canlanmış, 

hitit savaşçısının mızrağında güller açmış, 

erişilmezliği sembolü tanrıça, 

bindiği boğayı şaha kaldırmış, 

hoşap kalesindeki çoban ala geyikle sohbete başlamıştı, 

çiçekler baharı yaşıyordu, 

sandalyeler, hop tirilaylom şarkılar söylüyorlardı... 

ama... 

ama sen gittin... 

yüreğim yetim kaldı..! .. 

yüreğim; 

sokakların karanlık hüznü, 

yüreğim; 

yuvasız yavru kuşun ana çığlığı, 

yüreğim; 

dayanılmaz hasretlerin mavi tutsağı, 

yüreğim; cehennem azabı. 

gitme..gitme..! dedi yüreğim, 

nooolur...gitme kal dedi beynim... 

ama dilim ihanet etti bana, 

kal.. kal, gitme diyemedi sana..! 

gittin...... 

yüreğim yetim kaldı...! 

şimdi... 

hitit savaşçısının mızrağı yüreğimde.. 

tanrıça, boğayı üzerime sürmekte 

hoşap kalesi yıkıldı.çoban ala geyiğine ağlamakta.. 

çiçekler solgun yaz kuraklığında.. 

gittin dış kapı ağlamaklı, 

gittin yüreğim kimsesiz, 

gittin yüreğim ezik, 

gittin.............yüreğim yetim kaldı…! 

gitme..! 

gitme, dedi yüreğim.. 

noolur... 

gitme kal, dedi beynim. 

ama dilim ihanet etti bana.. 

kal... 

kal gitme, diyemedi sana 

gittin..... 

yüreğim sensiz kaldı..! 

gittin 

yüreğim 

yetim 

kaldı...!', 'bir yanım engin deniz,  bir yanım dağ..  heybetli ve asi..  her yanım sen,  Çılgın ve deli..!  ve piru pak yüreğim  hiç tükenmeyecek denizle...', ARRAY['Türk Edebiyatı','Şiir','Mirkan Acar']::text[], 8.5, '{"poet":"Mirkan Acar","poet_slug":"mirkan-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/yuregim-yetim-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ezgi', 'ezgi-turkan-i-ldeniz-4oj89', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben dedim mi bil ki başladığım sensin.

Senin sabrın, itilmişliğin, büyük boynundur çizdiğim.

Ellerin çeker beni yüz yıllar ötesine

O zamanlar ehramlar yükselten, şimdi kömüre inen

Ellerin, ellerin ve gene ellerin

Uzanır usulca öpüler gezdiririm her birinde.

Ben dedim mi bil ki başladığım sensin.

Sen olmasan çöker petrolün saltanatı

Kapanır betonlar kendi üstlerine

Kömür kalır, altın kalır hani o derinlerde

Yani ekmeğim, senin alnından dökülen emek.

Öküzün boynuzundadır demişler ya dünya, yalan

Ama senin omuzunda olduğu gerçek.

Ben dedim mi bil ki başladığım sensin

Uykularım sana bölünür

Yorgun kervanların yıkılır gözlerime

Gözlerim karanlığına bekçi, gözlerim özgür

Sabah tez gelsin isterim hele güneş doğsun

Kuzuları seveceğim bir bir.

Ben dedim mi bil ki başladığım sensin

Güneş doğuyor hadi kalk

Aralansın kirpiklerin', 'Ben dedim mi bil ki başladığım sensin. Senin sabrın, itilmişliğin, büyük boynundur çizdiğim. Ellerin çeker beni yüz yıllar ötesine O zamanla...', ARRAY['Türk Edebiyatı','Şiir','Türkan İldeniz']::text[], 8.5, '{"poet":"Türkan İldeniz","poet_slug":"turkan-i-ldeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ezgi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaban İklim', 'yaban-i-klim-turkan-i-ldeniz-tdqgf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni böyle sıkı tutma n''olursun

Yoluma süngüler dikme

Çevir gözlerini öyle durmasın

İncelen çok şey var aramızda

Bırak artık burada noktalansın

Sürdürmekte fayda yok kesme yolumu gideyim

Senin ikliminde açmıyor çiçeklerim.

Hep gün çevrile dedin, yıl döne

Yıllar döndü ben döndüm bu çemberde

Bunca dar yaşamak bunca yoğun

Daha daha tutma ne olursun

Sür gölgeni aradan, biraz ışık göreyim

Yağmuru batak, güneşi serin

Senin ikliminde açmıyor çiçeklerim

Tam güneşe, gülüşe duranda, öyle istekle

Bir bora çıkar, fırtına patlar, başlar şimşeklerin

Kumrular, kalyonlar mahzun dolanır olduğu yerde

Sende geçen yiter ama-bilemezsin

Her anı derin iz bırakır bende

O zaman da demiştim, yine de derim

Senin ikliminde açmıyor çiçeklerim.', 'Beni böyle sıkı tutma n''olursun Yoluma süngüler dikme Çevir gözlerini öyle durmasın İncelen çok şey var aramızda Bırak artık burada noktalan...', ARRAY['Türk Edebiyatı','Şiir','Türkan İldeniz']::text[], 8.5, '{"poet":"Türkan İldeniz","poet_slug":"turkan-i-ldeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yaban-iklim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolların Sonu', 'yollarin-sonu-ahmet-altumsek-58mdh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir kitap gibi sonuna geldik

Yürüdüğümüz yolların.

Dönüşü olmayan bir noktada

Ne olacağımız bilinmez yarın.

Arkada kalan yollarda rüzgarın

Savurduğu sarı güz yapraklarıdır.

Acı tatlı günleriyle ne varsa bizden olan

Ömrün yaşanmış yıllarıdır.

Dallar böyle böyle çıplak kalır

Toprak beslemez gövdeyi.

Yaşlanmış gövde kuşa, kurda karşı

Koruyacak neyi? 

Ki artık vakit ikindi sonrasıdır, 

Gölgeler vurmuş da kanatlarınca yola.

Göz nafile seçmeye uğraşır ileriyi

ışıklar, mevsimler, renkler arkada.

Altın kanatlı umutların sevinci yitik

Güneş de kaçmada dağların ardına

Bir vakit ki bundan sonrası

Yaşamak değil, hayatı temaşa.

Bir kitap gibi sonuna geldik

Yürüdüğümüz yolların.

Bir noktada ki, üzgün, yorgun

sığınmışız avuntusuna hatıraların.', 'Bir kitap gibi sonuna geldik Yürüdüğümüz yolların. Dönüşü olmayan bir noktada Ne olacağımız bilinmez yarın. Arkada kalan yollarda rüzgarın S...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Altümsek']::text[], 8.5, '{"poet":"Ahmet Altümsek","poet_slug":"ahmet-altumsek","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yollarin-sonu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak Sevgisi', 'yasamak-sevgisi-ahmet-altumsek-lh80i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşadıkça anlıyoruz yaşadığımızı

Dudaklarımıza değen suyu tattıkça

Yağmur ıslattıkça, ateş yaktıkça

Anlıyoruz yaşadığımızı, 

Yaşadıkça...

Elin ekmek tuttuğu günden başlar, 

Dünyaya ilk geliş.

Yaşanır yaşanır da bir altın çağ içinde

Bilinmez yaşamın değeri.

Şimdi geriye dönülmez bir çağın eşiğinde

Bulutlardan sıyrılacak güneş düşünülür.

Kül renkli bulutların yağdıracağı yağmur, 

Kopacak kızılca kıyamet

Bir an unutulur.

Sonu gelmez kavgaların yitiremediği

Aşk gibi, barış gibi, hürriyet gibi

bir şey var insan kalbinde yaşayan

Seller ayıramaz kökleri ağaçtan

Yaşadıkça yaşamayı sever insan...', 'Yaşadıkça anlıyoruz yaşadığımızı Dudaklarımıza değen suyu tattıkça Yağmur ıslattıkça, ateş yaktıkça Anlıyoruz yaşadığımızı,  Yaşadıkça... El...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Altümsek']::text[], 8.5, '{"poet":"Ahmet Altümsek","poet_slug":"ahmet-altumsek","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yasamak-sevgisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Üzerine Düşünceler', 'olum-uzerine-dusunceler-ahmet-altumsek-5i2am', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gün ölmek mukadder ya

Ölümlerden ölüm seçmek isterim

Elimde olsa...

Bir ince çizgi vardır

Ölmekle yaşamak arasında

Hani ip atlamak gibi bir şey

İnsanlar iki yanda...

Bilirim ölümün de çeşidi vardır: 

Zorlusu, rahatı, kolayı, erkeni, geci

Bilinmez, bir gün

İnsanın hangisine rastlayacağı.', 'Bir gün ölmek mukadder ya Ölümlerden ölüm seçmek isterim Elimde olsa... Bir ince çizgi vardır Ölmekle yaşamak arasında Hani ip atlamak gibi ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Altümsek']::text[], 8.5, '{"poet":"Ahmet Altümsek","poet_slug":"ahmet-altumsek","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/olum-uzerine-dusunceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gençlik Resmi', 'genclik-resmi-ahmet-altumsek-yots3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bekar odamın perişan masası üstünde

Parlak bakışlı, şen gülüşlü gençlik resmim! 

otuz yaşından sonra ben artık sen değilim.

Besbelli memnunsun küçük cam resimliğinde.

Nolurdu, ben de mesut olsaydım şimdi senin gibi

Martta ağaçların çiçek açışını yaşasaydım hâla.

Bak mevsim değişti benim şakaklarımda

Yeni bir fal gösteriyor alnımda her çizgi...

Yıllar etmiş bizi, birbirimize, ne kadar yabancı, 

İlk fark belli olmuş, görüyorum saçlarımda.

Bir balta dolaşmış haince bu gür ormanda

Kopmuş seni çektirdiğim günden beri kaç takvim yaprağı...

Yalnız saçlar mı ya? Yüz başka, gözler başka

Kulaklarda o günlerden kalma tatlı ses yok

Dünya mı değişti, bende mi eski heves yok, 

Yol almak için doludizgin, hayata ve aşka...

Bu dik duruş ne? Dağları ben yarattım der gibi.

Dünyayı nerdeyse yerinden oynatacak.

Şimdi sadece kuvvet aranıyor yaşanacak, 

Omuzların da hani az şey değil söyledikleri...

Hangi menzilde kalış bu? Ey mağrur delikanlı

Gün o gün değil, zaman durmuyor

Kalp aynı sesle, nabız hızla vurmuyor.

kanın da kalmamış damarda eskisi gibi...

Ama seni koymuşum yine masamda baş köşeye

Bilmem bi dönülmez çağı özleyiş mi bu? 

Yoksa senden hâla, fayda bekleyiş mi bu? 

Elde edilmesi şimdi, hayal olan her şeyde...

Sen, sen benim şen gülüşlü gençlik resmim

Vaktim sükûnu içinde yaklaşmada ikindi, 

Ömrün göz kamaştıran fecrinden şimdi, 

Sensin elimde kalan son şahidim...', 'Bekar odamın perişan masası üstünde Parlak bakışlı, şen gülüşlü gençlik resmim!  otuz yaşından sonra ben artık sen değilim. Besbelli memnuns...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Altümsek']::text[], 8.5, '{"poet":"Ahmet Altümsek","poet_slug":"ahmet-altumsek","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/genclik-resmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek Sevi', 'gercek-sevi-ahmet-altumsek-4h00a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşar o, derinlerde... doğdu bir kez

Doğduğunca var o, katıksız, 

Ağaçta özsu örneğin can verircesine.

Ay ışısın üstüne gün vursun istemez.

Önceleyin Tanrı elinden düşmüş toprağa

Düşmüş habersiz ve yıllarca, yıllarca

Mevsimler değişmiş, kaç nadas geçmiş üstünden

Tohum çürümemiş, güçten düşmemiş tarla.

Tül, tül duyuların saydamlığında ışıyan

Bir ses o kalp dilince, duyulmaz.

Tanrısal bir uyum ki evren içinde

ruhta sonsuz açan çıldırtısı erguvan.

Büyür yaşantılar evreninde esen

Mut içinde dünyaya gülümser.

Bir ezgi o, insan yüreklerde yankısı

Çağlarca titreşen.

Dost o, her yerde, her anlamda rastladığın

Konuşulmaktan anlamlı, sessizlik o.

İçtenliğince engin bakış o, konuşmasız

Şiir o, mısralarında yaşadığımız.

Yaşar o, derinlerde... doğdu bir kez

Doğduğunca var o, Tanrı vergisi, katıksız.

Ağaçta özsu örneğin görünmez

Dile gelsin, söz olsun, açıklansın istemez.', 'Yaşar o, derinlerde... doğdu bir kez Doğduğunca var o, katıksız,  Ağaçta özsu örneğin can verircesine. Ay ışısın üstüne gün vursun istemez. ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Altümsek']::text[], 8.5, '{"poet":"Ahmet Altümsek","poet_slug":"ahmet-altumsek","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gercek-sevi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşçakal Rize Şehri', 'hoscakal-rize-sehri-ahmet-altumsek-1gwbp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hoşçakal Rize şehri, hoşça kal

Yedi gençlik senemi verdiğim şehir, 

Senden ayrılmak isterdim ya, emin ol

Gariptir gönlüm, şimdi gariptir.

Balkonundan bakıp bakıp deryalara daldığım

Sisli dağlarında yeşile doyamadığım

Günler süren yağmurunda ıslanıp usandığım

Gökleri bulutlu, yağmurlu şehir.

Koynunda geçmiş yalnız günlerim.

Uykusuz gecelerim vardır.

Fener burnunu her dönen vapura yüklenmiş düşüncelerim

Islak kaldırımlarında kederlerim vardır.

Nasıl düşünmem şimdi yağmurlu hafta günleri

Sırtında sepet taşıyan köylü bacıları

Şube bahçesinde zevk günleri: 

Horon oynayan delikanlıları.

Hasreti kemençenin dilinden söyleten

Bir bendilin ucunda selam titreşen

''Çal! horon dağıtır hasreti'' diyen

Bıyığı yeni terlemiş uşakları.

Hoşçakal Rize şehri, hoşça kal

Yedi gençlik senemi verdiğim, yağmurlu şehir

Ağzımda Karadeniz''in tuzu, 

Dudaklarımda mandalina tadı vardır.

İliklerimde rutubetin üşütmesi

Dilimde çayın burukluğu vardır.

Koynunda kimsesiz, , uykusuz gecelerim

Bitmemiş sevgilerim vardır.

Hoşçakal Rize şehri, hoşça kal

Yedi gençlik senemi verdiğim şehir

Senden ayrılıyorum ya

Gariptir gönlüm, gariptir.', 'Hoşçakal Rize şehri, hoşça kal Yedi gençlik senemi verdiğim şehir,  Senden ayrılmak isterdim ya, emin ol Gariptir gönlüm, şimdi gariptir. Ba...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Altümsek']::text[], 8.5, '{"poet":"Ahmet Altümsek","poet_slug":"ahmet-altumsek","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/hoscakal-rize-sehri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aralık Kapı', 'aralik-kapi-ahmet-altumsek-1oqyf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hani aralıktı kapı içeri girmiştim.

Hırsız gibi gizliden, konuk gibi çekingen değil.

Kırk yıllık tanıdık gibi ellerim, ayaklarım özgür

Aralıktı kapı vurmadan girmiştim.

Eşiğinden tut, ne varsa içinde hep bildiğim

Elimle konmuşcasına her şey düşündüğüm gibi

Pencereler açıktı, perdeler yarı inik

Loşluğunda bir süre gezinmiştim.

Her şey aman ne güler yüzle karşılamıştı beni, 

Tanrı''nın gönderdiği beklenen miydim neydim? 

Yüce mağaralar örneği el, ayak değmemiş evde

Perdeleri çekmiştim, ışıklar dolmuştu içeri.

Birden değişmişti her şey ev, eşya, bahçe

Yediveren gülleri açmıştı kat kat ve renk renk

Duvarlar daha bir beyaz olmuştu, aydınlık

Bir şenlik dolaşmıştı ortalıkta bir süre.

Unutulmuş mutluluklar dirilmişti bir bir

Simsiyah yaşamalar yerine ak umutlar.

Her şey Tanrı eliyle konmuştu düzene

Tanrı diliyle söylenmişti bağlandığımız şiir.

Aralık kapıdan girmişti müziği

Uçsuz bucaksız sevilerin geleceklere bakan

Akla gelmez, bir gün hangi el hoyrat, 

Aralık kapıyı kapatmağa deyesi.', 'Hani aralıktı kapı içeri girmiştim. Hırsız gibi gizliden, konuk gibi çekingen değil. Kırk yıllık tanıdık gibi ellerim, ayaklarım özgür Aralı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Altümsek']::text[], 8.5, '{"poet":"Ahmet Altümsek","poet_slug":"ahmet-altumsek","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/aralik-kapi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varation', 'varation-ahmet-altumsek-5afc6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni düşündüğüm zaman: 

Duygular kanatların içimde, duygular ki

Karanlık toprakta gizli tohum misali

Güneş görünce, su görünce fışkıran.

Seni gördüğüm zaman; 

Yapraklar üstünde sabah vakti

Güneş vurmuş bir çiy damlası gibi

Kalbimdir sıcak bir titreyişle parlayan.

Gözlerine baktığım zaman: 

Sevinçler, güzelliklerle dolar dünya.

Bir sevinç ki yeniden doğmak gibi hayata

Bir güzellik ki yaşamak sevgisi uyandıran.

Seninle konuştuğum zaman: 

Altın kanatlı kuşlar etrafımızda uçar, uçar

Şiirleşir sözler dudaklarında, kalbe akar

Sözler ki bezgin ruhumu huzura kavuşturan.

Seni dinlediğim zaman: 

Sözlerinde düşüncemin tıpkısı düşünceler

Değişir herşey zaman, iklim, mesafeler

Mesafeler ki,  aramızda günden güne azalan.

Senden ayrı olduğum zaman: 

Bitmez rüya, değişmez evren, ışıklar sönmez.

Devam eder aynı müzik ve aynı ses

Söyler sonsuz şiirini aşkın yorulmadan.

Ve her zaman: 

Sen ömrün gecesini ağartan umut fecri, 

Ölmezliğe erişen sanat eseri gibi

Sensin hayatımda ve şiirimde kalacak olan.', 'Seni düşündüğüm zaman:  Duygular kanatların içimde, duygular ki Karanlık toprakta gizli tohum misali Güneş görünce, su görünce fışkıran. Sen...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Altümsek']::text[], 8.5, '{"poet":"Ahmet Altümsek","poet_slug":"ahmet-altumsek","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/varation-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım Türkü', 'yarim-turku-ahmet-altumsek-ux7c6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu son şiirim size

Ey beni seven dostlarım.

Soluğum kesildi birden bire

Dudaklarımdaki türkü yarım.

Hani eğildikçe suya

İkimiz bir görünürdük? 

Ayrımız, gayrımız yok diye

Sevinir, övünürdük.

Hangi sihirbaz eli, uğursuz

Bozdu bu görünmez büyüyü? 

Yağmurlar boşandı üstümüze

Karardı birden gökyüzü.

Düştü içimize bir kez

Bırakmaz yakamızı bu kuşku.

Soluğum kesildi birden bire

Yarım dudaklarımdaki türkü.', 'Bu son şiirim size Ey beni seven dostlarım. Soluğum kesildi birden bire Dudaklarımdaki türkü yarım. Hani eğildikçe suya İkimiz bir görünürdü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Altümsek']::text[], 8.5, '{"poet":"Ahmet Altümsek","poet_slug":"ahmet-altumsek","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yarim-turku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke', 'keske-melih-coskun-ftt57', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Keşke bu dünya dümdüz olsaydı  bir tepsi gibi 

Dünyanın bittiği yeri bularak bütün tankları oradan aşağı atmak isterdim

Tankların paletleri arasında ezilen çocuklar değil anaların yürekleri, 

Toprağa her düşen bir ölü değil, bir ananın gözyaşıdır 

ve yüreklere saplanan her mermi bir yıldızdır saçlarına düşen.

Keşke dünyanın bütün silahlarını bir meydanda toplayıp yakabilseydim, .

Acı yüzlü çocuklarımızın hürriyeti için.

(Üzülme dostum gün gelir 

Belki de çiçek dikeriz bütün kışlalara

Kavuşur belki bütün çocuklar analarına) 

3 Nisan 2002

00: 01', 'Keşke bu dünya dümdüz olsaydı  bir tepsi gibi  Dünyanın bittiği yeri bularak bütün tankları oradan aşağı atmak isterdim Tankların paletleri ...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/keske-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşadığıma Dair', 'yasadigima-dair-ahmet-altumsek-9y3uu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yarım kalıyor dudaklarımda

Her akşam tutturduğum şarkı

Alıp götürmüyor düşüncemi

Neşeli kıyılara

Engini kucaklayan yelkenli.

Ve beni 

Gelmiyor alacak gemi...

Yarım kalıyor gözlerimde

Beliren buğulu şekiller.

Duyuyorum bütün bir gün içimde

Nasıl hükmediyor geceler.

Gelmiyor, gelmiyor bir türlü

Beni rüyalarla dolu

Göğsüne çekecek uyku...

Yarım kalıyor dudaklarımda

Adımı çağıran ses.

Duyuramıyor bana kendini

Esen rüzgar, akan su

Kıyıları döeven dalga, deniz, 

Çekiyor derinliğine ruhumu

Sükût... O karanlık dehliz...

Yarım kalıyor hafızamda

Sevdiğim yüz, bellediğim şiir.

Kıyısında dinlenmek istediğim huzur, 

Lezzetinde aşkı tattığım arzu.

Yarım kalıyor dostlarım

Gülez bir dünya içinde, benim

Bu türlü yaşadığım.', 'Yarım kalıyor dudaklarımda Her akşam tutturduğum şarkı Alıp götürmüyor düşüncemi Neşeli kıyılara Engini kucaklayan yelkenli. Ve beni  Gelmiy...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Altümsek']::text[], 8.5, '{"poet":"Ahmet Altümsek","poet_slug":"ahmet-altumsek","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yasadigima-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Okulun Önünde Yatan Ölü', 'okulun-onunde-yatan-olu-melih-coskun-0ayq2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir ölü yatıyor, 

Okulun önünde

Sıcak kanı bulaşarak yoldaşların ayaklarına

Bir yiğit düşmüş 79 baharı ortalarında

Hayatının baharında

Ve yaşamaktan başka bir çıkarı olmayan dünyadan

(Yaşamak, ama hür

Yaşamak, ama eşit

Yaşamak, ama insanca) 

Havada ağır bir kan kokusu

Havada isyan kokuyor

Nefes almak zor

Toplanıyor on binler 

Toplanıyorlar işte takip ederek arkadaşlarının kanını

Güneşe gömmeye geliyorlar vuruşarak düşen yoldaşlarını

Yumrukları göğü delecek gibi

Yükseldikçe birleşiyor  gökyüzünde

Haykırıyorlar tek yürek: 

“Başın öne eğilmesin

Aldırma gönül aldırma”

Merak etme çocuk

Başımızı öne eğemediler

Biz bugün yine o okulun önündeyiz

Üç beş kişi kalsak bile 

İnadına haykırıyoruz 

“Aldırma gönül aldırma

görecek günler var daha”   

21 Temmuz 2002

01: 03', 'Bir ölü yatıyor,  Okulun önünde Sıcak kanı bulaşarak yoldaşların ayaklarına Bir yiğit düşmüş 79 baharı ortalarında Hayatının baharında Ve ya...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/okulun-onunde-yatan-olu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgisiz Sevgiliye', 'sevgisiz-sevgiliye-celal-sahir-erozan-dz4j2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eğer olsaydık ben deniz sen kaya; 

eteklerinde ağlaya ağlaya

Sert kalbine bir merhamet verirdim.

Eğer olsaydık ben bulut, sen ay; 

Yere düşse nurundan bir küçük pay

Kıskanırdım, damla damla erirdim.

Eğer olsaydık ben bülbül, sen gül; 

İnleyerek seni eğlendirirdim.

Sen bir CİN''sin bense çarptığın çocuk

Dilim tutuk karşında, benzim uçuk

Bir yaşayan ölü haline girdim!', 'Eğer olsaydık ben deniz sen kaya;  eteklerinde ağlaya ağlaya Sert kalbine bir merhamet verirdim. Eğer olsaydık ben bulut, sen ay;  Yere düşs...', ARRAY['Türk Edebiyatı','Şiir','Celal Sahir Erozan']::text[], 8.5, '{"poet":"Celal Sahir Erozan","poet_slug":"celal-sahir-erozan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevgisiz-sevgiliye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '52 Yıl', '52-yil-celal-sahir-erozan-pokfw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hala yaşım genç ama, vücudum ölgün gibi; 

Bütünacı günlerim aklımda, bugün gibi! 

İçimde hayata küskün, dış yüzüm düğün gibi; 

Elli iki yıl geçti: Elli iki gün gibi! ...

Doğmayan hülyaların saçlarını taradım, 

Ezop gibi fenerle gündüz insan aradım

Ne kendime yar oldum, ne kimseye yaradım, 

Elli iki yıl geçti: Elli iki gün gibi...', 'Hala yaşım genç ama, vücudum ölgün gibi;  Bütünacı günlerim aklımda, bugün gibi!  İçimde hayata küskün, dış yüzüm düğün gibi;  Elli iki yıl ...', ARRAY['Türk Edebiyatı','Şiir','Celal Sahir Erozan']::text[], 8.5, '{"poet":"Celal Sahir Erozan","poet_slug":"celal-sahir-erozan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/52-yil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarın Çocuğuna Bırakacak Bir Şiirin Olsun', 'yarin-cocuguna-birakacak-bir-siirin-olsun-melih-coskun-x172d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yarın çocuğuna bırakacak

Bir şeyin olsun

Bir şiirin olsun mesela

Görsün beynine sığmayıp taşan bir nehri

Güzel bir söz bırak mesela

Aklına gelsin umulmadık bir zamanda

İki damla gözyaşı yuvarlansın  yanaklarından

Sevgini bırak

Sevmeyi öğrensin insanları

Kavganı bırak

Baş eğmesin haksızlığa

Umudunu bırak

İnancını kaybetmesin geleceğe

Kederini bırakma ama

Kanatmasın yüreğini yok yere

Bırakacaksan da adam gibi hüzünler bırak ki

Anlasın mutluluğun kıymetini

Yüreğini bırak çocuğuna

Belki satamaz bir antikacıya ama

Bir gün merak edip de

Açıp bakarsa içine

Belki o anlar ne demek istediğini...

12 Ekim 2002

23: 39', 'Yarın çocuğuna bırakacak Bir şeyin olsun Bir şiirin olsun mesela Görsün beynine sığmayıp taşan bir nehri Güzel bir söz bırak mesela Aklına g...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yarin-cocuguna-birakacak-bir-siirin-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkma, Buradayız Daha', 'korkma-buradayiz-daha-melih-coskun-hox2t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen, 

Kazmasına bir yüreği tutar gibi sarılan

Yeraltından güneş ışığı çıkartan madenci

Sen, 

İşlediği çelikten yapılan bıçak

Sırtına saplanan çelik ustası, 

Sen, 

İngiliz anahtarını namusu gibi taşıyan 

Tamirci çocuk, 

Sen, 

Bir meçhule giden asker, 

Sen, 

Oğlu  meçhule gönderilmiş ana, 

İşitiyor musun sesimi? 

Bugün birileri bana 

Bırak bu işleri diyor

Bırak bu işleri

Devir, vahşi kapitalizmin, 

Devir, ölsün diye çocuklar

Yetki alanın parlamentosundan, 

Ve adına demokrasi diyenin, 

Adına dünya barışı diyenin vahşetin, 

Bırak diyor bu işleri

Eşitlik diye bir şey yok artık bu dünyada

Hürriyet yok 

Yirmi birinci yüzyıldayız artık farkında değil misin? 

Devir, vahşi kapitalizmin 

Devir kuyruğu kanlı köpeklerin 

Ve Artık yoksun sen.

Cevap: 

Korkma, 

Burdayım

Bırakmadım kavgayı

Senin insanın yaşıyorsa daha on altıncı yüzyılı

Gün ışığına muhtaçsa 

Açlıktan kokmuşsa nefesi

Yitiyorsa bir meçhulde

Ağlıyorsa analar, 

Ölüyorsa çocuklar, 

Ben buradayım, 

Bırakmam bu işleri...

12 Ekim 2002

00: 33', 'Sen,  Kazmasına bir yüreği tutar gibi sarılan Yeraltından güneş ışığı çıkartan madenci Sen,  İşlediği çelikten yapılan bıçak Sırtına saplana...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/korkma-buradayiz-daha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Maviler Biriktir', 'sen-maviler-biriktir-melih-coskun-5rcb8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevdalanmak değildi istediğin

Çok doluydu yüreğin 

Bölmek istedin sadece ikiye

Aynı yolları yürümek

Bastığı yerlere basmak

Güldüğü yerde gülmek

Öldüğü yerde ölmek

Anlamadı seni sonbahar akşamları

Anlamadı dostun 

Senin mavilerin az gelmişti bir sevgiye

Oysa istese bütün mavileri getirebilirdin dünyadaki

Sen beceremezsin ki sevmeyi 

Bu çocuk yüreğinle

Oyuncağını kaybetmiş bir çocuk gibi 

Ağlardın yitirdiğin zaman bir aşkı

Bakalım bölebilecek misin bu yüreği

Taşmadan içini dolduranlar

Üzülme daha zamanın var 

Sen maviler biriktir yeter ki

Bir sevgiye yetecek kadar...

2 Kasım 2002

00: 15', 'Sevdalanmak değildi istediğin Çok doluydu yüreğin  Bölmek istedin sadece ikiye Aynı yolları yürümek Bastığı yerlere basmak Güldüğü yerde gül...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sen-maviler-biriktir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolcu', 'yolcu-yasar-kurt-8zz8g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yolcu rüzgara karşı yürüdü.

Çöl, bozkır, sokaklar bedeniyle vardı

bir de zamanın sonsuzluğu...

^^boşver^^, ^^gel^^, ^^vazgeç^^, 

sözleri oyun sözcükleriydi ürkek çocukluğunun

bilirdi.

Uğursuzluk dedi, yaşanmayan aşklar için 

hep bir göz ışığıydı boynunda taşıyıp ta  hiç kimsenin görmediği...

Mavi onu alan ve örten oldu.

Yapmadan önce zarar vermedi çığlık attı.

Hiç utanmadı sesinden, 

sessizliği bir başka dili değilse o an 

ya da tanımı istemedi keyifliydi.

Kaç ^^ÇOCUK^^ yüzünü görmüştü.

Ölüm kendinin olunca 

ölümdü.......

ÖLMEDİ.', 'Yolcu rüzgara karşı yürüdü. Çöl, bozkır, sokaklar bedeniyle vardı bir de zamanın sonsuzluğu... ^^boşver^^, ^^gel^^, ^^vazgeç^^,  sözleri oyu...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Kurt']::text[], 8.5, '{"poet":"Yaşar Kurt","poet_slug":"yasar-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yolcu-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmek Dert Değil de Yazık Olmaz mı Umuda', 'olmek-dert-degil-de-yazik-olmaz-mi-umuda-melih-coskun-prs7a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerinde bu akşam 

Yumruk yumruk 

Yumruklaşan bir hasret

Sol kolun gökyüzüne özlemi

Ve yerçekimine meydan okuyan direnişi

Alnından akan tuzlu sıcak ter değil

Alnından akan kıpkızıl bir kan

En delikanlı günlerimizin 

Şakaklarında onlarca kurşun yarası

Tanklar geçiyor sanki yüreğinin üzerinden

En güzel günlerinin önünde dev barikatlar

Ve ölümünü düşünmediğin kadar cesursun

Yoldaşların türkü söylediği sokaklardan geçiyorsun

İçinde aynı yolu yürümenin gururu 

Böyle yitmemeliydi elbet bu hikaye

Bu tuzlu ter, bu kusursuz emek

Kuşkusuz daha güzel bir yarın adına

En güzel günlere ulaşmak adına bu fedakarlık

Dalgalı denizler durulur diye bir gün

Diner diye çatıları uçuran fırtınalar, 

Sonsuz anlamlı gözleri ve elleriyle

Davar gütmek yerine çayırlarda, 

Kalem tutsun 

Ve büyüsün 

Ve Yürüsün diye

Şu küçücük yürekler

Beynimde yumruklaşan bu hasret

Şakaklarından kızıl kanlar yerine 

Sıcak, tuzlu ve namusla aksın diyedir ter.

(Ölmek dert değil de

Yazık olmaz mı umuda...) 

18 Aralık 2002

01: 39', 'Gözlerinde bu akşam  Yumruk yumruk  Yumruklaşan bir hasret Sol kolun gökyüzüne özlemi Ve yerçekimine meydan okuyan direnişi Alnından akan tu...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/olmek-dert-degil-de-yazik-olmaz-mi-umuda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuyorum', 'korkuyorum-nihat-oztorun-79v1x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bakamıyorum o simsiyah gözlerine

İçim ürperiyor.

Sonu gelmeyen yollar gibi

omuzlarından dökülen kapkara saçlarına daldıkça

Gözlerim kararır, biliyorum.

Uçuruma terk edilmiş zavallı yolcuyum ben.

Elimden tut, ne olur! 

Anla beni, korkuyorum.

Neden istedin bunu benden? 

Bilmez misin ki her şey

Şaka ile başlar hayatta

Ama, yazık olur sonra o güzel gözlere

Fark edemezsin ağlayan, gülen insanları

Sağanak altında dökülen gözyaşımı, yağmur tanelerimi

Bilemezsin.

Bir gün nehirler gibi düşsem bile peşine, 

Dağlardan kopan bir çığ, 

elimde asa ile, Musa olsam çöllerde, 

Ve her gelene sorsam, 

Bulurum belki de ben dünyada yaşattığım kadını.

Yazık ki çok beklemiş, 

Yağmur tanelerine hasret topraklar gibi

Sararmış olurum ben.

Gözlerin küçülmesin, anlarım güldüğünü.

Duyarım gönüllerde kopan ince telleri.

Sonra yine fırtına, merhametsiz rüzgarlar

Sürüyüp giden zaman: 

Saçlarda bir iki ak...

Darmadağın olur hep kuruyan bahçelerde, 

Senden hatıra kalan sararmış bir kaç yaprak.

Durdurmak mümkün olsa tüm geçen zamanları; 

Dönülebilse heyhat, o en güzel günlere.

Mutlulukları bir bir uzayan yollar gibi çekebilsek

Yaşlı gözlerle, ruhumuzda kanayan hatıralar

Kıpkızıl güller açar.

İşte o zaman sen yavrum, 

Belki de ülkeler ötesinde, 

Yine taze bir çiçek, bin gül olursun

Fakat senin alemin başka.

Benim dünyam ne yazık apayrı dünya olur.

Anladın ya? 

İşte ben düşündükçe bunları, 

Hem senden kopuyor, 

Hem  de çok yavrum.

Çok korkuyorum...', 'Bakamıyorum o simsiyah gözlerine İçim ürperiyor. Sonu gelmeyen yollar gibi omuzlarından dökülen kapkara saçlarına daldıkça Gözlerim kararır,...', ARRAY['Türk Edebiyatı','Şiir','Nihat Öztorun']::text[], 8.5, '{"poet":"Nihat Öztorun","poet_slug":"nihat-oztorun","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/korkuyorum-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Gibi', 'hayal-gibi-nihat-oztorun-qvdda', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gündü, 

Bahar kadar tatlı, melekler kadar temiz

Bakışlar kadar füsûnkâr, taze bir alem.

Başlangıcıydı yeni bir hayatın

Ne güzeldi kainat

Her şey şirin, her şey vefakar.

Dünyaya geldiğim o günü anlattın

O gün hissettim varlığımı

Yaşadığımı, ağladığımı, hatta sevdiğimi

Demek hayat dedikleri kadar varmış

Bu sihirli alemin, bu sıcak günlerin

Birleştiği yerde başlar ve bitermiş.

Benim de başlamıştı sevgim böyle bir günde

Esiriydim güneşin, yıldızların elinde

Bir çocuk kadar masum, şen ve kaygısız

Tek ümidim, emelim, arzum

Hatta Allah''a yalvarışım oydu yavrum.

Bir gündü

Fecri ışıklarıyla söndü

Yapraklarını döktüğü, rüzgarların kamçıladığı bir gündü

Bu hayatta, her doğuş böyle bir günde başlar

Böyle bir günde heyhat, sessizce sona erer

Acıları neşeye, bahtsızları sevince ulaştıran günlerden bir gündü

Baharlar kışa döndü

Her şey onunla başladı, her şey onunla söndü.', 'Bir gündü,  Bahar kadar tatlı, melekler kadar temiz Bakışlar kadar füsûnkâr, taze bir alem. Başlangıcıydı yeni bir hayatın Ne güzeldi kainat...', ARRAY['Türk Edebiyatı','Şiir','Nihat Öztorun']::text[], 8.5, '{"poet":"Nihat Öztorun","poet_slug":"nihat-oztorun","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hayal-gibi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurda', 'yagmurda-sukran-kurdakul-e11nf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yağmurda parkta oturulmuyor, 

İstasyon çok hüzünlü; 

Acaba nasıl geçirmeliyim, 

Bu koskoca günü? 

Kitaplar koltuğumda ıslandı, 

Sigaram söndü sudan, 

Belki methiyeler yazdığım için, 

Çok iyilik gördük bulutlardan.

Dudaklarımda dostlardan şiirler, 

Şimdi haykırarak da okusam kimse duymaz; 

Şehir acınacak halde, 

Boşalmış bütün caddeler.

Hayatımı sürükleyen ayaklarım, 

Suları kabul ederek neredeyse; 

ağaçlar benimle alay etmeye başladı, 

Sokakta kalmadı kimse...', 'Yağmurda parkta oturulmuyor,  İstasyon çok hüzünlü;  Acaba nasıl geçirmeliyim,  Bu koskoca günü?  Kitaplar koltuğumda ıslandı,  Sigaram sönd...', ARRAY['Türk Edebiyatı','Şiir','Şükran Kurdakul']::text[], 8.5, '{"poet":"Şükran Kurdakul","poet_slug":"sukran-kurdakul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yagmurda-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekliyorum', 'bekliyorum-yasar-nabi-nayir-keyzz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'En güzel rüyaları andıran enginlere

En güzel ümitlerle açılmak istiyorum.

Gözlerinin içinde, bilmediğim bir yere

Günlerce gitmek gitmek ve dönmemek...diyorum.

Fakat siyah ufkunu ne gün, ne ay açıyor.

Dalgalar bulutlardan inmiyor bu denizde.

Bekliyorum, fırtına dinmiyor bu denizde.

Bu denizde en ıssız karanlıklar yaşıyor.

Ve ben şimdi aydınlık sokaklar bekliyorum.

Ümidi bir yelken gibi açarak bir gemiye

Sonsuz mesafelere doğru açılsam diye

Bir güzel gün, bir sükûn, bir bahar bekliyorum.', 'En güzel rüyaları andıran enginlere En güzel ümitlerle açılmak istiyorum. Gözlerinin içinde, bilmediğim bir yere Günlerce gitmek gitmek ve d...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Nabi Nayır']::text[], 8.5, '{"poet":"Yaşar Nabi Nayır","poet_slug":"yasar-nabi-nayir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bekliyorum-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlama', 'anlama-oruc-aruoba-z4n5d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bitirdiğim yerden başlarım her dönüşümde

ölüme-elime bakar anlarım, neredeyim.

Başladığım yerde bitiririm her dönüşümde

ölümü-dilime bakın anlayın, neredeyim.

İlerlediğim yerde giderim her dönüşümde

ölümle-selime bak anla, neredeyim.', 'Bitirdiğim yerden başlarım her dönüşümde ölüme-elime bakar anlarım, neredeyim. Başladığım yerde bitiririm her dönüşümde ölümü-dilime bakın a...', ARRAY['Türk Edebiyatı','Şiir','Oruç Aruoba']::text[], 8.5, '{"poet":"Oruç Aruoba","poet_slug":"oruc-aruoba","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/anlama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazılamayan Zaman', 'yazilamayan-zaman-oruc-aruoba-c4phl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Herşeyi yazarım da

zamanı yazamam-

o yazar çünkü

beni.

Yazar beni

yavaş yavaş

özenli-

azalta azalta

görkemli-

sanki

dolduracakmış

olduracakmış

gibi.

Halbuki

sıyırıp düşürmüştür

tırnağımdaki çürüğü

parmağımdaki yarayı

kabuk kabuk

geçirmiş-

geçerken, sanki

çoğalta çoğalta

yazarak

beni: 

özenli

görkemli.', 'Herşeyi yazarım da zamanı yazamam- o yazar çünkü beni. Yazar beni yavaş yavaş özenli- azalta azalta görkemli- sanki dolduracakmış olduracakm...', ARRAY['Türk Edebiyatı','Şiir','Oruç Aruoba']::text[], 8.5, '{"poet":"Oruç Aruoba","poet_slug":"oruc-aruoba","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yazilamayan-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hangi mevsimin yağmurusun?', 'hangi-mevsimin-yagmurusun-yasar-aslan-ophyt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hangi mevsimin yağmurusun? 

Böyle derin yıkıntılar bırakan, 

Kor bir ateş, 

Yangın, 

Kasıp kavuran

Tadına doyamadığım karanfil kokulum, 

Yüreğime ektiğim zehir tohumum, 

Hoyrat esen rüzgar, 

fırtınam, 

afetim, 

Paramparça olmuş hüzün tarlası

Kan tarlası gelincik şafağı 

Mevsimsiz çiçeğini özler...', 'Hangi mevsimin yağmurusun?  Böyle derin yıkıntılar bırakan,  Kor bir ateş,  Yangın,  Kasıp kavuran Tadına doyamadığım karanfil kokulum,  Yür...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Aslan']::text[], 8.5, '{"poet":"Yaşar Aslan","poet_slug":"yasar-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hangi-mevsimin-yagmurusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden', 'neden-mehmet-nuri-hasar-5mdgl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Neden bir kavga gibi seviyorum seni, 

Bir miting de gibi, faşizme ve emperyalizme karşı.

Bağrı yanık, bilinçsiz ve köle ruhlu halkım gibi.

Günahsız çocuklar gibi.Aydınlık okuyan gençler gibi

Anadolu’m gibi.

Neden bir atın koştuğu gibi doludizgin.

Ve bir yelkenli gibi rüzgarın önünde uçarak, 

Nerdeyse doğuracak bir bulut gibi, 

Yumruğunu kaldırmış dağlar ve sahibini bekleyen umutlar gibi.

Anam gibi.

Neden bekliyorum seni, gözü açılmadık kuş palazı gibi.

Neden bir karabaşın bir çocuğu beklediği gibi, 

Mısrasını bekleyen dudaklar, notasını bekleyen besteler gibi, 

Lokman hekimin gelmesini isteyen hastalar gibi.

Bacım gibi.

Aslı’yı seven Kerem gibi, Leyla’yı seven Mecnun gibi.

Altınlarını seven Karun gibi, bacısını seven Habil gibi.

Suyu seven toprak gibi, güneşi seven yaprak gibi, pulluğu seven harım gibi.

Hiç kavuşamadığım, saçlarına güller takamadığı yarim gibi.

Anadolu’m  gibi, Anam gibi, Bacım gibi, KARIM GİBİ.', 'Neden bir kavga gibi seviyorum seni,  Bir miting de gibi, faşizme ve emperyalizme karşı. Bağrı yanık, bilinçsiz ve köle ruhlu halkım gibi. G...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Nuri Haşar']::text[], 8.5, '{"poet":"Mehmet Nuri Haşar","poet_slug":"mehmet-nuri-hasar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/neden-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kupa Kızı', 'kupa-kizi-mehmet-nuri-hasar-i2wzo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Neden yoksun sen briç kağıtlarında

Yoksa burada ki 4 kızda sen misin göremiyorum ben.

Tam doğru empası attım derken ben kupa valeyle

İllede koltuk altından çıkmak zorunda mısın kız.

Yakalayacağım seni bir gün, empsta.Parmaklarımı kütürteceğim önce

Sonra bağlayacağım zonu bir fazlayla.

Elliikiden çekip seni sonra, tutacağım saçından.

Ver elini adıyan çayı.

Heey Adıyan çayı Adıyan çayı

Kafanı kaldır.Kupa kızını getirdim sana.

Bakma Belden aşağısının olmadığına

Pek sivri dillidir.At oradan iki sazan bir turna.

Kapatalım ağzınıda güzelliğini seyredelim doyunca.

1999 ocak', 'Neden yoksun sen briç kağıtlarında Yoksa burada ki 4 kızda sen misin göremiyorum ben. Tam doğru empası attım derken ben kupa valeyle İllede ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Nuri Haşar']::text[], 8.5, '{"poet":"Mehmet Nuri Haşar","poet_slug":"mehmet-nuri-hasar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kupa-kizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönüşüm', 'donusum-mustafa-altay-sonmez-a5d51', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Pek çok seneler giydim bu düz çizgili, uzun pantolonu

yani bacaklarım uzundur ona göre

ve takmışımdır koni biçimli tuhaf şapkamı-çok şükür

takmışımdır-

artık adım atmanın zamanı geldi sanıyorum

işte oturduğum yerden, 

üzülüyorum ya da korkuyorum

çünki oturmamla yüzyıldır başka bir şeye dönüştüm

-böceğe değil, hayır-başka bir şeye

rahat deri koltuğuma-ki bunca yılın kazancıdır-

yığılmış aynı hacimli bir pembe pudinge.

(biçimsiz  olduğu için öyle dedim, biliyorum-pembe puding biçimsizdir-ve ben de öyle olduğım için ki yani kendimi pembe pudinge benzettim.) 

Küçüklüğümde eriyip yoğunlaşan yıldızlarına

            bakardım gökyüzünün

ondan sonra böyle güzel hiçbir şey düşünmedim

ya da sıkıcı bir yaşam içinde en çok

güzel olduğunu tahmin ettiğim şeyleri bekledim

ben ki rahat deri koltuğuma gömülmemle bir...

Pantolonum  ütülüdür, gömleğim gibi tıpkı

yaşlı ve eskiyimdir ona göre

ve çalışmışımdır masalar üstünde, masalar

dışında-ne zaman  hayal etsem masalar dışında-

defterler tutmuşumdur

yani artık yürümeyi unuttuğuma göre 

öyleyse geç kaldım-olsun kalmışımdır.', 'Pek çok seneler giydim bu düz çizgili, uzun pantolonu yani bacaklarım uzundur ona göre ve takmışımdır koni biçimli tuhaf şapkamı-çok şükür t...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Altay Sönmez']::text[], 8.5, '{"poet":"Mustafa Altay Sönmez","poet_slug":"mustafa-altay-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/donusum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bilsen', 'bir-bilsen-melek-midikoglu-ske18', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kırmızıya kızıl serptim

Ruhuma seni...

Okyanus kadar istedim de

Kaç kere aldım cemalini

Bir bilsen hayalimle! 

Nafile yetinemedim 

Acının acısı var içimde

Karışmış hasretimle...

Yollar tuzak, sil buralardan 

Uzaklar kalbe yasak, 

Koş gel sabahlara...

Gün doğacak  batacak, 

Biliyorum can doyacak...', 'Kırmızıya kızıl serptim Ruhuma seni... Okyanus kadar istedim de Kaç kere aldım cemalini Bir bilsen hayalimle!  Nafile yetinemedim  Acının ac...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-bilsen-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Supradyn', 'supradyn-yusuf-karaman-6atao', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'I.

(Hipokrat yeminlerini konuşurduk

sallanırdı medeniyyet demokrat kravatlarımızda) 

II.

Ey ceplerime iğdeler karıştıran sevgilim

düşlerimizin kamaştığı bu çarşıda

perişan bir şarkıyla yürünür mü? 

pazartesiyi bekleyen memurlarız artık

sabrımız bir dahaki –ertesiye kadar; 

Oulu caddesinde yüzüme bakmıştın, gözlerime

utandım; bütün kitaplar orada bitecek sandım.

Demek ki

ağır bir yenilgiyi yaşayıp bitmek değilmiş

sabahın ağzında kandilleri yakan bir adam olmak.

III.

Bitmek...

nasıl da barıştırıyor içinde kan ve kurşun

ellerimi geceye vuruyorum

yüzümü kopartarak kitaplara

devrilip bitsin devrilip bitsin diye

Şili de bağbozumu ne zaman kimin umurunda.

IV.

Sevgilim

Oulu caddesinde hoyrat bir kız entarisi değilim artık

saçlarımı latin bir kelimeyle taradığım doğrudur

pencereni kırıp kaçtığım da

ama yürekten kurumuş bir ırmak da değilim

o bekçi düdüğünü üflemeden

bana bir şeyler söyle

beni pencerenden içeri al

beni –ertesiye, bitmeyen geceye bırakma

bir Supradyn olarak gir boğazıma...', 'I. (Hipokrat yeminlerini konuşurduk sallanırdı medeniyyet demokrat kravatlarımızda)  II. Ey ceplerime iğdeler karıştıran sevgilim düşlerimiz...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Karaman']::text[], 8.5, '{"poet":"Yusuf Karaman","poet_slug":"yusuf-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/supradyn-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asfalt, Oksijen, Kanser', 'asfalt-oksijen-kanser-yusuf-karaman-ibu16', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ekim ayları gelince bulaşıklar, sesler ve ötekiler

böbreklerimizden sızarak buzlu bir sabah bırakırlar üstümüze

hatırlarız orda kıravatlarımızla

bin çocuk ezikliğinden yapılma kalıntılarımızı.

Asfalt ki ayıplamıştır bizi

siyah, geceli, ışıksız bir kadının ardından.

rüzgar ne zaman değmişse yelelerimize

asarak bağrışların ortasında kumdan gözlerimizi

çertlemeklerden, leylek ayağından umutlarımızı.

Şarkılar

şakırtılar arasında büyüdük

alnımızda tebeşirler beyaz bir ölümle öldüler

göğsümden kelcebekler kanatlanmıyor artık

patikalar taşmıyor düğmelerimden.

Koridorlara varınca hatırladık herşeyi; 

hepimiz; 

esrarlı ama kırılgan bir türküyüz şimdi

kırlangıçlar yumuşatırdı umutlarımızı

sarı bir depremle göçtüler saçaklarımızdan.

Hatırlamak; 

yetmiyor. Kirli bir ölümleyiz çünkü.

Sana

bunun için harlıyım, 

omzum ıslak

Islak elbiseler içindeyim bunun için

kabarsam göğsüm erişmez, 

uzaksın

boynum desem homurtulu bir iple boğuşmakta.

Bana zor

zorlu bir üfleyişle getir yanaklarını

kekikten, 

ıhlamurdan kokularla 

gri

ıslak

bir sabahta gel

ki şehir yorgunluklarını

Sana vermesin...', 'Ekim ayları gelince bulaşıklar, sesler ve ötekiler böbreklerimizden sızarak buzlu bir sabah bırakırlar üstümüze hatırlarız orda kıravatlarım...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Karaman']::text[], 8.5, '{"poet":"Yusuf Karaman","poet_slug":"yusuf-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/asfalt-oksijen-kanser-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürüp Gelen Kavgadan', 'surup-gelen-kavgadan-yusuf-karaman-nqql0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dokunsalar

dağınık suları toplamaktan çıplak

bir sası akşamdır yürek.

Oradan, kartalların göğünden

kuyudan çıkmış bir isimle kovulanım

ürkek çocuk kanatlarından

bir tutam başakla

bir sarı tebessümmüş kopartıp aldığım

düş-müş

anlayamadım.

Bak

kırmızı bir suyla doymuyor bu sası akşam

aşksa

tanıdık bir yüz değil artık buralarda

seçilmiş adamların damıttığı bir iksir

öp ki uyansın gecenin hışmından kıyametim

öp ki korkunç bir ağustos tutsun gövdemi

geceden sakındıracak bir düş taşımıyorsa yürek

aşk niçin

doktor...', 'Dokunsalar dağınık suları toplamaktan çıplak bir sası akşamdır yürek. Oradan, kartalların göğünden kuyudan çıkmış bir isimle kovulanım ürkek...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Karaman']::text[], 8.5, '{"poet":"Yusuf Karaman","poet_slug":"yusuf-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/surup-gelen-kavgadan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Yürüyüşleri', 'i-nsan-yuruyusleri-yusuf-karaman-a984s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Baktım, 

bulanık, durmadan kasılan benim nefesim.

Sesime vurgun gibi gerilip duran

insan yürüyüşleri arasından

bir kuşku mu ne gelişen kasılarak

Ben ki daha suvarmadan duruşumu

hangi depreşen çılgınlıklarsınız.

Çünkü

Gün boyu ağlayan yağmurlar ve çocuk elleri

azgın bir gebelikle yakalayacaktır

kılıçsız girilen cumartesilerde

döşümde kurşun taşımayan herkesleri.

Bir serinlik yani sabah kuşu gibi bağrımda

herkeslerin duruşları vardır

duruşları; apansız gürleyen

olur olmaz karışıklıklarda unutulup söndürülen.

O en sessiz yerinden fırlayıp duran

Eylül’ün simsar yüzünü görmeye gidiyorum, 

cebimde son kalebent taşını düşürme planları

bir de

ağır dizlerime parıltıyla düşen çocuk

ki seni gören gün kaçar, gece durulur

en çok seni anlarsak

dibinde gür bir cehennemin

Sen artık bir gölgesin gel.', 'Baktım,  bulanık, durmadan kasılan benim nefesim. Sesime vurgun gibi gerilip duran insan yürüyüşleri arasından bir kuşku mu ne gelişen kasıl...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Karaman']::text[], 8.5, '{"poet":"Yusuf Karaman","poet_slug":"yusuf-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/insan-yuruyusleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Biz', 'sana-biz-yusuf-karaman-4ya8k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne telaşlı ve şaşırtan bir aşktır benimkisi

Seni geniş ve hünerli kılan

o birden dönerek erdiğin

duran ve kıpırdayan herşeyde zonklayan...

Senden bana dokunup konuştukların kaldı

içimde bin yemin denemesi; 

şaşırtan, öksürten ve boğan.

Şehrin, Senin gibi taa içindeyim

fakat insanın en kıyısında, 

Senin, bakışlarıyla yoğrulduğun O nurdan; 

ne sıvazlayan bir el ne de fotoğraflarım var.

Seni kapıya götüren öfkeyi öğrendim

Sana merhaba diyeni de.

Nasıl da dönmüştün oradan ağlayan yüreğinle

sonra, durup dört köşesine, hayata öyle baktın ki

hangi şehirden geçtiyse gözlerin

en duru ve sağlam yürekler o zaman fışkırdı

ve biz Sana Hattab''ın oğlu dedik.

Ben de şaşkın bir yürek değil miyim

üstelik bu kahrolası yerde; 

elsiz, fotoğrafsız ve rüyasız.', 'Ne telaşlı ve şaşırtan bir aşktır benimkisi Seni geniş ve hünerli kılan o birden dönerek erdiğin duran ve kıpırdayan herşeyde zonklayan... S...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Karaman']::text[], 8.5, '{"poet":"Yusuf Karaman","poet_slug":"yusuf-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sana-biz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçuk Suçlar', 'ucuk-suclar-yusuf-karaman-jzvtg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yakarışlarımdan doğan huylarımla birlikteyim

taşlarla konuştuğum günler geride kalmıştır

şimdi dinelmek vaktidir

asma bahçelerine karşı Babil’in.

Bir atın kişnemeleriyle uyandım genç düşlerimden

binlerce sesle girdiğim bu dehlizden

ayartılarak çıkmalıyım önce

ilk ben doğacak kadar ergen

okyanusa yürüyecek kadar cesaretim olmalı.

Şairleri inkar ederek başladım şiire

sonbahara yaşama sevinci diyen ilk benim

şimdi ben bir çocuğu öpersem

iğneler bırakırım kirpiklerine

uçuk suçlar taşır çünkü dudaklarım.

Tıpkı halet’i ruhiyesi içindeyim boğazların

gemiler yanaşıyor kıyılarıma, yanaşmalı bakışlar

demir atılıyor dişlerime, platinden

içime gömülmeliyim, sonra bir hortumla göğe çekilerek

kurmalıyım kendimi dişlerim sökülmeden.

Sınıfımı

piramitlere dair öykülere inanmadan geçtim

edebiyat derslerinden kalma birkaç tanımla

sağır bırakıldım kuşlu bakışlara.

Bir akşam

akşamın kıskançlığın rağmen

tünediğimde avurtlarıma

yanıp söndü içimdeki çağıltılar

oysa ben

hayata dair manalı sözler duymuştum.', 'Yakarışlarımdan doğan huylarımla birlikteyim taşlarla konuştuğum günler geride kalmıştır şimdi dinelmek vaktidir asma bahçelerine karşı Babi...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Karaman']::text[], 8.5, '{"poet":"Yusuf Karaman","poet_slug":"yusuf-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ucuk-suclar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Günlükten Acı Koylar', 'son-gunlukten-aci-koylar-zeynel-abidin-toprak-hf8fm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sevda düşmüş yürek dağından

Paramparça bakar yüceliklere.

Nefese duyulan sonsuz hasretle, 

Bir deniz dibinde, vazgeçmek candan.

Gökyüzü çapında yürümek gibi

Emeklemek gibi akkor zeminde, 

Umutla boşluğa sarılmak gibi, 

Toplamak gibi elsiz kollarla.

Islak bir ölüm, kuru hayatın, 

Önünde yürür de kaybolur anlam

Nedeni bilinmeyen bir derin çığlık, 

Kulaklara değmeden yükselir göğe.

Bu anlaşılmazlık, bir sır kalacak, 

İnsandan insana hiçlik geçecek.

Bir isim koymaya insan mı yeter? 

Bir ölüme hayat, yenilmedikçe.

Dünya kayıtlarında boşluk kalacak.', 'Bir sevda düşmüş yürek dağından Paramparça bakar yüceliklere. Nefese duyulan sonsuz hasretle,  Bir deniz dibinde, vazgeçmek candan. Gökyüzü ...', ARRAY['Türk Edebiyatı','Şiir','Zeynel Abidin Toprak']::text[], 8.5, '{"poet":"Zeynel Abidin Toprak","poet_slug":"zeynel-abidin-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/son-gunlukten-aci-koylar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuza Sesleniş', 'sonsuza-seslenis-zeynel-abidin-toprak-e3pu9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Artık beni, sonsuzluğun ardındaki ulaşılmazlıkta ara.

Ben, görme şansının olmayacağı yerdeyim.

Beni, henüz olmayan bir evrenin girişinde bekle

Ve anla yitirdiğin aşkın uçuşunu.

Bedelsiz bir sevgiyi tepmenin ağır bedelini.

Bulutlaradan ağlama iste kendin için

Geçmişte kalan mutlu günleri an

Ve bir daha geri iste o günleri

Gelmeyeceğini bile bile...

Susadıkça geçmişe, 

Yüreğindeki pişmanlık pınarından iç, 

Uykusuz gecelerine yeni karanlıklar ekle.

Gülmeyi unutmak varmış sevinmeyi anamamak...

Acıyı yutkunmak varmış, sevgiliyi anlamamak...

Sen kendine yetmeyeceksin biliyorum.

Ben olmadıkça sen hep var olacaksın 

Ve var olduğun yerde ben olmayacağım.

Yok olmayı istemek varmış, hayatı aşmak.

Canı salıvermek varmış, zamanı taşmak...

Susmak varmış sesizce bir serzeniş

Ve haykırmak varmış, sonsuza bir sesleniş....', 'Artık beni, sonsuzluğun ardındaki ulaşılmazlıkta ara. Ben, görme şansının olmayacağı yerdeyim. Beni, henüz olmayan bir evrenin girişinde bek...', ARRAY['Türk Edebiyatı','Şiir','Zeynel Abidin Toprak']::text[], 8.5, '{"poet":"Zeynel Abidin Toprak","poet_slug":"zeynel-abidin-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sonsuza-seslenis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Nöbetleri', 'sevda-nobetleri-zeynel-abidin-toprak-c29e1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Atlasına aşkımızı çizdiğim, 

Dört mevsimim hayal oldu sevdiğim.

Senin için buluşmaya seçtiğim, 

Bütün yerler harap olmuş sevdiğim.

Aşkın ile ıslattığın gözlere, 

Şimdi neden bakmıyorsun sevdiğim? 

Cıvıl cıvıl söyldiğin sözlere, 

Dilin neden yabanıldır sevdiğim? 

Bu aşkı ben sonsuzluğa yazmıştım, 

Sonsuzluğun sonu bu mu sevdiğim? 

Bin sevinçle sevgine can katmıştım, 

Cana hicran kısmet olmuş sevdiğim.

Anılardan aklım zail olurken, 

Sen çoktandır unutmuşsun sevdiğim.

Geçmişinle, bir teselli bulurken, 

Sen bir başka bahardasın sevdiğim.

Her halimden sana benden çağrılık

Uçuşurken görmüyorsun sevdiğim.

Dudağımda adından bir kor çığlık, 

Koparken hiç, duymuyorsun sevdiğim.

Hani bir gün gözlerine dalarken, 

''Bakma öyle'' demiştin ya sevdiğim.

O sözcüğü duymak için yeniden, 

Arar durur o gözleri sevdiğim.

Ben acıyı satır satır yazarken, 

Sen kimbilir neredesin sevdiğim.

Hayalinden aşk, ruhuma sinerken, 

Sen nisyana aldın beni sevdiğim.

Seni ben hiç görmemiş gibi olsam, 

Kuşlar kadar özgür olsam sevdiğim.

Düş gördüğüm olsaydı da uyansam.

Her şey rüya olsaydı, ah sevdiğim.

Biliyorum bütün aşklar isimsiz, 

Sana şiir yazılmıyor sevdiğim.

Can, ölüme göz kırpıyor çaresiz, 

İlacı yok bu acının sevdiğim...', 'Atlasına aşkımızı çizdiğim,  Dört mevsimim hayal oldu sevdiğim. Senin için buluşmaya seçtiğim,  Bütün yerler harap olmuş sevdiğim. Aşkın ile...', ARRAY['Türk Edebiyatı','Şiir','Zeynel Abidin Toprak']::text[], 8.5, '{"poet":"Zeynel Abidin Toprak","poet_slug":"zeynel-abidin-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sevda-nobetleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Aşkın Zehirinde Geceler', 'bir-askin-zehirinde-geceler-zeynel-abidin-toprak-p7wht', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiçbir yıldız onun kadar uzak değil bana, 

Hayalinin içimdeki yakınlığına inat.

Gecenin neresindeyim? 

Sabahı nerede katletmiş gece? 

Biri, bu parça yüreği alsın benden, 

Alıp o sevgilinin avuçlarına bıraksın.

Nasılsa yanmayacak buna, 

Nasılsa atacak bir köşeye.

Biri gecelerimi götürsün O’na, 

Nasılsa görmeyecek içinde beni, 

Sabahına katmayacak gecelerimi.

O’na sözlerimi götürün/şiirlerimi, 

O’na sayıklamalarımı götürün, 

Bakışlarımdaki merhamet dilenişini.

O’na en acıklı ''yeter! '' çığlığımı götürün, 

Nasılsa duymayacak.

O’na beni götürün sonra, 

Nasılsa görmeyeceğim o sevgiliyi, 

Geç kalmış olacağım sabahı görmeye, 

O’nu görmeye en yakın yerden, 

Sonsuza kadar uzaklaşmaya, 

Başlamış olacağım, 

Götürün beni.', 'Hiçbir yıldız onun kadar uzak değil bana,  Hayalinin içimdeki yakınlığına inat. Gecenin neresindeyim?  Sabahı nerede katletmiş gece?  Biri, ...', ARRAY['Türk Edebiyatı','Şiir','Zeynel Abidin Toprak']::text[], 8.5, '{"poet":"Zeynel Abidin Toprak","poet_slug":"zeynel-abidin-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bir-askin-zehirinde-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bileydin Beni', 'bileydin-beni-zeynel-abidin-toprak-c755n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayalini ruhuma döşeyip uçtun, 

Ne unutmak var ne de kurtulmak.

Aşklar aşkımı dinler, sevdalar suskun, 

Zehirden anıların ruhumda sağnak.

Gelmeyecek gibisin, bana, inatla

Ve çıkmayacak gibi, kalpten hayalin

Bir an yaşasaydın da, benim aşkımla

Bir ömür ödeşseydik, beni bileydin.

Heykelim bir zalimin ruhu peşinde

Her görünmeyen yerde bir ben yaşarım.

Gecenin kapkaranlık sessiz sesinde, 

Apaydınlık sesleri bir ben aşarım.', 'Hayalini ruhuma döşeyip uçtun,  Ne unutmak var ne de kurtulmak. Aşklar aşkımı dinler, sevdalar suskun,  Zehirden anıların ruhumda sağnak. Ge...', ARRAY['Türk Edebiyatı','Şiir','Zeynel Abidin Toprak']::text[], 8.5, '{"poet":"Zeynel Abidin Toprak","poet_slug":"zeynel-abidin-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bileydin-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş Ayalar', 'bos-ayalar-zeynel-abidin-toprak-0zqq8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşkı, düşmüş pencereme, 

Payıma görmek düşmüyor.

Yüzü, düşmüş göz rengime, 

Varlık, göze görünmüyor.

O’nu yolda gördüm de ben, 

Bir kelime konuşmadım.

Bana bakmadan giderken, 

''Neden? '' diye soramadım.

Ayrılıktan çektiğimi, 

Vicdanına seremedim.

Kaynar zehir hislerimi, 

Arzetmeden geri geldim.

Bir avuçta sevgi vardı, 

Diğerinde acılarım.

İkisini karıştırıp, 

Bir deli rüzgara saldım.', 'Aşkı, düşmüş pencereme,  Payıma görmek düşmüyor. Yüzü, düşmüş göz rengime,  Varlık, göze görünmüyor. O’nu yolda gördüm de ben,  Bir kelime k...', ARRAY['Türk Edebiyatı','Şiir','Zeynel Abidin Toprak']::text[], 8.5, '{"poet":"Zeynel Abidin Toprak","poet_slug":"zeynel-abidin-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bos-ayalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Nöbetlerinde Zaman', 'ayrilik-nobetlerinde-zaman-zeynel-abidin-toprak-6nusw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Elyafını eğirdiğin aşkının, 

Mintanını giyinmiştim ruhuma, 

Deli deli tutulduğum sevdanın, 

Teması bir ayrılıkmış bahtıma.

Yaz gelince yeşil ölür, anılar; 

Yeşeriyor, açılıyor yaralar, 

Gün bitmiyor, gece durur ve yıllar; 

Tek saate sığışıyor, dilnihal.

Aynalarda görünmüyor duygular, 

Anlatılmaz, anlaşılmaz bu aşklar, 

Deli eder, yürek dağlar, can yakar, 

Hücrelerim parçalanır, dilnihal.

Anıldıkça adın, aklım uçuyor, 

Kalbe derin bir ıstırap sızıyor, 

Damarımda dolaşan kan donuyor, 

Durgun canda, aşk azıyor dilnihal.

Anladım ki aşka galip gelinmez, 

Tanımı da sınırı da bilinmez, 

Bir başkadır şekil, zaman verilmez, 

Allah’tandır, el ve duâ dilnihal...', 'Elyafını eğirdiğin aşkının,  Mintanını giyinmiştim ruhuma,  Deli deli tutulduğum sevdanın,  Teması bir ayrılıkmış bahtıma. Yaz gelince yeşil...', ARRAY['Türk Edebiyatı','Şiir','Zeynel Abidin Toprak']::text[], 8.5, '{"poet":"Zeynel Abidin Toprak","poet_slug":"zeynel-abidin-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ayrilik-nobetlerinde-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Demlenen Ömür', 'aska-demlenen-omur-zeynel-abidin-toprak-62z0v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevdam, yüreğinde üşürken, 

Denizler yanıyor bakışlarımdan.

Yalnızlığın kalabalığına karıştığı gibi sensizliğim; 

Yokluğunun sesine karıştı sessizliğim.

Ellerimde kalan; 

Ayrılık acıları

Ve duygularımın dokusundaki bir tek hayalin.

Rüzgarın dokunuşları alnımın ateşini alırken; 

Islak gözlerim üşüyor bu sabrın buzulundan.

Zaman dışı saatleri kim anlar ki söylesem? 

Çiçekler tutuşturulmuş ayrılığın eline.

Ve bir yokluk yakamozu düşmüş gönül nehrine.

Gökyüzüne düşen gecelerimden alınmış sabah, 

Artık, yalnızlığım doğuyor güneş yerine.

Sesinin yankısıdır bu isimsiz çığlığım, 

Hasretin buharıdır bütün bulutlar.

Duyamazsın beni duymayacaksın; 

Çünkü acılarım kadar sevinçlerin var.

Bense, elime verdiğin bir bardak zehrin; 

Ölümünü yaşıyorum an be an sana.

Sana, can çekişimin her saatini, 

Armağan ediyorum, son nefese kadar.

Bin ömür mutlu olmana yetecek kadar

Bir acılı ömür yokoldu sana...', 'Sevdam, yüreğinde üşürken,  Denizler yanıyor bakışlarımdan. Yalnızlığın kalabalığına karıştığı gibi sensizliğim;  Yokluğunun sesine karıştı ...', ARRAY['Türk Edebiyatı','Şiir','Zeynel Abidin Toprak']::text[], 8.5, '{"poet":"Zeynel Abidin Toprak","poet_slug":"zeynel-abidin-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/aska-demlenen-omur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyiş', 'bekleyis-zeynel-abidin-toprak-k4fyn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Heyecanla dokuduğum, büyük umut aşk sayfası, 

Zamana silinip gitti, kalan; bir alın yazısı.

Geçmiş nerde konaklamış, geçmişe gidiş olsaydı, 

Seninle o eski günler, tekrar yaşanır olsaydı.

Rüya görsem o rüyada, koşarak gelişin olsa, 

Elin elimde uyansam, sonra rüyam gerçek olsa...

Acı dolu gözlerimi, sevinçle sana açsaydım, 

Ayrılıkta çektiğimi, bir bir sana anlatsaydım...

Çıkmıyor bu acılarım, karanlıklardan sabaha

Oysa imkansız sandığım, her dilek, kolay Allah’a', 'Heyecanla dokuduğum, büyük umut aşk sayfası,  Zamana silinip gitti, kalan; bir alın yazısı. Geçmiş nerde konaklamış, geçmişe gidiş olsaydı, ...', ARRAY['Türk Edebiyatı','Şiir','Zeynel Abidin Toprak']::text[], 8.5, '{"poet":"Zeynel Abidin Toprak","poet_slug":"zeynel-abidin-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bekleyis-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Satırlarımda Saklı Sevdam', 'satirlarimda-sakli-sevdam-fahrettin-ustun-xx6jp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şiirler yazdım sevdaya dair

Harfler kelimelerle oynaştı sesler kayboldu utanmadan

Dağlarda sevdam kaldı yalnız ve sensiz

Yağmurda ıslandım seni düşleyerek; sırılsıklamım zaten

Satırlarda kaldı sevdam zaten, şiirler sırdaşım oldu

Belki pişmanlığım...

Bilmezsin bilemezsin şiirlerdeki avuntumu 

Sevdamı bilmezsin, seni nice sevdiğimi 

Satırlarımda gizli, şiirlerimde gizli', 'Şiirler yazdım sevdaya dair Harfler kelimelerle oynaştı sesler kayboldu utanmadan Dağlarda sevdam kaldı yalnız ve sensiz Yağmurda ıslandım s...', ARRAY['Türk Edebiyatı','Şiir','Fahrettin Üstün']::text[], 8.5, '{"poet":"Fahrettin Üstün","poet_slug":"fahrettin-ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/satirlarimda-sakli-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kime Ne..?', 'kime-ne-nilgun-akcay-ow9ov', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine sabah..Yine yanlızlık..

Güneşle başlıyor hareket.

Herkeste özlenen bereket..

Güneş doğmuş, sabah olmuş...

Saat üç olmuş, beş olmuş...

Bunlardan bana ne....

Ağlamışım.Gülmüşüm...

Bunlardan Kime ne..?', 'Yine sabah..Yine yanlızlık.. Güneşle başlıyor hareket. Herkeste özlenen bereket.. Güneş doğmuş, sabah olmuş... Saat üç olmuş, beş olmuş... B...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Akçay']::text[], 8.5, '{"poet":"Nilgün Akçay","poet_slug":"nilgun-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kime-ne-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım', 'canim-ramazan-ceyhan-kmr7g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Canım dediklerim canımakıydı

Gözüm dediklerim gözümü oydu

Enyakın dostum beni sıtımdan vurdu

Sevdigim kadını elimden adı

Şimdi tek dostum kadehler kaldı

Onlarda beni sonunda terketti

şimdi dosus yanlız kaldım 

Bobboş sokaklarda yürüyorum 

sonunda neolacagını bilmiyorum 

yanız kaldın sonunda yanlız

sevdigimi arıyorum yürüyorum

yürüyorum bobboş sokaklarda', 'Canım dediklerim canımakıydı Gözüm dediklerim gözümü oydu Enyakın dostum beni sıtımdan vurdu Sevdigim kadını elimden adı Şimdi tek dostum ka...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Ceyhan']::text[], 8.5, '{"poet":"Ramazan Ceyhan","poet_slug":"ramazan-ceyhan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/canim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle Bana', 'soyle-bana-tuncay-emrem-of6km', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Söyle bana, 

Gecelerin derinliğinde ne saklı? 

Neden korku verir egzotik ağaçlar, 

Ve bu zehir yeşili, 

Yılan dili dallar? 

Sor bana, 

İnsan ne zaman ölür? 

Eğer yüreği taze, fakat elleri çürümüşse..

Ve gövdesine kırgınlıklar, 

Böcekler misali üşüşmüşse? 

Anlat bana, 

Kızgın çöllerde yaşayan çalılardan..

Fakat neden kurudu, 

Bahçemdeki manolya..

Nasıl oldu bilmem, 

Tablomdaki renkler karıştı birbirine.

Seçemiyorum.

Yaşamaya hazırlanıyorum hergün yeniden, 

Beceremiyorum.', 'Söyle bana,  Gecelerin derinliğinde ne saklı?  Neden korku verir egzotik ağaçlar,  Ve bu zehir yeşili,  Yılan dili dallar?  Sor bana,  İnsan...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Emrem']::text[], 8.5, '{"poet":"Tuncay Emrem","poet_slug":"tuncay-emrem","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/soyle-bana-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendime', 'kendime-derin-deniz-o467c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kendin için seviyorsun... 

biliyorsun aslında tek kişilik bu dünya 

söylediğim tüm yalanlar beni kandırdı oysa 

küçük umutlar birikti 

soldu 

birleşmeden 

şimdi soruyorsan yalnızlığı 

bu kimin suçu? 

eski masalar gibi eskimiş rüyalarım 

benim sevdiğim eski bir festivalde şimdi 

hiç görmemiş gibi aç 

biraz utangaç ve naçar 

eskiden kalma bir mezar oluyor gelecek 

yenemedim yenilmiyor silemedim hatıraları silinmiyor 

eskiye bir özlem hiç eskimeyen 

şimdi rüyalarım kendime arkadaş 

sönüp kayan bir yıldız 

ah yıllarımız 

eski bahçe oyunlarından kalma yaralarım 

kanayan kollarımda 

teri hâlâ üzerimde yırtık önlüğümün 

eskimişiz günden güne 

küçücük hikayelerle ulaşılamamakmış hayat 

neydi oysa kandırılış gerçeği cümlelerin 

yerinde durmayan bir hayat bırakırım geriye 

yani bir hoşça kal kardeşim 

yeniliyor bu hayat çaresizlik karşısında 

yenilen hayat 

kaybeden ben oluyorum mevsim sonlarında 

şiirime isim oluyorsun 

ben isimsiz kalıyorum 

sen sessizlik olurken ben çığlık oluyorum...', 'kendin için seviyorsun...  biliyorsun aslında tek kişilik bu dünya  söylediğim tüm yalanlar beni kandırdı oysa  küçük umutlar birikti  soldu...', ARRAY['Türk Edebiyatı','Şiir','Derin Deniz']::text[], 8.5, '{"poet":"Derin Deniz","poet_slug":"derin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kendime-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarımsamalar Ve Yanılsamalar', 'yarimsamalar-ve-yanilsamalar-derin-deniz-04s3e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Salaş akşamların yeni yetme sevdalarında bir akrep çığlığı

Uzaklara üflenmiş mısralar yarım, yarı çıplak soluklar

Martı beyazlarında, yukarıya doğru akan bir yok oluş çılgınlığı

Sabahlarım yarım.

Yarınlarımda, dünlerimde cam bulanık çalmakta neyler efkarı

Felekten çalınan bir avuç sevdanın sarhoş bakışlarında boşluklar

Bir iç kanama ölümcül, elde var sıfır, bir de küskünlüklerin kârı.

Anlarım yarım.

Basamaklarda sürünen yırtık şehirler ayaklarıma dolanıyor

Terelelli ağarışlar yapış yapış saçlarımda, saçlarım biraz da ahlaksız

Alakasız heceler cümlelerime tırmanıp manaları karalıyor

Anlamlarım yarım.

Bir akrep çığlığının yankısı sersem gecelerde hiç gereksiz.

Ödlek başkaldırışlar volta atmakta paslı karolarında yılların

Günahlara susmuş sesler, gümüş gülümsemeler öylesi yüreksiz

Yıllarım yarım.

Oysa. bir tutam martı sesi, hasrete mahkum ruhuma nasıl da iyi gelecek

Hasretin haritası yok, ne de hayatın pusulası ya da aşkın rotası

Bir tek çaresi var uzak bekleyişlerin, hırçın saatlere inat sevdam gelecek.

Onsuz anlarım, anlamlarım, yıllarım yarım...', 'Salaş akşamların yeni yetme sevdalarında bir akrep çığlığı Uzaklara üflenmiş mısralar yarım, yarı çıplak soluklar Martı beyazlarında, yukarı...', ARRAY['Türk Edebiyatı','Şiir','Derin Deniz']::text[], 8.5, '{"poet":"Derin Deniz","poet_slug":"derin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yarimsamalar-ve-yanilsamalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelepir', 'kelepir-derin-deniz-xhi9d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kelepir mutluluklar satılır dükkanlarda, 

Üstüne uysun uymasın, ucuz diye aldığın, 

Bir iki kullanıp sonra kenara attığın. 

Sadece güz geldiğinden değil, 

Sararmış yapraklar gibi insanların seli. 

Oradan oraya rüzgarla savrulan sokaklarda. 

Soluk yüzleri kadar, kararmış içleri, 

Anlık zevklerde, kelepir mutluluk peşinde. 

Seri sonu ya mutluluklar, 

Ucuz olduğundan kapış kapış satılır. 

Peki ya yeşermeyeceğini bilerek, umutsuz, 

Sadece güz geldiğinden aşk mı yaşanır? 

Olsam da tarifaiz çelişkiler içinde, 

Amaçlı yürüdüm tek başıma, 

Kuru kalabalığın ta içine. 

Öylesine bir sonbahar işte, 

Kurumuş bedenim anlık zevkler, 

Kapkara yüreğim seri sonu mutluluk peşinde...', 'Kelepir mutluluklar satılır dükkanlarda,  Üstüne uysun uymasın, ucuz diye aldığın,  Bir iki kullanıp sonra kenara attığın.  Sadece güz geldi...', ARRAY['Türk Edebiyatı','Şiir','Derin Deniz']::text[], 8.5, '{"poet":"Derin Deniz","poet_slug":"derin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kelepir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye (Sevgililer Gününüz Kutlu Olsun)', 'sevgiliye-sevgililer-gununuz-kutlu-olsun-ugur-oguz-sahin-ggcay', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gül kalbimden sana

Bugün sevgililer günü

Hadi kokla yaprakları

Ver mutluluk gülüşünü

Tomurcuksun goncasın

Her günümde açansın

Sen gönül kanaryamsın

Kalbimde şakıyansın

Gözünde kirpikler oktur

Aşkının izleri çoktur

Eşin benzerin yoktur

Gerisi yalan hep boştur

Yüreğimdeki sevda sensin

Sen ezelden sevilensin

Sanki ruh''a can verensin

Ölümüne sevilensin

Deryalarda denizlerde

Gecelerde gündüzlerde

Her yudumda her nefeste

Yaşatırsın her istekte

Sensin hayatın adı

Sensiz olmaz ki tadı

Mutluluğum hep sensin

Çünkü seviyorum seni', 'Bir gül kalbimden sana Bugün sevgililer günü Hadi kokla yaprakları Ver mutluluk gülüşünü Tomurcuksun goncasın Her günümde açansın Sen gönül ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevgiliye-sevgililer-gununuz-kutlu-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim', 'sevdim-ugur-oguz-sahin-ohc3w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben sevdim

Sevgim ki okyanuslar kadar derin

Tüm imkansızlıklara rağmen

Sevdim hâlâ yüreğimde sevgin

Ben sevdim

Bedenimde alıp verdiğim nefes gibiydin

Tüm ışıksız gecelere inat

Ruhumda dev bir deniz feneriydin

Ben sevdim

Acılarından bile haz alarak

Gelen senden gelsin dedim

Yaşadım her hüsranı içime kapatarak

Ben sevdim

Dilimde dualar içimde fırtınalar

Pişmanlık neymiş ölüm neymiş

Her şeyden öte yaşandığında sevdalar', 'Ben sevdim Sevgim ki okyanuslar kadar derin Tüm imkansızlıklara rağmen Sevdim hâlâ yüreğimde sevgin Ben sevdim Bedenimde alıp verdiğim nefes...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevdim-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzünlü Akşam', 'huzunlu-aksam-ugur-oguz-sahin-2kqcw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen yoksun bu akşam

Hüzünde masalar

Hüzünde şişeler bardaklar

Demek ki yalnız dinlenecek

Yine bu akşam şarkılar

Gözlerim yine gurbetinde

Hasrete dalacaklar

Demek ki boş bu akşam

Karşımdaki yerin

Yokluğunu

Bilmem ne kadar doldurur hayalin', 'Sen yoksun bu akşam Hüzünde masalar Hüzünde şişeler bardaklar Demek ki yalnız dinlenecek Yine bu akşam şarkılar Gözlerim yine gurbetinde Has...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/huzunlu-aksam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askıda', 'askida-oktay-avci-h9cdl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ayaklarım yerde

Ama yere değmiyorum

Çünkü astınız

Çünkü boynum ipte', 'Ayaklarım yerde Ama yere değmiyorum Çünkü astınız Çünkü boynum ipte...', ARRAY['Türk Edebiyatı','Şiir','Oktay Avcı']::text[], 8.5, '{"poet":"Oktay Avcı","poet_slug":"oktay-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/askida-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamala', 'yasamala-oktay-avci-yxp4i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevinçler paylaştıkça çoğalır

Acılar saklandıkça azalır.', 'Sevinçler paylaştıkça çoğalır Acılar saklandıkça azalır....', ARRAY['Türk Edebiyatı','Şiir','Oktay Avcı']::text[], 8.5, '{"poet":"Oktay Avcı","poet_slug":"oktay-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/yasamala-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Tabiatsın', 'sen-tabiatsin-ugur-oguz-sahin-rohn1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Unutamadım seni

Bir rüzgâr gibi çekip gidişini

Yaktın içimi

Bekledim hep yağmurla gelişini

Dokunamıyorum yüreğime

Ne zaman dokunsam bin ah ediyor

Hayalini koyuyorum önüme

Yetmiyor gerçeğini istiyor

Mor dağlara benziyor sanki

Mor halkalar gözlerimde büyüyor

Duman sarmış etrafı her yanımda tütüyor

Sabahlar oluyor ama sensiz güneş doğmuyor

Gel bütün baharlar senin için açsın

Hasretimsin sen gönlümün yağmur duasısın

Bütün çiçeklerde senin kokun var

Sen hazzına doyulmayan muhteşem tabiatsın', 'Unutamadım seni Bir rüzgâr gibi çekip gidişini Yaktın içimi Bekledim hep yağmurla gelişini Dokunamıyorum yüreğime Ne zaman dokunsam bin ah e...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-tabiatsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerekmezdi', 'gerekmezdi-oktay-avci-c87w5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Herkes güzel

Herkes dürüst

Herkes haksızlığa karşı

Herkes iyi

Herkes korkusuz

Herkes kendinin olanı alsaydı

O zaman  gerek kalmazdı tanrıya

Anlamı da olmazdı

Ve kimse tanrıya yaratamazdı.', 'Herkes güzel Herkes dürüst Herkes haksızlığa karşı Herkes iyi Herkes korkusuz Herkes kendinin olanı alsaydı O zaman  gerek kalmazdı tanrıya ...', ARRAY['Türk Edebiyatı','Şiir','Oktay Avcı']::text[], 8.5, '{"poet":"Oktay Avcı","poet_slug":"oktay-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gerekmezdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Gördün Bana', 'cok-gordun-bana-ugur-oguz-sahin-wn35y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne zaman bitecek bu acılar

Ne zaman tükenecek dertler

Başımda kara kara bulutlar

Sen varken bitmez sanırım bu kahırlar

Sevmek istedim çok gördün bana

Hep set çektin yürüdüğüm yollara

Acaba hakkın var mıydı buna

Hakkın var mıydı beni hüsrana sarmaya

Sevenin seveni üzmeye hakkı var mı

Sevgiler bu kadar ucuz kolay mı

Eğer sevgi gerçek kalplerde olsaydı

Solar mıydı çiçekler

Yaprak dökümü yaşar mıydı güller', 'Ne zaman bitecek bu acılar Ne zaman tükenecek dertler Başımda kara kara bulutlar Sen varken bitmez sanırım bu kahırlar Sevmek istedim çok gö...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cok-gordun-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçeğim', 'gercegim-ugur-oguz-sahin-7kxzo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayatın yoğunluğu sen demekti

Yaşamak seni umudu yeşertmekti

Günün her saatinde seninle olmak

Seninle birlikte

Her hayali gerçeğe dönüştürmekti', 'Hayatın yoğunluğu sen demekti Yaşamak seni umudu yeşertmekti Günün her saatinde seninle olmak Seninle birlikte Her hayali gerçeğe dönüştürme...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gercegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başı Sağolsun', 'basi-sagolsun-ugur-oguz-sahin-bcm7s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hep bizi kovalar mutsuzluklar

Kaderin yazgısı değil mi bu yaşananlar

Her kalpte yığınla kırık dökük umutlar

Ve gökyüzünü kaplamışsa siyah arzular

Nasıl yaşansın mutluluklar

Hep gecelerde hep voltalarda yalnızlık

Sönmüşse o göz bebeklerdeki ışık

Son demi yaşıyorsa nefeslerdeki çığlık

Nereye dönüp baksan her kolda sefalet açlık

Hep yarım hep kırık aşkı sevgiyi yaşamışlık

Tükettiler denizleri erittiler dağları

Söndürdüler gönüldeki volkanları

Katılaştı dondu o yürek sevdaları

Tutştu hayaller yandı gönül ormanları

Başı sağolsun herkesin

Gömdüler mutlulukları', 'Hep bizi kovalar mutsuzluklar Kaderin yazgısı değil mi bu yaşananlar Her kalpte yığınla kırık dökük umutlar Ve gökyüzünü kaplamışsa siyah ar...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/basi-sagolsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçemedim', 'vazgecemedim-habib-borekci-b5w6w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öyle bir zincir vurdun ki gönlüme

Ne aşkından ne senden vazgeçemedim

Sanki çizilmişsin  mahsun kaderime

Ne sevdandan ne senden vazgeçemedim

Derin  acılar  bıraktın  yüreğime

Bir başkası görünmez gözlerime

Benziyorsun yeni doğan güneşe

Ne yapsam da sende vazgeçemedim 

Sen unutsan da ben unutamadım

Akan göz yaşlarımı  kurutamadım

Şu virane gönlümü avutamadım

Ne aşkından ne senden vazgeçemedim', 'Öyle bir zincir vurdun ki gönlüme Ne aşkından ne senden vazgeçemedim Sanki çizilmişsin  mahsun kaderime Ne sevdandan ne senden vazgeçemedim ...', ARRAY['Türk Edebiyatı','Şiir','Habib Börekci']::text[], 8.5, '{"poet":"Habib Börekci","poet_slug":"habib-borekci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vazgecemedim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeyeceğim', 'sevmeyecegim-habib-borekci-y5z8o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kırık bir kalp bıraktın geride

Hasret kaldım  aşka, sevgiye

Acı hatıralar senden hediye

         Yoluna umutlarımı sermeyeceğim

         Bir daha kimseyi sevmeyeceğim

Her mevsimim, sonbahar oldu

Yaprağım sarardı, gülüm soldu

Senden hüzünler, miras kaldı

          Yakama çiçekleri takmayacağım

           Bir  daha yüzüne bakmayacağım

Duymadın ihanetine haykırışımı

Sonunda çatlattın sabır taşımı

Sende inkar  ettin  bana  aşkını

           Pembe hayaller kurmayacağım

           Bir daha kimseyi  sarmayacağım

Umutlarına kara perde çekildi

Kurduğun tatlı hayallerin yıkıldı

Sanki beynime kurşun sıkıldı

            Adını  bir daha anmayacağım

            Kimsenin sözüne kanmayacağım', 'Kırık bir kalp bıraktın geride Hasret kaldım  aşka, sevgiye Acı hatıralar senden hediye          Yoluna umutlarımı sermeyeceğim          Bir...', ARRAY['Türk Edebiyatı','Şiir','Habib Börekci']::text[], 8.5, '{"poet":"Habib Börekci","poet_slug":"habib-borekci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevmeyecegim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Sofrası', 'hayat-sofrasi-ugur-oguz-sahin-u7tx7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seninle yolculuklar yaptık hep hayal denizinde

Aşklar vardı hüzünler vardı neler neler vardı gemimizde

Mutluluklara yelkenler açmak vardı gönüllerimizde

İnsanın gözü bir şey görmüyormuş meğer sevince sevilince

Dalıp dalıp hayallere hesap  sorduğumuz o maziye gülmeyen

                                                           güldürmeyen kaderimize

Elimizde olsaydı dur demez miydik avuçlarımızdan 

                                                              kaçırdığımız gençliğe

Rüyalar yormadı mı bizi herkes gibi karanlıklara mahkûm

                                                                 etmedı mi hepimizi

İmrenmedik desek yalan mı olur başkalarının malına 

                                                                  mülküne sevgisine

Ne çare yine de elimizdekiyle yetinmeyi öğretti hayat bize

Tesadüfler milli piyango misali çıka geldi bazen o da 

                                                            deymedi güldüğümüze 

Uzun yollar yolculuklar ardından hep yorgunluklar çöker

                                                                               bedenimize

Neden bu hayatın çilesi hep garibe kimsesize çilekeş 

                                                                                   sevgilere

Aslında hayat bom boş bir ova deli divane gezer dururuz

                                                                                    üzerinde', 'Seninle yolculuklar yaptık hep hayal denizinde Aşklar vardı hüzünler vardı neler neler vardı gemimizde Mutluluklara yelkenler açmak vardı gö...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hayat-sofrasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökyüzüne Bak', 'gokyuzune-bak-sahin-yenilmez-t96rg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gök yüzüne bak 

Yıldızlara 

Ve en son aya

Ne kadar parlaklar değil mi? 

Ne kadar ışık saçıyorlar

Aynı senin gözlerin gibi

Aynı senin bakışın gibi.

Daha sonra karanlığa bak

Gecenin siyahına

Ne kadar korkunç

Ne kadar gizemli

Aynı benim gibi

Aynı benim kalbim gibi.

En son güneşe bak

Güneşin aydınlığına

Her kes ona muhtaç

Herkesin ondan beklentisi var

Aynı sevgi gibi

Aynı sevginin özlenmesi gibi.', 'Gök yüzüne bak  Yıldızlara  Ve en son aya Ne kadar parlaklar değil mi?  Ne kadar ışık saçıyorlar Aynı senin gözlerin gibi Aynı senin bakışın...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yenilmez']::text[], 8.5, '{"poet":"Şahin Yenilmez","poet_slug":"sahin-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gokyuzune-bak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşer', 'yeser-ufuk-nazim-n8tlx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sarsıldığını görüyorum çağların, 

Zalimler dönemecinde.

Bir cehennem barut kokusunda, 

Ta can evinden vurulmuş zincirlere; 

Promete.

Beynindeki karamsarlığın, 

Ta içinde; 

Yeşeren bir umut; 

Haykırıyor ta Urgakinadan.

Kan damlayan zaman süreci, 

Yıkılmalıdır; 

Hür insanlık dünyasından.', 'Sarsıldığını görüyorum çağların,  Zalimler dönemecinde. Bir cehennem barut kokusunda,  Ta can evinden vurulmuş zincirlere;  Promete. Beynind...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yeser-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hâlâ Sır Yapraklardasın', 'h-l-sir-yapraklardasin-ugur-oguz-sahin-pvbp3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Anılar defterimin yaprakları arasındaki sırsın

Tarifini yapamadığım dipsiz kuyular gibi korkumsun

Issız limanlara uğramayı bekleyen gemiler gibi umutsun

Laleye gelinciğe fesleğenlere inat koku musun

Akşamlardaki hüznün gecelerdeki hicranın yakamozu musun

Yıllardır yıkamadığım ömrümdeki en büyük tabusun

En vazgeçilmezler köşemden indirmediğim bir tablosun

Renksiz ve zevksiz şu yaşamın hâlâ bendeki mavisi gri 

                                                                                   tonusun

Gözlerinde o çok sevdiğim gözlerinde bırak da en son

                                                                     o renkler solsun   

Eskimiş o sır yapraklarda yaşayamadığım mutluluksun', 'Anılar defterimin yaprakları arasındaki sırsın Tarifini yapamadığım dipsiz kuyular gibi korkumsun Issız limanlara uğramayı bekleyen gemiler ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hala-sir-yapraklardasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimseye', 'kimseye-ender-guncelik-kmhht', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu şiirim kimseye 

Satırlarında yaşamı öykülenmiş herkese

Ne uzun, ne de kısa

Hayat gibi belirsizlikler içinde...', 'Bu şiirim kimseye  Satırlarında yaşamı öykülenmiş herkese Ne uzun, ne de kısa Hayat gibi belirsizlikler içinde......', ARRAY['Türk Edebiyatı','Şiir','Ender Günçelik']::text[], 8.5, '{"poet":"Ender Günçelik","poet_slug":"ender-guncelik","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kimseye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık Günler', 'karanlik-gunler-ender-guncelik-5zobv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şu kara bulutlar ardında 

Bir güneş var ki; sıcak ve aydınlık

Ama ben üşüyorum yalnızlıkta

Sanki yağmur, buz tanesi gibi tenime düşüyor

Biliyorum bir gün bir rüzgar dağıtacak tüm bulutları

İçim dahi ısınacak. 

Bu günler çok yakın

Ama daha fazla sabredemiyorum

Her yeni gün, ben o bulutlar içinde, 

Yavaş yavaş da olsa eriyip, bitiyorum.', 'Şu kara bulutlar ardında  Bir güneş var ki; sıcak ve aydınlık Ama ben üşüyorum yalnızlıkta Sanki yağmur, buz tanesi gibi tenime düşüyor Bili...', ARRAY['Türk Edebiyatı','Şiir','Ender Günçelik']::text[], 8.5, '{"poet":"Ender Günçelik","poet_slug":"ender-guncelik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/karanlik-gunler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalleş Dünya', 'kalles-dunya-ender-guncelik-khk6c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Niye bırakıp gittin beni, 

Hain sevgili, , , 

Hain dedim sana, kusura bakma

Kızgınlığımdan olacak

Hoş gör beni.

Sensiz bu ev, bu sokaklar

Bu güneş, bu yağmurlar

Yüreğimi damla damla eritiyorlar, 

Bu vakitte hep evde olurdun

Yanağıma yaklaşıp bir öpücük kondururdun

Masumca, bebek saflığında bir öpücük olurdu bu, 

Daha sonra kulağıma eğilip 

Seviyorum derdin bana

Saatlerce göz göze donup kalırdık

Elim eline değse 

Tüylerimiz diken diken olur, 

Boş yere ağlardık, 

Sanki bu günler sona varacak gibi

Her günü liseli aşıklar gibi yaşardık

Sanki her gün, yeniden kendimizi aşka adardık

Biz severdik birbirimizi, hem de çooook

Ve söz verirdik asla ayrılmayacağız diye

Öyleyse bu gidiş, bu terk ediş niye? 

Niye sözünü tutmadın? 

.......................

Özür dilerim sevdiğim, şimdi hatırladım, 

Sözümüzün ardına eklediğimiz bir laf vardı, 

“ölüm bile ayıramaz bizi”

O zaman sözünü tutmayan biri varsa, o da benim

Sabret meleğim.

Beş dakikaya kalmaz, ben de seninleyim.

Bu dünya fazlaydı zaten bize, 

Her büyük aşkı öldürdüğü gibi

Bizi de yok etti karanlığının içinde...', 'Niye bırakıp gittin beni,  Hain sevgili, , ,  Hain dedim sana, kusura bakma Kızgınlığımdan olacak Hoş gör beni. Sensiz bu ev, bu sokaklar Bu...', ARRAY['Türk Edebiyatı','Şiir','Ender Günçelik']::text[], 8.5, '{"poet":"Ender Günçelik","poet_slug":"ender-guncelik","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/kalles-dunya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmenin Bedeli', 'sevmenin-bedeli-ugur-oguz-sahin-gcwod', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mutlu bir umut yeşertir düşünceleri

İçindeki duygulardır kemiren kişileri

Nedenler sonuca getirendir bizleri

En güzel şey sevmek acılarsa bedeli mutlılıktur meyvesi', 'Mutlu bir umut yeşertir düşünceleri İçindeki duygulardır kemiren kişileri Nedenler sonuca getirendir bizleri En güzel şey sevmek acılarsa be...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevmenin-bedeli-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teklif', 'teklif-ugur-oguz-sahin-z9h7g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mutluluğadır duyduğum özlem

Eşsiz bir sevgiyle bana gelebilsen

Rüyalarım gerçek olurdu

Aşkım senle başlıyor desem

Layık olmak için sana ne yapsam ne etsem

Yakın olsun istiyorum gönüllerimiz

Üzüntüyü silsin bizden sevgimiz

Can ile canan misali olalım biz

Erişelim mutluluğa birlikte

Hadi gel kenetlensin ellerimiz', 'Mutluluğadır duyduğum özlem Eşsiz bir sevgiyle bana gelebilsen Rüyalarım gerçek olurdu Aşkım senle başlıyor desem Layık olmak için sana ne y...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/teklif-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haber Ver', 'haber-ver-ugur-oguz-sahin-x6vuv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Umut zincirlerimi taktın mı yeniden sevdiceğim

Gonca güllerim açtı mı yaralı bağrında

Uğur çiçeklerim göz göz oldu mu  gönül kapında

Rüzgârım savurup geçti mi saçından bana haber ver

Şafağım söktü mü alacakaranlığında sevdiceğim

Ansızın bir bıçak gibi saplandı mı yüreğine yokluğum

Hatıralarımız bir bir geçti mi usundan bana haber ver

İki damla süzüldü mü gözlerinden istemeden

Nerde diye döküldüm mü dudaklarından hece hece

                         bana haber ver bekletmeden geleyim', 'Umut zincirlerimi taktın mı yeniden sevdiceğim Gonca güllerim açtı mı yaralı bağrında Uğur çiçeklerim göz göz oldu mu  gönül kapında Rüzgârı...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/haber-ver-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölünceye Dek', 'olunceye-dek-yusuf-kaya-4lcai', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir ilkbahar günü vermişim sana, 

İlk mektubumla bir beyaz çiçek, 

Hani söz vermiştin ey canım benim 

> diyordun ölünceye dek, 

O an oturmuştuk bir çam altına, 

Ayrılmayalım diye etmiştik dua, 

Yaşlı gözlerle yaslanıp sağ omzuma 

> diyordun ölünceye dek

Vuslatın şerbetini o zaman içmiştik 

Ayrılmamaya yemin etmiştik

Sevgimiz için bir gül dikmiştik

> diyordum ölünceye dek

Geçenlerde uğradım bence, kutsal mekana

Eski hali kalmamış dönmüş virana

Aşkımıza şait ağaç seni soruyor bana

Cevap veremeyeceğim ölünceye dek

Gördüm ki gülümüz solmuş

Meğer gözyaşının sahtesi de olurmuş

Öğrendim ki düğünün başkasıyla olmuş

> diyorum ölünceye dek', 'Bir ilkbahar günü vermişim sana,  İlk mektubumla bir beyaz çiçek,  Hani söz vermiştin ey canım benim  > diyordun ölünceye dek,  O an oturmuş...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Kaya']::text[], 8.5, '{"poet":"Yusuf Kaya","poet_slug":"yusuf-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olunceye-dek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz De Oluyor', 'sensiz-de-oluyor-yusuf-kaya-045cm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen olmadan da yaşarım ben bir yanım eksik, 

Üzülmem ben, sen gittin diye inan 

Her aşkın ardında bir ayrılık vardır buna inan

Bir başka aşk bulmak o kadar da zor değil buna da inan', 'Sen olmadan da yaşarım ben bir yanım eksik,  Üzülmem ben, sen gittin diye inan  Her aşkın ardında bir ayrılık vardır buna inan Bir başka aşk...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Kaya']::text[], 8.5, '{"poet":"Yusuf Kaya","poet_slug":"yusuf-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sensiz-de-oluyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Bildiklerim', 'dost-bildiklerim-kazim-yaman-46105', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hepsi yanımdaydı baharda yazda

Kimi keman çalar kimi de sazda

Ne zaman ki kaldım biraz ayazda

Bırakıp ta gitti dost bildiklerim    

Kaybettim her şeyi dağıldı paralar

Kalmadı dermanım azdı yaralar

Ne zaman ki üstüme giydim karalar	

Bırakıp ta gitti dost bildiklerim', 'Hepsi yanımdaydı baharda yazda Kimi keman çalar kimi de sazda Ne zaman ki kaldım biraz ayazda Bırakıp ta gitti dost bildiklerim     Kaybetti...', ARRAY['Türk Edebiyatı','Şiir','Kazım Yaman']::text[], 8.5, '{"poet":"Kazım Yaman","poet_slug":"kazim-yaman","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dost-bildiklerim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Tükeniyor', 'zaman-tukeniyor-ugur-oguz-sahin-xh53t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçimde fırtınalar kopuyor ne olursun gel de dindir

Leylaklar zambaklar boynunu bükmeden bu canı sevindir

Kimse umrumda değil bir tanem kalbim sadece senindir

Eşsiz bir yerindesin ruhumun bu sana yemindir

Rüyalarımda sen gerçeğim sen bu alnıma yazılan kaderimdir

Yılların hüznüyle yaşadım hep bu yürekte alacağım var felekte

Işığım sen ol hadi gel bak mumlardaki alevler sönmekte

Laleler suskun karanfiller hüzünde her şey kahır çekmekte

Mutluluk sanki bana uzak meçhul bir limanda demirli 

                                                                                   beklemekte

Artık tak etti canıma yeter can özüm arzularım seni istemekte

Ziyan olmadan geçmeden bu ömür gel düşlerimi güldür

                                                                      zaman tükenmekte', 'İçimde fırtınalar kopuyor ne olursun gel de dindir Leylaklar zambaklar boynunu bükmeden bu canı sevindir Kimse umrumda değil bir tanem kalbi...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/zaman-tukeniyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolun Sonu Özgürlük', 'yolun-sonu-ozgurluk-melih-coskun-mgi3k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Işıksa eğer bu karanlık yolun sonu

Yürümeye değecek bir şey var vardır uğrunda 

Ölümün kalleşliği en fazla bir kez yakalar bizi

Ama bin defa yaşarız 

Bakışımız kalır bir anıt gibi

Düştüğümüz yerde 

Mezar taşlarımız fener olur bu yolda

Aydınlatır ardımızca gelenleri

Bu yolda kurban oluruz cahile aydınlık için 

Ama çıkacaksa karanlıklar aydınlığa gerçekten

Otuzar otuzar yanmaya da hazırız bu yolda

Yolun sonu bir destandır yüreklerde

Yolun sonu daha güzel bir dünya

Yolun sonu özgürlük

Bu yolun sonu aşktır güzelim... 

6 Temmuz 2002

00: 59', 'Işıksa eğer bu karanlık yolun sonu Yürümeye değecek bir şey var vardır uğrunda  Ölümün kalleşliği en fazla bir kez yakalar bizi Ama bin defa...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yolun-sonu-ozgurluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-kaan-demir-6h3g7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalnız kalmıs bır cocuk gıbı 

Aglamak geliyor icimden

Gözyaslarım akmaz oldu

Sen yokken göz pınarlarım kurudu

Şimdi kimbilir nerelerdesin

Hangi yabancı eller tutuyor elini

Kim paylaşıyor sevgini

Kim bırakıyor bana hasreti

Seni cok sevmiştim sen bilmesende

Birgün olsun yüzüme gülmesende

Beni yakıp yıksanda hasretinle

Seni cok seviyorum hepde delicesine', 'Yalnız kalmıs bır cocuk gıbı  Aglamak geliyor icimden Gözyaslarım akmaz oldu Sen yokken göz pınarlarım kurudu Şimdi kimbilir nerelerdesin Ha...', ARRAY['Türk Edebiyatı','Şiir','Kaan Demir']::text[], 8.5, '{"poet":"Kaan Demir","poet_slug":"kaan-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalnizlik-92-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çığlık Çığlığa', 'ciglik-cigliga-gonul-yilman-0y5du', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sessizce git gideceksen

kendine bile haber vermeden

ayrılığın izi sessizliklerde kalsın

gürültüsü

sevdiğinin yüreğinde koparken

sen

bütün çığlıkları

ardına koy git..

susuyorsam 

çığlık çığlığa

yıldızlara ve yalnızlıklara

gebeyse her gecem

karanlıkta görüyorsam

görüyorsam gözbebeklerini

sendeyse gözlerimin bütün ışığı

ve yalnızca çoğalıyorsam

seni ve sana dair herşeyi

ben aslında

seviyorum demektir.', 'sessizce git gideceksen kendine bile haber vermeden ayrılığın izi sessizliklerde kalsın gürültüsü sevdiğinin yüreğinde koparken sen bütün çı...', ARRAY['Türk Edebiyatı','Şiir','Gönül Yılman']::text[], 8.5, '{"poet":"Gönül Yılman","poet_slug":"gonul-yilman","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ciglik-cigliga-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluk Paylaşmaktır', 'dostluk-paylasmaktir-melih-coskun-t3q62', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dostluk: 

Paylaşmaktır 

Paylaşılan ne olursa olsun

Paylaşılan bir zindanın parmaklıkları da olsa kimi zaman

Kimi zaman kanayan bir yarayı

Korkunu 

Özgürlüğünü 

Sevgini ve sevincini

Ve geleceğini, 

Olduğu gibi kabul edeceksin dostunu

Eksik kalmışlığıyla seveceksin 

Senden fazla olan yanıyla veya

Beraber ağlayabilmelisin bir türküye

Beraber dövüşebilmelisin kavganda

Yarım kalmış bir şiiri tamamlayabilmelisin beraber

Gerekirse beraber ölebilmelisin

Yaşayabilmek adına...

22 Aralık 2002

23: 37', 'Dostluk:  Paylaşmaktır  Paylaşılan ne olursa olsun Paylaşılan bir zindanın parmaklıkları da olsa kimi zaman Kimi zaman kanayan bir yarayı Ko...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/dostluk-paylasmaktir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısır Kaldı Sevgiler', 'kisir-kaldi-sevgiler-ugur-oguz-sahin-k51lh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ansızın gelişlere benzer yürekteki sancılar yokluklar ayrılıklar

Sevgi gerçek sevmek gerçek ne kadar yaşanan mutluluklar

Leylalar Mecnunlar Şirinler Ferhat''lar tüketildi sevgideki 

                                                                                        miraslar

Anlık yaşanmaya başlandı sevdalar hani nerde kimde o 

                                                                            ölümsüz aşklar

Ne gerçek kalan besmele oldu her dilde yalan kalmadı güven

                                                                   her şey yerle bir talan

Gönüllerde yatan aslanlar niye kükremez neyle uyutuldu

Ümitler vaatler sevmek sevilmek hasret bu muydu

Viran edildi gönül bahçeleri hani nerde öbek öbek açan

                                                                      o mevsim gülleri

Elimizde yok kayboldu o sihirli asa şimdi yaşamak

                                                       zorundasın o kısır sevgileri

Nasıl ne şekilde kim çıkacak kim haykıracak gerçekleri kim

                             çözecek sevgi krizlerini çıkacak mı birileri', 'Ansızın gelişlere benzer yürekteki sancılar yokluklar ayrılıklar Sevgi gerçek sevmek gerçek ne kadar yaşanan mutluluklar Leylalar Mecnunlar ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kisir-kaldi-sevgiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Takvim Yapraklarını Koparma Hayatımdan', 'takvim-yapraklarini-koparma-hayatimdan-melih-coskun-5uq5b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Takvim yapraklarımı koparma hayatımdan

Bugün bir daha doğmayacak

Günlerin merhametine sığındık

Beklerken bilinmezini yarınlarımızın

Yarın yaşanmayacaksa yazık olur umuda

Yarının dipsiz kuyularında kaybolmak istemiyorum

Takvimimin yaprakları kopmasın istiyorum

Umudum bitmesin istiyorum

Umut bitmesin

Bugün hiç yitmesin...

25 Aralık 2002

00: 46', 'Takvim yapraklarımı koparma hayatımdan Bugün bir daha doğmayacak Günlerin merhametine sığındık Beklerken bilinmezini yarınlarımızın Yarın ya...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/takvim-yapraklarini-koparma-hayatimdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Çare Bulalım', 'bir-care-bulalim-ugur-oguz-sahin-dehog', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzaklarda mekân kurmuşsun sevdiğim

Geceler boyunca yaşarım sensizliği

Uçsuz bucaksız dağlar arasından

Rüzgârla gelirim bir nefes gibi

Şimdi yanımdasın günler geçiyor

Ama neyleyim yakında gideceksin

Hatıraların ve hayalinden başka ne kalacak

İnan benliğimi yine sensizlik saracak

Nereden bileyim sonumuz ne olacak', 'Uzaklarda mekân kurmuşsun sevdiğim Geceler boyunca yaşarım sensizliği Uçsuz bucaksız dağlar arasından Rüzgârla gelirim bir nefes gibi Şimdi ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-care-bulalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoktun', 'sen-yoktun-yasar-aslan-ymegl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'günler güz yaprakları gibi birer birer dökülürken ayaklarımın dibine 

ben her gece karanlığa dikip gözlerimi senin aydınlığını bekledim

sen yoktun.! 

binlerce adım attım bu kentin sokaklarında 

sevdaya bulanmış her kaldırım taşının altında senin adını aradım

özlem şarkılarını ezberledim

kimini bağıra bağıra, kimini fısıltıyla söyledim

karanlığa haykırdım hasretimi

sesimi duyacaksın diye bekledim

sen yoktun.! 

senden gelecek bir tek haberi bekledim saatler asır gibi geldi, geçmedi

çalan her telefonu yüreğimin çağlayana dönüşen atışıyla açtım

senden başka duyduğum her seste hep aynı hayal kırıklığını yaşadım

onlar beni duymak istiyordu bense seni

sen yoktun.! 

seni aramaktan yorgun düşmüş bedenimi

karanlığın kucağına uzattım her gece 

bir an önce  sabah olsun diye uykunun beni çekip almasını bekledim

olmadı, kaç gece sabahı sensiz ettim gözlerimi kapamadan

kaç gece merdivenlerdeki ayak seslerini dinledim, gelen sesindir diye

sen yoktun.! 

her yağmurla birlikte hüzün yağdı bu kentin üzerine

bulutlar yalnızlığımın işaretiydi benim için

beni ıslatan yağmur olmadı 

ben senin özleminle sırıl sıklamdım her mevsim

hayat merhaba dedi bahara çiçek çiçek

uzun kıştan sonra gelmez dediğim göçmen kuşların dönüşünü gördüm

sen yoktun.!

her istasyon her otogar adresim oldu

bir trenden inersin sandım

her yolcuya sensin diye baktım

yolculuklara vurdum kendimi

kimsenin uğramadığı köylere

adı duyulmamış kasabalara gittim

senden  bir iz aradım 

sen yoktun.! 

denizin sonsuz maviliklerine umut bağladım

kıyılarda tükettim bekleyişlerimi

hep sensiz gemiler geçti bu limandan

ben gemicilerin hasret türkülerine eşlik ettim 

sen yoktun.! 

gözümden bir tek damla yaş akmadı 

onlar sana aitti sana kalmalıydı

kimselere söyleyemedim acılarımı

bekleyişimin öyküsünü kimselere anlatamadım

nice fırtınalar koptu yüreğimde

dalgalar döğdü hayallerimi

sığınacak bir liman yaslanacak bir omuz aradım 

sen yoktun.! 

her gece ay paramparça oldu

yıldızlar birer birer düştü isimsiz sokaklara

yıldızları saçlarına takıp gelmeni

Ay''ı avuçlarında bana getirmeni 

ve bir güneş gibi doğup aydınlatmanı bekledim bu kapkaranlık dünyamı 

ama........ 

SEN YOKTUN.......', 'günler güz yaprakları gibi birer birer dökülürken ayaklarımın dibine  ben her gece karanlığa dikip gözlerimi senin aydınlığını bekledim sen ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Aslan']::text[], 8.5, '{"poet":"Yaşar Aslan","poet_slug":"yasar-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/sen-yoktun-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Affet Beni', 'affet-beni-ugur-oguz-sahin-u0f6s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Affet beni artık bitsin bu hasret

Figan olan bu gönülde beklemek bir illet

Fayda etmiyor yalvarış dedikodu fesat bu millet

Engellenir yoksa mutluluğun özlemlerinle sabret

Tüketme kendini elde edilmez bir daha bu nimet

Bir gün sende anlayacaksın her şey bir gerçek

Erişilmesi güç yollarda elde edilir sevmek

Nasırlaşmış ellerde sevgiyle büyümek

İşte sana erişmek ve sonunda benimsin seninim diyebilmek', 'Affet beni artık bitsin bu hasret Figan olan bu gönülde beklemek bir illet Fayda etmiyor yalvarış dedikodu fesat bu millet Engellenir yoksa ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/affet-beni-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rozetim Sensin', 'rozetim-sensin-ugur-oguz-sahin-c1tpt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Neredeydin bir tanem bu kadar zaman

Aşkımın yeşeren filizi oldun gülüm 

Ciğerimden söküldü o kirli duman

İçimde hasret bir de o zalim zaman

Yakaladık desem mi bilemiyorum 

Enginden süzülerek gelecek gibi olursun her an

Hasret duvarları çöktü çökecek

Esti mutluluk yeli gönüller gülecek

Kırdık prangaları artık kaleler fethedilecek

İmrenecek bize bütün umman

Mutluluk anahtarım sensin bu can da sana kurban', 'Neredeydin bir tanem bu kadar zaman Aşkımın yeşeren filizi oldun gülüm  Ciğerimden söküldü o kirli duman İçimde hasret bir de o zalim zaman ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/rozetim-sensin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanarsa Bir Kez Yara', 'kanarsa-bir-kez-yara-ugur-oguz-sahin-czd8q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İlk göz ağrısı ilk sancı ilk hevessin

Laleye mi benzersin mor menekşe mi yoksa sümbül müsün

Kaderin elinde bir gül mü yoksa şanslı bir bülbül müsün

Akşam sefası mısın yoksa yaşatacak bir ömür müsün

Ya da hiç biri değil bıkmadan açacak yediveren gül müsün

Çamda diken bir yaprak ya da bir kozalak

Onsuz olmaz su hayat her mevsimde yağmurla yaşamak

Lakin hayatın anahtarı sevmek mutluluk azdır gerisi ağlamak

Aşkı seçmesini bileceksin maharet koklamak değil gülü

                                                                  dikeninden sakınmak

Kanarsa bir kez yara zordur kapamak zordur mutluluğa

                                                                                       ulaşmak', 'İlk göz ağrısı ilk sancı ilk hevessin Laleye mi benzersin mor menekşe mi yoksa sümbül müsün Kaderin elinde bir gül mü yoksa şanslı bir bülbü...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kanarsa-bir-kez-yara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mum Alevi', 'mum-alevi-cevdet-ulas-zdtgd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sıradan bir başlangıç

Yeniden, 

yeni bir güne

Aynı dönüş, yorgunca

Yine yalnız eve...

Sıradan

kopyalanmış gecelerden bir gece

Tek farkı; 

Sen düştün derinden

Yine içime

Ağladım, sessizce

İnceden inceye

Yüregimdeki ateş, titrek

Mum alevince...', 'Sıradan bir başlangıç Yeniden,  yeni bir güne Aynı dönüş, yorgunca Yine yalnız eve... Sıradan kopyalanmış gecelerden bir gece Tek farkı;  Se...', ARRAY['Türk Edebiyatı','Şiir','Cevdet Ulaş']::text[], 8.5, '{"poet":"Cevdet Ulaş","poet_slug":"cevdet-ulas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/mum-alevi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karagözlüm', 'karagozlum-damla-koc-rx58q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gül kokuyor ak gerdaninda, 

yine görmüs beni kiz rüyasinda, 

ölem dedim.

dur yapma dedi...

Bu dünyanin bir sonu var, 

iyisi var, 

kötüsü var, 

karagözlüm ölesim var, 

inadina lan yasa dedi!', 'Gül kokuyor ak gerdaninda,  yine görmüs beni kiz rüyasinda,  ölem dedim. dur yapma dedi... Bu dünyanin bir sonu var,  iyisi var,  kötüsü var...', ARRAY['Türk Edebiyatı','Şiir','Damla Koç']::text[], 8.5, '{"poet":"Damla Koç","poet_slug":"damla-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/karagozlum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Adına', 'hep-adina-ugur-oguz-sahin-1bcc8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalbime kilitlerim seni 

Anla ne olur anla bendeki yerini

Derdimin dermanı ol gel yeter

İnan bitmek bilmiyor sensiz geceler

Rahata ermiyor özlemler

Uzun hep uzun bu yollar

Lakin sonunda hep mutluluk var

Uzasa da yollarımız mahşere kadar

Tanrı şahit olsun bu sevgimize

Aşkımız her şeyden üstün bunu bil

Şu üç günlük dünyada yaşadığımız sadece sevgi değilmidir', 'Kalbime kilitlerim seni  Anla ne olur anla bendeki yerini Derdimin dermanı ol gel yeter İnan bitmek bilmiyor sensiz geceler Rahata ermiyor ö...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hep-adina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiler (2)', 'sevgiler-2-ugur-oguz-sahin-8ww6n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevmek sevilmekse özlemin

Aşk denen şeye  yüklüdür isteğin

Duygular kaynaştırır arzuları

En derin hisler severken verilir

Tüm arzuların isteği mutlu edilmektir

Ilık bir rüzgâr eser bu hep sevgidir

Şayet kırıksa ümitler o rüzgâr fırtına getirir

Istırap yüklü yaşamın mutlulukları nedense eziktir

Kalpler yalancı değil daima gerçek sevgilerle ebedidir', 'Sevmek sevilmekse özlemin Aşk denen şeye  yüklüdür isteğin Duygular kaynaştırır arzuları En derin hisler severken verilir Tüm arzuların iste...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevgiler-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğmak ve Ölmek', 'dogmak-ve-olmek-ugur-oguz-sahin-e3buf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Neden esir eder bizi duygular

İnsanda kaynaşır tüm arzular

Lafta kalmaz gerçek yaşananlar

Gülmelisin ağladığın kadar

Üstüne örtmelisin mutluluğu dertlerin

Ne kadar zaman ki zaten yaşadığımız anlar

Özlem bir ateş aşk yakan bir alevdir

Zenginlik gönülde olsun eldeki kazanılan değerdir

Kaybettiğinde  mutluluğu sorarım ne geri getirir

Anlatılır hep hayat aslında o da iki kelimedir

Nasıl mı onların adları da doğmak ve ölmektir', 'Neden esir eder bizi duygular İnsanda kaynaşır tüm arzular Lafta kalmaz gerçek yaşananlar Gülmelisin ağladığın kadar Üstüne örtmelisin mutlu...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dogmak-ve-olmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiye Akış', 'sevgiye-akis-ugur-oguz-sahin-ohw72', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgidir kıpırdanış sevgidir can alıcı bir bakış

Eşsiz bir hazdır aşka gönülden sarılış

Rüyalar gerçek olunca unutulur yalvarış yakarış

Kalplerde noktalanır hep ruhlara inen akış

Anlatılmaz duygudur bedenlerdeki sarsılış

Ne var ki bilinmez bir yazgıdır kaderdeki ayrılış

Yarını düşünmez olur insan körü körünedir hayata sarılış

Issız bir çöl ortasında su bulmak hayali gibidir inanış

Lakin pes edersen bu yolda o zaman başlar yıkılış

Deryadır denizdir sevgidir aşktır bu bazense bir aldanış Istırabı derin bir yara açar hayali sukut-a uğrayış

Rızası olacak her şeyde yaradanın yoksa yaprak bile

                                                                              kımıldamazmış

Israrla yürümeli sevgi yolunda sevmek sevilmek çok

                                                                                       kutsalmış

Mutluluk dediğin sonunda bir bahçeden bir gül kopartmakmış', 'Sevgidir kıpırdanış sevgidir can alıcı bir bakış Eşsiz bir hazdır aşka gönülden sarılış Rüyalar gerçek olunca unutulur yalvarış yakarış Kalp...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevgiye-akis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-ugur-oguz-sahin-5x9ep', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevmeyi aslında bir kaç kelimeyle anlatamam sana

Ellerini tuttuğumda diyecek yok mutluluğuma

Narin bakışlarında eriyen bu vucudumla

İnan ki hep senin için yaşıyorum

Sorma yalnızlığında nasılım

Erişemez hiç bir sevgi yine sana aşığım

Varınla yoğunla vermiş seni bana alın yazım

İstemem seni başka gözlerde nazarlanırsın

Yok artık bende fırtına bitti o hüzünlü yaşama

Olgun bir devresinde yaşıyorum seni

Rahat bu gönlüm ıstıraptan uzak seninle bir başına

Umutlarımı biriktirdim yaşantımızdaki hazırlık yarına

Mutlu bir dünya kurmak başlangıcım SENİ SEVİYORUMLA', 'Sevmeyi aslında bir kaç kelimeyle anlatamam sana Ellerini tuttuğumda diyecek yok mutluluğuma Narin bakışlarında eriyen bu vucudumla İnan ki ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-seviyorum-111-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün', 'bir-gun-gursel-colak-6jss0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gelmek isterim gelemem

Sarmak isterim saramam

Üzülmeni istemem üzemem

Yitirme umudunu bir gün gelirim.

Sevindirmek için seni

Sarabilmek için seni

Tek bir günde olsa

Mutlu etmek için seni.

Tutarım ellerinden

Götürürüm seni benim dünyama.

Benim dünyam, mutluluk dünyası

Üzüntü olmaz orada.

Otururuz çam ağacının altında

Konuşuruz mutlulktan

Bilmiyorsan öğrenirsin

İnan bilmeyen tek sen değilsin.

Yatarsın dizlerimin üstüne

Okşarım ipek saçlarını

Bağrıma basarım dertli başını

Unutturmak için bütün sızılarını.

Ama bir gün mutlaka gelirim

Beklemeni dilerim

Mutlulukla dolu olan dünyama

Senide götürmek isterim.', 'Gelmek isterim gelemem Sarmak isterim saramam Üzülmeni istemem üzemem Yitirme umudunu bir gün gelirim. Sevindirmek için seni Sarabilmek için...', ARRAY['Türk Edebiyatı','Şiir','Gürsel Çolak']::text[], 8.5, '{"poet":"Gürsel Çolak","poet_slug":"gursel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-gun-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'La Luna', 'la-luna-lale-muldur-zuiuz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bana Zaman ve La Luna

herşey gitti bak

herşey ağlayarak gitti

sular soğudu

bir Kurban düşüyor şimdi aramıza La Luna

üçümüzden biri kurban

serin bir çizgi çekiliyor gökyüzüne

çok geç çok geç artık

terkedip gidiyor beni teker teker bütün güneşlerim

bir daha hiç dönmeyecekler mi yaşamıma

alnımdan fırlayan bir Kartal yarıp

            geçiyor göğü

görünmez bir Çarkın çıldırtıcı gürültüsü

            duyuluyor bir yerlerden

uzak anılar

yengeçler gibi

ç
..........
..........', 'bana Zaman ve La Luna herşey gitti bak herşey ağlayarak gitti sular soğudu bir Kurban düşüyor şimdi aramıza La Luna üçümüzden biri kurban se...', ARRAY['Türk Edebiyatı','Şiir','Lale Müldür']::text[], 8.5, '{"poet":"Lale Müldür","poet_slug":"lale-muldur","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/la-luna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
