INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gazel - Hızır Dersi', 'gazel-hizir-dersi-i-brahim-akca-wvty9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kıssayı Hızır’dan ders aldık biz ye’s-i şeytana kanmayız

Ateş-i Nemrud sarsa gönlümüzü ibrahimiz yanmayız

Kadere iman ettik dokunamaz bize ebedi keder

Muhal ihtimaldeki imkanın mededine inanmayız

Hikmet ile kaimdir alem, anlaşılsa da sonradan hem

Rahat ol bahtiyar adem, seni rahmetten uzak sanmayız    

Şirk-i mutlak biliriz ihtiyacları ağyardan talebi

Lisanımız tevhiddedir ölsek bile başka şey anmayız

Duadır sertâc-ı kelam, kadir-i mutlakın dergahında

Hep odur sığınağımız eller uyuşsa da usanmayız

Ilahi mukallibe l-kulûbsun, hem müfettihe l-ebvâbsın

-Hasbunallah- kâfi, ümitsiz boş kapılara dayanmayız

Ilahi bizleri hayra ilet, mübarek rızana yönelt

Istemezsek icbar et, sen uyandırmazsan biz uyanmayız

Leverkusen,15.11.2000', 'Kıssayı Hızır’dan ders aldık biz ye’s-i şeytana kanmayız Ateş-i Nemrud sarsa gönlümüzü ibrahimiz yanmayız Kadere iman ettik dokunamaz bize e...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Akça']::text[], 8.5, '{"poet":"İbrahim Akça","poet_slug":"i-brahim-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gazel-hizir-dersi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinle Beni Yobaz, Dinle!', 'dinle-beni-yobaz-dinle-necdet-cobanli-tgebi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yobazlar, sizler, korkutamazsınız yürekli beyinleri, 

Hiç susturamazsınız hep laikliği konuşacak  dilleri, 

Kıracaktır son kuşak, demokrasimize kalkan o elleri, 

Ezip geçeceğiz, yok edeceğiz utanmaz kara cahilleri. 

Göreceksiniz siz, yürüyeceğiz Atatürkün ilkeleriyle, 

Sizi dinlemeden örgütleneceğiz köylerde şehirlerde, 

Anlatacağız doğruyu size kanıp peşinizden gidenlere, 

Hep ezeceğiz o yobaz kafaları her gördüğümüz yerde. 

Durmıyacağız, dereler, ırmaklar gibi çağlayacağız, 

Herşeyi anlatıp insanlarımıza, gözlerini açacağız, 

Kafaları kapkara siz yobazlardan hesap soracağız, 

Söz veriyoruz Atam sana, layikliği koruyacağız, 

Bitecek artık o pis yazılar, o kalemler kırılacak, 

Susacak o pis yobazlar, yarın gençlerimizin olacak, 

Görürsünüz, şerefsiz yobazlarda ahımız kalmıyacak. 

Bizlerden size teker teker hesap soranlar çıkacak.', 'Yobazlar, sizler, korkutamazsınız yürekli beyinleri,  Hiç susturamazsınız hep laikliği konuşacak  dilleri,  Kıracaktır son kuşak, demokrasim...', ARRAY['Türk Edebiyatı','Şiir','Necdet Çobanlı']::text[], 8.5, '{"poet":"Necdet Çobanlı","poet_slug":"necdet-cobanli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dinle-beni-yobaz-dinle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Vatan Bizimdir, Bizim Kalacaktır', 'bu-vatan-bizimdir-bizim-kalacaktir-necdet-cobanli-qtidt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Babam sık sık ailemizi evde toplardı, 

Bizlere Kurtuluş Savaşını anlatırdı, 

O günleri anlatırken o hep ağlardı, 

Bu vatan bizimdir, bizim kalacaktır. 

Uzaklara dalardı o güzel nemli gözleri, 

Çok anlamlıydı o pırıl pırıl sözleri, 

Başlarımızı okşardı, severdi bizleri, 

Bu vatan bizimdir, bizim kalacaktır. 

Türk''ü, Kürt''ü, Lazı, Abazası hepsi birdir, 

Alevisi, sünnisi, Lazı, Çerkezi hepsi birdir. 

Unutmayın, bu vatan Atamızın bize emanetidir. 

Bu vatan bizimdir, bizim kalacaktır. 

Bu vatanın insanlarını hainler bölemediler, 

Perişan oldular, toprağımıza göz dikenler. 

Uyanın gafiller, uyanın hayasız zibidiler, 

Bu vatan bizimdir, bizim kalacaktır. 

Bizlerle barış ve dostluk içinde yaşayın,

Sakın ola gene insanların canına kıymayın, 

Başınıza gelecekleri hiç ama hiç unutmayın, 

Bu vatan bizimdir, bizim kalacaktır. 

Sevgili babamın nasihatleri var kulağımda, 

Şehitlerin ruhları var taşında toprağında, 

Onuncu yıl marşımız hepimizin ağızlarımızda, 

 Bu vatan bizimdir, bizim kalacaktır.', 'Babam sık sık ailemizi evde toplardı,  Bizlere Kurtuluş Savaşını anlatırdı,  O günleri anlatırken o hep ağlardı,  Bu vatan bizimdir, bizim k...', ARRAY['Türk Edebiyatı','Şiir','Necdet Çobanlı']::text[], 8.5, '{"poet":"Necdet Çobanlı","poet_slug":"necdet-cobanli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bu-vatan-bizimdir-bizim-kalacaktir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Necdetin Memleketi', 'necdetin-memleketi-necdet-cobanli-etlv6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Edirneden Ankaraya, Ardahan''a

Hataydan Malatya ve Trabzon''a

Sıvas, Tokat''tan ta Erzincan''a,

Dalgalansın bayrağım oralarda.?

Yobazlar! onun adı, ''Anadolu''.

Her bir yanı yiğitlerle dolu,

Çanakkale, Sakarya, Gelibolu,

Her yer şehitlerimizle dolu.

Sorma Atam kendine: Türkiyem ne olacak?

Üzülme verdiğin bayrak hep dalgalanacak,

Cumhuriyet''in  inan ebediyen kalacak,

Yobazlara da bu vatan mezar olacak.

Bu vatan Ata''mızındır bize emaneti,

Asla olamaz kimsenin buna ihaneti,

Görevimiz korumaktır Cunhuriyeti,

Budur işte Necdet''in memleketi.', 'Edirneden Ankaraya, Ardahan''a Hataydan Malatya ve Trabzon''a Sıvas, Tokat''tan ta Erzincan''a, Dalgalansın bayrağım oralarda.? Yobazlar! onun a...', ARRAY['Türk Edebiyatı','Şiir','Necdet Çobanlı']::text[], 8.5, '{"poet":"Necdet Çobanlı","poet_slug":"necdet-cobanli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/necdetin-memleketi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sınav!', 'sinav-fatih-cinar-k2lnb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hiç birimiz çalışmıyoruz dersimize

derslerimize

hepimiz kalacağız bu gidişle sınıfta

sınavımız belki bugün

belki yarın

belki bugündende yarındanda daha yakın

herbirimiz yoklamada varız bugün belki

ama kimbilir hangimiz hangi gün

birdaha gelemeyeceğiz bu sınıfa

belki hergün biryerlerde

sınav içinde sınavdayız

kimi zaman kederli

kimi zaman mutlu

kimi zaman umutsuz kimi zaman umutlu

dünya içinde birçok öğretmenimiz var

belki çoğu zaman siuleti bile olmayan

dokunamadığımız göremediğimiz

ama ya asıl öğretmenlerin öğretmeni

kimimizin çok iyi bilip

kimimizin hiç bilmediği

yada bilipte inkar ettiği

ya o öğretmen ya onun yapacağı

o büyük sınav

sınavların içindeki sınavdan geçipte

önünde sonunda olacağımız

onun o büyük sınavı

kanaat notu olmayan

kurtarma sözlüsü olmayan

bütünlemesi hiçmi hiç olmayan

en büyük notu

ne beş nede on

sadece şeref sadece haysiyet

sadece iyilik vce namus olan

ve herkesin raporluda olsa

girmek zorunda olduğu o büyük

sınava hazırmısınız şu andan

dedimya belki bugün

belki yakın bugünden ve yarından', 'hiç birimiz çalışmıyoruz dersimize derslerimize hepimiz kalacağız bu gidişle sınıfta sınavımız belki bugün belki yarın belki bugündende yarı...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/sinav-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heyyyy Var Mı Bana Yan Bakan!', 'heyyyy-var-mi-bana-yan-bakan-necdet-cobanli-py1ns', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bana derler Necmettin Erbakan, 

Bizde varsa yoksa din, iman, 

Bizim işimizdir ezanla kuran, 

Geldi işte mubarek ramazan,

Kılarım namazımı ben ayan beyan, 

Heyyy var mı bana yan bakan? 

Benden olur en iyi Başbakan,

Çiller hanım bana Dışbakan, 

Adalet bakanım Şevket Kazan. 

Vardır onun elinde borazan. 

Şeriatçılar onunla bana hayran, 

Heyyy var mı bana yan bakan? 

Demirel değil mi senin baban, 

Odur onu başımıza damdan atan, 

''Hayır gelmez, '' deme Bacıdan, 

Beni çekip alan odur bacadan, 

Hayır gelir Hacı ile Bacı''dan 

Heyyy var mı bana yan bakan? 

Ben elbet kalkarım bunun altından, 

Beni bacadan alanı sararım altından. 

Kocası elinden tutup kazanır havadan. 

O da ''Bismillâh'' çekip kıvırır yandan, 

Ne serden vazgeçer o, ne de yardan, 

Heyyy var mı bana yan bakan? 

O''dur hep yere bakıp yürek yakan,

''Uçuran'' a sarılıp yatıpta uyuyan, 

İşini yürütüp götüren el altından, 

O vazgeçemez hiç handan hamamdan, 

 Ne olur beni de görün zaman zaman. 

Heyyy var mı bana yan bakan? 

Oh! Oh! Uçuran hanımım yandan yandan, 

Var mı yok mu, İşimiz hep yalan dolan, 

Sensiz geçen her bahar uzun bir hazan, 

Benim Dışbakanıma dil uzatana el''aman!

Olmaz, ben vazgeçemem bu güzel yardan, 

Üzme sen kendini hiç sevgili Uçuran, 

Ben olurum senin her derdine derman,

 Heyyy var mı bana yan bakan?

 Korkma sen, veririm aklanmana ferman.

Dışarı aldırtmam seni o güzel yattan.

Kimse indiremez Bacı''mı Kırat''ından, 

 Heyyy var mı bana yan bakan. 

Kim olursa din yolundan sapan, 

Biz oluruz onu cayır cayır yakan, 

Varsa yoksa kuranla din iman, 

Heyyy var mı bana yan bakan? 

   

''Amin'' deyip din okullarını kuran, 

Eski Komutan Kenan Evren Paşa''dan, 

Selâm var hepinize çok uzaklardan, 

Olan oldu; artık korkmayın onlardan. 

Görün neler çıkar kadayıfın altından. 

Heyyy var mı bana yan bakan? 

Var mı benim gibi iyi paket yapan? 

Yapıp ta halkın yüzünü buruşturan,

''Amin'' diye diye memleketi soyan, 

Sonra da herşeyi yakıp yakıştıran, 

Fakir fukarayı kapkara dumana boğan. 

Heyyy var mı bana yan bakan?

Vaçgememem ben ne serden ne de yardan, 

Hele hele ortağım dönek ''Uçuran'' dan, 

Yürütürüm din işlerini hep el altından, 

İznim var var benim bizleri yaratandan 

Korkmam kimseden ben, korur beni Yaradan. 

Heyyy var mı bana yan bakan? 

Görürsünüz, çıkarlar bu bataktan,

Çatlı''yı sor sen Sedat Bucak''tan, 

O''dur memleketi koruyan APO''dan, 

Sor sen onu benim eşsiz Bacım''dan, 

Hiç bir şey çıkmaz bu tahkikattan, 

Heyyy var mı bana yan bakan?  

Ne ister bilmem bu adam benden durmadan, 

Necdet Çobanlı''ymış adı. Bana ne ondan, 

O başkası değildir bunak bir ihtiyardan, 

Haberi yoktur onun ne dinden ne imandan. 

Hiç anlamaz o ne ''Hoca'' ne de ''İmam''dan 

Heyy var mı bana yan bakan, benim adım Erbakan?', 'Bana derler Necmettin Erbakan,  Bizde varsa yoksa din, iman,  Bizim işimizdir ezanla kuran,  Geldi işte mubarek ramazan, Kılarım namazımı be...', ARRAY['Türk Edebiyatı','Şiir','Necdet Çobanlı']::text[], 8.5, '{"poet":"Necdet Çobanlı","poet_slug":"necdet-cobanli","theme":"Türk Şiiri","is_hero":false,"total_lines":76,"source_url":"https://www.antoloji.com/heyyyy-var-mi-bana-yan-bakan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmayacak Duaya ''Amin'' Demeyin', 'olmayacak-duaya-amin-demeyin-necdet-cobanli-wcsjr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yapmayın, etmeyin, ne olur lütfen gelin şu ihtiyarı dinleyin, 

Birilerine inanıp koştum hep peşlerinden, yanlıştır bu, bilin, 

Onlara kanıp inanılmaz hayaller kurdum. Siz  bana benzemeyin, 

Her seferinde yanılıp sonra benim gibi ''ne halt ettim, '' demeyin, 

Bu politikacılara inanıp, olmıyacak duaya sakın ''âmin'' demeyin.

Derseniz eğer, sonra bana benzeyip (Ah neyledim)   diye dertlenmeyin.

Ne olur ona buna inanmayın. Hacı ve Yobazlara sakın ola güvenmeyin.

Bir gün bu memleket bu yobazlardan kurtulur diye ümitlenmeyin.

Yalvarırım, bari sizler benim yaptığım hataları tekrar etmeyin.

Evet gelin gene de siz siz olun olmıyacak duaya ''âmin'' demeyin.

Bugün Bayramımız. Hadi gelin benimle Onuncu yıl marşını söyleyin.

Ona buna aldırmayıp yolunuzda yürüyüp Ankaradakilere güvenmeyin.

Hemen koşupta  Atatürk''ün yoluna, onun dediklerini ezberleyin.

Eğilip önünde, yolundan ayrılmıyacağınıza hep beraber yemin edin, 

Sonra da dönüp o yobazlara (Allah sizin belânızı versin,)   deyin.', 'Yapmayın, etmeyin, ne olur lütfen gelin şu ihtiyarı dinleyin,  Birilerine inanıp koştum hep peşlerinden, yanlıştır bu, bilin,  Onlara kanıp ...', ARRAY['Türk Edebiyatı','Şiir','Necdet Çobanlı']::text[], 8.5, '{"poet":"Necdet Çobanlı","poet_slug":"necdet-cobanli","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/olmayacak-duaya-amin-demeyin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümcül Hasta Ziyareti', 'olumcul-hasta-ziyareti-i-brahim-akca-ajxvd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hüseyin Amca merhuma

Ölümcül Hasta Ziyareti

Belliki biraz yabancısıydık ölümün

Ve biraz acemisi

İlk ve son ziyaretin

Serin bir Ramazan günü

Ellerimizde çam sakızı hurmalar

Gönlümüzde acaba bizi ne bekliyor sorusu

Belki son olacak buluşmanın buruk duygusu

Ve anlaşılmaz tedirginliği üzerimizde

Ölümcül hasta ziyaretinin

İsmail, ben ve Erkan Hoca

Ve yatakta bir ölümcül hasta

Hüseyin Amca

Sekaratu l-mevtle ülfetleşmekte

Ümit kalmamış 

Kurtulacakmış diye mihnet-i dünyadan

Yollamışlar eve

Hey gidi Hüseyin amca 

Demek sıra şimdi de sende

Takdir amenna amma

Bak buraya kadar getirdi bıraktı seni 

Şu kahrolası vefasız cığara

Gülüyordun her zamanki kadar içten

Sessiz ve sözsüz

Son defa bize bakarken 

Son defa elimizi sıkarken

Hissettinmi acaba gönlümdeki meramı

Komşu gideceğin Resul’e yolladığım selamı

Köln,26.08.2002', 'Hüseyin Amca merhuma Ölümcül Hasta Ziyareti Belliki biraz yabancısıydık ölümün Ve biraz acemisi İlk ve son ziyaretin Serin bir Ramazan günü ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Akça']::text[], 8.5, '{"poet":"İbrahim Akça","poet_slug":"i-brahim-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/olumcul-hasta-ziyareti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Pişman Olursunuz!', 'bir-gun-pisman-olursunuz-necdet-cobanli-wevvb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''Erbakan'' eğer buysa, ''Er'' olmayanı kimbilir ne olur?

''Hanım'' dediğin böyle olursa ''Hanımefendi'' nasıl olur?

''Er''le ''Hanım'' birleşince, memleketin hali  böyle olur. 

Gözü yalnız iktidarda olanların  böyle bir sonu olur. 

Zaten böyle olması da, hakkettikleri bir son olur.  

Gene (Hacı ile Bacı yaktı bizi)   diye dertlenirken, 

Kara kara bunları düşünerek gözlerimiz nemlenirken, 

(Yandım Allah!)   türküsüyle gelen sesle dinlenirken, 

Anlatmak istemez mi insan dertlerini, demlenirken? 

Ama anlatsan da, hep söyleyen o olur sen inlerken.  

Hadi kırmayın bu ihtiyarı, toplanıpda bir araya, 

Gelip güç verin sizler de bu boynu bükük insana, 

Koşup meydanlara bağıralım beraber o utanmazlara. 

Yoksa bir gün çok pişman olacaksınız  yana yakıla, 

Arabanın ''Son''a gelip çarpıp durduğunu görünce duvara.', '''Erbakan'' eğer buysa, ''Er'' olmayanı kimbilir ne olur? ''Hanım'' dediğin böyle olursa ''Hanımefendi'' nasıl olur? ''Er''le ''Hanım'' birleşince, meml...', ARRAY['Türk Edebiyatı','Şiir','Necdet Çobanlı']::text[], 8.5, '{"poet":"Necdet Çobanlı","poet_slug":"necdet-cobanli","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-gun-pisman-olursunuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Da Yaktın Bizi Be Hacı!', 'nasil-da-yaktin-bizi-be-haci-necdet-cobanli-y75rh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Takınca koluna o gözalıcı bacıyı, 

Yutturmayı umdun bize dinle imanı, 

Yedirdiğini mi sandın bize ayvayı? 

Bil ki yapacaklardır yakında yuvanı. 

Nasıl da yaktın bizi be Hacı! 

Belâ ettin bir de başımıza şu Kazan''ı 

Bilmiş ol, kabardı artık milletin ayranı, 

Görürsün, yakında bulacaksın sen belânı, 

Yaparlar sizin gibi insanların yuvasını, 

Nasıl da yaktın bizi be Hacı! 

Neden söylersin sen bu yalanla dolanı, 

Karıştırıp durursun gene sapla samanı, 

Utanmazsan tut da bak yüzüne şu aynayı, 

Göreceksin, süremezsin sen hep bu sefayı, 

Nasıl da yaktın bizi be Hacı! 

Geldi mubarek dediğin ramazan ayı, 

Hadi, bırak artık göbek atıp oynamayı, 

Millet görecektir Hanya ile Konya''yı, 

O zaman sende öğrenirsin akla karayı, 

Nasıl da yaktın bizi be Hacı! 

Görünce aynı kefede Hacı ile Bacı''yı, 

Zehir edersin tüm milletin bayramını, 

Bilmem nasıl da yaparsın sen o duayı, 

Allah affetsin derim, sana hayran olanı, 

Nasıl da yaktın bizi be Hacı! 

Köprüyü geçene kadar sen olursun bize dayı, 

Hiç ama hiç unutmayız biz bu dumanlı havayı, 

Artık hiç affetmez bu yüce millet Erbakan''ı, 

Kolay bırakmayız dini kullananın yakasını. 

Nasıl da yaktın bizi be Hacı! 

Artık çıkarıver ağzından şu pis baklayı, 

Zaten istesen de yutamazsın o lokmayı, 

Görmeyiz artık ne seyranı ne bayramı, 

Bu yüzden hep alırsın benim de bedduamı, 

Nasıl da yaktın bizi be Hacı! 

Bilmelisin, her şeyin vardır bir ilâcı, 

Olacaktır milleti kurtaracak bir kabadayı, 

Hakkından gelir senin Orgeneral Karadayı, 

O zaman görüp cezanı, tanırsın İmralı''yı. 

Nasıl da yaktın bizi be Hacı!', 'Takınca koluna o gözalıcı bacıyı,  Yutturmayı umdun bize dinle imanı,  Yedirdiğini mi sandın bize ayvayı?  Bil ki yapacaklardır yakında yuva...', ARRAY['Türk Edebiyatı','Şiir','Necdet Çobanlı']::text[], 8.5, '{"poet":"Necdet Çobanlı","poet_slug":"necdet-cobanli","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/nasil-da-yaktin-bizi-be-haci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayana Sivrisinek Saz', 'anlayana-sivrisinek-saz-necdet-cobanli-1igh8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ANLAYANA SİVİRİSİNEK SAZ

ANLAMAYANA DAVUL ZURNA AZ

(Yollar yürünmekle aşınmaz)   diyen sizsiniz, 

(Dün dündür, bugün bugün)   diyen de sizsiniz. 

Bacıyı elinden tutup başımıza belâ eden de sizsiniz, 

Şimdi de (Durmayın sonuna kadar gidin)   diyen de sizsiniz. 

Evet biliyoruz, üç beş defa gidip geldiniz, 

Ama söyleyiniz gidip gelipte neyi düzelttiniz? 

Başımıza gelen belâlara göz yumup bizi inlettiniz, 

Millete acımayıp Hacıyla Bacıya bizi esir ettiniz. 

Kızdınızsa, durmayın hemen dama çıkınız. 

Ama ne olur, gelin yakamızı bırakınız. 

Yazıktır, yazık bu ülkeye kıymayınız, 

Bizim başımızı yeni belâlara sokmayınız. 

Yo yo, herşey gibi bunun da bir sonu vardır. 

Evet, kendine çok güvenmenin de sonu vardır. 

İnanın, bu gidişe bir ''Dur'' diyen çıkacaktır. 

Sonunda''Atatürk''ümüz gelip bizi kurtaracaktır.', 'ANLAYANA SİVİRİSİNEK SAZ ANLAMAYANA DAVUL ZURNA AZ (Yollar yürünmekle aşınmaz)   diyen sizsiniz,  (Dün dündür, bugün bugün)   diyen de sizsi...', ARRAY['Türk Edebiyatı','Şiir','Necdet Çobanlı']::text[], 8.5, '{"poet":"Necdet Çobanlı","poet_slug":"necdet-cobanli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/anlayana-sivrisinek-saz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yo! Yo! Vallahi Olmaz', 'yo-yo-vallahi-olmaz-necdet-cobanli-x7bmn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yo Yo! ! Vallahi de billâhi de olmaz, 

Kırk yıllık ''Kâni''den ''Yani'' olmaz. 

Çiller hanım, Erbakan''sız hiç olmaz. 

Olsa da zaten bunun tadı tuzu olmaz. 

Siz nasıl bana ''korkma sen'' dersiniz, 

Ve de olmıyacak bir günah işlersiniz. 

Hem Hoca''nın koluna girip gezersiniz, 

Hem de sizi kınayınları azarlarsınız. 

Yo! Yo! Vallahi de billâhi de olmaz,  

Bu sözlerle bizi uyutmak hiç olmaz. 

Verdiğiniz sözde durmamazlık olmaz. 

Hele hele ezansız namaz asla olmaz. 

Biliyorum ben sizin hakkınızdan gelemem, 

Ne de olsa Erbabakan da gelsin istemem. 

Meydan yalnız ona kalsın, asla istemem, 

Çünkü sonra bende ne yapacağımı bilemem. 

Gelin biz bunları unutup,  rüyalara dalalım, 

Hacı ile Bacıyı bırakarak keyfimize bakalım. 

Gözümüzü açınca da gelin derdimizi unutalım, 

Oturup iki kadeh viskimizle efkâr dağıtalım.', 'Yo Yo! ! Vallahi de billâhi de olmaz,  Kırk yıllık ''Kâni''den ''Yani'' olmaz.  Çiller hanım, Erbakan''sız hiç olmaz.  Olsa da zaten bunun tadı t...', ARRAY['Türk Edebiyatı','Şiir','Necdet Çobanlı']::text[], 8.5, '{"poet":"Necdet Çobanlı","poet_slug":"necdet-cobanli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yo-yo-vallahi-olmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seben''liyiz', 'seben-liyiz-turan-yilmaz-nj8nh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Cennete benzer yöremiz, .......Yuva, Yağma, bir boyumuz, 

Seben’liyiz biz Seben’li.....Oğuz, Türkmen, hep soyumuz, 

Birlik, dirlik der, töremiz, .....Yunus’a benzer huyumuz, 

Seben’liyiz biz, Seben’li...... Seben’liyiz biz, Seben’li.

Pekmez, bulgur, coş aşımız.... El ele verip, koşarız, 

Genceciktir şu yaşımız, ......... Karlı dağları, aşarız, 

Eğilmez hiç, dik, başımız, ......Irmaklar gibi, coşarız, 

Seben’liyiz biz, Seben’li........Seben’liyiz biz, Seben’li.

Muhabbet var özümüzde, ....... Vatan içindir canımız, 

Yalan yoktur sözümüzde, ....... Toprağı sular kanımız, 

Solmaz renkler, güzümüzde, ....Sonsuzda saklı şanımız, 

Seben’liyiz biz, Seben’li.........Seben’liyiz biz, Seben’li.. 

Mavi, beyazdır, rengimiz, .......Kadir Mevlâ’yı anarız, 

Cihanda yoktur dengimiz, ......Ateşiyle hep yanarız, 

Bozulmaz hiç, ahengimiz, ......Goncaya, güle konarız, 

Seben’liyiz biz, Seben’li........Seben’liyiz biz, Seben’li.

Düze bakar yokuşumuz, ........Hak’ka uzanır, elimiz, 

Pembe, yeşil nakışımız, .........Engel tanımaz, selimiz, 

Türkü söyler bakışımız, ........Hasret kokar hep, yelimiz, 

Seben’liyiz biz, Seben’li........Seben’liyiz biz, Seben’li.

Dumansız olmaz, dağımız, ..... Şu aleme nur saçarız, 

Kekik kokar hep, yağımız, ..... Sır kapısını açarız, 

Salkım salkımdır, bağımız, .....Kanat takıp hep, uçarız, 

Seben’liyiz biz, Seben’li........Seben’liyiz biz, Seben’li.

                                                      25.05.1996 SEBEN-BOLU

                            Turan YILMAZ

                            Belediye Yazı İşleri Müdürü', 'Cennete benzer yöremiz, .......Yuva, Yağma, bir boyumuz,  Seben’liyiz biz Seben’li.....Oğuz, Türkmen, hep soyumuz,  Birlik, dirlik der, töre...', ARRAY['Türk Edebiyatı','Şiir','Turan Yılmaz']::text[], 8.5, '{"poet":"Turan Yılmaz","poet_slug":"turan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/seben-liyiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günah Mı Bu?', 'gunah-mi-bu-necdet-cobanli-w9fat', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Lütfen dinleyip anlayın beni hiç kızmadan,

Yoktur benim hiç nâsibim dinle imandan,

Anlamam hiç ne ezandan ne de kurandan,

Anlarım ama ben Allaha da inananlardan,

Korkmam ''şeriat'' diye bağıran yobazlardan.

Neden ''Aklını kaçırmışsın, '' diyorsunuz, ''

Niye ille de ''Amin'' dememi istiyorsunuz?

''Günahtır bu, '' diye yalan söylüyorsunuz?

Boşuna nefes tükettiğinizi bilmiyormusunuz? 

''Şeriatı hiç dilinizden neden düşürmezsiniz? 

 Susun be, artık yeter; bana vız gelirsiniz,

Hayırlı olsun kim olursa olsun peygamberiniz,

Hadi kılın namazınızı önünüzde seccadeniz,

Vız gelir bana ne olursa olsun şeriatınız.

İnsanın akıllısı hiç böylesine saçmalamaz,

''Yobaz'' dan hiç ama hiç ''Milliyetçi'' olamaz,

Bilinizki kurbağa hiç ikiden fazla sıçramaz, 

Sıçrasada, bunlar ordunun gözünden hiç kaçmaz, 

Ne Hacı ne de Bacı onları asla aldatamaz.

Lütfen inanınız, niyetim değildir sizi kandırmak,

Maksadım sadece doğruyu söyleyip sizi inandırmak,

Ama benim derdim sadece bundan ibaret değil ki!

Sorarım hep; mezara gitmeden camiden geçmek niye?

İnanın, kara kara düşünürüm (Elâlem ne der?)   diye.

Derdimin çaresini kime soracağımı bilemiyorum,

Kızıp da beni hemen kınamalarından çekiniyorum,

Kulağımdan tutup azarlıyacaklarından korkuyorum.

Onun için ben, boynumu büküp çaresiz oturuyorum.

Gitsem, doğru söyleyip yalan yapmış olacağım,

Gitmesem, derdimi nasıl yobazlara anlatacağım.

''Olmaz öyle şey! '' diyenleri nasıl susturacağım,

Yoksa gidip Ali Kalkancı''ya mürid mi olacağım?

Peki oldum diyelim, Fadimeyi nereden bulacağım?

Olsam da nasıl dinsiz imansız onu kandıracağım?

Bu yaştan sonra da onunla nasıl başa çıkacağım?

Yok yok karar verdim, en iyisi yatıp uyuyacağım.', 'Lütfen dinleyip anlayın beni hiç kızmadan, Yoktur benim hiç nâsibim dinle imandan, Anlamam hiç ne ezandan ne de kurandan, Anlarım ama ben Al...', ARRAY['Türk Edebiyatı','Şiir','Necdet Çobanlı']::text[], 8.5, '{"poet":"Necdet Çobanlı","poet_slug":"necdet-cobanli","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/gunah-mi-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Unutur Muyum Sanırsın?', 'seni-unutur-muyum-sanirsin-necdet-cobanli-1j84s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bilmem ki seni nasıl anlatsam, neler yazsam?

Bilmem ki özelliklerinin hangisini saysam?

Varlığınla hep yaşadım; yokluğunda ağlarsam,

Günü gelip kaçınılmaz son yolculuğa çıkarsam,

Mezarımda bile seni unutacak mıyım sanırsın?

Sen, çizilmedik resimsin,  yazılmadık şiirsin,

Yeşillikler arasından akıp gelen bir nehirsin.

Ezberimdeki tek şarkı, tarifsiz bir sevgisin.

Bendeki hakkını hiç unutturmayacak birisisin. 

Sen, beni yalancı ya da vefasız mı sanırsın?   

Sen canım kızlarımızın eşi bulunmaz annesi,

Torunlarımızın hiç unutulmaz  anne annesi,

Sen sıcak yuvamızın sıcak güneşi, bir tanesi,

Sen darda kaldığımda sorunlarımın  çaresi,

Ödenemez hakların unutulacak mı sanırsın? 

Çalıştın, çabaladın, yorgun argın, delice,

İğneyle kuyu kazdın,  emek verdin ömrünce,

''Öff'' demedin,  çevirdin gecemizi gündüze,

Bırak da hepimiz ölelim seni çok seve seve.

Sensiz yaşamın manası var mıdır sanırsın?

Elli yıllık eşsiz, çok mutlu evliliğimin,  

Baş tacı, mimarı, sevgisi, herşeyi sensin.

Canım benim, inan bana, sen daima içimdesin.

Dünyamın her yerinde, kafamda, kalbimdesin.

Ben ölsem de seni hiç unuturmuyum sanırsın?  

Sen canım, bilki ben seninle mutluluğa erdim,

Ölümün dönüşü olsa, inan gene sana dönerdim.

Yine seninle dolar, gene seni candan severdim.

İkinci ölüme de gene sen kalbimdeyken giderdim.

Bu satırlar sadece benim bir şiirim mi sanırsın?', 'Bilmem ki seni nasıl anlatsam, neler yazsam? Bilmem ki özelliklerinin hangisini saysam? Varlığınla hep yaşadım; yokluğunda ağlarsam, Günü ge...', ARRAY['Türk Edebiyatı','Şiir','Necdet Çobanlı']::text[], 8.5, '{"poet":"Necdet Çobanlı","poet_slug":"necdet-cobanli","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/seni-unutur-muyum-sanirsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelin Dinleyin Beni!', 'gelin-dinleyin-beni-necdet-cobanli-n1ioz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dün, bugün, yarın, oburgün. 

Bilmem ki ne zaman kararır gün. 

Yanımda olacakmısınız, karardığı gün? 

Olsanızda olmasanızda ben yokum ki o gün. 

Bakın, az gittik uz gittik, 

Durmadan dere tepe düz gittik. 

Dopdolu bir yaşamı yitirdik, 

Upuzun bir yolun sonuna geldik. 

Önemi yok; gene de şükürler olsun, 

Kızlar ve torunlarımız sağ olsun, 

Bütün hayatları hep dopdolu olsun, 

Bütün mutluluklar onların olsun. 

Kızıp bana, ''Hadi canım sende! ''demeyin, 

Gelin şu seksenlik ihtiyarı dinleyin, 

Kendinizi kederlere hiç teslim etmeyin, 

(Her akşamın bir sabahı vardır,)   deyin. 

Unutmayın ha; ben ak saçlı bir ''Dede'' yim, 

Aklım ve kalbimle hep sizinle birlikteyim, 

Sizlerden uzakta olduğum için de dertliyim. 

Bir gün sizinle olmasam da hep sizinleyim.', 'Dün, bugün, yarın, oburgün.  Bilmem ki ne zaman kararır gün.  Yanımda olacakmısınız, karardığı gün?  Olsanızda olmasanızda ben yokum ki o gü...', ARRAY['Türk Edebiyatı','Şiir','Necdet Çobanlı']::text[], 8.5, '{"poet":"Necdet Çobanlı","poet_slug":"necdet-cobanli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gelin-dinleyin-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebeğim Benim!', 'bebegim-benim-necdet-cobanli-98fbh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bebeğim benim, sen benim canım sevgilimsin, 

Bilki benim için hiç ama hiç vazgeçilmezsin, 

Tünelin ucunu görmene nasıl sevindim bilemezsin, 

Öbür tünelin de ucunu görseydin hiç üzülmezdim. 

Bilmem görecekmiyim yıllardır beklediğim o günleri? 

Bir de sen görebilseydin; aramazdın hiç bu günleri. 

Otuz yıldır inat edip, hiç dinlemedin bu sözlerimi. 

Geç de olsa, nihayet biraz da olsa aç o gözlerini. 

O zaman, inan bana sende bulursun yolun doğrusunu, 

O vakit anlayacaksın hayatın eğrisi ile doğrusunu, 

''Yazık olur, '' deme, öğren artık gelecek zaman olgusunu, 

Otuz yıl sonra bile göreceksin bulacaksın doğrusunu. 

Ben biliyorum, ne aşkı da nede meşki var bu işin, 

Söyle bana ne olur, hiç mi aklın yok ki senin? 

Evin var, barkın var.Seni çok seven çocukların kimin? 

''Yalnızlık mı? '' Korkma sakın; ondan sonra herkes senin. 

Eminim ki; bu dertleri çok çok çabuk atlatacaksın, 

Ayda on beş dolarla zaten keyfine keyif katarsın. 

Arada da şarabını içer seni çok seven beni anarsın, 

Toprağın altında da olsa onu huzura kavuşturursun. 

''Beni güldür'' dedim, sen ağlatıyorsun, '' deme sakın,

Bugün ağlasan bile sözümü dinlersen çok rahat edersin

dinle beni ne olur; bu ikimizin de son ağlaması olsun, 

Sana söz veriyorum artık bu işe son noktayı koyuyorum, 

Sil ne olur göz yaşlarını çünkü seni çok seviyorum, 

Söz veriyorum: Seni artık hiç ağlatmak istemiyorum. 

Seni mutlu bırakıp sizlere öyle veda etmek istiyorum. 

Bebeğim benim, seni çok hem de canımdan çok seviyorum.', 'Bebeğim benim, sen benim canım sevgilimsin,  Bilki benim için hiç ama hiç vazgeçilmezsin,  Tünelin ucunu görmene nasıl sevindim bilemezsin, ...', ARRAY['Türk Edebiyatı','Şiir','Necdet Çobanlı']::text[], 8.5, '{"poet":"Necdet Çobanlı","poet_slug":"necdet-cobanli","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bebegim-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cam Makas', 'cam-makas-kucuk-i-skender-z7tr8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'temmuz yırtılıyor yazın ortasında

küçük padişah ölmüş. ağlıyor alkolik lalası.

bach dinliyor benim karanfilim

dürbünlü tüfeğimin kabzasında verlaine''in 

parmakizleri.

düşürüp kırıyorum cam makasımı.

hüzünlü bir şeyler çalıyor akordeonla eski mevsim.

polisiye bir aşk bizimkisi

polisiye bir caz dinlediğimiz

erken yaşlanır terkedenler

erken ölür ellerini ellerden alıp da gidenler

yakışmaz ayrılık 

yakışmaz ihanet

sarıl bana

sarıl bana

beni sana davet et! 

temmuz yırtılıyor yazın ortasında

gümüş çocukların birbirlerini seyretmekten

utandıkları bir yerlerde. sen! bana artık

rimbaud deme! büyük bir buz kalıbı içinde

sonsuz uykusunda köpek yüreğim! 

arkama bakmadan öleceğim.

bir melek tıraş edecek saçlarımı

bir cin yıkayacak beni özsuyuyla

tertemiz entarilerimi giydirecekler sonra

gitmeme izin verme! 

vals bitiyor

çiftler öpüşüyorlar usulca

usulca pelerinini açıyor sis

usulca dönüyor baş

zehirli içkimi uzatıyorum karşımdaki 

satranç ustasına.

bir tarot destesinde buluyorum vesikalık resmimi

hangi kaderle çıkıyorsun karşıma

-karşım: nedir ki ellerim-

nasıl bir mutluluk mutluluğun

nedir senin sevdalarının kılavuzu

ödüllü bir hanımefendi gibi giriyorsun düşüme

talan ediyorsun

yakıyorsun

rüyalarım yanıyor

o zaman

ben de düşürüp kırıyorum cam makasımı

yalızlar bahçesinde

çiçeğiburnunda çiçeği topluyorum

peradaki bütün ampuller kırmızı

tramvaya binmiyor sokak sokak kendi

çocukluğumun troleybüslerini arıyorum

bir satyr''le sevişmemle başlıyor

çağımın gerisinde kalan hatıralarım

o zaman

bach dinliyor benim karanfilim

temmuz yırtılıyor yazın ortasında 

başkalarının aşk mektuplarında buluşuyoruz.

yoruluyorum seni sevmekten

düşürüp kırıyorum cam makasımı.

28.ocak.1991

      İstanbul,', 'temmuz yırtılıyor yazın ortasında küçük padişah ölmüş. ağlıyor alkolik lalası. bach dinliyor benim karanfilim dürbünlü tüfeğimin kabzasında ...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/cam-makas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Adam Gördüm', 'bir-adam-gordum-necdet-cobanli-ug9h4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir adam gördüm, gözleri yaşlı.

Yüzü bumburuşuk, asık suratlı.

Acıyıp sordum: ''Neden böylesin? ''

(Yok bir şeyim ben, iyiyim)   dedi.

Ama besbelli, onun bir derdi vardı.

Susup bekledim; sonra da o konuştu:

(Evet var derdim, ama çaresi yok ki)  

''Olmaz mı vardır her derdin bir çaresi.''

''Yok, yok beninkinin çaresi,

Herkes çekmiş benim çektiğimi,

Ama nedense bana ağır geliyor,

Kabul edemiyorum, herkesin kabul ettiğini.''

''Üzme kendini, söylesene derdini.''

''Peki söyleyeyim ama sen söyleme kimseye.''

''Peki peki, sen söyle hele.''

''Gözü körolası, ihtiyarlık.''', 'Bir adam gördüm, gözleri yaşlı. Yüzü bumburuşuk, asık suratlı. Acıyıp sordum: ''Neden böylesin? '' (Yok bir şeyim ben, iyiyim)   dedi. Ama bes...', ARRAY['Türk Edebiyatı','Şiir','Necdet Çobanlı']::text[], 8.5, '{"poet":"Necdet Çobanlı","poet_slug":"necdet-cobanli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-adam-gordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimliğimi Verin! ..', 'kimligimi-verin-kucuk-i-skender-d2ubc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kimliğimi verin gideceğim-şimdi, 

kaba(r) etlere kül suyu dökeceğim

uzun kürk mantolu bir rahibe 

seyredecek beni

kucağında bir leopar yavrusu/

şaşıracağım doğrusu

                                   gülümseyeceksiniz

elimi tutup kökümle birlikte özgür

savrulacağım bir kentin yakamozlarına

bakışlarımda çılgınca bir nüfus patlaması

ağzımda bana hiç yakışmayan 

                                   bir genç kız fidanı

odalarımı toplayacağım

dişlerimizi fırçalayacağım

portrelerinizi yapmayacağım ama, 

resimleriniz

daima imha edilecek birer ayçiçeğidir..

kimliğimi verin gideceğim -şimdi, 

özledim özledim öpüşmelerinizi özledim

özledim özledim öksürürken renk fışkırtmanızı

yürüyüşlerinizi, oturuşlarınızı..

sanki yürek hastası on ikisinde çocuğum

adınız oluyor içimde taşıdığım frengi boşluk

hanginiz tarayacak ki saçlarımı

saçlarım

daima ihmal edilecek birer yorgunluktur..

kimliğimi verin gideceğim-şimdi, 

çünkü sürekli ağlıyor gibi bir şeyim

ve yüzümde 

ağır ağır sürüklenen bir yaz ikindisi..

4.nisan.1988', 'kimliğimi verin gideceğim-şimdi,  kaba(r) etlere kül suyu dökeceğim uzun kürk mantolu bir rahibe  seyredecek beni kucağında bir leopar yavru...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/kimligimi-verin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilseydin', 'bilseydin-melek-midikoglu-oho3s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Damla damla dökülür yağmur

Gözyaşlarım gibi...

Varlığınla yokluğunun anlaşılmaz tadını

anlatır gibi...

Belki de aşka susuzluğumun

isyanı gibi...

O bulutlardan yapraklara, toprağa

Sen ise kalbimden gözlerime

Akar durursun bir nehir misali

Yokluğun varya o kahrolasıca yokluğun

Ağlatır beni hep ağlatır

Söyle ona ne olur artık gelmesin...

Neredesin, kimbilir neredesin? ! 

Belki pencerende yağmuru seyrettiğini 

sanıyorsundur

Bir bilseydin onlar benim gözyaşlarım, 

Koşar gelirdin. 

Ah bilseydin bir de üşüdüğümü, 

Sarılıverirdin.

Nereden bileceksin..', 'Damla damla dökülür yağmur Gözyaşlarım gibi... Varlığınla yokluğunun anlaşılmaz tadını anlatır gibi... Belki de aşka susuzluğumun isyanı gib...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bilseydin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevişmeler', 'sevismeler-i-smail-korkmaz-l907w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevdanın ateşi eğer 

Her an yanıbaşımda yatmasaydı 

Ben bu yükü taşıyamazdım 

Sevinçlerime biraz hüzün katan odur 

En çaresiz anımda 

Issız bir dere kenarını 

Şırıl şırıl akan suları hatırlatır bana. 

Gülüşmelerimizden arta kalan zamanlarda sevişir 

Sevişmelerimizden arta kalan zamanlarda 

................................................yıldızları sayardık. 

Bu hep böyle sürecek sanırdık. 

Göz hapsine tutardık birbirimizi 

Saatlerce usanmadan. 

O ağladığında ben gülerdim 

bir gün beraber ağladık ve ayrıldık. 

Belkide o günden sonra hiç yaşamadık. 

Bilsen ki nekadar pişmanım. 

Sırf inat oldun diye 

Karşı çıkardık birbirimize 

Konuşmadan geçen saatlerimiz 

Bakışmalarla geçerdi. 

Demekki anlatamadık 

Esirgedik birbirimizden birşeylerimizi 

Sırf inat olsun diye. 

Sırf inat olsun diye sevdik. 

karşıydı çünkü birileri bize. 

Sırf inat olsun diye ayrıldık 

Sırılsıklam aşıktık çünkü birbirimize. 

Bilsenki nekadar pişmanım. 

Suç sende 

..................ve 

......................bende. 

9 Aralık 1999-Münih', 'Sevdanın ateşi eğer  Her an yanıbaşımda yatmasaydı  Ben bu yükü taşıyamazdım  Sevinçlerime biraz hüzün katan odur  En çaresiz anımda  Issız ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Korkmaz']::text[], 8.5, '{"poet":"İsmail Korkmaz","poet_slug":"i-smail-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sevismeler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkinci Kez Oluyor', 'i-kinci-kez-oluyor-cem-kivancli-iuxcr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '2.kez oluyor

Heyecan, sevinç

Ama bu seferki titretiyor

Adına aşk dedikleri bir şeyle beni korkutuyor

2.kez oluyor

Adına sevgi dedikleri şeyle

Beni vuruyor

Bu ilk olmuyor

2.kez oluyor

Adına ayrılık dedikleri

Bir hüzün bombası ile

Beni parçalıyor

Dedimya 2.kez oluyor

Ayrılıkların sonu gelmiyor...', '2.kez oluyor Heyecan, sevinç Ama bu seferki titretiyor Adına aşk dedikleri bir şeyle beni korkutuyor 2.kez oluyor Adına sevgi dedikleri şeyl...', ARRAY['Türk Edebiyatı','Şiir','Cem Kıvançlı']::text[], 8.5, '{"poet":"Cem Kıvançlı","poet_slug":"cem-kivancli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ikinci-kez-oluyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Hikayesi', 'ask-hikayesi-cem-kivancli-eq78w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen benim hikayemsin

Hep yazmak istediğim

Yazamadığım sonu hep belli olan

Yazmaktan koktuğum sonunu değiştirmek

İstediğim bir hikaye

Çünkü bu sonbaharda sensizliğin

Hikayesi hiç ama hiç güzel olmazdı

Çünkü bu roman olurdu, o kadar uzun hikaye olmazdı

Dedim ya sen benim hikayemsin

Hep yazmak istediğim ama yazmaktan korktuğum

Bir hikaye

Sen benim hikayelerimin en güzelisin

Belkide ilkisin ama en özelisin

Şunu bilmeliydim aşk hikayelerinin sonunda

Hep ayrılık olurdu, ben bunu bilemedim

Ama sen gidince anladım

Demekki bu hikayenin sonu ta baştan belliymiş

Neyse aşk hikayemsin bunu bilmelisin

Ben artık aşkların sonunu baştan okuyorum

Ne yapabilirim aşk bir volkan gibidir

Yakar kavurur sonundada bırakıp gider

İşte sen öylesin dediğim gibi aşk hikayemsin', 'Sen benim hikayemsin Hep yazmak istediğim Yazamadığım sonu hep belli olan Yazmaktan koktuğum sonunu değiştirmek İstediğim bir hikaye Çünkü b...', ARRAY['Türk Edebiyatı','Şiir','Cem Kıvançlı']::text[], 8.5, '{"poet":"Cem Kıvançlı","poet_slug":"cem-kivancli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ask-hikayesi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-cem-kivancli-ktd99', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşk dedikleri şey böyleymiş

İnsanı en çok mutlu olduğu anda

Mutsuzluğa terkedermiş

Aşk dedikleri şey böyleymiş

İnsanı sevinçten deli ederken

Üzüntüden yok edermiş

Aşk dedikleri şey böyleymiş

İnsanın aklına sevdiğinden başka bir şey

Getirmezken çok şey götürürmüş

Aşk dedikleri şey böyleymiş

İnsanı hiç ayrılamam derken

Sevdiğinden ayrı koyarmı', 'Aşk dedikleri şey böyleymiş İnsanı en çok mutlu olduğu anda Mutsuzluğa terkedermiş Aşk dedikleri şey böyleymiş İnsanı sevinçten deli ederken...', ARRAY['Türk Edebiyatı','Şiir','Cem Kıvançlı']::text[], 8.5, '{"poet":"Cem Kıvançlı","poet_slug":"cem-kivancli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-128-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Prangadan Fışkıran Sorumluluk', 'prangadan-fiskiran-sorumluluk-ali-dikili-1o4sa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ruhuma atılan kementler iflahımı keserken birer birer

Yüreğin muhkem surlarını geçemeyen aşk, 

Ç-a-t-l-a-t-ı-l-ı-r, 

Kanıksanamamış kanıt metal boğumlar fırlatılıp atılır.

Sonra aşk, sanrıların mezarlığında bir mezara gömülür.

Belki de gömülmez ne bileyim.

Gömülmez ama, kalleş zamanın sırıtan yüzüne savrulur küller en azından

Bir züğürdün intikam edasıyla.

Gidemem heveslerimin peşi sıra, 

Lakin dünü yarının nadasına bırakır, aydınlık bir yüz

Ve acı azalmaya yüz tutarken

Prangası tehdit oklarını yönlendirir benliğime doğru hala

Evet hala.

ikibinüçyılınınocakayınınyirmibirincigünüsalı, ankara', 'Ruhuma atılan kementler iflahımı keserken birer birer Yüreğin muhkem surlarını geçemeyen aşk,  Ç-a-t-l-a-t-ı-l-ı-r,  Kanıksanamamış kanıt me...', ARRAY['Türk Edebiyatı','Şiir','Ali Dikili']::text[], 8.5, '{"poet":"Ali Dikili","poet_slug":"ali-dikili","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/prangadan-fiskiran-sorumluluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Revolution', 'revolution-mehmet-guzelyurt-y4216', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Onu otururken görmelisiniz; 

Eli alnında kitap okurken

Etli dudakları azıcık aralık: 

Martılar ve sözcükler rahatça girip yuvalansınlar diye...

Yürürken görmelisiniz onu; 

Hiç bir kadının bilekleri

Çizemez böyle bir yörünge kaldırımlara

Ve gündelik hayatın o kutsal ciddiyeti

Ezilir, ıslak bir köpeğe döner

Ayaklarının arasında..

Tartışırken görmelisiniz bir de: 

''Yaşam ikircikli olmayı bağışlamaz! ''

Bunun bilincinde ki

Ele geçirmiş sanki yaşamın gizli formüllerini

Kendinden emin ve burun hafifçe kalkık! 

Ve ille de sevişirken görmelisiniz onu

Yutmak için küçük dilinizi..

Islak köpek, martılar, irili ufaklı maskeler, kibir ve diğerleri, 

Hepsi yatağın az ötesinde uysalca beklerler..

Öperken, koklarken, inlerken, 

Kaldırımlardaki pervasız yörüngelerin sahibi değilmiş gibi, 

Yüzünde öyle dingin, öyle masum, öyle içten bir tebessüm, 

Salar üstüme yaşamın gizlerini

Kanayan yerlerimi öpsünler diye..

(Antalya-6 Ekim 1995)', 'Onu otururken görmelisiniz;  Eli alnında kitap okurken Etli dudakları azıcık aralık:  Martılar ve sözcükler rahatça girip yuvalansınlar diye...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Güzelyurt']::text[], 8.5, '{"poet":"Mehmet Güzelyurt","poet_slug":"mehmet-guzelyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/revolution-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben De Şu Dünyaya Geldim Geleli', 'ben-de-su-dunyaya-geldim-geleli-pir-sultan-abdal-f4lf5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben de şu dünyaya geldim geleli

Emanetten bir don giymişe döndüm

Sahibi çıktıda elimden aldı

Koru yerde koyun yaymışa döndüm

O yar geldi geçti geri bakmadı.

Hendekler kazdırdım sular akmadı

Çok yuva bekledim cücük çıkmadı

Boş yuva beklemiş yoz kuşa döndüm

Pir Sultan abdalım bu dünya fani

Baştan başa kim sürdü bu devranı

Yarin bir çift sözü üşüttü beni

Yüce dağ başında donmuşa döndüm', 'Ben de şu dünyaya geldim geleli Emanetten bir don giymişe döndüm Sahibi çıktıda elimden aldı Koru yerde koyun yaymışa döndüm O yar geldi geç...', ARRAY['Türk Edebiyatı','Şiir','Pir Sultan Abdal']::text[], 8.5, '{"poet":"Pir Sultan Abdal","poet_slug":"pir-sultan-abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-de-su-dunyaya-geldim-geleli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elbette', 'elbette-mehmet-guzelyurt-rq800', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uzak yerlerden geldim dün gece

Bu yüzden eteklerimdeki yıldızlar, 

Gözlerimdeki kelaynak yuvaları bu yüzden

Aklımın tavanına bir yıldız asıldı durdu yol boyunca: 

Sen.

Uyuyordun, ellerin yastığındı; savunmasızlığın yorganın..

Ve ne denli bilincindeyse bir ardıç kuşu koca dünyanın

İşte o kadarcık farkındaydın sen de, neler olup bittiğinin..

Bense delirmelerin ve aklın dışında, 

Açıklanmamış tüm sırların gözü doymaz arsızı

Gülüyordum boyuna..

Ve işte, yukarıda

Ne idüğü belirsiz bir dolunay

Acemi bir telaşla, sözüm ona bulutların ardına  saklanarak

(Halbuki ödünç beyaz gömleği gün gibi ortada) 

İzliyordu adım adım, bıkmadan: 

Treni

Trenin içindeki beni

Benim içimdeki seni

Senin içindeki treni..

(14 Mayıs 1995)', 'Uzak yerlerden geldim dün gece Bu yüzden eteklerimdeki yıldızlar,  Gözlerimdeki kelaynak yuvaları bu yüzden Aklımın tavanına bir yıldız asıl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Güzelyurt']::text[], 8.5, '{"poet":"Mehmet Güzelyurt","poet_slug":"mehmet-guzelyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/elbette-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizlik', 'sessizlik-barbaros-mustafa-guner-7smaw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilmiyorum ben sessizken kim neler düşünüyor? 

Ama sessiz kaldığımda biliyorumki

Elle tutulamıycak şeyler var içimde, 

Gözle görülemiyecek..

Sadece gözlerime bakıpta düşündüğünü gördüğümde, 

Biliyorumki sadece sana vermek istediğim

Bi damla gülümseyi, bi de o çingene kızının elindeki gülü

görüyosun.

Asla ellerinle tutamayacağını bilsende ayışığı simsiyah gölgeler yaratıyor üzerimde.

Kapı açık gir içeri

Gece bitmek üzere...', 'Bilmiyorum ben sessizken kim neler düşünüyor?  Ama sessiz kaldığımda biliyorumki Elle tutulamıycak şeyler var içimde,  Gözle görülemiyecek.....', ARRAY['Türk Edebiyatı','Şiir','Barbaros Mustafa Güner']::text[], 8.5, '{"poet":"Barbaros Mustafa Güner","poet_slug":"barbaros-mustafa-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sessizlik-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçüğüm...', 'kucugum-ugur-deniz-ulkegul-3qrid', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''Hiç kimse senin kadar uzak olmadı benden...Hiç kimse bu kadar yanıma yaklaşmadı, bulunduğu yerden...''

   Küçüğüm, 

   Sana cesaret veriyorum bir tutam, 

   Bir çay kaşığı da sevgi...

   Bir de yağmurda ıslanmış toprak kokusu, 

   Ara sıra çek diye içine buram buram....

   Ezmeyesin diye güçsüzü zayıfı, 

   Bir kucak dolusu korku veriyorum sana, 

   Biraz da merhamet yükledim sırtına....

   Ağlayabilesin diye biraz acı, 

   Direnebilesin diye bir nebze sancı....

   Büyüdükçe büyüyecek dertlerin, 

   Azalacak gitgide sevgilerin, 

   Korkutasın diye düşmanlarını, 

   Biraz nefretle sıvazladım avuçlarını....

   Biraz da umut koydum cebine, 

   Biraz düş, 

   En yalnız zamanlarında, 

   Kaybetme diye umutlarını, biraz gülüş...

  ....

   Küçüğüm, 

   Sana bir cinayet bıraktım, bul diye

   Bir de doğum sancısı, bitkin düş yorul diye...

   Bir de gölgeni bıraktım ayağının dibine, 

   Kaybedersen insanlığını, yeniden doğrul diye...

   Bir silah, bir de gül koydum masana, 

   Gülü sev, 

   Sevgi için vur, vurul diye......

   Kötü adamlar bıraktım mahallenizde, 

   Sevgililer bıraktım şehrinizde, 

   Çocuklar bıraktım bir de, 

   Hani her biri, içinizde....

   Dostluğu bırakamadım yalnız, 

   Bir de aşk''ı, 

   Bir de sana yazdığım en güzel şiiri...

   Dostu bulamadığımdan, 

   Aşk''ı bilemediğimden belki...

   Şiiri ise hala yazmaktayım, 

   Bitiremediğimden bil ki.......

  .....

   Küçüğüm, 

   Sana cesaret veriyorum bir tutam, 

   Bir çay kaşığıda sevgi....

   Cesareti yüreğine koy, 

   Sevgini denize at, 

   Nefreti toprağa karıştır....

   Sonra yağmuru dinle biraz, 

   Birazda toprağı kokla derinden, 

   Sevgiyle nefreti barıştır...

   Sonra büyüdün demektir artık, 

   Git gidebildiğin yere, sev sevebildiğini, 

    Her kaybediş sonrası, 

    Kalk ayağa yeniden..Yen yenebildiğini.....', '''Hiç kimse senin kadar uzak olmadı benden...Hiç kimse bu kadar yanıma yaklaşmadı, bulunduğu yerden...''    Küçüğüm,     Sana cesaret veriyoru...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/kucugum-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlaç', 'i-lac-i-smail-korkmaz-8pocx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Üç öğün ilaç olmuşsun 

ebedi hastalığıma 

Sabah, öğle, akşam 

Ellerinden tutup 

Gözlerine bakıp 

Yanağından birerdefa. 

10 Ocak 1994-Niksar', 'Üç öğün ilaç olmuşsun  ebedi hastalığıma  Sabah, öğle, akşam  Ellerinden tutup  Gözlerine bakıp  Yanağından birerdefa.  10 Ocak 1994-Niksar...', ARRAY['Türk Edebiyatı','Şiir','İsmail Korkmaz']::text[], 8.5, '{"poet":"İsmail Korkmaz","poet_slug":"i-smail-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ilac-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardelen Çiçeği', 'kardelen-cicegi-nizamettin-dereci-ab7go', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayat durdu sanki, 

Ovalarım, dağlarım kış uykusunda.

Binbir çiçekle süslenen yaylalarım

Nerde karçiçeklerim, ? nerde? sorarım

Başını kaldırtmadı mı? karlar? 

Sardılar mı o nazenin gövdeni? 

Ne olur biraz gayret, yırt kefenini.

Sessizce gel, 

Ama mutlaka gel.

Hatta, beyaz renginle, kar''dan sansınlar, 

Soğuktan oluşmuş, don''dan sansınlar

Gel, vefayı öğret, 

Dostluğu öğret bize.

Güneş altında güllenen çiçekler kıskansın, 

Ne çıkar, seni de insanlar Kar''dan sansın', 'Hayat durdu sanki,  Ovalarım, dağlarım kış uykusunda. Binbir çiçekle süslenen yaylalarım Nerde karçiçeklerim, ? nerde? sorarım Başını kaldır...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Dereci']::text[], 8.5, '{"poet":"Nizamettin Dereci","poet_slug":"nizamettin-dereci","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kardelen-cicegi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Tanem', 'kar-tanem-nizamettin-dereci-3iteg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gökyüzünde uzun yollar katedip

Yorgun düşmüş bir hal aldın kar tanem.

Yeryüzünde sana hasret ben varken, 

Başka diyarlara daldın birtanem.

Yağışında, uçuşunda zerafet, 

Yorgunluğun yorar beni kartanem.

Yokluğunda yok olmak düşer bana, 

Gözlerim hep seni arar birtanem.', 'Gökyüzünde uzun yollar katedip Yorgun düşmüş bir hal aldın kar tanem. Yeryüzünde sana hasret ben varken,  Başka diyarlara daldın birtanem. Y...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Dereci']::text[], 8.5, '{"poet":"Nizamettin Dereci","poet_slug":"nizamettin-dereci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kar-tanem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakma..!', 'bakma-nizamettin-dereci-9g9wl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dipsiz kuyu, kirli suyu dünyanın, 

Bakma, insanları nefes alıp veriyor.

Faydası yok, yazmanın, okumanın, 

Bakma öğretmenler figan ediyor.

Büyük, küçük, saygı, sevgi nostaji, 

Bakma, okullarda ant içiliyor, 

Sözüm senet, lafı mı olur filan, 

Bakma, günü geldimi yan çiziliyor.

İlim, irfan, tasavvuf rafa kalktı, 

Bakma, bazıları el öptürüyor.

Sömürü düzeni, hırs şaha kalktı, 

Güçlüler, zayıfa kök söktürüyor.', 'Dipsiz kuyu, kirli suyu dünyanın,  Bakma, insanları nefes alıp veriyor. Faydası yok, yazmanın, okumanın,  Bakma öğretmenler figan ediyor. Bü...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Dereci']::text[], 8.5, '{"poet":"Nizamettin Dereci","poet_slug":"nizamettin-dereci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bakma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahtiyarım', 'bahtiyarim-osman-oztunc-i6t9b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben böyle bahtiyarım

Sen gül, sen oyna

Okuluna git yavrum

Farzet ki bizim yarın

Kendine iyi bak yavrum kardeşin ağlamasın 

Erkenden uyursan

Sabah tez gelir yavrum

Farzet ki bizim yarın

Bak oğlum dinle sözümü

Ne diriyim ben, ne ölü

Anız altı topraklarda 

Ben güneşin içindeyim

Mavi kanat gökyüzünde İsa ile birlikteyim

Dinle, dinle de davran! 

Zalime kaşlarını çat

Zulümü ne gör, ne unut

Dar günler içinde öyle zorba bir yolki

Karanlığa ışık tut

Varıp gerçek olana

Sırda nur bulana

Bırak Karac''oğlanı bırak pınar başına

Yunusla yarış yavrum

Erenler, sultanlar, pirler

Yardımcı üçler, yediler

Vakit gaza vakti yavrum

Hazırlan zalime şahlan

Alev başlı kartal olup hürriyete kanatlan

Durma, durma ha davran!', 'Ben böyle bahtiyarım Sen gül, sen oyna Okuluna git yavrum Farzet ki bizim yarın Kendine iyi bak yavrum kardeşin ağlamasın  Erkenden uyursan ...', ARRAY['Türk Edebiyatı','Şiir','Osman Öztunç']::text[], 8.5, '{"poet":"Osman Öztunç","poet_slug":"osman-oztunc","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bahtiyarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ATA’YA ŞİKAYET', 'ata-ya-si-kayet-ahmet-kurt-aocdw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Fikirle değil de, kavgayla girdik, 

Bilimi tekniği, unuttuk ATAM.

Bütünü ararken kayboldu dirlik, 

Sevgiyi saygıyı kuruttuk ATAM.

Çizdiğin sınırlar tartışma oldu, 

Kutsal emanetin pazara döndü, 

Milletin gözünde umutlar söndü, 

Hüznü gönüllerde büyüttük ATAM.

Çağdaş medeniyet hayalet şimdi, 

Güçlünün cebinde adalet şimdi, 

Gururu unuttuk, asalet sindi, 

O büyük gemiyi çürüttük ATAM.

Sevr paçavraydı Lozan’dan önce, 

Tezgahlar kuruldu inceden ince, 

Boyanıp sunuldu, şimdi güzelce, 

Timsahın ağzına atıldık ATAM.

Gençlerin hedefsiz, eğitim bitti, 

En gümrah nehirler ömür tüketti, 

Ümitler kayboldu, rüyalar bitti, 

Kaynağı hortuma yürüttük ATAM.

Eşkıya şehirde karargah kurdu, 

Mazlumu, garibi yürekten vurdu, 

Seven evlatların hayale durdu, 

Gerçeği hayale bürüttük ATAM.

İşaret etmiştin işte Akdeniz, 

Baktıkça sarardı soldu benzimiz, 

Şimdi kafa tutar dünkü bendemiz, 

Koca bir milleti uyuttuk ATAM.

Kurdoğlu hasrettir çizdiğin yola, 

Doğudan batıya durdu kol kola, 

Büyükler sağ olsun süresiz mola, 

Verdiler derinden yürüttük ATAM.', 'Fikirle değil de, kavgayla girdik,  Bilimi tekniği, unuttuk ATAM. Bütünü ararken kayboldu dirlik,  Sevgiyi saygıyı kuruttuk ATAM. Çizdiğin s...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ata-ya-sikayet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yastadır', 'yastadir-osman-oztunc-ls6pb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şahım bu bayram gününde sultanım, 

Niye intizarda, niye yastadır, 

Eriyor gözler önünde sultanım, 

Niye intizarda niye yastadır.

Nedendir bu gamı efkarı niye, 

Efkarı gönülden deruni niye, 

Ey güzeller şahı sor hele niye, 

Niye intizarda, niye yastadır.

Ulular ulusu ey şahlar şahı, 

Sürükle sineme gönder bu ahı, 

Ermişler sultanı, cem padişahı, 

Niye intizarda niye yastadır.

Bu bayram gününü efkarlı açtık, 

Cümle divani, ervah birden ağlaştık, 

Sorduk şaha şah yönünde eğleştik, 

Niye intizarda niye yastadır.

Hu OSMANın sırrı dem efendisi, 

Hu OSMANın sırrı cem efendisi, 

Hu OSMANın sırrı gam efendisi, 

Niye intizarda niye yastadır.', 'Şahım bu bayram gününde sultanım,  Niye intizarda, niye yastadır,  Eriyor gözler önünde sultanım,  Niye intizarda niye yastadır. Nedendir bu...', ARRAY['Türk Edebiyatı','Şiir','Osman Öztunç']::text[], 8.5, '{"poet":"Osman Öztunç","poet_slug":"osman-oztunc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yastadir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dediler Dediler Ya', 'dediler-dediler-ya-handan-sezginer-5l89x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu pınar böyle derinden çağlamazdı 

Dediler.

Sen hep gülerdin, gözlerin ağlamazdı

Dediler.

Zaten vefasızdı, sana yaramazdı

Dediler.

Dediler demesine ya, demesi kolay.

Silin! dedim kalbimden, 

SİLEMEDİLER.', 'Bu pınar böyle derinden çağlamazdı  Dediler. Sen hep gülerdin, gözlerin ağlamazdı Dediler. Zaten vefasızdı, sana yaramazdı Dediler. Dediler ...', ARRAY['Türk Edebiyatı','Şiir','Handan Sezginer']::text[], 8.5, '{"poet":"Handan Sezginer","poet_slug":"handan-sezginer","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dediler-dediler-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlattılar Beni', 'aglattilar-beni-handan-sezginer-uf8z8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bırak be meyhaneci; boşver.

Boşalan tozlu şişeler olsun.

Bir de benim içim başlarsa boşalmaya

Yanıbaşıma oturduğuna pişman olursun.

Bu benim ilk gelişim meyhaneye.

İlk aldanışımın şerefine içiyorum.

Bir kara gözlüm vardı benim eskiden, 

Bugün onun düğününü kutluyorum.

Aldırma be meyhaneci boşver.

Giden kara gözlüler olsun.

Yeşili gelir yerine, mavisi gelir.

Yeter ki ''O'' mutluluğunu bulsun.

Buraya hep dertlenenler gelirmiş

Meyhaneci.

Ben acıyı o kara gözlerde buldum.

İnanmak benim suçum meyhaneci

İnandığım kadar aldandım, 

Sevdiğim kadar unutuldum.

Elimden düştü! Kızma be meyhaneci

Kırılan şu tozlu şişeler olsun.

Benim tertemiz kalbimi kırdılar bugün

Ağlattılar beni meyhaneci

OYSA

Erkekler ağlamazmış.

AĞLATTILAR BENİ

Dinliyor musun?', 'Bırak be meyhaneci; boşver. Boşalan tozlu şişeler olsun. Bir de benim içim başlarsa boşalmaya Yanıbaşıma oturduğuna pişman olursun. Bu benim...', ARRAY['Türk Edebiyatı','Şiir','Handan Sezginer']::text[], 8.5, '{"poet":"Handan Sezginer","poet_slug":"handan-sezginer","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/aglattilar-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliğin Ezgisi', 'sensizligin-ezgisi-handan-sezginer-dbqid', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu akşam ilk defa aradım seni

Köhne sokaklarında, 

Kirli kaldırımlarında bu kentin.

İlk defa bağırdım adını avaz avaz.

Ve; utanmadan

Hıçkıra hıçkıra ağladım sokaklarda.

Gecenin kirliliğini yeni farkettim

Yeni anladım temizini

Pisini dünyanın.

Elektrik lambalarının tozunu

Kedilerin arzısını bu gece gördüm.

Acıyı bu akşam içtim ilk defa

Kirli kadehlerinden köhne bir meyhanenin

İlk kez hayal ettim

En mutlu günümüzde

Siyah giysilerinle seni

Umutlarımızı, arzularımızı düşündüm.

Sonra gittiğin sisli sabahı.

Trenin acı düdüğü çınladı kulaklarımda.

Senin yaşlı gözlerin geldi aklıma.

Unutma! diye haykıran sesin geldi.

Gidişin, 

Ardından kahreden mektubun.

Resmin geldi aklıma sonra

Buruşmuştu cebimde.

Düzelttim önce özenerek.

Sonra milim milim yırttım.

Onu parçalayıp yok ettiğim gibi

Seni de, sevgini de

Söküp atmak geldi içimden

Ellerim çaresizce gitti yüreğime

Ve... adın istemeksizin 

Döküldü dudaklarımdan

Üstüste, birbiri ardınca döküldü.

Avaz avaz.

Deli dediler bana, delirmiş dediler

Sarhoş dediler, aldırmadım.

Sonra dışarı attılar beni, istemediler.

aynı senin gibi, 

İşte o zaman ağladım ilk olarak

Hıçkıra hıçkıra ağladım

Hayretle bakan gözlere aldırmadan

Evrenden korkmadan ağladım.

İlk defa bu akşam unutmak istedim seni

Ve..Delice sevdiğimi bugün anladım.', 'Bu akşam ilk defa aradım seni Köhne sokaklarında,  Kirli kaldırımlarında bu kentin. İlk defa bağırdım adını avaz avaz. Ve; utanmadan Hıçkıra...', ARRAY['Türk Edebiyatı','Şiir','Handan Sezginer']::text[], 8.5, '{"poet":"Handan Sezginer","poet_slug":"handan-sezginer","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/sensizligin-ezgisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Unutulmayacaksın', 'sen-unutulmayacaksin-handan-sezginer-tmgrj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güneş doğmaktan usanacak bir gün

Dinecek yaşları bulutların

Gök yerle kucaklaşacak özlemini yitirmek için

Ben; yana yakıla seni arayacağım o gün.

Duyacaksın.

Bileceksin ki unutulmamışsın.

Anlıyacaksın ki unutulmayacaksın.

Avuçlarım her açılışında gökyüzüne

Dudaklarımda dua olacaksın.

Evren bir gün tümüyle unutacak seni

Unutacak ya, 

SEN UNUTULMAYACAKSIN.

Sevdan öyle yüceltti ki seni gönlümde

Hep erişemeyeceğim yerlerde olacaksın.

tutamayacağım seni nice uzansam, lakin

SENUNUTULMAYACAKSIN.

Dinmeyecek, tükenmeyecek bu ayrılık

Bitmeyecek, yitmeyecek bu sevda

Haykıracağım sazımın telleri kırık; 

Duymayacaksın.

İster duy, ister duyma seni arayan sesimi

SEN UNUTULMAYACAKSIN.

Kara sevda bu benimke.

Nedir bilir misin? 

Yaşam bu; tükenir bir gün.

Durdurabilir misin? 

Sen de bir gün elbet toprak olacaksın.

Ben yaşasam da ölmüş olacağım o gün.

Tüm evren unutacak.

Yiten varlığımızla bizi.

Lakin; bir ben varım ki, 

Sevdanı içimden alamayacaksın.

GİT! Mahşere değin geleceğim seninle.

Kaçamayacaksın.

Unut, dilediğini haykır, sevmediğini söyle

Gene de

SEN UNUTULMAYACAKSIN.', 'Güneş doğmaktan usanacak bir gün Dinecek yaşları bulutların Gök yerle kucaklaşacak özlemini yitirmek için Ben; yana yakıla seni arayacağım o...', ARRAY['Türk Edebiyatı','Şiir','Handan Sezginer']::text[], 8.5, '{"poet":"Handan Sezginer","poet_slug":"handan-sezginer","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sen-unutulmayacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Değişmedi', 'gonul-degismedi-oguzkan-bolukbasi-29f7c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kelimeler bile güzellik arıyor

saadetler mutluluğa

hissiyatlar duyguya dönüşürken

leblerin dudaklarda öpüşürken

hazan sonbaharı oluyor ömrün

birtek adı değişmedi gönlün', 'kelimeler bile güzellik arıyor saadetler mutluluğa hissiyatlar duyguya dönüşürken leblerin dudaklarda öpüşürken hazan sonbaharı oluyor ömrün...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gonul-degismedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitirdiğimiz Anılar', 'yitirdigimiz-anilar-handan-sezginer-2141t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevdalar kovalayacak insanları gayrı yığın yığın

Gün bir başka doğacak her gün bin kahırla

Yitirdiğimiz anılar için ağlarken rüzgarlar

Anımsanmayacak aşklar var yığınca masallarda...

Nasır tutmuş çatlak eller arasında yeşermiş umutlar

Ve.. şarkılarda ağlayanlar bizleriz çoğu zamanlar

Yakılan bunca ağıtlar bizlere değil mi? 

Adem olup dünyaya gelenler diye başlar...

Sarı resimlerde yaşanırken geçici mutluluklar

İnsanın içini kemiren buruk, ağlatan bir şarkı, 

Ve acı dolu bakışlarımızda

Yaşam denizleri artık fırtınalı...', 'Sevdalar kovalayacak insanları gayrı yığın yığın Gün bir başka doğacak her gün bin kahırla Yitirdiğimiz anılar için ağlarken rüzgarlar Anıms...', ARRAY['Türk Edebiyatı','Şiir','Handan Sezginer']::text[], 8.5, '{"poet":"Handan Sezginer","poet_slug":"handan-sezginer","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yitirdigimiz-anilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Yaşarken', 'seni-yasarken-handan-sezginer-cbveh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Soğuktu, 

İnsanın iliklerine işleyen bir soğuk.

Seni düşünüyordum.

Her geçen gölge sana benziyordu

Penceremin önünden, 

Her gölgenin ardından ağlıyordum.

Akşamdı.

Yeni yeni çökmüştü sulara karalar.

Son ışıklarını topluyordu güneş evrenden.

Düşündüm de

Senindi içimdeki bütün yaralar.

Her dem eskiye dönüyordum

Bilmeden istemeden.

Boşalmıştı hazana boyun eğen ağaçlar.

Her solan düşen yaprakta

Kendimi buluyordum.

Tükendiğim kadar yok olmaktı dileğim.

Her düşen yaprağa imreniyordum.

Tüm kirleri örtmüştü delice yağan kar

Bütün karaları yenmişti de beyazlar, 

Benim kara sevdamı silememişti.', 'Soğuktu,  İnsanın iliklerine işleyen bir soğuk. Seni düşünüyordum. Her geçen gölge sana benziyordu Penceremin önünden,  Her gölgenin ardında...', ARRAY['Türk Edebiyatı','Şiir','Handan Sezginer']::text[], 8.5, '{"poet":"Handan Sezginer","poet_slug":"handan-sezginer","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/seni-yasarken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizdik', 'bizdik-bayram-karaali-pur4w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ellerimize koyduk yüreklerimizi derken, 

Nede çok yakın bir o kadarda uzaktaymışız, 

Yorgun serçemizdi sol göğsümüzdeki, 

Kanat çırpmaya takati kalmamış yenik, 

Gecenin yağmuru ağlıyordu oysa ellerimiz birleştiğinde, 

Acılar denizi büyümeye başlamıştı apansız, 

Bir ayrılık tiradı yazılmaya başladı gecede, 

Şafakla birlikte yittik sevdanın kahrolası karanlığında.', 'Ellerimize koyduk yüreklerimizi derken,  Nede çok yakın bir o kadarda uzaktaymışız,  Yorgun serçemizdi sol göğsümüzdeki,  Kanat çırpmaya tak...', ARRAY['Türk Edebiyatı','Şiir','Bayram Karaali']::text[], 8.5, '{"poet":"Bayram Karaali","poet_slug":"bayram-karaali","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bizdik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
